extern const OwlEnum E_httpAuthentification;
extern const OwlEnum E_typeMime;
extern const OwlEnum E_httpFlux;

/* ================================================================
 * PARSER STATE
 * ================================================================ */

typedef struct {
    Token current;
    Token previous;
    Scanner scanner;
    bool hadError;
    bool panicMode;
    /*  : flag "une faute a deja ete reportee dans ce fichier".
     * Contrairement a panicMode (clear par chaque synchronize()), ce flag
     * survit a la recovery. Utilise par les gardes top-level
     * enforce_class_file_isolation_at_top_level / _dsl_ pour s'abstenir
     * d'emettre un message en cascade ("Convention OWL : ...") lorsque
     * le parser est devenu erratique apres une faute syntaxique reelle
     * (typiquement FIN orphelin → parse continue, top-level voit du
     * runtime fantome). hadError ne convient pas : il porte aussi des
     * signaux non-parser (declare_variable invariant, etc.) et est lu
     * par d'autres consommateurs comme verdict global. */
    bool hadFileError;
} Parser;

/* ================================================================
 * PRECEDENCE LEVELS (Pratt parser)
 * ================================================================ */

typedef enum {
    PREC_NONE,
    PREC_ASSIGNMENT,    /* = <= <- */
    PREC_TERNARY,       /* ? ... SINON */
    PREC_OR,            /* OU _OU_ */
    PREC_AND,           /* ET _ET_ */
    PREC_BIT_OR,        /* | (OUBinaire) */
    PREC_BIT_XOR,       /* || (OUExclusifBinaire) */
    PREC_BIT_AND,       /* & (ETBinaire) */
    PREC_EQUALITY,      /* = <> */
    PREC_COMPARISON,    /* < > <= >= ~= ~~ [= =] [=] */
    PREC_BIT_SHIFT,     /* bitDécaleGauche / bitDécaleDroite */
    PREC_TERM,          /* + - */
    PREC_FACTOR,        /* * / MODULO */
    PREC_POWER,         /* ^ */
    PREC_UNARY,         /* - PAS ~ */
    PREC_CALL,          /* . () [] */
    PREC_PRIMARY,
} Precedence;

typedef void (*ParseFn)(bool canAssign);

typedef struct {
    ParseFn prefix;
    ParseFn infix;
    Precedence precedence;
} ParseRule;

/* ================================================================
 * LOCAL VARIABLES
 * ================================================================ */

typedef struct {
    Token name;
    int depth;
    int declaredLine;      /* line number where variable was declared (for accurate warnings) */
    bool isNullable;       /* declared with '?' or '<nullable>' */
    bool isUndetectable;   /* declared with '<indétectable>' -- masked-in-RAM string */
    bool isUsed;           /* whether the variable has been referenced */
    bool hasInitializer;   /* whether declared with an explicit = or <= initializer */
    int  declaredType;     /* token type of the declared type (e.g. TOKEN_ENTIER)
                            * or TOKEN_EOF if unknown */
    char structTypeName[64]; /* when declaredType is TOKEN_IDENTIFIER (struct/class/builtin type) */
    char arrayElemStructType[64]; /*  — pour un `tableau de <TypeUser>`, nom du type
                                   * d'element quand c'est une structure/classe UTILISATEUR.
                                   * ADDITIF, distinct de structTypeName qui reste VIDE pour un
                                   * tableau (invariant de desambiguisation tab[i] vs STY[etat]).
                                   * Sert au refus `t[i]..prop` du registre masque. */
    const char* icone_catalog_name; /* Pour une slot typee Icone, nom catalogue Iconify
                                     * (pointeur vers OwlIconCatalogEntry.name, static storage,
                                     * pas de free). NULL sinon. Sert au warning compile-time
                                     * W_SEM_ICONE_NOT_COLORABLE. Par-compiler donc nested-safe. */
    bool isErrorPlaceholder; /*  : slot ajoutee par declare_variable apres
                              * emission d'une erreur (shadow scope-different). Exclue
                              * de warn_unused_locals — l'erreur principale couvre deja
                              * le user, le warning "declaree mais jamais utilisee" en
                              * cascade ne serait que du bruit pedagogique. */
    bool suppressUnused;   /*  : attribut de declaration <utile>/<useful>
                            * pose intentionnellement -> exempte de W_SEM_VAR_UNUSED.
                            * Distinct de isUsed (aucun usage reel) : c'est un opt-out
                            * explicite, pendant nomme du prefixe `_`. */
} Local;

typedef enum {
    TYPE_FUNCTION,
    TYPE_SCRIPT,
    TYPE_METHOD,
    TYPE_CONSTRUCTOR,
} FunctionType;

/* MAX_LOOP_DEPTH, MAX_BREAKS et autres limites compile-time du compilateur
 * sont desormais declarees dans src/owl_limits.def (single source, cf.
 * ). Le include owl_limits.h en tete du fichier les fournit toutes
 * sous forme d'enum, transparente pour le code existant. */

typedef struct {
    int start;          /* bytecode offset of loop start (for CONTINUER) */
    int scopeDepth;     /* scope depth at loop entry (for unwinding locals) */
    int breaks[MAX_BREAKS]; /* list of break jump offsets to patch */
    int breakCount;
    int continues[MAX_BREAKS]; /* list of continue jump offsets to patch */
    int continueCount;
    bool useDeferredContinue; /* if true, CONTINUER uses forward jumps to patch */
} LoopContext;

/* SORTIR SELON tracking — strictement parallèle a LoopContext mais
 * independant : un SORTIR SELON saute uniquement au FIN du SELON le plus
 * proche, jamais a une boucle englobante. */
typedef struct {
    int scopeDepth;          /* scope depth at SELON entry */
    int breaks[MAX_BREAKS];  /* jump offsets to patch at FIN */
    int breakCount;
} SwitchContext;

typedef struct Compiler {
    struct Compiler* enclosing;
    ObjFunction* function;
    FunctionType type;
    int scopeDepth;

    Local locals[UINT8_COUNT];
    int localCount;

    LoopContext loopStack[MAX_LOOP_DEPTH];
    int loopDepth;

    SwitchContext switchStack[MAX_LOOP_DEPTH];
    int switchDepth;

    /* Enforcement canon (note ligne 134) : il est
     * interdit de mélanger RETOUR et RENVOYER dans une meme procedure.
     * `seenReturnKind` est 0 tant qu'aucun n'a ete vu, puis stocke
     * TOKEN_RETOUR ou TOKEN_RENVOYER apres le premier usage. Si une
     * 2e occurrence utilise l'autre keyword, compile-error.
     * `seenReturnLine` retient la ligne du premier pour le diagnostic. */
    int seenReturnKind;
    int seenReturnLine;

    /*  — identifiant unique alloue a init_compiler. Sert a marquer
     * les types user (Structure/Enumeration) declares DANS ce compiler pour
     * detecter la collision "nom de type + variable meme nom dans la meme
     * procedure". Utiliser l'adresse memoire ne suffit pas : la stack reuse
     * la meme adresse pour des compilers successifs. */
    int id;
} Compiler;

/* ================================================================
 * CLASS COMPILER (tracks current class context for methods)
 * ================================================================ */

typedef struct ClassCompiler {
    struct ClassCompiler* enclosing;
    Token name;
    bool isGlobalMethod;     /*  : true si on est dans le corps d'une
                              * PROCEDURE GLOBALE — interdit l'usage de ':'. */
} ClassCompiler;

/* ================================================================
 * GLOBALS
 * ================================================================ */

static Parser parser;
static Compiler* current = NULL;

/*  — compteur monotone pour Compiler.id. 0 reserve "pas de owner"
 * (= type user declare au top-level d'un fichier). Toute valeur > 0 designe
 * un compiler procedural specifique. */
static int g_nextCompilerId = 0;

static ClassCompiler* currentClass = NULL;

/* Project context (NULL when compiling single file) */
static const char* currentFilename = NULL;
static SymbolTable* projectSymbols = NULL;
static int currentFileIndex = -1;

/* Tracking per-fichier des declarations Fenetre vs Etat. Un fichier ne peut
 * pas contenir a la fois une declaration de Fenetre et une declaration d'Etat
 * (decision projet : separation stricte UI / impression). Les valeurs sont
 * 0 quand aucune declaration du kind n'a ete vue dans le fichier courant,
 * sinon la ligne de la PREMIERE declaration (pour pointer l'utilisateur). */
static int g_file_first_window_line = 0;
static int g_file_first_etat_line   = 0;

/*  — Detection PRESCAN de la presence d'un bloc Fenetre/Etat dans le
 * fichier. Necessaire pour le verrou DSL : interdit le code top-level
 * non-PROCEDURE des qu'on sait qu'on est dans un fichier-fenetre/-etat,
 * meme AVANT que la declaration soit rencontree par le compile principal.
 * Set par prescan_source_unified, lu par enforce_dsl_file_isolation_at_top_level. */
static bool g_file_has_window_block_prescan = false;
static bool g_file_has_etat_block_prescan   = false;

/*  — true pendant le dispatch d'un statement top-level du CORPS d'un
 * bloc DSL (Fenetre/Etat : instructions apres PROPRIETES). Autorise
 * synchronize() a faire son early-return sur frontiere de ligne propre
 * (crossedNewline) MEME dans un fichier-fenetre/-etat, afin que le corps
 * rapporte les N erreurs independantes (parite avec le top-level, 
 * volet B) au lieu d'en avaler tout apres la premiere. Reste FALSE au scan
 * de widgets/props du fichier-fenetre : la, une desynchro DSL doit collapser
 * (garde , cf. synchronize()). */
static bool g_in_dsl_body_stmt = false;

/*  — un fichier-projet (contenant un bloc `est un Projet`) ne peut
 * comporter QUE ce bloc au top-level : aucun statement/declaration avant la
 * declaration ni apres le FIN final. Le corps du bloc (apres PROPRIETES) EST
 * le programme d'initialisation. g_file_has_projet_block est pose au prescan
 * (permet de rejeter le code AVANT la declaration) ; g_projet_block_parsed
 * bascule a true une fois le FIN final du bloc consomme (distingue le "avant"
 * du "apres" pour le verrou top-level). */
static bool g_file_has_projet_block = false;
static bool g_projet_block_parsed   = false;

/*  — meme mecanique pour le bloc `<Nom> est une
 * CollectionDeProcédures ... FIN` : un fichier qui en declare un ne peut
 * contenir que ce bloc au top-level. g_file_has_collection_block est pose au
 * prescan (rejet du code AVANT la declaration) ; g_collection_block_parsed
 * bascule au FIN du bloc. Le flag survit a la fin du compile du fichier :
 * project_run le lit pour gater la capture du hook Terminaison. */
static bool g_file_has_collection_block = false;
static bool g_collection_block_parsed   = false;

/*  — meme mecanique pour le bloc `<Nom> est un ServiceREST ... FIN` :
 * un fichier-service ne peut contenir QUE ce bloc au top-level FICHIER (les
 * declarations — Structure — et les operations vivent DANS le bloc, modele
 * Projet). g_file_has_service_block est pose au prescan (rejet du code AVANT la
 * declaration) ; g_service_block_parsed bascule a true au FIN final du bloc
 * (distingue le "avant" du "apres" pour le verrou top-level). */
static bool g_file_has_service_block = false;
static bool g_service_block_parsed   = false;

/*  — `CollectionDeProcédures` (FR canon) / `ProcedureCollection`
 * (EN) ne sont pas des tokens dedies mais des IDENTIFIER : aucun mot n'est
 * reserve globalement. Casse-insensible (invariant 1) + accents strippes
 * (invariant 2). */
static bool token_is_collection_kw(const char* start, int length) {
    char probe[40];
    int n = scanner_strip_accents(start, length, probe, sizeof(probe));
    if (n <= 0 || n >= (int)sizeof(probe)) return false;
    return (n == 22 && strncasecmp(probe, "CollectionDeProcedures", 22) == 0)
        || (n == 19 && strncasecmp(probe, "ProcedureCollection", 19) == 0);
}

/*  — anti-cascade error-recovery. Quand un bloc Fenetre/Etat se
 * ferme trop tot (FIN surnumeraire, prop mal parsee, NBSP, == ...), les
 * widgets/bandes restants retombent dans la boucle top-level. Un
 * bloc-widget `NAME est un <WidgetType>` est un shape de declaration valide
 * => parse propre, panicMode cleared, synchronize() jamais appele =>
 * 1 erreur PAR widget (les 40-50). On collapse : 1 erreur pleine pointant
 * la VRAIE cause (ligne d'ouverture du bloc) + au plus ~2 erreurs DSL-
 * toplevel + UNE note agregee pour le surplus. Borne stricte au couple
 * DSL-toplevel meme-cause consecutif, jamais de dedup aveugle globale. */
#define OWL_DSL_TOPLEVEL_WIDGET_CAP 2            /* plafond d'erreurs pleines avant note */

/*  — profondeur lexicale du scope Etat en cours de parse. Bumpe a
 * l'entree d'`etat_declaration`, decremente a la sortie. Couvre top-level
 * body, sub-blocs (EnTeteDocument/Corps/...), PROCEDUREs internes
 * (Lecture/Filtre/Fermeture/helpers). Sert au verrou compile-time qui
 * interdit `Ouvre`/`OuvreFille`/`OuvreSoeur` dans un Etat (un Etat
 * genere un rapport, pas d'event loop UI). */
static int g_in_etat_scope_depth = 0;

/* Tracking per-fichier de la regle "1 classe = 1 fichier". Un fichier qui
 * declare une Classe ne peut contenir que cette classe + ses methodes
 * externes (PROCEDURE cName.Method) + constructeur/destructeur + comments.
 * Pas de 2e Classe, pas de Fenetre/Etat, pas de code runtime top-level.
 * Valeur 0 = aucune Classe vue ; sinon ligne de la PREMIERE Classe.
 * Le nom est capture pour les messages d'erreur (designe la 1ere classe). */
static int  g_file_first_class_line = 0;
static char g_file_first_class_name[64] = {0};
static int  g_file_first_class_name_len = 0;
/* Ligne du premier statement runtime top-level (hors declaration). Sert
 * a rejeter une Classe declaree apres du code top-level. 0 = rien vu. */
static int  g_file_first_non_class_stmt_line = 0;

/* Opt-out de la regle "1 fichier = 1 Fenetre". Active par la presence
 * du commentaire `// @owl-allow-multi-window` n'importe ou dans le source
 * (typiquement en tete de fichier). Reserve aux tests qui valident le
 * parser sur plusieurs fenetres ; le code utilisateur reel doit
 * respecter la regle (le designer + le packaging supposent 1:1). */
static bool g_file_allow_multi_window = false;

/* Per-compilation type map for typed globals. Compile-time only — used by
 * the strict Null-assignment check, the compile-time TypeEstNullable
 * resolution, and the OP_APPEND_IN_PLACE_GLOBAL string-builder optimization.
 * Reset at each compile entry point. Stores (name -> declared type token,
 * isNullable flag) for ALL globals declared with an explicit type. */
typedef struct {
    char*      name;
    int        length;
    int        declaredType;   /* TokenType of declared type, or TOKEN_EOF */
    bool       isNullable;     /* true if declared with `?` or `<nullable>` */
    bool       isUndetectable; /* true if declared with `<indétectable>` */
    char       structTypeName[64]; /* "httpRequête", "Chrono"… when declaredType==TOKEN_IDENTIFIER */
    char       arrayElemStructType[64]; /*  — cf. Local.arrayElemStructType : type
                                         * d'element user d'un `tableau de <TypeUser>`. ADDITIF. */
} TypedGlobal;

/* Dimensionnee sur MAX_DECLARED_GLOBALS : ses entrees viennent des memes
 * declarations que g_declaredGlobals, elle ne peut donc pas etre le mur qui
 * frappe en premier. */
static TypedGlobal g_typed_globals[MAX_DECLARED_GLOBALS];
static int g_typed_globals_count = 0;

/* ============================================================
 * Phase 6 : alias des PROCEDURE custom de widget pour resolution
 * implicite. Quand le compileur compile le body d'un event/proc d'un
 * widget, les noms de PROCEDURE custom du widget sont enregistres ici
 * avec leur nom qualifie '<widget>_<proc>'. named_variable consulte
 * cette table avant de tomber en OP_GET_GLOBAL : si match, le token
 * name est replace par la forme qualifiee.
 *
 * Stack de scopes : window_declaration / window_parse_subfield push un
 * marker au debut, pop a la fin. Les aliases ajoutes dans le scope
 * sont oublies au pop — c'est l'isolation par widget.
 * ============================================================ */

typedef struct {
    char proc[64];          /* nom local : 'Calcule' */
    char qualified[256];    /* nom qualifie : 'BTN_OK_Calcule' */
} DslProcAlias;
static DslProcAlias g_dsl_aliases[MAX_DSL_PROC_ALIASES];
static int          g_dsl_alias_count = 0;
static int          g_dsl_alias_stack[64];
static int          g_dsl_alias_stack_top = 0;

/*  — Pointeur sur le OwlWindowDecl en cours de parsing. Set au
 * debut de window_declaration, restore au pop. NULL en dehors d'un body
 * fenetre. Permet a var_declaration_after_est de pousser une entree dans
 * decl->variables[] quand on declare `GR_X est un Groupe` au top-level
 * fenetre (cf prop `champ..Groupe` qui parcourt vm.windows). */
static OwlWindowDecl* g_current_window_decl = NULL;

/*  lot 1b — Pointeur sur le OwlControlDecl en cours de parsing
 * (symetrique de g_current_window_decl). Set au debut de
 * window_parse_subfield, restore au pop. NULL hors body de champ.
 *
 * Sert a l'ISOLATION du scope des variables de top-level champ (OPTION A,
 * prefixe statique) : une variable declaree au niveau 0 du body d'un champ
 * devient en interne un global prefixe `<ctrl>__<var>` (DOUBLE underscore,
 * pour ne PAS collisionner avec le namespace `<ctrl>_<proc>` des procedures
 * de champ). Le prefixe la rend resoluble depuis le top-level du champ ET
 * ses events/procedures, INVISIBLE ailleurs (champ voisin, fenetre). */
/*  lot 3-bis A1 — mini-stack des controls EN COURS de parse.
 *
 * Avant : single-slot `g_current_control_decl`. Probleme : en cas de
 * Conteneur/ZoneRepetee, `window_parse_subfield` se rappelle pour les
 * sous-champs, save le pointer parent en C-stack et l'ecrase. Les parents
 * existent UNIQUEMENT en C-stack pendant le parse de l'enfant → leurs
 * ObjFunction user_procs/events deja compilees ne sont rootees nulle part
 * (le control n'est append dans decl->controls[] qu'en FIN du parse pour
 * eviter realloc). Sous DEBUG_STRESS_GC : collect, segfault.
 *
 * Apres : stack push/pop. `gc_mark_compiler_roots` mark CHAQUE entree.
 * Lecture inchangee via macro `g_current_control_decl` (= top du stack ou
 * NULL si vide) — les ~14 lecteurs existants compilent sans modification.
 * SEULS les 3 sites push/pop (window_parse_subfield + etat_parse_block_*)
 * connaissent la mini-stack. */
#define G_CONTROL_DECL_STACK_MAX 32
static OwlControlDecl* g_control_decl_stack[G_CONTROL_DECL_STACK_MAX];
static int g_control_decl_top = 0;

#define g_current_control_decl \
    (g_control_decl_top > 0 ? g_control_decl_stack[g_control_decl_top - 1] : NULL)

/* Construit `<ctrl>__<var>` dans `out`. Retourne la longueur (0 si pas de
 * champ courant ou debordement). Le double underscore distingue du namespace
 * proc `<ctrl>_<proc>`. */
static int control_var_prefix(const char* varName, int varLen,
                              char* out, size_t outSize) {
    if (g_current_control_decl == NULL || g_current_control_decl->name == NULL)
        return 0;
    int n = snprintf(out, outSize, "%s__%.*s",
                     g_current_control_decl->name, varLen, varName);
    if (n <= 0 || (size_t)n >= outSize) return 0;
    return n;
}

/*  — contexte de compilation « element courant » (Fenetre/Etat).
 *
 * Les globales declarees au top-level du body d'un element sont SCOPEES a
 * l'element ( portee) : invisibles en nom nu depuis le script, et
 * accessibles de l'exterieur uniquement en qualifie `FEN_X.gNom` /
 * `ETAT_X.gCode`. Pour materialiser ce scope, une telle globale est
 * renommee en interne `<ELEM>$<var>` (mangling) au define ET a la lecture
 * intra-element. Le `$` distingue ce namespace de celui des controles
 * (`<ctrl>__<var>`) et des variables ordinaires.
 *
 * g_current_element_name : nom de l'element en cours de parse (FEN_X /
 * ETAT_X), set a l'entree de window_declaration / etat_declaration,
 * restaure a la sortie. Vide hors body element.
 *
 * g_element_globals : registre compile-time des (element, globale) pour
 * servir la resolution QUALIFIEE cross-fichier (`FEN_X.gNom` depuis un
 * script voisin). Alimente par hydrate_globals_from_neighbors (voisins) et
 * par var_declaration_after_est (fichier courant). Reset par compile. */
static char g_current_element_name[64] = {0};

/*  — un seul bloc `est un Theme` autorise par fichier. Flag reset a
 * chaque compile (cf. element_globals_reset call sites) ; passe a true au 1er
 * bloc parse, un 2e bloc dans le meme fichier emet une compile-error. */
static bool g_theme_block_seen = false;

#define MAX_ELEMENT_GLOBALS 1024
typedef struct {
    char element[64];   /* nom de l'element, forme tapee (FEN_X / ETAT_X) */
    char name[64];      /* nom de la globale, forme tapee (gNom) */
    /*  — forme accent-strippee memorisee une fois a l'insertion (le
     * dedup/lookup comparaient auparavant en re-strippant les 2 champs a
     * CHAQUE iteration, cout O(count) x strip par register/has). */
    char elemStrip[64]; int elemStripLen;
    char nameStrip[64]; int nameStripLen;
} ElementGlobal;
static ElementGlobal g_element_globals[MAX_ELEMENT_GLOBALS];
static int g_element_globals_count = 0;

static void element_globals_reset(void) {
    g_element_globals_count = 0;
    g_theme_block_seen = false;
}

/* Construit `<ELEM>$<var>` dans `out`. Retourne la longueur (0 si pas
 * d'element courant ou debordement). */
static int element_var_prefix(const char* elem,
                              const char* varName, int varLen,
                              char* out, size_t outSize) {
    if (elem == NULL || elem[0] == '\0') return 0;
    int n = snprintf(out, outSize, "%s$%.*s", elem, varLen, varName);
    if (n <= 0 || (size_t)n >= outSize) return 0;
    return n;
}

/* Enregistre (element, name) si absent. Comparaison accent+casse-insensible
 * pour matcher les invariants 1 & 2 (FEN_X == fen_x). */
static void element_globals_register(const char* elem, int elemLen,
                                     const char* name, int nameLen) {
    if (elemLen <= 0 || elemLen >= 64 || nameLen <= 0 || nameLen >= 64) return;
    char eStrip[64], nStrip[64];
    int es = scanner_strip_accents(elem, elemLen, eStrip, sizeof(eStrip));
    int ns = scanner_strip_accents(name, nameLen, nStrip, sizeof(nStrip));
    for (int i = 0; i < g_element_globals_count; i++) {
        const ElementGlobal* gi = &g_element_globals[i];
        if (gi->elemStripLen == es && gi->nameStripLen == ns
            && strncasecmp(gi->elemStrip, eStrip, (size_t)es) == 0
            && strncasecmp(gi->nameStrip, nStrip, (size_t)ns) == 0) {
            return;
        }
    }
    if (g_element_globals_count >= MAX_ELEMENT_GLOBALS) return;
    ElementGlobal* g = &g_element_globals[g_element_globals_count++];
    memcpy(g->element, elem, (size_t)elemLen); g->element[elemLen] = '\0';
    memcpy(g->name, name, (size_t)nameLen);   g->name[nameLen] = '\0';
    memcpy(g->elemStrip, eStrip, (size_t)es); g->elemStrip[es] = '\0';
    g->elemStripLen = es;
    memcpy(g->nameStrip, nStrip, (size_t)ns); g->nameStrip[ns] = '\0';
    g->nameStripLen = ns;
}

/* (element, name) connait-il une globale ? Accent+casse-insensible. */
static bool element_globals_has(const char* elem, int elemLen,
                                const char* name, int nameLen) {
    if (elemLen <= 0 || nameLen <= 0) return false;
    char eStrip[64], nStrip[64];
    int es = scanner_strip_accents(elem, elemLen, eStrip, sizeof(eStrip));
    int ns = scanner_strip_accents(name, nameLen, nStrip, sizeof(nStrip));
    for (int i = 0; i < g_element_globals_count; i++) {
        const ElementGlobal* gi = &g_element_globals[i];
        if (gi->elemStripLen == es && gi->nameStripLen == ns
            && strncasecmp(gi->elemStrip, eStrip, (size_t)es) == 0
            && strncasecmp(gi->nameStrip, nStrip, (size_t)ns) == 0) {
            return true;
        }
    }
    return false;
}

/* ============================================================================
 *  — Membres de CollectionDeProcédures (mode "stockage scopé + EXPOSÉ")
 *
 * Contrairement a l'element Fenetre/Etat (g_current_element_name) qui ENCAPSULE
 * — mangled `<ELEM>$var` + nom nu INVISIBLE de l'exterieur — une
 * collection EXPOSE : le stockage est mangled `<COL>$membre` (slots DISTINCTS
 * par collection, ce qui desambiguise deux collections declarant le meme nom)
 * MAIS le nom nu RESOUT vers ce slot quand il est NON-AMBIGU. Le drapeau
 * `exposed` (defaut true) porte ce contrat PAR MEMBRE ; un futur mot-cle LOCAL
 * le basculera a false pour encapsuler facon fenetre. Mecanisme PARALLELE dedie :
 * g_current_element_name reste au chemin fenetre/etat pour ne pas regresser
 * l'encapsulation partagee.
 *
 * Casse : le NOM DE BLOC (namespace) est compare CASSE-SENSIBLE, comme les
 * autres reconnaissances de namespace cross-fichier du compilateur
 * (is_project_window_name / is_project_file_name via memcmp). Le NOM DE MEMBRE
 * est compare casse+accent-insensible (invariants 1/2) : le runtime resout de
 * toute facon la forme mangled via l'index canon de vm.globals. */
/*  — compile le corps d'une CollectionDeProcédures puis hoiste ses
 * declarations structurelles avant le code d'init (definition plus bas, pres de
 * la machinerie de hoisting reorder_*). */
static void compile_collection_body_hoisted(void);

static char g_current_collection_name[64] = {0};

#define MAX_COLLECTION_MEMBERS 1024
typedef struct {
    char collection[64];  /* nom de bloc tape (COL_A) */
    char name[64];        /* nom du membre tape (gConf / Doubler) */
    bool exposed;         /* visible en nom nu ? defaut true (LOCAL -> false) */
    /*  — provenance, pour le garde de coherence des deux indexations.
     * Le scan lexical (hydrate_collection_members) alimente les autres
     * fichiers ; le parse reel alimente le fichier courant. Un membre vu par
     * le parse mais PAS par le scan est invisible des voisins : c'est la
     * desynchronisation silencieuse que le garde transforme en diagnostic. */
    bool seenPrescan;
    bool seenParse;
} CollectionMember;
static CollectionMember g_collection_members[MAX_COLLECTION_MEMBERS];
static int g_collection_members_count = 0;

/*  — vrai pendant hydrate_collection_members : marque la provenance
 * des enregistrements. */
static bool g_collection_register_from_prescan = false;
/*  — le scan lexical a-t-il vu EXACTEMENT la source en cours de
 * compilation ? Faux quand la source n'est pas dans le perimetre projet
 * (fichier isole) ou quand elle en differe (buffer d'editeur non sauvegarde
 * face au fichier sur disque). Le garde reste alors muet : comparer un parse
 * a l'index d'un AUTRE texte ne prouve rien et produirait des faux positifs. */
static bool g_collection_prescan_saw_source = false;
/*  — une collection imbriquee a ete refusee dans ce fichier. Elle
 * desynchronise mecaniquement le scan lexical (buffer de bloc courant unique) :
 * le garde de coherence se tairait pour rien par-dessus le vrai diagnostic. */
static bool g_collection_nested_rejected = false;

static void collection_members_reset(void) {
    g_collection_members_count = 0;
    g_current_collection_name[0] = '\0';
    g_collection_prescan_saw_source = false;
    g_collection_nested_rejected = false;
}

/* Construit `<COL>$<membre>` dans out. Retourne la longueur (0 si debordement). */
static int collection_var_prefix(const char* coll,
                                 const char* varName, int varLen,
                                 char* out, size_t outSize) {
    if (coll == NULL || coll[0] == '\0') return 0;
    int n = snprintf(out, outSize, "%s$%.*s", coll, varLen, varName);
    if (n <= 0 || (size_t)n >= outSize) return 0;
    return n;
}

/* Compare deux noms de membre casse+accent-insensible. */
static bool collection_member_name_eq(const char* a, int aLen,
                                      const char* b, int bLen) {
    char as[64], bs[64];
    int an = scanner_strip_accents(a, aLen, as, sizeof(as));
    int bn = scanner_strip_accents(b, bLen, bs, sizeof(bs));
    return an == bn && an > 0 && strncasecmp(as, bs, (size_t)an) == 0;
}

/* Enregistre (collection, name, exposed) si le couple est absent. Collection
 * comparee CASSE-SENSIBLE, membre casse-insensible. */
static void collection_member_register(const char* coll, int collLen,
                                       const char* name, int nameLen,
                                       bool exposed) {
    if (collLen <= 0 || collLen >= 64 || nameLen <= 0 || nameLen >= 64) return;
    for (int i = 0; i < g_collection_members_count; i++) {
        CollectionMember* m = &g_collection_members[i];
        if ((int)strlen(m->collection) == collLen
            && memcmp(m->collection, coll, (size_t)collLen) == 0
            && collection_member_name_eq(m->name, (int)strlen(m->name),
                                         name, nameLen)) {
            /* Deja connu : on note quand meme la provenance. */
            if (g_collection_register_from_prescan) m->seenPrescan = true;
            else                                    m->seenParse   = true;
            return;
        }
    }
    if (g_collection_members_count >= MAX_COLLECTION_MEMBERS) return;
    CollectionMember* m = &g_collection_members[g_collection_members_count++];
    memcpy(m->collection, coll, (size_t)collLen); m->collection[collLen] = '\0';
    memcpy(m->name, name, (size_t)nameLen);       m->name[nameLen] = '\0';
    m->exposed = exposed;
    m->seenPrescan = g_collection_register_from_prescan;
    m->seenParse   = !g_collection_register_from_prescan;
}

/* (collection, name) est-il un membre connu ? Collection casse-sensible,
 * membre casse-insensible. */
static bool collection_member_has(const char* coll, int collLen,
                                  const char* name, int nameLen) {
    if (collLen <= 0 || nameLen <= 0) return false;
    for (int i = 0; i < g_collection_members_count; i++) {
        CollectionMember* m = &g_collection_members[i];
        if ((int)strlen(m->collection) == collLen
            && memcmp(m->collection, coll, (size_t)collLen) == 0
            && collection_member_name_eq(m->name, (int)strlen(m->name),
                                         name, nameLen)) {
            return true;
        }
    }
    return false;
}

/*  — (coll, name) est-il un membre enregistré NON-EXPOSÉ (exposed=
 * false) ? Vrai uniquement pour les types internes d'une Fenetre/Etat, qui
 * sont QUALIFIE-ONLY. Sert is_collection_qualified_type : un tel type est
 * validé comme type qualifié sans exiger qu'il soit résoluble en nom nu (il
 * ne l'est justement pas — encapsulation). */
static bool collection_member_is_unexposed(const char* coll, int collLen,
                                           const char* name, int nameLen) {
    if (collLen <= 0 || nameLen <= 0) return false;
    for (int i = 0; i < g_collection_members_count; i++) {
        CollectionMember* m = &g_collection_members[i];
        if ((int)strlen(m->collection) == collLen
            && memcmp(m->collection, coll, (size_t)collLen) == 0
            && collection_member_name_eq(m->name, (int)strlen(m->name),
                                         name, nameLen)) {
            return !m->exposed;
        }
    }
    return false;
}

/* Resolution NOM NU d'un membre expose : compte les collections DISTINCTES qui
 * exposent `name`. Si exactement 1, *outColl pointe son nom de bloc (pour
 * construire `COL$name`). >=2 => ambigu (remede : qualifier). Chaque couple
 * (coll,name) etant unique dans le registre, le nombre d'entrees matchant
 * `name` = le nombre de collections distinctes. */
static int collection_member_resolve_bare(const char* name, int nameLen,
                                          const char** outColl, int* outCollLen) {
    if (outColl)    *outColl = NULL;
    if (outCollLen) *outCollLen = 0;
    int count = 0;
    for (int i = 0; i < g_collection_members_count; i++) {
        CollectionMember* m = &g_collection_members[i];
        if (!m->exposed) continue;
        if (!collection_member_name_eq(m->name, (int)strlen(m->name),
                                       name, nameLen)) {
            continue;
        }
        count++;
        if (count == 1 && outColl) {
            *outColl = m->collection;
            if (outCollLen) *outCollLen = (int)strlen(m->collection);
        }
    }
    return count;
}

static void dsl_aliases_push_scope(void) {
    if (g_dsl_alias_stack_top < 64) {
        g_dsl_alias_stack[g_dsl_alias_stack_top++] = g_dsl_alias_count;
    }
}
static void dsl_aliases_pop_scope(void) {
    if (g_dsl_alias_stack_top > 0) {
        g_dsl_alias_count = g_dsl_alias_stack[--g_dsl_alias_stack_top];
    }
}
static void dsl_aliases_add(const char* proc, const char* qualified) {
    /*  : dedup. La pre-passe ordre-independant pose l'alias avant le
     * parse reel ; sans dedup, on aurait deux entrees identiques (consomme
     * MAX_DSL_PROC_ALIASES sur les gros fichiers). Compare sur (proc,
     * qualified) case-insensitive. */
    for (int i = 0; i < g_dsl_alias_count; i++) {
        if (strcasecmp(g_dsl_aliases[i].proc, proc) == 0
            && strcasecmp(g_dsl_aliases[i].qualified, qualified) == 0) {
            return;
        }
    }
    if (g_dsl_alias_count >= MAX_DSL_PROC_ALIASES) {
        error_capacity_exceeded("MAX_DSL_PROC_ALIASES", MAX_DSL_PROC_ALIASES);
        return;
    }
    DslProcAlias* a = &g_dsl_aliases[g_dsl_alias_count++];
    snprintf(a->proc, sizeof(a->proc), "%s", proc);
    snprintf(a->qualified, sizeof(a->qualified), "%s", qualified);
}
/*  — deux noms de PROCEDURE d'un bloc DSL (Etat, Fenetre) designent-ils
 * le meme identifiant ? Invariant 2 : casse ET accents ignores, comme partout
 * ailleurs dans le langage. Sert aux deux bouts de la chaine — la dedup a la
 * declaration (etat_compile_block_user_proc + etat_declaration) et la
 * resolution d'un appel nu via dsl_aliases_lookup — qui ne peuvent pas
 * diverger : le nom qualifie `<owner>_<proc>` est pose dans vm.globals, dont
 * l'index canon est deja accent-insensible. Une declaration plus stricte que
 * la liaison laissait deux procedures declarables mais une seule atteignable,
 * la premiere ecrasee sans message.
 * Buffers a 256 : scanner_strip_accents tronque en silence, et un cap trop bas
 * ferait passer deux noms longs et differents pour un doublon. */
static bool dsl_proc_name_eq(const char* a, int alen, const char* b, int blen) {
    if (!a || !b) return false;
    char sa[256], sb[256];
    int na = scanner_strip_accents(a, alen, sa, (int)sizeof(sa));
    int nb = scanner_strip_accents(b, blen, sb, (int)sizeof(sb));
    if (na <= 0 || nb <= 0 || na != nb) return false;
    for (int i = 0; i < na; i++) {
        if (tolower((unsigned char)sa[i]) != tolower((unsigned char)sb[i])) return false;
    }
    return true;
}

/* Lookup casse + accents ignores. Latest-first pour shadow inner→outer. */
static const char* dsl_aliases_lookup(const char* name, int len) {
    for (int i = g_dsl_alias_count - 1; i >= 0; i--) {
        if (dsl_proc_name_eq(g_dsl_aliases[i].proc,
                             (int)strlen(g_dsl_aliases[i].proc), name, len)) {
            return g_dsl_aliases[i].qualified;
        }
    }
    return NULL;
}

static void typed_globals_reset(void) {
    for (int i = 0; i < g_typed_globals_count; i++) {
        free(g_typed_globals[i].name);
    }
    g_typed_globals_count = 0;
}

static void typed_globals_add(const char* name, int length, int declaredType,
                                  bool isNullable, bool isUndetectable) {
    if (g_typed_globals_count >= MAX_DECLARED_GLOBALS) {
        error_capacity_exceeded("MAX_DECLARED_GLOBALS", MAX_DECLARED_GLOBALS);
        return;
    }
    TypedGlobal* g = &g_typed_globals[g_typed_globals_count++];
    g->name = (char*)malloc((size_t)length + 1);
    memcpy(g->name, name, (size_t)length);
    g->name[length] = 0;
    g->length = length;
    g->declaredType = declaredType;
    g->isNullable = isNullable;
    g->isUndetectable = isUndetectable;
    g->structTypeName[0] = '\0';
    g->arrayElemStructType[0] = '\0';
}


static void typed_globals_set_struct_type(const char* name, int length, const char* typeName, int typeNameLen) {
    for (int i = 0; i < g_typed_globals_count; i++) {
        TypedGlobal* g = &g_typed_globals[i];
        if (g->length == length && memcmp(g->name, name, (size_t)length) == 0) {
            int n = typeNameLen < 63 ? typeNameLen : 63;
            memcpy(g->structTypeName, typeName, (size_t)n);
            g->structTypeName[n] = '\0';
            return;
        }
    }
}

/*  — pendant additif de typed_globals_set_struct_type pour le type
 * d'element user d'un `tableau de <TypeUser>`. Distinct de structTypeName :
 * un tableau ne porte JAMAIS de structTypeName (invariant de desambiguisation
 * tab[i] vs STY[etat]), ce champ vit en parallele. */
static void typed_globals_set_array_elem_struct(const char* name, int length,
                                                const char* typeName, int typeNameLen) {
    for (int i = 0; i < g_typed_globals_count; i++) {
        TypedGlobal* g = &g_typed_globals[i];
        if (g->length == length && memcmp(g->name, name, (size_t)length) == 0) {
            int n = typeNameLen < 63 ? typeNameLen : 63;
            memcpy(g->arrayElemStructType, typeName, (size_t)n);
            g->arrayElemStructType[n] = '\0';
            return;
        }
    }
}

/* Const globals: noms déclarés via le bloc CONSTANTE. La réassignation
 * est interdite au compile-time (le compilateur émet une erreur quand il
 * détecte une cible nommée comme étant une constante).
 *
 * g_const_global_values[] est un tableau PARALLELE (meme index que
 * g_const_globals[]) qui memorise la Value repliee de chaque constante
 * utilisateur. Sert a resoudre une constante utilisee comme valeur par
 * defaut d'un parametre (`p(x est un entier = maConst)`) : parse_default_literal
 * la consulte au moment ou il rencontre l'identifiant. Peuple uniquement au
 * fil des declarations textuelles (pas de hoisting) — une constante doit
 * donc etre declaree AVANT la proc qui l'utilise en defaut.
 *
 * GC : la Value stockee (ObjString pour une constante chaine) est aussi
 * placee dans le pool de constantes du chunk courant via emit_constant() dans
 * constante_block ; ce pool est marque par le GC (gc.c) tant que la fonction
 * compilee vit. Ce tableau n'a donc pas besoin d'etre une racine GC propre —
 * il ne fait que referencer une Value deja enracinee. */
static char* g_const_globals[MAX_CONST_GLOBALS];
static Value g_const_global_values[MAX_CONST_GLOBALS];
static int   g_const_globals_count = 0;

static void const_globals_reset(void) {
    for (int i = 0; i < g_const_globals_count; i++) free(g_const_globals[i]);
    g_const_globals_count = 0;
}

static void const_globals_add(const char* name, int length, Value value) {
    if (g_const_globals_count >= MAX_CONST_GLOBALS) {
        error_capacity_exceeded("MAX_CONST_GLOBALS", MAX_CONST_GLOBALS);
        return;
    }
    char* dup = (char*)malloc((size_t)length + 1);
    memcpy(dup, name, (size_t)length);
    dup[length] = 0;
    g_const_global_values[g_const_globals_count] = value;
    g_const_globals[g_const_globals_count++] = dup;
}

/* Cherche la Value repliee d'une constante utilisateur par nom (case-insensible,
 * comme const_globals_find). Renvoie true et remplit *out si trouvee. */
static bool const_globals_find_value(const char* name, int length, Value* out) {
    for (int i = 0; i < g_const_globals_count; i++) {
        if ((int)strlen(g_const_globals[i]) == length
            && strncasecmp(g_const_globals[i], name, (size_t)length) == 0) {
            *out = g_const_global_values[i];
            return true;
        }
    }
    return false;
}

static bool const_globals_find(const char* name, int length) {
    for (int i = 0; i < g_const_globals_count; i++) {
        if ((int)strlen(g_const_globals[i]) == length
            && strncasecmp(g_const_globals[i], name, (size_t)length) == 0) {
            return true;
        }
    }
    return false;
}

/* Returns index if found (for declaredType access), -1 otherwise. */
static int typed_globals_find(const char* name, int length) {
    for (int i = 0; i < g_typed_globals_count; i++) {
        if (g_typed_globals[i].length == length
            && memcmp(g_typed_globals[i].name, name, (size_t)length) == 0) {
            return i;
        }
    }
    return -1;
}

/* AVEC/WITH block stack */
static int avecSlots[MAX_AVEC_DEPTH];
static int avecDepth = 0;

/* Set by advance_token when a newline/semicolon was skipped to reach
 * parser.current.  Used by parse_precedence to stop infix DOT from
 * chaining across lines inside AVEC blocks. */
static bool crossedNewline = false;

/* Note historique : un knownClasses[] / register_class_name / MAX_CLASSES
 * existait ici pour tracker les CLASSE user-declarees. Il dupliquait
 * knownUserTypes (chaque CLASSE etait enregistree dans les deux). Refonte :
 * le champ kind de knownUserTypes porte maintenant une semantique typee
 * (OWL_USER_TYPE_*). is_known_class est defini plus bas — filtre
 * knownUserTypes sur kind=CLASSE. */

typedef enum {
    OWL_USER_TYPE_UNKNOWN     = 0,  /* default state — non encore type, ou COMBINAISON / window prop block */
    OWL_USER_TYPE_STRUCTURE   = 1,  /* preserve la valeur historique kind==1 utilisee dans expressions */
    OWL_USER_TYPE_CLASSE      = 2,
    OWL_USER_TYPE_ENUMERATION = 3,
    OWL_USER_TYPE_INTERFACE   = 4,  /*  : track les interfaces comme user types */
} OwlUserTypeKind;

/* ---- Known user-defined types (structure / classe / enumeration / combinaison)
 *      + pending type references for compile-time "unknown type" detection. ---- */

/* Mode d'acces POO (canon : Public / Privé / Protégé).
 * Default PUBLIC sur tout field sans modifier explicite. Tracking pose
 * sur les fields de CLASSE par class_declaration (cf. ). */
typedef enum {
    OWL_VIS_PUBLIC  = 0,
    OWL_VIS_PRIVE   = 1,
    OWL_VIS_PROTEGE = 2,
} OwlVisibility;

typedef struct {
    char name[64];
    int  length;
    char typeName[64];   /* declared type token text (struct name, primitive, ...) */
    int  typeLen;
    /* Attributs de sérialisation. Posés via <Sérialise=Faux> ou
     * <Sérialise="autre_nom"> sur la ligne de déclaration du champ. */
    bool serialise_skip;       /* true -> exclu de Sérialise */
    char serialise_rename[64]; /* "" -> nom canonique, sinon nom JSON alternatif */
    /* Visibilité du membre dans une CLASSE. N'a de sens que
     * pour les fields déclarés via class_declaration ; les structs gardent
     * OWL_VIS_PUBLIC. */
    OwlVisibility visibility;
    /*  — le champ est-il un conteneur (`tableau` / `tableau
     * associatif`) ? Pose au registre du champ (premier token de type =
     * TABLEAU/ASSOCIATIF). Sert au validateur `.`/`..` : `s.champConteneur
     * ..Occurrence` est un acces propriete LEGITIME (Occurrence, Ajoute...),
     * a distinguer d'un vrai mesusage `s.champScalaire..prop`. Le nom de type
     * stocke (`tableau`) ne suffit pas a le deduire au moment de la
     * resolution (texte source localise). */
    bool is_container;
    /*  — position source du token de type declare (`… est un <Type>`).
     * Sert au check post-parse d'acyclicite des structures (validate_struct_
     * acyclicity) a pointer l'erreur sur le bon membre : le cycle indirect
     * n'est visible qu'une fois toutes les structures parsees, hors du flux de
     * tokens vivant. 0 = position inconnue. */
    int typeLine;
    int typeColumn;
    /*  — index du champ suivant du MEME type dans userTypeFieldPool,
     * -1 pour le dernier. Les champs d'un type ne sont pas contigus : une
     * Structure imbriquee dans un corps de Classe intercale ses
     * propres champs au milieu de ceux de la classe. */
    int next;
} UserTypeField;

/*  — pool plat partage par tous les types de l'unite de compilation.
 * Remplace la matrice "MAX_USER_TYPES x 64 champs" : a empreinte statique
 * equivalente (~3,4 Mo dans les deux cas), un type peut porter tout le budget
 * a lui seul au lieu de se voir reserver 64 emplacements dont il n'utilise
 * presque jamais plus de cinq. */
static UserTypeField userTypeFieldPool[MAX_USER_TYPE_FIELDS_TOTAL];
static int userTypeFieldPoolCount = 0;

static struct {
    char name[128];
    int length;
    /* Chaine des champs dans userTypeFieldPool, en ordre de declaration.
     * -1 / -1 quand le type n'a pas encore de champ. */
    int fieldFirst;
    int fieldLast;
    int fieldCount;
    OwlUserTypeKind kind;
    /*  — Compiler.id du compiler dans lequel ce type a ete declare.
     * 0 = top-level d'un fichier (pas de compiler procedural au moment de
     * la declaration). Une valeur > 0 = declaration DANS le corps de cette
     * procedure precise. Sert au check anti-collision dans declare_variable :
     * "variable de meme nom qu'un type user declare dans la MEME procedure
     * est interdit (alignement avec le check var+var)". */
    int ownerCompilerId;
    int declLine; /* ligne de la declaration du type (pour message d'erreur futur si besoin) */
    int hashNext; /*  : chainage dans le bucket de g_userTypeHashHead (-1 = fin) */
} knownUserTypes[MAX_USER_TYPES];
static int knownUserTypeCount = 0;

/*  — index de hash sur knownUserTypes pour rendre le lookup/dedup par
 * nom O(1) au lieu du scan lineaire O(knownUserTypeCount). knownUserTypes est
 * UNIQUE-par-nom (register_user_type dedup par name_iequals au seul site
 * d'append), donc chaque cle mappe au plus une entree ; le chainage ne sert
 * qu'a demeler les collisions de hash. L'index n'est qu'un accelerateur : la
 * table ordonnee reste la source de verite, name_iequals filtre les collisions
 * -> semantique casse-insensible/longueur-sensible strictement preservee. */
#define USER_TYPE_HASH_BUCKETS 1024  /* > 4x MAX_USER_TYPES (256), puissance de 2 */
static int g_userTypeHashHead[USER_TYPE_HASH_BUCKETS];
static bool g_userTypeHashInit = false;
static bool name_iequals(const char* a, int a_len, const char* b);  /* def plus bas */

static uint32_t utype_hash_key(const char* name, int len) {
    uint32_t h = 2166136261u;
    for (int i = 0; i < len; i++) {
        h ^= (unsigned char)tolower((unsigned char)name[i]);
        h *= 16777619u;
    }
    return h & (USER_TYPE_HASH_BUCKETS - 1);
}

static void user_types_hash_reset(void) {
    for (int i = 0; i < USER_TYPE_HASH_BUCKETS; i++) g_userTypeHashHead[i] = -1;
    g_userTypeHashInit = true;
}

/* Index de la 1ere entree knownUserTypes de ce nom, -1 si absent. Unique par
 * construction (register_user_type dedup), donc "1ere" == "la" entree. */
static int utype_find_index(const char* name, int length) {
    if (!g_userTypeHashInit) return -1;
    uint32_t b = utype_hash_key(name, length);
    for (int i = g_userTypeHashHead[b]; i != -1; i = knownUserTypes[i].hashNext) {
        if (name_iequals(name, length, knownUserTypes[i].name)) return i;
    }
    return -1;
}

static void user_types_hash_link(int idx) {
    if (!g_userTypeHashInit) user_types_hash_reset();
    uint32_t b = utype_hash_key(knownUserTypes[idx].name, knownUserTypes[idx].length);
    knownUserTypes[idx].hashNext = g_userTypeHashHead[b];
    g_userTypeHashHead[b] = idx;
}

/* Reset conjoint compteur + index (remplace `knownUserTypeCount = 0` nu). */
static void user_types_reset_all(void) {
    knownUserTypeCount = 0;
    user_types_hash_reset();
}

/* ---- Tracking compile-time des méthodes externes déclarées par classe.
 * Cf.  : deux méthodes même nom dans une même classe = erreur
 * compile-time. Table plate, scope = unité de compilation courante,
 * réinitialisée par reset_known_user_types (cf. plus bas). */
typedef struct {
    char className[64];
    int  classLen;
    char methodName[64];
    int  methodLen;
    int  declaredLine;
} DeclaredMethodEntry;
static DeclaredMethodEntry declaredMethods[MAX_DECLARED_METHODS];
static int declaredMethodCount = 0;

/* Comparaison casse-insensible accent-stripped déjà gérée par le scanner
 * sur les identifiants (les tokens nameEN/FR finissent canon). Ici on
 * compare octet à octet en case-insensible — c'est suffisant pour le
 * niveau registry-of-class-methods compile-time. */
static int find_declared_method(const char* className, int classLen,
                                const char* methodName, int methodLen) {
    for (int i = 0; i < declaredMethodCount; i++) {
        DeclaredMethodEntry* e = &declaredMethods[i];
        if (e->classLen != classLen || e->methodLen != methodLen) continue;
        bool match = true;
        for (int j = 0; j < classLen; j++) {
            if (tolower((unsigned char)e->className[j]) !=
                tolower((unsigned char)className[j])) { match = false; break; }
        }
        if (!match) continue;
        for (int j = 0; j < methodLen; j++) {
            if (tolower((unsigned char)e->methodName[j]) !=
                tolower((unsigned char)methodName[j])) { match = false; break; }
        }
        if (match) return i;
    }
    return -1;
}

static void register_declared_method(const char* className, int classLen,
                                     const char* methodName, int methodLen,
                                     int line) {
    if (declaredMethodCount >= MAX_DECLARED_METHODS) {
        error_capacity_exceeded("MAX_DECLARED_METHODS", MAX_DECLARED_METHODS);
        return;
    }
    DeclaredMethodEntry* e = &declaredMethods[declaredMethodCount++];
    int cl = classLen < 63 ? classLen : 63;
    int ml = methodLen < 63 ? methodLen : 63;
    memcpy(e->className, className, cl); e->className[cl] = 0; e->classLen = cl;
    memcpy(e->methodName, methodName, ml); e->methodName[ml] = 0; e->methodLen = ml;
    e->declaredLine = line;
}

/* ================================================================
 * VISIBILITY REGISTRY — persistant entre compiles
 *
 * Survit aux reset de knownUserTypes (qui sont remis à 0 à chaque
 * compile_in_project pour chaque fichier). Permet le check de
 * visibilité cross-fichier : si A.owl déclare `cFoo.PRIVE.nState`,
 * le compile de B.owl (qui réfère o.nState) peut retrouver cette
 * visibilité même si knownUserTypes a été reset entretemps.
 *
 * Pas de reset programmé : les entrées s'accumulent au cours d'une
 * session. Une redéclaration (test runner: nouveau projet, même VM)
 * écrase l'entrée existante par nom. Approche pragmatique tant que
 * les sessions sont courtes (test runner, --check, project_run
 * unique). Si fuite avérée plus tard : exposer un reset explicite
 * appelé par vm_init.
 * ================================================================ */

typedef struct {
    char className[64];
    int  classLen;
    char fieldName[64];
    int  fieldLen;
    OwlVisibility visibility;
    /*  — type déclaré du champ (TokenType), -1 si inconnu. Tracking
     * interne pour la coercition d'aplatissement multilingue au stockage
     * (`:champ = {...}`), PAS une réification de propriété first-class
     * : aucun getter/setter synthétisé, juste l'info de type. */
    int  typeToken;
} ClassFieldVisEntry;
static ClassFieldVisEntry g_class_field_vis[MAX_CLASS_FIELD_VIS];
static int g_class_field_vis_count = 0;

typedef struct {
    char className[64];
    int  classLen;
    char superName[64];
    int  superLen;
} ClassSuperEntry;
static ClassSuperEntry g_class_super[MAX_CLASS_SUPER];
static int g_class_super_count = 0;

/*  : constantes de classe (bloc CONSTANT dans body de Classe).
 * Une entree marque le couple (classe, nom-de-constante). Le storage runtime
 * passe par ObjClass.staticFields (cf. ) ; cette table sert
 * uniquement au check compile-time du write-block `cX.K = val`. */
typedef struct {
    char className[64];
    int  classLen;
    char constName[64];
    int  constLen;
} ClassConstantEntry;
static ClassConstantEntry g_class_constants[MAX_CLASS_CONSTANTS];
static int g_class_constants_count = 0;

static bool class_constant_is(const char* className, int classLen,
                              const char* constName, int constLen) {
    for (int i = 0; i < g_class_constants_count; i++) {
        ClassConstantEntry* e = &g_class_constants[i];
        if (e->classLen != classLen || e->constLen != constLen) continue;
        if (strncasecmp(e->className, className, (size_t)classLen) != 0) continue;
        if (strncasecmp(e->constName, constName, (size_t)constLen) != 0) continue;
        return true;
    }
    return false;
}

static void class_constant_register(const char* className, int classLen,
                                    const char* constName, int constLen) {
    if (class_constant_is(className, classLen, constName, constLen)) return;
    if (g_class_constants_count >= MAX_CLASS_CONSTANTS) {
        error_capacity_exceeded("MAX_CLASS_CONSTANTS", MAX_CLASS_CONSTANTS);
        return;
    }
    ClassConstantEntry* e = &g_class_constants[g_class_constants_count++];
    int cl = classLen < 63 ? classLen : 63;
    int kl = constLen < 63 ? constLen : 63;
    memcpy(e->className, className, cl); e->className[cl] = '\0'; e->classLen = cl;
    memcpy(e->constName, constName, kl); e->constName[kl] = '\0'; e->constLen = kl;
}

/*  : registre compile-time des methodes GLOBALE par classe. Sert
 * uniquement au check negatif dans dot_access : si `cClass.M()` est ecrit
 * dans body methode et cClass n'est pas ancetre transitif de currentClass,
 * on consulte ce registre pour distinguer un super-call invalide d'un
 * appel statique GLOBALE legitime. Persistant cross-file (meme pattern
 * que g_class_constants), reset par compiler_reset_poo_state(). */
typedef struct {
    char className[64];
    int  classLen;
    char methodName[64];
    int  methodLen;
} ClassGlobaleMethodEntry;
static ClassGlobaleMethodEntry g_class_globale_methods[MAX_DECLARED_METHODS];
static int g_class_globale_methods_count = 0;

static bool class_globale_method_is(const char* className, int classLen,
                                    const char* methodName, int methodLen) {
    for (int i = 0; i < g_class_globale_methods_count; i++) {
        ClassGlobaleMethodEntry* e = &g_class_globale_methods[i];
        if (e->classLen != classLen || e->methodLen != methodLen) continue;
        if (strncasecmp(e->className, className, (size_t)classLen) != 0) continue;
        if (strncasecmp(e->methodName, methodName, (size_t)methodLen) != 0) continue;
        return true;
    }
    return false;
}

static void class_globale_method_register(const char* className, int classLen,
                                          const char* methodName, int methodLen) {
    if (class_globale_method_is(className, classLen, methodName, methodLen)) return;
    if (g_class_globale_methods_count >= MAX_DECLARED_METHODS) {
        error_capacity_exceeded("MAX_DECLARED_METHODS", MAX_DECLARED_METHODS);
        return;
    }
    ClassGlobaleMethodEntry* e =
        &g_class_globale_methods[g_class_globale_methods_count++];
    int cl = classLen < 63 ? classLen : 63;
    int ml = methodLen < 63 ? methodLen : 63;
    memcpy(e->className, className, cl); e->className[cl] = '\0'; e->classLen = cl;
    memcpy(e->methodName, methodName, ml); e->methodName[ml] = '\0'; e->methodLen = ml;
}

/*  : arite minimale du constructeur par classe. Peuple par
 * compile_inline_class_method (INLINE_KIND_CONSTRUCTOR) avec la valeur
 * `minArity` deja calculee localement (params sans default).
 *
 * Sert au check compile-time de `oFoo est un cFoo` sans `()` :
 *  - hasConstructor == false (aucun cstr explicite declare) OU minArity == 0
 *    -> auto-instanciation triviale (emit OP_GET_GLOBAL + OP_CALL 0).
 *  - minArity > 0 -> erreur E_SEM_INSTANCE_NEEDS_ARGS (cstr requiert
 *    des arguments, oblige a ecrire `cFoo(...)`).
 *
 * Lookup_inherited remonte la chaine d'heritage : si une classe enfant
 * n'a pas de cstr propre, on prend celui du parent. Comportement aligne
 * avec canon (constructeur du parent appele implicitement). */
typedef struct {
    char className[64];
    int  classLen;
    int  minArity;       /* nombre d'arguments sans valeur par defaut */
    bool hasConstructor; /* true si PROCEDURE Constructeur(...) declaree */
} ClassConstructorArityEntry;
#ifndef MAX_CLASS_CONSTRUCTOR_ARITY
#define MAX_CLASS_CONSTRUCTOR_ARITY 256
#endif
static ClassConstructorArityEntry g_class_constructor_arity[MAX_CLASS_CONSTRUCTOR_ARITY];
static int g_class_constructor_arity_count = 0;

static void class_constructor_arity_register(const char* className, int classLen,
                                             int minArity) {
    for (int i = 0; i < g_class_constructor_arity_count; i++) {
        ClassConstructorArityEntry* e = &g_class_constructor_arity[i];
        if (e->classLen == classLen &&
            strncasecmp(e->className, className, (size_t)classLen) == 0) {
            e->minArity       = minArity;
            e->hasConstructor = true;
            return;
        }
    }
    if (g_class_constructor_arity_count >= MAX_CLASS_CONSTRUCTOR_ARITY) {
        error_capacity_exceeded("MAX_CLASS_CONSTRUCTOR_ARITY", MAX_CLASS_CONSTRUCTOR_ARITY);
        return;
    }
    ClassConstructorArityEntry* e =
        &g_class_constructor_arity[g_class_constructor_arity_count++];
    int cl = classLen < 63 ? classLen : 63;
    memcpy(e->className, className, cl); e->className[cl] = '\0'; e->classLen = cl;
    e->minArity       = minArity;
    e->hasConstructor = true;
}

/* Cherche l'entree pour `className` exact (pas d'heritage). Retourne NULL si
 * aucun constructeur n'a ete declare explicitement pour cette classe. */
static const ClassConstructorArityEntry*
class_constructor_arity_lookup(const char* className, int classLen) {
    for (int i = 0; i < g_class_constructor_arity_count; i++) {
        const ClassConstructorArityEntry* e = &g_class_constructor_arity[i];
        if (e->classLen == classLen &&
            strncasecmp(e->className, className, (size_t)classLen) == 0) {
            return e;
        }
    }
    return NULL;
}

/* Remonte la chaine d'heritage (g_class_super) pour trouver le premier
 * constructeur explicite. Retourne minArity (>= 0) si trouve, ou -1 si
 * aucune classe de la chaine n'a de constructeur declare (== auto-instan-
 * ciation triviale, equivalent minArity == 0). */
static int class_constructor_min_arity_inherited(const char* className,
                                                  int classLen) {
    const char* cur = className;
    int curLen = classLen;
    for (int hops = 0; hops < 64; hops++) {
        const ClassConstructorArityEntry* e =
            class_constructor_arity_lookup(cur, curLen);
        if (e != NULL) return e->minArity;
        /* Monte d'un cran. */
        const char* nextName = NULL;
        int nextLen = 0;
        for (int i = 0; i < g_class_super_count; i++) {
            ClassSuperEntry* se = &g_class_super[i];
            if (se->classLen == curLen &&
                strncasecmp(se->className, cur, (size_t)curLen) == 0) {
                nextName = se->superName;
                nextLen  = se->superLen;
                break;
            }
        }
        if (!nextName || nextLen <= 0) return -1;
        cur = nextName;
        curLen = nextLen;
    }
    return -1;
}

static int class_field_vis_find_index(const char* className, int classLen,
                                      const char* fieldName, int fieldLen) {
    for (int i = 0; i < g_class_field_vis_count; i++) {
        ClassFieldVisEntry* e = &g_class_field_vis[i];
        if (e->classLen != classLen || e->fieldLen != fieldLen) continue;
        if (strncasecmp(e->className, className, (size_t)classLen) != 0) continue;
        if (strncasecmp(e->fieldName, fieldName, (size_t)fieldLen) != 0) continue;
        return i;
    }
    return -1;
}

static void class_field_vis_register(const char* className, int classLen,
                                     const char* fieldName, int fieldLen,
                                     OwlVisibility vis) {
    int existing = class_field_vis_find_index(className, classLen,
                                              fieldName, fieldLen);
    if (existing >= 0) {
        g_class_field_vis[existing].visibility = vis;
        return;
    }
    if (g_class_field_vis_count >= MAX_CLASS_FIELD_VIS) {
        error_capacity_exceeded("MAX_CLASS_FIELD_VIS", MAX_CLASS_FIELD_VIS);
        return;
    }
    ClassFieldVisEntry* e = &g_class_field_vis[g_class_field_vis_count++];
    int cl = classLen < 63 ? classLen : 63;
    int fl = fieldLen < 63 ? fieldLen : 63;
    memcpy(e->className, className, cl); e->className[cl] = '\0'; e->classLen = cl;
    memcpy(e->fieldName, fieldName, fl); e->fieldName[fl] = '\0'; e->fieldLen = fl;
    e->visibility = vis;
    e->typeToken  = -1;
}

/*  — enregistre le type déclaré d'un champ de classe (après
 * class_field_vis_register). Sert à la coercition d'aplatissement multilingue
 * sur `:champ = ...` (this_field). */
static void class_field_type_set(const char* className, int classLen,
                                 const char* fieldName, int fieldLen,
                                 int typeToken) {
    int idx = class_field_vis_find_index(className, classLen, fieldName, fieldLen);
    if (idx >= 0) g_class_field_vis[idx].typeToken = typeToken;
}

/* Retourne le TokenType du type déclaré d'un champ de classe, -1 si inconnu.
 * Lookup direct sur la classe (pas de remontée d'héritage — un membre hérité
 * relève de la déclaration parente non résolue ici). */
static int class_field_type_lookup(const char* className, int classLen,
                                   const char* fieldName, int fieldLen) {
    int idx = class_field_vis_find_index(className, classLen, fieldName, fieldLen);
    if (idx < 0) return -1;
    return g_class_field_vis[idx].typeToken;
}

/* Returns -1 si le field n'est pas connu pour cette classe (= probable PUBLIC
 * non-tracké, ou field runtime-only). Sinon retourne la visibilité. */
static int class_field_vis_lookup(const char* className, int classLen,
                                  const char* fieldName, int fieldLen) {
    int idx = class_field_vis_find_index(className, classLen, fieldName, fieldLen);
    if (idx < 0) return -1;
    return (int)g_class_field_vis[idx].visibility;
}

static void class_super_register(const char* className, int classLen,
                                 const char* superName, int superLen) {
    /* Écrase l'entrée existante (re-déclaration). */
    for (int i = 0; i < g_class_super_count; i++) {
        ClassSuperEntry* e = &g_class_super[i];
        if (e->classLen == classLen &&
            strncasecmp(e->className, className, (size_t)classLen) == 0) {
            int sl = superLen < 63 ? superLen : 63;
            memcpy(e->superName, superName, sl); e->superName[sl] = '\0';
            e->superLen = sl;
            return;
        }
    }
    if (g_class_super_count >= MAX_CLASS_SUPER) {
        error_capacity_exceeded("MAX_CLASS_SUPER", MAX_CLASS_SUPER);
        return;
    }
    ClassSuperEntry* e = &g_class_super[g_class_super_count++];
    int cl = classLen < 63 ? classLen : 63;
    int sl = superLen < 63 ? superLen : 63;
    memcpy(e->className, className, cl); e->className[cl] = '\0'; e->classLen = cl;
    memcpy(e->superName, superName, sl); e->superName[sl] = '\0'; e->superLen = sl;
}

/*  — recherche une methode `methodName` dans `className` ou un
 * de ses ancetres (chaine via g_class_super), reposant uniquement sur les
 * declarations vues jusqu'ici dans la compile courante. Sert de fallback
 * quand projectSymbols est NULL (compile single-file hors projet). */
static bool find_declared_method_inherited(const char* className, int classLen,
                                           const char* methodName, int methodLen) {
    const char* cur = className;
    int curLen = classLen;
    for (int hops = 0; hops < 64; hops++) {
        if (find_declared_method(cur, curLen, methodName, methodLen) >= 0) {
            return true;
        }
        const char* nextName = NULL;
        int nextLen = 0;
        for (int i = 0; i < g_class_super_count; i++) {
            ClassSuperEntry* se = &g_class_super[i];
            if (se->classLen == curLen &&
                strncasecmp(se->className, cur, (size_t)curLen) == 0) {
                nextName = se->superName;
                nextLen  = se->superLen;
                break;
            }
        }
        if (!nextName || nextLen <= 0) return false;
        cur = nextName;
        curLen = nextLen;
    }
    return false;
}

/*  : hydrate g_class_constructor_arity[] + g_class_super[] depuis
 * les donnees prescan. Cf. compiler.h pour le pourquoi. */
void compiler_hydrate_constructor_arity_from_symbols(SymbolTable* t) {
    if (t == NULL) return;
    /* 1. Heritage : copie t->inheritances[] -> g_class_super[]. Necessaire
     *    pour que class_constructor_min_arity_inherited remonte la chaine
     *    parent quand cEnfant herite de cBase cross-file.
     *
     * Defense : on filtre les self-heritages (className == parentName) — le
     * prescan a un bug latent qui peut produire `cBase -> cBase` quand la
     * classe contient une `PROCEDURE ABSTRAITE Foo()` (pas de FIN, le
     * compteur cdepth ne redescend pas et le 2eme classe du fichier est
     * absorbee comme membre de la 1ere). Hydrater un self-heritage cree un
     * cycle dans g_class_super qui declenche class_is_same_or_derived a
     * boucler 64 hops -> cascade de 64 emissions sur certains checks
     * (notamment abstract_cross_check_global). Le fix complet du prescan
     * est hors-scope  ; le filtre defensif suffit. */
    for (int i = 0; i < t->inheritanceCount; i++) {
        const char* cn = t->inheritances[i].className;
        const char* pn = t->inheritances[i].parentName;
        if (cn[0] == '\0' || pn[0] == '\0') continue;
        if (strcasecmp(cn, pn) == 0) continue;  /* self-heritage : skip */
        class_super_register(cn, (int)strlen(cn), pn, (int)strlen(pn));
    }
    /* 2. Constructeurs : pour chaque entree classMethods[] avec
     *    methodName == "Constructeur", enregistre l'arite minimale (stockee
     *    dans paramCount du sig — convention prescan ). */
    for (int i = 0; i < t->classMethodCount; i++) {
        const char* cn = t->classMethods[i].className;
        const char* mn = t->classMethods[i].sig.name;
        if (cn[0] == '\0' || mn[0] == '\0') continue;
        if (strcasecmp(mn, "Constructeur") != 0 &&
            strcasecmp(mn, "Constructor") != 0) {
            continue;
        }
        int minArity = t->classMethods[i].sig.paramCount;
        class_constructor_arity_register(cn, (int)strlen(cn), minArity);
    }
}

/*  : hydrate g_class_field_vis[] depuis les membres prescan. Cf.
 * compiler.h. Ne touche que la visibilite (typeToken laisse a -1 : il n'est
 * consomme que pour la classe en cours de compile, cf. class_field_type_lookup
 * sur currentClass, jamais cross-fichier). */
void compiler_hydrate_field_vis_from_symbols(SymbolTable* t) {
    if (t == NULL) return;
    for (int i = 0; i < t->memberCount; i++) {
        ProjectMember* m = &t->members[i];
        if (m->visibility < 0) continue;  /* pas un champ de classe */
        int ol = (int)strlen(m->ownerType);
        int nl = (int)strlen(m->name);
        if (ol <= 0 || nl <= 0) continue;
        class_field_vis_register(m->ownerType, ol, m->name, nl,
                                 (OwlVisibility)m->visibility);
    }
}

/* Retourne true si `descendant` est égal à `ancestor` OU dérive de lui
 * (chaîne via g_class_super). Comparaison case-insensitive. */
static bool class_is_same_or_derived(const char* descendant, int descLen,
                                     const char* ancestor, int ancLen) {
    if (descLen <= 0 || ancLen <= 0) return false;
    /* Limite anti-cycle paranoïaque. */
    for (int hops = 0; hops < 64; hops++) {
        if (descLen == ancLen &&
            strncasecmp(descendant, ancestor, (size_t)descLen) == 0) {
            return true;
        }
        /* Cherche le super de descendant. */
        const char* nextName = NULL;
        int nextLen = 0;
        for (int i = 0; i < g_class_super_count; i++) {
            ClassSuperEntry* e = &g_class_super[i];
            if (e->classLen == descLen &&
                strncasecmp(e->className, descendant, (size_t)descLen) == 0) {
                nextName = e->superName;
                nextLen  = e->superLen;
                break;
            }
        }
        if (!nextName || nextLen <= 0) return false;
        descendant = nextName;
        descLen    = nextLen;
    }
    return false;
}

/* Cherche un field dans la classe ET sa chaîne d'héritage. Si trouvé,
 * remplit outOwnerStart et outOwnerLen avec le nom de la classe propriétaire
 * (celle qui déclare le field). Retourne la visibilité ou -1 si introuvable. */
static int class_field_vis_lookup_inherited(const char* className, int classLen,
                                            const char* fieldName, int fieldLen,
                                            const char** outOwnerStart,
                                            int* outOwnerLen) {
    const char* cur = className;
    int curLen = classLen;
    for (int hops = 0; hops < 64; hops++) {
        int v = class_field_vis_lookup(cur, curLen, fieldName, fieldLen);
        if (v >= 0) {
            if (outOwnerStart) *outOwnerStart = cur;
            if (outOwnerLen)   *outOwnerLen   = curLen;
            return v;
        }
        /* monte d'un cran */
        const char* nextName = NULL;
        int nextLen = 0;
        for (int i = 0; i < g_class_super_count; i++) {
            ClassSuperEntry* e = &g_class_super[i];
            if (e->classLen == curLen &&
                strncasecmp(e->className, cur, (size_t)curLen) == 0) {
                nextName = e->superName;
                nextLen  = e->superLen;
                break;
            }
        }
        if (!nextName || nextLen <= 0) return -1;
        cur = nextName;
        curLen = nextLen;
    }
    return -1;
}

/* ================================================================
 * METHOD VISIBILITY REGISTRY — visibilite des methodes
 * de classe et des procedures top-level.
 *
 * Une entree par methode/procedure declaree, capturee au parse du
 * mot-cle PROCEDURE. Pour les methodes : className renseigne. Pour
 * les procedures top-level : className == "" (chaine vide).
 * fileIdx permet le check cross-file des procedures top-level
 * PRIVEE (appelable uniquement depuis le fichier de declaration).
 *
 * Pattern aligne sur g_class_field_vis : compteur reset par
 * compiler_reset_poo_state() entre tests (testing.c), persistant
 * sur la duree d'un compile multi-fichier (project_run, --check).
 * ================================================================ */

typedef struct {
    char className[64];      /* "" si procedure top-level */
    int  classLen;
    char procName[64];
    int  procLen;
    OwlVisibility visibility;
    int  declaredLine;
    int  fileIdx;            /* index fichier pour cross-file check */
} MethodVisibilityEntry;
static MethodVisibilityEntry g_method_visibility[MAX_DECLARED_METHODS];
static int g_method_visibility_count = 0;

static int method_visibility_find_index(const char* className, int classLen,
                                        const char* procName, int procLen) {
    for (int i = 0; i < g_method_visibility_count; i++) {
        MethodVisibilityEntry* e = &g_method_visibility[i];
        if (e->classLen != classLen || e->procLen != procLen) continue;
        if (classLen > 0 &&
            strncasecmp(e->className, className, (size_t)classLen) != 0) continue;
        if (strncasecmp(e->procName, procName, (size_t)procLen) != 0) continue;
        return i;
    }
    return -1;
}

static void method_visibility_register(const char* className, int classLen,
                                       const char* procName, int procLen,
                                       OwlVisibility vis, int line, int fileIdx) {
    int existing = method_visibility_find_index(className, classLen,
                                                procName, procLen);
    if (existing >= 0) {
        /* Re-decl (test runner) : ecrase l'entree existante. */
        g_method_visibility[existing].visibility   = vis;
        g_method_visibility[existing].declaredLine = line;
        g_method_visibility[existing].fileIdx      = fileIdx;
        return;
    }
    if (g_method_visibility_count >= MAX_DECLARED_METHODS) {
        error_capacity_exceeded("MAX_DECLARED_METHODS", MAX_DECLARED_METHODS);
        return;
    }
    MethodVisibilityEntry* e = &g_method_visibility[g_method_visibility_count++];
    int cl = classLen < 63 ? classLen : 63;
    int pl = procLen  < 63 ? procLen  : 63;
    if (cl > 0) {
        memcpy(e->className, className, cl);
    }
    e->className[cl] = '\0';
    e->classLen = cl;
    memcpy(e->procName, procName, pl);
    e->procName[pl] = '\0';
    e->procLen = pl;
    e->visibility   = vis;
    e->declaredLine = line;
    e->fileIdx      = fileIdx;
}

/*  : hydrate g_method_visibility[] (visibilite des methodes de classe)
 * depuis classMethodVis[] du prescan. Remplace, dans la passe de contexte de
 * `owl --check <file> --project`, l'enregistrement des methodes voisines par le
 * full-compile : sans lui, un colon-ref :M() vers une methode heritee
 * d'une base declaree dans un AUTRE fichier remontait a tort "membre inconnu".
 * Cf. compiler.h. Idempotent (method_visibility_register ecrase par nom). */
void compiler_hydrate_method_vis_from_symbols(SymbolTable* t) {
    if (t == NULL) return;
    for (int i = 0; i < t->classMethodVisCount; i++) {
        const char* cn = t->classMethodVis[i].className;
        const char* mn = t->classMethodVis[i].methodName;
        int cl = (int)strlen(cn);
        int ml = (int)strlen(mn);
        if (cl <= 0 || ml <= 0) continue;
        method_visibility_register(cn, cl, mn, ml,
                                   (OwlVisibility)t->classMethodVis[i].visibility,
                                   t->classMethodVis[i].line,
                                   t->classMethodVis[i].fileIndex);
    }
}

/* Returns -1 si introuvable, sinon la visibilite + ligne + fileIdx via
 * outDeclaredLine / outFileIdx (peuvent etre NULL). Pour les methodes,
 * cherche d'abord dans la classe directe puis remonte la chaine
 * d'heritage (necessaire pour appeler une PROTEGE heritee depuis une
 * derivee : on doit savoir qui declare originalement la methode). */
static int method_visibility_lookup_inherited(const char* className, int classLen,
                                              const char* procName, int procLen,
                                              const char** outOwnerStart,
                                              int* outOwnerLen,
                                              int* outDeclaredLine) {
    const char* cur = className;
    int curLen = classLen;
    for (int hops = 0; hops < 64; hops++) {
        int idx = method_visibility_find_index(cur, curLen, procName, procLen);
        if (idx >= 0) {
            if (outOwnerStart)    *outOwnerStart    = cur;
            if (outOwnerLen)      *outOwnerLen      = curLen;
            if (outDeclaredLine)  *outDeclaredLine  = g_method_visibility[idx].declaredLine;
            return (int)g_method_visibility[idx].visibility;
        }
        /* monte d'un cran */
        const char* nextName = NULL;
        int nextLen = 0;
        for (int i = 0; i < g_class_super_count; i++) {
            ClassSuperEntry* e = &g_class_super[i];
            if (e->classLen == curLen &&
                strncasecmp(e->className, cur, (size_t)curLen) == 0) {
                nextName = e->superName;
                nextLen  = e->superLen;
                break;
            }
        }
        if (!nextName || nextLen <= 0) return -1;
        cur = nextName;
        curLen = nextLen;
    }
    return -1;
}

/* ================================================================
 * PENDING `:membre` REFERENCES — validation differee
 *
 * Probleme : le corps d'une methode inline est compile au fil du
 * parse du body de classe, AVANT que les champs/methodes declares
 * plus bas n'aient ete enregistres (g_class_field_vis /
 * g_method_visibility). Un check `:membre` immediat dans this_field()
 * produirait un faux positif sur toute reference-avant.
 *
 * Solution alignee sur interface_cross_check_global() : on enregistre
 * chaque acces `:membre` (champ OU appel methode) rencontre, puis on
 * valide en fin de compile via colon_member_cross_check_global(),
 * quand toutes les tables champs+methodes (chaine d'heritage incluse)
 * sont peuplees. La position du token `:` est memorisee pour pointer
 * l'erreur exactement comme le canon existant.
 *
 * Per-fichier : reset par compiler_reset_poo_state(). Le check ne
 * porte que sur les classes declarees dans le fichier courant.
 * ================================================================ */

typedef struct {
    char className[64];
    int  classLen;
    char memberName[64];
    int  memberLen;
    int  line;
    int  column;
} PendingColonRefEntry;
static PendingColonRefEntry g_pending_colon_refs[MAX_DECLARED_METHODS];
static int g_pending_colon_refs_count = 0;

static void colon_ref_pending_register(const char* className, int classLen,
                                       const char* memberName, int memberLen,
                                       int line, int column) {
    if (g_pending_colon_refs_count >= MAX_DECLARED_METHODS) {
        error_capacity_exceeded("MAX_DECLARED_METHODS", MAX_DECLARED_METHODS);
        return;
    }
    PendingColonRefEntry* e = &g_pending_colon_refs[g_pending_colon_refs_count++];
    int cl = classLen  < 63 ? classLen  : 63;
    int ml = memberLen < 63 ? memberLen : 63;
    memcpy(e->className, className, cl); e->className[cl] = '\0'; e->classLen = cl;
    memcpy(e->memberName, memberName, ml); e->memberName[ml] = '\0'; e->memberLen = ml;
    e->line   = line;
    e->column = column;
}

/* ================================================================
 * ABSTRACT REGISTRY — classes et methodes abstraites
 *
 * Suit le pattern g_class_super / g_class_interfaces (persistant cross-file).
 *   - g_class_abstract       : nom de classes marquees abstraites (soit
 *                              explicitement via `, abstraite` sur la decl,
 *                              soit implicitement si une de leurs methodes
 *                              externes est abstraite — canon 6010006
 *                              NOTE3_3).
 *   - g_class_abstract_methods : signatures (className, methodName) declarees
 *                                avec le mot-cle ABSTRAITE (sans corps).
 *
 * Les checks sont compile-time, en deux endroits :
 *   1. Site d'instanciation `o est un cX(...)` : compile-error si cX abstraite.
 *   2. Fin de compile : pour toute classe non-abstraite, parcourir la chaine
 *      d'heritage et verifier que chaque methode abstraite heritee a bien
 *      une implementation effective (redefinition). Sinon compile-error.
 *
 * En multi-fichier, la meme info est captee par prescan (cf. prescan.c +
 * SymbolTable.abstractClasses / abstractMethods) puis le check est fait
 * via symtable_verify_abstract avant le compile reel des fichiers.
 * ================================================================ */

typedef struct {
    char className[64];
    int  classLen;
} ClassAbstractEntry;
static ClassAbstractEntry g_class_abstract[MAX_ABSTRACT_CLASSES];
static int g_class_abstract_count = 0;

typedef struct {
    char className[64];
    int  classLen;
    char methodName[64];
    int  methodLen;
} ClassAbstractMethodEntry;
static ClassAbstractMethodEntry g_class_abstract_methods[MAX_DECLARED_METHODS];
static int g_class_abstract_methods_count = 0;

static bool class_is_abstract(const char* className, int classLen) {
    for (int i = 0; i < g_class_abstract_count; i++) {
        ClassAbstractEntry* e = &g_class_abstract[i];
        if (e->classLen == classLen &&
            strncasecmp(e->className, className, (size_t)classLen) == 0) {
            return true;
        }
    }
    return false;
}

static void class_abstract_register(const char* className, int classLen) {
    if (class_is_abstract(className, classLen)) return;
    if (g_class_abstract_count >= MAX_ABSTRACT_CLASSES) {
        error_capacity_exceeded("MAX_ABSTRACT_CLASSES", MAX_ABSTRACT_CLASSES);
        return;
    }
    ClassAbstractEntry* e = &g_class_abstract[g_class_abstract_count++];
    int cl = classLen < 63 ? classLen : 63;
    memcpy(e->className, className, cl); e->className[cl] = '\0';
    e->classLen = cl;
}

static void class_abstract_method_register(const char* className, int classLen,
                                           const char* methodName, int methodLen) {
    /* Skip doublons. */
    for (int i = 0; i < g_class_abstract_methods_count; i++) {
        ClassAbstractMethodEntry* e = &g_class_abstract_methods[i];
        if (e->classLen == classLen && e->methodLen == methodLen &&
            strncasecmp(e->className, className, (size_t)classLen) == 0 &&
            strncasecmp(e->methodName, methodName, (size_t)methodLen) == 0) {
            return;
        }
    }
    if (g_class_abstract_methods_count >= MAX_DECLARED_METHODS) {
        error_capacity_exceeded("MAX_DECLARED_METHODS", MAX_DECLARED_METHODS);
        return;
    }
    ClassAbstractMethodEntry* e =
        &g_class_abstract_methods[g_class_abstract_methods_count++];
    int cl = classLen < 63 ? classLen : 63;
    int ml = methodLen < 63 ? methodLen : 63;
    memcpy(e->className, className, cl); e->className[cl] = '\0'; e->classLen = cl;
    memcpy(e->methodName, methodName, ml); e->methodName[ml] = '\0';
    e->methodLen = ml;
    /* Canon : une classe avec une methode abstraite EST abstraite
     * (qu'elle ait ou non le mot-cle explicite). */
    class_abstract_register(className, classLen);
}

/* ================================================================
 * INTERFACE REGISTRY — persistant entre compiles
 *
 * Suit le meme pattern que g_class_super / g_class_field_vis :
 *   - g_interface_methods    : signatures des methodes declarees par chaque
 *                              interface (paramCount + paramTypes + returnType).
 *   - g_class_interfaces     : liens classe -> interface (un `implemente iX`
 *                              dans le body d'une CLASSE produit une entree).
 *   - g_declared_method_sigs : signatures des methodes externes effectivement
 *                              declarees (PROCEDURE cX.Foo(...) : type).
 *
 * Persistant entre fichiers d'un meme projet : compile_in_project reset
 * declaredMethods (table d'unicite locale) mais PAS ces tables-ci, sinon
 * le cross-check ne pourrait pas relier interface declaree dans iY.owl
 * et classe declaree dans cX.owl.
 *
 * Le cross-check final est fait dans compile_impl (mono-fichier) ; en
 * multi-fichier, c'est symtable_verify_interfaces (prescan-based) qui
 * couvre le check apres prescan de TOUS les fichiers. Les deux chemins
 * sont independants mais coherents : la regle de conformite est la meme.
 * ================================================================ */

typedef struct {
    char interfaceName[64];
    int  interfaceLen;
    char methodName[64];
    int  methodLen;
    int  paramCount;
    char paramTypes[MAX_METHOD_PARAMS][32]; /* "" si pas type explicite */
    char returnType[32];                    /* "" si pas de type retour */
} InterfaceMethodEntry;
static InterfaceMethodEntry g_interface_methods[MAX_INTERFACE_METHODS];
static int g_interface_methods_count = 0;

typedef struct {
    char className[64];
    int  classLen;
    char interfaceName[64];
    int  interfaceLen;
    int  declaredLine;
} ClassInterfaceEntry;
static ClassInterfaceEntry g_class_interfaces[MAX_CLASS_INTERFACES];
static int g_class_interfaces_count = 0;

/* Signatures des methodes externes effectivement declarees par les classes.
 * Couple avec declaredMethods[] mais persistant cross-file et incluant la
 * signature (param/retour) pour le check de divergence. */
typedef struct {
    char className[64];
    int  classLen;
    char methodName[64];
    int  methodLen;
    int  paramCount;
    char paramTypes[MAX_METHOD_PARAMS][32];
    char returnType[32];
} DeclaredMethodSigEntry;
static DeclaredMethodSigEntry g_declared_method_sigs[MAX_DECLARED_METHODS];
static int g_declared_method_sigs_count = 0;

/*  : reset des tables POO compile-time persistantes. Cible : le
 * test runner (testing.c) qui compile chaque test_*.owl dans une VM
 * fraiche. Sans ce reset, l'entree d'une classe abstraite ou la chaine
 * d'heritage du test precedent persiste et pollue la compilation suivante
 * — d'ou faux positifs (warning masquage champ herite, refus d'instancier
 * une classe pretendument abstraite, etc.). Seuls les compteurs sont
 * remis a zero : les tables elles-memes sont des tableaux statiques en
 * memoire (.bss), pas de heap a liberer. Une re-declaration ulterieure
 * ecrasera proprement les entrees lues a partir de l'index 0.
 *
 *  : ajout du reset des tables d'aliases DSL (push/pop stack
 * scopé, mais si crash mid-parse laisse stack non-poppé → pollution
 * latente) et surtout des user_procs (`g_user_proc_count`), qui
 * cumule cross-fichier et finit par saturer MAX_USER_PROCS (=512)
 * apres N tests. Symptome : "Capacity exceeded: too many user
 * procedures" en cascade puis segfault du runner sur les fichiers
 * suivants. La cause reelle de  dont l'audit avait conclu
 * faussement "pollution non observable" — le smoke test A→B etait
 * trop court pour deborder. */
/*  — forward decl. Definition plus bas, a cote de la table
 * g_user_procs (l. ~1165), pour eviter le forward-ref sur static int. */
static void user_procs_reset(void);

void compiler_reset_poo_state(void) {
    g_class_super_count           = 0;
    g_class_field_vis_count       = 0;
    g_class_abstract_count        = 0;
    g_class_abstract_methods_count = 0;
    g_class_interfaces_count      = 0;
    g_interface_methods_count     = 0;
    g_class_constants_count       = 0;
    g_declared_method_sigs_count  = 0;
    g_method_visibility_count     = 0;
    g_pending_colon_refs_count    = 0;
    g_class_globale_methods_count = 0;
    g_class_constructor_arity_count = 0;
    /*  — tables compile-time non-POO qui debordent cross-fichier. */
    user_procs_reset();
    /*  — registre des blocs ServiceREST collectes. Reset ici (entre
     * deux compilations independantes : fixtures, scenarios, requetes --check)
     * mais PAS entre fichiers d'un meme projet : la collecte s'accumule a
     * l'echelle projet, comme les types. */
    owl_service_registry_reset();
    /*  — le registre RUNTIME des routes est reset ICI aussi (debut de
     * compilation) : une compile fraiche reconstruit ses routes. Mais il n'est
     * PAS libere par owl_service_registry_reset apres compilation — il survit
     * jusqu'a l'execution, ou l'executeur HTTP le consulte. */
    owl_service_runtime_reset();
    g_dsl_alias_count             = 0;
    g_dsl_alias_stack_top         = 0;
    /*  lot 4 — mini-stack des decls control en cours de parse
     * (Lot 3-bis A1). Si une compile precedente a abort en plein body
     * (parse error remontee), le pop correspondant n'a pas eu lieu et
     * g_control_decl_stack contient des pointeurs vers des OwlControlDecl
     * libres par vm_free. Au premier alloc du fichier suivant sous
     * DEBUG_STRESS_GC, gc_mark_compiler_roots itere le stack et
     * dereference des pointeurs dangling -> segfault au setup du test
     * runner (avant tout output stdout). */
    g_control_decl_top            = 0;
}

static void interface_method_register(const char* ifaceName, int ifaceLen,
                                      const char* methodName, int methodLen,
                                      int paramCount,
                                      char paramTypes[][32],
                                      const char* returnType) {
    /* Eviter doublons (re-declaration cross-session). */
    for (int i = 0; i < g_interface_methods_count; i++) {
        InterfaceMethodEntry* e = &g_interface_methods[i];
        if (e->interfaceLen == ifaceLen && e->methodLen == methodLen &&
            strncasecmp(e->interfaceName, ifaceName, (size_t)ifaceLen) == 0 &&
            strncasecmp(e->methodName, methodName, (size_t)methodLen) == 0) {
            /* Ecrase l'entree existante avec la nouvelle signature. */
            e->paramCount = paramCount;
            for (int p = 0; p < paramCount && p < MAX_METHOD_PARAMS; p++) {
                strncpy(e->paramTypes[p], paramTypes[p], 31);
                e->paramTypes[p][31] = '\0';
            }
            strncpy(e->returnType, returnType ? returnType : "", 31);
            e->returnType[31] = '\0';
            return;
        }
    }
    /* Refus bruyant, et surtout PAS un `return` muet : sans entree dans cette
     * table, le contrat de l'interface cesse d'etre verifie pour les methodes
     * en trop — une classe qui n'en implemente qu'une partie compilait au vert
     *. Une limite atteinte ne doit jamais eteindre un controle. */
    if (g_interface_methods_count >= MAX_INTERFACE_METHODS) {
        error_capacity_exceeded("MAX_INTERFACE_METHODS", MAX_INTERFACE_METHODS);
        return;
    }
    InterfaceMethodEntry* e = &g_interface_methods[g_interface_methods_count++];
    int il = ifaceLen < 63 ? ifaceLen : 63;
    int ml = methodLen < 63 ? methodLen : 63;
    memcpy(e->interfaceName, ifaceName, il); e->interfaceName[il] = '\0';
    e->interfaceLen = il;
    memcpy(e->methodName, methodName, ml); e->methodName[ml] = '\0';
    e->methodLen = ml;
    e->paramCount = paramCount;
    memset(e->paramTypes, 0, sizeof(e->paramTypes));
    for (int p = 0; p < paramCount && p < MAX_METHOD_PARAMS; p++) {
        strncpy(e->paramTypes[p], paramTypes[p], 31);
        e->paramTypes[p][31] = '\0';
    }
    strncpy(e->returnType, returnType ? returnType : "", 31);
    e->returnType[31] = '\0';
}

static void class_interface_register(const char* className, int classLen,
                                     const char* ifaceName, int ifaceLen,
                                     int line) {
    /* Skip doublons (eviter de catcher 2x la meme paire). */
    for (int i = 0; i < g_class_interfaces_count; i++) {
        ClassInterfaceEntry* e = &g_class_interfaces[i];
        if (e->classLen == classLen && e->interfaceLen == ifaceLen &&
            strncasecmp(e->className, className, (size_t)classLen) == 0 &&
            strncasecmp(e->interfaceName, ifaceName, (size_t)ifaceLen) == 0) {
            return;
        }
    }
    /* Meme enjeu que interface_method_register : une relation non enregistree,
     * c'est une classe dont le contrat n'est plus verifie du tout. */
    if (g_class_interfaces_count >= MAX_CLASS_INTERFACES) {
        error_capacity_exceeded("MAX_CLASS_INTERFACES", MAX_CLASS_INTERFACES);
        return;
    }
    ClassInterfaceEntry* e = &g_class_interfaces[g_class_interfaces_count++];
    int cl = classLen < 63 ? classLen : 63;
    int il = ifaceLen < 63 ? ifaceLen : 63;
    memcpy(e->className, className, cl); e->className[cl] = '\0'; e->classLen = cl;
    memcpy(e->interfaceName, ifaceName, il); e->interfaceName[il] = '\0';
    e->interfaceLen = il;
    e->declaredLine = line;
}

static void declared_method_sig_register(const char* className, int classLen,
                                         const char* methodName, int methodLen,
                                         int paramCount,
                                         char paramTypes[][32],
                                         const char* returnType) {
    /* Ecrase si existant (re-compile du meme fichier). */
    for (int i = 0; i < g_declared_method_sigs_count; i++) {
        DeclaredMethodSigEntry* e = &g_declared_method_sigs[i];
        if (e->classLen == classLen && e->methodLen == methodLen &&
            strncasecmp(e->className, className, (size_t)classLen) == 0 &&
            strncasecmp(e->methodName, methodName, (size_t)methodLen) == 0) {
            e->paramCount = paramCount;
            memset(e->paramTypes, 0, sizeof(e->paramTypes));
            for (int p = 0; p < paramCount && p < MAX_METHOD_PARAMS; p++) {
                strncpy(e->paramTypes[p], paramTypes[p], 31);
                e->paramTypes[p][31] = '\0';
            }
            strncpy(e->returnType, returnType ? returnType : "", 31);
            e->returnType[31] = '\0';
            return;
        }
    }
    if (g_declared_method_sigs_count >= MAX_DECLARED_METHODS) {
        error_capacity_exceeded("MAX_DECLARED_METHODS", MAX_DECLARED_METHODS);
        return;
    }
    DeclaredMethodSigEntry* e = &g_declared_method_sigs[g_declared_method_sigs_count++];
    int cl = classLen < 63 ? classLen : 63;
    int ml = methodLen < 63 ? methodLen : 63;
    memcpy(e->className, className, cl); e->className[cl] = '\0'; e->classLen = cl;
    memcpy(e->methodName, methodName, ml); e->methodName[ml] = '\0'; e->methodLen = ml;
    e->paramCount = paramCount;
    memset(e->paramTypes, 0, sizeof(e->paramTypes));
    for (int p = 0; p < paramCount && p < MAX_METHOD_PARAMS; p++) {
        strncpy(e->paramTypes[p], paramTypes[p], 31);
        e->paramTypes[p][31] = '\0';
    }
    strncpy(e->returnType, returnType ? returnType : "", 31);
    e->returnType[31] = '\0';
}

/* Cherche une methode declaree pour `className` OU une de ses classes ancetres
 * (chaine via g_class_super). Retourne l'entree ou NULL. */
static DeclaredMethodSigEntry* declared_method_sig_lookup_inherited(
        const char* className, int classLen,
        const char* methodName, int methodLen) {
    const char* cur = className;
    int curLen = classLen;
    for (int hops = 0; hops < 64; hops++) {
        for (int i = 0; i < g_declared_method_sigs_count; i++) {
            DeclaredMethodSigEntry* e = &g_declared_method_sigs[i];
            if (e->classLen != curLen || e->methodLen != methodLen) continue;
            if (strncasecmp(e->className, cur, (size_t)curLen) != 0) continue;
            if (strncasecmp(e->methodName, methodName, (size_t)methodLen) != 0) continue;
            return e;
        }
        /* Monte d'un cran. */
        const char* nextName = NULL;
        int nextLen = 0;
        for (int i = 0; i < g_class_super_count; i++) {
            ClassSuperEntry* se = &g_class_super[i];
            if (se->classLen == curLen &&
                strncasecmp(se->className, cur, (size_t)curLen) == 0) {
                nextName = se->superName;
                nextLen  = se->superLen;
                break;
            }
        }
        if (!nextName || nextLen <= 0) return NULL;
        cur = nextName;
        curLen = nextLen;
    }
    return NULL;
}

/* is_known_class : itere knownUserTypes, filtre kind=CLASSE.
 * Remplace l'ancien knownClasses[] dedie qui dupliquait l'info. */
static bool is_known_class(const char* name, int length) {
    int idx = utype_find_index(name, length);  /*  : O(1) */
    return idx >= 0 && knownUserTypes[idx].kind == OWL_USER_TYPE_CLASSE;
}

/* V1.7-1 : table des PROCEDURE/FONCTION user-defined avec types params.
 * Permet `f({ ... })` quand un param a un type composé connu. */
typedef struct {
    char name[128];
    int  nameLen;
    int  paramCount;
    char paramTypes[MAX_USER_PROC_PARAMS][64];  /* "" si pas typé */
} UserProcInfo;
static UserProcInfo g_user_procs[MAX_USER_PROCS];
static int g_user_proc_count = 0;

/*  — reset entre fichiers de test (appele par compiler_reset_poo_state).
 * Les entries du tableau .bss sont laissees telles quelles : la prochaine
 * declaration ecrasera depuis l'index 0. */
static void user_procs_reset(void) {
    g_user_proc_count = 0;
}

static UserProcInfo* user_proc_find(const char* name, int len) {
    for (int i = 0; i < g_user_proc_count; i++) {
        if (g_user_procs[i].nameLen == len &&
            memcmp(g_user_procs[i].name, name, len) == 0) return &g_user_procs[i];
    }
    return NULL;
}

static UserProcInfo* user_proc_register(const char* name, int len) {
    UserProcInfo* existing = user_proc_find(name, len);
    if (existing) {
        /* re-decl : reset les params (peut etre un re-parse). */
        existing->paramCount = 0;
        memset(existing->paramTypes, 0, sizeof(existing->paramTypes));
        return existing;
    }
    if (g_user_proc_count >= MAX_USER_PROCS) {
        error_capacity_exceeded("MAX_USER_PROCS", MAX_USER_PROCS);
        return NULL;
    }
    UserProcInfo* p = &g_user_procs[g_user_proc_count++];
    int copy = len < (int)sizeof(p->name) - 1 ? len : (int)sizeof(p->name) - 1;
    memcpy(p->name, name, copy);
    p->name[copy] = '\0';
    p->nameLen = copy;
    p->paramCount = 0;
    memset(p->paramTypes, 0, sizeof(p->paramTypes));
    return p;
}

static void user_proc_add_param_type(UserProcInfo* p, const char* type, int typeLen) {
    if (!p) return;
    if (p->paramCount >= MAX_USER_PROC_PARAMS) {
        error_capacity_exceeded("MAX_USER_PROC_PARAMS", MAX_USER_PROC_PARAMS);
        return;
    }
    int copy = typeLen < (int)sizeof(p->paramTypes[0]) - 1 ? typeLen : (int)sizeof(p->paramTypes[0]) - 1;
    if (type && copy > 0) {
        memcpy(p->paramTypes[p->paramCount], type, copy);
        p->paramTypes[p->paramCount][copy] = '\0';
    } else {
        p->paramTypes[p->paramCount][0] = '\0';
    }
    p->paramCount++;
}

typedef struct {
    char name[128];
    int length;
    int line;
} PendingTypeRef;
static PendingTypeRef pendingTypeRefs[MAX_PENDING_TYPE_REFS];
static int pendingTypeRefCount = 0;

/* Note historique : un BUILTIN_TYPE_NAMES[] hardcoded existait ici. Il
 * dupliquait TYPES[] cote registry et derivait silencieusement. Remplace
 * par owl_resolve_type() ci-dessous qui consulte le registry comme seule
 * source de verite. Cf commit "refacto resolveur de type" pour le
 * detail des consommateurs migres. */

static bool name_iequals(const char* a, int a_len, const char* b) {
    int b_len = (int)strlen(b);
    if (a_len != b_len) return false;
    for (int i = 0; i < a_len; i++) {
        if (tolower((unsigned char)a[i]) != tolower((unsigned char)b[i])) return false;
    }
    return true;
}

/*  : compare un champ requete (deja accent-strippe) a un nom de
 * champ registry (`candidate`, potentiellement accentue) en mode
 * casse + accent-insensible. Strippe `candidate` puis compare lower. */
static bool inline_field_name_matches(const char* qStrip, int qLen,
                                      const char* candidate) {
    char cStrip[64];
    int cl = scanner_strip_accents(candidate, (int)strlen(candidate),
                                   cStrip, sizeof(cStrip));
    if (cl <= 0) return false;
    return name_iequals(qStrip, qLen, cStrip);
}

static void register_user_type(const char* name, int length, int declLine) {
    /*  — idempotent sur declLine : si l'entree existe deja (prescan
     * top-level qui pre-enregistre avant struct_declaration / class_declaration),
     * on remplace declLine=0 par la ligne reelle quand elle devient connue.
     * Sinon le check shadow type-top-level pointe ligne 0 au lieu de la vraie
     * ligne de la declaration. */
    int existing = utype_find_index(name, length);  /*  : O(1) */
    if (existing >= 0) {
        if (knownUserTypes[existing].declLine == 0 && declLine != 0) {
            knownUserTypes[existing].declLine = declLine;
        }
        return;
    }
    if (knownUserTypeCount >= MAX_USER_TYPES) {
        error_capacity_exceeded("MAX_USER_TYPES", MAX_USER_TYPES);
        return;
    }
    int len = length < 127 ? length : 127;
    memcpy(knownUserTypes[knownUserTypeCount].name, name, len);
    knownUserTypes[knownUserTypeCount].name[len] = '\0';
    knownUserTypes[knownUserTypeCount].length = len;
    knownUserTypes[knownUserTypeCount].fieldCount = 0;
    knownUserTypes[knownUserTypeCount].fieldFirst = -1;
    knownUserTypes[knownUserTypeCount].fieldLast  = -1;
    knownUserTypes[knownUserTypeCount].kind = OWL_USER_TYPE_UNKNOWN;
    /*  — marquer l'owner. TYPE_SCRIPT (top-level) = 0. TYPE_FUNCTION
     * (corps de procedure) = current->id. Idem pour TYPE_METHOD/CONSTRUCTOR
     * (corps de methode = un Compiler procedural). */
    knownUserTypes[knownUserTypeCount].ownerCompilerId =
        (current != NULL && current->type != TYPE_SCRIPT) ? current->id : 0;
    /*  — declLine peuple aux call sites qui ont le Token (declaration
     * directe du type dans ce fichier). 0 pour pre-population cross-file
     * (compile_in_project) ou la ligne d'origine est dans un autre fichier. */
    knownUserTypes[knownUserTypeCount].declLine = declLine;
    user_types_hash_link(knownUserTypeCount);  /*  */
    knownUserTypeCount++;
}

static void user_type_set_kind(const char* name, int length, OwlUserTypeKind kind) {
    int idx = utype_find_index(name, length);  /*  : O(1) */
    if (idx >= 0) knownUserTypes[idx].kind = kind;
}

/* Helper unifie : register + kind en un seul appel. Evite l'oubli du
 * user_type_set_kind apres register_user_type aux 5 call sites
 * historiques. */
static void register_user_type_kind(const char* name, int length,
                                     OwlUserTypeKind kind, int declLine) {
    register_user_type(name, length, declLine);
    /* user_type_set_kind est idempotent : pose kind sur la 1ere entree
     * matchante. register_user_type est devenu idempotent donc
     * "register puis set_kind" reste correct meme si l'entree pre-existait. */
    user_type_set_kind(name, length, kind);
}

static int user_type_index(const char* name, int length) {
    return utype_find_index(name, length);  /*  : O(1) */
}

static void user_type_add_field(const char* typeName, int typeLen,
                                const char* fieldName, int fieldLen,
                                const char* fieldType, int fieldTypeLen,
                                bool fieldIsContainer,
                                int fieldTypeLine, int fieldTypeColumn) {
    int idx = user_type_index(typeName, typeLen);
    if (idx < 0) return;
    /* Le budget est global, pas par type : le message doit parler du total
     * atteint, sans designer le type en cours de declaration. */
    if (userTypeFieldPoolCount >= MAX_USER_TYPE_FIELDS_TOTAL) {
        error_capacity_exceeded("MAX_USER_TYPE_FIELDS_TOTAL",
                                MAX_USER_TYPE_FIELDS_TOTAL);
        return;
    }
    int slot = userTypeFieldPoolCount++;
    int n = fieldLen < 63 ? fieldLen : 63;
    UserTypeField* f = &userTypeFieldPool[slot];
    f->next = -1;
    if (knownUserTypes[idx].fieldLast >= 0) {
        userTypeFieldPool[knownUserTypes[idx].fieldLast].next = slot;
    } else {
        knownUserTypes[idx].fieldFirst = slot;
    }
    knownUserTypes[idx].fieldLast = slot;
    knownUserTypes[idx].fieldCount++;
    memcpy(f->name, fieldName, n);
    f->name[n] = '\0';
    f->length = n;
    int tn = fieldTypeLen < 63 ? fieldTypeLen : 63;
    if (fieldType && tn > 0) {
        memcpy(f->typeName, fieldType, tn);
        f->typeName[tn] = '\0';
        f->typeLen = tn;
    } else {
        f->typeName[0] = '\0';
        f->typeLen = 0;
    }
    f->serialise_skip = false;
    f->serialise_rename[0] = '\0';
    f->visibility = OWL_VIS_PUBLIC;
    f->is_container = fieldIsContainer;
    f->typeLine = fieldTypeLine;
    f->typeColumn = fieldTypeColumn;
}

/*  — hydrate les champs (nom + type declare + conteneur?) d'une
 * STRUCTURE compagnon dans knownUserTypes, pour que user_type_find_field
 * reponde cross-fichier. Sans ces metadonnees, le garde `..prop` (gate
 * STRUCTURE) ne distingue pas un champ CONTENEUR (`s.dico..Occurrence`,
 * legitime) d'un champ SCALAIRE (`s.champ..prop`, mesusage) faute du type du
 * champ precedent. Les champs sont collectes au prescan projet dans
 * ProjectMember (, declType via prescan_capture_type_spec : premier
 * token du type — "tableau"/"associatif"/"array"/"associative" pour un
 * conteneur, sinon le nom du type). Appele UNIQUEMENT pour les structs
 * compagnons (fileIndex != courant) : les champs du fichier courant sont poses
 * par le prescan local (struct_declaration -> user_type_add_field), les
 * pre-hydrater ici les dupliquerait. */
static void hydrate_companion_struct_fields(const SymbolTable* symbols,
                                            const char* typeName, int typeLen,
                                            int selfFileIndex) {
    if (symbols == NULL) return;
    int idx = user_type_index(typeName, typeLen);
    if (idx < 0) return;
    if (knownUserTypes[idx].fieldCount > 0) return;  /* deja hydrate */
    for (int m = 0; m < symbols->memberCount; m++) {
        const ProjectMember* pm = &symbols->members[m];
        if (pm->fileIndex == selfFileIndex) continue;
        if (!name_iequals(typeName, typeLen, pm->ownerType)) continue;
        int dtl = (int)strlen(pm->declType);
        bool isContainer = dtl > 0 &&
            (name_iequals(pm->declType, dtl, "tableau")    ||
             name_iequals(pm->declType, dtl, "tableaux")   ||
             name_iequals(pm->declType, dtl, "array")      ||
             name_iequals(pm->declType, dtl, "associatif") ||
             name_iequals(pm->declType, dtl, "associative"));
        user_type_add_field(typeName, typeLen,
                            pm->name, (int)strlen(pm->name),
                            pm->declType, dtl, isContainer,
                            pm->line, pm->column);
    }
}

/* Forward decl — definition more bas. */
static const UserTypeField* user_type_find_field(const char* typeName, int typeLen,
                                                 const char* fieldName, int fieldLen);

/* Pose les attributs de sérialisation sur le DERNIER champ ajouté par
 * user_type_add_field. Appelé après le parse de la ligne de déclaration
 * du champ, à la lecture des attributs <…>. */
static void user_type_set_field_serialise(const char* typeName, int typeLen,
                                          bool skip, const char* rename, int renameLen) {
    int idx = user_type_index(typeName, typeLen);
    if (idx < 0) return;
    if (knownUserTypes[idx].fieldLast < 0) return;
    UserTypeField* f = &userTypeFieldPool[knownUserTypes[idx].fieldLast];
    f->serialise_skip = skip;
    if (rename && renameLen > 0) {
        int rn = renameLen < 63 ? renameLen : 63;
        memcpy(f->serialise_rename, rename, rn);
        f->serialise_rename[rn] = '\0';
    }
}

/* API publique pour le runtime (stdlib_json) : retrouve les attributs de
 * sérialisation d'un champ. Renvoie false si le type ou le champ n'est
 * pas connu compile-time. */
bool compiler_user_type_field_serialise(const char* typeName, int typeLen,
                                        const char* fieldName, int fieldLen,
                                        bool* outSkip, const char** outRename) {
    const UserTypeField* f = user_type_find_field(typeName, typeLen, fieldName, fieldLen);
    if (!f) return false;
    if (outSkip)   *outSkip = f->serialise_skip;
    if (outRename) *outRename = f->serialise_rename[0] ? f->serialise_rename : NULL;
    return true;
}

/* Variante recherche par rename (pour Désérialise) : trouve le champ
 * dont serialise_rename matche jsonKey (case+accent insensible). Renvoie
 * NULL si aucun. */
const char* compiler_user_type_field_by_rename(const char* typeName, int typeLen,
                                               const char* jsonKey, int jsonKeyLen,
                                               int* outFieldLen) {
    int idx = user_type_index(typeName, typeLen);
    if (idx < 0) return NULL;
    char keyStripped[64];
    int kl = scanner_strip_accents(jsonKey, jsonKeyLen, keyStripped, sizeof(keyStripped));
    for (int fi = knownUserTypes[idx].fieldFirst; fi >= 0; fi = userTypeFieldPool[fi].next) {
        UserTypeField* f = &userTypeFieldPool[fi];
        if (f->serialise_rename[0] == '\0') continue;
        char rnStripped[64];
        int rl = scanner_strip_accents(f->serialise_rename,
                                       (int)strlen(f->serialise_rename),
                                       rnStripped, sizeof(rnStripped));
        if (rl == kl && strncasecmp(keyStripped, rnStripped, (size_t)kl) == 0) {
            if (outFieldLen) *outFieldLen = f->length;
            return f->name;
        }
    }
    return NULL;
}

static const UserTypeField* user_type_find_field(const char* typeName, int typeLen,
                                                 const char* fieldName, int fieldLen) {
    int idx = user_type_index(typeName, typeLen);
    if (idx < 0) return NULL;
    /* Try strict match first, then accent-stripped match for accented field names. */
    for (int fi = knownUserTypes[idx].fieldFirst; fi >= 0; fi = userTypeFieldPool[fi].next) {
        UserTypeField* f = &userTypeFieldPool[fi];
        if (name_iequals(fieldName, fieldLen, f->name)) return f;
    }
    char strippedQ[64];
    int sql = scanner_strip_accents(fieldName, fieldLen, strippedQ, sizeof(strippedQ));
    for (int fi = knownUserTypes[idx].fieldFirst; fi >= 0; fi = userTypeFieldPool[fi].next) {
        UserTypeField* f = &userTypeFieldPool[fi];
        char strippedF[64];
        int sfl = scanner_strip_accents(f->name, f->length, strippedF, sizeof(strippedF));
        if (sfl == sql && strncasecmp(strippedQ, strippedF, (size_t)sql) == 0) return f;
    }
    return NULL;
}

static bool is_known_user_type(const char* name, int length) {
    return utype_find_index(name, length) >= 0;  /*  : O(1) */
}

/*  — le champ (de structure) supporte-t-il l'acces propriete `..` ?
 * Vrai pour un conteneur (tableau / tableau associatif : Occurrence, Ajoute...),
 * une structure/classe utilisateur, ou un type composé BUILTIN du registry
 * (httpRequête & co : fields non-NULL). Faux pour un scalaire (chaîne, entier...
 * : `s.champScalaire..prop` reste un vrai mésusage a refuser). */
static bool field_supports_property_access(const UserTypeField* f) {
    if (f == NULL) return false;
    if (f->is_container) return true;
    if (f->typeLen <= 0) return false;
    if (is_known_user_type(f->typeName, f->typeLen)) return true;
    char probe[64];
    int n = f->typeLen < 63 ? f->typeLen : 63;
    memcpy(probe, f->typeName, (size_t)n);
    probe[n] = '\0';
    const OwlTypeDef* td = owl_registry_type_find(probe);
    return td != NULL && td->fields != NULL;
}

/*  — le nom designe-t-il une STRUCTURE (utilisateur) ? Positif et
 * exclusif : classe / enum / combi / builtin renvoient false. Deux sources :
 *   1. knownUserTypes local si son kind est renseigne (cas structure imbriquee
 *      dans une classe, ou top-level du meme fichier — kind pose par
 *      register_user_type_kind).
 *   2. table de symboles projet (SYM_STRUCT) pour un type top-level d'un
 *      fichier voisin : le prescan cross-fichier enregistre alors le type dans
 *      knownUserTypes SANS poser son kind (reste UNKNOWN), d'ou le repli. */
static bool type_name_is_structure(const char* name, int length) {
    int idx = user_type_index(name, length);
    if (idx >= 0 && knownUserTypes[idx].kind != OWL_USER_TYPE_UNKNOWN) {
        return knownUserTypes[idx].kind == OWL_USER_TYPE_STRUCTURE;
    }
    if (projectSymbols != NULL) {
        bool ambig = false;
        ProjectSymbol* sym = symtable_find(projectSymbols, name, length, &ambig);
        if (sym != NULL) return sym->kind == SYM_STRUCT;
    }
    return false;
}

/*  — vrai si le type de parametre nomme le type FichierTéléversé
 * (forme FR accentuee/ASCII) ou son alias EN UploadedFile. Comparaison
 * accent-strippee, casse-insensible (invariants 1/2). Un tel parametre est une
 * source de liaison multipart valide (pas un scalaire sans source). */
static bool type_name_is_file_upload(const char* name, int length) {
    if (name == NULL || length <= 0) return false;
    char probe[64];
    int n = scanner_strip_accents(name, length, probe, sizeof(probe));
    if (n <= 0) return false;
    return strcasecmp(probe, "FichierTeleverse") == 0 ||
           strcasecmp(probe, "UploadedFile") == 0;
}

/* ================================================================
 * Resolveur de type unifie — seule API pour repondre "X est-il un type
 * valide pour `var est un X`".
 *
 * Avant refacto : 3 fonctions paralleles (is_builtin_type avec liste
 * hardcoded, is_known_user_type, is_known_class) + un is_any_known_type
 * qui orchestrait avec ordre implicite et fallback registry.
 *
 * Apres refacto : owl_resolve_type retourne un OwlTypeResolution qui dit
 * d'ou vient le type (builtin registry, user local, projet). Ordre de
 * priorite explicite. Pas de tableau hardcoded annexe — TYPES[] cote
 * stdlib_builtin_types.c est la source unique de verite pour les
 * builtins. zipArchive et tout type "opaque" (fields=NULL) y vit aussi.
 * ================================================================ */
typedef enum {
    OWL_TR_UNKNOWN = 0,
    OWL_TR_BUILTIN,       /* OwlTypeDef du registry */
    OWL_TR_USER_LOCAL,    /* declare dans le fichier courant (STRUCTURE/CLASSE/ENUMERATION) */
} OwlTypeResolutionKind;

/* Cherche par ordre de priorite : (1) user-defined local (STRUCTURE/CLASSE/
 * ENUMERATION), (2) builtin registry. La 3e couche "project-wide user"
 * existait conceptuellement mais n'est pas active a ce niveau — les
 * symboles projet sont consultes ailleurs (is_type_not_variable).
 *
 * Note : on ne retourne que le kind. Si un futur caller a besoin du
 * OwlTypeDef* (builtin) ou de l'index user_local (knownUserTypes), il
 * sera trivial de relancer un owl_registry_type_find / user_type_index
 * a partir du nom — pas besoin de cacher ces pointeurs ici aujourd'hui. */
static OwlTypeResolutionKind owl_resolve_type(const char* name, int length) {
    /* 1. User types declares dans ce fichier. */
    if (utype_find_index(name, length) >= 0) {  /*  : O(1) */
        return OWL_TR_USER_LOCAL;
    }

    /* 2. Registry — couvre les types builtin (Chrono, httpRequête, Cadre,
     *    Coin, Trait, Option, zipArchive opaque, etc.). */
    char probe[128];
    int n = length < (int)sizeof(probe) - 1 ? length : (int)sizeof(probe) - 1;
    memcpy(probe, name, n);
    probe[n] = '\0';
    if (owl_registry_type_find(probe)) {
        return OWL_TR_BUILTIN;
    }
    /* Les enums du registry NE SONT PAS des types declarables. Un nom d'enum
     * (httpMéthodes, sensÉcriture, sqlBackend...) employe comme type de
     * variable est rejete comme un type inconnu. Les enums restent une
     * metadonnee : contrainte de param (allowedBase) + valeurs resolubles
     * comme constantes. Cf. ADR retrait enum-as-type. */
    return OWL_TR_UNKNOWN;
}

/* Forward declaration - implementation after g_declaredGlobals is defined */
static bool is_any_known_type(const char* name, int length);
static bool is_collection_qualified_type(const char* name, int length);

static void record_pending_type_ref(Token tok) {
    if (pendingTypeRefCount >= MAX_PENDING_TYPE_REFS) {
        error_capacity_exceeded("MAX_PENDING_TYPE_REFS", MAX_PENDING_TYPE_REFS);
        return;
    }
    int len = tok.length < 127 ? tok.length : 127;
    memcpy(pendingTypeRefs[pendingTypeRefCount].name, tok.start, len);
    pendingTypeRefs[pendingTypeRefCount].name[len] = '\0';
    pendingTypeRefs[pendingTypeRefCount].length = len;
    pendingTypeRefs[pendingTypeRefCount].line = tok.line;
    pendingTypeRefCount++;
}

/*  /  — canonicalise un token de nom de type builtin vers la
 * forme canon du registry (`HTTPREQUÊTE` -> `httpRequete`). No-op si le nom
 * n'est pas un builtin (user type : la casse du token source fait foi). Partage
 * entre var_declaration et le parsing des types de parametres pour que le
 * record_pending_type_ref voie une forme stable. */
static void canonicalize_builtin_type_token(Token* tok) {
    char probe[128];
    int n = tok->length < (int)sizeof(probe) - 1
                ? tok->length : (int)sizeof(probe) - 1;
    memcpy(probe, tok->start, n);
    probe[n] = '\0';
    const OwlTypeDef* td = owl_registry_type_find(probe);
    if (td != NULL && td->canonical != NULL) {
        tok->start  = td->canonical;
        tok->length = (int)strlen(td->canonical);
    }
}

/* Walk pending refs after the full file has been parsed and report any that
 * don't resolve to a declared type. Handles forward references because user
 * declarations have all been recorded by the time we validate. */
static void validate_pending_type_refs(void) {
    for (int i = 0; i < pendingTypeRefCount; i++) {
        const PendingTypeRef* r = &pendingTypeRefs[i];
        if (is_any_known_type(r->name, r->length)) continue;
        /*  — position de type qualifiée `COL.Type` : le nom manglé
         * `COL$Type` est valide dès que (COL, Type) est un membre-type connu. */
        if (is_collection_qualified_type(r->name, r->length)) continue;

        /* Reset panic mode between distinct type errors so we emit all of them */
        parser.panicMode = false;

        Token synthetic;
        synthetic.start = r->name;
        synthetic.length = r->length;
        synthetic.line = r->line;
        synthetic.column = 0;
        synthetic.type = TOKEN_IDENTIFIER;
        char nameBuf[128];
        snprintf(nameBuf, sizeof(nameBuf), "%.127s", r->name);
        owl_emit_error_at(&synthetic, E_SEM_UNKNOWN_TYPE,
                          "name", nameBuf,
                          NULL);
    }
}

/*  : check de conformite des contrats `cX implemente iY`.
 *
 * Pour chaque entree g_class_interfaces :
 *   - resout l'interface dans g_interface_methods (ensemble des methodes
 *     signees),
 *   - pour chaque methode requise, cherche une declaration dans la classe
 *     ou ses ancetres (via declared_method_sig_lookup_inherited),
 *   - emit error si methode manquante ou signature divergente.
 *
 * "Signature divergente" = paramCount different OU returnType different
 * (comparaison case-insensible nom de type). Les paramTypes individuels
 * sont compares quand l'interface ET la classe en fournissent ; on est
 * permissif si l'un des deux est vide (declaration sans `est un type`)
 * pour eviter les faux positifs sur les types implicites.
 *
 * Mono-fichier : appele a la fin de compile_impl, voit toutes les
 * interfaces + classes du fichier (interfaces ont ete enregistrees
 * en amont via interface_method_register, classes via class_interface_register
 * + declared_method_sig_register).
 *
 * Multi-fichier : pas appele depuis compile_in_project (cf. ordre alphabetique
 * non-deterministe — cBase compile avant iBase). Le check passe par
 * symtable_verify_interfaces dans prescan.c sur l'ensemble pre-scanne. */
static void interface_cross_check_global(void) {
    for (int ci = 0; ci < g_class_interfaces_count; ci++) {
        ClassInterfaceEntry* link = &g_class_interfaces[ci];

        /* Filtre : ne check que les classes effectivement declarees dans CE
         * fichier (knownUserTypes contient les types declares dans ce file).
         * Sans ce filtre, on relancerait le check sur une classe d'un autre
         * fichier dont l'interface n'est peut-etre pas visible ici (faux
         * positif). */
        bool classDeclaredHere = false;
        for (int k = 0; k < knownUserTypeCount; k++) {
            if (knownUserTypes[k].length == link->classLen &&
                knownUserTypes[k].kind == OWL_USER_TYPE_CLASSE &&
                strncasecmp(knownUserTypes[k].name, link->className,
                            (size_t)link->classLen) == 0) {
                classDeclaredHere = true;
                break;
            }
        }
        if (!classDeclaredHere) continue;

        Token syntheticClassTok;
        syntheticClassTok.start = link->className;
        syntheticClassTok.length = link->classLen;
        syntheticClassTok.line = link->declaredLine;
        syntheticClassTok.column = 0;
        syntheticClassTok.type = TOKEN_IDENTIFIER;

        /* Parcourt toutes les methodes signees de cette interface. */
        bool interfaceFound = false;
        for (int mi = 0; mi < g_interface_methods_count; mi++) {
            InterfaceMethodEntry* method = &g_interface_methods[mi];
            if (method->interfaceLen != link->interfaceLen) continue;
            if (strncasecmp(method->interfaceName, link->interfaceName,
                            (size_t)link->interfaceLen) != 0) continue;
            interfaceFound = true;

            /* Cherche la methode dans la classe + chaine d'heritage. */
            DeclaredMethodSigEntry* impl =
                declared_method_sig_lookup_inherited(
                    link->className, link->classLen,
                    method->methodName, method->methodLen);

            if (impl == NULL) {
                parser.panicMode = false;
                char classBuf[128], ifaceBuf[128], methBuf[128];
                snprintf(classBuf, sizeof(classBuf), "%.*s",
                         link->classLen, link->className);
                snprintf(ifaceBuf, sizeof(ifaceBuf), "%.*s",
                         link->interfaceLen, link->interfaceName);
                snprintf(methBuf, sizeof(methBuf), "%.*s",
                         method->methodLen, method->methodName);
                owl_emit_error_at(&syntheticClassTok,
                                  E_SEM_INTERFACE_METHOD_MISSING,
                                  "class", classBuf,
                                  "interface", ifaceBuf,
                                  "method", methBuf,
                                  NULL);
                continue;
            }

            /* Compare la signature : nombre de parametres. */
            if (impl->paramCount != method->paramCount) {
                parser.panicMode = false;
                char classBuf[128], ifaceBuf[128], methBuf[128];
                char expBuf[16], gotBuf[16];
                snprintf(classBuf, sizeof(classBuf), "%.*s",
                         link->classLen, link->className);
                snprintf(ifaceBuf, sizeof(ifaceBuf), "%.*s",
                         link->interfaceLen, link->interfaceName);
                snprintf(methBuf, sizeof(methBuf), "%.*s",
                         method->methodLen, method->methodName);
                snprintf(expBuf, sizeof(expBuf), "%d", method->paramCount);
                snprintf(gotBuf, sizeof(gotBuf), "%d", impl->paramCount);
                owl_emit_error_at(&syntheticClassTok,
                                  E_SEM_INTERFACE_PARAM_COUNT_MISMATCH,
                                  "method", methBuf,
                                  "class", classBuf,
                                  "interface", ifaceBuf,
                                  "expected", expBuf,
                                  "got", gotBuf,
                                  NULL);
                continue;
            }

            /* Compare le type de retour (permissif si l'un des deux est ""). */
            if (method->returnType[0] != '\0' && impl->returnType[0] != '\0' &&
                strcasecmp(method->returnType, impl->returnType) != 0) {
                parser.panicMode = false;
                char classBuf[128], ifaceBuf[128], methBuf[128];
                snprintf(classBuf, sizeof(classBuf), "%.*s",
                         link->classLen, link->className);
                snprintf(ifaceBuf, sizeof(ifaceBuf), "%.*s",
                         link->interfaceLen, link->interfaceName);
                snprintf(methBuf, sizeof(methBuf), "%.*s",
                         method->methodLen, method->methodName);
                owl_emit_error_at(&syntheticClassTok,
                                  E_SEM_INTERFACE_RETURN_TYPE_MISMATCH,
                                  "method", methBuf,
                                  "class", classBuf,
                                  "interface", ifaceBuf,
                                  "expected", method->returnType,
                                  "got", impl->returnType,
                                  NULL);
                continue;
            }

            /* Compare les types de parametres position par position
             * (permissif si l'un des deux est non type).
             *
             * La borne MAX_METHOD_PARAMS n'ecrete rien ici : une signature qui
             * la depasse est refusee des sa declaration, donc aucune
             * comparaison ne porte sur une entree tronquee. paramCount, lui,
             * est toujours le nombre REEL de parametres — c'est ce qui rend le
             * compte ci-dessus fiable des deux cotes. */
            for (int p = 0; p < method->paramCount && p < MAX_METHOD_PARAMS; p++) {
                if (method->paramTypes[p][0] != '\0' &&
                    impl->paramTypes[p][0] != '\0' &&
                    strcasecmp(method->paramTypes[p],
                               impl->paramTypes[p]) != 0) {
                    parser.panicMode = false;
                    char classBuf[128], ifaceBuf[128], methBuf[128], posBuf[16];
                    snprintf(classBuf, sizeof(classBuf), "%.*s",
                             link->classLen, link->className);
                    snprintf(ifaceBuf, sizeof(ifaceBuf), "%.*s",
                             link->interfaceLen, link->interfaceName);
                    snprintf(methBuf, sizeof(methBuf), "%.*s",
                             method->methodLen, method->methodName);
                    snprintf(posBuf, sizeof(posBuf), "%d", p + 1);
                    owl_emit_error_at(&syntheticClassTok,
                                      E_SEM_INTERFACE_PARAM_TYPE_MISMATCH,
                                      "method", methBuf,
                                      "class", classBuf,
                                      "interface", ifaceBuf,
                                      "position", posBuf,
                                      "expected", method->paramTypes[p],
                                      "got", impl->paramTypes[p],
                                      NULL);
                    break;
                }
            }
        }

        /* L'interface n'a aucune methode signee enregistree : soit elle est
         * vide (legal — pas d'erreur), soit elle est dans un autre fichier
         * pas encore vu. En mono-fichier on n'a pas de cas "autre fichier",
         * donc on laisse passer (interface vide ne casse pas le contrat). */
        (void)interfaceFound;
    }
}

/*  : validation differee des acces `:membre`. Pour chaque
 * reference `:membre` collectee pendant le compile, on verifie que le
 * nom est declare comme champ OU comme methode dans la classe
 * proprietaire OU un de ses ancetres. Sinon compile-error pointant le
 * token `:`.
 *
 * Filtre : ne valide que les references dont la classe proprietaire est
 * declaree dans CE fichier (knownUserTypes) — comme interface/abstract
 * cross-check, pour eviter un faux positif sur une entree persistante
 * heritee d'un autre fichier dont la table n'est pas complete ici. En
 * pratique chaque `:membre` provient toujours d'une methode de la classe
 * du fichier courant, donc le filtre passe. */
static void colon_member_cross_check_global(void) {
    /*  : si une faute a deja ete reportee pour ce fichier, on ne
     * fait pas tourner ce cross-check differe. Un parse-error dans un corps
     * de methode (ex : bloc `< IF >` de compilation conditionnelle non
     * supporte) peut faire deriver le parser hors du body, si bien qu'une
     * methode pourtant definie ne s'enregistre pas dans la table. Le check
     * conclurait alors a un "membre inconnu" fantome. Les tables de methodes
     * sont potentiellement incompletes apres file-error : la cascade n'est
     * pas fiable. La cause racine (la vraie erreur de syntaxe) est deja
     * signalee. hadFileError est reset par fichier. */
    if (parser.hadFileError) return;
    for (int r = 0; r < g_pending_colon_refs_count; r++) {
        PendingColonRefEntry* ref = &g_pending_colon_refs[r];

        bool classDeclaredHere = false;
        for (int k = 0; k < knownUserTypeCount; k++) {
            if (knownUserTypes[k].length == ref->classLen &&
                knownUserTypes[k].kind == OWL_USER_TYPE_CLASSE &&
                strncasecmp(knownUserTypes[k].name, ref->className,
                            (size_t)ref->classLen) == 0) {
                classDeclaredHere = true;
                break;
            }
        }
        if (!classDeclaredHere) continue;

        int fieldVis = class_field_vis_lookup_inherited(
            ref->className, ref->classLen,
            ref->memberName, ref->memberLen, NULL, NULL);
        if (fieldVis >= 0) continue;

        int methodVis = method_visibility_lookup_inherited(
            ref->className, ref->classLen,
            ref->memberName, ref->memberLen, NULL, NULL, NULL);
        if (methodVis >= 0) continue;

        parser.panicMode = false;
        Token at;
        at.start = ref->memberName;
        at.length = ref->memberLen;
        at.line = ref->line;
        at.column = ref->column;
        at.type = TOKEN_IDENTIFIER;

        char memberBuf[128], classBuf[128];
        /* Le nom est rendu AVEC le ':' de tete (canon du message). */
        snprintf(memberBuf, sizeof(memberBuf), ":%.*s",
                 ref->memberLen, ref->memberName);
        snprintf(classBuf, sizeof(classBuf), "%.*s",
                 ref->classLen, ref->className);
        owl_emit_error_at(&at, E_SEM_COLON_MEMBER_UNKNOWN,
                          "member", memberBuf,
                          "class", classBuf,
                          NULL);
    }
}

/*  : cross-check des classes non-abstraites face aux methodes
 * abstraites heritees.
 *
 * Pour chaque classe declaree dans CE fichier ET non-abstraite :
 *   - parcourt sa chaine d'heritage (g_class_super) pour trouver les
 *     methodes abstraites declarees par les ancetres (g_class_abstract_methods),
 *   - verifie qu'une redefinition existe : declared_method_sig_lookup_inherited
 *     (qui regarde la classe + ses ancetres pour trouver une PROCEDURE
 *     cX.Method() *normale* — pas abstraite).
 *   - emit compile-error si une methode abstraite n'est pas redefinie.
 *
 * Une "redefinition" est une entree g_declared_method_sigs sur la classe
 * concrete OU un ancetre intermediaire concret. Comme g_declared_method_sigs
 * est aliment par toutes les PROCEDURE cX.Foo() (sauf abstraites), c'est
 * suffisant pour distinguer redefinition concrete vs abstraite. */
static void abstract_cross_check_global(void) {
    for (int k = 0; k < knownUserTypeCount; k++) {
        if (knownUserTypes[k].kind != OWL_USER_TYPE_CLASSE) continue;
        const char* cName = knownUserTypes[k].name;
        int cLen = knownUserTypes[k].length;
        if (class_is_abstract(cName, cLen)) continue;

        /* Parcourt toute la chaine d'ancetres et collecte les methodes
         * abstraites. */
        const char* cur = cName;
        int curLen = cLen;
        for (int hops = 0; hops < 64; hops++) {
            const char* nextName = NULL;
            int nextLen = 0;
            for (int i = 0; i < g_class_super_count; i++) {
                ClassSuperEntry* e = &g_class_super[i];
                if (e->classLen == curLen &&
                    strncasecmp(e->className, cur, (size_t)curLen) == 0) {
                    nextName = e->superName;
                    nextLen  = e->superLen;
                    break;
                }
            }
            if (!nextName || nextLen <= 0) break;
            /* Cherche methodes abstraites sur cet ancetre. */
            for (int m = 0; m < g_class_abstract_methods_count; m++) {
                ClassAbstractMethodEntry* am = &g_class_abstract_methods[m];
                if (am->classLen != nextLen) continue;
                if (strncasecmp(am->className, nextName,
                                (size_t)nextLen) != 0) continue;
                /* Cherche redefinition concrete dans cName ou ancetres
                 * intermediaires (entre cName exclus et nextName exclus).
                 * On utilise declared_method_sig_lookup_inherited qui ne
                 * matche que les methodes EFFECTIVEMENT declarees (non
                 * abstraites, car celles-ci ne sont pas inscrites dans
                 * g_declared_method_sigs — verifier). */
                DeclaredMethodSigEntry* impl =
                    declared_method_sig_lookup_inherited(
                        cName, cLen,
                        am->methodName, am->methodLen);
                /* Si impl existe, verifier qu'il n'est pas pose par
                 * l'ancetre abstrait lui-meme. */
                bool isRedefined = false;
                if (impl) {
                    /* impl->className peut etre = nextName (l'ancetre
                     * abstrait) — dans ce cas pas une vraie redefinition.
                     * Mais comme on n'enregistre PAS dans
                     * g_declared_method_sigs les methodes ABSTRAITES (cf.
                     * branche isAbstractMethod dans proc_declaration),
                     * impl est forcement concret. */
                    isRedefined = true;
                }
                if (!isRedefined) {
                    parser.panicMode = false;
                    Token syn;
                    syn.start = cName;
                    syn.length = cLen;
                    syn.line = 1;
                    syn.column = 0;
                    syn.type = TOKEN_IDENTIFIER;
                    char classBuf[128], methBuf[128], parentBuf[128];
                    snprintf(classBuf, sizeof(classBuf), "%.*s", cLen, cName);
                    snprintf(methBuf, sizeof(methBuf), "%.*s",
                             am->methodLen, am->methodName);
                    snprintf(parentBuf, sizeof(parentBuf), "%.*s",
                             nextLen, nextName);
                    owl_emit_error_at(&syn,
                                      E_SEM_ABSTRACT_METHOD_NOT_REDEFINED,
                                      "class", classBuf,
                                      "method", methBuf,
                                      "parent", parentBuf,
                                      NULL);
                }
            }
            cur = nextName;
            curLen = nextLen;
        }
    }
}

static Chunk* current_chunk(void) {
    return current->function->chunk;
}

/* ================================================================
 * GLOBAL USAGE TRACKING (for unused-variable warnings on script-level globals)
 * ================================================================ */

typedef struct {
    char name[64];
    int  nameLen;
    int  line;
    bool isUsed;
    bool hasInitializer;
    bool isStructureType;  /* true if this is a STRUCTURE declaration, not a variable */
    bool isPrescanned;     /* B.2 : ajoute par prescan_source_unified (forward
                            * ref support). Quand le compile principal rencontre
                            * la decl reelle, l'entree est "consommee" et perd
                            * ce flag — pas un doublon. */
    bool isFromNeighbor;   /*  : entree alimentee par
                            * hydrate_globals_from_neighbors depuis un fichier
                            * voisin du projet. Sert UNIQUEMENT a alimenter le
                            * shadow check (champ Fenetre / Etat / var locale
                            * qui collisionne avec un global declare ailleurs
                            * dans le meme projet). Skip dans :
                            *   - duplicate-decl path (declare_variable)
                            *   - consume-prescan path (declare_variable)
                            *   - warn_unused_globals (pas notre global)
                            * Pas de proprio fichier dans le message d'erreur :
                            * on emet E_SEM_VAR_SHADOWS_OUTER_SCOPE comme en
                            * mono-fichier, la ligne pointe le voisin. */
    bool isProcedure;      /*  : true si ce global materialise une
                            * PROCEDURE top-level (fonctions = globals first-
                            * class). Sert a emettre E_SEM_DUPLICATE_PROC_IN_SCOPE
                            * plutot que le message "variable" sur collision. */
    bool suppressUnused;   /*  : attribut <utile>/<useful> pose sur la
                            * declaration -> exempte de W_SEM_VAR_UNUSED (opt-out
                            * explicite, pendant nomme du prefixe `_`). */
    int hashNext;          /*  : chainage dans le bucket de
                            * g_declHashHead (-1 = fin de chaine). */
} DeclaredGlobal;

static DeclaredGlobal g_declaredGlobals[MAX_DECLARED_GLOBALS];
static int g_declaredGlobalsCount = 0;

/*  — index de hash sur g_declaredGlobals, cle = forme CANONIQUE de
 * l'identifiant (scanner_canonicalize_identifier : strip accents + lower), la
 * MEME que decl_globals_match. Rend le dedup/membership O(1) au lieu du scan
 * lineaire O(g_declaredGlobalsCount) qui, rejoue par fichier sur les globales
 * voisines (neighbor_replay_globals), etait la queue quadratique dominante.
 *
 * Contrairement a knownUserTypes, un meme nom PEUT avoir plusieurs entrees
 * (prescan + decl reelle + entree voisine + entree structure) : le chainage
 * porte donc TOUTES les entrees d'une cle. On APPEND EN QUEUE a l'insertion,
 * donc chaque chaine est en ordre d'INDEX CROISSANT : parcourir la chaine
 * d'un bucket visite les entrees de la cle exactement dans l'ordre du scan
 * lineaire historique `for (i=0..count)`. Les consommateurs sensibles a
 * l'ordre (dedup "premier gagne", `continue`/`return` sur la 1ere entree
 * actionnable, nom canonique de la 1ere entree) restent donc byte-identiques.
 * La table ordonnee reste la source de verite ; l'index n'evite que le scan. */
#define DECL_HASH_BUCKETS 8192  /* > 2x MAX_DECLARED_GLOBALS (4096), puissance de 2 */
static int g_declHashHead[DECL_HASH_BUCKETS];
static int g_declHashTail[DECL_HASH_BUCKETS];
static bool g_declHashInit = false;
static bool decl_globals_match(int idx, const char* name, int len);  /* def plus bas */

static uint32_t decl_hash_key(const char* name, int len) {
    char canon[256];
    int cl = scanner_canonicalize_identifier(name, len, canon, sizeof(canon));
    uint32_t h = 2166136261u;
    for (int i = 0; i < cl; i++) { h ^= (unsigned char)canon[i]; h *= 16777619u; }
    return h & (DECL_HASH_BUCKETS - 1);
}

static void decl_globals_hash_reset(void) {
    for (int i = 0; i < DECL_HASH_BUCKETS; i++) {
        g_declHashHead[i] = -1;
        g_declHashTail[i] = -1;
    }
    g_declHashInit = true;
}

static void decl_globals_hash_link(int idx) {
    if (!g_declHashInit) decl_globals_hash_reset();
    uint32_t b = decl_hash_key(g_declaredGlobals[idx].name,
                               g_declaredGlobals[idx].nameLen);
    g_declaredGlobals[idx].hashNext = -1;
    if (g_declHashTail[b] == -1) {
        g_declHashHead[b] = idx;
    } else {
        g_declaredGlobals[g_declHashTail[b]].hashNext = idx;
    }
    g_declHashTail[b] = idx;
}

/* Reset conjoint compteur + index (remplace `g_declaredGlobalsCount = 0` nu). */
static void decl_globals_reset_all(void) {
    g_declaredGlobalsCount = 0;
    decl_globals_hash_reset();
}

/* Tete de chaine du bucket de ce nom (-1 si vide/non initialise). A parcourir
 * via g_declaredGlobals[i].hashNext, en filtrant par decl_globals_match pour
 * ecarter les collisions de hash. */
static int decl_globals_bucket_head(const char* name, int len) {
    if (!g_declHashInit) return -1;
    return g_declHashHead[decl_hash_key(name, len)];
}

/*  : positionne par proc_declaration autour du declare_variable du nom
 * de PROCEDURE top-level. Lu dans declare_variable pour router la collision
 * de portee vers le message "procedure" au lieu de "variable". */
static bool g_declaring_procedure = false;

/*  — mode de portee courant des declarations top-level HORS classe.
 * false = GLOBAL (promotion : globale projet / globale d'element / membre de
 * collection ; c'est le DEFAUT retrocompat) ; true = LOCAL (confinement au flux
 * top-level immediat : slot local de la fonction top-level, pas de promotion,
 * invisible des procedures). Bascule "collante" posee par GLOBAL / LOCAL seuls
 * sur une ligne, alternable librement ; n'a d'effet qu'a scopeDepth 0. Reset au
 * defaut GLOBAL a chaque nouveau contexte (fichier, corps d'element, corps de
 * collection, corps de classe) via save/restore. Les classes ont leur propre
 * parsing (GLOBAL bloc membres, GLOBALE methode) et n'utilisent jamais ce mode. */
static bool g_toplevel_confine = false;

/*  — true pendant le parse du CORPS du bloc Projet (apres PROPRIETES,
 * jusqu'au FIN final). Gate la capture des variables GLOBAL du corps pour leur
 * materialisation precoce (Phase 1). Faux quand la declaration du bloc Projet
 * lui-meme (`APP est un Projet`) est materialisee : le meta-global suit sa
 * propre voie. */
static bool g_in_projet_body = false;

/*  — pont declare_variable -> define_variable : positionne true quand
 * declare_variable vient de router une variable en slot local confine (au lieu
 * du chemin global). define_variable saute alors OP_DEFINE_GLOBAL et laisse la
 * valeur d'init comme contenu du slot local. Consomme (remis a false) par
 * define_variable. */
static bool g_last_declare_confined = false;

/*  phase 2b — comparaison canon (strip_accents + tolower) entre une
 * entree g_declaredGlobals et un identifiant raw du source. Indispensable
 * pour les noms a accents : `Salué` declare (UTF-8 6 octets) et `Salue`
 * appele (ASCII 5 octets) ont des longueurs differentes mais doivent
 * matcher apres canonisation. Helper unique pour ne pas semer la logique
 * canon dans les 24 sites de lookup. */
static bool decl_globals_match(int idx, const char* name, int len) {
    const DeclaredGlobal* g = &g_declaredGlobals[idx];
    char canonG[256], canonN[256];
    int lg = scanner_canonicalize_identifier(g->name, g->nameLen,
                                             canonG, sizeof(canonG));
    int ln = scanner_canonicalize_identifier(name, len,
                                             canonN, sizeof(canonN));
    return lg == ln && memcmp(canonG, canonN, (size_t)lg) == 0;
}

static void global_track_declare(const char* name, int len, int line) {
    if (len <= 0 || len >= 64) return;
    /*  : si une entree prescan (isPrescanned=true, posee par la
     * pre-passe ordre-independant des blocs FEN/Etat) existe deja pour ce
     * nom, on "consomme" le flag (la decl reelle est compilee maintenant)
     * et on update la ligne. Sinon on append une nouvelle entree. Sans ce
     * dedup, l'append doublonnait l'entree pre-passe -> warning unused
     * sortait sur l'entree dupliquee. */
    for (int i = decl_globals_bucket_head(name, len); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (g_declaredGlobals[i].isPrescanned
            && decl_globals_match(i, name, len)) {
            g_declaredGlobals[i].isPrescanned = false;
            g_declaredGlobals[i].line = line;
            return;
        }
    }
    if (g_declaredGlobalsCount >= MAX_DECLARED_GLOBALS) {
        error_capacity_exceeded("MAX_DECLARED_GLOBALS", MAX_DECLARED_GLOBALS);
        return;
    }

    int idx = g_declaredGlobalsCount++;
    DeclaredGlobal* g = &g_declaredGlobals[idx];
    memcpy(g->name, name, (size_t)len);
    g->name[len] = '\0';
    g->nameLen = len;
    g->line = line;
    g->isUsed = false;
    g->hasInitializer = false;
    g->isStructureType = false;
    g->isPrescanned = false;
    g->isFromNeighbor = false;
    g->isProcedure = false;
    g->suppressUnused = false;
    decl_globals_hash_link(idx);
}

/*  : variante "voisin projet" — pousse un global declare dans un
 * fichier voisin pour alimenter le shadow check uniquement. Marque
 * hasInitializer=true pour eviter warn_unused_globals + isFromNeighbor=true
 * pour faire skipper les paths duplicate/consume du compile principal. */
static void global_track_declare_from_neighbor(const char* name, int len,
                                                int line) {
    if (len <= 0 || len >= 64) return;
    /* Skip si deja present (fichier en cours ou autre voisin) : on ne veut
     * pas creer de doublons qui fausseraient le matching. Le premier wins. */
    for (int i = decl_globals_bucket_head(name, len); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (decl_globals_match(i, name, len)) return;
    }
    if (g_declaredGlobalsCount >= MAX_DECLARED_GLOBALS) {
        error_capacity_exceeded("MAX_DECLARED_GLOBALS", MAX_DECLARED_GLOBALS);
        return;
    }
    int idx = g_declaredGlobalsCount++;
    DeclaredGlobal* g = &g_declaredGlobals[idx];
    memcpy(g->name, name, (size_t)len);
    g->name[len] = '\0';
    g->nameLen = len;
    g->line = line;
    g->isUsed = false;
    g->hasInitializer = true;  /* pas notre global, pas de warn unused */
    g->isStructureType = false;
    g->isPrescanned = false;
    g->isFromNeighbor = true;
    g->isProcedure = false;
    g->suppressUnused = false;
    decl_globals_hash_link(idx);
}

/* B.2 : variante prescan — l'entree existe pour autoriser les forward refs
 * mais sera "consommee" (flag clear) quand la decl reelle sera compilee. */
static void global_track_prescan(const char* name, int len, int line) {
    if (len <= 0 || len >= 64) return;
    /* Skip si deja prescanne (re-runs sur meme source) */
    for (int i = decl_globals_bucket_head(name, len); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (decl_globals_match(i, name, len)) {
            return;
        }
    }
    if (g_declaredGlobalsCount >= MAX_DECLARED_GLOBALS) {
        error_capacity_exceeded("MAX_DECLARED_GLOBALS", MAX_DECLARED_GLOBALS);
        return;
    }
    int idx = g_declaredGlobalsCount++;
    DeclaredGlobal* g = &g_declaredGlobals[idx];
    memcpy(g->name, name, (size_t)len);
    g->name[len] = '\0';
    g->nameLen = len;
    g->line = line;
    g->isUsed = false;
    g->hasInitializer = true;  /* Decl-style, pas une variable a verifier "unused" */
    g->isStructureType = false;
    g->isPrescanned = true;
    g->isFromNeighbor = false;
    g->isProcedure = false;
    g->suppressUnused = false;
    decl_globals_hash_link(idx);
}

/*  — marque TOUTES les entrees de ce nom comme portant l'attribut
 * <utile>/<useful> (opt-out unused). Itere toutes les entrees matchantes,
 * comme mark_initialized/mark_used (entree prescan + entree reelle). */
static void global_track_mark_suppress_unused(const char* name, int len) {
    for (int i = decl_globals_bucket_head(name, len); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (decl_globals_match(i, name, len)) {
            g_declaredGlobals[i].suppressUnused = true;
        }
    }
}

static void global_track_mark_initialized(const char* name, int len) {
    /*  — marque TOUTES les entrees matching (cf. mark_used).
     * Indispensable quand un meme nom apparait deux fois :
     *  - entree prescan (hasInitializer=true par construction)
     *  - entree compile reelle ajoutee par global_track_declare avec
     *    hasInitializer=false
     * Sans iteration complete, le faux positif "declaree mais jamais
     * utilisee" sortait sur la 2e entree (cas PROCEDURE top-level body
     * Fenetre/Etat). */
    for (int i = decl_globals_bucket_head(name, len); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (decl_globals_match(i, name, len)) {
            g_declaredGlobals[i].hasInitializer = true;
        }
    }
}

static void global_track_mark_used(const char* name, int len) {
    /* Mark ALL entries with this name — needed when a structure type and a
     * variable share the same case-insensitive name (e.g. Couleur/couleur). */
    for (int i = decl_globals_bucket_head(name, len); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (decl_globals_match(i, name, len)) {
            g_declaredGlobals[i].isUsed = true;
        }
    }
}

/*  : marque le(s) global(aux) de ce nom comme PROCEDURE. Appele par
 * proc_declaration apres declare_variable. Permet a une declaration ulterieure
 * de meme nom (variable OU procedure) d'emettre le message "procedure". Itere
 * toutes les entrees matchantes (entree prescan consommee + entree reelle). */
static void global_track_mark_procedure(const char* name, int len) {
    for (int i = decl_globals_bucket_head(name, len); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (decl_globals_match(i, name, len)) {
            g_declaredGlobals[i].isProcedure = true;
        }
    }
}

static void global_track_declare_structure(const char* name, int len, int line) {
    if (len <= 0 || len >= 64) return;
    /* Idempotent : si l'entree existe deja (prescan ou autre passe), update
     * sa ligne et ne pas dupliquer. Necessaire pour B.2 ou la prescan
     * pre-enregistre les types pour le hoisting de forward refs. */
    for (int i = decl_globals_bucket_head(name, len); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (decl_globals_match(i, name, len) &&
            g_declaredGlobals[i].isStructureType) {
            g_declaredGlobals[i].isPrescanned = false;
            g_declaredGlobals[i].line = line;
            return;
        }
    }
    if (g_declaredGlobalsCount >= MAX_DECLARED_GLOBALS) {
        error_capacity_exceeded("MAX_DECLARED_GLOBALS", MAX_DECLARED_GLOBALS);
        return;
    }

    int idx = g_declaredGlobalsCount++;
    DeclaredGlobal* g = &g_declaredGlobals[idx];
    memcpy(g->name, name, (size_t)len);
    g->name[len] = '\0';
    g->nameLen = len;
    g->line = line;
    g->isUsed = false;
    g->hasInitializer = false;
    g->isStructureType = true;  /* Mark as structure, not variable */
    g->isPrescanned = false;
    g->isFromNeighbor = false;
    g->isProcedure = false;
    g->suppressUnused = false;
    decl_globals_hash_link(idx);
}

/* Wrapper boolean autour de owl_resolve_type — conservé pour minimiser
 * la surface de changement des callers. La nouvelle API à utiliser pour
 * les nouveaux call sites est owl_resolve_type (retour structure). */
static bool is_any_known_type(const char* name, int length) {
    return owl_resolve_type(name, length) != OWL_TR_UNKNOWN;
}

/*  — un nom de type manglé `COL$Type` désigne-t-il un membre-type de
 * collection ? Vrai si (COL, Type) est un membre enregistré ET que la partie NUE
 * est elle-même un type connu (garde contre l'acceptation d'un membre-DONNÉE
 * `COL$gVar`). Volontairement HORS de is_any_known_type : la forme manglée ne
 * doit PAS être vue comme un « nom de type » en position de valeur (sinon
 * l'accès `COL.Énum.Membre` casse, cf. is_type_not_variable). Réservé à la
 * validation des pending-refs de la position de type qualifiée `COL.Type`. */
static bool is_collection_qualified_type(const char* name, int length) {
    const void* dollar = memchr(name, '$', (size_t)length);
    if (dollar == NULL || dollar == name) return false;
    int clen = (int)((const char*)dollar - name);
    int mlen = length - clen - 1;
    if (mlen <= 0) return false;
    if (!collection_member_has(name, clen, (const char*)dollar + 1, mlen)) {
        return false;
    }
    /*  — un membre-type NON-EXPOSÉ (type interne d'une Fenetre/Etat)
     * est qualifié-only : sa forme nue n'est PAS enregistrée comme type connu
     * (encapsulation), donc owl_resolve_type échouerait. On l'accepte
     * directement. Les membres de collection EXPOSÉS gardent la garde
     * owl_resolve_type (rejet d'un membre-DONNÉE `COL$gVar`). */
    if (collection_member_is_unexposed(name, clen, (const char*)dollar + 1, mlen)) {
        return true;
    }
    return owl_resolve_type((const char*)dollar + 1, mlen) != OWL_TR_UNKNOWN;
}

/* Check if name is a type being misused as a variable (reject assignment/read).
 * Context: user wrote `Definition = X` or used `Definition` as an expression.
 * If a variable `definition` was already declared, it's NOT a misuse — it's a
 * legitimate variable reference that happens to share a name (case-insensitive)
 * with a type. User-defined types (struct/enum/class) ARE variables at runtime
 * (template objects), so they're never a misuse — eCouleur.Rouge is valid. */
static bool is_type_not_variable(const char* name, int length) {
    /* Check if this name was declared as any kind of global in this unit.
     * User-defined types (marked isStructureType) ARE runtime variables,
     * so finding one means "not a type misuse". */
    for (int i = decl_globals_bucket_head(name, length); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (decl_globals_match(i, name, length)) {
            return false;  /* Found as variable (or user type object) */
        }
    }
    /* Forward reference : si le prescan a vu cette variable plus loin dans
     * le fichier (ou cross-file), elle n'est pas un type. Indispensable
     * pour `PROCEDURE Foo() Trace(gVar) FIN ; gVar est ...`. SYM_CLASS et
     * SYM_STRUCT comptent aussi comme valeurs runtime (objets template
     * stockés dans vm.globals via OP_CLASS / OP_STRUCT) — nécessaire pour
     * Herite de cParent cross-fichier (cf. ticket ). */
    if (projectSymbols != NULL) {
        bool ambig = false;
        ProjectSymbol* sym = symtable_find(projectSymbols, name, length, &ambig);
        if (sym != NULL && (sym->kind == SYM_VARIABLE ||
                            sym->kind == SYM_CLASS ||
                            sym->kind == SYM_STRUCT ||
                            sym->kind == SYM_ENUM ||
                            sym->kind == SYM_WINDOW)) return false;  /*  */
    }
    /* No variable/user-type found → check if it's a builtin type with no variable */
    return is_any_known_type(name, length);
}

/*  — le nom designe-t-il DEJA un type, tel quel ? Sert d'ordre de
 * priorite au repli pluriel ci-dessous : le nom exact prime toujours. On
 * consulte aussi le prescan projet, sinon un type utilisateur declare APRES
 * son usage (single-pass) serait vu comme inconnu et detourne vers le repli. */
static bool collection_elem_name_is_exact_type(const char* name, int length) {
    if (is_any_known_type(name, length)) return true;
    if (projectSymbols != NULL) {
        bool ambig = false;
        ProjectSymbol* sym = symtable_find(projectSymbols, name, length, &ambig);
        if (sym != NULL && (sym->kind == SYM_CLASS ||
                            sym->kind == SYM_STRUCT ||
                            sym->kind == SYM_ENUM)) return true;
    }
    return false;
}

/*  — un type primitif dont ce nom serait le pluriel, ou TOKEN_EOF.
 * Seuls six primitifs ont une forme plurielle parmi les mots du langage
 * (chaines, entiers, reels...) ; `dates`, `heures`, `durees`, `buffers`,
 * `caracteres`, `uuids`, `dateheures` n'en ont pas. Plutot que de reserver
 * ces mots (ils resteraient alors interdits comme noms de variables, ce qui
 * est cher paye pour `dates` ou `buffers`), on tolere le pluriel a la SEULE
 * position de type, ici.
 *
 * Repli volontairement limite : retrait d'un `s` final, et uniquement vers un
 * PRIMITIF. Les types utilisateur ne se pluralisent pas (`tableau de Points`
 * reste une erreur : la structure s'appelle Point), et les pluriels
 * irreguliers anglais ne sont pas couverts. */
static TokenType singular_primitive_type_token(const char* name, int length) {
    char canon[128];
    int n = scanner_canonicalize_identifier(name, length, canon, sizeof(canon));
    if (n < 2 || canon[n - 1] != 's') return TOKEN_EOF;
    canon[--n] = '\0';
    for (int i = 0; ; i++) {
        TokenType kw = TOKEN_EOF;
        const char* name_i = scanner_keyword_at(i, &kw);
        if (name_i == NULL) break;
        if ((int)strlen(name_i) != n || memcmp(name_i, canon, (size_t)n) != 0) continue;
        switch (kw) {
            case TOKEN_BOOLEEN:  case TOKEN_ENTIER:    case TOKEN_REEL:
            case TOKEN_MONETAIRE:case TOKEN_NUMERIQUE: case TOKEN_CHAINE:
            case TOKEN_CARACTERE:case TOKEN_DATE:      case TOKEN_HEURE:
            case TOKEN_DATEHEURE:case TOKEN_DUREE:     case TOKEN_BUFFER:
            case TOKEN_JSON_KW:  case TOKEN_UUID:
                return kw;
            default:
                return TOKEN_EOF; /* mot du langage, mais pas un type primitif */
        }
    }
    return TOKEN_EOF;
}

/*  /  — resolution du type d'element d'une collection
 * (`tableau de X`, `file de X`, `pile de X`, `liste de X`, tableau associatif
 * `de X`). Le nom etait avale en silence : un type inexistant produisait une
 * collection non typee au lieu d'une erreur. Meme traitement que
 * `x est un <Type>` : detection Variant dediee (retire du langage, singulier
 * ET pluriel — `de variants` est la forme naturelle en francais), sinon
 * record_pending_type_ref pour la validation post-parse, qui tolere la
 * reference avant declaration malgre le single-pass.
 *
 * Retourne le mot-cle primitif a lier quand le repli pluriel s'applique
 * (`de dates` -> TOKEN_DATE, strictement equivalent a `de date`), TOKEN_EOF
 * sinon : le caller lie alors le nom comme type d'element utilisateur.
 *
 * No-op si le token n'est pas un identifiant : les autres mots-cles de type
 * (chaine, entier, Date, Buffer, JSON...) sont deja resolus par le scanner. */
static TokenType record_collection_elem_type_ref(Token typeTok) {
    if (typeTok.type != TOKEN_IDENTIFIER) return TOKEN_EOF;
    if ((typeTok.length == 7 || typeTok.length == 8) &&
        strncasecmp(typeTok.start, "variant", 7) == 0 &&
        (typeTok.length == 7 || typeTok.start[7] == 's' || typeTok.start[7] == 'S')) {
        owl_emit_error_at(&typeTok, E_SEM_VARIANT_TYPE_REMOVED);
        return TOKEN_EOF;
    }
    canonicalize_builtin_type_token(&typeTok);
    if (!collection_elem_name_is_exact_type(typeTok.start, typeTok.length)) {
        TokenType prim = singular_primitive_type_token(typeTok.start, typeTok.length);
        if (prim != TOKEN_EOF) return prim;
    }
    record_pending_type_ref(typeTok);
    return TOKEN_EOF;
}

/*  — voir compiler.h : sources du perimetre que la decouverte du
 * controle ecarte (fichiers de test) mais qui comptent comme usage. */
#define MAX_USAGE_SCAN_SOURCES 512
static const char* g_usage_scan_sources[MAX_USAGE_SCAN_SOURCES];
static int         g_usage_scan_file_index[MAX_USAGE_SCAN_SOURCES];
static int         g_usage_scan_count = 0;
/*  — generation bumpee a tout changement de l'ensemble usage-scan.
 * Sert d'invalidant du set d'identifiants references precalcule (g_refset). */
static int         g_usage_scan_gen = 0;

void compiler_usage_scan_sources_clear(void) {
    g_usage_scan_count = 0;
    g_usage_scan_gen++;
}

void compiler_usage_scan_source_add(const char* source, int fileIndex) {
    if (source == NULL) return;
    if (g_usage_scan_count >= MAX_USAGE_SCAN_SOURCES) return;
    g_usage_scan_sources[g_usage_scan_count]    = source;
    g_usage_scan_file_index[g_usage_scan_count] = fileIndex;
    g_usage_scan_count++;
    g_usage_scan_gen++;
}

/* ============================================================================
 *  — set precalcule des identifiants references par le projet.
 *
 *  posait le principe : un global declare ici mais reference SEULEMENT
 * depuis un fichier voisin (globale top-level lue par un helper d'un bloc
 * Fenetre voisin, p.ex.) ne doit pas lever "declaree mais jamais utilisee".
 * L'implementation d'origine re-tokenisait INTEGRALEMENT chaque source voisine
 * a CHAQUE fichier compile, et pour chaque identifiant re-scannait tout
 * g_declaredGlobals (marquage lineaire) -> cout O(F x tokens_projet x G),
 * cubique sur les gros projets combines (support #370 : 28 s, > timeout LSP).
 *
 * On tokenise desormais chaque source du projet UNE fois par check et on
 * memorise, dans un hash set, la forme canonique (casse/accent-insensible) de
 * chaque identifiant reference, tag du fichier qui le reference. warn_unused_
 * globals interroge ensuite le set en O(1) par global au lieu de re-tokeniser
 * les voisins par fichier.
 *
 * Semantique preservee a l'octet :
 *  - un global est "utilise par un voisin" ssi le set contient sa forme
 *    canonique tagguee d'un fichier != le fichier courant. Skip-self de
 *     : l'usage du fichier courant sur ses propres globals est deja
 *    marque semantiquement pendant son compile ; re-scanner textuellement son
 *    propre source re-trouverait toujours la declaration elle-meme et
 *    eteindrait tout avertissement. D'ou le tag par fichier + le predicat
 *    "reference par un AUTRE fichier".
 *  - le pattern DOT-membre `X.Y` d'un voisin contribue la cle manglee `X$Y`
 *    ( : une globale d'element encapsulee `<ELEM>$<var>`, ,
 *    n'est jointe de l'exterieur que par l'acces qualifie , jamais par
 *    son nom nu). Le nom nu de la partie droite est aussi insere, parite avec
 *    le double marquage historique.
 *  - g_usage_scan_sources (fichiers de test, ) alimente le set au
 *    meme titre que projectSymbols->sources, avec son propre fileIndex.
 *
 * Le scanner ignore les commentaires et sort les chaines en TOKEN_STRING
 * distincts : pas de faux match textuel. Le set est bati paresseusement a la
 * premiere interrogation d'un check et invalide entre checks (changement de
 * projectSymbols ou de generation usage-scan). Sans projet ni usage-scan il
 * reste vide -> aucun marquage, identique au comportement mono historique.
 * ========================================================================= */
typedef struct {
    char* key;       /* forme canonique, possede (NULL = slot libre) */
    int   firstFile; /* premier fileIndex ayant reference cette cle */
    bool  multiFile; /* vrai des qu'un 2e fileIndex distinct la reference */
} RefSetEntry;

static RefSetEntry*      g_refset = NULL;
static int               g_refset_cap = 0;   /* puissance de 2, ou 0 */
static int               g_refset_count = 0;
static bool              g_refset_built = false;
static const SymbolTable* g_refset_symbols = NULL;
static int               g_refset_usage_gen = -1;

static void refset_free(void) {
    if (g_refset != NULL) {
        for (int i = 0; i < g_refset_cap; i++) free(g_refset[i].key);
        free(g_refset);
        g_refset = NULL;
    }
    g_refset_cap = 0;
    g_refset_count = 0;
    g_refset_built = false;
    g_refset_symbols = NULL;
    g_refset_usage_gen = -1;
}

static uint32_t refset_hash(const char* s, int len) {
    uint32_t h = 2166136261u;
    for (int i = 0; i < len; i++) {
        h ^= (unsigned char)s[i];
        h *= 16777619u;
    }
    return h;
}

/* Insere la cle canonique (deja canonicalisee par l'appelant) taggee du
 * fichier. Idempotent par (cle, fichier) ; passe multiFile a vrai des qu'un
 * second fichier distinct reference la meme cle. */
static void refset_insert(const char* canon, int len, int fileIndex) {
    if (len <= 0) return;
    /* Grow a l'entree (facteur de charge < 0.7). */
    if (g_refset_cap == 0 || (g_refset_count + 1) * 10 >= g_refset_cap * 7) {
        int newCap = g_refset_cap == 0 ? 1024 : g_refset_cap * 2;
        RefSetEntry* nt = (RefSetEntry*)calloc((size_t)newCap, sizeof(RefSetEntry));
        if (nt == NULL) return; /* OOM : le set restera partiel, degradation muette */
        for (int i = 0; i < g_refset_cap; i++) {
            if (g_refset[i].key == NULL) continue;
            uint32_t h = refset_hash(g_refset[i].key,
                                     (int)strlen(g_refset[i].key));
            int mask = newCap - 1;
            int idx = (int)(h & (uint32_t)mask);
            while (nt[idx].key != NULL) idx = (idx + 1) & mask;
            nt[idx] = g_refset[i];
        }
        free(g_refset);
        g_refset = nt;
        g_refset_cap = newCap;
    }
    int mask = g_refset_cap - 1;
    int idx = (int)(refset_hash(canon, len) & (uint32_t)mask);
    for (;;) {
        RefSetEntry* e = &g_refset[idx];
        if (e->key == NULL) {
            e->key = (char*)malloc((size_t)len + 1);
            if (e->key == NULL) return;
            memcpy(e->key, canon, (size_t)len);
            e->key[len] = '\0';
            e->firstFile = fileIndex;
            e->multiFile = false;
            g_refset_count++;
            return;
        }
        if ((int)strlen(e->key) == len && memcmp(e->key, canon, (size_t)len) == 0) {
            if (!e->multiFile && e->firstFile != fileIndex) e->multiFile = true;
            return;
        }
        idx = (idx + 1) & mask;
    }
}

/* Vrai si la cle canonique est referencee par un fichier != curFileIndex. */
static bool refset_referenced_by_other(const char* canon, int len,
                                       int curFileIndex) {
    if (g_refset_cap == 0 || len <= 0) return false;
    int mask = g_refset_cap - 1;
    int idx = (int)(refset_hash(canon, len) & (uint32_t)mask);
    for (;;) {
        RefSetEntry* e = &g_refset[idx];
        if (e->key == NULL) return false;
        if ((int)strlen(e->key) == len && memcmp(e->key, canon, (size_t)len) == 0) {
            if (e->multiFile) return true;
            return e->firstFile != curFileIndex;
        }
        idx = (idx + 1) & mask;
    }
}

/* Tokenise une source et insere les identifiants references (nom nu + cle
 * manglee DOT-membre `X$Y`), taggues du fichier. Corps repris de
 * l'ancien mark_globals_used_in_source ( / ), avec le
 * marquage redirige vers le set au lieu de g_declaredGlobals. */
static void refset_scan_source(const char* src, int fileIndex) {
    if (src == NULL) return;
    Scanner s;
    scanner_init(&s, src);
    Token prev1 = {0}, prev2 = {0};
    char canon[256];
    for (;;) {
        Token tok = scanner_scan_token(&s);
        if (tok.type == TOKEN_EOF) break;
        if (tok.type == TOKEN_IDENTIFIER) {
            int cl = scanner_canonicalize_identifier(tok.start, tok.length,
                                                     canon, sizeof(canon));
            refset_insert(canon, cl, fileIndex);
            if (prev1.type == TOKEN_DOT && prev2.type == TOKEN_IDENTIFIER) {
                char key[160];
                int n = snprintf(key, sizeof(key), "%.*s$%.*s",
                                 prev2.length, prev2.start,
                                 tok.length, tok.start);
                if (n > 0 && (size_t)n < sizeof(key)) {
                    int kl = scanner_canonicalize_identifier(key, n,
                                                             canon, sizeof(canon));
                    refset_insert(canon, kl, fileIndex);
                }
            }
        }
        prev2 = prev1;
        prev1 = tok;
    }
}

static void refset_ensure(void) {
    if (g_refset_built
        && g_refset_symbols == projectSymbols
        && g_refset_usage_gen == g_usage_scan_gen) return;
    refset_free();
    if (projectSymbols != NULL) {
        for (int k = 0; k < projectSymbols->sourceCount; k++) {
            refset_scan_source(projectSymbols->sources[k].source,
                               projectSymbols->sources[k].fileIndex);
        }
    }
    for (int k = 0; k < g_usage_scan_count; k++) {
        refset_scan_source(g_usage_scan_sources[k], g_usage_scan_file_index[k]);
    }
    g_refset_built = true;
    g_refset_symbols = projectSymbols;
    g_refset_usage_gen = g_usage_scan_gen;
}

static void mark_globals_used_from_neighbors(void) {
    if (g_declaredGlobalsCount == 0) return;
    if (projectSymbols == NULL && g_usage_scan_count == 0) return;
    refset_ensure();
    char canon[256];
    for (int i = 0; i < g_declaredGlobalsCount; i++) {
        DeclaredGlobal* g = &g_declaredGlobals[i];
        if (g->isUsed) continue;
        int cl = scanner_canonicalize_identifier(g->name, g->nameLen,
                                                 canon, sizeof(canon));
        if (refset_referenced_by_other(canon, cl, currentFileIndex))
            g->isUsed = true;
    }
}

/* ============================================================================
 *  — index des styles declares dans un bloc `est un Theme` du projet.
 *
 *  : les styles d'un theme sont accessibles UNIQUEMENT via `theme.`.
 * L'encapsulation elle-meme est posee par le mangling `<prefixe>$<style>` du
 * corps du bloc (cf. la branche Theme de var_declaration). Cet index sert
 * l'autre moitie : quand un nom nu ne resout plus, dire POURQUOI et vers quoi
 * — un « variable inconnue » sec sur un nom que l'utilisateur lit dans son
 * fichier n'oriente vers rien.
 *
 * Le scan est textuel (memes sources prescan que project_ident_declared_type)
 * et bati une fois par compile, a la premiere interrogation. La passe 2 marque
 * les noms qu'une declaration ORDINAIRE (hors bloc theme) porte aussi : dans ce
 * cas le nom nu designe cette globale-la, pas le style, et le refus n'a pas
 * lieu d'etre.
 * ========================================================================= */
/* Tout depassement de capacite de cet index est INVISIBLE a l'usage : le style
 * reste encapsule (le mangling ne depend pas de l'index), mais son nom nu perd
 * le message oriente et retombe sur le « variable inconnue » sec que ce
 * dispositif existe justement pour remplacer. Un plafond serait donc une
 * degradation muette du diagnostic — d'ou la croissance geometrique et les
 * noms pris sur le tas : ni nombre de styles, ni longueur de nom ne bornent. */
typedef struct {
    char* name;      /* nom du style, forme tapee */
    char* block;     /* nom du bloc theme qui le declare */
    bool  shadowed;  /* une globale ordinaire homonyme existe dans le projet */
} ThemeStyleEntry;
static ThemeStyleEntry* g_theme_styles = NULL;
static int  g_theme_styles_count    = 0;
static int  g_theme_styles_capacity = 0;
static bool g_theme_styles_built    = false;

/* Vrai dans le corps d'un bloc `est un Theme` : les references intra-bloc
 * passent par le scope element, pas par le refus de nom nu. */
static bool g_in_theme_block = false;

static char* theme_style_dup(const char* src, int length) {
    char* out = ALLOCATE(char, length + 1);
    memcpy(out, src, (size_t)length);
    out[length] = '\0';
    return out;
}

static void theme_style_free(char* s) {
    FREE_ARRAY(char, s, (int)strlen(s) + 1);
}

static void theme_style_index_clear(void) {
    for (int i = 0; i < g_theme_styles_count; i++) {
        theme_style_free(g_theme_styles[i].name);
        theme_style_free(g_theme_styles[i].block);
    }
    FREE_ARRAY(ThemeStyleEntry, g_theme_styles, g_theme_styles_capacity);
    g_theme_styles          = NULL;
    g_theme_styles_count    = 0;
    g_theme_styles_capacity = 0;
}

static void theme_style_index_reset(void) {
    theme_style_index_clear();
    g_theme_styles_built = false;
    g_in_theme_block     = false;  /* un parse interrompu ne doit pas fuir */
}

/* Le token est-il le mot-cle de type Theme (bilingue, accent-insensible) ? */
static bool token_is_theme_type_kw(Token t) {
    if (t.type != TOKEN_IDENTIFIER) return false;
    char probe[16];
    int n = scanner_strip_accents(t.start, t.length, probe, sizeof(probe));
    return n == 5 && strncasecmp(probe, "Theme", 5) == 0;
}

/* Tampons de travail sur la pile tant que les noms tiennent, sur le tas
 * au-dela : strip_accents tronque en silence quand il deborde, et deux noms
 * longs partageant un prefixe passeraient alors pour egaux. */
static bool theme_ident_equals(const char* a, int aLen, const char* b, int bLen) {
    char sa[128], sb[128];
    int   capA = aLen + 1 <= (int)sizeof(sa) ? (int)sizeof(sa) : aLen + 1;
    int   capB = bLen + 1 <= (int)sizeof(sb) ? (int)sizeof(sb) : bLen + 1;
    char* ca   = capA == (int)sizeof(sa) ? sa : ALLOCATE(char, capA);
    char* cb   = capB == (int)sizeof(sb) ? sb : ALLOCATE(char, capB);
    int  na = scanner_strip_accents(a, aLen, ca, capA);
    int  nb = scanner_strip_accents(b, bLen, cb, capB);
    bool eq = na > 0 && na == nb && strncasecmp(ca, cb, (size_t)na) == 0;
    if (ca != sa) FREE_ARRAY(char, ca, capA);
    if (cb != sb) FREE_ARRAY(char, cb, capB);
    return eq;
}

static void theme_style_index_add(Token nameTok, const char* block) {
    if (nameTok.length <= 0) return;
    if (g_theme_styles_count + 1 > g_theme_styles_capacity) {
        int oldCap = g_theme_styles_capacity;
        g_theme_styles_capacity = GROW_CAPACITY(oldCap);
        g_theme_styles = GROW_ARRAY(ThemeStyleEntry, g_theme_styles,
                                    oldCap, g_theme_styles_capacity);
    }
    ThemeStyleEntry* e = &g_theme_styles[g_theme_styles_count++];
    e->name     = theme_style_dup(nameTok.start, nameTok.length);
    e->block    = theme_style_dup(block, (int)strlen(block));
    e->shadowed = false;
}

static void theme_style_index_mark_shadowed(Token nameTok) {
    for (int i = 0; i < g_theme_styles_count; i++) {
        if (theme_ident_equals(g_theme_styles[i].name,
                               (int)strlen(g_theme_styles[i].name),
                               nameTok.start, nameTok.length)) {
            g_theme_styles[i].shadowed = true;
        }
    }
}

/*  — delta de profondeur d'un token lu sur un scanner LOCAL, rendu par
 * la source unique (prescan_depth_delta, prescan.h). `s` est le scanner du
 * caller, positionne juste apres `tok` ; il est copie, le scan reel n'avance
 * pas.
 *
 * A n'utiliser QUE sur les jetons de la table (cf. prescan_token_in_depth_table).
 * Ce que la table ne couvre pas — AVEC, et les mots-cles structurels
 * post-copule — reste a la charge du site, qui a le contexte : position dans la
 * ligne, lookbehind sur la copule. */
static int local_scan_depth_delta(Token tok, const Scanner* s) {
    Scanner peek = *s;
    return prescan_depth_delta(tok, &peek);
}

/* Une passe sur une source. collect=true : recense les membres de bloc theme.
 * collect=false : marque les homonymes declares hors bloc theme.
 *
 * Depth-tracker calque sur project_ident_declared_type, avec en plus le suivi
 * du bloc theme (qui, lui, ouvre bien une profondeur ici : ses membres ne sont
 * pas des declarations top-level). */
static void theme_style_index_scan(const char* src, bool collect) {
    Scanner s;
    scanner_init(&s, src);
    int   depth      = 0;
    int   themeDepth = -1;
    char* block      = NULL;   /* nom du bloc theme courant, sur le tas */
    Token prev2 = (Token){0};
    Token prev1 = (Token){0};
    for (;;) {
        Token tok = scanner_scan_token(&s);
        if (tok.type == TOKEN_EOF) break;
        if (tok.type == TOKEN_NEWLINE || tok.type == TOKEN_ERROR) continue;
        if (tok.type == TOKEN_FIN) {
            if (themeDepth >= 0 && depth == themeDepth + 1) {
                themeDepth = -1;
                theme_style_free(block);
                block = NULL;
            }
            if (depth > 0) depth--;
            prev2 = prev1; prev1 = tok; continue;
        }
        /* Ouvrants lexicaux : source unique. Les formes sans FIN
         * (`SI c ALORS instr`, `CONSTANTE K = 3`) rendent 0 et n'ouvrent rien. */
        if (prescan_token_in_depth_table(tok.type)) {
            if (local_scan_depth_delta(tok, &s) > 0) depth++;
            prev2 = prev1; prev1 = tok; continue;
        }
        if (tok.type == TOKEN_AVEC) {
            depth++;
            prev2 = prev1; prev1 = tok; continue;
        }
        /* Article EN intercale entre EST et le type (`is a/an <Type>`). */
        if (prev1.type == TOKEN_EST
            && (tok.type == TOKEN_A
                || (tok.type == TOKEN_IDENTIFIER && tok.length == 2
                    && strncasecmp(tok.start, "an", 2) == 0))) {
            continue;
        }
        bool tokIsType = tok.type == TOKEN_IDENTIFIER || tok.type == TOKEN_FENETRE;
        if (tokIsType && prev1.type == TOKEN_EST
            && prev2.type == TOKEN_IDENTIFIER) {
            if (themeDepth < 0 && depth == 0 && token_is_theme_type_kw(tok)) {
                themeDepth = depth;
                block = theme_style_dup(prev2.start, prev2.length);
                depth++;
                prev2 = prev1; prev1 = tok; continue;
            }
            if (themeDepth >= 0 && depth == themeDepth + 1) {
                if (collect) theme_style_index_add(prev2, block);
            } else if (!collect && depth == 0) {
                theme_style_index_mark_shadowed(prev2);
            }
        }
        prev2 = prev1; prev1 = tok;
    }
    if (block != NULL) theme_style_free(block);  /* bloc jamais referme */
}

static void theme_style_index_build(void) {
    theme_style_index_clear();
    g_theme_styles_built = true;
    if (projectSymbols == NULL) return;
    for (int k = 0; k < projectSymbols->sourceCount; k++) {
        const char* src = projectSymbols->sources[k].source;
        if (src != NULL) theme_style_index_scan(src, /*collect=*/true);
    }
    if (g_theme_styles_count == 0) return;
    for (int k = 0; k < projectSymbols->sourceCount; k++) {
        const char* src = projectSymbols->sources[k].source;
        if (src != NULL) theme_style_index_scan(src, /*collect=*/false);
    }
}

/* Le nom nu designe-t-il un style de bloc theme (et rien d'autre) ? Rend le nom
 * du bloc proprietaire, NULL sinon. */
static const char* theme_style_bare_owner(const char* name, int length) {
    if (!g_theme_styles_built) theme_style_index_build();
    for (int i = 0; i < g_theme_styles_count; i++) {
        if (g_theme_styles[i].shadowed) continue;
        if (theme_ident_equals(g_theme_styles[i].name,
                               (int)strlen(g_theme_styles[i].name),
                               name, length)) {
            return g_theme_styles[i].block;
        }
    }
    return NULL;
}

/*  — hydratation des globales declarees dans les fichiers voisins
 * du projet. Cible : permettre au shadow check (declare_variable, sites
 * window-field 3274 + general 3409) de detecter qu'un champ Fenetre ou
 * une variable locale masque une globale declaree dans un autre fichier
 * du MEME projet (frontiere  respectee par symtable).
 *
 * Sans cette passe, `g_declaredGlobals` est peuple uniquement par le
 * compile principal du fichier en cours -> shadow cross-fichier
 * silencieux (cf. .scratch/shadow_check : nScore global dans main.owl,
 * champ Saisie nScore dans FEN_Jeu.owl voisin -> aucun warning).
 *
 * Pattern detecte au top-level du voisin :
 *   IDENT EST [un|une|a|an]? <type-non-block>
 * Les types block (CLASSE/STRUCTURE/INTERFACE/ENUMERATION/COMBINAISON/
 * FENETRE/LIBELLE/BOUTON/SAISIE/ETAT) ne sont PAS hydrates : ils sont
 * traites par les voies SymbolTable / register_user_type / prescan
 * widgets existantes et ne sont pas des "variables globales" pour le
 * shadow check.
 *
 * Symetrique exact de mark_globals_used_from_neighbors :
 * lui consomme les usages cross-fichier pour eviter un faux positif
 * unused, nous declarons les globales cross-fichier pour alimenter un
 * vrai positif shadow.
 *
 * Depth-tracker calque sur prescan_source_unified : on ne capte que ce
 * qui est au depth 0 (top-level). */
/*  : le modificateur widget `Champ` accepte trois formes canon —
 * `Champ` (FR), `Field` et `Control` (les deux nameEN de Champ, cf.
 * check_ident_champ L15869). Helper token-based partage par les depth-counters
 * de prescan (top-level + depth>0) et le shadow-check cross-fenetre, qui
 * travaillent sur des tokens issus d'un scanner local (pas parser.current) et
 * ne peuvent donc pas appeler check_ident_champ. Sans ce triplet, un DSL
 * fenetre ecrit en anglais (`X is a Control Label`) desync la profondeur et
 * declenche de faux shadows. */
static bool token_is_champ_modifier(Token t) {
    if (t.type != TOKEN_IDENTIFIER) return false;
    if (t.length == 5 && strncasecmp(t.start, "Champ", 5) == 0) return true;
    if (t.length == 5 && strncasecmp(t.start, "Field", 5) == 0) return true;
    if (t.length == 7 && strncasecmp(t.start, "Control", 7) == 0) return true;
    return false;
}

/*  — genre du sous-bloc Volet (FR) / Pane (EN). Volet a un corps
 * (PROPRIETES + enfants + FIN) mais n'est PAS resolu par
 * owl_control_kind_from_token : son entree CONTROL_KINDS porte is_widget=false
 * (sous-bloc de role, comme Colonne). Les depth-counters lexicaux travaillent
 * sur des tokens d'un scanner local et ne peuvent pas appeler is_volet_token
 * (qui lit parser.current) : sans ce helper, le FIN du volet fait retomber la
 * profondeur d'un cran de trop et tout ce qui suit l'Onglet sort du scope
 * fenetre. */
static bool token_is_volet_genre(Token t) {
    if (t.type != TOKEN_IDENTIFIER) return false;
    if (t.length == 5 && strncasecmp(t.start, "Volet", 5) == 0) return true;
    if (t.length == 4 && strncasecmp(t.start, "Pane", 4) == 0) return true;
    return false;
}

/* ============================================================================
 *  — Etat voisins precalcule (contribution par fichier + replay).
 *
 * Les trois scans lexicaux des voisins (widgets/sous-widgets, globales bare,
 * membres de CollectionDeProcedures) etaient re-tokenises pour CHAQUE fichier
 * compile du projet -> cout O(N_fichiers x octets_projet), quadratique sur les
 * gros projets combines. On tokenise desormais chaque source UNE fois
 * (compiler_neighbor_prebuild, appele une fois par check depuis le driver), on
 * memorise sa contribution BRUTE (par position de source, sans dedup
 * cross-fichier), puis chaque compilation rejoue les contributions des AUTRES
 * fichiers (replay-sauf-self pour widgets/globales ; TOUS fichiers pour les
 * collections, parite avec le scan live qui inclut le fichier courant).
 *
 * La logique de scan et les sinks (global_track_declare_from_neighbor,
 * element_globals_register, collection_member_register, prescan_widget/child_
 * register) restent identiques : seule la SOURCE des donnees change (buffer au
 * lieu d'un re-scan). Le dedup "first wins" et l'ordre source sont preserves au
 * replay -> diagnostics byte-identiques. Fallback transparent : sans prebuild
 * (owl run/test, LSP split), les fonctions retombent sur le scan live. */
typedef struct { char name[64]; int line; } NeiGlobalRec;
typedef struct { char elem[64]; char name[64]; } NeiElemRec;
typedef struct { char coll[64]; char name[64]; bool exposed; } NeiCollRec;
typedef struct { char name[64]; OwlControlKind kind; } NeiWidgetRec;
typedef struct { int ownerLocal; char name[64]; } NeiChildRec;
typedef struct { char name[64]; int line; } NeiCGlobalRec;

typedef struct {
    int fileIndex;
    const char* source;          /* pointeur source du slot (compare saw_source) */
    NeiWidgetRec*  widgets;  int widgetCount;
    NeiChildRec*   children; int childCount;   /* ownerLocal = index dans widgets */
    NeiCGlobalRec* cglobals; int cglobalCount; /* globales Compile() du voisin */
    NeiGlobalRec*  globals;  int globalCount;
    NeiElemRec*    elems;    int elemCount;
    NeiCollRec*    colls;    int collCount;
} NeighborContribution;

static NeighborContribution* g_neighbor_buf = NULL;
static int g_neighbor_buf_count = 0;
static const SymbolTable* g_neighbor_buf_symbols = NULL;
static bool g_neighbor_prebuilt = false;

static bool neighbor_prebuilt_for(const SymbolTable* symbols) {
    return g_neighbor_prebuilt && symbols != NULL
        && g_neighbor_buf_symbols == symbols;
}

/* Replay des globales voisines (skip self, ordre source). Le dedup "first wins"
 * de global_track_declare_from_neighbor reproduit exactement le gagnant de ligne
 * du scan live (meme ordre d'iteration). */
static void neighbor_replay_globals(int curFileIndex) {
    for (int k = 0; k < g_neighbor_buf_count; k++) {
        NeighborContribution* c = &g_neighbor_buf[k];
        if (c->fileIndex == curFileIndex) continue;
        for (int i = 0; i < c->globalCount; i++)
            global_track_declare_from_neighbor(c->globals[i].name,
                (int)strlen(c->globals[i].name), c->globals[i].line);
        for (int i = 0; i < c->elemCount; i++)
            element_globals_register(c->elems[i].elem,
                (int)strlen(c->elems[i].elem),
                c->elems[i].name, (int)strlen(c->elems[i].name));
    }
}

/* Replay des membres de collection (TOUS fichiers, self inclus — parite avec
 * hydrate_collection_members). Le caller a deja pose
 * g_collection_register_from_prescan = true. */
static void neighbor_replay_collection(const char* currentSource) {
    for (int k = 0; k < g_neighbor_buf_count; k++) {
        NeighborContribution* c = &g_neighbor_buf[k];
        if (c->source == NULL) continue;
        if (currentSource != NULL && strcmp(c->source, currentSource) == 0)
            g_collection_prescan_saw_source = true;
        for (int i = 0; i < c->collCount; i++)
            collection_member_register(c->colls[i].coll,
                (int)strlen(c->colls[i].coll),
                c->colls[i].name, (int)strlen(c->colls[i].name),
                c->colls[i].exposed);
    }
}

/* Corps de scan par-source, extrait verbatim de la boucle historique (le seul
 * changement est le decoupage : la boucle et le skip currentFileIndex vivent
 * dans le wrapper). */

static void globals_scan_one_source(const char* src) {
        if (src == NULL) return;
        Scanner s;
        scanner_init(&s, src);
        int depth = 0;
        /*  — element courant du voisin en cours de scan. Quand on
         * descend dans un bloc Fenetre/Etat, on retient son nom + la
         * profondeur de son body, pour attribuer les globales de niveau body
         * a CET element (registre qualifie g_element_globals) au lieu de les
         * exposer en nom nu (g_declaredGlobals). elementDepth == -1 hors
         * element. */
        char curElem[64] = {0};
        int  elementDepth = -1;

        for (;;) {
            Token tok = scanner_scan_token(&s);
            if (tok.type == TOKEN_EOF) break;
            if (tok.type == TOKEN_NEWLINE || tok.type == TOKEN_ERROR) continue;

            if (tok.type == TOKEN_FIN) {
                if (depth > 0) depth--;
                /* Sortie du body element : on a referme son bloc. */
                if (elementDepth >= 0 && depth <= elementDepth) {
                    curElem[0] = '\0';
                    elementDepth = -1;
                }
                continue;
            }

            /*  — CONSTANTE : capter les noms declares au lieu de sauter
             * le bloc. Le motif general `IDENT est un <type>` plus bas ne matche
             * pas la forme `NOM = valeur` d'une constante, et le depth++ ci-
             * dessous masquait tout le contenu du bloc. Resultat : les CONSTANTE
             * d'un compagnon n'etaient jamais hydratees, donc inconnues des
             * fichiers compiles AVANT le declarant (ordre lexicographique) ->
             * "'X' : variable inconnue ou inaccessible", en mode projet.
             * Deux formes : bloc (`CONSTANTE\n NOM = v ... FIN`) et inline
             * (`CONSTANTE NOM = v`). On consomme le bloc ici (FIN inclus), donc
             * pas de depth++ a faire. */
            if (tok.type == TOKEN_CONSTANTE) {
                int constCaptureDepth = (elementDepth >= 0) ? elementDepth + 1 : 0;
                bool capture = (depth == constCaptureDepth);
                bool sawNewline = false;
                Token c = scanner_scan_token(&s);
                while (c.type == TOKEN_NEWLINE) {
                    sawNewline = true;
                    c = scanner_scan_token(&s);
                }
                if (!sawNewline) {
                    /* Forme inline : CONSTANTE NOM = valeur (pas de FIN). */
                    Token nxt = scanner_scan_token(&s);
                    if (capture && c.type == TOKEN_IDENTIFIER &&
                        nxt.type == TOKEN_EQUAL) {
                        global_track_declare_from_neighbor(c.start, c.length,
                                                            c.line);
                    }
                    continue;
                }
                /* Forme bloc : tout IDENT suivi de '=' est une constante. */
                for (;;) {
                    if (c.type == TOKEN_EOF || c.type == TOKEN_FIN) break;
                    Token nxt = scanner_scan_token(&s);
                    if (capture && c.type == TOKEN_IDENTIFIER &&
                        nxt.type == TOKEN_EQUAL) {
                        global_track_declare_from_neighbor(c.start, c.length,
                                                            c.line);
                    }
                    c = nxt;
                }
                continue;
            }

            /* block-openers au depth 0 ou plus : incrementent depth pour
             * eviter de capter des IDENT EST X internes a un bloc. Verdict de
             * la source unique — `SI c ALORS instr` n'ouvre rien. CONSTANTE est
             * traite au-dessus (le bloc y est consomme, FIN inclus). */
            if (prescan_token_in_depth_table(tok.type)) {
                if (local_scan_depth_delta(tok, &s) > 0) depth++;
                continue;
            }
            if (tok.type == TOKEN_AVEC) {
                depth++;
                continue;
            }

            /*  — niveau de capture : hors element, seul le depth 0
             * (historique). Dans un body element, seul le niveau directement
             * sous l'element (depth == elementDepth + 1). */
            int captureDepth = (elementDepth >= 0) ? elementDepth + 1 : 0;

            /*  — jumeau de prescan_source_unified : un bloc
             * `COL_X est une Colonne ... FIN` (ou Volet) ouvre un corps ferme par
             * FIN, mais son ouvreur (TOKEN_COLONNE / genre Volet) est post-copule
             * et absent de la table de profondeur. Niche dans une Table, il vit a
             * captureDepth+1, donc sous le guard ci-dessous : jamais compte comme
             * ouvreur ici, alors que son FIN, lui, decremente. La profondeur
             * sous-descend d'un cran par colonne, et la colonne SUIVANTE retombe a
             * captureDepth ou elle est captee a tort comme globale d'element
             * (`FEN$COL`). Ce nom nu reecrit court-circuite ensuite l'intercept
             * receveur `COL..Couleur` (repli widget-alias -> variable inconnue).
             * On equilibre l'ouvreur ici, a toute profondeur, avant le guard. */
            if (tok.type == TOKEN_IDENTIFIER && depth != captureDepth) {
                Scanner probe = s;
                Token t = scanner_scan_token(&probe);
                while (t.type == TOKEN_NEWLINE) t = scanner_scan_token(&probe);
                if (t.type == TOKEN_EST) {
                    do { t = scanner_scan_token(&probe); }
                    while (t.type == TOKEN_NEWLINE);
                    /* article optionnel un/une (FR) ou a/an (EN) */
                    if ((t.type == TOKEN_IDENTIFIER &&
                         ((t.length == 2 && strncasecmp(t.start, "un", 2) == 0) ||
                          (t.length == 3 && strncasecmp(t.start, "une", 3) == 0))) ||
                        t.type == TOKEN_A ||
                        (t.type == TOKEN_IDENTIFIER && t.length == 2 &&
                         strncasecmp(t.start, "an", 2) == 0) ||
                        (t.type == TOKEN_IDENTIFIER && t.length == 1 &&
                         (t.start[0] == 'a' || t.start[0] == 'A'))) {
                        do { t = scanner_scan_token(&probe); }
                        while (t.type == TOKEN_NEWLINE);
                    }
                    if (t.type == TOKEN_COLONNE || token_is_volet_genre(t)) {
                        depth++;
                        continue;
                    }
                }
            }

            if (depth != captureDepth) continue;
            if (tok.type != TOKEN_IDENTIFIER) continue;

            /* `IDENT est un? <type>` au top-level.  — lookahead NON
             * DESTRUCTIF (meme patron que le parse reel : clone, regarde,
             * restaure). Un IDENT qui n'ouvre pas une declaration doit rendre
             * le token qu'il a lu, sinon il l'avale : c'est la cause racine
             * corrigee par  sur le walker jumeau des collections. Le
             * jumeau n'a pas de symptome connu ici (les globales restent
             * exposees sous leur nom nu au runtime), mais le piege est le
             * meme. */
            Token name = tok;
            Scanner beforeLookahead = s;
            Token next;
            do { next = scanner_scan_token(&s); }
            while (next.type == TOKEN_NEWLINE);
            if (next.type != TOKEN_EST) { s = beforeLookahead; continue; }

            Token after;
            do { after = scanner_scan_token(&s); }
            while (after.type == TOKEN_NEWLINE);
            /* Skip optional "un"/"une". */
            if (after.type == TOKEN_IDENTIFIER &&
                (after.length == 2 || after.length == 3) &&
                (strncasecmp(after.start, "un", 2) == 0 ||
                 strncasecmp(after.start, "une", 3) == 0)) {
                do { after = scanner_scan_token(&s); }
                while (after.type == TOKEN_NEWLINE);
            }
            /* Skip optional EN article "a"/"an" (copule `is a/an <Type>`).
             * `a` est scanne comme TOKEN_A (borne de plage), sans ambiguite
             * en position post-EST ; `an` reste IDENT 2 chars. */
            else if (after.type == TOKEN_A ||
                     (after.type == TOKEN_IDENTIFIER && after.length == 2 &&
                      strncasecmp(after.start, "an", 2) == 0) ||
                     (after.type == TOKEN_IDENTIFIER && after.length == 1 &&
                      (after.start[0] == 'a' || after.start[0] == 'A'))) {
                do { after = scanner_scan_token(&s); }
                while (after.type == TOKEN_NEWLINE);
            }

            /*  : modificateur 'Champ'/'Field' = declaration de
             * controle de fenetre (`LIB_X est un Champ Libellé`). Chaque
             * fenetre a son propre espace de noms de controles : un controle
             * voisin n'est PAS une variable globale top-level et ne doit pas
             * alimenter le shadow check (sinon deux fenetres voisines avec un
             * controle homonyme se telescopent a tort). Le controle a un corps
             * (PROPRIETES/PROCEDURE) -> depth++ pour refermer le bloc. */
            if (token_is_champ_modifier(after)) {
                depth++;
                continue;
            }

            /*  — un bloc Fenetre/Etat voisin EXPOSE ses globales
             * top-level (declarations `sTest est une chaine` de niveau body,
             * = Declarations globales canon, ) sous leur nom NU. Depuis
             * que le top-level fenetre ne tourne plus en eager au chargement
             * (fenetre endormie jusqu'a Ouvre), ces noms ne sont plus exposes
             * au runtime au boot : il faut les rendre visibles au COMPILE pour
             * que `Trace(sTest)` apres `Ouvre(FEN_X)` dans un fichier voisin
             * compile (cf. tests/regression/window_global_var). On entre donc
             * dans le body au lieu de le rendre opaque : capture des globales
             * plain de niveau 1 (body fenetre), saut des sous-blocs (controles,
             * PROCEDURE, PROPRIETES) via le depth-tracker general de la boucle.
             * Les controles `LIB_X est un Champ ...` sont deja exclus plus haut
             * (modificateur Champ/Field -> depth++, ). */
            if (after.type == TOKEN_FENETRE || after.type == TOKEN_ETAT) {
                /*  — entre dans le body element : retient le nom de
                 * l'element et la profondeur de son body. Les globales de
                 * niveau body seront enregistrees QUALIFIEES (g_element_globals)
                 * et NON exposees en nom nu. depth++ pour suivre le FIN de
                 * l'element (son body vit a elementDepth + 1). Imbrication
                 * d'elements impossible (1 fichier = 1 Fenetre/Etat) -> pas de
                 * pile a gerer. */
                if (name.length < (int)sizeof(curElem)) {
                    memcpy(curElem, name.start, (size_t)name.length);
                    curElem[name.length] = '\0';
                    elementDepth = depth;
                }
                depth++;
                continue;
            }

            /* Skip si type "block" — geres ailleurs (knownUserTypes,
             * prescan widgets, etc.) et pas des variables au sens shadow. */
            bool isBlockType = (after.type == TOKEN_CLASSE ||
                                after.type == TOKEN_STRUCTURE ||
                                after.type == TOKEN_INTERFACE ||
                                after.type == TOKEN_ENUMERATION ||
                                after.type == TOKEN_COMBINAISON ||
                                after.type == TOKEN_LIBELLE ||
                                after.type == TOKEN_BOUTON ||
                                after.type == TOKEN_SAISIE);
            if (isBlockType) {
                /* Le block-opener n'est PAS reconsommable : le scanner l'a
                 * deja avance. On incremente depth pour que le FIN du bloc
                 * referme correctement. */
                depth++;
                continue;
            }

            /*  — un `GR_X est un Groupe` au top-level fenetre est un
             * MEMBRE d'element addressable en nom nu depuis le script (comme
             * un controle, canon ), PAS une globale scopee. Il reste
             * donc un global voisin bare (comportement historique). Symetrique
             * du skip cote var_declaration_after_est. */
            bool afterIsGroupe = (after.type == TOKEN_IDENTIFIER &&
                ((after.length == 6 && strncasecmp(after.start, "Groupe", 6) == 0) ||
                 (after.length == 5 && strncasecmp(after.start, "Group",  5) == 0)));
            if (afterIsGroupe) {
                global_track_declare_from_neighbor(name.start, name.length,
                                                   name.line);
                continue;
            }

            /*  — globale au niveau body d'un element voisin :
             * enregistree QUALIFIEE (g_element_globals) pour servir l'acces
             * `FEN_X.gNom` cross-fichier. PAS de global_track_declare_from_
             * neighbor : le nom nu ne doit pas devenir un global connu (sinon
             * il fuiterait au compile depuis le script -> regle de portee
             *  cassee). */
            if (elementDepth >= 0 && curElem[0] != '\0') {
                element_globals_register(curElem, (int)strlen(curElem),
                                         name.start, name.length);
                continue;
            }

            /* Variable globale ordinaire (entier, chaine, type user, ...). */
            global_track_declare_from_neighbor(name.start, name.length, name.line);
        }
}

static void hydrate_globals_from_neighbors(SymbolTable* symbols) {
    if (symbols == NULL) return;
    if (neighbor_prebuilt_for(symbols)) {
        neighbor_replay_globals(currentFileIndex);
        return;
    }
    for (int k = 0; k < symbols->sourceCount; k++) {
        if (symbols->sources[k].fileIndex == currentFileIndex) continue;
        globals_scan_one_source(symbols->sources[k].source);
    }
}

/*  — indexe les membres des blocs CollectionDeProcédures du projet
 * (fichier courant + voisins) dans g_collection_members, pour la resolution
 * nom-nu (avec detection d'ambiguite) et l'acces qualifie `COL.membre`
 * cross-fichier. Scan lexical leger calque sur hydrate_globals_from_neighbors.
 * On inclut le fichier courant (pas de skip currentFileIndex) : le define-side
 * re-enregistre (dedup) mais le scan upfront rend les forward-refs intra-
 * collection resolubles quel que soit l'ordre.
 *
 *  — `currentSource` est le texte que le parse reel va traiter juste
 * apres. S'il figure a l'identique dans les sources scannees, les deux
 * indexations sont comparables et le garde de coherence s'active en fin de
 * bloc collection. */
static void collection_scan_one_source(const char* src) {
        if (src == NULL) return;
        Scanner s;
        scanner_init(&s, src);
        int  depth = 0;
        char curColl[64] = {0};
        int  collDepth = -1;
        /*  — même mécanique pour les blocs Fenetre/Etat : leurs types
         * internes (Structure/Énum/Combinaison) sont enregistrés comme
         * membres-type QUALIFIE-ONLY (exposed=false) de l'element. */
        char curElem[64] = {0};
        int  elemDepth = -1;
        /*  — mode de portee courant dans le corps de collection : en
         * LOCAL, un membre de donnees est confine (pas enregistre comme membre
         * expose). Reset a GLOBAL a chaque ouverture de bloc collection. */
        bool confine = false;
        /*  — profondeur du bloc Interface ouvert (-1 = aucun). Les
         * signatures de methode d'une Interface n'ont PAS de corps ni de FIN
         * propre : les compter comme ouvrants (comme toute PROCEDURE) sur-
         * incremente la profondeur d'un cran jamais referme, et TOUT membre
         * declare apres l'Interface disparait de l'index. */
        int  ifaceDepth = -1;

        for (;;) {
            Token tok = scanner_scan_token(&s);
            if (tok.type == TOKEN_EOF) break;
            if (tok.type == TOKEN_NEWLINE || tok.type == TOKEN_ERROR) continue;

            if (tok.type == TOKEN_FIN) {
                if (depth > 0) depth--;
                if (collDepth >= 0 && depth <= collDepth) {
                    curColl[0] = '\0';
                    collDepth = -1;
                    confine = false;
                }
                if (elemDepth >= 0 && depth <= elemDepth) {
                    curElem[0] = '\0';
                    elemDepth = -1;
                }
                if (ifaceDepth >= 0 && depth <= ifaceDepth) ifaceDepth = -1;
                continue;
            }

            /*  — CONSTANTE dans le corps de collection : consommer le
             * bloc (FIN inclus) SANS depth++, comme le scan global.
             * Sinon le FIN du bloc CONSTANT fait un depth-- non apparié →
             * underflow → curColl vidé prématurément → les procédures qui
             * SUIVENT le bloc ne sont plus enregistrées comme membres → leur
             * appel dans le code d'init n'est pas manglé `<COL>$proc` et échoue
             * au runtime. Deux formes : bloc (`CONSTANTE\n NOM=v ... FIN`) et
             * inline (`CONSTANTE NOM = v`, pas de FIN). */
            if (tok.type == TOKEN_CONSTANTE) {
                bool sawNewline = false;
                Token c = scanner_scan_token(&s);
                while (c.type == TOKEN_NEWLINE) { sawNewline = true; c = scanner_scan_token(&s); }
                if (sawNewline) {
                    /* Forme bloc : consommer jusqu'au FIN apparié. */
                    while (c.type != TOKEN_EOF && c.type != TOKEN_FIN) {
                        c = scanner_scan_token(&s);
                    }
                }
                /* Forme inline : rien à refermer (le `= valeur` suivant est
                 * scanné normalement, sans effet sur depth). */
                continue;
            }

            /*  — bascule GLOBAL/LOCAL dans le corps de la collection. */
            if ((tok.type == TOKEN_GLOBAL || tok.type == TOKEN_LOCAL)
                && curColl[0] != '\0' && depth == collDepth + 1) {
                confine = (tok.type == TOKEN_LOCAL);
                continue;
            }

            /* Membre PROCEDURE/FONCTION du corps de collection : capture le nom
             * (apres visibilite optionnelle) puis descend dans le body. */
            if (tok.type == TOKEN_PROCEDURE || tok.type == TOKEN_FONCTION) {
                /*  — signature d'Interface : declaration sans corps,
                 * donc AUCUN FIN a suivre. Ni membre, ni ouvrant de bloc. */
                if (ifaceDepth >= 0 && depth == ifaceDepth + 1) continue;
                /*  — resync recovery : une PROCEDURE membre laissee sans
                 * son FIN propre laisse la profondeur au-dessus du niveau du
                 * corps de collection. Les procedures de collection ne
                 * s'imbriquent pas : un token PROCEDURE plus profond que
                 * collDepth+1 signifie que le membre precedent n'a pas ete
                 * ferme. On ramene la profondeur au niveau du corps pour que CE
                 * membre soit compte (sinon il sort de l'index -> « procedure
                 * inconnue » sur les appelants cross-fichier). Ne se declenche
                 * jamais sur une collection bien formee (aucun PROCEDURE n'y
                 * apparait au-dela de collDepth+1). Miroir prescan de la
                 * recovery du parse reel (proc_declaration). */
                if (curColl[0] != '\0' && depth > collDepth + 1) {
                    depth = collDepth + 1;
                }
                if (curColl[0] != '\0' && depth == collDepth + 1) {
                    Token nm;
                    do { nm = scanner_scan_token(&s); } while (nm.type == TOKEN_NEWLINE);
                    if (nm.type == TOKEN_PRIVE || nm.type == TOKEN_PROTEGE ||
                        nm.type == TOKEN_PUBLIC) {
                        do { nm = scanner_scan_token(&s); } while (nm.type == TOKEN_NEWLINE);
                    }
                    if (nm.type == TOKEN_IDENTIFIER) {
                        collection_member_register(curColl, (int)strlen(curColl),
                                                   nm.start, nm.length, true);
                    }
                }
                depth++;
                continue;
            }

            /* Autres ouvrants de bloc lexicaux (corps de proc / conditions).
             * Verdict de la source unique : `SI c ALORS instr` n'ouvre rien.
             * PROCEDURE/FONCTION sont traites au-dessus (capture du membre). */
            if (prescan_token_in_depth_table(tok.type)) {
                if (local_scan_depth_delta(tok, &s) > 0) depth++;
                continue;
            }
            if (tok.type == TOKEN_AVEC) {
                depth++;
                continue;
            }

            if (tok.type != TOKEN_IDENTIFIER) continue;

            Token name = tok;
            /*  — lookahead `IDENT est ?` NON DESTRUCTIF. Tout IDENT qui
             * n'ouvre pas une declaration doit rendre le token qu'il a lu :
             * sinon il le mange. Le cas nuisible est le type d'element d'un
             * `tableau [associatif] de <T>` — seule position ou le type reste un
             * IDENTIFIER (les types primitifs ont un token dedie). Un PROCEDURE
             * ainsi avale n'etait plus enregistre comme membre, et le FIN de son
             * corps refermait le bloc (depth <= collDepth) : TOUS les membres
             * suivants disparaissaient a leur tour. Le rattrapage  sur
             * `next == FIN` devient inutile, le rollback rend le FIN a la boucle
             * qui le traite par son chemin normal. */
            Scanner beforeLookahead = s;
            Token next;
            do { next = scanner_scan_token(&s); } while (next.type == TOKEN_NEWLINE);
            if (next.type != TOKEN_EST) { s = beforeLookahead; continue; }

            Token after;
            do { after = scanner_scan_token(&s); } while (after.type == TOKEN_NEWLINE);
            /* Skip un/une. */
            if (after.type == TOKEN_IDENTIFIER &&
                (after.length == 2 || after.length == 3) &&
                (strncasecmp(after.start, "un", 2) == 0 ||
                 strncasecmp(after.start, "une", 3) == 0)) {
                do { after = scanner_scan_token(&s); } while (after.type == TOKEN_NEWLINE);
            }
            /* Skip article EN a/an. */
            else if (after.type == TOKEN_A ||
                     (after.type == TOKEN_IDENTIFIER && after.length == 2 &&
                      strncasecmp(after.start, "an", 2) == 0) ||
                     (after.type == TOKEN_IDENTIFIER && after.length == 1 &&
                      (after.start[0] == 'a' || after.start[0] == 'A'))) {
                do { after = scanner_scan_token(&s); } while (after.type == TOKEN_NEWLINE);
            }

            /* Ouverture d'un bloc collection `NOM est une CollectionDeProcédures`. */
            if (after.type == TOKEN_IDENTIFIER &&
                token_is_collection_kw(after.start, after.length)) {
                if (name.length < (int)sizeof(curColl)) {
                    memcpy(curColl, name.start, (size_t)name.length);
                    curColl[name.length] = '\0';
                    collDepth = depth;
                    confine = false;  /*  : corps repart en mode GLOBAL */
                }
                depth++;
                continue;
            }

            /*  — ouverture d'un bloc Fenetre/Etat `NOM est une Fenêtre`
             * / `... est un Etat`. Le nom devient le namespace pour l'accès
             * qualifié de ses types internes. */
            if (after.type == TOKEN_FENETRE || after.type == TOKEN_ETAT) {
                if (name.length < (int)sizeof(curElem)) {
                    memcpy(curElem, name.start, (size_t)name.length);
                    curElem[name.length] = '\0';
                    elemDepth = depth;
                }
                depth++;
                continue;
            }

            /*  — ouverture d'un bloc Interface, quel que soit le
             * contexte. Son corps ne contient que des SIGNATURES sans FIN
             * propre : il faut retenir sa profondeur pour ne pas les compter
             * comme ouvrants (cf. le garde ifaceDepth sur TOKEN_PROCEDURE).
             * Membre EXPOSE de la collection quand elle est declaree au niveau
             * direct de son corps. */
            if (after.type == TOKEN_INTERFACE) {
                if (curColl[0] != '\0' && depth == collDepth + 1) {
                    collection_member_register(curColl, (int)strlen(curColl),
                                               name.start, name.length, true);
                }
                ifaceDepth = depth;
                depth++;
                continue;
            }

            /*  — type déclaré au top-level direct d'une Fenetre/Etat :
             * membre-type QUALIFIE-ONLY (exposed=false). Seule la forme
             * `ELEM.Type` resout ; le nom nu reste encapsulé (les VARIABLES de
             * l'element, elles, ne sont jamais enregistrées ici). */
            if (curElem[0] != '\0' && depth == elemDepth + 1) {
                if (after.type == TOKEN_STRUCTURE || after.type == TOKEN_ENUMERATION ||
                    after.type == TOKEN_COMBINAISON) {
                    collection_member_register(curElem, (int)strlen(curElem),
                                               name.start, name.length,
                                               /*exposed=*/false);
                    depth++;
                    continue;
                }
            }

            /* Dans le corps d'une collection : globale de donnees exposee en nom
             * nu. Les types-bloc Structure/Combinaison/Classe/Interface ne sont
             * PAS des membres exposes — types normaux ; depth++ pour suivre leur
             * FIN. L'ENUMERATION, elle, EST un membre expose :
             * enregistree comme membre (qualif `COL.Énum.membre` + nom nu) ET
             * depth++ (son corps a un FIN). */
            if (curColl[0] != '\0' && depth == collDepth + 1) {
                /*  — STRUCTURE/COMBINAISON/INTERFACE rejoignent
                 * l'ENUMERATION comme membres-type EXPOSES d'une
                 * collection : qualifiables `COL.Type` en position de type +
                 * resolubles en nom nu. Seule la CLASSE reste exclue (1 classe =
                 * 1 fichier, ) — type non-membre, depth++ pour son FIN.
                 * L'INTERFACE est traitee plus haut (corps sans FIN par
                 * signature, ). */
                if (after.type == TOKEN_ENUMERATION || after.type == TOKEN_STRUCTURE ||
                    after.type == TOKEN_COMBINAISON) {
                    collection_member_register(curColl, (int)strlen(curColl),
                                               name.start, name.length, true);
                    depth++;
                    continue;
                }
                if (after.type == TOKEN_CLASSE) {
                    depth++;
                    continue;
                }
                /*  — en mode LOCAL, la globale de donnees est confinee :
                 * pas de membre expose (invisible en nom nu + aux procedures de
                 * la collection). Les types ci-dessus restent exposes. */
                if (!confine) {
                    collection_member_register(curColl, (int)strlen(curColl),
                                               name.start, name.length, true);
                }
                continue;
            }

            /*  — type imbriqué (Structure/Énumération/Combinaison) DANS
             * le corps d'un membre struct d'une collection ou d'un élément
             * Fenêtre/État (donc à une profondeur > coll/elemDepth+1, non traité
             * par les branches de membre DIRECT ci-dessus, qui `continue`nt) :
             * ce n'est PAS un membre exposé (registre plat, parité avec le parse
             * réel après le guard g_current_collection_name), mais son bloc porte
             * un FIN propre. Suivre sa profondeur, sinon son FIN referme
             * prématurément la collection/l'élément englobant → les membres qui
             * SUIVENT disparaissent de l'index (stRectangle introuvable après un
             * stCercle à type niché). */
            if ((curColl[0] != '\0' || curElem[0] != '\0')
                && (after.type == TOKEN_STRUCTURE
                    || after.type == TOKEN_ENUMERATION
                    || after.type == TOKEN_COMBINAISON)) {
                depth++;
                continue;
            }
        }
}

static void hydrate_collection_members(SymbolTable* symbols,
                                       const char* currentSource) {
    if (symbols == NULL) return;
    g_collection_register_from_prescan = true;

    if (neighbor_prebuilt_for(symbols)) {
        neighbor_replay_collection(currentSource);
        g_collection_register_from_prescan = false;
        return;
    }

    for (int k = 0; k < symbols->sourceCount; k++) {
        const char* src = symbols->sources[k].source;
        if (src == NULL) continue;
        if (currentSource != NULL && strcmp(src, currentSource) == 0) {
            g_collection_prescan_saw_source = true;
        }
        collection_scan_one_source(src);
    }
    g_collection_register_from_prescan = false;
}

/*  — garde de coherence pre-scan / parse reel, appele a la fermeture
 * d'un bloc CollectionDeProcédures. Tout membre que le parse a defini mais que
 * le scan lexical n'a pas indexe serait introuvable sous son nom nu depuis un
 * autre fichier du projet : c'est la panne silencieuse de  (appel
 * accepte au compile, « Fonction ou procédure inconnue » au runtime).
 *
 * Sens UNIQUE volontaire (parse ⊆ scan). L'inverse — un nom vu par le scan que
 * le parse ne definit pas — est sans danger et arrive legitimement : membre
 * confine par LOCAL, bloc mort, autre collection homonyme d'un voisin. Le
 * signaler casserait des compilations correctes, exactement ce qu'un garde ne
 * doit jamais faire. */
static void collection_prescan_cross_check(const char* coll,
                                           const Token* where) {
    if (!g_collection_prescan_saw_source || g_collection_nested_rejected) return;
    if (coll == NULL || coll[0] == '\0') return;
    int collLen = (int)strlen(coll);
    for (int i = 0; i < g_collection_members_count; i++) {
        CollectionMember* m = &g_collection_members[i];
        if (!m->seenParse || m->seenPrescan) continue;
        if ((int)strlen(m->collection) != collLen) continue;
        if (memcmp(m->collection, coll, (size_t)collLen) != 0) continue;
        owl_emit_error_at(where, E_SEM_COLLECTION_MEMBER_NOT_PRESCANNED,
                          "member", m->name, "collection", m->collection, NULL);
        parser.panicMode = false;
    }
}

static void warn_unused_globals(void) {
    mark_globals_used_from_neighbors();
    for (int i = 0; i < g_declaredGlobalsCount; i++) {
        DeclaredGlobal* g = &g_declaredGlobals[i];
        if (g->isUsed || g->hasInitializer || g->suppressUnused) continue;
        /* Type definitions (struct/enum/class) aren't "used" variables */
        if (g->isStructureType) continue;
        /*  : entries from neighbor files aren't ours to warn. */
        if (g->isFromNeighbor) continue;
        /*  — pour une globale d'element mangled `<ELEM>$<var>`, le
         * test de prefixe "_" (opt-out unused) doit porter sur le nom NU
         * (apres le `$`), pas sur le prefixe element. */
        const char* baseName = g->name;
        const char* dollar = strchr(g->name, '$');
        if (dollar != NULL && dollar[1] != '\0') baseName = dollar + 1;
        if (baseName[0] == '$' || baseName[0] == '_' || baseName[0] == ' ')
            continue;
        Token tok;
        /*  — message utilisateur : afficher le nom NU (apres le `$`),
         * jamais la cle mangled interne `<ELEM>$<var>` (Regle 7). */
        tok.start  = baseName;
        tok.length = (int)strlen(baseName);
        tok.line   = g->line;
        tok.column = 0;
        tok.type   = TOKEN_IDENTIFIER;
        owl_emit_warning_at(&tok, W_SEM_VAR_UNUSED, "name", baseName, NULL);
    }
}

/* ================================================================
 * ERROR REPORTING
 * ================================================================ */

/* Diagnostic capture mode -- when set, errors go to buffer instead of stderr */
static CompileDiagnostic* diagBuffer = NULL;
static int diagCapacity = 0;
static int* diagCount = NULL;

void compile_set_error_capture(CompileDiagnostic* buffer, int capacity, int* count) {
    diagBuffer = buffer;
    diagCapacity = capacity;
    diagCount = count;
    if (count) *count = 0;
}

/* Warning capture mode -- parallel to error capture */
static CompileDiagnostic* warnBuffer = NULL;
static int warnCapacity = 0;
static int* warnCount = NULL;

void compile_set_warning_capture(CompileDiagnostic* buffer, int capacity, int* count) {
    warnBuffer = buffer;
    warnCapacity = capacity;
    warnCount = count;
    if (count) *count = 0;
}

/*  : basename du fichier en cours de compilation, grave dans chaque
 * diagnostic capture. Les consommateurs qui affichent en differe n'ont plus de
 * contexte de compilation et ne peuvent pas le reconstituer. */
static void diag_set_origin(CompileDiagnostic* d) {
    d->origin[0] = '\0';
    if (currentFilename == NULL) return;
    const char* base = currentFilename;
    for (const char* p = currentFilename; *p; p++) {
        if (*p == '/' || *p == '\\') base = p + 1;
    }
    snprintf(d->origin, sizeof(d->origin), "%s", base);
}

static bool g_json_compile_errors = false;
void compile_set_json_errors(bool enabled) { g_json_compile_errors = enabled; }

/* JSON-escape a string onto stderr. Matches vm.c:json_esc_stderr so the
 * compile/runtime channels produce consistently-escaped output. */
static void compile_json_esc(const char* s) {
    if (!s) { fputs("null", stderr); return; }
    fputc('"', stderr);
    for (const unsigned char* p = (const unsigned char*)s; *p; p++) {
        if (*p == '"')       fputs("\\\"", stderr);
        else if (*p == '\\') fputs("\\\\", stderr);
        else if (*p == '\n') fputs("\\n", stderr);
        else if (*p == '\r') fputs("\\r", stderr);
        else if (*p == '\t') fputs("\\t", stderr);
        else if (*p < 0x20)  fprintf(stderr, "\\u%04x", *p);
        else                 fputc(*p, stderr);
    }
    fputc('"', stderr);
}

/* Saturation d'une limite compile-time : message uniforme, renvoie
 * l'utilisateur vers `owl explain <name>` pour la doc. Defini ici (declare
 * dans owl_limits.h) parce que c'est le parser qui sait raconter le ou
 * (line/column courant).
 *
 * Cf.  : `owl_limits.def` est la single source des limites,
 * tous les sites qui pouvaient saturer silencieusement appellent
 * maintenant cette fonction. */
void error_capacity_exceeded(const char* limit_name, int max) {
    char maxBuf[24];
    snprintf(maxBuf, sizeof(maxBuf), "%d", max);
    owl_emit_error_at(&parser.previous, E_SYNTAX_CAPACITY_EXCEEDED,
                      "limite", limit_name ? limit_name : "MAX_",
                      "max", maxBuf,
                      NULL);
}

/* ================================================================
 * Bridge registry erreurs ( lot 2) — expose la machinerie
 * d'emission legacy (diagBuffer, JSON, currentFilename) aux helpers
 * compile-aware definis dans owl_errors.c. La fonction reproduit
 * exactement le format de error_at()/warning_at() : un appelant
 * qui passe par cette fonction obtient un diagnostic indiscernable
 * du legacy cote stderr / consommateur LSP.
 * ================================================================ */
void compile_emit_diagnostic_at(const Token* token, const char* message,
                                bool isWarning) {
    if (!token || !message) return;

    if (!isWarning) {
        /* Mimique error_at : respect panicMode + set hadError + panicMode. */
        if (parser.panicMode) return;
        parser.panicMode = true;

        if (diagBuffer != NULL && diagCount != NULL && *diagCount < diagCapacity) {
            CompileDiagnostic* d = &diagBuffer[*diagCount];
            d->line = token->line;
            d->column = token->column;
            snprintf(d->message, sizeof(d->message), "%s", message);
            d->file[0] = '\0';
            diag_set_origin(d);
            (*diagCount)++;
        } else if (diagBuffer == NULL) {
            if (g_json_compile_errors) {
                char msgBuf[1024];
                if (token->type == TOKEN_EOF) {
                    snprintf(msgBuf, sizeof(msgBuf), "at end: %s", message);
                } else if (token->type == TOKEN_ERROR) {
                    snprintf(msgBuf, sizeof(msgBuf), "%s", message);
                } else {
                    snprintf(msgBuf, sizeof(msgBuf), "at '%.*s': %s",
                             token->length, token->start, message);
                }
                fputs("{\"kind\":\"compile\",\"message\":", stderr);
                compile_json_esc(msgBuf);
                fprintf(stderr, ",\"line\":%d,\"column\":%d",
                        token->line, token->column);
                if (currentFilename) {
                    fputs(",\"file\":", stderr);
                    compile_json_esc(currentFilename);
                }
                fputs("}\n", stderr);
                fflush(stderr);
            } else {
                if (currentFilename)
                    fprintf(stderr, "[%s:%d] Error", currentFilename, token->line);
                else
                    fprintf(stderr, "[line %d] Error", token->line);

                if (token->type == TOKEN_EOF) {
                    fprintf(stderr, " at end");
                } else if (token->type != TOKEN_ERROR) {
                    fprintf(stderr, " at '%.*s'", token->length, token->start);
                }
                fprintf(stderr, ": %s\n", message);
            }
        }
        parser.hadError = true;
    } else {
        /* Mimique warning_at : route vers warnBuffer ou stderr, pas de
         * hadError ni panicMode. */
        if (warnBuffer != NULL && warnCount != NULL && *warnCount < warnCapacity) {
            CompileDiagnostic* d = &warnBuffer[*warnCount];
            d->line = token->line;
            d->column = token->column > 0 ? token->column : 1;
            snprintf(d->message, sizeof(d->message), "%s", message);
            d->file[0] = '\0';
            diag_set_origin(d);
            (*warnCount)++;
        } else {
            if (currentFilename != NULL) {
                fprintf(stderr, "[%s:%d] Warning", currentFilename, token->line);
            } else {
                fprintf(stderr, "[line %d] Warning", token->line);
            }
            if (token->type == TOKEN_EOF) {
                fprintf(stderr, " at end");
            } else if (token->type != TOKEN_ERROR) {
                fprintf(stderr, " at '%.*s'", token->length, token->start);
            }
            fprintf(stderr, ": %s\n", message);
        }
    }
}

const Token* compile_current_token(void) {
    return &parser.current;
}

int compile_peek_had_error(void) {
    return parser.hadError ? 1 : 0;
}

void compile_reset_parser_error_state(void) {
    parser.hadError = false;
    parser.panicMode = false;
    parser.hadFileError = false; /*  */
}

/* ================================================================
 * TOKEN CONSUMPTION
 * ================================================================ */

static void advance_token(void) {
    parser.previous = parser.current;
    crossedNewline = false;

    for (;;) {
        parser.current = scanner_scan_token(&parser.scanner);

        /* Skip newlines and semicolons (statement separators) */
        if (parser.current.type == TOKEN_NEWLINE) { crossedNewline = true; continue; }
        if (parser.current.type == TOKEN_SEMICOLON) { crossedNewline = true; continue; }

        if (parser.current.type != TOKEN_ERROR) break;
        if (parser.current.start != NULL) {
            owl_emit_error_current(E_SEM_SCANNER_LEX_ERROR,
                                   "message", parser.current.start,
                                   NULL);
        }
    }
}

static bool check(TokenType type) {
    return parser.current.type == type;
}

/*  — delta de profondeur du token COURANT DU PARSER, rendu par la
 * source unique (prescan_depth_delta, prescan.h). `parser.scanner` est
 * toujours positionne juste apres `parser.current` : c'est exactement le peek
 * attendu. Il est copie, le scan reel n'avance pas.
 *
 * Quinze boucles de saut/pre-passe de ce fichier portaient leur propre liste
 * d'ouvreurs, toutes comptant `SI c ALORS instr` comme un bloc a FIN. */
static int parser_depth_delta(void) {
    /* Un seul ajout par rapport a la table : la clause `SINON SI`. C'est un
     * LOOKBEHIND, donc hors de portee de la regle lexicale, et il vaut pour
     * les dix sites — une chaine SI / SINON SI / SINON est fermee par un SEUL
     * FIN. Le compter donne +1 par branche : dans un corps ENFIN, le FIN du
     * QUAND sert alors a refermer la fausse ouverture et le compilateur
     * reclame un FIN de plus sur une source legale. Meme critere que
     * if_statement (`check(TOKEN_SI) && !crossedNewline`) : un SI separe de
     * SINON par un saut de ligne est un vrai bloc imbrique, qui garde son FIN
     * propre. */
    if (parser.current.type == TOKEN_SI
        && parser.previous.type == TOKEN_SINON
        && !crossedNewline) {
        return 0;
    }
    Scanner peek = parser.scanner;
    return prescan_depth_delta(parser.current, &peek);
}

static bool match_token(TokenType type) {
    if (!check(type)) return false;
    advance_token();
    return true;
}

/*  — `consume` prend un code du catalogue, plus une prose anglaise.
 * Le litteral passe ici vivait une frame en amont de error_at_current() :
 * hors catalogue (donc monolingue) ET hors radar du lint de centralisation,
 * dont le perimetre etait defini par nom d'emetteur. La signature elle-meme
 * rend la regression impossible a ecrire. */
static void consume(TokenType type, OwlErrorCode code) {
    if (parser.current.type == type) {
        advance_token();
        return;
    }
    owl_emit_error_current(code);
}

/* ================================================================
 * EMIT BYTECODE
 * ================================================================ */

static void emit_byte(uint8_t byte) {
    chunk_write(current_chunk(), byte, parser.previous.line);
}

/* Lu une seule fois : le controle tourne a chaque emission d'instruction a
 * index de constante, plus une fois par fonction compilee. */
static bool owl_check_bytecode_enabled(void) {
    static int cached = -1;
    if (cached < 0) {
        const char* v = getenv("OWL_CHECK_BYTECODE");
        cached = (v != NULL && v[0] != '\0' && v[0] != '0') ? 1 : 0;
    }
    return cached == 1;
}

/*  — `byte1` est, par contrat, un opcode ; `byte2` son unique octet
 * d'operande brut (slot local, argCount, compteur, mode). Un opcode porteur
 * d'index de constante n'a rien a faire ici : son operande fait
 * OWL_CONST_IDX_BYTES octets et la largeur se lit dans la table canonique,
 * jamais au site d'appel. Le laisser passer ecrit une instruction plus courte
 * que ce que la VM lit — le flux d'octets qui suit devient illisible et le
 * programme part de travers loin du site fautif.
 *
 * Le typage de ConstIdx empeche la troncature distraite ; ce garde-fou-ci
 * couvre la troncature deliberee (`emit_bytes(getOp, (uint8_t)arg)`), que le
 * compilateur C accepte sans broncher. Refus bruyant, jamais d'octet tronque. */
static void emit_bytes(uint8_t byte1, uint8_t byte2) {
    if (chunk_opcode_has_const_index(byte1)) {
        fprintf(stderr,
                "OWL_BYTECODE_SHAPE: opcode %d porte un index de constante, "
                "emis par le chemin brut emit_bytes()\n", (int)byte1);
        owl_emit_error_at(&parser.previous, E_SEM_INTERNAL_BYTECODE_SHAPE);
        return;
    }
    emit_byte(byte1);
    emit_byte(byte2);
}

static void emit_return(void) {
    emit_byte(OP_NIL);
    emit_byte(OP_RETURN);
}

/*  — digue mecanique contre la troncature silencieuse.
 *
 * Un index de constante tient sur 16 bits. En C, passer un uint16_t a un
 * parametre uint8_t tronque SANS un mot du compilateur : c'est exactement le
 * mode de defaillance qui transforme un index > 255 en bytecode corrompu et
 * en crash a mille lignes de la. Le type struct rend cette conversion
 * impossible a ecrire — tout site qui veut un entier doit passer par
 * const_idx_i() et le dire.
 *
 * Corollaire : la largeur reellement emise n'est jamais choisie au site
 * d'appel, elle est lue dans chunk_opcode_shape() par emit_const_op(). */
typedef struct { uint16_t v; } ConstIdx;

static inline int const_idx_i(ConstIdx c) { return (int)c.v; }

static ConstIdx make_constant(Value value) {
    /* Deduplicate: reuse existing constant if SAME type and value. */
    Chunk* chunk = current_chunk();
    for (int i = 0; i < chunk->constants.count && i <= MAX_CHUNK_CONSTANTS; i++) {
        Value existing = chunk->constants.values[i];
        if (existing.type == value.type && values_equal(existing, value)) {
            ConstIdx r = { (uint16_t)i };
            return r;
        }
    }
    /*  lot 2b — root defensif systemique : value est typiquement le
     * resultat d'un obj_copy_string/obj_new_* transitoire NON encore rattache
     * au chunk. chunk_add_constant -> value_array_write -> GROW_ARRAY ->
     * owl_realloc peut declencher un GC qui collecte cette value avant qu'elle
     * soit ecrite dans le slot. Resultat : slot pointe sur memoire libre puis
     * reattribuee (signature : 'Undefined variable <garbage>' au runtime).
     * Push/pop est no-op pour les valeurs non-OBJ. */
    int isObj = IS_OBJ(value);
    if (isObj) vm_push(value);
    int constant = chunk_add_constant(current_chunk(), value);
    if (isObj) vm_pop();
    /* Le message dedie nomme la limite, donne sa valeur et renvoie vers
     * `owl explain` : meme contrat que le chemin commun, formule pour un mur
     * structurel du bytecode. */
    if (constant > MAX_CHUNK_CONSTANTS) { /* capacity-ok: E_SEM_BYTECODE_TOO_MANY_CONSTANTS */
        owl_emit_error_at(&parser.previous, E_SEM_BYTECODE_TOO_MANY_CONSTANTS);
        ConstIdx zero = { 0 };
        return zero;
    }
    ConstIdx r = { (uint16_t)constant };
    return r;
}

/* ----------------------------------------------------------------
 * Emission d'une instruction portant un index de constante.
 *
 * La largeur ecrite n'est PAS choisie ici : elle est lue dans la table
 * canonique chunk_opcode_shape(), celle-la meme qui sert a calculer les
 * tailles d'instruction, a marcher un slice et a desassembler. Emission et
 * lecture ne peuvent donc pas diverger par oubli d'un site.
 *
 * emit_const_op_n(op, indices[], nIdx, raw[], nRaw) est la forme generale ;
 * les trois wrappers couvrent les formes reellement emises.
 * ---------------------------------------------------------------- */
/*  — controle de synchronisation, actif sous OWL_CHECK_BYTECODE=1.
 *
 * Mesure faite sur le defaut trouve en revue : la verification TERMINALE
 * (marcher le chunk une seule fois, en fin de compilation, et exiger
 * d'atterrir sur count) ne detecte rien du tout. Un operande trop court fait
 * avaler a la marche l'octet d'opcode suivant ; l'octet de poids fort d'un
 * index < 256 vaut 0, qui est precisement OP_CONSTANT, donc la marche decode
 * une instruction fantome de 3 octets et se resynchronise sur le flux reel
 * deux instructions plus loin. Elle retombe sur count et se tait. Ce n'est pas
 * de la malchance : c'est le comportement normal d'une marche a re-synchro
 * libre sur un flux d'octets dense.
 *
 * D'ou ce controle-ci : on marche depuis le debut a CHAQUE emission
 * d'instruction a index de constante — moment ou l'on sait, par construction,
 * que chunk->count est une frontiere d'instruction. Une marche qui depasse
 * count (ou qui reste courte) signe une largeur ecrite ailleurs en desaccord
 * avec la table. Le desaccord est signale a l'instruction suivante, pas
 * plusieurs ecrans plus loin, et il ne peut plus etre efface par une
 * re-synchro fortuite. */
static void check_bytecode_sync(const char* where) {
    Chunk* ck = current_chunk();
    int i = 0;
    while (i < ck->count) {
        int sz = chunk_opcode_size(ck->code[i], ck, i);
        if (sz <= 0) break;
        i += sz;
    }
    if (i != ck->count) {
        fprintf(stderr,
                "OWL_CHECK_BYTECODE: chunk desynchronise avant %s "
                "(marche %d, count %d)\n", where, i, ck->count);
        owl_emit_error_at(&parser.previous, E_SEM_INTERNAL_BYTECODE_SHAPE);
    }
}

static void emit_const_op_n(uint8_t op, const ConstIdx* idx, int nIdx,
                            const uint8_t* raw, int nRaw) {
    if (owl_check_bytecode_enabled() && !parser.hadError) {
        check_bytecode_sync("emit_const_op");
    }
    OpcodeShape shape;
    if (!chunk_opcode_shape(op, &shape) ||
        shape.constIdx != nIdx || shape.raw != nRaw) {
        /* Table canonique et site d'emission en desaccord : le bytecode
         * produit serait illisible. On refuse d'emettre plutot que de poser
         * une instruction dont personne ne connait la taille. */
        owl_emit_error_at(&parser.previous, E_SEM_INTERNAL_BYTECODE_SHAPE);
        return;
    }
    emit_byte(op);
    for (int i = 0; i < nIdx; i++) {
        emit_byte((uint8_t)(idx[i].v >> 8));
        emit_byte((uint8_t)(idx[i].v & 0xFF));
    }
    for (int i = 0; i < nRaw; i++) emit_byte(raw[i]);
}

static void emit_const_op(uint8_t op, ConstIdx idx) {
    emit_const_op_n(op, &idx, 1, NULL, 0);
}

static void emit_const_op_b(uint8_t op, ConstIdx idx, uint8_t rawByte) {
    emit_const_op_n(op, &idx, 1, &rawByte, 1);
}

static void emit_const_op2_b(uint8_t op, ConstIdx a, ConstIdx b,
                             uint8_t rawByte) {
    ConstIdx pair[2] = { a, b };
    emit_const_op_n(op, pair, 2, &rawByte, 1);
}

/* Insere `[op][index]` a la position `pos`, a la largeur canonique. Sert aux
 * wrappers de coercion poses retroactivement devant un RHS deja emis. */
static void insert_const_op_before(int pos, uint8_t op, ConstIdx idx, int line) {
    OpcodeShape shape;
    if (!chunk_opcode_shape(op, &shape) || shape.constIdx != 1 || shape.raw != 0) {
        owl_emit_error_at(&parser.previous, E_SEM_INTERNAL_BYTECODE_SHAPE);
        return;
    }
    uint8_t buf[1 + OWL_CONST_IDX_BYTES];
    int n = 0;
    buf[n++] = op;
    buf[n++] = (uint8_t)(idx.v >> 8);
    buf[n++] = (uint8_t)(idx.v & 0xFF);
    chunk_insert_before(current_chunk(), pos, buf, n, line);
}

/* Opcode resolu a l'execution du compilateur : `arg` designe soit un slot
 * local (1 octet brut), soit un index de constante (largeur canonique). Le
 * dispatch se fait sur la table, jamais sur une hypothese du site d'appel. */
static void emit_var_op(uint8_t op, int arg) {
    if (chunk_opcode_has_const_index(op)) {
        ConstIdx idx = { (uint16_t)arg };
        emit_const_op(op, idx);
    } else {
        emit_bytes(op, (uint8_t)arg);
    }
}

/* Meme chose, mais ecrit directement dans le chunk avec une ligne imposee :
 * les peepholes reecrivent du bytecode deja emis, la ligne courante du parser
 * n'est plus celle de l'instruction reconstruite. */
static void write_var_op(Chunk* ck, uint8_t op, int arg, int line) {
    OpcodeShape shape;
    if (!chunk_opcode_shape(op, &shape)) return;
    chunk_write(ck, op, line);
    if (shape.constIdx == 1) {
        chunk_write(ck, (uint8_t)(((unsigned)arg >> 8) & 0xFF), line);
        chunk_write(ck, (uint8_t)((unsigned)arg & 0xFF), line);
    } else {
        chunk_write(ck, (uint8_t)arg, line);
    }
}

/* Premier operande d'une instruction : index de constante a la largeur
 * canonique, ou slot local sur un octet. -1 si l'opcode n'a pas d'operande. */
static int read_const_or_slot_operand(const Chunk* ck, int offset) {
    OpcodeShape shape;
    if (!chunk_opcode_shape(ck->code[offset], &shape)) return -1;
    if (shape.constIdx == 0 && shape.raw == 0) return -1;
    if (shape.constIdx == 1) {
        return (ck->code[offset + 1] << 8) | ck->code[offset + 2];
    }
    return ck->code[offset + 1];
}

static void emit_constant(Value value) {
    emit_const_op(OP_CONSTANT, make_constant(value));
}

static int emit_jump(uint8_t instruction) {
    emit_byte(instruction);
    emit_byte(0xff);
    emit_byte(0xff);
    return current_chunk()->count - 2;
}

static void patch_jump(int offset) {
    int jump = current_chunk()->count - offset - 2;
    if (jump > UINT16_MAX) {
        owl_emit_error_at(&parser.previous, E_SEM_BYTECODE_JUMP_TOO_LARGE);
    }
    current_chunk()->code[offset] = (jump >> 8) & 0xff;
    current_chunk()->code[offset + 1] = jump & 0xff;
}

static void emit_loop(int loopStart) {
    emit_byte(OP_LOOP);
    int offset = current_chunk()->count - loopStart + 2;
    if (offset > UINT16_MAX) {
        owl_emit_error_at(&parser.previous, E_SEM_BYTECODE_LOOP_BODY_TOO_LARGE);
    }
    emit_byte((offset >> 8) & 0xff);
    emit_byte(offset & 0xff);
}

/* ================================================================
 * COMPILER INIT
 * ================================================================ */

static void init_compiler(Compiler* compiler, FunctionType type) {
    compiler->enclosing = current;
    compiler->function = NULL;
    compiler->type = type;
    compiler->localCount = 0;
    compiler->scopeDepth = 0;
    compiler->loopDepth = 0;
    compiler->switchDepth = 0;
    compiler->seenReturnKind = 0;
    compiler->seenReturnLine = 0;
    compiler->id = ++g_nextCompilerId;
    /* Brancher current AVANT toute allocation GC : gc_mark_compiler_roots()
     * itere current->enclosing et marque compiler->function. Tant que
     * function==NULL, gc_mark_object(NULL) est no-op ; des qu'elle est
     * affectee, elle est dans la chaine root et survit aux GC declenches
     * par les allocations qui suivent (filename, chunk, etc.). */
    current = compiler;
    compiler->function = obj_new_function();
    if (currentFilename != NULL) {
        compiler->function->filename = obj_copy_string(
            currentFilename, (int)strlen(currentFilename));
    }
    compiler->function->chunk = ALLOCATE(Chunk, 1);
    chunk_init(compiler->function->chunk);

    /* Reserve stack slot 0: for methods it's the receiver (this),
     * for other functions it's the function itself */
    Local* local = &current->locals[current->localCount++];
    local->depth = 0;
    local->isNullable = false;
    local->isUndetectable = false;
    local->isUsed = true;  /* Always consider reserved slots as used */
    local->hasInitializer = false;
    local->declaredType = TOKEN_EOF;
    local->structTypeName[0] = '\0';
    local->arrayElemStructType[0] = '\0';
    local->icone_catalog_name = NULL;
    if (type == TYPE_METHOD || type == TYPE_CONSTRUCTOR) {
        local->name.start = "this";
        local->name.length = 4;
        /* Debug info : le slot 0 d'une methode/constructeur est le receveur
         * (l'instance, accessible via le mot-cle `Objet`/`this`). Sans nom
         * enregistre, le debogueur l'affiche "slot 0". On l'expose comme
         * `this` (plage ouverte sur toute la fonction). Les fonctions/script
         * ont en slot 0 la fonction elle-meme -> filtree par get_locals. */
        obj_function_add_local_name(current->function, "this", 4, 0, 0);
    } else {
        local->name.start = "";
        local->name.length = 0;
    }
}

static void warn_unused_locals(int depth);  /* Forward declaration */

static ObjFunction* end_compiler(void) {
    /* Warn about unused variables before finishing */
    warn_unused_locals(0);  /* Check all locals (depth >= 0) */
    if (current->type == TYPE_SCRIPT) {
        warn_unused_globals();  /* Check script-level globals */
    }
    emit_return();
    ObjFunction* function = current->function;

    /*  — derniere passe du filet, activee par OWL_CHECK_BYTECODE=1
     * (meme idiome que OWL_STRESS_GC).
     *
     * A ne PAS prendre pour une preuve de synchronisation : une marche qui
     * retombe sur count prouve seulement que le decalage eventuel s'est
     * resorbe avant la fin, ce qui est le cas courant (cf. le commentaire de
     * check_bytecode_sync). Le vrai controle est celui qui tourne a chaque
     * emission d'instruction a index de constante ; celui-ci ne rattrape que
     * le decalage survenu APRES la derniere de ces emissions. */
    if (!parser.hadError && owl_check_bytecode_enabled()
        && !chunk_walk_is_consistent(current_chunk())) {
        fprintf(stderr,
                "OWL_CHECK_BYTECODE: chunk desynchronise dans '%s' (%s)\n",
                function->name != NULL ? function->name->chars : "<script>",
                currentFilename != NULL ? currentFilename : "?");
        parser.hadError = true;
    }

#ifdef DEBUG_PRINT_CODE
    if (!parser.hadError) {
        debug_disassemble_chunk(current_chunk(),
            function->name != NULL ? function->name->chars : "<script>");
    }
#endif

    current = current->enclosing;
    return function;
}

/* ================================================================
 * VARIABLES AND SCOPING
 * ================================================================ */

static ConstIdx identifier_constant(Token* name) {
    /* Strip UTF-8 accents so "JSONVersChaîne" resolves to "JSONVersChaine".
     * This makes identifiers accent-insensitive at compile time. */
    char stripped[256];
    int len = scanner_strip_accents(name->start, name->length,
                                    stripped, sizeof(stripped));
    return make_constant(OBJ_VAL(obj_copy_string(stripped, len)));
}

/*  — choisit l'opcode adapte pour pousser un nom de TYPE :
 *  - builtin connu du registry (Cadre, httpRequête, Chrono, etc.) → vm.types
 *    via OP_GET_TYPE_GLOBAL (template enregistre par
 *    register_builtin_types/register_global_instance).
 *  - sinon (user struct/class declare dans le fichier ou cross-file) → vm.globals
 *    via OP_GET_GLOBAL (l'ObjInstance template y est pose par OP_DEFINE_GLOBAL).
 *
 * Phase 1 du chantier : on segmente uniquement les templates BUILTIN. La
 * migration eventuelle des user types vers vm.types est hors-scope. */
static void emit_get_type_global(const char* typeStart, int typeLen, ConstIdx typeIdx) {
    char probe[256];
    int n = typeLen < (int)sizeof(probe) - 1 ? typeLen : (int)sizeof(probe) - 1;
    memcpy(probe, typeStart, (size_t)n);
    probe[n] = '\0';
    if (owl_registry_type_find(probe) != NULL) {
        emit_const_op(OP_GET_TYPE_GLOBAL, typeIdx);
    } else {
        emit_const_op(OP_GET_GLOBAL, typeIdx);
    }
}

static void begin_scope(void) {
    current->scopeDepth++;
}

static void warn_unused_locals(int depth) {
    for (int i = current->localCount - 1; i >= 0; i--) {
        Local* local = &current->locals[i];
        if (local->depth < depth) break;
        /* Skip reserved/internal slots, $ and _ names, variables with explicit
         * initializers, et  : slots fantomes ajoutees apres erreur
         * shadow scope-different (l'erreur principale couvre deja le user). */
        if (!local->isUsed && !local->hasInitializer && !local->suppressUnused &&
            local->name.length > 0 &&
            local->name.start[0] != '$' && local->name.start[0] != '_' &&
            local->name.start[0] != ' ' && !local->isErrorPlaceholder) {
            Token tok = local->name;
            tok.line = local->declaredLine;
            char nameBuf[128];
            int nlen = local->name.length < (int)sizeof(nameBuf) - 1
                       ? local->name.length : (int)sizeof(nameBuf) - 1;
            memcpy(nameBuf, local->name.start, (size_t)nlen);
            nameBuf[nlen] = '\0';
            owl_emit_warning_at(&tok, W_SEM_VAR_UNUSED, "name", nameBuf, NULL);
        }
    }
}

static void end_scope(void) {
    warn_unused_locals(current->scopeDepth);
    current->scopeDepth--;
    /*  — ferme les plages de validite des noms de locales du scope
     * qui se termine AVANT d'emettre les OP_POP. Le slot le plus bas du scope
     * sortant est le premier local dont depth > scopeDepth ; au-dela, les noms
     * ne sont plus valides (slots recycles par un scope frere sequentiel). On
     * capture ce seuil sans toucher localCount, puis on ferme jusqu'a l'offset
     * bytecode courant, puis on pop normalement. */
    int firstClosedSlot = current->localCount;
    for (int i = current->localCount - 1; i >= 0; i--) {
        if (current->locals[i].depth > current->scopeDepth) {
            firstClosedSlot = i;
        } else {
            break;
        }
    }
    if (current->function && firstClosedSlot < current->localCount) {
        obj_function_close_local_names(current->function, firstClosedSlot,
                                       current_chunk()->count);
    }
    while (current->localCount > 0 &&
           current->locals[current->localCount - 1].depth > current->scopeDepth) {
        emit_byte(OP_POP);
        current->localCount--;
    }
}

/* ================================================================
 * LOOP CONTEXT (for SORTIR / CONTINUER)
 * ================================================================ */

static void push_loop(int start, bool deferContinue) {
    if (current->loopDepth >= MAX_LOOP_DEPTH) {
        error_capacity_exceeded("MAX_LOOP_DEPTH", MAX_LOOP_DEPTH);
        return;
    }
    LoopContext* loop = &current->loopStack[current->loopDepth++];
    loop->start = start;
    loop->scopeDepth = current->scopeDepth;
    loop->breakCount = 0;
    loop->continueCount = 0;
    loop->useDeferredContinue = deferContinue;
}

static void patch_loop_continues(void) {
    /* Patch deferred continue jumps to current position */
    if (current->loopDepth <= 0) return;
    LoopContext* loop = &current->loopStack[current->loopDepth - 1];
    for (int i = 0; i < loop->continueCount; i++) {
        patch_jump(loop->continues[i]);
    }
    loop->continueCount = 0;
}

static void pop_loop(void) {
    if (current->loopDepth <= 0) return;
    LoopContext* loop = &current->loopStack[current->loopDepth - 1];
    /* Patch all break jumps to point here */
    for (int i = 0; i < loop->breakCount; i++) {
        patch_jump(loop->breaks[i]);
    }
    current->loopDepth--;
}

/* emit_break_levels(N) — sort de N niveaux de boucles imbriquees.
 *   N=1 : sortie de la boucle la plus proche (forme `SORTIR` simple, canon)
 *   N>1 : sortie de N boucles imbriquees (forme `SORTIR(N)`, canon)
 * N doit etre compris entre 1 et loopDepth ; sinon compile-error. */
static void emit_break_levels(int levels) {
    if (current->loopDepth <= 0) {
        owl_emit_error_at(&parser.previous, E_SEM_SORTIR_OUTSIDE_LOOP);
        return;
    }
    if (levels < 1) levels = 1;
    if (levels > current->loopDepth) {
        char levBuf[16], availBuf[16];
        snprintf(levBuf, sizeof(levBuf), "%d", levels);
        snprintf(availBuf, sizeof(availBuf), "%d", current->loopDepth);
        owl_emit_error_at(&parser.previous, E_SEM_SORTIR_TOO_DEEP,
                          "levels", levBuf,
                          "available", availBuf,
                          NULL);
        return;
    }
    /* Boucle cible = la N-eme boucle englobante (N=1 -> la plus proche). */
    LoopContext* loop = &current->loopStack[current->loopDepth - levels];

    /* Pop locals that are deeper than the target loop's scope */
    int popCount = 0;
    for (int i = current->localCount - 1; i >= 0; i--) {
        if (current->locals[i].depth <= loop->scopeDepth) break;
        popCount++;
    }
    if (popCount > 0) {
        emit_bytes(OP_POPN, (uint8_t)popCount);
    }

    /* Emit forward jump (to be patched at target loop's exit) */
    if (loop->breakCount < MAX_BREAKS) {
        loop->breaks[loop->breakCount++] = emit_jump(OP_JUMP);
    } else {
        error_capacity_exceeded("MAX_BREAKS", MAX_BREAKS);
    }
}

static void emit_break(void) {
    emit_break_levels(1);
}

/* ----------------------------------------------------------------
 * SWITCH CONTEXT — pour SORTIR SELON. Parallele a loopStack mais
 * totalement independant : SORTIR (sans SELON) regarde loopStack,
 * SORTIR SELON regarde switchStack. Aucune interaction entre les
 * deux — un SELON dans une boucle laisse les deux stacks actifs.
 * ---------------------------------------------------------------- */

static void push_switch(void) {
    if (current->switchDepth >= MAX_LOOP_DEPTH) {
        error_capacity_exceeded("MAX_LOOP_DEPTH", MAX_LOOP_DEPTH);
        return;
    }
    SwitchContext* sw = &current->switchStack[current->switchDepth++];
    sw->scopeDepth = current->scopeDepth;
    sw->breakCount = 0;
}

static void pop_switch(void) {
    if (current->switchDepth <= 0) return;
    SwitchContext* sw = &current->switchStack[current->switchDepth - 1];
    for (int i = 0; i < sw->breakCount; i++) {
        patch_jump(sw->breaks[i]);
    }
    current->switchDepth--;
}

static void emit_break_switch_at(Token where) {
    if (current->switchDepth <= 0) {
        owl_emit_error_at(&where, E_SEM_SORTIR_SELON_OUTSIDE_SELON);
        return;
    }
    SwitchContext* sw = &current->switchStack[current->switchDepth - 1];

    /* Unwind locals plus profonds que le scope du SELON. */
    int popCount = 0;
    for (int i = current->localCount - 1; i >= 0; i--) {
        if (current->locals[i].depth <= sw->scopeDepth) break;
        popCount++;
    }
    if (popCount > 0) {
        emit_bytes(OP_POPN, (uint8_t)popCount);
    }

    if (sw->breakCount < MAX_BREAKS) {
        sw->breaks[sw->breakCount++] = emit_jump(OP_JUMP);
    } else {
        error_capacity_exceeded("MAX_BREAKS", MAX_BREAKS);
    }
}

static void emit_continue(void) {
    if (current->loopDepth <= 0) {
        owl_emit_error_at(&parser.previous, E_SEM_CONTINUER_OUTSIDE_LOOP);
        return;
    }
    LoopContext* loop = &current->loopStack[current->loopDepth - 1];

    /* Pop locals that are deeper than the loop's scope */
    int popCount = 0;
    for (int i = current->localCount - 1; i >= 0; i--) {
        if (current->locals[i].depth <= loop->scopeDepth) break;
        popCount++;
    }
    if (popCount > 0) {
        emit_bytes(OP_POPN, (uint8_t)popCount);
    }

    if (loop->useDeferredContinue) {
        /* Forward jump to be patched later (for POUR loops where
         * increment code comes after the body) */
        if (loop->continueCount < MAX_BREAKS) {
            loop->continues[loop->continueCount++] = emit_jump(OP_JUMP);
        } else {
            error_capacity_exceeded("MAX_BREAKS", MAX_BREAKS);
        }
    } else {
        /* Jump back to loop start (for TANTQUE, BOUCLE) */
        emit_loop(loop->start);
    }
}

static void add_local(Token name) {
    if (current->localCount >= MAX_LOCALS_PER_FUNCTION) {
        error_capacity_exceeded("MAX_LOCALS_PER_FUNCTION", MAX_LOCALS_PER_FUNCTION);
        /*  — bascule en panic mode pour neutraliser les 3
         * residus OOB write identifies par l'audit  dans
         * for_statement / foreach_array_statement /
         * declare_synthetic_local. Sans ce flag, le parser continue
         * la declaration en cours et appelle resolve_local qui peut
         * indexer locals[-1] ou locals[localCount-1] avec
         * localCount=0. panicMode fait que les emissions suivantes
         * sont silencieuses jusqu'au prochain synchronize(). */
        parser.panicMode = true;
        return;
    }
    Local* local = &current->locals[current->localCount++];
    local->name = name;
    local->depth = current->scopeDepth;
    local->declaredLine = name.line;
    local->isNullable = false;
    local->isUndetectable = false;
    local->isUsed = false;
    local->hasInitializer = false;
    local->declaredType = TOKEN_EOF;
    /* CRITIQUE : structTypeName est un char[64] non-pointeur. Sans reset,
     * il garde le contenu de la slot précédente — si un compileur antérieur
     * a déclaré là un local de type composé (ex. `req est un httpRequête`),
     * la string fuite vers le nouveau local et resolve_var_struct_type
     * retourne le faux type. C'est le bug du crash multi-fichier
     * test_json_vers_chaine. */
    local->structTypeName[0] = '\0';
    local->arrayElemStructType[0] = '\0';
    local->icone_catalog_name = NULL;
    local->isErrorPlaceholder = false;  /*  : set true par declare_variable apres
                                         * shadow erreur ; init false sinon. */
    local->suppressUnused = false;      /*  : set true si attribut <utile>/<useful>. */
    /*  — debug info : enregistre nom -> slot dans la fonction pour
     * que le debogueur resolve l'identifiant par nom dans la frame. Le slot
     * est l'index courant (slot 0 = la fonction, jamais passe ici). Les noms
     * synthetiques internes du compiler (commencant par '_' ou vides) ne sont
     * pas utiles a l'utilisateur mais inoffensifs ; on les laisse passer pour
     * coller a la convention de slots reelle. */
    if (current->function && name.start && name.length > 0) {
        /*  — ip_start = offset bytecode courant au moment de la
         * declaration. Borne le debut de la plage de validite du nom. */
        obj_function_add_local_name(current->function, name.start, name.length,
                                    current->localCount - 1,
                                    current_chunk()->count);
    }
}

/* Case-insensitive, accent-insensitive identifier comparison for locals */
static bool identifiers_equal(Token* a, Token* b) {
    /*  phase 2b : compare en forme canon (strip_accents + tolower)
     * pour rendre les locales insensibles a la casse ET aux accents.
     * Avant : tolower byte-a-byte ASCII pur — donc `nClé` (5 octets UTF-8)
     * et `nCle` (4 octets) etaient consideres distincts. */
    char canonA[256], canonB[256];
    int lenA = scanner_canonicalize_identifier(a->start, a->length,
                                               canonA, sizeof(canonA));
    int lenB = scanner_canonicalize_identifier(b->start, b->length,
                                               canonB, sizeof(canonB));
    if (lenA != lenB) return false;
    return memcmp(canonA, canonB, (size_t)lenA) == 0;
}

static int resolve_local(Compiler* compiler, Token* name) {
    for (int i = compiler->localCount - 1; i >= 0; i--) {
        Local* local = &compiler->locals[i];
        if (identifiers_equal(name, &local->name)) {
            local->isUsed = true;  /* Mark as used */
            return i;
        }
    }
    return -1;
}

/* Reject assignment to type names at global scope */
static bool reject_type_assignment(Token* name, bool isGlobal) {
    /* Locals can shadow type names, but globals cannot overwrite types.
     * Use is_type_not_variable to exclude variables already declared in this unit. */
    if (isGlobal && is_type_not_variable(name->start, name->length)) {
        owl_emit_error_at(name, E_SEM_CANNOT_ASSIGN_TO_TYPE_NAME);
        return true;  /* rejected */
    }
    return false;
}

/* Warning si la declaration shadow une constante "magique" du langage
 * (TAB/CRLF/LF/EOT/ESC/ESP/ValPI + Vrai/Faux/Null). Aligne sur canon
 * canon : `tab est un tableau` est accepte (variable locale gagne au
 * runtime), l'IDE WD emet juste un warning de surcharge.
 *
 * Le message dit exactement ce qui se passe (variable shadow constante,
 * forme uppercase reste accessible) plutot que d'alarmer le user avec
 * un "masque" qui sonne comme une erreur. La forme canonique uppercase
 * vient de fmt_keywords[].canonical — fiable pour TAB / CRLF / ValPI…
 *
 * Les formes heritees de fin de ligne rc/cr ne sont plus des
 * symboles du registre mais restent resolvables (EOL_LEGACY_ALIASES) : le
 * masquage y est reel et silencieux, d'ou un warning dedie dont le message
 * parle de la forme ecrite par le user et non de CRLF, qu'il n'a pas ecrit.
 *
 * Perimetre limite aux sets CAT_BOOL et CAT_EOL_LEGACY du formatter — on
 * NE warn PAS sur les
 * constantes "metier" du registry (httpGet, fLecture, psdMiseEnForme…). Trop
 * bruyant : la convention Hungarian (sTexte, fNum, nCount…) collisionne
 * regulierement avec ces noms metier, mais c'est un usage legitime, pas
 * un shadow conscient. */
static void warn_if_shadows_builtin_const(Token* name) {
    if (name == NULL || name->length <= 0 || name->length >= 128) return;
    char buf[128];
    memcpy(buf, name->start, (size_t)name->length);
    buf[name->length] = '\0';
    const char* canonical = owl_formatter_magic_const_canonical(buf);
    const char* eolCanonical = canonical != NULL
                               ? NULL
                               : owl_formatter_eol_legacy_canonical(buf);
    if (canonical == NULL && eolCanonical == NULL) return;

    char nameBuf[128];
    int nlen = name->length < (int)sizeof(nameBuf) - 1
               ? name->length : (int)sizeof(nameBuf) - 1;
    memcpy(nameBuf, name->start, (size_t)nlen);
    nameBuf[nlen] = '\0';

    if (canonical != NULL) {
        owl_emit_warning_at(name, W_SEM_VAR_SHADOWS_CONST,
                            "name", nameBuf,
                            "canonical", canonical,
                            NULL);
        return;
    }
    /* La forme masquee se nomme en majuscules (RC / CR), pas telle que le user
     * a orthographie sa variable. Les cles sont ASCII pur : toupper suffit. */
    char legacyBuf[128];
    for (int i = 0; i < nlen; i++) {
        legacyBuf[i] = (char)toupper((unsigned char)nameBuf[i]);
    }
    legacyBuf[nlen] = '\0';
    owl_emit_warning_at(name, W_SEM_VAR_SHADOWS_EOL_LEGACY,
                        "name", nameBuf,
                        "legacy", legacyBuf,
                        "canonical", eolCanonical,
                        NULL);
}

static void declare_variable(Token* name) {
    warn_if_shadows_builtin_const(name);
    if (current->scopeDepth == 0) {
        /*  — mode LOCAL top-level : la variable est confinee au flux
         * top-level (slot local de la fonction top-level), pas promue en
         * globale. On exclut les PROCEDURE (toujours globales / cross-file,
         * marquees g_declaring_procedure) ; les types (struct/classe/enum) ne
         * passent pas par declare_variable a ce niveau, ils restent exposes.
         * Signale a define_variable de ne pas emettre OP_DEFINE_GLOBAL. */
        if (g_toplevel_confine && !g_declaring_procedure) {
            add_local(*name);
            g_last_declare_confined = true;
            return;
        }
        g_last_declare_confined = false;
        /* At scopeDepth=0 we emit OP_DEFINE_GLOBAL regardless of compile
         * context — TYPE_SCRIPT (a .owl file) or TYPE_FUNCTION (the body
         * passed to ExécuteCode / Compile). Track the name in both cases
         * so later reads in the same unit pass the compile-time "known
         * identifier" check. The duplicate-check is TYPE_SCRIPT-only
         * because dynamic function bodies start with a fresh
         * g_declaredGlobals table (reset at each compile_impl call) — no
         * realistic duplicate path. */
        for (int i = decl_globals_bucket_head(name->start, name->length); i != -1;
             i = g_declaredGlobals[i].hashNext) {
            if (decl_globals_match(i, name->start, name->length)) {
                /*  — entree hydratee depuis un fichier voisin :
                 * traitement specifique.
                 *  - On NE veut PAS d'erreur DUPLICATE_VAR_IN_SCOPE (deux
                 *    fichiers du projet peuvent legitimement declarer le
                 *    meme nom au top-level — la passe duplicate cross-file
                 *    est geree par SymbolTable, pas ici).
                 *  - Le SEUL cas ou le neighbor entry doit declencher
                 *    quelque chose ici est le shadow champ Fenetre/Etat
                 *    (g_current_window_decl != NULL) : on emet
                 *    E_SEM_VAR_SHADOWS_OUTER_SCOPE comme en mono-fichier.
                 *    Le pointage "ligne du voisin" reste informatif (la
                 *    ligne est valide dans le fichier voisin). */
                if (g_declaredGlobals[i].isFromNeighbor) {
                    if (g_current_window_decl != NULL) {
                        char outerName[64];
                        int nl = g_declaredGlobals[i].nameLen;
                        if (nl >= (int)sizeof(outerName)) nl = (int)sizeof(outerName) - 1;
                        memcpy(outerName, g_declaredGlobals[i].name, (size_t)nl);
                        outerName[nl] = '\0';
                        char lineBuf[16];
                        snprintf(lineBuf, sizeof(lineBuf), "%d",
                                 g_declaredGlobals[i].line);
                        owl_emit_error_at(name, E_SEM_VAR_SHADOWS_OUTER_SCOPE,
                                          "name", outerName,
                                          "line", lineBuf,
                                          NULL);
                        return;
                    }
                    continue;
                }
                /*  — extension de  au scope top-level same-file.
                 * Un type user (Structure/Classe/Enumération/Combinaison/Interface)
                 * declare au top-level du MEME fichier ne peut pas etre re-utilise
                 * comme nom de variable au top-level : meme scope, meme collision
                 * que var+var. g_declaredGlobals n'est jamais pre-peuple avec des
                 * types cross-file (cf. compile_in_project : la pre-population va
                 * dans knownUserTypes, pas g_declaredGlobals) donc isStructureType
                 * true ici implique "declare dans CE fichier". En TYPE_FUNCTION
                 * (body dynamique Compile/ExécuteCode) on garde le bypass
                 * historique : pas de notion de "meme fichier" coherente. */
                if (g_declaredGlobals[i].isStructureType) {
                    if (current->type == TYPE_SCRIPT) {
                        owl_emit_error_at(&parser.previous, E_SEM_DUPLICATE_VAR_IN_SCOPE);
                        return;
                    }
                    continue;
                }
                /* B.2 : entree prescannee — c'est cet appel qui materialise
                 * la decl reelle. On consomme le flag et update la ligne. */
                if (g_declaredGlobals[i].isPrescanned) {
                    g_declaredGlobals[i].isPrescanned = false;
                    g_declaredGlobals[i].line = name->line;
                    return;
                }
                if (current->type == TYPE_SCRIPT) {
                    /*  — une PROCEDURE top-level est un global first-
                     * class. Si la nouvelle declaration EST une procedure
                     * (g_declaring_procedure) ou si le symbole en collision
                     * est deja une procedure (isProcedure), le message doit
                     * parler de "procedure", pas de "variable". */
                    if (g_declaring_procedure || g_declaredGlobals[i].isProcedure) {
                        owl_emit_error_at(&parser.previous, E_SEM_DUPLICATE_PROC_IN_SCOPE);
                    } else {
                        owl_emit_error_at(&parser.previous, E_SEM_DUPLICATE_VAR_IN_SCOPE);
                    }
                    return;
                }
                /*  — cas Fenetre/Etat : leur top-level body est compile
                 * en TYPE_FUNCTION (winTopCompiler / etat top-level) mais sans
                 * begin_scope, donc scopeDepth=0. Une variable declaree ici qui
                 * matche un global projet existant est un shadow scope-different
                 * (le scope conceptuel est l'objet Fenetre/Etat, pas le main).
                 * Le marqueur g_current_window_decl != NULL distingue ce cas
                 * du body dynamique ExécuteCode/Compile (ou aucun window decl
                 * n'est pose). Skip entree prescannee (forward ref consommee)
                 * et entree isStructureType (deja gere au-dessus). */
                if (g_current_window_decl != NULL &&
                    !g_declaredGlobals[i].isPrescanned &&
                    !g_declaredGlobals[i].isStructureType) {
                    char outerName[64];
                    int nl = g_declaredGlobals[i].nameLen;
                    if (nl >= (int)sizeof(outerName)) nl = (int)sizeof(outerName) - 1;
                    memcpy(outerName, g_declaredGlobals[i].name, (size_t)nl);
                    outerName[nl] = '\0';
                    char lineBuf[16];
                    snprintf(lineBuf, sizeof(lineBuf), "%d",
                             g_declaredGlobals[i].line);
                    owl_emit_error_at(name, E_SEM_VAR_SHADOWS_OUTER_SCOPE,
                                      "name", outerName,
                                      "line", lineBuf,
                                      NULL);
                    return;
                }
                /* In TYPE_FUNCTION, silently treat redeclaration as a
                 * no-op on the tracker side — runtime handles it. */
                return;
            }
        }
        global_track_declare(name->start, name->length, name->line);
        return;
    }

    /* Check for duplicate in current scope */
    for (int i = current->localCount - 1; i >= 0; i--) {
        Local* local = &current->locals[i];
        if (local->depth < current->scopeDepth) break;
        if (identifiers_equal(name, &local->name)) {
            owl_emit_error_at(name, E_SEM_DUPLICATE_VAR_IN_SCOPE);
        }
    }

    /*  — alignement avec le check var+var : declarer une variable
     * du meme nom qu'un type user (Structure/Enumeration) declare dans la
     * MEME procedure est une collision. Le tracking via Compiler.id evite
     * les faux positifs sur les types declares au top-level (ownerId=0)
     * ou dans une autre procedure. Insensible casse/accents (decl_globals_match
     * factorise scanner_canonicalize_identifier — meme principe ici via
     * name_iequals + strip d'accents cote nom). */
    if (current->type != TYPE_SCRIPT) {
        char nameStrip[128];
        int nameStripLen = scanner_strip_accents(name->start, name->length,
                                                  nameStrip, sizeof(nameStrip));
        if (nameStripLen > 0) {
            for (int i = 0; i < knownUserTypeCount; i++) {
                if (knownUserTypes[i].ownerCompilerId != current->id) continue;
                char typeStrip[128];
                int typeStripLen = scanner_strip_accents(
                    knownUserTypes[i].name, knownUserTypes[i].length,
                    typeStrip, sizeof(typeStrip) - 1);
                if (typeStripLen <= 0) continue;
                typeStrip[typeStripLen] = '\0';
                if (typeStripLen == nameStripLen &&
                    name_iequals(nameStrip, nameStripLen, typeStrip)) {
                    owl_emit_error_at(name, E_SEM_DUPLICATE_VAR_IN_SCOPE);
                    break;
                }
            }
        }
    }

    /*  — interdiction du shadow scope-different.
     *
     * On est ici en scopeDepth > 0 : variable locale, parametre procedure,
     * variable de boucle POUR, ou champ Fenetre/Etat declare dans un body.
     * Si le nom collisionne avec :
     *   - une globale projet declaree au top-level du meme fichier
     *     (g_declaredGlobals, hors isStructureType et hors entrees
     *     prescannees non encore consommees)
     *   - un type user declare au top-level du meme fichier
     *     (knownUserTypes avec ownerCompilerId=0)
     * on emet E_SEM_VAR_SHADOWS_OUTER_SCOPE avec pointage de la ligne outer.
     *
     * Alignement pilier 2 OWL : determinisme lecture. Divergence assumee vs
     * canon (warning d'office -> error compile). Cf .
     *
     * Cas cross-file (champ classe vs variable globale main.owl) traite hors
     * declare_variable, dans handle_check_command_no_vm_lifecycle, parce que
     * la pre-population cross-file via knownUserTypes/g_declaredGlobals n'a
     * pas la granularite fichier requise pour pointer le bon fichier. */
    {
        char outerName[64];
        int outerLine = 0;
        bool shadows = false;

        /* (a) Globales projet declarees au top-level de CE fichier. */
        for (int i = decl_globals_bucket_head(name->start, name->length); i != -1;
             i = g_declaredGlobals[i].hashNext) {
            if (!decl_globals_match(i, name->start, name->length)) continue;
            /* Les types user passent par knownUserTypes pour le pointage
             * (declLine connu). Skip ici. */
            if (g_declaredGlobals[i].isStructureType) continue;
            /* Entree prescannee non encore consommee : c'est bien une
             * declaration top-level reelle (ou en cours), shadow valide. */
            shadows = true;
            outerLine = g_declaredGlobals[i].line;
            int nl = g_declaredGlobals[i].nameLen;
            if (nl >= (int)sizeof(outerName)) nl = (int)sizeof(outerName) - 1;
            memcpy(outerName, g_declaredGlobals[i].name, (size_t)nl);
            outerName[nl] = '\0';
            break;
        }

        /* (b) Types user declares au top-level de CE fichier
         * (ownerCompilerId=0). Indispensable pour le cas type top-level
         * shadow par var locale (test var_shadows_type_top_level_by_local). */
        if (!shadows) {
            char nameStrip[128];
            int nameStripLen = scanner_strip_accents(name->start, name->length,
                                                      nameStrip, sizeof(nameStrip));
            if (nameStripLen > 0) {
                for (int i = 0; i < knownUserTypeCount; i++) {
                    if (knownUserTypes[i].ownerCompilerId != 0) continue;
                    char typeStrip[128];
                    int typeStripLen = scanner_strip_accents(
                        knownUserTypes[i].name, knownUserTypes[i].length,
                        typeStrip, sizeof(typeStrip) - 1);
                    if (typeStripLen <= 0) continue;
                    typeStrip[typeStripLen] = '\0';
                    if (typeStripLen == nameStripLen &&
                        name_iequals(nameStrip, nameStripLen, typeStrip)) {
                        shadows = true;
                        outerLine = knownUserTypes[i].declLine;
                        int nl = knownUserTypes[i].length;
                        if (nl >= (int)sizeof(outerName)) nl = (int)sizeof(outerName) - 1;
                        memcpy(outerName, knownUserTypes[i].name, (size_t)nl);
                        outerName[nl] = '\0';
                        break;
                    }
                }
            }
        }

        if (shadows) {
            char lineBuf[16];
            snprintf(lineBuf, sizeof(lineBuf), "%d", outerLine);
            owl_emit_error_at(name, E_SEM_VAR_SHADOWS_OUTER_SCOPE,
                              "name", outerName,
                              "line", lineBuf,
                              NULL);
            /*  — Invariant "declare_variable ne return jamais a
             * moitie" : on a emis l'erreur shadow mais on ajoute quand
             * meme le local. Sans ca, les callers (for_statement,
             * foreach_array_statement, foreach_string_split_statement,
             * foreach_string_position_statement) qui font ensuite
             * `resolve_local(current, &name)` recoivent -1, puis
             * indexent `current->locals[-1]` => OOB write negatif.
             * Latent en production (la corruption tombe sur des champs
             * adjacents de struct Compiler absorbes silencieusement),
             * mais bombe a retardement pour toute evolution future de
             * `struct Local`. Pad debug `int fix0342_repro_pad` revele
             * le crash : alignement saute, l'octet ecrit tombe sur la
             * save area, SIGSEGV au prochain ret.
             *
             * Le local est ajoute avec valeur NIL deja sur la stack (les
             * callers font `emit_byte(OP_NIL)` apres declare_variable
             * pour les variables visibles ; for_statement pousse la
             * borne start). Le bytecode genere apres l'erreur est jete
             * de toute facon — on est en compile-error, jamais execute. */
            add_local(*name);
            /*  : marquer la slot fantome pour qu'elle ne declenche pas
             * de warning W_SEM_VAR_UNUSED en cascade. L'erreur shadow est deja
             * la — un warning supplementaire ne ferait que du bruit. */
            if (current->localCount > 0) {
                current->locals[current->localCount - 1].isErrorPlaceholder = true;
            }
            return;
        }
    }

    add_local(*name);
}

static void define_variable(ConstIdx global) {
    if (current->scopeDepth > 0) return; /* local is already on the stack */
    /*  — variable confinee (mode LOCAL top-level) : la valeur d'init
     * reste le contenu du slot local reserve par declare_variable, pas de
     * promotion globale. On consomme le drapeau (une declaration = un define). */
    if (g_last_declare_confined) {
        g_last_declare_confined = false;
        return;
    }
    emit_const_op(OP_DEFINE_GLOBAL, global);
}

/* Enregistre la metadonnee de type d'une variable JUSTE declaree par
 * declare_variable, en routant vers le bon support :
 *  - slot local (`current->locals[localCount-1]`) si la declaration est un
 *    vrai local (scopeDepth > 0) OU un confine top-level (mode LOCAL,
 *    scopeDepth 0 mais `g_last_declare_confined` pose par declare_variable) ;
 *  - side-table `g_typed_globals` sinon (globale reelle, scopeDepth 0).
 *
 * Point unique d'alimentation : centralise la garde de confinement pour que
 * les cinq sites de declaration typee (File/Pile/Liste, JSON, Groupe, Champ,
 * variable typee ordinaire) ne puissent pas diverger — un 6e site ne peut
 * plus oublier le cas confine. A appeler APRES declare_variable et AVANT
 * define_variable (qui consomme g_last_declare_confined).
 *
 * Le declaredType TOKEN_EOF (variable sans type declare) ne peuple pas la
 * side-table globale (parite avec le comportement historique) mais est bien
 * pose sur le slot local. structName != NULL && structNameLen > 0 renseigne
 * le nom de type compose (struct/classe/builtin) sur le support choisi. */
static void record_declared_type(Token varName, int declaredType,
                                 bool isNullable, bool isUndetectable,
                                 const char* structName, int structNameLen) {
    if ((current->scopeDepth > 0 || g_last_declare_confined) && current->localCount > 0) {
        Local* lc = &current->locals[current->localCount - 1];
        lc->isNullable = isNullable;
        lc->isUndetectable = isUndetectable;
        lc->declaredType = declaredType;
        lc->structTypeName[0] = '\0';
        if (structName != NULL && structNameLen > 0) {
            int n = structNameLen < 63 ? structNameLen : 63;
            memcpy(lc->structTypeName, structName, (size_t)n);
            lc->structTypeName[n] = '\0';
        }
    } else if (current->scopeDepth == 0 && declaredType != TOKEN_EOF) {
        typed_globals_add(varName.start, varName.length,
                          declaredType, isNullable, isUndetectable);
        if (structName != NULL && structNameLen > 0) {
            typed_globals_set_struct_type(varName.start, varName.length,
                                          structName, structNameLen);
        }
    }
}

/*  — pose le type d'element user d'un `tableau de <TypeUser>` sur le
 * support de la variable JUSTE declaree (meme routage local/confine/global que
 * record_declared_type). A appeler APRES record_declared_type. Additif : ne
 * touche pas structTypeName, qui reste vide sur un tableau. */
static void record_array_elem_struct_type(Token varName,
                                          const char* elemName, int elemNameLen) {
    if (elemName == NULL || elemNameLen <= 0) return;
    if ((current->scopeDepth > 0 || g_last_declare_confined) && current->localCount > 0) {
        Local* lc = &current->locals[current->localCount - 1];
        int n = elemNameLen < 63 ? elemNameLen : 63;
        memcpy(lc->arrayElemStructType, elemName, (size_t)n);
        lc->arrayElemStructType[n] = '\0';
    } else if (current->scopeDepth == 0) {
        typed_globals_set_array_elem_struct(varName.start, varName.length,
                                            elemName, elemNameLen);
    }
}

/*  — pose l'opt-out unused (attribut <utile>/<useful>) sur le support
 * de la variable JUSTE declaree. Meme routage local/confine/global que
 * record_declared_type. A appeler APRES declare_variable. */
static void record_suppress_unused(Token varName) {
    if ((current->scopeDepth > 0 || g_last_declare_confined) && current->localCount > 0) {
        current->locals[current->localCount - 1].suppressUnused = true;
    } else if (current->scopeDepth == 0) {
        global_track_mark_suppress_unused(varName.start, varName.length);
    }
}

