/* Renvoie la table de propriétés correspondant au declaredType, ou NULL
 * si ce type n'expose pas de propriétés à dispatcher en strict.
 * NB : TOKEN_CHAINE n'a pas de propriétés runtime — uniquement des
 * méthodes (Taille, Gauche…) — donc absent de la liste. */
static const BuiltinKindProp* builtin_kind_props_for(int declaredType) {
    switch (declaredType) {
        case TOKEN_TABLEAU:   return PROPS_ARRAY;
        case TOKEN_FILE:
        case TOKEN_PILE:
        case TOKEN_LISTE:     return PROPS_COLLECTION;
        case TOKEN_JSON_KW:   return PROPS_JSON;
        case TOKEN_DATE:      return PROPS_DATE;
        case TOKEN_HEURE:     return PROPS_TIME;
        case TOKEN_DATEHEURE: return PROPS_DATETIME;
        case TOKEN_DUREE:     return PROPS_DURATION;
        default:              return NULL;
    }
}

/* Nom convivial pour les messages d'erreur — décliné du token de type. */
static const char* builtin_kind_name_for(int declaredType) {
    switch (declaredType) {
        case TOKEN_TABLEAU:   return "tableau";
        case TOKEN_FILE:      return "file";
        case TOKEN_PILE:      return "pile";
        case TOKEN_LISTE:     return "liste";
        case TOKEN_JSON_KW:   return "JSON";
        case TOKEN_DATE:      return "date";
        case TOKEN_HEURE:     return "heure";
        case TOKEN_DATEHEURE: return "dateheure";
        case TOKEN_DUREE:     return "dur\xc3\xa9" "e";   /* durée */
        default:              return "?";
    }
}

/*  — Composantes de CONSTRUCTION d'une durée littérale `{ }`.
 * STRICTEMENT les composantes lisibles fines (Jour/Heure/Minute/Seconde/
 * Milliseconde + alias EN), pondérées en millisecondes. EXCLUT les totaux
 * `En...` (EnSecondes = accesseur lecture, pas composante) et l'inexistant
 * Centième (grain le plus fin = ms). Symétrie lecture/écriture : on écrit
 * avec les noms qu'on lit (`d..Seconde` <=> `{ Seconde = ... }`).
 *
 * Match EXACT casse+accent-insensible (piège EnMillisecondes vs Milliseconde
 * — un préfixe-match laxe les confondrait). Renvoie le poids ms ou 0 si le
 * nom n'est pas une composante valide (le caller distingue via found). */
typedef struct {
    const char* canonAscii;   /* forme strip-accent lowercase à matcher */
    int64_t     weightMs;
} DureeComposante;
static const DureeComposante DUREE_COMPOSANTES[] = {
    {"jour",         86400000LL},
    {"day",          86400000LL},
    {"heure",         3600000LL},
    {"hour",          3600000LL},
    {"minute",          60000LL},
    {"seconde",          1000LL},
    {"second",           1000LL},
    {"milliseconde",        1LL},
    {"millisecond",         1LL},
    {0}
};

/* Renvoie le poids ms de la composante (via *out) si fieldName est une
 * composante de construction durée valide ; sinon false. */
static bool duree_composante_weight(const char* fieldName, int fieldLen,
                                    int64_t* out) {
    char norm[64];
    int nlen = scanner_strip_accents(fieldName, fieldLen, norm, (int)sizeof(norm));
    if (nlen <= 0) {
        nlen = fieldLen < (int)sizeof(norm) - 1 ? fieldLen : (int)sizeof(norm) - 1;
        memcpy(norm, fieldName, (size_t)nlen);
        norm[nlen] = '\0';
    }
    for (int i = 0; i < nlen; i++) {
        if (norm[i] >= 'A' && norm[i] <= 'Z') norm[i] = (char)(norm[i] - 'A' + 'a');
    }
    for (const DureeComposante* c = DUREE_COMPOSANTES; c->canonAscii; c++) {
        if ((int)strlen(c->canonAscii) == nlen
            && memcmp(c->canonAscii, norm, (size_t)nlen) == 0) {
            *out = c->weightMs;
            return true;
        }
    }
    return false;
}

/* Aggregat NULL-terminated de toutes les PROPS_* — utilise par les
 * consommateurs externes (formatter, self-test) qui ont besoin de matcher
 * un nom contre toutes les proprietes builtin sans connaitre le receveur. */
static const BuiltinKindProp* const ALL_BUILTIN_PROPS[] = {
    PROPS_ARRAY, PROPS_COLLECTION, PROPS_JSON,
    PROPS_DATE, PROPS_TIME, PROPS_DATETIME, PROPS_DURATION,
    NULL
};

/* Iteration index-based des proprietes builtin canoniques (date/heure/tableau/
 * JSON/duree...). Saute les alias de tolerance (descFR==NULL : variante ASCII
 * d'une forme accentuee, doublon kind) — meme filtre que compiler_iter_builtin_
 * props qui alimente OWL_BUILTIN_PROP_CATALOG. Le formatter matche dessus via
 * owl_name_matches : registre et catalogue iterent le meme ensemble canonique,
 * donc canonisent a l'identique (parite). */
int compiler_builtin_prop_count(void) {
    int n = 0;
    for (int i = 0; ALL_BUILTIN_PROPS[i] != NULL; i++)
        for (const BuiltinKindProp* p = ALL_BUILTIN_PROPS[i]; p->nameFR; p++)
            if (p->descFR) n++;
    return n;
}

bool compiler_builtin_prop_at(int idx, const char** outFR, const char** outEN) {
    int n = 0;
    for (int i = 0; ALL_BUILTIN_PROPS[i] != NULL; i++)
        for (const BuiltinKindProp* p = ALL_BUILTIN_PROPS[i]; p->nameFR; p++) {
            if (!p->descFR) continue;
            if (n == idx) {
                if (outFR) *outFR = p->nameFR;
                if (outEN) *outEN = p->nameEN;
                return true;
            }
            n++;
        }
    return false;
}

/* API publique : iterator pour LSP autocomplete / doc gen. Dedup par
 * nameFR sur l'ensemble des PROPS_*, et saute les entrees alias
 * (descFR == NULL). */
void compiler_iter_builtin_props(void (*cb)(const BuiltinKindProp* prop, void* ctx),
                                  void* ctx) {
    if (!cb) return;
    const char* seen[64];
    int seenCount = 0;
    for (int i = 0; ALL_BUILTIN_PROPS[i] != NULL; i++) {
        for (const BuiltinKindProp* p = ALL_BUILTIN_PROPS[i]; p->nameFR; p++) {
            if (!p->descFR) continue;  /* alias non expose */
            bool dup = false;
            for (int s = 0; s < seenCount; s++) {
                if (strcmp(seen[s], p->nameFR) == 0) { dup = true; break; }
            }
            if (dup) continue;
            if (seenCount < (int)(sizeof(seen)/sizeof(seen[0]))) {
                seen[seenCount++] = p->nameFR;
            }
            cb(p, ctx);
        }
    }
}

/* Liaison table → kind (FR canon utilisé en présentation user-facing). */
static const struct {
    const char* kindName;
    const BuiltinKindProp* table;
} PROPS_BY_KIND[] = {
    {"tableau",                          PROPS_ARRAY},
    {"file",                             PROPS_COLLECTION},
    {"pile",                             PROPS_COLLECTION},
    {"liste",                            PROPS_COLLECTION},
    {"JSON",                             PROPS_JSON},
    {"date",                             PROPS_DATE},
    {"heure",                            PROPS_TIME},
    {"dateheure",                        PROPS_DATETIME},
    {"dur\xc3\xa9" "e",                  PROPS_DURATION},  /* durée */
    {NULL, NULL}
};

void compiler_iter_builtin_props_full(
    void (*cb)(const char* kindName, const BuiltinKindProp* prop, void* ctx),
    void* ctx)
{
    if (!cb) return;
    for (int t = 0; PROPS_BY_KIND[t].kindName; t++) {
        const BuiltinKindProp* tab = PROPS_BY_KIND[t].table;
        for (const BuiltinKindProp* p = tab; p->nameFR; p++) {
            if (!p->descFR) continue;  /* alias non exposé */
            cb(PROPS_BY_KIND[t].kindName, p, ctx);
        }
    }
}

void compiler_iter_builtin_props_kinds(
    void (*cb)(const char* kindName, const char* propNameFR, void* ctx),
    void* ctx)
{
    if (!cb) return;
    for (int t = 0; PROPS_BY_KIND[t].kindName; t++) {
        for (const BuiltinKindProp* p = PROPS_BY_KIND[t].table; p->nameFR; p++) {
            /* Pas de skip sur descFR : builtin_kind_lookup_prop accepte les
             * alias, donc ils font bien partie de la surface du kind. */
            cb(PROPS_BY_KIND[t].kindName, p->nameFR, ctx);
        }
    }
}

/* Lookup d'une propriété builtin par nom (case + accent insensible via
 * strncasecmp octet par octet — pas de fold UTF-8). Retourne le nom canon
 * trouvé (pour les messages) ou NULL. */
static const BuiltinKindProp* builtin_kind_lookup_prop(const BuiltinKindProp* table,
                                                      const char* name, int nameLen) {
    if (!table) return NULL;
    for (const BuiltinKindProp* p = table; p->nameFR; p++) {
        int lFR = (int)strlen(p->nameFR);
        if (lFR == nameLen && strncasecmp(name, p->nameFR, (size_t)nameLen) == 0) {
            return p;
        }
        if (p->nameEN) {
            int lEN = (int)strlen(p->nameEN);
            if (lEN == nameLen && strncasecmp(name, p->nameEN, (size_t)nameLen) == 0) {
                return p;
            }
        }
    }
    return NULL;
}

/* ================================================================
 * Enum-constrained argument validation.
 *
 * When the callee is a registered native whose Nth param declares an
 * `allowedBase` enum, the compiler rejects a literal-identifier arg
 * that isn't a member. Variables / expressions / function calls pass
 * through unchecked (no runtime type system).
 * ================================================================ */

/* Emit a styled error attached to `tok`. */
static void enum_violation_error(Token tok, const char* argName, const OwlEnum* e) {
    /* Construit un echantillon de membres (max 5, suffixe ", ..." si plus)
     * cote appelant et injecte comme placeholder unique {sample} (cf.
     * design  "string pre-construite" pour listes dynamiques). */
    char sample[256];
    int off = 0;
    int shown = 0;
    /*  : les .values de l'enum ne portent que la forme FR canon
     *. Pour rester language-aware, on resout chaque valeur en
     * constante et on affiche sa forme EN canon si l'erreur est rendue en
     * EN (fallback = forme brute FR si pas de constante ou pas d'alias EN). */
    bool en = owl_error_render_lang_is_en();
    if (e->values) {
        for (const char* const* v = e->values;
                *v && off < (int)sizeof(sample) - 8 && shown < 5;
                v++, shown++) {
            const char* disp = *v;
            if (en) {
                const OwlConstDef* c = owl_registry_const_find(*v);
                if (c && c->nameEN) disp = c->nameEN;
            }
            off += snprintf(sample + off, sizeof(sample) - off, "%s%s",
                            shown == 0 ? "" : ", ", disp);
        }
        if (e->values[shown] != NULL) {
            off += snprintf(sample + off, sizeof(sample) - off, ", ...");
        }
    }
    sample[off < (int)sizeof(sample) ? off : (int)sizeof(sample) - 1] = '\0';
    owl_emit_error_at(&tok, E_SEM_ENUM_ARG_UNKNOWN,
                      "arg", argName,
                      "enumName", e->name,
                      "sample", sample,
                      NULL);
}

/* Validate the source span [start, end) against allowedBase/allowedOpts.
 * The span is the RHS of an assignment or a single call argument. We
 * tokenise manually at the source level to accept `a + b | c` style
 * combinations when allowedOpts is combinable. Errors are emitted via
 * error_at on the offending identifier. */
static void validate_enum_rhs(Token first, Token last,
                              const OwlEnum* allowedBase,
                              const OwlEnum* allowedOpts) {
    /*  : le garde nom-de-native/type doit tourner aussi
     * pour un param enum cable en allowedOptions-seul (allowedBase==NULL).
     * Fast-path uniquement si aucune contrainte enum n'est declaree. */
    if (!allowedBase && !allowedOpts) return;
    if (first.type != TOKEN_IDENTIFIER) return;

    Token idents[16];
    int identCount = 0;
    const char* p   = first.start;
    const char* end = last.start + last.length;
    if (end < p) return;
    while (p < end) {
        while (p < end && (*p == ' ' || *p == '\t' || *p == '\r' || *p == '\n')) p++;
        if (p >= end) break;
        if (*p == '+' || *p == '|') { p++; continue; }
        if (((*p) >= 'a' && (*p) <= 'z') || ((*p) >= 'A' && (*p) <= 'Z') ||
            (*p) == '_' || (unsigned char)(*p) >= 0x80) {
            const char* idStart = p;
            while (p < end && (((*p) >= 'a' && (*p) <= 'z') || ((*p) >= 'A' && (*p) <= 'Z') ||
                               ((*p) >= '0' && (*p) <= '9') || (*p) == '_' ||
                               (unsigned char)(*p) >= 0x80)) p++;
            if (identCount < 16) {
                Token t;
                t.start  = idStart;
                t.length = (int)(p - idStart);
                t.line   = first.line;
                t.type   = TOKEN_IDENTIFIER;
                t.column = 0;
                idents[identCount++] = t;
            }
            continue;
        }
        return;  /* unknown char — abort validation */
    }

    bool sawBase = false;
    bool sawOpt  = false;
    for (int i = 0; i < identCount; i++) {
        char argName[128];
        int alen = idents[i].length < 127 ? idents[i].length : 127;
        memcpy(argName, idents[i].start, alen);
        argName[alen] = '\0';

        /*  : resolution bilingue — une constante passee sous son nom EN
         * doit etre reconnue (sinon la contrainte enum n'est jamais verifiee
         * pour un membre EN, ou pour un nom EN hors enum). */
        if (owl_registry_const_find_bilingual(argName) == NULL) {
            /*  : pas une constante. Distinguer une variable (skip
             * legitime — elle peut porter la valeur d'enum au runtime, non
             * validable au compile) d'un nom de native/fonction ou de type
             * mal employe comme membre d'enum (ex: fFileName == nom EN de
             * fNomFichier, glisse a la place d'un membre de fExtraitPartie).
             * Un symbole registry connu qui n'est pas une constante ne peut
             * pas etre un membre d'enum valide → violation. */
            if (owl_registry_find(argName) != NULL ||
                owl_registry_type_find(argName) != NULL) {
                enum_violation_error(idents[i], argName,
                                     allowedBase ? allowedBase : allowedOpts);
                return;
            }
            continue;
        }

        bool inBase = owl_enum_contains_bilingual(allowedBase, argName);
        bool inOpts = owl_enum_contains_bilingual(allowedOpts, argName);
        bool baseCombinable = allowedBase && allowedBase->combinable;
        bool optsCombinable = allowedOpts && allowedOpts->combinable;
        if (inBase) {
            /* Multiple base members are only OK if the base is itself
             * combinable (bitmask enum) or if the options enum is
             * combinable and we're mixing freely. */
            if (sawBase && !baseCombinable && !optsCombinable) {
                enum_violation_error(idents[i], argName,
                                     allowedBase ? allowedBase : allowedOpts);
                return;
            }
            sawBase = true;
            continue;
        }
        if (inOpts) {
            /*  : quand allowedBase==NULL, allowedOptions joue le role de
             * base. Un membre UNIQUE d'allowedOptions est donc toujours accepte,
             * combinable ou non (ex: dEffacer sur E_dessinOptions non-combinable).
             * Seule la COMBINAISON de plusieurs membres options est gatee sur
             * combinable — symetrie avec sawBase pour allowedBase. */
            if (sawOpt && !optsCombinable) {
                enum_violation_error(idents[i], argName,
                                     allowedBase ? allowedBase : allowedOpts);
                return;
            }
            sawOpt = true;
            continue;
        }
        enum_violation_error(idents[i], argName,
                             allowedBase ? allowedBase : allowedOpts);
        return;
    }
}

/* Parse a single argument with enum checking. The `cp` (current param)
 * may be NULL or may have allowedBase/allowedOptions; if set and the
 * argument is a plain identifier (possibly combined via `+`/`|` if
 * allowedOptions is a combinable enum), we validate each operand.
 *
 * Pour les enums combinables (bitmask), un littéral entier passé directement
 * (ex: `iImprimeZone(..., 1)`) est techniquement valide numériquement (1 ==
 * iGauche par exemple) mais quasi toujours un BUG : l'utilisateur a écrit
 * une valeur magique au lieu d'utiliser la constante nommée. On émet un
 * warning compile-time pour pousser à utiliser les noms. */
/*  ( §1) — un type de paramètre déclaré `chaine` (forme
 * accentuée ou non, casse-insensible). Sert à décider si un littéral `{…}`
 * passé en argument doit être aplati à la langue active. */
static bool param_type_is_chaine(const char* t) {
    if (t == NULL || t[0] == '\0') return false;
    char ascii[64];
    int n = scanner_strip_accents(t, (int)strlen(t), ascii, sizeof(ascii));
    if (n <= 0 || n >= (int)sizeof(ascii)) return false;
    ascii[n] = '\0';
    return strcasecmp(ascii, "chaine") == 0;
}

/*  ( §1) — littéral colon-brace `{langueXxx: …}` passé à un
 * paramètre typé texte au site d'appel. Le type du paramètre pilote la
 * construction (typage par contexte cible, pas d'inférence) :
 *   - param `chaîneMultilingue` : le littéral reste multilingue (rétention).
 *   - param `chaine`            : construit puis aplati à la langue active via
 *     __BufferVersChaine (snapshot figé au passage d'argument).
 * Retourne true si l'argument a été entièrement compilé (le caller ne doit
 * PAS ré-émettre l'expression) ; false si paramType n'est pas texte ou si
 * l'argument n'est pas un `{…}` (le caller compile normalement). */
static bool compile_brace_arg_for_text_param(const char* paramType) {
    if (paramType == NULL || !check(TOKEN_LEFT_BRACE)) return false;
    bool paramMulti  = struct_name_is_multilingue(paramType);
    bool paramChaine = param_type_is_chaine(paramType);
    if (!paramMulti && !paramChaine) return false;

    g_inline_target_type     = "cha\xc3\xae" "neMultilingue";
    g_inline_target_type_len = (int)strlen("cha\xc3\xae" "neMultilingue");
    if (paramChaine) {
        /* Aplatit AVANT l'appel : __BufferVersChaine passe-through sur une
         * chaine, résout une multilingue à la langue active (value_to_string).
         * Stack : [__BufferVersChaine, multilingue] -> CALL 1 -> [chaine]. */
        Token fnTok;
        fnTok.start  = "__BufferVersChaine";
        fnTok.length = 18;
        ConstIdx c = identifier_constant(&fnTok);
        emit_const_op(OP_GET_GLOBAL, c);
        condition_expression();
        emit_bytes(OP_CALL, 1);
    } else {
        condition_expression();
    }
    return true;
}

/*  ( §1) — variante de argument_list() pour un appel de
 * native ou procédure dont on connaît les params déclarés (`params`, tableau
 * terminé par une entrée .name == NULL). Neutre par rapport à argument_list()
 * sauf pour un argument `{…}` dont le paramètre correspondant PAR POSITION est
 * typé texte : câble le contexte cible via compile_brace_arg_for_text_param
 * (symétrique de argument_list_with_method_sig côté méthode). Tout autre
 * argument passe par condition_expression() à l'identique. Un argument au-delà
 * du dernier param déclaré (variadique / optionnel) reçoit pt = NULL et se
 * compile normalement — pas d'indexation hors bornes. `params` == NULL est
 * strictement équivalent à argument_list(). */
static uint8_t argument_list_with_params(const OwlParam* params) {
    uint8_t argCount = 0;
    if (!check(TOKEN_RIGHT_PAREN)) {
        do {
            const char* pt = NULL;
            if (params) {
                int idx = 0;
                for (const OwlParam* p = params; p->name; p++, idx++) {
                    if (idx == argCount) {
                        pt = (p->type && p->type[0] != '\0') ? p->type : NULL;
                        break;
                    }
                }
            }
            if (!(pt && compile_brace_arg_for_text_param(pt))) {
                condition_expression();
            }
            if (argCount == 255) {
                owl_emit_error_at(&parser.previous, E_SYNTAX_CALL_TOO_MANY_ARGS);
            }
            argCount++;
        } while (match_token(TOKEN_COMMA));
    }
    consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_ARGS);
    return argCount;
}

/*  ( §1) — variante de argument_list() pour un appel de
 * méthode dont on connaît la signature déclarée (paramTypes). Neutre par
 * rapport à argument_list() sauf pour un argument `{…}` dont le paramètre
 * correspondant est typé texte : dans ce cas seul on câble le contexte cible
 * (cf. compile_brace_arg_for_text_param). Tout autre argument passe par
 * condition_expression() à l'identique. */
static uint8_t argument_list_with_method_sig(const DeclaredMethodSigEntry* sig) {
    uint8_t argCount = 0;
    if (!check(TOKEN_RIGHT_PAREN)) {
        do {
            const char* pt = (sig && argCount < sig->paramCount &&
                              sig->paramTypes[argCount][0] != '\0')
                             ? sig->paramTypes[argCount] : NULL;
            if (!(pt && compile_brace_arg_for_text_param(pt))) {
                condition_expression();
            }
            if (argCount == 255) {
                owl_emit_error_at(&parser.previous, E_SYNTAX_CALL_TOO_MANY_ARGS);
            }
            argCount++;
        } while (match_token(TOKEN_COMMA));
    }
    consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_ARGS);
    return argCount;
}

/*  — resout un symbole d'action AWS `aws<Service><Action>` en son nom
 * d'action canonique. Retourne le nom (pointeur dans AWS_SERVICES) ou NULL si
 * non resolu. `ident` est NUL-termine. */
static const char* aws_resolve_action_symbol(const char* ident) {
    if (strncmp(ident, "aws", 3) != 0) return NULL;
    const char* rest = ident + 3;
    for (int i = 0; i < AWS_SERVICE_COUNT; i++) {
        const AwsService* svc = &AWS_SERVICES[i];
        const char* sym = svc->symbolName;
        size_t sl = sym ? strlen(sym) : 0;
        if (sl == 0) continue;
        if (strncmp(rest, sym, sl) == 0) {
            const char* actionPart = rest + sl;
            for (int a = 0; a < svc->actionCount; a++) {
                if (strcmp(svc->actions[a].actionName, actionPart) == 0)
                    return svc->actions[a].actionName;
            }
        }
    }
    return NULL;
}

/* Echantillon de symboles d'action valides (max 5) pour le message d'erreur. */
static void aws_action_sample(char* out, size_t cap) {
    size_t off = 0;
    int shown = 0;
    for (int i = 0; i < AWS_SERVICE_COUNT && shown < 5; i++) {
        const AwsService* svc = &AWS_SERVICES[i];
        for (int a = 0; a < svc->actionCount && shown < 5; a++) {
            if (off < cap)
                off += (size_t)snprintf(out + off, cap - off, "%saws%s%s",
                                        shown == 0 ? "" : ", ",
                                        svc->symbolName, svc->actions[a].actionName);
            shown++;
        }
    }
    if (off >= cap) out[cap - 1] = '\0';
}

static void argument_with_enum_check(const OwlParam* cp) {
    Token first = parser.current;

    /*  — position d'action AWS : un identifiant NU prefixe "aws" est
     * resolu en son nom d'action (litteral chaine) ; un symbole "aws"-prefixe
     * introuvable est une erreur ; tout le reste (chaine, variable) reste une
     * expression normale. */
    if (cp && cp->awsAction && first.type == TOKEN_IDENTIFIER &&
        first.length > 3 && strncmp(first.start, "aws", 3) == 0) {
        Scanner peek = parser.scanner;
        Token nxt = scanner_scan_token(&peek);
        while (nxt.type == TOKEN_NEWLINE || nxt.type == TOKEN_SEMICOLON)
            nxt = scanner_scan_token(&peek);
        if (nxt.type == TOKEN_COMMA || nxt.type == TOKEN_RIGHT_PAREN) {
            char ident[128];
            int n = first.length < 127 ? first.length : 127;
            memcpy(ident, first.start, (size_t)n);
            ident[n] = '\0';
            const char* action = aws_resolve_action_symbol(ident);
            advance_token();  /* consomme l'identifiant */
            if (action != NULL) {
                emit_constant(OBJ_VAL(obj_copy_string(action, (int)strlen(action))));
            } else {
                char sample[256];
                aws_action_sample(sample, sizeof sample);
                owl_emit_error_at(&first, E_SEM_AWS_ACTION_UNKNOWN,
                                  "arg", ident, "sample", sample, NULL);
                emit_constant(OBJ_VAL(obj_copy_string("", 0)));  /* neutre : pas de cascade */
            }
            return;
        }
    }

    const OwlEnum* allowedBase = cp ? cp->allowedBase    : NULL;
    const OwlEnum* allowedOpts = cp ? cp->allowedOptions : NULL;

    /*  ( §1) — littéral `{…}` vers un param typé texte
     * (chaine / chaîneMultilingue) : construit selon le type déclaré du param
     * puis aplati si `chaine`. Prioritaire sur le bloc composite ci-dessous
     * (un type texte n'est jamais un template ObjInstance). */
    if (cp && compile_brace_arg_for_text_param(cp->type)) return;

    /* V1.5-B : si l'arg est un brace literal `{ ... }` ET que le type du
     * param est un type composé connu (template ObjInstance dans
     * vm.globals), set g_inline_target_type pour que instance_literal
     * connaisse le type cible. Permet `f({ Couleur = X })`. */
    if (cp && cp->type && first.type == TOKEN_LEFT_BRACE) {
        ObjString* tk = obj_copy_string(cp->type, (int)strlen(cp->type));
        vm_push(OBJ_VAL(tk));
        Value v;
        bool ft = table_get(&vm.types, tk, &v);  /*  Phase 1 : types builtins en vm.types. */
        if (!ft) ft = table_get(&vm.globals, tk, &v);
        vm_pop();
        if (ft && IS_INSTANCE(v)) {
            g_inline_target_type     = cp->type;
            g_inline_target_type_len = (int)strlen(cp->type);
        }
    }

    /* If no enum constraint at all, fast path.  : le check
     * nom-de-native/type doit aussi tourner pour un param allowedOptions-seul,
     * donc on ne fast-path que si les DEUX contraintes sont absentes. */
    if (!allowedBase && !allowedOpts) { condition_expression(); return; }

    /* Warning : littéral numérique direct sur un param enum. Quasi toujours
     * un bug de magie d'entier (ex : passer `1` pour "centre" alors que
     * `1` = `iGauche` dans le bitmask iAlign). Pousse à nommer.
     *  : réservé aux params allowedBase (validation stricte). Les
     * params allowedOptions-seul sont soft (défaut 0, littéraux admis) : on
     * n'étend PAS ce warning à eux. */
    if (allowedBase && (first.type == TOKEN_INTEGER || first.type == TOKEN_REAL)) {
        char first_name[64] = "?";
        if (allowedBase->values && allowedBase->values[0]) {
            /*  : values[0] ne porte que la forme FR canon.
             * En rendu EN, resoudre la constante et afficher sa forme EN canon
             * (fallback = forme brute FR si pas de constante ou pas d'alias EN). */
            const char* disp = allowedBase->values[0];
            if (owl_error_render_lang_is_en()) {
                const OwlConstDef* c = owl_registry_const_find(allowedBase->values[0]);
                if (c && c->nameEN) disp = c->nameEN;
            }
            int n = (int)strlen(disp);
            if (n >= (int)sizeof(first_name)) n = sizeof(first_name) - 1;
            memcpy(first_name, disp, n);
            first_name[n] = '\0';
        }
        owl_emit_warning_at(&first, W_SEM_ENUM_LITERAL_NUMERIC,
                            "enumName", allowedBase->name,
                            "example", first_name,
                            NULL);
    }

    /* Only try statically if the arg starts with an IDENTIFIER. */
    if (first.type != TOKEN_IDENTIFIER) { condition_expression(); return; }

    condition_expression();
    validate_enum_rhs(first, parser.previous, allowedBase, allowedOpts);
}

/* Compile-time arity check for a native call.
 * If the registered native has signatures and NONE of them match argCount
 * (where sig.arity == -1 means variadic / always matches), emit a compile
 * error with the list of accepted arities. */
/*  — coeur de la validation d'arité, partagé par le chemin natif
 * (`Foo(args)`) et le chemin méthode/chaîné (`recv.Foo(args)`).
 *   matchArgCount   : nb d'args pour le MATCHING (méthode : +1 receveur implicite)
 *   displayArgCount : nb d'args montré à l'utilisateur (méthode : explicites)
 *   isMethod        : forme chaînée → les arités affichées retirent le receveur
 *   errTok          : token à pointer (callee natif ou nom de méthode) */
static void check_call_arity_ex(const OwlNativeDef* def, int matchArgCount,
                                int displayArgCount, const Token* errTok,
                                bool isMethod) {
    if (!def || !def->signatures) return; /* no registry info: skip */
    const OwlSignature* sigs = def->signatures;
    int recvOffset = isMethod ? 1 : 0;
    /* Collect accepted arities; if any is -1 or equal to matchArgCount, OK. */
    int matched = 0;
    int arities[8]; int arityCount = 0;
    for (const OwlSignature* s = sigs; s->returnType != NULL; s++) {
        if (s->arity == -1) { matched = 1; break; }
        if (arityCount < 8) arities[arityCount++] = s->arity;
        if (s->arity == matchArgCount) { matched = 1; break; }
    }
    if (matched || arityCount == 0) return;

    /* Build readable list of expected arities (côté utilisateur : on retire
     * le receveur implicite pour la forme méthode). */
    char expected[128];
    int off = 0;
    int shown = 0;
    for (int i = 0; i < arityCount; i++) {
        int a = arities[i] - recvOffset;
        if (a < 0) continue; /* sig dont l'arité < receveur : non pertinente ici */
        off += snprintf(expected + off, sizeof(expected) - off,
                        "%s%d", shown == 0 ? "" : " ou ", a);
        shown++;
        if ((size_t)off >= sizeof(expected) - 8) break;
    }
    char name[128] = "";
    if (errTok && errTok->length > 0 && errTok->length < 127) {
        memcpy(name, errTok->start, (size_t)errTok->length);
        name[errTok->length] = '\0';
    }
    char argBuf[16];
    snprintf(argBuf, sizeof(argBuf), "%d", displayArgCount);

    /*  — message dédié pour ChaîneVersDurée 1-arg (chemin natif). */
    if (!isMethod && def->canonical &&
        strcmp(def->canonical, "Cha\xc3\xae" "neVersDur\xc3\xa9" "e") == 0 &&
        displayArgCount == 1) {
        owl_emit_error_at(&parser.previous,
                          E_SEM_CHAINE_VERS_DUREE_NEEDS_FORMAT,
                          NULL);
        return;
    }

    const char* dispName = name[0] ? name : (def->canonical ? def->canonical : "?");
    /* Multi-syntaxes (formes discrètes) OU forme méthode : message
     * "Aucune syntaxe de X ne correspond". Mono-syntaxe natif : message
     * "attend N argument(s)" historique. */
    if (arityCount > 1 || isMethod) {
        owl_emit_error_at(&parser.previous, E_SEM_NO_MATCHING_SYNTAX,
                          "name", dispName,
                          "expected", expected,
                          "got", argBuf,
                          NULL);
    } else {
        owl_emit_error_at(&parser.previous, E_SEM_CALL_BAD_ARITY,
                          "name", dispName,
                          "expected", expected,
                          "got", argBuf,
                          NULL);
    }
}

static void check_call_arity(const OwlNativeDef* def, int argCount,
                              const Token* callee) {
    check_call_arity_ex(def, argCount, argCount, callee, false);
}

/*  — mappe un token de type builtin déclaré vers le MethodReceiverType
 * runtime (pour résoudre les méthodes d'extension `recv.M()` à la compilation).
 * Retourne -1 si le type n'a pas de table de méthodes builtin. */
static int builtin_token_to_method_type(int tok) {
    switch (tok) {
        case TOKEN_TABLEAU:   return METHOD_TYPE_ARRAY;
        case TOKEN_CHAINE:    return METHOD_TYPE_STRING;
        case TOKEN_ENTIER:    return METHOD_TYPE_INTEGER;
        case TOKEN_REEL:      return METHOD_TYPE_REAL;
        case TOKEN_DATE:      return METHOD_TYPE_DATE;
        case TOKEN_HEURE:     return METHOD_TYPE_TIME;
        case TOKEN_DATEHEURE: return METHOD_TYPE_DATETIME;
        case TOKEN_DUREE:     return METHOD_TYPE_DURATION;
        case TOKEN_JSON_KW:   return METHOD_TYPE_JSON;
        case TOKEN_FILE:      return METHOD_TYPE_COLLECTION_QUEUE;
        case TOKEN_PILE:      return METHOD_TYPE_COLLECTION_STACK;
        case TOKEN_LISTE:     return METHOD_TYPE_COLLECTION_LIST;
        default:              return -1;
    }
}

/*  — valide l'arité d'un appel de méthode chaînée `recv.Methode(args)`
 * contre les signatures de la native sous-jacente. Conservateur : ne valide
 * QUE si le type du receveur est résolu en builtin AND la méthode résout vers
 * une native du registre. Sinon (type inconnu, méthode user/classe, native non
 * migrée variadique -1) → aucun effet. `explicitArgs` = args entre () (le
 * receveur est implicite et compté en plus). */
static void check_method_call_arity(int receiverTypeToken, const Token* methodTok,
                                    int explicitArgs) {
    if (!methodTok || methodTok->length <= 0) return;
    int mrt = builtin_token_to_method_type(receiverTypeToken);
    if (mrt < 0) return;
    int arity = 0;
    NativeFn fn = method_lookup((MethodReceiverType)mrt,
                                methodTok->start, methodTok->length, &arity);
    if (!fn) return;
    const OwlNativeDef* def = owl_registry_find_by_fn(fn);
    if (!def) return;
    /* matching avec le receveur implicite (+1), affichage sans. */
    check_call_arity_ex(def, explicitArgs + 1, explicitArgs, methodTok, true);
}

/*  — la native est-elle de la famille Enumération* dont le 1er
 * argument est un type d'énumération passé NU (EnumérationDepuisValeur, etc.) ?
 * Ces appels reçoivent en 1er argument l'ObjClass de l'énumération lu via
 * OP_GET_GLOBAL, d'où la relaxation ciblée de la garde enum-nu. */
static bool is_enum_manip_native(const OwlNativeDef* def) {
    const char* a = def ? def->canonicalAscii : NULL;
    if (a == NULL) return false;
    return strcmp(a, "EnumerationDepuisValeur") == 0
        || strcmp(a, "EnumerationDepuisNom") == 0
        || strcmp(a, "EnumerationVerifieValeur") == 0
        || strcmp(a, "EnumerationVerifieNom") == 0;
}

/*  — nom de type OWL d'un littéral direct, pour valider le type des
 * paramètres passés à DéclencheÉvénement. NULL = pas un littéral scalaire
 * direct (variable, expression) : type inconnu au compile -> pas de check. */
static const char* evt_literal_type_name(TokenType t) {
    switch (t) {
        case TOKEN_INTEGER:       return "entier";
        case TOKEN_REAL:          return "r\xc3\xa9""el";
        case TOKEN_STRING:        return "cha\xc3\xae""ne";
        case TOKEN_STRING_INTERP: return "cha\xc3\xae""ne";
        case TOKEN_VRAI:
        case TOKEN_FAUX:          return "bool\xc3\xa9""en";
        default:                  return NULL;
    }
}

/* Compare deux noms de type OWL, accent+casse insensibles. */
static bool evt_type_matches(const char* got, const char* expected) {
    if (!got || !expected) return true;
    char a[64], b[64];
    int la = scanner_strip_accents(got, (int)strlen(got), a, (int)sizeof(a));
    int lb = scanner_strip_accents(expected, (int)strlen(expected), b, (int)sizeof(b));
    if (la <= 0 || lb <= 0) return true;
    return strcasecmp(a, b) == 0;
}

/*  — valide + compile DéclencheÉvénement / TriggerEvent.
 *
 * Le '(' est déjà consommé (call() est l'infix parselet). On parse les args
 * à la main pour capturer la cible (arg0), l'événement (arg1) et les params
 * (arg2+), puis on émet OP_CALL comme un appel normal. 3 validations :
 *   1. cible objet (identifiant nu) ou chaîne littérale non résoluble -> erreur.
 *   2. événement non possédé par le widget cible (kind connu) -> erreur.
 *   3. arité + type des params contre la signature portée par la constante.
 * Une chaîne variable / expression comme cible est une indirection : les
 * checks 1-2 basculent au runtime, le check 3 (piloté par la constante) reste
 * fait au compile. Chaque erreur émise laisse le parse continuer (pas de
 * cascade syntaxique). */
static void compile_declenche_evenement(const Token* callee) {
    bool                       targetKnown = false;
    OwlControlKind             targetKind  = OWL_CONTROL_LABEL;
    const OwlControlKindInfo*  targetInfo  = NULL;
    char targetName[128]; targetName[0] = '\0';

    const OwlEventDef* ev = NULL;
    char evtName[96]; evtName[0] = '\0';

    TokenType argLeadType[16];
    int       argLeadCount = 0;

    uint8_t argCount = 0;
    if (!check(TOKEN_RIGHT_PAREN)) {
        do {
            Token lead = parser.current;
            if (argLeadCount < 16) argLeadType[argLeadCount++] = lead.type;

            condition_expression();

            /* Identifiant nu = un seul token consommé, dont le start coïncide. */
            bool bareIdent = (lead.type == TOKEN_IDENTIFIER &&
                              parser.previous.start == lead.start);

            if (argCount == 0) {
                /* ---- Cible ---- */
                if (bareIdent) {
                    int n = lead.length < 127 ? lead.length : 127;
                    memcpy(targetName, lead.start, (size_t)n);
                    targetName[n] = '\0';
                    targetInfo = compiler_prescan_widget_find(targetName);
                    if (targetInfo &&
                        owl_control_kind_of_info(targetInfo, &targetKind)) {
                        targetKnown = true;
                    } else {
                        owl_emit_error_at(&lead, E_SEM_EVT_TARGET_UNKNOWN,
                                          "name", targetName, NULL);
                    }
                } else if (lead.type == TOKEN_STRING) {
                    int inner = lead.length >= 2 ? lead.length - 2 : 0;
                    if (inner > 127) inner = 127;
                    memcpy(targetName, lead.start + 1, (size_t)inner);
                    targetName[inner] = '\0';
                    targetInfo = compiler_prescan_widget_find(targetName);
                    if (targetInfo &&
                        owl_control_kind_of_info(targetInfo, &targetKind)) {
                        targetKnown = true;
                    } else {
                        owl_emit_error_at(&lead, E_SEM_EVT_TARGET_STRING_UNKNOWN,
                                          "name", targetName, NULL);
                    }
                }
                /* else : indirection dynamique -> checks cible/appartenance
                 * reportés au runtime. */
            } else if (argCount == 1) {
                /* ---- Événement ---- */
                if (bareIdent) {
                    int n = lead.length < 95 ? lead.length : 95;
                    memcpy(evtName, lead.start, (size_t)n);
                    evtName[n] = '\0';
                    const OwlConstDef* c = owl_registry_const_find_bilingual(evtName);
                    if (c && IS_INTEGER(c->value)) {
                        int idx = (int)(AS_INTEGER(c->value) - (int64_t)OWL_EVT_BASE);
                        ev = owl_widget_event_dedup_at(idx);
                    }
                }
                if (ev == NULL) {
                    owl_emit_error_at(&lead, E_SEM_EVT_NOT_A_CONST,
                                      "name", evtName[0] ? evtName : "?", NULL);
                } else if (targetKnown &&
                           owl_event_catalog_find(targetKind, ev->canonical) == NULL) {
                    owl_emit_error_at(&lead, E_SEM_EVT_NOT_OWNED,
                                      "evt", evtName,
                                      "target", targetName,
                                      "kind", targetInfo ? targetInfo->nameFR : "?",
                                      NULL);
                }
            }

            if (argCount == 255) {
                owl_emit_error_at(&parser.previous, E_SYNTAX_CALL_TOO_MANY_ARGS);
            }
            argCount++;
        } while (match_token(TOKEN_COMMA));
    }
    consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_ARGS);

    /* ---- Événement manquant (moins de 2 args) ---- */
    if (argCount < 2) {
        owl_emit_error_at(callee, E_SEM_EVT_NOT_A_CONST,
                          "name", evtName[0] ? evtName : "?", NULL);
    }

    /* ---- Params : arité + type contre la signature de la constante ---- */
    if (ev != NULL && argCount >= 2) {
        int provided = (int)argCount - 2;
        int expected = ev->paramCount;
        if (provided != expected) {
            char eb[16], gb[16];
            snprintf(eb, sizeof(eb), "%d", expected);
            snprintf(gb, sizeof(gb), "%d", provided);
            owl_emit_error_at(callee, E_SEM_EVT_PARAM_ARITY,
                              "evt", evtName, "expected", eb, "got", gb, NULL);
        }
        int nchk = provided < expected ? provided : expected;
        for (int i = 0; i < nchk; i++) {
            int li = 2 + i;                 /* argLeadType : 0=cible, 1=evt */
            if (li >= argLeadCount) break;
            const char* got = evt_literal_type_name(argLeadType[li]);
            if (got == NULL) continue;      /* non-littéral : type inconnu */
            const char* expType = ev->params[i].typeName;
            if (!evt_type_matches(got, expType)) {
                char pos[16];
                snprintf(pos, sizeof(pos), "%d", i + 1);
                owl_emit_error_at(callee, E_SEM_EVT_PARAM_TYPE,
                                  "evt", evtName, "position", pos,
                                  "expected", expType, "got", got, NULL);
            }
        }
    }

    emit_bytes(OP_CALL, argCount);
}

static void call(bool canAssign) {
    (void)canAssign;

    /* Try to resolve the callee to a registered native so we can check
     * enum-constrained params. Snapshot first — parser.current changes
     * as we descend. */
    Token callee = g_last_var_token;

    /* Après le retour d'une fonction/méthode, le receveur effectif du
     * prochain `.X` est la valeur de retour (type inconnu côté compileur).
     * On marque g_chain_broken pour empêcher le strict dot check
     * de retomber par erreur sur le receiver original.
     * Exemple cassant : `m.Quand().Retourne(rep).Active()` où rep est
     * un httpRéponse — sans ce flag, `.Active()` se résout comme champ
     * de httpRéponse au lieu du résultat de Retourne (un MockNative).
     * Symétrique au flag posé dans subscript().
     * Note : on set le flag à la FIN de l'appel (après tous les args
     * compilés) sinon les args eux-mêmes hériteraient du chain_broken. */
    const OwlNativeDef* def = NULL;
    if (callee.length > 0 && callee.length < 128) {
        char fnName[128];
        memcpy(fnName, callee.start, (size_t)callee.length);
        fnName[callee.length] = '\0';
        def = owl_registry_find(fnName);
    }

    /*  — verrou compile-time : Ouvre / OuvreFille / OuvreSoeur sont
     * interdits dans le code d'execution d'un Etat (top-level body,
     * PROCEDUREs Lecture/Filtre/Fermeture/helpers, blocs Corps/EnTete*/
    /*BasDePage/...). Un Etat est un generateur de rapport, pas d'event
     * loop UI. La detection passe par def->canonical : ca couvre alias
     * accentues / casse-insensible / nameEN via le registry. */
    if (def && def->canonical && g_in_etat_scope_depth > 0) {
        const char* c = def->canonical;
        if (strcmp(c, "Ouvre") == 0 ||
            strcmp(c, "OuvreFille") == 0 ||
            strcmp(c, "OuvreSoeur") == 0) {
            owl_emit_error_at(&callee, E_SEM_OUVRE_FORBIDDEN_IN_ETAT,
                              "name", c,
                              NULL);
            /* On ne return PAS — laisser le call continuer le parse pour
             * eviter une cascade d'erreurs syntaxiques sur les args. */
        }
    }

    /*  — famille Enumération* : le 1er argument est un type
     * d'énumération NU (l'ObjClass est lu via OP_GET_GLOBAL). On relâche la
     * garde enum-nu le temps de ce seul argument, puis on compile
     * la suite normalement. Chemin dédié : aucune de ces natives n'a de
     * param composé/enum-contraint ni d'out-param, donc pas besoin du slow
     * path générique. */
    if (is_enum_manip_native(def)) {
        uint8_t argCount = 0;
        if (!check(TOKEN_RIGHT_PAREN)) {
            do {
                g_allow_bare_enum_type_arg = (argCount == 0);
                condition_expression();
                g_allow_bare_enum_type_arg = false;
                if (argCount == 255) {
                    owl_emit_error_at(&parser.previous, E_SYNTAX_CALL_TOO_MANY_ARGS);
                }
                argCount++;
            } while (match_token(TOKEN_COMMA));
        }
        consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_ARGS);
        check_call_arity(def, argCount, &callee);
        emit_bytes(OP_CALL, argCount);
        return;
    }

    /*  — DéclencheÉvénement / TriggerEvent : chemin dédié qui valide
     * la cible, l'appartenance de l'événement au widget et l'arité/type des
     * params contre la signature portée par la constante evt*. */
    if (def && def->canonicalAscii &&
        strcmp(def->canonicalAscii, "DeclencheEvenement") == 0) {
        compile_declenche_evenement(&callee);
        return;
    }

    const OwlParam* params = NULL;
    if (def && def->signatures && def->signatures[0].returnType != NULL) {
        params = def->signatures[0].params;
    }

    /* V1.7-1 : si pas de native trouvee, lookup dans la table des
     * PROCEDURE user-defined. Si trouvee avec un param composé, on
     * synthetise un OwlParam[] pour passer au slow path. */
    static OwlParam syntheticParams[MAX_USER_PROC_PARAMS + 1];
    UserProcInfo* userProc = NULL;
    if (!def && callee.length > 0) {
        userProc = user_proc_find(callee.start, callee.length);
        if (userProc && userProc->paramCount > 0) {
            for (int pi = 0; pi < userProc->paramCount; pi++) {
                syntheticParams[pi].name = "p";  /* placeholder */
                syntheticParams[pi].type = userProc->paramTypes[pi][0]
                                            ? userProc->paramTypes[pi] : NULL;
                syntheticParams[pi].desc = "";
                syntheticParams[pi].allowedBase = NULL;
                syntheticParams[pi].allowedOptions = NULL;
            }
            syntheticParams[userProc->paramCount].name = NULL;
            params = syntheticParams;
        }
    }

    /* Count how many params have an allowedBase OU un type composé
     * (V1.5-B : pour permettre `f({ ... })`), pour decider si le slow
     * path est necessaire. */
    bool hasEnumParam = false;
    if (params) {
        for (const OwlParam* p = params; p->name; p++) {
            /*  : un param enum câblé en allowedOptions-seul doit aussi
             * déclencher le slow path pour que le garde nom-de-native/type
             * tourne. */
            if (p->allowedBase || p->allowedOptions) { hasEnumParam = true; break; }
            if (p->awsAction) { hasEnumParam = true; break; }  /*  */
            /* V1.5-B : type composé (ObjInstance template dans vm.globals). */
            if (p->type) {
                ObjString* tk = obj_copy_string(p->type, (int)strlen(p->type));
                vm_push(OBJ_VAL(tk));
                Value v;
                bool ft = table_get(&vm.types, tk, &v);  /*  Phase 1. */
                if (!ft) ft = table_get(&vm.globals, tk, &v);
                vm_pop();
                if (ft && IS_INSTANCE(v)) {
                    hasEnumParam = true; break;
                }
            }
        }
    }

    /*  ( §1) — 1er argument littéral `{…}` vers un paramètre
     * typé texte : force le slow path pour câbler g_inline_target_type depuis
     * le type du paramètre avant de parser l'argument. Un `{…}` vers un param
     * non-texte reste refusé (BRACE_LITERAL_NO_TYPE), donc aucun appel vert
     * existant ne bascule (le cas erre aujourd'hui). */
    if (!hasEnumParam && params && check(TOKEN_LEFT_BRACE)) {
        for (const OwlParam* p = params; p->name; p++) {
            if (p->type && (param_type_is_chaine(p->type) ||
                            struct_name_is_multilingue(p->type))) {
                hasEnumParam = true;
                break;
            }
        }
    }

    /* Out-params variadic (cf VISION §5bis) — slow path obligatoire
     * pour valider lvalue + capturer le slot/nameConst de chaque
     * out-param avant de pouvoir émettre les writebacks après l'OP_CALL. */
    bool hasOutParams = def && (def->flags & OWL_NAT_OUT_PARAMS) &&
                        def->firstOutParamArg >= 0;

    if (!hasEnumParam && !hasOutParams) {
        /*  : argument_list_with_params applique la coercition `{…}`
         * -> param texte à CHAQUE position (pas seulement au 1er argument),
         * couvrant le cas N>1 `Foo(x, {langueXxx: …})`. Équivalent à
         * argument_list() quand params == NULL ou sans argument `{…}`. */
        uint8_t argCount = argument_list_with_params(params);
        check_call_arity(def, argCount, &callee);
        emit_bytes(OP_CALL, argCount);
        return;
    }

    /* Slow path: inline argument_list with per-arg enum validation
     * and/or out-param lvalue capture. */
    typedef struct { int kind; int operand; int line; } OutParamRef;
    /* kind: 0=local (operand=slot), 1=global (operand=nameConst) */
    OutParamRef outRefs[16];
    int outRefCount = 0;

    Chunk* chunk = current->function->chunk;
    uint8_t argCount = 0;
    if (!check(TOKEN_RIGHT_PAREN)) {
        do {
            const OwlParam* cp = NULL;
            int idx = 0;
            for (const OwlParam* p = params; p->name; p++, idx++) {
                if (idx == argCount) { cp = p; break; }
            }

            int snap = chunk->count;
            int argLine = parser.current.line;
            argument_with_enum_check(cp);

            /* Si cet arg est un out-param, valider qu'il vient d'un
             * OP_GET_LOCAL ou OP_GET_GLOBAL juste émis (= lvalue). La
             * fenêtre [firstOutParamArg .. lastOutParamArg] est inclusive ;
             * lastOutParamArg=-1 signifie « jusqu'à la fin » (variadic). */
            bool isOutSlot = hasOutParams && argCount >= def->firstOutParamArg &&
                             (def->lastOutParamArg < 0 ||
                              argCount <= def->lastOutParamArg);
            if (isOutSlot) {
                int emitted = chunk->count - snap;
                bool lvalue = false;
                /* L'argument doit etre une lecture de variable NUE : une seule
                 * instruction, OP_GET_LOCAL ou OP_GET_GLOBAL. La longueur
                 * attendue vient de la table canonique — les deux opcodes
                 * n'ont plus la meme largeur depuis . */
                uint8_t op = chunk->code[snap];
                if ((op == OP_GET_LOCAL || op == OP_GET_GLOBAL)
                    && emitted == chunk_opcode_size(op, chunk, snap)
                    && outRefCount < 16) {
                    outRefs[outRefCount].kind = (op == OP_GET_LOCAL) ? 0 : 1;
                    outRefs[outRefCount].operand =
                        read_const_or_slot_operand(chunk, snap);
                    outRefs[outRefCount].line = argLine;
                    outRefCount++;
                    lvalue = true;
                }
                if (!lvalue) {
                    owl_emit_error_at(&parser.previous,
                                      E_SEM_OUT_PARAM_NOT_SIMPLE_VAR);
                }
            }

            if (argCount == 255) owl_emit_error_at(&parser.previous, E_SYNTAX_CALL_TOO_MANY_ARGS);
            argCount++;
        } while (match_token(TOKEN_COMMA));
    }
    consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_ARGS);
    check_call_arity(def, argCount, &callee);
    emit_bytes(OP_CALL, argCount);

    /* Émettre les writebacks pour les out-params. L'idx commence à 0
     * (= premier out-param = arg à l'index firstOutParamArg). */
    for (int i = 0; i < outRefCount; i++) {
        if (outRefs[i].kind == 0) {
            emit_byte(OP_OUT_PARAM_TO_LOCAL);
            emit_byte((uint8_t)outRefs[i].operand);
            emit_byte((uint8_t)i);
        } else {
            ConstIdx nameIdx = { (uint16_t)outRefs[i].operand };
            emit_const_op_b(OP_OUT_PARAM_TO_GLOBAL, nameIdx, (uint8_t)i);
        }
    }

    /* Strict dot check : la valeur de retour est de type inconnu côté
     * compileur, on casse la chaîne pour empêcher la résolution fautive
     * sur le receiver d'origine (cf entry #3 queue.md — chaîne fluent
     * cassée par argument typé). Symétrique au flag posé dans subscript.
     *
     * On invalide AUSSI g_last_var_token : un argument passé à la fonction
     * (ex. `Retourne(rep)`) déclenche named_variable("rep") qui reset
     * g_chain_broken à false et set g_last_var_token = "rep". Si on ne
     * faisait que set g_chain_broken ici, le named_variable des args
     * l'aurait déjà annulé entretemps. En vidant g_last_var_token, on
     * garantit que le prochain dot() n'aura plus de receiver nommé sur
     * lequel résoudre un structTypeName. */
    g_chain_broken = true;
    g_last_field_type[0] = '\0';
    g_last_field_type_len = 0;
    g_last_var_token.start = NULL;
    g_last_var_token.length = 0;
}

/* Emet l'erreur "Membre 'X' inexistant sur Type. Propriétés disponibles : ...".
 *
 * Le message peut etre long (httpRequete a 17 proprietes, ~340 octets en
 * UTF-8). Buffer statique trop petit ⇒ troncature au milieu d'un nom (cf
 * ). On construit le texte dans un buffer dynamique qui croit a
 * la demande, puis on delegue a error_at qui copie dans son propre sink. */
static void emit_unknown_member_error(Token tok, const char* typeName,
                                      const OwlTypeDef* td) {
    char fieldBuf[128];
    snprintf(fieldBuf, sizeof(fieldBuf), "%.*s", tok.length, tok.start);

    /* Pre-construit la liste des proprietes affichables dans un buffer
     * dynamique (la liste peut etre longue : httpRequete a 17 props ~340
     * octets UTF-8). On la passe ensuite comme un seul placeholder
     * {fields_list} au template registry (cf.  +  design
     * "string pre-construite" pour listes dynamiques). */
    size_t cap = 512;
    char* list = (char*)malloc(cap);
    if (list == NULL) {
        /* OOM : message court sans liste. */
        owl_emit_error_at(&tok, E_SEM_UNKNOWN_MEMBER_NO_FIELDS,
                          "field", fieldBuf,
                          "type", typeName,
                          NULL);
        return;
    }
    size_t len = 0;
    list[0] = '\0';
    bool first = true;
    for (const OwlField* f = td->fields; f->name; f++) {
        if (f->name[0] == '_') continue;
        const char* show = f->nameAccented ? f->nameAccented : f->name;
        size_t sepLen = first ? 0 : 2;
        size_t showLen = strlen(show);
        size_t need = len + sepLen + showLen + 1; /* + '\0' final */
        if (need > cap) {
            size_t newCap = cap;
            while (newCap < need) newCap *= 2;
            char* grown = (char*)realloc(list, newCap);
            if (grown == NULL) break;
            list = grown;
            cap = newCap;
        }
        if (!first) {
            memcpy(list + len, ", ", 2);
            len += 2;
        }
        memcpy(list + len, show, showLen);
        len += showLen;
        first = false;
    }
    list[len < cap ? len : cap - 1] = '\0';

    if (first) {
        /* Aucun field affichable : pas de liste a montrer. */
        owl_emit_error_at(&tok, E_SEM_UNKNOWN_MEMBER_NO_FIELDS,
                          "field", fieldBuf,
                          "type", typeName,
                          NULL);
    } else {
        owl_emit_error_at(&tok, E_SEM_UNKNOWN_MEMBER,
                          "field", fieldBuf,
                          "type", typeName,
                          "fields_list", list,
                          NULL);
    }
    free(list);
}

/*  — cle de comparaison canon d'un nom de type pour le contrat de
 * signature callback. Un type primitif (entier/integer, réel/real, chaîne/
 * string, booléen/boolean...) rend son TokenType canon (FR et EN convergent) ;
 * un type compose/utilisateur rend sa forme strip-accents + lower. Deux noms
 * compatibles (accent, casse, langue pour les primitifs) rendent la meme cle. */
static void callback_type_canon_key(const char* name, int len,
                                    char* out, size_t outsz) {
    char stripped[64];
    int sl = scanner_strip_accents(name, len, stripped, sizeof(stripped));
    if (sl <= 0) {
        int n = len < (int)sizeof(stripped) - 1 ? len : (int)sizeof(stripped) - 1;
        if (n < 0) n = 0;
        memcpy(stripped, name, (size_t)n);
        sl = n;
    }
    for (int i = 0; i < sl; i++)
        stripped[i] = (char)tolower((unsigned char)stripped[i]);
    stripped[sl] = '\0';
    for (int i = 0; ; i++) {
        TokenType tt;
        const char* kw = scanner_keyword_at(i, &tt);
        if (kw == NULL) break;
        if (strcmp(kw, stripped) == 0) {
            snprintf(out, outsz, "#%d", (int)tt);
            return;
        }
    }
    snprintf(out, outsz, "%s", stripped);
}

/*  — valide le contrat de signature d'un callback au site
 * `recv..prop = MaProc`. Ne fait quelque chose QUE si :
 *   - `recvType` est un type composé du registre (pas un type utilisateur
 *     homonyme) portant le field `prop` de type "procédure" avec .callbackSig ;
 *   - le RHS est un identifiant NU (aucun `(`, opérateur ni suite) qui résout
 *     vers une PROCEDURE top-level connue (g_user_procs).
 * Dans ce cas, exige arité + types de params EXACTS. Tout RHS non résoluble
 * statiquement (variable, expression, appel, référence forward) est laissé
 * passer : le runtime tranche. Émet E_SEM_CALLBACK_SIGNATURE_MISMATCH sur le
 * token du récepteur (début de l'affectation) en cas de divergence. */
static void check_callback_signature_assignment(const char* recvType,
                                                 Token fieldTok,
                                                 Token receiverTok) {
    if (recvType == NULL) return;
    if (is_known_user_type(recvType, (int)strlen(recvType))) return;
    const OwlTypeDef* td = owl_registry_type_find(recvType);
    if (td == NULL || td->fields == NULL) return;

    /* Résolution du field (accent/casse insensible sur name/nameAccented/nameEN). */
    char qStrip[64];
    int ql = scanner_strip_accents(fieldTok.start, fieldTok.length,
                                   qStrip, sizeof(qStrip));
    if (ql <= 0) {
        ql = fieldTok.length < 63 ? fieldTok.length : 63;
        memcpy(qStrip, fieldTok.start, (size_t)ql);
        qStrip[ql] = '\0';
    }
    const OwlField* cb = NULL;
    for (const OwlField* f = td->fields; f->name; f++) {
        if (inline_field_name_matches(qStrip, ql, f->name)
            || (f->nameAccented && inline_field_name_matches(qStrip, ql, f->nameAccented))
            || (f->nameEN && inline_field_name_matches(qStrip, ql, f->nameEN))) {
            cb = f;
            break;
        }
    }
    /*  — modèle 2 états : NULL/absent = pas de contrat vérifié ici
     * (la garde registry rule 60 s'en charge) ; "" = contrat zéro-paramètre
     * STRICT (arité attendue 0), vérifié comme n'importe quel autre contrat.
     * L'ancien état « lenient » (callbackSig="" court-circuité, délégué au
     * runtime) est supprimé. */
    if (cb == NULL || cb->callbackSig == NULL) return;

    /* RHS = identifiant nu ? parser.current est le 1er token du RHS ; le token
     * qui le suit doit terminer l'instruction (sinon appel/expression). */
    if (parser.current.type != TOKEN_IDENTIFIER) return;
    Scanner peek = parser.scanner;
    Token after = scanner_scan_token(&peek);
    if (after.type != TOKEN_NEWLINE && after.type != TOKEN_EOF) return;

    UserProcInfo* up = user_proc_find(parser.current.start, parser.current.length);
    if (up == NULL) return;

    /* Compte des types attendus (tokens séparés par virgule). */
    int expCount = 0;
    if (cb->callbackSig[0] != '\0') {
        expCount = 1;
        for (const char* p = cb->callbackSig; *p; p++)
            if (*p == ',') expCount++;
    }

    bool mismatch = (expCount != up->paramCount);
    if (!mismatch) {
        const char* p = cb->callbackSig;
        int idx = 0;
        while (*p && !mismatch && idx < up->paramCount) {
            const char* tokStart = p;
            while (*p && *p != ',') p++;
            int tokLen = (int)(p - tokStart);
            while (tokLen > 0 && (tokStart[0] == ' ' || tokStart[0] == '\t')) {
                tokStart++; tokLen--;
            }
            while (tokLen > 0 && (tokStart[tokLen - 1] == ' ' || tokStart[tokLen - 1] == '\t'))
                tokLen--;
            char expKey[80], gotKey[80];
            callback_type_canon_key(tokStart, tokLen, expKey, sizeof(expKey));
            callback_type_canon_key(up->paramTypes[idx],
                                    (int)strlen(up->paramTypes[idx]),
                                    gotKey, sizeof(gotKey));
            if (strcmp(expKey, gotKey) != 0) mismatch = true;
            if (*p == ',') p++;
            idx++;
        }
    }
    if (!mismatch) return;

    /* Rendu des listes affichées : attendu = callbackSig avec ", " ; fourni =
     * types déclarés de la procédure, dans leur forme source. */
    char expDisp[256];
    if (cb->callbackSig[0] == '\0') {
        /*  — contrat zéro-paramètre : libellé lisible plutôt que le
         * "()" vide que produirait le rendu générique. Le template enveloppe
         * déjà entre parenthèses. */
        snprintf(expDisp, sizeof(expDisp), "%s",
                 owl_error_render_lang_is_en() ? "no parameter" : "aucun paramètre");
    } else {
        int o = 0;
        for (const char* p = cb->callbackSig; *p && o < (int)sizeof(expDisp) - 2; p++) {
            if (*p == ',') { expDisp[o++] = ','; expDisp[o++] = ' '; }
            else expDisp[o++] = *p;
        }
        expDisp[o] = '\0';
    }
    char provDisp[256];
    {
        int o = 0;
        for (int i = 0; i < up->paramCount; i++) {
            if (i > 0 && o < (int)sizeof(provDisp) - 2) {
                provDisp[o++] = ','; provDisp[o++] = ' ';
            }
            for (const char* p = up->paramTypes[i]; *p && o < (int)sizeof(provDisp) - 1; p++)
                provDisp[o++] = *p;
        }
        provDisp[o] = '\0';
    }
    char procBuf[128], propBuf[128];
    snprintf(procBuf, sizeof(procBuf), "%.*s",
             parser.current.length, parser.current.start);
    snprintf(propBuf, sizeof(propBuf), "%.*s",
             fieldTok.length, fieldTok.start);
    owl_emit_error_at(&receiverTok, E_SEM_CALLBACK_SIGNATURE_MISMATCH,
                      "proc", procBuf, "prop", propBuf,
                      "expected", expDisp, "provided", provDisp, NULL);
}

/*  (amendement ) — recepteur colonne EXTENSIBLE.
 *
 *  bornait le receveur de mise en forme d'une colonne de Table a
 * `Couleur`/`CouleurFond` : ces deux props etaient acceptees en dur (un `if`
 * strcasecmp), toute autre prop => E_SEM_TABLE_COLUMN_PROP_NOT_WRITABLE. Le
 * refus n'etait PAS un mur technique mais une garde anti-no-op : les autres
 * props n'avaient aucun chemin d'application Qt au niveau colonne, donc les
 * accepter aurait compile une ecriture dans le vide.
 *
 *  fabrique ce chemin pour `MasqueSaisie`/`InputMask` (store per-colonne
 * + createEditor du delegate colonne, cote ui_qt.cpp). La condition d'
 * (« inscriptible SANS chemin d'application Qt = interdit ») tombe pour cette
 * prop. Plutot que d'ajouter un 3e cas en dur, la liste des props receveur
 * colonne devient une TABLE : ajouter une future prop colonne = une entree ici
 * + son chemin d'application Qt, sans re-combattre le compilo.
 *
 * Chaque entree porte le canon FR et EN. La comparaison se fait sur la forme
 * accent-strippee (`propProbe`) : les canons ci-dessous sont sans accent par
 * construction (Couleur, CouleurFond, MasqueSaisie, InputMask...) et matchent
 * en casse-insensible. Invariant 6.3 (bilingue) : chaque prop expose FR ET EN. */
typedef struct {
    const char* canonFR;   /* forme FR, comparee accent-strippee, casse-insensible */
    const char* canonEN;   /* forme EN idem */
} OwlColumnReceiverProp;

static const OwlColumnReceiverProp OWL_COLUMN_RECEIVER_PROPS[] = {
    { "Couleur",      "Color" },
    { "CouleurFond",  "BackgroundColor" },
    { "MasqueSaisie", "InputMask" },   /*  — 1er cas non-formatage */
};

/* propProbe = nom de propriete deja accent-strippe. true si la prop est un
 * receveur colonne declare (a un chemin d'application Qt). */
static bool column_receiver_prop_is_writable(const char* propProbe) {
    size_t n = sizeof(OWL_COLUMN_RECEIVER_PROPS)
             / sizeof(OWL_COLUMN_RECEIVER_PROPS[0]);
    for (size_t i = 0; i < n; i++) {
        if (strcasecmp(propProbe, OWL_COLUMN_RECEIVER_PROPS[i].canonFR) == 0
            || strcasecmp(propProbe, OWL_COLUMN_RECEIVER_PROPS[i].canonEN) == 0)
            return true;
    }
    return false;
}

/* Dot access for struct fields and method calls: expr.fieldName or expr.method(args) */
static void dot(bool canAssign) {
    /* Capture which dot variant triggered this infix call BEFORE we
     * consume the field name (after which parser.previous is the field). */
    bool isDoubleDot = (parser.previous.type == TOKEN_DOUBLE_DOT);
    /*  lot 1 — etat du suivi `TABLE_X[ligne]..COL_Y..Prop` consomme
     * des maintenant : il ne vaut que pour CE dot, pas pour les sous-acces
     * compiles en cours de route (arguments d'une methode, RHS d'un assign). */
    char tblChainTable[128];
    char tblChainCol[128];
    int  tblChainTableLen = g_table_cell_table_len;
    int  tblChainColLen   = g_table_cell_col_len;
    /*  — profondeur de designation atteinte : 2 = cellule entierement
     * designee (colonne-first `.COL[l]`), 1 = ligne seule. Discrimine, au refus
     * d'une propriete inconnue, la cellule pleinement designee (message oriente
     * propriete) de la valeur `TABLE_X[l].COL` (aucune propriete). */
    int  tblChainDepth    = (tblChainTableLen > 0) ? g_table_cell_depth : 0;
    if (tblChainTableLen > 0)
        memcpy(tblChainTable, g_table_cell_table, (size_t)tblChainTableLen + 1);
    if (tblChainColLen > 0)
        memcpy(tblChainCol, g_table_cell_col, (size_t)tblChainColLen + 1);
    table_cell_chain_reset();
    /*  — meme consommation immediate pour le suivi `ZR_X[i].field` :
     * il ne vaut que pour CE dot. */
    char zrChainZr[128];
    int  zrChainZrLen = g_zr_cell_zr_len;
    if (zrChainZrLen > 0)
        memcpy(zrChainZr, g_zr_cell_zr, (size_t)zrChainZrLen + 1);
    zr_cell_chain_reset();
    /*  — meme consommation immediate pour le suivi `SEL_X[i]..Prop` :
     * il ne vaut que pour CE dot. */
    bool optChainOn    = g_ui_option_armed;
    bool optChainInter = g_ui_option_is_interrupteur;
    ui_option_chain_reset();
    /* obj.{expr [, scope]} — dynamic field access by name. */
    if (check(TOKEN_LEFT_BRACE)) {
        advance_token(); /* consume '{' */
        expression();
        if (match_token(TOKEN_COMMA)) {
            expression();
            emit_byte(OP_POP); /* discard scope constant */
        }
        consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_INDIRECTION);
        if (canAssign && match_token(TOKEN_EQUAL)) {
            expression();
            emit_byte(OP_INDIRECT_FIELD_SET);
        } else {
            emit_byte(OP_INDIRECT_FIELD_GET);
        }
        return;
    }

    /* Snapshot receiver for enum-validated field assignments. The receiver
     * was the last identifier compiled via named_variable (g_last_var_token). */
    Token receiverTok = g_last_var_token;

    /*  — snapshot + consommation du recepteur dynamique arme par
     * moimeme_self/monchamp_self/mafenetre_self. Consomme des maintenant
     * (remis a NONE) : ne vaut que pour CE `..`, pas pour les sous-acces de
     * la chaine (dont le kind est celui de la prop intermediaire). */
    DynReceiverKind dynRecv = g_last_dynamic_receiver;
    char dynRecvName[32];
    memcpy(dynRecvName, g_last_dynamic_receiver_name, sizeof(dynRecvName));
    g_last_dynamic_receiver = DYN_RECV_NONE;

    /*  — snapshot + consommation du conteneur de contexte service
     * (Requête/Réponse) arme au `..` precedent. Ne vaut que pour CE `..` : le
     * 2e niveau valide sa sous-propriete et canonise la constante emise. */
    ServiceCtxContainer svcPendingContainer = g_service_pending_container;
    g_service_pending_container = SVC_CTX_NONE;

    /*  — Snapshot du field name precedent dans la chaine (avant
     * qu'il soit overwritten par fieldTok current a L6333). Sert au
     * detecteur cas direct `icones.X..Couleur` ou X est le field precedent
     * et Couleur le field courant. */
    char prev_field_name[64];
    int  prev_field_name_len = g_last_field_name_len;
    if (prev_field_name_len > 0) {
        int n = prev_field_name_len < (int)sizeof(prev_field_name) - 1
                ? prev_field_name_len : (int)sizeof(prev_field_name) - 1;
        memcpy(prev_field_name, g_last_field_name, (size_t)n);
        prev_field_name[n] = '\0';
        prev_field_name_len = n;
    } else {
        prev_field_name[0] = '\0';
    }

    /* Bug #6 : si le receiver (variable racine) est une constante d'enum
     * (BordBas, RougeFonce, ...), `..` derriere n'a aucun sens.
     * NB: on NE traite PAS le cas chaîné g_last_field_name — un field
     * d'enum user-defined peut collisionner par nom avec une constante
     * globale (ex. `eStatut.Actif..X` : Actif est un field d'eStatut,
     * pas la constante UI Actif). Le strict check par-type (plus bas)
     * couvre les vrais cas DSL ; ici on garde uniquement la safety net
     * pour les receivers standalone. */
    if (isDoubleDot && g_last_field_name_len == 0) {
        char check_name[64] = "";
        if (receiverTok.length > 0 && receiverTok.length < 64) {
            bool shadowed = false;
            for (int i = decl_globals_bucket_head(receiverTok.start, receiverTok.length);
                 i != -1; i = g_declaredGlobals[i].hashNext) {
                if (decl_globals_match(i, receiverTok.start, receiverTok.length)) {
                    shadowed = true;
                    break;
                }
            }
            if (!shadowed) {
                memcpy(check_name, receiverTok.start, receiverTok.length);
                check_name[receiverTok.length] = '\0';
            }
        }
        if (check_name[0]) {
            const OwlConstDef* cd = owl_registry_const_find(check_name);
            if (cd) {
                owl_emit_error_at(&parser.previous, E_SEM_DOTDOT_ON_CONST,
                                  "name", check_name,
                                  "category", cd->category ? cd->category : "valeur",
                                  NULL);
            }
        }
    }

    /* After a dot, accept any word token (identifier or keyword) as a field/method name.
     * This allows d.Jour, h.Heure, t.Type, etc. where Jour/Heure/Type are keywords. */
    if (parser.current.type >= TOKEN_IDENTIFIER && parser.current.type < TOKEN_NEWLINE) {
        advance_token();
    } else {
        consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_FIELD_NAME_AFTER_DOT);
    }
    Token fieldTok = parser.previous;
    ConstIdx name = identifier_constant(&parser.previous);

    /*  lot 1 — machine a deux temps sur `TABLE_X[ligne]` :
     *   1er dot  -> la cellule <colonne> (valide, rend sa valeur) ;
     *   2e  dot  -> mise en forme par cellule : n'existe pas, on refuse ici
     *               au lieu de laisser mourir au runtime sur « valeur Null ».
     * Aucun return : le parsing continue normalement (une erreur, pas une
     * cascade), le compile echoue de toute facon. */
    if (tblChainColLen > 0 && tblChainTableLen > 0) {
        if (tblChainDepth >= 2 && fieldTok.length < 128) {
            /*  — colonne-first `TABLE_X.COL_A[l]..<nom>` : la cellule est
             * entierement designee (COL_A existe), seul <nom> est une propriete
             * inconnue. E_SEM_TABLE_CELL_NO_PROP decrivait la valeur `[l].COL_A`,
             * une forme que l'utilisateur n'avait pas ecrite : message oriente
             * propriete a la place. */
            char cellPropBuf[128];
            memcpy(cellPropBuf, fieldTok.start, (size_t)fieldTok.length);
            cellPropBuf[fieldTok.length] = '\0';
            owl_emit_error_at(&fieldTok, E_SEM_TABLE_CELL_UNKNOWN_PROP,
                              "nom", cellPropBuf,
                              "table", tblChainTable,
                              NULL);
        } else {
            owl_emit_error_at(&fieldTok, E_SEM_TABLE_CELL_NO_PROP,
                              "table", tblChainTable,
                              "colonne", tblChainCol,
                              NULL);
        }
    } else if (tblChainTableLen > 0 && fieldTok.length < 128) {
        char cellFieldBuf[128];
        memcpy(cellFieldBuf, fieldTok.start, (size_t)fieldTok.length);
        cellFieldBuf[fieldTok.length] = '\0';
        /*  — mise en forme d'une cellule ou d'une ligne
         * (`TABLE_X[ligne]..Couleur`, `TABLE_X[ligne][colonne]..CouleurFond`) :
         * le field designe une propriete, pas une cellule. On n'arme donc PAS
         * l'etat « cellule atteinte » — sinon un dot de plus produirait un
         * message parlant d'une « cellule 'Couleur' », charabia pour qui lit. */
        if (owl_table_cell_catalog_find(cellFieldBuf) == NULL) {
            g_table_cell_table_len = tblChainTableLen;
            memcpy(g_table_cell_table, tblChainTable,
                   (size_t)tblChainTableLen + 1);
            g_table_cell_col_len = fieldTok.length;
            memcpy(g_table_cell_col, cellFieldBuf,
                   (size_t)fieldTok.length + 1);
            /*  — forme ligne-first `TABLE_X[ligne].<nom>` : le nom doit
             * etre une colonne de CETTE Table. Un appel de methode derriere
             * (`(`) n'est pas un acces cellule, on laisse passer. */
            if (!check(TOKEN_LEFT_PAREN)) {
                /*  — `..` designe une propriete (invariant 6), `.` un nom
                 * de colonne pour l'acces valeur : le message se contextualise
                 * dessus (`TABLE_X[l][c]..<prop>` / `TABLE_X[l]..<prop>` vs
                 * `TABLE_X[l].<col>`). */
                table_cell_check_column(&fieldTok, tblChainTable,
                                        g_table_cell_col,
                                        isDoubleDot ? TBL_CELL_CTX_CELL_PROPERTY
                                                    : TBL_CELL_CTX_COLUMN_NAME);
            }
        } else if (!isDoubleDot && !check(TOKEN_LEFT_PAREN)) {
            /*  — mise en forme d'une cellule ecrite au point simple.
             * Le field EST une propriete du catalogue cellule : seule la
             * graphie de l'operateur est fautive. */
            owl_emit_error_at(&fieldTok, E_SEM_PROP_USE_DOUBLE_DOT,
                              "field", cellFieldBuf,
                              "type", "cellule de Table",
                              NULL);
        }
    }

    /*  — forme colonne-first QUALIFIEE NON INDEXEE `TABLE_X.COL_A..<prop>`.
     * Le proxy-colonne ne livre que `Couleur`/`CouleurFond` au niveau
     * colonne. Toute autre propriete compilait clean = ecriture dans
     * le vide (no-op silencieux). On applique ici le meme refus que la forme NUE
     * ( Lot A, try_intercept_bare_table_column) : seules Couleur/
     * CouleurFond (FR/EN, casse+accent-insensible) acceptees, meme symbole
     * d'erreur, memes placeholders.
     *
     * Borne stricte au cas NON INDEXE : `tblChainTableLen == 0` ecarte la forme
     * indexee `TABLE_X.COL_A[l]..Couleur`, qui arme le suivi cellule
     * et est traitee plus haut. Le receveur immediat de CE `..` est la colonne
     * (prev_field_name), avec la Table pour racine (receiverTok) : c'est l'etat
     * de chaine laisse par le 1er dot `.COL_A` (proxy-colonne) OU par le
     * desucrage de la forme nue. La double condition (receiverTok = Table +
     * prev_field_name = colonne declaree de cette Table) exclut les autres
     * chaines `racine.membre..prop`. */
    if (isDoubleDot && tblChainTableLen == 0 && prev_field_name_len > 0
        && receiverTok.length > 0 && receiverTok.length < 128
        && fieldTok.length < 64) {
        char tblBuf[128];
        memcpy(tblBuf, receiverTok.start, (size_t)receiverTok.length);
        tblBuf[receiverTok.length] = '\0';
        OwlControlKind rKind;
        const OwlControlKindInfo* rInfo = compiler_prescan_widget_find(tblBuf);
        if (rInfo != NULL && owl_control_kind_of_info(rInfo, &rKind)
            && rKind == OWL_CONTROL_TABLE
            && prescan_widget_has_child(tblBuf, prev_field_name)) {
            char propProbe[64];
            int pp = scanner_strip_accents(fieldTok.start, fieldTok.length,
                                           propProbe, sizeof(propProbe));
            propProbe[pp] = '\0';
            /*  — receveur data-driven (cf. OWL_COLUMN_RECEIVER_PROPS) :
             * les props sans chemin d'application Qt restent refusees. */
            if (!column_receiver_prop_is_writable(propProbe)) {
                char propRaw[64];
                memcpy(propRaw, fieldTok.start, (size_t)fieldTok.length);
                propRaw[fieldTok.length] = '\0';
                owl_emit_error_at(&fieldTok, E_SEM_TABLE_COLUMN_PROP_NOT_WRITABLE,
                                  "prop", propRaw,
                                  "nom", prev_field_name,
                                  "table", tblBuf,
                                  NULL);
            }
        }
    }

    /*  — forme ligne-first `ZR_X[ligne].<field>` : le nom doit etre un
     * enfant declare de CETTE ZoneRépétée. Un `..prop` (double point) designe une
     * mise en forme, pas une cellule ; un `(` derriere est un appel de methode :
     * dans les deux cas on se tait. Couvre lecture ET ecriture (ce point precede
     * le traitement de l'affectation). */
    if (zrChainZrLen > 0 && !isDoubleDot && fieldTok.length < 128
        && !check(TOKEN_LEFT_PAREN)) {
        char zrFieldBuf[128];
        memcpy(zrFieldBuf, fieldTok.start, (size_t)fieldTok.length);
        zrFieldBuf[fieldTok.length] = '\0';
        zr_cell_check_field(&fieldTok, zrChainZr, zrFieldBuf);
    }

    /*  +  — `SEL_X[i]..Prop` / `INT_X[i]..Prop` : le receveur de
     * CE dot est une option, pas le champ. Deux refus, dans cet ordre :
     *   - nom hors du jeu de proprietes d'une option -> liste ce qui existe
     *     (le message « inconnue pour Sélecteur » du catalogue de champ mentait :
     *     Libellé n'est pas non plus une propriete du Sélecteur lui-meme) ;
     *   - point simple sur une propriete valide -> refus d'operateur, nomme sur
     *     la forme INDEXEE : c'est ce que l'utilisateur vient d'ecrire, et
     *     `SEL_X..Libellé` (non indexe) reste faux.
     * L'ECRITURE d'une propriete valide (`SEL_X[i]..Libellé = "x"`) est desormais
     * autorisee : elle retombe sur le field-set normal (OP_STRUCT_SET sur `name`,
     * la cle canon posee ci-dessous), qui mute l'option live du store en headless
     * et pousse au widget en graphique (on_instance_modified_impl).
     * Un `(` derriere est un appel : hors sujet ici, on se tait. */
    if (optChainOn && fieldTok.length < 128
        && !check(TOKEN_LEFT_PAREN)) {
        char optPropBuf[128];
        memcpy(optPropBuf, fieldTok.start, (size_t)fieldTok.length);
        optPropBuf[fieldTok.length] = '\0';
        const char* optKindLabel = optChainInter
            ? "Interrupteur index\xc3\xa9" : "S\xc3\xa9lecteur index\xc3\xa9";
        const char* optCanon = ui_option_prop_find(optPropBuf, optChainInter);
        if (optCanon != NULL) {
            /*  — la forme EN (`..Label`) designe le meme casier que la
             * forme FR : on emet la cle CANON, sinon le STRUCT_GET/SET chercherait
             * un champ `Label` qui n'existe dans aucune option et rendrait Null
             * en silence. Bilingue reel, pas bilingue a l'analyse seulement.
             * En ecriture, cette canonicalisation fait converger
             * `SEL_X[i]..Label = ...` et la relecture `..Libellé`. */
            Token canonTok = fieldTok;
            canonTok.start  = optCanon;
            canonTok.length = (int)strlen(optCanon);
            name = identifier_constant(&canonTok);
        }
        if (optCanon == NULL) {
            char optList[128];
            ui_option_prop_list(optChainInter, optList, sizeof(optList));
            owl_emit_error_at(&fieldTok, E_SEM_UNKNOWN_MEMBER,
                              "field", optPropBuf,
                              "type", optKindLabel,
                              "fields_list", optList,
                              NULL);
        } else if (!isDoubleDot) {
            owl_emit_error_at(&fieldTok, E_SEM_PROP_USE_DOUBLE_DOT,
                              "field", optPropBuf,
                              "type", optKindLabel,
                              NULL);
        }
    }

    /* Validate single-dot field access against a user-defined structure.
     * If the receiver is a known struct and the field doesn't exist,
     * emit a precise compile error listing available fields. Skipped when
     * a `(` follows (method call — out of scope here). */
    /* Determine receiver type: chained access uses the type of the previous
     * field; otherwise fall back to the named variable's declared struct.
     *
     * Le type de la chaine precedente vit dans g_last_field_type, qui est
     * remis a zero juste apres (et repopule plus bas). On en prend un
     * snapshot local : sinon recvType aliase le buffer global et lit ""
     * apres le reset, ce qui casse la validation de cascade (`a..b..c`,
     * `WIDGET..Cadre..Champ`). */
    char recvTypeBuf[64];
    const char* recvType = NULL;
    bool recvFromUiObject = false;
    /*  — recvType decrit-il vraiment le receveur de CE dot ? Vrai s'il
     * vient de la propagation de chaine ; faux quand la chaine n'a rien propage
     * et qu'on retombe sur le type de la variable racine, qui ne designe alors
     * plus le receveur immediat (`obj.membreTableau..Occurrence`). */
    bool recvTypeFromChain = false;
    if (g_last_field_type_len > 0) {
        int n = g_last_field_type_len < (int)sizeof(recvTypeBuf) - 1
                ? g_last_field_type_len : (int)sizeof(recvTypeBuf) - 1;
        memcpy(recvTypeBuf, g_last_field_type, (size_t)n);
        recvTypeBuf[n] = '\0';
        recvType = recvTypeBuf;
        recvFromUiObject = g_last_field_from_ui_object;
        recvTypeFromChain = true;
    } else if (receiverTok.length > 0) {
        recvType = resolve_var_style_type_xfile(receiverTok.start,
                                                receiverTok.length);
    }

    /* Reset the chain tracker; we'll repopulate it below if we can resolve
     * this field's type. */
    g_last_field_from_ui_object = false;
    g_last_field_type[0] = '\0';
    g_last_field_type_len = 0;

    /* Track field name for next dot in chain (bug #6). */
    {
        int copy = fieldTok.length < 63 ? fieldTok.length : 63;
        memcpy(g_last_field_name, fieldTok.start, copy);
        g_last_field_name[copy] = '\0';
        g_last_field_name_len = copy;
    }

    /*  — forme colonne-first `TABLE_X.<nom>[ligne]` : le
     * crochet qui suit rend la cellule, donc <nom> designe une colonne et doit
     * exister dans CETTE Table. On ne se declenche que sur le 1er dot simple
     * d'une chaine suivi d'un `[` : au-dela le receveur n'est plus la Table. */
    if (!isDoubleDot && prev_field_name_len == 0 && check(TOKEN_LEFT_BRACKET)
        && receiverTok.length > 0 && receiverTok.length < 128
        && fieldTok.length < 128) {
        char tblBuf[128];
        memcpy(tblBuf, receiverTok.start, (size_t)receiverTok.length);
        tblBuf[receiverTok.length] = '\0';
        OwlControlKind rKind;
        const OwlControlKindInfo* rInfo = compiler_prescan_widget_find(tblBuf);
        if (rInfo != NULL && owl_control_kind_of_info(rInfo, &rKind)
            && rKind == OWL_CONTROL_TABLE) {
            char colBuf[128];
            memcpy(colBuf, fieldTok.start, (size_t)fieldTok.length);
            colBuf[fieldTok.length] = '\0';
            /*  — `TABLE_X.<nom>[l]` : le `[` qui suit rend la cellule,
             * donc <nom> designe une COLONNE et doit exister. */
            table_cell_check_column(&fieldTok, tblBuf, colBuf,
                                    TBL_CELL_CTX_COLUMN_NAME);
        }
    }

    /*  — validation `..prop` sur un recepteur dynamique UI (MoiMême/
     * MonChamp/MaFenêtre). Le kind reel n'est pas connu a la compile, donc on
     * ne rejette que ce qui est faux dans TOUS les cas possibles :
     *   - CONTROL (MoiMême/MonChamp) : prop absente de l'UNION des kinds de
     *     champ (seuil >= 1, zero faux positif). Nom/Style universelles passent.
     *   - WINDOW (MaFenêtre) : prop absente du catalogue Fenetre.
     * Uniquement sur le 1er `..` de la chaine (prev_field_name_len == 0) et
     * hors appel de methode (`(`) : au-dela, le receveur est la prop
     * intermediaire, non validable ici. */
    if (isDoubleDot && dynRecv != DYN_RECV_NONE && prev_field_name_len == 0
        && !check(TOKEN_LEFT_PAREN)) {
        char propBuf[128];
        int plen = fieldTok.length < (int)sizeof(propBuf) - 1
                   ? fieldTok.length : (int)sizeof(propBuf) - 1;
        memcpy(propBuf, fieldTok.start, (size_t)plen);
        propBuf[plen] = '\0';
        if (dynRecv == DYN_RECV_WINDOW) {
            if (owl_window_catalog_find(propBuf) == NULL
                && !owl_ui_prop_is_universal(propBuf)) {
                owl_emit_error_at(&fieldTok, E_SEM_DSL_PROP_UNKNOWN_FOR_WINDOW,
                                  "prop", propBuf, NULL);
            }
        } else {
            /* DYN_RECV_CONTROL : union des kinds de champ (stricte).
             * DYN_RECV_SELF : MoiMême resout aussi a la Fenetre / l'Etat en
             * handler de niveau fenetre — on elargit pour ne pas rejeter
             * `MoiMême..Titre` (prop Fenetre) ou une prop d'Etat. */
            bool ok = owl_ui_prop_exists_on_any_control_kind(propBuf);
            if (!ok && dynRecv == DYN_RECV_SELF) {
                ok = owl_window_catalog_find(propBuf) != NULL
                     || owl_etat_catalog_find(propBuf) != NULL;
            }
            /*  — en handler de service, MoiMême porte le contexte
             * d'echange : au 1er `..`, seuls les conteneurs Requête/Réponse
             * sont valides (le modele plat historique MoiMême..CodeÉtat est
             * retire — break net). On canonise la constante emise et on arme le
             * conteneur pour valider la sous-propriete au `..` suivant. */
            if (!ok && dynRecv == DYN_RECV_SELF && g_in_service_handler) {
                char propAscii[128];
                int pan = scanner_strip_accents(propBuf, (int)strlen(propBuf),
                                                propAscii, sizeof(propAscii));
                if (pan <= 0) { propAscii[0] = '\0'; }
                const char* canon = service_ctx_container_canon(propAscii);
                if (canon != NULL) {
                    ok   = true;
                    name = service_ctx_canon_const(canon);
                    g_service_pending_container =
                        (strcmp(canon, "Reponse") == 0) ? SVC_CTX_REPONSE
                                                        : SVC_CTX_REQUETE;
                }
            }
            if (!ok) {
                /* Le "kind" injecte porte la mention du recepteur pour un
                 * message clair. SELF valide champ ∪ Fenetre ∪ Etat, donc le
                 * libelle doit refleter l'union, contrairement a CONTROL qui
                 * est strictement champ. */
                char kindLabel[96];
                if (dynRecv == DYN_RECV_SELF) {
                    snprintf(kindLabel, sizeof(kindLabel),
                             "un champ, une fenêtre ou un état (via %s)",
                             dynRecvName);
                } else {
                    snprintf(kindLabel, sizeof(kindLabel), "tout champ (via %s)",
                             dynRecvName);
                }
                owl_emit_error_at(&fieldTok, E_SEM_DSL_PROP_UNKNOWN_FOR_KIND,
                                  "prop", propBuf,
                                  "kind", kindLabel,
                                  NULL);
            }
        }
    }

    /*  — 2e niveau du contexte d'echange service : valide la
     * sous-propriete de Requête/Réponse et canonise la constante emise. Un
     * typo ici (MoiMême..Réponse..CodeEta) erre au lieu de creer un champ
     * fantome sur la sous-instance. Le conteneur a ete arme au `..` precedent
     * (svcPendingContainer, consomme en tete de dot). Hors appel de methode. */
    if (isDoubleDot && svcPendingContainer != SVC_CTX_NONE
        && !check(TOKEN_LEFT_PAREN)) {
        char subBuf[128];
        int slen = fieldTok.length < (int)sizeof(subBuf) - 1
                   ? fieldTok.length : (int)sizeof(subBuf) - 1;
        memcpy(subBuf, fieldTok.start, (size_t)slen);
        subBuf[slen] = '\0';
        char subAscii[128];
        int san = scanner_strip_accents(subBuf, (int)strlen(subBuf),
                                        subAscii, sizeof(subAscii));
        if (san <= 0) { subAscii[0] = '\0'; }
        const char* canon = (svcPendingContainer == SVC_CTX_REPONSE)
            ? service_ctx_response_sub_canon(subAscii)
            : service_ctx_request_sub_canon(subAscii);
        if (canon != NULL) {
            name = service_ctx_canon_const(canon);
        } else {
            const char* kindLabel = (svcPendingContainer == SVC_CTX_REPONSE)
                ? "la réponse d'un service (via MoiMême..Réponse)"
                : "la requête d'un service (via MoiMême..Requête)";
            owl_emit_error_at(&fieldTok, E_SEM_DSL_PROP_UNKNOWN_FOR_KIND,
                              "prop", subBuf,
                              "kind", kindLabel,
                              NULL);
        }
    }

    /*  — raccourci CODE : `Style..<feuille>` ≡ `Style..ZoneSaisie..
     * <feuille>`. ZoneSaisie est le domicile unique des props de base
     * (Couleur/CouleurFond/Police/Cadre/Retraits). Sur toute cible de type
     * styleSaisie — prop UI OBJECT (`SAI..Style..CouleurFond`) OU variable
     * locale/globale/champ chaine (`st est un styleSaisie ; st..CouleurFond`)
     * — si le field est une feuille de la brique (connue sur
     * styleZoneSaisieBase mais PAS un membre structurel de styleSaisie), on
     * intercale un STRUCT_GET ZoneSaisie et on rebascule le type courant : le
     * receveur effectif de ce field devient la ZoneSaisie. Les formes
     * explicites ..ZoneSaisie../..Libellé../..CadreExtérieur.. restent intactes
     * (ces noms sont des membres de styleSaisie, pas des feuilles de brique).
     * Un tableau `tab[i]` n'est jamais touche : le raccourci exige `..field`
     * (isDoubleDot) et un fieldName feuille de brique, pas un `[`. */
    if (isDoubleDot && recvType != NULL
        && !check(TOKEN_LEFT_PAREN)
        && strcasecmp(recvType, "styleSaisie") == 0
        && object_field_known("styleZoneSaisieBase", 19, fieldTok)
        && !object_field_known("styleSaisie", 11, fieldTok)) {
        Token zsTok; zsTok.start = "ZoneSaisie"; zsTok.length = 10;
        ConstIdx zsIdx = identifier_constant(&zsTok);
        emit_const_op(OP_STRUCT_GET, zsIdx);   /* [styleSaisie] -> [zoneSaisie] */
        memcpy(recvTypeBuf, "styleZoneSaisie", 15);
        recvTypeBuf[15] = '\0';
        recvType = recvTypeBuf;
        /* recvFromUiObject inchange : cible UI-object => validation fieldTok
         * via la voie template UI ; variable declaree => voie user-type. Les
         * deux valident la feuille contre styleZoneSaisie. */
    }

    /*  : prop UI de type OBJECT (descripteur compose, ex Cadre).
     * Quand `WIDGET..Cadre` est un acces a une prop OBJECT, on propage le
     * type-cible (object_type) dans g_last_field_type pour que la cascade
     * `..SousChamp` soit validee compile-time contre les champs du type
     * compose (mecanisme builtin-composite ci-dessous). Symetrique du
     * propagate des champs de structure user-declaree.
     * En plus : si la prop OBJECT est la cible d'une affectation scalaire
     * directe (`WIDGET..Cadre = 5`), on rejette — seul un descripteur
     * compose est accepte.
     *
     *  — ce bloc est ouvert AUX DEUX graphies de l'operateur. Le
     * point simple ne designe jamais une propriete : il doit subir la meme
     * validation que `..` (sinon il la desarme silencieusement) et recevoir
     * en plus, quand la propriete est valide, le refus d'operateur dedie.
     *
     *  — `!optChainOn` : sur `SEL_X[1]..Libellé`, receiverTok reste le
     * nom du Sélecteur (l'indice litteral n'ecrase pas g_last_var_token). Le
     * catalogue a interroger est celui de l'OPTION, pas celui du champ ; le bloc
     * dedie plus haut a deja tranche. */
    if (recvType == NULL && receiverTok.length > 0
        && receiverTok.length < 128 && !check(TOKEN_LEFT_PAREN)
        && !optChainOn) {
        char nameBuf[128];
        memcpy(nameBuf, receiverTok.start, (size_t)receiverTok.length);
        nameBuf[receiverTok.length] = '\0';
        const OwlControlKindInfo* info = compiler_prescan_widget_find(nameBuf);
        OwlControlKind kind;
        if (info && owl_control_kind_of_info(info, &kind)) {
            char propBuf[128];
            int plen = fieldTok.length < (int)sizeof(propBuf) - 1
                       ? fieldTok.length : (int)sizeof(propBuf) - 1;
            memcpy(propBuf, fieldTok.start, (size_t)plen);
            propBuf[plen] = '\0';
            const OwlControlPropDef* pdef = owl_control_catalog_find(kind, propBuf);
            /*  — au point simple, le nom qui suit peut designer un
             * MEMBRE et non une propriete : une colonne de Table
             * (`TABLE_X[l].COL_A`, `TABLE_X.COL_A[l]`), un sous-champ de
             * ZoneRepetee (`ZR_L[l].LIB_R`), un controle qualifie par sa
             * fenetre (`FEN_A.SAI_X`). Ces designations sont legitimes : on
             * ne leur applique aucun controle de propriete. Reconnaissance
             * par le pre-scan (enfant nomme du receveur, ou nom de controle
             * declare) — permissive par construction, elle ne peut que
             * laisser passer, jamais refuser a tort. */
            bool dotMember = !isDoubleDot
                && (prescan_widget_has_child(nameBuf, propBuf)
                    || compiler_prescan_widget_find(propBuf) != NULL);
            /* Un diagnostic plus precis a deja parle : le refus d'operateur
             * du point simple est un dernier recours, il ne le double pas. */
            bool propDiag = dotMember;
            /*  : prop inconnue sur widget DSL type accede en code
             * (`SAI_X..Texte`, `BTN_X..Bidule = ...`). Le compilateur connait
             * le kind (prescan) et le catalogue de props : une prop hors
             * catalog est rejetee a la compile, symetriquement au check du
             * bloc PROPRIETES. Couvre lecture ET ecriture (ce point precede
             * le traitement de l'affectation). Le `kind` affiche est la forme
             * canon accentuee (info->nameFR), pas la forme ASCII de
             * owl_control_kind_name.
             *
             * Garde prev_field_name_len == 0 : on ne valide QUE le premier
             * dot de la chaine (acces direct widget). Un sous-acces apres une
             * prop VARIANT non type-propagee (`BTN_X..Groupe..Occurrence`) a
             * recvType == NULL mais prev_field_name != "" : ce n'est plus une
             * prop widget, c'est une prop runtime de la valeur intermediaire,
             * non verifiable a la compile. Les props OBJECT (`..Cadre..Coin`)
             * propagent g_last_field_type et passent par le check riche des
             * champs de type compose plus bas (recvType != NULL). */
            /*  — receveur INDEXE (`TABLE_X[ligne]..`,
             * `TABLE_X[ligne][colonne]..`) : le catalogue a interroger n'est pas
             * celui du widget mais celui de la cellule/ligne. Ce controle-ci
             * lit receiverTok, qui reste le nom de la Table quels que soient les
             * crochets traverses : sans cette garde il rejetait Couleur comme
             * « inconnue pour Table ». La validation du receveur indexe est
             * faite plus haut ( + abstention ) : un nom qui
             * n'est ni une colonne ni une prop de mise en forme y est refuse. */
            if (!dotMember && pdef == NULL && prev_field_name_len == 0
                && tblChainTableLen == 0
                && !owl_ui_prop_is_universal(propBuf)) {
                owl_emit_error_at(&fieldTok, E_SEM_DSL_PROP_UNKNOWN_FOR_KIND,
                                  "prop", propBuf,
                                  "kind", info->nameFR,
                                  NULL);
                propDiag = true;
            }
            /*  — ..Nom/..Name : prop universelle LECTURE SEULE. La
             * lecture compile (universelle), l'ECRITURE est rejetee ici : le
             * nom est l'identite declaree, non reassignable. */
            if (!dotMember && owl_ui_prop_is_universal_readonly(propBuf)
                && prev_field_name_len == 0
                && canAssign && check(TOKEN_EQUAL)) {
                owl_emit_error_at(&fieldTok, E_SEM_DSL_PROP_IDENTITY_READONLY,
                                  "prop", propBuf,
                                  NULL);
                propDiag = true;
            }
            /*  — prop design-init (readonly_runtime) : ecrivable dans
             * le bloc PROPRIETES mais lecture seule en code imperatif. Ici on
             * est sur le chemin imperatif (`WIDGET..prop = ...`, hors
             * control_parse_property_init). On rejette la seule ECRITURE
             * (canAssign + `=` en peek) ; la lecture reste autorisee. */
            if (!dotMember && pdef && pdef->readonly_runtime
                && prev_field_name_len == 0
                && canAssign && check(TOKEN_EQUAL)) {
                owl_emit_error_at(&fieldTok, E_SEM_DSL_PROP_READONLY_RUNTIME,
                                  "prop", pdef->nameFR,
                                  NULL);
                propDiag = true;
            }
            /*  — le point simple n'est jamais l'operateur de
             * propriete. Dernier recours : la propriete existe, rien d'autre
             * ne cloche, seule la graphie est fautive. La cascade s'arrete
             * ici — aucune propagation de type sous une racine refusee, donc
             * un seul diagnostic au bon niveau. */
            if (!isDoubleDot && !propDiag && prev_field_name_len == 0
                && tblChainTableLen == 0) {
                owl_emit_error_at(&fieldTok, E_SEM_PROP_USE_DOUBLE_DOT,
                                  "field", propBuf,
                                  "type", info->nameFR,
                                  NULL);
            }
            if (isDoubleDot && pdef && pdef->type == OWL_PROP_TYPE_OBJECT
                && pdef->object_type
                && prev_field_name_len == 0) {
                /* Garde prev_field_name_len == 0 (, cohérence avec les
                 * gardes 'prop inconnue' et 'readonly' ci-dessus) : on ne valide/
                 * propage QUE l'acces direct `WIDGET..PropObjet`. Un ref qualifié
                 * cross-fichier `FEN.CTRL..PropObjet` a receiverTok = la racine
                 * (FEN) mais un receveur immediat = CTRL : la valider contre le
                 * catalogue de la racine est faux (cas Style, present sur la
                 * Fenetre ET les widgets). Ces refs se resolvent au runtime. */
                /* Affectation scalaire directe interdite : `WIDGET..Cadre = <scalaire>`.
                 * On detecte `=` suivi d'un litteral scalaire (entier/reel/chaine/
                 * booleen). Une instance composee passe par une variable ou un
                 * litteral `{...}`, autorisees. */
                if (canAssign && check(TOKEN_EQUAL)) {
                    Scanner savedSc = parser.scanner;
                    Token savedCur = parser.current;
                    Token savedPrev = parser.previous;
                    bool savedCrossed = crossedNewline;
                    advance_token(); /* consume '=' */
                    bool scalar =
                        check(TOKEN_INTEGER) || check(TOKEN_REAL) ||
                        check(TOKEN_STRING)  ||
                        check(TOKEN_VRAI)    || check(TOKEN_FAUX);
                    const char* gotType =
                        check(TOKEN_INTEGER) ? "entier" :
                        check(TOKEN_REAL)    ? "r\xc3\xa9" "el" :
                        check(TOKEN_STRING)  ? "chaine" :
                        (check(TOKEN_VRAI) || check(TOKEN_FAUX)) ? "bool\xc3\xa9" "en" :
                        "valeur";
                    /*  — RHS identifiant nu d'un type objet incompatible
                     * avec object_type attendu (subsume `SAI..Style = <Cadre>`).
                     * Un sous-type de object_type reste accepte (heritage). */
                    bool objMismatch = false;
                    Token rhsTok = parser.current;
                    const char* rhsStruct = NULL;
                    if (!scalar && check(TOKEN_IDENTIFIER)) {
                        rhsStruct = resolve_var_struct_type(parser.current.start,
                                                            parser.current.length);
                        if (rhsStruct != NULL && rhsStruct[0] != '\0'
                            && !struct_name_is_multilingue(rhsStruct)
                            && current_identifier_is_isolated()
                            /*  — base Style generique accepte comme
                             * fallback sur un slot type styleXxx (Fenetre..Style
                             * = STY_base). Ne pas le rejeter en mismatch objet. */
                            && !(is_style_type_name(pdef->object_type)
                                 && is_base_style_type_name(rhsStruct))
                            && !class_is_same_or_derived(
                                    rhsStruct, (int)strlen(rhsStruct),
                                    pdef->object_type,
                                    (int)strlen(pdef->object_type))) {
                            objMismatch = true;
                        }
                    }
                    /*  — genre de style incompatible avec le genre du
                     * champ recepteur (`BTN..Style = theme.saiSaisie` ou un
                     * STY_ global du mauvais genre). Prioritaire sur le mismatch
                     * objet generique : message dedie citant les deux genres. */
                    char styleGot[64];
                    char styleDesig[160];
                    bool styleKindMismatch = false;
                    if (!scalar && is_style_type_name(pdef->object_type)
                        && style_rhs_resolve_type(styleGot, sizeof(styleGot),
                                                  styleDesig, sizeof(styleDesig))
                        && !is_base_style_type_name(styleGot)
                        && !style_type_names_equal(pdef->object_type, styleGot)) {
                        styleKindMismatch = true;
                    }
                    /*  — `WIDGET..Style = theme.<nom>` avec un nom de
                     * style inconnu du projet : avertissement non bloquant. */
                    Token unknownTok;
                    bool themeRefUnknown =
                        !scalar && is_style_type_name(pdef->object_type)
                        && style_rhs_theme_ref_undeclared(&unknownTok);
                    /* Restaure l'etat parser pour ne pas perturber la suite. */
                    parser.scanner = savedSc;
                    parser.current = savedCur;
                    parser.previous = savedPrev;
                    crossedNewline = savedCrossed;
                    if (themeRefUnknown) {
                        char nameBuf[128];
                        snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                                 unknownTok.length, unknownTok.start);
                        owl_emit_warning_at(&unknownTok,
                                            W_SEM_THEME_STYLE_UNDECLARED,
                                            "nom", nameBuf, NULL);
                    }
                    if (scalar) {
                        owl_emit_error_at(&fieldTok, E_SEM_DSL_OBJECT_PROP_SCALAR,
                                          "type", pdef->object_type,
                                          "got", gotType,
                                          NULL);
                    } else if (styleKindMismatch) {
                        char fieldBuf[128];
                        snprintf(fieldBuf, sizeof(fieldBuf), "%.*s",
                                 receiverTok.length, receiverTok.start);
                        owl_emit_error_at(&rhsTok, E_SEM_STYLE_KIND_MISMATCH,
                                          "field", fieldBuf,
                                          "kind", info->nameFR,
                                          "expected", pdef->object_type,
                                          "style", styleDesig,
                                          "got", styleGot,
                                          NULL);
                    } else if (objMismatch) {
                        char targetBuf[256];
                        snprintf(targetBuf, sizeof(targetBuf), "%.*s..%.*s",
                                 receiverTok.length, receiverTok.start,
                                 fieldTok.length, fieldTok.start);
                        owl_emit_error_at(&rhsTok, E_SEM_DSL_OBJECT_PROP_TYPE_MISMATCH,
                                          "target", targetBuf,
                                          "got", rhsStruct,
                                          "expected", pdef->object_type,
                                          NULL);
                    }
                }
                int copy = (int)strlen(pdef->object_type);
                if (copy > 63) copy = 63;
                memcpy(g_last_field_type, pdef->object_type, copy);
                g_last_field_type[copy] = '\0';
                g_last_field_type_len = copy;
                g_last_field_from_ui_object = true;
            }
        }
    }

    /*  — `..` est le seul operateur de propriete : derriere une classe
     * utilisateur, tout nom designe un membre ou une methode, jamais une
     * propriete. Symetrique du refus structure ci-dessous.
     *
     * Pose AVANT le gate `!check(TOKEN_LEFT_PAREN)`, qui exclut les appels :
     * `o..Methode()` est justement l'une des deux formes fautives, et la plus
     * couteuse — elle ne resolvait aucune methode, lisait un champ inexistant
     * et rendait la valeur par defaut sans un mot.
     *
     * recvType/user_type_index couvrent le cas cross-fichier : le prescan
     * projet enregistre les noms de classes des fichiers voisins (mesure :
     * `cible est un cBase` avec cBase declare ailleurs resout kind CLASSE).
     *
     * (prev_field_name_len == 0 || recvTypeFromChain) : au-dela du 1er dot,
     * recvType ne vaut que s'il a ete propage. Sans ca, `obj.dico..Occurrence`
     * — Occurrence est une vraie propriete du tableau associatif membre —
     * serait refuse sur la foi du type de la racine, qui n'est plus le
     * receveur. Mesure : au 2e dot, recvType retombe sur la classe racine
     * alors que le receveur reel est le membre. */
    bool classDotDiag = false;
    if (recvType != NULL && isDoubleDot
        && (prev_field_name_len == 0 || recvTypeFromChain)) {
        int rtl = (int)strlen(recvType);
        int idx = user_type_index(recvType, rtl);
        if (idx >= 0 && knownUserTypes[idx].kind == OWL_USER_TYPE_CLASSE) {
            char fieldBuf[128];
            snprintf(fieldBuf, sizeof(fieldBuf), "%.*s",
                     fieldTok.length, fieldTok.start);
            owl_emit_error_at(&fieldTok, E_SEM_CLASS_USE_SIMPLE_DOT,
                              "type", recvType,
                              "field", fieldBuf,
                              NULL);
            classDotDiag = true;
        }
    }

    if (recvType && !check(TOKEN_LEFT_PAREN)) {
        {
            int rtl = (int)strlen(recvType);
            int idx = user_type_index(recvType, rtl);
            /*  — type_name_is_structure (et non kind==STRUCTURE) : au
             * prescan projet, une struct compagnon est enregistree kind UNKNOWN
             * (fields ajoutes plus tard). Le repli SYM_STRUCT de la table de
             * symboles rend le verdict correct cross-fichier, ce que kind==1
             * seul manquait (refus `..prop` absent sur struct compagnon). */
            if (type_name_is_structure(recvType, rtl) && isDoubleDot) {
                /*  — garde miroir du refus classe, affinee.
                 * Au-dela du 1er dot ET sans type propage (recvType retombe sur
                 * la structure RACINE, plus le receveur reel), on ne refuse QUE
                 * si le champ precedent est un SCALAIRE. Si c'est un conteneur
                 * (`s.reqs..Occurrence`) ou un composite (`s.req..URL`,
                 * `s.reqs["k"]..URL`), `..prop` s'applique legitimement au champ
                 * et non a la structure : pas de faux refus. Le cas propage
                 * (recvTypeFromChain, ex. sous-structure `s.adr..Ville`) garde le
                 * refus strict — `..` sur un membre reste fautif. */
                bool suppress = false;
                if (prev_field_name_len > 0 && !recvTypeFromChain) {
                    const UserTypeField* pf = user_type_find_field(
                        recvType, rtl, prev_field_name, prev_field_name_len);
                    if (field_supports_property_access(pf)) suppress = true;
                }
                if (!suppress) {
                    char fieldBuf[128];
                    snprintf(fieldBuf, sizeof(fieldBuf), "%.*s",
                             fieldTok.length, fieldTok.start);
                    owl_emit_error_at(&fieldTok, E_SEM_STRUCT_USE_SIMPLE_DOT,
                                      "type", recvType,
                                      "field", fieldBuf,
                                      NULL);
                }
            } else if (idx >= 0 && knownUserTypes[idx].kind == 1) {
                const UserTypeField* fld = user_type_find_field(recvType, rtl, fieldTok.start, fieldTok.length);
                if (fld && fld->typeLen > 0 && is_known_user_type(fld->typeName, fld->typeLen)) {
                    int copy = fld->typeLen < 63 ? fld->typeLen : 63;
                    memcpy(g_last_field_type, fld->typeName, copy);
                    g_last_field_type[copy] = '\0';
                    g_last_field_type_len = copy;
                }
                if (fld == NULL) {
                    /* Construit la liste " (champs : a, b, c)." ou
                     * " (aucun champ declare)." comme placeholder unique
                     * {fields_list} (cf.  +  design
                     * "string pre-construite" pour listes dynamiques). */
                    char listBuf[384];
                    int loff = 0;
                    if (knownUserTypes[idx].fieldCount > 0) {
                        loff += snprintf(listBuf + loff,
                                         sizeof(listBuf) - loff,
                                         " (champs : ");
                        bool firstField = true;
                        for (int fi = knownUserTypes[idx].fieldFirst;
                             fi >= 0 && loff < (int)sizeof(listBuf) - 8;
                             fi = userTypeFieldPool[fi].next) {
                            loff += snprintf(listBuf + loff,
                                             sizeof(listBuf) - loff,
                                             "%s%s",
                                             firstField ? "" : ", ",
                                             userTypeFieldPool[fi].name);
                            firstField = false;
                        }
                        snprintf(listBuf + loff, sizeof(listBuf) - loff, ")");
                    } else {
                        snprintf(listBuf, sizeof(listBuf),
                                 " (aucun champ declare)");
                    }
                    char fieldBuf[128];
                    snprintf(fieldBuf, sizeof(fieldBuf), "%.*s",
                             fieldTok.length, fieldTok.start);
                    owl_emit_error_at(&fieldTok, E_SEM_STRUCT_FIELD_UNKNOWN,
                                      "field", fieldBuf,
                                      "type", recvType,
                                      "fields_list", listBuf,
                                      NULL);
                }
            } else if (idx < 0 && isDoubleDot && recvFromUiObject) {
                /* recvType n'est pas une structure user-declaree, mais un type
                 * compose builtin (Cadre, Style, Police...) atteint via une
                 * cascade de prop UI OBJECT : `LIB_X..Cadre..SousChamp` a
                 * propage g_last_field_type = "Cadre" plus haut (voir bloc UI
                 * prop OBJECT). On valide le champ contre le template vm.globals
                 * et on propage le type des sous-objets pour la cascade suivante.
                 * Garde recvFromUiObject : une variable builtin declaree
                 * (`c est un Chrono` ; `c..Coin`) garde la voie OwlTypeDef plus
                 * bas, qui produit le message riche listant les proprietes. */
                ObjString* tk = obj_copy_string(recvType, rtl);
                vm_push(OBJ_VAL(tk));
                Value templateVal;
                bool ft = table_get(&vm.types, tk, &templateVal);  /*  Phase 1. */
                if (!ft) ft = table_get(&vm.globals, tk, &templateVal);
                vm_pop();
                if (ft && IS_INSTANCE(templateVal)) {
                    ObjInstance* tpl = AS_INSTANCE(templateVal);
                    char fieldAscii[64];
                    int n = scanner_strip_accents(fieldTok.start, fieldTok.length,
                                                  fieldAscii, sizeof(fieldAscii));
                    if (n <= 0) n = fieldTok.length < 63 ? fieldTok.length : 63;
                    fieldAscii[n] = '\0';
                    ObjString* fk = obj_copy_string(fieldAscii, n);
                    Value fv;
                    bool fieldFound = table_get(&tpl->fields, fk, &fv);
                    if (!fieldFound) {
                        /*  — fallback bilingue EN->FR (complement du
                         * fix 0143). La cascade OBJECT strip les accents mais ne
                         * resolvait pas la forme EN : `..Font..Name` echouait a
                         * tort alors que le runtime resout `Name` -> `Nom`. On
                         * retente via la meme helper registry pour preserver
                         * l'invariant bilingue. Benefice retroactif a Cadre
                         * (`..Border..Color`) et tout type compose UI. */
                        const char* canon = owl_registry_resolve_field_en_to_canon(
                            recvType, fieldAscii);
                        if (canon != NULL) {
                            ObjString* ck = obj_copy_string(canon,
                                                            (int)strlen(canon));
                            fieldFound = table_get(&tpl->fields, ck, &fv);
                        }
                    }
                    if (fieldFound) {
                        /* Champ connu : propage le type pour la cascade. */
                        if (IS_INSTANCE(fv)) {
                            ObjInstance* sub = AS_INSTANCE(fv);
                            if (sub->structName && sub->structName->length > 0) {
                                int copy = sub->structName->length < 63
                                           ? sub->structName->length : 63;
                                memcpy(g_last_field_type, sub->structName->chars, copy);
                                g_last_field_type[copy] = '\0';
                                g_last_field_type_len = copy;
                                /* Maintient la voie template vm.globals pour le
                                 * sous-champ suivant de la cascade UI OBJECT. */
                                g_last_field_from_ui_object = true;
                            }
                        }
                    } else {
                        char fieldBuf[128];
                        snprintf(fieldBuf, sizeof(fieldBuf), "%.*s",
                                 fieldTok.length, fieldTok.start);
                        /* Liste les champs valides du type compose cible
                         * (Cadre, ...) sur le modele du message riche des
                         * types DSL declares (emit_unknown_member_error).
                         * On itere la declaration registry (OwlTypeDef) et
                         * non le template runtime (Table) pour garantir
                         * l'ordre de declaration et non l'ordre de hash. */
                        const OwlTypeDef* td = owl_registry_type_find(recvType);
                        size_t cap = 256;
                        char* list = (char*)malloc(cap);
                        size_t llen = 0;
                        if (list != NULL) {
                            list[0] = '\0';
                            bool first = true;
                            if (td != NULL) {
                                for (const OwlField* f = td->fields;
                                     f && f->name; f++) {
                                    if (f->name[0] == '_') continue;
                                    const char* show = f->nameAccented
                                                       ? f->nameAccented : f->name;
                                    size_t sepLen = first ? 0 : 2;
                                    size_t showLen = strlen(show);
                                    size_t need = llen + sepLen + showLen + 1;
                                    if (need > cap) {
                                        while (cap < need) cap *= 2;
                                        char* grown = (char*)realloc(list, cap);
                                        if (grown == NULL) break;
                                        list = grown;
                                    }
                                    if (!first) { memcpy(list + llen, ", ", 2); llen += 2; }
                                    memcpy(list + llen, show, showLen);
                                    llen += showLen;
                                    first = false;
                                }
                            }
                            list[llen < cap ? llen : cap - 1] = '\0';
                        }
                        owl_emit_error_at(&fieldTok, E_SEM_DSL_OBJECT_PROP_FIELD_UNKNOWN,
                                          "field", fieldBuf,
                                          "type", recvType,
                                          "fields_list", list ? list : "",
                                          NULL);
                        free(list);
                    }
                }
            }
        }

        /*  : visibilité POO compile-time. On regarde si le receveur
         * est une CLASSE connue et si le field ciblé a une visibilité PRIVE
         * ou PROTEGE incompatible avec le scope d'accès courant.
         * Skip si on est suivi de '(' (appel de méthode — V1 toutes publiques,
         * cf. ticket POO/7 dédié pour visibilité méthodes). */
        {
            int rtl = (int)strlen(recvType);
            int idx = user_type_index(recvType, rtl);
            bool isClass = (idx >= 0 && knownUserTypes[idx].kind == OWL_USER_TYPE_CLASSE);
            /* Fallback cross-file : si idx<0 (knownUserTypes a été reset entre
             * fichiers), on consulte directement la table persistante. Pas
             * d'is_known_class explicite : si le field n'est pas dans la
             * table de visibilité, on n'a rien à dire (PUBLIC implicite). */
            const char* ownerStart = NULL;
            int ownerLen = 0;
            int vis = class_field_vis_lookup_inherited(
                recvType, rtl,
                fieldTok.start, fieldTok.length,
                &ownerStart, &ownerLen);
            /* !classDotDiag : l'operateur vient d'etre refuse sur ce field.
             * Un seul diagnostic par site — la visibilite reparlera une fois
             * la graphie corrigee. */
            if (!classDotDiag && (isClass || vis >= 0)
                && vis >= 0 && vis != OWL_VIS_PUBLIC) {
                /* Scope d'accès courant : nom de la classe en cours de compile
                 * (currentClass) ou NULL si on est hors-classe. */
                const char* scopeStart = NULL;
                int scopeLen = 0;
                if (currentClass) {
                    scopeStart = currentClass->name.start;
                    scopeLen   = currentClass->name.length;
                }
                bool allowed = false;
                if (vis == OWL_VIS_PRIVE) {
                    /* Autorisé UNIQUEMENT depuis du code de la classe
                     * propriétaire (pas une dérivée). */
                    if (scopeStart && ownerStart &&
                        scopeLen == ownerLen &&
                        strncasecmp(scopeStart, ownerStart, (size_t)scopeLen) == 0) {
                        allowed = true;
                    }
                } else if (vis == OWL_VIS_PROTEGE) {
                    /* Autorisé depuis la classe OU une dérivée. */
                    if (scopeStart && ownerStart &&
                        class_is_same_or_derived(scopeStart, scopeLen,
                                                 ownerStart, ownerLen)) {
                        allowed = true;
                    }
                }
                if (!allowed) {
                    char fieldBuf[128], classBuf[128];
                    snprintf(fieldBuf, sizeof(fieldBuf), "%.*s",
                             fieldTok.length, fieldTok.start);
                    snprintf(classBuf, sizeof(classBuf), "%.*s",
                             ownerLen, ownerStart);
                    OwlErrorCode code = (vis == OWL_VIS_PRIVE)
                        ? E_SEM_MEMBER_PRIVATE
                        : E_SEM_MEMBER_PROTECTED;
                    owl_emit_error_at(&fieldTok, code,
                                      "field", fieldBuf,
                                      "class", classBuf,
                                      NULL);
                }
            }
        }
    }

    /* Resolve field metadata (allowedBase enum) at compile time if the
     * receiver's type is a registered OwlTypeDef.
     *
     * Strict dot enforcement (alpha) :
     *   '..X' obligatoire pour les propriétés de templates DSL (OwlField).
     *   '.X(…)' obligatoire pour les méthodes (owl_register_method).
     * Mismatch → erreur compile-time avec message explicite. */
    const OwlParam* fieldAsParam = NULL;  /* synthetic: wraps the field's allowed enums */
    OwlParam syntheticField = {0};
    /* Strict dot check : recvType est resolu plus haut, gagnant g_last_field_type
     * pour les chaînes (style..Cadre..Arrondi). Si on chaîne au-travers
     * d'un type non resolu (ex. tableau associatif), g_chain_broken empêche
     * de retomber par erreur sur le receiver original.
     *
     *  — un type utilisateur homonyme d'un type registry (ex.
     * `Couleur est une Structure` masquant le type integre Couleur) MASQUE
     * le canon dans toutes les positions. La validation registry ci-dessous
     * (template OwlTypeDef) ne doit alors PAS s'appliquer : c'est le bloc
     * user-type plus haut (user_type_find_field / E_SEM_STRUCT_USE_SIMPLE_DOT)
     * qui fait foi. Sans homonyme declare, is_known_user_type est faux et le
     * canon registry reste seul maitre (invariant 6.5 intact : une native et
     * un type peuvent partager un nom, ici c'est un TYPE user qui masque). */
    if (recvType != NULL && !g_chain_broken
        && !is_known_user_type(recvType, (int)strlen(recvType))) {
        const char* typeName = recvType;
        {
            const OwlTypeDef* td = owl_registry_type_find(typeName);
            if (td && td->fields) {
                /* Field match: accent/case insensitive on name, nameAccented, ou nameEN. */
                const OwlField* matchedField = NULL;
                char qStrip[64];
                int ql = scanner_strip_accents(fieldTok.start, fieldTok.length,
                                               qStrip, sizeof(qStrip));
                if (ql <= 0) {
                    ql = fieldTok.length < 63 ? fieldTok.length : 63;
                    memcpy(qStrip, fieldTok.start, (size_t)ql);
                    qStrip[ql] = '\0';
                }
                for (const OwlField* f = td->fields; f->name; f++) {
                    /* Skip champs internes prefixes par underscore (_handle, etc.). */
                    if (f->name[0] == '_') continue;
                    bool match = inline_field_name_matches(qStrip, ql, f->name)
                        || (f->nameAccented
                            && inline_field_name_matches(qStrip, ql, f->nameAccented))
                        || (f->nameEN
                            && inline_field_name_matches(qStrip, ql, f->nameEN));
                    if (match) { matchedField = f; break; }
                }

                bool isField  = (matchedField != NULL);
                bool isMethod = owl_method_exists_for_type_name(typeName,
                                    fieldTok.start, fieldTok.length);
                bool followedByParen = check(TOKEN_LEFT_PAREN);

                /* Discrimination strict :
                 *   '..X'  → propriete (OwlField)
                 *   '.X(…)' → methode (owl_register_method)
                 * Cas dual (field ET method, ex. Chrono.Valeur) : la forme
                 * dot/parens decide laquelle est referencee. */
                char fieldBuf[128];
                snprintf(fieldBuf, sizeof(fieldBuf), "%.*s",
                         fieldTok.length, fieldTok.start);
                if (isDoubleDot) {
                    if (isField && followedByParen) {
                        owl_emit_error_at(&fieldTok, E_SEM_PROP_NOT_A_METHOD,
                                          "field", fieldBuf,
                                          "type", typeName,
                                          NULL);
                    } else if (!isField && isMethod) {
                        owl_emit_error_at(&fieldTok, E_SEM_METHOD_USE_SIMPLE_DOT,
                                          "field", fieldBuf,
                                          "type", typeName,
                                          NULL);
                    } else if (!isField && !isMethod) {
                        emit_unknown_member_error(fieldTok, typeName, td);
                    }
                    /* isField && !followedByParen → OK (lecture/ecriture propriete) */
                } else {
                    /* Simple point */
                    if (isMethod && !followedByParen && !isField) {
                        owl_emit_error_at(&fieldTok, E_SEM_METHOD_MISSING_PARENS,
                                          "field", fieldBuf,
                                          "type", typeName,
                                          NULL);
                    } else if (isField && !isMethod && !followedByParen) {
                        owl_emit_error_at(&fieldTok, E_SEM_PROP_USE_DOUBLE_DOT,
                                          "field", fieldBuf,
                                          "type", typeName,
                                          NULL);
                    } else if (isField && !isMethod && followedByParen) {
                        owl_emit_error_at(&fieldTok, E_SEM_PROP_NOT_A_METHOD,
                                          "field", fieldBuf,
                                          "type", typeName,
                                          NULL);
                    } else if (!isField && !isMethod) {
                        emit_unknown_member_error(fieldTok, typeName, td);
                    }
                    /* isMethod && followedByParen → OK (appel methode) */
                }

                /* Propagation du type du field pour les chaînes (ex.
                 * style..Cadre..Arrondi : apres ..Cadre on doit savoir
                 * que la suite est sur un Cadre). On propage seulement
                 * si le type est un nom simple (pas "tableau de chaines"
                 * etc.). Pas besoin que le type soit registre OwlTypeDef —
                 * si pas registre, le strict check du prochain dot
                 * skip silencieusement (cas Coin/Trait sub-templates). */
                if (matchedField && matchedField->type) {
                    const char* t = matchedField->type;
                    bool simple_name = true;
                    for (const char* p = t; *p; p++) {
                        if (*p == ' ' || *p == '\t') { simple_name = false; break; }
                    }
                    if (simple_name) {
                        int copy = (int)strlen(t);
                        if (copy > 63) copy = 63;
                        memcpy(g_last_field_type, t, copy);
                        g_last_field_type[copy] = '\0';
                        g_last_field_type_len = copy;
                    } else {
                        /* Type non-simple (tableau, etc.) : chaîne suivante
                         * skip strict check (ne pas retomber sur receiver). */
                        g_chain_broken = true;
                    }
                }

                if (matchedField &&
                    (matchedField->allowedBase || matchedField->allowedOptions)) {
                    syntheticField.name          = matchedField->name;
                    syntheticField.type          = matchedField->type;
                    syntheticField.allowedBase   = matchedField->allowedBase;
                    syntheticField.allowedOptions= matchedField->allowedOptions;
                    fieldAsParam = &syntheticField;
                }
            }
        }
    }

    /* Strict dot check fallback : types builtin sans OwlTypeDef enregistré.
     * Couvre tableau, file/pile/liste, JSON, date, heure, dateheure, durée.
     * Mirrors la logique du strict check OwlTypeDef plus haut, avec deux
     * différences :
     *   - on consulte BuiltinKindProp tables (pas OwlField)
     *   - on identifie les méthodes via owl_method_exists_for_type_name avec
     *     le nom canonique du kind (cf builtin_kind_name_for + alias scanner).
     * Cas dual « propriété ET méthode » (ex. Date.Annee) : `..Annee` ⇒ prop,
     * `.Annee()` ⇒ méthode. La forme mal appariée déclenche une erreur. */
    if (g_last_field_type_len == 0 && !g_chain_broken && receiverTok.length > 0) {
        int kind = resolve_var_declared_type(receiverTok.start, receiverTok.length);
        const BuiltinKindProp* table = builtin_kind_props_for(kind);
        if (table) {
            const BuiltinKindProp* prop = builtin_kind_lookup_prop(
                table, fieldTok.start, fieldTok.length);
            const char* kindName = builtin_kind_name_for(kind);
            bool isProp = (prop != NULL);
            bool isMethod = owl_method_exists_for_type_name(kindName,
                                fieldTok.start, fieldTok.length);
            bool followedByParen = check(TOKEN_LEFT_PAREN);

            char fieldBuf[128];
            snprintf(fieldBuf, sizeof(fieldBuf), "%.*s",
                     fieldTok.length, fieldTok.start);
            /*  — un JSON n'expose que trois proprietes (Occurrence,
             * Vide, Type) ; tout autre nom derriere un point est une clef de
             * l'objet, donc un membre. Le double point y est faux et passait
             * jusqu'ici sans un mot. Borne au JSON : sur les autres kinds
             * builtin, un nom inconnu reste silencieux comme avant. */
            if (!isProp && !isMethod && isDoubleDot && kind == TOKEN_JSON_KW) {
                owl_emit_error_at(&fieldTok, E_SEM_JSON_USE_SIMPLE_DOT,
                                  "field", fieldBuf,
                                  NULL);
            }
            if (isProp || isMethod) {
                if (isDoubleDot) {
                    if (isProp && followedByParen) {
                        owl_emit_error_at(&fieldTok, E_SEM_PROP_NOT_A_METHOD,
                                          "field", fieldBuf,
                                          "type", kindName,
                                          NULL);
                    } else if (!isProp && isMethod) {
                        owl_emit_error_at(&fieldTok, E_SEM_METHOD_USE_SIMPLE_DOT,
                                          "field", fieldBuf,
                                          "type", kindName,
                                          NULL);
                    }
                    /* isProp && !followedByParen → OK (canon propriété) */
                } else {
                    /* Simple point */
                    if (isMethod && followedByParen) {
                        /* OK : appel de méthode canon */
                    } else if (isMethod && !followedByParen && !isProp) {
                        owl_emit_error_at(&fieldTok, E_SEM_METHOD_MISSING_PARENS,
                                          "field", fieldBuf,
                                          "type", kindName,
                                          NULL);
                    } else if (isProp && !followedByParen) {
                        owl_emit_error_at(&fieldTok, E_SEM_PROP_USE_DOUBLE_DOT,
                                          "field", fieldBuf,
                                          "type", kindName,
                                          NULL);
                    } else if (isProp && !isMethod && followedByParen) {
                        owl_emit_error_at(&fieldTok, E_SEM_PROP_NO_PARENS,
                                          "field", fieldBuf,
                                          "type", kindName,
                                          NULL);
                    }
                }
            }
        }
    }

    /*  : si receveur = nom de Classe et field = constante de cette
     * classe, toute forme d'ecriture (`= <= += -= *= /= %= ++ --`) est
     * rejetee au compile-time. La forme `cClasse.<champ>` cible un membre
     * statique : si ce membre est marque CONSTANT, c'est read-only. */
    if (receiverTok.length > 0 &&
        is_known_user_type(receiverTok.start, receiverTok.length) &&
        class_constant_is(receiverTok.start, receiverTok.length,
                          fieldTok.start, fieldTok.length)) {
        bool isWrite = check(TOKEN_EQUAL) || check(TOKEN_LESS_EQUAL) ||
                       check(TOKEN_PLUS_EQUAL) || check(TOKEN_MINUS_EQUAL) ||
                       check(TOKEN_STAR_EQUAL) || check(TOKEN_SLASH_EQUAL) ||
                       check(TOKEN_PERCENT_EQUAL) ||
                       check(TOKEN_PLUS_PLUS) || check(TOKEN_MINUS_MINUS);
        if (isWrite && canAssign) {
            char fieldBuf[128], classBuf[128];
            snprintf(fieldBuf, sizeof(fieldBuf), "%.*s",
                     fieldTok.length, fieldTok.start);
            snprintf(classBuf, sizeof(classBuf), "%.*s",
                     receiverTok.length, receiverTok.start);
            owl_emit_error_at(&fieldTok, E_SEM_CLASS_CONSTANT_READ_ONLY,
                              "field", fieldBuf,
                              "class", classBuf,
                              NULL);
        }
    }

    if (canAssign && match_token(TOKEN_EQUAL)) {
        /*  — membre droit absent en fin de ligne (crossedNewline pose
         * par advance_token qui a skippe le NEWLINE significatif apres `=`). On
         * refuse ici, ancre sur le `=`, plutot que d'aspirer le 1er token de la
         * ligne suivante comme valeur de la propriete. Cf. named_variable. */
        if (crossedNewline) {
            owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR);
            return;
        }
        /*  — contrat de signature callback : `recv..prop = MaProc`.
         * Vérif arité + types EXACTS quand prop est un field registry
         * "procédure" et MaProc une PROCEDURE top-level connue. */
        if (isDoubleDot && !g_chain_broken) {
            check_callback_signature_assignment(recvType, fieldTok, receiverTok);
        }
        /*  — Detection icone non-coloriable a `..Couleur = ...`.
         * Deux cas trackes :
         *   (A) Pattern direct `icones.X..Couleur = val` : au 2e dot,
         *       receiverTok = "icones" (token racine de la chaine) et
         *       prev_field_name = "X" (1er field accedé, snapshot pris en
         *       tete de dot()).
         *   (B) Pattern locale `loc..Couleur = val` ou loc typee Icone et
         *       slot taggee : recvType == "Icone", la slot porte un
         *       icone_catalog_name non-NULL (pose a l'init / re-assign).
         *
         * Le warning est emis sur le token `Couleur` (fieldTok). Pas de
         * suppression V1.
         *  : accepte aussi la forme EN canon `Color` (len 5) de la
         * propriete Couleur ; sans ca `icn..Color = ...` ne levait pas le
         * warning non-coloriable. */
        bool fieldIsCouleur =
            (fieldTok.length == 7 && strncasecmp(fieldTok.start, "Couleur", 7) == 0) ||
            (fieldTok.length == 5 && strncasecmp(fieldTok.start, "Color", 5) == 0);
        if (isDoubleDot && fieldIsCouleur) {
            const OwlIconCatalogEntry* iconeEntry = NULL;
            /* Cas A : icones.X..Couleur */
            if (receiverTok.length == 6 &&
                strncasecmp(receiverTok.start, "icones", 6) == 0 &&
                prev_field_name_len > 0) {
                iconeEntry = owl_icones_catalog_find(prev_field_name);
            }
            /* Cas B : slot Icone taggee via Local.icone_catalog_name.
             * Skip si Cas A a deja trouve.  : accept "Icône"
             * (canon FR avec accent) ET "Icone" (ASCII fallback). */
            if (iconeEntry == NULL && recvType != NULL &&
                (strcasecmp(recvType, "Icone") == 0
                 || strcasecmp(recvType, "Icône") == 0)
                && receiverTok.length > 0) {
                Token rnameTok = receiverTok;
                int slot = resolve_local(current, &rnameTok);
                if (slot >= 0 && slot < UINT8_COUNT &&
                    current->locals[slot].icone_catalog_name != NULL) {
                    iconeEntry = owl_icones_catalog_find(
                        current->locals[slot].icone_catalog_name);
                }
            }
            icone_emit_not_colorable_warning_if(iconeEntry, &fieldTok);
        }
        Token rhsFirst = parser.current;
        /*  : `WIDGET..Prop = <expr>` quand le slot vise est typee
         * MULTILINGUE. Deux ajustements pour eviter le crash compile-time et
         * preserver la semantique du slot apres affectation post-decl :
         *
         *  1. Si RHS est un litteral inline `{langueXxx: "..."}`, on tag
         *     g_inline_target_type AVANT le parsing du RHS. brace_indirection
         *     -> instance_literal voit le target et bifurque vers la branche
         *     __MultilingueNew + ARRAY_SET (au lieu d'echouer sur
         *     E_SYNTAX_BRACE_LITERAL_NO_TYPE / segfault). Symetrique de
         *     window_parse_property_init et control_parse_property_init
         *     en DSL PROPRIETES.
         *
         *  2. Pour preserver la backward-compat sur affectation string simple
         *     (`BTN_X..Libelle = "Aide"`), on wrap le RHS dans
         *     __InstanceCoerce(rhs, "chaineMultilingue") qui coerce string ->
         *     ObjMultilingue (string posee sur la langue source). Pass-through
         *     pour ObjMultilingue input. Sans ce wrap, la string brute serait
         *     stockee dans headless_store et l'indexation
         *     `BTN_X..Libelle[langueXxx]` echouerait (slot non indexable). */
        bool isMultilingueSlot = false;
        /*  ( §3) — slot contenu d'une Saisie (..Valeur /
         * ..ContenuInitial) : desormais MULTILINGUE (retient un vrai litteral
         * {langueXxx: ...}, re-resolu a la lecture), MAIS un scalaire y est
         * fige chaine sur la langue courante ( : `SAI..Valeur = 42`
         * puis `..Valeur + 1` doit valoir "421", pas 43). On ne wrap donc PAS
         * ce slot dans __InstanceCoerce (qui rejette les scalaires entier/reel/
         * booleen) : le brace-litteral construit sa multilingue via le target
         * type ci-dessous, le scalaire/chaine reste brut et est aplati au store
         * (ui_input_coerce_string_prop). */
        bool isInputContentSlot = false;
        /*  (L3.5) — prop widget typée couleur (OWL_PROP_TYPE_COLOR) :
         * un RHS littéral `{ Rouge=…, Opacité=… }` cible le type composé
         * Couleur. Symétrique du slot MULTILINGUE. */
        bool isColorSlot = false;
        /*  (L3.6 edge) — prop widget typée OBJECT composé
         * (OWL_PROP_TYPE_OBJECT, ex Style/Cadre) réaffectée EN BLOC par un
         * littéral (`SAI..Style = {ZoneSaisie = {Couleur = {...}}}`). Sans
         * cible, le littéral EXTERNE échoue « sans type cible » (le bloc
         * OBJECT plus haut, ~L8148, propage g_last_field_type pour la cascade
         * `..SousChamp` mais ne tague PAS la cible d'un RHS littéral en bloc).
         * On capture object_type ici pour tagger g_inline_target_type juste
         * avant le RHS, symétrique des slots MULTILINGUE et COLOR. Une fois
         * l'externe résolu, la résolution des sous-objets (dont les champs
         * couleur via resolve_object_subfield_type -> registry_field_is_color,
         * L3.5) prend le relais. */
        const char* objectSlotType = NULL;
        /*  — prop widget attendant un TABLEAU d'options riches
         * (Sélecteur/Interrupteur .Options, VARIANT + enum_name "Option").
         * Le RHS `[{...}, ...]` doit typer chaque élément brace vers le type
         * composé "Option", sinon instance_literal refuse « sans type cible ».
         * Symétrique de la forme déclarative (window/control_parse_property_init,
         * via prop_inline_target_type + array_literal). */
        const char* optionSlotType = NULL;
        if (isDoubleDot && receiverTok.length > 0 && receiverTok.length < 128) {
            char nameBuf[128];
            memcpy(nameBuf, receiverTok.start, (size_t)receiverTok.length);
            nameBuf[receiverTok.length] = '\0';
            const OwlControlKindInfo* info = compiler_prescan_widget_find(nameBuf);
            OwlControlKind kind;
            if (info && owl_control_kind_of_info(info, &kind)) {
                char propBuf[128];
                int plen = fieldTok.length < (int)sizeof(propBuf) - 1
                           ? fieldTok.length : (int)sizeof(propBuf) - 1;
                memcpy(propBuf, fieldTok.start, (size_t)plen);
                propBuf[plen] = '\0';
                const OwlControlPropDef* pdef =
                    owl_control_catalog_find(kind, propBuf);
                if (pdef && pdef->type == OWL_PROP_TYPE_MULTILINGUE) {
                    isMultilingueSlot = true;
                    if (kind == OWL_CONTROL_INPUT && pdef->nameFR != NULL &&
                        (strcmp(pdef->nameFR, "Valeur") == 0 ||
                         strcmp(pdef->nameFR, "ContenuInitial") == 0)) {
                        isInputContentSlot = true;
                    }
                } else if (pdef && pdef->type == OWL_PROP_TYPE_COLOR) {
                    isColorSlot = true;
                } else if (pdef && pdef->type == OWL_PROP_TYPE_OBJECT
                           && pdef->object_type && prev_field_name_len == 0) {
                    /* Garde prev_field_name_len == 0 : uniquement l'accès direct
                     * `WIDGET..PropObjet` (cohérence avec le bloc OBJECT ~L8148 ;
                     * un ref qualifié cross-fichier se résout au runtime). */
                    objectSlotType = pdef->object_type;
                } else if (dsl_prop_expects_array(pdef)) {
                    /*  — .Options : enum_name "Option" = type-élément du
                     * tableau, propagé à chaque brace par array_literal. */
                    optionSlotType = prop_inline_target_type(pdef);
                }
            }
        }
        /*  (L3.6) — cascade profonde SET
         * (`X..Style..ZoneSaisie..CouleurFond = {...}`) : le slot couleur
         * terminal est atteint via recvType (type composé résolu par la
         * cascade), pas via le lookup widget direct ci-dessus. La métadonnée
         * registry du champ (registry_field_is_color) le détecte, symétrique
         * du SET direct court. Sans ce tag, le littéral `{ Rouge=…, Opacité=…}`
         * est aplati en entier BGR opaque (alpha jeté). */
        if (!isColorSlot && recvType != NULL && check(TOKEN_LEFT_BRACE)
            && registry_field_is_color(recvType, (int)strlen(recvType), fieldTok)) {
            isColorSlot = true;
        }
        if (isMultilingueSlot && check(TOKEN_LEFT_BRACE)) {
            g_inline_target_type     = "cha\xc3\xae" "neMultilingue";
            g_inline_target_type_len =
                (int)strlen("cha\xc3\xae" "neMultilingue");
        }
        /* Le littéral inline construit une instance Couleur ; le slot widget
         * la consomme via owl_value_to_color (aucune coercion entier ici). */
        if (isColorSlot && check(TOKEN_LEFT_BRACE)) {
            g_inline_target_type     = "Couleur";
            g_inline_target_type_len = 7;
        }
        /* Slot OBJECT composé (Style/Cadre…) réaffecté par un littéral en bloc :
         * le littéral construit une instance du type composé, consommée par le
         * STRUCT_SET comme une affectation depuis variable typée. */
        if (objectSlotType != NULL && !isMultilingueSlot && !isColorSlot
            && check(TOKEN_LEFT_BRACE)) {
            g_inline_target_type     = objectSlotType;
            g_inline_target_type_len = (int)strlen(objectSlotType);
        }
        /*  — `SEL_X..Options = [{...}, ...]` : le RHS canon est un
         * littéral tableau (`[` non suivi d'un newline -> TOKEN_LEFT_BRACKET),
         * array_literal re-pose le target à chaque élément brace. On accepte
         * aussi un brace seul par symétrie avec la forme déclarative. */
        if (optionSlotType != NULL
            && (check(TOKEN_LEFT_BRACKET) || check(TOKEN_LEFT_BRACE))) {
            g_inline_target_type     = optionSlotType;
            g_inline_target_type_len = (int)strlen(optionSlotType);
        }
        /* Stack courant : [obj]. Si MULTILINGUE, on intercale GET_GLOBAL
         * __InstanceCoerce avant le RHS et CALL 2 apres avec le nom du type
         * en constante. Resultat : [obj, wrapped_value]. STRUCT_SET pop val
         * puis obj. Exclu pour un slot contenu Saisie (cf. note ci-dessus). */
        if (isMultilingueSlot && !isInputContentSlot) {
            Token fnTok;
            fnTok.start = "__InstanceCoerce";
            fnTok.length = 16;
            ConstIdx cIC = identifier_constant(&fnTok);
            emit_const_op(OP_GET_GLOBAL, cIC);
        }
        /*  : coercion sticky sur affectation de champ de structure,
         * symetrique du mecanisme `needsCoerce` des variables typees (cf.
         * named_variable + var_declaration_after_est). Si le champ vise a un
         * type declare scalaire a valeur-semantique (monetaire, numerique,
         * entier, reel, booleen, date, heure, dateheure, duree), on coerce le
         * RHS vers ce type avant le STRUCT_SET. Sans ca un champ monetaire
         * stockerait un reel et perdrait la garantie d'arithmetique exacte
         * anti-arrondi (bug financier). Les champs de structure ne supportent
         * pas le marqueur nullable, donc pas de garde !nullable a poser.
         * chaine/buffer exclus : pas de peephole string-append ici, et leur
         * coercion croiserait le mode builder des buffers (hors-scope). */
        const char* fieldCoerceFn = NULL;
        /*  (L3.6) — slot couleur en cascade profonde : le champ est
         * typé "entier" (BGR) au registry, ce qui déclencherait __EntierCoerce
         * et aplatirait l'instance Couleur du littéral en entier opaque (alpha
         * jeté). Le littéral construit une instance Couleur consommée telle
         * quelle par instance_get_color au rendu : on saute la coercion. */
        if (!isMultilingueSlot && !isColorSlot && recvType != NULL) {
            int fieldTypeTok = TOKEN_EOF;
            const UserTypeField* cfld = user_type_find_field(
                recvType, (int)strlen(recvType), fieldTok.start, fieldTok.length);
            if (cfld && cfld->typeLen > 0) {
                fieldTypeTok = field_type_token(cfld->typeName, cfld->typeLen);
            } else {
                /*  — types REGISTRY (Timer, Chrono…) : le path
                 * historique ne couvrait que les types USER. On interroge
                 * owl_registry_type_find(recvType)->fields pour récupérer le
                 * type déclaré du champ (ex Timer.Intervalle = "durée"). Match
                 * casse+accent-insensible sur name/nameAccented/nameEN. */
                char typeC[64];
                int tcl = (int)strlen(recvType);
                if (tcl > (int)sizeof(typeC) - 1) tcl = (int)sizeof(typeC) - 1;
                memcpy(typeC, recvType, (size_t)tcl);
                typeC[tcl] = '\0';
                const OwlTypeDef* td = owl_registry_type_find(typeC);
                if (td != NULL) {
                    char qStrip[64];
                    int ql = scanner_strip_accents(fieldTok.start, fieldTok.length,
                                                   qStrip, sizeof(qStrip));
                    if (ql <= 0) {
                        ql = fieldTok.length < 63 ? fieldTok.length : 63;
                        memcpy(qStrip, fieldTok.start, (size_t)ql);
                        qStrip[ql] = '\0';
                    }
                    for (const OwlField* f = td->fields; f && f->name; f++) {
                        if (f->name[0] == '_') continue;
                        bool m = inline_field_name_matches(qStrip, ql, f->name)
                            || (f->nameAccented
                                && inline_field_name_matches(qStrip, ql, f->nameAccented))
                            || (f->nameEN
                                && inline_field_name_matches(qStrip, ql, f->nameEN));
                        if (m && f->type) {
                            fieldTypeTok = field_type_token(f->type, (int)strlen(f->type));
                            break;
                        }
                    }
                }
            }
            switch (fieldTypeTok) {
                case TOKEN_MONETAIRE: fieldCoerceFn = "__MonetaireCoerce"; break;
                case TOKEN_NUMERIQUE: fieldCoerceFn = "__NumeriqueCoerce"; break;
                case TOKEN_ENTIER:    fieldCoerceFn = "__EntierCoerce";    break;
                case TOKEN_REEL:      fieldCoerceFn = "__ReelCoerce";      break;
                case TOKEN_BOOLEEN:   fieldCoerceFn = "__BooleenCoerce";   break;
                case TOKEN_DATE:      fieldCoerceFn = "__DateCoerce";      break;
                case TOKEN_HEURE:     fieldCoerceFn = "__HeureCoerce";     break;
                case TOKEN_DATEHEURE: fieldCoerceFn = "__DateHeureCoerce"; break;
                case TOKEN_DUREE:     fieldCoerceFn = "__DureeCoerce";     break;
                /*  ( §2) — champ de structure typé `chaine`
                 * recevant une valeur multilingue : aplatit à la langue active
                 * au STOCKAGE (plus de rétention de l'objet brut derriere un
                 * champ typé chaine). On ne coerce QUE si le RHS est réellement
                 * un multilingue — littéral `{...}` (construit via
                 * g_inline_target_type plus bas) OU variable chaîneMultilingue.
                 * Un __BufferVersChaine inconditionnel casserait les autres RHS
                 * légitimement affectés à un champ chaine (ex. sentinel Prefixe
                 * de FormatNumérique via la constante fnpAuto, que value_to_string
                 * aplatirait en sa repr décimale). */
                case TOKEN_CHAINE: {
                    bool rhsMulti = check(TOKEN_LEFT_BRACE);
                    if (!rhsMulti && check(TOKEN_IDENTIFIER)) {
                        const char* rhsTy = resolve_var_struct_type(
                            parser.current.start, parser.current.length);
                        if (struct_name_is_multilingue(rhsTy)) rhsMulti = true;
                    }
                    if (rhsMulti) fieldCoerceFn = "__BufferVersChaine";
                    break;
                }
                default: break;
            }
        }
        /*  — Site B : si le champ est une durée et le RHS est un
         * littéral `{ }`, tag g_inline_target_type pour que instance_literal
         * prenne la branche durée (somme pondérée ms), wrappée ensuite par
         * fieldCoerceFn == __DureeCoerce. */
        if (fieldCoerceFn != NULL && strcmp(fieldCoerceFn, "__DureeCoerce") == 0
            && check(TOKEN_LEFT_BRACE)) {
            g_inline_target_type     = "dur\xc3\xa9" "e";
            g_inline_target_type_len = (int)strlen("dur\xc3\xa9" "e");
        }
        /*  ( §2) — champ `chaine` + RHS littéral `{...}` : tag
         * la cible multilingue pour qu'instance_literal construise l'ObjMultilingue,
         * que __BufferVersChaine (fieldCoerceFn ci-dessus) aplatit ensuite. */
        if (fieldCoerceFn != NULL && strcmp(fieldCoerceFn, "__BufferVersChaine") == 0
            && check(TOKEN_LEFT_BRACE)) {
            g_inline_target_type     = "cha\xc3\xae" "neMultilingue";
            g_inline_target_type_len = (int)strlen("cha\xc3\xae" "neMultilingue");
        }
        int fieldRhsStart = current_chunk()->count;
        int fieldRhsLine  = parser.previous.line;
        /* RHS d'assignment : on utilise condition_expression (PREC_TERNARY)
         * pour empecher les sub-named_variable de matcher leur `=` ou `<=`
         * comme un assignment chaine. Sinon `obj.field = n <= 0` aspire
         * `<=` comme deep-copy de `n` au lieu de comparer. */
        condition_expression();
        if (fieldCoerceFn != NULL) {
            /* Stack avant RHS : [obj]. On intercale GET_GLOBAL <coerce> juste
             * avant le bytecode du RHS (=> [obj, coerceFn, rhs]) puis CALL 1
             * (=> [obj, coercedVal]). STRUCT_SET pop val puis obj. */
            Token fnTok;
            fnTok.start = fieldCoerceFn;
            fnTok.length = (int)strlen(fieldCoerceFn);
            ConstIdx cidx = identifier_constant(&fnTok);
            insert_const_op_before(fieldRhsStart, OP_GET_GLOBAL, cidx,
                                   fieldRhsLine);
            emit_bytes(OP_CALL, 1);
        }
        if (isMultilingueSlot && !isInputContentSlot) {
            const char* tname = "cha\xc3\xae" "neMultilingue";
            ObjString* sName = obj_copy_string(tname, (int)strlen(tname));
            ConstIdx k = make_constant(OBJ_VAL(sName));
            emit_const_op(OP_CONSTANT, k);
            emit_bytes(OP_CALL, 2);
        }
        if (fieldAsParam) {
            validate_enum_rhs(rhsFirst, parser.previous,
                              fieldAsParam->allowedBase,
                              fieldAsParam->allowedOptions);
        }
        emit_const_op(OP_STRUCT_SET, name);
    } else if (canAssign && match_token(TOKEN_LESS_EQUAL)) {
        /* Deep copy assignment: obj.field <= expr */
        condition_expression();
        emit_byte(OP_DEEP_COPY);
        emit_const_op(OP_STRUCT_SET, name);
    } else if (canAssign && (check(TOKEN_PLUS_EQUAL) || check(TOKEN_MINUS_EQUAL) ||
                              check(TOKEN_STAR_EQUAL) || check(TOKEN_SLASH_EQUAL) ||
                              check(TOKEN_PERCENT_EQUAL) ||
                              check(TOKEN_PLUS_PLUS) || check(TOKEN_MINUS_MINUS))) {
        /* Compound assignment on property: obj.field += expr
         * Stack before: [obj]
         * Emit: DUP, STRUCT_GET name, <expr>, <op>, STRUCT_SET name */
        TokenType op = parser.current.type;
        advance_token(); /* consume the compound operator */
        /*  — RHS absent en fin de ligne sur affectation composée de
         * propriété (`obj..champ +=`) : le NEWLINE apres l'operateur a ete
         * skippe (crossedNewline). On refuse, ancre sur l'operateur. `++`/`--`
         * n'ont pas de RHS : ils restent complets en fin de ligne. */
        if (op != TOKEN_PLUS_PLUS && op != TOKEN_MINUS_MINUS && crossedNewline) {
            owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR);
            return;
        }
        emit_byte(OP_DUP);                      /* [obj, obj] */
        emit_const_op(OP_STRUCT_GET, name);         /* [obj, oldVal] */
        Chunk* divChunk = NULL;
        int divStart = 0;
        if (op == TOKEN_PLUS_PLUS || op == TOKEN_MINUS_MINUS) {
            emit_const_op(OP_CONSTANT, make_constant(INTEGER_VAL(1)));
        } else {
            divChunk = current_chunk();
            divStart = divChunk->count;
            expression();                        /* [obj, oldVal, expr] */
        }
        uint8_t arithOp;
        switch (op) {
            case TOKEN_MINUS_EQUAL:
            case TOKEN_MINUS_MINUS:  arithOp = OP_SUBTRACT; break;
            case TOKEN_STAR_EQUAL:   arithOp = OP_MULTIPLY; break;
            case TOKEN_SLASH_EQUAL:  arithOp = OP_DIVIDE;   break;
            case TOKEN_PERCENT_EQUAL: arithOp = OP_MODULO;  break;
            default:                 arithOp = OP_ADD;      break;
        }
        if (arithOp == OP_DIVIDE)
            check_div_by_zero_const(divChunk, divStart);
        emit_byte(arithOp);                      /* [obj, newVal] */
        emit_const_op(OP_STRUCT_SET, name);         /* [result] */
    } else if (check(TOKEN_LEFT_PAREN)) {
        /*  — super-call by-name : detection avant tout autre check.
         * Pattern : dans le body d'une methode de classe (`currentClass`),
         * `cAncestor.M(args)` ou cAncestor est un ancetre transitif strict
         * de la classe courante. On emet OP_INVOKE_DIRECT qui dispatch
         * directement sur cAncestor.methods[M] sans walk virtual.
         *
         * Le receveur (la classe) est deja sur la pile (push par named_variable)
         * — on l'evacue avec OP_POP et on pousse `this` (slot 0) a la place,
         * symetrique a `Ancetre.M()` (OP_INVOKE_SUPER) qui prend aussi
         * [this][args].
         *
         * Conditions cumulees :
         *   - currentClass != NULL (dans une methode)
         *   - receiverTok = nom d'une classe connue
         *   - receiver != currentClass (strict-ancetre)
         *   - receiver est ancetre transitif de currentClass
         * Sinon : comportement OP_INVOKE normal (qui peut etre un appel
         * statique GLOBALE legitime ou produire un runtime error). */
        if (currentClass != NULL &&
            receiverTok.length > 0 &&
            is_known_user_type(receiverTok.start, receiverTok.length)) {
            int curLen = currentClass->name.length;
            const char* curStart = currentClass->name.start;
            bool sameAsCurrent = (receiverTok.length == curLen &&
                strncasecmp(receiverTok.start, curStart, (size_t)curLen) == 0);
            if (!sameAsCurrent &&
                class_is_same_or_derived(curStart, curLen,
                                         receiverTok.start, receiverTok.length)) {
                /* Super-call by-name confirme. */
                ConstIdx classNameConst = identifier_constant(&receiverTok);
                emit_byte(OP_POP);                /* discard classObj */
                emit_bytes(OP_GET_LOCAL, 0);      /* push this */
                advance_token();                  /* consume '(' */
                uint8_t argCount = argument_list();
                emit_const_op2_b(OP_INVOKE_DIRECT, classNameConst, name,
                                 argCount);
                /* Aligne sur le post-OP_INVOKE normal : chain broken
                 * (la valeur de retour est de type inconnu). */
                g_chain_broken = true;
                g_last_field_type[0] = '\0';
                g_last_field_type_len = 0;
                g_last_var_token.start = NULL;
                g_last_var_token.length = 0;
                return;
            }
            /*  : check negatif compile-time. Si receiver est une
             * classe connue ET on est dans body methode ET ce n'est pas
             * un super-call ancetre transitif valide (cf. bloc au-dessus)
             * ET ce n'est pas un appel statique GLOBALE legitime → emettre
             * E_SEM_SUPER_CALL_NOT_ANCESTOR. Le cas same-class (cMath.M
             * depuis body de cMath) est legitime tant que M est GLOBALE :
             * laisser passer pour rejoindre OP_INVOKE statique normal.
             * Note V1 : pas de lookup transitif GLOBALE sur ancetres
             * (`cChild.M()` ou M est GLOBALE heritee de cParent) — direct
             * lookup uniquement. Hors-scope V1 (cf. ticket ). */
            if (!sameAsCurrent &&
                !class_globale_method_is(receiverTok.start, receiverTok.length,
                                         fieldTok.start, fieldTok.length)) {
                char recvBuf[128], methBuf[128], curBuf[128];
                int rl = receiverTok.length < 127 ? receiverTok.length : 127;
                int fl = fieldTok.length < 127 ? fieldTok.length : 127;
                int cl = curLen < 127 ? curLen : 127;
                memcpy(recvBuf, receiverTok.start, rl); recvBuf[rl] = '\0';
                memcpy(methBuf, fieldTok.start, fl); methBuf[fl] = '\0';
                memcpy(curBuf, curStart, cl); curBuf[cl] = '\0';
                owl_emit_error_at(&fieldTok, E_SEM_SUPER_CALL_NOT_ANCESTOR,
                                  "target", recvBuf,
                                  "class", curBuf,
                                  "method", methBuf,
                                  NULL);
            }
        }

        /*  : visibilite POO compile-time pour les appels de
         * methode. Symetrique au check des fields a ~4615 mais pour
         * un site `.method(...)` (suivi de `(`). */
        if (recvType) {
            int rtl = (int)strlen(recvType);
            int uidx = user_type_index(recvType, rtl);
            bool isClass = (uidx >= 0 &&
                            knownUserTypes[uidx].kind == OWL_USER_TYPE_CLASSE);
            const char* ownerStart = NULL;
            int ownerLen = 0;
            int declaredLine = 0;
            int vis = method_visibility_lookup_inherited(
                recvType, rtl,
                fieldTok.start, fieldTok.length,
                &ownerStart, &ownerLen, &declaredLine);
            if ((isClass || vis >= 0) && vis >= 0 && vis != OWL_VIS_PUBLIC) {
                const char* scopeStart = NULL;
                int scopeLen = 0;
                if (currentClass) {
                    scopeStart = currentClass->name.start;
                    scopeLen   = currentClass->name.length;
                }
                bool allowed = false;
                if (vis == OWL_VIS_PRIVE) {
                    /* Autorise UNIQUEMENT depuis du code de la classe
                     * proprietaire (pas une derivee). */
                    if (scopeStart && ownerStart &&
                        scopeLen == ownerLen &&
                        strncasecmp(scopeStart, ownerStart, (size_t)scopeLen) == 0) {
                        allowed = true;
                    }
                } else if (vis == OWL_VIS_PROTEGE) {
                    /* Autorise depuis la classe OU une derivee. */
                    if (scopeStart && ownerStart &&
                        class_is_same_or_derived(scopeStart, scopeLen,
                                                 ownerStart, ownerLen)) {
                        allowed = true;
                    }
                }
                if (!allowed) {
                    char methodBuf[128], classBuf[128], lineBuf[16];
                    snprintf(methodBuf, sizeof(methodBuf), "%.*s",
                             fieldTok.length, fieldTok.start);
                    snprintf(classBuf, sizeof(classBuf), "%.*s",
                             ownerLen, ownerStart);
                    snprintf(lineBuf, sizeof(lineBuf), "%d", declaredLine);
                    OwlErrorCode code = (vis == OWL_VIS_PRIVE)
                        ? E_SEM_METHOD_PRIVATE
                        : E_SEM_METHOD_PROTECTED;
                    owl_emit_error_at(&fieldTok, code,
                                      "method", methodBuf,
                                      "class", classBuf,
                                      "line", lineBuf,
                                      NULL);
                }
            }
        }

        /* Method call: obj.method(args) -> OP_INVOKE */
        advance_token(); /* consume '(' */
        /*  — résout le type builtin du receveur AVANT de compiler les
         * args (argument_list peut écraser g_last_var_token via named_variable).
         * Valide l'arité contre la native sous-jacente (chemin chaîné). */
        /* Conservateur : on ne valide QUE le receveur direct (variable nue).
         * g_last_field_type_len==0 écarte les chaînes `a..b.M()`. NB lots
         * suivants : si un jour une méthode retourne un type builtin portant
         * une méthode homonyme (`x.M1().M2()`), ajouter `!g_chain_broken` ici
         * pour ne pas valider M2 contre le type de x (symétrique L~7436). */
        int methRecvType = TOKEN_EOF;
        if (g_last_field_type_len == 0 && receiverTok.length > 0) {
            methRecvType = resolve_var_declared_type(receiverTok.start,
                                                     receiverTok.length);
        }
        Token methTok = fieldTok;
        /*  ( §1) — si le receveur est une classe connue et la
         * méthode a une signature déclarée, on parse les arguments en tenant
         * compte des types de paramètres : un littéral `{…}` vers un paramètre
         * typé texte est aplati au site d'appel. Sinon parse générique. */
        const DeclaredMethodSigEntry* methSig = NULL;
        if (recvType != NULL) {
            methSig = declared_method_sig_lookup_inherited(
                recvType, (int)strlen(recvType),
                fieldTok.start, fieldTok.length);
        }
        uint8_t argCount = methSig ? argument_list_with_method_sig(methSig)
                                   : argument_list();
        check_method_call_arity(methRecvType, &methTok, (int)argCount);
        emit_const_op_b(OP_INVOKE, name, argCount);
        /* Symétrique à call() : après un appel de méthode, le receveur
         * effectif du prochain dot est la valeur de retour (type inconnu).
         * On casse la chaîne pour éviter `m.Quand().Retourne(rep).Active()`
         * où `.Active` se résout fautivement sur le type de `rep`.
         * Les arguments compilés ont pu réinitialiser g_chain_broken via
         * named_variable, donc on le re-pose ICI, après argument_list. */
        g_chain_broken = true;
        g_last_field_type[0] = '\0';
        g_last_field_type_len = 0;
        g_last_var_token.start = NULL;
        g_last_var_token.length = 0;
    } else {
        /*  — `MonApp..Thème` SUIVI d'un acces membre (`.X` / `..X`)
         * navigue l'instance de theme vivante au lieu de lire la metadonnee
         * chaine. `MonApp..Thème` SEUL reste le NOM (cascade metadonnee, cf
         * case_034 : lecture cross-fichier `MonApp..Thème`). L'unification avec
         * le sucre `theme.X` est structurelle : on remplace le receveur Projet
         * par le global `theme` (le meme ObjThemeNamespace singleton), la suite
         * de la chaine dispatche via IS_THEME_NAMESPACE -> `theme$<nom>`
         * exactement comme `theme.X..Y`. Aucune resolution divergente, aucun
         * etat runtime neuf : `MonApp..Thème.X` et `theme.X` compilent vers la
         * meme cible. Les styles du theme designe sont deja poses (`theme$<nom>`
         * globals) quand le corps de projet.owl s'execute (compagnons avant le
         * corps, ). Reroute uniquement quand le type du receveur est
         * resolu a Projet (corps de projet.owl) : `MonApp..Thème` seul retombe
         * sur OP_STRUCT_GET -> le NOM. */
        bool projetRecv = recvType != NULL
            && (strcasecmp(recvType, "Projet") == 0
                || strcasecmp(recvType, "Project") == 0);
        char themeFldProbe[16];
        int themeFldLen = scanner_strip_accents(fieldTok.start, fieldTok.length,
                                                themeFldProbe,
                                                sizeof(themeFldProbe));
        bool fieldIsTheme = (themeFldLen == 5
                             && strncasecmp(themeFldProbe, "Theme", 5) == 0);
        bool followedByMember = check(TOKEN_DOT) || check(TOKEN_DOUBLE_DOT);
        if (projetRecv && fieldIsTheme && followedByMember) {
            emit_byte(OP_POP);  /* jette l'instance Projet du receveur */
            Token themeTok = fieldTok;
            themeTok.start  = "theme";
            themeTok.length = 5;
            ConstIdx themeGlobal = identifier_constant(&themeTok);
            emit_const_op(OP_GET_GLOBAL, themeGlobal);  /* pousse le namespace */
            /* Le receveur est desormais `theme` (runtime pur), donc la suite de
             * la chaine se resout EXACTEMENT comme le sucre direct `theme.X` :
             * meme else-branch  sur `.<style>`, puis meme propagation de
             * type riche. g_chain_broken = false : le strict-check qui suit
             * porte sur le receveur `theme` (non type => inoffensif), plus sur
             * le type Projet d'origine ; surtout, la propagation reste armee
             * pour `..CadreExterieur..Etats[etat]`. Poser `true` ici
             * fuyait sur toute la chaine : le type retombait a vide des le
             * second `..` et l'acces a un etat degenerait en indexation. */
            g_last_var_token       = themeTok;
            g_chain_broken         = false;
            g_last_field_type[0]   = '\0';
            g_last_field_type_len  = 0;
        } else {
            /*  — `theme.<style>` : seme le TYPE du style pour la suite
             * de la cascade. Le namespace est un receveur runtime pur, donc
             * `..ZoneSaisie` arrivait sans type et le `[etat]` suivant retombait
             * sur l'indexation de tableau — d'ou « 'survol' : variable inconnue »
             * alors que le meme style relu par une variable typee marchait.
             * Meme parade que  sur l'autre chemin, meme filtre que
             * style_rhs_resolve_type : borne aux TYPES DE STYLE. Un nom qui ne
             * resout pas vers un style (dont `theme.inconnu`) garde le dispatch
             * dynamique nu. La garde g_last_field_type_len == 0 restreint au
             * PREMIER `.` derriere le namespace : au-dela le receveur est le
             * sous-element, deja type.
             *
             * Couvre AUSSI le sucre `MonApp..Theme.X` du corps de projet.owl :
             * le reroute  remplace le receveur Projet par le global
             * `theme`, donc le segment `.<style>` qui suit repasse par ce meme
             * seed. ( : le reroute laissait fuir g_chain_broken = true,
             * ce qui sautait la propagation de type des `..` suivants et faisait
             * errer l'acces a un etat — corrige a la source dans le reroute.) */
            char themeStyleType[64];
            if (g_last_field_type_len == 0
                && is_theme_namespace_name(receiverTok.start, receiverTok.length)
                && project_ident_declared_type(fieldTok.start, fieldTok.length,
                                               themeStyleType,
                                               sizeof(themeStyleType))
                && is_style_type_name(themeStyleType)) {
                int copy = (int)strlen(themeStyleType);
                if (copy > 63) copy = 63;
                memcpy(g_last_field_type, themeStyleType, (size_t)copy);
                g_last_field_type[copy] = '\0';
                g_last_field_type_len = copy;
            }
            emit_const_op(OP_STRUCT_GET, name);
        }
    }
}

/* :member access (this field) - used as prefix when TOKEN_COLON appears */
static void this_field(bool canAssign) {
    if (currentClass == NULL) {
        owl_emit_error_at(&parser.previous, E_SEM_COLON_MEMBER_OUTSIDE_METHOD);
        return;
    }
    /*  : une methode GLOBALE n'a pas d'instance courante — ':champ'
     * n'a aucune cible. Erreur ciblee + suggestion. */
    if (currentClass->isGlobalMethod) {
        char className[128];
        int cn = currentClass->name.length < (int)sizeof(className) - 1
                 ? currentClass->name.length : (int)sizeof(className) - 1;
        memcpy(className, currentClass->name.start, (size_t)cn);
        className[cn] = '\0';
        owl_emit_error_at(&parser.previous, E_SEM_COLON_MEMBER_IN_GLOBAL_METHOD,
                          "class", className,
                          NULL);
        /* On consomme l'IDENT suivant pour eviter un cascading d'erreurs
         * incomprehensibles. */
        if (check(TOKEN_IDENTIFIER)) advance_token();
        return;
    }
    /*  : la position de l'erreur "membre inconnu" pointe le
     * token `:` (parser.previous a l'entree, avant de consommer l'IDENT). */
    Token colonTok = parser.previous;
    consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_FIELD_NAME_AFTER_COLON);
    Token memberTok = parser.previous;
    ConstIdx name = identifier_constant(&parser.previous);

    /*  : enregistre l'acces pour validation differee (champ ou
     * methode) en fin de compile, quand toutes les declarations — y compris
     * en reference-avant et heritees — sont connues. La classe proprietaire
     * est la classe courante (currentClass). */
    colon_ref_pending_register(currentClass->name.start, currentClass->name.length,
                               memberTok.start, memberTok.length,
                               colonTok.line, colonTok.column);

    /*  : ':methode(args)' est un appel de methode sur 'this' —
     * symetrique a `dot_access` quand un IDENT est suivi de '(' (cf. 5099+)
     * et a `dot_prefix` pour AVEC/WITH (cf. 5234+). On emet OP_INVOKE qui
     * attend [this][arg1]...[argN] sur la pile.
     *
     * Sans ce branch, on emettait OP_GET_LOCAL 0 puis OP_STRUCT_GET, ce qui
     * essaie de lire un *champ* nomme M sur l'instance puis fait un OP_CALL
     * sur lui — d'ou l'erreur "Only struct instances have fields" des que
     * la methode appelee touche `:champ` (le 'this' transmis est faux).
     *
     * Note canAssign : `:M(args) = ...` n'a aucun sens (LHS d'assignment ne
     * peut pas etre un appel), donc on ne traite pas TOKEN_EQUAL ici. */
    if (check(TOKEN_LEFT_PAREN)) {
        emit_bytes(OP_GET_LOCAL, 0);              /* push this */
        advance_token();                          /* consume '(' */
        uint8_t argCount = argument_list();
        emit_const_op_b(OP_INVOKE, name, argCount);
        /* Apres un appel de methode, le receveur effectif du prochain dot
         * est la valeur de retour (type inconnu). Aligne sur dot_access. */
        g_chain_broken = true;
        g_last_field_type[0] = '\0';
        g_last_field_type_len = 0;
        g_last_var_token.start = NULL;
        g_last_var_token.length = 0;
        return;
    }

    /* Push 'this' (slot 0) */
    emit_bytes(OP_GET_LOCAL, 0);

    if (canAssign && match_token(TOKEN_EQUAL)) {
        /*  ( §2) — membre de classe typé `chaine` : coercition
         * d'aplatissement multilingue au STOCKAGE, symétrique du fieldCoerceFn
         * des champs de structure et du needsCoerce des variables typées. Un
         * littéral `{...}` construit un ObjMultilingue (g_inline_target_type),
         * une variable chaîneMultilingue est aplatie ; __BufferVersChaine résout
         * à la langue active. Les classes ne réifiant pas leur type de champ
         *, on consulte la table de tracking dédiée. */
        int memberType = class_field_type_lookup(currentClass->name.start,
                                                 currentClass->name.length,
                                                 memberTok.start, memberTok.length);
        /* Ne coerce QUE si le RHS est réellement multilingue (littéral {...} ou
         * variable chaîneMultilingue) — même garde que le fieldCoerceFn des
         * structs, pour ne pas altérer les autres affectations `:champ = x`. */
        bool coerceChaine = false;
        if (memberType == TOKEN_CHAINE) {
            if (check(TOKEN_LEFT_BRACE)) {
                coerceChaine = true;
                g_inline_target_type     = "cha\xc3\xae" "neMultilingue";
                g_inline_target_type_len = (int)strlen("cha\xc3\xae" "neMultilingue");
            } else if (check(TOKEN_IDENTIFIER)) {
                const char* rhsTy = resolve_var_struct_type(
                    parser.current.start, parser.current.length);
                if (struct_name_is_multilingue(rhsTy)) coerceChaine = true;
            }
        }
        int rhsStart = current_chunk()->count;
        int rhsLine  = parser.previous.line;
        condition_expression();  /* RHS d'assignment, cf bug `<=`/`=` aspire */
        if (coerceChaine) {
            const char* fn = "__BufferVersChaine";
            Token fnTok;
            fnTok.start  = fn;
            fnTok.length = (int)strlen(fn);
            ConstIdx cidx = identifier_constant(&fnTok);
            insert_const_op_before(rhsStart, OP_GET_GLOBAL, cidx, rhsLine);
            emit_bytes(OP_CALL, 1);
        }
        emit_const_op(OP_STRUCT_SET, name);
    } else if (canAssign && match_token(TOKEN_LESS_EQUAL)) {
        /* Deep copy assignment on this field: :field <= expr */
        condition_expression();
        emit_byte(OP_DEEP_COPY);
        emit_const_op(OP_STRUCT_SET, name);
    } else if (canAssign && (check(TOKEN_PLUS_EQUAL) || check(TOKEN_MINUS_EQUAL) ||
                              check(TOKEN_STAR_EQUAL) || check(TOKEN_SLASH_EQUAL) ||
                              check(TOKEN_PERCENT_EQUAL) ||
                              check(TOKEN_PLUS_PLUS) || check(TOKEN_MINUS_MINUS))) {
        /*  : affectation composee sur un membre `:champ`, alignee sur
         * le desugar des variables locales (cf. named_variable) et sur dot() :
         *   :champ OP= rhs  ==  :champ = (:champ OP rhs)
         *   :champ++         ==  :champ = (:champ + 1)
         *   :champ--         ==  :champ = (:champ - 1)
         * Stack cible pour OP_STRUCT_SET : [instance][newValue]. 'this' (le
         * receveur du SET) est deja sur la pile (push OP_GET_LOCAL 0 ci-dessus).
         * On repush 'this' pour le GET, on lit le membre, on applique l'op,
         * puis on stocke — sans dupliquer la logique d'operateur arithmetique. */
        TokenType op = parser.current.type;
        uint8_t arithOp;
        switch (op) {
            case TOKEN_MINUS_EQUAL:
            case TOKEN_MINUS_MINUS:   arithOp = OP_SUBTRACT; break;
            case TOKEN_STAR_EQUAL:    arithOp = OP_MULTIPLY; break;
            case TOKEN_SLASH_EQUAL:   arithOp = OP_DIVIDE;   break;
            case TOKEN_PERCENT_EQUAL: arithOp = OP_MODULO;   break;
            default:                  arithOp = OP_ADD;      break; /* PLUS_EQUAL, PLUS_PLUS */
        }
        advance_token();                /* consume the compound operator */
        /*  — RHS absent en fin de ligne sur affectation composée de
         * membre `:champ` : NEWLINE skippé (crossedNewline). `++`/`--` sans RHS
         * restent complets. */
        if (op != TOKEN_PLUS_PLUS && op != TOKEN_MINUS_MINUS && crossedNewline) {
            owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR);
            return;
        }
        emit_bytes(OP_GET_LOCAL, 0);    /* push 'this' pour le GET */
        emit_const_op(OP_STRUCT_GET, name);/* [instance][oldValue] */
        Chunk* divChunk = NULL;
        int divStart = 0;
        if (op == TOKEN_PLUS_PLUS || op == TOKEN_MINUS_MINUS) {
            emit_const_op(OP_CONSTANT, make_constant(INTEGER_VAL(1)));  /* [instance][oldValue][1] */
        } else {
            divChunk = current_chunk();
            divStart = divChunk->count;
            expression();               /* [instance][oldValue][rhs] */
        }
        if (arithOp == OP_DIVIDE)
            check_div_by_zero_const(divChunk, divStart);
        emit_byte(arithOp);             /* [instance][newValue] */
        emit_const_op(OP_STRUCT_SET, name);
    } else {
        emit_const_op(OP_STRUCT_GET, name);
    }
}

/* Ancetre.Methode(args) — super-call dans une override de classe heritante.
 * . Le keyword est reserve scanner-only (TOKEN_ANCETRE) ; ici on
 * lui donne sa semantique.
 *
 * Conditions :
 *   - DOIT etre dans le corps d'une methode de classe (currentClass != NULL).
 *   - La classe courante DOIT avoir un parent enregistre (g_class_super).
 *   - Syntaxe stricte : Ancetre.IDENT(args) — pas de field-only Ancetre.x.
 *
 * Emission : push this (slot 0), parse args, emit OP_INVOKE_SUPER avec le
 * nom de methode et l'arg count. Le dispatch reel demarre dans
 * instance->klass->superclass cote VM. */
static void ancetre_call(bool canAssign) {
    (void)canAssign;
    if (currentClass == NULL) {
        owl_emit_error_at(&parser.previous, E_SEM_ANCETRE_OUTSIDE_METHOD);
        return;
    }
    /* Verifie que la classe courante a un parent declare. */
    bool hasParent = false;
    for (int i = 0; i < g_class_super_count; i++) {
        ClassSuperEntry* e = &g_class_super[i];
        if (e->classLen == currentClass->name.length &&
            strncasecmp(e->className, currentClass->name.start,
                        (size_t)e->classLen) == 0) {
            hasParent = true;
            break;
        }
    }
    if (!hasParent) {
        char className[128];
        int cn = currentClass->name.length < (int)sizeof(className) - 1
                 ? currentClass->name.length : (int)sizeof(className) - 1;
        memcpy(className, currentClass->name.start, (size_t)cn);
        className[cn] = '\0';
        owl_emit_error_at(&parser.previous, E_SEM_ANCETRE_NO_PARENT,
                          "class", className,
                          NULL);
        return;
    }

    consume(TOKEN_DOT, E_SYNTAX_EXP_DOT_AFTER_ANCETRE);
    /*  T1 : `Ancetre.Constructeur()` et `Ancetre.Destructeur()` sont
     * des cas legitimes (appel super-ctor / super-dtor depuis un override).
     * Le scanner emet TOKEN_CONSTRUCTEUR / TOKEN_DESTRUCTEUR pour ces
     * mot-cles, donc consume(TOKEN_IDENTIFIER) les rejette. On les
     * accepte explicitement et on fabrique un Token synthetique avec le
     * nom interne utilise au stockage (cf. compile_inline_class_method) :
     *   - Constructeur -> nom du parent (la classe parente)
     *   - Destructeur  -> "__destructor"
     */
    Token methodTok;
    if (check(TOKEN_DESTRUCTEUR)) {
        advance_token();
        methodTok.type   = TOKEN_IDENTIFIER;
        methodTok.start  = "__destructor";
        methodTok.length = 12;
        methodTok.line   = parser.previous.line;
        methodTok.column = parser.previous.column;
    } else if (check(TOKEN_CONSTRUCTEUR)) {
        advance_token();
        /* Trouve l'entree parent pour la classe courante (deja garantie
         * existante au check hasParent plus haut). */
        const char* parentName = NULL;
        int parentLen = 0;
        for (int i = 0; i < g_class_super_count; i++) {
            ClassSuperEntry* e = &g_class_super[i];
            if (e->classLen == currentClass->name.length &&
                strncasecmp(e->className, currentClass->name.start,
                            (size_t)e->classLen) == 0) {
                parentName = e->superName;
                parentLen  = e->superLen;
                break;
            }
        }
        methodTok.type   = TOKEN_IDENTIFIER;
        methodTok.start  = parentName;
        methodTok.length = parentLen;
        methodTok.line   = parser.previous.line;
        methodTok.column = parser.previous.column;
    } else {
        consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_METHOD_NAME_AFTER_ANCETRE);
        methodTok = parser.previous;
    }
    ConstIdx name = identifier_constant(&methodTok);

    consume(TOKEN_LEFT_PAREN, E_SYNTAX_EXP_LPAREN_ANCETRE_CALL);

    /* Push 'this' (slot 0) en tant que receveur avant les arguments :
     * OP_INVOKE_SUPER attend [this] [arg1]...[argN] sur la pile (meme
     * convention que OP_INVOKE — l'instance est sous les args). */
    emit_bytes(OP_GET_LOCAL, 0);
    uint8_t argCount = argument_list();

    emit_const_op_b(OP_INVOKE_SUPER, name, argCount);
}

/*  : `Objet` — designe l'instance courante dans une methode
 * (equivalent canon de `this`/`self`). Aligne sur `this_field` pour
 * la verification de contexte (hors classe → erreur, methode globale →
 * erreur) mais sans suivre par un acces de champ : on emet juste un
 * push du slot 0 (qui contient l'instance reelle) — le reste de la
 * chaine d'expression (`Objet.M(...)`, `Objet:champ`, comparaison...)
 * est gere par les infix habituels.
 *
 * `Objet = qqch` n'a aucun sens (ce n'est pas un lvalue), donc on
 * ignore canAssign. */
static void objet_self(bool canAssign) {
    (void)canAssign;
    if (currentClass == NULL) {
        owl_emit_error_at(&parser.previous, E_SEM_OBJET_OUTSIDE_METHOD);
        return;
    }
    if (currentClass->isGlobalMethod) {
        char className[128];
        char methodName[128];
        int cn = currentClass->name.length < (int)sizeof(className) - 1
                 ? currentClass->name.length : (int)sizeof(className) - 1;
        memcpy(className, currentClass->name.start, (size_t)cn);
        className[cn] = '\0';
        /* Nom de la methode courante = current->function->name (pose par
         * compile_inline_class_method via obj_copy_string). */
        const char* mStart = "";
        int mLen = 0;
        if (current && current->function && current->function->name) {
            mStart = current->function->name->chars;
            mLen   = current->function->name->length;
        }
        int mn = mLen < (int)sizeof(methodName) - 1
                 ? mLen : (int)sizeof(methodName) - 1;
        memcpy(methodName, mStart, (size_t)mn);
        methodName[mn] = '\0';
        owl_emit_error_at(&parser.previous, E_SEM_OBJET_IN_GLOBAL_METHOD,
                          "class", className,
                          "method", methodName,
                          NULL);
        return;
    }
    /* Cas nominal : push slot 0 = `this` (l'instance courante). */
    emit_bytes(OP_GET_LOCAL, 0);
}

/*  — Namespace `OWL.` : echappatoire pour atteindre la FONCTION
 * native d'origine malgre une procedure globale homonyme qui la masque. En
 * OWL une proc globale homonyme gagne (l'utilisateur reste maitre de ses
 * noms) ; `OWL.<nom>` rappelle explicitement la native. `OWL` est un keyword
 * reserve (scanner-only jusqu'ici) ; ce parselet lui donne sa semantique.
 *
 * Contrat :
 *   - point SIMPLE obligatoire (invariant 6.6 « namespace ») : `OWL..X` refuse.
 *   - le nom qui suit DOIT resoudre vers une fonction native connue
 *     (owl_registry_find : casse/accent/bilingue). Sinon erreur compile. Un
 *     nom qui n'est QU'un type (ex. Couleur) n'est pas une fonction -> refus.
 *   - emet OP_GET_GLOBAL vers la cle pristine `__wl$<canonical>`, le coffre que
 *     le OP_DEFINE_GLOBAL d'une proc homonyme n'ecrase pas (owl_define_native_wl).
 *     Le `(...)` qui suit compile en OP_CALL normal via le call() infix.
 *
 * `OWL` n'est jamais un lvalue : canAssign ignore. */
static void owl_namespace(bool canAssign) {
    (void)canAssign;
    Token owlTok = parser.previous;  /* le keyword OWL, pour pointer l'erreur */

    /* Point simple obligatoire. Le double point est reserve aux proprietes
     * de type compose, pas au namespace d'appel. */
    if (check(TOKEN_DOUBLE_DOT)) {
        owl_emit_error_at(&owlTok, E_SYNTAX_OWL_NS_SIMPLE_DOT);
        return;
    }
    consume(TOKEN_DOT, E_SYNTAX_OWL_NS_EXP_NAME);

    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_at(&owlTok, E_SYNTAX_OWL_NS_EXP_NAME);
        return;
    }
    advance_token();
    Token nameTok = parser.previous;

    char fnName[128];
    int n = nameTok.length < (int)sizeof(fnName) - 1
            ? nameTok.length : (int)sizeof(fnName) - 1;
    memcpy(fnName, nameTok.start, (size_t)n);
    fnName[n] = '\0';

    const OwlNativeDef* def = owl_registry_find(fnName);
    if (def == NULL || def->canonical == NULL) {
        owl_emit_error_at(&nameTok, E_SEM_OWL_NS_UNKNOWN_NATIVE,
                          "name", fnName, NULL);
        return;
    }

    /* Cle pristine `__wl$<canonical>` : le coffre non masquable. La resolution
     * globale runtime est canon (casse/accent insensible), donc l'accent-strip
     * d'identifier_constant reste aligne avec la cle stockee. */
    char wlName[256];
    snprintf(wlName, sizeof(wlName), "__wl$%s", def->canonical);
    Token wlTok = nameTok;
    wlTok.start  = wlName;
    wlTok.length = (int)strlen(wlName);
    ConstIdx wlIdx = identifier_constant(&wlTok);
    emit_const_op(OP_GET_GLOBAL, wlIdx);

    /* call() lit g_last_var_token pour la validation enum/out-param : le
     * pointer vers le nom CANON (et non `__wl$...`) fait resoudre le def et
     * preserve le meme traitement que l'appel direct de la native. canonical
     * est un literal statique du registry (duree de vie programme). */
    g_last_var_token = nameTok;
    g_last_var_token.start  = def->canonical;
    g_last_var_token.length = (int)strlen(def->canonical);
}

/*  — le top-level "programme" (ou MoiMême n'a pas de sens : aucun
 * widget en cours) est celui de projet.owl (le nouveau point de demarrage du
 * projet) ou celui d'un fichier isole. currentFilename est resolu par le
 * project loader (separateurs '/'). Si NULL (single-file, REPL, fixture
 * compile-error sans path projet), on traite comme un top-level programme. */
static bool current_file_is_program_toplevel(void) {
    if (currentFilename == NULL) {
        return true;
    }
    size_t n = strlen(currentFilename);
    const char* suffixes[] = { "projet.owl", "project.owl" };
    for (size_t s = 0; s < 2; s++) {
        size_t slen = strlen(suffixes[s]);
        if (n < slen) continue;
        const char* tail = currentFilename + (n - slen);
        bool match = true;
        for (size_t i = 0; i < slen; i++) {
            if (tolower((unsigned char)tail[i]) != suffixes[s][i]) {
                match = false; break;
            }
        }
        if (match) return true;
    }
    return false;
}

/*  — un fichier dont le basename (casse-insensible) est le nom
 * reserve projet.owl / project.owl DOIT declarer un bloc `est un Projet`.
 * Distinct de current_file_is_program_toplevel (qui traite aussi NULL /
 * single-file comme top-level programme) : ici on veut STRICTEMENT le nom
 * reserve, pour ne pas armer le verrou sur un .owl quelconque. */
static bool current_file_is_reserved_projet_name(void) {
    if (currentFilename == NULL) return false;
    size_t n = strlen(currentFilename);
    const char* names[] = { "projet.owl", "project.owl" };
    for (size_t s = 0; s < 2; s++) {
        size_t slen = strlen(names[s]);
        if (n < slen) continue;
        /* basename exact : le caractere qui precede le suffixe doit etre un
         * separateur de chemin (ou rien), sinon "monprojet.owl" matcherait. */
        if (n > slen) {
            char sep = currentFilename[n - slen - 1];
            if (sep != '/' && sep != '\\') continue;
        }
        const char* tail = currentFilename + (n - slen);
        bool match = true;
        for (size_t i = 0; i < slen; i++) {
            if (tolower((unsigned char)tail[i]) != names[s][i]) {
                match = false; break;
            }
        }
        if (match) return true;
    }
    return false;
}

/*  — verrou : un fichier au nom reserve projet.owl/project.owl sans
 * bloc `est un Projet` est rejete (erreur pointant ligne 1 col 1). Appele
 * apres le prescan (g_file_has_projet_block pose) et avant la boucle de
 * parse, pour emettre une erreur unique et court-circuiter les diagnostics
 * de code flottant. */
static void enforce_reserved_projet_requires_block(void) {
    if (!current_file_is_reserved_projet_name()) return;
    if (g_file_has_projet_block) return;
    Token at;
    memset(&at, 0, sizeof at);
    at.type   = TOKEN_ERROR;   /* message nu, pas de "at '<lexeme>'" */
    at.start  = "";
    at.length = 0;
    at.line   = 1;
    at.column = 1;
    owl_emit_error_at(&at, E_SEM_PROJET_BLOC_MANQUANT);
}

/*  — coexistence des deux graphies bilingues du marqueur de projet
 * (projet.owl FR + project.owl EN) dans le dossier-frontiere : ambiguite. Le
 * chemin d'execution (project_discover) la bloque des la decouverte ; le
 * chemin --check (LSP/VSCode) compile un fichier isole sans passer par ce
 * garde, d'ou ce verrou compile-time symetrique. Arme UNIQUEMENT quand le
 * fichier courant est lui-meme un marqueur (comme ) : eviter de
 * faire remonter l'ambiguite sur un fichier quelconque du projet. */
extern bool project_dir_has_ambiguous_markers(const char* filepath);
static void enforce_no_ambiguous_projet_markers(void) {
    if (!current_file_is_reserved_projet_name()) return;
    if (currentFilename == NULL) return;
    if (!project_dir_has_ambiguous_markers(currentFilename)) return;
    Token at;
    memset(&at, 0, sizeof at);
    at.type   = TOKEN_ERROR;   /* message nu, pas de "at '<lexeme>'" */
    at.start  = "";
    at.length = 0;
    at.line   = 1;
    at.column = 1;
    owl_emit_error_at(&at, E_SEM_PROJET_MARQUEURS_AMBIGUS);
}

/*  — MoiMême / MySelf. Emit OP_MOIMEME qui lira au runtime la
 * stack vm.event_sender (alimentee par les sites natifs ouvrant un
 * contexte widget : open_window_instance, vm_etat_stack_push, dispatchers
 * d'events). Compile-time : refus si on est dans le top-level (TYPE_SCRIPT)
 * du programme (top-level de projet.owl ou fichier isole) — aucun widget
 * ne peut etre en cours d'execution a ce stade. Toute autre situation
 * (PROCEDURE libre, scope Fenetre, scope Etat, classe, collection de proc)
 * est acceptee car peut etre invoquee depuis un handler ; un appel direct
 * depuis le top-level planterait au runtime via E_RT_MOIMEME_NO_WIDGET
 * (soft, ErreurDetectee). */
/*  — arme le tracker de recepteur dynamique pour la validation du
 * premier `..prop` de la chaine. Capture le lexeme source (bilingue : MoiMême
 * / MySelf …) pour le reinjecter dans le message d'erreur. */
static void arm_dynamic_receiver(DynReceiverKind kind) {
    g_last_dynamic_receiver = kind;
    const Token* t = &parser.previous;
    int n = t->length;
    if (n < 0) n = 0;
    if (n > (int)sizeof(g_last_dynamic_receiver_name) - 1) {
        n = (int)sizeof(g_last_dynamic_receiver_name) - 1;
    }
    memcpy(g_last_dynamic_receiver_name, t->start, (size_t)n);
    g_last_dynamic_receiver_name[n] = '\0';
    /* Nouvelle chaine : le recepteur dynamique est la racine, pas un field
     * intermediaire. On repart d'un tracker vierge — le recepteur reel est le
     * receveur dynamique arme ici, pas g_last_var_token.  : sans le
     * reset de g_last_var_token, un `MoiMême..prop = <const>` laisse la
     * constante du membre droit (compilee via named_variable) comme dernier
     * token-variable ; le `MoiMême..` suivant la prend pour un receveur
     * constant nu et rejette faussement le `..` (E_SEM_DOTDOT_ON_CONST). */
    reset_indirection_chain_trackers();
}

static void moimeme_self(bool canAssign) {
    (void)canAssign;
    if (current != NULL && current->type == TYPE_SCRIPT
        && current_file_is_program_toplevel()) {
        owl_emit_error_at(&parser.previous, E_SEM_MOIMEME_IN_MAIN);
        return;
    }
    arm_dynamic_receiver(DYN_RECV_SELF);
    emit_byte(OP_MOIMEME);
}

/*  — MonChamp / MyControl. Variante STRICTE de MoiMême : resout
 * uniquement au champ emetteur courant (event_sender_stack), sans repli
 * fenetre/etat. Emet OP_MONCHAMP ; la resolution runtime refuse une fenetre
 * ou une stack vide (E_RT_MONCHAMP_NO_CONTROL, soft). Compile-time : meme
 * garde que MoiMême — refus au top-level programme (aucun champ possible a
 * ce stade). Dans une procedure/fenetre/champ : accepte (peut etre invoquee
 * depuis un handler ; sinon plante au runtime). */
static void monchamp_self(bool canAssign) {
    (void)canAssign;
    if (current != NULL && current->type == TYPE_SCRIPT
        && current_file_is_program_toplevel()) {
        owl_emit_error_at(&parser.previous, E_SEM_MONCHAMP_IN_MAIN);
        return;
    }
    arm_dynamic_receiver(DYN_RECV_CONTROL);
    emit_byte(OP_MONCHAMP);
}

/*  — MaFenêtre / MyWindow. Resout a la fenetre courante via
 * vm_window_stack_top(). Emet OP_MAFENETRE ; runtime refuse l'absence de
 * fenetre (E_RT_MAFENETRE_NO_WINDOW, soft). Compile-time : meme garde que
 * MoiMême. */
static void mafenetre_self(bool canAssign) {
    (void)canAssign;
    if (current != NULL && current->type == TYPE_SCRIPT
        && current_file_is_program_toplevel()) {
        owl_emit_error_at(&parser.previous, E_SEM_MAFENETRE_IN_MAIN);
        return;
    }
    arm_dynamic_receiver(DYN_RECV_WINDOW);
    emit_byte(OP_MAFENETRE);
}

/* AVEC/WITH: .member prefix in expression context (read-only) */
static void dot_prefix(bool canAssign) {
    (void)canAssign;
    if (avecDepth <= 0) {
        owl_emit_error_at(&parser.previous, E_SEM_DOT_OUTSIDE_AVEC);
        return;
    }
    consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_MEMBER_NAME_AFTER_DOT);
    ConstIdx name = identifier_constant(&parser.previous);

    /* Push AVEC target */
    emit_bytes(OP_GET_LOCAL, (uint8_t)avecSlots[avecDepth - 1]);

    if (check(TOKEN_LEFT_PAREN)) {
        /* .method(args) in expression context — OP_INVOKE for proper this */
        advance_token(); /* consume '(' */
        uint8_t argCount = argument_list();
        emit_const_op_b(OP_INVOKE, name, argCount);
    } else {
        emit_const_op(OP_STRUCT_GET, name);
    }
}

/* ================================================================
 *  — palette d'etats de style (Style[etat]).
 *
 * La syntaxe `Style[etat]` (survol/focus) est desambiguisee de
 * l'indexation tableau `tab[i]` par le TYPE de la cible du `[` :
 * un type de style (styleSaisie) n'est jamais un tableau. Chaque type
 * de style expose une palette d'etats ; chaque etat mappe un slot du
 * template (sous-instance styleSaisie interne, cf. build_styleSaisie_
 * template). Resolution bilingue (FR/EN) + accent/casse insensible.
 *
 * Ces etats ne sont volontairement PAS des constantes globales : "Survol"
 * collisionne avec l'action souris, et un etat n'a de sens qu'ici. La
 * table ci-dessous est l'unique source de verite (pas d'OwlEnum registry,
 * qui exigerait allowedBase + constantes orphelines artificielles). */
typedef struct {
    const char* fr;    /* forme FR canon (minuscule) */
    const char* en;    /* forme EN canon */
    const char* slot;  /* nom du slot template (STRUCT_GET/SET) */
} StyleStateSlot;

typedef struct {
    const char* styleType;          /* type COLLECTION porteur du crochet (ex "styleZoneSaisieEtats") */
    const StyleStateSlot* states;   /* NULL-terminee */
    const char* baseType;           /* type PLAT sous ..Etats[etat] (ex "styleZoneSaisieBase") */
} StylePalette;

/*  — le crochet [etat] vit desormais sur le membre Etats (collection),
 * plus a la racine du style. La palette est keyee sur le type de la collection
 * (styleZoneSaisieEtats) ; ..Etats[survol] resout le slot puis type le resultat
 * comme styleZoneSaisieBase (plat, sans Etats -> recursion inecrivable). */
static const StyleStateSlot STATES_styleZoneSaisie[] = {
    {"survol",       "hover",    "_Survol"},
    {"focus",        "focus",    "_Focus"},
    {"grisé",        "grayed",   "_Grise"},
    {"lectureSeule", "readOnly", "_LectureSeule"},
    {NULL, NULL, NULL}
};

/*  — palette du bouton : survol/appuyé/focus/grisé. `appuyé`/pressed
 * est un etat NEUF (absent du Saisie) mappe :pressed cote QSS. PAS de
 * lectureSeule (sans sens sur un bouton). */
static const StyleStateSlot STATES_styleZoneBouton[] = {
    {"survol", "hover",    "_Survol"},
    {"appuyé", "pressed",  "_Appuye"},
    {"focus",  "focus",    "_Focus"},
    {"grisé",  "grayed",   "_Grise"},
    {NULL, NULL, NULL}
};

/*  — palette d'icone du bouton : survol/grisé UNIQUEMENT (echange
 * d'icone gratuit via QIcon::Active/Disabled). PAS d'appuyé ni de focus pour
 * l'icone (event filter custom hors-scope, decision dev — Option A). */
static const StyleStateSlot STATES_styleImageBouton[] = {
    {"survol", "hover",    "_Survol"},
    {"grisé",  "grayed",   "_Grise"},
    {NULL, NULL, NULL}
};

/*  — palette du cadre exterieur : survol/appuyé/focus/grisé. Meme
 * forme que STATES_styleZoneBouton (frame stateful d'un bouton/conteneur), mais
 * le type PLAT sous ..Etats[etat] differe (styleCadreExterieurBase : props du
 * cadre avec Ombre/Dégradé, pas la brique texte du bouton). */
static const StyleStateSlot STATES_styleCadreExterieur[] = {
    {"survol", "hover",    "_Survol"},
    {"appuyé", "pressed",  "_Appuye"},
    {"focus",  "focus",    "_Focus"},
    {"grisé",  "grayed",   "_Grise"},
    {NULL, NULL, NULL}
};

/*  — palette du volet d'un Champ Onglet : survol seul (une languette
 * n'a ni focus ni etat appuye propres). Entree de plein droit dans
 * STYLE_PALETTES, comme les palettes des autres familles : c'est ce qui rend la
 * forme litterale `Etats = { Survol = {...} }` et la cascade
 * `..Etats[survol]..X` disponibles sur styleVolet exactement comme sur
 * styleSaisie / styleBouton. */
static const StyleStateSlot STATES_styleVolet[] = {
    {"survol", "hover", "_Survol"},
    {NULL, NULL, NULL}
};

static const StylePalette STYLE_PALETTES[] = {
    {"styleZoneSaisieEtats", STATES_styleZoneSaisie, "styleZoneSaisieBase"},
    {"styleZoneBoutonEtats", STATES_styleZoneBouton, "styleZoneBoutonBase"},
    {"styleImageBoutonEtats", STATES_styleImageBouton, "styleImageBoutonBase"},
    {"styleCadreExterieurEtats", STATES_styleCadreExterieur, "styleCadreExterieurBase"},
    {"styleVoletEtats", STATES_styleVolet, "styleVoletBase"},
    {NULL, NULL, NULL}
};

/*  — types de style STRUCTURELS (non-collection) : un crochet [etat]
 * directement dessus est une erreur (le crochet doit viser ..Etats). Sert a
 * distinguer une indexation invalide sur un style d'un vrai tableau tab[i]
 * (qui ne resout jamais vers un de ces noms). Compare accent/casse insensible. */
static bool style_type_is_structural(const char* typeName, int typeLen) {
    if (typeName == NULL || typeLen <= 0) return false;
    static const char* const K[] = {
        "styleSaisie", "styleZoneSaisie", "styleZoneSaisieBase",
        "styleLibelle", "styleLibelleSaisie", "styleCadreExterieur",
        "styleCadreExterieurBase",
        "styleBouton", "styleZoneBouton", "styleZoneBoutonBase",
        "styleImageBouton", "styleImageBoutonBase",
        /*  — meme facture de message sur la famille du Champ Onglet :
         * `..VoletActif[survol]` doit dire « le crochet vise Etats », pas
         * tomber sur « variable inconnue ». */
        "styleOnglet", "styleVolet", "styleVoletBase", NULL
    };
    char norm[64];
    int n = scanner_strip_accents(typeName, typeLen, norm, (int)sizeof(norm));
    if (n <= 0) return false;
    for (int i = 0; K[i]; i++) {
        if ((int)strlen(K[i]) == n &&
            strncasecmp(K[i], norm, (size_t)n) == 0) {
            return true;
        }
    }
    return false;
}

/* Retourne la palette d'etats du type donne, ou NULL si ce n'est pas un
 * type de style porteur d'etats. Casse-insensible. */
static const StylePalette* style_palette_for_type(const char* typeName,
                                                  int typeLen) {
    if (typeName == NULL || typeLen <= 0) return NULL;
    for (const StylePalette* p = STYLE_PALETTES; p->styleType; p++) {
        if ((int)strlen(p->styleType) == typeLen &&
            strncasecmp(p->styleType, typeName, (size_t)typeLen) == 0) {
            return p;
        }
    }
    return NULL;
}

/* Resout un identifiant d'etat (accent-strip + casse insensible, FR ou EN)
 * contre une palette. Retourne le slot template, ou NULL si hors palette. */
static const char* style_state_slot(const StylePalette* pal,
                                    const char* stateText, int stateLen) {
    if (!pal || !stateText || stateLen <= 0) return NULL;
    char norm[64];
    int n = scanner_strip_accents(stateText, stateLen, norm, (int)sizeof(norm));
    if (n <= 0) return NULL;
    norm[n] = '\0';
    /* Les formes canon de la table peuvent porter un accent (ex "grisé") : on
     * strip aussi cote table pour comparer accent-a-accent avec `norm` (deja
     * strippe cote input). Sans ca "grisé" (6 octets) ne matcherait jamais la
     * saisie strippee "grise" (5 octets). */
    for (const StyleStateSlot* s = pal->states; s->fr; s++) {
        char frn[64], enn[64];
        int fn = scanner_strip_accents(s->fr, (int)strlen(s->fr), frn, (int)sizeof(frn));
        int en = scanner_strip_accents(s->en, (int)strlen(s->en), enn, (int)sizeof(enn));
        if ((fn == n && strncasecmp(frn, norm, (size_t)n) == 0) ||
            (en == n && strncasecmp(enn, norm, (size_t)n) == 0)) {
            return s->slot;
        }
    }
    return NULL;
}

/* Construit la liste " survol, focus" des etats valides d'une palette
 * (pour les messages d'erreur). Ecrit dans buf, retourne buf. */
static const char* style_states_list(const StylePalette* pal, char* buf,
                                     size_t cap) {
    size_t off = 0;
    buf[0] = '\0';
    for (const StyleStateSlot* s = pal->states; s->fr && off < cap - 1; s++) {
        off += (size_t)snprintf(buf + off, cap - off, "%s%s",
                                s == pal->states ? "" : ", ", s->fr);
    }
    return buf;
}

/*  — ponts minces vers STYLE_PALETTES pour la cascade declarative
 * (definie en amont, avant le type StylePalette). Chacun re-resout la palette
 * du type collection donne ; NULL/vide si le type ne porte pas d'etats. */
static bool style_type_has_palette(const char* type, int len) {
    return style_palette_for_type(type, len) != NULL;
}

static const char* style_palette_resolve_slot(const char* collType, int collTypeLen,
                                              const char* stateText, int stateLen) {
    const StylePalette* pal = style_palette_for_type(collType, collTypeLen);
    return style_state_slot(pal, stateText, stateLen);
}

static const char* style_palette_baseType(const char* collType, int collTypeLen,
                                          int* outBaseLen) {
    const StylePalette* pal = style_palette_for_type(collType, collTypeLen);
    if (pal == NULL || pal->baseType == NULL) {
        if (outBaseLen) *outBaseLen = 0;
        return NULL;
    }
    if (outBaseLen) *outBaseLen = (int)strlen(pal->baseType);
    return pal->baseType;
}

static void style_palette_states_list_for(const char* collType, int collTypeLen,
                                          char* buf, size_t cap) {
    const StylePalette* pal = style_palette_for_type(collType, collTypeLen);
    if (pal == NULL) { if (cap > 0) buf[0] = '\0'; return; }
    style_states_list(pal, buf, cap);
}

/*  — accesseurs de lecture de STYLE_PALETTES pour --vscode-data.
 * La table reste l'unique source de verite ; main.c itere via ces bornes
 * plutot que de dupliquer les etats cote front. */
int compiler_style_palette_count(void) {
    int n = 0;
    for (const StylePalette* p = STYLE_PALETTES; p->styleType; p++) n++;
    return n;
}

const char* compiler_style_palette_type_at(int paletteIdx) {
    if (paletteIdx < 0) return NULL;
    int n = 0;
    for (const StylePalette* p = STYLE_PALETTES; p->styleType; p++, n++)
        if (n == paletteIdx) return p->styleType;
    return NULL;
}

int compiler_style_palette_state_count(int paletteIdx) {
    if (paletteIdx < 0 || paletteIdx >= compiler_style_palette_count()) return 0;
    const StylePalette* p = &STYLE_PALETTES[paletteIdx];
    int n = 0;
    for (const StyleStateSlot* s = p->states; s->fr; s++) n++;
    return n;
}

bool compiler_style_palette_state_at(int paletteIdx, int stateIdx,
                                     const char** outFR, const char** outEN) {
    if (paletteIdx < 0 || paletteIdx >= compiler_style_palette_count()) return false;
    if (stateIdx < 0) return false;
    const StylePalette* p = &STYLE_PALETTES[paletteIdx];
    int n = 0;
    for (const StyleStateSlot* s = p->states; s->fr; s++, n++) {
        if (n == stateIdx) {
            if (outFR) *outFR = s->fr;
            if (outEN) *outEN = s->en;
            return true;
        }
    }
    return false;
}

/*  — index de la palette du type COLLECTION porteur d'etats donne
 * (ex "styleZoneSaisieEtats"), ou -1 si ce type ne porte pas d'etats. Permet
 * a --vscode-data de relier un sous-element (via le type de son membre d'etats)
 * a sa palette sans dupliquer les etats cote main.c. Casse/accent insensible. */
int compiler_style_palette_index_for_type(const char* collTypeName) {
    if (collTypeName == NULL) return -1;
    int n = 0;
    for (const StylePalette* p = STYLE_PALETTES; p->styleType; p++, n++) {
        char norm[64];
        int m = scanner_strip_accents(collTypeName, (int)strlen(collTypeName),
                                      norm, (int)sizeof(norm));
        if (m <= 0) return -1;
        if ((int)strlen(p->styleType) == m &&
            strncasecmp(p->styleType, norm, (size_t)m) == 0) {
            return n;
        }
    }
    return -1;
}

/*  — etats des collections ..Etats des MENUS : survol seul. Parite
 * stricte avec le check parser menu_style_tok_is(stateTok,"survol","hover")
 * (~L22094/22205) : un menu n'expose que l'etat survol. Les menus ne passent
 * pas par STYLE_PALETTES (resolution parser dediee), mais cette table vit
 * cote compiler.c pour rester la source unique cote runtime — le LSP la lit
 * par derivation, jamais en recopie. */
static const StyleStateSlot STATES_menuSurvol[] = {
    {"survol", "hover", NULL},
    {NULL, NULL, NULL}
};
static const struct { const char* etatsType; const StyleStateSlot* states; }
MENU_ETATS_STATES[] = {
    {"styleMenuPrincipalBarreEtats",  STATES_menuSurvol},
    {"styleMenuPrincipalOptionEtats", STATES_menuSurvol},
    {NULL, NULL}
};

/* Resout la liste NULL-terminee des etats indexables via ..Etats[etat] pour un
 * type collection styleXxxEtats donne : widgets via STYLE_PALETTES, menus via
 * MENU_ETATS_STATES. NULL si le type ne porte pas d'etats. Casse/accent
 * insensible. */
static const StyleStateSlot* etats_states_for_type(const char* etatsType) {
    if (etatsType == NULL) return NULL;
    int pi = compiler_style_palette_index_for_type(etatsType);
    if (pi >= 0) return STYLE_PALETTES[pi].states;
    char norm[64];
    int n = scanner_strip_accents(etatsType, (int)strlen(etatsType),
                                  norm, (int)sizeof(norm));
    if (n <= 0) return NULL;
    for (int i = 0; MENU_ETATS_STATES[i].etatsType; i++) {
        if ((int)strlen(MENU_ETATS_STATES[i].etatsType) == n &&
            strncasecmp(MENU_ETATS_STATES[i].etatsType, norm, (size_t)n) == 0)
            return MENU_ETATS_STATES[i].states;
    }
    return NULL;
}

/*  — accesseurs unifies (widgets + menus) des etats valides d'un type
 * collection ..Etats, pour l'expo LSP (dump catalogue + completion). Source
 * unique : STYLE_PALETTES / MENU_ETATS_STATES. */
int compiler_etats_type_state_count(const char* etatsType) {
    const StyleStateSlot* s = etats_states_for_type(etatsType);
    int n = 0;
    for (; s && s->fr; s++) n++;
    return n;
}

bool compiler_etats_type_state_at(const char* etatsType, int stateIdx,
                                  const char** outFR, const char** outEN) {
    const StyleStateSlot* s = etats_states_for_type(etatsType);
    if (s == NULL || stateIdx < 0) return false;
    for (int i = 0; s->fr; s++, i++) {
        if (i == stateIdx) {
            if (outFR) *outFR = s->fr;
            if (outEN) *outEN = s->en;
            return true;
        }
    }
    return false;
}

/*  — types de style RACINE exposes dans l'accordeon du designer.
 * Chaque racine est un struct pur de sous-elements (ZoneSaisie/Libellé/...).
 * Source de verite unique pour l'iteration --vscode-data : main.c derive les
 * sous-elements et leurs etats depuis le registre a partir de cette liste, qui
 * grossit quand un nouveau type de style apparait (futur styleBouton). */
static const char* const STYLE_MODELS[] = {
    "styleSaisie",
    "styleLibell\xc3\xa9",   /* styleLibellé — Champ Libellé */
    "styleBouton",           /* styleBouton — Champ Bouton */
    "styleImage",            /* styleImage — Champ Image */
    "styleCodeBarre",        /* styleCodeBarre — Champ CodeBarres */
    "styleConteneur",        /* styleConteneur — Champ Conteneur */
    "styleInterrupteur",     /* styleInterrupteur — Champ Interrupteur */
    "styleS\xc3\xa9lecteur",  /* styleSélecteur — Champ Sélecteur */
    "styleListe",            /* styleListe — Champ Liste */
    "styleCombo",            /* styleCombo — Champ Combo */
    "styleTable",            /* styleTable — Champ Table */
    "styleJauge",            /* styleJauge — Champ Jauge */
    "styleColonne",          /* styleColonne — override par colonne */
    "styleZoneR\xc3\xa9p\xc3\xa9t\xc3\xa9""e",  /* styleZoneRépétée — Champ Zone répétée */
    /*  — racines de menu NON materialisees : pas de widget, pas de prop
     * Style dans le catalogue, mais leur structure de style se derive du TYPE
     * comme un widget. Sous-elements Barre/SousMenu/OptionMenu (states survol via
     * MENU_ETATS_STATES, exposes par les accesseurs compiler_etats_type_*). */
    "styleMenuPrincipal",    /* styleMenuPrincipal — racine MenuPrincipal */
    "styleMenuContextuel",   /* styleMenuContextuel — racine MenuContextuel */
    /*  — styleOnglet : racine du Champ Onglet. Pas de prop Style DSL
     * (le parser 5b intercepte Style en amont, slots plats ong_*) ; sa structure
     * se derive du TYPE comme un menu. Sous-elements VoletActif/VoletInactif de
     * type partage styleVolet (etat survol via styleVoletEtats). */
    "styleOnglet",           /* styleOnglet — racine Champ Onglet */
    NULL
};

int compiler_style_model_count(void) {
    int n = 0;
    for (const char* const* m = STYLE_MODELS; *m; m++) n++;
    return n;
}

const char* compiler_style_model_type_at(int idx) {
    if (idx < 0) return NULL;
    int n = 0;
    for (const char* const* m = STYLE_MODELS; *m; m++, n++)
        if (n == idx) return *m;
    return NULL;
}

/*  — chemin ETAT du subscript. La cible du `[` est un type de style
 * (pal != NULL) : `[etat]` designe un sous-etat (Survol/Focus), pas un index.
 * Emet OP_STRUCT_GET/SET sur le slot template ; aucun nouvel opcode. */
static void subscript_style_state(bool canAssign, const StylePalette* pal,
                                  const char* styleType, int styleTypeLen) {
    /* Le token courant est l'etat entre crochets. Lu tel quel (pas
     * d'expression) : un etat est un mot-cle contextuel resolu au compile,
     * jamais une valeur runtime. */
    Token stateTok = parser.current;
    advance_token();
    consume(TOKEN_RIGHT_BRACKET, E_SYNTAX_EXP_RBRACKET_STYLE_STATE);

    const char* slot = NULL;
    if (stateTok.type >= TOKEN_IDENTIFIER && stateTok.type < TOKEN_NEWLINE) {
        slot = style_state_slot(pal, stateTok.start, stateTok.length);
    }
    if (slot == NULL) {
        char stateBuf[64];
        int sn = stateTok.length < 63 ? stateTok.length : 63;
        if (sn < 0) sn = 0;
        memcpy(stateBuf, stateTok.start, (size_t)sn);
        stateBuf[sn] = '\0';
        char typeBuf[64];
        int tn = styleTypeLen < 63 ? styleTypeLen : 63;
        memcpy(typeBuf, styleType, (size_t)tn);
        typeBuf[tn] = '\0';
        char listBuf[128];
        style_states_list(pal, listBuf, sizeof(listBuf));
        owl_emit_error_at(&stateTok, E_SEM_STYLE_STATE_INVALID,
                          "state", stateBuf,
                          "type", typeBuf,
                          "states", listBuf,
                          NULL);
        return;
    }

    ConstIdx slotConst = make_constant(OBJ_VAL(obj_copy_string(slot,
                                                    (int)strlen(slot))));
    /*  — le slot ..Etats[etat] est type PLAT (styleZoneSaisieBase),
     * pas la collection. C'est ce type que l'affectation attend et que la
     * cascade `..CouleurFond` doit voir. */
    const char* baseType = pal->baseType ? pal->baseType : styleType;
    int baseTypeLen = (int)strlen(baseType);
    if (canAssign && match_token(TOKEN_EQUAL)) {
        /* ..Etats[etat] = unStyle : affectation complete de la surcharge. Le
         * slot cible est de type `baseType` (styleZoneSaisieBase) — le RHS doit
         * l'etre aussi. Symetrique au rejet de l'affectation de base `..Style =
         * X` (cf. dot(), OWL_PROP_TYPE_OBJECT). Sans ce garde, un scalaire ou un
         * objet d'un autre type passait silencieusement a la compile ET au
         * runtime. Le `=` est deja consomme : parser.current est le
         * premier token du RHS, on le peek sans avancer (expression() reparse
         * ensuite depuis ce meme token). */
        bool scalar = check(TOKEN_INTEGER) || check(TOKEN_REAL) ||
                      check(TOKEN_STRING)  || check(TOKEN_VRAI) ||
                      check(TOKEN_FAUX);
        if (scalar) {
            const char* gotType =
                check(TOKEN_INTEGER) ? "entier" :
                check(TOKEN_REAL)    ? "r\xc3\xa9" "el" :
                check(TOKEN_STRING)  ? "chaine" :
                "bool\xc3\xa9" "en";
            owl_emit_error_at(&stateTok, E_SEM_DSL_OBJECT_PROP_SCALAR,
                              "type", baseType,
                              "got", gotType,
                              NULL);
        } else if (check(TOKEN_IDENTIFIER)) {
            /* RHS identifiant nu d'un type objet incompatible avec baseType
             * (ex `..Etats[focus] = unCadre`). Un sous-type reste accepte
             * (heritage). Meme heuristique isolated/multilingue que la base. */
            Token rhsTok = parser.current;
            const char* rhsStruct = resolve_var_struct_type(rhsTok.start,
                                                            rhsTok.length);
            if (rhsStruct != NULL && rhsStruct[0] != '\0'
                && !struct_name_is_multilingue(rhsStruct)
                && current_identifier_is_isolated()
                && !class_is_same_or_derived(rhsStruct, (int)strlen(rhsStruct),
                                             baseType, baseTypeLen)) {
                owl_emit_error_at(&rhsTok, E_SEM_DSL_OBJECT_PROP_SCALAR,
                                  "type", baseType,
                                  "got", rhsStruct,
                                  NULL);
            }
        }
        expression();
        emit_const_op(OP_STRUCT_SET, slotConst);
    } else {
        /* ..Etats[etat]..X : lecture du slot, la cascade `..X` continue via
         * dot(). Le slot est une sous-instance styleZoneSaisieBase (cf.
         * build_styleZoneSaisieEtats_template) : on type le resultat comme
         * baseType + la voie UI-object pour valider `..CouleurFond`. */
        emit_const_op(OP_STRUCT_GET, slotConst);
        int copy = baseTypeLen < 63 ? baseTypeLen : 63;
        memcpy(g_last_field_type, baseType, (size_t)copy);
        g_last_field_type[copy] = '\0';
        g_last_field_type_len = copy;
        g_last_field_from_ui_object = true;
        g_chain_broken = false;
        int sc = (int)strlen(slot);
        if (sc > 63) sc = 63;
        memcpy(g_last_field_name, slot, (size_t)sc);
        g_last_field_name[sc] = '\0';
        g_last_field_name_len = sc;
    }
}

/*  — le token qui suit le `.`/`..` juste apres un `]` est-il une
 * propriete de mise en forme de cellule ? Deux tokens d'avance, alors que le
 * parser n'en offre qu'un : on scanne sur une COPIE du scanner, sans toucher
 * parser.current/previous ni emettre quoi que ce soit. Un advance_token() +
 * rembobinage aurait pu emettre deux fois une erreur lexicale. */
static bool lookahead_is_table_fmt_prop(void) {
    if (!check(TOKEN_DOT) && !check(TOKEN_DOUBLE_DOT)) return false;
    Scanner sc = parser.scanner;
    Token t;
    do {
        t = scanner_scan_token(&sc);
    } while (t.type == TOKEN_NEWLINE || t.type == TOKEN_SEMICOLON);
    /* Meme acceptation que dot() : identifiant ou mot-cle. */
    if (t.type < TOKEN_IDENTIFIER || t.type >= TOKEN_NEWLINE) return false;
    if (t.length <= 0 || t.length >= 64) return false;
    char buf[64];
    memcpy(buf, t.start, (size_t)t.length);
    buf[t.length] = '\0';
    return owl_table_cell_catalog_find(buf) != NULL;
}

/*  — un nom de colonne REEL de cette Table, pour illustrer la forme
 * colonne-first dans un message d'erreur. Placeholder explicite quand le
 * pre-scan n'en connait aucun : on n'invente pas un nom qui n'existe pas. */
static void table_first_column_hint(const char* table, char* out, size_t cap) {
    char cols[512];
    prescan_widget_child_list(table, cols, sizeof(cols));
    const char* sep = strchr(cols, ',');
    size_t n = (sep != NULL) ? (size_t)(sep - cols) : strlen(cols);
    while (n > 0 && cols[n - 1] == ' ') n--;
    if (n == 0 || n >= cap) {
        snprintf(out, cap, "COL_X");
        return;
    }
    memcpy(out, cols, n);
    out[n] = '\0';
}

/*  — fermeture du `]` d'un indice `tab[i]`. Le scanner fusionne
 * gloutonnement deux `]` adjacents en un seul jeton DOUBLE_BRACKET_CLOSE (`]]`),
 * sans connaitre le contexte. Quand un element indexe termine une construction
 * englobee — indexation imbriquee (`data[idx[1]]`), litteral tableau
 * (`[src[1]]`), litteral argument de Tenseur (`Tenseur([a[1]])`) — le `]` de
 * l'indice colle au `]` englobant : le jeton devient `]]` et le consume(`]`)
 * echouait ("']' attendu apres l'indice."). On scinde le jeton en place — le
 * premier `]` ferme l'indice, le second devient un RIGHT_BRACKET rendu au
 * contexte englobant. Le scanner est deja positionne apres les deux `]` :
 * aucune re-lecture, on relabelle simplement parser.current sans avancer. */
static void consume_index_close(void) {
    if (parser.current.type == TOKEN_DOUBLE_BRACKET_CLOSE) {
        parser.current.type    = TOKEN_RIGHT_BRACKET;
        parser.current.start  += 1;
        parser.current.length  = 1;
        return;
    }
    consume(TOKEN_RIGHT_BRACKET, E_SYNTAX_EXP_RBRACKET_INDEX);
}

/* Index access: expr[idx] or expr[i, j, ..., k] (multi-dim sugar for nested access).
 * `t[i, j]` compiles to the same bytecode as `t[i][j]`: chained ARRAY_GETs
 * (or final ARRAY_SET for assignment). Supports arbitrary arity (nested array-of-array). */
static void subscript(bool canAssign) {
    /*  — chemin ETAT (Style[survol]/Style[focus]). Desambiguise
     * de tab[i] par le TYPE de la cible du `[`, connu en single-pass :
     *   - via cascade `..Style` : g_last_field_type = "styleSaisie" ;
     *   - via variable nue `STY[survol]` : structTypeName du receveur.
     * Un tableau n'a jamais de structTypeName (isArray -> pas de isStruct),
     * donc tab[i] ne peut pas etre detourne ici. */
    {
        char styleTypeBuf[64];
        const char* styleType = NULL;
        int styleTypeLen = 0;
        if (g_last_field_type_len > 0) {
            styleTypeLen = g_last_field_type_len < 63 ? g_last_field_type_len : 63;
            memcpy(styleTypeBuf, g_last_field_type, (size_t)styleTypeLen);
            styleTypeBuf[styleTypeLen] = '\0';
            styleType = styleTypeBuf;
        } else if (g_last_var_token.length > 0) {
            const char* st = resolve_var_style_type_xfile(g_last_var_token.start,
                                                          g_last_var_token.length);
            if (st != NULL) {
                styleTypeLen = (int)strlen(st);
                styleType = st;
            }
        }
        const StylePalette* pal = style_palette_for_type(styleType, styleTypeLen);
        if (pal != NULL) {
            subscript_style_state(canAssign, pal, styleType, styleTypeLen);
            return;
        }
        /*  — crochet [etat] directement sur un type de style
         * STRUCTUREL (styleSaisie / styleZoneSaisie / Libellé / CadreExtérieur /
         * base) : erreur COMPILE. Le crochet ne vit que sur le membre Etats
         * (collection). Break-net de l'ancienne forme racine `Style[survol]`.
         * Un vrai tableau ne resout jamais vers un de ces noms -> tab[i] sauf. */
        if (styleType != NULL &&
            style_type_is_structural(styleType, styleTypeLen)) {
            Token bracketTok = parser.previous;   /* le `[` */
            /* Consomme `[etat]` pour ne pas cascader d'erreurs de parsing. */
            if (!check(TOKEN_RIGHT_BRACKET) && !check(TOKEN_EOF)) advance_token();
            match_token(TOKEN_RIGHT_BRACKET);
            char typeBuf[64];
            int tn = styleTypeLen < 63 ? styleTypeLen : 63;
            memcpy(typeBuf, styleType, (size_t)tn);
            typeBuf[tn] = '\0';
            owl_emit_error_at(&bracketTok, E_SEM_STYLE_INDEX_NOT_COLLECTION,
                              "type", typeBuf,
                              NULL);
            return;
        }
    }
    /*  lot 1 — `TABLE_X[...]` sur un widget Table : on arme le
     * suivi de chaine (le `.COL` suivant designe une cellule) et on refuse
     * l'indice non numerique. Toute autre cible de `[` desarme le suivi. */
    /*  — etat de chaine DEJA arme, lu AVANT le reset : c'est la seule
     * trace qu'un crochet precedent existait sur le meme receveur.  :
     * c'est aussi la SEULE source fiable pour le garde de profondeur —
     * g_last_var_token, lui, pointe la variable d'indice des que l'indice
     * precedent etait un identifiant (`TABLE_X[i][1][1]`), ce qui rendait le
     * garde aveugle a la seule graphie que les gens ecrivent vraiment. */
    char tblPrevTable[128];
    int  tblPrevTableLen = g_table_cell_table_len;
    int  tblPrevDepth    = (tblPrevTableLen > 0) ? g_table_cell_depth : 0;
    if (tblPrevTableLen > 0)
        memcpy(tblPrevTable, g_table_cell_table, (size_t)tblPrevTableLen + 1);
    table_cell_chain_reset();
    zr_cell_chain_reset();   /*  : une ZoneRépétée n'a pas de chaine de crochets a preserver */
    char tblRecvName[128];
    int  tblRecvNameLen = 0;
    int  tblRecvDepth   = 0;
    /* Forme colonne-first `TABLE_X.COL_Y[ligne]` : le crochet rend
     * DEJA la cellule. Une prop du catalogue Table (`..Groupe[...]`) n'est pas
     * une colonne -> pas d'armement. */
    char tblCellCol[128];
    int  tblCellColLen = 0;
    if (tblPrevTableLen > 0 && tblPrevDepth > 0) {
        /*  — crochet SUIVANT sur la meme chaine de designation. Prioritaire
         * sur les deux reconnaissances par nom ci-dessous, qui repartiraient de
         * zero : g_last_var_token pointe encore la Table quand l'indice precedent
         * etait un litteral, et la variable d'indice sinon — deux comptages
         * differents pour la meme faute. L'etat arme, lui, dit la verite dans les
         * deux cas. `tblPrevDepth > 0` isole les chaines de DESIGNATION
         * (crochets) de `TABLE_X[l].COL_Y`, qui rend une valeur : indexer cette
         * valeur n'est pas une sur-designation. */
        tblRecvNameLen = tblPrevTableLen;
        memcpy(tblRecvName, tblPrevTable, (size_t)tblPrevTableLen + 1);
        tblRecvDepth = tblPrevDepth + 1;
    } else {
        OwlControlKind wKind;
        if (g_last_field_type_len == 0 && g_last_field_name_len > 0 &&
            g_last_field_name_len < 128 &&
            g_last_var_token.length > 0 && g_last_var_token.length < 128) {
            char tblBuf[128];
            memcpy(tblBuf, g_last_var_token.start,
                   (size_t)g_last_var_token.length);
            tblBuf[g_last_var_token.length] = '\0';
            const OwlControlKindInfo* wInfo = compiler_prescan_widget_find(tblBuf);
            if (wInfo != NULL && owl_control_kind_of_info(wInfo, &wKind) &&
                wKind == OWL_CONTROL_TABLE &&
                owl_control_catalog_find(OWL_CONTROL_TABLE,
                                         g_last_field_name) == NULL) {
                tblRecvNameLen = g_last_var_token.length;
                memcpy(tblRecvName, tblBuf, (size_t)tblRecvNameLen + 1);
                tblCellColLen = g_last_field_name_len;
                memcpy(tblCellCol, g_last_field_name,
                       (size_t)tblCellColLen + 1);
                /* La colonne nommee vaut le 2e niveau : la cellule est deja
                 * entierement designee, un crochet de plus est de trop. */
                tblRecvDepth = 2;
            }
        }
        if (tblRecvNameLen == 0 &&
            g_last_field_name_len == 0 && g_last_field_type_len == 0 &&
            g_last_var_token.length > 0 && g_last_var_token.length < 128) {
            char tblBuf[128];
            memcpy(tblBuf, g_last_var_token.start,
                   (size_t)g_last_var_token.length);
            tblBuf[g_last_var_token.length] = '\0';
            const OwlControlKindInfo* wInfo = compiler_prescan_widget_find(tblBuf);
            if (wInfo != NULL && owl_control_kind_of_info(wInfo, &wKind) &&
                wKind == OWL_CONTROL_TABLE) {
                tblRecvNameLen = g_last_var_token.length;
                memcpy(tblRecvName, tblBuf, (size_t)tblRecvNameLen + 1);
                tblRecvDepth = 1;
            }
        }
    }
    if (tblRecvNameLen > 0) {
        /*  — 1 crochet = une ligne, 2 = une cellule (ou 1 crochet
         * derriere une colonne nommee). Au-dela il n'y a plus rien a
         * designer : refus nomme ici plutot qu'un « seuls les tableaux ou
         * les combinaisons peuvent etre indexes » a l'execution, qui ne
         * nomme pas la cause. */
        if (tblRecvDepth >= 3) {
            char colHint[128];
            table_first_column_hint(tblRecvName, colHint, sizeof(colHint));
            owl_emit_error_at(&parser.previous,
                              E_SEM_TABLE_INDEX_TOO_DEEP,
                              "table", tblRecvName,
                              "colonne", colHint,
                              NULL);
        }
        /* `TABLE_X[TABLE_X]` — l'idiome « ligne courante ». L'indice
         * est un nom de champ, jamais un numero de ligne : refus
         * nomme, avec l'alternative qui existe (TableSelect). */
        if (check(TOKEN_IDENTIFIER) && parser.current.length < 128) {
            char idxBuf[128];
            memcpy(idxBuf, parser.current.start,
                   (size_t)parser.current.length);
            idxBuf[parser.current.length] = '\0';
            if (compiler_prescan_widget_find(idxBuf) != NULL) {
                owl_emit_error_at(&parser.current,
                                  E_SEM_TABLE_ROW_INDEX_NOT_NUMBER,
                                  "table", tblRecvName,
                                  "index", idxBuf,
                                  NULL);
            }
        }
    }
    /*  — receveur Sélecteur / Interrupteur : `SEL_X[i]` designe une
     * OPTION. Capture du kind AVANT de compiler l'indice, qui ecrase
     * g_last_var_token des qu'il est un identifiant ; re-armement apres
     * l'OP_ARRAY_GET, comme le suivi Table. */
    bool optRecvFound = false;
    bool optRecvInter = false;
    if (tblRecvNameLen == 0 &&
        g_last_field_name_len == 0 && g_last_field_type_len == 0 &&
        g_last_var_token.length > 0 && g_last_var_token.length < 128) {
        char optBuf[128];
        memcpy(optBuf, g_last_var_token.start,
               (size_t)g_last_var_token.length);
        optBuf[g_last_var_token.length] = '\0';
        OwlControlKind oKind;
        const OwlControlKindInfo* oInfo = compiler_prescan_widget_find(optBuf);
        if (oInfo != NULL && owl_control_kind_of_info(oInfo, &oKind) &&
            (oKind == OWL_CONTROL_SELECTEUR ||
             oKind == OWL_CONTROL_INTERRUPTEUR)) {
            optRecvFound = true;
            optRecvInter = (oKind == OWL_CONTROL_INTERRUPTEUR);
        }
    }
    /*  — receveur ZoneRépétée : `ZR_X[i]` designe une ligne ; le `.field`
     * suivant doit nommer un enfant declare de CETTE ZoneRépétée. Meme capture
     * AVANT l'index que la Table / l'option, re-armee apres l'OP_ARRAY_GET. Une
     * chaine nue seulement (pas de field/type intermediaire) : `obj.membre[i]`
     * n'est pas une ligne de ZoneRépétée. */
    bool zrRecvFound = false;
    char zrRecvName[128];
    int  zrRecvNameLen = 0;
    if (tblRecvNameLen == 0 && !optRecvFound &&
        g_last_field_name_len == 0 && g_last_field_type_len == 0 &&
        g_last_var_token.length > 0 && g_last_var_token.length < 128) {
        char zrBuf[128];
        memcpy(zrBuf, g_last_var_token.start,
               (size_t)g_last_var_token.length);
        zrBuf[g_last_var_token.length] = '\0';
        OwlControlKind zKind;
        const OwlControlKindInfo* zInfo = compiler_prescan_widget_find(zrBuf);
        if (zInfo != NULL && owl_control_kind_of_info(zInfo, &zKind) &&
            zKind == OWL_CONTROL_ZONE_REPETEE) {
            zrRecvFound = true;
            zrRecvNameLen = g_last_var_token.length;
            memcpy(zrRecvName, zrBuf, (size_t)zrRecvNameLen + 1);
        }
    }
    /*  — type d'element STRUCTURE/CLASSE user d'un `tableau de <TypeUser>`,
     * capture AVANT l'index (l'expression d'indice passe par named_variable et
     * ecrase g_last_var_token). Uniquement sur un receveur NU (pas de chaine
     * field/type en cours), sinon `obj.membre[i]` n'est pas concerne. Propage
     * comme type de receveur APRES l'OP_ARRAY_GET mono-index pour que le dot()
     * suivant refuse `t[i]..prop` du registre masque, comme sur toute autre
     * position (variable, parametre, champ, retour). */
    char arrElemStructBuf[64];
    int  arrElemStructLen = 0;
    if (g_last_field_name_len == 0 && g_last_field_type_len == 0 &&
        g_last_var_token.length > 0) {
        const char* es = resolve_var_array_element_struct(g_last_var_token.start,
                                                          g_last_var_token.length);
        if (es != NULL) {
            int n = (int)strlen(es);
            if (n > 63) n = 63;
            memcpy(arrElemStructBuf, es, (size_t)n);
            arrElemStructBuf[n] = '\0';
            arrElemStructLen = n;
        }
    }
    /* Après un subscript, le receveur effectif est l'élément (type imprécis
     * côté compileur). On marque g_chain_broken pour empêcher les strict
     * dot checks suivants de retomber par erreur sur le receiver original
     * (ex. `points[1]..X` : points est un tableau, mais l'élément est
     * une structure). */
    g_chain_broken = true;
    g_last_field_type[0] = '\0';
    g_last_field_type_len = 0;
    /* First index */
    expression();

    if (!match_token(TOKEN_COMMA)) {
        /* 1 seul index : comportement standard arr[i] / arr[i] = v. */
        consume_index_close();
        /*  — Interrupteur : `INT_X[i]` NU (aucun `..` derriere) designe
         * la COCHE (0/1/-1), pas la struct d'option. Canon : `INT_X[n]` ≡
         * `INT_X[n]..Valeur`. On desucre donc la forme nue vers la propriete
         * Valeur : OP_ARRAY_GET (proxy d'option) + OP_STRUCT_GET/SET "Valeur".
         * La forme `INT_X[i]..prop` (un `..` suit) garde le chemin propriete
         * inchange ( Libellé/SousLibellé). Le Sélecteur n'a pas de coche
         * par option : sa forme nue est laissee au comportement existant. */
        /* NU = ni `..prop` (acces propriete valide) ni `.prop` (point simple, que
         * dot() refuse en nommant la forme double-point). Les deux designent la
         * struct d'option, pas la coche : ne pas desucrer. */
        bool interOptNu = optRecvFound && optRecvInter
                          && !check(TOKEN_DOUBLE_DOT) && !check(TOKEN_DOT);
        Token valeurTok = parser.previous;
        valeurTok.start  = "Valeur";
        valeurTok.length = 6;
        if (canAssign && match_token(TOKEN_EQUAL)) {
            /*  — RHS absent en fin de ligne sur cible indexee (`t[i] =`) :
             * le NEWLINE apres `=` a ete skippe (crossedNewline). On refuse, ancre
             * sur le `=`, plutot que d'avaler la ligne suivante comme operande. */
            if (crossedNewline) { owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR); return; }
            if (interOptNu) {
                /* Ecriture nue = pose de coche : [ref, idx] -> OP_ARRAY_GET ->
                 * [option] ; puis la valeur ; puis STRUCT_SET "Valeur" (qui
                 * dispatche la validation -1 / mode par option cote runtime). */
                emit_byte(OP_ARRAY_GET);
                expression();
                emit_const_op(OP_STRUCT_SET, identifier_constant(&valeurTok));
                ui_option_chain_reset();
                table_cell_chain_reset();
                zr_cell_chain_reset();
                return;
            }
            expression();
            emit_byte(OP_ARRAY_SET);
        } else if (interOptNu) {
            /* Lecture nue = coche : OP_ARRAY_GET + STRUCT_GET "Valeur". */
            emit_byte(OP_ARRAY_GET);
            emit_const_op(OP_STRUCT_GET, identifier_constant(&valeurTok));
            ui_option_chain_reset();
            table_cell_chain_reset();
            zr_cell_chain_reset();
            return;
        } else {
            /*  — forme colonne-first `TABLE_X.COL_Y[ligne]`. Le meme
             * crochet rend soit la VALEUR de la cellule, soit la
             * cellule elle-meme quand une propriete de mise en forme suit.
             * L'execution ne peut pas trancher : quand elle voit le `..`, la
             * valeur est deja lue. La discrimination est donc ici, sur le
             * lookahead de ce qui suit le `]`. */
            bool wantCellDesc = false;
            if (tblCellColLen > 0)
                wantCellDesc = lookahead_is_table_fmt_prop();
            emit_byte(wantCellDesc ? OP_TABLE_CELL_DESC : OP_ARRAY_GET);
            /*  lot 1 — armement APRES l'index : l'expression
             * d'indice passe par named_variable, qui reset le suivi. */
            if (tblRecvNameLen > 0) {
                g_table_cell_table_len = tblRecvNameLen;
                memcpy(g_table_cell_table, tblRecvName,
                       (size_t)tblRecvNameLen + 1);
                g_table_cell_depth = tblRecvDepth;
                /* `g_table_cell_col` arme le refus « la cellule est une
                 * valeur ». Sur le chemin descripteur il n'y a rien a refuser :
                 * la propriete qui suit est justement celle qu'on sert. */
                if (tblCellColLen > 0 && !wantCellDesc) {
                    g_table_cell_col_len = tblCellColLen;
                    memcpy(g_table_cell_col, tblCellCol,
                           (size_t)tblCellColLen + 1);
                }
            } else {
                /* Receveur non-Table : l'indice a pu armer la chaine en cours de
                 * route (`tab[TABLE_X[1]]`). Sans ce desarmement, le crochet
                 * suivant se croirait sur la Table. */
                table_cell_chain_reset();
            }
            /*  — meme armement retarde pour l'option indexee, et meme
             * desarmement quand le receveur n'en est pas une (`tab[SEL_X[1]]`). */
            if (optRecvFound) {
                g_ui_option_armed = true;
                g_ui_option_is_interrupteur = optRecvInter;
            } else {
                ui_option_chain_reset();
            }
            /*  — meme armement retarde pour la ligne de ZoneRépétée. */
            if (zrRecvFound) {
                g_zr_cell_zr_len = zrRecvNameLen;
                memcpy(g_zr_cell_zr, zrRecvName, (size_t)zrRecvNameLen + 1);
            } else {
                zr_cell_chain_reset();
            }
            /*  — l'element rendu par `t[i]` est une structure/classe
             * utilisateur : propage son type comme receveur pour le dot() suivant.
             * Un receveur Table/option/ZoneRépétée ne resout jamais ici (leur
             * variable n'a pas d'arrayElemStructType) : pas de collision. Le
             * dot() lit ce type via recvType (recvTypeFromChain) et refuse
             * `t[i]..prop` du registre masque. */
            if (arrElemStructLen > 0) {
                memcpy(g_last_field_type, arrElemStructBuf,
                       (size_t)arrElemStructLen);
                g_last_field_type[arrElemStructLen] = '\0';
                g_last_field_type_len = arrElemStructLen;
            }
        }
        return;
    }

    /* Au moins 2 indices. On veut distinguer :
     *   - exactement 2 (`recv[x, y]`) → OP_ARRAY_GET_2D / OP_ARRAY_SET_2D
     *     (dispatch runtime Image vs tableau 2D nested, doc
     *     Multimedia/Images/1000019650 §"Accès aux pixels").
     *   - 3+ (`recv[x, y, z, ...]`) → chaîne legacy de OP_ARRAY_GET
     *     intercalés (préserve l'usage existant des tableaux ND).
     *
     * Le souci : pour respecter l'ordre des push (stack = [recv][x][y])
     * en 2D, on doit émettre la 2e expression avant de savoir s'il y a
     * une 3e virgule. Si finalement il y en a une, on rewind le chunk
     * et le scanner et on réémet en mode legacy (OP_ARRAY_GET intercalé
     * entre chaque expression). Pattern emprunté à
     * try_intercept_type_est_nullable. */
    Scanner savedScanner = parser.scanner;
    Token   savedPrev    = parser.previous;
    Token   savedCurr    = parser.current;
    int     savedChunkCount = current_chunk()->count;

    expression();  /* 2e index — peut être réémis si 3+ */

    if (match_token(TOKEN_COMMA)) {
        /* 3+ indices détectés : rewind à l'état d'avant la 2e expression
         * et utiliser le mode legacy. */
        parser.scanner   = savedScanner;
        parser.previous  = savedPrev;
        parser.current   = savedCurr;
        current_chunk()->count = savedChunkCount;

        emit_byte(OP_ARRAY_GET);   /* descend recv[x] -> recv' */
        expression();              /* 2e index re-parsed */
        while (match_token(TOKEN_COMMA)) {
            emit_byte(OP_ARRAY_GET);
            expression();
        }
        consume_index_close();
        if (canAssign && match_token(TOKEN_EQUAL)) {
            /*  — RHS absent en fin de ligne (cf. cas 1 index). */
            if (crossedNewline) { owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR); return; }
            expression();
            emit_byte(OP_ARRAY_SET);
        } else {
            emit_byte(OP_ARRAY_GET);
        }
        return;
    }

    /* Exactement 2 indices : opcode dédié. */
    consume_index_close();
    if (canAssign && match_token(TOKEN_EQUAL)) {
        /*  — RHS absent en fin de ligne (cf. cas 1 index). */
        if (crossedNewline) { owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR); return; }
        expression();
        emit_byte(OP_ARRAY_SET_2D);
    } else {
        emit_byte(OP_ARRAY_GET_2D);
    }
}

/* Compile-time intercept for TypeEstNullable(identifier). Returns true if
 * the call was handled. Only the simple `TypeEstNullable(name)` form is
 * supported — complex expressions fall through to the native which returns
 * Faux. */
static bool try_intercept_type_est_nullable(Token name) {
    if (name.length != 15) return false;
    if (strncmp(name.start, "TypeEstNullable", 15) != 0) return false;
    if (!check(TOKEN_LEFT_PAREN)) return false;

    /* Save parser state so we can roll back if the argument isn't a simple
     * identifier (then the native handles it). */
    Scanner savedScanner = parser.scanner;
    Token   savedPrev    = parser.previous;
    Token   savedCurr    = parser.current;

    advance_token(); /* consume '(' */
    if (!check(TOKEN_IDENTIFIER)) {
        parser.scanner = savedScanner;
        parser.previous = savedPrev;
        parser.current  = savedCurr;
        return false;
    }
    Token argTok = parser.current;
    advance_token();
    if (!match_token(TOKEN_RIGHT_PAREN)) {
        parser.scanner = savedScanner;
        parser.previous = savedPrev;
        parser.current  = savedCurr;
        return false;
    }

    bool isNullable = false;
    int localIdx = resolve_local(current, &argTok);
    if (localIdx != -1) {
        isNullable = current->locals[localIdx].isNullable;
    } else {
        int gi = typed_globals_find(argTok.start, argTok.length);
        isNullable = (gi >= 0) && g_typed_globals[gi].isNullable;
        /* Mark global as used (TypeEstNullable accesses it at compile time) */
        if (current->type == TYPE_SCRIPT) {
            global_track_mark_used(argTok.start, argTok.length);
        }
    }
    emit_constant(BOOL_VAL(isNullable));
    return true;
}

/* Compile-time intercept for Exécute(proc, args...). The first argument is
 * the callee (a Procédure value, function reference, or any callable value),
 * subsequent arguments are passed positionally. Compiles down to OP_CALL.
 * The accented "Exécute" is reduced to "Execute" at identifier compare time
 * because the scanner strips accents for keyword matching (but not for free
 * identifiers); accept both spellings explicitly. */
static bool try_intercept_execute(Token name) {
    bool matches = (name.length == 7 && memcmp(name.start, "Execute", 7) == 0)
                || (name.length == 8 && memcmp(name.start, "Ex\xc3\xa9""cute", 8) == 0)
                || (name.length == 8 && memcmp(name.start, "Ex\xe9""cute", 7) == 0);
    if (!matches) return false;
    if (!check(TOKEN_LEFT_PAREN)) return false;

    advance_token(); /* consume '(' */
    /* First argument: the callee. */
    if (check(TOKEN_RIGHT_PAREN)) {
        owl_emit_error_at(&parser.previous, E_SEM_EXECUTE_NEEDS_PROC_ARG);
        return true;
    }
    condition_expression(); /* pushes callee */

    /* Remaining args. */
    int argCount = 0;
    while (match_token(TOKEN_COMMA)) {
        if (argCount == 255) owl_emit_error_at(&parser.previous, E_SYNTAX_CALL_TOO_MANY_ARGS);
        condition_expression();
        argCount++;
    }
    consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_EXECUTE_ARGS);
    emit_bytes(OP_CALL, (uint8_t)argCount);
    return true;
}

/* Detect the procedure-hook pattern `IDENT.Avant = expr` /
 * `IDENT.Après = expr` and compile it as:
 *   GET ident; <expr>; OP_PROC_SET_HOOK k; SET ident
 * so that a plain function gets auto-promoted to a chain on the first hook
 * assignment. Returns true if the pattern was matched and compiled. */
static bool try_intercept_proc_hook_assign(Token name, bool canAssign) {
    if (!canAssign) return false;
    if (!check(TOKEN_DOT)) return false;
    /* Save parser state for rollback if this isn't the pattern. */
    Scanner savedScanner = parser.scanner;
    Token savedPrev = parser.previous;
    Token savedCurr = parser.current;

    advance_token(); /* '.' */
    if (!check(TOKEN_IDENTIFIER)) goto rollback;
    Token fieldTok = parser.current;
    int hookKind = -1;
    if (fieldTok.length == 5 && memcmp(fieldTok.start, "Avant", 5) == 0) hookKind = 0;
    else if (fieldTok.length == 5 && memcmp(fieldTok.start, "Apres", 5) == 0) hookKind = 1;
    else if (fieldTok.length == 6 && memcmp(fieldTok.start, "Apr\xc3\xa8s", 6) == 0) hookKind = 1;
    else if (fieldTok.length == 6 && memcmp(fieldTok.start, "Apr\xe8s", 5) == 0) hookKind = 1;
    if (hookKind < 0) goto rollback;
    advance_token(); /* field */
    if (!match_token(TOKEN_EQUAL)) goto rollback;

    /* Resolve the variable so we know its getOp/setOp/arg. */
    uint8_t getOp, setOp;
    int arg = resolve_local(current, &name);
    if (arg != -1) { getOp = OP_GET_LOCAL; setOp = OP_SET_LOCAL; }
    else {
        arg = const_idx_i(identifier_constant(&name));
        getOp = OP_GET_GLOBAL; setOp = OP_SET_GLOBAL;
    }

    emit_var_op(getOp, arg);  /* push current p */
    expression();                      /* push RHS */
    emit_bytes(OP_PROC_SET_HOOK, (uint8_t)hookKind);
    emit_var_op(setOp, arg);   /* write updated chain back to p */
    return true;

rollback:
    parser.scanner = savedScanner;
    parser.previous = savedPrev;
    parser.current  = savedCurr;
    return false;
}

/* Whitelist of pure string-returning natives that the peephole is
 * allowed to accept as the RHS of `s = s + fn(...)`. These must:
 *   - always return a string (so appending is sound);
 *   - have NO side effects on the LHS slot (no write to `s`, no call-
 *     back into user code that could alter it);
 *   - be deterministic w.r.t. their arguments (same in, same out).
 * The guarantee comes from the fact that all these functions live in
 * stdlib_string.c / stdlib_crypto.c with pure, local implementations.
 * Adding to this list requires verifying the implementation.
 * Function names must be listed exactly as emitted (identifier_constant
 * uses the source token verbatim, so case-sensitive). */
static const char* PURE_STRING_NATIVES[] = {
    "Milieu", "MilieuChaine", "Middle",
    "Gauche", "Left",
    "Droite", "Right",
    "Remplace", "Replace",
    "MajChaine", "Majuscule", "Upper",
    "MinChaine", "Minuscule", "Lower",
    "Inverse", "Reverse",
    "Repete", "Repeat",
    "SansEspace", "NoSpace",  /*  : forme EN canon de SansEspace */
    NULL
};

static bool is_pure_string_native(const char* name, int length) {
    for (int i = 0; PURE_STRING_NATIVES[i] != NULL; i++) {
        const char* p = PURE_STRING_NATIVES[i];
        size_t pl = strlen(p);
        if ((size_t)length == pl && memcmp(p, name, pl) == 0) return true;
    }
    return false;
}

/* ----------------------------------------------------------------
 * Peephole: detect `s = s + <rhs>` (or `s += <rhs>`) on a string-typed
 * variable and emit OP_APPEND_IN_PLACE instead of the usual GET/expr/
 * ADD/SET sequence. Makes `POUR i = 1 _A_ N : s = s + fn(...) : FIN`
 * run in O(n) instead of O(n²) by having the VM mutate `s` in place.
 *
 * Returns true on successful rewrite (caller must NOT emit setOp).
 *
 * Two accepted shapes, reconnues par une marche AVANT depuis `startPos`
 * (position du bytecode du RHS, connue du caller) :
 *   1. SIMPLE   [getOp][arg][rhs_load][rhs_arg][OP_ADD]
 *      where rhs_load is OP_CONSTANT / OP_GET_LOCAL / OP_GET_GLOBAL.
 *   2. EXTENDED [getOp][arg]
 *                [OP_GET_GLOBAL_CALLEE][callee_idx]
 *                <argCount simple loads>
 *                [OP_CALL][argCount]
 *                [OP_ADD]
 *      where the callee at `callee_idx` is a name from the pure-native
 *      whitelist above.
 *
 * Pattern (2) is the one that unlocks `s = s + Milieu(x, i, 1)` hot
 * loops (CLBG k_nucleotide and similar).
 *
 *  — la reconnaissance se faisait par arithmetique ARRIERE en
 * supposant « toute instruction fait 2 octets ». Les index de constante
 * passes a 16 bits, cette hypothese est fausse et un decodage arriere est de
 * toute facon ambigu quand les tailles varient. On marche donc vers l'avant
 * depuis un point d'ancrage sur, avec la table canonique de tailles.
 *
 * False negatives (multi-step expressions, non-whitelisted calls,
 * nested calls, complex args) are fine: they fall back to the standard
 * concat path.
 * ---------------------------------------------------------------- */
static bool is_simple_load_op(uint8_t op) {
    return op == OP_CONSTANT || op == OP_GET_LOCAL || op == OP_GET_GLOBAL;
}

static bool try_emit_string_append(int startPos, int arg, uint8_t setOp,
                                   int lhsDeclaredType) {
    /* Only safe when the compiler can prove the LHS is a string. Without
     * this guard, any `total += val` on integers would be miscompiled into
     * a string concatenation by the OP_APPEND fallback path. */
    if (lhsDeclaredType != TOKEN_CHAINE) return false;

    /* Determine matching GET opcode + final OP_APPEND opcode. */
    uint8_t getOp;
    uint8_t appendOp;
    if (setOp == OP_SET_LOCAL) {
        getOp = OP_GET_LOCAL;
        appendOp = OP_APPEND_IN_PLACE;
    } else if (setOp == OP_SET_GLOBAL) {
        getOp = OP_GET_GLOBAL;
        appendOp = OP_APPEND_IN_PLACE_GLOBAL;
    } else {
        return false;
    }

    Chunk* ck = current_chunk();
    uint8_t* c = ck->code;
    int n = ck->count;
    if (startPos < 0 || startPos >= n) return false;
    if (c[n - 1] != OP_ADD) return false;
    int line = ck->lines[n - 1];

    /* Le RHS doit commencer par la relecture de la variable elle-meme. */
    int getLen = chunk_opcode_size(getOp, ck, startPos);
    if (getLen <= 0 || startPos + getLen > n) return false;
    if (c[startPos] != getOp) return false;
    if (read_const_or_slot_operand(ck, startPos) != arg) return false;

    int pos = startPos + getLen;

    /* ---- Shape 1: simple RHS load ---- */
    if (is_simple_load_op(c[pos])) {
        int rhsLen = chunk_opcode_size(c[pos], ck, pos);
        if (rhsLen > 0 && pos + rhsLen == n - 1) {
            /* Rewind : on recopie la charge du RHS en tete, puis l'append. */
            uint8_t rhs[1 + OWL_CONST_IDX_BYTES];
            memcpy(rhs, c + pos, (size_t)rhsLen);
            ck->count = startPos;
            for (int k = 0; k < rhsLen; k++) chunk_write(ck, rhs[k], line);
            write_var_op(ck, appendOp, arg, line);
            return true;
        }
    }

    /* ---- Shape 2: pure whitelisted call as RHS ---- */
    int callee_pos = pos;
    if (c[callee_pos] != OP_GET_GLOBAL_CALLEE) return false;
    int calleeLen = chunk_opcode_size(OP_GET_GLOBAL_CALLEE, ck, callee_pos);
    if (calleeLen <= 0) return false;
    pos = callee_pos + calleeLen;

    /* Chaque argument doit etre une charge simple. Rejette les appels
     * imbriques, les expressions arithmetiques en argument, etc. Ces formes
     * restent correctes via le chemin OP_ADD standard, on ne les reecrit
     * simplement pas. */
    int argCount = 0;
    while (pos < n && is_simple_load_op(c[pos])) {
        int len = chunk_opcode_size(c[pos], ck, pos);
        if (len <= 0) return false;
        pos += len;
        if (++argCount > 5) return false;
    }
    /* Il doit rester exactement [OP_CALL][argCount][OP_ADD]. */
    if (pos + 3 != n) return false;
    if (c[pos] != OP_CALL || c[pos + 1] != (uint8_t)argCount) return false;

    /* Look up the callee name in the constants table and match against
     * the pure-native whitelist. */
    int cidx = read_const_or_slot_operand(ck, callee_pos);
    if (cidx < 0 || cidx >= ck->constants.count) return false;
    Value calleeVal = ck->constants.values[cidx];
    if (!IS_STRING(calleeVal)) return false;
    ObjString* calleeName = AS_STRING(calleeVal);
    if (!is_pure_string_native(calleeName->chars, calleeName->length)) return false;

    int get_pos    = startPos;
    int call_bytes = n - 1 - callee_pos;   /* callee + args + OP_CALL(2) */

    /* Apply the rewrite:
     *   Before:  [getOp][arg] <call_bytes...> [OP_ADD]
     *   After:   <call_bytes...> [appendOp][arg]
     *
     * On decale l'appel vers la gauche (on retire [getOp][arg]) puis on
     * remplace l'OP_ADD final par [appendOp][arg]. */
    memmove(c + get_pos, c + callee_pos, (size_t)call_bytes);
    /* Adjust lines[] in parallel so debug info stays aligned. */
    memmove(ck->lines + get_pos, ck->lines + callee_pos,
            (size_t)call_bytes * sizeof(ck->lines[0]));
    ck->count = get_pos + call_bytes;
    write_var_op(ck, appendOp, arg, line);
    return true;
}

/* True when parser.previous is an IDENTIFIER that names a registered native
 * function — used to detect bare dangling references like `HTTPRequête` on
 * its own line. Returns NULL if not applicable. */
static const OwlNativeDef* bare_identifier_as_native(Token* t) {
    if (t->type != TOKEN_IDENTIFIER) return NULL;
    char probe[128];
    int n = t->length < (int)sizeof(probe) - 1 ? t->length : (int)sizeof(probe) - 1;
    memcpy(probe, t->start, n);
    probe[n] = '\0';
    return owl_registry_find(probe);
}

/* Check whether a global identifier name resolves to something known at
 * compile time. Scans in this order:
 *   1. Globals declared earlier in this file (g_declaredGlobals)
 *   2. Project-wide symbols from prescan (cross-file procedures, classes…)
 *   3. Registry: natives, constants (httpGet, RC…), builtin types
 *   4. User-declared types (structures/classes/enums in any loaded file)
 *
 * Returns false only when the name belongs to NONE of those — meaning a
 * typo or a call to something that doesn't exist. */
static bool is_known_global_name(const char* name, int length) {
    if (length <= 0) return true;  /* defensive: don't flag weirdness */

    /*  — un membre de collection mangled `COL$membre` est connu des que
     * le couple (COL, membre) est enregistre (define-side ou hydrate). Necessaire
     * car la resolution nom-nu reecrit vers cette forme, absente de
     * g_declaredGlobals du fichier LECTEUR (la collection vit ailleurs). */
    {
        const void* dollar = memchr(name, '$', (size_t)length);
        if (dollar != NULL && dollar != name) {
            int clen = (int)((const char*)dollar - name);
            int mlen = length - clen - 1;
            if (mlen > 0 &&
                collection_member_has(name, clen, (const char*)dollar + 1, mlen)) {
                return true;
            }
        }
    }

    /* 1. Globals declared earlier in this file */
    for (int i = decl_globals_bucket_head(name, length); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (decl_globals_match(i, name, length)) {
            return true;
        }
    }

    /* 2. Cross-file project symbols (pre-scanned procedures, classes…) */
    if (projectSymbols != NULL) {
        bool ambiguous = false;
        if (symtable_find(projectSymbols, name, length, &ambiguous) != NULL) {
            return true;
        }
    }

    /* 3. Registry lookups (natives, constants, types) — case+accent insensitive */
    char probe[128];
    int n = length < (int)sizeof(probe) - 1 ? length : (int)sizeof(probe) - 1;
    memcpy(probe, name, n);
    probe[n] = '\0';
    if (owl_registry_find(probe)       != NULL) return true;
    if (owl_registry_const_find(probe) != NULL) return true;
    if (owl_registry_type_find(probe)  != NULL) return true;

    /* 4. User-declared structs/classes/enums dans ce fichier.
     * Les builtins (Chrono, httpRequête, Cadre, Coin, zipArchive…) sont
     * deja attrapes par owl_registry_type_find ci-dessus — plus de
     * hardcoded list paralelle a maintenir. */
    if (is_known_user_type(name, length)) return true;

    /* 5. Widgets pre-scannes de la fenetre/etat courante (forward-ref).
     * Le compilo est single-pass : un widget reference AVANT sa declaration
     * source (PROCEDURE/event place avant `WIDGET est un ...`) n'est pas
     * encore dans vm.globals au moment de compiler le body. Le prescan
     * widgets (prescan_source_unified) recense tous les widgets de la
     * fenetre/etat avec leur kind AVANT le compile principal : on l'autorise
     * ici pour que la reference se resolve quel que soit l'ordre. Le widget
     * VRAIMENT inexistant reste absent du prescan -> erreur nominative. */
    {
        char wbuf[128];
        int wn = length < (int)sizeof(wbuf) - 1 ? length : (int)sizeof(wbuf) - 1;
        memcpy(wbuf, name, (size_t)wn);
        wbuf[wn] = '\0';
        if (compiler_prescan_widget_find(wbuf) != NULL) return true;
    }

    /* 6. Anything already sitting in vm.globals at compile time — covers
     * raw table_set() registrations (e.g. owlEntier, WL_* constants in
     * stdlib_reflect.c, ErreurDetectee) that bypass the OwlRegistry.
     * Phase 2b : lookup via l'index canon de vm.globals, qui rend la
     * resolution insensible casse+accents pour ces entrees aussi. */
    {
        char canonBuf[256];
        int canonLen = scanner_canonicalize_identifier(name, length,
                                                       canonBuf, sizeof(canonBuf));
        ObjString* canonKey = obj_copy_string(canonBuf, canonLen);
        Value dummy;
        if (table_get(&vm.globals_canon_idx, canonKey, &dummy)) return true;
    }

    return false;
}

/*  — un nom nu candidat au receveur colonne est-il deja un
 * symbole GENUINE qui doit garder la priorite (arbre de decision : « deja connu
 * -> inchange ») ? Reprend les criteres de is_known_global_name SAUF la table
 * des symboles projet : une colonne homonyme intra-fenetre y fuite (le pre-scan
 * la catalogue comme symbole des que deux Tables la declarent), et cette fuite
 * ne doit pas eteindre la resolution colonne — sinon la forme nue redevient un
 * OP_GET_GLOBAL fantome (compile propre, no-op runtime) au lieu du refus
 * d'homonymie attendu. Un VRAI global/local reste capte par g_declaredGlobals,
 * le registry, les types user, les widgets prescannes ou vm.globals. */
/*  — FONCTION LOAD-BEARING : NE PAS SUPPRIMER SANS PASSER PAR SON VERROU.
 * Le garde `!bare_column_name_shadowed(...)` de named_variable (plus bas) en
 * depend : sans elle, la forme NUE d'un nom de colonne homonyme redevient un
 * OP_GET_GLOBAL fantome (compile propre, no-op runtime) au lieu du refus
 * d'homonymie attendu.
 * INCIDENT : effacee (+ rebranch de named_variable sur is_known_global_name) par
 * des hunks non commites de , absorbes par accident dans le commit
 * checkpoint 2618940a4 de  (contamination compiler.c multi-agents). La
 * cloture de  A VU la contamination mais l'a jugee « effet fonctionnel
 * nul » sur la foi de `make quick` — qui N'EXECUTE PAS la batterie compile-error :
 * le snapshot ci-dessous etait pourtant ROUGE et l'est reste ~8 tickets (classe a
 * tort « travail parallele » sans repro ni datation). Restauree OCTET POUR OCTET
 * a la version  par e53e11117.
 * VERROU : tests/compile-error/table_colonne_receveur_couleur_bare_homonyme
 * (+ _non_premiere) rougit si cette fonction ou son appel disparait. */
static bool bare_column_name_shadowed(const char* name, int length) {
    if (length <= 0) return true;
    for (int i = decl_globals_bucket_head(name, length); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (decl_globals_match(i, name, length)) return true;
    }
    char probe[128];
    int n = length < (int)sizeof(probe) - 1 ? length : (int)sizeof(probe) - 1;
    memcpy(probe, name, (size_t)n);
    probe[n] = '\0';
    if (owl_registry_find(probe)       != NULL) return true;
    if (owl_registry_const_find(probe) != NULL) return true;
    if (owl_registry_type_find(probe)  != NULL) return true;
    if (is_known_user_type(name, length)) return true;
    {
        char wbuf[128];
        int wn = length < (int)sizeof(wbuf) - 1 ? length : (int)sizeof(wbuf) - 1;
        memcpy(wbuf, name, (size_t)wn);
        wbuf[wn] = '\0';
        if (compiler_prescan_widget_find(wbuf) != NULL) return true;
    }
    {
        char canonBuf[256];
        int canonLen = scanner_canonicalize_identifier(name, length,
                                                       canonBuf, sizeof(canonBuf));
        ObjString* canonKey = obj_copy_string(canonBuf, canonLen);
        Value dummy;
        if (table_get(&vm.globals_canon_idx, canonKey, &dummy)) return true;
    }
    return false;
}

/* Detection compile-time du format court OWL "<digits><unite>" pour duree.
 * Unites : ms, cs, s, mn (insensible casse). Espaces ws toleres en tete/queue
 * et entre digits/unite. Symetrique de owl_duree_parse_short_form (stdlib_date.c).
 * Retourne true si la chaine matche un short form syntaxiquement plausible.
 * Le runtime fera le parsing reel — ici on detecte seulement pour decider si
 * on doit appliquer le check format canon strict. */
static bool duree_string_looks_like_short_form(const char* s, int len) {
    int i = 0;
    while (i < len && (s[i] == ' ' || s[i] == '\t')) i++;
    int ndig = 0;
    while (i < len && s[i] >= '0' && s[i] <= '9') { i++; ndig++; }
    if (ndig == 0) return false;
    while (i < len && (s[i] == ' ' || s[i] == '\t')) i++;
    /* Au moins une lettre d'unite doit suivre. */
    if (i >= len) return false;
    char c0 = s[i] | 0x20;  /* ascii-tolower */
    if (c0 != 'm' && c0 != 'c' && c0 != 's') return false;
    return true;
}

/* Rejette compile-time le cast `entier = <DateHeure>` (statique).
 * Le RHS n'est pas encore consomme : on peek parser.current via save/restore
 * du scanner. On ne couvre que le cas "identifiant simple isole" (variable
 * typee DateHeure, sans `.VersEpoch()`, `+`, etc. apres) — sinon on
 * rejetterait a tort `ep est un entier = dh.VersEpoch()` qui est justement
 * la conversion explicite suggeree. Les cas dynamiques (expression composee
 * qui renvoie DateHeure) tombent sur fn_entier_coerce case IS_DATETIME
 * runtime (ErreurDetectee). Cf. . */
static void check_datetime_to_int_static(int lhsDeclaredType) {
    if (lhsDeclaredType != TOKEN_ENTIER) return;
    if (parser.current.type != TOKEN_IDENTIFIER) return;
    int rhsType = resolve_var_declared_type(parser.current.start,
                                            parser.current.length);
    if (rhsType != TOKEN_DATEHEURE) return;
    /* Peek le token apres l'identifiant : on ne rejette que si l'identifiant
     * est utilise nu (suivi d'un terminator). Save/restore du scanner. */
    Scanner ss = parser.scanner;
    Token cur = parser.current;
    Token prev = parser.previous;
    bool nl = crossedNewline;
    Token rhsTok = parser.current;
    advance_token();
    bool isIsolated = check(TOKEN_EOF) || check(TOKEN_RIGHT_PAREN) ||
                      check(TOKEN_COMMA) || check(TOKEN_SEMICOLON) ||
                      check(TOKEN_NEWLINE) || crossedNewline;
    parser.scanner = ss; parser.current = cur;
    parser.previous = prev; crossedNewline = nl;
    if (isIsolated) {
        owl_emit_error_at(&rhsTok, E_SEM_DATEHEURE_TO_INT_NO_CANON, NULL);
    }
}

/*  — un TokenType de declaration designe-t-il un scalaire (par
 * opposition a un tableau / type compose) ? Sert au rejet de la coercion
 * structurelle tableau <-> scalaire. */
static bool token_type_is_scalar_declared(int t) {
    switch (t) {
        case TOKEN_ENTIER: case TOKEN_REEL: case TOKEN_CHAINE:
        case TOKEN_BOOLEEN: case TOKEN_MONETAIRE: case TOKEN_NUMERIQUE:
        case TOKEN_DATE: case TOKEN_HEURE: case TOKEN_DATEHEURE:
        case TOKEN_DUREE: case TOKEN_BUFFER:
            return true;
        default:
            return false;
    }
}

/* Peek : l'identifiant courant (parser.current) est-il utilise NU, c.-a-d.
 * suivi d'un terminator (pas `[` indexation, `.` methode, `(` appel, `+`
 * concat...) ? Save/restore du scanner. Calque de check_datetime_to_int_static. */
static bool current_identifier_is_isolated(void) {
    Scanner ss = parser.scanner;
    Token cur = parser.current;
    Token prev = parser.previous;
    bool nl = crossedNewline;
    advance_token();
    bool isolated = check(TOKEN_EOF) || check(TOKEN_RIGHT_PAREN) ||
                    check(TOKEN_COMMA) || check(TOKEN_SEMICOLON) ||
                    check(TOKEN_NEWLINE) || crossedNewline;
    parser.scanner = ss; parser.current = cur;
    parser.previous = prev; crossedNewline = nl;
    return isolated;
}

/* Peek : parser.current (identifiant) est-il immediatement suivi d'un '(' —
 * c.-a-d. tete d'un appel de fonction/procedure ? Save/restore du scanner.
 * Distingue `f(...)` d'un identifiant nu / d'un acces `.membre`. */
static bool current_identifier_is_call(void) {
    Scanner ss = parser.scanner;
    Token cur = parser.current;
    Token prev = parser.previous;
    bool nl = crossedNewline;
    advance_token();
    bool isCall = check(TOKEN_LEFT_PAREN);
    parser.scanner = ss; parser.current = cur;
    parser.previous = prev; crossedNewline = nl;
    return isCall;
}

/*  — le type de retour d'un appel (chaine tel que stockee dans le
 * registre : "chaîne", "entier", "réel"...) est-il un scalaire ? Compare en
 * forme ASCII strippee (le registre stocke la forme canon accentuee). Un
 * suffixe '?' (nullable) ne change pas la scalarite. "tableau", "tout", un
 * type composite, ou une chaine vide -> non scalaire (pas de rejet). */
static bool return_type_string_is_scalar(const char* rt) {
    if (rt == NULL || rt[0] == '\0') return false;
    char ascii[32];
    int n = scanner_strip_accents(rt, (int)strlen(rt), ascii, sizeof(ascii));
    if (n <= 0 || n >= (int)sizeof(ascii)) return false;
    ascii[n] = '\0';
    if (ascii[n - 1] == '?') ascii[n - 1] = '\0';
    return strcasecmp(ascii, "chaine") == 0 || strcasecmp(ascii, "entier") == 0 ||
           strcasecmp(ascii, "reel") == 0 || strcasecmp(ascii, "booleen") == 0 ||
           strcasecmp(ascii, "monetaire") == 0 || strcasecmp(ascii, "numerique") == 0 ||
           strcasecmp(ascii, "date") == 0 || strcasecmp(ascii, "heure") == 0 ||
           strcasecmp(ascii, "dateheure") == 0 || strcasecmp(ascii, "duree") == 0 ||
           strcasecmp(ascii, "buffer") == 0;
}

/*  — toutes les formes (signatures) d'une native renvoient-elles un
 * scalaire ? Conservateur : si au moins une forme renvoie autre chose (tableau,
 * composite, void), on n'affirme pas la scalarite (evite un faux rejet quand
 * l'overload appele n'est pas resoluble compile-time). */
static bool native_all_signatures_return_scalar(const OwlNativeDef* def) {
    if (def == NULL || def->signatures == NULL) return false;
    const OwlSignature* s = def->signatures;
    if (s->returnType == NULL) return false;
    for (; s->returnType != NULL; s++) {
        if (!return_type_string_is_scalar(s->returnType)) return false;
    }
    return true;
}

/*  — Rejet compile-time de la coercion structurelle tableau <-> scalaire.
 * La frontiere tableau/scalaire est un mismatch toujours invalide (contrairement
 * aux coercions valeur-dependantes scalaire<->scalaire qui restent legitimes :
 * chaine<->entier<->reel<->booleen<->date...).
 *
 * Deux directions, RHS pas encore consomme (on inspecte parser.current) :
 *   - LHS tableau, RHS scalaire (litteral chaine/nombre/booleen en tete — couvre
 *     aussi `"a" + "b"`, `42 + i` — ou identifiant nu statiquement scalaire)
 *     -> E_SEM_ARRAY_FROM_SCALAR.
 *   - LHS scalaire, RHS tableau (litteral `[...]` en tete, ou identifiant nu
 *     statiquement tableau) -> E_SEM_SCALAR_FROM_ARRAY.
 *
 * On distingue litteral tableau (`[` en tete) de l'indexation (`tab[1]` : tete =
 * identifiant suivi de `[`, non isole). Cas appel : `tableau de chaine =
 * fListeFichier(...)` — le retour scalaire (chaine RC-separee) est rejete
 * compile-time via le type de retour du registre (plus de smart-split
 * implicite). Le cas `tableau <- chaine multi-lignes` est deja gere en amont
 * (E_SYNTAX_TABLEAU_INIT_MULTILIGNE) -> pas de doublon ici. */
static void check_array_scalar_mismatch_static(int lhsDeclaredType) {
    bool lhsIsArray  = (lhsDeclaredType == TOKEN_TABLEAU);
    bool lhsIsScalar = token_type_is_scalar_declared(lhsDeclaredType);
    if (!lhsIsArray && !lhsIsScalar) return;

    if (lhsIsArray) {
        /* Litteral scalaire en tete de RHS. */
        if (check(TOKEN_STRING) || check(TOKEN_INTEGER) || check(TOKEN_REAL) ||
            check(TOKEN_VRAI) || check(TOKEN_FAUX)) {
            owl_emit_error_at(&parser.current, E_SEM_ARRAY_FROM_SCALAR, NULL);
            return;
        }
        /* Identifiant nu statiquement scalaire. */
        if (check(TOKEN_IDENTIFIER)) {
            int rhsType = resolve_var_declared_type(parser.current.start,
                                                    parser.current.length);
            if (token_type_is_scalar_declared(rhsType) &&
                current_identifier_is_isolated()) {
                owl_emit_error_at(&parser.current, E_SEM_ARRAY_FROM_SCALAR, NULL);
                return;
            }
            /* Appel de native dont toutes les formes renvoient un scalaire
             * (ex. fListeFichier -> chaine RC-separee). Ancien terrain du
             * smart-dispatch, desormais un mismatch de type. */
            if (current_identifier_is_call() &&
                parser.current.length > 0 && parser.current.length < 128) {
                char fnName[128];
                memcpy(fnName, parser.current.start, (size_t)parser.current.length);
                fnName[parser.current.length] = '\0';
                const OwlNativeDef* def = owl_registry_find(fnName);
                if (native_all_signatures_return_scalar(def)) {
                    owl_emit_error_at(&parser.current, E_SEM_ARRAY_FROM_SCALAR, NULL);
                }
            }
        }
        return;
    }

    /* LHS scalaire <- tableau. Litteral tableau : RHS commence par `[`. */
    if (check(TOKEN_LEFT_BRACKET)) {
        owl_emit_error_at(&parser.current, E_SEM_SCALAR_FROM_ARRAY, NULL);
        return;
    }
    /* Identifiant nu statiquement tableau. */
    if (check(TOKEN_IDENTIFIER)) {
        int rhsType = resolve_var_declared_type(parser.current.start,
                                                parser.current.length);
        if (rhsType == TOKEN_TABLEAU && current_identifier_is_isolated()) {
            owl_emit_error_at(&parser.current, E_SEM_SCALAR_FROM_ARRAY, NULL);
        }
    }
}

/*  — un structTypeName designe-t-il chaineMultilingue ? Coercions
 * chaine <-> chaineMultilingue preservees ( §4), donc exemptees du
 * typage strict objet. */
static bool struct_name_is_multilingue(const char* n) {
    if (n == NULL || n[0] == '\0') return false;
    return strcmp(n, "cha\xc3\xae" "neMultilingue") == 0 ||
           strcasecmp(n, "chaineMultilingue") == 0;
}

/*  — nom convivial du litteral scalaire courant (parser.current)
 * pour les messages d'erreur ("un entier", "une chaine"...). */
static const char* current_scalar_literal_name_fr(void) {
    if (check(TOKEN_INTEGER)) return "un entier";
    if (check(TOKEN_REAL))    return "un r\xc3\xa9" "el";
    if (check(TOKEN_STRING))  return "une cha\xc3\xae" "ne";
    if (check(TOKEN_VRAI) || check(TOKEN_FAUX)) return "un bool\xc3\xa9" "en";
    return "un scalaire";
}

/*  — Rejet compile-time de l'affectation d'une valeur incompatible a
 * une variable typee objet/struct. Politique (extension d') :
 *   - identite stricte + heritage : un sous-type reste assignable a un
 *     super-type (walk g_class_super), pas l'inverse ni entre types objet
 *     sans lien commun.
 *   - un scalaire n'est jamais une instance compatible d'un type objet.
 *
 * RHS pas encore consomme (on inspecte parser.current, save/restore via les
 * helpers current_identifier_is_*). lhsStructName : nom canon null-termine du
 * type declare du LHS (httpRequête, cVoiture, Cadre...).
 *
 * Exemptions (pas de check) :
 *   - chaineMultilingue : coercions chaine <-> chaineMultilingue.
 *   - types a coerce scalaire enregistre (Couleur, Icone, UUID... via
 *     owl_has_instance_coerce) : acceptent legitimement un scalaire nomme.
 *   - enums (integer-backed) : `e est un MonEnum = 3` reste valide. */
static void check_object_struct_mismatch_static(const char* lhsStructName) {
    if (lhsStructName == NULL || lhsStructName[0] == '\0') return;
    if (struct_name_is_multilingue(lhsStructName)) return;
    /* Types a coerce scalaire enregistre (Couleur, Icone, UUID, Image...).
     * La registration se fait sous la forme ASCII ("Icone"), le type declare
     * peut etre accentue ("Icône") -> sonde les deux formes. */
    if (owl_has_instance_coerce(lhsStructName)) return;
    {
        char ascii[128];
        int an = scanner_strip_accents(lhsStructName, (int)strlen(lhsStructName),
                                       ascii, (int)sizeof(ascii));
        if (an > 0 && an < (int)sizeof(ascii)) {
            ascii[an] = '\0';
            if (owl_has_instance_coerce(ascii)) return;
        }
    }
    if (owl_registry_enum_find(lhsStructName) != NULL) return;
    /* Ne verifier QUE les types objet/struct/classe CONNUS : un identifiant de
     * type inexistant (`n est un byte = 5`) est deja rejete par la validation
     * des pending-type-refs ("Type inconnu"). Interfaces exclues (heritage non
     * resoluble via g_class_super seul -> risque de faux positif). */
    {
        bool known = (owl_registry_type_find(lhsStructName) != NULL);
        if (!known) {
            int uidx = user_type_index(lhsStructName, (int)strlen(lhsStructName));
            if (uidx >= 0) {
                int k = knownUserTypes[uidx].kind;
                known = (k == OWL_USER_TYPE_STRUCTURE || k == OWL_USER_TYPE_CLASSE);
            }
        }
        if (!known) return;
    }

    /* Litteral scalaire en tete de RHS : jamais une instance d'objet. */
    if (check(TOKEN_INTEGER) || check(TOKEN_REAL) || check(TOKEN_STRING) ||
        check(TOKEN_VRAI) || check(TOKEN_FAUX)) {
        owl_emit_error_at(&parser.current, E_SEM_OBJECT_ASSIGN_FROM_SCALAR,
                          "got", current_scalar_literal_name_fr(),
                          "expected", lhsStructName,
                          NULL);
        return;
    }

    /* Identifiant nu statiquement typé objet/struct : incompatible si son type
     * n'est ni le type du LHS ni un de ses descendants. */
    if (check(TOKEN_IDENTIFIER)) {
        const char* rhsStruct = resolve_var_struct_type(parser.current.start,
                                                         parser.current.length);
        if (rhsStruct == NULL || rhsStruct[0] == '\0') return;
        if (struct_name_is_multilingue(rhsStruct)) return;
        if (!current_identifier_is_isolated()) return;
        /* Sous-type -> super-type autorise : rhs doit etre le LHS ou en deriver. */
        if (class_is_same_or_derived(rhsStruct, (int)strlen(rhsStruct),
                                     lhsStructName, (int)strlen(lhsStructName))) {
            return;
        }
        owl_emit_error_at(&parser.current, E_SEM_OBJECT_ASSIGN_TYPE_MISMATCH,
                          "got", rhsStruct,
                          "expected", lhsStructName,
                          NULL);
    }
}

/* Valide un litteral chaine pour init/reassign `dur est une duree = "..."`.
 * Tolere le format court OWL ("200ms", "1s", "5mn") qui est valide au runtime.
 * Rejette compile-time uniquement les chaines qui ne sont ni short form ni
 * canon Q5-bis "[+/-]<J>HHMMSSCC".
 *
 * Single-parser invariant : passe par owl_parse_duration_multi
 * (meme parser que la coerce runtime). Pas de duplication d'heuristique.
 *
 * tok pointe sur le TOKEN_STRING (incluant les guillemets). */
static void check_duree_string_literal(const Token* tok) {
    if (tok == NULL || tok->length < 2) return;
    /* Skip les guillemets : contenu = tok->start[1..tok->length-2]. */
    const char* s = tok->start + 1;
    int len = tok->length - 2;
    /* Si la chaine ressemble a un short form OWL ("200ms" / "1s" / "5mn" /
     * "10cs"), on ne fait PAS de check compile-time canon — le runtime parse
     * cette forme via owl_duree_parse_short_form. */
    if (duree_string_looks_like_short_form(s, len)) return;
    /* Sinon : passe par le dispatcher canon Q5-bis. Distingue FORMAT vs
     * BOUNDS via outErr. Bornes hors-plage (HH=24, MM=60, SS=60) emettent
     * BAD_COUNT pour l'instant (reserve evolution code dedie BOUNDS). */
    int64_t ms = 0;
    int perr = 0;
    if (owl_parse_duration_multi(s, len, &ms, &perr)) return;
    if (perr == OWL_DATE_PARSE_ERR_BOUNDS) {
        /* Reutilise BAD_COUNT pour bornes — message reste parlant
         * (le user voit "format invalide" mais avec un compte attendu). */
        owl_emit_error_at(tok, E_SEM_DUREE_LITERAL_FORMAT_BAD_COUNT,
                          "got", "bornes hors-plage", NULL);
        return;
    }
    /* FORMAT : signe manquant, non-digit, ou longueur invalide. */
    int i = 0;
    if (len > 0 && (s[0] == '+' || s[0] == '-')) i = 1;
    int ndig = 0;
    bool only_digits = true;
    for (; i < len; i++) {
        if (s[i] >= '0' && s[i] <= '9') ndig++;
        else { only_digits = false; break; }
    }
    if (!only_digits) {
        owl_emit_error_at(tok, E_SEM_DUREE_LITERAL_FORMAT_NON_DIGITS, NULL);
        return;
    }
    char gotBuf[16];
    snprintf(gotBuf, sizeof(gotBuf), "%d", ndig);
    owl_emit_error_at(tok, E_SEM_DUREE_LITERAL_FORMAT_BAD_COUNT,
                      "got", gotBuf, NULL);
}

/*  /  lot 1 — Valide un litteral chaine pour init/reassign
 * `var est une <date|heure|dateheure> = "..."`. Single-parser invariant :
 * passe par les parsers BOUNDS-aware de stdlib_date_parsers.h (memes que
 * les coerce runtime).
 *
 *  lot 1 — distinction FORMAT vs BOUNDS via outErr du dispatcher :
 *   - format invalide => E_SEM_<T>_LITERAL_FORMAT
 *   - bornes hors-plage => E_SEM_<T>_LITERAL_BOUNDS
 * Permet aux fixtures compile-error de cibler "format invalide" /
 * "mois invalide" / "heure invalide" sans ambiguite (oracle stable).
 *
 * Pas de check si la chaine est l'operande d'une expression
 * (`"..." + "..."`, etc.) — verifie par le caller via peek-and-restore
 * du scanner. Couvre uniquement le litteral isole.
 *
 * declaredType : TOKEN_DATE / TOKEN_HEURE / TOKEN_DATEHEURE. */
static void check_temporal_string_literal(const Token* tok, int declaredType) {
    if (tok == NULL || tok->length < 2) return;
    const char* s = tok->start + 1;
    int len = tok->length - 2;
    if (declaredType == TOKEN_DATE) {
        /*  Q5 — dispatcher multi-format avec distinction FORMAT/BOUNDS. */
        int y, m, d, perr = 0;
        if (!owl_parse_date_multi(s, len, &y, &m, &d, &perr)) {
            if (perr == OWL_DATE_PARSE_ERR_BOUNDS) {
                owl_emit_error_at(tok, E_SEM_DATE_LITERAL_BOUNDS, NULL);
            } else {
                owl_emit_error_at(tok, E_SEM_DATE_LITERAL_FORMAT, NULL);
            }
        }
    } else if (declaredType == TOKEN_HEURE) {
        int h, m, sec, cs, perr = 0;
        if (!owl_parse_time_string_cs_ex(s, len, &h, &m, &sec, &cs, &perr)) {
            if (perr == OWL_DATE_PARSE_ERR_BOUNDS) {
                owl_emit_error_at(tok, E_SEM_HEURE_LITERAL_BOUNDS, NULL);
            } else {
                owl_emit_error_at(tok, E_SEM_HEURE_LITERAL_FORMAT, NULL);
            }
        }
    } else if (declaredType == TOKEN_DATEHEURE) {
        /* La coerce runtime accepte ISO (16/19) OU le format compact
         * AAAAMMJJ[HHMM[SS[CC|FFF]]] (8/12/14/16/17 — date seule
         * length 8 acceptee, heure par defaut 00:00:00). On reflete
         * EXACTEMENT ce dispatch ici (single-parser strict).
         *
         * Note : len 10 (date seule ISO) reste rejete car la coerce
         * runtime route via parse_dateheure_iso qui exige une partie
         * horaire et len 10 ne matche pas la branche compact 8.
         * cf. test_temporal_parser_parity bloc A 'date seule invalide'. */
        int y, m, d, hh, mm, ss, perr_iso = 0;
        bool iso_ok = owl_parse_dateheure_iso_ex(s, len, &y, &m, &d, &hh, &mm, &ss, &perr_iso);
        bool compact_format_ok = false;
        bool compact_bounds_ok = false;
        /* Branche compact : date 8 chars + heure optionnelle. */
        if (!iso_ok && len >= 8) {
            int dy, dm, dd, derr = 0;
            if (owl_parse_date_multi(s, 8, &dy, &dm, &dd, &derr) ||
                derr == OWL_DATE_PARSE_ERR_BOUNDS) {
                /* Verifions le reste : digits HHmm[SS[CC|FFF]]. */
                bool dig_ok = true;
                if (len == 8) {
                    /* Date seule -> heure par defaut. */
                } else if (len == 12 || len == 14) {
                    for (int i = 8; i < len; i++) {
                        if (s[i] < '0' || s[i] > '9') { dig_ok = false; break; }
                    }
                } else if (len == 16) {
                    for (int i = 8; i < 16; i++) {
                        if (s[i] < '0' || s[i] > '9') { dig_ok = false; break; }
                    }
                } else if (len >= 17) {
                    for (int i = 8; i < 17; i++) {
                        if (s[i] < '0' || s[i] > '9') { dig_ok = false; break; }
                    }
                } else {
                    /* len 9/10/11/13/15 : pas un format compact valide. */
                    dig_ok = false;
                }
                if (dig_ok) {
                    compact_format_ok = true;
                    hh = mm = ss = 0;
                    if (len >= 12) {
                        hh = (s[8]-'0')*10 + (s[9]-'0');
                        mm = (s[10]-'0')*10 + (s[11]-'0');
                    }
                    if (len >= 14) ss = (s[12]-'0')*10 + (s[13]-'0');
                    if (derr == OWL_DATE_PARSE_OK &&
                        hh <= 23 && mm <= 59 && ss <= 59) {
                        compact_bounds_ok = true;
                    }
                }
            }
        }
        if (iso_ok) {
            /* OK. */
        } else if (compact_bounds_ok) {
            /* OK via branche compact. */
        } else if (compact_format_ok) {
            /* Format compact reconnu mais bornes hors-plage. */
            owl_emit_error_at(tok, E_SEM_DATEHEURE_LITERAL_BOUNDS, NULL);
        } else if (perr_iso == OWL_DATE_PARSE_ERR_BOUNDS) {
            /* Format ISO reconnu mais bornes hors-plage (mois>12, etc.).
             * Prioritaire sur compact_format echoue (compact pas applicable
             * a "AAAA-MM-JJ..." vu les separateurs). */
            owl_emit_error_at(tok, E_SEM_DATEHEURE_LITERAL_BOUNDS, NULL);
        } else {
            /* Aucun format ne matche. */
            owl_emit_error_at(tok, E_SEM_DATEHEURE_LITERAL_FORMAT, NULL);
        }
    }
}

/*  — Helpers icone non-coloriable.
 *
 * `icone_peek_literal_at_current` examine si la sequence parser COURANTE
 * commence par `icones . IDENT` SUIVI d'un terminator (newline / EOF / `,`
 * / `;` / `)` ). Le scanner est restaure dans tous les cas (peek pur, ne
 * consomme rien). Retourne l'entry catalogue (NULL si miss / pas le pattern).
 *
 * On exige le terminator pour eviter de tagger `icones.X.Champ` ou
 * `icones.X + autre_chose` — seul `icones.X` isole compte comme literal
 * pur trackable. */
static const OwlIconCatalogEntry* icone_peek_literal_at_current(void) {
    /* Token courant doit etre `icones` (case-insensible). */
    if (!check(TOKEN_IDENTIFIER)) return NULL;
    if (parser.current.length != 6) return NULL;
    if (strncasecmp(parser.current.start, "icones", 6) != 0) return NULL;

    /* Save complet pour restaurer apres peek. */
    Scanner ss = parser.scanner;
    Token cur = parser.current;
    Token prev = parser.previous;
    bool nl = crossedNewline;

    const OwlIconCatalogEntry* result = NULL;

    advance_token(); /* consume `icones` */
    if (!check(TOKEN_DOT)) goto restore;
    advance_token(); /* consume `.` */
    if (!check(TOKEN_IDENTIFIER)) goto restore;

    Token idTok = parser.current;
    advance_token(); /* consume `IDENT` */

    /* Verifier que la suite est un terminator (literal pur isole). */
    bool isIsolated = check(TOKEN_EOF) || check(TOKEN_RIGHT_PAREN) ||
                      check(TOKEN_COMMA) || check(TOKEN_SEMICOLON) ||
                      check(TOKEN_NEWLINE) || crossedNewline;
    if (!isIsolated) goto restore;

    /* Lookup catalogue (case+accent insensible deja gere par
     * owl_icones_catalog_find via icones_normalize_name : strip accents,
     * lower, `_` -> `-`). */
    char nameBuf[128];
    int n = idTok.length < (int)sizeof(nameBuf) - 1
            ? idTok.length : (int)sizeof(nameBuf) - 1;
    memcpy(nameBuf, idTok.start, (size_t)n);
    nameBuf[n] = '\0';
    result = owl_icones_catalog_find(nameBuf);

restore:
    parser.scanner = ss;
    parser.current = cur;
    parser.previous = prev;
    crossedNewline = nl;
    return result;
}

/*  — Emit le warning W_SEM_ICONE_NOT_COLORABLE si l'entry catalogue
 * est marquee non-coloriable. NULL entry ou coloriable -> noop.
 * Le warning est ancre sur `couleurTok` (token `Couleur` de l'assign). */
static void icone_emit_not_colorable_warning_if(
        const OwlIconCatalogEntry* entry, const Token* couleurTok) {
    if (entry == NULL || entry->couleur_modifiable) return;
    if (couleurTok == NULL) return;
    /* `set` resolu via OWL_ICONS_SET_NAMES[entry->set_id]. La table est
     * terminee NULL ; set_id valide par construction (catalog gen). */
    const char* setName = OWL_ICONS_SET_NAMES[entry->set_id];
    if (setName == NULL) setName = "?";
    owl_emit_warning_at(couleurTok, W_SEM_ICONE_NOT_COLORABLE,
                        "set", setName,
                        "nom", entry->name,
                        NULL);
}

/*  — une colonne de Table est un receveur de mise en forme
 * pour `..Couleur` / `..CouleurFond`, adressable par la forme NUE `COL_X..prop`.
 * Le nom nu inconnu par ailleurs, suivi d'un operateur d'acces, est resolu au
 * COMPILE-TIME par desucrage vers `TABLE_X.COL_X` (le proxy-colonne de 
 * existe deja) — SANS jamais poser COL_X dans vm.globals (interdit /
 * ). La resolution runtime passe donc par la Table via l'instance de
 * fenetre montee.
 *
 * Retourne true si l'intercept a traite le nom (bytecode desucre emis, ou
 * erreur emise) : l'appelant sort alors immediatement.
 *
 * Contrat de l'arbre de decision :
 *   - 0 Table proprietaire  -> false (le nom retombe sur « variable inconnue »).
 *   - >=2 Tables            -> E_SEM_TABLE_COLUMN_BARE_AMBIGUOUS (homonymie).
 *   - exactement 1 Table    -> valider la propriete affectee :
 *       * prop receveur declaree (OWL_COLUMN_RECEIVER_PROPS, FR/EN, casse+
 *         accent-insensible : Couleur/CouleurFond/MasqueSaisie...) -> desucrer.
 *       * autre prop -> E_SEM_TABLE_COLUMN_PROP_NOT_WRITABLE (pas de retour au
 *         no-op silencieux que ce chantier ferme). */
static bool try_intercept_bare_table_column(Token name) {
    /* Un receveur colonne se lit `COL_X..prop`. On ne s'arme que sur un
     * operateur d'acces suivant ; `COL_X` seul reste « variable inconnue ». */
    if (!check(TOKEN_DOUBLE_DOT) && !check(TOKEN_DOT)) return false;
    if (name.length <= 0 || name.length >= 64) return false;

    char colBuf[64];
    memcpy(colBuf, name.start, (size_t)name.length);
    colBuf[name.length] = '\0';

    static char s_bareColTable[64];
    char tablesList[512];
    int nTables = prescan_tables_declaring_column(colBuf,
                                                  s_bareColTable, sizeof(s_bareColTable),
                                                  tablesList, sizeof(tablesList));
    if (nTables == 0) return false;   /* pas une colonne connue -> inchange */

    if (nTables >= 2) {
        owl_emit_error_at(&name, E_SEM_TABLE_COLUMN_BARE_AMBIGUOUS,
                          "nom", colBuf,
                          "tables", tablesList,
                          NULL);
        return true;
    }

    /* Exactement 1 Table proprietaire. Peek la propriete affectee : le scanner
     * du parser est positionne juste apres parser.current (= l'operateur `..`/
     * `.`), donc un scan sur une copie rend le token de propriete sans avancer
     * le parser reel. */
    Scanner peek = parser.scanner;
    Token propTok = scanner_scan_token(&peek);
    char propRaw[64];
    int prl = propTok.length > 0 && propTok.length < 64 ? propTok.length : 0;
    memcpy(propRaw, propTok.start, (size_t)prl);
    propRaw[prl] = '\0';

    char propProbe[64];
    int pp = scanner_strip_accents(propRaw, prl, propProbe, sizeof(propProbe));
    propProbe[pp] = '\0';

    /*  — receveur data-driven (cf. OWL_COLUMN_RECEIVER_PROPS) : les props
     * sans chemin d'application Qt restent refusees (no-op silencieux evite). */
    if (!column_receiver_prop_is_writable(propProbe)) {
        owl_emit_error_at(&name, E_SEM_TABLE_COLUMN_PROP_NOT_WRITABLE,
                          "prop", propRaw,
                          "nom", colBuf,
                          "table", s_bareColTable,
                          NULL);
        return true;
    }

    /* Desucrage `COL_X..prop` -> `TABLE_X.COL_X..prop`. On emet le meme bytecode
     * de base que la forme colonne-first : OP_GET_GLOBAL <Table> (proxy widget
     * pose sous le nom de declaration) puis OP_STRUCT_GET <COL_X> (proxy-colonne
     * ). La suite `..prop = ...` est ensuite conduite par dot() via la
     * boucle Pratt, exactement comme `TABLE_X.COL_X..prop`. */
    Token tblTok;
    tblTok.start  = s_bareColTable;
    tblTok.length = (int)strlen(s_bareColTable);
    tblTok.line   = name.line;
    tblTok.column = name.column;
    emit_const_op(OP_GET_GLOBAL, identifier_constant(&tblTok));
    emit_const_op(OP_STRUCT_GET, identifier_constant(&name));

    /* Etat de chaine identique a celui laisse par `TABLE_X.COL_X` : le receveur
     * du prochain `..` est la Table (g_last_var_token), et le field precedent
     * est la colonne (g_last_field_name != vide) — ce dernier neutralise la
     * validation prop-widget de dot() (gardee sur prev_field_name_len == 0),
     * comme pour la forme colonne-first. */
    g_last_var_token = tblTok;
    {
        int n = name.length < 63 ? name.length : 63;
        memcpy(g_last_field_name, colBuf, (size_t)n);
        g_last_field_name[n] = '\0';
        g_last_field_name_len = n;
    }
    g_chain_broken = false;
    g_last_field_type[0] = '\0';
    g_last_field_type_len = 0;
    g_last_dynamic_receiver = DYN_RECV_NONE;
    return true;
}

static void named_variable(Token name, bool canAssign) {
    g_last_var_token = name;
    table_cell_chain_reset();   /*  : nouvelle chaine */
    ui_option_chain_reset();    /*  : idem pour l'option indexee */
    zr_cell_chain_reset();      /*  : idem pour la ligne de ZoneRépétée */
    /* New chain: reset field-name tracker (bug #6) + type tracker (chain
     * propagation strict dot). Sinon le type du dernier field d'un chain
     * precedent (ex. type "entier" apres `..Couleur = 0`) fuit sur le
     * nouveau chain et casse la resolution du recvType. */
    g_last_field_name[0] = '\0';
    g_last_field_name_len = 0;
    g_last_field_type[0] = '\0';
    g_last_field_type_len = 0;
    g_chain_broken = false;
    /*  — un nom nu ouvre une chaine a recepteur STATIQUE : neutralise
     * un eventuel recepteur dynamique arme par une expression precedente. */
    g_last_dynamic_receiver = DYN_RECV_NONE;
    /* Compile-time intercepts that need the raw name before resolving. */
    if (try_intercept_type_est_nullable(name)) return;
    if (try_intercept_execute(name)) return;
    if (try_intercept_proc_hook_assign(name, canAssign)) return;
    /*  — MonChamp/MaFenêtre (et alias EN MyControl/MyWindow) ne
     * transitent plus par named_variable : ce sont des mots-cles scanner
     * (TOKEN_MONCHAMP/TOKEN_MAFENETRE) resolus dynamiquement au runtime par
     * les opcodes OP_MONCHAMP/OP_MAFENETRE (parselets dedies, cf.
     * monchamp_self/mafenetre_self). L'ancien mecanisme d'alias statique
     * (substitution compile-time par le nom du champ/fenetre) est supprime —
     * il ne fonctionnait que dans un bloc Champ/Fenetre litteral et cassait
     * en procedure agnostique / casse alternative. */

    uint8_t getOp, setOp;
    int arg = resolve_local(current, &name);

    /*  lot 1b — isolation scope champ : si on est dans un body de
     * champ (top-level OU event/proc) et que le nom n'est pas un local,
     * tenter d'abord la variable prefixee `<ctrl>__<var>` declaree dans CE
     * champ. Si elle existe comme globale connue -> resoudre vers la forme
     * prefixee. Sinon on retombe sur le nom nu (variable FENETRE, globale de
     * script…). C'est ce qui rend les variables fenetre toujours visibles
     * depuis les champs tout en isolant les variables propres au champ.
     * Place AVANT dsl_aliases_lookup : une variable de champ shadow un alias
     * de proc homonyme — cas marginal, mais l'ordre est deterministe. */
    const char* preResolveName = name.start;  /*  — cf. collection */
    static char fieldResolveBuf[256];
    if (arg == -1 && g_current_control_decl != NULL) {
        int pn = control_var_prefix(name.start, name.length,
                                    fieldResolveBuf, sizeof(fieldResolveBuf));
        if (pn > 0 && is_known_global_name(fieldResolveBuf, pn)) {
            name.start  = fieldResolveBuf;
            name.length = pn;
        }
    }

    /*  — resolution intra-element des globales scopees a l'element.
     * Dans le body / les events / les PROCEDURE d'une Fenetre/Etat, un nom nu
     * qui matche une globale top-level de l'element courant est reecrit vers
     * sa forme mangled `<ELEM>$<var>` (la forme reellement definie au runtime,
     * cf var_declaration_after_est). Place APRES la resolution control-var
     * (plus specifique) : une variable de controle masque une globale element
     * homonyme. Point UNIQUE de reecriture lecture/ecriture intra-element. */
    static char elementResolveBuf[256];
    if (arg == -1 && g_current_element_name[0] != '\0'
        && element_globals_has(g_current_element_name,
                               (int)strlen(g_current_element_name),
                               name.start, name.length)) {
        int pn = element_var_prefix(g_current_element_name,
                                    name.start, name.length,
                                    elementResolveBuf, sizeof(elementResolveBuf));
        if (pn > 0) {
            name.start  = elementResolveBuf;
            name.length = pn;
        }
    }

    /*  — resolution NOM NU d'un membre de CollectionDeProcédures
     * EXPOSE. Si le nom n'a ete happe ni par le scope champ ni par le scope
     * element (formes ENCAPSULEES, name.start deja reecrit), et qu'il matche un
     * membre expose, on reecrit vers le slot mangled `COL$membre` (le stockage
     * reel, cf. var_declaration_after_est / funct_declaration). DEUX collections
     * exposant le meme nom nu -> ambigu (remede : qualifier COL.Nom, cf.
     * E_SEM_AMBIGUOUS_SYMBOL). C'est l'INVERSE de l'encapsulation element : ici
     * le nom nu DOIT resoudre. */
    static char collectionResolveBuf[256];
    if (arg == -1 && name.start == preResolveName
        && g_collection_members_count > 0) {
        const char* coll = NULL;
        int collLen = 0;
        int m = collection_member_resolve_bare(name.start, name.length,
                                               &coll, &collLen);
        if (m >= 2) {
            owl_emit_error_at(&parser.previous, E_SEM_AMBIGUOUS_SYMBOL);
            return;
        } else if (m == 1) {
            int pn = collection_var_prefix(coll, name.start, name.length,
                                           collectionResolveBuf,
                                           sizeof(collectionResolveBuf));
            if (pn > 0) {
                name.start  = collectionResolveBuf;
                name.length = pn;
            }
        }
    }

    /*  — nom nu d'un style de bloc theme : refus oriente. Le style est
     * stocke `<prefixe>$<style>` (encapsulation ), le nom nu ne
     * designe donc plus rien. Place AVANT le check d'ambiguite plus bas :
     * deux blocs theme declarant un homonyme ne se disputent aucun nom, et
     * « symbole ambigu » enverrait qualifier ce qui ne se qualifie pas.
     * Une faute, un message : on sort ici, la cascade de la chaine `..` ne
     * s'ouvre pas.
     *
     * Garde name.start == preResolveName : un nom deja reecrit (scope
     * controle / element / collection) a resolu, il n'est pas concerne. Le
     * corps du bloc theme lui-meme (g_in_theme_block) passe par le scope
     * element, jamais par ce refus. */
    if (arg == -1 && !g_in_theme_block && name.start == preResolveName) {
        const char* themeOwner = theme_style_bare_owner(name.start, name.length);
        if (themeOwner != NULL) {
            char* nameZ = theme_style_dup(name.start, name.length);
            owl_emit_error_at(&parser.previous, E_SEM_THEME_STYLE_BARE_ACCESS,
                              "nom", nameZ,
                              "theme", themeOwner,
                              NULL);
            theme_style_free(nameZ);
            return;
        }
    }

    /*  — colonne de Table receveur de mise en forme : la
     * forme nue `COL_X..Couleur` desucre vers `TABLE_X.COL_X`. Place ici, sur le
     * nom NON reecrit (name.start == preResolveName) et INCONNU par ailleurs
     * (pas un local, pas une globale/symbole projet) : une variable homonyme
     * garde la priorite (arbre de decision, cas « deja connu -> inchange »).
     *  : le garde `!bare_column_name_shadowed(...)` est LOAD-BEARING
     * (deja efface une fois par accident, cf. sa def) ; verrou compile-error
     * `table_colonne_receveur_couleur_bare_homonyme`. */
    if (arg == -1 && name.start == preResolveName
        && !bare_column_name_shadowed(name.start, name.length)
        && try_intercept_bare_table_column(name)) {
        return;
    }

    /* Phase 6 : si le nom n'est pas local et matche un alias DSL widget,
     * remplace par le nom qualifie. Ainsi 'Calcule()' dans un body event
     * de BTN_OK compile vers OP_GET_GLOBAL("BTN_OK_Calcule"). */
    if (arg == -1) {
        const char* qualified = dsl_aliases_lookup(name.start, name.length);
        if (qualified) {
            name.start  = qualified;
            name.length = (int)strlen(qualified);
        }
    }

    /* Remember whether the LHS is nullable so we can enforce the
     * "no Null to non-nullable" rule on '= Null' assignments.
     * Also pick up the undetectable flag so reassignments mask the new
     * value (otherwise a `s = "newvalue"` would leak the cleartext). */
    bool lhsNullable = false;
    bool lhsUndetectable = false;
    int lhsDeclaredType = TOKEN_EOF;
    const char* lhsStructTypeName = NULL; /*  lot C : pour detecter chaineMultilingue */
    if (arg != -1) {
        lhsNullable = current->locals[arg].isNullable;
        lhsUndetectable = current->locals[arg].isUndetectable;
        lhsDeclaredType = current->locals[arg].declaredType;
        if (current->locals[arg].structTypeName[0] != '\0') {
            lhsStructTypeName = current->locals[arg].structTypeName;
        }
    } else {
        int gi = typed_globals_find(name.start, name.length);
        if (gi >= 0) {
            lhsNullable     = g_typed_globals[gi].isNullable;
            lhsUndetectable = g_typed_globals[gi].isUndetectable;
            lhsDeclaredType = g_typed_globals[gi].declaredType;
            if (g_typed_globals[gi].structTypeName[0] != '\0') {
                lhsStructTypeName = g_typed_globals[gi].structTypeName;
            }
        }
    }
    /*  lot C : detection chaineMultilingue (canonical accentue
     * "cha\xc3\xae" "neMultilingue" ou ASCII "chaineMultilingue") pour le
     * dispatch d'affectation mutation-en-place ci-dessous. */
    bool lhsIsMultilingue = (lhsStructTypeName != NULL &&
        (strcmp(lhsStructTypeName, "cha\xc3\xae" "neMultilingue") == 0 ||
         strcmp(lhsStructTypeName, "chaineMultilingue") == 0));

    bool isGlobal = (arg == -1);  /* Remember before arg is reassigned */

    /* Mark global as referenced (GET or SET) for unused-variable tracking */
    if (isGlobal) {
        global_track_mark_used(name.start, name.length);
        #ifdef DEBUG_UNUSED_VARS
        fprintf(stderr, "[DEBUG] Marking global '%.*s' as used\n", name.length, name.start);
        #endif
    }

    /*  — appel nu d'une methode soeur (ou heritee). Dans le body
     * d'une methode d'instance (`currentClass != NULL` ET non-GLOBALE), un
     * identifiant nu suivi de `(` qui matche une methode de la classe
     * courante ou d'un de ses ancetres est emis comme `:Ident(args)` :
     * push `this`, OP_INVOKE. Dispatch virtuel preserve cote VM.
     *
     * Priorites respectees :
     *   - local (arg != -1) deja traite ci-dessus, gagne sur tout.
     *   - methode soeur prioritaire sur procedure globale homonyme
     *     (Regle 4 spec : la plus proche gagne). Le warning de shadowing
     *     est emis a la declaration de la methode, pas ici.
     *   - non-call (`Ident` sans `(`) -> fallback global preserve. Un
     *     champ instance `:champ` continue d'utiliser sa syntaxe propre.
     *   - hors body methode (currentClass==NULL) ou methode GLOBALE
     *     (isGlobalMethod==true, pas d'instance courante) -> fallback. */
    if (arg == -1 && currentClass != NULL && !currentClass->isGlobalMethod
        && check(TOKEN_LEFT_PAREN)) {
        bool isMethodSibling = false;
        if (projectSymbols != NULL) {
            isMethodSibling = symtable_has_class_method_inherited(
                projectSymbols,
                currentClass->name.start, currentClass->name.length,
                name.start, name.length);
        }
        if (!isMethodSibling) {
            /* Fallback intra-compile : utile en l'absence de SymbolTable
             * (chemin compile_impl pur). Couvre les methodes deja vues. */
            isMethodSibling = find_declared_method_inherited(
                currentClass->name.start, currentClass->name.length,
                name.start, name.length);
        }
        if (isMethodSibling) {
            ConstIdx methodName = identifier_constant(&name);
            emit_bytes(OP_GET_LOCAL, 0);              /* push this */
            advance_token();                          /* consume '(' */
            uint8_t argCount = argument_list();
            emit_const_op_b(OP_INVOKE, methodName, argCount);
            /* Aligne sur dot_access / this_field : la valeur de retour est de
             * type inconnu, on casse la chaine pour eviter les .Field fautifs. */
            g_chain_broken = true;
            g_last_field_type[0] = '\0';
            g_last_field_type_len = 0;
            g_last_var_token.start = NULL;
            g_last_var_token.length = 0;
            return;
        }
    }

    if (arg != -1) {
        getOp = OP_GET_LOCAL;
        setOp = OP_SET_LOCAL;
    } else {
        /*  : dispatch case-insensible contextuel au call site.
         *
         * Invariant 1 OWL : la résolution doit etre case-insensible. Mais
         * vm.globals est strictement case-sensible (string interning + ptr
         * compare). Quand l'utilisateur tape `httprequête("url")` en
         * minuscules, scanner_strip_accents produit `httprequete` qui ne
         * matche dans vm.globals que le TYPE template (enregistre comme
         * tel par stdlib_builtin_types.c). La NATIVE `HTTPRequête` est
         * sous la clef `HTTPRequete` (canonical accent-strippe), donc
         * inaccessible.
         *
         * Fix : si on est en call site (`(` suit), qu'aucun symbole user
         * connu ne shadow ce nom, et qu'`owl_registry_find` matche une
         * native (lookup case+accent insensible), on substitue le token
         * par le canonical de la native. Le bytecode emis pointe alors
         * sur la clef exacte presente dans vm.globals.
         *
         * Garde-fous :
         *   - arg != -1 deja gere ci-dessus (local prioritaire)
         *   - g_declaredGlobals : proc/global user declare prioritaire
         *   - projectSymbols : proc cross-file prioritaire
         *   - sinon registry native (case-insensible)
         *
         * Symetrique cote annotation type dans var_declaration_after_est. */
        if (check(TOKEN_LEFT_PAREN)) {
            bool userShadowed = false;
            for (int i = decl_globals_bucket_head(name.start, name.length);
                 i != -1 && !userShadowed; i = g_declaredGlobals[i].hashNext) {
                if (decl_globals_match(i, name.start, name.length)) {
                    userShadowed = true;
                }
            }
            if (!userShadowed && projectSymbols != NULL) {
                bool ambiguous = false;
                if (symtable_find(projectSymbols, name.start, name.length,
                                   &ambiguous) != NULL) {
                    userShadowed = true;
                }
            }
            if (!userShadowed) {
                char probe[128];
                int n = name.length < (int)sizeof(probe) - 1
                            ? name.length : (int)sizeof(probe) - 1;
                memcpy(probe, name.start, n);
                probe[n] = '\0';
                const OwlNativeDef* d = owl_registry_find(probe);
                if (d != NULL && d->canonical != NULL) {
                    name.start  = d->canonical;
                    name.length = (int)strlen(d->canonical);
                }
            }
        }
        arg = const_idx_i(identifier_constant(&name));
        /* If the identifier is immediately followed by `(`, it's being used
         * as a function call — emit the CALLEE variant so a missing-global
         * error says "Undefined function/procedure" rather than "variable". */
        getOp = check(TOKEN_LEFT_PAREN) ? OP_GET_GLOBAL_CALLEE : OP_GET_GLOBAL;
        setOp = OP_SET_GLOBAL;

        /* Project mode: PRIVE enforcement + ambiguity check.
         *
         * D'abord chercher dans le fichier courant : un symbole local
         * (meme si declare PRIVÉE) est toujours accessible depuis son
         * propre fichier. Sans ca, symtable_find renverrait le premier
         * match du projet — potentiellement le symbole homonyme PRIVÉE
         * d'un autre fichier — et l'enforcement "from another file"
         * planterait sur l'auto-reference. Bug T5 du QA. */
        if (projectSymbols != NULL) {
            ProjectSymbol* sym = NULL;
            if (currentFileIndex >= 0) {
                sym = symtable_find_in_file(projectSymbols,
                    name.start, name.length, currentFileIndex);
            }
            bool ambiguous = false;
            if (sym == NULL) {
                sym = symtable_find(projectSymbols,
                    name.start, name.length, &ambiguous);
                if (sym != NULL && sym->isPrivate &&
                    sym->fileIndex != currentFileIndex) {
                    owl_emit_error_at(&parser.previous, E_SEM_PRIVATE_SYMBOL_ACCESS);
                    return;
                }
                if (ambiguous) {
                    owl_emit_error_at(&parser.previous, E_SEM_AMBIGUOUS_SYMBOL);
                    return;
                }
            }
        }
    }

    if (canAssign && match_token(TOKEN_EQUAL)) {
        /*  — membre droit absent en fin de ligne : le NEWLINE
         * significatif emis apres `=` a ete skippe par advance_token
         * (crossedNewline). La valeur droite demarrerait sur la ligne suivante.
         * On ancre "Expression attendue" sur le `=` (parser.previous) et on rend
         * la main SANS consommer la ligne suivante (synchronize() la reparse via
         * son newline-stop), plutot que d'aspirer son 1er token comme operande.
         * Les continuations `_` / `...` ne produisent pas de NEWLINE et un
         * litteral `{...}` / `[...]` multi-ligne demarre sur la ligne du `=` :
         * aucun cas legitime ne pose crossedNewline ici. */
        if (crossedNewline) {
            owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR);
            return;
        }
        /* Reject assignment to type names at global scope */
        if (reject_type_assignment(&name, isGlobal)) return;
        /* Reject assignment to constant names declared via CONSTANTE block. */
        if (isGlobal && const_globals_find(name.start, name.length)) {
            char nameZ[128];
            int nz = name.length < (int)sizeof(nameZ) - 1
                     ? name.length : (int)sizeof(nameZ) - 1;
            memcpy(nameZ, name.start, (size_t)nz);
            nameZ[nz] = '\0';
            owl_emit_error_at(&name, E_SEM_REASSIGN_CONSTANTE,
                              "name", nameZ,
                              NULL);
            return;
        }
        /* Reject assignment to predefined read-only global variables
         * (ex. ErreurDétectée, mis à jour automatiquement par le runtime).
         * Divergence assumée vs canon : canon tolère syntaxiquement
         * l'écriture mais l'ignore silencieusement. OWL rejette
         * compile-time pour forcer l'usage de ErreurRAZ() / mécanisme
         * dédié. Cf.  + . */
        if (isGlobal) {
            char nameZ[128];
            int nz = name.length < (int)sizeof(nameZ) - 1
                     ? name.length : (int)sizeof(nameZ) - 1;
            memcpy(nameZ, name.start, (size_t)nz);
            nameZ[nz] = '\0';
            const OwlGlobalVarDef* gvDef = owl_globalvar_catalog_find(nameZ);
            if (gvDef != NULL && gvDef->readOnly) {
                owl_emit_error_at(&name, E_SEM_REASSIGN_READONLY_GLOBAL,
                                  "name", gvDef->canonical,
                                  NULL);
                return;
            }
        }
        /* Phase 2 widget default-property : translate `WIDGET = X` en
         * `WIDGET..<defaultProperty> = X` quand WIDGET est un widget DSL
         * user-declare (Libelle/Bouton/Saisie/Image/Combo/Liste/Selecteur)
         * dont la prop par defaut est connue. Conforme au canon :
         * `<Champ Libelle> = "x"` ≡ `..Valeur = "x"` ≡ `..Libelle`.
         *
         * Avant ce fix : LIB_X = "x" creait silencieusement un global qui
         * shadow le widget. Le widget gardait sa valeur initiale, l'UI ne
         * bougeait pas, le code semblait OK — silencieux et faux, le pire
         * des deux. Repere en test.
         *
         * Sentinel-zone : si defaultProperty=NULL (Table/Interrupteur/
         * ZoneRepetee/Fenetre — widgets composes ou non scalaires), on
         * refuse net avec un message pointant l'alternative correcte.
         * Source de verite : OwlControlKindInfo.defaultProperty defini
         * une seule fois dans ui_decl.c::CONTROL_KINDS. */
        if (isGlobal) {
            char nameBuf[128];
            int nlen = name.length < (int)sizeof(nameBuf) - 1
                       ? name.length : (int)sizeof(nameBuf) - 1;
            memcpy(nameBuf, name.start, (size_t)nlen);
            nameBuf[nlen] = '\0';
            const OwlControlKindInfo* w = vm_find_widget_info_by_name(nameBuf);
            if (w != NULL) {
                if (w->defaultProperty == NULL) {
                    char nameZ[128];
                    int nz = name.length < (int)sizeof(nameZ) - 1
                             ? name.length : (int)sizeof(nameZ) - 1;
                    memcpy(nameZ, name.start, (size_t)nz);
                    nameZ[nz] = '\0';
                    owl_emit_error_at(&name, E_SEM_WIDGET_NOT_SCALAR_ASSIGN,
                                      "name", nameZ,
                                      "kind", w->nameFR,
                                      NULL);
                    return;
                }
                /* Translate `name = RHS` en `name..defaultProperty = RHS` :
                 * stack [widget, val] puis OP_STRUCT_SET <prop>. */
                /*  (Bug B) : si la prop par defaut est MULTILINGUE et le
                 * RHS un litteral inline `{ langueXxx: ... }`, poser le type
                 * cible pour qu'instance_literal construise une chaine
                 * multilingue au lieu d'echouer sur "Litteral {...} sans type
                 * cible". Symetrique de la forme explicite `WIDGET..Prop = {...}`
                 * (~L8265) et de window_parse_property_init (~L18077). Pour une
                 * prop par defaut STRING (Saisie ..Valeur), on ne pose RIEN : le
                 * `{...}` echoue avec le meme diagnostic que la forme explicite
                 * (invariant direct == explicite). */
                if (check(TOKEN_LEFT_BRACE)) {
                    OwlControlKind wkind;
                    if (owl_control_kind_of_info(w, &wkind)) {
                        const OwlControlPropDef* dpdef =
                            owl_control_catalog_find(wkind, w->defaultProperty);
                        if (dpdef && dpdef->type == OWL_PROP_TYPE_MULTILINGUE) {
                            g_inline_target_type     = "cha\xc3\xae" "neMultilingue";
                            g_inline_target_type_len =
                                (int)strlen("cha\xc3\xae" "neMultilingue");
                        }
                    }
                }
                Token rhsFirst = parser.current;
                (void)rhsFirst;
                emit_var_op(OP_GET_GLOBAL, arg);
                condition_expression();
                Token propTok;
                propTok.start = w->defaultProperty;
                propTok.length = (int)strlen(w->defaultProperty);
                propTok.line = name.line;
                propTok.column = name.column;
                propTok.type = TOKEN_IDENTIFIER;
                ConstIdx propConst = identifier_constant(&propTok);
                emit_const_op(OP_STRUCT_SET, propConst);
                /* OP_STRUCT_SET laisse val sur stack (cf vm.c:3267) — pour
                 * un statement plain, l'expression-statement caller pop. */
                return;
            }
        }
        /*  lot 1b — symetrique du check GET ~L7517 : rejeter au
         * compile l'AFFECTATION a une variable globale jamais declaree.
         * Avant : `nInconnu = 42` creait silencieusement une globale fantome
         * write-only (illisible donc inutilisable), alors que `Trace(nInconnu)`
         * levait deja l'erreur en lecture. On ferme l'asymetrie — alignement
         * sur le pilier "typage explicite, pas d'inference implicite".
         *
         * Place APRES le bloc widget : un `WIDGET = X` legitime a deja ete
         * traduit + return ci-dessus. Garde-fous (couverts par
         * is_known_global_name) :
         *   - declarations (`x est un entier = 5`) : x est enregistre dans
         *     g_declaredGlobals AVANT que ce path soit atteint (la decl route
         *     via var_declaration_after_est ; une reaffectation ulterieure
         *     `x = 6` trouve x deja connu).
         *   - locaux / params / membres : arg != -1 -> isGlobal == false.
         *   - noms EXTERNE / Compile(...) pre-scannes -> dans vm.globals.
         *   - variables de champ : <ctrl>__var deja resolu + enregistre. */
        if (isGlobal && setOp == OP_SET_GLOBAL &&
            !is_known_global_name(name.start, name.length)) {
            char nameZ[128];
            int nz = name.length < (int)sizeof(nameZ) - 1
                     ? name.length : (int)sizeof(nameZ) - 1;
            memcpy(nameZ, name.start, (size_t)nz);
            nameZ[nz] = '\0';
            /* willReport : l'erreur est-elle reellement emise (pas deja
             * masquee par un panicMode en cours) ? owl_emit_error_at ignore
             * l'appel si panicMode est deja arme. */
            bool willReport = !parser.panicMode;
            owl_emit_error_at(&name, E_SEM_UNKNOWN_SYMBOL,
                              "name", nameZ,
                              "kind", "variable",
                              NULL);
            /* Quand on emet une NOUVELLE erreur, on consomme le RHS pour
             * laisser le parser sur la frontiere de statement suivante
             * (crossedNewline=true) : synchronize() rend alors la main
             * immediatement et l'erreur du statement suivant est rapportee.
             * Sans ca, le RHS non consomme laisse le parser en milieu de
             * ligne, synchronize() skippe jusqu'au prochain mot-cle et avale
             * les erreurs des lignes suivantes (`x=1 / y=2 / z=3` ne signalait
             * que la premiere). L'appel inconnu, lui, consomme deja tout avant
             * d'emettre — on aligne ce chemin dessus. panicMode (arme par
             * l'emission) suppress les erreurs cascade du RHS.
             *
             * Si l'erreur etait deja masquee (willReport=false), on ne touche
             * PAS a la position : la recuperation de bloc en cours (skip
             * jusqu'au prochain mot-cle) reste maitre, pour ne pas perturber
             * les cascades DSL deja gerees ailleurs. */
            if (willReport) condition_expression();
            return;
        }
        /*  lot C : affectation `m = expr` quand m est typee
         * chaineMultilingue → mutation en place via
         * __MultilingueAssignSource(m, expr). On NE remplace PAS m par un
         * nouveau ObjMultilingue (cela perdrait les autres traductions
         * deja posees — cf scenario_coerce_reaffectation_ecrase_source).
         * Le natif pose la valeur sur la langue source (hardcodee "fr-FR"
         * v1) et laisse les autres clefs intactes.
         *
         * Stack final : [m, expr] -> CALL 2 -> [retour]. Le retour de la
         * native est NIL ; on POP pour ne pas laisser de trace sur la
         * stack (expression-statement caller attend rien). */
        /*  — `m = { ... }` (RHS littéral dict) sur une variable
         * chaîneMultilingue déjà déclarée séparément : REMPLACEMENT. Le type
         * cible n'était câblé qu'à la déclaration (var est un T = {...}), pas à
         * l'affectation nue -> instance_literal levait E_SYNTAX_BRACE_LITERAL_
         * NO_TYPE. On tag g_inline_target_type avec la forme canon accentuée
         * pour qu'instance_literal construise une multilingue fraîche, puis on
         * laisse le path général plus bas faire un SET (le RHS multilingue passe
         * par __InstanceCoerce, pass-through sur ObjMultilingue) : la valeur
         * remplace intégralement m. On court-circuite donc le détour merge
         * __MultilingueAssignSource, réservé au cas scalaire (`m = "x"`) et à
         * `m = <autre variable multilingue>`. */
        if (lhsIsMultilingue && check(TOKEN_LEFT_BRACE)) {
            g_inline_target_type     = "cha\xc3\xae" "neMultilingue";
            g_inline_target_type_len = (int)strlen("cha\xc3\xae" "neMultilingue");
            /* fall-through vers le path d'affectation général (remplacement) */
        } else if (lhsIsMultilingue) {
            /* Stack: [fn, m, rhs] -> CALL 2 pops 3, pushes NIL. expression_
             * statement caller emet ensuite son propre OP_POP qui drop NIL :
             * exactement le contrat de SET_LOCAL/GLOBAL qui ne pop pas non
             * plus (cf OP_SET_LOCAL vm.c::vm_peek(0)). NE PAS rajouter
             * d'OP_POP ici sinon double-pop -> vide le slot local. */
            Token fnTok;
            fnTok.start  = "__MultilingueAssignSource";
            fnTok.length = 25;
            ConstIdx fnIdx = identifier_constant(&fnTok);
            emit_const_op(OP_GET_GLOBAL, fnIdx);
            /* `getOp` vaut OP_GET_LOCAL (slot, 1 octet) ou OP_GET_GLOBAL
             * (index de constante, largeur canonique) : la largeur ne peut
             * pas etre decidee ici, elle vient de la table. */
            emit_var_op(getOp == OP_GET_GLOBAL_CALLEE ? OP_GET_GLOBAL : getOp,
                        arg);  /* push m */
            condition_expression();    /* push rhs */
            emit_bytes(OP_CALL, 2);
            return;
        }

        /*  — littéral {…} en affectation nue sur une variable au type
         * déclaré brace-initialisable (struct utilisateur, Cadre, Style,
         * Police, httpRequête/httpRéponse, durée…) : câble g_inline_target_type
         * depuis le type déclaré de la LHS, exactement comme la déclaration
         * same-line (~L12764). Sans ça instance_literal levait
         * E_SYNTAX_BRACE_LITERAL_NO_TYPE alors que le compilo connaît le type.
         * Sémantique = REMPLACEMENT (instance fraîche), aligné .
         *
         * Le gate check(TOKEN_LEFT_BRACE) laisse intactes les branches à RHS
         * non-`{` (durée string __DureeCoerce, Date/Heure temporel, icones.X
         * in-place isStructIcone, coerce composite __InstanceCoerce, mismatch
         * statique) : elles ne fabriquent jamais d'instance_literal.
         *   - durée : la branche isDuree d'instance_literal émet un entier ms
         *     que le __DureeCoerce du path needsCoerce matérialise (pas de
         *     conflit avec le chemin scalaire, RHS `{` ≠ RHS chaîne/entier).
         *   - Icône : exclu — routing parseur dédié (in-place icones.X, brace
         *     Icône non supporté en décl séparée). */
        if (!lhsIsMultilingue && check(TOKEN_LEFT_BRACE)) {
            bool lhsIsIcone = (lhsStructTypeName != NULL
                               && (strcasecmp(lhsStructTypeName, "Icone") == 0
                                   || strcasecmp(lhsStructTypeName, "Ic\xc3\xb4" "ne") == 0));
            if (lhsStructTypeName != NULL && !lhsIsIcone) {
                g_inline_target_type     = lhsStructTypeName;
                g_inline_target_type_len = (int)strlen(lhsStructTypeName);
            } else if (lhsDeclaredType == TOKEN_DUREE) {
                g_inline_target_type     = "dur\xc3\xa9" "e";
                g_inline_target_type_len = (int)strlen("dur\xc3\xa9" "e");
            } else if (lhsStructTypeName == NULL
                       && type_token_refuses_brace_literal(lhsDeclaredType)) {
                /*  — symetrique de la declaration : cible scalaire
                 * connue, le litteral `{ }` reste refuse quelle que soit sa
                 * forme (sinon `{cle: valeur}` s'auto-nommerait multilingue). */
                g_inline_target_refuses_literal = true;
            }
        }

        /* `var = Null` sur variable non-nullable typée : reset à la zero-value
         * du type déclaré (pattern canon "remettre à valeur par défaut").
         * - chaîne   -> ""
         * - entier   -> 0
         * - réel     -> 0.0
         * - booléen  -> Faux
         * - autres   -> NIL_VAL (fallback ; runtime gère)
         * Sur une nullable, on laisse passer Null tel quel (NIL_VAL stocké). */
        if (check(TOKEN_NUL) && !lhsNullable) {
            advance_token(); /* consume NUL */
            switch (lhsDeclaredType) {
                case TOKEN_CHAINE:
                    emit_constant(OBJ_VAL(obj_copy_string("", 0)));
                    break;
                case TOKEN_ENTIER:
                    emit_constant(INTEGER_VAL(0));
                    break;
                case TOKEN_REEL:
                    emit_constant(REAL_VAL(0.0));
                    break;
                case TOKEN_BOOLEEN:
                    emit_byte(OP_FALSE);
                    break;
                case TOKEN_MONETAIRE:
                    emit_constant(CURRENCY_VAL(0));
                    break;
                case TOKEN_NUMERIQUE:
                    emit_constant(numeric_from_i64(0));
                    break;
                default:
                    /* Type non-typed (Variant retiré) ou type composé sans
                     * zero-value triviale : fallback Null. Le runtime gère. */
                    emit_byte(OP_NIL);
                    break;
            }
            emit_var_op(setOp, arg);
            return;
        }
        /* Sticky type coercion: if the variable was declared with Date/Heure/
         * DateHeure/chaîne, apply the same coercion on reassignment as on
         * initialisation. Sinon `d est une Date` puis `d = "20191225"`
         * écraserait le type (bug canon non-conformité).
         *
         * Strategy: emit the RHS first, THEN try the string-append peephole
         * (compile-time pattern detection that rewrites `s = s + ...` into
         * OP_APPEND_IN_PLACE for O(n) instead of O(n²)). If the peephole
         * succeeds, the result is type-stable by construction (the in-place
         * mutation keeps `s` a string), so no coerce is needed. If it fails
         * AND a coerce was required, retroactively wrap the RHS by inserting
         * `OP_GET_GLOBAL <coerce>` at the saved start position and emitting
         * `OP_CALL 1` at the end. This preserves both behaviours: the hot-loop
         * concat optimisation stays effective, and the Buffer→String / Date /
         * Heure / DateHeure auto-coerce still applies in every other case. */
        /*  — temporels nullables passent par la variante
         * __<T>CoerceNullable (echec parse -> NIL au lieu de chaine brute).
         *
         *  — chaine et Buffer se coercent aussi au cas nullable ;
         * les cinq autres scalaires nullables gardent le passthrough. Meme
         * raison qu'au site de declaration, ne pas refactoriser en un
         * `!lhsNullable` commun : __BufferVersChaine / __ChaineVersBuffer
         * laissent passer NIL intact, alors que __EntierCoerce et consorts
         * l'ecrasent en zero-value et detruiraient la distinction Null /
         * zero-value promise par le `?`. */
        bool lhsIsTemporal = (lhsDeclaredType == TOKEN_DATE ||
                              lhsDeclaredType == TOKEN_HEURE ||
                              lhsDeclaredType == TOKEN_DATEHEURE ||
                              lhsDeclaredType == TOKEN_DUREE);
        bool needsCoerce = lhsIsTemporal ||
                           lhsDeclaredType == TOKEN_CHAINE ||
                           lhsDeclaredType == TOKEN_BUFFER ||
                           lhsDeclaredType == TOKEN_JSON_KW ||
                           (!lhsNullable && (
                            lhsDeclaredType == TOKEN_ENTIER ||
                            lhsDeclaredType == TOKEN_REEL ||
                            lhsDeclaredType == TOKEN_BOOLEEN ||
                            lhsDeclaredType == TOKEN_MONETAIRE ||
                            lhsDeclaredType == TOKEN_NUMERIQUE));
        int rhsStart = current_chunk()->count;
        int rhsLine  = parser.previous.line;
        /* Reassign `dur = "..."` (variable typee duree) -> valide le litteral
         * chaine compile-time (cf. ), symetrique du path init. Skip si
         * la chaine n'est pas isolee (`"...".VersDurée(...)`, concat, etc.).
         * Cf. . */
        if (lhsDeclaredType == TOKEN_DUREE && check(TOKEN_STRING)) {
            Scanner ss = parser.scanner;
            Token cur = parser.current; Token prev = parser.previous;
            bool nl = crossedNewline;
            Token strTok = parser.current;
            advance_token();
            bool isIsolated = check(TOKEN_EOF) || check(TOKEN_RIGHT_PAREN) ||
                              check(TOKEN_COMMA) || check(TOKEN_SEMICOLON) ||
                              check(TOKEN_NEWLINE) || crossedNewline;
            parser.scanner = ss; parser.current = cur;
            parser.previous = prev; crossedNewline = nl;
            if (isIsolated) check_duree_string_literal(&strTok);
        }
        /*  — symetrique reassign pour Date / Heure / DateHeure. */
        if ((lhsDeclaredType == TOKEN_DATE || lhsDeclaredType == TOKEN_HEURE ||
             lhsDeclaredType == TOKEN_DATEHEURE) && check(TOKEN_STRING)) {
            Scanner ss = parser.scanner;
            Token cur = parser.current; Token prev = parser.previous;
            bool nl = crossedNewline;
            Token strTok = parser.current;
            advance_token();
            bool isIsolated = check(TOKEN_EOF) || check(TOKEN_RIGHT_PAREN) ||
                              check(TOKEN_COMMA) || check(TOKEN_SEMICOLON) ||
                              check(TOKEN_NEWLINE) || crossedNewline;
            parser.scanner = ss; parser.current = cur;
            parser.previous = prev; crossedNewline = nl;
            if (isIsolated) check_temporal_string_literal(&strTok, lhsDeclaredType);
        }
        /* `entier = DateHeure` (reassign) : meme check que le path init.
         * Cf. . */
        check_datetime_to_int_static(lhsDeclaredType);
        /*  — rejet coercion structurelle tableau <-> scalaire (reassign). */
        check_array_scalar_mismatch_static(lhsDeclaredType);
        /*  — typage strict objet/struct a la reaffectation. */
        check_object_struct_mismatch_static(lhsStructTypeName);

        /*  Lot 2e-2 — Reassignation polymorphique d'une variable
         * de type Icone : `ICN = icones.X` est un sucre vers
         * `ICN..Icone = icones.X`. Doit preserver les customisations
         * (Couleur, Rotation, Forme) du recepteur (Cas F).
         *
         * Sequence emise :
         *   GET var                   ; [icn]
         *   <expr>                    ; [icn, src]
         *   STRUCT_SET "Icone"        ; [icn, src]  (mutate icn.svg_raw,
         *                               valide, couleur_modifiable, hash —
         *                               cf. vm.c L5496+)
         *   POP                       ; [icn]
         *   SET var                   ; stack vide, var pointe toujours
         *                               sur le meme icn (mutation in-place).
         *
         * On consomme RHS + emet bytecode + return pour bypasser le path
         * commun condition_expression + SET_LOCAL classique qui ecraserait
         * la reference (sans preserver Couleur/Rotation/Forme).
         *
         * Garde-fou : isStructIcone & arg != -1 & locale (les globales
         * suivent un chemin different qu'on n'a pas besoin de gerer ici
         * car les Icones declaree en `est une Icone` sont locales en
         * pratique scenario). Si arg == -1 (global), on retombe sur le
         * path normal (qui ecrase, comportement degrade mais pas crash). */
        /*  : accent-insensible canon Icone/Icône (cf. 
         * canon FR aligne avec canon : Icône avec accent). */
        bool isStructIcone = (lhsStructTypeName != NULL
                              && (strcasecmp(lhsStructTypeName, "Icone") == 0
                                  || strcasecmp(lhsStructTypeName, "Icône") == 0));
        if (isStructIcone && arg != -1) {
            /* OP_STRUCT_SET pop instance + val, push val (cf. compiler.c
             * L4282 + vm.c L5476 IS_ICONE branch). On charge la var deux
             * fois (GET + DUP) pour preserver une copie sous l'expression
             * RHS : la 1ere est consommee par STRUCT_SET (mutate in-place),
             * la 2nde sert au SET de fermeture qui rebind le slot a la
             * meme reference. */
            emit_var_op(getOp, arg);   /* [icn] */
            emit_byte(OP_DUP);                 /* [icn, icn] */
            /*  — Reassignation de slot Icone : re-tag ou invalide.
             * Seulement si la slot est une locale (setOp == OP_SET_LOCAL).
             * Si RHS est literal `icones.Y` pur, re-tag avec Y. Sinon, le
             * RHS est une expression generique (autre Icone, chaine SVG,
             * appel fonction...) -> invalide le tag (plus de warning sur
             * usages suivants). */
            if (setOp == OP_SET_LOCAL && arg >= 0 && arg < UINT8_COUNT) {
                const OwlIconCatalogEntry* iconeEntry =
                    icone_peek_literal_at_current();
                current->locals[arg].icone_catalog_name =
                    (iconeEntry != NULL) ? iconeEntry->name : NULL;
            }
            condition_expression();            /* [icn, icn, src] */
            Token fnameTok;
            fnameTok.start  = "Icone";
            fnameTok.length = 5;
            ConstIdx fnameIdx = identifier_constant(&fnameTok);
            emit_const_op(OP_STRUCT_SET, fnameIdx);/* [icn, src] */
            emit_byte(OP_POP);                  /* [icn] */
            emit_var_op(setOp, arg);    /* stack vide */
            return;
        }

        /* RHS d'assignment : utilise condition_expression (PREC_TERNARY)
         * pour empecher les sub-named_variable d'aspirer leur propre `=`
         * ou `<=` comme assignment chaine — bug parser ambigu. */
        condition_expression();
        /* Mask the freshly-evaluated RHS if the destination is `<indétectable>`.
         * The string-append peephole bypass would defeat masking (the buffer
         * stays in builder mode), so we disable it for undetectable LHS. */
        if (lhsUndetectable) {
            emit_byte(OP_TO_UNDETECTABLE);
            emit_var_op(setOp, arg);
        } else if (try_emit_string_append(rhsStart, arg, setOp,
                                          lhsDeclaredType)) {
            /* Peephole succeeded: OP_APPEND_IN_PLACE(_GLOBAL) was emitted.
             * The in-place mutation keeps `s` a string, no coerce needed. */
        } else if (needsCoerce) {
            const char* fn;
            if (lhsNullable && lhsIsTemporal) {
                fn = lhsDeclaredType == TOKEN_DATE  ? "__DateCoerceNullable" :
                     lhsDeclaredType == TOKEN_HEURE ? "__HeureCoerceNullable" :
                     lhsDeclaredType == TOKEN_DUREE ? "__DureeCoerceNullable" :
                                                      "__DateHeureCoerceNullable";
            } else {
                fn = lhsDeclaredType == TOKEN_DATE      ? "__DateCoerce" :
                     lhsDeclaredType == TOKEN_HEURE     ? "__HeureCoerce" :
                     lhsDeclaredType == TOKEN_DUREE     ? "__DureeCoerce" :
                     lhsDeclaredType == TOKEN_CHAINE    ? "__BufferVersChaine" :
                     lhsDeclaredType == TOKEN_BUFFER    ? "__ChaineVersBuffer" :
                     lhsDeclaredType == TOKEN_JSON_KW   ? "__JSONCoerce" :
                     lhsDeclaredType == TOKEN_ENTIER    ? "__EntierCoerce" :
                     lhsDeclaredType == TOKEN_REEL      ? "__ReelCoerce" :
                     lhsDeclaredType == TOKEN_BOOLEEN   ? "__BooleenCoerce" :
                     lhsDeclaredType == TOKEN_MONETAIRE ? "__MonetaireCoerce" :
                     lhsDeclaredType == TOKEN_NUMERIQUE ? "__NumeriqueCoerce" :
                                                          "__DateHeureCoerce";
            }
            Token fnTok;
            fnTok.start = fn;
            fnTok.length = (int)strlen(fn);
            ConstIdx cidx = identifier_constant(&fnTok);
            insert_const_op_before(rhsStart, OP_GET_GLOBAL, cidx, rhsLine);
            emit_bytes(OP_CALL, 1);
            emit_var_op(setOp, arg);
        } else if (!lhsNullable && lhsStructTypeName != NULL
                   && owl_has_instance_coerce(lhsStructTypeName)) {
            /*  — Reassignation d'une variable typee composite
             * avec parser de coerce enregistre (Couleur, ...) :
             *   c = RVB(...)  ou  c = JauneClair
             * Wrap le RHS via __InstanceCoerce("<typeName>") pour
             * reconstruire une instance composite a partir de l'entier.
             * Sans ce wrap, c deviendrait un scalaire entier brut et
             * perdrait son type composite (regression `c..Rouge`). */
            Token fnTok;
            fnTok.start = "__InstanceCoerce";
            fnTok.length = 16;
            ConstIdx cidx = identifier_constant(&fnTok);
            insert_const_op_before(rhsStart, OP_GET_GLOBAL, cidx, rhsLine);
            ObjString* sName = obj_copy_string(lhsStructTypeName,
                                                (int)strlen(lhsStructTypeName));
            ConstIdx k = make_constant(OBJ_VAL(sName));
            emit_const_op(OP_CONSTANT, k);
            emit_bytes(OP_CALL, 2);
            emit_var_op(setOp, arg);
        } else {
            emit_var_op(setOp, arg);
        }
    } else if (canAssign && match_token(TOKEN_LESS_EQUAL)) {
        /* Deep copy assignment: var <= expr */
        condition_expression();
        emit_byte(OP_DEEP_COPY);
        emit_var_op(setOp, arg);
    } else if (canAssign && match_token(TOKEN_QUESTION_EQUAL)) {
        /* Null-coalescing assignment: var ??= expr
         * Semantics: if var is Null, var = expr; else no-op. Result of the
         * expression-statement is the (possibly updated) current value. */
        emit_var_op(getOp, arg);                /* push current */
        int skipJump = emit_jump(OP_JUMP_IF_NOT_NIL);   /* not null -> skip */
        emit_byte(OP_POP);                              /* drop old value */
        expression();
        emit_var_op(setOp, arg);                /* store RHS */
        patch_jump(skipJump);
    } else if (canAssign && check(TOKEN_REFERENCE)) {
        owl_emit_error_at(&parser.previous, E_SEM_REASSIGN_REFERENCE_OP);
        return;
    } else if (canAssign && match_token(TOKEN_PLUS_EQUAL)) {
        /*  — RHS absent en fin de ligne sur affectation composée : le
         * NEWLINE significatif apres `+=` a ete skippe (crossedNewline). On
         * refuse, ancre sur l'operateur, plutot que d'avaler la ligne suivante
         * comme operande. Meme garde que l'affectation simple ci-dessus. */
        if (crossedNewline) { owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR); return; }
        if (reject_type_assignment(&name, isGlobal)) return;
        int appendStart = current_chunk()->count;
        emit_var_op(getOp, arg);
        expression();
        emit_byte(OP_ADD);
        if (!try_emit_string_append(appendStart, arg, setOp, lhsDeclaredType)) {
            emit_var_op(setOp, arg);
        }
    } else if (canAssign && match_token(TOKEN_MINUS_EQUAL)) {
        /*  — RHS absent en fin de ligne (cf. TOKEN_PLUS_EQUAL). */
        if (crossedNewline) { owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR); return; }
        if (reject_type_assignment(&name, isGlobal)) return;
        emit_var_op(getOp, arg);
        expression();
        emit_byte(OP_SUBTRACT);
        emit_var_op(setOp, arg);
    } else if (canAssign && match_token(TOKEN_STAR_EQUAL)) {
        /*  — RHS absent en fin de ligne (cf. TOKEN_PLUS_EQUAL). */
        if (crossedNewline) { owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR); return; }
        if (reject_type_assignment(&name, isGlobal)) return;
        emit_var_op(getOp, arg);
        expression();
        emit_byte(OP_MULTIPLY);
        emit_var_op(setOp, arg);
    } else if (canAssign && match_token(TOKEN_SLASH_EQUAL)) {
        /*  — RHS absent en fin de ligne (cf. TOKEN_PLUS_EQUAL). */
        if (crossedNewline) { owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR); return; }
        if (reject_type_assignment(&name, isGlobal)) return;
        emit_var_op(getOp, arg);
        Chunk* divChunk = current_chunk();
        int divStart = divChunk->count;
        expression();
        check_div_by_zero_const(divChunk, divStart);
        emit_byte(OP_DIVIDE);
        emit_var_op(setOp, arg);
    } else if (canAssign && match_token(TOKEN_PERCENT_EQUAL)) {
        /*  — RHS absent en fin de ligne (cf. TOKEN_PLUS_EQUAL). */
        if (crossedNewline) { owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR); return; }
        if (reject_type_assignment(&name, isGlobal)) return;
        emit_var_op(getOp, arg);
        expression();
        emit_byte(OP_MODULO);
        emit_var_op(setOp, arg);
    } else if (canAssign && match_token(TOKEN_PLUS_PLUS)) {
        if (reject_type_assignment(&name, isGlobal)) return;
        emit_var_op(getOp, arg);
        emit_byte(OP_INCREMENT);
        emit_var_op(setOp, arg);
    } else if (canAssign && match_token(TOKEN_MINUS_MINUS)) {
        if (reject_type_assignment(&name, isGlobal)) return;
        emit_var_op(getOp, arg);
        emit_byte(OP_DECREMENT);
        emit_var_op(setOp, arg);
    } else {
        /* Block type names used as values (e.g. Definition.Nom instead of def.Nom).
         * Types are never valid as expressions; flag it at compile time.
         *
         * Exceptions legitimes (3 cas) :
         *   1. Le nom double comme fonction native (ex : `httpRequête` type
         *      vs `HTTPRequête` fonction — meme cle apres
         *      case+accent normalisation). L'utilisateur demande la
         *      reference de la fonction, pas le type.
         *   2. Le nom double comme valeur d'enum (ex : `errInfo` est le
         *      nom de l'enumeration ET une de ses valeurs ; cas legitime
         *      cf. stdlib_erreur.c). L'utilisateur ecrit `ExceptionInfo(errInfo)`
         *      pour passer la valeur d'enum.
         *
         * is_type_not_variable excludes variables declared in this unit,
         * so `definition` (variable) won't be rejected even though `Definition`
         * (type) exists. */
        /*  : un nom de type d'enumeration n'est une valeur valide que
         * suivi de `.membre` (acces qualifie). En forme NUE (token suivant !=
         * `.`/`..`), c'est un usage invalide capte au compile — strict-mieux
         * que canon (qui leve une exception runtime). is_type_not_variable() rend
         * false pour SYM_ENUM (, l'enum est lisible comme receveur),
         * donc ce check vit hors de la garde TYPE_USED_AS_VARIABLE ci-dessous. */
        if (isGlobal && getOp == OP_GET_GLOBAL
            && !g_allow_bare_enum_type_arg
            && parser.current.type != TOKEN_DOT
            && parser.current.type != TOKEN_DOUBLE_DOT
            && is_enum_type_name(name.start, name.length)) {
            char probe[128];
            int probeLen = name.length < (int)sizeof(probe) - 1 ? name.length : (int)sizeof(probe) - 1;
            memcpy(probe, name.start, probeLen);
            probe[probeLen] = '\0';
            owl_emit_error_at(&name, E_SEM_ENUM_TYPE_AS_VALUE,
                              "name", probe,
                              NULL);
            return;
        }
        if (isGlobal && getOp == OP_GET_GLOBAL && is_type_not_variable(name.start, name.length)) {
            char probe[128];
            int probeLen = name.length < (int)sizeof(probe) - 1 ? name.length : (int)sizeof(probe) - 1;
            memcpy(probe, name.start, probeLen);
            probe[probeLen] = '\0';
            const OwlNativeDef* asFn = owl_registry_find(probe);
            const OwlConstDef*  asConst = (asFn == NULL)
                ? owl_registry_const_find(probe) : NULL;
            if (asFn == NULL && asConst == NULL) {
                owl_emit_error_at(&name, E_SEM_TYPE_USED_AS_VARIABLE,
                                  "name", probe,
                                  NULL);
                return;
            }
        }

        /* Compile-time identifier validation: we're about to emit a global
         * read (OP_GET_GLOBAL or the _CALLEE variant) for a name that
         * doesn't resolve locally. If it isn't known anywhere in the
         * current compilation unit + registry + prescan, it's a typo or
         * missing declaration — hard compile error.
         *
         * Dynamically-evaluated code (Compile(), EvalueExpression()) is
         * opt-in advanced territory: if the user builds a function body
         * that reads an unknown name, the runtime raises a catchable
         * exception — that's the contract they accepted. */
        /*  (support #212) — nom NU resolvant vers une CONSTANTE de la
         * classe englobante : la resoudre comme <Classe>.<const>. Les constantes
         * de classe sont des static fields, lus par OP_STRUCT_GET sur
         * l'objet classe ; en nom nu dans une methode elles n'etaient pas
         * consultees -> "variable inconnue ou inaccessible". On charge l'objet
         * classe (global) puis on lit le static field, exactement comme l'acces
         * qualifie qui compile deja. Lecture seule (l'ecriture reste rejetee). */
        if (isGlobal && getOp == OP_GET_GLOBAL && currentClass != NULL &&
            class_constant_is(currentClass->name.start, currentClass->name.length,
                              name.start, name.length)) {
            ConstIdx classGlobalC = identifier_constant(&currentClass->name);
            emit_const_op(OP_GET_GLOBAL, classGlobalC);
            ConstIdx constNameC = identifier_constant(&name);
            emit_const_op(OP_STRUCT_GET, constNameC);
            return;
        }
        if (isGlobal && (getOp == OP_GET_GLOBAL || getOp == OP_GET_GLOBAL_CALLEE) &&
            !is_known_global_name(name.start, name.length)) {
            const char* kind = (getOp == OP_GET_GLOBAL_CALLEE)
                             ? "fonction/procedure"
                             : "variable";
            char nameZ[128];
            int nz = name.length < (int)sizeof(nameZ) - 1
                     ? name.length : (int)sizeof(nameZ) - 1;
            memcpy(nameZ, name.start, (size_t)nz);
            nameZ[nz] = '\0';
            owl_emit_error_at(&name, E_SEM_UNKNOWN_SYMBOL,
                              "name", nameZ,
                              "kind", kind,
                              NULL);
            return;
        }

        emit_var_op(getOp, arg);
        /* ??*  — coalesce to the declared type's default value. Works only
         * on simple named variables whose declared type the compiler knows. */
        if (match_token(TOKEN_QUESTION_STAR)) {
            int skipJump = emit_jump(OP_JUMP_IF_NOT_NIL);
            emit_byte(OP_POP);
            switch (lhsDeclaredType) {
                case TOKEN_ENTIER:
                case TOKEN_MONETAIRE:
                case TOKEN_NUMERIQUE:
                case TOKEN_DUREE:
                    emit_constant(INTEGER_VAL(0));
                    break;
                case TOKEN_REEL:
                    emit_constant(REAL_VAL(0.0));
                    break;
                case TOKEN_CHAINE:
                case TOKEN_CARACTERE:
                    emit_constant(OBJ_VAL(obj_copy_string("", 0)));
                    break;
                case TOKEN_BOOLEEN:
                    emit_byte(OP_FALSE);
                    break;
                case TOKEN_DATE:
                case TOKEN_HEURE:
                case TOKEN_DATEHEURE: {
                    /* Call the auto-init native: DateSys / HeureSys / DateHeureSys */
                    const char* fn = lhsDeclaredType == TOKEN_DATE    ? "DateSys"
                                   : lhsDeclaredType == TOKEN_HEURE   ? "HeureSys"
                                   :                                    "DateHeureSys";
                    Token fnTok; fnTok.start = fn; fnTok.length = (int)strlen(fn);
                    ConstIdx c = identifier_constant(&fnTok);
                    emit_const_op(OP_GET_GLOBAL, c);
                    emit_bytes(OP_CALL, 0);
                    break;
                }
                default:
                    /* Unknown / unsupported declared type — fall back to Null. */
                    emit_byte(OP_NIL);
                    break;
            }
            patch_jump(skipJump);
        }
    }
}

/* Check if an identifier matches a project file name */
static bool is_project_file_name(const char* name, int length) {
    if (projectSymbols == NULL) return false;
    for (int i = 0; i < projectSymbols->fileNameCount; i++) {
        int fLen = (int)strlen(projectSymbols->fileNames[i]);
        if (fLen == length && memcmp(projectSymbols->fileNames[i], name, length) == 0) {
            return true;
        }
    }
    return false;
}

/*  — Le nom designe-t-il une Fenetre DSL (SYM_WINDOW) declaree dans
 * le projet ? Une Fenetre voisine s'enregistre AUSSI comme nom de fichier
 * projet (FEN_X.owl). Sans ce filtre, `FEN_X.SAI_Y` se ferait happer par un
 * dispatch cross-file -> global `FEN_X$SAI_Y` inexistant (le proxy du champ
 * est pose sous son nom strippe seul, SAI_Y). On laisse retomber sur
 * named_variable (ObjWindowRef global) + dot() : OP_STRUCT_GET resout la prop
 * fenetre ou le sous-control via la liste plate du decl (fallback ,
 * champs niches inclus). */
static bool is_project_window_name(const char* name, int length) {
    if (projectSymbols == NULL) return false;
    bool ambiguous = false;
    ProjectSymbol* sym = symtable_find(projectSymbols, name, length, &ambiguous);
    if (sym == NULL) return false;
    return sym->kind == SYM_WINDOW;
}

/*  — `theme`/`Theme` est un nom de namespace global reserve, enregistre
 * inconditionnellement au VM init (obj_new_theme_namespace, cf. stdlib_theme.c),
 * exactement comme `icones`. Le fichier de styles s'appelle par convention
 * theme.owl, donc `theme` est aussi un nom de fichier projet : sans cette
 * exclusion, `theme.boutonPrimaire` se ferait happer par le dispatch cross-file
 * -> global `theme$boutonPrimaire` inexistant. On force le fallback sur
 * named_variable (ObjThemeNamespace global) + dot() -> OP_STRUCT_GET.
 * Exclusion INCONDITIONNELLE (pas de check projectSymbols) : le namespace existe
 * toujours. Consequence assumee : pas d'appel cross-file `theme.MaProc()` depuis
 * theme.owl — `theme` est reserve au namespace, comme `icones`.
 * Match case-insensible (scanner strippe les accents mais preserve la casse :
 * `thème` -> `theme`, `Thème` -> `Theme`). */
static bool is_theme_namespace_name(const char* name, int length) {
    return length == 5 && strncasecmp(name, "theme", 5) == 0;
}

/* Le nom designe-t-il un type d'enumeration (in-file ou cross-file) ?
 *  a ajoute SYM_ENUM a is_type_not_variable (l'enum est un objet
 * template lisible comme receveur runtime), ce qui a fait passer aussi
 * `Statut` NU (sans .membre) comme valeur — effet de bord. Ce helper sert
 * a resserrer : un type d'enum n'est une valeur valide que suivi de
 * `.membre` (acces qualifie). On exclut les variables du meme nom : en
 * accent/case-insensible, une variable `couleur` partage la cle du type
 * `Couleur` ; declarée comme global non-structure, elle EST une valeur
 * runtime legitime et ne doit pas etre rejetee. */
static bool is_enum_type_name(const char* name, int length) {
    for (int i = decl_globals_bucket_head(name, length); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (decl_globals_match(i, name, length) &&
            !g_declaredGlobals[i].isStructureType) {
            return false;  /* variable runtime, pas un type nu */
        }
    }
    int idx = user_type_index(name, length);
    if (idx >= 0 && knownUserTypes[idx].kind != OWL_USER_TYPE_UNKNOWN) {
        /* Kind connu (type declare dans CE fichier) : reponse directe. */
        return knownUserTypes[idx].kind == OWL_USER_TYPE_ENUMERATION;
    }
    /* idx >= 0 mais kind UNKNOWN : c'est un type cross-file pre-enregistre par
     * compile_in_project (register_user_type sans poser le kind pour
     * STRUCT/ENUM, cf. ~17150). Le kind reel ne vit que dans projectSymbols —
     * on retombe dessus au lieu de conclure faussement "pas un enum". Sans ce
     * fallthrough, `Statut` NU cross-file echappait au resserrement . */
    if (projectSymbols != NULL) {
        bool ambiguous = false;
        ProjectSymbol* sym = symtable_find(projectSymbols, name, length, &ambiguous);
        if (sym != NULL) return sym->kind == SYM_ENUM;
    }
    return false;
}

/* Compile une lambda N-args : params[0..count-1] deja parses, on compile une
 * expression comme body. La lambda devient un ObjFunction anonyme empile. */
static void compile_lambda_n(Token* params, int paramCount) {
    Compiler compiler;
    init_compiler(&compiler, TYPE_FUNCTION);
    begin_scope();

    char buf[32];
    int line = (paramCount > 0) ? params[0].line : 0;
    snprintf(buf, sizeof(buf), "<lambda@%d>", line);
    current->function->name = obj_copy_string(buf, (int)strlen(buf));
    current->function->arity = paramCount;
    current->function->minArity = paramCount;

    for (int i = 0; i < paramCount; i++) {
        declare_variable(&params[i]);
        if (current->localCount > 0) {
            current->locals[current->localCount - 1].depth = current->scopeDepth;
            current->locals[current->localCount - 1].hasInitializer = true;
        }
    }

    expression();
    emit_byte(OP_RETURN);

    ObjFunction* function = end_compiler();
    emit_const_op(OP_CONSTANT, make_constant(OBJ_VAL(function)));
}

/* Compile une lambda 1-arg : "X => expr". IDENT deja consomme par variable().
 * On consomme '=>' et on delegue a compile_lambda_n. */
static void compile_lambda_1arg(Token paramName) {
    advance_token();  /* consume '=>' */
    Token params[1] = { paramName };
    compile_lambda_n(params, 1);
}

static void variable(bool canAssign) {
    /* Lambda 1-arg : IDENT '=>' expr */
    if (check(TOKEN_FAT_ARROW)) {
        compile_lambda_1arg(parser.previous);
        return;
    }

    /*  — acces qualifie a une globale d'element : `FEN_X.gNom` /
     * `ETAT_X.gCode`. Si le receiver est un nom de fenetre/etat du projet ET
     * que le field nomme une globale top-level connue de cet element, on emet
     * l'opcode dedie OP_GET_ELEMENT_GLOBAL (NIL-tolerant : element endormi ->
     * NIL). Place AVANT le dispatch cross-file `$` general (qui crashe sur
     * symbole inconnu) et avant le dispatch fenetre named_variable+dot (qui
     * resout controle/prop). On peek le field via clone du scanner pour ne
     * consommer que si c'est bien une globale d'element. */
    if (check(TOKEN_DOT)
        && (is_project_window_name(parser.previous.start, parser.previous.length)
            || is_project_file_name(parser.previous.start, parser.previous.length))) {
        Token elemName = parser.previous;
        Scanner savedScan = parser.scanner;
        Token   savedCur  = parser.current;
        Token   savedPrev = parser.previous;
        bool    savedXNL  = crossedNewline;
        advance_token();  /* consume DOT */
        if (check(TOKEN_IDENTIFIER)
            && element_globals_has(elemName.start, elemName.length,
                                   parser.current.start, parser.current.length)) {
            Token fieldTok = parser.current;
            advance_token();  /* consume field name */
            /* Cle mangled `<ELEM>$<field>` = la forme reellement DEFINIE au
             * runtime par var_declaration_after_est lors du parse de
             * l'element. Forme tapee du receiver (invariants casse/accent
             * geres au lookup runtime canon). */
            char qualified[256];
            int qn = snprintf(qualified, sizeof(qualified), "%.*s$%.*s",
                              elemName.length, elemName.start,
                              fieldTok.length, fieldTok.start);
            ConstIdx arg = make_constant(OBJ_VAL(
                obj_copy_string(qualified, qn)));
            emit_const_op(OP_GET_ELEMENT_GLOBAL, arg);
            return;
        }
        /* Pas une globale d'element : rollback, laisse les dispatchs suivants
         * (controle/prop fenetre, cross-file $) traiter. */
        parser.scanner  = savedScan;
        parser.current  = savedCur;
        parser.previous = savedPrev;
        crossedNewline  = savedXNL;
    }

    /*  — acces qualifie a un membre de CollectionDeProcédures :
     * `COL_X.gVar` / `COL_X.Proc(...)`. Le receiver doit etre un nom de bloc
     * collection declare (casse-sensible via collection_member_has, comme
     * is_project_window_name) ET le field un membre connu. Resout vers le slot
     * mangled `COL_X$membre` (OP_GET_GLOBAL, + OP_CALL si suivi de '('). Le nom
     * de FICHIER n'est plus un qualifiant (retire — mort depuis ) :
     * `col_lib.Proc()` ne resout pas (col_lib != COL_Lib au niveau namespace),
     * il retombe en symbole inconnu. */
    if (check(TOKEN_DOT)) {
        Token collName = parser.previous;
        Scanner savedScan = parser.scanner;
        Token   savedCur  = parser.current;
        Token   savedPrev = parser.previous;
        bool    savedXNL  = crossedNewline;
        advance_token();  /* consume DOT */
        if (check(TOKEN_IDENTIFIER)
            && collection_member_has(collName.start, collName.length,
                                     parser.current.start, parser.current.length)) {
            Token memberTok = parser.current;
            advance_token();  /* consume member name */
            char qualified[256];
            int qn = snprintf(qualified, sizeof(qualified), "%.*s$%.*s",
                              collName.length, collName.start,
                              memberTok.length, memberTok.start);
            ConstIdx arg = make_constant(OBJ_VAL(
                obj_copy_string(qualified, qn)));
            emit_const_op(OP_GET_GLOBAL, arg);
            if (check(TOKEN_LEFT_PAREN)) {
                advance_token();  /* consume '(' */
                uint8_t argCount = argument_list();
                emit_bytes(OP_CALL, argCount);
            }
            return;
        }
        /* Pas un membre de collection : rollback, laisse named_variable + dot
         * (classe/type/fenetre/prop) traiter. */
        parser.scanner  = savedScan;
        parser.current  = savedCur;
        parser.previous = savedPrev;
        crossedNewline  = savedXNL;
    }
    named_variable(parser.previous, canAssign);
}

/* ================================================================
 * PARSE RULES TABLE
 * ================================================================ */

/*  : operateur d'introspection (obj est cClasse).
 * Infix sur TOKEN_EST. Le LHS (objet) est deja sur la pile. On consume
 * un IDENT (nom de classe) et on emet OP_IS_CLASS avec le nom. Le
 * runtime walk la chaine superclass et renvoie un booleen.
 *
 * Forme canon : `<obj> est <NomClasse>` (sans `un/une`).
 * Exemple : `Objet1 est ClasseBase1`. */
static void est_class_infix(bool canAssign) {
    (void)canAssign;
    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_at(&parser.previous, E_SEM_EST_EXPECTED_CLASS_NAME);
        return;
    }
    advance_token();
    ConstIdx name = identifier_constant(&parser.previous);
    emit_const_op(OP_IS_CLASS, name);
}

static ParseRule rules[TOKEN_COUNT];

static void init_rules(void) {
    memset(rules, 0, sizeof(rules));

    /* Prefix rules */
    rules[TOKEN_LEFT_PAREN]  = (ParseRule){grouping, call,      PREC_CALL};
    rules[TOKEN_MINUS]       = (ParseRule){unary,    binary,     PREC_TERM};
    rules[TOKEN_INTEGER]     = (ParseRule){number,   NULL,       PREC_NONE};
    rules[TOKEN_REAL]        = (ParseRule){number,   NULL,       PREC_NONE};
    rules[TOKEN_NUMERIC]     = (ParseRule){number,   NULL,       PREC_NONE};
    rules[TOKEN_MONETARY]    = (ParseRule){number,   NULL,       PREC_NONE};
    rules[TOKEN_STRING]          = (ParseRule){string,   NULL,       PREC_NONE};
    rules[TOKEN_STRING_INTERP]   = (ParseRule){string,   NULL,       PREC_NONE};
    rules[TOKEN_BACKTICK_STRING] = (ParseRule){string,   NULL,       PREC_NONE};
    rules[TOKEN_MULTILINE_STRING] = (ParseRule){multiline_string, NULL, PREC_NONE};
    rules[TOKEN_IDENTIFIER]  = (ParseRule){variable, NULL,       PREC_NONE};
    rules[TOKEN_VRAI]        = (ParseRule){literal,  NULL,       PREC_NONE};
    rules[TOKEN_FAUX]        = (ParseRule){literal,  NULL,       PREC_NONE};
    rules[TOKEN_NUL]         = (ParseRule){literal,  NULL,       PREC_NONE};
    rules[TOKEN_PAS]         = (ParseRule){unary,    NULL,       PREC_NONE};

    /* Infix rules */
    rules[TOKEN_PLUS]          = (ParseRule){NULL, binary, PREC_TERM};
    rules[TOKEN_STAR]          = (ParseRule){NULL, binary, PREC_FACTOR};
    rules[TOKEN_SLASH]         = (ParseRule){NULL, binary, PREC_FACTOR};
    rules[TOKEN_MODULO]        = (ParseRule){modulo_prefix, binary, PREC_FACTOR};
    rules[TOKEN_PERCENT]       = (ParseRule){NULL, binary, PREC_FACTOR};
    rules[TOKEN_CARET]         = (ParseRule){NULL, binary, PREC_POWER};
    rules[TOKEN_EQUAL]         = (ParseRule){NULL, binary, PREC_EQUALITY};
    rules[TOKEN_NOT_EQUAL]     = (ParseRule){NULL, binary, PREC_EQUALITY};
    rules[TOKEN_LESS]          = (ParseRule){NULL, binary, PREC_COMPARISON};
    rules[TOKEN_LESS_EQUAL]    = (ParseRule){NULL, binary, PREC_COMPARISON};
    rules[TOKEN_GREATER]       = (ParseRule){NULL, binary, PREC_COMPARISON};
    rules[TOKEN_GREATER_EQUAL] = (ParseRule){NULL, binary, PREC_COMPARISON};
    rules[TOKEN_ET]            = (ParseRule){NULL, and_full, PREC_AND};
    rules[TOKEN_ET_SC]         = (ParseRule){NULL, and_sc,   PREC_AND};
    rules[TOKEN_OU]            = (ParseRule){NULL, or_full,  PREC_OR};
    rules[TOKEN_OU_SC]         = (ParseRule){NULL, or_sc,    PREC_OR};

    /* Opérateur DANS / _DANS_ — appartenance à une liste. Précédence
     * `PREC_EQUALITY` (variante d'égalité). PAS DANS / PAS _DANS_ est
     * détecté en amont dans parse_precedence (peek-2). */
    rules[TOKEN_DANS]          = (ParseRule){NULL, in_operator_infix, PREC_EQUALITY};
    rules[TOKEN_DANS_SC]       = (ParseRule){NULL, in_operator_infix, PREC_EQUALITY};

    /* Bitwise operators (canon : opérateurs binaires).
     * Précédences C-style : ~ unaire (PREC_UNARY) > shifts > comparison >
     * equality > & > || (XOR) > | > logique ET > logique OU. */
    rules[TOKEN_AMPERSAND]     = (ParseRule){NULL, binary, PREC_BIT_AND};
    rules[TOKEN_PIPE]          = (ParseRule){NULL, binary, PREC_BIT_OR};
    rules[TOKEN_DOUBLE_PIPE]   = (ParseRule){NULL, binary, PREC_BIT_XOR};
    rules[TOKEN_TILDE]         = (ParseRule){unary, NULL,  PREC_NONE};
    rules[TOKEN_BIT_SHL]       = (ParseRule){bit_shift_prefix, binary, PREC_BIT_SHIFT};
    rules[TOKEN_BIT_SHR]       = (ParseRule){bit_shift_prefix, binary, PREC_BIT_SHIFT};

    /* Flexible string matching (precedence = equality) */
    rules[TOKEN_TILDE_EQUAL]       = (ParseRule){NULL, string_match_binary, PREC_EQUALITY};
    rules[TOKEN_DOUBLE_TILDE]      = (ParseRule){NULL, string_match_binary, PREC_EQUALITY};
    rules[TOKEN_STARTS_WITH]       = (ParseRule){NULL, string_match_binary, PREC_EQUALITY};
    rules[TOKEN_ENDS_WITH]         = (ParseRule){NULL, string_match_binary, PREC_EQUALITY};
    rules[TOKEN_CONTAINS]          = (ParseRule){NULL, string_match_binary, PREC_EQUALITY};
    rules[TOKEN_STARTS_WITH_FLEX]  = (ParseRule){NULL, string_match_binary, PREC_EQUALITY};
    rules[TOKEN_ENDS_WITH_FLEX]    = (ParseRule){NULL, string_match_binary, PREC_EQUALITY};
    rules[TOKEN_CONTAINS_FLEX]     = (ParseRule){NULL, string_match_binary, PREC_EQUALITY};
    rules[TOKEN_STARTS_WITH_VFLEX] = (ParseRule){NULL, string_match_binary, PREC_EQUALITY};
    rules[TOKEN_ENDS_WITH_VFLEX]   = (ParseRule){NULL, string_match_binary, PREC_EQUALITY};
    rules[TOKEN_CONTAINS_VFLEX]    = (ParseRule){NULL, string_match_binary, PREC_EQUALITY};

    /* Ternary */
    rules[TOKEN_QUESTION]      = (ParseRule){NULL, ternary, PREC_TERNARY};

    /* Null-safe operators */
    rules[TOKEN_QUESTION_QUESTION] = (ParseRule){NULL, coalesce, PREC_TERNARY};
    rules[TOKEN_QUESTION_DOT]      = (ParseRule){NULL, safe_dot, PREC_CALL};

    /* Dot and subscript */
    rules[TOKEN_DOT]           = (ParseRule){dot_prefix, dot, PREC_CALL};
    rules[TOKEN_DOUBLE_DOT]    = (ParseRule){dot_prefix, dot, PREC_CALL}; /* .. = . (property syntax) */
    rules[TOKEN_LEFT_BRACKET]  = (ParseRule){array_literal, subscript, PREC_CALL};
    rules[TOKEN_DOUBLE_BRACKET_OPEN] = (ParseRule){array_literal_2d, string_slice, PREC_CALL};
    rules[TOKEN_LEFT_BRACE]    = (ParseRule){brace_indirection, NULL, PREC_NONE};

    /* :member access (this field) */
    rules[TOKEN_COLON]         = (ParseRule){this_field, NULL, PREC_NONE};

    /*  : Ancetre.Methode() — super-call dans une override. */
    rules[TOKEN_ANCETRE]       = (ParseRule){ancetre_call, NULL, PREC_NONE};

    /*  : Objet — instance courante dans une methode (this/self). */
    rules[TOKEN_OBJET]         = (ParseRule){objet_self, NULL, PREC_NONE};

    /*  : OWL.<native> — namespace d'appel qui vise la fonction
     * native d'origine malgre une procedure globale homonyme. */
    rules[TOKEN_OWL_RESERVED]  = (ParseRule){owl_namespace, NULL, PREC_NONE};

    /*  : MoiMême / MySelf — widget courant resolu via la stack
     * event_sender runtime (top-level fenetre/etat + handler emetteur). */
    rules[TOKEN_MOIMEME]       = (ParseRule){moimeme_self, NULL, PREC_NONE};

    /*  : MonChamp / MyControl (champ courant strict) et
     * MaFenêtre / MyWindow (fenetre courante) — resolution dynamique
     * runtime, calquee sur MoiMême. */
    rules[TOKEN_MONCHAMP]      = (ParseRule){monchamp_self, NULL, PREC_NONE};
    rules[TOKEN_MAFENETRE]     = (ParseRule){mafenetre_self, NULL, PREC_NONE};

    /*  : operateur d'introspection `obj est cClasse`.
     * Le mot-cle EST n'a pas de role en prefix (les declarations
     * `x est un T` sont gerees par var_declaration_after_est en amont,
     * via une detection au niveau statement avant l'entree dans
     * expression()). En contexte expression on a forcement la forme
     * d'introspection — le LHS est deja sur la pile. */
    rules[TOKEN_EST]           = (ParseRule){NULL, est_class_infix, PREC_EQUALITY};
}

static ParseRule* get_rule(TokenType type) {
    return &rules[type];
}

/* Peek non-destructif : le current token est-il TOKEN_PAS suivi (next)
 * par TOKEN_DANS ou TOKEN_DANS_SC ?  Utilisé par parse_precedence pour
 * détecter l'opérateur composé `PAS DANS` / `PAS _DANS_` qui n'est pas
 * exprimable comme simple ParseRule infix (deux tokens consécutifs). */
static bool peek_is_pas_dans(void) {
    if (parser.current.type != TOKEN_PAS) return false;
    Scanner saved     = parser.scanner;
    Token   savedCur  = parser.current;
    Token   savedPrev = parser.previous;
    bool    savedXNL  = crossedNewline;
    advance_token();  /* consume PAS provisoirement */
    bool match = (parser.current.type == TOKEN_DANS ||
                  parser.current.type == TOKEN_DANS_SC);
    parser.scanner    = saved;
    parser.current    = savedCur;
    parser.previous   = savedPrev;
    crossedNewline    = savedXNL;
    return match;
}

static void parse_precedence(Precedence precedence) {
    /*  : TOKEN_TYPE libres (date, heure, dateheure, duree, json, uuid)
     * peuvent servir de noms de variable / parametre / champ. Ici en position
     * d'expression (lecture), on les "demote" en IDENTIFIER avant le dispatch
     * parselet pour que le path identifier classique resolve la variable.
     * Si aucune variable de ce nom n'existe en scope, le message "Variable
     * inconnue" sera emis — bien plus parlant que "Expression attendue". */
    (void)demote_free_type_to_identifier();
    /*  : idem pour les noms de type widget (Fenetre, Libelle, Bouton,
     * Saisie, Table, Colonne) utilises comme variable en position d'expression. */
    (void)demote_widget_keyword_to_identifier();
    (void)demote_liberer_native_call_to_identifier();
    advance_token();
    ParseFn prefixRule = get_rule(parser.previous.type)->prefix;
    if (prefixRule == NULL) {
        /*  — GLOBAL / LOCAL au milieu d'une expression (pas en tete de
         * declaration) : diagnostic dedie plutot que le generique "Expression
         * attendue", pour pointer l'usage correct (bascule de portee top-level). */
        if (parser.previous.type == TOKEN_GLOBAL || parser.previous.type == TOKEN_LOCAL) {
            owl_emit_error_at(&parser.previous, E_SYNTAX_GLOBAL_LOCAL_MISPLACED);
            return;
        }
        owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR);
        return;
    }

    bool canAssign = precedence <= PREC_ASSIGNMENT;
    prefixRule(canAssign);

    /* Boucle infix : la condition de garde combine la précédence
     * standard ParseRule ET la détection peek-2 de `PAS DANS` (qui n'a
     * pas de ParseRule propre car composé de 2 tokens). */
    while (precedence <= get_rule(parser.current.type)->precedence ||
           (precedence <= PREC_EQUALITY && peek_is_pas_dans())) {
        /* Inside AVEC blocks, a DOT after a newline is a new `.member`
         * statement, not an infix member access on the previous value. */
        if (avecDepth > 0 && parser.current.type == TOKEN_DOT
                          && crossedNewline) {
            break;
        }
        /* A ( after a newline is a new statement (possibly multi-assign),
         * not a function call on the previous expression. */
        if (parser.current.type == TOKEN_LEFT_PAREN && crossedNewline) {
            break;
        }
        /* PAS DANS / PAS _DANS_ : opérateur composé invisible aux
         * ParseRules. On consume les deux tokens et on émet la cascade
         * négative directement (équivalent à NON (v DANS (...))). La
         * stratégie SC/full dépend du token DANS rencontré. */
        if (parser.current.type == TOKEN_PAS) {
            advance_token();                              /* consume PAS */
            TokenType inTok = parser.current.type;        /* DANS ou DANS_SC */
            advance_token();                              /* consume DANS / _DANS_ */
            in_operator_dispatch(true, inTok);
            continue;
        }
        advance_token();
        ParseFn infixRule = get_rule(parser.previous.type)->infix;
        if (infixRule == NULL) break;
        infixRule(canAssign);
    }
}

static void expression(void) {
    parse_precedence(PREC_ASSIGNMENT);
}

/* Parse an expression where '=' is always comparison, never assignment.
 * Used in contexts like SI condition, TANTQUE condition, etc. */
static void condition_expression(void) {
    parse_precedence(PREC_TERNARY);
}

/* ================================================================
 * STATEMENT PARSING
 * ================================================================ */

/* When true (set by owl --repl), bare expressions auto-print their value.
 * Off by default so compiled scripts / project mode keep their original
 * "silent unless Trace()" semantics. */
static bool g_auto_print_expr = false;

void compile_set_auto_print(bool enabled) { g_auto_print_expr = enabled; }

/* Whitelist of "pure read" opcodes: those that only load/compute a value
 * without any side effect (no call, no assignment, no mutation). Returns true
 * and sets *outLen to the total instruction length (opcode + operands) when
 * `op` is a pure read. Returns false for anything else — calls (OP_CALL /
 * OP_INVOKE*), stores (OP_SET_* / OP_STRUCT_SET / OP_ARRAY_SET* /
 * OP_APPEND_* / OP_OUT_PARAM_* ...), control flow, and every unknown opcode.
 *
 * Direction of safety: an expression made ONLY of pure reads has no effect
 * (report it). The moment a non-whitelisted opcode appears, we treat the
 * statement as effectful and stay silent — so a mis-classification can only
 * miss a diagnostic, never wrongly reject legit effectful code. */
static bool expr_stmt_is_pure_read(uint8_t op) {
    switch (op) {
        case OP_NIL: case OP_TRUE: case OP_FALSE:
        case OP_ADD: case OP_SUBTRACT: case OP_MULTIPLY: case OP_DIVIDE:
        case OP_MODULO: case OP_POWER: case OP_NEGATE:
        case OP_EQUAL: case OP_NOT_EQUAL:
        case OP_GREATER: case OP_GREATER_EQUAL: case OP_LESS: case OP_LESS_EQUAL:
        case OP_NOT: case OP_AND_FULL: case OP_OR_FULL:
        case OP_BIT_AND: case OP_BIT_OR: case OP_BIT_XOR: case OP_BIT_NOT:
        case OP_BIT_SHL: case OP_BIT_SHR:
        case OP_CONCAT:
        case OP_ARRAY_GET: case OP_ARRAY_GET_2D: case OP_ARRAY_LENGTH:
        case OP_GET_THIS: case OP_DUP: case OP_SWAP:
        case OP_CONSTANT:
        case OP_GET_GLOBAL: case OP_GET_GLOBAL_CALLEE:
        case OP_GET_ELEMENT_GLOBAL: case OP_GET_TYPE_GLOBAL:
        case OP_GET_LOCAL:
        case OP_STRUCT_GET:
        case OP_STRING_MATCH:
            return true;
        default:
            return false;
    }
}

/* True if the bytecode emitted for the current statement-expression
 * (chunk[start .. count)) contains at least one effectful opcode. */
static bool expr_stmt_has_effect(Chunk* chunk, int start) {
    int ip = start;
    while (ip < chunk->count) {
        if (!expr_stmt_is_pure_read(chunk->code[ip])) return true;
        int len = chunk_opcode_size(chunk->code[ip], chunk, ip);
        if (len <= 0) return true;
        ip += len;
    }
    return false;
}

/* Longueur d'une lecture nue `[OP_GET_GLOBAL][nom]`, seule forme reconnue
 * comme « reference a une fonction sans les parentheses ». */
static int bare_global_read_len(void) {
    Chunk dummy = { 0, 0, NULL, NULL, { 0, 0, NULL } };
    return chunk_opcode_size(OP_GET_GLOBAL, &dummy, 0);
}

static void expression_statement(void) {
    /* Snapshot before parsing so we can detect a bare dangling identifier
     * (expression consisted of nothing but OP_GET_GLOBAL). */
    int chunkStart = current_chunk()->count;
    Token firstTok = parser.current;

    expression();

    /* An expression-statement whose bytecode has no side effect (no call, no
     * assignment) does nothing useful — reject it. Exempt REPL mode where a
     * bare expression is auto-printed. */
    if (!g_auto_print_expr && !expr_stmt_has_effect(current_chunk(), chunkStart)) {
        /* Prefer the tailored "forgot the ()" message when the whole
         * statement is a lone native function identifier. */
        int emitted = current_chunk()->count - chunkStart;
        bool barePattern = (emitted == bare_global_read_len() &&
                            current_chunk()->code[chunkStart] == OP_GET_GLOBAL);
        const OwlNativeDef* d = barePattern
            ? bare_identifier_as_native(&firstTok) : NULL;
        if (d != NULL) {
            char nameZ[128];
            int nz = firstTok.length < (int)sizeof(nameZ) - 1
                     ? firstTok.length : (int)sizeof(nameZ) - 1;
            memcpy(nameZ, firstTok.start, (size_t)nz);
            nameZ[nz] = '\0';
            owl_emit_error_at(&firstTok, E_SEM_BARE_FUNCTION_REFERENCE,
                              "name", nameZ,
                              NULL);
        } else {
            owl_emit_error_at(&firstTok, E_SEM_INSTRUCTION_SANS_EFFET, NULL);
        }
        /* Still emit the POP so the stack stays balanced; downstream compile
         * passes keep going to surface further errors. */
    }

    emit_byte(g_auto_print_expr ? OP_PRINT : OP_POP);
}

/* Check if TOKEN_COLON is a return type separator (not :fieldAccess).
 * A return type colon is followed by a builtin type keyword. */
static bool is_return_type_colon(void) {
    if (!check(TOKEN_COLON)) return false;
    /* Peek at token after the colon without consuming it.
     * Since our scanner skips newlines in advance_token, we scan ahead. */
    Scanner saved = parser.scanner;
    Token savedCurrent = parser.current;
    /*  : save crossedNewline aussi. advance_token reset
     * crossedNewline a chaque appel, donc sans restore les callers
     * post-is_return_type_colon voient un crossedNewline corrompu
     * (typiquement false alors qu'on a saute un newline avant le ':'). */
    bool savedCrossed = crossedNewline;
    advance_token(); /* consume ':' */
    bool result = check(TOKEN_ENTIER) || check(TOKEN_REEL) ||
                  check(TOKEN_CHAINE) || check(TOKEN_BOOLEEN) ||
                  check(TOKEN_MONETAIRE) || check(TOKEN_NUMERIQUE) ||
                  check(TOKEN_CARACTERE) || check(TOKEN_DATE) ||
                  check(TOKEN_HEURE) || check(TOKEN_DATEHEURE) ||
                  check(TOKEN_DUREE) || check(TOKEN_BUFFER) ||
                  check(TOKEN_UUID) ||
                  check(TOKEN_JSON_KW) ||
                  check(TOKEN_TABLEAU) ||
                  check(TOKEN_STRUCTURE);
    /* User-defined type names (struct/class/enum declared in this file or
     * in the project). Accept any IDENTIFIER that matches a known type. */
    if (!result && check(TOKEN_IDENTIFIER)) {
        result = is_any_known_type(parser.current.start, parser.current.length);
    }
    /* Restore scanner state */
    parser.scanner = saved;
    parser.current = savedCurrent;
    crossedNewline = savedCrossed;
    return result;
}

/* Skip tokens of a type declaration: entier, chaine, reel, etc. */
static bool is_type_token(void) {
    return check(TOKEN_ENTIER) || check(TOKEN_REEL) || check(TOKEN_CHAINE) ||
           check(TOKEN_BOOLEEN) || check(TOKEN_MONETAIRE) || check(TOKEN_NUMERIQUE) ||
           check(TOKEN_CARACTERE) || check(TOKEN_DATE) || check(TOKEN_HEURE) ||
           check(TOKEN_DATEHEURE) || check(TOKEN_DUREE) || check(TOKEN_BUFFER) ||
           check(TOKEN_UUID) || check(TOKEN_JSON_KW) ||
           check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION) ||
           check(TOKEN_TABLEAU) || check(TOKEN_STRUCTURE) || check(TOKEN_IDENTIFIER);
}

/* After a type has been parsed, consume an optional nullability/attribute
 * marker:
 *   '?'                       — postfix shorthand for <nullable>
 *   '<nullable>'              — nullability attribute
 *   '<indétectable>'          — RAM-masking attribute (chaîne only)
 *   '<attr1, attr2, ...>'     — list form, attributes recognized as above;
 *                               unknown attributes are tolerated and skipped
 *
 * Returns true if the type is nullable. Sets *outUndetectable (if non-NULL)
 * when an indétectable attribute is encountered. */
static bool parse_nullability_marker_ex(bool* outUndetectable,
                                        bool* outSuppressUnused) {
    bool nullable = false;
    if (outUndetectable) *outUndetectable = false;
    if (outSuppressUnused) *outSuppressUnused = false;
    /* Postfix '?' */
    if (match_token(TOKEN_QUESTION)) nullable = true;
    /* <attr1, attr2, ...> extension attribute list. */
    while (check(TOKEN_LESS)) {
        advance_token(); /* consume '<' */
        while (!check(TOKEN_GREATER) && !check(TOKEN_EOF) && !check(TOKEN_NEWLINE)) {
            if (check(TOKEN_IDENTIFIER)) {
                int n = parser.current.length;
                const char* p = parser.current.start;
                if (n == 8 && strncmp(p, "nullable", 8) == 0) {
                    nullable = true;
                } else if (outUndetectable &&
                    /* "indétectable" UTF-8 = 13 bytes (é = 0xC3 0xA9), or
                     * ASCII alias "indetectable" = 12 bytes. */
                    ((n == 13 && strncmp(p, "ind\xc3\xa9tectable", 13) == 0) ||
                     (n == 12 && strncmp(p, "indetectable", 12) == 0))) {
                    *outUndetectable = true;
                } else if (outSuppressUnused &&
                    /*  — attribut d'opt-out unused. Casse-insensible
                     * (invariant 1), bilingue (invariant 3). Ni "utile" ni
                     * "useful" ne portent d'accent -> pas de strip requis.
                     * La forme valeur `<utile="...">` est toleree telle quelle :
                     * le `=` et la chaine libre tombent dans le else generique
                     * ci-dessous et sont simplement consommes (pas d'usage
                     * semantique lot 1). */
                    ((n == 5 && strncasecmp(p, "utile", 5) == 0) ||
                     (n == 6 && strncasecmp(p, "useful", 6) == 0))) {
                    *outSuppressUnused = true;
                }
                advance_token();
            } else {
                advance_token(); /* tolerate other attribute tokens (=, "valeur", ...) */
            }
            if (check(TOKEN_COMMA)) advance_token();
        }
        if (check(TOKEN_GREATER)) advance_token();
    }
    return nullable;
}


/* Parse a literal default value for an optional parameter.
 *   foo(x est un entier = 5, name est une chaine = "hi", flag = Faux)
 * Only literals are accepted (integer/real/string/bool/Null + unary '-').
 * Returns the Value by reference and true on success; emits an error and
 * returns false otherwise. The caller is responsible for advancing past
 * the leading '='. */
/* Tente de resoudre un identifiant comme constante compile-time utilisable en
 * valeur par defaut de parametre. Deux sources, dans cet ordre :
 *   1. CONSTANT utilisateur declaree AVANT (map compile-time nom->Value).
 *   2. Constante native/systeme + membre d'enum (registre, dispo au parse-time).
 * Renvoie true et remplit *out si l'identifiant designe une constante connue ;
 * false sinon (l'appelant retombe alors sur E_SEM_DEFAULT_MUST_BE_LITERAL).
 * N'accepte JAMAIS une variable, un appel de fonction ou une expression :
 * seules les valeurs repliees compile-time matchent. */
static bool resolve_const_default_value(Token tok, Value* out) {
    if (const_globals_find_value(tok.start, tok.length, out)) {
        return true;
    }
    char name[256];
    if (tok.length > 0 && tok.length < (int)sizeof(name)) {
        memcpy(name, tok.start, (size_t)tok.length);
        name[tok.length] = '\0';
        const OwlConstDef* c = owl_registry_const_find_bilingual(name);
        if (c != NULL) {
            *out = c->value;
            return true;
        }
    }
    return false;
}

/* Resync apres rejet d'une valeur par defaut invalide (ex : appel de
 * fonction, non const-foldable). Sans ca, les tokens restants de
 * l'expression rejetee (`Taille("xx")`) restent dans le flux, la boucle
 * `do { ... } while (match_token(COMMA))` de parsing des params ne voit pas
 * la virgule suivante et le parametre d'apres est perdu -> cascade d'erreurs
 * parasites. On avale jusqu'au prochain separateur de param au niveau 0
 * (virgule) ou la parenthese fermante, en gardant les parentheses internes
 * equilibrees. Bornes de securite : FIN / EOF si la `)` manque. */
static void skip_invalid_param_default(void) {
    int depth = 0;
    for (;;) {
        TokenType t = parser.current.type;
        if (t == TOKEN_EOF || t == TOKEN_FIN) return;
        if (depth == 0 && (t == TOKEN_COMMA || t == TOKEN_RIGHT_PAREN)) return;
        if (t == TOKEN_LEFT_PAREN) depth++;
        else if (t == TOKEN_RIGHT_PAREN) depth--;
        advance_token();
    }
}

static bool parse_default_literal_atom(Value* out) {
    bool negate = false;
    if (match_token(TOKEN_MINUS)) {
        negate = true;
    }
    Token tok = parser.current;
    switch (tok.type) {
        case TOKEN_INTEGER: {
            char buf[64];
            int j = 0;
            for (int i = 0; i < tok.length && j < 63; i++) {
                char c = tok.start[i];
                if (c != '_' && c != ' ') buf[j++] = c;
            }
            buf[j] = '\0';
            int64_t v = strtoll(buf, NULL, 0);
            if (negate) v = -v;
            *out = INTEGER_VAL(v);
            advance_token();
            return true;
        }
        case TOKEN_REAL: {
            char buf[64];
            int j = 0;
            for (int i = 0; i < tok.length && j < 63; i++) {
                char c = tok.start[i];
                if (c != '_' && c != ' ') buf[j++] = c;
            }
            buf[j] = '\0';
            double v = strtod(buf, NULL);
            if (negate) v = -v;
            *out = REAL_VAL(v);
            advance_token();
            return true;
        }
        case TOKEN_STRING: {
            if (negate) {
                owl_emit_error_at(&parser.previous, E_SEM_DEFAULT_MINUS_PREFIX_INVALID,
                                  "kind", "string",
                                  NULL);
                return false;
            }
            *out = OBJ_VAL(string_literal_value_from_token(tok));
            advance_token();
            return true;
        }
        case TOKEN_VRAI:
            if (negate) {
                owl_emit_error_at(&parser.previous, E_SEM_DEFAULT_MINUS_PREFIX_INVALID,
                                  "kind", "boolean", NULL);
                return false;
            }
            *out = BOOL_VAL(true);
            advance_token();
            return true;
        case TOKEN_FAUX:
            if (negate) {
                owl_emit_error_at(&parser.previous, E_SEM_DEFAULT_MINUS_PREFIX_INVALID,
                                  "kind", "boolean", NULL);
                return false;
            }
            *out = BOOL_VAL(false);
            advance_token();
            return true;
        case TOKEN_NUL:
            if (negate) {
                owl_emit_error_at(&parser.previous, E_SEM_DEFAULT_MINUS_PREFIX_INVALID,
                                  "kind", "Null", NULL);
                return false;
            }
            *out = NIL_VAL;
            advance_token();
            return true;
        default:
            /* Identifiant : tente une resolution en constante compile-time
             * (CONSTANT utilisateur, native/systeme, membre d'enum). Le `-`
             * unaire ne s'applique qu'aux constantes numeriques. */
            if (tok.type == TOKEN_IDENTIFIER) {
                Value cval;
                if (resolve_const_default_value(tok, &cval)) {
                    if (negate) {
                        if (IS_INTEGER(cval)) {
                            cval = INTEGER_VAL(-AS_INTEGER(cval));
                        } else if (IS_REAL(cval)) {
                            cval = REAL_VAL(-AS_REAL(cval));
                        } else {
                            owl_emit_error_at(&parser.previous,
                                              E_SEM_DEFAULT_MINUS_PREFIX_INVALID,
                                              "kind", "constant", NULL);
                            return false;
                        }
                    }
                    *out = cval;
                    advance_token();
                    return true;
                }
            }
            owl_emit_error_at(&parser.previous, E_SEM_DEFAULT_MUST_BE_LITERAL);
            return false;
    }
}

/* Wrapper : parse un litteral de valeur par defaut ; sur rejet, resynchronise
 * le flux de tokens sur le prochain separateur de param pour ne pas
 * desynchroniser la boucle de parsing des params (cf.
 * skip_invalid_param_default). */
static bool parse_default_literal(Value* out) {
    if (parse_default_literal_atom(out)) return true;
    skip_invalid_param_default();
    return false;
}

/* Avale les fillers EN "a"/"an" optionnellement presents apres IS/ARE
 * (equivalent des articles FR "un"/"une"/"des", strippes en position d'article
 * par le scanner, cf. scan_identifier).
 * Ne peut pas etre cote scanner car "a" est surcharge : le scanner le mappe
 * sur TOKEN_A (borne de plage `POUR i DE 1 A 10`). En position de
 * declaration (juste apres EST/SONT) une borne de plage n'a aucun sens, donc
 * un TOKEN_A ici est sans ambiguite l'article EN `a` (`is a Window`). `an`
 * n'est pas un keyword scanner -> arrive en TOKEN_IDENTIFIER. */
static void consume_en_a_an_filler(void) {
    if (check(TOKEN_A)) {            /* article `a` (scanne comme borne TOKEN_A) */
        advance_token();
        return;
    }
    if (!check(TOKEN_IDENTIFIER)) return;
    Token t = parser.current;
    if (t.length == 1 && (t.start[0] == 'a' || t.start[0] == 'A')) {
        advance_token();
    } else if (t.length == 2 &&
               (t.start[0] == 'a' || t.start[0] == 'A') &&
               (t.start[1] == 'n' || t.start[1] == 'N')) {
        advance_token();
    }
}

/*  — peek non destructif : le construct courant est-il une
 * declaration de classe (`IDENT est un[e] Classe`) ? Renseigne le token du nom
 * pour le message d'erreur. Utilise par le corps du bloc collection, ou une
 * classe est interdite (1 classe = 1 fichier). */
static bool peek_top_level_is_class_declaration(Token* outName) {
    if (!check(TOKEN_IDENTIFIER)) return false;
    Scanner saved     = parser.scanner;
    Token   savedCur  = parser.current;
    Token   savedPrev = parser.previous;
    bool    savedXNL  = crossedNewline;
    Token   nameTok   = parser.current;
    bool    isClass   = false;
    advance_token();  /* IDENT (nom de la classe) */
    if (check(TOKEN_EST) || check(TOKEN_SONT)) {
        advance_token();
        consume_en_a_an_filler();
        isClass = check(TOKEN_CLASSE);
    }
    parser.scanner   = saved;
    parser.current   = savedCur;
    parser.previous  = savedPrev;
    crossedNewline   = savedXNL;
    if (isClass && outName != NULL) *outName = nameTok;
    return isClass;
}

/* Defini plus bas (17813) ; utilise par skip_type_spec_ex pour absorber la
 * forme `tableau associatif de <T>` (les deux ordres de mots). */
static bool try_consume_assoc_array_field_type(int* outValueKind,
                                               Token* outValueTypeName);

/*  — variante validante de skip_type_spec. `validate` branche la
 * verification du nom de type (via la table pending post-parse) sur les
 * contextes qui l'ignoraient (champ de structure, parametre collection) ;
 * `asCollectionElem` distingue la position :
 *   - HEAD scalaire (`x est un Montan`) -> semantique var-scalaire :
 *     record_pending_type_ref, le pluriel est rejete.
 *   - ELEMENT de collection (apres `de`, `x est un tableau de Zorglub`) ->
 *     record_collection_elem_type_ref, qui tolere le pluriel primitif
 *     (`de dates` -> date) et detecte le Variant retire.
 * Les primitifs (TOKEN_ENTIER, TOKEN_CHAINE...) arrivent en tokens dedies,
 * jamais IDENTIFIER : jamais enregistres, jamais rejetes. skip_type_spec()
 * reste le chemin non-validant historique (validate=false). */
static void skip_type_spec_ex(bool validate, bool asCollectionElem) {
    /* Avale "a"/"an" EN fillers (canon EN 'is a string'). */
    consume_en_a_an_filler();

    /*  — `tableau associatif de <T>` (les deux ordres de mots) etait
     * refuse en position de PARAMETRE de procedure (skip_type_spec ne connait
     * que TOKEN_TABLEAU seul et laissait `associatif de <T>` en suspens ->
     * "')' attendu apres les parametres"), alors qu'il est accepte en
     * declaration de variable locale. Meme helper que les champs de structure
     * : consomme TOUTE la spec assoc ou ne consomme rien. */
    {
        int assocVK = 0;
        Token assocVTN; assocVTN.start = NULL; assocVTN.length = 0;
        if (try_consume_assoc_array_field_type(&assocVK, &assocVTN)) return;
    }

    bool wasString = check(TOKEN_CHAINE);
    if (validate && check(TOKEN_IDENTIFIER)) {
        if (asCollectionElem) {
            (void)record_collection_elem_type_ref(parser.current);
        } else {
            Token typeTok = parser.current;
            canonicalize_builtin_type_token(&typeTok);
            record_pending_type_ref(typeTok);
        }
    }
    if (is_type_token()) {
        advance_token();
    } else {
        owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_TYPE_NAME);
        return;
    }

    /* "chaîne ANSI" / "chaîne UNICODE" / "chaîne fixe" : encodage/taille
     * attaches au type chaine -> rejet (/ : chaines UTF-8
     * uniformes, sans encodage ni taille fixe). skip_type_spec est le chemin
     * partage (var, parametre, champ...) : le rejet couvre tous les contextes.
     * On consomme le modifieur avant d'emettre pour eviter une cascade
     * d'erreurs secondaires (meme pattern que 'sur N octets' / 'sans signe'). */
    if (wasString) {
        /* 'fixe' est un mot-cle (TOKEN_FIXE) ; 'ANSI'/'UNICODE' arrivent en
         * TOKEN_IDENTIFIER. On couvre les deux tokenisations. */
        bool isChaineModif = check(TOKEN_FIXE);
        if (!isChaineModif && check(TOKEN_IDENTIFIER)) {
            Token tok = parser.current;
            isChaineModif =
                (tok.length == 4 && strncasecmp(tok.start, "ANSI", 4) == 0) ||
                (tok.length == 7 && strncasecmp(tok.start, "UNICODE", 7) == 0);
        }
        if (isChaineModif) {
            Token tok = parser.current;
            advance_token();
            owl_emit_error_at(&tok, E_SYNTAX_TYPE_CHAINE_ENCODAGE);
            return;
        }
    }

    /* "sur N octets" : type dimensionne -> rejet. On consomme la
     * forme entiere pour pointer l'erreur dessus, puis on s'arrete. */
    if (match_token(TOKEN_SUR)) {
        if (check(TOKEN_INTEGER)) advance_token();
        /* 'octets' / 'bytes' n'est plus un mot-cle : il arrive en
         * TOKEN_IDENTIFIER. On le consomme pour eviter un token residuel en
         * cascade ; l'erreur reste pointee sur la forme dimensionnee. */
        if (check(TOKEN_IDENTIFIER)) advance_token();
        owl_emit_error_at(&parser.previous, E_SYNTAX_TYPE_DIMENSIONNE);
        return;
    }

    /* "sans signe" : modificateur sans effet sur le modele octet -> rejet. */
    if (match_token(TOKEN_SANS)) {
        if (check(TOKEN_SIGNE)) advance_token();
        owl_emit_error_at(&parser.previous, E_SYNTAX_TYPE_SANS_SIGNE);
        return;
    }

    /* Handle "de <type>" for arrays: tableau de entiers
     * Also handle "d'entiers" where d' was eaten by scanner as filler.
     * Only match actual type keywords (not identifiers) to avoid eating the next statement.
     *
     *  : ajouter une garde !crossedNewline. Sans cela, quand une
     * variable porte le nom d'un TOKEN_TYPE libre (`date`, `duree`, ...)
     * en debut de ligne suivante, skip_type_spec consomme cette ligne
     * comme suffixe de type. Ex: `durée est une durée\ndate est une date`
     * voyait `date` apres le 2e `durée` et l'avalait, cassant la decl
     * suivante. */
    if (match_token(TOKEN_DE)) {
        /* Element de collection : semantique record_collection_elem_type_ref. */
        skip_type_spec_ex(validate, true);
    } else if (!crossedNewline &&
               (check(TOKEN_ENTIER) || check(TOKEN_REEL) || check(TOKEN_CHAINE) ||
                check(TOKEN_BOOLEEN) || check(TOKEN_MONETAIRE) || check(TOKEN_NUMERIQUE) ||
                check(TOKEN_CARACTERE) || check(TOKEN_DATE) || check(TOKEN_HEURE) ||
                check(TOKEN_DATEHEURE) || check(TOKEN_DUREE) || check(TOKEN_BUFFER) ||
                check(TOKEN_UUID) || check(TOKEN_JSON_KW))) {
        advance_token(); /* consume the type keyword directly after d' elision */
    }
}

static void skip_type_spec(void) {
    skip_type_spec_ex(false, false);
}

/* Parse the rest of a var declaration AFTER identifier and EST have been consumed. */
/* ================================================================
 * Helper enum partage par la contrainte de prop DSL (param ∈ enum) :
 * verification d'appartenance d'une valeur entiere a un enum du registry.
 * ================================================================ */

/* True si target tombe dans la plage sentinel de e (au moins une de ses
 * constantes a cette valeur). Utilise pour rejeter une valeur entiere
 * hors-plage sur une prop DSL enum-contrainte au compile-time. */
static bool enum_contains_int(const OwlEnum* e, int64_t target) {
    if (e == NULL || e->values == NULL) return false;
    for (int i = 0; e->values[i] != NULL; i++) {
        const OwlConstDef* c = owl_registry_const_find(e->values[i]);
        if (c == NULL) continue;
        if (IS_INTEGER(c->value) && AS_INTEGER(c->value) == target) return true;
    }
    return false;
}

/*  — resolution d'une constante langueXxx vers son tag BCP 47.
 * Definie dans stdlib_i18n.c ; declaree ici pour le const-check du champ
 * Langues du type Projet sans tirer tout owl_stdlib.h dans le compilo. */
extern const char* owl_i18n_lookup_tag_by_constant_name(const char* constName);

/* owl_bcp47_canon vient de owl_name_normalize.h (source UNIQUE dep-free). */

/*  — capture COMPILE-TIME de la 1ere langue declaree dans le champ
 * Langues d'un bloc Projet ( : metadonnee constante, lisible sans
 * executer le corps). Le runtime (project_run) boote l'i18n depuis ce tag
 * AVANT d'executer les compagnons, alors meme que le top-level de projet.owl
 * (= le programme) s'execute en dernier. Reset avant chaque compile de
 * projet.owl. */
static char g_projet_boot_langue[32]  = "";
static bool g_projet_boot_langue_set  = false;

/*  — capture compile-time de l'instance de metadonnees Projet
 * (identifiant + champs constants). Materialisee TOT dans project_run (avant
 * l'execution des compagnons) pour que la cascade cross-fichier
 * MonApp..Champ voie les metadonnees, alors meme que le corps de projet.owl
 * (= le programme) s'execute en dernier.  : les champs du bloc sont
 * des constantes, lisibles sans executer le corps du programme.
 *
 * Cycle de vie parallele au boot langue : reset avant chaque compile de
 * projet.owl, capture pendant le parse du bloc PROPRIETES, lecture unique
 * dans project_run juste apres compile (projetScript rooté), ou les Value
 * capturees (ObjString de la table de constantes du chunk) sont vivantes. */
#define PROJET_META_MAX_FIELDS  8
#define PROJET_META_MAX_LANGUES 255
typedef struct { char name[64]; Value value; } ProjetMetaField;
static char  g_projet_meta_ident[128] = "";
static bool  g_projet_meta_set        = false;
static ProjetMetaField g_projet_meta_fields[PROJET_META_MAX_FIELDS];
static int   g_projet_meta_field_count = 0;
static bool  g_projet_meta_has_langues = false;
static char  g_projet_meta_langues_field[64] = "";
static Value g_projet_meta_langues[PROJET_META_MAX_LANGUES];
static int   g_projet_meta_langues_count = 0;

/*  — capture compile-time du champ FormatNombre du bloc Projet.
 * Meme cycle de vie que les autres metas (reset par
 * compiler_projet_boot_langue_reset). `set` = le projet a declare FormatNombre ;
 * les scalaires sont stockes deja resolus vers le canon (EN->FR). Sert a la
 * fois a la materialisation precoce de l'objet MonApp..FormatNombre et au repli
 * runtime des champs numeriques (compiler_projet_format_nombre). */
static bool g_projet_fnb_set          = false;
static int  g_projet_fnb_chiffres     = 0;   /* OWL_FNB_AUTO si non pose */
static char g_projet_fnb_sep_decimal[8]  = "";
static char g_projet_fnb_sep_milliers[8] = "";

/*  — capture compile-time du champ FormatMonétaire du bloc Projet.
 * Miroir strict de g_projet_fnb_* : `set` = le projet a declare FormatMonétaire ;
 * scalaires resolus vers le canon (EN->FR). Sert a la materialisation precoce de
 * MonApp..FormatMonétaire et au repli runtime des champs monetaires
 * (compiler_projet_format_monetaire). */
static bool g_projet_fmn_set          = false;
static char g_projet_fmn_symbole[16]      = "";
static int  g_projet_fmn_position         = 0;   /* OWL_POSSYM_APRES si non pose */
static char g_projet_fmn_sep_decimal[8]   = "";
static char g_projet_fmn_sep_milliers[8]  = "";
static int  g_projet_fmn_chiffres         = 2;   /* precision monetaire */
static int  g_projet_fmn_negatif          = 0;   /* OWL_FMN_MOINS si non pose */

/*  — declarations de variables GLOBAL du corps du bloc Projet, captees
 * au parse pour une materialisation precoce (Phase 1 de project_run). Un
 * compagnon lance avant le corps de projet.owl (Phase 2.c) doit resoudre la
 * globale au runtime : on hisse la DECLARATION (nom + valeur zero du type),
 * l'init explicite (`= ...`) restant jouee par le corps. Meme cycle de vie que
 * les metas (reset par compiler_projet_boot_langue_reset). LOCAL est exclu a la
 * capture (confine au flux de demarrage). */
#define PROJET_GLOBALS_MAX 128
typedef struct { char name[128]; TokenType type; bool nullable; } ProjetGlobalDecl;
static ProjetGlobalDecl g_projet_globals[PROJET_GLOBALS_MAX];
static int   g_projet_globals_count = 0;

/*  — noms des fenetres DSL declarees du projet (kind SYM_WINDOW dans la
 * table de symboles cross-fichier), captures au compile pour la reflexion
 * runtime ElementsDe(enumFenetre). Rempli depuis le SymbolTable complet a chaque
 * compile_in_project(_split) — idempotent (meme table pour tous les fichiers
 * d'un projet). Reste vide en mode script (table sans fenetre). Remis a zero par
 * vm_init pour ne pas laisser de residu entre fichiers d'un `owl test` recursif. */
#define PROJET_WINDOWS_MAX 512
static char g_projet_windows[PROJET_WINDOWS_MAX][128];
static int  g_projet_window_count = 0;

/*  — tags canoniques deja vus dans le champ Langues courant, pour
 * detecter les doublons post-normalisation (constante+litteral ou repetition).
 * Reset au debut de projet_emit_langues_value. */
static char g_projet_langues_seen[PROJET_META_MAX_LANGUES][48];
static int  g_projet_langues_seen_count = 0;

void compiler_projet_boot_langue_reset(void) {
    g_projet_boot_langue[0] = '\0';
    g_projet_boot_langue_set = false;
    /* Reset du side-channel metadonnees (meme cycle de vie que boot langue). */
    g_projet_meta_ident[0]        = '\0';
    g_projet_meta_set             = false;
    g_projet_meta_field_count     = 0;
    g_projet_meta_has_langues     = false;
    g_projet_meta_langues_field[0] = '\0';
    g_projet_meta_langues_count   = 0;
    g_projet_globals_count        = 0;  /*  */
    /*  — reset capture FormatNombre. */
    g_projet_fnb_set          = false;
    g_projet_fnb_chiffres     = OWL_FNB_AUTO;
    g_projet_fnb_sep_decimal[0]  = '\0';
    g_projet_fnb_sep_milliers[0] = '\0';
    /*  — reset capture FormatMonétaire. */
    g_projet_fmn_set          = false;
    g_projet_fmn_symbole[0]      = '\0';
    g_projet_fmn_position     = OWL_POSSYM_APRES;
    g_projet_fmn_sep_decimal[0]  = '\0';
    g_projet_fmn_sep_milliers[0] = '\0';
    g_projet_fmn_chiffres     = 2;
    g_projet_fmn_negatif      = OWL_FMN_MOINS;
}

const char* compiler_projet_boot_langue(void) {
    return g_projet_boot_langue_set ? g_projet_boot_langue : NULL;
}

/*  — liste COMPLETE des tags BCP 47 declares dans le champ Langues,
 * capturee au compile (g_projet_meta_langues, meme cycle de vie que le boot
 * langue : reset par compiler_projet_boot_langue_reset, materialisee dans
 * project_run juste apres le compile ou les ObjString du chunk sont rootees).
 * _count = nombre de langues ; _tag(i) = chaine C du i-eme tag (ordre de
 * declaration, [0] = langue source), NULL hors plage. Symetrique de
 * compiler_projet_boot_langue (qui n'expose que la 1ere). */
int compiler_projet_boot_langue_count(void) {
    return g_projet_meta_langues_count;
}

const char* compiler_projet_boot_langue_tag(int index) {
    if (index < 0 || index >= g_projet_meta_langues_count) return NULL;
    Value v = g_projet_meta_langues[index];
    if (!IS_STRING(v)) return NULL;
    return AS_STRING(v)->chars;
}

/*  — lecture seule de l'identifiant du bloc Projet. Meme fenetre de
 * validite que la capture des metadonnees : posee au parse de projet.owl,
 * conservee jusqu'au prochain compile d'un projet.owl. */
const char* compiler_projet_ident(void) {
    if (!g_projet_meta_set || g_projet_meta_ident[0] == '\0') return NULL;
    return g_projet_meta_ident;
}

/*  — capture des fenetres declarees du projet depuis la table de
 * symboles cross-fichier. Reset + refill : la table passee est la meme pour
 * tous les fichiers d'un projet, l'appel est donc idempotent. */
void compiler_projet_windows_collect(const SymbolTable* symbols) {
    g_projet_window_count = 0;
    if (symbols == NULL) return;
    for (int i = 0; i < symbols->count; i++) {
        if (symbols->symbols[i].kind != SYM_WINDOW) continue;
        if (g_projet_window_count >= PROJET_WINDOWS_MAX) break;
        const char* n = symbols->symbols[i].name;
        int len = (int)strlen(n);
        if (len >= (int)sizeof(g_projet_windows[0])) len = (int)sizeof(g_projet_windows[0]) - 1;
        memcpy(g_projet_windows[g_projet_window_count], n, (size_t)len);
        g_projet_windows[g_projet_window_count][len] = '\0';
        g_projet_window_count++;
    }
}

void compiler_projet_windows_reset(void) {
    g_projet_window_count = 0;
}

int compiler_projet_window_count(void) {
    return g_projet_window_count;
}

const char* compiler_projet_window_name(int i) {
    if (i < 0 || i >= g_projet_window_count) return NULL;
    return g_projet_windows[i];
}

bool compiler_file_declares_collection(void) {
    return g_file_has_collection_block;
}

/*  — nom de l'INSTANCE de theme designee par le champ Theme du bloc
 * Projet (`Theme = ThemeDemo`, reference typee vers un bloc `est un Theme`).
 * Lu depuis la capture compile-time des metas projet (g_projet_meta_fields,
 * cle accent-strippee "Theme") : la voie de parse dediee y stocke le NOM de
 * l'instance sous forme de chaine. Le bloc Projet est compile en phase 1.a
 * AVANT tout compagnon, et g_projet_meta_fields n'est remis a zero qu'au
 * prochain compile de projet.owl : la capture reste donc disponible quand un
 * compagnon (le fichier declarant le bloc `est un Theme`) compile ensuite.
 * Retourne NULL si pas de projet / pas de champ Theme / valeur absente. */
const char* compiler_projet_designated_theme(void) {
    if (!g_projet_meta_set) return NULL;
    for (int i = 0; i < g_projet_meta_field_count; i++) {
        if (strcasecmp(g_projet_meta_fields[i].name, "Theme") == 0) {
            Value v = g_projet_meta_fields[i].value;
            if (IS_STRING(v)) return AS_CSTRING(v);
            return NULL;
        }
    }
    return NULL;
}

/*  — un nom de type strippe designe-t-il le type Theme ? (bilingue
 * Theme, accent-insensible). */
static bool type_name_is_theme(const char* type) {
    if (type == NULL) return false;
    char probe[16];
    int n = scanner_strip_accents(type, (int)strlen(type), probe, sizeof(probe));
    return n == 5 && strncasecmp(probe, "Theme", 5) == 0;
}

/*  — nom de l'instance Fenetre designee par le champ FenetreDemarrage
 * du bloc Projet (bilingue StartupWindow). La voie de parse dediee y stocke le
 * NOM de l'instance sous forme de chaine (cle accent-strippee, "FenetreDemarrage"
 * ou "StartupWindow" selon la forme ecrite). Meme cycle de vie que la
 * designation de theme : capture en phase 1.a, lisible ensuite par le lancement.
 * Retourne NULL si pas de projet / champ absent / valeur non-chaine. */
const char* compiler_projet_designated_startup_window(void) {
    if (!g_projet_meta_set) return NULL;
    for (int i = 0; i < g_projet_meta_field_count; i++) {
        const char* fname = g_projet_meta_fields[i].name;
        if (strcasecmp(fname, "FenetreDemarrage") == 0
            || strcasecmp(fname, "StartupWindow") == 0) {
            Value v = g_projet_meta_fields[i].value;
            if (IS_STRING(v)) return AS_CSTRING(v);
            return NULL;
        }
    }
    return NULL;
}

/*  — format de date par defaut du projet (champ FormatDate du bloc
 * `est un Projet`, bilingue DateFormat). Meme cycle de vie que la designation
 * de theme / fenetre : capture compile-time en phase 1.a, lisible ensuite par
 * le rendu des champs Date comme repli quand le champ ne porte pas de
 * MasqueAffichage. Retourne NULL si pas de projet / champ absent / valeur
 * non-chaine (le repli defaut en dur JJ/MM/AAAA reste alors le dernier recours
 * cote runtime). */
const char* compiler_projet_format_date(void) {
    if (!g_projet_meta_set) return NULL;
    for (int i = 0; i < g_projet_meta_field_count; i++) {
        const char* fname = g_projet_meta_fields[i].name;
        if (strcasecmp(fname, "FormatDate") == 0
            || strcasecmp(fname, "DateFormat") == 0) {
            Value v = g_projet_meta_fields[i].value;
            if (IS_STRING(v)) return AS_CSTRING(v);
            return NULL;
        }
    }
    return NULL;
}

/*  — format d'heure par defaut du projet (champ FormatHeure du bloc
 * `est un Projet`, bilingue TimeFormat). Miroir exact de compiler_projet_format_date :
 * capture compile-time en phase 1.a, lisible ensuite par le rendu des champs Heure
 * comme repli quand le champ ne porte pas de MasqueAffichage. Retourne NULL si pas
 * de projet / champ absent / valeur non-chaine (le repli defaut en dur HH:MI reste
 * alors le dernier recours cote runtime). */
const char* compiler_projet_format_heure(void) {
    if (!g_projet_meta_set) return NULL;
    for (int i = 0; i < g_projet_meta_field_count; i++) {
        const char* fname = g_projet_meta_fields[i].name;
        if (strcasecmp(fname, "FormatHeure") == 0
            || strcasecmp(fname, "TimeFormat") == 0) {
            Value v = g_projet_meta_fields[i].value;
            if (IS_STRING(v)) return AS_CSTRING(v);
            return NULL;
        }
    }
    return NULL;
}

/*  — format de duree par defaut du projet (champ FormatDurée du bloc
 * `est un Projet`, bilingue DurationFormat). Miroir exact de
 * compiler_projet_format_heure : capture compile-time en phase 1.a, lisible
 * ensuite par le rendu des champs Durée comme repli quand le champ ne porte pas
 * de MasqueAffichage. Retourne NULL si pas de projet / champ absent / valeur
 * non-chaine (le repli defaut en dur HH:MI:SS reste alors le dernier recours
 * cote runtime). */
const char* compiler_projet_format_duree(void) {
    if (!g_projet_meta_set) return NULL;
    for (int i = 0; i < g_projet_meta_field_count; i++) {
        const char* fname = g_projet_meta_fields[i].name;
        /* fname est stocke accent-strippe (cf. projet_meta_add_field) : on
         * compare donc a la forme ASCII "FormatDuree", pas "FormatDurée". */
        if (strcasecmp(fname, "FormatDuree") == 0
            || strcasecmp(fname, "DurationFormat") == 0) {
            Value v = g_projet_meta_fields[i].value;
            if (IS_STRING(v)) return AS_CSTRING(v);
            return NULL;
        }
    }
    return NULL;
}

/*  — config du champ FormatNombre du bloc Projet, capturee au compile
 * (g_projet_fnb_*). Repli des champs numeriques sans FormatNombre propre.
 * Retourne false + laisse `out` intact si le projet n'a pas declare FormatNombre
 * (le runtime substitue alors le defaut plat). */
bool compiler_projet_format_nombre(int* chiffres,
                                   char* sepDec, int sepDecCap,
                                   char* sepMil, int sepMilCap) {
    if (!g_projet_fnb_set) return false;
    if (chiffres != NULL) *chiffres = g_projet_fnb_chiffres;
    if (sepDec != NULL && sepDecCap > 0)
        snprintf(sepDec, (size_t)sepDecCap, "%s", g_projet_fnb_sep_decimal);
    if (sepMil != NULL && sepMilCap > 0)
        snprintf(sepMil, (size_t)sepMilCap, "%s", g_projet_fnb_sep_milliers);
    return true;
}

/*  — config du champ FormatMonétaire du bloc Projet, capturee au
 * compile (g_projet_fmn_*). Repli des champs monetaires sans FormatMonétaire
 * propre. Retourne false + laisse les `out` intacts si le projet n'a pas
 * declare FormatMonétaire (le runtime substitue alors le defaut plat). */
bool compiler_projet_format_monetaire(char* symbole, int symboleCap,
                                      int* position,
                                      char* sepDec, int sepDecCap,
                                      char* sepMil, int sepMilCap,
                                      int* chiffres,
                                      int* negatif) {
    if (!g_projet_fmn_set) return false;
    if (symbole != NULL && symboleCap > 0)
        snprintf(symbole, (size_t)symboleCap, "%s", g_projet_fmn_symbole);
    if (position != NULL) *position = g_projet_fmn_position;
    if (sepDec != NULL && sepDecCap > 0)
        snprintf(sepDec, (size_t)sepDecCap, "%s", g_projet_fmn_sep_decimal);
    if (sepMil != NULL && sepMilCap > 0)
        snprintf(sepMil, (size_t)sepMilCap, "%s", g_projet_fmn_sep_milliers);
    if (chiffres != NULL) *chiffres = g_projet_fmn_chiffres;
    if (negatif != NULL) *negatif = g_projet_fmn_negatif;
    return true;
}

/*  — le projet a-t-il active la propriete opt-in
 * ActiveAvertissementConventionDeNommage (bilingue
 * EnableNamingConventionWarning) a Vrai ?
 *
 * Lu depuis les SOURCES du prescan et non depuis la capture compile-time des
 * metas projet : comme pour project_designates_a_theme,
 * compiler_projet_* rend le defaut quand un fichier compile SEUL (--check,
 * buffer LSP) — le mono `owl --check FEN.owl` PRESCANNE projet.owl mais ne le
 * COMPILE pas, donc g_projet_meta_fields reste vide. Le prescan, lui, voit
 * projet.owl dans les deux contextes.
 *
 * Motif cherche : dans un fichier declarant `<X> est un Projet`, un champ
 * `ActiveAvertissementConventionDeNommage = Vrai` (bilingue
 * EnableNamingConventionWarning = True) a l'interieur du bloc. Le suivi de
 * profondeur ne sert qu'a delimiter le bloc Projet ; jeu d'ouvreurs calque sur
 * project_designates_a_theme. Faux / absent -> false. */
static bool compiler_projet_active_avertissement_nommage(void) {
    if (projectSymbols == NULL) return false;
    for (int k = 0; k < projectSymbols->sourceCount; k++) {
        const char* src = projectSymbols->sources[k].source;
        if (src == NULL) continue;
        Scanner s;
        scanner_init(&s, src);
        bool inProjet = false;
        int  depth = 0;
        Token prev2 = (Token){0};
        Token prev1 = (Token){0};
        for (;;) {
            Token tok = scanner_scan_token(&s);
            if (tok.type == TOKEN_EOF) break;
            if (tok.type == TOKEN_NEWLINE || tok.type == TOKEN_ERROR) continue;
            /* Copule EN `is a/an <Type>` : article absorbe sans pousser prev1. */
            if (prev1.type == TOKEN_EST
                && (tok.type == TOKEN_A
                    || (tok.type == TOKEN_IDENTIFIER && tok.length == 2
                        && strncasecmp(tok.start, "an", 2) == 0))) {
                continue;
            }
            if (!inProjet) {
                if (prev1.type == TOKEN_EST && tok.type == TOKEN_IDENTIFIER
                    && ((tok.length == 6
                            && strncasecmp(tok.start, "Projet", 6) == 0)
                     || (tok.length == 7
                            && strncasecmp(tok.start, "Project", 7) == 0))) {
                    inProjet = true;
                    depth = 0;
                }
            } else if (tok.type == TOKEN_FIN) {
                if (depth == 0) inProjet = false;  /* FIN du bloc Projet */
                else depth--;
            } else if (tok.type == TOKEN_AVEC) {
                depth++;
            } else if (prescan_token_in_depth_table(tok.type)) {
                if (local_scan_depth_delta(tok, &s) > 0) depth++;
            } else if (tok.type == TOKEN_VRAI
                       && prev1.type == TOKEN_EQUAL
                       && prev2.type == TOKEN_IDENTIFIER) {
                char probe[64];
                int n = scanner_strip_accents(prev2.start, prev2.length,
                                              probe, sizeof(probe));
                if ((n == 38
                        && strncasecmp(probe,
                               "ActiveAvertissementConventionDeNommage", 38) == 0)
                 || (n == 29
                        && strncasecmp(probe,
                               "EnableNamingConventionWarning", 29) == 0))
                    return true;
            }
            prev2 = prev1;
            prev1 = tok;
        }
    }
    return false;
}

/*  — un nom de type strippe designe-t-il le type Fenetre ? (bilingue
 * Fenetre / Window, accent-insensible). */
static bool type_name_is_window(const char* type) {
    if (type == NULL) return false;
    char probe[16];
    int n = scanner_strip_accents(type, (int)strlen(type), probe, sizeof(probe));
    if (n == 7 && strncasecmp(probe, "Fenetre", 7) == 0) return true;
    if (n == 6 && strncasecmp(probe, "Window", 6) == 0) return true;
    return false;
}

/*  — cherche dans les sources du projet (prescan) une declaration
 * top-level `<name> est un <Type>` et rend son type declare. Reutilise l'idiome
 * de scan cross-fichier de hydrate_globals_from_neighbors (projectSymbols->
 * sources). Sert a valider que la reference assignee a Projet..Theme designe
 * bien une instance de type Theme, et a nommer le type reel dans le message de
 * type-mismatch sinon. Retourne true + remplit outType si la declaration est
 * trouvee. */
static bool project_ident_declared_type(const char* name, int len,
                                        char* outType, int outSize) {
    if (projectSymbols == NULL || name == NULL || len <= 0 || outSize <= 0)
        return false;
    char wantCanon[128];
    int wantLen = scanner_strip_accents(name, len, wantCanon, sizeof(wantCanon));
    if (wantLen <= 0) return false;
    for (int k = 0; k < projectSymbols->sourceCount; k++) {
        const char* src = projectSymbols->sources[k].source;
        if (src == NULL) continue;
        Scanner s;
        scanner_init(&s, src);
        int depth = 0;
        Token prev2 = (Token){0};
        Token prev1 = (Token){0};
        for (;;) {
            Token tok = scanner_scan_token(&s);
            if (tok.type == TOKEN_EOF) break;
            if (tok.type == TOKEN_NEWLINE || tok.type == TOKEN_ERROR) continue;
            if (tok.type == TOKEN_FIN) {
                if (depth > 0) depth--;
                prev2 = prev1; prev1 = tok; continue;
            }
            /* Ouvrants lexicaux : source unique. Les formes sans FIN
             * rendent 0. AVEC reste local — hors table, discriminant de
             * position, que cette boucle ne suit pas. */
            if (prescan_token_in_depth_table(tok.type)) {
                if (local_scan_depth_delta(tok, &s) > 0) depth++;
                prev2 = prev1; prev1 = tok; continue;
            }
            if (tok.type == TOKEN_AVEC) {
                depth++;
                prev2 = prev1; prev1 = tok; continue;
            }
            /* Motif top-level `IDENT(name) EST IDENT(type)` : le scanner strippe
             * l'article un/une, le type suit donc directement EST. Le type peut
             * etre un IDENTIFIER (Theme, styleXxx...) ou un mot-cle de bloc :
             * `est une Fenetre` scanne Fenetre en TOKEN_FENETRE, on
             * l'accepte comme type et on copie son texte source (accent-strippe
             * ensuite par les tests de type appelants). */
            /*  — copule EN `is a/an <Type>` : l'article s'intercale
             * entre EST et le type. Le scanner mappe `a` sur TOKEN_A (borne de
             * plage, non-strippable) et laisse `an` en IDENT 2-char ; en FR il
             * strippe deja `un/une`. En position post-copule on absorbe cet
             * article comme filler (sans le pousser dans prev1/prev2), sinon le
             * motif `IDENT EST TYPE` ne matche jamais en EN (prev1 serait
             * l'article, pas EST). Miroir de consume_en_a_an_filler. */
            if (prev1.type == TOKEN_EST
                && (tok.type == TOKEN_A
                    || (tok.type == TOKEN_IDENTIFIER && tok.length == 2
                        && strncasecmp(tok.start, "an", 2) == 0))) {
                continue;
            }
            bool tokIsType = tok.type == TOKEN_IDENTIFIER
                          || tok.type == TOKEN_FENETRE;
            if (depth == 0 && tokIsType
                && prev1.type == TOKEN_EST && prev2.type == TOKEN_IDENTIFIER) {
                char haveCanon[128];
                int haveLen = scanner_strip_accents(prev2.start, prev2.length,
                                                    haveCanon, sizeof(haveCanon));
                if (haveLen == wantLen
                    && strncasecmp(haveCanon, wantCanon, wantLen) == 0) {
                    int n = tok.length < outSize - 1 ? tok.length : outSize - 1;
                    memcpy(outType, tok.start, (size_t)n);
                    outType[n] = '\0';
                    return true;
                }
            }
            prev2 = prev1; prev1 = tok;
        }
    }
    return false;
}

/*  — le projet designe-t-il UN theme, quel qu'il soit ?
 *
 * Lu depuis les SOURCES du prescan et non depuis la capture compile-time des
 * metas projet. Mesure : compiler_projet_designated_theme() rend NULL quand un
 * fichier est compile SEUL (--check, buffer LSP), y compris dans un projet qui
 * designe correctement son theme — s'y fier ferait crier l'avertissement
 * d'inertie sur tout projet valide pendant la frappe. Le prescan, lui, voit
 * projet.owl dans les deux contextes.
 *
 * Motif cherche : dans un fichier declarant `<X> est un Projet`, un champ
 * `Theme = ...` a l'interieur du bloc (bilingue, accent-insensible). Le suivi
 * de profondeur ne sert qu'a ne pas prendre pour une designation un `Theme =`
 * ecrit APRES le FIN du bloc Projet ; jeu d'ouvreurs calque sur
 * project_ident_declared_type, sortie sur EOF garantie. */
static bool project_designates_a_theme(void) {
    if (projectSymbols == NULL) return false;
    for (int k = 0; k < projectSymbols->sourceCount; k++) {
        const char* src = projectSymbols->sources[k].source;
        if (src == NULL) continue;
        Scanner s;
        scanner_init(&s, src);
        bool inProjet = false;
        int  depth = 0;
        Token prev1 = (Token){0};
        for (;;) {
            Token tok = scanner_scan_token(&s);
            if (tok.type == TOKEN_EOF) break;
            if (tok.type == TOKEN_NEWLINE || tok.type == TOKEN_ERROR) continue;
            /* Copule EN `is a/an <Type>` : l'article s'intercale entre EST et le
             * type. On l'absorbe sans le pousser dans prev1, sinon le motif
             * `EST Projet` ne matche jamais en anglais (miroir de
             * project_ident_declared_type). */
            if (prev1.type == TOKEN_EST
                && (tok.type == TOKEN_A
                    || (tok.type == TOKEN_IDENTIFIER && tok.length == 2
                        && strncasecmp(tok.start, "an", 2) == 0))) {
                continue;
            }
            if (!inProjet) {
                if (prev1.type == TOKEN_EST && tok.type == TOKEN_IDENTIFIER
                    && ((tok.length == 6
                            && strncasecmp(tok.start, "Projet", 6) == 0)
                     || (tok.length == 7
                            && strncasecmp(tok.start, "Project", 7) == 0))) {
                    inProjet = true;
                    depth = 0;
                }
            } else if (tok.type == TOKEN_FIN) {
                if (depth == 0) inProjet = false;  /* FIN du bloc Projet */
                else depth--;
            } else if (tok.type == TOKEN_AVEC) {
                depth++;
            } else if (prescan_token_in_depth_table(tok.type)) {
                /*  — source unique : les formes sans FIN rendent 0.
                 * FIN est deja traite par la branche precedente. */
                if (local_scan_depth_delta(tok, &s) > 0) depth++;
            } else if (tok.type == TOKEN_EQUAL
                       && prev1.type == TOKEN_IDENTIFIER) {
                char probe[16];
                int n = scanner_strip_accents(prev1.start, prev1.length,
                                              probe, sizeof(probe));
                if (n == 5 && strncasecmp(probe, "Theme", 5) == 0) return true;
            }
            prev1 = tok;
        }
    }
    return false;
}

/*  — un nom de type designe-t-il un type de style compose ? Les types
 * de style du catalogue UI ont un nom prefixe "style" (styleBouton, styleSaisie,
 * styleLibelle, ...). Compare en forme ASCII strippee (accent-insensible). */
static bool is_style_type_name(const char* t) {
    if (t == NULL || t[0] == '\0') return false;
    char probe[64];
    int n = scanner_strip_accents(t, (int)strlen(t), probe, sizeof(probe));
    if (n < 5) return false;
    return strncasecmp(probe, "style", 5) == 0;
}

/*  — le type est-il EXACTEMENT le base `Style` generique (strip ==
 * "style", 5 car) et non un genre type (styleConteneur, styleBouton...) ?
 * Le base Style reste la prop universelle (owl_ui_prop_is_universal("Style"))
 * et est accepte comme fallback partout : ne jamais le flaguer en genre
 * incompatible (design "Style non type = Fenetre only", tests curseur). */
static bool is_base_style_type_name(const char* t) {
    if (t == NULL || t[0] == '\0') return false;
    char probe[64];
    int n = scanner_strip_accents(t, (int)strlen(t), probe, sizeof(probe));
    return n == 5 && strncasecmp(probe, "style", 5) == 0;
}

/*  — deux noms de type de style designent-ils le meme genre ? Compare
 * en forme ASCII strippee, casse-insensible (styleLibellé == styleLibelle). */
static bool style_type_names_equal(const char* a, const char* b) {
    if (a == NULL || b == NULL) return false;
    char pa[64], pb[64];
    int na = scanner_strip_accents(a, (int)strlen(a), pa, sizeof(pa));
    int nb = scanner_strip_accents(b, (int)strlen(b), pb, sizeof(pb));
    if (na <= 0 || nb <= 0 || na != nb) return false;
    return strncasecmp(pa, pb, (size_t)na) == 0;
}

/*  — a partir de parser.current (positionne sur le debut de la RHS
 * d'une affectation `..Style = ...`), resout le TYPE de style effectif de la
 * valeur affectee et sa designation lisible. Deux formes reconnues :
 *   - `theme.<nom>` : type declare du style <nom> dans le bloc `est un Thème`
 *     (project_ident_declared_type, resolution cross-fichier depth-0) ;
 *   - `<IDENT>` nu (ex STY_x global) : resolve_var_struct_type (per-fichier)
 *     puis fallback cross-fichier project_ident_declared_type.
 * Ne consomme aucun token (snapshot/restore interne). Retourne true + remplit
 * outType (forme source du type de style) et outDesig si un type de style est
 * resolu ; false sinon (RHS non resoluble ou pas un style -> pas de rejet). */
static bool style_rhs_resolve_type(char* outType, int typeSize,
                                   char* outDesig, int desigSize) {
    if (typeSize <= 0 || desigSize <= 0) return false;
    outType[0] = '\0';
    outDesig[0] = '\0';
    if (!check(TOKEN_IDENTIFIER)) return false;
    Token head = parser.current;

    /* Forme `theme.<nom>` : namespace reserve suivi d'un point + nom de style. */
    if (is_theme_namespace_name(head.start, head.length)) {
        Scanner savedSc   = parser.scanner;
        Token   savedCur  = parser.current;
        Token   savedPrev = parser.previous;
        bool    savedNl   = crossedNewline;
        bool ok = false;
        advance_token();                 /* consume 'theme' */
        if (check(TOKEN_DOT)) {
            advance_token();             /* consume '.' */
            if (check(TOKEN_IDENTIFIER)) {
                Token nameTok = parser.current;
                char t[64];
                if (project_ident_declared_type(nameTok.start, nameTok.length,
                                                t, sizeof(t))
                    && is_style_type_name(t)) {
                    snprintf(outType, (size_t)typeSize, "%s", t);
                    snprintf(outDesig, (size_t)desigSize, "%.*s.%.*s",
                             head.length, head.start,
                             nameTok.length, nameTok.start);
                    ok = true;
                }
            }
        }
        parser.scanner = savedSc; parser.current = savedCur;
        parser.previous = savedPrev; crossedNewline = savedNl;
        return ok;
    }

    /* Forme identifiant nu (ex STY_x global). Doit etre isole : `STY_x..Champ`
     * est une cascade, pas une instance de style affectee telle quelle. */
    if (!current_identifier_is_isolated()) return false;
    const char* st = resolve_var_struct_type(head.start, head.length);
    char buf[64];
    if (st == NULL
        && project_ident_declared_type(head.start, head.length,
                                       buf, sizeof(buf))) {
        st = buf;
    }
    if (st == NULL || !is_style_type_name(st)) return false;
    snprintf(outType, (size_t)typeSize, "%s", st);
    snprintf(outDesig, (size_t)desigSize, "%.*s", head.length, head.start);
    return true;
}

/*  — la RHS est-elle un `theme.<nom>` dont le nom n'est declare nulle
 * part dans les sources du projet ? Sert a signaler la faute de frappe avant
 * l'execution (ou le nom non resolu produit une sentinelle qui, combinee a une
 * cascade `Style..`, fabriquait un graphe cyclique). Avertissement seulement :
 * la vue disponible ici est celle du prescan projet, qui ne dit rien de la
 * designation du theme — on ne signale donc que ce qu'on prouve, l'absence de
 * declaration. projectSymbols NULL (fichier hors projet, buffer isole) = muet.
 * Ne consomme aucun token (snapshot/restore interne). */
static bool style_rhs_theme_ref_undeclared(Token* outNameTok) {
    if (projectSymbols == NULL) return false;
    if (!check(TOKEN_IDENTIFIER)) return false;
    Token head = parser.current;
    if (!is_theme_namespace_name(head.start, head.length)) return false;

    Scanner savedSc   = parser.scanner;
    Token   savedCur  = parser.current;
    Token   savedPrev = parser.previous;
    bool    savedNl   = crossedNewline;
    bool undeclared = false;
    advance_token();                 /* consume 'theme' */
    if (check(TOKEN_DOT)) {
        advance_token();             /* consume '.' */
        if (check(TOKEN_IDENTIFIER)) {
            Token nameTok = parser.current;
            char t[64];
            if (!project_ident_declared_type(nameTok.start, nameTok.length,
                                             t, sizeof(t))) {
                *outNameTok = nameTok;
                undeclared = true;
            }
        }
    }
    parser.scanner = savedSc; parser.current = savedCur;
    parser.previous = savedPrev; crossedNewline = savedNl;
    return undeclared;
}

/*  — le bloc `<blockName> est un Theme` en cours de compilation est-il
 * celui designe par Projet..Theme ? Compare le nom du bloc a l'instance
 * designee (casse + accent-insensible, invariants 1 & 2). Sert de gate a la
 * registration des styles du bloc : seule l'instance designee alimente le
 * namespace `theme.X` — un bloc non designe est parse valide mais inerte
 * (inertness multi-fichier). */
static bool theme_block_is_designated(Token blockName) {
    const char* designated = compiler_projet_designated_theme();
    if (designated == NULL || designated[0] == '\0') return false;
    char blockCanon[128];
    char desCanon[128];
    int bn = scanner_strip_accents(blockName.start, blockName.length,
                                   blockCanon, sizeof(blockCanon));
    int dn = scanner_strip_accents(designated, (int)strlen(designated),
                                   desCanon, sizeof(desCanon));
    if (bn <= 0 || dn <= 0) return false;
    return bn == dn && strncasecmp(blockCanon, desCanon, bn) == 0;
}

/* Capture l'identifiant du bloc `<Ident> est un Projet` (nom canon du global
 * de metadonnees) au moment ou PROPRIETES est confirme pour un Projet. */
static void projet_meta_set_ident(Token nameTok) {
    int n = nameTok.length < (int)sizeof(g_projet_meta_ident) - 1
                ? nameTok.length : (int)sizeof(g_projet_meta_ident) - 1;
    memcpy(g_projet_meta_ident, nameTok.start, (size_t)n);
    g_projet_meta_ident[n] = '\0';
    g_projet_meta_set = true;
    g_projet_meta_field_count = 0;
    g_projet_meta_has_langues = false;
    g_projet_meta_langues_count = 0;
    /*  — reset la capture FormatNombre a CHAQUE bloc Projet parse (le
     * test runner ne passe pas par compiler_projet_boot_langue_reset). Sans ca,
     * un projet SANS FormatNombre heriterait de la capture du projet precedent
     * (fuite cross-projet, cf. les autres captures ci-dessus remises a zero
     * ici). g_projet_fnb_set n'est re-arme que si CE projet declare FormatNombre. */
    g_projet_fnb_set          = false;
    g_projet_fnb_chiffres     = OWL_FNB_AUTO;
    g_projet_fnb_sep_decimal[0]  = '\0';
    g_projet_fnb_sep_milliers[0] = '\0';
    /*  — reset la capture FormatMonétaire a CHAQUE bloc Projet parse
     * (meme raison que FormatNombre : eviter la fuite cross-projet). */
    g_projet_fmn_set          = false;
    g_projet_fmn_symbole[0]      = '\0';
    g_projet_fmn_position     = OWL_POSSYM_APRES;
    g_projet_fmn_sep_decimal[0]  = '\0';
    g_projet_fmn_sep_milliers[0] = '\0';
    g_projet_fmn_chiffres     = 2;
    g_projet_fmn_negatif      = OWL_FMN_MOINS;
}

/* Capture un champ scalaire constant (Description/Auteur/Licence/Theme). value
 * pointe une constante du chunk courant (vivante tant que projetScript est
 * rooté au moment de la materialisation dans project_run). Le nom du champ est
 * stocké accent-strippé (canon ASCII du template, ex "Theme" pour "Thème") :
 * la materialisation ecrit alors sous la meme cle que le defaut du template,
 * sinon un champ accentue creerait une cle parallele et le read `..Theme`
 * verrait le defaut vide au lieu de la valeur declaree. */
static void projet_meta_add_field(Token fieldTok, Value value) {
    if (!g_projet_meta_set) return;
    if (g_projet_meta_field_count >= PROJET_META_MAX_FIELDS) return;
    ProjetMetaField* f = &g_projet_meta_fields[g_projet_meta_field_count++];
    int n = scanner_strip_accents(fieldTok.start, fieldTok.length,
                                  f->name, (int)sizeof(f->name));
    if (n <= 0 || n >= (int)sizeof(f->name)) {
        /* Fallback : copie verbatim tronquee si le strip echoue. */
        n = fieldTok.length < (int)sizeof(f->name) - 1
                ? fieldTok.length : (int)sizeof(f->name) - 1;
        memcpy(f->name, fieldTok.start, (size_t)n);
    }
    f->name[n] = '\0';
    f->value = value;
}

/* Capture le nom du champ Langues (tel qu'ecrit : Langues / Languages). */
static void projet_meta_set_langues_field(Token fieldTok) {
    if (!g_projet_meta_set) return;
    int n = fieldTok.length < (int)sizeof(g_projet_meta_langues_field) - 1
                ? fieldTok.length : (int)sizeof(g_projet_meta_langues_field) - 1;
    memcpy(g_projet_meta_langues_field, fieldTok.start, (size_t)n);
    g_projet_meta_langues_field[n] = '\0';
    g_projet_meta_has_langues = true;
}

/* Capture un tag de langue (constante registre, rootée en permanence). */
static void projet_meta_add_langue(Value tag) {
    if (!g_projet_meta_set) return;
    if (g_projet_meta_langues_count >= PROJET_META_MAX_LANGUES) return;
    g_projet_meta_langues[g_projet_meta_langues_count++] = tag;
}

/* Materialise le global de metadonnees Projet depuis la capture compile-time.
 * Appelee par project_run TOT (avant les compagnons) quand projet.owl a ete
 * compile. No-op si aucun bloc Projet capture. Reproduit la forme du template
 * (Description/Auteur/Licence chaine "" par defaut + Langues tableau) pour que
 * l'instance precoce ait la meme surface que celle posee par le corps.
 *
 * GC : inst est rooté (vm_push) pendant toutes les sous-allocs de
 * champs ; les helpers inst_field_set_* / obj_globals_set / obj_array_push
 * sont canon (push/pop internes). Les Value capturees sont vivantes via le
 * chunk de projetScript, rooté par project_run au moment de l'appel. */
void compiler_projet_meta_materialize(void) {
    if (!g_projet_meta_set || g_projet_meta_ident[0] == '\0') return;

    ObjString* tname = obj_copy_string("Projet", 6);
    vm_push(OBJ_VAL(tname));
    ObjInstance* inst = obj_new_instance(tname);
    vm_pop();  /* tname : desormais reference par inst->structName */
    vm_push(OBJ_VAL(inst));

    /* Defauts catalogue (champs chaine optionnels), ecrases ensuite par les
     * valeurs declarees. Aligne sur build_Projet_template. */
    inst_field_set_str(inst, "Description",      "");
    inst_field_set_str(inst, "Auteur",           "");
    inst_field_set_str(inst, "Licence",          "");
    inst_field_set_str(inst, "Theme",            "");
    inst_field_set_str(inst, "FenetreDemarrage", "");
    inst_field_set_str(inst, "FormatDate",       "");
    inst_field_set_str(inst, "FormatHeure",      "");
    inst_field_set_str(inst, "FormatDuree",      "");

    for (int i = 0; i < g_projet_meta_field_count; i++) {
        inst_field_set_value(inst, g_projet_meta_fields[i].name,
                             g_projet_meta_fields[i].value);
    }

    /*  — FormatNombre TOUJOURS materialise comme OBJET (jamais nil,
     * jamais ""). Configure inline sinon defaut plat (ChiffresAprèsVirgule =
     * fnbAuto). structName "FormatNombre" -> les reads `..FormatNombre..X`
     * (FR/EN) resolvent via le canon du registre. */
    {
        ObjString* fnbName = obj_copy_string("FormatNombre", 12);
        vm_push(OBJ_VAL(fnbName));
        ObjInstance* fnb = obj_new_instance(fnbName);
        vm_pop();  /* fnbName : desormais reference par fnb->structName */
        vm_push(OBJ_VAL(fnb));
        inst_field_set_str(fnb, "SeparateurDecimal",
                           g_projet_fnb_set ? g_projet_fnb_sep_decimal : "");
        inst_field_set_str(fnb, "SeparateurMilliers",
                           g_projet_fnb_set ? g_projet_fnb_sep_milliers : "");
        inst_field_set_int(fnb, "ChiffresApresVirgule",
                           g_projet_fnb_set ? g_projet_fnb_chiffres : OWL_FNB_AUTO);
        inst_field_set_value(inst, "FormatNombre", OBJ_VAL(fnb));
        vm_pop();  /* fnb */
    }

    /*  — FormatMonétaire TOUJOURS materialise comme OBJET (jamais nil).
     * Configure inline sinon defaut plat (Symbole "", 2 decimales, signe '-'). */
    {
        ObjString* fmnName = obj_copy_string("FormatMon\xc3\xa9taire", 16);
        vm_push(OBJ_VAL(fmnName));
        ObjInstance* fmn = obj_new_instance(fmnName);
        vm_pop();  /* fmnName : desormais reference par fmn->structName */
        vm_push(OBJ_VAL(fmn));
        inst_field_set_str(fmn, "Symbole",
                           g_projet_fmn_set ? g_projet_fmn_symbole : "");
        inst_field_set_int(fmn, "PositionSymbole",
                           g_projet_fmn_set ? g_projet_fmn_position : OWL_POSSYM_APRES);
        inst_field_set_str(fmn, "SeparateurDecimal",
                           g_projet_fmn_set ? g_projet_fmn_sep_decimal : "");
        inst_field_set_str(fmn, "SeparateurMilliers",
                           g_projet_fmn_set ? g_projet_fmn_sep_milliers : "");
        inst_field_set_int(fmn, "ChiffresApresVirgule",
                           g_projet_fmn_set ? g_projet_fmn_chiffres : 2);
        inst_field_set_int(fmn, "FormatNegatif",
                           g_projet_fmn_set ? g_projet_fmn_negatif : OWL_FMN_MOINS);
        inst_field_set_value(inst, "FormatMonetaire", OBJ_VAL(fmn));
        vm_pop();  /* fmn */
    }

    ObjArray* langues = obj_new_array();
    vm_push(OBJ_VAL(langues));
    for (int i = 0; i < g_projet_meta_langues_count; i++) {
        obj_array_push(langues, g_projet_meta_langues[i]);
    }
    const char* lf = g_projet_meta_langues_field[0]
                        ? g_projet_meta_langues_field : "Langues";
    inst_field_set_value(inst, lf, OBJ_VAL(langues));
    vm_pop();  /* langues */

    obj_globals_set(g_projet_meta_ident, OBJ_VAL(inst));
    vm_pop();  /* inst */
}

/*  — capture une variable GLOBAL declaree au top-level du corps du bloc
 * Projet (nom tel qu'ecrit + type + nullabilite). Appelee par
 * var_declaration_after_est quand g_in_projet_body et mode GLOBAL. Le nom est
 * stocke verbatim (la resolution runtime est casse/accent-insensible via le
 * canon index de vm.globals, comme pour l'identifiant du meta-global). */
static void projet_global_capture(Token nameTok, TokenType declaredType,
                                  bool isNullable) {
    if (g_projet_globals_count >= PROJET_GLOBALS_MAX) return;
    ProjetGlobalDecl* g = &g_projet_globals[g_projet_globals_count++];
    int n = nameTok.length < (int)sizeof(g->name) - 1
                ? nameTok.length : (int)sizeof(g->name) - 1;
    memcpy(g->name, nameTok.start, (size_t)n);
    g->name[n] = '\0';
    g->type     = declaredType;
    g->nullable = isNullable;
}

/*  — materialise les globales de projet capturees avec la valeur zero
 * de leur type, TOT dans project_run (Phase 1, avant les compagnons). Un
 * compagnon lance avant le corps de projet.owl resout ainsi la globale ; son
 * init explicite est ecrite plus tard, au corps (Phase 2.c). Les valeurs zero
 * scalaires reproduisent celles emises par var_declaration_after_est pour un
 * type sans initialiseur ; les types composes (structure/classe/tableau) et les
 * types nullable prennent Null (leur construction reelle vit dans le corps).
 *
 * GC : chaque Value zero est passee par valeur a obj_globals_set qui
 * la push (si Obj) avant toute alloc interne ; aucune alloc OWL entre la
 * creation d'un zero chaine et son enregistrement. */
void compiler_projet_globals_materialize(void) {
    for (int i = 0; i < g_projet_globals_count; i++) {
        const ProjetGlobalDecl* g = &g_projet_globals[i];
        Value zero;
        if (g->nullable) {
            zero = NIL_VAL;
        } else if (g->type == TOKEN_CHAINE) {
            zero = OBJ_VAL(obj_copy_string("", 0));
        } else if (g->type == TOKEN_ENTIER) {
            zero = INTEGER_VAL(0);
        } else if (g->type == TOKEN_REEL) {
            zero = REAL_VAL(0.0);
        } else if (g->type == TOKEN_BOOLEEN) {
            zero = BOOL_VAL(false);
        } else {
            zero = NIL_VAL;
        }
        obj_globals_set(g->name, zero);
    }
}

/*  — champ Langues du type Projet (bloc PROPRIETES de projet.owl).
 * Emet la valeur d'UN element langue : une constante langueXxx officielle,
 * dont le tag BCP 47 (valeur registre) est pose sur la pile. Laisse toujours
 * exactement une valeur sur la pile (le tag, ou NIL sur erreur) pour equilibrer
 * l'OP_ARRAY_PACK qui suit. Retourne false + emet une erreur si l'element n'est
 * pas une langue officielle (langue inconnue) ou pas une constante (appel de
 * fonction / variable => metadonnee non constante, ). */
/*  — accepte un tag langue (constante officielle OU litteral chaine),
 * le normalise en forme canonique BCP 47, detecte les doublons
 * post-normalisation, memorise la 1ere langue (source) et emet le tag canonique.
 * `tok` designe l'element dans la source (pour pointer les erreurs). Laisse
 * toujours exactement une valeur sur la pile pour equilibrer l'OP_ARRAY_PACK. */
static bool projet_accept_langue_tag(const char* rawTag, Token tok) {
    char canon[48];
    owl_bcp47_canon(rawTag, canon, sizeof(canon));
    const char* tag = (canon[0] != '\0') ? canon : rawTag;

    /* Doublon post-normalisation (constante+litteral ou repetition). */
    for (int i = 0; i < g_projet_langues_seen_count; i++) {
        if (strcmp(g_projet_langues_seen[i], tag) == 0) {
            owl_emit_error_at(&tok, E_SEM_PROJET_LANGUES_DOUBLON,
                              "langue", tag, NULL);
            emit_constant(NIL_VAL);  /* equilibre OP_ARRAY_PACK */
            return false;
        }
    }
    if (g_projet_langues_seen_count < PROJET_META_MAX_LANGUES) {
        strncpy(g_projet_langues_seen[g_projet_langues_seen_count], tag,
                sizeof(g_projet_langues_seen[0]) - 1);
        g_projet_langues_seen[g_projet_langues_seen_count]
            [sizeof(g_projet_langues_seen[0]) - 1] = '\0';
        g_projet_langues_seen_count++;
    }

    /*  — memorise la 1ere langue (langue source) pour le boot i18n
     * compile-time, avant emission bytecode. */
    if (!g_projet_boot_langue_set) {
        strncpy(g_projet_boot_langue, tag, sizeof(g_projet_boot_langue) - 1);
        g_projet_boot_langue[sizeof(g_projet_boot_langue) - 1] = '\0';
        g_projet_boot_langue_set = true;
    }

    /* Emet le tag canonique (ObjString ancre dans les constantes du chunk,
     * rootees) + capture pour la materialisation precoce du global de
     * metadonnees (champ Langues de l'instance). */
    ObjString* tagStr = obj_copy_string(tag, (int)strlen(tag));
    Value tagVal = OBJ_VAL(tagStr);
    projet_meta_add_langue(tagVal);
    emit_constant(tagVal);
    return true;
}

static bool projet_emit_langue_element(Token fieldTok) {
    if (check(TOKEN_IDENTIFIER)) {
        Token idTok = parser.current;
        Scanner sv  = parser.scanner;
        Token curSv = parser.current, prevSv = parser.previous;
        bool  nlSv  = crossedNewline;
        advance_token();                    /* consume identifier */
        if (!check(TOKEN_LEFT_PAREN)) {
            /* Identifiant nu : soit une constante langue officielle (accepte,
             * normalise), soit un symbole inconnu -> LANGUE_INCONNUE. */
            char buf[128];
            int n = idTok.length < (int)sizeof(buf) - 1
                        ? idTok.length : (int)sizeof(buf) - 1;
            memcpy(buf, idTok.start, (size_t)n);
            buf[n] = '\0';
            const OwlConstDef* cst = owl_registry_const_find_bilingual(buf);
            const char* tag = cst
                ? owl_i18n_lookup_tag_by_constant_name(cst->name) : NULL;
            if (tag != NULL) {
                return projet_accept_langue_tag(tag, idTok);
            }
            char nameBuf[128];
            snprintf(nameBuf, sizeof(nameBuf), "%.*s", idTok.length, idTok.start);
            owl_emit_error_at(&idTok, E_SEM_PROJET_LANGUE_INCONNUE,
                              "langue", nameBuf, NULL);
            emit_constant(NIL_VAL);
            return false;
        }
        /* Identifiant suivi de '(' : appel => non constant. Rollback. */
        parser.scanner  = sv;
        parser.current  = curSv;
        parser.previous = prevSv;
        crossedNewline  = nlSv;
    }
    /* RHS non-identifiant. Deux cas a distinguer :
     *  - un litteral CHAINE non-vide : tag BCP 47 valide (custom inclus, )
     *    -> accepte + normalise. Un litteral non-chaine (nombre, booleen) ou une
     *    chaine vide n'est pas une langue -> LANGUE_INCONNUE.
     *  - une expression NON constante (appel de fonction, concat non foldee,
     *    variable...) : metadonnee non constante -> NOT_CONSTANT. */
    Token   litTok = parser.current;
    Scanner vScan  = parser.scanner;
    Token   vCur   = parser.current, vPrev = parser.previous;
    bool    vNl    = crossedNewline;
    Value   constVal;
    if (window_try_parse_const_literal(&constVal)) {
        if (IS_STRING(constVal) && AS_STRING(constVal)->length > 0) {
            return projet_accept_langue_tag(AS_STRING(constVal)->chars, litTok);
        }
        char langBuf[128];
        int ln = litTok.length < (int)sizeof(langBuf) - 1
                     ? litTok.length : (int)sizeof(langBuf) - 1;
        memcpy(langBuf, litTok.start, (size_t)ln);
        langBuf[ln] = '\0';
        owl_emit_error_at(&litTok, E_SEM_PROJET_LANGUE_INCONNUE,
                          "langue", langBuf, NULL);
        emit_constant(NIL_VAL);  /* equilibre OP_ARRAY_PACK */
        return false;
    }
    /* Rollback (const-folder a pu consommer partiellement) puis rejet. */
    parser.scanner  = vScan;
    parser.current  = vCur;
    parser.previous = vPrev;
    crossedNewline  = vNl;
    /* RHS non-constante : metadonnee non constante.
     * condition_expression consomme la RHS et laisse une valeur sur la pile. */
    char nameBuf[128];
    snprintf(nameBuf, sizeof(nameBuf), "%.*s", fieldTok.length, fieldTok.start);
    owl_emit_error_at(&fieldTok, E_SEM_PROJET_METADATA_NOT_CONSTANT,
                      "name", nameBuf, NULL);
    condition_expression();
    return false;
}

/*  — parse la RHS du champ Langues et emet un tableau runtime de tags
 * BCP 47 (OP_ARRAY_PACK).  (break net) : seule forme acceptee =
 * litteral liste [langueX, ...], y compris pour une seule langue. La forme
 * scalaire nue (raccourci ) est desormais rejetee. Liste vide =>
 * erreur (au moins une langue). Laisse un tableau sur la pile pour OP_STRUCT_SET. */
static void projet_emit_langues_value(Token fieldTok) {
    projet_meta_set_langues_field(fieldTok);  /*  — capture precoce */
    g_projet_langues_seen_count = 0;          /*  — reset anti-doublon */
    int count = 0;
    if (check(TOKEN_LEFT_BRACKET)) {
        advance_token();                    /* consume '[' */
        if (check(TOKEN_RIGHT_BRACKET)) {
            owl_emit_error_current(E_SEM_PROJET_LANGUES_VIDE);
        }
        while (!check(TOKEN_RIGHT_BRACKET) && !check(TOKEN_EOF)) {
            projet_emit_langue_element(fieldTok);
            count++;
            if (count >= 255) break;
            if (check(TOKEN_COMMA)) { advance_token(); continue; }
            break;
        }
        consume(TOKEN_RIGHT_BRACKET, E_SYNTAX_EXP_RBRACKET_LANGUES);
    } else {
        /*  — plus de raccourci scalaire. Un identifiant nu (l'ancienne
         * forme scalaire, valide ou non) est rejete avec un message qui montre
         * la forme liste attendue. Les autres RHS non-liste (appel de fonction,
         * litteral) restent traitees par projet_emit_langue_element : elles
         * tombent sur "metadonnee non constante", inchange. */
        bool bareIdent = false;
        if (check(TOKEN_IDENTIFIER)) {
            Scanner sv  = parser.scanner;
            Token curSv = parser.current, prevSv = parser.previous;
            bool  nlSv  = crossedNewline;
            advance_token();                /* peek au-dela de l'identifiant */
            bareIdent = !check(TOKEN_LEFT_PAREN);
            parser.scanner  = sv;           /* rollback */
            parser.current  = curSv;
            parser.previous = prevSv;
            crossedNewline  = nlSv;
        }
        if (bareIdent) {
            owl_emit_error_at(&fieldTok, E_SEM_PROJET_LANGUES_SCALAIRE, NULL);
            advance_token();                /* consomme l'identifiant nu */
            emit_constant(NIL_VAL);         /* equilibre OP_ARRAY_PACK */
        } else {
            projet_emit_langue_element(fieldTok);
        }
        count = 1;
    }
    emit_bytes(OP_ARRAY_PACK, (uint8_t)count);
}

/*  — parse la RHS du champ Theme du bloc Projet. Le theme actif est
 * designe par une REFERENCE TYPEE vers une instance `est un Theme` declaree
 * dans un compagnon (plus par un chemin de fichier). Voie de parse dediee : le
 * const-folder generique rejetterait une reference de globale ("metadonnee non
 * constante"). On capte l'identifiant, on verifie via les sources du projet
 * (prescan) qu'il designe bien une instance de type Theme, et on stocke son NOM
 * comme designation du theme actif (lu par compiler_projet_designated_theme,
 * gate du namespace theme.X). Rejets compile-time (break-net) :
 *   - l'ancienne forme chaine `Theme = "..."` (ou tout autre litteral) ;
 *   - une reference dont le type declare n'est pas Theme (ex un styleXxx).
 * Laisse exactement une valeur sur la pile pour l'OP_STRUCT_SET du caller. */
static void projet_emit_theme_value(Token fieldTok) {
    if (check(TOKEN_IDENTIFIER)) {
        Token idTok = parser.current;
        char declType[128];
        bool found = project_ident_declared_type(idTok.start, idTok.length,
                                                 declType, sizeof(declType));
        if (found && type_name_is_theme(declType)) {
            advance_token();  /* consume l'identifiant de l'instance */
            /* Stocke le nom de l'instance comme designation (capture precoce +
             * runtime). Interne (obj_copy_string) : emit_constant l'ancre dans
             * les constantes du chunk (rootees), la capture meta pointe le meme
             * objet. */
            ObjString* nameStr = obj_copy_string(idTok.start, idTok.length);
            Value nameVal = OBJ_VAL(nameStr);
            emit_constant(nameVal);
            projet_meta_add_field(fieldTok, nameVal);
            return;
        }
        /* Reference qui ne designe pas un Theme (type incompatible ou instance
         * introuvable) -> type-mismatch. got = type reel si connu, sinon le nom
         * de l'identifiant. */
        char gotBuf[128];
        if (found) {
            snprintf(gotBuf, sizeof(gotBuf), "%s", declType);
        } else {
            snprintf(gotBuf, sizeof(gotBuf), "%.*s", idTok.length, idTok.start);
        }
        owl_emit_error_at(&idTok, E_SEM_DSL_OBJECT_PROP_TYPE_MISMATCH,
                          "target", "Th\xc3\xa8me",
                          "got", gotBuf,
                          "expected", "Th\xc3\xa8me",
                          NULL);
        condition_expression();  /* consomme la RHS + equilibre la pile */
        return;
    }
    /* RHS non-identifiant : type-mismatch. Break-net : la forme chaine
     * `Theme = "theme.owl"` est desormais refusee. */
    const char* got = "valeur";
    if (check(TOKEN_STRING))                              got = "cha\xc3\xaene";
    else if (check(TOKEN_INTEGER) || check(TOKEN_REAL))   got = "num\xc3\xa9rique";
    owl_emit_error_at(&parser.current, E_SEM_DSL_OBJECT_PROP_TYPE_MISMATCH,
                      "target", "Th\xc3\xa8me",
                      "got", got,
                      "expected", "Th\xc3\xa8me",
                      NULL);
    condition_expression();  /* consomme la RHS + equilibre la pile */
}

/*  — parse la RHS du champ FenetreDemarrage / StartupWindow du bloc
 * Projet. Meme famille que Theme (voie de parse dediee) : la fenetre de
 * demarrage est designee par une REFERENCE TYPEE (sans guillemets) vers une
 * instance `est une Fenetre` declaree dans un compagnon. On capte
 * l'identifiant, on verifie via le prescan qu'il designe bien une Fenetre, et
 * on stocke son NOM comme designation (lu au lancement projet pour l'ouvrir).
 * Rejets compile-time (break-net) :
 *   - la forme chaine `FenetreDemarrage = "..."` (ou tout autre litteral) ;
 *   - une reference dont le type declare n'est pas Fenetre.
 * Laisse exactement une valeur sur la pile pour l'OP_STRUCT_SET du caller. */
static void projet_emit_fenetre_demarrage_value(Token fieldTok) {
    if (check(TOKEN_IDENTIFIER)) {
        Token idTok = parser.current;
        char declType[128];
        bool found = project_ident_declared_type(idTok.start, idTok.length,
                                                 declType, sizeof(declType));
        if (found && type_name_is_window(declType)) {
            advance_token();  /* consume l'identifiant de l'instance */
            ObjString* nameStr = obj_copy_string(idTok.start, idTok.length);
            Value nameVal = OBJ_VAL(nameStr);
            emit_constant(nameVal);
            projet_meta_add_field(fieldTok, nameVal);
            return;
        }
        char gotBuf[128];
        if (found) {
            snprintf(gotBuf, sizeof(gotBuf), "%s", declType);
        } else {
            snprintf(gotBuf, sizeof(gotBuf), "%.*s", idTok.length, idTok.start);
        }
        owl_emit_error_at(&idTok, E_SEM_DSL_OBJECT_PROP_TYPE_MISMATCH,
                          "target", "Fen\xc3\xaatreD\xc3\xa9marrage",
                          "got", gotBuf,
                          "expected", "Fen\xc3\xaatre",
                          NULL);
        condition_expression();  /* consomme la RHS + equilibre la pile */
        return;
    }
    /* RHS non-identifiant : type-mismatch. Break-net : la forme chaine
     * `FenetreDemarrage = "FEN_X.owl"` est refusee. */
    const char* got = "valeur";
    if (check(TOKEN_STRING))                              got = "cha\xc3\xaene";
    else if (check(TOKEN_INTEGER) || check(TOKEN_REAL))   got = "num\xc3\xa9rique";
    owl_emit_error_at(&parser.current, E_SEM_DSL_OBJECT_PROP_TYPE_MISMATCH,
                      "target", "Fen\xc3\xaatreD\xc3\xa9marrage",
                      "got", got,
                      "expected", "Fen\xc3\xaatre",
                      NULL);
    condition_expression();  /* consomme la RHS + equilibre la pile */
}

/*  — controle de coherence des separateurs d'un FormatNombre.
 * Retourne le separateur fautif (pointeur vers sepMil ou sepDec) si la config
 * est invalide, NULL si valide. Rejets : (1) un separateur contient un chiffre
 * (indistinguable des chiffres du nombre) ; (2) milliers == decimal, les deux
 * non vides (le de-formatage ne saurait plus les distinguer). Partage avec le
 * repli runtime cote stdlib_ui.c (meme logique dupliquee : TU separes). */
static const char* fnb_sep_conflict(const char* sepMil, const char* sepDec) {
    for (const char* s = sepMil; s != NULL && *s != '\0'; s++)
        if (*s >= '0' && *s <= '9') return sepMil;
    for (const char* s = sepDec; s != NULL && *s != '\0'; s++)
        if (*s >= '0' && *s <= '9') return sepDec;
    if (sepMil != NULL && sepDec != NULL && sepMil[0] != '\0' && sepDec[0] != '\0'
        && strcmp(sepMil, sepDec) == 0)
        return sepMil;
    return NULL;
}

/*  — controle de coherence d'une config FormatMonetaire. Retourne
 * l'element fautif (separateur ou symbole) si la config est absurde, NULL
 * sinon. Etend fnb_sep_conflict au symbole : (1)(2) un separateur qui contient
 * un chiffre ; (3) milliers == decimal ; (4) le symbole contient un chiffre
 * (indistinguable au de-formatage) ; (5) le symbole egale un separateur (ambigu
 * au reparse). Chaines comparees non vides uniquement. */
static const char* fmn_config_conflict(const char* symbole, const char* sepMil,
                                       const char* sepDec) {
    const char* badSep = fnb_sep_conflict(sepMil, sepDec);
    if (badSep != NULL) return badSep;
    for (const char* s = symbole; s != NULL && *s != '\0'; s++)
        if (*s >= '0' && *s <= '9') return symbole;
    if (symbole != NULL && symbole[0] != '\0') {
        if (sepMil != NULL && sepMil[0] != '\0' && strcmp(symbole, sepMil) == 0)
            return symbole;
        if (sepDec != NULL && sepDec[0] != '\0' && strcmp(symbole, sepDec) == 0)
            return symbole;
    }
    return NULL;
}

/*  — parse la RHS du champ FormatNombre du bloc Projet : un litteral
 * composite inline `{ SéparateurMilliers = " ", ... }`. Emet le bytecode de
 * construction (__StructClone(FormatNombre) + STRUCT_SET par champ) pour le
 * STRUCT_SET du caller, ET capture les scalaires (g_projet_fnb_*, resolus
 * EN->FR) pour la materialisation precoce de MonApp..FormatNombre + le repli
 * runtime des champs numeriques. Laisse exactement une valeur sur la pile. */
static void projet_emit_format_nombre_value(Token fieldTok) {
    /* Une seule instance FormatNombre par projet : reset la capture. */
    g_projet_fnb_set             = true;
    g_projet_fnb_chiffres        = OWL_FNB_AUTO;
    g_projet_fnb_sep_decimal[0]  = '\0';
    g_projet_fnb_sep_milliers[0] = '\0';

    /* __StructClone(FormatNombre) -> instance fresh (defauts du template). */
    Token cloneName; cloneName.start = "__StructClone"; cloneName.length = 13;
    ConstIdx cloneIdx = identifier_constant(&cloneName);
    emit_const_op(OP_GET_GLOBAL, cloneIdx);
    Token typeTok; typeTok.start = "FormatNombre"; typeTok.length = 12;
    ConstIdx typeIdx = identifier_constant(&typeTok);
    emit_get_type_global("FormatNombre", 12, typeIdx);
    emit_bytes(OP_CALL, 1);

    if (!check(TOKEN_LEFT_BRACE)) {
        /* Break-net : FormatNombre attend un litteral composite `{ ... }`. */
        const char* got = "valeur";
        if (check(TOKEN_STRING))                            got = "cha\xc3\xaene";
        else if (check(TOKEN_INTEGER) || check(TOKEN_REAL)) got = "num\xc3\xa9rique";
        owl_emit_error_at(&parser.current, E_SEM_DSL_OBJECT_PROP_SCALAR,
                          "type", "FormatNombre", "got", got, NULL);
        /* Consomme la RHS jusqu'au terminateur (l'instance defaut reste sur la
         * pile pour le STRUCT_SET du caller). */
        while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) && !check(TOKEN_EOF))
            advance_token();
        return;
    }

    advance_token();  /* consume '{' */
    while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE) || check(TOKEN_COMMA)) advance_token();
        if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;

        if (parser.current.type < TOKEN_IDENTIFIER
            || parser.current.type >= TOKEN_NEWLINE) {
            owl_emit_error_current(E_SYNTAX_EXPECTED_FIELD_NAME_IN_BRACE);
            break;
        }
        Token fname = parser.current;
        advance_token();
        if (!match_token(TOKEN_EQUAL)) {
            owl_emit_error_at(&fname, E_SYNTAX_EXPECTED_EQUAL_AFTER_FIELD);
            break;
        }

        Value cval;
        if (!window_try_parse_const_literal(&cval)) {
            char nameBuf[64];
            snprintf(nameBuf, sizeof(nameBuf), "%.*s", fname.length, fname.start);
            owl_emit_error_at(&fname, E_SEM_PROJET_METADATA_NOT_CONSTANT,
                              "name", nameBuf, NULL);
            while (!check(TOKEN_COMMA) && !check(TOKEN_NEWLINE)
                   && !check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF))
                advance_token();
            continue;
        }

        /* Capture EN->FR pour la materialisation precoce + le repli runtime. */
        char strip[64];
        int sl = scanner_strip_accents(fname.start, fname.length,
                                       strip, sizeof(strip));
        if (sl <= 0) { sl = fname.length < 63 ? fname.length : 63; memcpy(strip, fname.start, (size_t)sl); strip[sl] = '\0'; }
        for (int i = 0; i < sl; i++)
            if (strip[i] >= 'A' && strip[i] <= 'Z') strip[i] = (char)(strip[i] - 'A' + 'a');
        if (strcmp(strip, "separateurdecimal") == 0
            || strcmp(strip, "decimalseparator") == 0) {
            if (IS_STRING(cval))
                snprintf(g_projet_fnb_sep_decimal, sizeof(g_projet_fnb_sep_decimal),
                         "%s", AS_CSTRING(cval));
        } else if (strcmp(strip, "separateurmilliers") == 0
                   || strcmp(strip, "thousandsseparator") == 0) {
            if (IS_STRING(cval))
                snprintf(g_projet_fnb_sep_milliers, sizeof(g_projet_fnb_sep_milliers),
                         "%s", AS_CSTRING(cval));
        } else if (strcmp(strip, "chiffresapresvirgule") == 0
                   || strcmp(strip, "decimalplaces") == 0) {
            if (IS_INTEGER(cval)) g_projet_fnb_chiffres = (int)AS_INTEGER(cval);
        }

        /* Bytecode : DUP instance + const + STRUCT_SET field (EN->FR resolu
         * cote VM) + POP val. */
        emit_byte(OP_DUP);
        emit_constant(cval);
        ConstIdx setIdx = identifier_constant(&fname);
        emit_const_op(OP_STRUCT_SET, setIdx);
        emit_byte(OP_POP);
    }
    consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_INSTANCE_LITERAL);

    /*  — rejette une config de separateurs contradictoire (milliers ==
     * decimal, ou un separateur qui est un chiffre) : sans ca le de-formatage
     * confond les separateurs et fabrique des zeros parasites. */
    const char* badSep = fnb_sep_conflict(g_projet_fnb_sep_milliers,
                                          g_projet_fnb_sep_decimal);
    if (badSep != NULL)
        owl_emit_error_at(&fieldTok, E_SEM_FORMAT_NOMBRE_SEP_INVALIDE,
                          "sep", badSep, NULL);
}

/*  — parse la RHS du champ FormatMonétaire du bloc Projet : litteral
 * composite inline `{ Symbole = "€", SéparateurMilliers = " ", ... }`. Miroir
 * strict de projet_emit_format_nombre_value : emet le bytecode de construction
 * (__StructClone(FormatMonétaire) + STRUCT_SET par champ) ET capture les
 * scalaires (g_projet_fmn_*, resolus EN->FR) pour la materialisation precoce +
 * le repli runtime des champs monetaires. Laisse une valeur sur la pile. */
static void projet_emit_format_monetaire_value(Token fieldTok) {
    /* Une seule instance FormatMonétaire par projet : reset la capture. */
    g_projet_fmn_set             = true;
    g_projet_fmn_symbole[0]      = '\0';
    g_projet_fmn_position        = OWL_POSSYM_APRES;
    g_projet_fmn_sep_decimal[0]  = '\0';
    g_projet_fmn_sep_milliers[0] = '\0';
    g_projet_fmn_chiffres        = 2;
    g_projet_fmn_negatif         = OWL_FMN_MOINS;

    /* __StructClone(FormatMonétaire) -> instance fresh (defauts du template). */
    Token cloneName; cloneName.start = "__StructClone"; cloneName.length = 13;
    ConstIdx cloneIdx = identifier_constant(&cloneName);
    emit_const_op(OP_GET_GLOBAL, cloneIdx);
    Token typeTok; typeTok.start = "FormatMon\xc3\xa9taire"; typeTok.length = 16;
    ConstIdx typeIdx = identifier_constant(&typeTok);
    emit_get_type_global("FormatMon\xc3\xa9taire", 16, typeIdx);
    emit_bytes(OP_CALL, 1);

    if (!check(TOKEN_LEFT_BRACE)) {
        const char* got = "valeur";
        if (check(TOKEN_STRING))                            got = "cha\xc3\xaene";
        else if (check(TOKEN_INTEGER) || check(TOKEN_REAL)) got = "num\xc3\xa9rique";
        owl_emit_error_at(&parser.current, E_SEM_DSL_OBJECT_PROP_SCALAR,
                          "type", "FormatMon\xc3\xa9taire", "got", got, NULL);
        while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) && !check(TOKEN_EOF))
            advance_token();
        return;
    }

    advance_token();  /* consume '{' */
    while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE) || check(TOKEN_COMMA)) advance_token();
        if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;

        if (parser.current.type < TOKEN_IDENTIFIER
            || parser.current.type >= TOKEN_NEWLINE) {
            owl_emit_error_current(E_SYNTAX_EXPECTED_FIELD_NAME_IN_BRACE);
            break;
        }
        Token fname = parser.current;
        advance_token();
        if (!match_token(TOKEN_EQUAL)) {
            owl_emit_error_at(&fname, E_SYNTAX_EXPECTED_EQUAL_AFTER_FIELD);
            break;
        }

        Value cval;
        if (!window_try_parse_const_literal(&cval)) {
            char nameBuf[64];
            snprintf(nameBuf, sizeof(nameBuf), "%.*s", fname.length, fname.start);
            owl_emit_error_at(&fname, E_SEM_PROJET_METADATA_NOT_CONSTANT,
                              "name", nameBuf, NULL);
            while (!check(TOKEN_COMMA) && !check(TOKEN_NEWLINE)
                   && !check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF))
                advance_token();
            continue;
        }

        /* Capture EN->FR pour la materialisation precoce + le repli runtime. */
        char strip[64];
        int sl = scanner_strip_accents(fname.start, fname.length,
                                       strip, sizeof(strip));
        if (sl <= 0) { sl = fname.length < 63 ? fname.length : 63; memcpy(strip, fname.start, (size_t)sl); strip[sl] = '\0'; }
        for (int i = 0; i < sl; i++)
            if (strip[i] >= 'A' && strip[i] <= 'Z') strip[i] = (char)(strip[i] - 'A' + 'a');
        if (strcmp(strip, "symbole") == 0 || strcmp(strip, "symbol") == 0) {
            if (IS_STRING(cval))
                snprintf(g_projet_fmn_symbole, sizeof(g_projet_fmn_symbole),
                         "%s", AS_CSTRING(cval));
        } else if (strcmp(strip, "positionsymbole") == 0
                   || strcmp(strip, "symbolposition") == 0) {
            if (IS_INTEGER(cval)) g_projet_fmn_position = (int)AS_INTEGER(cval);
        } else if (strcmp(strip, "separateurdecimal") == 0
                   || strcmp(strip, "decimalseparator") == 0) {
            if (IS_STRING(cval))
                snprintf(g_projet_fmn_sep_decimal, sizeof(g_projet_fmn_sep_decimal),
                         "%s", AS_CSTRING(cval));
        } else if (strcmp(strip, "separateurmilliers") == 0
                   || strcmp(strip, "thousandsseparator") == 0) {
            if (IS_STRING(cval))
                snprintf(g_projet_fmn_sep_milliers, sizeof(g_projet_fmn_sep_milliers),
                         "%s", AS_CSTRING(cval));
        } else if (strcmp(strip, "chiffresapresvirgule") == 0
                   || strcmp(strip, "decimalplaces") == 0) {
            if (IS_INTEGER(cval)) g_projet_fmn_chiffres = (int)AS_INTEGER(cval);
        } else if (strcmp(strip, "formatnegatif") == 0
                   || strcmp(strip, "negativeformat") == 0) {
            if (IS_INTEGER(cval)) g_projet_fmn_negatif = (int)AS_INTEGER(cval);
        }

        emit_byte(OP_DUP);
        emit_constant(cval);
        ConstIdx setIdx = identifier_constant(&fname);
        emit_const_op(OP_STRUCT_SET, setIdx);
        emit_byte(OP_POP);
    }
    consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_INSTANCE_LITERAL);

    /*  — rejette une config monetaire absurde (separateurs milliers ==
     * decimal, separateur/symbole = chiffre, symbole = separateur) : sans ca le
     * de-formatage confond les elements et fabrique des valeurs parasites. */
    const char* badElem = fmn_config_conflict(g_projet_fmn_symbole,
                                              g_projet_fmn_sep_milliers,
                                              g_projet_fmn_sep_decimal);
    if (badElem != NULL)
        owl_emit_error_at(&fieldTok, E_SEM_FORMAT_MONETAIRE_CONFIG_INVALIDE,
                          "elem", badElem, NULL);
}

/*  — une PROCEDURE declaree dans le corps d'un bloc Projet n'est
 * autorisee que si son nom est un event projet canonique. Aujourd'hui le seul
 * event de teardown est Fermeture (FR) / Closing (EN). Casse-insensible
 * (invariant 1) ; ces deux noms n'ont pas d'accent a stripper. */
static bool projet_event_proc_allowed(const char* name, int len) {
    return (len == 9 && strncasecmp(name, "Fermeture", 9) == 0)
        || (len == 7 && strncasecmp(name, "Closing", 7) == 0);
}

/* Queue de parse commune aux deux ordres de mots du tableau associatif
 * (FR "tableau associatif" / calque "array associative" / anglais naturel
 * "associative array"). Les deux mots-cles ont deja ete consommes ; on
 * absorbe ici les options parenthesees optionnelles puis la liaison
 * `DE/OF <type>` qui fixe le genre de valeur (0 = variant par defaut). */
static void parse_assoc_array_type_tail(int* outValueKind, Token* outValueTypeName) {
    /*  — la forme parenthesee (options, valeur par defaut, type de cle,
     * taille initiale) n'est pas implementee. Elle etait avalee sans etre lue :
     * `tableau associatif(chaine, entier)` compilait en tableau NON type. Refus
     * explicite, puis on consomme quand meme le groupe pour que la suite de la
     * declaration parse proprement (pas de cascade de bruit). */
    if (check(TOKEN_LEFT_PAREN)) {
        owl_emit_error_at(&parser.current, E_SYNTAX_ASSOC_ARRAY_PAREN_UNSUPPORTED);
    }
    if (match_token(TOKEN_LEFT_PAREN)) {
        int depth = 1;
        while (depth > 0 && !check(TOKEN_EOF)) {
            if (check(TOKEN_LEFT_PAREN)) { advance_token(); depth++; continue; }
            if (check(TOKEN_RIGHT_PAREN)) {
                depth--;
                advance_token();
                if (depth == 0) break;
                continue;
            }
            advance_token();
        }
    }
    /* DE/OF <type> optionnel pour lier le genre de valeur. La liaison est
     * FACULTATIVE (`x est un tableau associatif` = valeurs heterogenes,
     * usage legitime : lignes SQL), mais des qu'elle est ecrite le nom doit
     * designer un type REEL.
     *  — l'elision `d'<type>` (francais naturel) est acceptee a
     * parite avec `de`/`of` : le scanner a deja avale le filler `d'`, le type
     * est donc le token courant sur la MEME ligne (pas de `de` a matcher).
     * Sans ca `tableau associatif d'entiers` echouait « Expression attendue »
     * alors que la forme bancale `de entiers` passait. */
    if (match_token(TOKEN_DE) || (!crossedNewline && is_type_token())) {
        /*  — un nom non resolu (`of int`, `of Zorglub`) retombait
         * silencieusement sur le genre 0 (non type). Les autres mots-cles de
         * type (Date, Heure, Buffer, JSON...) sont des types connus du
         * scanner : pas d'erreur, simplement pas de valeur par defaut.
         *  — un pluriel primitif sans mot dedie resout au singulier. */
        TokenType elemTok = parser.current.type;
        TokenType prim = record_collection_elem_type_ref(parser.current);
        if (prim != TOKEN_EOF) elemTok = prim;
        switch (elemTok) {
            case TOKEN_CHAINE:    *outValueKind = 1; break;
            case TOKEN_ENTIER:    *outValueKind = 2; break;
            case TOKEN_REEL:      *outValueKind = 3; break;
            case TOKEN_BOOLEEN:   *outValueKind = 4; break;
            case TOKEN_MONETAIRE: *outValueKind = 5; break;
            case TOKEN_NUMERIQUE: *outValueKind = 6; break;
            default:              *outValueKind = 0; break;
        }
        /*  — nom d'un type de valeur NON primitif (identifiant : type
         * registry composé comme httpRequête, ou structure utilisateur). On le
         * capture avant advance ; stocké sur l'assoc au runtime, il pilote
         * l'auto-vivification objet à la lecture/écriture d'une clé absente.
         * Les mots-clés de type non résolus (Date, Buffer, JSON…) restent en
         * variant sans nom -> pas de vivification, comportement inchangé. */
        if (outValueTypeName != NULL && *outValueKind == 0
            && check(TOKEN_IDENTIFIER)) {
            *outValueTypeName = parser.current;
        }
        if (is_type_token()) advance_token();
    }
}

/* Renvoie le prochain token significatif d'un scanner cloné (saute
 * NEWLINE / SEMICOLON). Utilisé pour peeker un type composé sans effet
 * de bord sur le scanner du parser. */
static Token peek_next_significant(Scanner* s) {
    Token t;
    do {
        t = scanner_scan_token(s);
    } while (t.type == TOKEN_NEWLINE || t.type == TOKEN_SEMICOLON);
    return t;
}

/* True si `t` est l'article EN `a` / `an` (scanné soit en TOKEN_A, soit
 * en IDENTIFIER "a"/"an"). Miroir de consume_en_a_an_filler mais sur un
 * token arbitraire (pour peek). */
static bool token_is_en_a_an_filler(Token t) {
    if (t.type == TOKEN_A) return true;
    if (t.type != TOKEN_IDENTIFIER) return false;
    if (t.length == 1 && (t.start[0] == 'a' || t.start[0] == 'A')) return true;
    if (t.length == 2 && (t.start[0] == 'a' || t.start[0] == 'A') &&
        (t.start[1] == 'n' || t.start[1] == 'N')) return true;
    return false;
}

/*  — détection d'un tableau associatif en position de type de
 * CHAMP (classe / structure). Les champs passent par skip_type_spec qui
 * ne connaît que TOKEN_TABLEAU ; ce helper reproduit la détection du
 * parseur de variable locale (deux ordres de mots) et, si un tableau
 * associatif est reconnu, consomme TOUTE la spec de type (article EN
 * optionnel + les deux mots-clés + tail `de/of <type>`) et pose
 * *outValueKind. Sinon ne consomme RIEN (le chemin skip_type_spec
 * habituel prend le relais). Ordres acceptés :
 *   FR : `tableau associatif de X`  -> TABLEAU ASSOCIATIF
 *   EN : `associative array of X`   -> ASSOCIATIF TABLEAU
 * L'article `a`/`an` peut précéder (contexte structure où le filler
 * n'est pas gommé avant l'appel). */
static bool try_consume_assoc_array_field_type(int* outValueKind,
                                               Token* outValueTypeName) {
    Scanner peek = parser.scanner;   /* positionné APRÈS parser.current */
    bool hasFiller = token_is_en_a_an_filler(parser.current);
    Token first = hasFiller ? peek_next_significant(&peek) : parser.current;
    if (first.type != TOKEN_TABLEAU && first.type != TOKEN_ASSOCIATIF) {
        return false;
    }
    Token second = peek_next_significant(&peek);
    bool isAssoc =
        (first.type == TOKEN_TABLEAU   && second.type == TOKEN_ASSOCIATIF) ||
        (first.type == TOKEN_ASSOCIATIF && second.type == TOKEN_TABLEAU);
    if (!isAssoc) return false;
    if (hasFiller) advance_token();  /* a / an */
    advance_token();                 /* premier mot-clé */
    advance_token();                 /* second mot-clé */
    /*  — path champ (structure/classe) : capture du nom de type de
     * valeur NON primitif (httpRequête & co), threade jusqu'a l'ObjAssocArray
     * du champ pour piloter l'auto-vivification objet (machinerie ). */
    parse_assoc_array_type_tail(outValueKind, outValueTypeName);
    return true;
}

/*  — émet un tableau associatif vide sur la pile
 * (__AssocNew(clé=chaîne, options=0, valueKind)). Miroir de l'émission
 * du parseur local (~15673) pour poser un default de champ utilisable
 * dès l'instanciation, symétrique au OP_ARRAY vide du tableau dynamique
 *. */
static void emit_empty_assoc_array(int valueKind, const Token* valueTypeName) {
    Token anTok;
    anTok.start = "__AssocNew";
    anTok.length = 10;
    anTok.type = TOKEN_IDENTIFIER;
    anTok.line = parser.previous.line;
    anTok.column = 0;
    ConstIdx anConst = identifier_constant(&anTok);
    emit_const_op(OP_GET_GLOBAL, anConst);
    emit_constant(INTEGER_VAL(0));          /* ASSOC_KEY_STRING */
    emit_constant(INTEGER_VAL(0));          /* options */
    emit_constant(INTEGER_VAL(valueKind));
    /*  — si un type de valeur NON primitif a été nommé, on l'émet en
     * 4e argument (miroir du path direct ) : il pilote l'auto-
     * vivification objet du champ. Sinon 3 args (inchangé). */
    if (valueTypeName != NULL && valueTypeName->start != NULL
        && valueTypeName->length > 0) {
        ObjString* vtn = obj_copy_string(valueTypeName->start,
                                         valueTypeName->length);
        emit_constant(OBJ_VAL(vtn));
        emit_bytes(OP_CALL, 4);
    } else {
        emit_bytes(OP_CALL, 3);
    }
}

/* ================================================================
 *  — DSL de service HTTP : blocs `<Nom> est un ServiceREST` et
 * `<Op> est une OpérationHTTP`. Chantier 1 : parse + validation statique.
 * Aucune emission de bytecode, aucune invocation — la signature de
 * `surRequête` est capturee mais le corps est ignore (skip a profondeur).
 * ================================================================ */

/* Cle canon (accents strippes + minuscule) pour comparaisons de valeurs
 * d'enum entre elles (CodeÉtat vs Réponses). */
static void service_canon_key(const char* s, int len, char* out, int cap) {
    char stripped[256];
    int n = scanner_strip_accents(s, len, stripped, sizeof(stripped));
    if (n <= 0) {
        n = len < (int)sizeof(stripped) - 1 ? len : (int)sizeof(stripped) - 1;
        memcpy(stripped, s, (size_t)n);
    }
    if (n > cap - 1) n = cap - 1;
    for (int i = 0; i < n; i++) {
        char c = stripped[i];
        if (c >= 'A' && c <= 'Z') c = (char)(c - 'A' + 'a');
        out[i] = c;
    }
    out[n] = '\0';
}

/* Vrai si l'identifiant courant (accent-strippe) matche `kw` (ASCII). */
static bool service_ident_is(const char* kw) {
    if (!check(TOKEN_IDENTIFIER)) return false;
    char probe[64];
    int n = scanner_strip_accents(parser.current.start, parser.current.length,
                                  probe, sizeof(probe));
    if (n <= 0) return false;
    return (int)strlen(kw) == n && strncasecmp(probe, kw, (size_t)n) == 0;
}

/*  — un nom d'operation / de service REST peut collisionner avec un
 * mot-cle du langage (`Publique`->TOKEN_PUBLIC, `Etat`->TOKEN_ETAT, ...). Ce
 * sont des ressources REST naturelles en francais (/publique, /etat...). En
 * position GATEE par `<nom> est une OperationHTTP` / `<nom> est un ServiceREST`
 * le contexte desambiguise totalement, donc on accepte un token mot-cle comme
 * nom au meme titre qu'un TOKEN_IDENTIFIER. Critere name-like : lexeme non vide
 * commencant par une lettre / underscore / octet UTF-8 (couvre tous les
 * mots-cles, exclut operateurs, nombres, ponctuation, chaines). Le lexeme sert
 * de label + de base au handler synthetise, jamais re-parse comme identifiant
 * -> aucun effet de bord. */
static bool token_lexeme_is_namelike(Token t) {
    if (t.length <= 0 || t.start == NULL) return false;
    unsigned char c = (unsigned char)t.start[0];
    return c == '_' || c >= 0x80 ||
           (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

/*  — peek non destructif depuis un token LEADING name-like NON
 * identifiant (mot-cle) : le construct courant est-il `<mot-cle> est un[e]
 * ServiceREST` ? Gate strict pour n'elargir la reconnaissance du nom qu'a la
 * position de nom de service (un `PUBLIC est un entier` hors ServiceREST reste
 * refuse : la suite n'est pas `ServiceREST`). Miroir de
 * peek_top_level_is_class_declaration. */
static bool peek_leading_keyword_is_service_rest(void) {
    if (check(TOKEN_IDENTIFIER)) return false;   /* chemin identifiant deja gere */
    if (!token_lexeme_is_namelike(parser.current)) return false;
    Scanner saved     = parser.scanner;
    Token   savedCur  = parser.current;
    Token   savedPrev = parser.previous;
    bool    savedXNL  = crossedNewline;
    bool    isSvc     = false;
    advance_token();                             /* le nom (mot-cle) */
    if (check(TOKEN_EST) || check(TOKEN_SONT)) {
        advance_token();
        consume_en_a_an_filler();
        isSvc = service_ident_is("ServiceREST");
    }
    parser.scanner   = saved;
    parser.current   = savedCur;
    parser.previous  = savedPrev;
    crossedNewline   = savedXNL;
    return isSvc;
}

/* Segment litteral de chemin/URL valide : non vide, sans '/' ni caractere
 * reserve d'URL / de query. Les octets UTF-8 (>= 0x80) restent permis. */
static bool service_path_segment_ok(const char* s, int len) {
    if (len == 0) return false;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)s[i];
        if (c == '/' || c == '?' || c == '#' || c == '&' ||
            c == ' ' || c == '\t' || c < 0x20) {
            return false;
        }
    }
    return true;
}

static void str_array_push(char*** arr, int* count, const char* s, int len) {
    *arr = (char**)realloc(*arr, (size_t)(*count + 1) * sizeof(char*));
    char* c = (char*)malloc((size_t)len + 1);
    memcpy(c, s, (size_t)len);
    c[len] = '\0';
    (*arr)[(*count)++] = c;
}

/* Enregistre la nature du dernier segment de chemin pousse dans
 * op->pathSegments. Tableau parallele a pathSegments, tenu en phase par
 * pathSegmentCount. `kind` : 0 = litteral, 1 = parametre nomme, 2 = parametre
 * catch-all glouton. Le routeur (http_route) s'en sert pour la
 * specificite, la regle de position du catch-all et la liaison des parametres. */
static void path_segment_kind_push(OwlOperationDecl* op, unsigned char kind) {
    op->pathSegmentIsParam = (unsigned char*)realloc(
        op->pathSegmentIsParam, (size_t)op->pathSegmentCount);
    op->pathSegmentIsParam[op->pathSegmentCount - 1] = kind;
}

/* Saute jusqu'a la fin de la ligne courante (resync apres erreur / valeur
 * ignoree). S'arrete sur NEWLINE / FIN / EOF sans les consommer (sauf le
 * NEWLINE, laisse au loop). */
static void service_skip_to_eol(void) {
    while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        advance_token();
    }
}

/*  — nom global synthetise sous lequel le corps de surRequete est
 * compile : `<service>__<op>__surReq`, en canon ASCII (le lookup global est
 * accent/casse-insensible, mais on garde un nom propre et sans collision).
 * Buffer statique : la duree de vie couvre identifier_constant / declare /
 * define, tous immediats. */
static const char* service_handler_synth_name(const OwlServiceDecl* svc,
                                               const OwlOperationDecl* op) {
    static char buf[256];
    char svcA[96], opA[96];
    int sn = scanner_strip_accents(svc->name, (int)strlen(svc->name),
                                   svcA, sizeof(svcA));
    if (sn <= 0) { sn = 0; svcA[0] = '\0'; }
    int on = scanner_strip_accents(op->name, (int)strlen(op->name),
                                   opA, sizeof(opA));
    if (on <= 0) { on = 0; opA[0] = '\0'; }
    snprintf(buf, sizeof(buf), "%s__%s__surReq", svcA, opA);
    return buf;
}

/* Events reconnus au NIVEAU SERVICE.  : la validite (nom connu ou
 * non) vient desormais du catalogue owl_service_event_catalog — source unique
 * partagee avec le LSP (coloration + completion). Plus de liste de noms en
 * dur : un event absent du catalogue est rejete. Le ServiceEventKind ci-dessous
 * n'est qu'un aiguillage INTERNE au compilateur (chaque hook a un chemin de
 * compilation distinct : contexte MoiMême, nom synthetise, retour) ; il est
 * derive de la forme canonique retournee par le catalogue. */
typedef enum {
    SVC_EVT_UNKNOWN = 0,
    SVC_EVT_AUTH,      /* surAuthentification / onAuthentication */
    SVC_EVT_INIT,      /* FinInitialisation / EndInitialization  */
    SVC_EVT_CLOSE,     /* Fermeture / Closing                    */
    SVC_EVT_ERROR,     /* surErreur / onError                    */
    SVC_EVT_AUTHZ      /* surAutorisation / onAuthorization       */
} ServiceEventKind;

static ServiceEventKind service_event_classify(const char* name, int len) {
    char probe[64];
    int n = scanner_strip_accents(name, len, probe, sizeof(probe));
    if (n <= 0) return SVC_EVT_UNKNOWN;
    /* Validite : source unique = catalogue service. */
    const OwlEventDef* d = owl_service_event_catalog_find(probe);
    if (d == NULL || d->canonical == NULL) return SVC_EVT_UNKNOWN;
    /* Aiguillage interne compilateur sur la forme canonique (FR, ASCII : les
     * cinq hooks service n'ont pas d'accent dans leur canon). */
    if (strcasecmp(d->canonical, "surAuthentification") == 0) return SVC_EVT_AUTH;
    if (strcasecmp(d->canonical, "FinInitialisation") == 0)   return SVC_EVT_INIT;
    if (strcasecmp(d->canonical, "Fermeture") == 0)           return SVC_EVT_CLOSE;
    if (strcasecmp(d->canonical, "surErreur") == 0)           return SVC_EVT_ERROR;
    if (strcasecmp(d->canonical, "surAutorisation") == 0)     return SVC_EVT_AUTHZ;
    return SVC_EVT_UNKNOWN;
}

/* Nom global synthetise du hook surAuthentification : `<service>__surAuth`. */
static const char* service_auth_synth_name(const OwlServiceDecl* svc) {
    static char buf[256];
    char svcA[96];
    int sn = scanner_strip_accents(svc->name, (int)strlen(svc->name),
                                   svcA, sizeof(svcA));
    if (sn <= 0) { svcA[0] = '\0'; }
    snprintf(buf, sizeof(buf), "%s__surAuth", svcA);
    return buf;
}

/* Nom global synthetise du hook surErreur : `<service>__surErr`. */
static const char* service_error_synth_name(const OwlServiceDecl* svc) {
    static char buf[256];
    char svcA[96];
    int sn = scanner_strip_accents(svc->name, (int)strlen(svc->name),
                                   svcA, sizeof(svcA));
    if (sn <= 0) { svcA[0] = '\0'; }
    snprintf(buf, sizeof(buf), "%s__surErr", svcA);
    return buf;
}

/* Nom global synthetise du hook surAutorisation : `<service>__surAuthz`. */
static const char* service_authz_synth_name(const OwlServiceDecl* svc) {
    static char buf[256];
    char svcA[96];
    int sn = scanner_strip_accents(svc->name, (int)strlen(svc->name),
                                   svcA, sizeof(svcA));
    if (sn <= 0) { svcA[0] = '\0'; }
    snprintf(buf, sizeof(buf), "%s__surAuthz", svcA);
    return buf;
}

/* Saute le corps d'une PROCEDURE deja consommee jusqu'a son FIN (compte de
 * profondeur), sans compiler — cas jetable / doublon. */
static void service_skip_proc_body(void) {
    int depth = 1;
    while (depth > 0 && !check(TOKEN_EOF)) {
        depth += local_scan_depth_delta(parser.current, &parser.scanner);
        advance_token();
    }
}

/*  — parse un hook de CYCLE DE VIE au NIVEAU SERVICE : FinInitialisation
 * / Fermeture (one-shot, SANS contexte MoiMême) et surErreur (sur le crash du
 * handler, AVEC contexte MoiMême). Precondition : current = nom du hook (deja
 * classifie), PROCEDURE/FONCTION deja consomme.
 *
 * FinInitialisation / Fermeture sont compiles sous leur nom LITTERAL (globaux
 * resolus par vm_call_global depuis l'executeur, calque du teardown projet) :
 * aucun MoiMême n'a de sens (pas de requete). surErreur est compile sous un nom
 * SYNTHETISE `<service>__surErr` (miroir surAuthentification) avec
 * g_in_service_handler=true, memorise dans svc->errorHandlerGlobal pour
 * propagation aux routes runtime.  — surAutorisation suit le meme
 * moule (nom synthetise `<service>__surAuthz`, contexte MoiMême, 0 argument,
 * RENVOYER booleen), memorise dans svc->authzHandlerGlobal. */
static void service_parse_lifecycle_procedure(OwlServiceDecl* svc,
                                              ServiceEventKind kind) {
    Token nameTok = parser.current;
    advance_token(); /* consume hook name */

    bool withContext = (kind == SVC_EVT_ERROR || kind == SVC_EVT_AUTHZ);

    /* Compile une seule fois par service (doublon -> saut propre). */
    bool compile = false;
    if (svc != NULL) {
        if (kind == SVC_EVT_INIT)  compile = !svc->initHookSeen;
        if (kind == SVC_EVT_CLOSE) compile = !svc->closeHookSeen;
        if (kind == SVC_EVT_ERROR) compile = (svc->errorHandlerGlobal == NULL);
        if (kind == SVC_EVT_AUTHZ) compile = (svc->authzHandlerGlobal == NULL);
    }

    ConstIdx gIdx = {0};
    Token    gTok;
    Compiler hookCompiler;
    if (compile) {
        if (kind == SVC_EVT_ERROR || kind == SVC_EVT_AUTHZ) {
            char** slot = (kind == SVC_EVT_ERROR) ? &svc->errorHandlerGlobal
                                                  : &svc->authzHandlerGlobal;
            const char* synth = (kind == SVC_EVT_ERROR)
                ? service_error_synth_name(svc)
                : service_authz_synth_name(svc);
            *slot = (char*)malloc(strlen(synth) + 1);
            memcpy(*slot, synth, strlen(synth) + 1);
            gTok.start  = *slot;
            gTok.length = (int)strlen(*slot);
        } else {
            /* Nom LITTERAL : le token source designe le global (resolu canon a
             * l'execution, casse/accent-insensible). */
            gTok.start  = nameTok.start;
            gTok.length = nameTok.length;
            if (kind == SVC_EVT_INIT)  svc->initHookSeen  = 1;
            if (kind == SVC_EVT_CLOSE) svc->closeHookSeen = 1;
        }
        gTok.line   = nameTok.line;
        gTok.column = 0;
        gTok.type   = TOKEN_IDENTIFIER;
        gIdx = identifier_constant(&gTok);
        declare_variable(&gTok);
        global_track_mark_used(gTok.start, gTok.length);

        init_compiler(&hookCompiler, TYPE_FUNCTION);
        begin_scope();
        current->function->name = obj_copy_string(gTok.start, gTok.length);
    }

    /* Signature vide `()` toleree : aucun parametre attendu. Ces crochets de
     * cycle de vie s'executent dans le contexte de l'echange (MoiMeme), pas
     * avec des arguments — un groupe de parametres non vide echouerait en
     * silence a la frontiere reentrante (mismatch d'arite). On refuse a la
     * compilation. */
    if (match_token(TOKEN_LEFT_PAREN)) {
        if (!check(TOKEN_RIGHT_PAREN)) {
            char hookName[64];
            int hn = nameTok.length < 63 ? nameTok.length : 63;
            memcpy(hookName, nameTok.start, (size_t)hn);
            hookName[hn] = '\0';
            owl_emit_error_at(&nameTok, E_SEM_DSL_SERVICE_HOOK_ARITE,
                              "hook", hookName, NULL);
            parser.panicMode = false;
        }
        while (!check(TOKEN_RIGHT_PAREN) && !check(TOKEN_NEWLINE) &&
               !check(TOKEN_EOF)) {
            advance_token();
        }
        match_token(TOKEN_RIGHT_PAREN);
    }

    /* Type de retour `: type` eventuel : avale sur la meme ligne. */
    if (match_token(TOKEN_COLON)) {
        consume_en_a_an_filler();
        while (!crossedNewline && !check(TOKEN_EOF) && !check(TOKEN_FIN)) {
            advance_token();
        }
    }

    if (compile) {
        bool savedInService = g_in_service_handler;
        g_in_service_handler = withContext;
        while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
            declaration();
        }
        g_in_service_handler = savedInService;

        ObjFunction* function = end_compiler();
        emit_const_op(OP_CONSTANT, make_constant(OBJ_VAL(function)));
        define_variable(gIdx);
        consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROCEDURE);
        return;
    }

    service_skip_proc_body();
}

/*  — parse un event au NIVEAU SERVICE (surAuthentification et, depuis
 * , les hooks de cycle de vie). Classifie le nom puis delegue :
 * surAuthentification est compile ici (signature + retour booleen), les hooks de
 * cycle de vie via service_parse_lifecycle_procedure. Le corps auth est compile
 * en fonction globale a nom synthetise (miroir de service_parse_procedure),
 * invocable a l'execution ; MoiMême y designe le contexte d'echange
 * (g_in_service_handler). Le nom est memorise dans svc->authHandlerGlobal pour
 * propagation au registre runtime. Precondition : current = PROCEDURE/FONCTION. */
static void service_parse_auth_procedure(OwlServiceDecl* svc) {
    advance_token(); /* consume PROCEDURE / FONCTION */

    ServiceEventKind kind = check(TOKEN_IDENTIFIER)
        ? service_event_classify(parser.current.start, parser.current.length)
        : SVC_EVT_UNKNOWN;

    /* Nom hors whitelist service -> erreur + saut propre du corps. */
    if (kind == SVC_EVT_UNKNOWN) {
        char nm[128];
        int nl = parser.current.length < 127 ? parser.current.length : 127;
        memcpy(nm, parser.current.start, (size_t)nl); nm[nl] = '\0';
        owl_emit_error_at(&parser.current, E_SYNTAX_SERVICE_EVENT_UNKNOWN,
                          "name", nm, NULL);
        parser.panicMode = false;
        service_skip_proc_body();
        return;
    }

    /* Hooks de cycle de vie (FinInitialisation / Fermeture / surErreur). */
    if (kind != SVC_EVT_AUTH) {
        service_parse_lifecycle_procedure(svc, kind);
        return;
    }

    /* --- surAuthentification / onAuthentication --- */
    Token nameTok = parser.current;
    advance_token(); /* consume hook name */

    /* Service jetable (doublon) ou hook deja declare -> on ne compile pas, on
     * saute le corps proprement (pas de cascade de bruit). */
    bool compile = (svc != NULL && svc->authHandlerGlobal == NULL);

    ConstIdx synthIdx = {0};
    Token    synthTok;
    Compiler hookCompiler;
    if (compile) {
        const char* synth = service_auth_synth_name(svc);
        svc->authHandlerGlobal = (char*)malloc(strlen(synth) + 1);
        memcpy(svc->authHandlerGlobal, synth, strlen(synth) + 1);
        synthTok.start  = svc->authHandlerGlobal;
        synthTok.length = (int)strlen(svc->authHandlerGlobal);
        synthTok.line   = nameTok.line;
        synthTok.column = 0;
        synthTok.type   = TOKEN_IDENTIFIER;
        synthIdx = identifier_constant(&synthTok);
        declare_variable(&synthTok);
        global_track_mark_used(synthTok.start, synthTok.length);

        init_compiler(&hookCompiler, TYPE_FUNCTION);
        begin_scope();
        current->function->name = obj_copy_string(synthTok.start, synthTok.length);
    }

    /* Signature : (jeton est une chaine). Chaque param est declare local du
     * handler (arite) et marque utilise (contrat de liaison : le framework le
     * remplit, un param non lu reste legitime). */
    if (match_token(TOKEN_LEFT_PAREN)) {
        if (!check(TOKEN_RIGHT_PAREN)) {
            do {
                if (!check(TOKEN_IDENTIFIER)) break;
                Token pName = parser.current;
                advance_token();
                if (compile) {
                    current->function->arity++;
                    declare_variable(&pName);
                    if (current->localCount > 0) {
                        current->locals[current->localCount - 1].isUsed = true;
                    }
                }
                /* `est un <type>` optionnel : avale la specification de type
                 * jusqu'a la borne du parametre. */
                if (match_token(TOKEN_EST)) {
                    consume_en_a_an_filler();
                    while (!check(TOKEN_COMMA) && !check(TOKEN_RIGHT_PAREN) &&
                           !check(TOKEN_NEWLINE) && !check(TOKEN_EOF)) {
                        advance_token();
                    }
                }
            } while (match_token(TOKEN_COMMA));
        }
        match_token(TOKEN_RIGHT_PAREN);
    }

    /* Type de retour `: booleen` : consomme la specification sur la meme ligne
     * (meme garde crossedNewline que service_parse_procedure, ). */
    if (match_token(TOKEN_COLON)) {
        consume_en_a_an_filler();
        while (!crossedNewline && !check(TOKEN_EOF) && !check(TOKEN_FIN)) {
            advance_token();
        }
    }

    if (compile) {
        bool savedInService = g_in_service_handler;
        g_in_service_handler = true;
        while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
            declaration();
        }
        g_in_service_handler = savedInService;

        ObjFunction* function = end_compiler();
        emit_const_op(OP_CONSTANT, make_constant(OBJ_VAL(function)));
        define_variable(synthIdx);
        consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROCEDURE);
        return;
    }

    service_skip_proc_body();
}

/* Compile (ou saute) le handler `PROCEDURE surRequete(params) : type ... FIN`.
 *
 *  — fondation runtime : au lieu de sauter le corps, on le COMPILE en
 * fonction globale a nom synthetise (miroir de proc_declaration), callable a
 * l'execution via vm_call_global. Le nom synthetise est memorise dans
 * op->handlerGlobal pour que service_rest_declaration l'enregistre au routeur
 * runtime. On ne compile QUE pour une operation reelle (svc + op nommes) ; sur
 * un bloc jetable (doublon), on retombe sur l'ancien saut a profondeur.
 *
 * La signature (op->procParams / procReturnType) reste capturee comme avant
 * pour le chantier de binding. Precondition : current =
 * PROCEDURE/FONCTION, au top-level (current = compiler script). */
static void service_parse_procedure(OwlServiceDecl* svc, OwlOperationDecl* op) {
    advance_token(); /* consume PROCEDURE / FONCTION */

    bool compileHandler = (svc != NULL && op != NULL && op->name != NULL
                           && op->handlerGlobal == NULL);

    if (check(TOKEN_IDENTIFIER)) {
        if (op->procName == NULL) {
            int n = parser.current.length;
            op->procName = (char*)malloc((size_t)n + 1);
            memcpy(op->procName, parser.current.start, (size_t)n);
            op->procName[n] = '\0';
            op->hasProc = 1;
        }
        advance_token();
    }

    /* Prepare la compilation en fonction globale : declare le nom synthetise
     * dans le scope script AVANT d'ouvrir le compiler de fonction.
     * handlerCompiler est en scope FONCTION : init_compiler branche `current`
     * dessus, il doit vivre jusqu'a end_compiler (plus bas). */
    ConstIdx handlerGlobalIdx = {0};
    Token    synthTok;
    Compiler handlerCompiler;
    if (compileHandler) {
        const char* synth = service_handler_synth_name(svc, op);
        op->handlerGlobal = (char*)malloc(strlen(synth) + 1);
        memcpy(op->handlerGlobal, synth, strlen(synth) + 1);
        synthTok.start  = op->handlerGlobal;
        synthTok.length = (int)strlen(op->handlerGlobal);
        synthTok.line   = op->line;
        synthTok.column = 0;
        synthTok.type   = TOKEN_IDENTIFIER;
        handlerGlobalIdx = identifier_constant(&synthTok);
        declare_variable(&synthTok);
        /* Le handler est appele a l'execution par le routeur (vm_call_global),
         * jamais reference par son nom dans le source : on le marque utilise
         * pour ne pas declencher le warning "declare mais jamais utilise". */
        global_track_mark_used(synthTok.start, synthTok.length);

        init_compiler(&handlerCompiler, TYPE_FUNCTION);
        begin_scope();
        current->function->name = obj_copy_string(synthTok.start, synthTok.length);
    }

    /* Parametres : (nom [est un <type>], ...). En mode compile, chaque param
     * est aussi declare comme local de la fonction (arite). */
    /* Valeurs par defaut (query optionnels) : capturees comme pour une
     * procedure standard, dans function->defaults/minArity, pour que la VM
     * comble un argument optionnel trailing absent. */
    Value handlerDefaults[64];
    int   handlerDefaultCount = 0;
    int   handlerMinArity     = 0;
    int   handlerDefaultSeen  = 0;   /* un param a defaut a-t-il ete vu ? */
    if (match_token(TOKEN_LEFT_PAREN)) {
        if (!check(TOKEN_RIGHT_PAREN)) {
            do {
                if (!check(TOKEN_IDENTIFIER)) break;
                Token pName = parser.current;
                advance_token();
                if (compileHandler) {
                    current->function->arity++;
                    declare_variable(&pName);
                    /* Les params du handler sont le CONTRAT de liaison (chemin/
                     * query/corps) : la framework les lie par nom, un param non
                     * lu dans le corps reste legitime. On les marque utilises
                     * pour ne pas emettre "declare mais jamais utilise". */
                    if (current->localCount > 0) {
                        current->locals[current->localCount - 1].isUsed = true;
                    }
                }
                char* typeName = NULL;
                int   isStructured = 0;
                int   isFileUpload = 0;
                int   hasDefault = 0;
                if (match_token(TOKEN_EST)) {
                    consume_en_a_an_filler();
                    if (!check(TOKEN_RIGHT_PAREN) && !check(TOKEN_COMMA) &&
                        !check(TOKEN_NEWLINE) && !check(TOKEN_EOF)) {
                        int tn = parser.current.length;
                        typeName = (char*)malloc((size_t)tn + 1);
                        memcpy(typeName, parser.current.start, (size_t)tn);
                        typeName[tn] = '\0';
                        /* Classe le type : structure (candidat corps) vs scalaire.
                         * Les structures declarees en amont sont deja connues
                         * (single-pass, bloc service apres les Structure). */
                        isStructured = type_name_is_structure(parser.current.start,
                                                              parser.current.length);
                        /*  — un param FichierTéléversé est une source
                         * multipart (ni chemin/query, ni corps structure). */
                        isFileUpload = type_name_is_file_upload(parser.current.start,
                                                                parser.current.length);
                        advance_token();
                        /* Avale d'eventuels modificateurs de type jusqu'a la
                         * borne du parametre ou la valeur par defaut. Une
                         * valeur par defaut (`= <litteral>`) rend le param
                         * optionnel (query optionnel) et est captee pour que la
                         * VM la comble a l'invocation. */
                        while (!check(TOKEN_COMMA) && !check(TOKEN_RIGHT_PAREN) &&
                               !check(TOKEN_NEWLINE) && !check(TOKEN_EOF)) {
                            if (check(TOKEN_EQUAL)) {
                                hasDefault = 1;
                                if (compileHandler) {
                                    advance_token();   /* consume '=' */
                                    Value dv;
                                    if (parse_default_literal(&dv)) {
                                        if (handlerDefaultCount < 64)
                                            handlerDefaults[handlerDefaultCount++] = dv;
                                        if (current->localCount > 0)
                                            current->locals[current->localCount - 1]
                                                .hasInitializer = true;
                                    }
                                    break;   /* la valeur par defaut clot le param */
                                }
                            }
                            /*  — `tableau de FichierTéléversé` : le type
                             * element apparait dans les modificateurs (le 1er
                             * token est `tableau`). Un tel param reste une source
                             * multipart (plusieurs parties de meme nom). */
                            if (check(TOKEN_IDENTIFIER) &&
                                type_name_is_file_upload(parser.current.start,
                                                         parser.current.length)) {
                                isFileUpload = 1;
                            }
                            advance_token();
                        }
                    }
                }
                /* Ordre des parametres : un param requis (sans defaut) ne peut
                 * pas suivre un param a defaut (miroir du parsing methode/
                 * procedure, compiler.c ~23515). parser.previous = token de
                 * type du param requis -> diagnostic pointe dessus. Garde
                 * uniforme : aucun cas special, le corps de requete structure
                 * est soumis a la meme regle que les params scalaires. */
                if (!hasDefault && handlerDefaultSeen) {
                    owl_emit_error_at(&parser.previous, E_SEM_REQUIRED_PARAM_AFTER_DEFAULT);
                }
                if (hasDefault) handlerDefaultSeen = 1;
                op->procParams = (OwlServiceProcParam*)realloc(
                    op->procParams,
                    (size_t)(op->procParamCount + 1) * sizeof(OwlServiceProcParam));
                OwlServiceProcParam* p = &op->procParams[op->procParamCount++];
                int pn = pName.length;
                p->name = (char*)malloc((size_t)pn + 1);
                memcpy(p->name, pName.start, (size_t)pn);
                p->name[pn] = '\0';
                p->typeName = typeName;
                p->isStructured = isStructured;
                p->isFileUpload = isFileUpload;
                p->hasDefault = hasDefault;
                /* minArity = nombre de parametres requis en tete : chaque param
                 * sans defaut repousse la borne (contrat trailing-optionnel). */
                if (compileHandler && !hasDefault) {
                    handlerMinArity = current->function->arity;
                }
            } while (match_token(TOKEN_COMMA));
        }
        match_token(TOKEN_RIGHT_PAREN);
    }
    if (compileHandler) {
        current->function->minArity = handlerMinArity;
        if (handlerDefaultCount > 0) {
            current->function->defaults =
                (Value*)malloc(sizeof(Value) * (size_t)handlerDefaultCount);
            for (int di = 0; di < handlerDefaultCount; di++) {
                current->function->defaults[di] = handlerDefaults[di];
            }
            current->function->defaultCount = handlerDefaultCount;
        }
    }

    /* Type de retour : : <type>. Le spec de type tient sur LA MEME ligne que
     * l'entete ; on s'arrete a la frontiere de ligne. advance_token() avale les
     * NEWLINE en posant crossedNewline (parser.current n'est JAMAIS un
     * TOKEN_NEWLINE), donc un stop sur check(TOKEN_NEWLINE) ne se declenche
     * jamais et engloutit tout le corps du handler jusqu'a FIN (retour NIL,
     * MoiMême..X perdus). Le garde correct est crossedNewline. */
    if (match_token(TOKEN_COLON)) {
        consume_en_a_an_filler();
        if (!crossedNewline && !check(TOKEN_EOF) && !check(TOKEN_FIN)) {
            int rn = parser.current.length;
            op->procReturnType = (char*)malloc((size_t)rn + 1);
            memcpy(op->procReturnType, parser.current.start, (size_t)rn);
            op->procReturnType[rn] = '\0';
            advance_token();
            while (!crossedNewline && !check(TOKEN_EOF) && !check(TOKEN_FIN)) {
                advance_token();
            }
        }
    }

    if (compileHandler) {
        /* Corps : compile chaque declaration jusqu'au FIN, en contexte service
         * (MoiMême = reponse implicite). */
        bool savedInService = g_in_service_handler;
        g_in_service_handler = true;
        while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
            declaration();
        }
        g_in_service_handler = savedInService;

        ObjFunction* function = end_compiler();
        emit_const_op(OP_CONSTANT, make_constant(OBJ_VAL(function)));
        define_variable(handlerGlobalIdx);
        consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROCEDURE);
        return;
    }

    /* Bloc jetable : ancien saut a profondeur (la PROCEDURE deja consommee a
     * ouvert un bloc, on compte jusqu'a son FIN). */
    int depth = 1;
    while (depth > 0 && !check(TOKEN_EOF)) {
        depth += local_scan_depth_delta(parser.current, &parser.scanner);
        advance_token();
    }
}

/* Ramène un nom de propriété DSL service (forme FR, FR sans accent, ou EN)
 * à sa clé ASCII FR canon, via le catalogue bilingue. Le dispatch en aval
 * teste toujours la clé FR-ASCII ; cette normalisation rend l'invariant 3
 * (bilingue FR⇄EN) effectif côté parser sans dupliquer les orthographes EN.
 * Propriété inconnue : probe laissé tel quel (tombe dans la branche unknown). */
static void service_prop_canon_ascii(const char* kind, char* probe, size_t sz) {
    const OwlControlPropDef* pdef = owl_dsl_prop_find(kind, probe);
    if (pdef == NULL) return;
    const char* fr = pdef->nameAscii ? pdef->nameAscii : pdef->nameFR;
    if (fr == NULL) return;
    snprintf(probe, sz, "%s", fr);
}

/* Parse le bloc PROPRIETES ... FIN d'une OpérationHTTP. Collecte
 * method / chemin / responses / codeEtat, valide les enums, puis vérifie
 * CodeÉtat ∈ Réponses. Precondition : current = PROPRIETES. */
static void service_parse_operation_properties(OwlOperationDecl* op) {
    advance_token(); /* consume PROPRIETES */

    /* Position (pour l'erreur CodeÉtat) capturee au parse de CodeÉtat. */
    Token codeEtatTok; codeEtatTok.start = NULL; codeEtatTok.length = 0;
    codeEtatTok.line = 0; codeEtatTok.column = 0; codeEtatTok.type = TOKEN_ERROR;
    bool sawCodeEtat = false;

    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;

        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_current(E_SYNTAX_EXPECTED_PROP_NAME_IN_PROPRIETES);
            parser.panicMode = false;
            service_skip_to_eol();
            continue;
        }
        Token propTok = parser.current;
        char probe[64];
        int pn = scanner_strip_accents(propTok.start, propTok.length,
                                       probe, sizeof(probe));
        if (pn <= 0) { probe[0] = '\0'; }
        service_prop_canon_ascii("OperationHTTP", probe, sizeof(probe));
        advance_token(); /* consume prop name */

        if (!match_token(TOKEN_EQUAL)) {
            owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
            parser.panicMode = false;
            service_skip_to_eol();
            continue;
        }

        if (strcasecmp(probe, "Methode") == 0) {
            if (check(TOKEN_IDENTIFIER)) {
                Token v = parser.current;
                char buf[128];
                int n = v.length < 127 ? v.length : 127;
                memcpy(buf, v.start, (size_t)n); buf[n] = '\0';
                advance_token();
                if (owl_enum_contains_bilingual(&E_httpMethodes, buf)) {
                    free(op->method);
                    op->method = (char*)malloc((size_t)n + 1);
                    memcpy(op->method, buf, (size_t)n + 1);
                } else {
                    owl_emit_error_at(&v, E_SEM_DSL_SERVICE_METHOD_INVALID,
                                      "value", buf, NULL);
                    parser.panicMode = false;
                }
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "M\xc3\xa9thode",
                                  "expected", "une valeur de httpM\xc3\xa9thodes",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "Chemin") == 0) {
            /* [ (STRING littéral | IDENT param), ... ] */
            if (match_token(TOKEN_LEFT_BRACKET)) {
                if (!check(TOKEN_RIGHT_BRACKET)) {
                    do {
                        while (check(TOKEN_NEWLINE)) advance_token();
                        if (check(TOKEN_STRING)) {
                            Token st = parser.current;
                            const char* inner = st.start + 1;
                            int ilen = st.length >= 2 ? st.length - 2 : 0;
                            advance_token();
                            if (!service_path_segment_ok(inner, ilen)) {
                                char seg[128];
                                int sl = ilen < 127 ? ilen : 127;
                                memcpy(seg, inner, (size_t)sl); seg[sl] = '\0';
                                owl_emit_error_at(&st,
                                    E_SEM_DSL_SERVICE_PATH_SEGMENT_INVALID,
                                    "segment", seg, NULL);
                                parser.panicMode = false;
                                op->pathHadError = 1;
                            } else {
                                str_array_push(&op->pathSegments,
                                    &op->pathSegmentCount, inner, ilen);
                                path_segment_kind_push(op, 0);
                            }
                        } else if (check(TOKEN_IDENTIFIER)) {
                            /* Paramètre de chemin (référence un param de
                             * surRequête). Liaison vérifiée par le routeur. */
                            str_array_push(&op->pathSegments,
                                &op->pathSegmentCount,
                                parser.current.start, parser.current.length);
                            path_segment_kind_push(op, 1);
                            advance_token();
                        } else if (check(TOKEN_STAR)) {
                            /*  — marqueur catch-all glouton `*<nom>` :
                             * un parametre de chemin qui capture 1+ segments
                             * finaux. Les deux graphies `*reste` et `* reste`
                             * produisent la meme suite TOKEN_STAR +
                             * TOKEN_IDENTIFIER. La regle de position (dernier
                             * segment, un seul) est controlee par l'analyseur
                             * de routes ; le `*` n'est jamais une multiplication
                             * ici (position de segment d'une liste Chemin). */
                            Token star = parser.current;
                            advance_token(); /* consume '*' */
                            if (check(TOKEN_IDENTIFIER)) {
                                str_array_push(&op->pathSegments,
                                    &op->pathSegmentCount,
                                    parser.current.start, parser.current.length);
                                path_segment_kind_push(op, 2); /* catch-all */
                                advance_token();
                            } else {
                                owl_emit_error_at(&star,
                                    E_SEM_DSL_SERVICE_PATH_SEGMENT_INVALID,
                                    "segment", "*", NULL);
                                parser.panicMode = false;
                                op->pathHadError = 1;
                            }
                        } else {
                            break;
                        }
                    } while (match_token(TOKEN_COMMA));
                }
                match_token(TOKEN_RIGHT_BRACKET);
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "Chemin",
                                  "expected", "une liste de segments",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "Reponses") == 0) {
            if (match_token(TOKEN_LEFT_BRACKET)) {
                if (!check(TOKEN_RIGHT_BRACKET)) {
                    do {
                        while (check(TOKEN_NEWLINE)) advance_token();
                        if (check(TOKEN_IDENTIFIER)) {
                            Token v = parser.current;
                            char buf[128];
                            int n = v.length < 127 ? v.length : 127;
                            memcpy(buf, v.start, (size_t)n); buf[n] = '\0';
                            advance_token();
                            if (owl_enum_contains_bilingual(&E_httpCodeEtat, buf)) {
                                str_array_push(&op->responses,
                                    &op->responseCount, v.start, v.length);
                            } else {
                                owl_emit_error_at(&v, E_SEM_DSL_ENUM_VALUE_INVALID,
                                    "value", buf,
                                    "enumName", "httpCode\xc3\x89tat", NULL);
                                parser.panicMode = false;
                            }
                        } else {
                            break;
                        }
                    } while (match_token(TOKEN_COMMA));
                }
                match_token(TOKEN_RIGHT_BRACKET);
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "R\xc3\xa9ponses",
                                  "expected", "une liste de httpCode\xc3\x89tat",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "CodeEtat") == 0) {
            if (check(TOKEN_IDENTIFIER)) {
                Token v = parser.current;
                char buf[128];
                int n = v.length < 127 ? v.length : 127;
                memcpy(buf, v.start, (size_t)n); buf[n] = '\0';
                advance_token();
                if (owl_enum_contains_bilingual(&E_httpCodeEtat, buf)) {
                    free(op->codeEtat);
                    op->codeEtat = (char*)malloc((size_t)n + 1);
                    memcpy(op->codeEtat, buf, (size_t)n + 1);
                    codeEtatTok = v;
                    sawCodeEtat = true;
                } else {
                    owl_emit_error_at(&v, E_SEM_DSL_ENUM_VALUE_INVALID,
                        "value", buf, "enumName", "httpCode\xc3\x89tat", NULL);
                    parser.panicMode = false;
                }
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "Code\xc3\x89tat",
                                  "expected", "une valeur de httpCode\xc3\x89tat",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "Requete") == 0) {
            /* Query : liste d'identifiants referencant des params de
             * surRequête (source = query). Grammaire fine (contraintes,
             * types) reportée ; on collecte les noms pour la liaison. */
            if (match_token(TOKEN_LEFT_BRACKET)) {
                if (!check(TOKEN_RIGHT_BRACKET)) {
                    do {
                        while (check(TOKEN_NEWLINE)) advance_token();
                        if (check(TOKEN_IDENTIFIER)) {
                            str_array_push(&op->queryParams,
                                &op->queryParamCount,
                                parser.current.start, parser.current.length);
                            advance_token();
                        } else {
                            break;
                        }
                    } while (match_token(TOKEN_COMMA));
                }
                match_token(TOKEN_RIGHT_BRACKET);
            } else {
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "Authentification") == 0) {
            /*  — opt-out par operation. Seule httpAuthAucune a un sens
             * au niveau operation en lot 1 : elle exempte l'operation du hook
             * surAuthentification du service (login / health public). Toute autre
             * valeur d'enum est acceptee syntaxiquement mais n'active pas
             * l'opt-out (surcharge de schema = chantier aval). */
            if (check(TOKEN_IDENTIFIER)) {
                Token v = parser.current;
                char buf[128];
                int n = v.length < 127 ? v.length : 127;
                memcpy(buf, v.start, (size_t)n); buf[n] = '\0';
                advance_token();
                if (owl_enum_contains_bilingual(&E_httpAuthentification, buf)) {
                    if (strcasecmp(buf, "httpAuthAucune") == 0 ||
                        strcasecmp(buf, "httpAuthNone") == 0) {
                        op->authOptOut = 1;
                    }
                } else {
                    owl_emit_error_at(&v, E_SEM_DSL_SERVICE_AUTH_INVALID,
                                      "value", buf, NULL);
                    parser.panicMode = false;
                }
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "Authentification",
                                  "expected", "une valeur de httpAuthentification",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "TypeContenu") == 0) {
            /*  — type de contenu du corps. Seule la valeur multipart
             * a un effet en lot 1 : elle arme le contrat d'upload (verif
             * bidirectionnelle avec les params FichierTéléversé). Toute autre
             * valeur d'enum est acceptee syntaxiquement, sans armer le contrat. */
            if (check(TOKEN_IDENTIFIER)) {
                Token v = parser.current;
                char buf[128];
                int n = v.length < 127 ? v.length : 127;
                memcpy(buf, v.start, (size_t)n); buf[n] = '\0';
                advance_token();
                if (owl_enum_contains_bilingual(&E_typeMime, buf)) {
                    if (strcasecmp(buf, "typeMimeFormulaireMultiPartie") == 0 ||
                        strcasecmp(buf, "mimeTypeMultipartForm") == 0) {
                        op->contentTypeMultipart = 1;
                    }
                } else {
                    owl_emit_error_at(&v, E_SEM_DSL_ENUM_VALUE_INVALID,
                        "value", buf, "enumName", "typeMime", NULL);
                    parser.panicMode = false;
                }
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "TypeContenu",
                                  "expected", "une valeur de typeMime",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "ExclureDeOpenAPI") == 0) {
            /*  — booleen : Vrai retire l'operation du document OpenAPI
             * genere (routage runtime inchange). Defaut Faux (documentee). */
            if (check(TOKEN_VRAI) || check(TOKEN_FAUX)) {
                op->excludeOpenAPI = check(TOKEN_VRAI) ? 1 : 0;
                advance_token();
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "ExclureDeOpenAPI",
                                  "expected", "Vrai ou Faux", NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "Flux") == 0) {
            /*  — mode de diffusion progressive : une valeur de httpFlux
             * (fluxSSE / fluxOctets). Absente = reponse normale bufferisee. En P1
             * la valeur est validee et stockee (portee jusqu'a la route runtime),
             * sans activer de comportement de flux (3e mode d'execution = P3). */
            if (check(TOKEN_IDENTIFIER)) {
                Token v = parser.current;
                char buf[128];
                int n = v.length < 127 ? v.length : 127;
                memcpy(buf, v.start, (size_t)n); buf[n] = '\0';
                advance_token();
                if (owl_enum_contains_bilingual(&E_httpFlux, buf)) {
                    free(op->flux);
                    op->flux = (char*)malloc((size_t)n + 1);
                    memcpy(op->flux, buf, (size_t)n + 1);
                } else {
                    owl_emit_error_at(&v, E_SEM_DSL_ENUM_VALUE_INVALID,
                        "value", buf, "enumName", "httpFlux", NULL);
                    parser.panicMode = false;
                }
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "Flux",
                                  "expected", "une valeur de httpFlux",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "DelaiMax") == 0) {
            /*  — borne applicative de duree d'un flux, en secondes.
             * Entier positif ou nul (0 = illimite, defaut). Un signe negatif
             * n'a pas de sens (refuse). Portee jusqu'a la route runtime ; le
             * timer reacteur qui l'applique est P5. */
            if (check(TOKEN_MINUS)) {
                Token neg = parser.current;
                advance_token(); /* consume '-' */
                if (check(TOKEN_INTEGER)) advance_token();
                owl_emit_error_at(&neg, E_SEM_DSL_SERVICE_DELAIMAX_INVALID,
                                  NULL);
                parser.panicMode = false;
            } else if (check(TOKEN_INTEGER)) {
                Token v = parser.current;
                char buf[32];
                int n = v.length < 31 ? v.length : 31;
                memcpy(buf, v.start, (size_t)n); buf[n] = '\0';
                advance_token();
                op->delaiMax = (int)strtol(buf, NULL, 10);
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "D\xc3\xa9laiMax",
                                  "expected", "un entier positif ou nul (secondes)",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else {
            char prop[128];
            int prl = propTok.length < 127 ? propTok.length : 127;
            memcpy(prop, propTok.start, (size_t)prl); prop[prl] = '\0';
            owl_emit_error_at(&propTok, E_SEM_DSL_OPERATION_PROP_UNKNOWN,
                              "prop", prop, NULL);
            parser.panicMode = false;
            service_skip_to_eol();
        }
    }

    /* CodeÉtat ∈ Réponses (vérifié après collecte complète du bloc). */
    if (sawCodeEtat && op->codeEtat != NULL) {
        char want[256];
        service_canon_key(op->codeEtat, (int)strlen(op->codeEtat),
                          want, sizeof(want));
        bool found = false;
        for (int i = 0; i < op->responseCount; i++) {
            char have[256];
            service_canon_key(op->responses[i], (int)strlen(op->responses[i]),
                              have, sizeof(have));
            if (strcmp(have, want) == 0) { found = true; break; }
        }
        if (!found) {
            char buf[128];
            int bl = codeEtatTok.length < 127 ? codeEtatTok.length : 127;
            memcpy(buf, codeEtatTok.start, (size_t)bl); buf[bl] = '\0';
            owl_emit_error_at(&codeEtatTok,
                E_SEM_DSL_SERVICE_CODE_NOT_IN_RESPONSES, "value", buf, NULL);
            parser.panicMode = false;
        }
    }

    if (!match_token(TOKEN_FIN)) {
        owl_emit_error_current(E_SYNTAX_EXP_FIN_PROPRIETES);
    }
}

/* Parse une OpérationHTTP : `<nom> est une OpérationHTTP` déjà reconnu, on
 * entre avec `opName` capturé et le mot-clé OpérationHTTP consommé. */
static void service_operation_declaration(OwlServiceDecl* svc, Token opName) {
    /* Doublon de nom d'opération dans ce service. */
    char opAscii[128];
    int oan = scanner_strip_accents(opName.start, opName.length,
                                    opAscii, sizeof(opAscii));
    if (oan <= 0) { oan = opName.length < 127 ? opName.length : 127;
                    memcpy(opAscii, opName.start, (size_t)oan); }
    opAscii[oan] = '\0';
    bool dup = false;
    if (svc != NULL) {
        for (int i = 0; i < svc->operationCount; i++) {
            char exist[128];
            service_canon_key(svc->operations[i]->name,
                              (int)strlen(svc->operations[i]->name),
                              exist, sizeof(exist));
            char cand[128];
            service_canon_key(opName.start, opName.length, cand, sizeof(cand));
            if (strcmp(exist, cand) == 0) { dup = true; break; }
        }
    }
    if (dup) {
        char nm[128];
        int nl = opName.length < 127 ? opName.length : 127;
        memcpy(nm, opName.start, (size_t)nl); nm[nl] = '\0';
        owl_emit_error_at(&opName, E_SEM_DSL_OPERATION_NAME_DUPLICATE,
                          "name", nm, NULL);
        parser.panicMode = false;
    }

    char opNameBuf[128];
    int nl = opName.length < 127 ? opName.length : 127;
    memcpy(opNameBuf, opName.start, (size_t)nl); opNameBuf[nl] = '\0';
    OwlOperationDecl* op = (svc != NULL && !dup)
        ? owl_service_decl_add_operation(svc, opNameBuf, opName.line)
        : NULL;
    /* decl jetable si pas de service ou doublon : on parse quand meme pour ne
     * pas casser le flux. */
    OwlOperationDecl scratch;
    if (op == NULL) { memset(&scratch, 0, sizeof(scratch)); op = &scratch; }

    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
        if (check(TOKEN_PROPRIETES)) {
            service_parse_operation_properties(op);
        } else if (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION)) {
            service_parse_procedure(svc, op);
        } else {
            advance_token();
            parser.panicMode = false;
        }
    }
    if (!match_token(TOKEN_FIN)) {
        owl_emit_error_current(E_SYNTAX_EXP_FIN_OPERATION);
    }

    if (op == &scratch) {
        /* Libere le scratch (jamais rattache au registre). */
        free(scratch.name);
        free(scratch.method);
        free(scratch.codeEtat);
        for (int i = 0; i < scratch.pathSegmentCount; i++) free(scratch.pathSegments[i]);
        free(scratch.pathSegments);
        free(scratch.pathSegmentIsParam);
        for (int i = 0; i < scratch.responseCount; i++) free(scratch.responses[i]);
        free(scratch.responses);
        for (int i = 0; i < scratch.procParamCount; i++) {
            free(scratch.procParams[i].name);
            free(scratch.procParams[i].typeName);
        }
        free(scratch.procParams);
        free(scratch.procName);
        free(scratch.procReturnType);
    }
}

/*  — un host est-il une IPv4 STRICTE dans 127.0.0.0/8 ? Exige
 * exactement 4 octets decimaux 0-255 separes par '.', 1er octet == 127, et
 * RIEN d'autre sur [h, h+len) : pas de 5e label, pas de suffixe DNS, pas de
 * caractere non-chiffre/point, pas de zero de tete (forme ambigue rejetee).
 * Fail-closed : au moindre ecart de forme -> false. `h`/`len` = host deja
 * ampute du userinfo et du port. Interdit d'accepter "127.evil.com" ou
 * "127.0.0.1.attacker.io" (noms DNS qui satisfaisaient l'ancien match prefixe). */
static bool service_host_est_ipv4_loopback(const char* h, size_t len) {
    int premier = 0;
    size_t i = 0;
    for (int octet = 0; octet < 4; octet++) {
        if (i >= len || h[i] < '0' || h[i] > '9') return false;
        int val = 0, chiffres = 0;
        while (i < len && h[i] >= '0' && h[i] <= '9') {
            val = val * 10 + (h[i] - '0');
            if (++chiffres > 3 || val > 255) return false;   /* >255 ou 4 chiffres */
            i++;
        }
        if (chiffres > 1 && h[i - chiffres] == '0') return false;  /* zero de tete */
        if (octet == 0) premier = val;
        if (octet < 3) {
            if (i >= len || h[i] != '.') return false;
            i++;
        }
    }
    if (i != len) return false;            /* residu apres le 4e octet -> rejet */
    return premier == 127;
}

/*  — valide la FORME d'une URL JWKS a la COMPILATION (l'URL est un
 * litteral statique). https:// est accepte vers n'importe quel hote ; http://
 * n'est tolere que vers une adresse locale (127.0.0.0/8 STRICT, localhost,
 * [::1]) — sans TLS, une cle de verification recuperee sur un hote distant
 * serait falsifiable en clair sur le fil. Toute autre forme (scheme
 * absent/autre, http distant, host DNS deguise en loopback) -> false, rejet
 * sans jamais tenter la moindre connexion reseau. `url` NUL-termine. */
static bool service_jwks_url_forme_ok(const char* url) {
    if (url == NULL) return false;
    const char* auth;
    if (strncasecmp(url, "https://", 8) == 0) {
        return true;                       /* TLS : hote distant autorise */
    } else if (strncasecmp(url, "http://", 7) == 0) {
        auth = url + 7;
    } else {
        return false;                      /* scheme absent ou non supporte */
    }
    /* Fin de l'authority : jusqu'a '/' '?' '#' ou fin de chaine. Le ':' n'est
     * PAS un delimiteur ici (il separe userinfo user:pass ou host:port). */
    size_t authlen = 0;
    while (auth[authlen] != '\0' && auth[authlen] != '/' &&
           auth[authlen] != '?'  && auth[authlen] != '#') authlen++;
    /* userinfo : le vrai host est APRES le DERNIER '@'. "127.0.0.1@evil.com"
     * a pour host reel "evil.com", pas "127.0.0.1". */
    size_t hstart = 0;
    for (size_t i = 0; i < authlen; i++) {
        if (auth[i] == '@') hstart = i + 1;
    }
    const char* h = auth + hstart;
    size_t hspan = authlen - hstart;
    if (hspan == 0) return false;
    /* IPv6 litterale bracketee : "[...]" suivi eventuellement de ":port". */
    if (h[0] == '[') {
        size_t j = 1;
        while (j < hspan && h[j] != ']') j++;
        if (j >= hspan) return false;                   /* ']' fermant absent */
        if (j + 1 != hspan && h[j + 1] != ':') return false; /* que ':port' apres ']' */
        size_t innerlen = j - 1;
        if (innerlen == 3 && strncmp(h + 1, "::1", 3) == 0) return true;
        return false;
    }
    /* Host non-bracketee : ampute le port sur le premier ':'. */
    size_t hlen = 0;
    while (hlen < hspan && h[hlen] != ':') hlen++;
    if (hlen == 0) return false;
    if (hlen == 9 && strncasecmp(h, "localhost", 9) == 0) return true;
    if (service_host_est_ipv4_loopback(h, hlen))          return true;
    return false;
}

/* Parse le bloc PROPRIETES ... FIN d'un ServiceREST (UrlBase,
 * Authentification). Precondition : current = PROPRIETES. */
static void service_parse_service_properties(OwlServiceDecl* svc) {
    advance_token(); /* consume PROPRIETES */
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;

        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_current(E_SYNTAX_EXPECTED_PROP_NAME_IN_PROPRIETES);
            parser.panicMode = false;
            service_skip_to_eol();
            continue;
        }
        Token propTok = parser.current;
        char probe[64];
        int pn = scanner_strip_accents(propTok.start, propTok.length,
                                       probe, sizeof(probe));
        if (pn <= 0) probe[0] = '\0';
        service_prop_canon_ascii("ServiceREST", probe, sizeof(probe));
        advance_token();

        if (!match_token(TOKEN_EQUAL)) {
            owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
            parser.panicMode = false;
            service_skip_to_eol();
            continue;
        }

        if (strcasecmp(probe, "UrlBase") == 0) {
            if (match_token(TOKEN_LEFT_BRACKET)) {
                if (!check(TOKEN_RIGHT_BRACKET)) {
                    do {
                        while (check(TOKEN_NEWLINE)) advance_token();
                        if (check(TOKEN_STRING)) {
                            Token st = parser.current;
                            const char* inner = st.start + 1;
                            int ilen = st.length >= 2 ? st.length - 2 : 0;
                            advance_token();
                            if (!service_path_segment_ok(inner, ilen)) {
                                char seg[128];
                                int sl = ilen < 127 ? ilen : 127;
                                memcpy(seg, inner, (size_t)sl); seg[sl] = '\0';
                                owl_emit_error_at(&st,
                                    E_SEM_DSL_SERVICE_PATH_SEGMENT_INVALID,
                                    "segment", seg, NULL);
                                parser.panicMode = false;
                            } else if (svc != NULL) {
                                str_array_push(&svc->urlBase,
                                    &svc->urlBaseCount, inner, ilen);
                            }
                        } else {
                            break;
                        }
                    } while (match_token(TOKEN_COMMA));
                }
                match_token(TOKEN_RIGHT_BRACKET);
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "UrlBase",
                                  "expected", "une liste de segments",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "Authentification") == 0) {
            if (check(TOKEN_IDENTIFIER)) {
                Token v = parser.current;
                char buf[128];
                int n = v.length < 127 ? v.length : 127;
                memcpy(buf, v.start, (size_t)n); buf[n] = '\0';
                advance_token();
                if (owl_enum_contains_bilingual(&E_httpAuthentification, buf)) {
                    if (svc != NULL) {
                        free(svc->authentication);
                        svc->authentication = (char*)malloc((size_t)n + 1);
                        memcpy(svc->authentication, buf, (size_t)n + 1);
                    }
                    /* Securite : un schema protecteur (Bearer / Basique / CleAPI)
                     * n'est reellement applique que si le service fournit un hook
                     * surAuthentification. On MEMORISE ici la position
                     * du schema ; le warning « declaree mais pas appliquee » est
                     * emis DIFFERE en fin de parse, uniquement si aucun hook n'a
                     * ete declare (le hook peut apparaitre apres les proprietes).
                     * httpAuthAucune ne promet rien -> jamais de warning
                     * (FR = httpAuthAucune, EN = httpAuthNone). */
                    if (svc != NULL &&
                        strcasecmp(buf, "httpAuthAucune") != 0 &&
                        strcasecmp(buf, "httpAuthNone") != 0) {
                        svc->authSchemeStart      = v.start;
                        svc->authSchemeLen        = v.length;
                        svc->authSchemeLine       = v.line;
                        svc->authSchemeCol        = v.column;
                        svc->authSchemeProtective = 1;
                    }
                } else {
                    owl_emit_error_at(&v, E_SEM_DSL_SERVICE_AUTH_INVALID,
                                      "value", buf, NULL);
                    parser.panicMode = false;
                }
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "Authentification",
                                  "expected", "une valeur de httpAuthentification",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "ClePubliqueJWT") == 0 ||
                   strcasecmp(probe, "EmetteurJWT") == 0 ||
                   strcasecmp(probe, "AudienceJWT") == 0) {
            /*  — chaine libre : cle publique RS256 (PEM, souvent en
             * chaine backtick multiligne) ou emetteur JWT attendu. Le contenu
             * brut est copie tel quel (delimiteurs retires), sans traitement
             * d'echappement — le PEM doit rester byte-pour-byte.
             *  — audience attendue (claim aud) : meme patron chaine. */
            bool isKey    = (strcasecmp(probe, "ClePubliqueJWT") == 0);
            bool isIssuer = (strcasecmp(probe, "EmetteurJWT") == 0);
            if (check(TOKEN_STRING) || check(TOKEN_BACKTICK_STRING)) {
                Token st = parser.current;
                const char* inner = st.start + 1;
                int ilen = st.length >= 2 ? st.length - 2 : 0;
                advance_token();
                if (svc != NULL) {
                    char** slot = isKey    ? &svc->jwtPublicKeyPem :
                                  isIssuer ? &svc->jwtIssuer       :
                                             &svc->jwtAudience;
                    free(*slot);
                    *slot = (char*)malloc((size_t)ilen + 1);
                    memcpy(*slot, inner, (size_t)ilen);
                    (*slot)[ilen] = '\0';
                }
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", isKey    ? "ClePubliqueJWT" :
                                          isIssuer ? "EmetteurJWT"    : "AudienceJWT",
                                  "expected", "une chaine",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else if (strcasecmp(probe, "URLJWKS") == 0) {
            /*  — URL d'un jeu de cles JWKS (source de cle dynamique).
             * Meme patron chaine que ClePubliqueJWT. La FORME de l'URL est
             * validee ici (litteral statique) : http:// distant refuse net,
             * avant toute connexion reseau. L'exclusivite avec ClePubliqueJWT
             * est verifiee en fin de parse (les deux props peuvent apparaitre
             * dans n'importe quel ordre). */
            if (check(TOKEN_STRING) || check(TOKEN_BACKTICK_STRING)) {
                Token st = parser.current;
                const char* inner = st.start + 1;
                int ilen = st.length >= 2 ? st.length - 2 : 0;
                advance_token();
                char* urlbuf = (char*)malloc((size_t)ilen + 1);
                memcpy(urlbuf, inner, (size_t)ilen);
                urlbuf[ilen] = '\0';
                if (!service_jwks_url_forme_ok(urlbuf)) {
                    owl_emit_error_at(&st, E_SEM_DSL_SERVICE_JWKS_HTTP_INTERDIT, NULL);
                    parser.panicMode = false;
                    free(urlbuf);
                } else if (svc != NULL) {
                    free(svc->jwtJwksUrl);
                    svc->jwtJwksUrl = urlbuf;
                } else {
                    free(urlbuf);
                }
            } else {
                owl_emit_error_at(&propTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                                  "prop", "URLJWKS",
                                  "expected", "une chaine",
                                  NULL);
                parser.panicMode = false;
                service_skip_to_eol();
            }
        } else {
            char prop[128];
            int prl = propTok.length < 127 ? propTok.length : 127;
            memcpy(prop, propTok.start, (size_t)prl); prop[prl] = '\0';
            owl_emit_error_at(&propTok, E_SEM_DSL_SERVICE_PROP_UNKNOWN,
                              "prop", prop, NULL);
            parser.panicMode = false;
            service_skip_to_eol();
        }
    }
    if (!match_token(TOKEN_FIN)) {
        owl_emit_error_current(E_SYNTAX_EXP_FIN_PROPRIETES);
    }
}

/*  — traduit une valeur httpMethodes (`httpGet`) en verbe HTTP
 * majuscule (`GET`) : retire le prefixe "http" et met le reste en majuscules.
 * out doit tenir >= 16. Retourne 0 si method est NULL/invalide. */
static int service_method_to_verb(const char* method, char* out, int outSz) {
    if (method == NULL) return 0;
    const char* p = method;
    if (strncasecmp(p, "http", 4) == 0) p += 4;
    int n = 0;
    while (*p != '\0' && n < outSz - 1) {
        out[n++] = (char)toupper((unsigned char)*p);
        p++;
    }
    out[n] = '\0';
    return n > 0;
}

/*  — enregistre au routeur RUNTIME les routes des operations dont le
 * handler surRequete a ete compile (op->handlerGlobal non NULL). Le chemin
 * canonique = "/" + UrlBase + segments litteraux de Chemin. Une route dont le
 * chemin porte un parametre est marquee hasParam (appariement litteral exact
 * seulement dans cette fondation ; le binding par nom est ). */
/* Segments canoniques d'une route : UrlBase (litteraux) puis Chemin (litteraux
 * + parametres). Ecrit dans des tableaux paralleles et rend le compte. Le
 * chemin joint (avec slashs) est ecrit dans `path`. */
#define OWL_SVC_REG_MAX_SEG 32
static int service_collect_segments(const OwlServiceDecl* svc,
                                    const OwlOperationDecl* op,
                                    const char* segs[OWL_SVC_REG_MAX_SEG],
                                    int isParam[OWL_SVC_REG_MAX_SEG],
                                    char* path, size_t pathCap) {
    int count = 0;
    int len = 0;
    for (int u = 0; u < svc->urlBaseCount && count < OWL_SVC_REG_MAX_SEG; u++) {
        segs[count]    = svc->urlBase[u];
        isParam[count] = 0;
        count++;
        len += snprintf(path + len, pathCap - (size_t)len, "/%s", svc->urlBase[u]);
        if (len >= (int)pathCap - 1) break;
    }
    for (int s = 0; s < op->pathSegmentCount && count < OWL_SVC_REG_MAX_SEG; s++) {
        int ip = (op->pathSegmentIsParam != NULL) ? op->pathSegmentIsParam[s] : 0;
        segs[count]    = op->pathSegments[s];
        isParam[count] = ip;
        count++;
        len += snprintf(path + len, pathCap - (size_t)len, "/%s", op->pathSegments[s]);
        if (len >= (int)pathCap - 1) break;
    }
    if (len == 0 && pathCap > 1) { path[0] = '/'; path[1] = '\0'; }
    return count;
}

/* Classe un parametre du handler vers sa source de liaison. Priorite : un nom
 * present comme segment parametre du chemin -> PATH (pathIndex renseigne) ;
 * sinon present dans Requete -> QUERY ; sinon type structure -> BODY (corps) ;
 * sinon QUERY par defaut (scalaire non declare : le controle statique strict
 * est un chantier aval, le binding reste tolerant ici). */
static int service_classify_param(const OwlOperationDecl* op,
                                  const OwlServiceProcParam* p,
                                  const char* segs[OWL_SVC_REG_MAX_SEG],
                                  const int isParam[OWL_SVC_REG_MAX_SEG],
                                  int segCount, int* pathIndex) {
    *pathIndex = -1;
    for (int s = 0; s < segCount; s++) {
        if (isParam[s] && segs[s] != NULL && strcmp(segs[s], p->name) == 0) {
            *pathIndex = s;
            return 0 /* OWL_SVC_SRC_PATH */;
        }
    }
    for (int q = 0; q < op->queryParamCount; q++) {
        if (op->queryParams[q] != NULL && strcmp(op->queryParams[q], p->name) == 0) {
            return 1 /* OWL_SVC_SRC_QUERY */;
        }
    }
    if (p->isStructured) return 2 /* OWL_SVC_SRC_BODY */;
    return 1 /* OWL_SVC_SRC_QUERY */;
}

static void service_register_runtime_routes(const OwlServiceDecl* svc) {
    for (int i = 0; i < svc->operationCount; i++) {
        const OwlOperationDecl* op = svc->operations[i];
        if (op->handlerGlobal == NULL) continue;

        char verb[16];
        if (!service_method_to_verb(op->method, verb, sizeof(verb))) continue;

        const char* segs[OWL_SVC_REG_MAX_SEG];
        int         isParam[OWL_SVC_REG_MAX_SEG];
        char        path[512];
        int segCount = service_collect_segments(svc, op, segs, isParam,
                                                path, sizeof(path));
        int hasParam = 0;
        for (int s = 0; s < segCount; s++) if (isParam[s]) hasParam = 1;

        int routeIdx = owl_service_runtime_add(verb, path, op->handlerGlobal, hasParam);
        if (routeIdx < 0) continue;

        /*  — contexte d'auth de la route : schema + hook au niveau
         * service, opt-out au niveau operation. L'executeur ne consulte que la
         * route appariee, donc chaque route porte sa propre copie. */
        owl_service_runtime_set_auth(routeIdx, svc->authentication,
                                     svc->authHandlerGlobal, op->authOptOut);
        /*  — hook surErreur (niveau service) recopie sur chaque route :
         * l'executeur ne consulte que la route appariee sur le crash du handler. */
        owl_service_runtime_set_error_hook(routeIdx, svc->errorHandlerGlobal);
        /*  — hook surAutorisation (niveau service) recopie sur chaque
         * route : invoque APRES l'authn, AVANT le binding. */
        owl_service_runtime_set_authz_hook(routeIdx, svc->authzHandlerGlobal);
        /*  — contexte JWT declaratif (cle publique + emetteur) recopie
         * sur chaque route : l'executeur valide le jeton sans hook.
         *  — audience attendue (claim aud) portee de meme. */
        owl_service_runtime_set_jwt(routeIdx, svc->jwtPublicKeyPem, svc->jwtJwksUrl,
                                    svc->jwtIssuer, svc->jwtAudience);
        /*  — CodeÉtat declare de l'operation resolu en entier HTTP via
         * le registre de constantes (meme source que l'OpenAPI, case+accent
         * insensible). Pilote le statut par defaut du chemin succes. 0 si non
         * declare -> l'executeur retombe sur 200. */
        if (op->codeEtat != NULL) {
            const OwlConstDef* cs = owl_registry_const_find(op->codeEtat);
            if (cs != NULL && IS_INTEGER(cs->value)) {
                owl_service_runtime_set_default_status(routeIdx,
                                                       (int)AS_INTEGER(cs->value));
            }
        }
        /*  — mode de flux (P1) : la route PORTE la valeur canon de
         * httpFlux et la borne DelaiMax, mais ne les EXECUTE pas encore (le 3e
         * mode d'execution streaming est P3). flux NULL = reponse normale. */
        owl_service_runtime_set_flux(routeIdx, op->flux, op->delaiMax);

        for (int s = 0; s < segCount; s++) {
            owl_service_runtime_add_segment(routeIdx, segs[s], isParam[s]);
        }
        /* Contrat de liaison : chaque parametre du handler dans l'ordre de
         * declaration, avec sa source (chemin/query/corps). */
        for (int pp = 0; pp < op->procParamCount; pp++) {
            const OwlServiceProcParam* p = &op->procParams[pp];
            int pathIndex = -1;
            int source = service_classify_param(op, p, segs, isParam,
                                                segCount, &pathIndex);
            /*  — nature du parametre FichierTéléversé portee jusqu'a la
             * route runtime : le serve-time doit distinguer une instance unique
             * d'un `tableau de` (element type perdu dans typeName == "tableau").
             * Le type scalaire porte lui-meme le nom FichierTéléversé/UploadedFile
             * (type_name_is_file_upload vrai) ; l'array a typeName container. */
            int fileUpload = 0 /* OWL_SVC_UPLOAD_NONE */;
            if (p->isFileUpload) {
                fileUpload = (p->typeName != NULL &&
                              type_name_is_file_upload(p->typeName,
                                                       (int)strlen(p->typeName)))
                             ? 1 /* SCALAR */ : 2 /* ARRAY */;
            }
            owl_service_runtime_add_param(routeIdx, p->name, source, p->typeName,
                                          p->isStructured, p->hasDefault, pathIndex,
                                          fileUpload);
        }
    }
}

/*  — le construct courant du corps service est-il `<Nom> est une
 * OperationHTTP` ? Peek non destructif (le nom peut etre un mot-cle, ).
 * Sert a distinguer une operation d'une globale / structure qui partagent le
 * prefixe `<Nom> est un(e) ...` et passent par le dispatch commun declaration(). */
static bool peek_service_body_is_operation(void) {
    if (!check(TOKEN_IDENTIFIER) && !token_lexeme_is_namelike(parser.current))
        return false;
    Scanner saved     = parser.scanner;
    Token   savedCur  = parser.current;
    Token   savedPrev = parser.previous;
    bool    savedXNL  = crossedNewline;
    bool    isOp      = false;
    advance_token();                 /* nom d'operation */
    if (check(TOKEN_EST) || check(TOKEN_SONT)) {
        advance_token();
        consume_en_a_an_filler();
        isOp = service_ident_is("OperationHTTP") ||
               service_ident_is("HTTPOperation");
    }
    parser.scanner   = saved;
    parser.current   = savedCur;
    parser.previous  = savedPrev;
    crossedNewline   = savedXNL;
    return isOp;
}

/* Point d'entrée : `<serviceName> est un ServiceREST` reconnu, mot-clé
 * ServiceREST consommé. Parse le corps jusqu'au FIN. */
static void service_rest_declaration(Token serviceName) {
    char nameBuf[128];
    int nl = serviceName.length < 127 ? serviceName.length : 127;
    memcpy(nameBuf, serviceName.start, (size_t)nl); nameBuf[nl] = '\0';

    /* Doublon de bloc service (même compilation / projet). */
    OwlServiceDecl* svc = owl_service_registry_add(nameBuf, serviceName.line);
    if (svc == NULL) {
        owl_emit_error_at(&serviceName, E_SEM_DSL_SERVICE_BLOCK_DUPLICATE,
                          "name", nameBuf, NULL);
        parser.panicMode = false;
        /* On parse le corps sans l'enregistrer (svc reste NULL). */
    }

    bool propsSeen = false;
    /*  — corps du bloc service = contexte top-level en mode GLOBAL
     * (meme mecanique que Projet/Collection). Les declarations partagees
     * (Structure DTO co-localisee, globales du fichier) passent par le
     * dispatch commun declaration() ; operations HTTP et events service
     * gardent leur chemin dedie. Ordre PROPRIETES / globales / structures /
     * operations / events libre. */
    bool savedConfineSvc = g_toplevel_confine;
    g_toplevel_confine = false;
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;

        if (check(TOKEN_PROPRIETES)) {
            if (propsSeen) {
                owl_emit_error_current(E_SYNTAX_DUPLICATE_PROPRIETES_WINDOW);
                parser.panicMode = false;
            }
            propsSeen = true;
            service_parse_service_properties(svc);
            continue;
        }

        /* Events service (surErreur / surAuthentification / surAutorisation /
         * FinInitialisation / Fermeture) : le gating vient du catalogue partage
         * dans service_parse_auth_procedure (une PROCEDURE non-event y est
         * rejetee, E_SYNTAX_SERVICE_EVENT_UNKNOWN). Un helper libre vit
         * ailleurs, comme le corps Projet interdit les procs utilisateur. */
        if (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION)) {
            service_parse_auth_procedure(svc);
            continue;
        }

        /* `<Nom> est une OperationHTTP ... FIN` : chemin dedie (nom possiblement
         * mot-cle, ). Peek non destructif pour le distinguer d'une
         * globale / structure au meme prefixe `<Nom> est un(e) ...`. */
        if (peek_service_body_is_operation()) {
            Token opName = parser.current;
            advance_token();          /* nom d'operation */
            advance_token();          /* est / sont */
            consume_en_a_an_filler();
            advance_token();          /* OpérationHTTP / HTTPOperation */
            service_operation_declaration(svc, opName);
            continue;
        }

        /* Reste = declarations top-level partagees (Structure, globales) via le
         * dispatch commun, mode GLOBAL. declaration() garantit l'avance du
         * curseur (meme sur un construct invalide : erreur + resync). */
        declaration();
        while (check(TOKEN_NEWLINE)) advance_token();
    }
    g_toplevel_confine = savedConfineSvc;

    if (!match_token(TOKEN_FIN)) {
        owl_emit_error_current(E_SYNTAX_EXP_FIN_SERVICE);
    }

    /* Analyse statique des routes du service : liaison des parametres de
     * chemin a surRequete + detection des conflits (comparaison par paires).
     * Portee par service : UrlBase prefixe, deux services distincts ne
     * conflictent pas. */
    if (svc != NULL) {
        parser.panicMode = false; /* les diagnostics de l'analyseur ne doivent
                                   * pas etre avales par un panic residuel. */
        /*  — schema JWT declaratif : le framework valide lui-meme le
         * jeton (signature / exp / iss), l'app ne fournit AUCUN code d'authn.
         * Fournir surAuthentification EN PLUS est contradictoire -> erreur. Le
         * hook pouvant suivre les proprietes, la decision est prise ici. */
        bool authIsJwt = svc->authentication != NULL &&
                         (strcasecmp(svc->authentication, "httpAuthJWT") == 0);
        if (authIsJwt && svc->authHandlerGlobal != NULL) {
            Token schemeTok;
            schemeTok.type   = TOKEN_IDENTIFIER;
            schemeTok.start  = svc->authSchemeStart;
            schemeTok.length = svc->authSchemeLen;
            schemeTok.line   = svc->authSchemeLine;
            schemeTok.column = svc->authSchemeCol;
            owl_emit_error_at(&schemeTok, E_SEM_DSL_SERVICE_JWT_HOOK_INTERDIT, NULL);
            parser.panicMode = false;
        }

        /*  — exclusivite des deux sources de cle JWT : URLJWKS (fetch
         * distant + rotation) et ClePubliqueJWT (cle statique pinnee) sont
         * contradictoires. Poser les deux -> erreur (invariant de securite :
         * une seule source de verite pour la cle de verification). */
        if (svc->jwtJwksUrl != NULL && svc->jwtPublicKeyPem != NULL) {
            Token schemeTok;
            schemeTok.type   = TOKEN_IDENTIFIER;
            schemeTok.start  = svc->authSchemeStart;
            schemeTok.length = svc->authSchemeLen;
            schemeTok.line   = svc->authSchemeLine;
            schemeTok.column = svc->authSchemeCol;
            owl_emit_error_at(&schemeTok, E_SEM_DSL_SERVICE_JWKS_CLE_EXCLUSIVE, NULL);
            parser.panicMode = false;
        }

        /*  — warning DIFFERE : un schema protecteur (Bearer / Basique /
         * CleAPI) SANS hook surAuthentification laisse le service non protege
         * a l'execution. Le hook pouvant suivre les proprietes, la decision est
         * prise ici, une fois tout le corps parse. Avec hook -> auth vivante,
         * pas de warning. Exception JWT : la protection ne vient
         * PAS d'un hook mais de la cle publique declaree ; un service JWT avec
         * cle est donc protege sans hook -> pas de faux warning. */
        if (svc->authSchemeProtective && svc->authHandlerGlobal == NULL &&
            !(authIsJwt && (svc->jwtPublicKeyPem != NULL ||
                            svc->jwtJwksUrl != NULL))) {
            Token schemeTok;
            schemeTok.type   = TOKEN_IDENTIFIER;
            schemeTok.start  = svc->authSchemeStart;
            schemeTok.length = svc->authSchemeLen;
            schemeTok.line   = svc->authSchemeLine;
            schemeTok.column = svc->authSchemeCol;
            char scheme[128];
            int sl = svc->authSchemeLen < 127 ? svc->authSchemeLen : 127;
            memcpy(scheme, svc->authSchemeStart, (size_t)sl); scheme[sl] = '\0';
            owl_emit_warning_at(&schemeTok, W_SEM_DSL_SERVICE_AUTH_NON_APPLIQUEE,
                                "scheme", scheme, NULL);
        }
        owl_http_route_analyze_service(svc);
        /*  — publie les routes au registre runtime (survit au reset
         * de compilation, consulte par l'executeur a l'execution). */
        service_register_runtime_routes(svc);
    }
}

static void var_declaration_after_est(Token varName) {
    /*  lot 1b — isolation scope champ (OPTION A, prefixe statique).
     * Une variable declaree au niveau 0 du body d'un champ (scopeDepth 0 +
     * g_current_control_decl != NULL) est renommee `<ctrl>__<var>` AVANT
     * tout traitement : declare_variable / typed_globals_add /
     * identifier_constant / define_variable l'utilisent alors de maniere
     * uniforme, et g_declaredGlobals enregistre la forme prefixee. Le nom nu
     * n'entre jamais dans g_declaredGlobals -> un champ voisin / la fenetre
     * qui le reference tombe en erreur compile "variable inconnue". Le buffer
     * est static : pas de reentrance possible au niveau 0 d'un meme champ. */
    static char fieldVarBuf[256];
    if (current->scopeDepth == 0 && g_current_control_decl != NULL) {
        int pn = control_var_prefix(varName.start, varName.length,
                                    fieldVarBuf, sizeof(fieldVarBuf));
        if (pn > 0) {
            varName.start  = fieldVarBuf;
            varName.length = pn;
        }
    }
    /*  — isolation scope element (Fenetre/Etat) : une variable
     * declaree au niveau body de l'element (scopeDepth 0, contexte element,
     * HORS controle) est renommee `<ELEM>$<var>` AVANT tout traitement, comme
     * le `<ctrl>__<var>` ci-dessus. Le nom nu n'entre jamais dans
     * g_declaredGlobals -> invisible en nom nu depuis le script (portee
     * ). On enregistre aussi (element, name) dans g_element_globals
     * pour servir l'acces qualifie `FEN_X.gNom` du fichier courant (le
     * cross-fichier passe par hydrate). Le buffer est static, pas de
     * reentrance au niveau 0 d'un meme element. */
    else if (current->scopeDepth == 0
             && !g_toplevel_confine   /*  : LOCAL -> pas de globale d'element */
             && g_current_control_decl == NULL
             && g_current_element_name[0] != '\0') {
        /* Peek le type pour exclure les MEMBRES d'element addressables en nom
         * nu depuis le script (pas des globales scopees). Un `GR_X est un
         * Groupe` ou `LIB_X est un Champ` est un membre de l'element, expose
         * globalement comme un controle — il ne doit PAS etre mangle. Seules
         * les VRAIES globales de donnees (entier, chaine, type user...) le
         * sont. Clone du scanner pour ne rien consommer. */
        Scanner peekScan      = parser.scanner;
        Token   peekCur       = parser.current;
        Token   peekPrev      = parser.previous;
        bool    peekXNL       = crossedNewline;
        consume_en_a_an_filler();
        bool isElementMember =
            (check(TOKEN_IDENTIFIER) &&
             ((parser.current.length == 6 &&
               strncasecmp(parser.current.start, "Groupe", 6) == 0) ||
              (parser.current.length == 5 &&
               strncasecmp(parser.current.start, "Group", 5) == 0) ||
              (parser.current.length == 5 &&
               strncasecmp(parser.current.start, "Champ", 5) == 0) ||
              (parser.current.length == 5 &&
               strncasecmp(parser.current.start, "Field", 5) == 0)));
        parser.scanner  = peekScan;
        parser.current  = peekCur;
        parser.previous = peekPrev;
        crossedNewline  = peekXNL;
        if (!isElementMember) {
            element_globals_register(g_current_element_name,
                                     (int)strlen(g_current_element_name),
                                     varName.start, varName.length);
            int pn = element_var_prefix(g_current_element_name,
                                        varName.start, varName.length,
                                        fieldVarBuf, sizeof(fieldVarBuf));
            if (pn > 0) {
                varName.start  = fieldVarBuf;
                varName.length = pn;
            }
        }
    }
    /*  — membre GLOBAL d'un bloc CollectionDeProcédures : stockage
     * mangled `<COL>$<var>` (slot distinct par collection) + enregistrement
     * EXPOSE (nom nu resout, sauf futur LOCAL). Parallele DEDIE au chemin
     * element ci-dessus qui, lui, ENCAPSULE.  — le peek n'exclut plus
     * que la CLASSE : ENUMERATION/STRUCTURE/COMBINAISON/INTERFACE sont des
     * membres-type EXPOSES (slot mangled `<COL>$<Type>`, qualifiable `COL.Type`
     * + resoluble en nom nu quand non-ambigu). Deux collections declarant
     * `stForme` ont ainsi deux slots distincts (case_071). */
    else if (current->scopeDepth == 0
             && !g_toplevel_confine   /*  : LOCAL -> pas de membre de collection */
             && g_current_control_decl == NULL
             && g_current_element_name[0] == '\0'
             && g_current_collection_name[0] != '\0') {
        Scanner peekScan = parser.scanner;
        Token   peekCur  = parser.current;
        Token   peekPrev = parser.previous;
        bool    peekXNL  = crossedNewline;
        consume_en_a_an_filler();
        /*  — seule la CLASSE reste un type NON-membre (1 classe = 1
         * fichier). COMBINAISON/INTERFACE (comme l'ENUMERATION depuis )
         * deviennent des membres-type exposes : manglees `<COL>$<Type>` +
         * enregistrees (qualif + nom nu). La STRUCTURE est manglee dans
         * struct_declaration (elle court-circuite ce chemin, cf. le dispatch
         * TOKEN_STRUCTURE au niveau statement).  — une collection
         * imbriquee n'est pas davantage un membre : elle est refusee un peu
         * plus bas, et la mangler ferait fuiter `<COL>$<COL>` dans le message. */
        bool isBlockType = check(TOKEN_CLASSE)
                           || (check(TOKEN_IDENTIFIER)
                               && token_is_collection_kw(parser.current.start,
                                                         parser.current.length));
        parser.scanner  = peekScan;
        parser.current  = peekCur;
        parser.previous = peekPrev;
        crossedNewline  = peekXNL;
        if (!isBlockType) {
            collection_member_register(g_current_collection_name,
                                       (int)strlen(g_current_collection_name),
                                       varName.start, varName.length, true);
            int pn = collection_var_prefix(g_current_collection_name,
                                           varName.start, varName.length,
                                           fieldVarBuf, sizeof(fieldVarBuf));
            if (pn > 0) {
                varName.start  = fieldVarBuf;
                varName.length = pn;
            }
        }
    }

    consume_en_a_an_filler();

    /* Check what type follows */
    bool isArray = check(TOKEN_TABLEAU);
    int  arrayPresize = 0;       /* >0 for "tableau de N ..." (fixed-size 1D, back-compat) */
    int  arrayDims[10] = {0};    /* Multi-dim sizes for N-D: tableau de 2 par 3 par 4 */
    int  arrayDimCount = 0;      /* 0 = dynamic 1D, 1 = fixed 1D, 2+ = multi-dim */
    int  arrayGrowthMode = 0;    /* 0=none, 1=grow by 1, 2=grow to N (canon <agrandissement=N>) */
    Token arrayElemStructName;   /* set if `tableau de <StructureName>` (user type) */
    arrayElemStructName.start = NULL;
    arrayElemStructName.length = 0;
    int  arrayElemTokenType = 0; /* primitive elem type (TOKEN_CHAINE, TOKEN_ENTIER…) */
    bool isAssocArray = false;
    int  assocKeyType = 0;  /* ASSOC_KEY_STRING */
    int  assocOptions = 0;
    int  assocValueKind = 0; /* ASSOC_VALUE_VARIANT */
    Token assocValueTypeName;   /*  — nom du type de valeur non primitif */
    assocValueTypeName.start = NULL;
    assocValueTypeName.length = 0;
    bool isStruct = false;
    bool isClass = false;
    Token structTypeName;
    structTypeName.start = NULL;
    structTypeName.length = 0;
    structTypeName.line = 0;
    structTypeName.column = 0;
    structTypeName.type = TOKEN_ERROR;
    /*  — buffer du nom mangle `COL$Type` quand le type est un membre
     * de collection (qualifie ou nom nu). Portée fonction : structTypeName y
     * pointe jusqu'à la fin (tous les consommateurs recopient). */
    char collTypeMangleBuf[256];

    /* Detect an associative array BEFORE the regular type-skip logic.
     * Two word orders are accepted, both requiring the two keywords:
     *   TABLEAU ASSOCIATIF   ("tableau associatif" FR / "array associative" calque)
     *   ASSOCIATIF TABLEAU   ("associative array" — ordre anglais naturel)
     * Un ASSOCIATIF seul (non suivi de TABLEAU) n'est PAS un tableau
     * associatif : on ne consomme rien et on retombe sur le parse de type
     * normal (evite la sur-tolerance). Si detecte, on consomme toute la
     * spec de type nous-memes et on pose typeSpecHandled. */
    bool typeSpecHandled = false;

    /* Ordre anglais naturel : ASSOCIATIF suivi de TABLEAU. On peek le token
     * significatif suivant via un clone du scanner (struct valeur, sans effet
     * de bord) pour n'engager la consommation que si les deux mots sont la. */
    bool isAssocNaturalEN = false;
    if (!isArray && check(TOKEN_ASSOCIATIF)) {
        Scanner peekScanner = parser.scanner;
        Token nextTok;
        do {
            nextTok = scanner_scan_token(&peekScanner);
        } while (nextTok.type == TOKEN_NEWLINE || nextTok.type == TOKEN_SEMICOLON);
        if (nextTok.type == TOKEN_TABLEAU) isAssocNaturalEN = true;
    }

    if (isAssocNaturalEN) {
        advance_token(); /* consume ASSOCIATIF */
        advance_token(); /* consume TABLEAU */
        isAssocArray = true;
        typeSpecHandled = true;
        parse_assoc_array_type_tail(&assocValueKind, &assocValueTypeName);
    } else if (isArray) {
        advance_token(); /* consume TABLEAU */
        if (match_token(TOKEN_ASSOCIATIF)) {
            isAssocArray = true;
            isArray = false;
            typeSpecHandled = true;
            parse_assoc_array_type_tail(&assocValueKind, &assocValueTypeName);
        } else {
            /* Regular array: TABLEAU consumed. Optional shape + type.
             * canon syntax (all forms supported):
             *   tableau [<agrandissement[=0|1|N]>] de <type>               // dynamic 1D
             *   tableau [<agrandissement...>] de N <type>                  // fixed 1D
             *   tableau de N par M [par K] <type>                          // multi-dim
             *   tableau [N] <type>          (= tableau de N <type>)
             *   tableau [N, M, ...] <type>  (= tableau de N par M <type>)
             *   tableau d'<type>            (apostrophe elision, ASCII safe) */
            typeSpecHandled = true;

            /* Optional <agrandissement[=N]> attribute.
             *
             *  — la forme generique style C++ `tableau<T>` n'est pas
             * une syntaxe OWL valide (canon : `tableau de T` ou `tableau d'T`).
             * Avant de tenter le parse `<agrandissement>`, on regarde si le
             * token apres `<` est en fait un type / un identifier autre que
             * `agrandissement` : dans ce cas on emet un message d'erreur
             * explicite qui guide vers la forme canon, au lieu du message
             * generique "Expected '>' to close <agrandissement>" qui pointait
             * vers une grammaire interne deroutante pour l'utilisateur. */
            if (match_token(TOKEN_LESS)) {
                bool agrandissement_form = false;
                if (check(TOKEN_IDENTIFIER)) {
                    Token tk = parser.current;
                    if (tk.length == 14 && strncasecmp(tk.start, "agrandissement", 14) == 0) {
                        agrandissement_form = true;
                        advance_token();
                        if (match_token(TOKEN_EQUAL)) {
                            if (check(TOKEN_INTEGER)) {
                                long v = strtol(parser.current.start, NULL, 10);
                                arrayGrowthMode = (v == 0) ? 0 : (v == 1) ? 1 : 2; /* 2 = grow-to-N */
                                advance_token();
                            } else if (check(TOKEN_IDENTIFIER) && parser.current.length == 1 &&
                                       (parser.current.start[0] == 'N' || parser.current.start[0] == 'n')) {
                                arrayGrowthMode = 2;
                                advance_token();
                            }
                        } else {
                            /* <agrandissement> alone = grow by 1 */
                            arrayGrowthMode = 1;
                        }
                    }
                }
                if (!agrandissement_form && (is_type_token() || check(TOKEN_IDENTIFIER))) {
                    owl_emit_error_at(&parser.current, E_SYNTAX_TABLEAU_GENERIC_BRACKET, NULL);
                    return;
                }
                consume(TOKEN_GREATER, E_SYNTAX_EXP_GT_AGRANDISSEMENT);
            }

            /* Crochet form: [N] or [N, M, ...] */
            if (match_token(TOKEN_LEFT_BRACKET)) {
                /* Empty [] = dynamic */
                if (!check(TOKEN_RIGHT_BRACKET)) {
                    /* First dim */
                    if (check(TOKEN_INTEGER)) {
                        long v = strtol(parser.current.start, NULL, 10);
                        if (v > 0 && v < 256 && arrayDimCount < 10) {
                            arrayDims[arrayDimCount++] = (int)v;
                        }
                        advance_token();
                    } else if (check(TOKEN_STAR)) {
                        advance_token(); /* dynamic */
                    }
                    /* Additional dims separated by commas */
                    while (match_token(TOKEN_COMMA)) {
                        if (check(TOKEN_INTEGER)) {
                            long v = strtol(parser.current.start, NULL, 10);
                            if (v > 0 && v < 256 && arrayDimCount < 10) {
                                arrayDims[arrayDimCount++] = (int)v;
                            }
                            advance_token();
                        } else if (check(TOKEN_STAR)) {
                            advance_token();
                        }
                    }
                }
                consume(TOKEN_RIGHT_BRACKET, E_SYNTAX_EXP_RBRACKET_ARRAY_DIMS);
                /* After crochets, expect type directly (no `de`) */
                if (is_type_token()) {
                    if (check(TOKEN_IDENTIFIER)) {
                        TokenType prim = record_collection_elem_type_ref(parser.current);
                        if (prim != TOKEN_EOF) {
                            arrayElemTokenType = (int)prim;
                        } else {
                            arrayElemStructName = parser.current;
                        }
                    } else {
                        arrayElemTokenType = (int)parser.current.type;
                    }
                    advance_token();
                }
            } else if (match_token(TOKEN_DE)) {
                /* "de" form: optional N [par M [par K ...]] <type> */
                if (check(TOKEN_INTEGER)) {
                    long v = strtol(parser.current.start, NULL, 10);
                    if (v > 0 && v < 256 && arrayDimCount < 10) {
                        arrayDims[arrayDimCount++] = (int)v;
                    }
                    advance_token();
                    while (match_token(TOKEN_PAR)) {
                        if (check(TOKEN_INTEGER)) {
                            long vv = strtol(parser.current.start, NULL, 10);
                            if (vv > 0 && vv < 256 && arrayDimCount < 10) {
                                arrayDims[arrayDimCount++] = (int)vv;
                            }
                            advance_token();
                        } else if (check(TOKEN_STAR)) {
                            advance_token();
                        }
                    }
                } else if (check(TOKEN_STAR)) {
                    advance_token();
                    while (match_token(TOKEN_PAR)) {
                        if (check(TOKEN_INTEGER) || check(TOKEN_STAR)) {
                            advance_token();
                        }
                    }
                }
                if (is_type_token()) {
                    if (check(TOKEN_IDENTIFIER)) {
                        TokenType prim = record_collection_elem_type_ref(parser.current);
                        if (prim != TOKEN_EOF) {
                            arrayElemTokenType = (int)prim;
                        } else {
                            arrayElemStructName = parser.current;
                        }
                    } else {
                        arrayElemTokenType = (int)parser.current.type;
                    }
                    advance_token();
                }
            } else if (!crossedNewline && is_type_token()) {
                /* d' elision: scanner ate "d'" filler, type is next token on SAME line. */
                if (check(TOKEN_IDENTIFIER)) {
                    TokenType prim = record_collection_elem_type_ref(parser.current);
                    if (prim != TOKEN_EOF) {
                        arrayElemTokenType = (int)prim;
                    } else {
                        arrayElemStructName = parser.current;
                    }
                } else {
                    arrayElemTokenType = (int)parser.current.type;
                }
                advance_token();
            }

            /* Back-compat: if exactly 1 dim captured, also set arrayPresize
             * so existing 1D emit path still works. */
            if (arrayDimCount == 1) {
                arrayPresize = arrayDims[0];
            }
        }
    }

    /* Check if it's a class declaration: "est une Classe" */
    if (check(TOKEN_CLASSE)) {
        advance_token(); /* consume CLASSE */
        class_declaration(varName);
        return;
    }

    /* DSL Fenetre v1 (Phase G v2) : 'IDENT est une Fenetre ... FIN' */
    if (check(TOKEN_FENETRE)) {
        advance_token(); /* consume FENETRE/WINDOW */
        window_declaration(varName, varName.line);
        return;
    }

    /* DSL Etat V2 : 'IDENT est un Etat ... FIN' */
    if (check(TOKEN_ETAT)) {
        advance_token(); /* consume ETAT/REPORT */
        etat_declaration(varName, varName.line);
        return;
    }

    /* Sous-champ DSL au top-level : erreur (champ orphelin). */
    if (check(TOKEN_LIBELLE) || check(TOKEN_BOUTON) || check(TOKEN_SAISIE)
                             || check(TOKEN_TABLE)  || check(TOKEN_CONTENEUR)) {
        const char* kind = check(TOKEN_LIBELLE)   ? "Libelle"
                         : check(TOKEN_BOUTON)    ? "Bouton"
                         : check(TOKEN_TABLE)     ? "Table"
                         : check(TOKEN_CONTENEUR) ? "Conteneur"
                         : "Saisie";
        owl_emit_error_at(&varName, E_SEM_CONTROL_KIND_OUTSIDE_WINDOW,
                          "kind", kind,
                          NULL);
        advance_token();
        return;
    }

    /* Check if it's an enumeration: "est une Enumeration" */
    if (check(TOKEN_ENUMERATION)) {
        advance_token(); /* consume ENUMERATION */
        enum_declaration(varName);
        return;
    }

    /* Check if it's a combination: "est une Combinaison" */
    if (check(TOKEN_COMBINAISON)) {
        advance_token(); /* consume COMBINAISON */
        combination_declaration(varName);
        return;
    }

    /* Check if it's a collection: "est une File/Pile/Liste [de <type>]" */
    if (check(TOKEN_FILE) || check(TOKEN_PILE) || check(TOKEN_LISTE)) {
        TokenType collToken = parser.current.type;
        advance_token(); /* consume File/Pile/Liste */
        /* "de <type>" optionnel. Le type d'element ne contraint rien au
         * runtime (les 3 collections stockent des valeurs libres), mais il
         * doit designer un type REEL : cf. record_collection_elem_type_ref.
         *  — l'elision `d'<type>` est acceptee a parite avec `de`/`of`
         * (le scanner a avale le filler `d'`, le type est le token courant sur
         * la MEME ligne). Parite avec le tableau simple. */
        if (match_token(TOKEN_DE) || (!crossedNewline && is_type_token())) {
            (void)record_collection_elem_type_ref(parser.current);
            if (is_type_token()) {
                advance_token(); /* consume the element type */
            }
        }

        declare_variable(&varName);
        /* Tracking type pour le strict dot check : file/pile/liste exposent
         * les mêmes propriétés runtime (Occurrence, Vide). */
        record_declared_type(varName, (int)collToken, false, false, NULL, 0);
        ConstIdx global = { 0 };
        if (current->scopeDepth == 0) {
            global = identifier_constant(&varName);
        }

        uint8_t collType = collToken == TOKEN_FILE ? 0 :
                           collToken == TOKEN_PILE ? 1 : 2;
        emit_bytes(OP_COLLECTION, collType);
        define_variable(global);
        return;
    }

    /* Check if it's a JSON variable: "est un JSON [= expression]" */
    if (check(TOKEN_JSON_KW)) {
        advance_token(); /* consume JSON */
        declare_variable(&varName);
        /* Tracking type pour le strict dot check (JSON expose Occurrence,
         * Vide, Type côté runtime). */
        record_declared_type(varName, (int)TOKEN_JSON_KW, false, false, NULL, 0);
        ConstIdx global = { 0 };
        if (current->scopeDepth == 0) {
            global = identifier_constant(&varName);
        }

        /* Optional initializer: "est un JSON = <expr>" */
        if (match_token(TOKEN_EQUAL)) {
            /*  — coercion structurelle chaine -> JSON. Le RHS est
             * enveloppe dans __JSONCoerce (meme point commun que la
             * reaffectation `o = <chaine>`) : une chaine `{...}`/`[...]` est
             * parsee en document reel, une chaine libre reste inchangee, une
             * structure malformee leve une erreur runtime. */
            Token jcTok;
            jcTok.start  = "__JSONCoerce";
            jcTok.length = 12;
            ConstIdx jcConst = identifier_constant(&jcTok);
            emit_const_op(OP_GET_GLOBAL, jcConst);
            condition_expression();  /* RHS d'init, cf bug ambiguite <= / = */
            emit_bytes(OP_CALL, 1);
        } else {
            /* No initializer: call __JsonNew() to create empty JSON object */
            Token jnTok;
            jnTok.start = "__JsonNew";
            jnTok.length = 9;
            ConstIdx jnConst = identifier_constant(&jnTok);
            emit_const_op(OP_GET_GLOBAL, jnConst);
            emit_bytes(OP_CALL, 0);
        }

        define_variable(global);
        return;
    }

    /* Check if it's an interface declaration: "est une Interface" */
    if (check(TOKEN_INTERFACE)) {
        advance_token(); /* consume INTERFACE */
        /*  : capture les signatures des methodes pour cross-check
         * du contrat `cX implemente iY`. Les methodes d'interface ont la
         * forme `PROCEDURE Foo([param1 est un type, ...]) [: type_retour]`
         * sans corps (canon : pas de FIN apres chaque PROCEDURE, le FIN
         * unique ferme l'interface entiere). */
        /*  — interface de CollectionDeProcédures : arrive manglée
         * `COL$iForme` (peek collection). Le CONTRAT et l'identité de type restent
         * sous le nom NU : `cX implemente iForme` référence l'interface au nom nu
         * (mono-fichier via g_interface_methods, cross-fichier via le prescan qui
         * lit le texte source). La position de type qualifiée `COL.iForme` est
         * validée par is_collection_qualified_type (pending-refs) ; l'interface
         * n'ayant pas de template runtime, aucun slot mangled n'est requis. */
        Token bareIface = varName;
        const char* ifaceDollar = memchr(varName.start, '$', (size_t)varName.length);
        if (ifaceDollar != NULL) {
            bareIface.start  = ifaceDollar + 1;
            bareIface.length = varName.length - (int)(ifaceDollar + 1 - varName.start);
        }
        register_user_type_kind(bareIface.start, bareIface.length,
                                OWL_USER_TYPE_INTERFACE, varName.line);
        Token ifaceName = bareIface;
        while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
            if (check(TOKEN_NEWLINE)) {
                advance_token();
                continue;
            }
            if (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION)) {
                advance_token(); /* consume PROCEDURE/FONCTION */
                if (!check(TOKEN_IDENTIFIER)) {
                    /* Pas un identifiant : signature mal formee, on skip
                     * jusqu'au prochain NEWLINE pour continuer le parse. */
                    while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) &&
                           !check(TOKEN_EOF)) advance_token();
                    continue;
                }
                Token methodName = parser.previous;
                advance_token(); /* consume method name */
                methodName = parser.previous;
                /* Parametres */
                int paramCount = 0;
                char paramTypes[MAX_METHOD_PARAMS][32];
                memset(paramTypes, 0, sizeof(paramTypes));
                if (match_token(TOKEN_LEFT_PAREN)) {
                    if (!check(TOKEN_RIGHT_PAREN)) {
                        do {
                            /*  — la saturation ne coupe PAS le comptage.
                             * Ecreter paramCount ici faisait comparer la
                             * signature reelle de la classe a une version
                             * tronquee de l'interface : du code strictement
                             * conforme etait refuse au motif d'une divergence
                             * inventee ("attendu : 16, trouve : 17"). La limite
                             * se nomme elle-meme et le comptage continue. */
                            if (paramCount == MAX_METHOD_PARAMS) {
                                error_capacity_exceeded("MAX_METHOD_PARAMS",
                                                        MAX_METHOD_PARAMS);
                            }
                            /* Param name */
                            if (check(TOKEN_IDENTIFIER)) advance_token();
                            /* Optional `est un <type>` */
                            if (match_token(TOKEN_EST)) {
                                /* Capture le 1er token de la type spec
                                 * comme nom de type "approximatif" (suffit
                                 * pour le check de signature). */
                                if (paramCount < MAX_METHOD_PARAMS && /* capacity-ok: borne d'ecriture, le refus est pose juste au-dessus */
                                    (check(TOKEN_IDENTIFIER) || is_type_token())) {
                                    int n = parser.current.length < 31
                                            ? parser.current.length : 31;
                                    memcpy(paramTypes[paramCount],
                                           parser.current.start, n);
                                    paramTypes[paramCount][n] = '\0';
                                }
                                skip_type_spec();
                            }
                            paramCount++;
                        } while (match_token(TOKEN_COMMA));
                    }
                    consume(TOKEN_RIGHT_PAREN,
                            E_SYNTAX_EXP_RPAREN_INTERFACE_METHOD_PARAMS);
                }
                /* Type retour optionnel : `: type` */
                char returnType[32];
                returnType[0] = '\0';
                if (is_return_type_colon()) {
                    advance_token(); /* consume ':' */
                    if (check(TOKEN_IDENTIFIER) || is_type_token()) {
                        int n = parser.current.length < 31
                                ? parser.current.length : 31;
                        memcpy(returnType, parser.current.start, n);
                        returnType[n] = '\0';
                    }
                    skip_type_spec();
                }
                interface_method_register(ifaceName.start, ifaceName.length,
                                          methodName.start, methodName.length,
                                          paramCount, paramTypes, returnType);
                continue;
            }
            /* Token non reconnu dans le body : skip pour rester resilient. */
            advance_token();
        }
        consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_INTERFACE);
        return;
    }

    /*  — `IDENT est un Groupe [= [...]]`. Sous-type tableau de Champ
     * avec tag is_group cote ObjArray. Reutilise l'init litterale tableau
     * standard (`[BTN_A, BTN_B]`) qui sait deja resoudre les identifiants en
     * OP_GET_GLOBAL. Pousse une entree dans decl->variables[] uniquement si
     * la decla est au top-level fenetre (g_current_window_decl != NULL), car
     * la prop `champ..Groupe` cote ObjUiControl ne voit que les Groupes
     * top-level fenetre (les Groupes locaux a une procedure broadcastent
     * sans etre visibles cote champ).
     *
     * Bilingue : "Group" (alias EN) accepte. */
    if (!isArray && check(TOKEN_IDENTIFIER)) {
        /*  — `<Nom> est un Theme ... FIN` : bloc DSL declarant les
         * styles nommes du theme actif. Intercepte AVANT la branche struct-type
         * (qui produirait "Type inconnu 'Theme'"). Le corps est une suite de
         * declarations standard (`nom est un styleXxx = {...}`) parsees via
         * declaration(). Les styles du corps sont mangles `theme$<nom>` (reuse
         * de l'idiome element-globals via g_current_element_name = "theme")
         * UNIQUEMENT si CE bloc est l'instance designee par Projet..Theme
         * (comparaison sur le nom du bloc, ) — sinon corps parse valide
         * mais inerte (aucune registration).
         *
         * Le mangle passe par element_globals_register + element_var_prefix :
         * l'idiome garantit la coherence de la cle canonique (strip accents /
         * casse) entre la registration et le lookup runtime
         * `vm_globals_canon_get("theme$X")`. `theme` apparait donc dans le
         * registre element-globals, MAIS is_theme_namespace_name (exclusion
         * inconditionnelle) empeche `theme.X` d'emprunter le dispatch element /
         * cross-file : personne ne lit `theme` comme un vrai element, la
         * resolution passe par le namespace ObjThemeNamespace + OP_STRUCT_GET.
         * Bilingue : "Theme" (accent-strippe de "Thème"). Le token pointe la
         * source (accent conserve) : on strippe avant de comparer. */
        char themeProbe[16];
        int themeProbeLen = scanner_strip_accents(
            parser.current.start, parser.current.length,
            themeProbe, sizeof(themeProbe));
        bool isThemeKw = (themeProbeLen == 5 &&
                          strncasecmp(themeProbe, "Theme", 5) == 0);
        if (isThemeKw) {
            advance_token(); /* consume "Theme" */

            if (g_theme_block_seen) {
                owl_emit_error_current(E_SYNTAX_THEME_BLOCK_DUPLICATE);
            }
            g_theme_block_seen = true;

            bool designated = theme_block_is_designated(varName);

            /*  — un bloc que RIEN ne designe est inerte et
             * l'etait en silence : la fenetre s'affichait nue, sans le moindre
             * signe. On le dit ici, une fois, a la racine — pas a chaque
             * `theme.<style>`, qui multiplierait le meme message.
             *
             * Emis seulement quand AUCUN theme n'est designe dans le projet.
             * Un bloc non designe cotoyant un bloc designe est une ambiance de
             * reserve, usage prevu du modele : rester muet dessus.
             * projectSymbols == NULL (buffer isole, hors projet) = muet aussi,
             * meme garde que l'avertissement de style introuvable. */
            if (!designated && projectSymbols != NULL
                && !project_designates_a_theme()) {
                char nameBuf[128];
                snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                         varName.length, varName.start);
                owl_emit_warning_at(&varName, W_SEM_THEME_BLOCK_NOT_DESIGNATED,
                                    "nom", nameBuf, NULL);
            }

            /* Active le mangling pendant le corps. Sauvegarde/restaure
             * g_current_element_name (comme window_declaration /
             * etat_declaration).
             *
             *  — le bloc INERTE est mangle lui aussi. Il declarait
             * jusqu'ici des globales ORDINAIRES, atteignables par leur nom nu :
             * une porte que l' interdit ("acces uniquement via
             * theme."), et par laquelle deux ambiances de reserve homonymes
             * se marchaient dessus dans l'espace global (silencieux a la
             * declaration, « symbole ambigu » a la lecture).
             *
             * Le prefixe d'un bloc inerte porte le nom du bloc : deux reserves
             * ont des emplacements DISTINCTS, et aucune ne peut s'installer sur
             * `theme$<style>`, reserve au designe. Le `@` le rend intypable —
             * un bloc inerte n'est adressable par aucun chemin, ce qui est
             * exactement son contrat. */
            char savedElem[64];
            memcpy(savedElem, g_current_element_name, sizeof(savedElem));
            bool savedInTheme = g_in_theme_block;
            g_in_theme_block = true;
            if (designated) {
                snprintf(g_current_element_name,
                         sizeof(g_current_element_name), "theme");
            } else {
                char blockCanon[64];
                int bn = scanner_strip_accents(varName.start, varName.length,
                                               blockCanon, sizeof(blockCanon));
                if (bn <= 0) {
                    bn = varName.length < (int)sizeof(blockCanon) - 1
                             ? varName.length : (int)sizeof(blockCanon) - 1;
                    memcpy(blockCanon, varName.start, (size_t)bn);
                }
                snprintf(g_current_element_name,
                         sizeof(g_current_element_name),
                         "theme@%.*s", bn, blockCanon);
            }
            bool savedConfineTheme = g_toplevel_confine;  /*  */
            g_toplevel_confine = false;

            /* Corps : suite de declarations standard jusqu'a FIN. Bloc vide
             * legal. */
            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                declaration();
            }

            memcpy(g_current_element_name, savedElem, sizeof(savedElem));
            g_in_theme_block   = savedInTheme;       /*  */
            g_toplevel_confine = savedConfineTheme;  /*  */

            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_THEME);
            return;
        }

        /*  — `<Nom> est un ServiceREST ... FIN` : bloc DSL du service
         * HTTP declaratif. Reconnu par comparaison de chaine accent-strippee
         * (comme Theme), AVANT la branche struct-type (qui produirait "Type
         * inconnu 'ServiceREST'"). Parse + validation statique ; aucune
         * variable/global declaree pour le nom (return sec, comme Theme). */
        {
            char srProbe[24];
            int srLen = scanner_strip_accents(parser.current.start,
                                              parser.current.length,
                                              srProbe, sizeof(srProbe));
            if (srLen == 11 && strncasecmp(srProbe, "ServiceREST", 11) == 0) {
                advance_token(); /* consume "ServiceREST" */
                service_rest_declaration(varName);
                g_service_block_parsed = true;  /*  : verrou top-level */
                return;
            }
        }

        /*  — `<Nom> est une CollectionDeProcédures ... FIN` : bloc DSL
         * declarant une collection de procedures. Intercepte AVANT la branche
         * struct-type (qui produirait "Type inconnu"). Le corps est une suite de
         * declarations standard (PROCEDURE/FONCTION, globales, CONSTANTE,
         * ENUMERATION, STRUCTURE) plus, comme le bloc Projet, du code
         * d'initialisation emis INLINE dans le chunk du fichier.
         *
         * Difference DELIBEREE avec Fenetre/Etat/Theme : on ne pose PAS
         * g_current_element_name. Une collection n'encapsule rien — ses globales
         * restent des globales PROJET accessibles en NOM NU depuis n'importe
         * quel fichier. Le mangling `<ELEM>$var` en ferait une boite hermetique,
         * contresens du modele. Une CLASSE reste interdite dans le bloc
         * (1 classe = 1 fichier). Top-level uniquement. */
        if (current->scopeDepth == 0
            && token_is_collection_kw(parser.current.start,
                                      parser.current.length)) {
            Token kwTok = parser.current;
            advance_token();  /* consume CollectionDeProcedures */

            if (g_collection_block_parsed) {
                owl_emit_error_at(&kwTok, E_SEM_COLLECTION_DUPLICATE, NULL);
            }
            /*  — collection imbriquee dans une collection : refus
             * explicite, comme Fenetre dans Fenetre et Classe dans Classe. Le
             * suivi lexical des membres (hydrate_collection_members) n'a qu'un
             * seul bloc courant, sans pile : le FIN de l'imbriquee refermait le
             * suivi de l'englobante et tous ses membres suivants sortaient de
             * l'index, sans un mot. Le parse, lui, sait empiler (savedColl
             * ci-dessous) : on le laisse finir le corps pour ne pas cascader,
             * l'erreur suffit. */
            if (g_current_collection_name[0] != '\0') {
                char nestedNameBuf[128];
                snprintf(nestedNameBuf, sizeof(nestedNameBuf), "%.*s",
                         varName.length, varName.start);
                owl_emit_error_at(&varName, E_SEM_COLLECTION_NESTED,
                                  "name", nestedNameBuf, NULL);
                parser.panicMode = false;
                g_collection_nested_rejected = true;
            }
            if (g_file_has_window_block_prescan || g_file_has_etat_block_prescan
                || g_file_has_projet_block || g_file_first_class_line != 0) {
                owl_emit_error_at(&kwTok, E_SEM_COLLECTION_FILE_AND_OTHER_BLOCK,
                                  NULL);
            }
            g_file_has_collection_block = true;

            /*  — active le contexte collection pendant le corps : les
             * globales (var_declaration_after_est) et procedures
             * (funct_declaration) declarees ici sont manglees `<COL>$membre` et
             * enregistrees exposees. Save/restore comme window/etat/theme. */
            char savedColl[64];
            memcpy(savedColl, g_current_collection_name, sizeof(savedColl));
            {
                int cn = varName.length < (int)sizeof(g_current_collection_name) - 1
                         ? varName.length : (int)sizeof(g_current_collection_name) - 1;
                memcpy(g_current_collection_name, varName.start, (size_t)cn);
                g_current_collection_name[cn] = '\0';
            }
            /*  — corps de collection = contexte top-level : mode GLOBAL. */
            bool savedConfineColl = g_toplevel_confine;
            g_toplevel_confine = false;

            /*  — corps compilé en ordre source PUIS déclarations
             * structurelles (PROCEDURE/FONCTION/STRUCTURE/CONSTANTE/ENUM)
             * hoistées avant le code d'init, comme le top-level d'un script.
             * Sinon un appel dans l'init à une procédure déclarée plus bas
             * échouait au runtime ("Fonction ou procédure inconnue"). */
            compile_collection_body_hoisted();
            /*  — le corps est parse : les deux indexations doivent
             * coincider. Avant restauration, le nom courant est bien celui de
             * CE bloc. */
            collection_prescan_cross_check(g_current_collection_name, &varName);
            memcpy(g_current_collection_name, savedColl, sizeof(savedColl));
            g_toplevel_confine = savedConfineColl;  /*  */
            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_COLLECTION);
            g_collection_block_parsed = true;
            return;
        }

        bool isGroupKw =
            (parser.current.length == 6 && strncasecmp(parser.current.start, "Groupe", 6) == 0) ||
            (parser.current.length == 5 && strncasecmp(parser.current.start, "Group",  5) == 0);
        if (isGroupKw) {
            Token typeTok = parser.current;
            advance_token(); /* consume "Groupe" / "Group" */

            /* Pousse l'entree dans decl->variables[] si top-level fenetre. */
            if (g_current_window_decl != NULL) {
                char nameBuf[128];
                int n = varName.length < (int)sizeof(nameBuf) - 1
                        ? varName.length : (int)sizeof(nameBuf) - 1;
                memcpy(nameBuf, varName.start, (size_t)n);
                nameBuf[n] = '\0';
                owl_window_decl_add_variable(g_current_window_decl, nameBuf,
                                              "Groupe", typeTok.line);
            }

            /* Declare la variable + slot global. */
            declare_variable(&varName);
            record_declared_type(varName, (int)TOKEN_TABLEAU, false, false, NULL, 0);
            /*  — Groupe top-level body Fenetre (winTopCompiler,
             * TYPE_FUNCTION, scopeDepth 0 => tombe ici via le local 0 du
             * winTop). Public par construction (canon ), reference
             * cross-file via widgets `Groupe = GR_X` et scripts voisins :
             * pas de warning "declaree mais jamais utilisee". L'init est
             * implicite (tableau vide ou litteral, toujours pose). */
            if (current->scopeDepth > 0 && current->localCount > 0
                && g_current_window_decl != NULL) {
                current->locals[current->localCount - 1].hasInitializer = true;
            }
            ConstIdx global = { 0 };
            if (current->scopeDepth == 0) {
                global = identifier_constant(&varName);
            }

            /* Initialisation : tableau litteral si `= [...]`, sinon vide. */
            if (match_token(TOKEN_EQUAL)) {
                /* expression() supporte deja `[a, b, c]` -> OP_ARRAY + Ajoute. */
                expression();
            } else {
                emit_byte(OP_ARRAY);
            }

            /* Tag is_group sur l'ObjArray top-of-stack. */
            emit_byte(OP_ARRAY_MARK_GROUP);

            /*  — track le Groupe top-level body Fenetre cote
             * g_declaredGlobals (chemin scopeDepth 0 dans winTopCompiler).
             * Le path standard de var_declaration n'est pas emprunte ici,
             * d'ou le faux positif unused-global avant ce track explicite. */
            if (g_current_window_decl != NULL && current->scopeDepth == 0) {
                global_track_declare(varName.start, varName.length,
                                     varName.line);
                global_track_mark_initialized(varName.start, varName.length);
            }

            define_variable(global);
            return;
        }
        /* `IDENT est un Champ` : variable scalaire opaque (ref ObjUiControl).
         * Initialise a NIL si pas d'init explicite, sinon a l'expression
         * (typiquement `GR_X[i]`). */
        bool isChampKw =
            (parser.current.length == 5 && strncasecmp(parser.current.start, "Champ", 5) == 0) ||
            (parser.current.length == 5 && strncasecmp(parser.current.start, "Field", 5) == 0);
        if (isChampKw) {
            advance_token(); /* consume "Champ" / "Field" */

            declare_variable(&varName);
            record_declared_type(varName, (int)TOKEN_IDENTIFIER, false, false, NULL, 0);
            ConstIdx global = { 0 };
            if (current->scopeDepth == 0) {
                global = identifier_constant(&varName);
            }

            if (match_token(TOKEN_EQUAL)) {
                expression();
            } else {
                emit_byte(OP_NIL);
            }
            define_variable(global);
            return;
        }
    }

    /* Remember the declared type for default value generation.
     * Pour les arrays/assoc, le parser a déjà consommé la spec (tableau de N
     * <type>) donc parser.current pointe sur ce qui suit (= / NEWLINE / ...).
     * On force la valeur attendue pour que le strict dot check connaisse le
     * kind du receveur (cf. resolve_var_declared_type). */
    TokenType declaredType;
    if (isArray || isAssocArray) {
        declaredType = TOKEN_TABLEAU;
    } else {
        declaredType = parser.current.type;
    }

    /*  — type membre de CollectionDeProcédures en POSITION DE TYPE,
     * forme QUALIFIÉE `COL_X.NomType` : `COL_X` est une collection connue et
     * `NomType` un de ses membres -> résout vers le slot mangled DISTINCT
     * `COL_X$NomType` (structure/interface/combinaison/énumération, case_070/072).
     * Le clone `__StructClone(COL_X$NomType)` (structures) ou la validation de
     * type (interfaces via init) passent alors par le slot distinct — deux
     * `stForme` de deux collections ne se confondent pas (case_071). Le nom NU
     * reste résolu par le chemin ordinaire via l'alias nu (case_073). Le nom
     * mangled est posé dans collTypeMangleBuf (portée fonction) ; typeSpecHandled
     * inhibe le skip_type_spec en aval. */
    if (!isArray && !typeSpecHandled && check(TOKEN_IDENTIFIER)
        && g_collection_members_count > 0) {
        Token first     = parser.current;
        Scanner svScan  = parser.scanner;
        Token   svCur   = parser.current;
        Token   svPrev  = parser.previous;
        bool    svXNL   = crossedNewline;
        advance_token();  /* consume `COL_X` */
        bool matched = false;
        if (check(TOKEN_DOT)) {
            advance_token();  /* consume '.' */
            if (check(TOKEN_IDENTIFIER)
                && collection_member_has(first.start, first.length,
                                         parser.current.start, parser.current.length)) {
                Token member = parser.current;
                advance_token();  /* consume NomType */
                int mn = snprintf(collTypeMangleBuf, sizeof(collTypeMangleBuf),
                                  "%.*s$%.*s", first.length, first.start,
                                  member.length, member.start);
                if (mn > 0 && mn < (int)sizeof(collTypeMangleBuf)) {
                    structTypeName.start  = collTypeMangleBuf;
                    structTypeName.length = mn;
                    structTypeName.type   = TOKEN_IDENTIFIER;
                    structTypeName.line   = first.line;
                    structTypeName.column = first.column;
                    isStruct        = true;
                    record_pending_type_ref(structTypeName);
                    typeSpecHandled = true;
                    matched         = true;
                }
            }
        }
        if (!matched) {
            /* Pas un type qualifié de collection : rollback, la résolution de
             * type ordinaire (nom nu / builtin) reprend. */
            parser.scanner  = svScan;
            parser.current  = svCur;
            parser.previous = svPrev;
            crossedNewline  = svXNL;
        }
    }

    /* Check if identifier after EST matches a struct/class type.
     * Gate par !typeSpecHandled : si le type a deja ete entierement consomme
     * (path tableau / tableau associatif), parser.current pointe sur le token
     * suivant la declaration (typiquement un appel de procedure sur la ligne
     * d'apres). Sans ce garde, on enregistrait ce token comme "type a valider"
     * et on produisait un faux "Type inconnu 'dbgVerifieEgalite'" (regression
     *  v1, reproduite par tests/regression/test_assoc_array_decl_then_call.owl). */
    if (!isArray && !typeSpecHandled && check(TOKEN_IDENTIFIER)) {
        bool isVariantRemoved = (parser.current.length == 7 &&
            strncasecmp(parser.current.start, "variant", 7) == 0);
        /* Détection dédiée du Variant retiré : message clair au lieu d'un
         * "Type inconnu" générique. */
        if (isVariantRemoved) {
            owl_emit_error_at(&parser.previous, E_SEM_VARIANT_TYPE_REMOVED);
        }
        isStruct = true;
        structTypeName = parser.current;
        /*  : canonicalise le nom du type pour fixer le dispatch
         * case-insensible en annotation. `r est un HTTPREQUÊTE` strippait
         * en `HTTPREQUETE` (majuscules), clef absente de vm.globals (le
         * template est sous `httpRequete`). Resultat : "Undefined
         * variable" alors que le type existe en casse insensible.
         *
         * On substitue le token par le canonical du type des qu'il
         * matche le registry. Tout le code downstream (record_pending_type_ref,
         * record dans structTypeName du local/global, emission
         * __StructClone, etc.) voit alors la forme canon stable.
         *
         * Pas de substitution si le type est user-declare (knownUserTypes)
         * — la casse du token source est deja celle de la declaration. */
        {
            char tprobe[128];
            int tn = parser.current.length < (int)sizeof(tprobe) - 1
                         ? parser.current.length : (int)sizeof(tprobe) - 1;
            memcpy(tprobe, parser.current.start, tn);
            tprobe[tn] = '\0';
            const OwlTypeDef* td = owl_registry_type_find(tprobe);
            if (td != NULL && td->canonical != NULL) {
                structTypeName.start  = td->canonical;
                structTypeName.length = (int)strlen(td->canonical);
            }
        }
        /* Record le type pour validation post-parse. Place ici (et non plus
         * dans la branche emit-struct-default plus bas) pour que le check
         * couvre TOUS les chemins en aval — y compris le path avec
         * initialiseur explicite `= <expr>`, qui contournait silencieusement
         * la validation et acceptait `x est un truc_inexistant = 42`
         *. is_any_known_type (appelé par validate_pending_type_refs
         * en fin de compilation) couvre :
         *   - types fondamentaux et builtins via owl_registry_type_find
         *   - structures/classes/enums déclarées localement ou cross-file
         *     via knownUserTypes (renseigné par prescan + class/enum_decl).
         * Skip si on vient déjà d'émettre le message Variant dédié, sinon
         * on doublonne avec un générique "Type inconnu 'variant'". */
        if (!isVariantRemoved) {
            record_pending_type_ref(structTypeName);
        }
    }

    /* Skip type specification (unless we already consumed it for assoc arrays) */
    if (!typeSpecHandled) {
        skip_type_spec();
    }

    /* Optional nullability/attribute markers: 'entier?', 'entier <nullable>',
     * 'chaine <indétectable>', etc. */
    bool isUndetectable = false;
    bool suppressUnused = false;
    bool isNullable = parse_nullability_marker_ex(&isUndetectable, &suppressUnused);

    /* Check if this is a class instantiation with constructor args */
    bool autoInstantiateZeroArgs = false;
    if (isStruct && check(TOKEN_LEFT_PAREN)) {
        isClass = true;
        isStruct = false;
    } else if (isStruct && !isNullable && structTypeName.start != NULL &&
               structTypeName.length > 0 &&
               !check(TOKEN_EQUAL) && !check(TOKEN_LESS_EQUAL)) {
        /*  : `oFoo est un cFoo` sans `()`, sans nullable, sans init
         * explicite. Si cFoo est une CLASSE :
         *   - cstr trivial (0 args requis OU pas de cstr declare) -> emet
         *     le meme bytecode que `cFoo()` (auto-instanciation).
         *   - cstr avec args requis -> erreur compile-time avec message
         *     E_SEM_INSTANCE_NEEDS_ARGS.
         * Le check classe abstraite est traite plus bas dans le bloc
         * `if (isClass)` (priorite naturelle : on prend le path classe). */
        int uidx = user_type_index(structTypeName.start,
                                   structTypeName.length);
        bool isUserClass = (uidx >= 0 &&
                            knownUserTypes[uidx].kind ==
                                OWL_USER_TYPE_CLASSE);
        if (isUserClass) {
            int minArity = class_constructor_min_arity_inherited(
                structTypeName.start, structTypeName.length);
            /* minArity == -1 -> aucune classe de la chaine n'a de cstr
             * explicite. Equivalent semantique a minArity == 0 (cstr
             * implicite trivial). */
            if (minArity <= 0) {
                isClass = true;
                isStruct = false;
                autoInstantiateZeroArgs = true;
            } else {
                char nameZ[128];
                int nz = structTypeName.length < (int)sizeof(nameZ) - 1
                         ? structTypeName.length : (int)sizeof(nameZ) - 1;
                memcpy(nameZ, structTypeName.start, (size_t)nz);
                nameZ[nz] = '\0';
                char arityZ[16];
                snprintf(arityZ, sizeof(arityZ), "%d", minArity);
                owl_emit_error_at(&structTypeName,
                                  E_SEM_INSTANCE_NEEDS_ARGS,
                                  "name", nameZ,
                                  "arity", arityZ,
                                  NULL);
                /* Bascule quand meme en path classe pour eviter une cascade
                 * de "Null bypass" en aval. Le bloc isClass va emettre un
                 * OP_GET_GLOBAL + OP_CALL 0 — le runtime echouera proprement
                 * via le check d'arite si jamais l'erreur compile-time
                 * etait ignoree (--check rapporte mais le bytecode part). */
                isClass = true;
                isStruct = false;
                autoInstantiateZeroArgs = true;
            }
        }
    }

    /* Declare the variable */
    declare_variable(&varName);
    /* Apply the nullability/attribute markers to the just-declared local
     * (globals use the side-table `g_typed_globals`).
     *  — un local confine (mode LOCAL top-level, scopeDepth 0) porte
     * aussi ses metadonnees sur le slot local, pas dans la side-table globale.
     *  : le structTypeName est pose quand isStruct/isClass (instantiation
     * `o est un cTest(...)`) — necessaire au check de visibilite compile-time
     * cote dot() qui doit resoudre le type du receveur apres construction. */
    bool hasStructName = (isStruct || isClass)
                         && structTypeName.start != NULL && structTypeName.length > 0;
    record_declared_type(varName, (int)declaredType, isNullable, isUndetectable,
                         hasStructName ? structTypeName.start : NULL,
                         hasStructName ? structTypeName.length : 0);
    /*  — pour un `tableau de <TypeUser>`, memorise le type d'element
     * (structure/classe utilisateur uniquement) sur la variable. Le subscript
     * le propagera comme type de receveur pour que `t[i]..prop` du registre
     * masque soit refuse comme sur toute autre position. Limite aux types user
     * declares : un `tableau de httpRequête` garde la resolution laxe. */
    if (isArray && arrayElemStructName.start != NULL
        && arrayElemStructName.length > 0
        && is_known_user_type(arrayElemStructName.start,
                              arrayElemStructName.length)) {
        record_array_elem_struct_type(varName, arrayElemStructName.start,
                                      arrayElemStructName.length);
    }
    /*  — attribut <utile>/<useful> parse ci-dessus : exempte du
     * W_SEM_VAR_UNUSED, comme le prefixe `_` mais explicite et nommable. */
    if (suppressUnused) {
        record_suppress_unused(varName);
    }
    ConstIdx global = { 0 };
    if (current->scopeDepth == 0) {
        global = identifier_constant(&varName);
    }

    /* Initializer */
    bool hadExplicitInit = false;
    if (isClass) {
        /* Class instantiation: oVar est un ClassName(args)
         * Emit: GET_GLOBAL(ClassName) then OP_CALL with args.
         * The class call handler will create the instance and call constructor. */
        hadExplicitInit = true;

        /*  : interdit l'instanciation directe d'une classe
         * abstraite. Canon 6010006 NOTE3_3 : "Une classe abstraite
         * ne peut pas etre instanciee". */
        if (class_is_abstract(structTypeName.start, structTypeName.length)) {
            char nameZ[128];
            int nz = structTypeName.length < (int)sizeof(nameZ) - 1
                     ? structTypeName.length : (int)sizeof(nameZ) - 1;
            memcpy(nameZ, structTypeName.start, (size_t)nz);
            nameZ[nz] = '\0';
            owl_emit_error_at(&structTypeName, E_SEM_ABSTRACT_CLASS_INSTANTIATION,
                              "name", nameZ,
                              NULL);
        }

        ConstIdx nameIdx = identifier_constant(&structTypeName);
        emit_const_op(OP_GET_GLOBAL, nameIdx);

        if (autoInstantiateZeroArgs) {
            /*  : `oFoo est un cFoo` sans `()` avec cstr trivial.
             * On emet OP_CALL 0 sans consommer de `(` — le call handler
             * cree l'instance et appelle le constructeur 0-arg. */
            emit_bytes(OP_CALL, 0);
        } else {
            consume(TOKEN_LEFT_PAREN, E_SYNTAX_EXP_LPAREN_CTOR_ARGS);
            uint8_t argCount = argument_list();
            emit_bytes(OP_CALL, argCount);
        }
    } else if (match_token(TOKEN_EQUAL)) {
        hadExplicitInit = true;
        /*  — initialiseur absent en fin de ligne (crossedNewline pose
         * par advance_token qui a skippe le NEWLINE significatif apres `=`). On
         * refuse ici, ancre sur le `=`, plutot que d'aspirer la ligne suivante
         * comme valeur d'init. Cf. named_variable. */
        if (crossedNewline) {
            owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EXPR);
            return;
        }
        /*  — diagnostic dedie : `<var> est un tableau de T = [`
         * avec `[` en fin de ligne. Le scanner a lu un TOKEN_MULTILINE_STRING
         * (chaine multi-lignes, fermee par une ligne commencant par `]`), pas
         * un litteral tableau. Sans ce garde, la chaine absorbe la declaration
         * suivante jusqu'au `]` isole, et l'erreur tombe plusieurs lignes plus
         * loin sous la forme "variable inconnue", incomprehensible. On ancre
         * l'erreur sur varName (ligne de la declaration = ligne du `[` ouvrant)
         * car le token multiline porte la ligne de SA fermeture `]`. */
        if (isArray && check(TOKEN_MULTILINE_STRING)) {
            owl_emit_error_at(&varName, E_SYNTAX_TABLEAU_INIT_MULTILIGNE, NULL);
            return;
        }
        /* Lot inline literal : si le RHS est `{`, on est dans un init litteral
         * d'instance. Le type cible est le type de la variable declaree.
         * On tag g_inline_target_type pour que instance_literal le consomme. */
        if (isStruct && check(TOKEN_LEFT_BRACE) && structTypeName.start) {
            g_inline_target_type     = structTypeName.start;
            g_inline_target_type_len = structTypeName.length;
        }
        /*  — Site A : `d est une durée = { ... }`. durée est un
         * keyword TOKEN_DUREE (pas un structTypeName), on tag la cible avec
         * la forme canon accentuée pour que instance_literal prenne la
         * branche durée. La coercion __DureeCoerce (needsCoerce plus bas)
         * wrap l'entier ms produit. */
        if (declaredType == TOKEN_DUREE && check(TOKEN_LEFT_BRACE)) {
            g_inline_target_type     = "dur\xc3\xa9" "e";
            g_inline_target_type_len = (int)strlen("dur\xc3\xa9" "e");
        }
        /*  ( §1-2) — cible `chaine` + RHS littéral colon-brace
         * `{langueXxx: ...}`. On tag g_inline_target_type pour qu'instance_literal
         * construise un ObjMultilingue au lieu d'echouer sur BRACE_LITERAL_NO_TYPE ;
         * la coercition __BufferVersChaine (needsCoerce, declaredType TOKEN_CHAINE)
         * l'aplatit ensuite a la langue active (snapshot fige au moment de
         * l'affectation). Une cible non-texte (entier, reel...) ne pose rien : le
         * `{...}` reste refuse — le type declare est l'unique source de verite. */
        if (declaredType == TOKEN_CHAINE && check(TOKEN_LEFT_BRACE)) {
            g_inline_target_type     = "cha\xc3\xae" "neMultilingue";
            g_inline_target_type_len = (int)strlen("cha\xc3\xae" "neMultilingue");
        }
        /*  — aucune des trois branches ci-dessus n'a cable de type :
         * la cible est un scalaire qui n'accepte pas de litteral `{ }`. On le
         * dit explicitement au parseur du brace, sinon la forme `{cle: valeur}`
         * s'auto-nommerait chaineMultilingue et on perdrait le refus. */
        if (check(TOKEN_LEFT_BRACE) && g_inline_target_type == NULL
            && type_token_refuses_brace_literal(declaredType)) {
            g_inline_target_refuses_literal = true;
        }
        /* For Date/Heure/DateHeure/chaîne/Buffer/FichierDisque: emit coercion
         * function call around the expression. Stack order: [callee] [arg] -> OP_CALL 1
         * - chaîne: __BufferVersChaine (Buffer → String, pass-through sinon) —
         *   conforme au canon (cast auto type 28 → type 16).
         * - Buffer: __ChaineVersBuffer (String → Buffer, pass-through sinon) —
         *   symetrique du chaine, conforme au canon (cast auto
         *   type 16 → type 28).
         * - FichierDisque: __FichierDisqueCoerce wraps int ID (de fOuvre) en
         *   ObjInstance avec methodes prefix. */
        /* Detection coerce composite : extraction du typeName cible pour
         * dispatch via __InstanceCoerce(v, typeName) generique. Le compilo
         * consulte owl_has_instance_coerce qui regarde le registre central
         * (peuple par stdlib_<module>_init() au boot VM via
         * owl_register_instance_coerce).
         *
         * 2 sources possibles pour le typeName :
         *   - declaredType == TOKEN_UUID -> typeName "UUID" (historique
         *     scanner — UUID a son token dedie)
         *   - isStruct + structTypeName -> nom user-fourni (Image,
         *     FichierDisque, et tout futur type composite enregistre).
         *
         * Avantage : ajouter un nouveau type composite (XML, URL, IPv4...)
         * ne demande PAS de toucher compiler.c — juste un appel
         * owl_register_instance_coerce dans le stdlib du nouveau module. */
        char composedTypeName[64];
        char composedTypeNameAscii[64];   /*  */
        composedTypeName[0] = '\0';
        composedTypeNameAscii[0] = '\0';
        if (declaredType == TOKEN_UUID) {
            strcpy(composedTypeName, "UUID");
            strcpy(composedTypeNameAscii, "UUID");
        } else if (isStruct && structTypeName.start != NULL &&
                   structTypeName.length > 0 &&
                   structTypeName.length < (int)sizeof(composedTypeName)) {
            memcpy(composedTypeName, structTypeName.start,
                   (size_t)structTypeName.length);
            composedTypeName[structTypeName.length] = '\0';
            /*  — strip accents pour matcher la registration ASCII
             * des coerces (`owl_register_instance_coerce("Icone", ...)`
             * stocke ASCII, mais composedTypeName peut etre la forme canon
             * accentuee "Icône" issue de la declaration). Sans strip, le
             * `strcmp` du lookup echoue silencieusement → la chaine
             * litterale `est une Icône = "/path.svg"` reste une chaine. */
            int al = scanner_strip_accents(structTypeName.start,
                                           structTypeName.length,
                                           composedTypeNameAscii,
                                           sizeof(composedTypeNameAscii));
            if (al > 0 && al < (int)sizeof(composedTypeNameAscii)) {
                composedTypeNameAscii[al] = '\0';
            } else {
                composedTypeNameAscii[0] = '\0';
            }
        }
        /*  — un type utilisateur homonyme (ex. `Couleur est une
         * Interface/Structure/Classe` masquant le type integre coercible
         * Couleur) masque le canon registry : l'initialiseur ne doit PAS
         * etre passe au coerce registry (`__InstanceCoerce(v, "Couleur")`),
         * qui detruirait l'instance user (ex. transforme le retour d'une
         * fabrique cImplCouleur() en valeur Couleur registry sans classe).
         * Sans homonyme declare, is_known_user_type est faux et le coerce
         * canon reste actif. */
        bool isInstanceCoerce = !isNullable && composedTypeNameAscii[0] != '\0' &&
                                 owl_has_instance_coerce(composedTypeNameAscii) &&
                                 !(structTypeName.start != NULL && structTypeName.length > 0 &&
                                   is_known_user_type(structTypeName.start, structTypeName.length));

        /* Coerce scalaires (Date/Heure/Entier/Reel/Booleen/Monetaire/
         * Numerique/Chaine/Buffer/DateHeure) — chacun a sa native dediee,
         * peu de duplication entre eux car la semantique de parsing est
         * fondamentalement differente par type. Pas concerne par le
         * registre __InstanceCoerce qui est reserve aux composites. */
        /*  — pour les 4 types temporels, la coerce s'applique
         * AUSSI au cas nullable (variante __<T>CoerceNullable qui retourne
         * NIL au lieu du sentinel quand le parse echoue). Sans ca, une
         * chaine invalide affectee a `d est une date? = ...` resterait
         * une chaine brute (drift de type).
         *
         *  — la coerce s'applique AUSSI au cas nullable pour chaine
         * et Buffer, mais PAS pour les autres scalaires. La distinction n'est
         * pas cosmetique, ne pas refactoriser en un `!isNullable` commun :
         *   - __BufferVersChaine / __ChaineVersBuffer commencent par
         *     `if (IS_NIL(v)) return v;` : le temoin Null traverse la coerce
         *     intact, une cible nullable reste donc nullable.
         *   - __EntierCoerce / __ReelCoerce / __BooleenCoerce /
         *     __MonetaireCoerce / __NumeriqueCoerce ecrasent NIL en
         *     zero-value (0, Faux). Les brancher sur une cible nullable
         *     detruirait la distinction Null / zero-value que le `?` promet
         *     (verrouille par tests/runtime/test_collections.owl : `Defile`
         *     sur file vide rend Null dans un `entier?`). Leur cas exige des
         *     variantes __<T>CoerceNullable sur le patron , plus une
         *     semantique du nullable qui reste a ecrire. */
        bool isTemporal = (declaredType == TOKEN_DATE || declaredType == TOKEN_HEURE ||
                           declaredType == TOKEN_DATEHEURE || declaredType == TOKEN_DUREE);
        bool needsCoerce = isTemporal ||
                           declaredType == TOKEN_CHAINE ||
                           declaredType == TOKEN_BUFFER ||
                           (!isNullable && (
                            declaredType == TOKEN_ENTIER ||
                            declaredType == TOKEN_REEL ||
                            declaredType == TOKEN_BOOLEEN ||
                            declaredType == TOKEN_MONETAIRE ||
                            declaredType == TOKEN_NUMERIQUE));

        /* Lot 2d-alpha — type Icone : 2 chemins specifiques.
         *
         * (Q1) Cross-type Image -> Icone : rejet compile-time si le RHS est
         *      un identifiant statiquement typé Image. Le message est
         *      ancre sur (line=ligne courante, column=0) pour ne pas
         *      dependre de la position exacte du token RHS dans le
         *      decoupage scanner.
         *
         * (Q2) Litteral inline `{ icones.X, Couleur = ..., ... }` : stub
         *      consume-and-pop. On consume le bloc sans rien faire de la
         *      semantique (la coerce + props arrive en 2d-beta) et on
         *      pousse NIL. Le test runtime echoue proprement sur l'usage
         *      des props, mais les autres procedures du fichier scenario
         *      continuent a parser.
         */
        /*  : compare en forme ASCII strippee pour reconnaitre
         * aussi la canonical accentuee "Icône" (length=6, byte 0xC3 0xB4
         * pour ô) que le registry expose comme td->canonical. Sans ca,
         * tout init litteral `var est une Icone = { ... }` retombait sur
         * brace_indirection -> reject_type_assignment sur les field names
         * homonymes de types (Couleur, Forme, ...). */
        bool isIconeTarget = false;
        if (isStruct && structTypeName.start != NULL && structTypeName.length > 0) {
            char asciiBuf[32];
            int al = scanner_strip_accents(structTypeName.start,
                                            structTypeName.length,
                                            asciiBuf, sizeof(asciiBuf));
            if (al == 5 && strncasecmp(asciiBuf, "Icone", 5) == 0) {
                isIconeTarget = true;
            }
        }
        bool iconeLiteralStubHandled = false;
        if (isIconeTarget) {
            if (check(TOKEN_IDENTIFIER)) {
                const char* rhsStructTy =
                    resolve_var_struct_type(parser.current.start,
                                            parser.current.length);
                if (rhsStructTy != NULL &&
                    strcasecmp(rhsStructTy, "Image") == 0) {
                    Token errTok = {0};
                    errTok.start  = "";
                    errTok.length = 0;
                    errTok.line   = parser.current.line;
                    errTok.column = 0;
                    errTok.type   = TOKEN_IDENTIFIER;
                    owl_emit_error_at(&errTok,
                                      E_SEM_IMAGE_NOT_ASSIGNABLE_TO_ICONE);
                }
            }
            if (check(TOKEN_LEFT_BRACE)) {
                /* Lot 2e-2 — litteral Icone complet, parseur
                 * factorise en compile_icone_brace_literal_inplace
                 * pour partage avec les props widget (Image = {icones.X,
                 * Couleur = ...} dans un bloc PROPRIETES).
                 *
                 * Le helper laisse l'ObjIcone materialisee au sommet de la
                 * pile ; on signale au path commun (iconeLiteralStubHandled)
                 * que la valeur est deja la — pas de wrap InstanceCoerce
                 * additionnel ni de condition_expression(). */
                compile_icone_brace_literal_inplace();
                iconeLiteralStubHandled = true;
            }
        }

        if (iconeLiteralStubHandled) {
            /* Litteral Icone deja materialise sur le stack par
             * compile_icone_brace_literal_inplace. Skip needsCoerce /
             * isInstanceCoerce / condition_expression. */
        } else {
        if (needsCoerce) {
            /*  — temporels : variante nullable selon isNullable. */
            const char* fn;
            if (isNullable && isTemporal) {
                fn = declaredType == TOKEN_DATE  ? "__DateCoerceNullable" :
                     declaredType == TOKEN_HEURE ? "__HeureCoerceNullable" :
                     declaredType == TOKEN_DUREE ? "__DureeCoerceNullable" :
                                                    "__DateHeureCoerceNullable";
            } else {
                fn = declaredType == TOKEN_DATE        ? "__DateCoerce" :
                     declaredType == TOKEN_HEURE       ? "__HeureCoerce" :
                     declaredType == TOKEN_DUREE       ? "__DureeCoerce" :
                     declaredType == TOKEN_CHAINE      ? "__BufferVersChaine" :
                     declaredType == TOKEN_BUFFER      ? "__ChaineVersBuffer" :
                     declaredType == TOKEN_ENTIER      ? "__EntierCoerce" :
                     declaredType == TOKEN_REEL        ? "__ReelCoerce" :
                     declaredType == TOKEN_BOOLEEN     ? "__BooleenCoerce" :
                     declaredType == TOKEN_MONETAIRE   ? "__MonetaireCoerce" :
                     declaredType == TOKEN_NUMERIQUE   ? "__NumeriqueCoerce" : "__DateHeureCoerce";
            }
            Token fnTok;
            fnTok.start = fn;
            fnTok.length = (int)strlen(fn);
            ConstIdx c = identifier_constant(&fnTok);
            emit_const_op(OP_GET_GLOBAL, c);
        } else if (isInstanceCoerce) {
            Token fnTok;
            fnTok.start = "__InstanceCoerce";
            fnTok.length = 16;
            ConstIdx c = identifier_constant(&fnTok);
            emit_const_op(OP_GET_GLOBAL, c);
        }
        /* `dur est une duree = "..."` -> valide le litteral chaine
         * compile-time (format canon strict [+/-]JHHMMSSCCC, 10 chiffres).
         * Cf. . Le path runtime (dur = fonction()) reste pris en
         * charge par fn_duree_coerce qui pose ErreurDetectee = Vrai.
         *
         * On ne valide QUE le cas chaine litterale isolee (suivie d'un token
         * terminator) — pas si la chaine est l'oprandg d'une expression
         * (`"...".VersDurée(...)`, `"..." + "..."`, etc.). On peek le token
         * suivant via save/restore scanner. */
        if (declaredType == TOKEN_DUREE && check(TOKEN_STRING)) {
            Scanner ss = parser.scanner;
            Token cur = parser.current; Token prev = parser.previous;
            bool nl = crossedNewline;
            Token strTok = parser.current;
            advance_token();
            bool isIsolated = check(TOKEN_EOF) || check(TOKEN_RIGHT_PAREN) ||
                              check(TOKEN_COMMA) || check(TOKEN_SEMICOLON) ||
                              check(TOKEN_NEWLINE) || crossedNewline;
            parser.scanner = ss; parser.current = cur;
            parser.previous = prev; crossedNewline = nl;
            if (isIsolated) check_duree_string_literal(&strTok);
        }
        /*  — symetrique pour Date / Heure / DateHeure : valide
         * le litteral chaine au compile-time via les memes parsers que
         * la coerce runtime (single-parser invariant). */
        if ((declaredType == TOKEN_DATE || declaredType == TOKEN_HEURE ||
             declaredType == TOKEN_DATEHEURE) && check(TOKEN_STRING)) {
            Scanner ss = parser.scanner;
            Token cur = parser.current; Token prev = parser.previous;
            bool nl = crossedNewline;
            Token strTok = parser.current;
            advance_token();
            bool isIsolated = check(TOKEN_EOF) || check(TOKEN_RIGHT_PAREN) ||
                              check(TOKEN_COMMA) || check(TOKEN_SEMICOLON) ||
                              check(TOKEN_NEWLINE) || crossedNewline;
            parser.scanner = ss; parser.current = cur;
            parser.previous = prev; crossedNewline = nl;
            if (isIsolated) check_temporal_string_literal(&strTok, (int)declaredType);
        }
        /* `entier = DateHeure` : rejet compile-time si RHS = identifiant
         * statiquement typé DateHeure. Cf. . */
        check_datetime_to_int_static((int)declaredType);
        /*  — rejet coercion structurelle tableau <-> scalaire (init). */
        check_array_scalar_mismatch_static((int)declaredType);
        /*  — typage strict objet/struct a l'initialisation. Le nom du
         * type declare est dans structTypeName (Token) — copie null-terminee. */
        if (isStruct && structTypeName.start != NULL && structTypeName.length > 0) {
            char lhsTypeZ[128];
            int nz = structTypeName.length < (int)sizeof(lhsTypeZ) - 1
                     ? structTypeName.length : (int)sizeof(lhsTypeZ) - 1;
            memcpy(lhsTypeZ, structTypeName.start, (size_t)nz);
            lhsTypeZ[nz] = '\0';
            check_object_struct_mismatch_static(lhsTypeZ);
        }
        /* Si target = Icone et RHS = literal `icones.X` pur, tag la slot
         * locale fraichement creee avec le nom catalogue X via
         * Local.icone_catalog_name. Sert au tracking pour le warning a
         * l'usage `loc..Couleur = ...`. */
        if (isIconeTarget && current->scopeDepth > 0 &&
            current->localCount > 0) {
            int slot = current->localCount - 1;
            const OwlIconCatalogEntry* iconeEntry =
                icone_peek_literal_at_current();
            if (iconeEntry != NULL && slot < UINT8_COUNT) {
                current->locals[slot].icone_catalog_name = iconeEntry->name;
            }
        }
        condition_expression();  /* RHS d'init, cf bug `<=`/`=` aspire */
        if (needsCoerce) {
            emit_bytes(OP_CALL, 1);
        } else if (isInstanceCoerce) {
            /*  — passe la forme ASCII (strip accents) au runtime
             * pour matcher la registration `owl_register_instance_coerce`
             * cote stdlib. */
            ObjString* sName = obj_copy_string(composedTypeNameAscii,
                                                (int)strlen(composedTypeNameAscii));
            ConstIdx k = make_constant(OBJ_VAL(sName));
            emit_const_op(OP_CONSTANT, k);
            emit_bytes(OP_CALL, 2);
        }
        }  /* fin du else (path standard, hors litteral Icone) */
    } else if (match_token(TOKEN_LESS_EQUAL)) {
        hadExplicitInit = true;
        /* Deep copy initializer: var est un T <= expr */
        condition_expression();
        emit_byte(OP_DEEP_COPY);
    } else if (isArray) {
        /* Default: create array. Emit shape based on collected dimensions. */
        if (arrayDimCount >= 2) {
            /* Multi-dim nested: OP_ARRAY_PRESIZE_ND dimCount dim0 dim1 ... */
            emit_bytes(OP_ARRAY_PRESIZE_ND, (uint8_t)arrayDimCount);
            for (int k = 0; k < arrayDimCount; k++) {
                emit_byte((uint8_t)arrayDims[k]);
            }
        } else if (arrayPresize > 0) {
            emit_bytes(OP_ARRAY_PRESIZE, (uint8_t)arrayPresize);
        } else {
            emit_byte(OP_ARRAY);
        }
        /* If declared as `tableau de <StructureName>`, tag the element type so
         * Ajoute can coerce [v1,v2,...] literals into struct instances. */
        if (arrayElemStructName.start != NULL && arrayElemStructName.length > 0) {
            ObjString* name = obj_copy_string(arrayElemStructName.start,
                                              arrayElemStructName.length);
            ConstIdx nameIdx = make_constant(OBJ_VAL(name));
            emit_const_op(OP_ARRAY_TYPE_STRUCT, nameIdx);
        }
        /* Canon : `tableau de <type>` taggue l'elementPrimKind
         * pour que les extensions (presize, agrandissement, set hors-bornes)
         * créent des cells = valeur par défaut du type, pas Null. Émis pour
         * TOUT tableau typé primitif (même vide à la déclaration). */
        {
            uint8_t fillKind = 0;
            switch (arrayElemTokenType) {
                case TOKEN_CHAINE:    fillKind = 1; break;
                case TOKEN_ENTIER:    fillKind = 2; break;
                case TOKEN_REEL:      fillKind = 3; break;
                case TOKEN_BOOLEEN:   fillKind = 4; break;
                case TOKEN_MONETAIRE: fillKind = 5; break;
                case TOKEN_NUMERIQUE: fillKind = 6; break;
                default: break;
            }
            if (fillKind != 0) {
                emit_bytes(OP_ARRAY_FILL_DEFAULT, fillKind);
            } else if (arrayPresize > 0 && arrayDimCount <= 1
                       && arrayElemStructName.start != NULL
                       && arrayElemStructName.length > 0) {
                /*  — pendant du fill primitif pour un type NOMMÉ :
                 * `tableau de N <Structure>` et `tableau de N <TypeObjet>`
                 * construisent N instances distinctes a la declaration (canon).
                 * Sans ca les cells restaient Null et `t[1].Champ = v` levait
                 * "Acces a un champ sur une valeur Null".
                 *
                 * Le runtime resout le nom dans vm.types (types du registry)
                 * puis vm.globals (structures utilisateur), et ne remplit que
                 * si la resolution rend un ObjInstance. Mesure des cas :
                 *   rempli  — structure utilisateur, type registry compose
                 *             (httpRequete, Couleur).
                 *   no-op   — type registry sans template instance
                 *             (zipArchive, MockNative), classe,
                 *             chaineMultilingue : cells Null, comportement
                 *             anterieur conserve.
                 * Un nom inconnu n'atteint jamais l'opcode : la declaration
                 * est refusee des la compilation. */
                ConstIdx fillIdx = identifier_constant(&arrayElemStructName);
                emit_const_op(OP_ARRAY_FILL_STRUCT, fillIdx);
            }
        }
        /* canon <agrandissement=N>: set growth mode on the newly-created array */
        if (arrayGrowthMode != 0) {
            emit_bytes(OP_ARRAY_GROWTH, (uint8_t)arrayGrowthMode);
        }
    } else if (isAssocArray) {
        /* Emit: __AssocNew(keyType, options, valueKind [, valueTypeName]).
         *  — si un type de valeur NON primitif a été nommé
         * (assocValueTypeName), on l'émet en 4e argument : il pilote
         * l'auto-vivification objet côté runtime. Sinon 3 args (inchangé). */
        Token anTok; anTok.start = "__AssocNew"; anTok.length = 10;
        ConstIdx anConst = identifier_constant(&anTok);
        emit_const_op(OP_GET_GLOBAL, anConst);
        emit_constant(INTEGER_VAL(assocKeyType));
        emit_constant(INTEGER_VAL(assocOptions));
        emit_constant(INTEGER_VAL(assocValueKind));
        if (assocValueTypeName.start != NULL && assocValueTypeName.length > 0) {
            ObjString* vtn = obj_copy_string(assocValueTypeName.start,
                                             assocValueTypeName.length);
            emit_constant(OBJ_VAL(vtn));
            emit_bytes(OP_CALL, 4);
        } else {
            emit_bytes(OP_CALL, 3);
        }
    } else if (isStruct) {
        /* Le record_pending_type_ref est désormais fait plus haut, dès la
         * pose de isStruct/structTypeName, pour couvrir aussi le path avec
         * initialiseur explicite (cf ). */

        /*  : un type registry alias scalaire (Couleur, zipArchive,
         * MockNative...) n'a pas de template global enregistre via
         * register_global_instance -- emettre __StructClone <name>
         * crashait au runtime ("Undefined variable 'Couleur'"). On
         * consulte le registry : si le type declare une defaultValue
         * explicite (hasDefault == true), on l'emet directement comme
         * constante. Sinon path historique __StructClone (types composes
         * avec fields, structures utilisateur, etc.). */
        char probe[128];
        int probeLen = structTypeName.length < (int)sizeof(probe) - 1
                           ? structTypeName.length
                           : (int)sizeof(probe) - 1;
        memcpy(probe, structTypeName.start, probeLen);
        probe[probeLen] = '\0';
        const OwlTypeDef* td = owl_registry_type_find(probe);
        bool isMultilingue = (td != NULL && td->canonicalAscii &&
                              strcmp(td->canonicalAscii, "chaineMultilingue") == 0);
        if (td != NULL && td->hasDefault && td->defaultFactoryNative != NULL) {
            /*  — type objet mutable natif (IAModèle) : instance
             * FRAICHE par declaration via une factory arite 0, plutot que la
             * constante partagee (qui ferait aliaser plusieurs `var est un T`
             * sur le meme objet mutable). Symetrique generique du path
             * chaineMultilingue ci-dessous, pilote par le registre. */
            Token fnTok;
            fnTok.start  = td->defaultFactoryNative;
            fnTok.length = (int)strlen(td->defaultFactoryNative);
            ConstIdx fnIdx = identifier_constant(&fnTok);
            emit_const_op(OP_GET_GLOBAL, fnIdx);
            emit_bytes(OP_CALL, 0);
        } else if (td != NULL && td->hasDefault) {
            emit_constant(td->defaultValue);
        } else if (isMultilingue) {
            /*  lot B : chaineMultilingue est un type mutable —
             * un singleton statique partage casserait la semantique. On
             * emet l'appel d'une factory native __MultilingueNew qui
             * alloue une instance fraiche a chaque declaration. */
            Token fnTok; fnTok.start = "__MultilingueNew"; fnTok.length = 16;
            ConstIdx fnIdx = identifier_constant(&fnTok);
            emit_const_op(OP_GET_GLOBAL, fnIdx);
            emit_bytes(OP_CALL, 0);
        } else {
            /* Create struct instance by cloning template */
            Token cloneName;
            cloneName.start = "__StructClone";
            cloneName.length = 13;
            ConstIdx cloneConst = identifier_constant(&cloneName);
            emit_const_op(OP_GET_GLOBAL, cloneConst);

            ConstIdx nameIdx = identifier_constant(&structTypeName);
            emit_get_type_global(structTypeName.start, structTypeName.length,
                                 nameIdx);   /*  */
            emit_bytes(OP_CALL, 1);
        }
    } else if (declaredType == TOKEN_DATE || declaredType == TOKEN_HEURE ||
               declaredType == TOKEN_DATEHEURE) {
        /* Default: Date -> DateSys(), Heure -> HeureSys(), DateHeure -> DateHeureSys() */
        const char* fn = declaredType == TOKEN_DATE ? "DateSys" :
                         declaredType == TOKEN_HEURE ? "HeureSys" : "DateHeureSys";
        Token fnTok;
        fnTok.start = fn;
        fnTok.length = (int)strlen(fn);
        ConstIdx fnConst = identifier_constant(&fnTok);
        emit_const_op(OP_GET_GLOBAL, fnConst);
        emit_bytes(OP_CALL, 0);
    } else if (declaredType == TOKEN_MONETAIRE) {
        emit_constant(CURRENCY_VAL(0));
    } else if (declaredType == TOKEN_NUMERIQUE) {
        emit_constant(numeric_from_i64(0));
    } else if (declaredType == TOKEN_BUFFER) {
        /* Empty buffer via __BufferNew() native */
        Token bnTok; bnTok.start = "__BufferNew"; bnTok.length = 11;
        ConstIdx bnConst = identifier_constant(&bnTok);
        emit_const_op(OP_GET_GLOBAL, bnConst);
        emit_bytes(OP_CALL, 0);
    } else if (declaredType == TOKEN_UUID && !isNullable) {
        /* UUID nul : clone le template "UUID" enregistré par
         * register_builtin_types (instance ObjInstance avec _bytes = 16 zéros).
         * Trace(MonU) affichera alors "00000000-0000-0000-0000-000000000000"
         * au lieu de "Null". Symétrique du path isStruct → __StructClone.
         *
         * __StructClone prend le template (ObjInstance global "UUID")
         * directement en argument, pas son nom — comme ligne 5527. */
        Token cloneName; cloneName.start = "__StructClone"; cloneName.length = 13;
        ConstIdx cloneConst = identifier_constant(&cloneName);
        emit_const_op(OP_GET_GLOBAL, cloneConst);
        Token uuidTok; uuidTok.start = "UUID"; uuidTok.length = 4;
        ConstIdx nameIdx = identifier_constant(&uuidTok);
        emit_get_type_global("UUID", 4, nameIdx);   /*  (builtin connu) */
        emit_bytes(OP_CALL, 1);
    } else if (declaredType == TOKEN_CHAINE && !isNullable) {
        /* Canon : chaîne non-init = "" (pas Null).
         * Pour `chaîne?` (nullable), l'init reste Null pour distinguer
         * runtime "Null absent" de "chaîne vide affectée". */
        emit_constant(OBJ_VAL(obj_copy_string("", 0)));
    } else if (declaredType == TOKEN_ENTIER && !isNullable) {
        emit_constant(INTEGER_VAL(0));
    } else if (declaredType == TOKEN_REEL && !isNullable) {
        emit_constant(REAL_VAL(0.0));
    } else if (declaredType == TOKEN_BOOLEEN && !isNullable) {
        emit_byte(OP_FALSE);
    } else {
        /* Nullable explicite, Variant, ou type sans init zero-typé prédéfini :
         * Null reste l'état initial — distingue "non affecté" du zéro typé. */
        emit_byte(OP_NIL);
    }

    /* If the variable was declared `<indétectable>`, mask the initial value
     * before storing. The opcode is a no-op for non-strings or already-
     * undetectable strings, so it's safe to emit unconditionally when
     * the flag is set. */
    if (isUndetectable) {
        emit_byte(OP_TO_UNDETECTABLE);
    }

    if (hadExplicitInit) {
        /*  — local confine (scopeDepth 0, mode LOCAL) : marque le slot
         * local comme initialise, sinon faux positif "declaree mais jamais
         * utilisee" alors que l'init est bien present. */
        if ((current->scopeDepth > 0 || g_last_declare_confined) && current->localCount > 0) {
            current->locals[current->localCount - 1].hasInitializer = true;
        } else if (current->scopeDepth == 0 &&
                   (current->type == TYPE_SCRIPT
                    || g_current_control_decl != NULL
                    || g_current_window_decl != NULL
                    /*  — top-level Etat : ouvCompiler est TYPE_FUNCTION
                     * scopeDepth 0 sans g_current_window_decl. Sans ca, une
                     * globale etat `gCode est un entier = 77` (desormais
                     * mangled <ELEM>$gCode) leverait un faux "declaree mais
                     * jamais utilisee". g_current_element_name couvre fenetre
                     * ET etat. */
                    || g_current_element_name[0] != '\0')) {
            /*  lot 1b — le top-level champ est compile en TYPE_FUNCTION
             * (ctrlTopCompiler), pas TYPE_SCRIPT : sans cette branche, une
             * variable de champ avec init `= 0` ne serait pas marquee
             * "initialisee" et leverait un faux "declaree mais jamais utilisee"
             * exposant en plus le nom interne prefixe <ctrl>__var.
             *
             *  — meme probleme au top-level body Fenetre :
             * winTopCompiler est aussi un TYPE_FUNCTION et a scopeDepth 0
             * (volontairement, pour que les variables tombent dans vm.globals
             * et soient visibles depuis les events/procedures). Les variables
             * declarees DANS le body Fenetre (pas dans un sous-champ) ne
             * voyaient pas leur hasInitializer set, d'ou faux positif. */
            global_track_mark_initialized(varName.start, varName.length);
        }
    }

    /*  — une variable GLOBAL declaree au top-level du corps du bloc
     * Projet est hissee en Phase 1 (nom + valeur zero du type) pour qu'un
     * compagnon lance avant le corps de projet.owl la resolve. Gate : corps du
     * bloc Projet (g_in_projet_body, donc PAS la declaration du bloc lui-meme),
     * scopeDepth 0, mode GLOBAL (LOCAL exclu : confine au flux de demarrage). */
    if (g_in_projet_body && current->scopeDepth == 0 && !g_toplevel_confine) {
        projet_global_capture(varName, declaredType, isNullable);
    }

    define_variable(global);

    /* Bloc 'PROPRIETES ... FIN' top-level réservé au type Projet : catalogue
     * de champs figé et validé (comme Style/Fenêtre) — un champ hors du
     * catalogue Projet est rejeté au compile-time. Cf. projet.owl (métadonnées).
     * Les autres types composés (Style, Cadre, Police, httpRequête, ...)
     * restent en assignations linéaires alignées canon. */
    bool isProjet = isStruct && structTypeName.start != NULL
        && ((structTypeName.length == 6
                && strncasecmp(structTypeName.start, "Projet", 6) == 0)
         || (structTypeName.length == 7
                && strncasecmp(structTypeName.start, "Project", 7) == 0));
    if (isProjet && current->scopeDepth == 0) {
        /* Le global projet est une métadonnée du projet, consommée en cascade
         * depuis d'AUTRES fichiers (MonApp..Version). L'heuristique unused
         * single-file est un faux positif ici (comme FEN_/ETAT_) : on marque le
         * global initialisé pour le taire, y compris quand PROPRIETES est vide. */
        global_track_mark_initialized(varName.start, varName.length);
    }
    if (current->scopeDepth == 0 && isProjet && !isClass && !isArray
        && !hadExplicitInit) {
        /* Peek non destructif : sauve scanner+parser. */
        Scanner sSaved   = parser.scanner;
        Token   curSaved = parser.current;
        Token   prevSaved = parser.previous;
        bool    crossedSaved = crossedNewline;

        while (check(TOKEN_NEWLINE)) advance_token();

        if (check(TOKEN_PROPRIETES)) {
            advance_token();  /* consume PROPRIETES */
            /*  — capture l'identifiant du bloc Projet pour la
             * materialisation precoce du global de metadonnees (cascade
             * cross-fichier avant execution des compagnons). */
            projet_meta_set_ident(varName);
            /* Projet : Langues est obligatoire (au moins une langue). On suit
             * sa présence pendant la boucle des champs pour rejeter, au FIN du
             * bloc, un projet qui ne la déclare pas. Les autres métadonnées
             * (Description/Auteur/Licence) restent optionnelles. */
            bool languesSeen = false;
            /* Body : <prop> = <expr> (les métadonnées projet sont des
             * scalaires plats + le champ liste Langues). */
            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                while (check(TOKEN_NEWLINE)) advance_token();
                if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
                if (!check(TOKEN_IDENTIFIER)) {
                    owl_emit_error_current(E_SYNTAX_EXPECTED_VAR_NAME_IN_PROJET_PROPS);
                    advance_token();
                    continue;
                }

                Token varTok = parser.current;
                advance_token();  /* consume var name */

                /* Projet : catalogue figé — un champ hors du catalogue du type
                 * est rejeté (aligné sur la validation Style/Fenêtre). */
                if (!object_field_known("Projet", 6, varTok)) {
                    emit_object_field_unknown("Projet", 6, varTok);
                }

                /* Push instance globale via OP_GET_GLOBAL <varName>. */
                ConstIdx varConst = identifier_constant(&varName);
                emit_const_op(OP_GET_GLOBAL, varConst);

                consume(TOKEN_EQUAL, E_SYNTAX_EXP_EQUAL_PROJET_FIELD);

                /*  — champ Langues : liste (ou constante unique) de
                 * constantes langue officielles. Voie de parse dediee (le
                 * const-folder scalaire ne gere pas les litteraux liste). */
                bool isLangues = (varTok.length == 7
                         && strncasecmp(varTok.start, "Langues", 7) == 0)
                     || (varTok.length == 9
                         && strncasecmp(varTok.start, "Languages", 9) == 0);

                /*  — champ Theme : reference typee vers une instance
                 * `est un Theme` (voie dediee, le const-folder rejetterait une
                 * reference de globale). Bilingue Theme, accent-insensible. */
                char themeFieldProbe[32];
                int themeFieldLen = scanner_strip_accents(
                    varTok.start, varTok.length,
                    themeFieldProbe, sizeof(themeFieldProbe));
                bool isTheme = (themeFieldLen == 5
                    && strncasecmp(themeFieldProbe, "Theme", 5) == 0);

                /*  — champ FenetreDemarrage / StartupWindow : reference
                 * typee vers une instance `est une Fenetre` (voie dediee, meme
                 * famille que Theme). Bilingue, accent-insensible. */
                bool isFenetreDemarrage = (themeFieldLen == 16
                        && strncasecmp(themeFieldProbe, "FenetreDemarrage", 16) == 0)
                    || (themeFieldLen == 13
                        && strncasecmp(themeFieldProbe, "StartupWindow", 13) == 0);

                /*  — champ FormatNombre / NumberFormat : litteral
                 * composite inline `{ ... }`. Voie dediee (le const-folder
                 * scalaire ne construit pas d'instance). Bilingue, accent-insensible. */
                bool isFormatNombre = (themeFieldLen == 12
                        && strncasecmp(themeFieldProbe, "FormatNombre", 12) == 0)
                    || (themeFieldLen == 12
                        && strncasecmp(themeFieldProbe, "NumberFormat", 12) == 0);

                /*  — champ FormatMonétaire / CurrencyFormat : litteral
                 * composite inline `{ ... }`, voie dediee (miroir FormatNombre). */
                bool isFormatMonetaire = (themeFieldLen == 15
                        && strncasecmp(themeFieldProbe, "FormatMonetaire", 15) == 0)
                    || (themeFieldLen == 14
                        && strncasecmp(themeFieldProbe, "CurrencyFormat", 14) == 0);

                if (isLangues) {
                    languesSeen = true;
                    projet_emit_langues_value(varTok);
                } else if (isTheme) {
                    projet_emit_theme_value(varTok);
                } else if (isFenetreDemarrage) {
                    projet_emit_fenetre_demarrage_value(varTok);
                } else if (isFormatNombre) {
                    projet_emit_format_nombre_value(varTok);
                } else if (isFormatMonetaire) {
                    projet_emit_format_monetaire_value(varTok);
                } else {
                    /* Introspectabilite du manifeste : la valeur
                     * d'une metadonnee projet doit etre une expression
                     * constante — litteral, constante du registre, const-fold
                     * numerique ou native pure. Lire les metadonnees ne doit
                     * jamais exiger d'executer du code metier (le trou setup.py).
                     * On reutilise la machinerie const-folder du DSL fenetre :
                     * si elle consomme toute la RHS jusqu'au terminateur, la
                     * valeur est constante ; sinon (appel de proc, variable,
                     * concat de chaines non foldee) -> rejet compile-time. */
                    Scanner vScan = parser.scanner;
                    Token   vCur  = parser.current;
                    Token   vPrev = parser.previous;
                    bool    vNl   = crossedNewline;
                    Value   constVal;
                    /* Une valeur pleinement const-foldee laisse le curseur sur
                     * un terminateur de champ : NEWLINE, le nom du champ suivant
                     * (IDENTIFIER — les NEWLINE sont escamotes dans ce contexte),
                     * FIN, ou EOF. Un reliquat d'operateur (ex. `"1." + "0"`, non
                     * folde car concat de chaines) laisse un PLUS/MINUS/... et
                     * signale une expression non entierement constante -> rejet. */
                    bool isConst = window_try_parse_const_literal(&constVal)
                        && (check(TOKEN_NEWLINE) || check(TOKEN_IDENTIFIER)
                            || check(TOKEN_FIN) || check(TOKEN_EOF));
                    if (isConst) {
                        /*  — capture le champ scalaire constant pour
                         * la materialisation precoce du global de metadonnees. */
                        projet_meta_add_field(varTok, constVal);
                        emit_constant(constVal);
                    } else {
                        /* Rollback + erreur + consommation de la RHS pour
                         * eviter une cascade de parse errors. */
                        parser.scanner  = vScan;
                        parser.current  = vCur;
                        parser.previous = vPrev;
                        crossedNewline  = vNl;
                        char nameBuf[128];
                        snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                                 varTok.length, varTok.start);
                        owl_emit_error_at(&varTok,
                                          E_SEM_PROJET_METADATA_NOT_CONSTANT,
                                          "name", nameBuf,
                                          NULL);
                        condition_expression();
                    }
                }

                ConstIdx propConst = identifier_constant(&varTok);
                emit_const_op(OP_STRUCT_SET, propConst);
                emit_byte(OP_POP);
            }
            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROPRIETES_PROJET);

            /* Projet : Langues obligatoire. Un bloc Projet qui ne la déclare
             * pas (y compris PROPRIETES vide) est rejeté. Emis au FIN du bloc,
             * une fois tous les champs vus, sur l'identifiant du projet. */
            if (!languesSeen) {
                owl_emit_error_at(&varName, E_SEM_PROJET_LANGUES_MANQUANT, NULL);
            }

            /*  — corps du bloc Projet = le programme d'initialisation
             * ( amende). Apres PROPRIETES, on accepte des statements
             * executables (l'init, ex. Ouvre(...)) et des declarations de
             * variables : emis inline dans le chunk top-level, ils forment le
             * programme (execute en dernier par project_run, ordre inchange).
             * Seuls les events projet canoniques (Fermeture/Closing) sont des
             * PROCEDUREs autorisees ; toute autre procedure utilisateur est
             * rejetee (un helper vit dans une classe / une collection de
             * procedures). Le bloc se termine sur un FIN final. */
            /*  — corps du bloc Projet = contexte top-level : mode
             * GLOBAL par defaut, LOCAL/GLOBAL basculables dedans. */
            bool savedConfineProjet = g_toplevel_confine;
            g_toplevel_confine = false;
            bool savedInProjetBody = g_in_projet_body;  /*  */
            g_in_projet_body = true;
            while (check(TOKEN_NEWLINE)) advance_token();
            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                if (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION)) {
                    /* Peek non destructif du nom de la procedure. */
                    Scanner pScan = parser.scanner;
                    Token   pCur  = parser.current;
                    Token   pPrev = parser.previous;
                    bool    pNl   = crossedNewline;
                    advance_token();  /* consume PROCEDURE/FONCTION */
                    Token procNameTok = parser.current;
                    bool  isEvent = procNameTok.type == TOKEN_IDENTIFIER
                        && projet_event_proc_allowed(procNameTok.start,
                                                     procNameTok.length);
                    parser.scanner  = pScan;
                    parser.current  = pCur;
                    parser.previous = pPrev;
                    crossedNewline  = pNl;
                    if (!isEvent) {
                        char nameBuf[128];
                        snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                                 procNameTok.length, procNameTok.start);
                        owl_emit_error_at(&procNameTok,
                                          E_SEM_PROJET_USER_PROC_FORBIDDEN,
                                          "name", nameBuf, NULL);
                        parser.panicMode = false;  /* le parse continue proprement */
                    }
                }
                declaration();
                while (check(TOKEN_NEWLINE)) advance_token();
            }
            g_in_projet_body = savedInProjetBody;      /*  */
            g_toplevel_confine = savedConfineProjet;  /*  */
            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROJET);
            /*  — bloc Projet pleinement parse : tout construct
             * top-level apres ce FIN final est hors-la-loi (verrou top-level). */
            g_projet_block_parsed = true;
        } else {
            /*  — bloc Projet declare sans PROPRIETES : le bloc est
             * incomplet (PROPRIETES obligatoire, au moins Langues). On emet un
             * message dedie plutot que de laisser le verrou top-level generique
             * (enforce_projet_file_isolation_at_top_level) parler a tort d'une
             * instruction a deplacer alors qu'aucune n'existe. hadFileError
             * silence ce verrou sur le FIN orphelin qui suit. */
            parser.scanner   = sSaved;
            parser.current   = curSaved;
            parser.previous  = prevSaved;
            crossedNewline   = crossedSaved;
            char nameBuf[128];
            snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                     varName.length, varName.start);
            owl_emit_error_at(&varName, E_SEM_PROJET_PROPRIETES_MANQUANT,
                              "name", nameBuf, NULL);
            /* Recuperation : l'utilisateur a probablement pose un FIN "de bloc"
             * apres la declaration (bloc Projet incomplet). On l'avale pour
             * eviter qu'il ne cascade en "Expression attendue" et que le verrou
             * top-level generique ne le signale a tort comme du code hors bloc. */
            while (check(TOKEN_NEWLINE)) advance_token();
            if (check(TOKEN_FIN)) advance_token();
            parser.panicMode = false;
        }
    }
}

/* Parse: SI <expr> ALORS <body> [SINON <body>] FIN
 *    OR: SI <expr> ALORS <single-statement>          (same line, no FIN)
 *
 * Single-line form: if the next token after ALORS is on the same source
 * line as ALORS, parse exactly one statement and skip the FIN requirement.
 * Shortcut for early-return / early-break patterns. */
static void if_statement(void) {
    /* We collect all end-jumps to patch at the very end */
    int endJumps[64];
    int endJumpCount = 0;

    /* --- First SI branch --- */
    condition_expression();
    /* Canon strict : refuse les types non-booléens en condition.
     * Runtime check via OP_VERIFY_BOOL_COND avant le jump. */
    emit_byte(OP_VERIFY_BOOL_COND);
    consume(TOKEN_ALORS, E_SYNTAX_EXP_ALORS_AFTER_COND);
    int alorsLine = parser.previous.line;

    int thenJump = emit_jump(OP_JUMP_IF_FALSE);
    emit_byte(OP_POP);

    /* Detect single-line form: body begins on the same line as ALORS. */
    bool singleLine = (parser.current.line == alorsLine &&
                       !check(TOKEN_SINON) && !check(TOKEN_FIN) &&
                       !check(TOKEN_EOF));

    begin_scope();
    if (singleLine) {
        declaration();  /* one statement, no FIN */
    } else {
        while (!check(TOKEN_SINON) && !check(TOKEN_FIN) && !check(TOKEN_EOF)) {
            declaration();
        }
    }
    end_scope();

    endJumps[endJumpCount++] = emit_jump(OP_JUMP);
    patch_jump(thenJump);
    emit_byte(OP_POP);

    /* Single-line form: no FIN expected. Optionnel : branche SINON sur
     * la même ligne que ALORS (`SI cond ALORS x SINON y`). Symétrique :
     * 1 declaration() par branche, pas de FIN. */
    if (singleLine) {
        if (check(TOKEN_SINON) && parser.current.line == alorsLine) {
            advance_token();  /* consume SINON */
            begin_scope();
            declaration();
            end_scope();
        }
        /* FIN parasite sur la même ligne : reflexe naturel (« SI cond
         * ALORS instr FIN ») qui produirait sinon le cryptique « Expected
         * expression » au top-level. On capture pour diagnostic ciblé et
         * on avale le FIN pour éviter une erreur cascade au parser racine. */
        if (check(TOKEN_FIN) && parser.current.line == alorsLine) {
            owl_emit_error_current(E_SYNTAX_SHORT_SI_FIN_SAME_LINE);
            advance_token();
        }
        for (int i = 0; i < endJumpCount; i++) patch_jump(endJumps[i]);
        return;
    }

    /* --- SINON SI chains --- */
    while (check(TOKEN_SINON)) {
        advance_token(); /* consume SINON */

        /* Désambiguïsation elif vs SI imbriqué dans la branche SINON :
         *   `SINON SI cond ALORS ...`  (SI sur la même ligne) = clause elif,
         *      un seul FIN ferme toute la structure.
         *   `SINON` <newline> `SI ... FIN`                     = branche SINON
         *      ouvrant un bloc qui CONTIENT un SI imbriqué (FIN propre), puis
         *      le FIN de la structure.
         * Le séparateur (newline/`;`) entre SINON et SI, tracké par
         * crossedNewline lors de l'advance ci-dessus, tranche le cas. Un SI
         * séparé par un newline n'est pas une continuation de la condition. */
        if (check(TOKEN_SI) && !crossedNewline) {
            advance_token(); /* consume SI */
            condition_expression();
            emit_byte(OP_VERIFY_BOOL_COND);
            consume(TOKEN_ALORS, E_SYNTAX_EXP_ALORS_AFTER_SINONSI);

            int elseIfJump = emit_jump(OP_JUMP_IF_FALSE);
            emit_byte(OP_POP);

            begin_scope();
            while (!check(TOKEN_SINON) && !check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                declaration();
            }
            end_scope();

            if (endJumpCount < 64) {
                endJumps[endJumpCount++] = emit_jump(OP_JUMP);
            }
            patch_jump(elseIfJump);
            emit_byte(OP_POP);
            /* Continue loop to check for more SINON SI or final SINON */
        } else {
            /* Plain SINON (final else) */
            begin_scope();
            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                declaration();
            }
            end_scope();
            break;
        }
    }

    /* Patch all end-jumps to here */
    for (int i = 0; i < endJumpCount; i++) {
        patch_jump(endJumps[i]);
    }

    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_SI);
}

/* Parse: POUR <id> = <start> A <end> [PAS <step>] ... FIN */
static void for_statement(void) {
    begin_scope();

    consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_LOOP_VAR_NAME);
    Token varName = parser.previous;
    declare_variable(&varName);

    consume(TOKEN_EQUAL, E_SYNTAX_EXP_EQUAL_LOOP_VAR);
    expression();

    /* Détection du token A / _A_ — canon : sans soulignement = re-eval
     * (borne ré-évaluée à chaque tour), avec soulignements = eval unique. */
    bool boundReEval = false;
    if (match_token(TOKEN_A)) {
        boundReEval = true;        /* canon : `A` / `TO` (sans soulignement) */
    } else if (match_token(TOKEN_A_SC)) {
        boundReEval = false;       /* `_A_` / `_TO_` : eval unique */
    } else {
        owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_TO_AFTER_START);
    }

    /* Capture du slice bytecode de la borne si re-eval. Stratégie alignée
     * sur AVEC dans foreach_array_statement : on compile l'expression dans
     * le chunk, on copie les octets émis dans un buffer scratch persistant,
     * puis on truncate le chunk principal pour annuler l'émission. À chaque
     * test d'arrêt, on réinjecte le slice via chunk_insert_before/append.
     *
     * Pourquoi pas garder le bytecode initial en place ? Parce que la borne
     * serait alors évaluée 1 fois au début (pollue le compteur d'effets de
     * bord) PUIS à chaque tour, soit N+2 appels au lieu des N+1 canon
     * (N tours + 1 test final). Avec truncate, on n'évalue qu'aux tours
     * (et au test d'arrêt initial).
     *
     * Validation compile-time : pas d'opcode de contrôle de flux dans le
     * slice (offsets internes deviendraient invalides après copie à un
     * offset différent). */
    Token boundOpenTok   = parser.current;  /* pour error_at en cas de rejet */
    uint8_t boundSlice[256];
    int     boundSliceLine[256];
    int     boundSliceLen = 0;

    int boundStart = current_chunk()->count;
    expression();
    int boundEnd   = current_chunk()->count;

    if (boundReEval) {
        int len = boundEnd - boundStart;
        /* Si la borne s'ouvre sur une parenthèse, on décale le pointage de
         * l'erreur d'un caractère pour viser le 1er token significatif à
         * l'intérieur — cohérent avec la position attendue par les tests
         * snapshot et l'intuition utilisateur (l'erreur porte sur le contenu
         * complexe, pas sur la parenthèse). */
        Token errTok = boundOpenTok;
        if (errTok.type == TOKEN_LEFT_PAREN) errTok.column++;
        if (len > (int)sizeof(boundSlice)) {
            owl_emit_error_at(&errTok, E_SEM_FOR_BOUND_REEVAL_TOO_LARGE);
            boundReEval = false;
        } else if (chunk_slice_has_jumps(current_chunk(),
                                         boundStart, len)) {
            owl_emit_error_at(&errTok, E_SEM_FOR_BOUND_REEVAL_COMPLEX);
            boundReEval = false;
        } else {
            /* Snapshot avant truncate : on copie les octets ET les lignes. */
            memcpy(boundSlice, current_chunk()->code + boundStart, (size_t)len);
            for (int i = 0; i < len; i++) {
                boundSliceLine[i] = current_chunk()->lines[boundStart + i];
            }
            boundSliceLen = len;
            /* Truncate : retire l'émission initiale du chunk. Le slot endSlot
             * recevra une valeur placeholder NIL plus bas. */
            current_chunk()->count = boundStart;
            emit_byte(OP_NIL);
        }
    }

    /* Détection optionnelle DepuisFin / DepuisDébut AVANT le bloc PAS (ordre
     * `POUR i = 1 A 5 DepuisFin [PAS ...]`). DepuisFin sans PAS impose un
     * step -1 implicite et inverse les bornes ; DepuisDébut est un no-op
     * explicite (sens ascendant par défaut). Combinaison DepuisFin + PAS
     * (dans n'importe quel ordre) est rejetée plus bas comme mutex strict.
     *
     * Si la borne était en mode re-eval (`A` / `À` sans soulignement) et que
     * DepuisFin est demandé, on retombe sur eval-unique : la sémantique
     * "re-eval + inversion" n'a pas d'utilité observable (DepuisFin signifie
     * inverser une plage, pas re-évaluer dynamiquement), et le swap initial
     * a besoin d'une vraie valeur dans endSlot — pas un OP_NIL placeholder. */
    bool depuisFin = false;
    Token depuisFinTok = {0};
    {
        if (check(TOKEN_IDENTIFIER)) {
            Token tok = parser.current;
            char stripped[32];
            int n = scanner_strip_accents(tok.start, tok.length,
                                          stripped, sizeof(stripped));
            for (int i = 0; i < n; i++) {
                if (stripped[i] >= 'A' && stripped[i] <= 'Z') stripped[i] += 32;
            }
            if (n == 9 && memcmp(stripped, "depuisfin", 9) == 0) {
                depuisFin = true;
                depuisFinTok = tok;
                advance_token();
            } else if (n == 11 && memcmp(stripped, "depuisdebut", 11) == 0) {
                advance_token();  /* no-op explicite, ascendant par défaut */
            }
        }
    }

    /* Rollback du truncate si DepuisFin + boundReEval : on restaure le
     * bytecode original de la borne pour que endSlot ait une valeur réelle
     * (pas un NIL placeholder). Le slice persistant a été copié en stack,
     * on le rewrite par-dessus le OP_NIL et on désactive boundReEval. */
    if (depuisFin && boundReEval) {
        /* Chunk actuel: [..., boundStart..boundStart] = OP_NIL (1 byte).
         * On retire le OP_NIL et on réinjecte le slice complet. */
        current_chunk()->count = boundStart;
        for (int i = 0; i < boundSliceLen; i++) {
            chunk_write(current_chunk(), boundSlice[i], boundSliceLine[i]);
        }
        boundReEval = false;
        boundSliceLen = 0;
    }

    bool hasStep = false;
    /* Sign of the step at compile time:
     *    +1 = known positive (ascending, use `i <= end`)
     *    -1 = known negative (descending, use `i >= end`)
     *     0 = unknown at compile time (fall back to runtime check)
     * Default step = 1 (positive) when no PAS clause is present. */
    int stepSign = 1;
    bool stepReEval = false;
    uint8_t stepSlice[256];
    int     stepSliceLine[256];
    int     stepSliceLen = 0;
    Token stepOpenTok = parser.current;
    if (match_token(TOKEN_PAS) || match_token(TOKEN_PAS_SC)) {
        if (depuisFin) {
            /* Mutex DepuisFin + PAS : DepuisFin a déjà imposé un step -1
             * implicite. Refus net (ordre DepuisFin avant PAS). */
            owl_emit_error_at(&parser.previous, E_SEM_FOR_DEPUISFIN_PAS_MUTEX);
        }
        stepReEval = (parser.previous.type == TOKEN_PAS);
        stepOpenTok = parser.current;
        int stepStartOffset = current_chunk()->count;
        expression();
        hasStep = true;
        int stepEndOffset = current_chunk()->count;
        int stepLen = stepEndOffset - stepStartOffset;

        if (stepReEval) {
            if (stepLen > (int)sizeof(stepSlice)) {
                owl_emit_error_at(&stepOpenTok,
                                  E_SEM_FOR_STEP_REEVAL_TOO_LARGE);
                stepReEval = false;
            } else if (chunk_slice_has_jumps(current_chunk(),
                                             stepStartOffset, stepLen)) {
                owl_emit_error_at(&stepOpenTok,
                                  E_SEM_FOR_STEP_REEVAL_COMPLEX);
                stepReEval = false;
            } else {
                memcpy(stepSlice,
                       current_chunk()->code + stepStartOffset,
                       (size_t)stepLen);
                for (int i = 0; i < stepLen; i++) {
                    stepSliceLine[i] = current_chunk()->lines[stepStartOffset + i];
                }
                stepSliceLen = stepLen;
                current_chunk()->count = stepStartOffset;
                emit_byte(OP_NIL);  /* placeholder dans stepSlot */
            }
        }

        /* Détection compile-time du signe du step.
         *
         * Forme _PAS_ (eval unique) : lecture directe dans le chunk principal
         * (le bytecode est encore en place). Pattern [OP_CONSTANT idx] ou
         * [OP_CONSTANT idx, OP_NEGATE].
         *
         * Forme PAS (re-eval) : le slice a été truncate, mais on en a une
         * copie persistante (stepSlice). On y détecte le même pattern.
         * Sémantique : un step litéral constant ne change pas entre les
         * tours — l'optimisation de signe est sûre. Pour un step non-litéral
         * en re-eval (appel de fonction), on assume positif (canon le plus
         * courant) ; descendante avec step variable demande '_PAS_'.
         *
         * Le test d'arrêt utilise le signe inféré ; l'incrément ré-évalue
         * le step (slice complet) à chaque tour si reEval. */
        const uint8_t* sliceBytes = NULL;
        int            sliceN     = 0;
        if (stepReEval) {
            sliceBytes = stepSlice;
            sliceN     = stepSliceLen;
            stepSign   = 1;   /* fallback si pas un litéral constant */
        } else {
            sliceBytes = current_chunk()->code + stepStartOffset;
            sliceN     = stepLen;
            stepSign   = 0;
        }
        Chunk* ck = current_chunk();
        /* La longueur d'un `[OP_CONSTANT][index]` vient de la table canonique
         * (l'index n'est plus forcement sur un octet). */
        int constLen = chunk_opcode_size(OP_CONSTANT, ck, 0);
        if (sliceN >= constLen && sliceBytes[0] == OP_CONSTANT &&
            (sliceN == constLen ||
             (sliceN == constLen + 1 && sliceBytes[constLen] == OP_NEGATE))) {
            bool negated = (sliceN == constLen + 1);
            int idx = (constLen == 2)
                        ? sliceBytes[1]
                        : ((sliceBytes[1] << 8) | sliceBytes[2]);
            Value v = ck->constants.values[idx];
            if (IS_INTEGER(v)) {
                int64_t s = AS_INTEGER(v);
                int sign = (s > 0) ? 1 : (s < 0) ? -1 : 0;
                if (sign != 0) stepSign = negated ? -sign : sign;
            }
        }
    }

    /* Second peek DepuisFin / DepuisDébut APRÈS le bloc PAS (ordre
     * `POUR i = 1 A 5 PAS 2 DepuisFin`). Si PAS déjà consommé, c'est mutex. */
    if (check(TOKEN_IDENTIFIER)) {
        Token tok = parser.current;
        char stripped[32];
        int n = scanner_strip_accents(tok.start, tok.length,
                                      stripped, sizeof(stripped));
        for (int i = 0; i < n; i++) {
            if (stripped[i] >= 'A' && stripped[i] <= 'Z') stripped[i] += 32;
        }
        if (n == 9 && memcmp(stripped, "depuisfin", 9) == 0) {
            if (hasStep) {
                owl_emit_error_current(E_SYNTAX_DEPUISFIN_STEP_EXCLUSIVE);
            } else if (depuisFin) {
                /* Doublon DepuisFin DepuisFin — improbable mais propre. */
                owl_emit_error_current(E_SYNTAX_DEPUISFIN_DUPLICATE);
            }
            depuisFin = true;
            depuisFinTok = tok;
            advance_token();
        } else if (n == 11 && memcmp(stripped, "depuisdebut", 11) == 0) {
            advance_token();  /* no-op explicite */
        }
    }

    (void)depuisFinTok; /* Réservé : pourrait servir si on ré-introduit une
                         * diagnostic positionnée sur ce token (mutex/etc.). */

    add_local((Token){.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER});

    if (!hasStep) {
        /* DepuisFin sans PAS explicite : step -1 implicite. Sinon +1. */
        emit_constant(INTEGER_VAL(depuisFin ? -1 : 1));
        if (depuisFin) stepSign = -1;
    }
    add_local((Token){.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER});

    int varSlot = resolve_local(current, &varName);
    int endSlot = varSlot + 1;
    int stepSlot = endSlot + 1;

    /* DepuisFin avec borne eval-unique : swap les valeurs varSlot ↔ endSlot
     * AVANT loopStart. Sémantique : `POUR i = a A b DepuisFin` devient
     * `POUR i = b A a PAS -1` (i parcourt b, b-1, ..., a inclus). */
    if (depuisFin && !boundReEval) {
        emit_bytes(OP_GET_LOCAL, (uint8_t)varSlot);
        emit_bytes(OP_GET_LOCAL, (uint8_t)endSlot);
        emit_bytes(OP_SET_LOCAL, (uint8_t)varSlot);
        emit_byte(OP_POP);
        emit_bytes(OP_SET_LOCAL, (uint8_t)endSlot);
        emit_byte(OP_POP);
    }

    int loopStart = current_chunk()->count;
    push_loop(loopStart, true); /* deferred continue for POUR */

    /* Helpers locaux : en mode re-eval on injecte le slice bytecode capturé
     * depuis le buffer scratch ; en mode eval-unique on lit le slot local
     * (comportement historique).
     *
     * Note GC-safety : chunk_write peut réallouer le buffer interne, mais
     * boundSlice/stepSlice vivent dans la stack frame du compiler donc pas
     * de souci de dangling pointer. */
    #define EMIT_GET_END() do { \
        if (boundReEval) { \
            for (int _bi = 0; _bi < boundSliceLen; _bi++) \
                chunk_write(current_chunk(), boundSlice[_bi], boundSliceLine[_bi]); \
        } else { \
            emit_bytes(OP_GET_LOCAL, (uint8_t)endSlot); \
        } \
    } while (0)
    #define EMIT_GET_STEP() do { \
        if (stepReEval) { \
            for (int _si = 0; _si < stepSliceLen; _si++) \
                chunk_write(current_chunk(), stepSlice[_si], stepSliceLine[_si]); \
        } else { \
            emit_bytes(OP_GET_LOCAL, (uint8_t)stepSlot); \
        } \
    } while (0)

    /* Emit the termination check. When the step sign is known at compile
     * time (the default, and most explicit PAS uses), we emit only the
     * matching comparison -- skipping the runtime step-sign check that
     * otherwise dominates empty-body POUR loops. Saves ~5 opcodes per
     * iteration on the hot path. */
    int exitJump;
    if (stepSign > 0) {
        /* Ascending (default case: no PAS, or _PAS_ +N) -- `i <= end`. */
        emit_bytes(OP_GET_LOCAL, (uint8_t)varSlot);
        EMIT_GET_END();
        emit_byte(OP_LESS_EQUAL);
        exitJump = emit_jump(OP_JUMP_IF_FALSE);
        emit_byte(OP_POP);
    } else if (stepSign < 0) {
        /* Descending (`_PAS_ -N`) -- `i >= end`. */
        emit_bytes(OP_GET_LOCAL, (uint8_t)varSlot);
        EMIT_GET_END();
        emit_byte(OP_GREATER_EQUAL);
        exitJump = emit_jump(OP_JUMP_IF_FALSE);
        emit_byte(OP_POP);
    } else {
        /* Unknown at compile time: runtime branch on step sign. */
        EMIT_GET_STEP();
        emit_constant(INTEGER_VAL(0));
        emit_byte(OP_GREATER_EQUAL);

        int positiveJump = emit_jump(OP_JUMP_IF_FALSE);
        emit_byte(OP_POP);

        emit_bytes(OP_GET_LOCAL, (uint8_t)varSlot);
        EMIT_GET_END();
        emit_byte(OP_LESS_EQUAL);
        int condJump = emit_jump(OP_JUMP);

        patch_jump(positiveJump);
        emit_byte(OP_POP);
        emit_bytes(OP_GET_LOCAL, (uint8_t)varSlot);
        EMIT_GET_END();
        emit_byte(OP_GREATER_EQUAL);

        patch_jump(condJump);

        exitJump = emit_jump(OP_JUMP_IF_FALSE);
        emit_byte(OP_POP);
    }

    /*  — Capture l'etat isUsed du local POUR avant le corps puis
     * le reset. Le `varSlot = resolve_local(...)` plus haut a deja marque
     * isUsed=true ; on isole les usages effectifs dans le corps (qui
     * passent par resolve_local depuis les expressions utilisateur). Le
     * test d'arret et l'increment qui suivent emettent OP_GET_LOCAL en
     * direct (sans resolve_local), donc ne re-flagent pas. Restauration
     * apres lecture pour eviter un faux warning sur le slot POUR
     * lui-meme via warn_unused_locals du end_scope. */
    current->locals[varSlot].isUsed = false;

    begin_scope(); /* body scope: locals declared here are cleaned each iteration */
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        declaration();
    }
    end_scope(); /* clean up body locals before increment */

    bool bodyUsesIterator = current->locals[varSlot].isUsed;
    current->locals[varSlot].isUsed = true;  /* restore : evite faux warning sur le slot POUR */

    /* Set continue target to the increment code */
    patch_loop_continues();

    emit_bytes(OP_GET_LOCAL, (uint8_t)varSlot);
    EMIT_GET_STEP();
    emit_byte(OP_ADD);
    emit_bytes(OP_SET_LOCAL, (uint8_t)varSlot);
    emit_byte(OP_POP);

    emit_loop(loopStart);

    patch_jump(exitJump);
    emit_byte(OP_POP);

    /*  — Si le corps de la boucle a reference l'iterateur, on
     * propage l'usage a une eventuelle variable de meme nom declaree au
     * scope englobant : sans ca, le pattern canon
     *    i est un entier
     *    POUR i = 1 _A_ N
     *        ... i ...
     *    FIN
     * declenche un faux positif "Variable 'i' declaree mais jamais
     * utilisee" sur la declaration externe, qui est en realite shadow
     * par le local POUR. Si le corps ne touche PAS i, le warning reste
     * (vrai positif — la declaration externe est inutile). */
    if (bodyUsesIterator) {
        /* Local englobant de meme nom (scope parent). */
        for (int li = varSlot - 1; li >= 0; li--) {
            if (identifiers_equal(&varName, &current->locals[li].name)) {
                current->locals[li].isUsed = true;
                break;
            }
        }
        /* Global de meme nom (no-op safe si pas global). */
        global_track_mark_used(varName.start, varName.length);
    }

    pop_loop();
    end_scope(); /* outer for scope: i, end, step */
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_POUR);

    #undef EMIT_GET_END
    #undef EMIT_GET_STEP
}

/* ---------------------------------------------------------------------------
 * POUR TOUT — statement de parcours générique.
 *
 * Cinq formes supportées (doc 1510016/1510018/1510019) :
 *   1. POUR TOUT[E] [ELEMENT] v [, idx]  DE <iterable> [AVEC <cond>] [<sens>]
 *   2. POUR TOUT[E] CHAÎNE   sc [, p [, c]] DE <chaîne> SEPAREE PAR <sep|[seps]> [<sens>]
 *   3. POUR TOUT[E] POSITION p              DE <motif>  DANS <chaîne> [AVEC <opts>] [<sens>]
 *   4. Synonymes scanner : TOUT/TOUTE/TOUS/CHAQUE/EACH/EVERY/ALL → TOKEN_TOUT
 *   5. <sens> ::= DepuisFin | DepuisDébut (identifiants — pas un keyword scanner)
 *
 * Le dispatcher détecte le mode après TOUT en peekant le token courant.
 * --------------------------------------------------------------------------- */

/* Détecte le sens du parcours après l'iterable (ou après AVEC <cond>).
 * Reconnaît DepuisDébut / DepuisFin comme identifiants (accent-strip
 * + casse-insensible). Retourne true si on a consommé un sens inverse.
 * Le sens DepuisDébut explicite est consommé mais traité comme défaut. */
static bool consume_optional_depuis_sens(void) {
    if (!check(TOKEN_IDENTIFIER)) return false;
    Token tok = parser.current;
    char stripped[32];
    int n = scanner_strip_accents(tok.start, tok.length, stripped, sizeof(stripped));
    if (n <= 0) return false;
    /* Lowercase pour comparaison */
    for (int i = 0; i < n; i++) {
        if (stripped[i] >= 'A' && stripped[i] <= 'Z') stripped[i] += 32;
    }
    if (n == 9 && memcmp(stripped, "depuisfin", 9) == 0) {
        advance_token();
        return true;
    }
    if (n == 11 && memcmp(stripped, "depuisdebut", 11) == 0) {
        advance_token();
        return false;
    }
    return false;
}

/* True si le token IDENT courant a pour texte "position" (accent-strip,
 * casse-insensible). Utilisé pour détecter contextuellement le mode
 * POUR TOUTE POSITION sans introduire un keyword scanner réservé qui
 * casserait l'usage `Position(s, sub)` en tant que native function. */
static bool current_is_position_keyword(void) {
    if (!check(TOKEN_IDENTIFIER)) return false;
    Token tok = parser.current;
    char stripped[32];
    int n = scanner_strip_accents(tok.start, tok.length, stripped, sizeof(stripped));
    if (n != 8) return false;
    for (int i = 0; i < n; i++) {
        if (stripped[i] >= 'A' && stripped[i] <= 'Z') stripped[i] += 32;
    }
    return memcmp(stripped, "position", 8) == 0;
}

/* ============================================================
 * Mode tableau (forme 1) + AVEC + DepuisFin
 * ============================================================
 * Stratégie AVEC : on capture le bytecode de la condition au moment
 * du parse (où les tokens sont disponibles), on le copie dans un
 * buffer scratch, puis on truncate le chunk pour annuler l'émission.
 * Plus tard, après l'assignation de la variable d'itération, on
 * réinsère ce bytecode via chunk_insert_before. Les jumps internes
 * de la cond (court-circuit ET/OU) sont relatifs → relocation-safe.
 * Les références au pool de constantes restent valides puisqu'on
 * réutilise le même chunk principal. */
static void foreach_array_statement(void) {
    begin_scope();

    /* Skip ELEMENT optionnel (canon : POUR TOUT [ELEMENT] var DE tab) */
    match_token(TOKEN_ELEMENT);

    consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_ELEMENT_VAR);
    Token elemName = parser.previous;
    declare_variable(&elemName);
    emit_byte(OP_NIL);

    bool hasIndex = false;
    Token indexName;
    indexName.start = "";
    indexName.length = 0;
    if (match_token(TOKEN_COMMA)) {
        consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_INDEX_VAR);
        indexName = parser.previous;
        hasIndex = true;
        declare_variable(&indexName);
        emit_byte(OP_NIL);
    }

    consume(TOKEN_DE, E_SYNTAX_EXP_DE_AFTER_VAR_NAME);
    expression();

    /* AVEC <cond> : on parse maintenant et on capture le bytecode généré
     * pour le réinjecter en tête de body après l'assignation de v. */
    bool hasAvec = false;
    uint8_t avecBuf[256];
    int avecBufLen = 0;
    int avecLine = parser.previous.line;
    if (match_token(TOKEN_AVEC)) {
        hasAvec = true;
        avecLine = parser.previous.line;
        int bcStart = current_chunk()->count;
        condition_expression();
        int bcEnd = current_chunk()->count;
        int len = bcEnd - bcStart;
        if (len > (int)sizeof(avecBuf)) {
            owl_emit_error_at(&parser.previous,
                              E_SEM_BYTECODE_AVEC_FILTER_TOO_LARGE);
            return;
        }
        memcpy(avecBuf, current_chunk()->code + bcStart, (size_t)len);
        avecBufLen = len;
        /* Truncate : on supprime le bytecode de la cond du chunk principal.
         * Il sera réinjecté plus tard via chunk_insert_before. */
        current_chunk()->count = bcStart;
    }

    /* Sens : DepuisFin / DepuisDébut */
    bool isReverse = consume_optional_depuis_sens();

    Token hidden1 = {.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER};
    add_local(hidden1);

    /* counter init : 0 (forward) ou (length-1) (reverse) */
    if (isReverse) {
        emit_byte(OP_DUP);
        emit_byte(OP_ARRAY_LENGTH);
        emit_constant(INTEGER_VAL(1));
        emit_byte(OP_SUBTRACT);
    } else {
        emit_constant(INTEGER_VAL(0));
    }
    Token hidden2 = {.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER};
    add_local(hidden2);

    /* hidden3 = savedLen : longueur capturée juste avant le body, utilisée
     * pour détecter une suppression de l'élément courant pendant le body
     * (cf doc canon : Supprime(tab, ÉlémentCourant) dans POUR TOUT). */
    emit_constant(INTEGER_VAL(0));
    Token hidden3 = {.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER};
    add_local(hidden3);

    int elemSlot = resolve_local(current, &elemName);
    int arraySlot, counterSlot, savedLenSlot;

    if (hasIndex) {
        int indexSlot = resolve_local(current, &indexName);
        arraySlot = indexSlot + 1;
        counterSlot = arraySlot + 1;
        savedLenSlot = counterSlot + 1;
        (void)indexSlot;
    } else {
        arraySlot = elemSlot + 1;
        counterSlot = arraySlot + 1;
        savedLenSlot = counterSlot + 1;
    }

    /* OP_ITER_BEGIN */
    emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
    emit_byte(OP_ITER_BEGIN);
    emit_byte(OP_POP);

    int loopStart = current_chunk()->count;
    push_loop(loopStart, true);

    if (isReverse) {
        emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
        emit_constant(INTEGER_VAL(0));
        emit_byte(OP_GREATER_EQUAL);
    } else {
        emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
        emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
        emit_byte(OP_ARRAY_LENGTH);
        emit_byte(OP_LESS);
    }

    int exitJump = emit_jump(OP_JUMP_IF_FALSE);
    emit_byte(OP_POP);

    emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
    emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
    emit_constant(INTEGER_VAL(1));
    emit_byte(OP_ADD);
    emit_byte(OP_ARRAY_GET);
    emit_bytes(OP_SET_LOCAL, (uint8_t)elemSlot);
    emit_byte(OP_POP);

    /* Tracker la clé courante pour ÉlémentCourant */
    emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
    emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
    emit_constant(INTEGER_VAL(1));
    emit_byte(OP_ADD);
    emit_byte(OP_ITER_KEY);
    if (hasIndex) {
        int indexSlot = resolve_local(current, &indexName);
        emit_bytes(OP_SET_LOCAL, (uint8_t)indexSlot);
    }
    emit_byte(OP_ITER_TRACK_KEY);
    emit_byte(OP_POP);

    /* Capturer savedLen avant le body (pour suppression élément courant) */
    emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
    emit_byte(OP_ARRAY_LENGTH);
    emit_bytes(OP_SET_LOCAL, (uint8_t)savedLenSlot);
    emit_byte(OP_POP);

    /* AVEC : réinjecte le bytecode capturé + VERIFY + JUMP_IF_FALSE → continue.
     * On émet ces bytes directement maintenant via chunk_insert_before pour
     * profiter du fait qu'on est au bon endroit. */
    int avecJumpPatchPos = -1;
    if (hasAvec) {
        /* Re-injection du bytecode cond. Le buffer contient l'expression
         * complète qui pousse le résultat sur la stack. */
        chunk_insert_before(current_chunk(), current_chunk()->count,
                            avecBuf, avecBufLen, avecLine);
        emit_byte(OP_VERIFY_BOOL_COND);
        /* JUMP_IF_FALSE → patché plus tard vers continueTarget */
        avecJumpPatchPos = emit_jump(OP_JUMP_IF_FALSE);
        emit_byte(OP_POP); /* drop bool true (cond passée) */
    }

    begin_scope(); /* body scope */
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        declaration();
    }
    end_scope();

    patch_loop_continues();

    /* À ce point, c'est le continueTarget. Patcher le JUMP_IF_FALSE AVEC
     * pour qu'il saute ici (en popant le bool false avant). */
    if (avecJumpPatchPos >= 0) {
        /* Skip le pop du bool-true path : on émet un JUMP qui saute le
         * pop du bool-false (qu'on va émettre dans une seconde).
         * Pattern :
         *    [JUMP_IF_FALSE → falseBranch]
         *    POP (bool true)
         *    body...
         *    →ICI←  (continueTarget)
         *    JUMP → afterFalsePop  (skip le POP du false branch)
         *  falseBranch:
         *    POP (bool false)
         *  afterFalsePop:
         *    increment...
         */
        int skipFalsePop = emit_jump(OP_JUMP);
        patch_jump(avecJumpPatchPos);
        emit_byte(OP_POP); /* drop bool false */
        patch_jump(skipFalsePop);
    }

    if (isReverse) {
        /* Forme reverse : counter-- inconditionnel.
         * La suppression de l'élément courant en mode reverse ne perturbe
         * pas les indices restants (déjà parcourus à droite du courant).
         * On décrémente toujours. */
        emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
        emit_constant(INTEGER_VAL(1));
        emit_byte(OP_SUBTRACT);
        emit_bytes(OP_SET_LOCAL, (uint8_t)counterSlot);
        emit_byte(OP_POP);
    } else {
        /* Forme forward : incrément conditionnel du counter (cf comment ci-haut).
         *   si lenAprèsBody >= savedLen → counter++ (cas normal, pas de mut).
         *   sinon (length a baissé)     → counter inchangé. */
        emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
        emit_byte(OP_ARRAY_LENGTH);
        emit_bytes(OP_GET_LOCAL, (uint8_t)savedLenSlot);
        emit_byte(OP_LESS); /* (newLen < savedLen) ? */
        int skipIncJump = emit_jump(OP_JUMP_IF_FALSE);
        emit_byte(OP_POP); /* drop bool true (length a baissé : on saute l'increment) */
        int doneJump = emit_jump(OP_JUMP);
        patch_jump(skipIncJump);
        emit_byte(OP_POP); /* drop bool false : on incrémente */
        emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
        emit_constant(INTEGER_VAL(1));
        emit_byte(OP_ADD);
        emit_bytes(OP_SET_LOCAL, (uint8_t)counterSlot);
        emit_byte(OP_POP);
        patch_jump(doneJump);
    }

    emit_loop(loopStart);

    patch_jump(exitJump);
    emit_byte(OP_POP);

    pop_loop();
    /* Fermer le contexte d'itération (cf OP_ITER_BEGIN plus haut). */
    emit_byte(OP_ITER_END);
    end_scope();
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_POUR_TOUT);
}

/* ============================================================
 * Mode CHAÎNE séparée — POUR TOUTE CHAÎNE sc [, pos [, cpt]] DE str
 *                       SEPAREE PAR sep|[seps] [DepuisFin]
 * ============================================================
 * Stratégie : appel à __pourtoutChaineSegments(src, sep) qui retourne
 * un tableau 2D [[sub, posCp], ...]. Le compiler génère ensuite une
 * boucle POUR TOUT classique sur ce tableau et déstructure les paires
 * pour assigner sc, pos, cpt. */
static void foreach_string_split_statement(void) {
    begin_scope();

    /* Variables sortantes : 1 à 3 (sc [, pos [, cpt]]) */
    consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_SUBSTRING_VAR);
    Token scName = parser.previous;
    declare_variable(&scName);
    emit_byte(OP_NIL);

    Token posName = {0}; bool hasPos = false;
    Token cptName = {0}; bool hasCpt = false;
    if (match_token(TOKEN_COMMA)) {
        consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_POSITION_VAR_AFTER_COMMA);
        posName = parser.previous;
        hasPos = true;
        declare_variable(&posName);
        emit_byte(OP_NIL);
        if (match_token(TOKEN_COMMA)) {
            consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_COUNTER_VAR);
            cptName = parser.previous;
            hasCpt = true;
            declare_variable(&cptName);
            emit_byte(OP_NIL);
        }
    }

    consume(TOKEN_DE, E_SYNTAX_EXP_DE_AFTER_VAR_NAMES);

    /* On parse src et sep, mais on les met directement dans le bon ordre
     * pour appeler le helper. Stratégie : émettre le GET_GLOBAL helper
     * AVANT les args. Pattern :
     *   GET_GLOBAL __pourtoutChaineSegments
     *   <expression src>      (parser émet)
     *   <SEPAREE PAR expression sep>
     *   CALL 2  → tableau 2D sur la stack */
    {
        Token helperTok;
        helperTok.start  = "__pourtoutChaineSegments";
        helperTok.length = 24;
        ConstIdx hIdx = identifier_constant(&helperTok);
        emit_const_op(OP_GET_GLOBAL, hIdx);
    }
    expression(); /* src */

    consume(TOKEN_SEPAREE, E_SYNTAX_EXP_SEPAREE_AFTER_SOURCE);
    consume(TOKEN_PAR, E_SYNTAX_EXP_PAR_AFTER_SEPAREE);
    expression(); /* sep */

    emit_bytes(OP_CALL, 2);
    /* Stack : tableau 2D [[sub, pos], ...] */

    /* Sens : DepuisFin / DepuisDébut */
    bool isReverse = consume_optional_depuis_sens();

    /* add_local pour arraySlot et counterSlot.
     * Layout : scSlot, [posSlot?], [cptSlot?], arraySlot, counterSlot */
    Token hiddenArr = {.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER};
    add_local(hiddenArr);
    int arraySlot = current->localCount - 1;

    /* counter init : 0 (forward) ou length-1 (reverse) */
    if (isReverse) {
        emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
        emit_byte(OP_ARRAY_LENGTH);
        emit_constant(INTEGER_VAL(1));
        emit_byte(OP_SUBTRACT);
    } else {
        emit_constant(INTEGER_VAL(0));
    }
    Token hiddenCnt = {.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER};
    add_local(hiddenCnt);
    int counterSlot = current->localCount - 1;

    int scSlot = resolve_local(current, &scName);
    int posSlot = hasPos ? resolve_local(current, &posName) : -1;
    int cptSlot = hasCpt ? resolve_local(current, &cptName) : -1;

    int loopStart = current_chunk()->count;
    push_loop(loopStart, true);

    /* Condition de boucle */
    if (isReverse) {
        emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
        emit_constant(INTEGER_VAL(0));
        emit_byte(OP_GREATER_EQUAL);
    } else {
        emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
        emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
        emit_byte(OP_ARRAY_LENGTH);
        emit_byte(OP_LESS);
    }

    int exitJump = emit_jump(OP_JUMP_IF_FALSE);
    emit_byte(OP_POP);

    /* Récupérer la paire : arr[counter+1] → [sub, pos] */
    emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
    emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
    emit_constant(INTEGER_VAL(1));
    emit_byte(OP_ADD);
    emit_byte(OP_ARRAY_GET);
    /* La paire est sur la stack. Extraire [1] et [2]. */

    /* On dup la paire pour pouvoir l'indexer 2x : */
    emit_byte(OP_DUP);
    emit_constant(INTEGER_VAL(1));
    emit_byte(OP_ARRAY_GET);
    emit_bytes(OP_SET_LOCAL, (uint8_t)scSlot);
    emit_byte(OP_POP); /* drop sub-string copy */

    if (hasPos) {
        emit_byte(OP_DUP);
        emit_constant(INTEGER_VAL(2));
        emit_byte(OP_ARRAY_GET);
        emit_bytes(OP_SET_LOCAL, (uint8_t)posSlot);
        emit_byte(OP_POP);
    }

    emit_byte(OP_POP); /* drop la paire originale */

    if (hasCpt) {
        /* cpt = counter + 1 (1-based) — en mode reverse on inverse aussi
         * pour matcher le compteur d'itération vue, mais la spec canon n'est
         * pas explicite ; en mode forward le compteur suit. En mode reverse
         * on garde le même 1-based croissant (1 pour la première vue). */
        if (isReverse) {
            /* lengthArr - counter (counter décroît, on veut compteur qui croît) */
            emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
            emit_byte(OP_ARRAY_LENGTH);
            emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
            emit_byte(OP_SUBTRACT);
            emit_bytes(OP_SET_LOCAL, (uint8_t)cptSlot);
        } else {
            emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
            emit_constant(INTEGER_VAL(1));
            emit_byte(OP_ADD);
            emit_bytes(OP_SET_LOCAL, (uint8_t)cptSlot);
        }
        emit_byte(OP_POP);
    }

    begin_scope();
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        declaration();
    }
    end_scope();

    patch_loop_continues();

    /* Increment / decrement counter */
    if (isReverse) {
        emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
        emit_constant(INTEGER_VAL(1));
        emit_byte(OP_SUBTRACT);
        emit_bytes(OP_SET_LOCAL, (uint8_t)counterSlot);
        emit_byte(OP_POP);
    } else {
        emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
        emit_constant(INTEGER_VAL(1));
        emit_byte(OP_ADD);
        emit_bytes(OP_SET_LOCAL, (uint8_t)counterSlot);
        emit_byte(OP_POP);
    }

    emit_loop(loopStart);
    patch_jump(exitJump);
    emit_byte(OP_POP);

    pop_loop();
    end_scope();
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_POUR_TOUTE_CHAINE);
}

/* ============================================================
 * Mode POSITION — POUR TOUTE POSITION p DE motif DANS chaîne
 *                 [AVEC <opts>] [DepuisFin]
 * ============================================================
 * Stratégie : appel à __pourtoutChainePositions(src, motif, opts) qui
 * retourne un tableau d'entiers (positions 1-based codepoint). Le
 * compiler itère ensuite ce tableau d'entiers classiquement.
 *
 * Conflit DANS : le motif est parsé avec PREC_BIT_SHIFT pour empêcher
 * que l'opérateur DANS (PREC_EQUALITY) soit absorbé dans l'expression
 * du motif. Cf spec §"Conflit syntaxique critique". */
static void foreach_string_position_statement(void) {
    begin_scope();

    /* Une seule variable sortante en mode POSITION (SYNTAXE2). */
    consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_POSITION_VAR);
    Token pName = parser.previous;
    declare_variable(&pName);
    emit_byte(OP_NIL);

    consume(TOKEN_DE, E_SYNTAX_EXP_DE_AFTER_POS_VAR);

    /* Parser <motif> avec précédence haute pour bloquer DANS infix.
     * Le motif occupe ensuite le slot d'un local hidden tMotSlot. */
    parse_precedence(PREC_BIT_SHIFT);
    Token tMot = {.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER};
    add_local(tMot);
    int tMotSlot = current->localCount - 1;

    consume(TOKEN_DANS, E_SYNTAX_EXP_DANS_MOTIF_CHAINE);
    expression(); /* haystack */
    Token tChn = {.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER};
    add_local(tChn);
    int tChnSlot = current->localCount - 1;

    /* AVEC <opts> : combinaison de constantes (MotComplet/SansCasse/DepuisFin).
     * Position : APRÈS chaîne, AVANT <sens>. */
    if (match_token(TOKEN_AVEC)) {
        condition_expression(); /* supporte v|c, v+c (OR/SUM de constantes) */
    } else {
        emit_constant(INTEGER_VAL(0));
    }
    Token tOpts = {.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER};
    add_local(tOpts);
    int tOptsSlot = current->localCount - 1;

    /* Sens : DepuisFin / DepuisDébut */
    bool isReverse = consume_optional_depuis_sens();
    if (isReverse) {
        /* OR le slot opts avec SEARCH_DEPUIS_FIN = 4 */
        emit_bytes(OP_GET_LOCAL, (uint8_t)tOptsSlot);
        emit_constant(INTEGER_VAL(4));
        emit_byte(OP_BIT_OR);
        emit_bytes(OP_SET_LOCAL, (uint8_t)tOptsSlot);
        emit_byte(OP_POP);
    }

    /* Appel __pourtoutChainePositions(chaine, motif, opts) → tableau d'entiers */
    {
        Token helperTok;
        helperTok.start  = "__pourtoutChainePositions";
        helperTok.length = 25;
        ConstIdx hIdx = identifier_constant(&helperTok);
        emit_const_op(OP_GET_GLOBAL, hIdx);
        emit_bytes(OP_GET_LOCAL, (uint8_t)tChnSlot);
        emit_bytes(OP_GET_LOCAL, (uint8_t)tMotSlot);
        emit_bytes(OP_GET_LOCAL, (uint8_t)tOptsSlot);
        emit_bytes(OP_CALL, 3);
    }

    /* Stack : tableau d'entiers (positions 1-based) */
    Token hiddenArr = {.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER};
    add_local(hiddenArr);
    int arraySlot = current->localCount - 1;

    emit_constant(INTEGER_VAL(0));
    Token hiddenCnt = {.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER};
    add_local(hiddenCnt);
    int counterSlot = current->localCount - 1;

    /* Note : pas de mode reverse côté itération ici — le helper a déjà
     * inversé l'ordre via le bit SEARCH_DEPUIS_FIN s'il était demandé. */

    int pSlot = resolve_local(current, &pName);

    int loopStart = current_chunk()->count;
    push_loop(loopStart, true);

    emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
    emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
    emit_byte(OP_ARRAY_LENGTH);
    emit_byte(OP_LESS);

    int exitJump = emit_jump(OP_JUMP_IF_FALSE);
    emit_byte(OP_POP);

    emit_bytes(OP_GET_LOCAL, (uint8_t)arraySlot);
    emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
    emit_constant(INTEGER_VAL(1));
    emit_byte(OP_ADD);
    emit_byte(OP_ARRAY_GET);
    emit_bytes(OP_SET_LOCAL, (uint8_t)pSlot);
    emit_byte(OP_POP);

    begin_scope();
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        declaration();
    }
    end_scope();

    patch_loop_continues();

    emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
    emit_constant(INTEGER_VAL(1));
    emit_byte(OP_ADD);
    emit_bytes(OP_SET_LOCAL, (uint8_t)counterSlot);
    emit_byte(OP_POP);

    emit_loop(loopStart);
    patch_jump(exitJump);
    emit_byte(OP_POP);

    pop_loop();
    end_scope();
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_POUR_TOUTE_POSITION);
}

/* ============================================================
 * Dispatcher — détecte le mode après POUR TOUT et délègue.
 * ============================================================ */
static void foreach_statement(void) {
    /* Mode CHAÎNE : POUR TOUTE CHAÎNE <var>... */
    if (check(TOKEN_CHAINE)) {
        advance_token();
        foreach_string_split_statement();
        return;
    }
    /* Mode POSITION : POUR TOUTE POSITION <var>... (contextuel) */
    if (current_is_position_keyword()) {
        advance_token();
        foreach_string_position_statement();
        return;
    }
    /* Mode tableau (forme 1, défaut) */
    foreach_array_statement();
}

/* Parse: TANTQUE <expr> ... FIN */
static void while_statement(void) {
    int loopStart = current_chunk()->count;
    push_loop(loopStart, false);

    condition_expression();
    emit_byte(OP_VERIFY_BOOL_COND);

    int exitJump = emit_jump(OP_JUMP_IF_FALSE);
    emit_byte(OP_POP);

    begin_scope();
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        declaration();
    }
    end_scope();

    emit_loop(loopStart);
    patch_jump(exitJump);
    emit_byte(OP_POP);

    pop_loop();
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_TANTQUE);
}

/* Parse: BOUCLE [(N)] ... FIN
 *
 * Deux formes :
 *  - SYNTAXE1 historique : `BOUCLE ... FIN` boucle infinie sortie par SORTIR.
 *  - SYNTAXE3 canon    : `BOUCLE (N) ... FIN` exécute le body N fois.
 *
 * Pour la forme (N) : N évalué une seule fois au démarrage, comparé à un
 * compteur interne incrémenté en fin de tour. Si N <= 0, le body n'est
 * pas exécuté. CONTINUER passe à l'itération suivante (compteur incrémenté
 * via patch_loop_continues), SORTIR sort de la boucle normalement. */
static void loop_statement(void) {
    bool hasCount = false;
    int countSlot = -1;
    int counterSlot = -1;

    /* Le compteur (N) doit être adjacent au mot-clé sur la même ligne.
     * Sinon un BOUCLE infini dont le corps commence par une paren
     * (multi-affectation `(a, b) = f()` ou expression parenthésée) verrait
     * cette paren avalée comme compteur. crossedNewline est intact ici car
     * le dispatch appelle loop_statement() juste après match_token(BOUCLE). */
    if (!crossedNewline && match_token(TOKEN_LEFT_PAREN)) {
        hasCount = true;
        begin_scope();

        /* Évaluation unique de N au démarrage, stockée dans un local anonyme. */
        expression();
        consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_BOUCLE_COUNT);
        add_local((Token){.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER});
        countSlot = current->localCount - 1;

        /* Compteur d'itérations initialisé à 0, dans un autre local anonyme. */
        emit_constant(INTEGER_VAL(0));
        add_local((Token){.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER});
        counterSlot = current->localCount - 1;
    }

    int loopStart = current_chunk()->count;
    /* deferContinue = hasCount : pour BOUCLE (N), CONTINUER doit sauter au
     * point d'incrémentation du compteur interne, pas directement à loopStart. */
    push_loop(loopStart, hasCount);

    int exitJump = -1;
    if (hasCount) {
        /* Test d'arrêt : compteur < N ? */
        emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
        emit_bytes(OP_GET_LOCAL, (uint8_t)countSlot);
        emit_byte(OP_LESS);
        exitJump = emit_jump(OP_JUMP_IF_FALSE);
        emit_byte(OP_POP);
    }

    begin_scope();
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        declaration();
    }
    end_scope();

    if (hasCount) {
        /* Cible des CONTINUER : juste avant l'incrémentation du compteur. */
        patch_loop_continues();

        emit_bytes(OP_GET_LOCAL, (uint8_t)counterSlot);
        emit_constant(INTEGER_VAL(1));
        emit_byte(OP_ADD);
        emit_bytes(OP_SET_LOCAL, (uint8_t)counterSlot);
        emit_byte(OP_POP);
    }

    emit_loop(loopStart);

    if (hasCount) {
        patch_jump(exitJump);
        emit_byte(OP_POP);
    }

    pop_loop();
    if (hasCount) end_scope();
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_BOUCLE);
}

/* ----------------------------------------------------------------
 * SELON / CAS — dispatch des patterns etendus.
 *
 * Un pattern peut prendre cinq formes :
 *   - simple     : CAS 5                       (egalite)
 *   - plage      : CAS 1 A 10 | CAS A 10 | CAS 1 A
 *   - comparateur: CAS > 5 | CAS [= "abc" ...
 *   - sandwich   : CAS 10 < * < 20             (et variantes <= / <)
 *
 * Tous emettent une sequence qui pose un booleen sur la pile (Vrai
 * = match). Les jumps "match" sont accumules par le caller pour
 * realiser le OU des patterns separes par virgule.
 * ---------------------------------------------------------------- */

/* Separateur `A` / `TO` d'une plage CAS — meme keyword que la borne POUR. */
static bool check_cas_a_separator(void) {
    return parser.current.type == TOKEN_A;
}

static bool match_cas_a_separator(void) {
    return match_token(TOKEN_A);
}

static bool is_cas_comparator_token(TokenType t) {
    switch (t) {
        case TOKEN_GREATER: case TOKEN_GREATER_EQUAL:
        case TOKEN_LESS:    case TOKEN_LESS_EQUAL:
        case TOKEN_EQUAL:   case TOKEN_NOT_EQUAL:
        case TOKEN_TILDE_EQUAL: case TOKEN_DOUBLE_TILDE:
        case TOKEN_STARTS_WITH: case TOKEN_ENDS_WITH: case TOKEN_CONTAINS:
        case TOKEN_STARTS_WITH_FLEX: case TOKEN_ENDS_WITH_FLEX: case TOKEN_CONTAINS_FLEX:
        case TOKEN_STARTS_WITH_VFLEX: case TOKEN_ENDS_WITH_VFLEX: case TOKEN_CONTAINS_VFLEX:
            return true;
        default:
            return false;
    }
}

/* Frontiere de pattern apres avoir consomme `expr A` : `CAS 11 A` (borne
 * inf seule). Vrai si le token courant signale la fin du pattern. */
static bool is_cas_pattern_boundary(void) {
    if (crossedNewline) return true;
    switch (parser.current.type) {
        case TOKEN_COMMA: case TOKEN_COLON:
        case TOKEN_CAS:   case TOKEN_AUTRE:
        case TOKEN_FIN:   case TOKEN_EOF:
            return true;
        default:
            return false;
    }
}

/* Emit `switchSlot OP expr` pour les operateurs numerique/egalite. */
static void emit_cas_numeric_op(TokenType op) {
    switch (op) {
        case TOKEN_GREATER:       emit_byte(OP_GREATER); break;
        case TOKEN_GREATER_EQUAL: emit_byte(OP_GREATER_EQUAL); break;
        case TOKEN_LESS:          emit_byte(OP_LESS); break;
        case TOKEN_LESS_EQUAL:    emit_byte(OP_LESS_EQUAL); break;
        case TOKEN_EQUAL:         emit_byte(OP_EQUAL); break;
        case TOKEN_NOT_EQUAL:     emit_byte(OP_NOT_EQUAL); break;
        default: break;
    }
}

/* Peek 3 tokens en avant pour decider si on est en sandwich. Bornes
 * limitees a un atome (NUMBER / STRING / IDENT) — un sandwich complexe
 * doit etre parenthese. */
static bool peek_is_sandwich_pattern(void) {
    TokenType t0 = parser.current.type;
    if (t0 != TOKEN_INTEGER && t0 != TOKEN_REAL &&
        t0 != TOKEN_NUMERIC && t0 != TOKEN_MONETARY &&
        t0 != TOKEN_STRING && t0 != TOKEN_IDENTIFIER) {
        return false;
    }
    Scanner saved     = parser.scanner;
    Token   savedCur  = parser.current;
    Token   savedPrev = parser.previous;
    bool    savedXNL  = crossedNewline;

    bool result = false;
    advance_token();  /* skip atom */
    if (parser.current.type == TOKEN_LESS ||
        parser.current.type == TOKEN_LESS_EQUAL) {
        advance_token();
        if (parser.current.type == TOKEN_STAR) {
            result = true;
        }
    }

    parser.scanner   = saved;
    parser.current   = savedCur;
    parser.previous  = savedPrev;
    crossedNewline   = savedXNL;
    return result;
}

/* Parse + emit un seul pattern. Apres retour, la pile contient un
 * booleen au sommet (Vrai = match). */
static void compile_cas_pattern(int switchSlot) {
    /* Cas 1 : "CAS A max" — borne sup seule. */
    if (check_cas_a_separator()) {
        advance_token();
        emit_bytes(OP_GET_LOCAL, (uint8_t)switchSlot);
        expression();
        emit_byte(OP_LESS_EQUAL);
        return;
    }

    /* Cas 2 : "CAS <op> val" — comparateur prefixe. */
    if (is_cas_comparator_token(parser.current.type)) {
        TokenType op = parser.current.type;
        advance_token();
        emit_bytes(OP_GET_LOCAL, (uint8_t)switchSlot);
        expression();
        int strSpec = string_match_spec_for(op);
        if (strSpec >= 0) {
            emit_bytes(OP_STRING_MATCH, (uint8_t)strSpec);
        } else {
            emit_cas_numeric_op(op);
        }
        return;
    }

    /* Cas 3 : "CAS min < * < max" — sandwich (peek pour decider). */
    if (peek_is_sandwich_pattern()) {
        emit_bytes(OP_GET_LOCAL, (uint8_t)switchSlot);
        /* min — borne atomique consommee par parse_precedence(BIT_SHIFT) */
        parse_precedence(PREC_BIT_SHIFT);
        /* op1 inverse : switchSlot > min (si <), >= min (si <=). */
        TokenType op1 = parser.current.type;
        advance_token();  /* consume < or <= */
        if (op1 == TOKEN_LESS) {
            emit_byte(OP_GREATER);
        } else {
            emit_byte(OP_GREATER_EQUAL);
        }
        /* Court-circuit : si la premiere borne est fausse, on saute le
         * test de la seconde et on laisse Faux sur la pile. */
        int skipSecond = emit_jump(OP_JUMP_IF_FALSE);
        emit_byte(OP_POP);  /* pop le Vrai du premier test */

        consume(TOKEN_STAR, E_SYNTAX_EXP_STAR_SANDWICH);
        if (!check(TOKEN_LESS) && !check(TOKEN_LESS_EQUAL)) {
            owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_LT_OR_LE_IN_SANDWICH);
            return;
        }
        TokenType op2 = parser.current.type;
        advance_token();
        emit_bytes(OP_GET_LOCAL, (uint8_t)switchSlot);
        expression();
        if (op2 == TOKEN_LESS) {
            emit_byte(OP_LESS);
        } else {
            emit_byte(OP_LESS_EQUAL);
        }
        patch_jump(skipSecond);
        return;
    }

    /* Cas 4 : pattern qui commence par une expression. Peut etre :
     *   - simple_value (egalite)
     *   - "expr A"     (borne inf seule)
     *   - "expr A max" (plage pleine) */
    emit_bytes(OP_GET_LOCAL, (uint8_t)switchSlot);
    expression();

    if (match_cas_a_separator()) {
        if (is_cas_pattern_boundary()) {
            /* CAS min A — switchSlot >= min */
            emit_byte(OP_GREATER_EQUAL);
        } else {
            /* CAS min A max — switchSlot >= min ET switchSlot <= max */
            emit_byte(OP_GREATER_EQUAL);
            int skipSecond = emit_jump(OP_JUMP_IF_FALSE);
            emit_byte(OP_POP);  /* drop Vrai */
            emit_bytes(OP_GET_LOCAL, (uint8_t)switchSlot);
            expression();
            emit_byte(OP_LESS_EQUAL);
            patch_jump(skipSecond);
        }
        return;
    }

    /* Cas 4 final : pattern simple — egalite. */
    emit_byte(OP_EQUAL);
}

/* Parse: SELON expression CAS ... FIN */
static void switch_statement(void) {
    begin_scope();
    expression();
    add_local((Token){.start = "", .length = 0, .line = 0, .column = 0, .type = TOKEN_IDENTIFIER});
    int switchSlot = current->localCount - 1;

    push_switch();

    int endJumps[256];
    int endCount = 0;

    while (check(TOKEN_CAS) || check(TOKEN_AUTRE)) {
        if (match_token(TOKEN_CAS)) {
            int orJumps[64];
            int orCount = 0;

            compile_cas_pattern(switchSlot);
            int matchJump = emit_jump(OP_JUMP_IF_FALSE);
            emit_byte(OP_POP);
            int bodyJump = emit_jump(OP_JUMP);
            orJumps[orCount++] = bodyJump;
            patch_jump(matchJump);
            emit_byte(OP_POP);

            while (match_token(TOKEN_COMMA)) {
                compile_cas_pattern(switchSlot);
                int mj = emit_jump(OP_JUMP_IF_FALSE);
                emit_byte(OP_POP);
                int bj = emit_jump(OP_JUMP);
                if (orCount < 64) orJumps[orCount++] = bj;
                patch_jump(mj);
                emit_byte(OP_POP);
            }

            int skipBody = emit_jump(OP_JUMP);

            for (int i = 0; i < orCount; i++) {
                patch_jump(orJumps[i]);
            }

            /* `:` apres pattern(s) — optionnel en canon. */
            match_token(TOKEN_COLON);

            while (!check(TOKEN_CAS) && !check(TOKEN_AUTRE) &&
                   !check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                declaration();
            }

            if (endCount < 256) {
                endJumps[endCount++] = emit_jump(OP_JUMP);
            }

            patch_jump(skipBody);

        } else if (match_token(TOKEN_AUTRE)) {
            if (check(TOKEN_CAS)) {
                advance_token();
            }
            /* `:` apres AUTRE CAS — optionnel par symetrie avec CAS. */
            match_token(TOKEN_COLON);

            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                declaration();
            }

            if (endCount < 256) {
                endJumps[endCount++] = emit_jump(OP_JUMP);
            }
        }
    }

    for (int i = 0; i < endCount; i++) {
        patch_jump(endJumps[i]);
    }

    pop_switch();
    end_scope();
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_SELON);
}

/* Parse: QUAND EXCEPTION DANS ... FAIRE ... [SINON ...] [ENFIN ...] FIN */
/* True while compiling the body of an exception handler. Used to unlock
 * the bare `EXCEPTION` keyword that re-raises the current exception. */
static int insideExceptionHandler = 0;

/* True while compiling the body of a ENFIN (FINALLY) block. Used to
 * reject statements that would interrupt the cleanup flow (RENVOYER,
 * RETOUR, SORTIR, CONTINUER, EXCEPTION re-raise, ExceptionDéclenche). */
static int insideEnfinBody = 0;

/* Source range of the current ENFIN body (the bytes between the token
 * after `ENFIN` and the `FIN` of the surrounding QUAND EXCEPTION DANS).
 * Captured during the first parse pass and re-scanned to emit the body
 * once per exit path (success, caught, propagated). NULL when no ENFIN
 * is active in the current QUAND EXCEPTION DANS scope.
 *
 * The range is anchored on the source memory of the compilation unit
 * — re-scanning is safe because the scanner is purely a view over the
 * source string. */
typedef struct {
    const char* start;   /* first byte of the body */
    const char* end;     /* one past the last byte of the body */
    int         line;    /* line of the first body token (for error pointers) */
    int         column;  /* column of the first body token */
} EnfinRange;

/* Re-parse and emit the body F of a ENFIN block at the current insertion
 * point. Repositions the scanner inside the ORIGINAL source so line /
 * column tracking remains accurate for diagnostics emitted inside F.
 * Restores the scanner state on return so the caller's parsing stream
 * is unaffected. Used three times for a complete construct (one per
 * exit path : success / caught / re-raise). */
static void enfin_emit_body(const EnfinRange* range) {
    if (range == NULL || range->start == range->end) return;

    /* Save full parser/scanner state. */
    Scanner savedScanner = parser.scanner;
    Token   savedPrev    = parser.previous;
    Token   savedCurr    = parser.current;
    bool    savedXNL     = crossedNewline;
    bool    savedPanic   = parser.panicMode;

    /* Reposition in the original source. The scanner keeps its
     * `source` pointer (start of file) and we just slide `current` to
     * the body start. line/column are restored to the body's actual
     * position so error_at_current emits the user's real coordinates. */
    parser.scanner.current     = range->start;
    parser.scanner.start       = range->start;
    parser.scanner.line        = range->line;
    parser.scanner.column      = range->column;
    parser.scanner.startColumn = range->column;
    parser.scanner.atLineStart = (range->column == 1);

    parser.previous.type = TOKEN_NEWLINE;
    parser.current.type  = TOKEN_NEWLINE;
    crossedNewline       = false;
    parser.panicMode     = false;

    /* Re-arm by advancing onto the first real token of F. */
    advance_token();

    insideEnfinBody++;
    begin_scope();
    /* Stop when the scanner has reached the end of the captured range —
     * we don't want to consume the surrounding `FIN`. The check is
     * conservative : if parser.current sits AT or PAST range->end,
     * we're done. */
    while (parser.current.start < range->end &&
           !check(TOKEN_EOF) && !parser.hadError) {
        declaration();
    }
    end_scope();
    insideEnfinBody--;

    /* Restore the outer parsing state untouched. */
    parser.scanner   = savedScanner;
    parser.previous  = savedPrev;
    parser.current   = savedCurr;
    crossedNewline   = savedXNL;
    parser.panicMode = savedPanic;
}

/* Skip-scan from the current scanner position until the matching `FIN`
 * of an ENFIN body is found (depth-aware : nested QUAND EXCEPTION /
 * SI / POUR / TANTQUE / BOUCLE / SELON / SI / FONCTION / PROCEDURE
 * push depth that consumes intermediate FIN). Returns the source range
 * for re-emission. On success, leaves the scanner pointing AT the
 * `FIN` token (i.e. current = TOKEN_FIN). */
static EnfinRange enfin_capture_body(void) {
    EnfinRange range = { NULL, NULL, parser.current.line, parser.current.column };

    /* `parser.current` is positioned on the first token AFTER `ENFIN`. */
    range.start  = parser.current.start;
    range.line   = parser.current.line;
    range.column = parser.current.column;

    int depth = 0;
    while (!check(TOKEN_EOF)) {
        TokenType t = parser.current.type;

        /* Ouvrants de bloc — on n'empile que ce qui amene un FIN.
         *
         *  — la liste locale est remplacee par la source unique. Elle
         * comptait `SI c ALORS instr` : le FIN du QUAND servait alors a
         * refermer ce faux bloc, la capture continuait au-dela, et le
         * compilateur rendait « 'FIN' attendu apres le bloc de traitement
         * d'exception » sur une source parfaitement legale.
         *
         * Les mots-cles structurels restent locaux : hors table, parce qu'ils
         * n'arrivent qu'apres la copule (`st est une Structure`), forme qui
         * ouvre bien un corps + FIN dans un corps de clause. */
        if (prescan_token_in_depth_table(t)) {
            if (t == TOKEN_FIN) {
                if (depth == 0) {
                    /* This is the FIN of our QUAND EXCEPTION DANS. */
                    range.end = parser.current.start;
                    return range;
                }
                depth--;
            } else if (parser_depth_delta() > 0) {
                depth++;
            }
        } else if (t == TOKEN_STRUCTURE || t == TOKEN_CLASSE ||
                   t == TOKEN_ENUMERATION || t == TOKEN_COMBINAISON) {
            depth++;
        } else if (depth == 0 &&
                   (t == TOKEN_FAIRE || t == TOKEN_SINON || t == TOKEN_ENFIN)) {
            /* Order violation : another clause keyword appears after
             * ENFIN at the same nesting level. Stop the capture here so
             * the caller's ordering check sees the offending token in
             * parser.current and emits the precise diagnostic. */
            range.end = parser.current.start;
            return range;
        }
        advance_token();
    }
    /* EOF before FIN — let the caller's `consume(FIN, ...)` produce the
     * standard diagnostic. */
    range.end = parser.current.start;
    return range;
}

/* Helper : parse a sequence of statements until a clause boundary.
 * Used for each of T / H / E body blocks inside QUAND EXCEPTION DANS.
 * Bails on FIN / FAIRE / SINON / ENFIN / EOF. */
static void exception_parse_clause_body(void) {
    while (!check(TOKEN_FAIRE) && !check(TOKEN_SINON) &&
           !check(TOKEN_ENFIN) && !check(TOKEN_FIN) &&
           !check(TOKEN_EOF)) {
        declaration();
    }
}

/* Parse les clauses optionnelles `[FAIRE ...] [SINON ...] [ENFIN ...]`
 * APRÈS le body T. Émet H et E inline (cas B et cas A respectivement),
 * capture la source-range de F sans l'émettre. Retourne via les out-
 * params l'état des clauses pour la phase d'émission finale.
 *
 * Émet aussi les compile-errors d'ordre (FAIRE après SINON/ENFIN, etc.). */

/* Panic-mode recovery après une erreur de structure dans une forme
 * QUAND EXCEPTION DANS : on consomme jusqu'au TOKEN_FIN qui clôture le
 * bloc afin que le caller (exception_statement) puisse s'aligner et que
 * le parser parent ne cascade pas d'erreurs sur le contenu hors-norme.
 * On compte les blocs imbriqués (SI/POUR/TANTQUE/...) pour matcher le
 * FIN de niveau adéquat. Laisse le TOKEN_FIN courant pour que le caller
 * le consomme via consume(TOKEN_FIN, ...). */
static void exception_skip_to_matching_fin(void) {
    int depth = 1;
    while (!check(TOKEN_EOF)) {
        if (check(TOKEN_FIN)) {
            depth--;
            if (depth == 0) return;
            advance_token();
            continue;
        }
        /*  — verdict de la source unique : `SI c ALORS instr` n'ouvre
         * rien, et le compter ferait sauter le FIN cherche. */
        if (prescan_token_in_depth_table(parser.current.type)
            && parser_depth_delta() > 0) {
            depth++;
        }
        advance_token();
    }
}

static void exception_parse_optional_clauses(
        int afterTryJump,         /* jump à patcher pour le success path */
        bool* outHasFaire, int* outAfterHandlerJump,
        bool* outHasSinon, int* outAfterSinonJump,
        bool* outHasEnfin, EnfinRange* outEnfinRange) {
    *outHasFaire = false; *outAfterHandlerJump = -1;
    *outHasSinon = false; *outAfterSinonJump   = -1;
    *outHasEnfin = false;
    outEnfinRange->start = NULL; outEnfinRange->end = NULL;
    outEnfinRange->line  = 0;    outEnfinRange->column = 0;

    /* --- FAIRE ? */
    if (match_token(TOKEN_FAIRE)) {
        *outHasFaire = true;
        insideExceptionHandler++;
        begin_scope();
        exception_parse_clause_body();
        end_scope();
        insideExceptionHandler--;
        /*  : sortie NORMALE du handler → restaure le contexte
         * d'exception englobant (snapshot posé par l'OP_TRY correspondant).
         * Emis ici uniquement, PAS sur le chemin de propagation (OP_RERAISE via
         * le mot-clé EXCEPTION saute avant ce point ; RENVOYER termine la frame
         * et le rembobinage se fait sur OP_RETURN). Hors imbrication, restaure
         * le contexte vide du top-level → ExceptionInfo vide hors handler. */
        emit_byte(OP_EXC_RESTORE);
        *outAfterHandlerJump = emit_jump(OP_JUMP);
    }

    /* --- SINON ? (doit suivre FAIRE) */
    if (check(TOKEN_SINON)) {
        advance_token();
        *outHasSinon = true;
        /* No-exception arrives here. */
        patch_jump(afterTryJump);
        begin_scope();
        exception_parse_clause_body();
        end_scope();
        *outAfterSinonJump = emit_jump(OP_JUMP);
    }

    /* --- FAIRE après SINON ? */
    if (check(TOKEN_FAIRE)) {
        owl_emit_error_current(E_SYNTAX_EXCEPTION_FAIRE_ORDER);
        return;
    }

    /* --- ENFIN ? */
    if (check(TOKEN_ENFIN)) {
        advance_token(); /* consume ENFIN */
        *outHasEnfin = true;
        *outEnfinRange = enfin_capture_body();
        /* parser.current pointe maintenant sur TOKEN_FIN. */
    }

    /* --- Clauses après ENFIN : compile-errors. */
    if (check(TOKEN_ENFIN)) {
        owl_emit_error_current(E_SYNTAX_EXCEPTION_DUPLICATE_ENFIN);
        exception_skip_to_matching_fin();
        return;
    }
    if (check(TOKEN_SINON)) {
        owl_emit_error_current(E_SYNTAX_EXCEPTION_SINON_AFTER_ENFIN);
        exception_skip_to_matching_fin();
        return;
    }
    if (check(TOKEN_FAIRE)) {
        owl_emit_error_current(E_SYNTAX_EXCEPTION_FAIRE_ORDER);
        exception_skip_to_matching_fin();
        return;
    }
}

static void exception_statement(void) {
    consume(TOKEN_EXCEPTION, E_SYNTAX_EXP_EXCEPTION_AFTER_QUAND);

    if (match_token(TOKEN_DANS)) {
        /* --------------------------------------------------------------
         * FORME SPECIFIQUE :
         *   QUAND EXCEPTION DANS <try>
         *   [FAIRE <catch>]
         *   [SINON <else>]
         *   [ENFIN <cleanup>]
         *   FIN
         *
         * Ordre strict des clauses (validé pendant le parse). ENFIN
         * s'exécute sur les trois chemins de sortie (succès, attrapée,
         * propagée) via inline d'émission : le body F est re-scanné
         * depuis le source à chaque point de sortie (Arb 2). Pour la
         * propagation (cas C/D), un OP_TRY englobant supplémentaire
         * pose un handler "finally-unwind" qui inline F puis OP_RERAISE.
         *
         * Layout bytecode avec ENFIN :
         *
         *     OP_TRY outer_unwind                ; cas C / D
         *     OP_TRY inner_catch                 ; cas B (FAIRE)
         *     [T]
         *     OP_END_TRY                          ; pop inner
         *     OP_JUMP after_T_no_exc
         *   inner_catch:                          ; cas B / D arrive ici
         *     [H if FAIRE; sinon : OP_RERAISE]
         *     OP_JUMP after_H
         *   after_T_no_exc:                       ; cas A
         *     [E if SINON]
         *     OP_JUMP joinSuccess
         *   after_H:                              ; cas B (post-H)
         *   joinSuccess:                          ; cas A + cas B convergent
         *     OP_END_TRY                          ; pop outer
         *     [F inline]                          ; cas A + cas B
         *     OP_JUMP end
         *   outer_unwind:                         ; cas C (T raise) ou D (H reraise)
         *     [F inline]
         *     OP_RERAISE
         *   end:
         *
         * Layout bytecode sans ENFIN : pas d'outer wrapping ; layout
         * identique à pre-0014.
         * -------------------------------------------------------------- */

        /* === Spec : on doit savoir AVANT d'émettre T si ENFIN est
         * présent (pour décider d'installer ou non l'outer wrapper).
         * Solution : peek-scan forward depuis la position courante en
         * mode skip-but-depth-aware jusqu'à matcher ENFIN ou FIN. Ne
         * touche pas au scanner principal. */
        bool hasEnfinAhead = false;
        {
            Scanner savedS = parser.scanner;
            Token   savedP = parser.previous;
            Token   savedC = parser.current;
            bool    savedX = crossedNewline;
            bool    savedPanic = parser.panicMode;

            int depth = 0;
            while (!check(TOKEN_EOF)) {
                TokenType t = parser.current.type;
                /*  — meme regle que enfin_capture_body, meme source.
                 * Ce peek decide s'il faut installer l'OP_TRY englobant du
                 * chemin de propagation. Un sur-comptage le faisait rater le
                 * ENFIN pourtant present : le wrapper n'etait pas installe,
                 * puis la clause ENFIN etait quand meme parsee et l'emission
                 * patchait un saut jamais emis. Symptome mesure : `owl --check`
                 * MEURT (sortie 127, aucun diagnostic) sur un source legal
                 * portant un `SI c ALORS instr` dans le corps TRY. */
                if (prescan_token_in_depth_table(t)) {
                    if (t == TOKEN_FIN) {
                        if (depth == 0) break;
                        depth--;
                    } else if (parser_depth_delta() > 0) {
                        depth++;
                    }
                } else if (t == TOKEN_STRUCTURE || t == TOKEN_CLASSE ||
                           t == TOKEN_ENUMERATION || t == TOKEN_COMBINAISON) {
                    depth++;
                } else if (t == TOKEN_ENFIN && depth == 0) {
                    hasEnfinAhead = true;
                    break;
                }
                advance_token();
            }
            parser.scanner   = savedS;
            parser.previous  = savedP;
            parser.current   = savedC;
            crossedNewline   = savedX;
            parser.panicMode = savedPanic;
        }

        /* Outer OP_TRY pour cas C/D — seulement si ENFIN présent. */
        int outerTryJump = -1;
        if (hasEnfinAhead) {
            outerTryJump = emit_jump(OP_TRY);
        }

        /* Inner OP_TRY (cas B). */
        int innerTryJump = emit_jump(OP_TRY);

        /* try block */
        begin_scope();
        exception_parse_clause_body();
        end_scope();

        emit_byte(OP_END_TRY); /* pop inner */

        /* Le chemin no-exception saute le handler block. */
        int afterTryJump = emit_jump(OP_JUMP);

        /* --- Handler block (catch) — landing du inner OP_TRY. */
        patch_jump(innerTryJump);

        bool hasFaire, hasSinon, hasEnfin;
        int  afterHandlerJump = -1;
        int  afterSinonJump   = -1;
        EnfinRange enfinRange;

        /* Parse les clauses FAIRE / SINON / ENFIN.
         * Important : on PARSE H ici (dans la zone catch). Si pas de
         * FAIRE, le handler block ne contient rien (mais on doit
         * quand même émettre un OP_RERAISE si hasEnfinAhead pour que
         * cas C transite vers outer_unwind via inner). */
        bool emittedInnerReraise = false;
        if (!check(TOKEN_FAIRE)) {
            /* Aucun FAIRE : le handler block est vide. Si on a un outer
             * unwind (hasEnfinAhead), on émet OP_RERAISE pour que la
             * propagation passe par outer. Sinon (NI ENFIN NI FAIRE),
             * c'est un cas où on doit produire l'erreur legacy. */
            if (!check(TOKEN_SINON) && !check(TOKEN_ENFIN)) {
                consume(TOKEN_FAIRE, E_SYNTAX_EXP_FAIRE_AFTER_TRY);
                return;
            }
            if (hasEnfinAhead) {
                emit_byte(OP_RERAISE);
                emittedInnerReraise = true;
            } else {
                /*  : handler vide sans FAIRE ni ENFIN (donc avec
                 * SINON). Le chemin exception atterrit ici puis tombe dans le
                 * corps SINON. Sans rééquilibrage, le snapshot posé par
                 * l'OP_TRY fuit (+1 sur excSaveDepth) et son contexte périmé
                 * contamine un QUAND EXCEPTION ultérieur du même frame.
                 * OP_EXC_RESTORE dépile le snapshot ET restaure le contexte
                 * englobant, aligné . Le chemin no-exception passe par
                 * l'OP_END_TRY (déjà dépilé) et saute cet opcode : le
                 * patch_jump(afterTryJump) fait par la clause SINON pointe
                 * APRÈS ce byte. Ne change PAS le fait que SINON s'exécute sur
                 * exception (pré-existant, hors scope). */
                emit_byte(OP_EXC_RESTORE);
            }
        }

        exception_parse_optional_clauses(
            afterTryJump,
            &hasFaire, &afterHandlerJump,
            &hasSinon, &afterSinonJump,
            &hasEnfin, &enfinRange);

        /* ==============================================================
         * Émission des chemins finaux.
         * ============================================================== */

        /* Point de convergence success (cas A) + cas B (post-H). */
        if (!hasSinon) {
            patch_jump(afterTryJump);
        }
        if (hasFaire) {
            patch_jump(afterHandlerJump);
        } else if (!emittedInnerReraise) {
            /* Handler block vide sans outer : impossible théoriquement
             * (consume FAIRE plus haut a déjà fail). */
        }
        if (hasSinon) {
            patch_jump(afterSinonJump);
        }

        if (hasEnfin) {
            emit_byte(OP_END_TRY); /* pop outer (succès complet OU cas B) */
            enfin_emit_body(&enfinRange);
            int endJump = emit_jump(OP_JUMP);

            /* outer_unwind : cas C ou D. */
            patch_jump(outerTryJump);
            enfin_emit_body(&enfinRange);
            emit_byte(OP_RERAISE);

            patch_jump(endJump);
        }

        consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_EXCEPTION_HANDLER);
        return;
    }

    /* ------------------------------------------------------------------
     * FORME GENERALE : QUAND EXCEPTION <handler> FIN
     *
     * Scope: from this point to the end of the enclosing function. At
     * most one general-form handler is active at any time per frame —
     * declaring a second one further down replaces the first from its
     * declaration onward (no stacking).
     *
     * Architecture :
     *     OP_TRY handler_label
     *     OP_JUMP past_handler
     * handler_label:
     *     <handler body>
     *     OP_NIL
     *     OP_RETURN              ; terminates the frame after the handler
     * past_handler:
     *     <rest of function>
     *
     * The handler body terminates the frame on completion : no
     * fall-through to the code after FIN. If a handler caught an
     * exception, it owns the rest of the function. Replacement (T1)
     * and use-once (T2) are both consequences of this single rule.
     *
     * Forbidden inside a loop (T3) — use 'QUAND EXCEPTION DANS ... FAIRE'
     * for block-level scoping.
     * ------------------------------------------------------------------ */

    /* T3 : forme générale interdite dans une boucle (canon 3034001
     * §NOTE4_1). The check uses parser.previous which points at the
     * EXCEPTION token already consumed at function entry. */
    if (current->loopDepth > 0) {
        owl_emit_error_at(&parser.previous, E_SEM_QUAND_EXCEPTION_INSIDE_LOOP);
        /* Continue parsing so the rest of the file still produces
         * meaningful diagnostics, but emit nothing for this construct. */
        insideExceptionHandler++;
        begin_scope();
        while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
            declaration();
        }
        end_scope();
        insideExceptionHandler--;
        consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_EXCEPTION_HANDLER);
        return;
    }

    int tryJump = emit_jump(OP_TRY);
    int skipHandlerJump = emit_jump(OP_JUMP);

    /* Handler body — runs when the try catches. */
    patch_jump(tryJump);
    insideExceptionHandler++;
    begin_scope();
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF) && !check(TOKEN_ENFIN)) {
        declaration();
    }
    end_scope();
    insideExceptionHandler--;

    /* ENFIN refusé dans la forme générale (cf. spec §"Forme générale + ENFIN"). */
    if (check(TOKEN_ENFIN)) {
        owl_emit_error_current(E_SYNTAX_EXCEPTION_ENFIN_NOT_IN_GENERAL_FORM);
        /* Continue parsing so further diagnostics still surface. */
        advance_token();
        while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
            advance_token();
        }
    }

    /* Terminate the frame implicitly. Any RENVOYER inside the body
     * already returns earlier; this is the fallback path. */
    emit_byte(OP_NIL);
    emit_byte(OP_RETURN);

    /* Past the handler: reached only on normal (no-exception) flow.
     * The handler body NEVER falls through here. */
    patch_jump(skipHandlerJump);

    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_EXCEPTION_HANDLER);
}

/* ================================================================
 * ENUMERATION DECLARATION
 * ================================================================
 * Compiles: eCouleur est une Enumeration
 *               Rouge
 *               Vert = 10
 *               Bleu
 *           FIN
 *
 * Each enum value is an ObjInstance with fields "Nom" (string) and "Valeur".
 * Values are stored as class defaults, accessible via eCouleur.Rouge etc.
 * Uses native __EnumVal(enumName, valueName, value) to create instances.
 */
static void enum_declaration(Token enumName) {
    /*  — une énumération de CollectionDeProcédures arrive ici manglée
     * `COL$Énum` (slot GLOBAL distinct par collection, cf. var_declaration_after_est
     * + case_066 désambiguïsation 1 vs 2). Mais l'IDENTITÉ DE TYPE reste NUE :
     * l'enregistrement type (register_user_type_kind) et le TAG des instances
     * (__EnumVal arg1) portent le nom nu `Énum`, pour que la position de type
     * `e est un Énum` résolve et que deux valeurs de la même énum comparent égal
     * quel que soit le chemin (qualifié / nom nu). Énum hors collection : pas de
     * `$`, bareEnum == enumName, comportement identique. */
    Token bareEnum = enumName;
    const char* enumDollar = memchr(enumName.start, '$', (size_t)enumName.length);
    if (enumDollar != NULL) {
        bareEnum.start  = enumDollar + 1;
        bareEnum.length = enumName.length - (int)(enumDollar + 1 - enumName.start);
    }
    register_user_type_kind(bareEnum.start, bareEnum.length,
                            OWL_USER_TYPE_ENUMERATION, enumName.line);
    /* Track enum as a type (not a variable) so variables with same name are allowed.
     * On track le GLOBAL réellement défini (mangled si collection) pour l'exemption
     * unused + le nom nu pour la reconnaissance de type en position de valeur. */
    if (current->scopeDepth == 0) {
        global_track_declare_structure(enumName.start, enumName.length, enumName.line);
        if (enumDollar != NULL) {
            global_track_declare_structure(bareEnum.start, bareEnum.length, enumName.line);
        }
    }
    ConstIdx nameConst = identifier_constant(&enumName);

    /* Create the enum class */
    emit_const_op(OP_CLASS, nameConst);
    /* Tag as Enumeration (CLASS_KIND_ENUM = 1) so TypeVar/RécupèreDéfinition
     * retournent owlEnumeration et non owlClasse. */
    emit_bytes(OP_MARK_CLASS_KIND, 1);

    /* Define as global immediately */
    ConstIdx global = { 0 };
    if (current->scopeDepth == 0) {
        global = nameConst;
    }
    define_variable(global);

    /*  — énum de CollectionDeProcédures : la classe est aussi exposée
     * sous son nom NU (alias vers le même ObjClass). Le slot MANGLED `COL$Énum`
     * reste le canon de l'accès qualifié `COL.Énum` (distinct par collection,
     * case_066). Le slot NU permet à fn_entier_coerce de résoudre le tag `Énum`
     * de l'instance vers un ObjClass CLASS_KIND_ENUM (extraction `.Valeur`) et
     * assure l'identité de type stable (pass-through des coerces homonymes). Deux
     * collections déclarant `Statut` collisionnent sur le slot nu (dernier gagne)
     * sans impact : l'accès qualifié passe par les slots mangled distincts, la
     * coercion lit la `.Valeur` de l'instance elle-même. */
    if (current->scopeDepth == 0 && enumDollar != NULL) {
        ConstIdx bareConst = identifier_constant(&bareEnum);
        emit_const_op(OP_GET_GLOBAL, nameConst);
        emit_const_op(OP_DEFINE_GLOBAL, bareConst);
    }

    /* Get class back on stack for OP_ENUM_VALUE ops */
    if (current->scopeDepth == 0) {
        emit_const_op(OP_GET_GLOBAL, nameConst);
    } else {
        int slot = resolve_local(current, &enumName);
        emit_bytes(OP_GET_LOCAL, (uint8_t)slot);
    }

    /* Parse enum values until FIN */
    int autoValue = 0;

    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_ENUM_VALUE_NAME);
            advance_token();
            continue;
        }

        advance_token();
        Token valueName = parser.previous;
        ConstIdx valueNameConst = identifier_constant(&valueName);

        /* Enum members are type constants — exempt from unused-variable warnings */
        global_track_declare_structure(valueName.start, valueName.length, valueName.line);

        /* Call __EnumVal(enumTypeName, valueName, valeur) -> instance */
        {
            Token evTok;
            evTok.start = "__EnumVal";
            evTok.length = 9;
            ConstIdx evConst = identifier_constant(&evTok);
            emit_const_op(OP_GET_GLOBAL, evConst);

            /* arg 1: enum type name as string — nom NU (identité de type stable :
             * pass-through des coerces composites homonymes comme `Couleur`,
             * comparaison d'instances, et résolution par fn_entier_coerce via
             * l'alias de classe NU défini ci-dessous). Cf.  en tête. */
            ConstIdx enumStr = make_constant(OBJ_VAL(
                obj_copy_string(bareEnum.start, bareEnum.length)));
            emit_const_op(OP_CONSTANT, enumStr);

            /* arg 2: value name as string */
            ConstIdx valNameStr = make_constant(OBJ_VAL(
                obj_copy_string(valueName.start, valueName.length)));
            emit_const_op(OP_CONSTANT, valNameStr);

            /* arg 3: the actual value */
            if (match_token(TOKEN_EQUAL)) {
                /* Explicit value — must be a constant integer or string */
                expression();
                /* We can't reliably read autoValue from runtime, so for
                 * auto-increment after explicit we just use compile-time tracking.
                 * This works for integer literals. */
                /* Try to track: if the expression was a simple integer literal,
                 * update autoValue. For complex expressions, autoValue continues. */
                /* For now: bump autoValue regardless. User should use explicit for all
                 * or rely on auto for all. Mixed = autoValue continues from last auto. */
            } else {
                emit_const_op(OP_CONSTANT, make_constant(INTEGER_VAL(autoValue)));
            }
            autoValue++;

            emit_bytes(OP_CALL, 3);
        }

        /* Stack: [class] [instance] */
        /* For global scope, define the value as a global AND store in class defaults */
        if (current->scopeDepth == 0) {
            emit_byte(OP_DUP);  /* Stack: [class] [instance] [instance] */
            emit_const_op(OP_DEFINE_GLOBAL, valueNameConst);  /* Stack: [class] [instance] */
        }
        /* Store as class default via OP_ENUM_VALUE */
        emit_const_op(OP_ENUM_VALUE, valueNameConst);
        /* Stack: [class] */
    }

    emit_byte(OP_POP); /* pop the class */
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_ENUMERATION);
}

/* ================================================================
 * COMBINATION DECLARATION
 * Same pattern as enum but with power-of-2 auto-values and a
 * __isCombination marker on each value instance.
 * ================================================================ */
static void combination_declaration(Token combiName) {
    /*  — combinaison de CollectionDeProcédures : arrive manglée
     * `COL$Combi` (peek collection, cf. var_declaration_after_est). Miroir exact
     * du traitement énum : IDENTITÉ DE TYPE NUE (register_user_type +
     * tag __EnumVal sous `Combi`), slot GLOBAL mangled distinct par collection +
     * alias NU (dernier gagnant sur collision, l'accès qualifié passe par les
     * slots mangled). Hors collection : pas de `$`, bareCombi == combiName. */
    Token bareCombi = combiName;
    const char* combiDollar = memchr(combiName.start, '$', (size_t)combiName.length);
    if (combiDollar != NULL) {
        bareCombi.start  = combiDollar + 1;
        bareCombi.length = combiName.length - (int)(combiDollar + 1 - combiName.start);
    }
    register_user_type(bareCombi.start, bareCombi.length, combiName.line);
    /* Track combination as a type (not a variable) so variables with same name are allowed */
    if (current->scopeDepth == 0) {
        global_track_declare_structure(combiName.start, combiName.length, combiName.line);
        if (combiDollar != NULL) {
            global_track_declare_structure(bareCombi.start, bareCombi.length, combiName.line);
        }
    }
    ConstIdx nameConst = identifier_constant(&combiName);

    /* Create the combination class */
    emit_const_op(OP_CLASS, nameConst);
    /* Tag as Combinaison (CLASS_KIND_COMBINATION = 2). */
    emit_bytes(OP_MARK_CLASS_KIND, 2);

    /* Define as global immediately */
    ConstIdx global = { 0 };
    if (current->scopeDepth == 0) {
        global = nameConst;
    }
    define_variable(global);

    /*  — alias NU vers le même ObjClass (cf. enum_declaration). */
    if (current->scopeDepth == 0 && combiDollar != NULL) {
        ConstIdx bareConst = identifier_constant(&bareCombi);
        emit_const_op(OP_GET_GLOBAL, nameConst);
        emit_const_op(OP_DEFINE_GLOBAL, bareConst);
    }

    /* Get class back on stack for OP_ENUM_VALUE ops */
    if (current->scopeDepth == 0) {
        emit_const_op(OP_GET_GLOBAL, nameConst);
    } else {
        int slot = resolve_local(current, &combiName);
        emit_bytes(OP_GET_LOCAL, (uint8_t)slot);
    }

    /* Mark class itself as combination: store __isCombination = true */
    {
        Token markerTok;
        markerTok.start = "__CombinationMark";
        markerTok.length = 17;
        ConstIdx markerConst = identifier_constant(&markerTok);
        emit_byte(OP_TRUE);
        emit_const_op(OP_ENUM_VALUE, markerConst);
    }

    /* Parse combination values until FIN.
     * Auto-values are powers of 2: 1, 2, 4, 8, ... */
    int autoBit = 0; /* bit position: value = 1 << autoBit */

    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_COMBINATION_VALUE_NAME);
            advance_token();
            continue;
        }

        advance_token();
        Token valueName = parser.previous;
        ConstIdx valueNameConst = identifier_constant(&valueName);

        /* Combination members are type constants — exempt from unused-variable warnings */
        global_track_declare_structure(valueName.start, valueName.length, valueName.line);

        /* Call __EnumVal(combiTypeName, valueName, valeur) -> instance */
        {
            Token evTok;
            evTok.start = "__EnumVal";
            evTok.length = 9;
            ConstIdx evConst = identifier_constant(&evTok);
            emit_const_op(OP_GET_GLOBAL, evConst);

            /* arg 1: combination type name as string — nom NU (identité de type
             * stable quel que soit le chemin, cf.  en tête). */
            ConstIdx combiStr = make_constant(OBJ_VAL(
                obj_copy_string(bareCombi.start, bareCombi.length)));
            emit_const_op(OP_CONSTANT, combiStr);

            /* arg 2: value name as string */
            ConstIdx valNameStr = make_constant(OBJ_VAL(
                obj_copy_string(valueName.start, valueName.length)));
            emit_const_op(OP_CONSTANT, valNameStr);

            /* arg 3: the actual value */
            if (match_token(TOKEN_EQUAL)) {
                /* Explicit value - can be an expression like Lecture + Ecriture */
                expression();
            } else {
                /* Auto power of 2 */
                int64_t autoVal = (int64_t)1 << autoBit;
                emit_const_op(OP_CONSTANT, make_constant(INTEGER_VAL(autoVal)));
            }
            autoBit++;

            emit_bytes(OP_CALL, 3);
        }

        /* Stack: [class] [instance] */
        /* For global scope, define the value as a global AND store in class defaults */
        if (current->scopeDepth == 0) {
            emit_byte(OP_DUP);  /* Stack: [class] [instance] [instance] */
            emit_const_op(OP_DEFINE_GLOBAL, valueNameConst);  /* Stack: [class] [instance] */
        }
        /* Store as class default via OP_ENUM_VALUE */
        emit_const_op(OP_ENUM_VALUE, valueNameConst);
        /* Stack: [class] */
    }

    emit_byte(OP_POP); /* pop the class */
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_COMBINAISON);
}

/* ================================================================
 * INLINE METHOD / CONSTRUCTOR / DESTRUCTOR
 *
 * Helpers appeles depuis le body parse de class_declaration. Reprennent
 * la structure de l'ancien chemin externe (PROCEDURE cClass.M / cClass()
 * / Destructeur cClass()) mais en mode inline : la classe est deja sur
 * la pile (push effectue par class_declaration via OP_GET_GLOBAL/LOCAL),
 * il ne faut donc PAS la pousser de nouveau ni la POP en sortie.
 * ================================================================ */

/* Kind discriminant pour le helper unifie. */
typedef enum {
    INLINE_KIND_METHOD,
    INLINE_KIND_CONSTRUCTOR,
    INLINE_KIND_DESTRUCTOR,
} InlineMethodKind;

/* compile_inline_class_method : parse `<Nom>(args) [: returnType]
 * <body> FIN` en mode inline body class. La classe est SUPPOSEE deja
 * pushee sur la pile par class_declaration (le caller). On emit le
 * OP_METHOD a la fin mais on NE POP PAS la classe (le caller s'en
 * charge a la fin du body class). */
static void compile_inline_class_method(InlineMethodKind kind,
                                        Token className,
                                        Token procKeyword,
                                        Token methodName,
                                        OwlVisibility procVis,
                                        bool isGlobalMethod,
                                        bool isAbstractMethod) {
    /* Nom effectif emis dans OP_METHOD. */
    const char* effectiveNameStart = methodName.start;
    int         effectiveNameLen   = methodName.length;
    if (kind == INLINE_KIND_CONSTRUCTOR) {
        /* Le constructeur est stocke sous le nom de la classe (canon
         * + parite avec l'ancien chemin externe). */
        effectiveNameStart = className.start;
        effectiveNameLen   = className.length;
    } else if (kind == INLINE_KIND_DESTRUCTOR) {
        effectiveNameStart = "__destructor";
        effectiveNameLen   = 12;
    }

    /* Dup detection (uniquement pour les methodes nommees user — pas pour
     * constructeur/destructeur qui ont une cle reservee unique par classe). */
    if (kind == INLINE_KIND_METHOD) {
        int dupIdx = find_declared_method(
            className.start, className.length,
            methodName.start, methodName.length);
        if (dupIdx >= 0) {
            char methodBuf[128];
            char classBuf[128];
            int ml = methodName.length < (int)sizeof(methodBuf) - 1
                     ? methodName.length : (int)sizeof(methodBuf) - 1;
            int cl = className.length < (int)sizeof(classBuf) - 1
                     ? className.length : (int)sizeof(classBuf) - 1;
            memcpy(methodBuf, methodName.start, (size_t)ml); methodBuf[ml] = '\0';
            memcpy(classBuf, className.start, (size_t)cl); classBuf[cl] = '\0';
            char lineBuf[16];
            snprintf(lineBuf, sizeof(lineBuf), "%d",
                     declaredMethods[dupIdx].declaredLine);
            owl_emit_error_at(&procKeyword, E_SEM_METHOD_DUPLICATE,
                              "method", methodBuf,
                              "class", classBuf,
                              "line", lineBuf,
                              NULL);
        } else {
            register_declared_method(
                className.start, className.length,
                methodName.start, methodName.length,
                procKeyword.line);
        }
        method_visibility_register(
            className.start, className.length,
            methodName.start, methodName.length,
            procVis, procKeyword.line, currentFileIndex);
        /*  : peupler le registre des methodes GLOBALE pour le check
         * negatif au site `cClass.M()` dans body methode (cf. dot_access). */
        if (isGlobalMethod) {
            class_globale_method_register(
                className.start, className.length,
                methodName.start, methodName.length);
        }
        /*  — warning d'homonymie methode/procedure globale.
         *
         * Depuis ce ticket, dans le body d'une methode d'instance, un appel
         * nu `M(...)` resout d'abord sur la methode soeur (priorite au plus
         * proche) puis fallback sur la globale. Si l'utilisateur a une
         * methode et une procedure globale portant le meme nom, son intuition
         * peut diverger de la realite — d'ou le warning au declarateur le
         * plus tardif (la methode, qui masque la globale dans son scope).
         *
         * Conditions :
         *   - Methode d'instance uniquement (les GLOBALE s'appellent
         *     `cClass.M()` et n'ont pas d'appel nu depuis une soeur).
         *   - Une procedure/fonction de meme nom existe au projet (cross-file
         *     inclus). Source de verite : projectSymbols (alimente par le
         *     prescan_file). Si NULL (compile single-file), pas de check —
         *     V1 acceptable, l'utilisateur travaille en script isole.
         *   - Pas de warning sur les natives (sinon une methode `Trace` ou
         *     `Info` ferait du bruit en cascade sur des classes legitimes). */
        if (kind == INLINE_KIND_METHOD && !isGlobalMethod
            && projectSymbols != NULL) {
            char mNameZ[128];
            int mz = methodName.length < (int)sizeof(mNameZ) - 1
                     ? methodName.length : (int)sizeof(mNameZ) - 1;
            memcpy(mNameZ, methodName.start, (size_t)mz);
            mNameZ[mz] = '\0';
            for (int i = 0; i < projectSymbols->count; i++) {
                const ProjectSymbol* sym = &projectSymbols->symbols[i];
                if (sym->kind != SYM_PROCEDURE && sym->kind != SYM_FUNCTION) {
                    continue;
                }
                if (strcasecmp(sym->name, mNameZ) != 0) continue;
                /*  : le garde-fou fileIndex anti faux positif a
                 * ete retire — le depth tracker prescan est desormais
                 * exact (helper prescan_depth_delta couvrant les 6
                 * ouvrants lexicaux + SI inline). L'homonymie
                 * intra-fichier est maintenant detectee correctement
                 * (cas reel : une procedure globale vraiment declaree
                 * dans le meme fichier qu'une classe portant une
                 * methode de meme nom). Limitation V1 d' levee. */
                char clsBuf[128];
                int cb = className.length < (int)sizeof(clsBuf) - 1
                         ? className.length : (int)sizeof(clsBuf) - 1;
                memcpy(clsBuf, className.start, (size_t)cb);
                clsBuf[cb] = '\0';
                owl_emit_warning_at(&methodName,
                    W_SEM_METHOD_SHADOWS_GLOBAL_PROC,
                    "method", mNameZ,
                    "class", clsBuf,
                    NULL);
                break;
            }
        }
    }

    /* Sauvegarde + push ClassCompiler local (le caller class_declaration a
     * deja installe son propre ClassCompiler, on en empile un second pour
     * coder l'interieur de la methode avec son nom propre — same pattern
     * que l'ancien chemin externe). */
    ClassCompiler classCompiler;
    classCompiler.enclosing = currentClass;
    classCompiler.name = className;
    classCompiler.isGlobalMethod = isGlobalMethod;
    currentClass = &classCompiler;

    Compiler compiler;
    init_compiler(&compiler, kind == INLINE_KIND_CONSTRUCTOR
                             ? TYPE_CONSTRUCTOR : TYPE_METHOD);
    begin_scope();
    current->function->name = obj_copy_string(effectiveNameStart, effectiveNameLen);

    /*  — methode ecrite DANS le body de la classe avec un prefixe
     * `PROCEDURE <Classe>.<methode>()`. Le nom avant le `.` a ete lu comme
     * methodName ; on arrive ici avec `.` en token courant. On est deja dans
     * le corps de la classe : le message "methodes externes supprimees,
     * declarez inline" (voie top-level) serait absurde ici.  — on
     * pointe le vrai probleme : le prefixe de classe est redondant. {class} =
     * le prefixe ecrit (methodName), {method} = le nom apres le point. On
     * consomme `.` + nom pour retomber sur `(` et eviter la cascade. */
    if (check(TOKEN_DOT)) {
        advance_token(); /* consume '.' */
        Token extMethod = parser.current;
        if (check(TOKEN_IDENTIFIER)) advance_token();
        char classBuf[128];
        char methodBuf[128];
        int cl = methodName.length < (int)sizeof(classBuf) - 1
                 ? methodName.length : (int)sizeof(classBuf) - 1;
        int ml = extMethod.length < (int)sizeof(methodBuf) - 1
                 ? extMethod.length : (int)sizeof(methodBuf) - 1;
        memcpy(classBuf, methodName.start, (size_t)cl); classBuf[cl] = '\0';
        memcpy(methodBuf, extMethod.start, (size_t)ml); methodBuf[ml] = '\0';
        owl_emit_error_at(&procKeyword, E_SEM_METHODE_PREFIXE_REDONDANT,
                          "class", classBuf,
                          "method", methodBuf,
                          NULL);
    }

    consume(TOKEN_LEFT_PAREN, E_SYNTAX_EXP_LPAREN_AFTER_MEMBER_NAME);

    /* Capture signature (params + retour) pour cross-check interface. */
    int sigParamCount = 0;
    char sigParamTypes[MAX_METHOD_PARAMS][32];
    memset(sigParamTypes, 0, sizeof(sigParamTypes));
    Value defaults[255];
    int defaultCount = 0;
    int minArity = 0;
    /*  — parite avec les params de procedure top-level : LOCAL en
     * tete d'un parametre force une copie profonde a l'entree de la methode,
     * si bien qu'une mutation dans le corps ne remonte pas a l'appelant. */
    uint8_t localParamSlots[256];
    int localParamCount = 0;
    if (!check(TOKEN_RIGHT_PAREN)) {
        do {
            current->function->arity++;
            if (current->function->arity > 255) {
                owl_emit_error_current(E_SYNTAX_TOO_MANY_PARAMETERS);
            }
            bool isLocalParam = match_token(TOKEN_LOCAL);
            if (reject_keyword_as_param_name()) advance_token();
            else consume(TOKEN_IDENTIFIER, E_SYNTAX_EXPECTED_PARAM_NAME);
            Token paramName = parser.previous;
            declare_variable(&paramName);
            if (isLocalParam) {
                localParamSlots[localParamCount++] = (uint8_t)(current->localCount - 1);
            }
            /*  — une methode est une routine : elle bute sur la meme
             * limite de parametres qu'une procedure, et au meme endroit. Sans
             * ce refus, une methode acceptait silencieusement plus de
             * parametres que sa table de signatures n'en memorise. */
            if (sigParamCount == MAX_METHOD_PARAMS) {
                error_capacity_exceeded("MAX_METHOD_PARAMS", MAX_METHOD_PARAMS);
            }
            if (match_token(TOKEN_EST)) {
                if (sigParamCount < MAX_METHOD_PARAMS && /* capacity-ok: borne d'ecriture, le refus est pose juste au-dessus */
                    (check(TOKEN_IDENTIFIER) || is_type_token())) {
                    int n = parser.current.length < 31
                            ? parser.current.length : 31;
                    memcpy(sigParamTypes[sigParamCount],
                           parser.current.start, n);
                    sigParamTypes[sigParamCount][n] = '\0';
                }
                /*  /  — parite avec les params de procedure : un
                 * type inconnu en position de parametre de methode est rejete
                 * net, HEAD scalaire (record_pending_type_ref) ET element de
                 * collection apres `de` (`tableau de Zorglub` ->
                 * record_collection_elem_type_ref). skip_type_spec_ex se charge
                 * des deux enregistrements ; les primitifs ne sont jamais
                 * rejetes. */
                skip_type_spec_ex(true, false);
            }
            /*  — attribut de declaration <utile>/<useful> pose apres le
             * type d'un parametre de METHODE (2e des trois copies du parseur de
             * params, cf.  pour la 1ere). Meme mecanisme que les
             * locals/globals (parse_nullability_marker_ex + record_suppress_unused),
             * pas de chemin de parse duplique. Le parametre marque est exempte de
             * W_SEM_VAR_UNUSED. Les autres sorties du marqueur (nullable /
             * indetectable) n'ont pas de support sur un slot de parametre : elles
             * sont consommees puis ignorees ici. */
            {
                bool pUndetectable = false;
                bool pSuppressUnused = false;
                (void)parse_nullability_marker_ex(&pUndetectable, &pSuppressUnused);
                if (pSuppressUnused) {
                    record_suppress_unused(paramName);
                }
            }
            sigParamCount++;
            /* Defaults : autorises pour constructeur (multi-arity) et
             * methode normale. Destructeur : aucun parametre attendu. */
            if (match_token(TOKEN_EQUAL)) {
                Value v;
                if (parse_default_literal(&v)) {
                    defaults[defaultCount++] = v;
                    if (current->localCount > 0)
                        current->locals[current->localCount - 1].hasInitializer = true;
                }
            } else {
                if (defaultCount > 0) {
                    owl_emit_error_at(&parser.previous, E_SEM_REQUIRED_PARAM_AFTER_DEFAULT);
                }
                minArity = current->function->arity;
            }
        } while (match_token(TOKEN_COMMA));
    }
    consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_PARAMS);
    current->function->minArity = minArity;
    if (defaultCount > 0) {
        current->function->defaults = (Value*)malloc(sizeof(Value) * defaultCount);
        for (int di = 0; di < defaultCount; di++) {
            current->function->defaults[di] = defaults[di];
        }
        current->function->defaultCount = defaultCount;
    }

    char sigReturnType[32];
    sigReturnType[0] = '\0';
    /*  : annotation type retour `: <Type>` permissive — on consomme
     * le `:` meme si le type qui suit n'est pas reconnu, a condition d'etre
     * sur la meme ligne que `)`. Sinon le prefix parselet `this_field`
     * mange le `:` comme acces `:champ` et enregistre une ref invalide qui
     * cascade en faux positif "membre inconnu" via colon_member_cross_check_global.
     * Le seul contexte legal apres `)` d'une signature est l'annotation type
     * retour : pas d'ambiguite. */
    if (is_return_type_colon() ||
        (check(TOKEN_COLON) && !crossedNewline)) {
        advance_token(); /* consume ':' */
        if (check(TOKEN_IDENTIFIER) || is_type_token()) {
            int n = parser.current.length < 31
                    ? parser.current.length : 31;
            memcpy(sigReturnType, parser.current.start, n);
            sigReturnType[n] = '\0';
        }
        skip_type_spec();
    }

    /* Methode abstraite : signature seule, pas de body ni de FIN.
     * Pas applicable au constructeur/destructeur. */
    if (kind == INLINE_KIND_METHOD && isAbstractMethod) {
        class_abstract_method_register(className.start, className.length,
                                       methodName.start, methodName.length);
        (void)end_compiler();
        currentClass = classCompiler.enclosing;
        return; /* pas de OP_METHOD, pas de FIN attendu */
    }

    if (kind == INLINE_KIND_METHOD) {
        declared_method_sig_register(className.start, className.length,
                                     methodName.start, methodName.length,
                                     sigParamCount, sigParamTypes,
                                     sigReturnType);
    } else if (kind == INLINE_KIND_CONSTRUCTOR) {
        /*  : enregistre l'arite minimale du constructeur pour le
         * check compile-time de `oFoo est un cFoo` (sans `()`). minArity
         * = nombre de params sans valeur par defaut (calcule plus haut). */
        class_constructor_arity_register(className.start, className.length,
                                         minArity);
    }

    /*  — LOCAL params: deep-clone chaque slot marque pour que la
     * methode mute sa copie locale sans toucher la valeur de l'appelant
     * (pendant du chemin procedure top-level). */
    for (int li = 0; li < localParamCount; li++) {
        uint8_t slot = localParamSlots[li];
        emit_bytes(OP_GET_LOCAL, slot);
        emit_byte(OP_DEEP_COPY);
        emit_bytes(OP_SET_LOCAL, slot);
        emit_byte(OP_POP);
    }

    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        declaration();
    }

    if (kind == INLINE_KIND_CONSTRUCTOR) {
        /* Constructor returns 'this' (slot 0). */
        emit_bytes(OP_GET_LOCAL, 0);
        emit_byte(OP_RETURN);
    }

    ObjFunction* function = end_compiler();
    currentClass = classCompiler.enclosing;

    /* Les OP de DEFINITION de la methode (OP_CONSTANT + OP_METHOD) sont emis
     * dans le chunk ENGLOBANT (corps de classe / script du fichier). Sans
     * ancrage, emit_byte() les etiquette avec parser.previous.line = dernier
     * token du corps -> une ligne DU CORPS de la methode. Meme bug debug que
     *  pour les procedures : un breakpoint sur la derniere ligne du
     * corps taperait pendant la definition de la classe (frame fichier-script,
     * pas la frame methode). On ancre sur la ligne de declaration. */
    Token savedPrev = parser.previous;
    parser.previous = procKeyword;

    emit_const_op(OP_CONSTANT, make_constant(OBJ_VAL(function)));
    /*  : strip les accents du nom de methode AVANT obj_copy_string
     * pour symetrie avec identifier_constant (le call site). Sans ce strip,
     * une decl 'Crédite' stockait verbatim alors que le call cherchait
     * 'Credite' (deja strippe) -> "Methode inconnue" runtime. Invariant 2
     * (accent-insensible). Constructeur/__destructor : strip no-op. */
    char methodNameStripped[256];
    int methodNameStrippedLen = scanner_strip_accents(
        effectiveNameStart, effectiveNameLen,
        methodNameStripped, sizeof(methodNameStripped));
    ConstIdx methodNameConst = make_constant(OBJ_VAL(
        obj_copy_string(methodNameStripped, methodNameStrippedLen)));
    emit_const_op(OP_METHOD, methodNameConst);

    parser.previous = savedPrev;

    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_METHOD);
}

/* ================================================================
 * CLASS DECLARATION
 * ================================================================ */
static void class_declaration(Token className) {
    /*  : interdire les classes declarees a l'interieur d'une
     * procedure / methode / bloc local. Les classes vivent uniquement
     * au top-level d'un fichier (aligne avec la regle "1 classe = 1
     * fichier"). Sans ce garde-fou, la suite du parse enregistre un
     * type local jamais resolu au runtime -> crash "Undefined function".
     * Check place AVANT 1c1f pour donner un message precis ciblant le
     * vrai probleme (nested) plutot que le symptome (collision fichier). */
    if (current->type != TYPE_SCRIPT || current->scopeDepth != 0) {
        owl_emit_error_at(&className, E_SEM_CLASS_NOT_TOP_LEVEL);
        /* Skip le corps de la classe (jusqu'au FIN equilibre) pour
         * eviter une cascade d'erreurs secondaires ("Type inconnu",
         * "Expected expression") qui ne servent pas l'utilisateur. */
        int depth = 1;
        while (depth > 0 && parser.current.type != TOKEN_EOF) {
            if (parser.current.type == TOKEN_FIN) {
                depth--;
                advance_token();
            } else if (prescan_token_in_depth_table(parser.current.type)
                       && parser_depth_delta() > 0) {
                depth++;
                advance_token();
            } else {
                advance_token();
            }
        }
        return;
    }

    /*  — le corps de classe n'utilise JAMAIS le mode de portee
     * top-level (GLOBAL/GLOBALE y designent membres/methodes statiques, chemin
     * de parsing distinct). On force le defaut GLOBAL pour garantir qu'une
     * bascule LOCAL qui precederait une classe ne confine pas ses membres.
     * Pas de restore : un fichier ne contient qu'une classe (verrou 1c1f) et
     * le mode est reinitialise par fichier. */
    g_toplevel_confine = false;

    /* Convention OWL "1 classe = 1 fichier" : un fichier ne peut declarer
     * qu'UNE seule Classe, et ne peut la melanger avec aucune autre Fenetre/
     * Etat ni code runtime top-level. Ce mapping fichier <-> classe simplifie
     * editeur, packaging, auto-discovery cross-fichier. Divergence assumee
     * vs canon qui n'enforce pas (regle OWL pragmatique). */
    if (g_file_first_class_line > 0) {
        char fcName[128];
        int nl = g_file_first_class_name_len < (int)sizeof(fcName) - 1
                 ? g_file_first_class_name_len : (int)sizeof(fcName) - 1;
        memcpy(fcName, g_file_first_class_name, (size_t)nl);
        fcName[nl] = '\0';
        char lineBuf[16];
        snprintf(lineBuf, sizeof(lineBuf), "%d", g_file_first_class_line);
        owl_emit_error_at(&className, E_SEM_CLASS_FILE_ALREADY_HAS_CLASS,
                          "name", fcName,
                          "line", lineBuf,
                          NULL);
    } else if (g_file_first_window_line > 0) {
        char lineBuf[16];
        snprintf(lineBuf, sizeof(lineBuf), "%d", g_file_first_window_line);
        owl_emit_error_at(&className, E_SEM_CLASS_FILE_HAS_WINDOW,
                          "line", lineBuf,
                          NULL);
    } else if (g_file_first_etat_line > 0) {
        char lineBuf[16];
        snprintf(lineBuf, sizeof(lineBuf), "%d", g_file_first_etat_line);
        owl_emit_error_at(&className, E_SEM_CLASS_FILE_HAS_ETAT,
                          "line", lineBuf,
                          NULL);
    } else if (g_file_first_non_class_stmt_line > 0) {
        char lineBuf[16];
        snprintf(lineBuf, sizeof(lineBuf), "%d", g_file_first_non_class_stmt_line);
        owl_emit_error_at(&className, E_SEM_CLASS_FILE_HAS_RUNTIME_CODE,
                          "line", lineBuf,
                          NULL);
    } else {
        /* Premiere (et unique attendue) Classe du fichier : memoriser. */
        g_file_first_class_line = className.line;
        int n = className.length;
        if (n >= (int)sizeof(g_file_first_class_name)) {
            n = (int)sizeof(g_file_first_class_name) - 1;
        }
        memcpy(g_file_first_class_name, className.start, (size_t)n);
        g_file_first_class_name[n] = '\0';
        g_file_first_class_name_len = n;
    }

    register_user_type_kind(className.start, className.length,
                            OWL_USER_TYPE_CLASSE, className.line);
    /* Track class as a type (not a variable) so variables with same name are allowed */
    if (current->scopeDepth == 0) {
        global_track_declare_structure(className.start, className.length, className.line);
    }

    /*  : modificateur optionnel `, abstraite` apres CLASSE.
     * Canon 6010006 NOTE3_3 : `<NomClasse> est une Classe [, abstraite]`.
     * Une classe abstraite ne peut pas etre instanciee directement. */
    if (check(TOKEN_COMMA)) {
        Scanner savedScan = parser.scanner;
        Token savedCur = parser.current;
        Token savedPrev = parser.previous;
        bool savedXNL = crossedNewline;
        advance_token(); /* consume ',' */
        if (check(TOKEN_ABSTRAITE)) {
            advance_token(); /* consume ABSTRAITE */
            class_abstract_register(className.start, className.length);
        } else {
            /* Pas la virgule attendue, restaurer pour ne pas perturber le
             * parse (eviter de consommer la virgule d'une autre construction). */
            parser.scanner = savedScan;
            parser.current = savedCur;
            parser.previous = savedPrev;
            crossedNewline = savedXNL;
        }
    }

    ConstIdx nameConst = identifier_constant(&className);

    emit_const_op(OP_CLASS, nameConst);

    ConstIdx global = { 0 };
    if (current->scopeDepth == 0) {
        global = nameConst;
    }
    define_variable(global);

    ClassCompiler classCompiler;
    classCompiler.enclosing = currentClass;
    classCompiler.name = className;
    classCompiler.isGlobalMethod = false;
    currentClass = &classCompiler;

    /* Get class back on stack for OP_INHERIT and OP_METHOD */
    if (current->scopeDepth == 0) {
        emit_const_op(OP_GET_GLOBAL, nameConst);
    } else {
        int slot = resolve_local(current, &className);
        emit_bytes(OP_GET_LOCAL, (uint8_t)slot);
    }

    /* Check for inheritance: Herite de cParent */
    if (match_token(TOKEN_HERITE)) {
        match_token(TOKEN_DE);
        consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_SUPERCLASS_NAME);
        Token superName = parser.previous;
        class_super_register(className.start, className.length,
                             superName.start, superName.length);
        named_variable(superName, false);
        emit_byte(OP_INHERIT);
    }

    /*  : modes d'accès POO. Le keyword PUBLIC/PRIVE/PROTEGE pose
     * le mode pour TOUS les fields déclarés en-dessous, jusqu'au prochain
     * keyword ou FIN. Default sans keyword = PUBLIC (alignement canon). */
    OwlVisibility currentVis = OWL_VIS_PUBLIC;

    /*  : bloc GLOBAL — membres communs a toutes les instances,
     * accessibles via cClasse.nom sans instance. Le mot-cle GLOBAL pose
     * le mode pour TOUS les membres declares en-dessous, jusqu'au prochain
     * keyword (PUBLIC/PRIVE/PROTEGE/GLOBAL) ou FIN. */
    bool inGlobalBlock = false;

    /*  : singletons en attente d'allocation. Quand on detecte
     * `GLOBAL <nom> est <ClasseCourante>` dans le body, l'instance unique
     * doit etre creee a la fin du class_declaration (apres OP_INHERIT et
     * eventuels enregistrements). Les noms sont collectes ici et emis
     * juste avant le OP_POP final. Limite intentionnelle : si la classe
     * a un constructeur user avec args, l'appel sans args echouera au
     * runtime (alignement canon : un singleton suppose un ctor 0-arg
     * ou pas de ctor). */
    #define MAX_SINGLETONS_PER_CLASS 8
    ConstIdx pendingSingletons[MAX_SINGLETONS_PER_CLASS];
    int pendingSingletonCount = 0;

    /* Parse class body until FIN */
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        /*  : TOKEN_TYPE libres (date, duree, json, ...) comme nom
         * de champ de classe → demote en IDENTIFIER. Ces tokens ne sont
         * jamais utilises comme directive structurelle (PUBLIC/PRIVE/
         * PROCEDURE/HERITE/etc.) donc le demote en tete de tour est safe. */
        (void)demote_free_type_to_identifier();
        if (check(TOKEN_PUBLIC)) {
            advance_token();
            currentVis = OWL_VIS_PUBLIC;
            inGlobalBlock = false;
            continue;
        }
        if (check(TOKEN_PRIVE)) {
            advance_token();
            currentVis = OWL_VIS_PRIVE;
            inGlobalBlock = false;
            continue;
        }
        if (check(TOKEN_PROTEGE)) {
            advance_token();
            currentVis = OWL_VIS_PROTEGE;
            inGlobalBlock = false;
            continue;
        }
        if (check(TOKEN_GLOBAL)) {
            advance_token();
            inGlobalBlock = true;
            continue;
        }
        /*  : bloc LOCAL — complement explicite de GLOBAL. Ramene
         * l'axe instance (membres non partages, un exemplaire par objet).
         * N'altere pas currentVis (axe visibilite orthogonal, comme GLOBAL). */
        if (check(TOKEN_LOCAL)) {
            advance_token();
            inGlobalBlock = false;
            continue;
        }

        /*  : `implemente iX` enregistre le contrat. Le check
         * de conformite (signatures) est fait post-parse via
         * interface_cross_check_global(). */
        if (check(TOKEN_IMPLEMENTE)) {
            Token implKw = parser.current;
            advance_token(); /* consume IMPLEMENTE */
            if (check(TOKEN_IDENTIFIER)) {
                Token ifaceTok = parser.current;
                advance_token(); /* consume interface name */
                class_interface_register(className.start, className.length,
                                         ifaceTok.start, ifaceTok.length,
                                         implKw.line);
                /*  : inscrire le nom d'interface dans la table
                 * runtime de la classe (sommet de pile). Permet a
                 * `obj est iInterface` de resoudre Vrai au runtime. Le
                 * check de conformite des signatures reste compile-time
                 * via interface_cross_check_global() — non touche ici. */
                ConstIdx ifaceConst = identifier_constant(&ifaceTok);
                emit_const_op(OP_CLASS_DECLARE_INTERFACE, ifaceConst);
            }
            continue;
        }

        /*  : bloc CONSTANT dans body de Classe (canon 6010006
         * NOTE5). Deux syntaxes :
         *   CONSTANT K = 5                   ; ligne unique (IDENT sur meme ligne)
         *   CONSTANT                         ; bloc multi-constantes
         *      K = 5
         *      J = 10
         *   FIN
         * Toutes constantes sont PUBLIC par defaut (canon). Le storage
         * runtime reutilise ObjClass.staticFields (cf. ) ; on
         * marque en plus les noms dans g_class_constants pour rejeter
         * `cX.K = val` au compile-time.
         * Discrimination ligne-unique vs bloc : on lit l'IDENT suivant ; si
         * crossedNewline est true entre CONSTANT et l'IDENT, c'est un bloc
         * (termine par FIN), sinon une ligne unique. */
        if (check(TOKEN_CONSTANTE)) {
            advance_token(); /* consume CONSTANT */
            if (!check(TOKEN_IDENTIFIER)) {
                owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_CONST_NAME_IN_CLASS);
                continue;
            }
            bool isBlock = crossedNewline;
            do {
                Token constTok = parser.current;
                advance_token(); /* consume IDENT */
                consume(TOKEN_EQUAL, E_SYNTAX_EXP_EQUAL_CONST_NAME);
                expression(); /* push valeur initiale sur la pile */
                ConstIdx constNameConst = identifier_constant(&constTok);
                emit_const_op(OP_STATIC_FIELD, constNameConst);
                class_constant_register(className.start, className.length,
                                        constTok.start, constTok.length);
                /* Visibilite PUBLIC explicite (canon : constante toujours
                 * publique). Permet aux messages cross-check de citer la
                 * classe proprietaire. */
                class_field_vis_register(className.start, className.length,
                                         constTok.start, constTok.length,
                                         OWL_VIS_PUBLIC);
            } while (isBlock && check(TOKEN_IDENTIFIER));
            if (isBlock) {
                consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_CONSTANTE);
            }
            continue;
        }

        /*  : methode/constructeur/destructeur inline dans body class.
         * Canon 6010006 NOTE3_3 + NOTE6_2 : tout `PROCEDURE` declare au
         * sein du body class enregistre une methode de cette classe.
         * Syntaxe acceptee :
         *   PROCEDURE [<Acces>] [GLOBALE] [ABSTRAITE] <Nom>(<params>)
         *   PROCEDURE Constructeur(<params>)
         *   PROCEDURE Destructeur()
         * Visibilite : hierarchie 1. modificateur explicite sur PROCEDURE,
         * 2. bloc currentVis en cours (PUBLIC/PRIVE/PROTEGE), 3. defaut
         * PUBLIC. */
        if (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION)) {
            Token procKw = parser.current;
            advance_token(); /* consume PROCEDURE/FONCTION */

            /* Modificateur visibilite explicite (override du bloc en cours). */
            OwlVisibility procVis = currentVis;
            if (check(TOKEN_PRIVE)) {
                procVis = OWL_VIS_PRIVE;
                advance_token();
            } else if (check(TOKEN_PROTEGE)) {
                procVis = OWL_VIS_PROTEGE;
                advance_token();
            } else if (check(TOKEN_PUBLIC)) {
                procVis = OWL_VIS_PUBLIC;
                advance_token();
            }

            /* GLOBALE / GLOBAL (methode statique de classe). GLOBAL est la
             * forme anglaise canon (invariant bilingue) du modificateur,
             * a egalite stricte avec GLOBALE. */
            bool isGlobalMethod = false;
            if (check(TOKEN_GLOBALE) || check(TOKEN_GLOBAL)) {
                advance_token();
                isGlobalMethod = true;
            }

            /* ABSTRAITE (signature seule, redefinie en classe derivee). */
            bool isAbstractMethod = false;
            if (check(TOKEN_ABSTRAITE)) {
                advance_token();
                isAbstractMethod = true;
            }

            /* Constructeur inline : `PROCEDURE Constructeur(...)`. */
            if (check(TOKEN_CONSTRUCTEUR)) {
                advance_token(); /* consume Constructeur */
                Token methodName = procKw; /* placeholder, non utilise pour ctor */
                compile_inline_class_method(
                    INLINE_KIND_CONSTRUCTOR,
                    className, procKw, methodName,
                    procVis, false, false);
                continue;
            }

            /* Destructeur inline : `PROCEDURE Destructeur()`. Parentheses
             * obligatoires (canon strict). */
            if (check(TOKEN_DESTRUCTEUR)) {
                advance_token(); /* consume Destructeur */
                Token methodName = procKw;
                compile_inline_class_method(
                    INLINE_KIND_DESTRUCTOR,
                    className, procKw, methodName,
                    procVis, false, false);
                continue;
            }

            /* Methode normale : `PROCEDURE <Nom>(...)`. */
            if (!check(TOKEN_IDENTIFIER)) {
                /*  Cas 2 : nom de methode = mot reserve (TOKEN_ETAT,
                 * TOKEN_SIGNE, TOKEN_FENETRE, scalaires primitifs, control-flow,
                 * ...). Sans ce check, "Expected expr" generique au `(`, puis
                 * ~60 erreurs cascade (':membre' hors methode, 'moi' inconnu,
                 * `FIN` orphelin) parce que le parser repart en mode statement
                 * dans le body de la classe au lieu de scope methode.
                 * Symetrique du check existant pour les champs de classe
                 * (cf. ~L14444). Saut au FIN matching pour eviter la cascade. */
                if (tokentype_is_reserved_keyword(parser.current.type)
                    || parser.current.type == TOKEN_ETAT
                    || parser.current.type == TOKEN_FENETRE) {
                    char kwname[32];
                    keyword_canonical_uppercase_for(parser.current, kwname,
                                                     sizeof(kwname));
                    owl_emit_error_current(E_SEM_KEYWORD_AS_VAR_NAME,
                                           "name", kwname, NULL);
                    /* Skip tout le bloc PROCEDURE (signature + body) jusqu'au
                     * FIN matching, comme window_skip_nested_block. */
                    int depth = 1;
                    while (depth > 0 && !check(TOKEN_EOF)) {
                        if (!check(TOKEN_FIN)
                            && prescan_token_in_depth_table(parser.current.type)
                            && parser_depth_delta() > 0) {
                            depth++;
                            advance_token();
                        } else if (check(TOKEN_FIN)) {
                            depth--;
                            advance_token();
                        } else {
                            advance_token();
                        }
                    }
                    parser.panicMode = false;
                    continue;
                }
                owl_emit_error_current(E_SYNTAX_EXPECTED_EXPR);
                advance_token();
                continue;
            }
            Token methodName = parser.current;
            advance_token();
            compile_inline_class_method(
                INLINE_KIND_METHOD,
                className, procKw, methodName,
                procVis, isGlobalMethod, isAbstractMethod);
            continue;
        }

        if (check(TOKEN_HERITE)) {
            advance_token();
            match_token(TOKEN_DE);
            consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_SUPERCLASS_NAME);
            Token superName = parser.previous;
            class_super_register(className.start, className.length,
                                 superName.start, superName.length);
            named_variable(superName, false);
            emit_byte(OP_INHERIT);
        } else if (check(TOKEN_IDENTIFIER)) {
            advance_token();
            Token fieldName = parser.previous;

            if (check(TOKEN_EST)) {
                advance_token();
                /*  : consommer l'article EN `a`/`an` juste apres
                 * `is`/`est`, AVANT les pre-checks de type (singleton ~19093,
                 * TOKEN_CHAINE , TOKEN_TABLEAU ). Sans ca en
                 * EN l'article pollue ces peeks -> champ collection perd sa
                 * nature tableau dynamique (crash "No method Add"). Les
                 * articles FR sont deja gommes par le scanner en position
                 * d'article (scan_identifier).
                 * No-op si pas d'article. skip_type_spec() en aval reste
                 * inchange (sa propre consommation d'article devient no-op). */
                consume_en_a_an_filler();

                /*  — Structure imbriquee dans le corps de classe :
                 * parite avec la Fenetre (window_declaration, dispatch
                 * isUserType ~L25709). Semantique TYPE-PUR : le bloc
                 * `champ est une Structure ... FIN` enregistre un TYPE
                 * utilisable au niveau fichier (registre plat knownUserTypes,
                 * comme top-level/fenetre), PAS un membre d'instance
                 * first-class (aligne ). Une fois enregistre, un champ
                 * `autreChamp est un stMyStruc` et une variable locale de
                 * methode `stvStruc est un stMyStruc` se resolvent
                 * gratuitement. Contrairement a la fenetre (qui compile son
                 * body dans winTopCompiler et swap `current = current->enclosing`
                 * pour materialiser le type au niveau script), class_declaration
                 * opere DEJA dans le compiler script enclosing a scopeDepth 0
                 * (garde ~L19383) : aucun swap. Effet pile neutre de
                 * struct_declaration (push template __StructNew / define_variable
                 * qui le consomme) -> l'objet-classe sur la pile reste intact. */
                if (check(TOKEN_STRUCTURE)) {
                    advance_token();  /* consume STRUCTURE */
                    struct_declaration(fieldName);
                    continue;
                }

                /*  — Enumeration / Combinaison imbriquees : complement
                 * de  (Structure), meme doctrine TYPE-PUR et meme point
                 * d'insertion. Parite Fenetre (window_declaration dispatch
                 * isUserType ~L25739) et top-level (~L15351). Comme
                 * struct_declaration, enum_declaration/combination_declaration
                 * sont neutres sur la pile a scopeDepth 0 (OP_CLASS push ->
                 * define_variable pop dans le global -> OP_GET_GLOBAL re-push
                 * pour les OP_ENUM_VALUE -> OP_POP final) : l'objet-classe en
                 * cours reste intact. class_declaration opere deja dans le
                 * compiler script enclosing a scopeDepth 0 (garde ~L19383) :
                 * aucun swap `current = current->enclosing` necessaire,
                 * contrairement a la fenetre. */
                if (check(TOKEN_ENUMERATION)) {
                    advance_token();  /* consume ENUMERATION */
                    enum_declaration(fieldName);
                    continue;
                }

                if (check(TOKEN_COMBINAISON)) {
                    advance_token();  /* consume COMBINAISON */
                    combination_declaration(fieldName);
                    continue;
                }

                if (inGlobalBlock) {
                    /*  : membre GLOBAL — stocke dans
                     * klass->staticFields (PAS dans defaults, donc non copie
                     * dans les instances). Detection singleton : si le type
                     * declare = classe en cours, allouer instance immediate. */
                    ConstIdx fieldNameConst = identifier_constant(&fieldName);

                    /* Peek le 1er token du type pour detecter le singleton. */
                    bool isSingleton = false;
                    if (check(TOKEN_IDENTIFIER) &&
                        parser.current.length == className.length &&
                        strncasecmp(parser.current.start, className.start,
                                    (size_t)className.length) == 0) {
                        isSingleton = true;
                    }
                    skip_type_spec();

                    if (match_token(TOKEN_EQUAL)) {
                        /* Membre global avec valeur initiale literale. */
                        expression();
                        emit_const_op(OP_STATIC_FIELD, fieldNameConst);
                    } else if (isSingleton) {
                        /* Singleton differé : on collecte le nom, allocation
                         * emise juste avant OP_POP final (voir bas de la
                         * fonction). On ne pousse rien sur la pile maintenant. */
                        if (pendingSingletonCount < MAX_SINGLETONS_PER_CLASS) {
                            pendingSingletons[pendingSingletonCount++] = fieldNameConst;
                        } else {
                            owl_emit_error_at(&parser.previous, E_SYNTAX_TOO_MANY_SINGLETONS);
                        }
                    } else {
                        /* Membre global sans valeur initiale : default Nil. */
                        emit_byte(OP_NIL);
                        emit_const_op(OP_STATIC_FIELD, fieldNameConst);
                    }
                } else {
                    /* Field d'instance classique. */
                    /*  : warning compile-time si le champ shadow un
                     * homonyme deja declare par un ancetre dans la chaine
                     * d'heritage. Le comportement runtime reste un override
                     * (valeur de l'enfant gagne), mais on signale l'intention
                     * probable d'erreur. Le check doit etre fait AVANT
                     * class_field_vis_register, sinon le lookup trouve la
                     * classe courante (qu'on vient d'inscrire) au lieu de
                     * l'ancetre. On cherche directement dans le super et au-dela
                     * via la version "inherited" qui suit g_class_super. */
                    if (g_class_super_count > 0) {
                        const char* superName = NULL;
                        int superLen = 0;
                        for (int i = 0; i < g_class_super_count; i++) {
                            ClassSuperEntry* e = &g_class_super[i];
                            if (e->classLen == className.length &&
                                strncasecmp(e->className, className.start,
                                            (size_t)className.length) == 0) {
                                superName = e->superName;
                                superLen  = e->superLen;
                                break;
                            }
                        }
                        if (superName && superLen > 0) {
                            const char* ownerStart = NULL;
                            int ownerLen = 0;
                            int v = class_field_vis_lookup_inherited(
                                superName, superLen,
                                fieldName.start, fieldName.length,
                                &ownerStart, &ownerLen);
                            if (v >= 0 && ownerStart && ownerLen > 0) {
                                char fBuf[128], cBuf[128], pBuf[128];
                                int fl = fieldName.length < 127 ? fieldName.length : 127;
                                int cl = className.length < 127 ? className.length : 127;
                                int pl = ownerLen < 127 ? ownerLen : 127;
                                memcpy(fBuf, fieldName.start, (size_t)fl); fBuf[fl] = '\0';
                                memcpy(cBuf, className.start, (size_t)cl); cBuf[cl] = '\0';
                                memcpy(pBuf, ownerStart, (size_t)pl); pBuf[pl] = '\0';
                                owl_emit_warning_at(&fieldName,
                                    W_SEM_FIELD_SHADOWS_INHERITED,
                                    "field", fBuf,
                                    "class", cBuf,
                                    "parent", pBuf,
                                    NULL);
                            }
                        }
                    }
                    /* Track field visibility (per-class + persistant cross-file).
                     * Ne touche pas user_type_add_field ( : pas de
                     * propriétés first-class — on ne réifie pas le type du field
                     * dans knownUserTypes pour les CLASSE, on stocke uniquement
                     * la visibilité dans la table dédiée). */
                    class_field_vis_register(className.start, className.length,
                                             fieldName.start, fieldName.length,
                                             currentVis);
                    /*  — capture le type déclaré (avant skip_type_spec
                     * qui le consomme) pour la coercition multilingue au
                     * stockage sur `:champ = ...`. Seul TOKEN_CHAINE nu nous
                     * intéresse (aplatissement) ; les autres types restent -1. */
                    if (check(TOKEN_CHAINE)) {
                        class_field_type_set(className.start, className.length,
                                             fieldName.start, fieldName.length,
                                             TOKEN_CHAINE);
                    }
                    ConstIdx fieldNameConst = identifier_constant(&fieldName);
                    /*  : un champ `tableau de X` doit etre un tableau
                     * vide utilisable des l'instanciation (Ajoute/Taille/POUR
                     * TOUT), comme un tableau local. Sans default explicite, le
                     * champ resterait absent de klass->defaults donc Nil a
                     * l'instanciation. On detecte le type tableau AVANT le skip
                     * (qui le consomme) et, si aucun `= <expr>` ne suit, on pose
                     * un OP_ARRAY vide comme default. */
                    /*  : un champ `tableau associatif de X` doit, comme
                     * le tableau dynamique, etre vide-mais-utilisable des
                     * l'instanciation. On le detecte AVANT skip_type_spec (qui
                     * ne connait pas TOKEN_ASSOCIATIF) et on consomme la spec
                     * assoc nous-memes ; sinon le chemin skip_type_spec normal
                     * prend le relais. */
                    int fieldAssocVK = 0;
                    Token fieldAssocValueType;      /*  */
                    fieldAssocValueType.start = NULL;
                    fieldAssocValueType.length = 0;
                    bool fieldIsAssoc =
                        try_consume_assoc_array_field_type(&fieldAssocVK,
                                                           &fieldAssocValueType);
                    bool fieldIsArray = !fieldIsAssoc && check(TOKEN_TABLEAU);
                    /*  : capture le token de type AVANT skip_type_spec
                     * (qui le consomme) pour detecter un champ type par une
                     * STRUCTURE connue — imbriquee dans la classe
                     * ou top-level voisine (registre plat knownUserTypes). Comme
                     * les champs tableau/assoc, un tel champ doit etre auto-init
                     * a une instance fraiche des la construction, sinon il reste
                     * Null et `:champ.sousChamp = ...` echoue (« Acces champ sur
                     * Null »). On ne traite QUE les structures : classe (type
                     * reference, reste Null intentionnellement) et enum/combi
                     * sont hors scope. */
                    Token fieldTypeTok = parser.current;
                    bool fieldIsUserStruct =
                        !fieldIsAssoc && !fieldIsArray &&
                        fieldTypeTok.type == TOKEN_IDENTIFIER &&
                        type_name_is_structure(fieldTypeTok.start,
                                               fieldTypeTok.length);
                    if (!fieldIsAssoc) skip_type_spec();
                    if (match_token(TOKEN_EQUAL)) {
                        /*  : valeur par defaut d'un champ d'instance.
                         * On stocke dans klass->defaults via OP_ENUM_VALUE
                         * (meme stockage que CONSTANT — voir vm.c OP_ENUM_VALUE).
                         * A l'instanciation, OBJ_CLASS recopie klass->defaults
                         * (chaine d'heritage incluse) dans instance->fields. */
                        expression();
                        emit_const_op(OP_ENUM_VALUE, fieldNameConst);
                    } else if (fieldIsArray) {
                        emit_byte(OP_ARRAY);
                        emit_const_op(OP_ENUM_VALUE, fieldNameConst);
                    } else if (fieldIsAssoc) {
                        emit_empty_assoc_array(fieldAssocVK, &fieldAssocValueType);
                        emit_const_op(OP_ENUM_VALUE, fieldNameConst);
                    } else if (fieldIsUserStruct) {
                        /* Default = instance fraiche via __StructClone(<type>),
                         * stockee dans klass->defaults (OP_ENUM_VALUE). Elle est
                         * deep-clonee par instance a la construction
                         * (instance_copy_defaults, vm.c) : pas de partage entre
                         * instances. Miroir du path user-struct de
                         * struct_declaration (auto-init de sous-structure). */
                        Token cloneName;
                        cloneName.start = "__StructClone";
                        cloneName.length = 13;
                        cloneName.type = TOKEN_IDENTIFIER;
                        cloneName.line = parser.previous.line;
                        cloneName.column = 0;
                        ConstIdx cloneConst = identifier_constant(&cloneName);
                        emit_const_op(OP_GET_GLOBAL, cloneConst);
                        ConstIdx typeNameConst = identifier_constant(&fieldTypeTok);
                        emit_get_type_global(fieldTypeTok.start,
                                             fieldTypeTok.length, typeNameConst);
                        emit_bytes(OP_CALL, 1);
                        emit_const_op(OP_ENUM_VALUE, fieldNameConst);
                    }
                }
            } else {
                owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EST_AFTER_CLASS_FIELD);
            }
        } else if (tokentype_is_reserved_keyword(parser.current.type)) {
            /*  : nom de champ de classe ne peut pas etre un mot-cle
             * reserve. Note : TOKEN_PROCEDURE / TOKEN_FONCTION / TOKEN_HERITE /
             * TOKEN_PUBLIC / TOKEN_PRIVE / TOKEN_PROTEGE / TOKEN_GLOBAL /
             * TOKEN_IMPLEMENTE sont deja consommes plus haut comme directives
             * legitimes — on n'arrive ici que pour les keywords fautifs en
             * position de nom de champ (`chaine est une chaîne`, etc.). */
            char kwname[32];
            keyword_canonical_uppercase_for(parser.current, kwname, sizeof(kwname));
            owl_emit_error_current(E_SEM_KEYWORD_AS_VAR_NAME, "name", kwname, NULL);
            /* Skip jusqu'a la fin de la ligne logique. */
            while (parser.current.type != TOKEN_FIN &&
                   parser.current.type != TOKEN_EOF &&
                   parser.current.type != TOKEN_NEWLINE) {
                advance_token();
            }
            if (parser.current.type == TOKEN_NEWLINE) advance_token();
        } else {
            owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_MEMBER_DECL_IN_CLASS);
            advance_token();
        }
    }

    /*  : emission des singletons en attente. La classe en cours est
     * sur la pile (sommet). Pour chaque singleton : push classe-callee via
     * OP_GET_GLOBAL, OP_CALL 0 → instance, OP_STATIC_FIELD pose dans
     * staticFields. Stack apres : classe (toujours). */
    for (int i = 0; i < pendingSingletonCount; i++) {
        emit_const_op(OP_GET_GLOBAL, nameConst); /* push callee = la classe */
        emit_bytes(OP_CALL, 0);               /* -> instance */
        emit_const_op(OP_STATIC_FIELD, pendingSingletons[i]);
    }

    emit_byte(OP_POP); /* pop the class */

    currentClass = classCompiler.enclosing;
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_CLASSE);
}

/* ================================================================
 * PROCEDURE / METHOD DECLARATION
 * ================================================================ */

/*  — Pilier 2 : un parametre de PROCEDURE/FONCTION sans type
 * explicite (`est un/une` FR, `is a/an` EN) serait un Variant de facto,
 * ce que le langage interdit. Emet l'erreur, pointee sur le nom du
 * parametre. Appele apres la tentative de lecture de type : `typeSeen`
 * vaut vrai si une copule `est`/`is` a ete consommee. Ne fait rien si le
 * "nom" n'est pas un identifiant (cas mot-cle deja diagnostique). */
static void reject_untyped_param(const Token* paramName, bool typeSeen) {
    if (typeSeen) return;
    if (paramName->type != TOKEN_IDENTIFIER) return;
    char nameBuf[128];
    snprintf(nameBuf, sizeof(nameBuf), "%.*s",
             paramName->length, paramName->start);
    owl_emit_error_at(paramName, E_SEM_PARAM_TYPE_REQUIRED,
                      "name", nameBuf, NULL);
}

static void proc_declaration(void) {
    /* Token PROCEDURE/FONCTION qui vient d'être consommé par l'appelant ;
     * sert d'ancre line/column pour les erreurs portant sur la déclaration
     * entière (ex. méthode dup, cf. ). */
    Token procKeyword = parser.previous;

    /*  : la syntaxe destructeur externe `PROCEDURE Destructeur cClass()`
     * (ou `PROCEDURE ~cClass()`) au top-level est supprimee. Le destructeur
     * doit etre declare inline dans le body de la classe via
     * `PROCEDURE Destructeur()`. Rejet explicite avec suggestion. */
    if (check(TOKEN_TILDE) || check(TOKEN_DESTRUCTEUR)) {
        advance_token(); /* consume ~ or Destructeur */
        if (check(TOKEN_IDENTIFIER)) {
            Token className = parser.current;
            char classBuf[128];
            int cl = className.length < (int)sizeof(classBuf) - 1
                     ? className.length : (int)sizeof(classBuf) - 1;
            memcpy(classBuf, className.start, (size_t)cl); classBuf[cl] = '\0';
            owl_emit_error_at(&procKeyword, E_SEM_DESTRUCTEUR_EXTERNE_SUPPRIME,
                              "class", classBuf,
                              NULL);
            advance_token(); /* consume class IDENT */
        } else {
            owl_emit_error_at(&procKeyword, E_SEM_DESTRUCTEUR_EXTERNE_SUPPRIME,
                              "class", "?",
                              NULL);
        }
        /* Skip optional ( ... ) header + body jusqu'au FIN equilibre. */
        if (check(TOKEN_LEFT_PAREN)) {
            int parenDepth = 0;
            do {
                if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                advance_token();
            } while (parenDepth > 0 && !check(TOKEN_EOF));
        }
        exception_skip_to_matching_fin();
        if (check(TOKEN_FIN)) advance_token();
        return;
    }

    /*  : capture visibilite optionnelle PROCEDURE [PRIVE|PROTEGE|PUBLIC].
     * Canon 6010006 NOTE6_3 : `PROCEDURE [<Acces>] [Globale] [VIRTUELLE]
     * [ABSTRAITE] <Nom>(...)`. Scanner accepte prive/privee/private →
     * TOKEN_PRIVE. Captured ici, enregistree plus bas via
     * method_visibility_register selon le chemin classe/top-level. */
    OwlVisibility procVis = OWL_VIS_PUBLIC;
    Token visToken = parser.current; /* fallback line/col pour rejet PROTEGEE top-level */
    bool  visExplicit = false;
    if (check(TOKEN_PRIVE)) {
        procVis = OWL_VIS_PRIVE;
        visToken = parser.current;
        visExplicit = true;
        advance_token();
    } else if (check(TOKEN_PROTEGE)) {
        procVis = OWL_VIS_PROTEGE;
        visToken = parser.current;
        visExplicit = true;
        advance_token();
    } else if (check(TOKEN_PUBLIC)) {
        visToken = parser.current;
        visExplicit = true;
        advance_token();
    }
    (void)visExplicit;

    /*  : modificateur optionnel GLOBALE apres PROCEDURE [<vis>].
     * Canon 6010006 NOTE6_3 : methode globale (statique). En top-level
     * GLOBALE n'a de sens qu'avec l'ancienne syntaxe externe `cClass.M`
     * (rejetee ). On consomme le token pour produire ensuite un
     * rejet sur `.` ou nom de classe, sinon erreur de pattern. GLOBAL
     * (forme anglaise canon) accepte a egalite avec GLOBALE. */
    if (check(TOKEN_GLOBALE) || check(TOKEN_GLOBAL)) {
        advance_token();
    }

    /*  : modificateur optionnel ABSTRAITE apres PROCEDURE [<vis>].
     * Canon 6010006 NOTE6_3 : `PROCEDURE [<Acces>] [Globale] [VIRTUELLE]
     * [ABSTRAITE] <Nom>(...)`. Methode abstraite = signature sans corps,
     * doit etre redefinie dans les classes derivees non-abstraites. */
    bool isAbstractMethod = false;
    if (check(TOKEN_ABSTRAITE)) {
        advance_token();
        isAbstractMethod = true;
    }

    if (check(TOKEN_IDENTIFIER)) {
        /* Détection typo sur modificateur de visibilité : la séquence
         * `PROCEDURE <IDENT> <IDENT> (` est presque toujours un mot mal
         * orthographié à la place de PRIVÉE / PUBLIC / PROTÉGÉE.
         * On peek 2 tokens et on émet une erreur ciblée AVANT de consommer
         * l'IDENT comme nom de fonction (qui produirait un message d'erreur
         * trompeur sur la suite). */
        Scanner saved     = parser.scanner;
        Token   savedCur  = parser.current;
        Token   savedPrev = parser.previous;
        bool    savedXNL  = crossedNewline;
        advance_token();  /* skip first IDENT */
        bool typoPattern = check(TOKEN_IDENTIFIER);
        if (typoPattern) {
            advance_token();  /* skip second IDENT */
            typoPattern = check(TOKEN_LEFT_PAREN);
        }
        parser.scanner   = saved;
        parser.current   = savedCur;
        parser.previous  = savedPrev;
        crossedNewline   = savedXNL;
        if (typoPattern) {
            char nameZ[128];
            int nz = parser.current.length < (int)sizeof(nameZ) - 1
                     ? parser.current.length : (int)sizeof(nameZ) - 1;
            memcpy(nameZ, parser.current.start, (size_t)nz);
            nameZ[nz] = '\0';
            owl_emit_error_current(E_SEM_UNKNOWN_VISIBILITY_MODIFIER,
                                   "name", nameZ,
                                   NULL);
            advance_token();  /* consomme le mot fautif pour continuer parsing */
        }
    }

    consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_PROC_NAME);
    Token funcName = parser.previous;

    /*  : ABSTRAITE ne s'applique qu'aux methodes externes de classe
     * (forme `PROCEDURE ABSTRAITE cClass.Method(...)`). Sur une procedure
     * top-level c'est une erreur (pas de sens canon). */
    if (isAbstractMethod && !check(TOKEN_DOT)) {
        owl_emit_error_at(&funcName, E_SEM_ABSTRAITE_OUTSIDE_CLASS_METHOD);
    }

    /*  : la syntaxe methode externe `PROCEDURE cClass.M(...)` au
     * top-level est supprimee. La methode doit etre declaree inline dans
     * le body de la classe. Rejet explicite avec suggestion ; on skip
     * ensuite le bloc jusqu'au FIN equilibre pour ne pas cascader. */
    if (check(TOKEN_DOT)) {
        advance_token(); /* consume '.' */
        Token methodName = parser.current;
        if (check(TOKEN_IDENTIFIER)) advance_token();
        Token className = funcName;
        char methodBuf[128];
        char classBuf[128];
        int ml = methodName.length < (int)sizeof(methodBuf) - 1
                 ? methodName.length : (int)sizeof(methodBuf) - 1;
        int cl = className.length < (int)sizeof(classBuf) - 1
                 ? className.length : (int)sizeof(classBuf) - 1;
        memcpy(methodBuf, methodName.start, (size_t)ml); methodBuf[ml] = '\0';
        memcpy(classBuf, className.start, (size_t)cl); classBuf[cl] = '\0';
        owl_emit_error_at(&procKeyword, E_SEM_METHODE_EXTERNE_SUPPRIMEE,
                          "class", classBuf,
                          "method", methodBuf,
                          NULL);
        /* Skip header `(...)` + optional `:returnType` + body jusqu'au FIN.
         * Cas ABSTRAITE : pas de body / FIN — l'exception_skip_to_matching_fin
         * boucle jusqu'a EOF si pas de FIN, donc on doit detecter le pattern
         * ABSTRAITE pour s'arreter apres `)`. */
        if (check(TOKEN_LEFT_PAREN)) {
            int parenDepth = 0;
            do {
                if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                advance_token();
            } while (parenDepth > 0 && !check(TOKEN_EOF));
        }
        if (is_return_type_colon()) {
            advance_token();
            skip_type_spec();
        }
        if (!isAbstractMethod) {
            exception_skip_to_matching_fin();
            if (check(TOKEN_FIN)) advance_token();
        }
        return;
    }

    /*  : la syntaxe constructeur externe `PROCEDURE cClass(args)`
     * au top-level est supprimee. Le constructeur doit etre declare inline
     * dans le body de la classe via `PROCEDURE Constructeur(...)`. Rejet
     * explicite avec suggestion. */
    if (is_known_class(funcName.start, funcName.length)) {
        Token className = funcName;
        char classBuf[128];
        int cl = className.length < (int)sizeof(classBuf) - 1
                 ? className.length : (int)sizeof(classBuf) - 1;
        memcpy(classBuf, className.start, (size_t)cl); classBuf[cl] = '\0';
        owl_emit_error_at(&procKeyword, E_SEM_CONSTRUCTEUR_EXTERNE_SUPPRIME,
                          "class", classBuf,
                          NULL);
        /* Skip header + body. */
        if (check(TOKEN_LEFT_PAREN)) {
            int parenDepth = 0;
            do {
                if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                advance_token();
            } while (parenDepth > 0 && !check(TOKEN_EOF));
        }
        exception_skip_to_matching_fin();
        if (check(TOKEN_FIN)) advance_token();
        return;
    }

    /* Regular procedure/function */
    {
        /*  : PROTEGEE n'a aucun sens pour une procedure top-level
         * (pas de chaine d'heritage hors classe). Rejet a la declaration. */
        if (procVis == OWL_VIS_PROTEGE) {
            owl_emit_error_at(&visToken, E_SEM_PROTEGEE_OUTSIDE_CLASS);
        }

        /*  — procedure membre d'une CollectionDeProcédures : stockage
         * mangled `<COL>$<Proc>` (slot distinct par collection) + enregistrement
         * EXPOSE. On mangle le NOM DE GLOBAL (identifier_constant / declare /
         * define / user_proc) mais on garde le nom NU pour ObjFunction->name :
         * le hook de teardown Terminaison()/Termination() se capture par ce nom
         * (companion_termination_hook), et les traces restent lisibles. */
        Token bareFuncName = funcName;
        static char collProcBuf[256];
        /*  — cette procedure est-elle un membre DIRECT d'une collection
         * (top-level du corps de collection) ? Si oui, son corps ne peut pas
         * contenir de PROCEDURE/FONCTION imbriquee : en rencontrer une signale
         * que CE membre n'a pas ferme son FIN (voir la boucle de corps + le
         * consume FIN plus bas, recovery nominative). */
        bool isCollectionMember =
            (current->scopeDepth == 0 && g_current_collection_name[0] != '\0');
        char collNameForRecovery[64] = {0};
        if (isCollectionMember) {
            int cn = (int)strlen(g_current_collection_name);
            if (cn >= (int)sizeof(collNameForRecovery)) cn = (int)sizeof(collNameForRecovery) - 1;
            memcpy(collNameForRecovery, g_current_collection_name, (size_t)cn);
            collNameForRecovery[cn] = '\0';
        }
        if (isCollectionMember) {
            collection_member_register(g_current_collection_name,
                                       (int)strlen(g_current_collection_name),
                                       funcName.start, funcName.length, true);
            int pn = collection_var_prefix(g_current_collection_name,
                                           funcName.start, funcName.length,
                                           collProcBuf, sizeof(collProcBuf));
            if (pn > 0) {
                funcName.start  = collProcBuf;
                funcName.length = pn;
            }
        }

        ConstIdx global = identifier_constant(&funcName);
        /*  — signale a declare_variable qu'on declare une PROCEDURE,
         * pour qu'une collision de nom au top-level emette le message dedie
         * "procedure" et non "variable". */
        g_declaring_procedure = true;
        declare_variable(&funcName);
        g_declaring_procedure = false;
        global_track_mark_used(funcName.start, funcName.length);
        /*  — marque ce global comme procedure pour qu'une declaration
         * ulterieure de meme nom (variable ou procedure) herite du message. */
        global_track_mark_procedure(funcName.start, funcName.length);

        /* V1.7-1 : register la PROCEDURE pour le tracking des types params. */
        UserProcInfo* userProc = user_proc_register(funcName.start, funcName.length);

        /*  : enregistre la visibilite (className="" = top-level).
         * fileIdx capture pour permettre le check cross-file PRIVE
         * (deja effectue par prescan + check 5550, on enregistre quand
         * meme pour exhaustivite et debug). */
        method_visibility_register(
            "", 0,
            funcName.start, funcName.length,
            procVis, funcName.line, currentFileIndex);

        Compiler compiler;
        init_compiler(&compiler, TYPE_FUNCTION);
        begin_scope();
        current->function->name = obj_copy_string(bareFuncName.start,
                                                  bareFuncName.length);

        consume(TOKEN_LEFT_PAREN, E_SYNTAX_EXPECTED_LPAREN_AFTER_PROC_NAME);
        uint8_t localParamSlots[256];
        int localParamCount = 0;
        Value defaults[255];
        int defaultCount = 0;
        int minArity = 0;
        if (!check(TOKEN_RIGHT_PAREN)) {
            do {
                current->function->arity++;
                if (current->function->arity > 255) {
                    owl_emit_error_current(E_SYNTAX_TOO_MANY_PARAMETERS);
                }
                bool isLocalParam = match_token(TOKEN_LOCAL);
                if (reject_keyword_as_param_name()) advance_token();
                else consume(TOKEN_IDENTIFIER, E_SYNTAX_EXPECTED_PARAM_NAME);
                Token paramName = parser.previous;
                declare_variable(&paramName);
                if (isLocalParam) {
                    localParamSlots[localParamCount++] = (uint8_t)(current->localCount - 1);
                }
                /* V1.7-1 : capturer le nom du type pour le tracking. */
                const char* capturedType = NULL;
                int capturedTypeLen = 0;
                if (match_token(TOKEN_EST)) {
                    /*  /  — valide le nom de type du parametre
                     * au meme titre qu'une declaration de variable, HEAD
                     * scalaire (`x est un Montan`) ET element de collection
                     * (`t est un tableau de Zorglub`). skip_type_spec_ex se
                     * charge de l'enregistrement (record_pending_type_ref pour
                     * le scalaire, record_collection_elem_type_ref pour
                     * l'element apres `de`) ; les primitifs ne sont jamais
                     * rejetes. On lit parser.previous apres pour le tracking
                     * du type (le dernier token de type consomme). */
                    /*  — capture le PREMIER token de type (avant skip)
                     * pour distinguer un type scalaire `p est un Couleur` d'un
                     * `p est un tableau de Couleur` : dans le second, le dernier
                     * token consomme est aussi "Couleur" (element), mais le
                     * receveur n'est PAS une structure Couleur. */
                    Token firstTypeTok = parser.current;
                    skip_type_spec_ex(true, false);
                    capturedType = parser.previous.start;
                    capturedTypeLen = parser.previous.length;
                    /*  — un parametre typé sur un type UTILISATEUR
                     * (structure homonyme d'un type registry comprise) doit
                     * resoudre son type comme une variable locale : sans
                     * structTypeName sur le slot, la resolution de recepteur
                     * (recvType) reste muette et `p..Rouge` ne serait pas
                     * refuse, alors que la meme forme l'est sur une variable
                     * simple. Limite aux types user declares : un param sur un
                     * type registry pur garde la resolution laxe historique
                     * (aucune validation `..prop` sur param aujourd'hui, hors
                     * scope de ce ticket). On ne pose le type que pour un nom
                     * SIMPLE : le premier ET le dernier token de type sont le
                     * meme (ecarte `tableau de X`, `de X`...). */
                    if (capturedType != NULL && capturedTypeLen > 0
                        && firstTypeTok.start == capturedType
                        && current->localCount > 0
                        && is_known_user_type(capturedType, capturedTypeLen)) {
                        Local* lc = &current->locals[current->localCount - 1];
                        if (lc->structTypeName[0] == '\0') {
                            int n = capturedTypeLen < 63 ? capturedTypeLen : 63;
                            memcpy(lc->structTypeName, capturedType, (size_t)n);
                            lc->structTypeName[n] = '\0';
                        }
                    }
                }
                if (userProc) {
                    user_proc_add_param_type(userProc, capturedType, capturedTypeLen);
                }
                /*  — attribut de declaration <utile>/<useful> pose apres
                 * le type d'un parametre : meme mecanisme que les locals/globals
                 * (parse_nullability_marker_ex + record_suppress_unused), pas de
                 * chemin de parse duplique. Le parametre marque est exempte de
                 * W_SEM_VAR_UNUSED. Les autres sorties du marqueur (nullable /
                 * indetectable) n'ont pas de support sur un slot de parametre :
                 * elles sont consommees puis ignorees ici. */
                {
                    bool pUndetectable = false;
                    bool pSuppressUnused = false;
                    (void)parse_nullability_marker_ex(&pUndetectable, &pSuppressUnused);
                    if (pSuppressUnused) {
                        record_suppress_unused(paramName);
                    }
                }
                reject_untyped_param(&paramName, capturedType != NULL);
                /* Optional default value: "= <literal>". Once a param has a
                 * default, all subsequent params must also have one (parity
                 * rule). */
                if (match_token(TOKEN_EQUAL)) {
                    Value v;
                    if (parse_default_literal(&v)) {
                        defaults[defaultCount++] = v;
                        if (current->localCount > 0)
                            current->locals[current->localCount - 1].hasInitializer = true;
                    }
                } else {
                    if (defaultCount > 0) {
                        owl_emit_error_at(&parser.previous, E_SEM_REQUIRED_PARAM_AFTER_DEFAULT);
                    }
                    minArity = current->function->arity;
                }
            } while (match_token(TOKEN_COMMA));
        }
        consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_PARAMS);
        current->function->minArity = minArity;
        if (defaultCount > 0) {
            current->function->defaults = (Value*)malloc(sizeof(Value) * defaultCount);
            for (int di = 0; di < defaultCount; di++) {
                current->function->defaults[di] = defaults[di];
            }
            current->function->defaultCount = defaultCount;
        }

        if (is_return_type_colon()) {
            advance_token(); /* consume ':' */
            skip_type_spec();
        }

        /* LOCAL params: deep-clone each so the function can mutate the local
         * copy without affecting the caller's value. */
        for (int li = 0; li < localParamCount; li++) {
            uint8_t slot = localParamSlots[li];
            emit_bytes(OP_GET_LOCAL, slot);
            emit_byte(OP_DEEP_COPY);
            emit_bytes(OP_SET_LOCAL, slot);
            emit_byte(OP_POP);
        }

        while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
            /*  — un membre de collection ne peut pas nicher de
             * PROCEDURE/FONCTION : en rencontrer une signifie que CE membre n'a
             * pas ferme son FIN. On stoppe le corps ici pour rendre la
             * PROCEDURE suivante a la boucle du corps de collection (qui la
             * reenregistre comme membre a scopeDepth 0), evitant la cascade de
             * membres perdus. Le diagnostic est emis apres end_compiler. */
            if (isCollectionMember &&
                (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION))) {
                break;
            }
            declaration();
        }

        ObjFunction* function = end_compiler();

        /* Les instructions de DEFINITION de la procedure (OP_CONSTANT +
         * DEFINE_GLOBAL) vivent dans le chunk SCRIPT. emit_byte() etiquette
         * chaque octet avec parser.previous.line — or ici parser.previous est
         * le DERNIER token du corps, donc ces instructions du script
         * heriteraient d'une ligne DU CORPS de la procedure. Conséquence
         * debug : un breakpoint sur une ligne de corps taperait
         * pendant la definition (frame script, pas de locals) au lieu de
         * l'execution (frame de la procedure). On ancre sur la ligne de
         * declaration. */
        Token savedPrev = parser.previous;
        parser.previous = procKeyword;

        emit_const_op(OP_CONSTANT, make_constant(OBJ_VAL(function)));
        define_variable(global);

        parser.previous = savedPrev;

        /*  — recovery FIN manquant sur un membre de collection : si le
         * corps s'est arrete sur une PROCEDURE/FONCTION suivante (pas sur un
         * FIN), CE membre n'a jamais ete ferme. Diagnostic nominatif pose sur la
         * declaration non fermee (procKeyword), puis on NE consomme PAS de FIN :
         * le token courant (la PROCEDURE suivante, ou le FIN de la collection)
         * est rendu au corps de collection pour un parse propre — pas de
         * cascade de « procedure inconnue » ni de faux « FIN attendu ». */
        if (isCollectionMember && !check(TOKEN_FIN)) {
            char procNameBuf[128];
            int pn = bareFuncName.length < (int)sizeof(procNameBuf) - 1
                     ? bareFuncName.length : (int)sizeof(procNameBuf) - 1;
            memcpy(procNameBuf, bareFuncName.start, (size_t)pn);
            procNameBuf[pn] = '\0';
            owl_emit_error_at(&procKeyword, E_SYNTAX_FIN_MANQUANT_PROC_COLLECTION,
                              "proc", procNameBuf,
                              "collection", collNameForRecovery,
                              NULL);
            parser.panicMode = false;
        } else {
            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROCEDURE);
        }
    }
}

/* ============================================================================
 * DSL Fenetre v1 — parsing top-level "Fenetre FEN_X ... FIN"
 *
 * Structure cible : OwlWindowDecl (cf. ui_decl.h).
 * Phase actuelle : B.0 — squelette qui parse le nom + saute le body
 * jusqu'au FIN matching, en emettant une erreur claire pour signaler
 * que l'implementation est en cours.
 * ============================================================================ */

/* Parse un literal constant simple (entier, reel, chaine sans interpolation,
 * Vrai/Faux/Null). Renvoie true si le current token a ete consume et que
 * out_value est rempli. Renvoie false sinon (et ne consume rien).
 *
 * Pour B.2 on reste minimaliste : pas d'expressions composees, pas
 * d'echappements dans les chaines, pas de constantes nommees. Les cas
 * plus riches seront supportes en B.5+ (compile en ObjFunction d'eval). */
/* Parse un atome const-foldable (entier brut, reel, chaine, bool, ref de
 * constante, appel de native pure). Pas de chaining +/- entre atomes. */
static bool window_try_parse_const_atom(Value* out_value) {
    /* Unary minus devant un literal numerique (entier ou reel). */
    if (check(TOKEN_MINUS)) {
        advance_token();
        if (!window_try_parse_const_atom(out_value)) return false;
        if (IS_INTEGER(*out_value)) {
            *out_value = INTEGER_VAL(-AS_INTEGER(*out_value));
            return true;
        }
        if (IS_REAL(*out_value)) {
            *out_value = REAL_VAL(-AS_REAL(*out_value));
            return true;
        }
        return false;
    }
    /* Entier brut. */
    if (check(TOKEN_INTEGER)) {
        Token t = parser.current;
        int64_t v = 0;
        for (int i = 0; i < t.length; i++) {
            char c = t.start[i];
            if (c == '_' || c == ' ') continue;
            if (c == 'x' || c == 'X') {
                v = 0;
                for (int j = i + 1; j < t.length; j++) {
                    char d = t.start[j];
                    if (d == '_') continue;
                    v *= 16;
                    if (d >= '0' && d <= '9') v += d - '0';
                    else if (d >= 'a' && d <= 'f') v += d - 'a' + 10;
                    else if (d >= 'A' && d <= 'F') v += d - 'A' + 10;
                }
                break;
            }
            v = v * 10 + (c - '0');
        }
        *out_value = INTEGER_VAL(v);
        advance_token();
        return true;
    }
    /* Reel. */
    if (check(TOKEN_REAL)) {
        Token t = parser.current;
        char buf[64];
        int n = t.length < 63 ? t.length : 63;
        memcpy(buf, t.start, (size_t)n);
        buf[n] = '\0';
        *out_value = REAL_VAL(strtod(buf, NULL));
        advance_token();
        return true;
    }
    /* Chaine non interpolee (TOKEN_STRING). */
    if (check(TOKEN_STRING)) {
        Token t = parser.current;
        *out_value = OBJ_VAL(string_literal_value_from_token(t));
        advance_token();
        return true;
    }
    /* Booleens. */
    if (check(TOKEN_VRAI))  { *out_value = BOOL_VAL(true);  advance_token(); return true; }
    if (check(TOKEN_FAUX))  { *out_value = BOOL_VAL(false); advance_token(); return true; }
    if (check(TOKEN_NUL))   { *out_value = NIL_VAL;         advance_token(); return true; }
    /* Phase D : reference a une constante du registry (ex: TBValider).
     * Permet l'init de proprietes par enum-ref sans warning B.5+.
     *
     * Phase D+ : appel a une native PURE avec args literaux (ex: RVB(0,0,255)).
     * La native est evaluee a compile-time, equivalent a ecrire l'entier
     * resultat directement. Limite aux retours non-objet (entier/reel/bool)
     * pour eviter les soucis GC sur les valeurs allouees pendant compile. */
    if (check(TOKEN_IDENTIFIER)) {
        Token t = parser.current;
        char buf[128];
        int n = t.length < (int)sizeof(buf) - 1 ? t.length : (int)sizeof(buf) - 1;
        memcpy(buf, t.start, (size_t)n);
        buf[n] = '\0';
        /* Bilingue : une valeur d'enum / constante en forme EN (`dispFree`,
         * nameEN de `dispLibre`) se replie comme sa forme FR. Aligne le
         * const-folder DSL sur la resolution bilingue runtime (globals EN). */
        const OwlConstDef* cst = owl_registry_const_find_bilingual(buf);
        if (cst) {
            *out_value = cst->value;
            advance_token();
            return true;
        }
        /* Native pure ? Tente le compile-time eval. */
        const OwlNativeDef* nat = owl_registry_find(buf);
        if (nat && (nat->flags & OWL_NAT_PURE)) {
            /* Checkpoint pour rollback si echec a n'importe quel point. */
            Token saved_current  = parser.current;
            Token saved_previous = parser.previous;
            Scanner saved_scan   = parser.scanner;
            bool saved_nl        = crossedNewline;
            advance_token();  /* consume IDENTIFIER */
            if (check(TOKEN_LEFT_PAREN)) {
                advance_token();  /* consume ( */
                Value args[16];
                int argCount = 0;
                bool ok = true;
                if (!check(TOKEN_RIGHT_PAREN)) {
                    for (;;) {
                        if (argCount >= 16) { ok = false; break; }
                        if (!window_try_parse_const_atom(&args[argCount])) { ok = false; break; }
                        argCount++;
                        if (check(TOKEN_RIGHT_PAREN)) break;
                        if (!match_token(TOKEN_COMMA)) { ok = false; break; }
                    }
                }
                if (ok && check(TOKEN_RIGHT_PAREN)) {
                    advance_token();  /* consume ) */
                    Value result = nat->impl(argCount, args);
                    /* Accepte uniquement les Values sans objet GC : un ObjString
                     * alloue ici pourrait etre collecte avant l'open de la
                     * fenetre. Suffisant pour RVB/TSL (entiers). */
                    if (IS_INTEGER(result) || IS_REAL(result) ||
                        IS_BOOL(result) || IS_NIL(result)) {
                        *out_value = result;
                        return true;
                    }
                }
            }
            /* Echec : rollback complet. */
            parser.current  = saved_current;
            parser.previous = saved_previous;
            parser.scanner  = saved_scan;
            crossedNewline  = saved_nl;
        }
    }
    return false;
}

/* Wrapper : parse un atome puis chaine '+' / '-' avec d'autres atomes tant
 * que les operandes sont entier ou reel. Permet aux PROPRIETES DSL d'accepter
 * les enums combinables canon : `Bords = BordHaut + BordBas`,
 * `OptionTri = ccSansAccent + ccSansCasse`, etc. Entiers : '+' et '-'. Reels :
 * '+' et '-'. Tout autre token ou type = stop normal du chainage. */
static bool window_try_parse_const_literal(Value* out_value) {
    if (!window_try_parse_const_atom(out_value)) return false;

    /* Chaine + / - tant que les deux operandes sont numeriques. */
    while (check(TOKEN_PLUS) || check(TOKEN_MINUS)) {
        bool isPlus = check(TOKEN_PLUS);
        /* Snapshot pour rollback si l'atome droite n'est pas const-foldable. */
        Token saved_current  = parser.current;
        Token saved_previous = parser.previous;
        Scanner saved_scan   = parser.scanner;
        bool saved_nl        = crossedNewline;

        advance_token(); /* consume + / - */
        Value rhs;
        if (!window_try_parse_const_atom(&rhs)) {
            /* Rollback : laisse le + / - + suite a un autre parseur. */
            parser.current = saved_current;
            parser.previous = saved_previous;
            parser.scanner = saved_scan;
            crossedNewline = saved_nl;
            break;
        }
        if (IS_INTEGER(*out_value) && IS_INTEGER(rhs)) {
            int64_t a = AS_INTEGER(*out_value);
            int64_t b = AS_INTEGER(rhs);
            *out_value = INTEGER_VAL(isPlus ? a + b : a - b);
        } else if ((IS_INTEGER(*out_value) || IS_REAL(*out_value)) &&
                   (IS_INTEGER(rhs)        || IS_REAL(rhs))) {
            double a = IS_INTEGER(*out_value) ? (double)AS_INTEGER(*out_value)
                                              : AS_REAL(*out_value);
            double b = IS_INTEGER(rhs) ? (double)AS_INTEGER(rhs) : AS_REAL(rhs);
            *out_value = REAL_VAL(isPlus ? a + b : a - b);
        } else {
            /* Type non chainable (ex: chaine + chaine) : on reverse l'op et stop. */
            parser.current = saved_current;
            parser.previous = saved_previous;
            parser.scanner = saved_scan;
            crossedNewline = saved_nl;
            break;
        }
    }
    return true;
}

/* Detection contextuelle : current token est IDENT avec exactement "Champ"
 * (FR), "Field" ou "Control" (EN — nameEN canon du type Champ), case-insensitive.
 * Sert au modifier optionnel "Champ Bouton/Libellé/.../Image" dans le DSL
 * fenetre. Pas un keyword scanner pour eviter le conflit avec des variables
 * nommees "champ". */
static bool check_ident_champ(void) {
    if (!check(TOKEN_IDENTIFIER)) return false;
    if (parser.current.length == 5 &&
        strncasecmp(parser.current.start, "Champ", 5) == 0) return true;
    if (parser.current.length == 5 &&
        strncasecmp(parser.current.start, "Field", 5) == 0) return true;
    /*  : 'Control' est le nameEN canon du type Champ. Le prefixe
     * widget bilingue accepte donc 'Control Label' comme 'Champ Libellé'. */
    if (parser.current.length == 7 &&
        strncasecmp(parser.current.start, "Control", 7) == 0) return true;
    return false;
}

/*  : 'de'/'of' filler optionnel entre le modificateur 'Champ' et le
 * genre ('X est un Champ de Saisie' == 'X est un Champ Saisie'). PUR filler :
 * zero effet semantique. A n'appeler QU'APRES avoir consomme 'Champ' — jamais
 * pour un genre nu (Image/Liste sans Champ gardent leur 'de' de collection). */
static void skip_optional_de_after_champ(void) {
    if (check(TOKEN_DE)) advance_token();
}

/* Detection unifiee du genre d'un controle apres `est un[e] [Champ]`.
 * Gere les keywords scanner (TOKEN_LIBELLE/BOUTON/SAISIE/TABLE/CONTENEUR/
 * LISTE) ET les IDENTs DSL (Image/Liste/Combo/Selecteur/Interrupteur/
 * ZoneRepetee). Retourne true + remplit *out si le token courant nomme un
 * OwlControlKind, false sinon.
 *
 *  : la fonction ne tient plus compte du modifier 'Champ' — elle
 * detecte le genre brut. C'est le caller qui tranche accepter (Champ present)
 * vs rejeter E_SEM_DSL_CHAMP_PREFIXE_REQUIS (Champ absent). Les anciens peeks
 * de desambiguisation Image (`=`/`PROPRIETES`) et Liste (`de`) sont supprimes :
 * avec 'Champ' obligatoire, Image/Liste nus sont toujours variable/collection,
 * jamais un widget — il n'y a plus rien a desambiguer ici.
 *
 * Cette fonction est partagee entre les 2 sites de dispatch (window
 * subfield + nested Conteneur), evitant la duplication de la chaine
 * `if check_ident_X then OWL_CONTROL_X`. */
static bool detect_subfield_kind(OwlControlKind* out) {
    if (check(TOKEN_LIBELLE))   { *out = OWL_CONTROL_LABEL;     return true; }
    if (check(TOKEN_BOUTON))    { *out = OWL_CONTROL_BUTTON;    return true; }
    if (check(TOKEN_SAISIE))    { *out = OWL_CONTROL_INPUT;     return true; }
    if (check(TOKEN_TABLE))     { *out = OWL_CONTROL_TABLE;     return true; }
    if (check(TOKEN_CONTENEUR)) { *out = OWL_CONTROL_CONTAINER; return true; }
    if (check(TOKEN_LISTE))     { *out = OWL_CONTROL_LISTE;     return true; }
    /* IDENTs DSL widgets : Image, Combo, Selecteur, Interrupteur,
     * ZoneRepetee (Image est aussi un type runtime — tranche par 'Champ'
     * cote caller). */
    if (check(TOKEN_IDENTIFIER)) {
        OwlControlKind k;
        if (!owl_control_kind_from_token(parser.current.start,
                                          parser.current.length, &k, NULL))
            return false;
        *out = k;
        return true;
    }
    return false;
}

/*  : detection contextuelle du sous-bloc Volet (FR) / Pane (EN).
 * Comme Colonne, Volet est un sous-bloc de rôle SANS prefixe `Champ` — mais,
 * a la difference de Colonne, ce n'est pas un keyword scanner (pas de conflit
 * a proteger, et pour rester symetrique du reste du DSL widget qui detecte les
 * genres par IDENT). Le token courant doit etre l'IDENT du genre. */
static bool is_volet_token(void) {
    return token_is_volet_genre(parser.current);
}

/*  lot 1-bis : genres ambigus avec un type runtime / collection.
 * Image (type raster), Liste (collection generique) et CodeBarres (type
 * compose first-class) : une forme nue `X est une Image` / `X est une Liste
 * [de ...]` / `X est un CodeBarres` est une VARIABLE/COLLECTION deterministe
 * — le type gagne, aucune erreur Champ. Le controle correspondant EXIGE
 * `Champ Image` / `Champ Liste` / `Champ CodeBarres`. Les autres genres
 * (Libelle, Bouton, Saisie, Table, Conteneur, Combo, Selecteur, Interrupteur,
 * ZoneRepetee, Jauge) sont controle-seuls : forme nue =>
 * E_SEM_DSL_CHAMP_PREFIXE_REQUIS toujours. */
static bool owl_control_kind_is_ambiguous(OwlControlKind kind) {
    return kind == OWL_CONTROL_IMAGE || kind == OWL_CONTROL_LISTE
        || kind == OWL_CONTROL_CODEBARRE;
}

/*  lot 1-bis : peek si un bloc PROPRIETES suit immediatement (a
 * travers les NEWLINE) la position courante du scanner. Sert d'EXCEPTION
 * MESSAGING pour Image/Liste nus : `X est une Image` <nl> `PROPRIETES` =
 * intention controle evidente -> emettre l'erreur Champ d'aide. Le peek ne
 * sert QU'au message, pas a la desambiguisation semantique (decision figee).
 * Restaure integralement l'etat scanner/tokens. */
static bool peek_proprietes_follows(void) {
    Scanner ss = parser.scanner;
    Token   sc = parser.current;
    Token   sp = parser.previous;
    bool    sn = crossedNewline;
    advance_token();
    while (check(TOKEN_NEWLINE)) advance_token();
    bool follows = check(TOKEN_PROPRIETES);
    parser.scanner = ss; parser.current = sc; parser.previous = sp;
    crossedNewline = sn;
    return follows;
}

/* Skip jusqu'au prochain newline (via crossedNewline) ou jusqu'a un token
 * qui ressemble au debut d'un nouveau statement dans le body de fenetre.
 * advance_token consume les NEWLINE silencieusement (crossedNewline=true). */
static void window_skip_to_next_stmt(void) {
    /* Avance au moins une fois pour eviter une boucle infinie quand le
     * caller restaure le scanner state avant l'appel : crossedNewline
     * peut etre deja true a l'entree (token au debut d'une ligne), et
     * sans avancement on retomberait sur le meme token a la prochaine
     * iteration de la boucle parent. */
    bool advanced = false;
    while (!check(TOKEN_EOF) && !check(TOKEN_FIN)) {
        if (advanced && crossedNewline) break;
        if (check(TOKEN_LIBELLE) || check(TOKEN_BOUTON) ||
            check(TOKEN_SAISIE)  || check(TOKEN_TABLE)  ||
            check(TOKEN_CONTENEUR) ||
            check_ident_champ() ||
            check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION)) break;
        advance_token();
        advanced = true;
    }
}

/* Comparaison de deux noms de blocs de la DSL fenetre : casse ET accents
 * ignores (invariant 2), comme partout ailleurs dans le langage. */
static bool window_ci_eq(const char* a, const char* b) {
    if (!a || !b) return false;
    return dsl_proc_name_eq(a, (int)strlen(a), b, (int)strlen(b));
}

/* Forme sous laquelle deux graphies d'un meme bloc doivent se rencontrer.
 * Un evenement predefini est ramene a son canon par le catalogue, qui absorbe
 * a la fois la casse, les accents et la paire FR/EN ; un nom libre reste
 * lui-meme et sera compare par window_ci_eq. Sans cette resolution prealable,
 * `Fermeture` et `Closing` — ou `surEntree` et `surEntrée` — passaient pour
 * deux blocs distincts a la declaration alors que le cablage runtime, lui,
 * n'en retient qu'un : le second bloc etait du code mort, sans message. */
static const char* window_block_canon(const char* name) {
    const OwlEventDef* e = owl_window_lifecycle_catalog_find(name);
    return e ? e->canonical : name;
}
static const char* control_block_canon(OwlControlKind kind, const char* name) {
    const OwlEventDef* e = owl_event_catalog_find(kind, name);
    return e ? e->canonical : name;
}

/* Helpers : detecte si un nom de bloc PROCEDURE est deja declare dans
 * le widget/fenetre courant (event OU user_proc). */
static bool control_decl_has_block_name(OwlControlDecl* c, const char* name) {
    if (!c) return false;
    const char* want = control_block_canon(c->kind, name);
    for (int i = 0; i < c->event_count; i++)
        if (window_ci_eq(control_block_canon(c->kind, c->events[i].name), want))
            return true;
    for (int i = 0; i < c->user_proc_count; i++)
        if (window_ci_eq(c->user_procs[i].name, name)) return true;
    return false;
}
static bool window_decl_has_block_name(OwlWindowDecl* w, const char* name) {
    if (!w) return false;
    const char* want = window_block_canon(name);
    for (int i = 0; i < w->event_count; i++)
        if (window_ci_eq(window_block_canon(w->events[i].name), want)) return true;
    for (int i = 0; i < w->user_proc_count; i++)
        if (window_ci_eq(w->user_procs[i].name, name)) return true;
    return false;
}

/* Liste blanche des blocs predefinis valides au niveau Fenetre.
 * Convention : lifecycle sans prefixe (FinInitialisation, Fermeture).
 * 'Initialisation' n'existe plus comme event : le code d'init
 * vit dans le top-level de la fenetre, rejete en amont.
 *
 * Source de verite : owl_window_lifecycle_catalog (event_catalog_widgets.c).
 * Plus de liste hardcodee : le catalogue est case+accent insensible et
 * couvre les alias EN via le champ nameEN. */
static bool is_predefined_window_block(const char* name) {
    return owl_window_lifecycle_catalog_find(name) != NULL;
}

/* Liste blanche des blocs predefinis valides selon le kind de champ.
 * Convention OWL stricte : lifecycle Initialisation sans prefixe ; events
 * avec prefixe sur* systematique (surClic / surEntr\xc3\xa9""e / surSortie
 * / surAChaqueModification / surValidation / surDoubleClic / ...).
 *
 * Les noms canon strict sans prefixe (Clic, Click, Modification, Validation,
 * Entree, Sortie, etc.) NE SONT PAS acceptes — break-net assume vs canon.
 * Rationale : "sur*" elimine l'ambiguite procedure custom vs event handler
 * et evite la collision avec un IDENT user `Clic est un Bouton`. Cf
 * docs/VISION.md §5bis pour la divergence assumee. */
static bool is_predefined_control_block(OwlControlKind kind, const char* name) {
    /* 'Initialisation' n'est plus un event : le code d'init vit
     * dans le top-level du champ, rejete en amont du dispatch.
     * Source de verite : le catalogue d'events (event_catalog_widgets.c).
     * Le filet de securite : le self-test regle 8 valide chaque entree. */
    return owl_event_catalog_find(kind, name) != NULL;
}

/* Helper : declare un local synthetique (auto-bound mot-cle contextuel)
 * dans le compileur courant. Retourne l'index du slot. Le slot sera
 * rempli par le runtime (Phase E) avant chaque appel — en V1 les blocs
 * ne sont pas encore appeles. */
static int declare_synthetic_local(const char* name) {
    Token tok = (Token){0};
    tok.type   = TOKEN_IDENTIFIER;
    tok.start  = name;
    tok.length = (int)strlen(name);
    tok.line   = parser.previous.line;
    add_local(tok);
    int slot = current->localCount - 1;
    Local* local = &current->locals[slot];
    local->isUsed = true;          /* eviter le warning "unused" */
    local->hasInitializer = true;  /* runtime fournit la valeur */
    return slot;
}

/* Compile le body d'un bloc PROCEDURE en ObjFunction.
 * Le current token doit etre juste APRES le ')' fermant des parametres.
 * Le body s'etend jusqu'au FIN matching, qui est consume.
 *
 * with_monchamp : true pour les blocs PROCEDURE de champ (Bouton/
 *   Libelle/Saisie) qui exposent MonChamp. false pour les blocs au
 *   niveau Fenetre (Initialisation/Fermeture/...) qui n'exposent que
 *   MaFenetre.
 *
 * Les auto-locals MaFenetre [+ MonChamp] sont declares comme parametres
 * de la fonction (arity++) : Phase E poussera les valeurs sur la pile
 * avant l'OP_CALL. */
static ObjFunction* compile_event_block_body_with_params(
        const char* blockName, bool with_monchamp,
        int paramCount, const char* const* paramNames)
{
    Compiler compiler;
    init_compiler(&compiler, TYPE_FUNCTION);
    begin_scope();
    current->function->name = obj_copy_string(blockName, (int)strlen(blockName));

    /* Phase C : declare MaFenetre comme local implicite (slot 1, parametre 1).
     * Slot 0 reste reserve pour la fonction (cf init_compiler). */
    declare_synthetic_local("MaFenetre");
    current->function->arity++;

    /* MonChamp seulement dans les blocs de champ. */
    if (with_monchamp) {
        declare_synthetic_local("MonChamp");
        current->function->arity++;
    }

    /* Params canon de l'event (declares par le dev avec types typés —
     * cf event_catalog_widgets.c). Chaque param devient un local
     * accessible par nom dans le body. */
    for (int i = 0; i < paramCount; i++) {
        declare_synthetic_local(paramNames[i]);
        current->function->arity++;
    }

    /* Recovery panicMode : si une erreur se produit dans le body, on skip
     * au prochain statement boundary avant de continuer — sinon le
     * declaration() suivant peut mal interpreter les tokens (notamment
     * manquer le FIN matching, ce qui fait sortir le parser DSL parent
     * au mauvais endroit). Aligne sur window_declaration / subfield. */
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        if (parser.panicMode) {
            while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                advance_token();
            }
            parser.panicMode = false;
        }
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
        declaration();
    }
    /* Clear panicMode avant le consume FIN final pour qu'un parser parent
     * ne reste pas bloque. */
    parser.panicMode = false;
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_BLOCK_BODY);

    return end_compiler();
}

/* Wrapper compatibilite : ancienne signature (events 0-arg). */
static ObjFunction* compile_event_block_body(const char* blockName, bool with_monchamp) {
    return compile_event_block_body_with_params(blockName, with_monchamp, 0, NULL);
}

/* Phase 6 : compile une PROCEDURE custom dans le body d'un widget.
 * Le current token doit etre juste APRES le '(' ouvrant des parametres
 * (entre '(' et ')'). Les params utilisateur sont parses ici, puis le
 * ')' est consume, puis le body jusqu'au FIN.
 *
 * V1 KISS : la fonction recoit UNIQUEMENT les params utilisateur (pas
 * MaFenetre/MonChamp implicites). L'utilisateur accede aux controles
 * via leurs noms globaux. V2 : injection MaFenetre+MonChamp possible.
 *
 * Resolution implicite : 'Calcule()' dans le body d'un event du meme
 * widget compile vers OP_GET_GLOBAL("<widget>_Calcule") via la table
 * g_widget_proc_aliases (cf named_variable). */
static ObjFunction* compile_user_proc_body(const char* procName) {
    Compiler compiler;
    init_compiler(&compiler, TYPE_FUNCTION);
    begin_scope();
    current->function->name = obj_copy_string(procName, (int)strlen(procName));

    /* Parse params utilisateur entre '(' et ')'. */
    Value defaults[255];
    int defaultCount = 0;
    int minArity = 0;
    if (!check(TOKEN_RIGHT_PAREN)) {
        do {
            current->function->arity++;
            if (current->function->arity > 255) {
                owl_emit_error_current(E_SYNTAX_TOO_MANY_PARAMETERS);
                break;
            }
            if (!check(TOKEN_IDENTIFIER)) {
                owl_emit_error_current(E_SYNTAX_EXPECTED_PARAM_NAME);
                break;
            }
            advance_token();
            Token paramName = parser.previous;
            declare_variable(&paramName);
            bool typeSeen = match_token(TOKEN_EST);
            if (typeSeen) {
                skip_type_spec();
            }
            reject_untyped_param(&paramName, typeSeen);
            /* Optional default value: "= <literal>". Once a param has a
             * default, all subsequent params must also have one (parity
             * rule). */
            if (match_token(TOKEN_EQUAL)) {
                Value v;
                if (parse_default_literal(&v)) {
                    defaults[defaultCount++] = v;
                    if (current->localCount > 0)
                        current->locals[current->localCount - 1].hasInitializer = true;
                }
            } else {
                if (defaultCount > 0) {
                    owl_emit_error_at(&parser.previous, E_SEM_REQUIRED_PARAM_AFTER_DEFAULT);
                }
                minArity = current->function->arity;
            }
        } while (match_token(TOKEN_COMMA));
    }
    consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_PARAMS);
    current->function->minArity = minArity;
    if (defaultCount > 0) {
        current->function->defaults = (Value*)malloc(sizeof(Value) * defaultCount);
        for (int di = 0; di < defaultCount; di++) {
            current->function->defaults[di] = defaults[di];
        }
        current->function->defaultCount = defaultCount;
    }

    /*  Cas 1 : annotation type retour `: <Type>` optionnelle sur la
     * meme ligne que `)`. Sans cette consommation, le `:` etait happe par le
     * prefix parselet `this_field` du body (premier statement) -> erreur
     * trompeuse ":membre' ne peut etre utilise qu'a l'interieur d'une methode"
     * en lieu et place de l'annotation de type retour evidente. Pattern
     * symetrique avec compile_inline_class_method (cf. ~L13900). */
    if (is_return_type_colon() ||
        (check(TOKEN_COLON) && !crossedNewline)) {
        advance_token(); /* consume ':' */
        skip_type_spec();
    }

    /*  — un parametre qui shadow une globale (voisine ou de ce
     * fichier) emet E_SEM_VAR_SHADOWS_OUTER_SCOPE via declare_variable, ce
     * qui pose panicMode. Ce diagnostic est legitime et deja bufferise.
     * Mais s'il fuit dans la boucle de body ci-dessous, sa recovery
     * (skip-to-newline) avale la PREMIERE ligne du body avant le 1er
     * declaration(). Si cette ligne est l'entete d'un bloc imbrique
     * (POUR/SI/...), son FIN reste mais l'ouverture a disparu : le compteur
     * de FIN desynchronise, le consume(FIN) final happe le FIN du bloc
     * imbrique et la PROCEDURE est vue comme fermee trop tot -> cascade
     * hors-bloc cote parseur DSL Fenetre. On clear panicMode ici : la
     * declaration des params est terminee, le body doit etre parse propre.
     * Symetrique du clear panicMode des blocs predefinis (~L18086) et du
     * chemin champ. */
    parser.panicMode = false;

    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        if (parser.panicMode) {
            while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                advance_token();
            }
            parser.panicMode = false;
        }
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
        declaration();
    }
    parser.panicMode = false;
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROCEDURE);

    return end_compiler();
}

/* Skip un bloc imbrique du type "X ... FIN" (sous-champ ou PROCEDURE). */
static void window_skip_nested_block(void) {
    int depth = 1;
    while (depth > 0 && !check(TOKEN_EOF)) {
        /* Genres de widget + prefixe Champ : hors table (ils n'ouvrent qu'apres
         * la copule). Le reste vient de la source unique — .
         *
         * PROPRIETES est explicitement EXCLU, alors que la table le classe
         * ouvrant : ce helper ne l'a jamais compte, et cette divergence est
         * load-bearing — dsl_skip_toplevel_widget_block existe justement parce
         * que ce skip-ci s'arrete trop tot sur un corps a PROPRIETES. La
         * corriger deplacerait le comportement de tous ses appelants, ce qui
         * n'est pas l'objet de ce ticket. Signale au coordinator. */
        if (check(TOKEN_FENETRE) || check(TOKEN_LIBELLE) ||
            check(TOKEN_BOUTON)  || check(TOKEN_SAISIE)  ||
            check(TOKEN_TABLE)   || check(TOKEN_CONTENEUR) ||
            check_ident_champ()  ||
            (!check(TOKEN_FIN) && !check(TOKEN_PROPRIETES)
             && prescan_token_in_depth_table(parser.current.type)
             && parser_depth_delta() > 0)) {
            depth++;
        } else if (check(TOKEN_FIN)) {
            depth--;
            if (depth == 0) { advance_token(); return; }
        }
        advance_token();
    }
}

/*  : skip d'un bloc-controle complet 'IDENT est un[e] [Champ]
 * <Genre> ... FIN' apres detection d'une erreur (controle nu). Le caller doit
 * restaurer le scanner au DEBUT du statement (sur l'IDENT) avant l'appel.
 * Delegue a dsl_skip_toplevel_widget_block, qui compte correctement les
 * ouvreurs imbriques (PROPRIETES, PROCEDURE, structures de controle, et les
 * sous-widgets 'IDENT est un Champ X'). window_skip_nested_block ne compte PAS
 * PROPRIETES comme ouvreur et sortirait trop tot -> cascade sur le FIN orphelin. */
static void dsl_skip_toplevel_widget_block(void); /* fwd (def plus bas) */
static void dsl_skip_block_body(void);            /* fwd (def plus bas) */
static void window_skip_control_block(void) {
    dsl_skip_toplevel_widget_block();
}

/* Nom FR du type d'une Value scalaire (pour messages d'erreur DSL). */
static const char* value_scalar_type_name_fr(Value v) {
    if (IS_INTEGER(v)) return "entier";
    if (IS_REAL(v))    return "r\xc3\xa9" "el";
    if (IS_STRING(v))  return "chaine";
    if (IS_BOOL(v))    return "bool\xc3\xa9" "en";
    if (IS_NIL(v))     return "Null";
    return "valeur";
}

/* Nom du type-cible a propager pour un litteral inline `Prop = { ... }` :
 *   - prop ENUM   -> enum_name (ex: Option)
 *   - prop OBJECT -> object_type (ex: Cadre, descripteur compose)
 * NULL si la prop n'attend pas de target type composable. */
static const char* prop_inline_target_type(const OwlControlPropDef* def) {
    if (!def) return NULL;
    if (def->type == OWL_PROP_TYPE_OBJECT) return def->object_type;
    return def->enum_name;
}

/*  (volet A) — prop DSL de widget attendant un TABLEAU. Aujourd'hui les
 * seules : Selecteur.Options et Interrupteur.Options, cataloguees VARIANT +
 * enum_name "Option" (element-type du tableau, propage par array_literal).
 * Le litteral tableau canon est mono-ligne ; un `[` en fin de ligne produit un
 * TOKEN_MULTILINE_STRING (chaine multi-ligne canon), type incompatible avec une
 * cible tableau (erreur "Types incompatibles"). Sert au garde symetrique de
 *  sur le chemin prop DSL, ou la chaine etait avalee en silence. */
static bool dsl_prop_expects_array(const OwlControlPropDef* def) {
    return def && def->type == OWL_PROP_TYPE_VARIANT
        && def->enum_name && strcmp(def->enum_name, "Option") == 0;
}

/*  : une prop STRING peut porter un enum_base (ex: PoliceNom avec
 * enum_base "iFamille"). Dans ce cas elle accepte AUSSI une constante membre
 * de cet enum en plus d'une chaine litterale — alignement sur la cascade
 * (`LIB..PoliceNom = iPoliceArial`) et le litteral compose (`Police = { Nom =
 * iPoliceArial }`). Detection au niveau du token AVANT le const-folding :
 * l'identifiant doit etre une constante membre de enum_base. Casse/accent-
 * insensibilite + bilinguisme FR/EN herites de owl_enum_contains_bilingual. */
static bool window_string_enum_member_token(const OwlControlPropDef* def) {
    if (!def)                              return false;
    if (def->type != OWL_PROP_TYPE_STRING) return false;
    if (!def->enum_name)                   return false;
    if (!check(TOKEN_IDENTIFIER))          return false;

    Token vTok = parser.current;
    char buf[128];
    int n = vTok.length < (int)sizeof(buf) - 1 ? vTok.length : (int)sizeof(buf) - 1;
    memcpy(buf, vTok.start, (size_t)n);
    buf[n] = '\0';

    const OwlEnum* e = owl_registry_enum_find(def->enum_name);
    if (!e) return false;
    return owl_enum_contains_bilingual(e, buf);
}

/* Phase D : verifie qu'une Value parsee est compatible avec le type
 * attendu d'une propriete UI. Emet une erreur sur errTok si non. */
static bool window_check_value_type(const OwlControlPropDef* def, Value v,
                                     Token* errTok) {
    switch (def->type) {
        case OWL_PROP_TYPE_INT:
        case OWL_PROP_TYPE_COLOR:
            if (IS_INTEGER(v)) return true;
            break;
        case OWL_PROP_TYPE_ENUM:
            if (IS_INTEGER(v)) {
                /* Determinisme (pilier 2) : un entier litteral pose sur une
                 * prop enum doit correspondre a une constante declaree.
                 * Extension aux props DSL du comportement deja en place pour
                 * les variables (`maVar est un EnumX = 42`, cf.
                 * enum_contains_int call sites). */
                const OwlEnum* e = def->enum_name
                                 ? owl_registry_enum_find(def->enum_name)
                                 : NULL;
                if (e == NULL) return true; /* enum non resolu : laisser passer */
                /* Garde defensif : pour un enum combinable (bitmask), un entier
                 * peut etre un OR de constantes != constante unique, donc on ne
                 * peut pas appliquer enum_contains_int strict. Aucun enum
                 * combinable n'est aujourd'hui une prop DSL (allowedBase) ; ce
                 * skip best-effort couvre un futur ajout sans faux positif. */
                if (e->combinable) return true;
                if (enum_contains_int(e, AS_INTEGER(v))) return true;
                char valBuf[32];
                snprintf(valBuf, sizeof(valBuf), "%lld",
                         (long long)AS_INTEGER(v));
                owl_emit_error_at(errTok, E_SEM_DSL_PROP_ENUM_INT_OUT_OF_RANGE,
                                  "type", def->enum_name,
                                  "value", valBuf,
                                  NULL);
                return false;
            }
            break;
        case OWL_PROP_TYPE_STRING:
            if (IS_STRING(v) || IS_NIL(v)) return true;
            break;
        case OWL_PROP_TYPE_MULTILINGUE:
            /* Slot chaineMultilingue : accepte chaine litterale (coerce
             * auto -> remplit langue source au build_control) OU objet
             * ObjMultilingue deja construit (cas litteral inline qui passe
             * par compile_expression_as_fn donc non-const ici, mais defense
             * runtime). Le NIL est aussi accepte. */
            if (IS_STRING(v) || IS_NIL(v) || IS_MULTILINGUE(v)) return true;
            break;
        case OWL_PROP_TYPE_BOOL:
            if (IS_BOOL(v)) return true;
            break;
        case OWL_PROP_TYPE_VARIANT:
            return true;
        case OWL_PROP_TYPE_OBJECT:
            /*  : descripteur compose. Un litteral const (scalaire)
             * n'est jamais valide — seul un descripteur compose (instance ou
             * litteral inline `{...}`, qui passe par le chemin non-const)
             * convient. Message nominatif aligne sur le rejet top-level. */
            owl_emit_error_at(errTok, E_SEM_DSL_OBJECT_PROP_SCALAR,
                              "type", def->object_type ? def->object_type
                                                       : def->nameFR,
                              "got", value_scalar_type_name_fr(v),
                              NULL);
            return false;
        case OWL_PROP_TYPE_POSITION:
            /* V1 : init litteral non supporte (tuple syntax V1.5+). On laisse
             * passer mais on skip — Phase E prendra les defaults (0, 0). */
            owl_emit_warning_at(errTok,
                W_SEM_PROP_POSITION_LITERAL_NOT_SUPPORTED,
                "prop", def->nameFR,
                NULL);
            return false;
    }
    owl_emit_error_at(errTok, E_SEM_DSL_PROP_TYPE_INCOMPATIBLE,
                      "prop", def->nameFR,
                      "expected", owl_prop_type_name(def->type),
                      NULL);
    return false;
}

/* Pour les props ENUM, valide directement le nom d'identifier reference
 * contre les valeurs de l'enum AVANT le parse litteral. Donne un meilleur
 * message d'erreur ('TBLicorne' n'est pas une valeur de TypeBouton).
 *
 * Retourne true si validation OK ou non applicable, false si erreur emise. */
static bool window_validate_enum_ref(const OwlControlPropDef* def) {
    if (def->type != OWL_PROP_TYPE_ENUM)         return true;
    if (!check(TOKEN_IDENTIFIER))                 return true; /* sera int */
    if (!def->enum_name)                          return true;

    Token vTok = parser.current;
    char buf[128];
    int n = vTok.length < (int)sizeof(buf) - 1 ? vTok.length : (int)sizeof(buf) - 1;
    memcpy(buf, vTok.start, (size_t)n);
    buf[n] = '\0';

    const OwlEnum* e = owl_registry_enum_find(def->enum_name);
    if (!e) return true; /* enum non enregistre : laisser passer */
    if (owl_enum_contains_bilingual(e, buf)) return true;

    owl_emit_error_at(&vTok, E_SEM_DSL_ENUM_VALUE_INVALID,
                      "value", buf,
                      "enumName", def->enum_name,
                      NULL);
    advance_token();
    return false;
}

static bool prop_is_context_menu_attach(Token t);  /*  (defini plus bas) */

/* Parse une init de propriete : 'Nom = literal' au niveau Fenetre.
 * Le current token est sur l'identifiant de la propriete. */
static void window_parse_property_init(OwlWindowDecl* decl) {
    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_PROP_NAME_WINDOW);
        advance_token();
        return;
    }
    Token propTok = parser.current;
    advance_token(); /* consume IDENT */

    /*  — `MenuContextuel = <nom>` dans le bloc PROPRIETES de la
     * Fenetre : menu contextuel du fond de fenetre (clic droit sur une zone
     * vide, hors de tout champ). Meme resolution differee que le champ. */
    if (decl && prop_is_context_menu_attach(propTok)) {
        if (!match_token(TOKEN_EQUAL) || !check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&propTok, E_SEM_CTXMENU_ASSIGN_EXPECTED_NAME, NULL);
            window_skip_to_next_stmt();
            if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
            return;
        }
        Token valTok = parser.current;
        advance_token();
        if (decl->context_menu_name != NULL) {
            owl_emit_error_at(&propTok, E_SEM_CTXMENU_ASSIGN_DUPLICATE,
                              "name", decl->context_menu_name, NULL);
            if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
            return;
        }
        char nameBuf[128];
        int vl = valTok.length < 127 ? valTok.length : 127;
        memcpy(nameBuf, valTok.start, (size_t)vl);
        nameBuf[vl] = '\0';
        owl_window_decl_set_context_menu(decl, nameBuf, valTok.line);
        return;
    }

    /*  : cascade declarative `Prop..SousChamp = valeur` au niveau
     * Fenetre. Symetrique de control_parse_property_init.
     *  : si un buffer cascade est actif (bloc PROPRIETES), bufferise
     * pour regroupement compile-time avec les autres cascades homonymes. */
    if (check(TOKEN_DOUBLE_DOT)) {
        char propAsciiC[128];
        int pl = scanner_strip_accents(propTok.start, propTok.length,
                                       propAsciiC, sizeof(propAsciiC));
        if (pl <= 0) pl = propTok.length < 127 ? propTok.length : 127;
        propAsciiC[pl] = '\0';
        const OwlControlPropDef* wdef = owl_window_catalog_find(propAsciiC);
        if (!wdef) {
            owl_emit_error_at(&propTok, E_SEM_DSL_PROP_UNKNOWN_FOR_WINDOW,
                              "prop", propAsciiC, NULL);
            window_skip_to_next_stmt();
            /*  : resync propre sur la prop suivante — rearmer le
             * reporting pour ne pas avaler l'erreur de la prochaine prop
             * inconnue du meme bloc PROPRIETES Fenetre. On ne rearme QUE si
             * une autre prop suit : a la frontiere (FIN/EOF), preserver
             * l'etat panic pour ne pas relancer la cascade downstream. */
            if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
            return;
        }
        if (wdef->type != OWL_PROP_TYPE_OBJECT || !wdef->object_type) {
            owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
            window_skip_to_next_stmt();
            return;
        }
        /* Invariant : g_cascade_buffer est toujours actif ici. Toute prop DSL
         * (donc toute cascade `..`) est parsee dans un bloc PROPRIETES qui ouvre
         * ce buffer ; il n'existe pas de chemin d'entree hors buffer. La cascade
         * est bufferisee pour regroupement compile-time des cascades homonymes. */
        cascade_buffer_capture(g_cascade_buffer, propTok,
                               propAsciiC, pl,
                               wdef->object_type,
                               (int)strlen(wdef->object_type), NULL);
        return;
    }

    if (!match_token(TOKEN_EQUAL)) {
        owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
        return;
    }
    if (dsl_prop_value_missing_reported(&propTok)) return;

    /* Phase G v2 fix : normaliser en accent-stripped (cf control_parse_property_init). */
    char propAsciiF[128];
    int  propAsciiFLen = scanner_strip_accents(propTok.start, propTok.length,
                                                propAsciiF, sizeof(propAsciiF));
    if (propAsciiFLen <= 0) propAsciiFLen = propTok.length < 127 ? propTok.length : 127;
    char* propName = (char*)malloc((size_t)propAsciiFLen + 1);
    memcpy(propName, propAsciiF, propAsciiFLen);
    propName[propAsciiFLen] = '\0';

    /* Phase D : lookup dans le catalogue. */
    const OwlControlPropDef* def = owl_window_catalog_find(propName);
    if (!def) {
        owl_emit_error_at(&propTok, E_SEM_DSL_PROP_UNKNOWN_FOR_WINDOW,
                          "prop", propName,
                          NULL);
        free(propName);
        /*  (cause #1) : une valeur litterale `{...}` multiligne
         * (typiquement un litteral chaineMultilingue mal place dans le corps de
         * Fenetre, hors PROPRIETES) doit etre avalee en entier. Sans ca,
         * window_skip_to_next_stmt s'arrete au premier newline et le contenu du
         * bloc `{...}` retombe comme statements top-level de la Fenetre ->
         * cascade fantome (bloc ferme trop tot, +N hors bloc). Apres avoir avale
         * le bloc balance, current est deja sur la borne de statement (juste
         * apres le '}') : on NE rappelle PAS window_skip_to_next_stmt, qui en
         * re-traversant un newline laisserait le classifieur du corps sans le
         * crossedNewline attendu pour dispatcher correctement le widget suivant. */
        if (check(TOKEN_LEFT_BRACE)) {
            int depth = 0;
            do {
                if (check(TOKEN_LEFT_BRACE)) depth++;
                else if (check(TOKEN_RIGHT_BRACE)) depth--;
                advance_token();
            } while (depth > 0 && !check(TOKEN_EOF));
        } else {
            window_skip_to_next_stmt();
        }
        /*  : resync propre sur la prop suivante — rearmer le
         * reporting (cf. chemin cascade ci-dessus). */
        if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
        return;
    }

    /* Pour les enums, valider la reference identifier d'abord. */
    if (!window_validate_enum_ref(def)) {
        free(propName);
        window_skip_to_next_stmt();
        return;
    }

    /*  : valeur nue chaine-sans-guillemets au niveau Fenetre (symetrie
     * stricte avec control_parse_property_init). Diagnostic clair + resync. */
    if (dsl_prop_value_is_bare_words(def)) {
        owl_emit_error_at(&propTok, E_SEM_DSL_PROP_VALUE_BARE_WORDS,
                          "prop", propName, NULL);
        free(propName);
        window_skip_to_next_stmt();
        return;
    }

    Token valTok = parser.current;
    Value v;
    int line = propTok.line;

    /*  : litteral inline dict `{...}` au niveau Fenetre.
     * Cf. control_parse_property_init pour la rationale (meme logique). */
    if (def && check(TOKEN_LEFT_BRACE)) {
        if (def->type == OWL_PROP_TYPE_MULTILINGUE) {
            g_inline_target_type     = "cha\xc3\xae" "neMultilingue";
            g_inline_target_type_len = (int)strlen("cha\xc3\xae" "neMultilingue");
            char fnNameBuf[160];
            snprintf(fnNameBuf, sizeof(fnNameBuf), "__win_prop_%s", propName);
            ObjFunction* eval = compile_expression_as_fn(fnNameBuf);
            if (decl) {
                owl_window_decl_add_property(decl, propName, NIL_VAL, eval, false, line);
            }
            free(propName);
            return;
        }
        if (def->type == OWL_PROP_TYPE_VARIANT) {
            /*  — symetrique de control_parse_property_init pour les
             * props Fenetre de type variant qui accepteraient une Icone. */
            char fnNameBuf[160];
            snprintf(fnNameBuf, sizeof(fnNameBuf), "__win_prop_%s", propName);
            ObjFunction* eval = compile_icone_brace_literal_as_fn(fnNameBuf);
            if (decl) {
                owl_window_decl_add_property(decl, propName, NIL_VAL, eval, false, line);
            }
            free(propName);
            return;
        }
        if (def->type == OWL_PROP_TYPE_COLOR) {
            /*  (L3.6) — littéral couleur inline `{ Rouge=…, Opacité=…}`
             * posé DIRECTEMENT en PROPRIETES sur un slot couleur : cible le
             * type composé Couleur (symétrique du slot MULTILINGUE et du SET
             * direct L3.5). Le littéral produit une instance Couleur consommée
             * au rendu par owl_value_to_color / instance_get_color. */
            g_inline_target_type     = "Couleur";
            g_inline_target_type_len = 7;
            char fnNameBuf[160];
            snprintf(fnNameBuf, sizeof(fnNameBuf), "__win_prop_%s", propName);
            ObjFunction* eval = compile_expression_as_fn(fnNameBuf);
            if (decl) {
                owl_window_decl_add_property(decl, propName, NIL_VAL, eval, false, line);
            }
            free(propName);
            return;
        }
        if (def->type != OWL_PROP_TYPE_ENUM
            && def->type != OWL_PROP_TYPE_OBJECT) {
            owl_emit_error_at(&parser.current, E_SEM_DSL_INLINE_DICT_NOT_MULTILINGUE,
                              "prop", def->nameFR,
                              "type", owl_prop_type_name(def->type),
                              NULL);
            window_skip_to_next_stmt();
            free(propName);
            return;
        }
    }

    /*  : capturer AVANT folding si le token est une constante membre
     * de l'enum_base d'une prop STRING (ex: PoliceNom = iPoliceArial). */
    bool stringEnumMember = window_string_enum_member_token(def);

    Scanner saved        = parser.scanner;
    Token   savedCur     = parser.current;
    Token   savedPrev    = parser.previous;
    bool    savedCrossed = crossedNewline;

    /*  : le const-folder s'arrete au premier atome non foldable et
     * rollback le reste (ex: `"a" + RC + "b"` folde `"a"` puis rend `+ RC ...`).
     * Une valeur pleinement constante laisse le curseur sur un terminateur de
     * propriete (newline traverse, FIN, EOF) ; un reliquat d'operateur sur la
     * meme ligne signale une expression composee -> chemin dynamique (parite
     * avec l'imperatif `..Prop = <expr>`). Meme garde qu'au site metadonnees
     * projet. */
    if (window_try_parse_const_literal(&v)
        && (crossedNewline || check(TOKEN_FIN) || check(TOKEN_EOF))) {
        if (stringEnumMember || window_check_value_type(def, v, &valTok)) {
            if (decl) {
                owl_window_decl_add_property(decl, propName, v, NULL, true, line);
            }
        }
    } else {
        /* V1.5-A : expression dynamique compilee comme eval. */
        parser.scanner = saved;
        parser.current = savedCur;
        parser.previous = savedPrev;
        crossedNewline = savedCrossed;
        const char* inlineTarget = prop_inline_target_type(def);
        if (inlineTarget &&
            (check(TOKEN_LEFT_BRACE) || check(TOKEN_LEFT_BRACKET))) {
            /* `{` direct OU `[ {...} ]` (array de braces) : array_literal
             * propage le target a chaque element. */
            g_inline_target_type     = inlineTarget;
            g_inline_target_type_len = (int)strlen(inlineTarget);
        }
        char fnNameBuf[160];
        snprintf(fnNameBuf, sizeof(fnNameBuf), "__win_prop_%s", propName);
        ObjFunction* eval = compile_expression_as_fn(fnNameBuf);
        if (decl) {
            owl_window_decl_add_property(decl, propName, NIL_VAL, eval, false, line);
        }
    }
    free(propName);
}

/*  — detecte une valeur de propriete DSL malformee du type "chaine
 * ecrite sans guillemets, en plusieurs mots" (ex: `Bulle = ma bulle`,
 * `Bulle = Info bouton`). Sans ce garde, la valeur nue part sur le chemin
 * expression dynamique : le premier mot compile en lecture de variable
 * inconnue ("'ma' : variable inconnue") et les mots restants desynchronisent
 * la boucle PROPRIETES, ce qui fait cascader des diagnostics trompeurs
 * ("propriete Visible non supportee", "Bloc PROPRIETES manquant") sur les
 * lignes suivantes pourtant valides.
 *
 * Signal SUR : IDENT suivi, sur la MEME ligne, d'un second atome-mot/litteral
 * sans operateur intercale. Deux atomes colles ne forment JAMAIS une
 * expression OWL valide, quel que soit le type de la prop -> aucun faux
 * positif possible.
 *
 * Volontairement NON capture (reste sur le chemin dynamique, message
 * "variable inconnue" conserve) : le mot nu UNIQUE (`Bulle = maBulle`). Un
 * identifiant seul est indistinguable a ce stade d'une reference variable
 * legitime — `Bulle = gTexte` ou gTexte est une variable fenetre COMPILE (sa
 * resolution passe par des mecanismes que is_known_global_name ne couvre pas
 * a ce point du parse) ; le rejeter introduirait un faux positif sur du code
 * valide. "variable inconnue" reste correct, localise sur la bonne ligne, et
 * sans cascade.
 *
 * Autres cas non captures (valides) : expression composee (`Bulle = "a" +
 * gTexte`), appel/acces membre/index (`f(x)`, `a..b`, `t[0]`), constante
 * membre d'enum-string (`PoliceNom = iPoliceArial`). Peek pur : aucun token
 * consomme. */
static bool dsl_prop_value_is_bare_words(const OwlControlPropDef* def) {
    (void)def;
    if (!check(TOKEN_IDENTIFIER)) return false;

    Scanner ss = parser.scanner;
    Token   sc = parser.current;
    Token   sp = parser.previous;
    bool    sn = crossedNewline;

    advance_token();  /* consume le 1er mot */

    bool bare = false;
    if (!crossedNewline && !check(TOKEN_EOF)) {
        /* Second atome-mot/litteral colle sur la meme ligne. Les litterals
         * sont contigus dans l'enum (TOKEN_INTEGER..MULTILINE), plus
         * l'identifiant et les mots-cles-widget nus (bouton/libelle/saisie/etat). */
        TokenType t = parser.current.type;
        if (t == TOKEN_IDENTIFIER
            || (t >= TOKEN_INTEGER && t <= TOKEN_MULTILINE_STRING)
            || t == TOKEN_BOUTON || t == TOKEN_LIBELLE
            || t == TOKEN_SAISIE || t == TOKEN_ETAT) {
            bare = true;
        }
    }

    parser.scanner = ss;
    parser.current = sc;
    parser.previous = sp;
    crossedNewline = sn;
    return bare;
}

/*  — valeur de propriete DSL ABSENTE apres le '=' : un retour a la
 * ligne (ou FIN/EOF) suit immediatement, avant toute valeur-expression (ex :
 * `Bulle =` seul sur sa ligne). Sans ce garde, le parseur part sur le chemin
 * expression et avale le NOM de la propriete suivante comme valeur -> le
 * diagnostic mensonger "variable inconnue" tombe sur la LIGNE SUIVANTE (et
 * cascade sur les props valides d'apres). A appeler juste apres avoir consomme
 * le '='. Si vrai : emet E_SYNTAX_PROP_VALUE_MISSING localise sur le nom de
 * propriete et NE CONSOMME AUCUN token -> la prop suivante se parse
 * normalement (recovery sans cascade). Le nom rapporte est la forme brute du
 * token (accents conserves). Une valeur presente sur la meme ligne (litteral,
 * variable, expression, `{...}`) laisse crossedNewline faux -> pas de faux
 * positif ; les valeurs DSL sont mono-ligne (le const-folder utilise deja le
 * newline comme terminateur). */
static bool dsl_prop_value_missing_reported(Token* propTok) {
    if (!(crossedNewline || check(TOKEN_FIN) || check(TOKEN_EOF))) return false;
    char propRaw[128];
    int rawLen = propTok->length < 127 ? propTok->length : 127;
    if (rawLen < 0) rawLen = 0;
    memcpy(propRaw, propTok->start, (size_t)rawLen);
    propRaw[rawLen] = '\0';
    owl_emit_error_at(propTok, E_SYNTAX_PROP_VALUE_MISSING,
                      "prop", propRaw, NULL);
    return true;
}

/* Parse une init de propriete au niveau d'un sous-champ. Memes regles
 * que window_parse_property_init mais append dans control->properties.
 * Accepte aussi les tokens-keyword Libelle/Bouton/Saisie comme nom de
 * propriete : un Bouton a une propriete "Libelle = ..." par exemple. */
/*  — le token est-il la propriete d'attache `MenuContextuel` /
 * `ContextMenu` (accent + casse insensibles) ? Ce n'est pas une propriete de
 * valeur (aucun slot runtime, aucune entree catalogue) : c'est le choix de
 * l'arbre de menu contextuel qui s'applique au clic droit. Definie plus bas ;
 * utilisee des window_parse_property_init. */
static bool prop_is_context_menu_attach(Token t) {
    if (t.type != TOKEN_IDENTIFIER || t.start == NULL) return false;
    char buf[64];
    int n = scanner_strip_accents(t.start, t.length, buf, sizeof(buf));
    if (n <= 0 || n >= (int)sizeof(buf)) return false;
    buf[n] = '\0';
    return strcasecmp(buf, "MenuContextuel") == 0
        || strcasecmp(buf, "ContextMenu") == 0;
}

/*  — le token est-il la propriete d'attache `MenuLoupe` /
 * `MagnifierMenu` (accent + casse insensibles) ? Meme regime que
 * prop_is_context_menu_attach mais cible le menu de la LOUPE d'un Champ Table
 * (clic droit sur l'en-tete de colonne). Propriete d'attache distincte de
 * MenuContextuel (menu du corps) : les deux coexistent sur une meme Table. */
static bool prop_is_magnifier_menu_attach(Token t) {
    if (t.type != TOKEN_IDENTIFIER || t.start == NULL) return false;
    char buf[64];
    int n = scanner_strip_accents(t.start, t.length, buf, sizeof(buf));
    if (n <= 0 || n >= (int)sizeof(buf)) return false;
    buf[n] = '\0';
    return strcasecmp(buf, "MenuLoupe") == 0
        || strcasecmp(buf, "MagnifierMenu") == 0;
}

/*  — style typé du Champ Onglet : parseurs définis plus bas (avec la
 * famille menu_parse_style_*), déclarés ici car appelés depuis
 * control_parse_property_init. */
static bool menu_style_tok_is(Token t, const char* a, const char* b);
static void onglet_parse_style_inline(OwlControlDecl* ctrl);
static void onglet_parse_style_statement(OwlControlDecl* ctrl);

/*  — le parser est sur le `=` d'un `Style = ...` (Champ Onglet,
 * MenuPrincipal, MenuContextuel) : la valeur qui suit est-elle un littéral
 * `{ ... }` (parseur dédié, slots plats) ou une référence/expression (chemin
 * générique) ? Peek non destructif : snapshot/restore scanner, même patron que
 * dsl_prop_value_is_bare_words. */
static bool dsl_style_rhs_is_brace_literal(void) {
    Scanner ss = parser.scanner;
    Token   sc = parser.current;
    Token   sp = parser.previous;
    bool    sn = crossedNewline;

    advance_token();                     /* consume `=` */
    bool brace = check(TOKEN_LEFT_BRACE);

    parser.scanner  = ss;
    parser.current  = sc;
    parser.previous = sp;
    crossedNewline  = sn;
    return brace;
}

static void control_parse_property_init(OwlControlDecl* control) {
    if (!check(TOKEN_IDENTIFIER)
        && !check(TOKEN_LIBELLE)
        && !check(TOKEN_BOUTON)
        && !check(TOKEN_SAISIE)
        /*  : `etat`/`report` sont des mots-cles DSL de declaration
         * de fichier Etat, mais `Etat` est aussi une propriete unifiee de
         * controle (Actif/AffichageSeulement/Grise/Invisible). En position
         * nom-de-propriete d'un bloc PROPRIETES on l'accepte comme identifiant
         * (cf. invariant 5 : nom a double role resolu par le contexte). */
        && !check(TOKEN_ETAT)) {
        owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_PROP_NAME_CONTROL);
        advance_token();
        return;
    }
    Token propTok = parser.current;
    advance_token();

    /*  — `MenuContextuel = <nom>` : attache d'un menu contextuel au
     * champ. Interceptee avant le lookup catalogue (ce n'est pas une prop de
     * valeur). Le nom est resolu de maniere differee a la fermeture du body
     * fenetre (le bloc MenuContextuel peut etre declare apres le champ). */
    if (control && prop_is_context_menu_attach(propTok)) {
        if (!match_token(TOKEN_EQUAL) || !check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&propTok, E_SEM_CTXMENU_ASSIGN_EXPECTED_NAME, NULL);
            window_skip_to_next_stmt();
            if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
            return;
        }
        Token valTok = parser.current;
        advance_token();
        if (control->context_menu_name != NULL) {
            owl_emit_error_at(&propTok, E_SEM_CTXMENU_ASSIGN_DUPLICATE,
                              "name", control->context_menu_name, NULL);
            if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
            return;
        }
        char nameBuf[128];
        int vl = valTok.length < 127 ? valTok.length : 127;
        memcpy(nameBuf, valTok.start, (size_t)vl);
        nameBuf[vl] = '\0';
        owl_control_decl_set_context_menu(control, nameBuf, valTok.line);
        return;
    }

    /*  — `MenuLoupe = <nom>` : attache du menu de la loupe (clic droit
     * sur l'en-tete de colonne) d'un Champ Table. Meme mecanique differee que
     * MenuContextuel, mais RESERVEE au Champ Table (le catalogue ne publie
     * MenuLoupe que sur PROPS_TABLE) : sur un autre kind, on ne l'intercepte
     * pas -> le nom retombe sur le lookup catalogue -> prop inconnue (contrat
     * catalogue applique, cf. dsl-parser-guards §3). */
    if (control && control->kind == OWL_CONTROL_TABLE
        && prop_is_magnifier_menu_attach(propTok)) {
        if (!match_token(TOKEN_EQUAL) || !check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&propTok, E_SEM_CTXMENU_ASSIGN_EXPECTED_NAME, NULL);
            window_skip_to_next_stmt();
            if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
            return;
        }
        Token valTok = parser.current;
        advance_token();
        if (control->magnifier_menu_name != NULL) {
            owl_emit_error_at(&propTok, E_SEM_CTXMENU_ASSIGN_DUPLICATE,
                              "name", control->magnifier_menu_name, NULL);
            if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
            return;
        }
        char nameBuf[128];
        int vl = valTok.length < 127 ? valTok.length : 127;
        memcpy(nameBuf, valTok.start, (size_t)vl);
        nameBuf[vl] = '\0';
        owl_control_decl_set_magnifier_menu(control, nameBuf, valTok.line);
        return;
    }

    /*  — propriété `Style` d'un Champ Onglet (styleOnglet) : racine
     * (fond du pane) + sous-éléments VoletActif/VoletInactif. Interceptée avant
     * le lookup catalogue pour les deux formes const-foldées vers les slots
     * plats : statement `Style..X..Y = v` et inline `Style = { ... }`, même
     * mécanique que le style menu.
     *
     *  — la forme REFERENCE `Style = theme.<nom>` (ou `= STY_<nom>`, ou
     * toute expression) N'est PAS interceptée : elle retombe sur le chemin
     * OBJECT générique du catalogue (Onglet.Style porte object_type
     * "styleOnglet"), exactement comme les autres champs stylés. Le runtime
     * compose alors l'instance résolue (base) avec les slots plats (surcharge).
     * Une affectation de la propriété ENTIÈRE remet les slots plats à zéro :
     * canon  « ..sous = Y puis Style = X -> X gagne (reset) ». */
    if (control && control->kind == OWL_CONTROL_ONGLET
        && menu_style_tok_is(propTok, "Style", NULL)) {
        if (check(TOKEN_DOUBLE_DOT)) {
            advance_token();  /* consume .. */
            onglet_parse_style_statement(control);
            return;
        }
        if (!check(TOKEN_EQUAL)) {
            owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        if (dsl_style_rhs_is_brace_literal()) {
            onglet_parse_style_inline(control);
            return;
        }
        owl_control_decl_reset_onglet_style(control);
        /* pas de `return` : le chemin catalogue générique prend la main. */
    }

    /*  : `Prop[etat]..SousChamp = valeur` en PROPRIETES declaratif
     * (ex Style[focus]..CouleurFond = ...). Le `[etat]` n'est valide que sur
     * une prop de type style (styleSaisie) ; sinon erreur (pas d'indexation
     * tableau en declaratif). Le slot d'etat est injecte comme premier niveau
     * de la cascade (merge avec les autres ecritures du meme etat). */
    if (check(TOKEN_LEFT_BRACKET) && control) {
        char propAsciiS[128];
        int pl = scanner_strip_accents(propTok.start, propTok.length,
                                       propAsciiS, sizeof(propAsciiS));
        if (pl <= 0) pl = propTok.length < 127 ? propTok.length : 127;
        propAsciiS[pl] = '\0';
        const OwlControlPropDef* sdef =
            owl_control_catalog_find(control->kind, propAsciiS);
        const StylePalette* pal =
            (sdef && sdef->type == OWL_PROP_TYPE_OBJECT && sdef->object_type)
                ? style_palette_for_type(sdef->object_type,
                                         (int)strlen(sdef->object_type))
                : NULL;
        if (pal == NULL) {
            owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
            window_skip_to_next_stmt();
            return;
        }
        advance_token(); /* consume '[' */
        Token stateTok = parser.current;
        advance_token(); /* consume state token */
        consume(TOKEN_RIGHT_BRACKET, E_SYNTAX_EXP_RBRACKET_STYLE_STATE);
        const char* slot = NULL;
        if (stateTok.type >= TOKEN_IDENTIFIER && stateTok.type < TOKEN_NEWLINE) {
            slot = style_state_slot(pal, stateTok.start, stateTok.length);
        }
        if (slot == NULL) {
            char stateBuf[64];
            int sn = stateTok.length < 63 ? stateTok.length : 63;
            if (sn < 0) sn = 0;
            memcpy(stateBuf, stateTok.start, (size_t)sn);
            stateBuf[sn] = '\0';
            char listBuf[128];
            style_states_list(pal, listBuf, sizeof(listBuf));
            owl_emit_error_at(&stateTok, E_SEM_STYLE_STATE_INVALID,
                              "state", stateBuf,
                              "type", sdef->object_type,
                              "states", listBuf,
                              NULL);
            window_skip_to_next_stmt();
            return;
        }
        if (!check(TOKEN_DOUBLE_DOT)) {
            /* Phase 1 : seule la forme granulaire Style[etat]..Champ est
             * supportee en declaratif (l'affectation complete = unStyle passe
             * par le code). */
            owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
            window_skip_to_next_stmt();
            return;
        }
        if (g_cascade_buffer) {
            cascade_buffer_capture(g_cascade_buffer, propTok,
                                    propAsciiS, pl,
                                    sdef->object_type,
                                    (int)strlen(sdef->object_type), slot);
            return;
        }
        owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
        window_skip_to_next_stmt();
        return;
    }

    /*  : cascade declarative `Prop..SousChamp [..SousChamp]* = valeur`.
     * Equivalent a `Prop = { SousChamp = valeur }`. Detectee AVANT le check
     * `=` (qui rejetterait `..`). Reservee aux props composees (OBJECT).
     *  : si un buffer cascade est actif (bloc PROPRIETES), bufferise
     * pour regroupement compile-time avec les autres cascades homonymes. */
    if (check(TOKEN_DOUBLE_DOT) && control) {
        char propAsciiC[128];
        int pl = scanner_strip_accents(propTok.start, propTok.length,
                                       propAsciiC, sizeof(propAsciiC));
        if (pl <= 0) pl = propTok.length < 127 ? propTok.length : 127;
        propAsciiC[pl] = '\0';
        const OwlControlPropDef* cdef = owl_control_catalog_find(control->kind, propAsciiC);
        if (!cdef) {
            const char* kindName = owl_control_kind_name(control->kind);
            owl_emit_error_at(&propTok, E_SEM_DSL_PROP_UNKNOWN_FOR_KIND,
                              "prop", propAsciiC, "kind", kindName, NULL);
            window_skip_to_next_stmt();
            /*  : resync propre sur la prop suivante — rearmer le
             * reporting pour ne pas avaler l'erreur de la prochaine prop
             * inconnue du meme bloc (panicMode arme par l'emit ci-dessus).
             * On ne rearme QUE si une autre prop suit vraiment : a la
             * frontiere du bloc (FIN/EOF), preserver l'etat panic pour ne
             * pas relancer la cascade downstream (bloc jumeau hors-scope). */
            if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
            return;
        }
        if (cdef->type != OWL_PROP_TYPE_OBJECT || !cdef->object_type) {
            owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
            window_skip_to_next_stmt();
            return;
        }
        /* Invariant : g_cascade_buffer est toujours actif ici. Toute prop DSL
         * (donc toute cascade `..`) est parsee dans un bloc PROPRIETES qui ouvre
         * ce buffer ; il n'existe pas de chemin d'entree hors buffer. La cascade
         * est bufferisee pour regroupement compile-time des cascades homonymes. */
        cascade_buffer_capture(g_cascade_buffer, propTok,
                               propAsciiC, pl,
                               cdef->object_type,
                               (int)strlen(cdef->object_type), NULL);
        return;
    }

    if (!match_token(TOKEN_EQUAL)) {
        owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
        return;
    }
    if (dsl_prop_value_missing_reported(&propTok)) return;

    /* Phase G v2 fix : normaliser le nom de prop en accent-stripped pour
     * que le runtime (build_control) puisse le retrouver via strcasecmp.
     * Sans ca 'Libellé' (UTF-8) vs 'Libelle' (recherche runtime) ne
     * matchaient pas → libellé invisible sur le bouton. */
    char propAscii[128];
    int propAsciiLen = scanner_strip_accents(propTok.start, propTok.length,
                                              propAscii, sizeof(propAscii));
    if (propAsciiLen <= 0) propAsciiLen = propTok.length < 127 ? propTok.length : 127;
    char* propName = (char*)malloc((size_t)propAsciiLen + 1);
    memcpy(propName, propAscii, propAsciiLen);
    propName[propAsciiLen] = '\0';

    /* Phase D : lookup dans le catalogue selon le kind du champ. */
    const OwlControlPropDef* def = NULL;
    if (control) {
        def = owl_control_catalog_find(control->kind, propName);
        if (!def) {
            const char* kindName = owl_control_kind_name(control->kind);
            owl_emit_error_at(&propTok, E_SEM_DSL_PROP_UNKNOWN_FOR_KIND,
                              "prop", propName,
                              "kind", kindName,
                              NULL);
            free(propName);
            window_skip_to_next_stmt();
            /*  : resync propre sur la prop suivante — rearmer le
             * reporting (cf. chemin cascade ci-dessus). */
            if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
            return;
        }
        if (!window_validate_enum_ref(def)) {
            free(propName);
            window_skip_to_next_stmt();
            return;
        }
        /*  — mémoriser la position d'une borne de valeur numérique
         * (BorneMax/BorneMin, tout alias) pour un warning cross-prop différé :
         * la vérification a besoin de l'InputType effectif, qui peut être
         * déclaré APRÈS la borne dans le bloc. Présence suffit (la valeur
         * n'entre pas dans le diagnostic). Non-borné par kind ici : le filtre
         * Champ Saisie est appliqué à l'émission différée. */
        if (def->nameFR && strcmp(def->nameFR, "BorneMax") == 0) {
            control->bound_max_line = propTok.line;
            control->bound_max_col  = propTok.column;
        } else if (def->nameFR && strcmp(def->nameFR, "BorneMin") == 0) {
            control->bound_min_line = propTok.line;
            control->bound_min_col  = propTok.column;
        }
    }

    /*  (volet A) — `Options = [` avec `[` en fin de ligne : le scanner a
     * lu un TOKEN_MULTILINE_STRING (chaine multi-ligne), pas un litteral tableau.
     * Sans ce garde la chaine etait avalee en silence par build_control (IS_ARRAY
     * echoue) -> widget vide (Occurrence = 0), aucun diagnostic. Meme code que le
     * garde `X est un tableau = [` de , ancre sur la ligne de la prop. */
    if (dsl_prop_expects_array(def) && check(TOKEN_MULTILINE_STRING)) {
        owl_emit_error_at(&propTok, E_SYNTAX_TABLEAU_INIT_MULTILIGNE, NULL);
        free(propName);
        window_skip_to_next_stmt();
        if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
        return;
    }

    /*  : valeur nue de type chaine-sans-guillemets. Diagnostic clair
     * sur la ligne de la prop + resync propre (skip a la prop suivante), au
     * lieu de la cascade trompeuse du chemin expression dynamique. */
    if (dsl_prop_value_is_bare_words(def)) {
        owl_emit_error_at(&propTok, E_SEM_DSL_PROP_VALUE_BARE_WORDS,
                          "prop", propName, NULL);
        free(propName);
        window_skip_to_next_stmt();
        return;
    }

    /*  — genre de style incompatible en PROPRIETES : `Style = <style
     * d'un autre genre>` (theme.<nom> ou STY_ global). Le champ n'accepte que le
     * styleXxx correspondant a son genre. Verifie AVANT la compilation de la
     * valeur ; parser.current pointe le debut de la RHS. */
    if (control && def && def->type == OWL_PROP_TYPE_OBJECT && def->object_type
        && is_style_type_name(def->object_type)) {
        char styleGot[64];
        char styleDesig[160];
        if (style_rhs_resolve_type(styleGot, sizeof(styleGot),
                                   styleDesig, sizeof(styleDesig))
            && !is_base_style_type_name(styleGot)
            && !style_type_names_equal(def->object_type, styleGot)) {
            owl_emit_error_at(&parser.current, E_SEM_STYLE_KIND_MISMATCH,
                              "field", control->name,
                              "kind", owl_control_kind_name_fr(control->kind),
                              "expected", def->object_type,
                              "style", styleDesig,
                              "got", styleGot,
                              NULL);
            free(propName);
            window_skip_to_next_stmt();
            return;
        }
        /*  — nom de style inconnu du projet : avertissement, la
         * compilation continue (le runtime a son propre message). */
        Token unknownTok;
        if (style_rhs_theme_ref_undeclared(&unknownTok)) {
            char nameBuf[128];
            snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                     unknownTok.length, unknownTok.start);
            owl_emit_warning_at(&unknownTok, W_SEM_THEME_STYLE_UNDECLARED,
                                "nom", nameBuf, NULL);
        }
    }

    Token valTok = parser.current;
    Value v;
    int line = propTok.line;

    /*  — capture de la propriete Valeur (volet actif) d'un Champ
     * Onglet. On memorise le litteral entier + la position du token pour borner
     * la valeur contre le nombre de volets une fois le body parse (le compte de
     * volets n'est connu qu'a la fin du body). Litteral entier uniquement : une
     * expression dynamique ne peut pas etre bornee au compile-time. */
    if (control && control->kind == OWL_CONTROL_ONGLET
        && (strcasecmp(propName, "Valeur") == 0
            || strcasecmp(propName, "Value") == 0)
        && check(TOKEN_INTEGER)) {
        char nb[32];
        int nl = valTok.length < 31 ? valTok.length : 31;
        memcpy(nb, valTok.start, (size_t)nl);
        nb[nl] = '\0';
        control->ong_valeur_set  = true;
        control->ong_valeur      = strtol(nb, NULL, 10);
        control->ong_valeur_line = valTok.line;
        control->ong_valeur_col  = valTok.column;
    }

    /*  : litteral inline dict `{...}` dans PROPRIETES.
     * Trois cas selon le type du slot :
     *   - chaineMultilingue : tag g_inline_target_type pour que
     *     instance_literal route vers la bifurcation  lot B
     *     (__MultilingueNew + ARRAY_SET sur chaque entry).
     *   - enum avec allowedBase (ex: Cadre) : deja gere plus bas
     *     (branchement existant g_inline_target_type = def->enum_name).
     *   - autre (entier, chaine, bool, ...) : erreur compile propre.
     *     Avant ce fix, on tombait dans compile_expression_as_fn ->
     *     instance_literal sans target type -> segfault dans certains
     *     cas (string-libre `{"fr": ...}` notamment).
     */
    if (def && check(TOKEN_LEFT_BRACE)) {
        if (def->type == OWL_PROP_TYPE_MULTILINGUE) {
            /* OK : route directement vers compile_expression_as_fn avec
             * target type tagge. Le try_const_literal ne sait pas parser
             * un dict, donc on saute cette etape. */
            g_inline_target_type     = "cha\xc3\xae" "neMultilingue";
            g_inline_target_type_len = (int)strlen("cha\xc3\xae" "neMultilingue");
            char fnNameBuf[160];
            snprintf(fnNameBuf, sizeof(fnNameBuf), "__ctrl_prop_%s", propName);
            ObjFunction* eval = compile_expression_as_fn(fnNameBuf);
            if (control) {
                owl_control_decl_add_property(control, propName, NIL_VAL, eval, false, line);
            }
            free(propName);
            return;
        }
        if (def->type == OWL_PROP_TYPE_VARIANT) {
            /*  — slot variant qui accepte une Icone (Image sur
             * Bouton / Champ Image / etc.). Le brace literal `{icones.X,
             * Couleur = ..., ...}` part du meme parseur que la forme
             * variable `ICN est une Icone = {...}`. Sans ce branchement, le
             * `,` apres `icones.X` est consomme comme scope d'indirection
             * canon `{expr, scope}` et `Couleur = ...` retombait sur
             * reject_type_assignment ("Affectation a un nom de type
             * interdite."). */
            char fnNameBuf[160];
            snprintf(fnNameBuf, sizeof(fnNameBuf), "__ctrl_prop_%s", propName);
            ObjFunction* eval = compile_icone_brace_literal_as_fn(fnNameBuf);
            if (control) {
                owl_control_decl_add_property(control, propName, NIL_VAL, eval, false, line);
            }
            free(propName);
            return;
        }
        if (def->type == OWL_PROP_TYPE_COLOR) {
            /*  (L3.6) — cf. window_parse_property_init : littéral
             * couleur inline en PROPRIETES sur un slot couleur -> type composé
             * Couleur. */
            g_inline_target_type     = "Couleur";
            g_inline_target_type_len = 7;
            char fnNameBuf[160];
            snprintf(fnNameBuf, sizeof(fnNameBuf), "__ctrl_prop_%s", propName);
            ObjFunction* eval = compile_expression_as_fn(fnNameBuf);
            if (control) {
                owl_control_decl_add_property(control, propName, NIL_VAL, eval, false, line);
            }
            free(propName);
            return;
        }
        if (def->type != OWL_PROP_TYPE_ENUM
            && def->type != OWL_PROP_TYPE_OBJECT) {
            /* Slot non-multilingue : rejet propre. */
            owl_emit_error_at(&parser.current, E_SEM_DSL_INLINE_DICT_NOT_MULTILINGUE,
                              "prop", def->nameFR,
                              "type", owl_prop_type_name(def->type),
                              NULL);
            window_skip_to_next_stmt();
            free(propName);
            return;
        }
    }

    /*  : capturer AVANT folding si le token est une constante membre
     * de l'enum_base d'une prop STRING (ex: PoliceNom = iPoliceArial). */
    bool stringEnumMember = window_string_enum_member_token(def);

    /* Snapshot scanner pour pouvoir revenir et compiler l'expression
     * dynamique si le literal echoue. */
    Scanner saved        = parser.scanner;
    Token   savedCur     = parser.current;
    Token   savedPrev    = parser.previous;
    bool    savedCrossed = crossedNewline;

    /* Lot V1.5-A : tentative literal d'abord (const-folding). Si echec,
     * on compile l'expression en bytecode eval (ObjFunction 0-arg). Le
     * runtime build_control execute eval puis fait set_prop avec le
     * resultat. Pattern reuse de etat_label_parse_property_init. */
    /*  : cf. window_parse_property_init. Une valeur composee (`"a" + RC
     * + "b"`, `100 + 25` non entierement folde, concat de chaines) laisse un
     * reliquat d'operateur sur la meme ligne apres le const-folder ; on bascule
     * alors sur le chemin dynamique (compile_expression_as_fn) au lieu d'accepter
     * un litteral partiel. Parite avec l'imperatif `WIDGET..Prop = <expr>`. */
    if (window_try_parse_const_literal(&v)
        && (crossedNewline || check(TOKEN_FIN) || check(TOKEN_EOF))) {
        if (def && !stringEnumMember && !window_check_value_type(def, v, &valTok)) {
            free(propName);
            /*  : le literal vient d'etre consomme (crossedNewline / FIN
             * / EOF garanti par la condition du if), donc parser.current pointe
             * deja le debut du stmt suivant — PAS de window_skip_to_next_stmt()
             * ici, il avancerait au moins une fois et engloutirait la prop
             * suivante. On se contente de desarmer panicMode si une autre prop
             * suit dans le meme bloc (parite avec les autres chemins d'erreur de
             * cette fonction, ), pour ne pas avaler ses diagnostics.
             * A la frontiere du bloc (FIN/EOF) on preserve l'etat panic : le
             * reset post-PROPRIETES du body widget s'en charge. */
            if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
            return;
        }
        if (control) {
            owl_control_decl_add_property(control, propName, v, NULL, true, line);
        }
    } else {
        /* Restore + compile expression dynamique. Lot inline literal :
         * si la prop a un allowedBase (ex: Cadre), on tag g_inline_target_type
         * pour que `Prop = { ... }` compile en init compose. */
        parser.scanner = saved;
        parser.current = savedCur;
        parser.previous = savedPrev;
        crossedNewline = savedCrossed;

        const char* inlineTarget = prop_inline_target_type(def);
        if (inlineTarget &&
            (check(TOKEN_LEFT_BRACE) || check(TOKEN_LEFT_BRACKET))) {
            /* `{` direct OU `[ {...} ]` (array de braces) : array_literal
             * propage le target a chaque element. */
            g_inline_target_type     = inlineTarget;
            g_inline_target_type_len = (int)strlen(inlineTarget);
        }

        char fnNameBuf[160];
        snprintf(fnNameBuf, sizeof(fnNameBuf), "__ctrl_prop_%s", propName);
        ObjFunction* eval = compile_expression_as_fn(fnNameBuf);
        if (control) {
            owl_control_decl_add_property(control, propName, NIL_VAL, eval, false, line);
        }
    }
    free(propName);
}

/*  — warning cross-prop : une borne de valeur numerique (BorneMax/
 * BorneMin) declaree sur un Champ Saisie dont l'InputType effectif n'est PAS
 * bornable (num / monetaire / num precis) est ignoree en silence au runtime
 * (validateur pose seulement pour ces 3 types, cf. stdlib_ui.c). Appelee apres
 * le parse COMPLET du body du champ : l'ordre BorneMax/InputType dans le bloc
 * est indifferent (positions memorisees pendant le parse, type relu ici).
 *
 * InputType effectif : defaut catalogue = typSaisieTexte (donc un champ sans
 * TypeSaisie mais avec une borne warne — coherent, la borne y reste sans
 * effet). Un InputType dynamique (non const-folde) desarme le diagnostic :
 * pas de faux positif quand le type n'est pas connu au compile-time. */
static void input_emit_bound_not_numeric_warning_if(const OwlControlDecl* control) {
    if (!control || control->kind != OWL_CONTROL_INPUT) return;
    if (control->bound_max_col == 0 && control->bound_min_col == 0) return;

    int64_t inputType = OWL_TYPESAISIE_TEXTE;
    bool typeKnown = true;
    for (int i = 0; i < control->property_count; i++) {
        const char* pn = control->properties[i].name;
        if (pn && (strcasecmp(pn, "TypeSaisie") == 0
                   || strcasecmp(pn, "InputType") == 0)) {
            const OwlPropertyInit* p = &control->properties[i];
            if (p->is_constant && IS_INTEGER(p->const_value)) {
                inputType = AS_INTEGER(p->const_value);
            } else {
                typeKnown = false;
            }
            break;
        }
    }
    if (!typeKnown) return;
    if (inputType == OWL_TYPESAISIE_NUM
        || inputType == OWL_TYPESAISIE_MONETAIRE
        || inputType == OWL_TYPESAISIE_NUM_PRECIS) {
        return; /* borne legitime */
    }

    if (control->bound_max_col != 0) {
        Token t;
        memset(&t, 0, sizeof(t));
        t.type   = TOKEN_IDENTIFIER;
        t.start  = "BorneMax";
        t.length = 8;
        t.line   = control->bound_max_line;
        t.column = control->bound_max_col;
        owl_emit_warning_at(&t, W_SEM_BOUND_MAX_NOT_NUMERIC, NULL);
    }
    if (control->bound_min_col != 0) {
        Token t;
        memset(&t, 0, sizeof(t));
        t.type   = TOKEN_IDENTIFIER;
        t.start  = "BorneMin";
        t.length = 8;
        t.line   = control->bound_min_line;
        t.column = control->bound_min_col;
        owl_emit_warning_at(&t, W_SEM_BOUND_MIN_NOT_NUMERIC, NULL);
    }
}

/* Champ Table V1 — parse une init de propriete au niveau d'une colonne.
 * Memes regles que control_parse_property_init mais append dans la
 * colonne. Pas de lookup catalog en V1 (les 3 props Libelle/Type/Largeur
 * sont lues directement par le runtime). */
static void column_parse_property_init(OwlColumnDecl* col) {
    if (!check(TOKEN_IDENTIFIER)
        && !check(TOKEN_LIBELLE)
        && !check(TOKEN_BOUTON)
        && !check(TOKEN_SAISIE)
        /*  : 'Etat' est un mot-cle DSL (fichier Etat) mais aussi une
         * propriete de colonne (Actif/AffichageSeulement/Grisé). En position
         * nom-de-propriete on l'accepte comme identifiant, symetriquement a
         * control_parse_property_init. */
        && !check(TOKEN_ETAT)) {
        owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_PROP_NAME_COLUMN);
        advance_token();
        return;
    }
    Token propTok = parser.current;
    advance_token();

    /*  — cascade declarative `Style..<sous-element>..<feuille> = valeur`
     * sur le bloc Colonne, symetrique de control_parse_property_init. Le point
     * neuf de l'archi "style sur sous-element" : la Colonne porte son propre
     * bloc de style (styleColonne) qui surcharge le styleTable. Detecte AVANT
     * le check `=` (qui rejetterait `..`). Reservee aux props OBJECT du
     * catalogue Colonne. */
    if (check(TOKEN_DOUBLE_DOT)) {
        char propAsciiC[128];
        int pl = scanner_strip_accents(propTok.start, propTok.length,
                                       propAsciiC, sizeof(propAsciiC));
        if (pl <= 0) pl = propTok.length < 127 ? propTok.length : 127;
        propAsciiC[pl] = '\0';
        const OwlControlPropDef* cdef = owl_dsl_prop_find("Colonne", propAsciiC);
        if (!cdef || cdef->type != OWL_PROP_TYPE_OBJECT || !cdef->object_type) {
            owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
            window_skip_to_next_stmt();
            return;
        }
        /* Invariant : g_cascade_buffer est toujours actif ici. Toute prop DSL
         * (donc toute cascade `..`) est parsee dans un bloc PROPRIETES qui ouvre
         * ce buffer ; il n'existe pas de chemin d'entree hors buffer. La cascade
         * est bufferisee pour regroupement compile-time des cascades homonymes. */
        cascade_buffer_capture(g_cascade_buffer, propTok,
                               propAsciiC, pl,
                               cdef->object_type,
                               (int)strlen(cdef->object_type), NULL);
        return;
    }

    if (!match_token(TOKEN_EQUAL)) {
        owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
        return;
    }
    if (dsl_prop_value_missing_reported(&propTok)) return;
    char propAscii[128];
    int propAsciiLen = scanner_strip_accents(propTok.start, propTok.length,
                                              propAscii, sizeof(propAscii));
    if (propAsciiLen <= 0) propAsciiLen = propTok.length < 127 ? propTok.length : 127;
    char* propName = (char*)malloc((size_t)propAsciiLen + 1);
    memcpy(propName, propAscii, propAsciiLen);
    propName[propAsciiLen] = '\0';

    Value v;
    int line = propTok.line;
    if (window_try_parse_const_literal(&v)) {
        if (col) owl_column_decl_add_property(col, propName, v, NULL, true, line);
    } else {
        owl_emit_warning_at(&propTok,
            W_SEM_PROP_COLUMN_DYNAMIC_NOT_SUPPORTED,
            "prop", propName,
            NULL);
        window_skip_to_next_stmt();
    }
    free(propName);
}

/* Champ Table V1 — parse une declaration de colonne :
 *   COL_X est une colonne PROPRIETES ... FIN FIN
 * Le caller a deja consume 'IDENT est un/une' et on est sur TOKEN_COLONNE.
 * 'control' doit etre OWL_CONTROL_TABLE (verifie par le caller). */
/*  — avertissement non bloquant si le projet a active
 * ActiveAvertissementConventionDeNommage et que le nom d'un champ ne commence
 * pas par le prefixe canonique de son type. Ancre sur le token du nom de champ.
 * NULL info ou type sans prefixe conventionnel (Fenetre, Onglet, sous-blocs)
 * -> noop. */
static void field_check_canonical_prefix(Token nameTok,
                                         const OwlControlKindInfo* info) {
    if (info == NULL || info->canonicalPrefix == NULL) return;
    if (!compiler_projet_active_avertissement_nommage()) return;
    const char* prefix = info->canonicalPrefix;
    int plen = (int)strlen(prefix);
    /* Debut du nom compare au prefixe canon (ASCII, casse-insensible). */
    if (nameTok.length >= plen
        && strncasecmp(nameTok.start, prefix, (size_t)plen) == 0) return;
    char nameBuf[128];
    snprintf(nameBuf, sizeof(nameBuf), "%.*s", nameTok.length, nameTok.start);
    owl_emit_warning_at(&nameTok, W_SEM_FIELD_NONCANONICAL_PREFIX,
                        "nom", nameBuf,
                        "type", info->nameFR,
                        "prefixe", prefix,
                        NULL);
}

static void parse_one_column(OwlControlDecl* control, Token nameTok, int kindLine) {
    advance_token(); /* consume COLONNE */

    /* Allocation du col + ajout au control. */
    char* colName = (char*)malloc((size_t)nameTok.length + 1);
    memcpy(colName, nameTok.start, nameTok.length);
    colName[nameTok.length] = '\0';
    OwlColumnDecl* col = NULL;
    if (control && owl_control_decl_find_column(control, colName) != NULL) {
        owl_emit_error_at(&nameTok, E_SEM_DSL_COLUMN_NAME_DUPLICATE,
                          "name", colName,
                          "table", control->name,
                          NULL);
        free(colName);
        /*  — saute le corps de la colonne en doublon plutot que de le
         * parser sans decl : le parcours des proprietes avec un col NULL
         * desynchronise le comptage des FIN et fait cascader une faute unique
         * en quatre erreurs. Meme sortie que pour un champ en doublon. */
        dsl_skip_block_body();
        parser.panicMode = false;
        return;
    }
    if (control) {
        col = owl_control_decl_add_column(control, colName, kindLine);
    }
    free(colName);

    /*  — prefixe de nommage canonique (opt-in projet) : COL_. */
    field_check_canonical_prefix(nameTok, owl_control_kind_info_by_name("Colonne"));

    /* Body de la colonne : un seul bloc PROPRIETES en V1. */
    bool sawProps = false;
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
        if (check(TOKEN_PROPRIETES)) {
            advance_token();
            if (sawProps) owl_emit_error_current(E_SYNTAX_DUPLICATE_PROPRIETES_COLUMN);
            sawProps = true;
            bool firstProp = true;
            /*  — buffer cascade pour regrouper les ecritures
             * `Style..X..Y` d'une meme colonne (symetrique du bloc control). */
            CascadeBuffer colCascadeBuf;
            cascade_buffer_init(&colCascadeBuf);
            CascadeBuffer* savedCascadeBufCol = g_cascade_buffer;
            g_cascade_buffer = &colCascadeBuf;
            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                while (check(TOKEN_NEWLINE)) advance_token();
                if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
                if (!firstProp && !crossedNewline) {
                    owl_emit_error_current(E_SYNTAX_PROPS_NEED_SEPARATOR);
                }
                firstProp = false;
                column_parse_property_init(col);
            }
            g_cascade_buffer = savedCascadeBufCol;
            cascade_buffer_flush(&colCascadeBuf, CASCADE_FLUSH_COLUMN, col,
                                  "__col_prop");
            cascade_buffer_free(&colCascadeBuf);
            if (check(TOKEN_FIN) && !crossedNewline && !firstProp) {
                owl_emit_error_current(E_SYNTAX_FIN_ON_OWN_LINE);
            }
            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROPRIETES);
        } else {
            owl_emit_error_current(E_SYNTAX_COLUMN_BODY_PROPRIETES_ONLY);
            window_skip_to_next_stmt();
        }
    }
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_COLONNE);
}

/*  — normalise un type de parametre d'event vers sa forme canon FR
 * accent-strip + minuscule, en resolvant le bilingue EN -> FR :
 *   - primitif (`integer`, `string`...) : le scanner collapse deja EN/FR sur
 *     le meme token type, keyword_canonical_uppercase_for rend la forme canon
 *     FR (`entier`, `chaine`...).
 *   - type registry compose (EN ou FR) : owl_registry_type_find resout vers
 *     l'OwlTypeDef et on prend sa forme canon ascii.
 *   - fallback : le texte declare tel quel.
 * outBuf doit faire au moins 32 octets. */
static void event_param_type_canon(Token typeTok, const char* declaredText,
                                    char* outBuf, int outBufSz) {
    char canonBuf[32];
    const char* canon = NULL;

    /* keyword_canonical_uppercase_for couvre les TOKEN_ENTIER/CHAINE/... ; pour
     * les identifiers il retombe sur l'uppercase. On distingue via le token
     * type : si c'est un IDENTIFIER, on passe par le registry bilingue. */
    if (typeTok.type == TOKEN_IDENTIFIER) {
        const OwlTypeDef* td = owl_registry_type_find(declaredText);
        if (td) {
            canon = td->canonicalAscii ? td->canonicalAscii : td->canonical;
        }
    } else {
        canon = keyword_canonical_uppercase_for(typeTok, canonBuf, sizeof(canonBuf));
    }
    if (canon == NULL) canon = declaredText;

    /* accent-strip + lowercase pour comparaison loose. */
    char stripped[32];
    scanner_strip_accents(canon, (int)strlen(canon), stripped, sizeof(stripped));
    int n = (int)strlen(stripped);
    if (n > outBufSz - 1) n = outBufSz - 1;
    for (int i = 0; i < n; i++) outBuf[i] = (char)tolower((unsigned char)stripped[i]);
    outBuf[n] = '\0';
}

/* ====================================================================
 *  — menu classique de fenetre
 *
 * Grammaire (figee) :
 *   MNU_X est un MenuPrincipal
 *       SM_A est un SousMenu
 *           PROPRIETES  Libelle = "&Fichier"  FIN
 *           OPT_A est une OptionMenu
 *               PROPRIETES  Libelle = "&Nouveau"  Raccourci = "Ctrl+N"  FIN
 *               PROCEDURE surSelection() ... FIN
 *           FIN
 *           SEP_1 est un MenuSeparateur FIN
 *       FIN
 *   FIN
 *
 * Politique : aucun ecart n'est avale. Le parse continue toujours (pas de
 * skip du sous-arbre fautif) pour que le fichier remonte TOUTES ses erreurs
 * d'un coup ; seule la validation echoue.
 * ==================================================================== */

typedef enum {
    MENU_KW_NONE = 0,
    MENU_KW_MAIN,
    MENU_KW_CONTEXT,   /*  — MenuContextuel / ContextMenu */
    MENU_KW_SUBMENU,
    MENU_KW_OPTION,
    MENU_KW_SEPARATOR,
} MenuKeyword;

static MenuKeyword menu_keyword_of_token(Token t) {
    if (t.type != TOKEN_IDENTIFIER || t.start == NULL) return MENU_KW_NONE;
    char buf[64];
    int n = scanner_strip_accents(t.start, t.length, buf, sizeof(buf));
    if (n <= 0 || n >= (int)sizeof(buf)) return MENU_KW_NONE;
    buf[n] = '\0';
    if (strcasecmp(buf, "MenuPrincipal")  == 0 ||
        strcasecmp(buf, "MainMenu")       == 0) return MENU_KW_MAIN;
    if (strcasecmp(buf, "MenuContextuel") == 0 ||
        strcasecmp(buf, "ContextMenu")    == 0) return MENU_KW_CONTEXT;
    if (strcasecmp(buf, "SousMenu")       == 0 ||
        strcasecmp(buf, "Submenu")        == 0) return MENU_KW_SUBMENU;
    if (strcasecmp(buf, "OptionMenu")     == 0 ||
        strcasecmp(buf, "MenuOption")     == 0) return MENU_KW_OPTION;
    if (strcasecmp(buf, "MenuSeparateur") == 0 ||
        strcasecmp(buf, "MenuSeparator")  == 0) return MENU_KW_SEPARATOR;
    return MENU_KW_NONE;
}

static OwlMenuNodeKind menu_node_kind_of_keyword(MenuKeyword kw) {
    if (kw == MENU_KW_OPTION)    return OWL_MENU_NODE_OPTION;
    if (kw == MENU_KW_SEPARATOR) return OWL_MENU_NODE_SEPARATOR;
    return OWL_MENU_NODE_SUBMENU;
}

/* `IDENT est un[e] <mot-cle menu>` : reconnaissance sans consommer. Le token
 * courant doit etre l'IDENT de nom. Retourne MENU_KW_NONE si la forme ne
 * correspond pas. */
static MenuKeyword menu_peek_declaration(void) {
    if (!check(TOKEN_IDENTIFIER)) return MENU_KW_NONE;
    Scanner s = parser.scanner;
    Token   c = parser.current, p = parser.previous;
    bool    n = crossedNewline;
    advance_token();               /* IDENT */
    MenuKeyword kw = MENU_KW_NONE;
    if (check(TOKEN_EST)) {
        advance_token();           /* est */
        consume_en_a_an_filler();  /* copule EN `is a/an` */
        kw = menu_keyword_of_token(parser.current);
    }
    parser.scanner = s; parser.current = c; parser.previous = p;
    crossedNewline = n;
    return kw;
}

/* Skip un bloc dont l'en-tete vient d'etre consomme et dont le contenu n'est
 * pas exploitable (bloc inconnu dans un menu). Conservateur : ne compte comme
 * ouvreurs que les mots-cles structurels. */
static void menu_skip_unknown_block(void) {
    int depth = 1;
    while (depth > 0 && !check(TOKEN_EOF)) {
        /*  — source unique. `SI c ALORS instr` ne compte pas. */
        if (!check(TOKEN_FIN)
            && prescan_token_in_depth_table(parser.current.type)
            && parser_depth_delta() > 0) {
            depth++;
        } else if (check(TOKEN_FIN)) {
            depth--;
            if (depth == 0) { advance_token(); return; }
        }
        advance_token();
    }
}

/* Un segment de raccourci est-il un modificateur connu ? */
static bool menu_shortcut_is_modifier(const char* seg, int len) {
    static const char* const MODS[] = {
        "ctrl", "control", "alt", "altgr", "maj", "shift", "cmd", "meta", NULL
    };
    for (int i = 0; MODS[i]; i++) {
        if ((int)strlen(MODS[i]) == len && strncasecmp(seg, MODS[i], (size_t)len) == 0)
            return true;
    }
    return false;
}

/* Un raccourci est une suite de modificateurs separes par '+' suivie d'une
 * touche : "Ctrl+N", "Ctrl+Maj+S", "F5". La touche finale est un mot simple
 * (lettres/chiffres apres suppression des accents). Tout le reste est refuse
 * a la compilation plutot qu'ignore silencieusement au runtime. */
static bool menu_shortcut_is_valid(const char* raw) {
    if (raw == NULL) return false;
    char s[128];
    int n = scanner_strip_accents(raw, (int)strlen(raw), s, sizeof(s));
    if (n <= 0 || n >= (int)sizeof(s)) return false;
    s[n] = '\0';
    int start = 0;
    int segCount = 0;
    for (int i = 0; i <= n; i++) {
        if (i != n && s[i] != '+') continue;
        int len = i - start;
        if (len <= 0) return false;
        bool last = (i == n);
        if (!last) {
            if (!menu_shortcut_is_modifier(s + start, len)) return false;
        } else {
            for (int k = 0; k < len; k++) {
                if (!isalnum((unsigned char)s[start + k])) return false;
            }
        }
        segCount++;
        start = i + 1;
    }
    return segCount >= 1;
}

/* Parse une init de propriete d'un noeud de menu. Meme forme que les autres
 * blocs PROPRIETES (const-folding puis expression dynamique), mais catalogue
 * dedie : un noeud de menu n'accepte que ses propres proprietes. */
static void menu_parse_property_init(OwlMenuNode* node, OwlMenuNodeKind kind) {
    /* `Libellé` (TOKEN_LIBELLE) et `Etat` (TOKEN_ETAT) sont des mots-cles
     * scanner : acceptes en position de nom de propriete, comme dans les blocs
     * widget (cf. parse control). */
    if (!check(TOKEN_IDENTIFIER) && !check(TOKEN_LIBELLE) && !check(TOKEN_ETAT)) {
        owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_PROP_NAME_CONTROL);
        advance_token();
        return;
    }
    Token propTok = parser.current;
    advance_token();

    char propAscii[128];
    int propLen = scanner_strip_accents(propTok.start, propTok.length,
                                        propAscii, sizeof(propAscii));
    if (propLen <= 0) propLen = propTok.length < 127 ? propTok.length : 127;
    propAscii[propLen] = '\0';

    const OwlControlPropDef* def = owl_menu_catalog_find(kind, propAscii);
    if (def == NULL) {
        /* Message : la forme ECRITE par l'utilisateur, pas la forme strippee. */
        char propRaw[128];
        int rl = propTok.length < 127 ? propTok.length : 127;
        memcpy(propRaw, propTok.start, (size_t)rl);
        propRaw[rl] = '\0';
        owl_emit_error_at(&propTok, E_SEM_MENU_PROP_UNKNOWN,
                          "prop", propRaw,
                          "kind", owl_menu_node_kind_name_fr(kind),
                          "allowed", owl_menu_catalog_prop_list(kind),
                          NULL);
        window_skip_to_next_stmt();
        if (!check(TOKEN_FIN) && !check(TOKEN_EOF)) parser.panicMode = false;
        return;
    }

    if (!match_token(TOKEN_EQUAL)) {
        owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
        return;
    }
    if (dsl_prop_value_missing_reported(&propTok)) return;

    int line = propTok.line;
    Token valTok = parser.current;

    /* Litteral inline multilingue `{langueXxx: "..."}` sur Libelle. */
    if (def->type == OWL_PROP_TYPE_MULTILINGUE && check(TOKEN_LEFT_BRACE)) {
        g_inline_target_type     = "cha\xc3\xae" "neMultilingue";
        g_inline_target_type_len = (int)strlen("cha\xc3\xae" "neMultilingue");
        char fnNameBuf[160];
        snprintf(fnNameBuf, sizeof(fnNameBuf), "__menu_prop_%s", propAscii);
        ObjFunction* eval = compile_expression_as_fn(fnNameBuf);
        owl_menu_node_add_property(node, propAscii, NIL_VAL, eval, false, line);
        return;
    }

    Scanner saved        = parser.scanner;
    Token   savedCur     = parser.current;
    Token   savedPrev    = parser.previous;
    bool    savedCrossed = crossedNewline;

    Value v;
    if (window_try_parse_const_literal(&v)
        && (crossedNewline || check(TOKEN_FIN) || check(TOKEN_EOF))) {
        if (!window_check_value_type(def, v, &valTok)) return;
        /* Raccourci : la forme est verifiee des la compilation — un
         * accelerateur malforme ne doit pas etre decouvert au runtime. */
        if (strcasecmp(propAscii, "Raccourci") == 0 && IS_STRING(v)) {
            const char* raw = AS_CSTRING(v);
            if (!menu_shortcut_is_valid(raw)) {
                owl_emit_error_at(&propTok, E_SEM_MENU_SHORTCUT_MALFORMED,
                                  "value", raw, NULL);
                return;
            }
        }
        owl_menu_node_add_property(node, propAscii, v, NULL, true, line);
        return;
    }

    parser.scanner  = saved;
    parser.current  = savedCur;
    parser.previous = savedPrev;
    crossedNewline  = savedCrossed;

    char fnNameBuf[160];
    snprintf(fnNameBuf, sizeof(fnNameBuf), "__menu_prop_%s", propAscii);
    ObjFunction* eval = compile_expression_as_fn(fnNameBuf);
    owl_menu_node_add_property(node, propAscii, NIL_VAL, eval, false, line);
}

static void menu_parse_node(OwlMenuDecl* menu, OwlMenuNode* parent,
                             OwlMenuNodeKind kind, Token nameTok, int line);

/* Parse le contenu commun d'un conteneur de menu (MenuPrincipal ou noeud) :
 * une suite de declarations `NOM est un <kind menu> ... FIN`. `menu` et
 * `parent` designent la destination des enfants (l'un des deux est NULL).
 * `ownerKind` sert aux messages ; `ownerName` idem, NULL au niveau MenuPrincipal.
 * `acceptsChildren` = false quand le conteneur ne peut PAS avoir d'enfants
 * (OptionMenu, MenuSeparateur) : on parse quand meme, mais on refuse. */
static void menu_parse_child_declarations(OwlMenuDecl* menu, OwlMenuNode* parent,
                                           const char* ownerKindName,
                                           const char* ownerName,
                                           bool acceptsChildren) {
    Token nameTok = parser.current;
    int   line    = nameTok.line;
    MenuKeyword kw = menu_peek_declaration();
    OwlMenuNodeKind kind = menu_node_kind_of_keyword(kw);

    char childName[128];
    int cl = nameTok.length < 127 ? nameTok.length : 127;
    memcpy(childName, nameTok.start, (size_t)cl);
    childName[cl] = '\0';

    if (!acceptsChildren) {
        OwlErrorCode code = (strcmp(ownerKindName, "OptionMenu") == 0)
                            ? E_SEM_MENU_OPTION_HAS_CHILDREN
                            : E_SEM_MENU_SEPARATOR_HAS_CHILDREN;
        owl_emit_error_at(&nameTok, code, "name", ownerName ? ownerName : "?", NULL);
        parser.panicMode = false;
    }

    advance_token();              /* IDENT */
    advance_token();              /* est */
    consume_en_a_an_filler();
    advance_token();              /* mot-cle menu */

    OwlMenuNode* node = NULL;
    if (acceptsChildren) {
        /*  — un frere porte deja ce nom : refuser. Un separateur n'a
         * pas de nom adressable (plusieurs SEP_x homonymes sont sans
         * consequence), on ne dedoublonne que ce qui se resout par son nom. */
        const OwlMenuNode* twin =
            (kind == OWL_MENU_NODE_SEPARATOR)
            ? NULL
            : (menu ? owl_menu_children_find(menu->children,
                                             menu->child_count, childName)
                    : owl_menu_children_find(parent->children,
                                             parent->child_count, childName));
        if (twin != NULL) {
            owl_emit_error_at(&nameTok, E_SEM_MENU_NODE_NAME_DUPLICATE,
                              "name", childName,
                              "parent", menu ? menu->name : parent->name,
                              NULL);
            parser.panicMode = false;
        } else {
            node = menu ? owl_menu_decl_add_child(menu, kind, childName, line)
                        : owl_menu_node_add_child(parent, kind, childName, line);
        }
    }
    menu_parse_node(menu, node, kind, nameTok, line);
}

/* Parse le body d'un noeud de menu (apres son en-tete). `node` peut etre NULL
 * quand le noeud a ete refuse (declaration hors contexte) : on parse alors la
 * structure sans rien construire. */
static void menu_parse_node(OwlMenuDecl* menu, OwlMenuNode* node,
                             OwlMenuNodeKind kind, Token nameTok, int line) {
    (void)menu; (void)line;
    char selfName[128];
    int nl = nameTok.length < 127 ? nameTok.length : 127;
    memcpy(selfName, nameTok.start, (size_t)nl);
    selfName[nl] = '\0';
    const char* kindName = owl_menu_node_kind_name_fr(kind);

    bool propertiesSeen = false;
    bool captionSeen    = false;
    const char* lastPos = NULL;

    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        if (parser.current.start == lastPos) { advance_token(); parser.panicMode = false; continue; }
        lastPos = parser.current.start;
        if (parser.panicMode) {
            while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) && !check(TOKEN_EOF)) advance_token();
            parser.panicMode = false;
        }
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;

        if (check(TOKEN_PROPRIETES)) {
            Token propTok = parser.current;
            advance_token();
            if (propertiesSeen) owl_emit_error_at(&propTok, E_SYNTAX_DUPLICATE_PROPRIETES_CONTROL);
            propertiesSeen = true;
            bool firstProp = true;
            const char* lastPropPos = NULL;
            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                while (check(TOKEN_NEWLINE)) advance_token();
                if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
                if (parser.current.start == lastPropPos) { advance_token(); parser.panicMode = false; continue; }
                lastPropPos = parser.current.start;
                if (!firstProp && !crossedNewline) {
                    owl_emit_error_current(E_SYNTAX_PROPS_NEED_SEPARATOR);
                }
                firstProp = false;
                if (check(TOKEN_LIBELLE)) captionSeen = true;
                else if (check(TOKEN_IDENTIFIER)) {
                    char pb[64];
                    int pn = scanner_strip_accents(parser.current.start,
                                                   parser.current.length,
                                                   pb, sizeof(pb));
                    if (pn > 0 && pn < (int)sizeof(pb)) {
                        pb[pn] = '\0';
                        if (strcasecmp(pb, "Libelle") == 0 ||
                            strcasecmp(pb, "Caption") == 0) captionSeen = true;
                    }
                }
                menu_parse_property_init(node, kind);
            }
            if (check(TOKEN_FIN) && !crossedNewline && !firstProp) {
                owl_emit_error_current(E_SYNTAX_FIN_ON_OWN_LINE);
            }
            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROPRIETES);
            /* Le bloc est referme : plus rien a resynchroniser. Laisser le
             * panic arme ici ferait avaler l'en-tete du bloc suivant (la
             * recovery skip-to-newline demarre apres le FIN consomme). */
            parser.panicMode = false;
            continue;
        }

        if (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION)) {
            advance_token();
            if (!check(TOKEN_IDENTIFIER)) {
                owl_emit_error_current(E_SYNTAX_EXPECTED_BLOCK_NAME_AFTER_PROC);
                menu_skip_unknown_block();
                continue;
            }
            Token procTok = parser.current;
            char procName[128];
            int pl = procTok.length < 127 ? procTok.length : 127;
            memcpy(procName, procTok.start, (size_t)pl);
            procName[pl] = '\0';
            advance_token();
            if (!match_token(TOKEN_LEFT_PAREN)) {
                owl_emit_error_at(&procTok, E_SYNTAX_EXPECTED_LPAREN_AFTER_BLOCK_NAME);
                menu_skip_unknown_block();
                continue;
            }
            while (!check(TOKEN_RIGHT_PAREN) && !check(TOKEN_EOF)) advance_token();
            consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_BLOCK_PARAMS);

            const OwlEventDef* evt = owl_menu_option_event_catalog_find(procName);
            if (evt == NULL) {
                owl_emit_error_at(&procTok, E_SEM_MENU_PROC_UNKNOWN,
                                  "name", procName, "kind", kindName, NULL);
                parser.panicMode = false;
            } else if (kind == OWL_MENU_NODE_SUBMENU) {
                owl_emit_error_at(&procTok, E_SEM_MENU_SUBMENU_HAS_SELECTION,
                                  "name", selfName, NULL);
                parser.panicMode = false;
            } else if (kind == OWL_MENU_NODE_SEPARATOR) {
                owl_emit_error_at(&procTok, E_SEM_MENU_SEPARATOR_HAS_SELECTION,
                                  "name", selfName, NULL);
                parser.panicMode = false;
            }
            /*  — deuxieme bloc du meme evenement sur ce noeud : le
             * cablage runtime ne retient que le premier, le second ne
             * s'executait jamais. La comparaison porte sur la forme canon
             * rendue par le catalogue, qui absorbe deja la paire FR/EN. */
            bool dupEvent = (node != NULL && evt != NULL
                             && owl_menu_node_has_event(node, evt->canonical));
            if (dupEvent) {
                owl_emit_error_at(&procTok, E_SEM_MENU_NODE_EVENT_DUPLICATE,
                                  "name", procName,
                                  "node", selfName,
                                  NULL);
                parser.panicMode = false;
            }
            ObjFunction* fn = compile_event_block_body_with_params(
                evt ? evt->canonical : procName, false, 0, NULL);
            if (!dupEvent && node != NULL && evt != NULL
                && kind == OWL_MENU_NODE_OPTION && fn != NULL) {
                owl_menu_node_add_event(node, evt->canonical, fn, procTok.line);
            }
            parser.panicMode = false;
            continue;
        }

        if (menu_peek_declaration() != MENU_KW_NONE) {
            menu_parse_child_declarations(NULL, node, kindName, selfName,
                                          kind == OWL_MENU_NODE_SUBMENU);
            continue;
        }

        /* Tout le reste : bloc ou instruction inconnue dans un menu. */
        Token badTok = parser.current;
        char badName[128];
        int bl = badTok.length < 127 ? badTok.length : 127;
        if (bl < 0) bl = 0;
        memcpy(badName, badTok.start, (size_t)bl);
        badName[bl] = '\0';
        owl_emit_error_at(&badTok, E_SEM_MENU_UNKNOWN_BLOCK,
                          "name", badName, "kind", kindName, NULL);
        advance_token();
        menu_skip_unknown_block();
        parser.panicMode = false;
    }
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_MENU);

    /* Un menu deroulant et une option ont besoin d'un texte affiche. */
    if (node != NULL && !captionSeen) {
        if (kind == OWL_MENU_NODE_SUBMENU) {
            owl_emit_error_at(&nameTok, E_SEM_MENU_SUBMENU_NO_CAPTION,
                              "name", selfName, NULL);
            parser.panicMode = false;
        } else if (kind == OWL_MENU_NODE_OPTION) {
            owl_emit_error_at(&nameTok, E_SEM_MENU_OPTION_NO_CAPTION,
                              "name", selfName, NULL);
            parser.panicMode = false;
        }
    }
}

/* `MNU_X est un MenuPrincipal ... FIN` dans le body d'une Fenetre. Le caller a
 * consomme `IDENT est un[e] MenuPrincipal`. */
/*  (ticket C) — le token (identifiant) correspond-il, apres strip
 * d'accents et casse-insensible, a l'une des formes ASCII donnees (FR ou EN) ? */
static bool menu_style_tok_is(Token t, const char* a, const char* b) {
    char norm[64];
    int n = scanner_strip_accents(t.start, t.length, norm, (int)sizeof(norm));
    if (n <= 0) return false;
    norm[n] = '\0';
    if (a && (int)strlen(a) == n && strncasecmp(a, norm, (size_t)n) == 0) return true;
    if (b && (int)strlen(b) == n && strncasecmp(b, norm, (size_t)n) == 0) return true;
    return false;
}

/* Copie la forme ECRITE d'un token dans buf (pour les messages d'erreur). */
static void menu_style_tok_raw(Token t, char* buf, int cap) {
    int n = t.length < cap - 1 ? t.length : cap - 1;
    if (n < 0) n = 0;
    memcpy(buf, t.start, (size_t)n);
    buf[n] = '\0';
}

typedef enum { MSTY_BARRE, MSTY_SOUSMENU, MSTY_OPTION } MenuStyleSurface;

static int menu_style_clamp_byte(int64_t v) {
    if (v < 0) return 0;
    if (v > 255) return 255;
    return (int)v;
}

/*  — parse la valeur d'une prop couleur du bloc Style menu. Accepte
 * soit le littéral composé `Couleur(r,v,b[,a])` / `Color(...)` (chaque composant
 * const-foldable), soit toute valeur const entière (couleur nommée, RVB(...),
 * entier BGR). Le résultat est le BGR packé dans *out, alpha encodé (cf.
 * OWL_MENU_COL_PACK) quand a<255. Retourne false sur valeur non const-foldable
 * (variable, appel dynamique, composant Couleur() non const, arité != 3/4) —
 * le caller émet alors E_SEM_MENU_STYLE_VALUE_NOT_CONST. */
static bool menu_parse_style_color_value(int64_t* out) {
    /* Littéral `Couleur(...)` : le type composé première classe (Couleur/Color)
     * est réutilisé comme littéral compile-time — le bloc Style stocke des slots
     * plats, pas d'instance runtime. */
    if (check(TOKEN_IDENTIFIER)
        && menu_style_tok_is(parser.current, "Couleur", "Color")) {
        Token saved_current  = parser.current;
        Token saved_previous = parser.previous;
        Scanner saved_scan   = parser.scanner;
        bool saved_nl        = crossedNewline;
        advance_token();  /* consume Couleur / Color */
        if (check(TOKEN_LEFT_PAREN)) {
            advance_token();  /* consume ( */
            int64_t comp[4];
            int n = 0;
            bool ok = true;
            if (!check(TOKEN_RIGHT_PAREN)) {
                for (;;) {
                    if (n >= 4) { ok = false; break; }
                    Value cv;
                    if (!window_try_parse_const_literal(&cv) || !IS_INTEGER(cv)) {
                        ok = false; break;
                    }
                    comp[n++] = AS_INTEGER(cv);
                    if (check(TOKEN_RIGHT_PAREN)) break;
                    if (!match_token(TOKEN_COMMA)) { ok = false; break; }
                }
            }
            if (ok && check(TOKEN_RIGHT_PAREN) && (n == 3 || n == 4)) {
                advance_token();  /* consume ) */
                int r = menu_style_clamp_byte(comp[0]);
                int v = menu_style_clamp_byte(comp[1]);
                int b = menu_style_clamp_byte(comp[2]);
                int a = (n == 4) ? menu_style_clamp_byte(comp[3]) : 255;
                int64_t bgr = (int64_t)r + (int64_t)v * 256 + (int64_t)b * 65536;
                *out = OWL_MENU_COL_PACK(bgr, a);
                return true;
            }
        }
        /* Pas un littéral Couleur() valide : rollback complet, retente la voie
         * const entière (couleur nommée / RVB() / entier). */
        parser.current  = saved_current;
        parser.previous = saved_previous;
        parser.scanner  = saved_scan;
        crossedNewline  = saved_nl;
    }

    Value v;
    if (!window_try_parse_const_literal(&v) || !IS_INTEGER(v)) return false;
    *out = AS_INTEGER(v);
    return true;
}

typedef enum { MSTY_LEAF_COLOR, MSTY_LEAF_BOOL, MSTY_LEAF_SIZE, MSTY_LEAF_STR } MenuLeafKind;

/* Feuille de style resolue : leafKind + exactement un slot pointeur (les autres
 * NULL, ou tous NULL si menu==NULL). propRaw = forme ecrite de la prop pour les
 * messages. */
typedef struct {
    MenuLeafKind kind;
    int*     intSlot;
    int64_t* colorSlot;
    char**   strSlot;
    char     propRaw[128];
} MenuStyleLeaf;

/* La brique de style d'une surface texte (Barre/OptionMenu). SousMenu range ses
 * props directement sur le decl (pas de brique) -> NULL. */
static OwlMenuStyleBrick* menu_style_brick_for(OwlMenuDecl* menu,
                                               MenuStyleSurface surf, bool survol) {
    if (menu == NULL) return NULL;
    if (surf == MSTY_BARRE)  return survol ? &menu->barre_survol  : &menu->barre_base;
    if (surf == MSTY_OPTION) return survol ? &menu->option_survol : &menu->option_base;
    return NULL;
}

/* Resout un attribut de police (`Police..<sub>` / `Police = { <sub> = ... }`).
 * subTok = le sous-attribut (Gras, Nom, ...). Emet PROP_UNKNOWN + false si
 * inconnu. */
static bool menu_style_resolve_font(OwlMenuStyleBrick* brick, Token subTok,
                                    MenuStyleLeaf* leaf) {
    menu_style_tok_raw(subTok, leaf->propRaw, sizeof(leaf->propRaw));
    leaf->intSlot = NULL; leaf->colorSlot = NULL; leaf->strSlot = NULL;
    if (menu_style_tok_is(subTok, "Nom", "Name")) {
        leaf->strSlot = brick ? &brick->police_nom : NULL; leaf->kind = MSTY_LEAF_STR;
    } else if (menu_style_tok_is(subTok, "Taille", "Size")) {
        leaf->intSlot = brick ? &brick->police_taille : NULL; leaf->kind = MSTY_LEAF_SIZE;
    } else if (menu_style_tok_is(subTok, "Gras", "Bold")) {
        leaf->intSlot = brick ? &brick->police_gras : NULL; leaf->kind = MSTY_LEAF_BOOL;
    } else if (menu_style_tok_is(subTok, "Italique", "Italic")) {
        leaf->intSlot = brick ? &brick->police_italique : NULL; leaf->kind = MSTY_LEAF_BOOL;
    } else if (menu_style_tok_is(subTok, "Souligne", "Underline")) {
        leaf->intSlot = brick ? &brick->police_souligne : NULL; leaf->kind = MSTY_LEAF_BOOL;
    } else if (menu_style_tok_is(subTok, "Barre", "StrikeThrough")) {
        leaf->intSlot = brick ? &brick->police_barre : NULL; leaf->kind = MSTY_LEAF_BOOL;
    } else if (menu_style_tok_is(subTok, "Couleur", "Color")) {
        leaf->colorSlot = brick ? &brick->couleur : NULL; leaf->kind = MSTY_LEAF_COLOR;
    } else {
        owl_emit_error_at(&subTok, E_SEM_MENU_STYLE_PROP_UNKNOWN,
                          "prop", leaf->propRaw, "surface", "Police",
                          "allowed", "Nom, Taille, Gras, Italique, Souligne, Barre, Couleur", NULL);
        return false;
    }
    return true;
}

typedef enum { MSTY_RES_OK, MSTY_RES_IS_POLICE, MSTY_RES_UNKNOWN } MenuPropResolve;

/* Resout une prop directe de surface (hors Police). Retourne IS_POLICE pour la
 * prop Police (le caller lit le sous-attribut selon la forme). UNKNOWN + erreur
 * sinon. */
static MenuPropResolve menu_style_resolve_prop(OwlMenuDecl* menu, MenuStyleSurface surf,
                                               OwlMenuStyleBrick* brick, Token propTok,
                                               const char* surfName, MenuStyleLeaf* leaf) {
    menu_style_tok_raw(propTok, leaf->propRaw, sizeof(leaf->propRaw));
    leaf->intSlot = NULL; leaf->colorSlot = NULL; leaf->strSlot = NULL;
    if (surf == MSTY_SOUSMENU) {
        if (menu_style_tok_is(propTok, "CouleurFond", "BackgroundColor")) {
            leaf->colorSlot = menu ? &menu->sousmenu_couleur_fond : NULL; leaf->kind = MSTY_LEAF_COLOR;
        } else if (menu_style_tok_is(propTok, "CouleurSeparateur", "SeparatorColor")) {
            leaf->colorSlot = menu ? &menu->sousmenu_couleur_separateur : NULL; leaf->kind = MSTY_LEAF_COLOR;
        } else if (menu_style_tok_is(propTok, "Arrondi", "CornerRadius")) {
            leaf->intSlot = menu ? &menu->sousmenu_arrondi : NULL; leaf->kind = MSTY_LEAF_SIZE;
        } else if (menu_style_tok_is(propTok, "Epaisseur", "Thickness")) {
            leaf->intSlot = menu ? &menu->sousmenu_epaisseur : NULL; leaf->kind = MSTY_LEAF_SIZE;
        } else if (menu_style_tok_is(propTok, "CouleurBordure", "BorderColor")) {
            leaf->colorSlot = menu ? &menu->sousmenu_couleur_bordure : NULL; leaf->kind = MSTY_LEAF_COLOR;
        } else {
            owl_emit_error_at(&propTok, E_SEM_MENU_STYLE_PROP_UNKNOWN,
                              "prop", leaf->propRaw, "surface", surfName,
                              "allowed", "CouleurFond, CouleurS\xc3\xa9parateur, "
                              "Arrondi, Epaisseur, CouleurBordure", NULL);
            return MSTY_RES_UNKNOWN;
        }
    } else {
        if (menu_style_tok_is(propTok, "CouleurFond", "BackgroundColor")) {
            leaf->colorSlot = brick ? &brick->couleur_fond : NULL; leaf->kind = MSTY_LEAF_COLOR;
        } else if (menu_style_tok_is(propTok, "Couleur", "Color")) {
            leaf->colorSlot = brick ? &brick->couleur : NULL; leaf->kind = MSTY_LEAF_COLOR;
        } else if (menu_style_tok_is(propTok, "Police", "Font")) {
            return MSTY_RES_IS_POLICE;
        } else {
            owl_emit_error_at(&propTok, E_SEM_MENU_STYLE_PROP_UNKNOWN,
                              "prop", leaf->propRaw, "surface", surfName,
                              "allowed", "CouleurFond, Couleur, Police", NULL);
            return MSTY_RES_UNKNOWN;
        }
    }
    return MSTY_RES_OK;
}

/* Resolution d'une sentinelle iPolice (membre de iFamille) vers la fonte
 * embarquee, definie dans ui_catalog.c. Meme resolveur que le chemin widget
 * (owl_ui_control_set_font_name). NULL = pas une sentinelle iFamille. */
extern const char* owl_ui_ipol_embedded_family(long long v);

/* Parse la valeur const (parser positionne apres le `=`) et la range dans le
 * slot resolu. errTok localise l'erreur de type. Retourne false (valeur non
 * const) -> le caller resynchronise ; true sinon (y compris type incompatible :
 * l'erreur est deja emise, la valeur est consommee, rien a resynchroniser). */
static bool menu_style_store_value(OwlMenuDecl* menu, const MenuStyleLeaf* leaf,
                                   Token errTok) {
    if (leaf->kind == MSTY_LEAF_COLOR) {
        int64_t packed;
        if (!menu_parse_style_color_value(&packed)) {
            owl_emit_error_at(&parser.current, E_SEM_MENU_STYLE_VALUE_NOT_CONST,
                              "prop", leaf->propRaw, NULL);
            return false;
        }
        if (leaf->colorSlot) *leaf->colorSlot = packed;
        if (menu) menu->has_style = 1;
        return true;
    }

    Value v;
    if (!window_try_parse_const_literal(&v)) {
        owl_emit_error_at(&parser.current, E_SEM_MENU_STYLE_VALUE_NOT_CONST,
                          "prop", leaf->propRaw, NULL);
        return false;
    }

    switch (leaf->kind) {
        case MSTY_LEAF_COLOR:
            break;  /* traite au-dessus */
        case MSTY_LEAF_BOOL:
            if (!IS_BOOL(v)) {
                owl_emit_error_at(&errTok, E_SEM_MENU_STYLE_VALUE_TYPE, "prop", leaf->propRaw, NULL);
            } else if (leaf->intSlot) { *leaf->intSlot = AS_BOOL(v) ? 1 : 0; }
            break;
        case MSTY_LEAF_SIZE:
            if (!IS_INTEGER(v)) {
                owl_emit_error_at(&errTok, E_SEM_MENU_STYLE_VALUE_TYPE, "prop", leaf->propRaw, NULL);
            } else if (leaf->intSlot) { *leaf->intSlot = (int)AS_INTEGER(v); }
            break;
        case MSTY_LEAF_STR: {
            const char* fontName = NULL;
            if (IS_STRING(v)) {
                fontName = AS_CSTRING(v);
            } else if (IS_INTEGER(v)) {
                /* Parite widget : Police..Nom accepte une constante
                 * iPolice (membre de iFamille) en plus d'un litteral chaine. On
                 * la resout vers la meme fonte embarquee que le chemin widget
                 * (owl_ui_control_set_font_name), pour un rendu identique. Un
                 * entier hors iFamille (ex : couleur Bleu) -> NULL -> rejet type.
                 * iDefaut resout "" (police heritee conservee, aucun fragment). */
                fontName = owl_ui_ipol_embedded_family(AS_INTEGER(v));
            }
            if (fontName == NULL) {
                owl_emit_error_at(&errTok, E_SEM_MENU_STYLE_VALUE_TYPE, "prop", leaf->propRaw, NULL);
            } else if (leaf->strSlot) {
                free(*leaf->strSlot);
                size_t len = strlen(fontName);
                char* dup = (char*)malloc(len + 1);
                memcpy(dup, fontName, len + 1);
                *leaf->strSlot = dup;
            }
            break;
        }
    }

    if (menu) menu->has_style = 1;
    return true;
}

/* Parse une instruction de style ligne-par-ligne : Surface[..Etats[etat]]..
 * Prop[..Sous] = <const>. `Style` + le `..` de tete ont deja ete consommes par
 * le caller (menu_parse_menu_properties). Const-fold immediat dans les slots
 * plats du OwlMenuDecl. Defensif : surface/prop/etat inconnus, prop au racine,
 * valeur non constante -> erreur. */
static void menu_parse_style_statement(OwlMenuDecl* menu) {
    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_at(&parser.current, E_SEM_MENU_STYLE_SYNTAX, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    Token first = parser.current;
    advance_token();

    /* Prop au racine sans surface : `CouleurFond = ...`. */
    if (check(TOKEN_EQUAL)) {
        char raw[128]; menu_style_tok_raw(first, raw, sizeof(raw));
        owl_emit_error_at(&first, E_SEM_MENU_STYLE_NO_SURFACE, "prop", raw, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    if (!check(TOKEN_DOUBLE_DOT)) {
        owl_emit_error_at(&first, E_SEM_MENU_STYLE_SYNTAX, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }

    MenuStyleSurface surf;
    const char* surfName;
    if (menu_style_tok_is(first, "Barre", "Bar")) { surf = MSTY_BARRE; surfName = "Barre"; }
    else if (menu_style_tok_is(first, "SousMenu", "Submenu")) { surf = MSTY_SOUSMENU; surfName = "SousMenu"; }
    else if (menu_style_tok_is(first, "OptionMenu", "MenuOption")) { surf = MSTY_OPTION; surfName = "OptionMenu"; }
    else {
        char raw[128]; menu_style_tok_raw(first, raw, sizeof(raw));
        owl_emit_error_at(&first, E_SEM_MENU_STYLE_SURFACE_UNKNOWN, "name", raw, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }

    /*  — un menu contextuel n'a pas de barre : Barre.. est refuse. */
    if (surf == MSTY_BARRE && menu != NULL && menu->is_context) {
        owl_emit_error_at(&first, E_SEM_CTXMENU_STYLE_BAR, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    advance_token();  /* consume .. */

    bool survol = false;
    if (check(TOKEN_IDENTIFIER) && menu_style_tok_is(parser.current, "Etats", "States")) {
        Token etatsTok = parser.current;
        advance_token();
        if (surf == MSTY_SOUSMENU) {
            owl_emit_error_at(&etatsTok, E_SEM_MENU_STYLE_STATE_ON_STATIC,
                              "surface", surfName, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        if (!match_token(TOKEN_LEFT_BRACKET) || !check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&etatsTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        Token stateTok = parser.current;
        advance_token();
        if (!match_token(TOKEN_RIGHT_BRACKET)) {
            owl_emit_error_at(&stateTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        if (!menu_style_tok_is(stateTok, "survol", "hover")) {
            char raw[64]; menu_style_tok_raw(stateTok, raw, sizeof(raw));
            owl_emit_error_at(&stateTok, E_SEM_MENU_STYLE_STATE_UNKNOWN, "state", raw, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        survol = true;
        if (!match_token(TOKEN_DOUBLE_DOT)) {
            owl_emit_error_at(&stateTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
    }

    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_at(&parser.current, E_SEM_MENU_STYLE_SYNTAX, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    Token propTok = parser.current;
    advance_token();

    OwlMenuStyleBrick* brick = menu_style_brick_for(menu, surf, survol);
    MenuStyleLeaf leaf;
    MenuPropResolve r = menu_style_resolve_prop(menu, surf, brick, propTok, surfName, &leaf);
    if (r == MSTY_RES_UNKNOWN) {
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    if (r == MSTY_RES_IS_POLICE) {
        /*  — la police par état (survol) n'est pas rendue : refus net.
         * Seules les couleurs varient par état sur un menu. */
        if (survol) {
            owl_emit_error_at(&propTok, E_SEM_MENU_STYLE_FONT_NO_STATE, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        /* Police exige un sous-attribut : Police..Gras, Police..Nom, ... */
        if (!match_token(TOKEN_DOUBLE_DOT) || !check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&propTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        Token subTok = parser.current;
        advance_token();
        if (!menu_style_resolve_font(brick, subTok, &leaf)) {
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
    }

    if (!match_token(TOKEN_EQUAL)) {
        owl_emit_error_at(&propTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }

    /* errTok = propTok : sur Police..X, l'ancien code localisait l'erreur de
     * type sur le token Police (pas le sous-attribut). Conserve. */
    if (!menu_style_store_value(menu, &leaf, propTok)) {
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    /* Un store `true` a consomme la valeur (y compris sur type incompatible :
     * l'erreur est deja emise). Rien a resynchroniser -> ne pas laisser fuiter
     * le panic, sinon la recovery du bloc avale la suite. */
    parser.panicMode = false;
}

/* Parse le corps d'une surface en forme inline : `{ Prop = val | Police = {...}
 * | Etats[survol] = {...} }`. Le `{` a deja ete consomme. Recursif pour l'etat
 * survol. */
static void menu_parse_style_surface_inline(OwlMenuDecl* menu, MenuStyleSurface surf,
                                            const char* surfName, bool survol) {
    OwlMenuStyleBrick* brick = menu_style_brick_for(menu, surf, survol);
    const char* lastPos = NULL;
    while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE) || check(TOKEN_COMMA)) advance_token();
        if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;
        if (parser.current.start == lastPos) { advance_token(); parser.panicMode = false; continue; }
        lastPos = parser.current.start;

        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&parser.current, E_SEM_MENU_STYLE_SYNTAX, NULL);
            advance_token();
            parser.panicMode = false;
            continue;
        }
        Token propTok = parser.current;

        /* Etats[survol] = { ... } (sous-bloc d'etat). */
        if (menu_style_tok_is(propTok, "Etats", "States")) {
            advance_token();  /* consume Etats */
            if (surf == MSTY_SOUSMENU) {
                owl_emit_error_at(&propTok, E_SEM_MENU_STYLE_STATE_ON_STATIC,
                                  "surface", surfName, NULL);
                parser.panicMode = false;
            }
            if (!match_token(TOKEN_LEFT_BRACKET) || !check(TOKEN_IDENTIFIER)) {
                owl_emit_error_at(&propTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
                parser.panicMode = false;
                continue;
            }
            Token stateTok = parser.current;
            advance_token();
            if (!match_token(TOKEN_RIGHT_BRACKET)) {
                owl_emit_error_at(&stateTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
                parser.panicMode = false;
                continue;
            }
            if (!menu_style_tok_is(stateTok, "survol", "hover")) {
                char raw[64]; menu_style_tok_raw(stateTok, raw, sizeof(raw));
                owl_emit_error_at(&stateTok, E_SEM_MENU_STYLE_STATE_UNKNOWN, "state", raw, NULL);
                parser.panicMode = false;
                continue;
            }
            if (!match_token(TOKEN_EQUAL) || !match_token(TOKEN_LEFT_BRACE)) {
                owl_emit_error_at(&stateTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
                parser.panicMode = false;
                continue;
            }
            menu_parse_style_surface_inline(menu, surf, surfName, true);
            continue;
        }

        MenuStyleLeaf leaf;
        MenuPropResolve r = menu_style_resolve_prop(menu, surf, brick, propTok, surfName, &leaf);
        if (r == MSTY_RES_UNKNOWN) {
            advance_token();
            parser.panicMode = false;
            continue;
        }

        /* Police = { <attr> = val ... } (sous-bloc de police en inline). */
        if (r == MSTY_RES_IS_POLICE) {
            advance_token();  /* consume Police */
            /*  — police par état (survol) non rendue : refus net. On
             * consomme le bloc `= { ... }` sans le stocker. */
            if (survol) {
                owl_emit_error_at(&propTok, E_SEM_MENU_STYLE_FONT_NO_STATE, NULL);
                if (match_token(TOKEN_EQUAL) && match_token(TOKEN_LEFT_BRACE)) {
                    int depth = 1;
                    while (depth > 0 && !check(TOKEN_EOF)) {
                        if (check(TOKEN_LEFT_BRACE)) depth++;
                        else if (check(TOKEN_RIGHT_BRACE)) depth--;
                        advance_token();
                    }
                }
                parser.panicMode = false;
                continue;
            }
            if (!match_token(TOKEN_EQUAL) || !match_token(TOKEN_LEFT_BRACE)) {
                owl_emit_error_at(&propTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
                parser.panicMode = false;
                continue;
            }
            const char* subLast = NULL;
            while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
                while (check(TOKEN_NEWLINE) || check(TOKEN_COMMA)) advance_token();
                if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;
                if (parser.current.start == subLast) { advance_token(); continue; }
                subLast = parser.current.start;
                if (!check(TOKEN_IDENTIFIER)) {
                    owl_emit_error_at(&parser.current, E_SEM_MENU_STYLE_SYNTAX, NULL);
                    advance_token();
                    parser.panicMode = false;
                    continue;
                }
                Token subTok = parser.current;
                advance_token();
                MenuStyleLeaf fleaf;
                if (!menu_style_resolve_font(brick, subTok, &fleaf)) {
                    parser.panicMode = false;
                    continue;
                }
                if (!match_token(TOKEN_EQUAL)) {
                    owl_emit_error_at(&subTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
                    parser.panicMode = false;
                    continue;
                }
                menu_style_store_value(menu, &fleaf, subTok);
            }
            consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_POLICE);
            parser.panicMode = false;
            continue;
        }

        advance_token();  /* consume la prop */
        if (!match_token(TOKEN_EQUAL)) {
            owl_emit_error_at(&propTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
            parser.panicMode = false;
            continue;
        }
        menu_style_store_value(menu, &leaf, propTok);
    }
    consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_STYLE_SURFACE);
    parser.panicMode = false;
}

/* Parse la forme inline littérale `Style = { Barre = {...}, SousMenu = {...},
 * OptionMenu = {...} }`. Le token `Style` a deja ete consomme ; le parser est
 * positionne sur le `=`. */
static void menu_parse_style_inline(OwlMenuDecl* menu) {
    advance_token();  /* consume = */
    if (!match_token(TOKEN_LEFT_BRACE)) {
        owl_emit_error_at(&parser.current, E_SEM_MENU_STYLE_SYNTAX, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    const char* lastPos = NULL;
    while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE) || check(TOKEN_COMMA)) advance_token();
        if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;
        if (parser.current.start == lastPos) { advance_token(); parser.panicMode = false; continue; }
        lastPos = parser.current.start;

        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&parser.current, E_SEM_MENU_STYLE_SYNTAX, NULL);
            advance_token();
            parser.panicMode = false;
            continue;
        }
        Token surfTok = parser.current;
        MenuStyleSurface surf;
        const char* surfName;
        if (menu_style_tok_is(surfTok, "Barre", "Bar")) { surf = MSTY_BARRE; surfName = "Barre"; }
        else if (menu_style_tok_is(surfTok, "SousMenu", "Submenu")) { surf = MSTY_SOUSMENU; surfName = "SousMenu"; }
        else if (menu_style_tok_is(surfTok, "OptionMenu", "MenuOption")) { surf = MSTY_OPTION; surfName = "OptionMenu"; }
        else {
            char raw[128]; menu_style_tok_raw(surfTok, raw, sizeof(raw));
            owl_emit_error_at(&surfTok, E_SEM_MENU_STYLE_SURFACE_UNKNOWN, "name", raw, NULL);
            advance_token();
            parser.panicMode = false;
            continue;
        }
        advance_token();  /* consume surface */

        if (surf == MSTY_BARRE && menu != NULL && menu->is_context) {
            owl_emit_error_at(&surfTok, E_SEM_CTXMENU_STYLE_BAR, NULL);
            parser.panicMode = false;
        }
        if (!match_token(TOKEN_EQUAL) || !match_token(TOKEN_LEFT_BRACE)) {
            owl_emit_error_at(&surfTok, E_SEM_MENU_STYLE_SYNTAX, NULL);
            parser.panicMode = false;
            continue;
        }
        menu_parse_style_surface_inline(menu, surf, surfName, false);
    }
    consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_STYLE);
    parser.panicMode = false;
    if (menu) menu->has_style = 1;
}

/* ===================================================================
 *   — style typé du Champ Onglet (styleOnglet)
 *
 *  Modèle : trois sous-éléments composites — `CadreExtérieur`
 *  (EN : OuterFrame ; fond + bordure du pane : CouleurFond + Cadre..Couleur/
 *  Épaisseur/Arrondi) + `VoletActif` / `VoletInactif` (EN : ActivePane /
 *  InactivePane), chacun portant Couleur / CouleurFond / Police + une surcharge
 *  d'état `survol`. Plus aucune prop scalaire à la racine.
 *  Slots plats const-folded sur l'OwlControlDecl (miroir du modèle menu).
 *  Réutilise les briques token/valeur du style menu (menu_style_tok_is,
 *  menu_style_tok_raw, menu_parse_style_color_value, MenuStyleLeaf).
 * =================================================================== */

typedef enum { OSTY_ACTIF, OSTY_INACTIF } OngletStyleElement;
/* REFUSED : prop connue de la surface de base mais interdite dans un corps
 * d'etat (erreur deja emise, le caller consomme la valeur). */
typedef enum { OSTY_RES_OK, OSTY_RES_IS_POLICE, OSTY_RES_UNKNOWN,
               OSTY_RES_REFUSED } OngletPropResolve;

static OwlOngletStyleBrick* onglet_style_brick_for(OwlControlDecl* ctrl,
                                                   OngletStyleElement el, bool survol) {
    if (ctrl == NULL) return NULL;
    if (el == OSTY_ACTIF) return survol ? &ctrl->ong_actif_survol : &ctrl->ong_actif_base;
    return survol ? &ctrl->ong_inactif_survol : &ctrl->ong_inactif_base;
}

/* Resout un attribut de police (`Police..<sub>`). Emet PROP_UNKNOWN + false si
 * inconnu (surface reportee « Police »). */
static bool onglet_style_resolve_font(OwlOngletStyleBrick* brick, Token subTok,
                                      MenuStyleLeaf* leaf) {
    menu_style_tok_raw(subTok, leaf->propRaw, sizeof(leaf->propRaw));
    leaf->intSlot = NULL; leaf->colorSlot = NULL; leaf->strSlot = NULL;
    if (menu_style_tok_is(subTok, "Nom", "Name")) {
        leaf->strSlot = brick ? &brick->police_nom : NULL; leaf->kind = MSTY_LEAF_STR;
    } else if (menu_style_tok_is(subTok, "Taille", "Size")) {
        leaf->intSlot = brick ? &brick->police_taille : NULL; leaf->kind = MSTY_LEAF_SIZE;
    } else if (menu_style_tok_is(subTok, "Gras", "Bold")) {
        leaf->intSlot = brick ? &brick->police_gras : NULL; leaf->kind = MSTY_LEAF_BOOL;
    } else if (menu_style_tok_is(subTok, "Italique", "Italic")) {
        leaf->intSlot = brick ? &brick->police_italique : NULL; leaf->kind = MSTY_LEAF_BOOL;
    } else if (menu_style_tok_is(subTok, "Souligne", "Underline")) {
        leaf->intSlot = brick ? &brick->police_souligne : NULL; leaf->kind = MSTY_LEAF_BOOL;
    } else if (menu_style_tok_is(subTok, "Barre", "StrikeThrough")) {
        leaf->intSlot = brick ? &brick->police_barre : NULL; leaf->kind = MSTY_LEAF_BOOL;
    } else if (menu_style_tok_is(subTok, "Couleur", "Color")) {
        leaf->colorSlot = brick ? &brick->couleur : NULL; leaf->kind = MSTY_LEAF_COLOR;
    } else {
        owl_emit_error_at(&subTok, E_SEM_ONGLET_STYLE_PROP_UNKNOWN,
                          "prop", leaf->propRaw, "surface", "Police",
                          "allowed", "Nom, Taille, Gras, Italique, Souligne, Barre, Couleur", NULL);
        return false;
    }
    return true;
}

/* Resout une prop directe d'un volet (Couleur / CouleurFond / Police / Arrondi).
 * Retourne IS_POLICE pour Police (le caller lit le sous-attribut). UNKNOWN +
 * erreur sinon (surface = nom du volet, ex « VoletActif »). `survol` : l'etat
 * survol (styleVoletBase) ne pilote que les couleurs — Arrondi y est refuse,
 * comme le type restreint styleVoletBase l'expose. */
static OngletPropResolve onglet_style_resolve_prop(OwlOngletStyleBrick* brick,
                                                   Token propTok, const char* elemName,
                                                   bool survol, MenuStyleLeaf* leaf) {
    menu_style_tok_raw(propTok, leaf->propRaw, sizeof(leaf->propRaw));
    leaf->intSlot = NULL; leaf->colorSlot = NULL; leaf->strSlot = NULL;
    /*  — le corps d'un etat est un styleVoletBase : couleurs seules,
     * pas de Police par etat, pas de membre Etats (fin de chaine). Meme refus
     * ET meme message que le chemin litteral typé (theme, variable
     * styleOnglet), qui rend deja « Champ 'X' inconnu sur type
     * styleVoletBase ». */
    if (survol && (menu_style_tok_is(propTok, "Police", "Font")
                   || menu_style_tok_is(propTok, "Etats", "States"))) {
        emit_object_field_unknown("styleVoletBase", 14, propTok);
        return OSTY_RES_REFUSED;
    }
    if (menu_style_tok_is(propTok, "CouleurFond", "BackgroundColor")) {
        leaf->colorSlot = brick ? &brick->couleur_fond : NULL; leaf->kind = MSTY_LEAF_COLOR;
    } else if (menu_style_tok_is(propTok, "Couleur", "Color")) {
        leaf->colorSlot = brick ? &brick->couleur : NULL; leaf->kind = MSTY_LEAF_COLOR;
    } else if (menu_style_tok_is(propTok, "Police", "Font")) {
        return OSTY_RES_IS_POLICE;
    } else if (!survol && menu_style_tok_is(propTok, "Arrondi", "CornerRadius")) {
        leaf->intSlot = brick ? &brick->arrondi : NULL; leaf->kind = MSTY_LEAF_SIZE;
    } else if (survol) {
        /*  — dans un corps d'etat, la surface EST un styleVoletBase :
         * tout refus (Arrondi comme n'importe quel nom inconnu) doit rendre la
         * meme facture que Police / Etats ci-dessus, celle du chemin litteral
         * typé. REFUSED (et non UNKNOWN) : le caller consomme la valeur, une
         * faute = un message. */
        emit_object_field_unknown("styleVoletBase", 14, propTok);
        return OSTY_RES_REFUSED;
    } else {
        owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_PROP_UNKNOWN,
                          "prop", leaf->propRaw, "surface", elemName,
                          "allowed", "CouleurFond, Couleur, Police, Arrondi", NULL);
        return OSTY_RES_UNKNOWN;
    }
    return OSTY_RES_OK;
}

/* Parse la valeur const (parser positionne apres le `=`) et la range dans le
 * slot resolu. Miroir de menu_style_store_value, mais emet les codes Onglet.
 * Retourne false (valeur non const) -> le caller resynchronise ; true sinon
 * (y compris type incompatible : erreur emise, valeur consommee). */
static bool onglet_style_store(OwlControlDecl* ctrl, const MenuStyleLeaf* leaf,
                               Token errTok) {
    if (leaf->kind == MSTY_LEAF_COLOR) {
        int64_t packed;
        if (!menu_parse_style_color_value(&packed)) {
            owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_VALUE_NOT_CONST,
                              "prop", leaf->propRaw, NULL);
            return false;
        }
        if (leaf->colorSlot) *leaf->colorSlot = packed;
        if (ctrl) ctrl->ong_has_style = 1;
        return true;
    }

    Value v;
    if (!window_try_parse_const_literal(&v)) {
        owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_VALUE_NOT_CONST,
                          "prop", leaf->propRaw, NULL);
        return false;
    }
    switch (leaf->kind) {
        case MSTY_LEAF_COLOR:
            break;  /* traite au-dessus */
        case MSTY_LEAF_BOOL:
            if (!IS_BOOL(v)) {
                owl_emit_error_at(&errTok, E_SEM_MENU_STYLE_VALUE_TYPE, "prop", leaf->propRaw, NULL);
            } else if (leaf->intSlot) { *leaf->intSlot = AS_BOOL(v) ? 1 : 0; }
            break;
        case MSTY_LEAF_SIZE:
            if (!IS_INTEGER(v)) {
                owl_emit_error_at(&errTok, E_SEM_MENU_STYLE_VALUE_TYPE, "prop", leaf->propRaw, NULL);
            } else if (leaf->intSlot) { *leaf->intSlot = (int)AS_INTEGER(v); }
            break;
        case MSTY_LEAF_STR: {
            const char* fontName = NULL;
            if (IS_STRING(v)) {
                fontName = AS_CSTRING(v);
            } else if (IS_INTEGER(v)) {
                fontName = owl_ui_ipol_embedded_family(AS_INTEGER(v));
            }
            if (fontName == NULL) {
                owl_emit_error_at(&errTok, E_SEM_MENU_STYLE_VALUE_TYPE, "prop", leaf->propRaw, NULL);
            } else if (leaf->strSlot) {
                free(*leaf->strSlot);
                size_t len = strlen(fontName);
                char* dup = (char*)malloc(len + 1);
                memcpy(dup, fontName, len + 1);
                *leaf->strSlot = dup;
            }
            break;
        }
    }
    if (ctrl) ctrl->ong_has_style = 1;
    return true;
}

/*  — la racine du style Onglet n'a plus de propriete scalaire : les
 * trois sous-elements composites (CadreExtérieur / VoletActif / VoletInactif)
 * sont les seules cibles valides. Une prop directe sous Style est donc toujours
 * une erreur. */
static void onglet_style_root_prop_unknown(Token first) {
    char raw[128];
    menu_style_tok_raw(first, raw, sizeof(raw));
    owl_emit_error_at(&first, E_SEM_ONGLET_STYLE_PROP_UNKNOWN,
                      "prop", raw,
                      "surface", "la racine du style Onglet",
                      "allowed", "CadreExt\xc3\xa9rieur, VoletActif, VoletInactif", NULL);
}

/*  — resout un sous-attribut du Cadre du CadreExtérieur
 * (`Cadre..Couleur/Épaisseur/Arrondi`). Emet PROP_UNKNOWN + false si inconnu
 * (surface reportee « Cadre »). */
static bool onglet_cadre_resolve_border(OwlControlDecl* ctrl, Token subTok,
                                        MenuStyleLeaf* leaf) {
    menu_style_tok_raw(subTok, leaf->propRaw, sizeof(leaf->propRaw));
    leaf->intSlot = NULL; leaf->colorSlot = NULL; leaf->strSlot = NULL;
    if (menu_style_tok_is(subTok, "Couleur", "Color")) {
        leaf->colorSlot = ctrl ? &ctrl->ong_cadre_ext.cadre_couleur : NULL;
        leaf->kind = MSTY_LEAF_COLOR;
    } else if (menu_style_tok_is(subTok, "Epaisseur", "Thickness")) {
        leaf->intSlot = ctrl ? &ctrl->ong_cadre_ext.cadre_epaisseur : NULL;
        leaf->kind = MSTY_LEAF_SIZE;
    } else if (menu_style_tok_is(subTok, "Arrondi", "CornerRadius")) {
        leaf->intSlot = ctrl ? &ctrl->ong_cadre_ext.cadre_arrondi : NULL;
        leaf->kind = MSTY_LEAF_SIZE;
    } else {
        owl_emit_error_at(&subTok, E_SEM_ONGLET_STYLE_PROP_UNKNOWN,
                          "prop", leaf->propRaw, "surface", "Cadre",
                          "allowed", "Couleur, Epaisseur, Arrondi", NULL);
        return false;
    }
    return true;
}

/* Consomme la valeur d'une prop refusee (`= <val>`, `= { ... }` ou
 * `[etat] = { ... }`) pour ne pas relire son corps comme une suite de props :
 * une erreur nominative, pas une cascade. Le parser est positionne sur le
 * token qui suit le nom de la prop. */
static void onglet_skip_style_value(void) {
    while (!check(TOKEN_LEFT_BRACE) && !check(TOKEN_RIGHT_BRACE)
           && !check(TOKEN_NEWLINE) && !check(TOKEN_EOF)) {
        advance_token();
    }
    if (!check(TOKEN_LEFT_BRACE)) return;
    int depth = 0;
    do {
        if (check(TOKEN_LEFT_BRACE)) depth++;
        else if (check(TOKEN_RIGHT_BRACE)) depth--;
        advance_token();
    } while (depth > 0 && !check(TOKEN_EOF));
}

/* Corps d'un volet en forme inline `{ Prop = val | Police = {...}
 * | Etats[survol] = {...} }`. Le `{` a deja ete consomme. Recursif pour
 * l'etat survol. */
static void onglet_parse_style_element_inline(OwlControlDecl* ctrl, OngletStyleElement el,
                                              const char* elemName, bool survol) {
    OwlOngletStyleBrick* brick = onglet_style_brick_for(ctrl, el, survol);
    const char* lastPos = NULL;
    while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE) || check(TOKEN_COMMA)) advance_token();
        if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;
        if (parser.current.start == lastPos) { advance_token(); parser.panicMode = false; continue; }
        lastPos = parser.current.start;

        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            advance_token();
            parser.panicMode = false;
            continue;
        }
        Token propTok = parser.current;

        /* Etats[survol] = { ... } (sous-bloc d'etat, forme indexee) OU
         * Etats = { Survol = { ... } } (forme litterale par cle, celle des
         * autres familles de style — cf. le chemin generique L7059). Les deux
         * alimentent la meme brique survol. */
        if (menu_style_tok_is(propTok, "Etats", "States")) {
            /*  — refermer la boucle de recursion : le corps d'un etat
             * est un styleVoletBase (couleurs seules, fin de chaine), il ne
             * porte pas de membre Etats. Sans cette garde, `Etats` dans un
             * `Etats` etait avale silencieusement et ecrasait l'etat qui
             * l'englobe. Meme facture de message que le refus du chemin
             * litteral generique (« Champ 'Etats' inconnu sur type
             * styleZoneSaisieBase »). */
            if (survol) {
                emit_object_field_unknown("styleVoletBase", 14, propTok);
                advance_token();  /* consume Etats */
                onglet_skip_style_value();
                parser.panicMode = false;
                continue;
            }
            advance_token();  /* consume Etats */
            /*  — forme litterale : les cles du bloc sont les etats. */
            if (check(TOKEN_EQUAL)) {
                advance_token();  /* consume = */
                if (!match_token(TOKEN_LEFT_BRACE)) {
                    owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                    parser.panicMode = false;
                    continue;
                }
                const char* stLast = NULL;
                while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
                    while (check(TOKEN_NEWLINE) || check(TOKEN_COMMA)) advance_token();
                    if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;
                    if (parser.current.start == stLast) { advance_token(); parser.panicMode = false; continue; }
                    stLast = parser.current.start;
                    if (!check(TOKEN_IDENTIFIER)) {
                        owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                        advance_token();
                        parser.panicMode = false;
                        continue;
                    }
                    Token stTok = parser.current;
                    advance_token();
                    if (!menu_style_tok_is(stTok, "survol", "hover")) {
                        char raw[64]; menu_style_tok_raw(stTok, raw, sizeof(raw));
                        owl_emit_error_at(&stTok, E_SEM_MENU_STYLE_STATE_UNKNOWN, "state", raw, NULL);
                        /* Consomme la valeur de l'etat inconnu pour ne pas relire
                         * son corps comme une suite de cles d'etat (une erreur
                         * nominative, pas une cascade). */
                        if (match_token(TOKEN_EQUAL) && check(TOKEN_LEFT_BRACE)) {
                            int depth = 0;
                            do {
                                if (check(TOKEN_LEFT_BRACE)) depth++;
                                else if (check(TOKEN_RIGHT_BRACE)) depth--;
                                advance_token();
                            } while (depth > 0 && !check(TOKEN_EOF));
                        }
                        parser.panicMode = false;
                        continue;
                    }
                    if (!match_token(TOKEN_EQUAL) || !match_token(TOKEN_LEFT_BRACE)) {
                        owl_emit_error_at(&stTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                        parser.panicMode = false;
                        continue;
                    }
                    onglet_parse_style_element_inline(ctrl, el, elemName, true);
                }
                consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_ETATS);
                parser.panicMode = false;
                continue;
            }
            if (!match_token(TOKEN_LEFT_BRACKET) || !check(TOKEN_IDENTIFIER)) {
                owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                parser.panicMode = false;
                continue;
            }
            Token stateTok = parser.current;
            advance_token();
            if (!match_token(TOKEN_RIGHT_BRACKET)) {
                owl_emit_error_at(&stateTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                parser.panicMode = false;
                continue;
            }
            if (!menu_style_tok_is(stateTok, "survol", "hover")) {
                char raw[64]; menu_style_tok_raw(stateTok, raw, sizeof(raw));
                owl_emit_error_at(&stateTok, E_SEM_MENU_STYLE_STATE_UNKNOWN, "state", raw, NULL);
                parser.panicMode = false;
                continue;
            }
            if (!match_token(TOKEN_EQUAL) || !match_token(TOKEN_LEFT_BRACE)) {
                owl_emit_error_at(&stateTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                parser.panicMode = false;
                continue;
            }
            onglet_parse_style_element_inline(ctrl, el, elemName, true);
            continue;
        }

        MenuStyleLeaf leaf;
        OngletPropResolve r = onglet_style_resolve_prop(brick, propTok, elemName, survol, &leaf);
        if (r == OSTY_RES_UNKNOWN) {
            /*  — consommer aussi la valeur : sans ca le `= <val>`
             * restant etait relu comme une suite de props et une prop inconnue
             * rendait 3 messages au lieu d'un (meme resync que REFUSED). */
            advance_token();
            onglet_skip_style_value();
            parser.panicMode = false;
            continue;
        }
        if (r == OSTY_RES_REFUSED) {
            advance_token();
            onglet_skip_style_value();
            parser.panicMode = false;
            continue;
        }

        /* Police = { <attr> = val ... } (sous-bloc de police en inline). */
        if (r == OSTY_RES_IS_POLICE) {
            advance_token();  /* consume Police */
            if (!match_token(TOKEN_EQUAL) || !match_token(TOKEN_LEFT_BRACE)) {
                owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                parser.panicMode = false;
                continue;
            }
            const char* subLast = NULL;
            while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
                while (check(TOKEN_NEWLINE) || check(TOKEN_COMMA)) advance_token();
                if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;
                if (parser.current.start == subLast) { advance_token(); continue; }
                subLast = parser.current.start;
                if (!check(TOKEN_IDENTIFIER)) {
                    owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                    advance_token();
                    parser.panicMode = false;
                    continue;
                }
                Token subTok = parser.current;
                advance_token();
                MenuStyleLeaf fleaf;
                if (!onglet_style_resolve_font(brick, subTok, &fleaf)) {
                    parser.panicMode = false;
                    continue;
                }
                if (!match_token(TOKEN_EQUAL)) {
                    owl_emit_error_at(&subTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                    parser.panicMode = false;
                    continue;
                }
                onglet_style_store(ctrl, &fleaf, subTok);
            }
            consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_POLICE);
            parser.panicMode = false;
            continue;
        }

        advance_token();  /* consume la prop */
        if (!match_token(TOKEN_EQUAL)) {
            owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            parser.panicMode = false;
            continue;
        }
        onglet_style_store(ctrl, &leaf, propTok);
    }
    consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_STYLE_SUBELEM);
    parser.panicMode = false;
}

/*  — corps inline du sous-element CadreExtérieur `{ CouleurFond = val
 * | Cadre = { Couleur = val, Épaisseur = val, Arrondi = val } }`. Le `{` a deja
 * ete consomme. */
static void onglet_parse_cadre_ext_inline(OwlControlDecl* ctrl) {
    const char* lastPos = NULL;
    while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE) || check(TOKEN_COMMA)) advance_token();
        if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;
        if (parser.current.start == lastPos) { advance_token(); parser.panicMode = false; continue; }
        lastPos = parser.current.start;

        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            advance_token();
            parser.panicMode = false;
            continue;
        }
        Token propTok = parser.current;
        MenuStyleLeaf leaf;
        menu_style_tok_raw(propTok, leaf.propRaw, sizeof(leaf.propRaw));
        leaf.intSlot = NULL; leaf.colorSlot = NULL; leaf.strSlot = NULL;

        /* CadreExtérieur..Cadre = { ... } (bordure du pane). */
        if (menu_style_tok_is(propTok, "Cadre", "Border")) {
            advance_token();  /* consume Cadre */
            if (!match_token(TOKEN_EQUAL) || !match_token(TOKEN_LEFT_BRACE)) {
                owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                parser.panicMode = false;
                continue;
            }
            const char* subLast = NULL;
            while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
                while (check(TOKEN_NEWLINE) || check(TOKEN_COMMA)) advance_token();
                if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;
                if (parser.current.start == subLast) { advance_token(); continue; }
                subLast = parser.current.start;
                if (!check(TOKEN_IDENTIFIER)) {
                    owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                    advance_token();
                    parser.panicMode = false;
                    continue;
                }
                Token subTok = parser.current;
                advance_token();
                MenuStyleLeaf cleaf;
                if (!onglet_cadre_resolve_border(ctrl, subTok, &cleaf)) {
                    parser.panicMode = false;
                    continue;
                }
                if (!match_token(TOKEN_EQUAL)) {
                    owl_emit_error_at(&subTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                    parser.panicMode = false;
                    continue;
                }
                onglet_style_store(ctrl, &cleaf, subTok);
            }
            consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_CADRE);
            parser.panicMode = false;
            continue;
        }

        /* CadreExtérieur..CouleurFond = val (fond du pane). */
        if (menu_style_tok_is(propTok, "CouleurFond", "BackgroundColor")) {
            advance_token();  /* consume CouleurFond */
            leaf.colorSlot = ctrl ? &ctrl->ong_cadre_ext.couleur_fond : NULL;
            leaf.kind = MSTY_LEAF_COLOR;
            if (!match_token(TOKEN_EQUAL)) {
                owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                parser.panicMode = false;
                continue;
            }
            onglet_style_store(ctrl, &leaf, propTok);
            continue;
        }

        owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_PROP_UNKNOWN,
                          "prop", leaf.propRaw, "surface", "CadreExt\xc3\xa9rieur",
                          "allowed", "CouleurFond, Cadre", NULL);
        advance_token();
        parser.panicMode = false;
    }
    consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_CADRE_EXTERIEUR);
    parser.panicMode = false;
}

/* Forme inline littérale `Style = { CadreExtérieur = {...}, VoletActif = {...},
 * VoletInactif = {...} }`. Le token `Style` a deja ete consomme ; le parser est
 * positionne sur le `=`. */
static void onglet_parse_style_inline(OwlControlDecl* ctrl) {
    advance_token();  /* consume = */
    if (!match_token(TOKEN_LEFT_BRACE)) {
        owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    const char* lastPos = NULL;
    while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE) || check(TOKEN_COMMA)) advance_token();
        if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;
        if (parser.current.start == lastPos) { advance_token(); parser.panicMode = false; continue; }
        lastPos = parser.current.start;

        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            advance_token();
            parser.panicMode = false;
            continue;
        }
        Token first = parser.current;

        /* CadreExtérieur = { ... } (fond + bordure du pane). */
        if (menu_style_tok_is(first, "CadreExterieur", "OuterFrame")) {
            advance_token();  /* consume le sous-élément */
            if (!match_token(TOKEN_EQUAL) || !match_token(TOKEN_LEFT_BRACE)) {
                owl_emit_error_at(&first, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                parser.panicMode = false;
                continue;
            }
            onglet_parse_cadre_ext_inline(ctrl);
            continue;
        }

        OngletStyleElement el;
        const char* elemName;
        if (menu_style_tok_is(first, "VoletActif", "ActivePane")) { el = OSTY_ACTIF; elemName = "VoletActif"; }
        else if (menu_style_tok_is(first, "VoletInactif", "InactivePane")) { el = OSTY_INACTIF; elemName = "VoletInactif"; }
        else {
            char raw[128]; menu_style_tok_raw(first, raw, sizeof(raw));
            owl_emit_error_at(&first, E_SEM_ONGLET_STYLE_ELEMENT_UNKNOWN, "name", raw, NULL);
            advance_token();
            parser.panicMode = false;
            continue;
        }
        advance_token();  /* consume le sous-élément */
        if (!match_token(TOKEN_EQUAL) || !match_token(TOKEN_LEFT_BRACE)) {
            owl_emit_error_at(&first, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            parser.panicMode = false;
            continue;
        }
        onglet_parse_style_element_inline(ctrl, el, elemName, false);
    }
    consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_STYLE);
    parser.panicMode = false;
}

/* Forme ligne-par-ligne : `Style..[VoletActif|VoletInactif..[Etats[survol]..]]
 * Prop[..Sous] = <const>` ou `Style..CadreExtérieur..CouleurFond = <const>` /
 * `Style..CadreExtérieur..Cadre..<sub> = <const>` (fond + bordure du pane).
 * `Style` + le `..` de tete ont deja ete consommes par le caller. */
static void onglet_parse_style_statement(OwlControlDecl* ctrl) {
    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    Token first = parser.current;
    advance_token();

    /* Etats[...] directement sous Style : la racine n'a pas d'états. */
    if (menu_style_tok_is(first, "Etats", "States")) {
        owl_emit_error_at(&first, E_SEM_ONGLET_STYLE_STATE_ON_ROOT, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }

    /* Racine `Style..Prop = ...` : pas de `..` après le premier token. La racine
     * n'a plus de prop scalaire -> toujours une erreur. */
    if (check(TOKEN_EQUAL)) {
        onglet_style_root_prop_unknown(first);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    if (!check(TOKEN_DOUBLE_DOT)) {
        owl_emit_error_at(&first, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }

    /* CadreExtérieur..CouleurFond | CadreExtérieur..Cadre..<sub> (fond + bordure
     * du pane). */
    if (menu_style_tok_is(first, "CadreExterieur", "OuterFrame")) {
        advance_token();  /* consume .. */
        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        Token propTok = parser.current;
        advance_token();
        MenuStyleLeaf leaf;
        menu_style_tok_raw(propTok, leaf.propRaw, sizeof(leaf.propRaw));
        leaf.intSlot = NULL; leaf.colorSlot = NULL; leaf.strSlot = NULL;

        if (menu_style_tok_is(propTok, "CouleurFond", "BackgroundColor")) {
            leaf.colorSlot = ctrl ? &ctrl->ong_cadre_ext.couleur_fond : NULL;
            leaf.kind = MSTY_LEAF_COLOR;
        } else if (menu_style_tok_is(propTok, "Cadre", "Border")) {
            if (!match_token(TOKEN_DOUBLE_DOT) || !check(TOKEN_IDENTIFIER)) {
                owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
                window_skip_to_next_stmt();
                parser.panicMode = false;
                return;
            }
            Token subTok = parser.current;
            advance_token();
            if (!onglet_cadre_resolve_border(ctrl, subTok, &leaf)) {
                window_skip_to_next_stmt();
                parser.panicMode = false;
                return;
            }
        } else {
            owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_PROP_UNKNOWN,
                              "prop", leaf.propRaw, "surface", "CadreExt\xc3\xa9rieur",
                              "allowed", "CouleurFond, Cadre", NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        if (!match_token(TOKEN_EQUAL)) {
            owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        if (!onglet_style_store(ctrl, &leaf, propTok)) {
            window_skip_to_next_stmt();
        }
        parser.panicMode = false;
        return;
    }

    OngletStyleElement el;
    const char* elemName;
    if (menu_style_tok_is(first, "VoletActif", "ActivePane")) { el = OSTY_ACTIF; elemName = "VoletActif"; }
    else if (menu_style_tok_is(first, "VoletInactif", "InactivePane")) { el = OSTY_INACTIF; elemName = "VoletInactif"; }
    else {
        char raw[128]; menu_style_tok_raw(first, raw, sizeof(raw));
        owl_emit_error_at(&first, E_SEM_ONGLET_STYLE_ELEMENT_UNKNOWN, "name", raw, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    advance_token();  /* consume .. */

    bool survol = false;
    if (check(TOKEN_IDENTIFIER) && menu_style_tok_is(parser.current, "Etats", "States")) {
        Token etatsTok = parser.current;
        advance_token();
        if (!match_token(TOKEN_LEFT_BRACKET) || !check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&etatsTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        Token stateTok = parser.current;
        advance_token();
        if (!match_token(TOKEN_RIGHT_BRACKET)) {
            owl_emit_error_at(&stateTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        if (!menu_style_tok_is(stateTok, "survol", "hover")) {
            char raw[64]; menu_style_tok_raw(stateTok, raw, sizeof(raw));
            owl_emit_error_at(&stateTok, E_SEM_MENU_STYLE_STATE_UNKNOWN, "state", raw, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        survol = true;
        if (!match_token(TOKEN_DOUBLE_DOT)) {
            owl_emit_error_at(&stateTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
    }

    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_at(&parser.current, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    Token propTok = parser.current;
    advance_token();

    OwlOngletStyleBrick* brick = onglet_style_brick_for(ctrl, el, survol);
    MenuStyleLeaf leaf;
    OngletPropResolve r = onglet_style_resolve_prop(brick, propTok, elemName, survol, &leaf);
    if (r == OSTY_RES_UNKNOWN || r == OSTY_RES_REFUSED) {
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    if (r == OSTY_RES_IS_POLICE) {
        if (!match_token(TOKEN_DOUBLE_DOT) || !check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
        Token subTok = parser.current;
        advance_token();
        if (!onglet_style_resolve_font(brick, subTok, &leaf)) {
            window_skip_to_next_stmt();
            parser.panicMode = false;
            return;
        }
    }

    if (!match_token(TOKEN_EQUAL)) {
        owl_emit_error_at(&propTok, E_SEM_ONGLET_STYLE_SYNTAX, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    if (!onglet_style_store(ctrl, &leaf, propTok)) {
        window_skip_to_next_stmt();
    }
    parser.panicMode = false;
}

/*  — `Style = <reference>` sur un MenuPrincipal / MenuContextuel. Le
 * parser est sur le `=`.  : le genre attendu se lit sur la prop `Style`
 * de la fiche de catalogue de la sorte (object_type), comme pour un champ stylé
 * — plus de correspondance en dur ici. L'expression est ensuite
 * compilee en evaluateur 0-arg, resolu au montage de la fenetre. */
static void menu_parse_style_reference(OwlMenuDecl* menu, const char* menuKindName,
                                       const char* menuName, Token styleTok) {
    advance_token();  /* consume `=` */

    const OwlControlPropDef* styleDef = owl_dsl_prop_find(menuKindName, "Style");
    const char* expected = styleDef ? styleDef->object_type : NULL;
    char styleGot[64];
    char styleDesig[160];
    if (expected != NULL
        && style_rhs_resolve_type(styleGot, sizeof(styleGot),
                                  styleDesig, sizeof(styleDesig))
        && !is_base_style_type_name(styleGot)
        && !style_type_names_equal(expected, styleGot)) {
        owl_emit_error_at(&parser.current, E_SEM_STYLE_KIND_MISMATCH,
                          "field", menuName,
                          "kind", menuKindName,
                          "expected", expected,
                          "style", styleDesig,
                          "got", styleGot,
                          NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return;
    }
    /*  — meme avertissement que sur un champ style. */
    Token unknownTok;
    if (style_rhs_theme_ref_undeclared(&unknownTok)) {
        char nameBuf[128];
        snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                 unknownTok.length, unknownTok.start);
        owl_emit_warning_at(&unknownTok, W_SEM_THEME_STYLE_UNDECLARED,
                            "nom", nameBuf, NULL);
    }

    ObjFunction* eval = compile_expression_as_fn("__menu_style_ref");
    if (menu != NULL) {
        /* Canon  : l'affectation de la propriete ENTIERE reset les
         * cascades anterieures ; celles qui suivent surchargent la reference. */
        owl_menu_decl_reset_style(menu);
        owl_menu_decl_set_style_ref(menu, eval, styleTok.line);
    }
}

/* Parse le bloc `PROPRIETES` d'un MenuPrincipal / MenuContextuel. Seule la prop
 * universelle `Style` est acceptee ici, en forme ligne-par-ligne
 * (`Style..Surface..Prop = val`), inline (`Style = { ... }`) ou par reference
 * (`Style = theme.<nom>`, ). Le `PROPRIETES` a deja ete consomme ; on
 * lit jusqu'a FIN. */
static void menu_parse_menu_properties(OwlMenuDecl* menu, const char* menuKindName,
                                       const char* menuName) {
    const char* lastPos = NULL;
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        if (parser.current.start == lastPos) { advance_token(); parser.panicMode = false; continue; }
        lastPos = parser.current.start;
        if (parser.panicMode) {
            while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) && !check(TOKEN_EOF)) advance_token();
            parser.panicMode = false;
        }
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;

        if (check(TOKEN_IDENTIFIER) && menu_style_tok_is(parser.current, "Style", NULL)) {
            Token styleTok = parser.current;
            advance_token();  /* consume Style */
            if (check(TOKEN_DOUBLE_DOT)) {
                advance_token();  /* consume .. */
                menu_parse_style_statement(menu);
                continue;
            }
            if (!check(TOKEN_EQUAL)) {
                owl_emit_error_at(&parser.current, E_SEM_MENU_STYLE_SYNTAX, NULL);
                window_skip_to_next_stmt();
                parser.panicMode = false;
                continue;
            }
            if (dsl_style_rhs_is_brace_literal()) {
                menu_parse_style_inline(menu);
                continue;
            }
            /*  — forme REFERENCE `Style = theme.<nom>` (ou `= STY_<nom>`,
             * ou toute expression). Symetrique du Champ Onglet : le
             * parseur dedie ne garde que les deux formes const-foldees vers les
             * slots plats, la reference compile une expression resolue au montage
             * de la fenetre. Un menu n'etant pas un champ du catalogue, le
             * controle de genre est fait ici plutot que par la prop OBJECT. */
            menu_parse_style_reference(menu, menuKindName, menuName, styleTok);
            continue;
        }

        /* Toute autre prop est inconnue dans un menu : seul Style est accepte. */
        Token badTok = parser.current;
        char badName[128];
        int bl = badTok.length < 127 ? badTok.length : 127;
        if (bl < 0) bl = 0;
        memcpy(badName, badTok.start, (size_t)bl);
        badName[bl] = '\0';
        owl_emit_error_at(&badTok, E_SEM_MENU_PROP_UNKNOWN,
                          "prop", badName, "kind", menuKindName,
                          "allowed", "Style", NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
    }
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROPRIETES);
}

static void window_parse_menu(OwlWindowDecl* decl, Token nameTok, int line,
                              bool is_context) {
    char menuName[128];
    int nl = nameTok.length < 127 ? nameTok.length : 127;
    memcpy(menuName, nameTok.start, (size_t)nl);
    menuName[nl] = '\0';

    OwlMenuDecl* menu = NULL;
    if (decl != NULL) {
        if (owl_window_decl_find_menu(decl, menuName) != NULL ||
            owl_window_decl_find_control(decl, menuName) != NULL) {
            owl_emit_error_at(&nameTok, E_SEM_MENU_NAME_DUPLICATE,
                              "name", menuName, "window", decl->name, NULL);
            parser.panicMode = false;
        } else {
            menu = owl_window_decl_add_menu(decl, menuName, line);
            menu->is_context = is_context ? 1 : 0;
            /*  — le nom de l'arbre doit etre citable comme valeur pour
             * la bascule runtime `FEN_X..MenuPrincipal = MNU_Autre`. On pose
             * donc une globale sous la clef strippee (invariant 2), portant le
             * nom ECRIT du bloc : le runtime resout l'arbre par ce nom dans le
             * decl de la fenetre (owl_window_decl_find_menu), ce qui reste
             * correct si deux fenetres declarent des menus homonymes.
             * Meme mecanique que le proxy global des champs. */
            char gstripped[256];
            int glen = scanner_strip_accents(menuName, (int)strlen(menuName),
                                             gstripped, sizeof(gstripped));
            if (glen > 0) {
                ObjString* gkey = obj_copy_string(gstripped, glen);
                vm_push(OBJ_VAL(gkey));
                ObjString* gval = obj_copy_string(menuName, (int)strlen(menuName));
                vm_push(OBJ_VAL(gval));
                obj_globals_set_kv(gkey, OBJ_VAL(gval));
                vm_pop();  /* gval */
                vm_pop();  /* gkey */
            }
        }
    }

    /* Nom de sorte du conteneur pour les messages (menu principal ou contextuel). */
    const char* menuKindName = is_context ? "MenuContextuel" : "MenuPrincipal";

    const char* lastPos = NULL;
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        if (parser.current.start == lastPos) { advance_token(); parser.panicMode = false; continue; }
        lastPos = parser.current.start;
        if (parser.panicMode) {
            while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) && !check(TOKEN_EOF)) advance_token();
            parser.panicMode = false;
        }
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;

        if (menu_peek_declaration() != MENU_KW_NONE) {
            menu_parse_child_declarations(menu, NULL, menuKindName, menuName, true);
            continue;
        }

        /* Le style du menu se declare dans un bloc PROPRIETES via la prop
         * universelle `Style` (ligne-par-ligne ou inline), comme sur un
         * widget. */
        if (check(TOKEN_PROPRIETES)) {
            advance_token();  /* consume PROPRIETES */
            menu_parse_menu_properties(menu, menuKindName, menuName);
            continue;
        }

        /* `Style` seul en tete de ligne = ancienne syntaxe (bloc autonome),
         * retiree : Style est desormais une prop du bloc PROPRIETES. Erreur
         * dediee pour guider la migration. */
        if (check(TOKEN_IDENTIFIER) &&
            menu_style_tok_is(parser.current, "Style", NULL)) {
            owl_emit_error_at(&parser.current, E_SEM_MENU_STYLE_BLOCK_OBSOLETE,
                              "kind", menuKindName, NULL);
            advance_token();  /* consume `Style` */
            menu_skip_unknown_block();
            parser.panicMode = false;
            continue;
        }

        Token badTok = parser.current;
        char badName[128];
        int bl = badTok.length < 127 ? badTok.length : 127;
        if (bl < 0) bl = 0;
        memcpy(badName, badTok.start, (size_t)bl);
        badName[bl] = '\0';
        owl_emit_error_at(&badTok, E_SEM_MENU_UNKNOWN_BLOCK,
                          "name", badName, "kind", menuKindName, NULL);
        advance_token();
        menu_skip_unknown_block();
        parser.panicMode = false;
    }
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_MENU);

    /*  — un menu contextuel vide n'affiche rien : refuse plutot que
     * silencieusement inoperant. Le menu principal, lui, tolere le vide (une
     * barre nue reste visible). */
    if (menu != NULL && is_context && menu->child_count == 0) {
        owl_emit_error_at(&nameTok, E_SEM_CTXMENU_EMPTY, "name", menuName, NULL);
        parser.panicMode = false;
    }
}

/* Un SousMenu / OptionMenu / MenuSeparateur declare ailleurs que dans un
 * MenuPrincipal est orphelin. Chemin unique pour les trois, quel que soit le
 * contexte (body de Fenetre ou body de champ) : meme message, meme forme. */
static void menu_reject_orphan_node(MenuKeyword kw, Token nameTok) {
    char name[128];
    int nl = nameTok.length < 127 ? nameTok.length : 127;
    memcpy(name, nameTok.start, (size_t)nl);
    name[nl] = '\0';
    owl_emit_error_at(&nameTok, E_SEM_MENU_NODE_OUTSIDE_MAIN,
                      "kind", owl_menu_node_kind_name_fr(menu_node_kind_of_keyword(kw)),
                      "name", name, NULL);
    parser.panicMode = false;
    advance_token();              /* IDENT */
    advance_token();              /* est */
    consume_en_a_an_filler();
    advance_token();              /* mot-cle menu */
    menu_skip_unknown_block();
    parser.panicMode = false;
}

/* Token de la derniere affectation `MenuPrincipal = X` d'une Fenetre, garde
 * pour pointer l'erreur au bon endroit lors de la resolution differee (les
 * MenuPrincipal se declarent APRES le bloc PROPRIETES). */
static Token g_window_main_menu_tok;
static bool  g_window_main_menu_pending = false;

/* `MenuPrincipal = MNU_X` dans le bloc PROPRIETES d'une Fenetre. Ce n'est pas
 * une propriete de valeur (aucun slot runtime, aucune entree catalogue) : c'est
 * le choix de l'arbre de menu qui s'applique. Retourne true si la ligne a ete
 * consommee ici. */
static bool window_try_parse_main_menu_assign(OwlWindowDecl* decl) {
    if (menu_keyword_of_token(parser.current) != MENU_KW_MAIN) return false;

    Scanner s = parser.scanner;
    Token   c = parser.current, p = parser.previous;
    bool    n = crossedNewline;
    Token   propTok = parser.current;
    advance_token();
    if (!check(TOKEN_EQUAL)) {
        parser.scanner = s; parser.current = c; parser.previous = p;
        crossedNewline = n;
        return false;
    }
    advance_token();   /* '=' */

    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_at(&propTok, E_SEM_MENU_ASSIGN_EXPECTED_NAME, NULL);
        window_skip_to_next_stmt();
        parser.panicMode = false;
        return true;
    }
    Token valTok = parser.current;
    advance_token();

    if (decl != NULL) {
        if (decl->main_menu_name != NULL) {
            owl_emit_error_at(&propTok, E_SEM_MENU_ASSIGN_DUPLICATE,
                              "name", decl->main_menu_name, NULL);
            parser.panicMode = false;
            return true;
        }
        char nameBuf[128];
        int vl = valTok.length < 127 ? valTok.length : 127;
        memcpy(nameBuf, valTok.start, (size_t)vl);
        nameBuf[vl] = '\0';
        owl_window_decl_set_main_menu(decl, nameBuf, propTok.line);
        g_window_main_menu_tok     = propTok;
        g_window_main_menu_pending = true;
    }
    return true;
}

/* Resolution differee de `MenuPrincipal = X` : appelee a la fermeture du body
 * de la Fenetre, quand tous les MenuPrincipal et champs sont connus. */
static void window_resolve_main_menu(OwlWindowDecl* decl) {
    if (decl == NULL || !g_window_main_menu_pending) {
        g_window_main_menu_pending = false;
        return;
    }
    g_window_main_menu_pending = false;
    const char* want = decl->main_menu_name;
    if (want == NULL) return;
    if (owl_window_decl_find_menu(decl, want) != NULL) return;

    OwlErrorCode code = (owl_window_decl_find_control(decl, want) != NULL)
                        ? E_SEM_MENU_ASSIGN_TYPE_MISMATCH
                        : E_SEM_MENU_ASSIGN_UNKNOWN;
    owl_emit_error_at(&g_window_main_menu_tok, code, "name", want, NULL);
    parser.panicMode = false;
}

/*  — resolution differee d'une attache `MenuContextuel = X` : le nom
 * doit designer un bloc `X est un MenuContextuel` de la fenetre (pas un
 * MenuPrincipal, pas un champ, pas un inconnu). */
static void window_resolve_context_menu_ref(OwlWindowDecl* decl,
                                            const char* want, int line) {
    if (want == NULL) return;
    const OwlMenuDecl* m = owl_window_decl_find_menu(decl, want);
    if (m != NULL && m->is_context) return;   /* OK : bon type */

    Token synth;
    synth.start  = want;
    synth.length = (int)strlen(want);
    synth.line   = line;
    synth.column = 0;
    synth.type   = TOKEN_IDENTIFIER;

    /* Trouve comme MenuPrincipal (m non NULL, is_context==0) ou comme champ :
     * mauvais type. Sinon : identificateur inconnu. */
    OwlErrorCode code = (m != NULL
                         || owl_window_decl_find_control(decl, want) != NULL)
                        ? E_SEM_CTXMENU_ASSIGN_TYPE_MISMATCH
                        : E_SEM_CTXMENU_ASSIGN_UNKNOWN;
    owl_emit_error_at(&synth, code, "name", want, NULL);
    parser.panicMode = false;
}

/* Resolution differee de toutes les attaches `MenuContextuel = X` (fenetre +
 * champs), a la fermeture du body : un bloc MenuContextuel peut etre declare
 * apres le champ qui le reference. */
static void window_resolve_context_menus(OwlWindowDecl* decl) {
    if (decl == NULL) return;
    window_resolve_context_menu_ref(decl, decl->context_menu_name,
                                    decl->context_menu_line);
    for (int i = 0; i < decl->control_count; i++) {
        OwlControlDecl* c = &decl->controls[i];
        window_resolve_context_menu_ref(decl, c->context_menu_name,
                                        c->context_menu_line);
        /*  — le menu de loupe attache (`MenuLoupe = X`) doit aussi
         * designer un bloc `X est un MenuContextuel` de la fenetre : meme
         * resolveur (memes diagnostics type-mismatch / inconnu). */
        window_resolve_context_menu_ref(decl, c->magnifier_menu_name,
                                        c->magnifier_menu_line);
    }
}

/* Parse un sous-champ "Libelle/Bouton/Saisie nom ... FIN".
 * Le current token est sur le mot-cle (TOKEN_LIBELLE/BOUTON/SAISIE). */
/* Phase G v2 — DSL syntax post-fixed style canon : 'lblX est un Libellé ... FIN'.
 * Le caller a deja consomme 'IDENT est un/une <kind>'. On recoit kind +
 * Token du nom + line ; on parse le body jusqu'au FIN matching. */
static void window_parse_subfield(OwlWindowDecl* decl, OwlControlKind kind,
                                   Token ctrlTok, int kindLine) {
    /*  — un champ widget (Saisie / Bouton / Libelle / ...) declare
     * dans une Fenetre porte un nom global au runtime (proxy ObjUiControlRef
     * pose dans vm.globals, cf. infra L16264). Si ce nom collisionne avec
     * une variable globale du PROJET (declaree au top-level d'un fichier
     * du meme projet, voisin ou courant), c'est un shadow scope-different
     * (pilier 2 OWL : determinisme lecture). Alignement avec le check
     * declare_variable scope>0 / scope=0+windowDecl. L'entree
     * g_declaredGlobals[] peut etre :
     *   - un global declare au top-level du fichier courant
     *   - un global hydrate depuis un voisin (hydrate_globals_from_neighbors)
     * dans les deux cas la collision est un shadow legitime. */
    for (int i = decl_globals_bucket_head(ctrlTok.start, ctrlTok.length); i != -1;
         i = g_declaredGlobals[i].hashNext) {
        if (!decl_globals_match(i, ctrlTok.start, ctrlTok.length)) continue;
        if (g_declaredGlobals[i].isStructureType) continue;
        if (g_declaredGlobals[i].isPrescanned) continue;
        char outerName[64];
        int nl = g_declaredGlobals[i].nameLen;
        if (nl >= (int)sizeof(outerName)) nl = (int)sizeof(outerName) - 1;
        memcpy(outerName, g_declaredGlobals[i].name, (size_t)nl);
        outerName[nl] = '\0';
        char lineBuf[16];
        snprintf(lineBuf, sizeof(lineBuf), "%d", g_declaredGlobals[i].line);
        owl_emit_error_at(&ctrlTok, E_SEM_VAR_SHADOWS_OUTER_SCOPE,
                          "name", outerName,
                          "line", lineBuf,
                          NULL);
        /*  — reset panicMode pour ne pas casser le parse du body
         * du subfield (PROPRIETES, EVENEMENTS, ...). Sans ca, le path
         * normal du subfield skip les statements suivants jusqu'a sync,
         * ce qui declenche un faux positif E_SEM_DSL_PROPRIETES_BLOCK_
         * MISSING_CONTROL sur le meme champ. Le shadow est purement
         * semantique : la structure du body reste valide a parser. */
        parser.panicMode = false;
        break;
    }

    /* Allocation du nom + verification d'unicite dans la fenetre. */
    char* ctrlName = (char*)malloc((size_t)ctrlTok.length + 1);
    memcpy(ctrlName, ctrlTok.start, ctrlTok.length);
    ctrlName[ctrlTok.length] = '\0';

    OwlControlDecl* control = NULL;
    if (decl && owl_window_decl_find_control(decl, ctrlName) != NULL) {
        owl_emit_error_at(&ctrlTok, E_SEM_DSL_CONTROL_NAME_DUPLICATE,
                          "name", ctrlName,
                          "window", decl->name,
                          NULL);
        free(ctrlName);
        /*  — saute le corps du champ en doublon plutot que de le
         * parser sans decl. La reprise generique du body (plus bas) teste
         * check(TOKEN_NEWLINE), une condition morte : advance_token boucle
         * par-dessus les NEWLINE sans jamais les exposer. Elle courait donc
         * jusqu'au premier FIN venu — celui du bloc PROPRIETES — d'ou un
         * « PROPRIETES manquant » fantome puis un comptage de FIN decale qui
         * fermait la Fenetre un cran trop tot. Trois erreurs pour une faute.
         * dsl_skip_block_body consomme le corps jusqu'a son FIN
         * matching inclus : le comptage reste juste, l'erreur reste seule. */
        dsl_skip_block_body();
        parser.panicMode = false;
        return;
    }

    /*  — prefixe de nommage canonique (opt-in projet). */
    field_check_canonical_prefix(ctrlTok, owl_control_kind_info(kind));

    {
        control = owl_control_decl_new(kind, ctrlName, kindLine);
        /*  — Modele C : on pose un ObjUiControlRef dans
         * vm.globals (proxy de resolution). Le ref est sans storage : a
         * chaque OP_STRUCT_GET/SET, on resout via vm_window_stack_top() ->
         * inst->controls[] pour atteindre l'ObjUiControlInstance attache a
         * la fenetre courante. Sans fenetre ouverte = erreur runtime
         * explicite (cf. vm.c::OP_STRUCT_GET).
         *
         * La cle de resolution est strippee (invariant 2 accent-insensible).
         * Le decl conserve son nom brut (objectName Qt + affichage). */
        char gstripped[256];
        int glen = scanner_strip_accents(ctrlName, (int)strlen(ctrlName),
                                         gstripped, sizeof(gstripped));
        ObjString* gname = obj_copy_string(gstripped, glen);
        /*  lot 2 — gname doit etre rootee pendant l'alloc de ref
         * (ALLOCATE_OBJ peut declencher GC sous DEBUG_STRESS_GC) ET pendant
         * table_set (grow de vm.globals -> alloc -> GC). Sans push, la string
         * orpheline est libre + le slot peut etre reattribue (signature :
         * concat foireuse type 'LIB_X__LIB_X'). */
        vm_push(OBJ_VAL(gname));
        /*  — pass gname (nom strippe) au ref pour resolution
         * stable. Le pointeur `control` sera freed par
         * owl_window_decl_add_control (shallow copy + free), donc on ne
         * peut pas se baser dessus pour la resolution runtime. */
        ObjUiControlRef* ref = obj_new_ui_control_ref_named(control, gname);
        vm_push(OBJ_VAL(ref));
        obj_globals_set_kv(gname, OBJ_VAL(ref));  /*  : canon */
        vm_pop();  /* ref */
        vm_pop();  /* gname */
    }
    free(ctrlName);

    /* Phase 6 : nouveau scope pour les aliases de PROCEDURE custom du
     * widget. Les user_procs declarees dans ce control sont visibles
     * uniquement entre push et pop. */
    dsl_aliases_push_scope();

    /*  lot 1b +  lot 3-bis A1 — active l'isolation du scope
     * champ pour TOUT le body (top-level champ ET events/procedures, qui
     * resolvent les variables prefixees). Push dans la mini-stack pour les
     * conteneurs (recursion sur sous-champs : chaque parent reste rootable
     * par le GC via gc_mark_compiler_roots → mark_control_decl). Pop au
     * sortir restaure le parent. */
    if (g_control_decl_top >= G_CONTROL_DECL_STACK_MAX) {
        /* Limite interne (32 niveaux d'imbrication Conteneur/ZoneRepetee).
         * Cas pathologique : un .owl avec 32 conteneurs imbriques. Pas
         * d'OwlError dedie : abort propre via parser.hadError. */
        fprintf(stderr,
                "[compile] control nesting depth > %d (limite interne)\n",
                G_CONTROL_DECL_STACK_MAX);
        parser.hadError = true;
        return;
    }
    g_control_decl_stack[g_control_decl_top++] = control;

    /*  — top-level executable du champ. Tout code de niveau 0 dans
     * le body du champ (declarations + statements orphelins) est compile dans
     * cette ObjFunction implicite, executee A L'OUVERTURE apres le top-level
     * fenetre, dans l'ordre d'ecriture des champs.
     *
     * SCOPE (1a) : init SANS begin_scope() -> scopeDepth 0 -> les declarations
     * emettent OP_DEFINE_GLOBAL. En 1a les variables du top-level champ
     * tombent donc AUSSI en globales (fuite transitoire assumee ; l'isolation
     * du scope champ = Lot 1b). */
    Compiler ctrlTopCompiler;
    init_compiler(&ctrlTopCompiler, TYPE_FUNCTION);
    {
        char topFnName[200];
        snprintf(topFnName, sizeof(topFnName), "__champ_%s_TopLevel",
                 control ? control->name : "?");
        current->function->name =
            obj_copy_string(topFnName, (int)strlen(topFnName));
    }

    /* Parse le body du sous-champ jusqu'a FIN. */
    bool ctrlPropertiesBlockSeen = false;
    int  voletCount = 0;  /*  — nombre de sous-blocs Volet (kind ONGLET) */
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        if (parser.panicMode) {
            while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                advance_token();
            }
            parser.panicMode = false;
        }
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;

        /* DSL v2 : bloc PROPRIETES ... FIN — section statique des props. */
        if (check(TOKEN_PROPRIETES)) {
            Token propTok = parser.current;
            advance_token();
            if (ctrlPropertiesBlockSeen) {
                owl_emit_error_at(&propTok, E_SYNTAX_DUPLICATE_PROPRIETES_CONTROL);
            }
            ctrlPropertiesBlockSeen = true;
            bool firstProp = true;
            /*  : buffer cascade pour regroupement compile-time. */
            CascadeBuffer ctrlCascadeBuf;
            cascade_buffer_init(&ctrlCascadeBuf);
            CascadeBuffer* savedCascadeBufCtrl = g_cascade_buffer;
            g_cascade_buffer = &ctrlCascadeBuf;
            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                while (check(TOKEN_NEWLINE)) advance_token();
                if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
                if (!check(TOKEN_IDENTIFIER) && !check(TOKEN_LIBELLE)
                    && !check(TOKEN_BOUTON) && !check(TOKEN_SAISIE)
                    && !check(TOKEN_ETAT)) {
                    owl_emit_error_current(E_SYNTAX_EXPECTED_PROP_NAME_IN_PROPRIETES);
                    /*  — filet anti-hang : window_skip_to_next_stmt
                     * fait break sans consommer sur un token-sentinelle
                     * (PROCEDURE/FONCTION/champ...). Si le curseur n'a pas
                     * avance, le bloc PROPRIETES est manifestement fini ->
                     * sortir au lieu de boucler a l'infini. */
                    const char* beforeSkip = parser.current.start;
                    window_skip_to_next_stmt();
                    if (parser.current.start == beforeSkip) break;
                    continue;
                }
                if (!firstProp && !crossedNewline) {
                    owl_emit_error_current(E_SYNTAX_PROPS_NEED_SEPARATOR);
                }
                firstProp = false;
                control_parse_property_init(control);
            }
            g_cascade_buffer = savedCascadeBufCtrl;
            cascade_buffer_flush(&ctrlCascadeBuf, CASCADE_FLUSH_CONTROL, control,
                                  "__ctrl_prop");
            cascade_buffer_free(&ctrlCascadeBuf);
            /* FIN du bloc : doit etre sur sa propre ligne (canon). */
            if (check(TOKEN_FIN) && !crossedNewline && !firstProp) {
                owl_emit_error_current(E_SYNTAX_FIN_ON_OWN_LINE);
            }
            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROPRIETES);
            /* Un widget declare des sous-blocs APRES son bloc PROPRIETES : un
             * PROCEDURE pour tout champ, et en plus des sous-champs pour les
             * conteneurs (Volet enfant / colonne / sous-champ). Une erreur sur
             * une propriete laisse panicMode arme au FIN du bloc (, pour
             * ne pas relancer une cascade sur un bloc jumeau) ; sans reset ici,
             * ce sous-bloc suivant se fait engloutir par la resync du body loop
             * (qui degenere en "skip jusqu'au FIN" et avale le END du PROCEDURE),
             * produisant une cascade trompeuse "FIN desequilibre" / "fichier ne
             * peut contenir que le bloc Fenetre" au lieu d'une erreur nette sur
             * la seule prop fautive.  : on desarme donc pour TOUT kind
             * de champ (avant ce fix, seuls les conteneurs etaient couverts, ce
             * qui laissait les widgets simples suivis d'un PROCEDURE cascader). */
            parser.panicMode = false;
            continue;
        }

        /* Dans le body d'un sous-champ : props (nom = literal) ou PROCEDURE.
         * Les keywords-types Libellé/Bouton/Saisie peuvent apparaître comme
         * NOM de propriété (ex: 'Libellé = "OK"' sur un Bouton) — peek pour
         * distinguer prop vs variable locale 'nom est un Type'. */
        if (check(TOKEN_IDENTIFIER) || check(TOKEN_LIBELLE)
            || check(TOKEN_BOUTON)   || check(TOKEN_SAISIE)) {
            Scanner ss = parser.scanner;
            Token   sc = parser.current;
            Token   sp = parser.previous;
            bool    sn = crossedNewline;
            advance_token();
            bool isProperty = check(TOKEN_EQUAL);
            bool isVariable = check(TOKEN_EST);
            parser.scanner = ss; parser.current = sc; parser.previous = sp;
            crossedNewline = sn;

            if (isProperty) {
                control_parse_property_init(control);
            } else if (isVariable) {
                /* 'IDENT est un Type' : peek le Type. 3 cas :
                 *   - colonne -> declaration valide UNIQUEMENT dans une Table
                 *   - Libelle/Bouton/Saisie/Table -> sous-widget interdit
                 *   - autre -> variable locale (V1 : warning + skip)
                 * Le caller a deja consume IDENT, ici on a EST puis Type. */
                Scanner ss2 = parser.scanner;
                Token   sc2 = parser.current;
                Token   sp2 = parser.previous;
                bool    sn2 = crossedNewline;
                Token   nameTok = parser.current;
                int     kindLine = parser.current.line;
                advance_token(); /* consume IDENT */
                advance_token(); /* consume EST */
                consume_en_a_an_filler(); /*  : copule EN `is a/an` */
                bool nestedSawChamp = false;
                if (check_ident_champ()) {
                    advance_token();
                    nestedSawChamp = true;
                    skip_optional_de_after_champ(); /*  */
                }
                /*  — un noeud de menu (ou un MenuPrincipal) declare
                 * dans un champ est orphelin : meme chemin de validation que
                 * dans le body de la Fenetre. */
                MenuKeyword nestedMenuKw = menu_keyword_of_token(parser.current);
                if (nestedMenuKw != MENU_KW_NONE) {
                    parser.scanner = ss2; parser.current = sc2; parser.previous = sp2;
                    crossedNewline = sn2;
                    if (nestedMenuKw == MENU_KW_MAIN
                        || nestedMenuKw == MENU_KW_CONTEXT) {
                        Token mTok = parser.current;
                        char mName[128];
                        int ml = mTok.length < 127 ? mTok.length : 127;
                        memcpy(mName, mTok.start, (size_t)ml);
                        mName[ml] = '\0';
                        owl_emit_error_at(&mTok, E_SEM_MENU_UNKNOWN_BLOCK,
                                          "name", mName,
                                          "kind", owl_control_kind_name_fr(kind),
                                          NULL);
                        parser.panicMode = false;
                        advance_token(); advance_token();
                        consume_en_a_an_filler();
                        advance_token();
                        menu_skip_unknown_block();
                        parser.panicMode = false;
                    } else {
                        menu_reject_orphan_node(nestedMenuKw, parser.current);
                    }
                    continue;
                }
                bool isColonne = check(TOKEN_COLONNE);
                /*  — sous-bloc Volet (page d'un Champ Onglet). */
                bool isVolet = is_volet_token();
                /*  — def de type dans un body de champ
                 * ('X est une Enumeration/Structure/Combinaison/Classe/Interface').
                 * NON supportee aujourd'hui (avant : warning + code jete). Decl
                 * statique declarative, surtout PAS du code d'init -> ne doit PAS
                 * etre routee vers le top-level champ (sinon executee a
                 * l'ouverture). On garde le comportement legacy : warning + skip,
                 * sans introduire de support (hors scope 1a). */
                bool isTypeDef = check(TOKEN_ENUMERATION) || check(TOKEN_STRUCTURE)
                              || check(TOKEN_COMBINAISON)  || check(TOKEN_CLASSE)
                              || check(TOKEN_INTERFACE);
                /* Detection unifiee : delegate au helper detect_subfield_kind
                 * qui consulte CONTROL_KINDS (cf src/ui_decl.c). Le prefixe
                 * 'Champ' (nestedSawChamp) est tranche par les branches ci-dessous. */
                OwlControlKind detectedKind = OWL_CONTROL_LABEL;
                bool subWidget = detect_subfield_kind(&detectedKind);
                /*  : type IDENT non reconnu (typo de widget) suivi d'un
                 * bloc PROPRIETES, IMBRIQUÉ dans un Conteneur. Comme côté
                 * fenêtre, on le nomme + skip au lieu de le traiter
                 * en variable locale (sinon le PROPRIETES orphelin cascade en
                 * erreurs trompeuses). parser.current est sur le type ici. */
                bool isUnknownWidgetNested = false;
                Token unknownNestedTok = parser.current;
                if (!subWidget && !isTypeDef && !isColonne && !isVolet
                    && check(TOKEN_IDENTIFIER)) {
                    Scanner pk = parser.scanner;
                    Token pc = parser.current, pp = parser.previous;
                    bool pn = crossedNewline;
                    advance_token();
                    while (check(TOKEN_NEWLINE)) advance_token();
                    isUnknownWidgetNested = check(TOKEN_PROPRIETES);
                    parser.scanner = pk; parser.current = pc;
                    parser.previous = pp; crossedNewline = pn;
                }
                if (isTypeDef) {
                    Token tdTok = nameTok;
                    owl_emit_warning_at(&tdTok, W_SEM_FIELD_LOCAL_VAR_IGNORED, NULL);
                    /* On est positionne sur le keyword de type (IDENT/EST/(Champ)
                     * deja consommes plus haut). Consume le keyword puis skip le
                     * body jusqu'au FIN matching (meme schema que isRejectedType
                     * cote fenetre). */
                    advance_token(); /* ENUMERATION/STRUCTURE/COMBINAISON/CLASSE/INTERFACE */
                    window_skip_nested_block();
                    parser.panicMode = false;
                } else if (isColonne) {
                    if (kind != OWL_CONTROL_TABLE) {
                        owl_emit_error_at(&nameTok, E_SEM_DSL_COLONNE_OUTSIDE_TABLE);
                        parser.scanner = ss2; parser.current = sc2; parser.previous = sp2;
                        crossedNewline = sn2;
                        window_skip_to_next_stmt();
                    } else {
                        /* parse_one_column attend qu'on soit sur TOKEN_COLONNE. */
                        parse_one_column(control, nameTok, kindLine);
                    }
                } else if (isVolet) {
                    /*  — un Volet n'est valide que directement dans un
                     * Champ Onglet. Ailleurs (Conteneur, autre Volet, ...) =
                     * erreur. Dans un Onglet : recursion enfants comme un
                     * Conteneur (kind VOLET, cf branche container ci-dessous). */
                    if (kind != OWL_CONTROL_ONGLET) {
                        owl_emit_error_at(&nameTok, E_SEM_DSL_VOLET_OUTSIDE_ONGLET);
                        parser.scanner = ss2; parser.current = sc2; parser.previous = sp2;
                        crossedNewline = sn2;
                        window_skip_control_block();
                        parser.panicMode = false;
                    } else {
                        advance_token(); /* consume 'Volet' */
                        int prevCount = decl ? decl->control_count : 0;
                        window_parse_subfield(decl, OWL_CONTROL_VOLET,
                                              nameTok, kindLine);
                        if (decl && decl->control_count > prevCount && control) {
                            OwlControlDecl* directChild =
                                &decl->controls[decl->control_count - 1];
                            owl_control_decl_set_parent_name(directChild,
                                                             control->name);
                        }
                        voletCount++;
                    }
                } else if (subWidget && !nestedSawChamp
                           && owl_control_kind_is_ambiguous(detectedKind)
                           && !peek_proprietes_follows()) {
                    /*  lot 1-bis : Image/Liste nu SANS corps
                     * PROPRIETES imbrique = variable/collection (le type gagne).
                     * Pas d'erreur Champ : restore au debut du statement et
                     * compile via declaration() (scanner sur le genre pour le
                     * peek PROPRIETES). */
                    parser.scanner = ss2; parser.current = sc2; parser.previous = sp2;
                    crossedNewline = sn2;
                    declaration();
                } else if (subWidget && !nestedSawChamp) {
                    /*  : prefixe 'Champ' obligatoire (controle nu
                     * imbrique). Erreur nommee + skip du body. Couvre les 9
                     * genres controle-seuls (toujours) ET Image/Liste nu suivi
                     * d'un corps PROPRIETES (exception messaging). */
                    char cname[128];
                    int cl = nameTok.length < 127 ? nameTok.length : 127;
                    memcpy(cname, nameTok.start, (size_t)cl);
                    cname[cl] = '\0';
                    owl_emit_error_at(&nameTok, E_SEM_DSL_CHAMP_PREFIXE_REQUIS,
                                      "name", cname,
                                      "genre", owl_control_kind_name_fr(detectedKind),
                                      NULL);
                    /* Restore au debut du statement (sur l'IDENT) avant le skip. */
                    parser.scanner = ss2; parser.current = sc2; parser.previous = sp2;
                    crossedNewline = sn2;
                    window_skip_control_block();
                    parser.panicMode = false;
                } else if (subWidget && (kind == OWL_CONTROL_CONTAINER ||
                                          kind == OWL_CONTROL_ZONE_REPETEE ||
                                          kind == OWL_CONTROL_VOLET)) {
                    /* Conteneur : nesting libre. ZoneRepetee : sous-champs =
                     * template instancie a chaque repetition. Volet :
                     * page d'un Onglet, meme recursion enfants que le Conteneur.
                     * Le kind a deja ete resolu par detect_subfield_kind ci-dessus. */
                    advance_token(); /* consume Type (keyword OU IDENT) */
                    int prevCount = decl ? decl->control_count : 0;
                    window_parse_subfield(decl, detectedKind, nameTok, kindLine);
                    /* Lot F : append-en-fin = le widget direct (PNL_X) est
                     * appende APRES ses petits-enfants. Donc son index est le
                     * DERNIER post-recursion. */
                    if (decl && decl->control_count > prevCount && control) {
                        OwlControlDecl* directChild =
                            &decl->controls[decl->control_count - 1];
                        owl_control_decl_set_parent_name(directChild, control->name);
                    }
                } else if (subWidget) {
                    Token tok = parser.current;
                    owl_emit_error_at(&tok, E_SEM_DSL_SUBFIELD_NOT_VALID_IN_KIND,
                                      "kind", owl_control_kind_name(kind),
                                      NULL);
                    advance_token(); /* consume Type */
                    window_skip_nested_block();
                } else if (isUnknownWidgetNested) {
                    /*  : widget à type inconnu (typo) + PROPRIETES dans
                     * un Conteneur. Erreur nommée + skip du bloc (anti-cascade),
                     * miroir du site fenêtre. */
                    char tname[128];
                    int tl = unknownNestedTok.length < 127
                             ? unknownNestedTok.length : 127;
                    memcpy(tname, unknownNestedTok.start, (size_t)tl);
                    tname[tl] = '\0';
                    owl_emit_error_at(&unknownNestedTok,
                                      E_SEM_DSL_UNKNOWN_WIDGET_TYPE,
                                      "name", tname, NULL);
                    advance_token(); /* consume type IDENT inconnu */
                    window_skip_nested_block();
                    parser.panicMode = false;
                } else {
                    /*  — 'nom est un Type [= init]' au niveau 0 du
                     * champ = declaration du top-level champ. Restore au debut
                     * du statement et compile via declaration() dans
                     * ctrlTopCompiler (current, scopeDepth 0 -> global en 1a). */
                    parser.scanner = ss2; parser.current = sc2; parser.previous = sp2;
                    crossedNewline = sn2;
                    declaration();
                }
            } else {
                /*  — statement de niveau 0 du champ (Trace(...),
                 * x += y, appel…) = code top-level champ. Compile via
                 * declaration() dans ctrlTopCompiler (current). Avant : warning
                 * W_SEM_FIELD_BODY_UNKNOWN + skip (code jete). */
                declaration();
            }
        } else if (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION)) {
            advance_token(); /* consume PROCEDURE/FONCTION */
            if (!check(TOKEN_IDENTIFIER)) {
                owl_emit_error_current(E_SYNTAX_EXPECTED_BLOCK_NAME_AFTER_PROC);
                window_skip_nested_block();
                continue;
            }
            Token nameTok = parser.current;
            advance_token();

            char* blockName = (char*)malloc((size_t)nameTok.length + 1);
            memcpy(blockName, nameTok.start, nameTok.length);
            blockName[nameTok.length] = '\0';

            if (!match_token(TOKEN_LEFT_PAREN)) {
                owl_emit_error_at(&nameTok, E_SYNTAX_EXPECTED_LPAREN_AFTER_BLOCK_NAME);
                free(blockName);
                window_skip_nested_block();
                continue;
            }
            bool hasParams = !check(TOKEN_RIGHT_PAREN);

            /*  — l'event 'Initialisation' n'existe plus : le code
             * d'init vit dans le top-level du champ. Rejet net (break alpha). */
            if (window_ci_eq(blockName, "Initialisation")
                || window_ci_eq(blockName, "Initialization")) {
                owl_emit_error_at(&nameTok, E_SEM_DSL_INITIALISATION_OBSOLETE, NULL);
                int parenDepth = 1;
                while (parenDepth > 0 && !check(TOKEN_EOF)) {
                    if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                    else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                    if (parenDepth > 0) advance_token();
                }
                if (check(TOKEN_RIGHT_PAREN)) advance_token();
                window_skip_nested_block();
                free(blockName);
                continue;
            }

            /* Detection doublon : meme nom deja declare comme event ou
             * user_proc dans ce widget. Skip body et continue. */
            if (control && control_decl_has_block_name(control, blockName)) {
                owl_emit_error_at(&nameTok, E_SEM_DSL_PROC_DUPLICATE_IN_CONTROL,
                                  "name", blockName,
                                  NULL);
                int parenDepth = 1;
                while (parenDepth > 0 && !check(TOKEN_EOF)) {
                    if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                    else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                    if (parenDepth > 0) advance_token();
                }
                if (check(TOKEN_RIGHT_PAREN)) advance_token();
                window_skip_nested_block();
                free(blockName);
                continue;
            }

            if (is_predefined_control_block(kind, blockName)) {
                /* Lookup catalogue : si l'event a une signature canon a
                 * payload (cf event_catalog_widgets.c), on accepte les
                 * params et on les valide. Si non au catalogue (alias
                 * legacy comme "Clic"), on garde le warning historique. */
                const OwlEventDef* eventDef =
                    owl_event_catalog_find(kind, blockName);

                /* Buffer pour params declares (max 8). */
                char declaredNames[8][64];
                char declaredTypes[8][32];
                Token declaredTypeToks[8];
                int  declaredCount = 0;
                bool paramsParseOK = true;

                if (hasParams) {
                    /* Parse "name est un[e] type[, ...]" jusqu'au ')'. */
                    while (!check(TOKEN_RIGHT_PAREN) && !check(TOKEN_EOF)) {
                        if (declaredCount >= 8) {
                            owl_emit_error_current(E_SEM_DSL_TOO_MANY_EVENT_PARAMS);
                            paramsParseOK = false;
                            break;
                        }
                        if (!check(TOKEN_IDENTIFIER)) {
                            owl_emit_error_current(E_SEM_DSL_EXPECTED_PARAM_NAME_AFTER_LPAREN);
                            paramsParseOK = false;
                            break;
                        }
                        Token pNameTok = parser.current;
                        advance_token();
                        if (!match_token(TOKEN_EST)) {
                            owl_emit_error_current(E_SEM_DSL_EXPECTED_EST_AFTER_PARAM);
                            paramsParseOK = false;
                            break;
                        }
                        /*  : avale l'article EN `a`/`an` (le FR `un`/
                         * `une` est deja un filler scanner). */
                        consume_en_a_an_filler();
                        /* Type : peut etre un keyword (TOKEN_ENTIER, etc.)
                         * ou un IDENTIFIER (nom de type user/registry, FR ou EN). */
                        Token pTypeTok = parser.current;
                        advance_token();
                        int nlen = pNameTok.length < 63 ? pNameTok.length : 63;
                        memcpy(declaredNames[declaredCount], pNameTok.start, nlen);
                        declaredNames[declaredCount][nlen] = '\0';
                        int tlen = pTypeTok.length < 31 ? pTypeTok.length : 31;
                        memcpy(declaredTypes[declaredCount], pTypeTok.start, tlen);
                        declaredTypes[declaredCount][tlen] = '\0';
                        declaredTypeToks[declaredCount] = pTypeTok;
                        declaredCount++;
                        if (!match_token(TOKEN_COMMA)) break;
                    }
                }
                consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_BLOCK_PARAMS);

                /*  Cas 1 : annotation type retour `: <Type>` toleree
                 * sur event de sous-champ (symetrique compile_user_proc_body
                 * et methode inline classe). */
                if (is_return_type_colon() ||
                    (check(TOKEN_COLON) && !crossedNewline)) {
                    advance_token(); /* consume ':' */
                    skip_type_spec();
                }

                /* Validation contre catalogue. */
                if (paramsParseOK && declaredCount > 0) {
                    if (eventDef == NULL) {
                        /* Defensif : ne devrait plus arriver depuis le napalm
                         * des aliases legacy — is_predefined_control_block
                         * delegue 100% au catalog. Si on tombe ici c'est
                         * qu'un nouveau path d'event a ete introduit hors
                         * catalog. */
                        owl_emit_error_at(&nameTok,
                                          E_SEM_DSL_EVENT_PARAMS_NO_CATALOG);
                        declaredCount = 0;
                    } else if (declaredCount > eventDef->paramCount) {
                        /* Construit la string "name est un Type, ..." cote
                         * appelant (placeholder unique {signature}, cf.
                         * design  "string pre-construite"). */
                        char sigBuf[160];
                        if (eventDef->paramCount == 0) {
                            snprintf(sigBuf, sizeof(sigBuf), "aucun");
                        } else {
                            snprintf(sigBuf, sizeof(sigBuf), "%s est un %s%s",
                                eventDef->params[0].name,
                                eventDef->params[0].typeName,
                                eventDef->paramCount > 1 ? ", ..." : "");
                        }
                        char declaredBuf[16], maxBuf[16];
                        snprintf(declaredBuf, sizeof(declaredBuf), "%d", declaredCount);
                        snprintf(maxBuf, sizeof(maxBuf), "%d", eventDef->paramCount);
                        owl_emit_error_at(&nameTok, E_SEM_DSL_EVENT_TOO_MANY_PARAMS,
                                          "event", blockName,
                                          "declared", declaredBuf,
                                          "max", maxBuf,
                                          "signature", sigBuf,
                                          NULL);
                        declaredCount = 0;
                    } else {
                        /* Type check par position.  : on resout le type
                         * declare ET le type attendu vers leur canon FR
                         * accent-strip+minuscule, ce qui accepte les noms de
                         * type EN (`integer` -> `entier`...) comme une decl de
                         * param de procedure normale. */
                        for (int i = 0; i < declaredCount; i++) {
                            char declCanon[32], expCanon[32];
                            event_param_type_canon(declaredTypeToks[i],
                                declaredTypes[i], declCanon, sizeof(declCanon));
                            scanner_strip_accents(eventDef->params[i].typeName,
                                (int)strlen(eventDef->params[i].typeName),
                                expCanon, sizeof(expCanon));
                            for (char* p = expCanon; *p; p++)
                                *p = (char)tolower((unsigned char)*p);
                            if (strcmp(declCanon, expCanon) != 0) {
                                char posBuf[16];
                                snprintf(posBuf, sizeof(posBuf), "%d", i + 1);
                                owl_emit_error_at(&nameTok,
                                    E_SEM_DSL_EVENT_PARAM_TYPE_MISMATCH,
                                    "event", blockName,
                                    "position", posBuf,
                                    "name", declaredNames[i],
                                    "expected", eventDef->params[i].typeName,
                                    "got", declaredTypes[i],
                                    NULL);
                                declaredCount = 0;
                                break;
                            }
                        }
                    }
                }

                /* Bloc PROCEDURE de champ : MaFenetre + MonChamp dispos +
                 * params canon de l'event declares en locals. */
                const char* paramNamePtrs[8];
                for (int i = 0; i < declaredCount; i++)
                    paramNamePtrs[i] = declaredNames[i];
                ObjFunction* fn = compile_event_block_body_with_params(
                    blockName, true, declaredCount, paramNamePtrs);
                if (control && fn) {
                    /* Normalise le nom du bloc event vers son canon FR (le
                     * catalog est source unique). FR (surBoutonGauche) et EN
                     * (onLeftButtonDown) se rangent alors sous la MEME cle :
                     * le cablage runtime (find_event / find_callback_fn /
                     * dispatch Qt) retrouve le handler par le canon quel que
                     * soit le nom source ecrit par l'utilisateur. Sans ca, un
                     * handler EN reste stocke sous son nom EN et le cablage
                     * (qui cherche par canon FR) le rate -> event non cable. */
                    owl_control_decl_add_event(control,
                        eventDef ? eventDef->canonical : blockName,
                        fn, nameTok.line);
                }
                /* Clear panicMode pour que le parser DSL parent (subfield body)
                 * reprenne propre meme si une erreur s'est produite dans le
                 * body de la PROCEDURE Clic/etc. */
                parser.panicMode = false;
            } else {
                /*  — PROCEDURE a nom libre (helper) dans un widget de
                 * Fenetre : refusee. Miroir de la politique Etat : seul le
                 * top-level de la Fenetre porte des procedures globales ; un
                 * widget ne porte que ses events (noms connus du catalogue).
                 * Message pedagogique : deplacer la proc au niveau superieur.
                 * On skip les params + le body (anti-cascade) et on repart
                 * propre. */
                owl_emit_error_at(&nameTok, E_SEM_DSL_PROC_HELPER_NOT_TOPLEVEL,
                                  "name", blockName, NULL);
                int parenDepth = 1;
                while (parenDepth > 0 && !check(TOKEN_EOF)) {
                    if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                    else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                    if (parenDepth > 0) advance_token();
                }
                if (check(TOKEN_RIGHT_PAREN)) advance_token();
                window_skip_nested_block();
                parser.panicMode = false;
            }

            free(blockName);
        } else {
            /*  — statement de niveau 0 non-IDENTIFIER (SI, POUR,
             * TANTQUE, SELON…) = code top-level champ. Compile via
             * declaration() dans ctrlTopCompiler. Avant : advance_token (jete). */
            declaration();
        }
    }

    /*  — finalise le top-level champ. Stocke l'ObjFunction seulement
     * si le body contient du code utile (chunk->count > 1 = plus que l'OP_RETURN
     * implicite). end_compiler restore current vers l'enclosing (winTopCompiler
     * ou le compiler ouvert par le caller). */
    ObjFunction* ctrlTopFn = end_compiler();
    if (control && ctrlTopFn && ctrlTopFn->chunk && ctrlTopFn->chunk->count > 1) {
        control->top_level = ctrlTopFn;
    }

    if (check(TOKEN_FIN)) {
        advance_token();
    } else {
        owl_emit_error_at(&ctrlTok, E_SYNTAX_EXPECTED_FIN_CLOSE_CONTROL);
    }

    /*  lot 1b +  lot 3-bis A1 — pop la mini-stack : top
     * redevient le parent (Conteneur/ZoneRepetee) ou NULL au retour au
     * niveau fenetre. Le control qu'on vient de parser est append a
     * decl->controls[] par le caller (ou deja la-bas) → reste rooted via
     * mark_ui_decl_roots. */
    if (g_control_decl_top > 0) g_control_decl_top--;

    /* Phase 6 : pop le scope d'aliases du widget. */
    dsl_aliases_pop_scope();

    /* DSL v2 : bloc PROPRIETES obligatoire dans chaque widget. */
    if (!ctrlPropertiesBlockSeen) {
        char nameBuf[128];
        snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                 ctrlTok.length, ctrlTok.start);
        owl_emit_error_at(&ctrlTok, E_SEM_DSL_PROPRIETES_BLOCK_MISSING_CONTROL,
                          "name", nameBuf,
                          NULL);
    }

    /*  — les colonnes d'une Table sont compile-time only (aucun
     * ajout runtime). Une Table sans colonne est un widget inutile : on la
     * refuse a la compilation, avec la ligne de la declaration du champ. */
    if (control && kind == OWL_CONTROL_TABLE && control->column_count == 0) {
        owl_emit_error_at(&ctrlTok, E_SEM_DSL_TABLE_NO_COLUMN, NULL);
    }

    /*  — un Champ Onglet sans aucun Volet est un widget inutile (les
     * volets sont declares a la compilation, aucun ajout runtime en statique).
     * Refuse a la compilation, sur la ligne de la declaration du champ. */
    if (control && kind == OWL_CONTROL_ONGLET && voletCount == 0) {
        owl_emit_error_at(&ctrlTok, E_SEM_DSL_ONGLET_NO_VOLET, NULL);
    }

    /*  — Valeur (volet actif, 1-based) hors bornes : detectable a la
     * compilation quand elle est un litteral entier ecrit hors [1, nb_volets].
     * Le token capture (control->ong_valeur_*) porte la position exacte de la
     * valeur pour un diagnostic pointant sur le litteral fautif. */
    if (control && kind == OWL_CONTROL_ONGLET && control->ong_valeur_set
        && voletCount > 0
        && (control->ong_valeur < 1 || control->ong_valeur > voletCount)) {
        Token vt;
        vt.start  = ctrlTok.start;
        vt.length = ctrlTok.length;
        vt.line   = control->ong_valeur_line;
        vt.column = control->ong_valeur_col;
        vt.type   = TOKEN_INTEGER;
        char valBuf[32], cntBuf[32];
        snprintf(valBuf, sizeof(valBuf), "%ld", control->ong_valeur);
        snprintf(cntBuf, sizeof(cntBuf), "%d", voletCount);
        owl_emit_error_at(&vt, E_SEM_DSL_ONGLET_VALEUR_HORS_BORNES,
                          "value", valBuf,
                          "count", cntBuf,
                          NULL);
    }

    /*  — un Volet doit porter un Libellé (le texte affiché sur son
     * onglet). Sans lui, l'onglet n'a pas de titre : erreur, sur la ligne de la
     * declaration du volet. */
    if (control && kind == OWL_CONTROL_VOLET) {
        bool hasLibelle = false;
        for (int i = 0; i < control->property_count; i++) {
            const char* pn = control->properties[i].name;
            if (pn && (strcasecmp(pn, "Libelle") == 0
                       || strcasecmp(pn, "Caption") == 0)) {
                hasLibelle = true;
                break;
            }
        }
        if (!hasLibelle) {
            char nameBuf[128];
            snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                     ctrlTok.length, ctrlTok.start);
            owl_emit_error_at(&ctrlTok, E_SEM_DSL_VOLET_LIBELLE_MANQUANT,
                              "name", nameBuf,
                              NULL);
        }
    }

    /*  — body complet parse : verifier les bornes numeriques posees sur
     * un Champ Saisie non bornable (cross-prop, ordre indifferent). */
    input_emit_bound_not_numeric_warning_if(control);

    /* Append au decl. NB : l'append doit rester EN FIN (et pas avant le parse
     * du body) — sinon le realloc du tableau lors de l'append d'un sibling
     * invaliderait le pointer `control` pendant qu'on parse encore son body.
     * L'ordre topologique parent->enfant pour le runtime est gere
     * differemment (cf stdlib_ui.c : 2 passes via parent_name). */
    if (control && decl) {
        owl_window_decl_add_control(decl, control);
    }

    parser.panicMode = false;
}

/* ============================================================
 *  : pre-passe ordre-independant pour les blocs FEN/Etat.
 *
 * La contrainte historique "declarer avant d'utiliser" est lexicale stricte
 * (compilateur single-pass) : un PROCEDURE custom defini en bas d'une
 * Fenetre n'etait pas resoluble depuis un handler/top-level/PROCEDURE
 * defini plus haut. Ergonomie casse : layout en haut, helpers en bas =
 * pattern naturel d'ecriture d'une fenetre.
 *
 * Solution scope-locale : avant le parse reel du body, on fait un scan
 * leger qui collecte les noms des PROCEDURE custom au top-level du bloc
 * et les pre-enregistre :
 *   - dans dsl_aliases (pour resolution implicite '<proc>' -> '<owner>_<proc>')
 *   - dans global_track (pre-scan, pour passer le check 'fonction inconnue')
 *   - dans vm.globals avec NIL_VAL (le parse reel ecrasera avec la vraie fn)
 *
 * Le scan utilise un Scanner local (pas parser.scanner) — la pre-passe ne
 * touche jamais l'etat parser. Les erreurs eventuelles (syntaxe casse) sont
 * silencieusement avalees ; le parse reel les emettra avec contexte complet.
 *
 * Perimetre : top-level du bloc uniquement. Sous-champs et methodes de
 * classe non couverts (cf ticket : la classe est traitee separement,
 * sous-champ peut etre etendu plus tard si demande).
 * ============================================================ */

/* Helper de skip d'une parenthese matching dans un scanner local. La
 * lparen courante a deja ete consommee ; on consomme jusqu'a la rparen
 * matching incluse. */
static void prepass_skip_to_matching_rparen(Scanner* s) {
    int depth = 1;
    while (depth > 0) {
        Token t = scanner_scan_token(s);
        if (t.type == TOKEN_EOF) return;
        if (t.type == TOKEN_LEFT_PAREN)  depth++;
        else if (t.type == TOKEN_RIGHT_PAREN) depth--;
    }
}

/* Helper : est-ce un nom predefini de bloc fenetre OU 'Initialisation'
 * (rejet net ) ? Si oui, on ne doit PAS enregistrer comme
 * user_proc. */
static bool prepass_window_proc_is_predefined(const char* blockName,
                                                const char* windowName) {
    (void)windowName;
    if (window_ci_eq(blockName, "Initialisation")
        || window_ci_eq(blockName, "Initialization")) return true;
    return is_predefined_window_block(blockName);
}

/* Helper : est-ce un nom predefini de bloc Etat ? */
static bool prepass_etat_proc_is_predefined(const char* procName,
                                              const char* etatName) {
    if (window_ci_eq(procName, "Initialisation")
        || window_ci_eq(procName, "Initialization")) return true;
    if (etatName && strcasecmp(procName, etatName) == 0) return true;
    return strcasecmp(procName, "Filtre") == 0
        || strcasecmp(procName, "Filter") == 0
        || strcasecmp(procName, "Lecture") == 0
        || strcasecmp(procName, "Read") == 0
        || strcasecmp(procName, "Fermeture") == 0
        || strcasecmp(procName, "Closing") == 0;
}

/* Pre-enregistre une user_proc top-level Fenetre/Etat : alias DSL +
 * global track prescan + reservation slot vm.globals avec NIL. Le parse
 * reel ulterieur emettra OP_DEFINE_GLOBAL avec la vraie ObjFunction et
 * appellera global_track_declare qui consommera le flag prescan. */
static void prepass_register_user_proc(const char* ownerName,
                                         const char* blockName,
                                         int blockNameLen,
                                         int line) {
    /* 1. Alias DSL : '<proc>' -> '<owner>_<proc>'. dsl_aliases_add est
     *    desormais dedup : safe meme si parse reel reappellera. */
    char qualified[256];
    snprintf(qualified, sizeof(qualified), "%s_%s", ownerName, blockName);
    dsl_aliases_add(blockName, qualified);

    /* 2. Global track prescan pour le nom NU : permet a un appel
     *    `MonHelper(...)` plus haut dans le source de passer le check
     *    compile-time 'fonction/procedure inconnue'. La fonction
     *    global_track_declare appelee par le parse reel consommera ce
     *    flag prescan (cf modif  dans global_track_declare). */
    global_track_prescan(blockName, blockNameLen, line);
    /* hasInitializer=true pose par prescan -> pas de warn unused.
     * mark_initialized n'est pas necessaire (prescan le pose deja). */

    /* 3. Reserve le slot vm.globals avec NIL pour le nom NU. Le parse reel
     *    emettra OP_DEFINE_GLOBAL qui ecrasera avec la vraie ObjFunction
     *    via table_set. Idempotent. */
    ObjString* nuStr = obj_copy_string(blockName, blockNameLen);
    vm_push(OBJ_VAL(nuStr));
    obj_globals_set_kv(nuStr, NIL_VAL);
    vm_pop();

    /* 4. Reserve aussi le qualifie (le parse reel le fait aussi).
     *    Idempotent. */
    ObjString* qStr = obj_copy_string(qualified, (int)strlen(qualified));
    vm_push(OBJ_VAL(qStr));
    obj_globals_set_kv(qStr, NIL_VAL);
    vm_pop();
}

/*  — le type suivant `IDENT est un ...` designe-t-il un MEMBRE
 * d'element ou un bloc DSL a contexte propre PLUTOT qu'une vraie globale de
 * donnees ? Miroir des exclusions de var_declaration_after_est (~L14100) : un
 * Groupe est un membre addressable en nom nu (pas mangle `FEN$var`) ; Theme et
 * CollectionDeProcedures ouvrent leur propre espace de noms. Ces formes ne
 * doivent PAS etre pre-enregistrees comme globales d'element (sinon le nom nu
 * serait reecrit `FEN$X` a tort). Champ/Field sont deja consommes en amont
 * comme modificateur (token_is_champ_modifier). */
static bool prepass_type_not_element_global(Token typeTok) {
    if (typeTok.type != TOKEN_IDENTIFIER || typeTok.start == NULL) return false;
    char probe[40];
    int n = scanner_strip_accents(typeTok.start, typeTok.length,
                                  probe, sizeof(probe));
    if (n <= 0 || n >= (int)sizeof(probe)) return false;
    if ((n == 6 && strncasecmp(probe, "Groupe", 6) == 0) ||
        (n == 5 && strncasecmp(probe, "Group",  5) == 0) ||
        (n == 5 && strncasecmp(probe, "Theme",  5) == 0)) {
        return true;
    }
    return token_is_collection_kw(typeTok.start, typeTok.length);
}

/* Pre-passe d'un bloc Fenetre/Etat. Scanner part juste APRES le keyword
 * (Fenetre/Etat) — donc soit sur '(' (capture parametres Etat), soit sur
 * NEWLINE / token body. On scanne jusqu'au FIN matching (depth=0).
 *
 *  : collecte les PROCEDURE custom (forward-ref des helpers).
 *  : pre-enregistre aussi les variables de body element-global
 * (`FEN$var`) pour la SYMETRIE avec les procedures — une variable declaree
 * APRES un handler qui l'utilise doit rester forward-referencable. Meme
 * critere que var_declaration_after_est (niveau body, hors membre/bloc DSL).
 * Requiert un depth-tracking correct des noeuds de menu (MenuPrincipal /
 * SousMenu / OptionMenu / MenuSeparateur ferment tous par FIN) : sans ca la
 * pre-passe se termine trop tot sur le FIN d'un menu et rate les declarations
 * qui le suivent.
 *
 * isEtat : differencie le filtrage user_proc vs predefini.
 * ownerName : nom du bloc parent ('FEN_X' ou 'ETA_X') utilise pour le
 *             qualifie '<owner>_<proc>'.
 *
 * Note ouvreurs de bloc : on equilibre tout token connu pour ouvrir un
 * sous-bloc ferme par FIN. Aligne sur window_skip_nested_block. Sans
 * besoin d'etre exhaustif sur les keywords obscurs : un FIN mal apparie
 * dans le source = erreur compile reelle, le parse normal la levera. La
 * pre-passe peut juste finir trop tot (sur un FIN orphelin) — pas grave,
 * elle ne fait que pre-enregistrer ; ce qui n'a pas ete pre-enregistre
 * resterait introuvable avant declaration (comportement legacy). */
static void prepass_block_collect_procs(Scanner localScanner,
                                          const char* ownerName,
                                          bool isEtat) {
    /* Si on entre sur '(' (Etat avec params), skip jusqu'a la rparen
     * matching pour atteindre le body proprement dit. */
    {
        Scanner peek = localScanner;
        Token t = scanner_scan_token(&peek);
        /* Skip filler / newlines. scanner_scan_token retourne deja les
         * tokens sans filler ; mais NEWLINE est retourne. */
        while (t.type == TOKEN_NEWLINE || t.type == TOKEN_SEMICOLON) {
            localScanner = peek;
            t = scanner_scan_token(&peek);
        }
        if (t.type == TOKEN_LEFT_PAREN) {
            localScanner = peek;
            prepass_skip_to_matching_rparen(&localScanner);
        }
    }

    int depth = 0;  /* depth=0 = niveau top-level du bloc */
    /* Pour detecter 'IDENT est un X' au depth=0, on tracke un flag
     * "le precedent token au depth=0 etait un IDENT". */
    bool sawIdentAtTopLevel = false;
    /*  : un keyword ouvreur (PROCEDURE/FONCTION/SI/...) precede d'un
     * point est en realite un acces propriete/methode, pas un ouvreur de
     * bloc. Cas reel : `tTimer..Procedure = X` ou `Procedure` scanne comme
     * TOKEN_PROCEDURE. Sans cette garde, le faux PROCEDURE incremente depth
     * sans FIN apparie -> les vraies PROCEDURE suivantes passent a depth>0 et
     * ne sont plus pre-enregistrees (ordre-dependance regressive). */
    bool prevWasDot = false;
    /*  : meme piege via l'annotation de type. `f est une procedure`
     * scanne `est`(TOKEN_EST) puis `procedure`(TOKEN_PROCEDURE) ; ce dernier
     * est un nom de TYPE, pas un ouvreur de bloc. A n'importe quelle
     * profondeur (la decl locale dans un body est a depth>0), il ne doit pas
     * incrementer depth. On tracke le token EST precedent pour neutraliser. */
    bool prevWasEst = false;
    /*  : `SINON SI` (clause elif) = continuation de la meme
     * conditionnelle, fermee par un SEUL FIN. Le SI qui suit immediatement un
     * SINON (meme ligne, pas de newline) ne doit PAS incrementer depth, sinon
     * desync permanente de +1 -> les PROCEDURE declarees apres ne sont plus
     * pre-enregistrees (ordre-dependance regressive). Miroir de la
     * desambiguation elif/imbrique du parser if_statement (`check(TOKEN_SI) &&
     * !crossedNewline`, ) : le reset sur NEWLINE separe naturellement
     * `SINON`<nl>`SI...FIN` (vrai SI imbrique, qui garde son depth++). */
    bool prevWasSinon = false;
    /*  : dernier IDENT vu au depth courant (nom potentiel de variable
     * dans `IDENT est un <type>`), pour pre-enregistrer les globales element. */
    Token lastIdent;
    lastIdent.start = NULL;
    lastIdent.length = 0;
    /*  — mode de portee dans le corps de l'element : en LOCAL, une
     * globale de donnees est confinee -> PAS pre-enregistree comme globale
     * d'element (pas d'acces FEN.var, invisible des handlers). Bascule
     * GLOBAL/LOCAL seule sur une ligne au niveau body (depth 0). */
    bool confine = false;

    while (1) {
        Token tok = scanner_scan_token(&localScanner);
        if (tok.type == TOKEN_EOF) return;
        if (tok.type == TOKEN_NEWLINE || tok.type == TOKEN_SEMICOLON) {
            /* Newline isole le 'IDENT' du depth=0 du EST potentiel. */
            sawIdentAtTopLevel = false;
            prevWasDot = false;
            prevWasEst = false;
            prevWasSinon = false;
            continue;
        }
        /* Mémorise point / EST pour le prochain tour, puis poursuit le scan.
         * Les flags sont consommés (remis a false) par tout autre token via les
         * captures locales `afterDot` / `afterEst`. */
        bool afterDot = prevWasDot;
        bool afterEst = prevWasEst;
        bool afterSinon = prevWasSinon;
        prevWasDot = (tok.type == TOKEN_DOT || tok.type == TOKEN_DOUBLE_DOT);
        prevWasEst = (tok.type == TOKEN_EST);
        prevWasSinon = (tok.type == TOKEN_SINON);
        if (prevWasDot) continue;
        /*  : SI de `SINON SI` = elif, pas un ouvreur de bloc. */
        if (tok.type == TOKEN_SI && afterSinon) continue;

        /*  : tout token suivant un point est un membre accede
         * (`obj..Procedure`, `obj.Champ`, `obj..Si`...), jamais un ouvreur de
         * bloc ni un debut de declaration `IDENT est un X`. On l'ignore pour ne
         * pas desequilibrer le compteur de profondeur. Cas reel : `Procedure`
         * d'un Timer scanne comme TOKEN_PROCEDURE et incrementait depth sans
         * FIN apparie, masquant les PROCEDURE declarees plus bas. */
        if (afterDot) {
            sawIdentAtTopLevel = false;
            continue;
        }

        /*  — bascule GLOBAL/LOCAL au niveau body de l'element (depth 0).
         * En LOCAL, les globales de donnees qui suivent sont confinees (non
         * pre-enregistrees comme globales d'element ci-dessous). */
        if (depth == 0 && (tok.type == TOKEN_GLOBAL || tok.type == TOKEN_LOCAL)) {
            confine = (tok.type == TOKEN_LOCAL);
            sawIdentAtTopLevel = false;
            continue;
        }

        /* IDENT suivi de 'est un Widget' -> ouvre un sous-bloc (depth++).
         *  : valable a TOUTE profondeur, pas seulement au depth=0. Les
         * widgets imbriques dans un Conteneur (`LIB_x est un Libelle` au sein
         * d'un `BAR est un Conteneur`) sont a depth>0 ; sans les compter, leur
         * FIN de fermeture sur-decremente le compteur -> sortie prematuree du
         * pre-scan (return sur FIN a depth 0) -> les PROCEDURE helpers declares
         * APRES le conteneur ne sont jamais pre-enregistrees. La detection
         * `est un <WidgetType>` + PROPRIETES distingue le widget-bloc d'une
         * simple decl locale (`oP est un cPiece = ...`, pas de PROPRIETES). */
        if (tok.type == TOKEN_IDENTIFIER) {
            sawIdentAtTopLevel = true;
            lastIdent = tok;   /*  : nom candidat de la globale */
            continue;
        }
        if (sawIdentAtTopLevel && tok.type == TOKEN_EST) {
            /* peek le type suivant : widget DSL ou type user ouvre un bloc
             * ferme par FIN. Type scalaire (entier/chaine/...) = simple
             * decl sans bloc. */
            Scanner peek = localScanner;
            Token typeTok = scanner_scan_token(&peek);
            while (typeTok.type == TOKEN_NEWLINE) typeTok = scanner_scan_token(&peek);
            /*  : copule EN `is a/an <Type>` — saute l'article (`a`=TOKEN_A,
             * `an`=IDENT 2 chars) sinon typeTok reste sur l'article et le widget
             * n'est pas reconnu -> desync depth en EN. */
            if (typeTok.type == TOKEN_A ||
                (typeTok.type == TOKEN_IDENTIFIER &&
                 ((typeTok.length == 1 &&
                   (typeTok.start[0] == 'a' || typeTok.start[0] == 'A')) ||
                  (typeTok.length == 2 &&
                   (typeTok.start[0] == 'a' || typeTok.start[0] == 'A') &&
                   (typeTok.start[1] == 'n' || typeTok.start[1] == 'N'))))) {
                localScanner = peek;
                typeTok = scanner_scan_token(&peek);
                while (typeTok.type == TOKEN_NEWLINE) typeTok = scanner_scan_token(&peek);
            }
            /*  lot 1-bis : consomme le modificateur 'Champ' optionnel
             * ('IDENT est un Champ <Genre>') exactement comme le parsing
             * principal, sinon le genre suivant (Libelle/Bouton/Image...) n'est
             * pas reconnu -> bloc non compte -> desync depth -> helpers declares
             * plus bas non pre-enregistres ('fonction inconnue'). */
            bool sawChampMod = token_is_champ_modifier(typeTok);
            if (sawChampMod) {
                localScanner = peek;
                typeTok = scanner_scan_token(&peek);
                while (typeTok.type == TOKEN_NEWLINE) typeTok = scanner_scan_token(&peek);
            }
            /* Widgets DSL : ouvrent un sous-bloc ferme par FIN, a toute
             * profondeur (top-level OU imbriques dans un Conteneur). */
            bool opensBlock =
                typeTok.type == TOKEN_LIBELLE  || typeTok.type == TOKEN_BOUTON  ||
                typeTok.type == TOKEN_SAISIE   || typeTok.type == TOKEN_TABLE   ||
                typeTok.type == TOKEN_CONTENEUR|| typeTok.type == TOKEN_LISTE;
            /*  — les sous-blocs Colonne (`COL_X est une Colonne`) et Volet
             * ferment aussi par FIN mais leur genre n'est pas resolu comme widget
             * (is_widget=false). Sans les compter ici, leur FIN sur-decremente la
             * profondeur : la colonne SUIVANTE d'une meme Table retombe a depth 0
             * et est pre-enregistree a tort comme globale d'element (`FEN$COL`).
             * Ce nom nu materialise court-circuite ensuite l'intercept du receveur
             * de mise en forme `COL..Couleur` (repli widget-alias -> variable
             * inconnue), et seule la 1re colonne d'une Table restait resoluble. */
            opensBlock = opensBlock ||
                typeTok.type == TOKEN_COLONNE || token_is_volet_genre(typeTok);
            /*  : les noeuds de menu (MenuPrincipal/SousMenu/OptionMenu/
             * MenuSeparateur) ferment tous par FIN. MenuPrincipal et
             * MenuSeparateur n'exposent pas de PROPRIETES en tete -> l'heuristique
             * IDENT+PROPRIETES ci-dessous ne les detecte pas et leur FIN
             * desynchronisait la profondeur (pre-passe terminee trop tot, ratant
             * les declarations posees APRES le bloc menu). On les compte ici. */
            if (menu_keyword_of_token(typeTok) != MENU_KW_NONE) opensBlock = true;
            /* Mots-cles structurels (classe/struct/enum/interface/combinaison/
             * Fenetre) : ouvrent un bloc UNIQUEMENT au top-level du fichier
             * (depth=0). A depth>0, `x est une structure`/`est une procedure`
             * est une annotation de type, pas un ouvreur — ne pas
             * compter pour ne pas desequilibrer. */
            if (depth == 0) {
                opensBlock = opensBlock ||
                    typeTok.type == TOKEN_FENETRE  ||
                    typeTok.type == TOKEN_CLASSE   || typeTok.type == TOKEN_INTERFACE ||
                    typeTok.type == TOKEN_ENUMERATION || typeTok.type == TOKEN_STRUCTURE ||
                    typeTok.type == TOKEN_COMBINAISON;
            }
            /* IDENT type = peut etre un widget DSL (Image/Combo/...) ou un
             * type user — dans les deux cas, traitement parent identique :
             * le body se termine par FIN si bloc, sinon = simple decl. On
             * ne peut pas trancher sans peek plus loin (ex: '= ...' = decl
             * sans bloc). Heuristique safe : on suppose bloc si IDENT, on
             * incremente depth. Si en realite c'est une decl simple sans
             * bloc, on n'incremente pas (mais alors il n'y aura pas de FIN
             * pour decrementer — risque). Plus prudent : peek encore un
             * token pour voir si '=' ou rien-de-bloc. */
            if (typeTok.type == TOKEN_IDENTIFIER) {
                /* Peek encore : un type widget IDENT est suivi par NEWLINE
                 * (puis PROPRIETES) ou directement par PROPRIETES. Une decl
                 * simple est suivie par '=' / NEWLINE-puis-autre-decl. */
                Scanner peek2 = peek;
                Token after = scanner_scan_token(&peek2);
                while (after.type == TOKEN_NEWLINE) after = scanner_scan_token(&peek2);
                if (after.type == TOKEN_PROPRIETES) opensBlock = true;
            }
            /*  — pre-enregistrement des variables element-global, par
             * SYMETRIE avec la collecte des procedures ci-dessous. Une vraie
             * globale de donnees du body (`gNom est un entier`, `oP est un
             * cPiece`, un tableau...) declaree APRES un handler qui l'utilise
             * doit rester forward-referencable : on la pre-enregistre pour que
             * element_globals_has() la connaisse pendant la compilation inline
             * des handlers, quel que soit l'ordre lexical. Critere aligne sur
             * var_declaration_after_est (~L14086) : niveau body de l'element
             * (depth==0), forme sans bloc (!opensBlock : pas un controle/type
             * user/menu), hors modificateur Champ et hors membre/bloc DSL a
             * contexte propre (Groupe/Theme/CollectionDeProcedures). */
            if (depth == 0 && !opensBlock && !sawChampMod && !confine
                && lastIdent.start != NULL
                && !prepass_type_not_element_global(typeTok)) {
                element_globals_register(ownerName, (int)strlen(ownerName),
                                         lastIdent.start, lastIdent.length);
            }
            sawIdentAtTopLevel = false;
            if (opensBlock) {
                depth++;
                /* Consomme le type token. */
                localScanner = peek;
            }
            continue;
        }
        sawIdentAtTopLevel = false;

        /*  : keyword precede de `est`/`est un`/`est une` = nom de
         * TYPE (`f est une procedure`, `s est une structure`...), pas un
         * ouvreur de bloc. Ne touche pas depth. Le cas depth==0 est deja
         * couvert par la branche EST ci-dessus ; ici on traite depth>0 (decl
         * locale dans un body de proc/event). */
        if (afterEst) {
            continue;
        }

        /* Ouvreurs explicites (toujours fermes par FIN). Aligne sur
         * window_skip_nested_block. */
        if (tok.type == TOKEN_PROCEDURE || tok.type == TOKEN_FONCTION) {
            /* Capturer le nom + checker si custom user_proc.
             * Au depth=0 SEUL on enregistre — les PROCEDUREs imbriquees
             * (rares en OWL : methodes de classe declaree dans une fenetre
             * sont rejetees, donc en pratique pas de PROCEDURE imbriquee
             * a part les events de sous-champs). */
            Token nameTok = scanner_scan_token(&localScanner);
            while (nameTok.type == TOKEN_NEWLINE) nameTok = scanner_scan_token(&localScanner);
            /*  — une PROCEDURE a nom libre (helper) n'est globale a
             * l'Etat/Fenetre QUE declaree au top-level (depth==0). Dans un
             * bloc/section/widget (depth>0), seuls les events connus sont
             * admis, et ils sont geres par leur parse dedie (pas comme des
             * globales) ; un helper y est desormais une erreur compile. On ne
             * pre-enregistre donc que le top-level, Etat comme Fenetre. */
            if (nameTok.type == TOKEN_IDENTIFIER && depth == 0) {
                char blockName[128];
                int nlen = nameTok.length < 127 ? nameTok.length : 127;
                memcpy(blockName, nameTok.start, nlen);
                blockName[nlen] = '\0';
                bool isPredef = isEtat
                    ? prepass_etat_proc_is_predefined(blockName, ownerName)
                    : prepass_window_proc_is_predefined(blockName, ownerName);
                if (!isPredef) {
                    prepass_register_user_proc(ownerName, blockName, nlen,
                                                 nameTok.line);
                }
            }
            depth++;
            continue;
        }
        /* Ouvreurs lexicaux : regle unique partagee (prescan_depth_delta,
         * ). Couvre PROPRIETES / POUR / TANTQUE / BOUCLE / SELON /
         * QUAND, et les deux tokens qui ont AUSSI une forme sans FIN et ne
         * doivent alors PAS incrementer : `SI cond ALORS <stmt>` mono-ligne
         * et `CONSTANTE K = 3` inline.
         *
         * Cette passe comptait CONSTANTE inconditionnellement jusqu'a
         *  : une `CONSTANTE K = 3` dans un corps de Fenetre laissait
         * depth a +1, le FIN de la Fenetre refermait la fausse constante, et
         * les helpers declares APRES n'etaient plus pre-enregistres ->
         * « 'aide' : fonction/procedure inconnue » sur un source legal.
         *
         * PROCEDURE/FONCTION sont traites au-dessus (capture du nom). */
        {
            Scanner peek = localScanner;
            if (prescan_depth_delta(tok, &peek) > 0) {
                depth++;
                continue;
            }
        }
        if (tok.type == TOKEN_SI || tok.type == TOKEN_CONSTANTE) {
            continue;  /* forme sans FIN : rien a equilibrer */
        }
        if (tok.type == TOKEN_FIN) {
            if (depth == 0) return;  /* FIN du bloc top-level — fin du scan */
            depth--;
            continue;
        }
        /* Tous les autres tokens : ignores. */
    }
}

/*  — Resout le raccourci clavier EFFECTIF d'un control.
 * Priorite alignee sur le runtime : ToucheRaccourci explicite
 * l'emporte sur le mnemonic '&Lettre' du libelle (Qt ne cable qu'un seul
 * raccourci par bouton). Le mnemonic n'est considere que pour les boutons.
 *   norm : forme comparable (minuscules, sans espaces) — ex "alt+o".
 *   disp : forme lisible pour le message — ex "Alt+O".
 *   *line : ligne du site source (prop ToucheRaccourci ou Libelle).
 * Retourne true si un raccourci est declare. */
static bool control_effective_shortcut(const OwlControlDecl* c,
                                        char* norm, size_t normSz,
                                        char* disp, size_t dispSz,
                                        int* outLine) {
    /* 1. ToucheRaccourci / ShortcutKey explicite (chaine constante). */
    for (int j = 0; j < c->property_count; j++) {
        const OwlPropertyInit* p = &c->properties[j];
        if ((strcasecmp(p->name, "ToucheRaccourci") == 0
             || strcasecmp(p->name, "ShortcutKey") == 0)
            && p->is_constant && IS_STRING(p->const_value)) {
            const char* s = AS_CSTRING(p->const_value);
            if (s && s[0] != '\0') {
                snprintf(disp, dispSz, "%s", s);
                size_t n = 0;
                for (const char* q = s; *q && n + 1 < normSz; q++) {
                    if (*q == ' ' || *q == '\t') continue;
                    norm[n++] = (char)tolower((unsigned char)*q);
                }
                norm[n] = '\0';
                *outLine = p->line;
                return true;
            }
        }
    }
    /* 2. Mnemonic '&Lettre' du libelle (boutons uniquement). Premier '&'
     * suivi d'une lettre => Alt+<lettre>. '&&' = '&' litteral, on saute. */
    if (c->kind == OWL_CONTROL_BUTTON) {
        for (int j = 0; j < c->property_count; j++) {
            const OwlPropertyInit* p = &c->properties[j];
            if ((strcasecmp(p->name, "Libelle") == 0
                 || strcasecmp(p->name, "Caption") == 0)
                && p->is_constant && IS_STRING(p->const_value)) {
                const char* s = AS_CSTRING(p->const_value);
                if (!s) break;
                for (const char* q = s; *q; q++) {
                    if (*q != '&') continue;
                    if (q[1] == '&') { q++; continue; }
                    if (isalpha((unsigned char)q[1])) {
                        char lo = (char)tolower((unsigned char)q[1]);
                        char up = (char)toupper((unsigned char)q[1]);
                        snprintf(norm, normSz, "alt+%c", lo);
                        snprintf(disp, dispSz, "Alt+%c", up);
                        *outLine = p->line;
                        return true;
                    }
                }
                break;  /* un seul libelle */
            }
        }
    }
    return false;
}

/* Phase G v2 — DSL post-fixed style canon : 'FEN_X est une Fenetre ... FIN'.
 * Le caller a deja consomme 'IDENT est un/une Fenetre'. On recoit le
 * Token du nom + line ; on parse le body jusqu'au FIN matching. */
static void window_declaration(Token windowName, int line) {
    /* Garde-fou : un fichier ne peut pas mixer Classe + Fenetre (convention
     * OWL "1 classe = 1 fichier"). */
    if (g_file_first_class_line > 0) {
        char classNameBuf[128], lineBuf[16];
        snprintf(classNameBuf, sizeof(classNameBuf), "%.*s",
                 g_file_first_class_name_len, g_file_first_class_name);
        snprintf(lineBuf, sizeof(lineBuf), "%d", g_file_first_class_line);
        owl_emit_error_at(&windowName, E_SEM_DSL_FILE_WINDOW_AND_CLASS,
                          "name", classNameBuf,
                          "line", lineBuf,
                          NULL);
    }
    /* Garde-fou : un fichier ne peut pas mixer Fenetre + Etat. */
    if (g_file_first_etat_line > 0) {
        char lineBuf[16];
        snprintf(lineBuf, sizeof(lineBuf), "%d", g_file_first_etat_line);
        owl_emit_error_at(&windowName, E_SEM_FILE_WINDOW_AND_ETAT,
                          "line", lineBuf,
                          NULL);
    }
    /* Garde-fou : un fichier ne peut contenir qu'UNE seule Fenetre. Le
     * designer custom (VSCode + web viewer) suppose 1 fichier = 1 fenetre
     * pour le routage canvas / sync source. Mixer plusieurs fenetres dans
     * un seul fichier rend l'editeur visuel ingerable (quelle fenetre
     * representer ? comment switcher ?). On force la separation explicite. */
    if (!g_file_allow_multi_window
        && g_file_first_window_line > 0
        && line != g_file_first_window_line) {
        char lineBuf[16];
        snprintf(lineBuf, sizeof(lineBuf), "%d", g_file_first_window_line);
        owl_emit_error_at(&windowName, E_SEM_MULTIPLE_WINDOWS_IN_FILE,
                          "line", lineBuf,
                          NULL);
    }
    if (g_file_first_window_line == 0) g_file_first_window_line = line;

    /* Allocation du nom (cstr null-terminated). */
    char* nameBuf = (char*)malloc((size_t)windowName.length + 1);
    memcpy(nameBuf, windowName.start, windowName.length);
    nameBuf[windowName.length] = '\0';

    OwlWindowDecl* decl = NULL;
    bool dup = false;

    /*  — doublon de nom d'element cross-fichier (tous types confondus).
     * Detecte et signale de facon deterministe par le check unifie
     * (E_SEM_ELEMENT_NAME_DUPLICATE, emis en fin de compile_in_project sur la
     * declaration de fileIndex le plus eleve). Ici on evite le double-report et
     * le ré-enregistrement : le nom appartient au 1er fichier. On reutilise sa
     * decl (deja enregistree — ordre fileIndex) pour parser le corps sans
     * cascade ; a defaut on cree une decl jetable. Remplace l'ancien crossFileDup
     * SYM_WINDOW : voie unique, message unique, tous types.
     * Le cas intra-fichier (2 Fenetre dans un fichier) est deja rejete plus haut
     * par E_SEM_MULTIPLE_WINDOWS_IN_FILE. */
    bool projectElementDup = (projectSymbols != NULL)
        && symtable_element_has_earlier_dup(projectSymbols,
               windowName.start, windowName.length, currentFileIndex);
    if (projectElementDup) {
        /* decl jetable (non enregistree) : parse du corps propre, pas de cascade,
         * pas de ré-enregistrement du nom appartenant au 1er fichier. */
        decl = owl_window_decl_new(nameBuf, line);
        dup = true;
    } else if (vm_window_lookup(nameBuf) != NULL) {
        /* Hors contexte projet (ou pollution inter-run) : repli order-dependant. */
        owl_emit_error_at(&windowName, E_SEM_WINDOW_DUPLICATE,
                          "name", nameBuf,
                          NULL);
        dup = true;
    } else {
        decl = owl_window_decl_new(nameBuf, line);
        if (!vm_window_register(decl)) {
            owl_window_decl_free(decl);
            decl = NULL;
            owl_emit_error_at(&parser.previous, E_SEM_INTERNAL_WINDOW_REGISTER_FAILED);
        }
    }
    free(nameBuf);

    /* Parametres optionnels : 'est une Fenetre(<param1> [est un <type1>], ...)'.
     * Symetrie stricte avec etat_declaration : les params sont accessibles
     * comme globales dans tout le scope de la fenetre (top-level + champs +
     * events + PROCEDUREs). Au runtime Ouvre(FEN_X, val1, val2, ...) injecte
     * les valeurs avant d'executer le top-level fenetre. Parse AVANT la
     * pre-passe pour que les noms soient connus des le scan des procs. */
    if (match_token(TOKEN_LEFT_PAREN)) {
        bool sawDefault = false;
        if (!check(TOKEN_RIGHT_PAREN)) {
            do {
                if (!check(TOKEN_IDENTIFIER)) {
                    owl_emit_error_current(E_SYNTAX_EXPECTED_PARAM_NAME);
                    break;
                }
                Token paramTok = parser.current;
                advance_token();
                char paramName[128];
                int plen = paramTok.length < 127 ? paramTok.length : 127;
                memcpy(paramName, paramTok.start, plen);
                paramName[plen] = '\0';

                /* Type optionnel : 'est un <Type>'. 'un'/'une' sont des filler
                 * words consommes par le scanner — on ne voit que EST puis
                 * directement le type token. */
                char typeNameBuf[128] = "";
                bool hasType = false;
                if (match_token(TOKEN_EST)) {
                    /*  /  — valide le nom de type au meme titre
                     * qu'un param de PROCEDURE (parite stricte), HEAD scalaire
                     * (record_pending_type_ref) ET element de collection apres
                     * `de` (`tableau de Zorglub` -> record_collection_elem_type_ref).
                     * On avale le filler EN (a/an) d'abord pour capturer le nom
                     * de type affiche (typeNameBuf) sur parser.current, puis
                     * skip_type_spec_ex se charge des deux enregistrements ; les
                     * primitifs et TOKEN_TABLEAU ne sont jamais rejetes. */
                    consume_en_a_an_filler();
                    Token typTok = parser.current;
                    int tlen = typTok.length < 127 ? typTok.length : 127;
                    memcpy(typeNameBuf, typTok.start, tlen);
                    typeNameBuf[tlen] = '\0';
                    hasType = (tlen > 0);
                    skip_type_spec_ex(true, false);
                    /* Erreur de type emise par skip_type_spec (modifieur chaine
                     * ANSI/UNICODE/fixe, type dimensionne...) : le flux de
                     * tokens reste synchronise (les tokens fautifs ont ete
                     * consommes). On desactive le panic mode pour eviter la
                     * cascade parasite « Bloc PROPRIETES manquant » — meme
                     * discipline que E_SEM_REQUIRED_PARAM_AFTER_DEFAULT
                     * ci-dessous. */
                    parser.panicMode = false;
                }

                /* Valeur par defaut optionnelle : `= <litteral>`. Parite stricte
                 * avec les params de PROCEDURE. Un param requis (sans
                 * defaut) ne peut pas suivre un param a valeur par defaut. */
                Value defaultVal = NIL_VAL;
                bool hasDefault = false;
                if (match_token(TOKEN_EQUAL)) {
                    if (parse_default_literal(&defaultVal)) {
                        hasDefault = true;
                        sawDefault = true;
                    }
                } else if (sawDefault) {
                    owl_emit_error_at(&parser.previous, E_SEM_REQUIRED_PARAM_AFTER_DEFAULT);
                    /* Erreur SEMANTIQUE : le flux de tokens reste synchronise
                     * (le param a ete consomme proprement). On desactive le
                     * panic mode pour que le body de la fenetre parse sans
                     * cascade parasite (sinon la recovery skip-to-newline
                     * desynchronise et fait croire a un PROPRIETES manquant). */
                    parser.panicMode = false;
                }

                if (decl) {
                    owl_window_decl_add_param(decl, paramName,
                                              hasType ? typeNameBuf : NULL,
                                              defaultVal, hasDefault,
                                              paramTok.line);
                    /* Expose le nom comme global (BARE, non mangle) pour que la
                     * validation compile-time accepte les references depuis le
                     * top-level, les champs, events et PROCEDUREs. La vraie
                     * valeur est injectee par Ouvre au runtime. */
                    obj_globals_set(paramName, NIL_VAL);
                }
            } while (match_token(TOKEN_COMMA));
        }
        consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_FENETRE_PARAMS);
    }

    /* Phase 6 : nouveau scope d'aliases pour la fenetre. */
    dsl_aliases_push_scope();

    /*  : pre-passe ordre-independant. Scanne le body du bloc
     * Fenetre pour pre-enregistrer les PROCEDURE custom (aliases DSL +
     * global track). Permet aux handlers/top-level/PROCEDURE definis en
     * haut d'invoquer des helpers definis plus bas dans la meme Fenetre.
     *
     * On positionne le scanner local au DEBUT de parser.current (le token
     * courant a deja ete tokenise mais pas encore consume cote parser ; sans
     * ce rewind, on sauterait ce premier token du body).
     *
     * Env var OWL_DISABLE_PREPASS=1 desactive la pre-passe (utile pour
     * benchmark perf single-pass vs double-passe). Garde-fou silencieux,
     * pas de doc utilisateur — usage interne dev. */
    if (decl != NULL && getenv("OWL_DISABLE_PREPASS") == NULL) {
        Scanner pre = parser.scanner;
        if (parser.current.start != NULL) {
            pre.current = parser.current.start;
            pre.start   = parser.current.start;
            pre.line    = parser.current.line;
            pre.column  = parser.current.column;
            pre.startColumn = parser.current.column;
            pre.atLineStart = false;
        }
        prepass_block_collect_procs(pre, decl->name, /*isEtat=*/false);
    }

    /*  — Set du pointeur fenetre courante pour que
     * var_declaration_after_est puisse pousser dans decl->variables[]
     * quand il rencontre `GR_X est un Groupe`. Restore en fin de body. */
    OwlWindowDecl* savedWindowDecl = g_current_window_decl;
    g_current_window_decl = decl;

    /*  — contexte element courant (nom de la fenetre, forme tapee).
     * Sert au mangling `<ELEM>$<var>` des globales top-level (portee scopee
     * a l'element, ). Restaure en fin de body. */
    char savedElementName[64];
    memcpy(savedElementName, g_current_element_name, sizeof(savedElementName));
    {
        int wn = windowName.length < (int)sizeof(g_current_element_name) - 1
                 ? windowName.length : (int)sizeof(g_current_element_name) - 1;
        memcpy(g_current_element_name, windowName.start, (size_t)wn);
        g_current_element_name[wn] = '\0';
    }
    /*  — le corps de la Fenetre est un nouveau contexte top-level :
     * repart en mode GLOBAL, restaure a la sortie du body. */
    bool savedConfineWin = g_toplevel_confine;
    g_toplevel_confine = false;

    /*  lot B — pose le proxy global ObjWindowRef sous le nom
     * STRIPPE de la fenetre (cle = FEN_Test sans accents/casse). C'est cette
     * cle que l'alias compile-time `MaFenetre` substitue (cf. named_variable),
     * et c'est aussi le nom direct utilisable dans le script utilisateur
     * (`FEN_Test..Titre`).
     *
     * Le ref est sans storage : a chaque OP_STRUCT_GET/SET window-ref, on
     * resout vers vm_window_stack_top() (l'instance fenetre courante).
     * Stack vide = soft error (cf. vm.c::OP_STRUCT_GET branche WINDOW_REF).
     *
     * Shadow GUI : en mode GUI, build_window (stdlib_ui.c) re-pose un
     * `ObjUiControl(kind=WINDOW)` sous la meme cle (L2989 historique) qui
     * ecrase ce ref pour la duree de la fenetre ouverte. C'est la branche
     * legacy `IS_UI_CONTROL` qui dispatch alors les acces `FEN_X..Prop` vers
     * Qt directement. En mode HEADLESS (vm.headless_mode), build_window
     * n'est pas appele, le ref survit, et les acces tombent sur la branche
     * window-ref qui lit/ecrit le casier d'instance.
     *
     * MaFenetre dans un event GUI passera donc par l'ObjUiControl shadowing
     * (compatibilite legacy) — semantique equivalente pour les props Qt
     * standards (Titre/Largeur/Hauteur/Visible). L'unification reste un
     * chantier futur (alignement headless/GUI sur le casier d'instance). */
    if (decl) {
        char winStrip[256];
        int wlen = scanner_strip_accents(decl->name, (int)strlen(decl->name),
                                          winStrip, sizeof(winStrip));
        /* 3 allocs en cascade (string + window_ref + grow potentielle de
         * vm.globals dans table_set) : on root les transients sur la pile
         * pour qu'un GC declenche entre deux allocs ne les collecte pas. */
        ObjString* refKeyStr = obj_copy_string(winStrip, wlen);
        vm_push(OBJ_VAL(refKeyStr));
        ObjWindowRef* ref = obj_new_window_ref(decl, refKeyStr);
        vm_push(OBJ_VAL(ref));
        obj_globals_set_kv(refKeyStr, OBJ_VAL(ref));  /*  : canon */
        vm_pop();
        vm_pop();
    }

    /* B.2 : on parse maintenant le body. Pour chaque ligne :
     *  - IDENT = literal      -> init de propriete (compile-time const)
     *  - IDENT est un Type    -> declaration variable globale fenetre (top-level)
     *  - Libelle/Bouton/...   -> sous-champ
     *  - PROCEDURE ...        -> bloc de code (event/user_proc)
     *  - autre (statement)    -> code top-level (Trace, x += y, appels…)
     */

    /*  — top-level executable de la fenetre. Tout code de niveau 0
     * (declarations globales + statements orphelins) est compile dans cette
     * ObjFunction implicite, executee A L'OUVERTURE en premier (avant les
     * top-levels des champs). Modele : pseudo-event "Ouverture" de l'Etat.
     *
     * POINT D'ARCHI (scope global) : on init le compiler en TYPE_FUNCTION mais
     * SANS begin_scope() -> scopeDepth reste 0 -> declare_variable /
     * define_variable / var_declaration_after_est emettent OP_DEFINE_GLOBAL.
     * Les variables du top-level fenetre tombent donc dans vm.globals au
     * runtime, visibles depuis les champs / procedures / events (exigence dev).
     * (L'Etat "Ouverture" fait begin_scope() -> locals ; on diverge ici
     * volontairement pour obtenir des globales.) */
    Compiler winTopCompiler;
    init_compiler(&winTopCompiler, TYPE_FUNCTION);
    {
        char topFnName[160];
        snprintf(topFnName, sizeof(topFnName), "__fenetre_%s_TopLevel",
                 decl ? decl->name : "?");
        current->function->name =
            obj_copy_string(topFnName, (int)strlen(topFnName));
    }

    bool propertiesBlockSeen = false;
    g_window_main_menu_pending = false;   /*  */
    /*  : garde anti-hang. Si deux iterations consecutives demarrent
     * a la MEME position source, la boucle ne progresse pas (un sous-parse a
     * laisse un token non consomme) -> on force l'avancement pour garantir la
     * terminaison. Ne devrait jamais se declencher (le dispatch consomme
     * toujours), mais verrouille la classe de bug "boucle infinie compilo". */
    const char* lastLoopPos = NULL;
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        if (parser.current.start == lastLoopPos) {
            advance_token();
            parser.panicMode = false;
            lastLoopPos = parser.current.start;
            continue;
        }
        lastLoopPos = parser.current.start;
        /* Si panicMode actif (erreur dans le statement precedent), skip
         * jusqu'au newline pour isoler la cascade. */
        if (parser.panicMode) {
            while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                advance_token();
            }
            parser.panicMode = false;
        }
        /* Eat newlines. */
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;

        /* DSL v2 : bloc PROPRIETES ... FIN — section statique des props
         * (ecrasable par Qt Designer, contenu = init de prop pure). */
        if (check(TOKEN_PROPRIETES)) {
            Token propTok = parser.current;
            advance_token(); /* consume PROPRIETES */
            if (propertiesBlockSeen) {
                owl_emit_error_at(&propTok, E_SYNTAX_DUPLICATE_PROPRIETES_WINDOW);
            }
            propertiesBlockSeen = true;
            bool firstWinProp = true;
            /*  : buffer cascade actif pendant la duree du bloc
             * PROPRIETES pour regrouper les cascades homonymes en un seul
             * eval (cf cascade_buffer_capture / cascade_buffer_flush). */
            CascadeBuffer winCascadeBuf;
            cascade_buffer_init(&winCascadeBuf);
            CascadeBuffer* savedCascadeBuf = g_cascade_buffer;
            g_cascade_buffer = &winCascadeBuf;
            /*  : garde anti-hang (cf  sur la boucle body). Un
             * sous-champ declare DANS le bloc (`B est un Champ Bouton`) fait que
             * window_skip_to_next_stmt() se gare sur le keyword Bouton/Saisie
             * sans le consommer (stop-list), et la boucle n'accepte que des
             * IDENT : sans avancement force, on tourne dans le vide. */
            const char* lastPropPos = NULL;
            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                while (check(TOKEN_NEWLINE)) advance_token();
                if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
                if (parser.current.start == lastPropPos) {
                    advance_token();
                    parser.panicMode = false;
                    continue;
                }
                lastPropPos = parser.current.start;
                if (!check(TOKEN_IDENTIFIER)) {
                    owl_emit_error_current(E_SYNTAX_EXPECTED_PROP_NAME_IN_PROPRIETES);
                    window_skip_to_next_stmt();
                    continue;
                }
                if (!firstWinProp && !crossedNewline) {
                    owl_emit_error_current(E_SYNTAX_PROPS_NEED_SEPARATOR);
                }
                firstWinProp = false;
                /*  — `MenuPrincipal = MNU_X` : affectation de l'arbre
                 * de menu, pas une propriete de valeur (resolue en fin de body). */
                if (window_try_parse_main_menu_assign(decl)) continue;
                window_parse_property_init(decl);
            }
            g_cascade_buffer = savedCascadeBuf;
            cascade_buffer_flush(&winCascadeBuf, CASCADE_FLUSH_WINDOW, decl,
                                  "__win_prop");
            cascade_buffer_free(&winCascadeBuf);
            if (check(TOKEN_FIN) && !crossedNewline && !firstWinProp) {
                owl_emit_error_current(E_SYNTAX_FIN_ON_OWN_LINE);
            }
            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROPRIETES);
            continue;
        }

        /* Bloc CONSTANTE dans body fenetre : delegue au handler standard.
         * Les constantes sont emises comme globales du main script. */
        if (check(TOKEN_CONSTANTE)) {
            advance_token(); /* consume CONSTANTE */
            constante_block();
            continue;
        }

        if (check(TOKEN_IDENTIFIER)) {
            /* Peek pour distinguer :
             *   IDENT = literal               -> prop
             *   IDENT est un/une Libellé/Bouton/Saisie -> sous-champ DSL
             *   IDENT est un/une <type>       -> variable propre fenetre */
            Scanner savedScanner = parser.scanner;
            Token savedCurrent   = parser.current;
            Token savedPrevious  = parser.previous;
            bool  savedCrossed   = crossedNewline;

            advance_token(); /* consume IDENT */
            bool isProperty = check(TOKEN_EQUAL);
            bool isVariable = check(TOKEN_EST);

            /* Si 'est', peek encore le type : Libellé/Bouton/Saisie => sous-champ.
             * Fenetre => fenetre imbriquee non supportee V1.
             * Enumeration/Structure/Combinaison => declaration de type user
             * (DSL Fenetre body accepte les types user-defined locaux).
             * Classe/Interface => REJET canon-conforme : ces types doivent etre
             * declares au top-level (fichier separe ou collection). */
            OwlControlKind subfieldKind = (OwlControlKind)-1;
            MenuKeyword menuKw = MENU_KW_NONE;   /*  */
            bool isNestedWindow = false;
            bool isUserType = false;
            bool isRejectedType = false;
            bool sawChampModifier = false;
            bool isVolet = false;                /*  */
            TokenType userTypeTok = TOKEN_EOF;
            const char* rejectedTypeName = NULL;
            /*  : widget a type inconnu (typo) + bloc PROPRIETES. */
            bool isUnknownWidget = false;
            bool sawProprietesAfterControl = false; /*  lot 1-bis */
            Token unknownWidgetTok;
            unknownWidgetTok.start = NULL;
            unknownWidgetTok.length = 0;
            if (isVariable) {
                advance_token(); /* consume EST */
                consume_en_a_an_filler(); /*  : copule EN `is a/an` */
                /* "Champ" modifier optionnel pour les widgets, obligatoire
                 * pour "Champ Image" (Image est un type runtime, conflit). */
                if (check_ident_champ()) {
                    advance_token();
                    sawChampModifier = true;
                    skip_optional_de_after_champ(); /*  */
                }
                /* Detection unifiee des sous-champs DSL : delegate au helper
                 * detect_subfield_kind (keywords scanner + IDENTs DSL). Le
                 * prefixe 'Champ' (sawChampModifier) est tranche plus bas. */
                OwlControlKind detected;
                /*  — mots-cles du menu classique : ni widget, ni
                 * variable. Detectes avant les genres de champ. */
                menuKw = menu_keyword_of_token(parser.current);
                if (menuKw != MENU_KW_NONE) { /* traite plus bas */ }
                /*  — un Volet au niveau fenetre est orphelin (valide
                 * uniquement dans un Champ Onglet). Detecte avant les genres de
                 * champ (Volet n'est pas un widget resolu par from_token). */
                else if (is_volet_token()) { isVolet = true; }
                else if (detect_subfield_kind(&detected)) {
                    subfieldKind = detected;
                    /*  lot 1-bis : pour les genres ambigus (Image/
                     * Liste) sans 'Champ', peek si PROPRIETES suit le genre.
                     * Sert l'exception messaging (forme nue + corps = intention
                     * controle -> erreur Champ d'aide). scanner positionne sur
                     * le token de genre. */
                    if (!sawChampModifier
                        && owl_control_kind_is_ambiguous(detected)) {
                        sawProprietesAfterControl = peek_proprietes_follows();
                    }
                }
                else if (check(TOKEN_FENETRE))   isNestedWindow = true;
                else if (check(TOKEN_ENUMERATION) || check(TOKEN_STRUCTURE)
                      || check(TOKEN_COMBINAISON)) {
                    isUserType = true;
                    userTypeTok = parser.current.type;
                }
                else if (check(TOKEN_CLASSE)) {
                    isRejectedType = true;
                    rejectedTypeName = "Classe";
                }
                else if (check(TOKEN_INTERFACE)) {
                    isRejectedType = true;
                    rejectedTypeName = "Interface";
                }
                else if (check(TOKEN_IDENTIFIER)) {
                    /*  : type IDENT non reconnu (typo de widget, ex.
                     * "Libellésdsd") suivi d'un bloc PROPRIETES = widget
                     * malformé, PAS une variable. Sans ce cas, le fallback
                     * var_declaration_after_est traite ça comme une variable et
                     * laisse le PROPRIETES orphelin -> la boucle body fenêtre
                     * ne progresse plus = hang infini (le LSP valide a chaque
                     * save -> serveur mort). On peek PROPRIETES pour trancher. */
                    Token unkTok = parser.current;
                    Scanner pk = parser.scanner;
                    Token pc = parser.current; Token pp = parser.previous;
                    bool pn = crossedNewline;
                    advance_token();
                    while (check(TOKEN_NEWLINE)) advance_token();
                    if (check(TOKEN_PROPRIETES)) {
                        isUnknownWidget = true;
                        unknownWidgetTok = unkTok;
                    }
                    parser.scanner = pk; parser.current = pc;
                    parser.previous = pp; crossedNewline = pn;
                }
            }

            /* Restore scanner state pour reprendre proprement. */
            parser.scanner   = savedScanner;
            parser.current   = savedCurrent;
            parser.previous  = savedPrevious;
            crossedNewline   = savedCrossed;

            if (isProperty) {
                /*  (Bug A) : `WIDGET = X` au top-level du corps
                 * Fenetre. Si l'IDENT est un widget deja declare, ce n'est PAS
                 * une init de propriete Fenetre mais une affectation a la
                 * propriete par defaut du widget (canon). On
                 * route vers declaration() qui passe par le chemin imperatif
                 * commun aux procedures (named_variable ~L10745) : meme
                 * translation `WIDGET..<defaultProperty> = X`, meme rejet net
                 * des widgets composes (defaultProperty=NULL ->
                 * E_SEM_WIDGET_NOT_SCALAR_ASSIGN). Sans ce test, le lookup
                 * catalogue Fenetre echoue -> E_SEM_DSL_PROP_UNKNOWN_FOR_WINDOW
                 * trompeur. Les vraies props Fenetre (Titre...) tombent dans le
                 * else et continuent vers window_parse_property_init. */
                char widgetNameBuf[128];
                int wnl = savedCurrent.length < (int)sizeof(widgetNameBuf) - 1
                          ? savedCurrent.length : (int)sizeof(widgetNameBuf) - 1;
                memcpy(widgetNameBuf, savedCurrent.start, (size_t)wnl);
                widgetNameBuf[wnl] = '\0';
                if (vm_find_widget_info_by_name(widgetNameBuf) != NULL) {
                    declaration();
                } else {
                    window_parse_property_init(decl);
                }
            } else if (isVariable && (menuKw == MENU_KW_MAIN
                                      || menuKw == MENU_KW_CONTEXT)) {
                /*  — `MNU_X est un MenuPrincipal ... FIN`.
                 *  — `MNU_X est un MenuContextuel ... FIN`. */
                Token menuTok  = parser.current;
                int   menuLine = parser.current.line;
                advance_token(); /* IDENT */
                advance_token(); /* EST */
                consume_en_a_an_filler();
                advance_token(); /* MenuPrincipal / MenuContextuel */
                window_parse_menu(decl, menuTok, menuLine,
                                  menuKw == MENU_KW_CONTEXT);
            } else if (isVariable && menuKw != MENU_KW_NONE) {
                /*  — noeud de menu declare hors d'un MenuPrincipal. */
                menu_reject_orphan_node(menuKw, parser.current);
            } else if (isVariable && isNestedWindow) {
                /* Fenetre imbriquee non supportée à ce jour. Message clair
                 * et skip jusqu'au FIN matching. */
                Token nestedNameTok = parser.current;
                owl_emit_error_at(&nestedNameTok,
                                  E_SEM_DSL_NESTED_WINDOW_NOT_SUPPORTED);
                /* Skip jusqu'au FIN matching pour eviter cascade. */
                window_skip_nested_block();
            } else if (isVariable && isVolet) {
                /*  — Volet declare au niveau fenetre (hors Champ
                 * Onglet) : orphelin. Erreur nommee + skip du bloc (anti-cascade).
                 * parser.current est restaure sur l'IDENT du volet. */
                Token voletNameTok = parser.current;
                owl_emit_error_at(&voletNameTok, E_SEM_DSL_VOLET_OUTSIDE_ONGLET);
                window_skip_control_block();
                parser.panicMode = false;
            } else if (isVariable && subfieldKind != (OwlControlKind)-1
                       && !sawChampModifier
                       && owl_control_kind_is_ambiguous(subfieldKind)
                       && !sawProprietesAfterControl) {
                /*  lot 1-bis : Image/Liste nu SANS corps PROPRIETES =
                 * VARIABLE / COLLECTION deterministe (le type gagne). Aucune
                 * erreur Champ : delegue a var_declaration_after_est comme une
                 * variable ordinaire. parser.current est sur l'IDENT (restore
                 * ci-dessus). */
                Token nameTok = parser.current;
                advance_token(); /* IDENT */
                advance_token(); /* EST */
                var_declaration_after_est(nameTok);
            } else if (isVariable && subfieldKind != (OwlControlKind)-1
                       && !sawChampModifier) {
                /*  : prefixe 'Champ' obligatoire devant tout
                 * controle posable. Forme nue 'lblX est un Libellé' rejetee :
                 * erreur nommee + skip du body pour eviter la cascade.
                 * Couvre les 9 genres controle-seuls (toujours) ET Image/Liste
                 * nu SUIVI d'un corps PROPRIETES (exception messaging). */
                Token ctrlTok = parser.current;
                char cname[128];
                int cl = ctrlTok.length < 127 ? ctrlTok.length : 127;
                memcpy(cname, ctrlTok.start, (size_t)cl);
                cname[cl] = '\0';
                owl_emit_error_at(&ctrlTok, E_SEM_DSL_CHAMP_PREFIXE_REQUIS,
                                  "name", cname,
                                  "genre", owl_control_kind_name_fr(subfieldKind),
                                  NULL);
                /* parser.current est restaure sur l'IDENT (cf restore ci-dessus). */
                window_skip_control_block();
                parser.panicMode = false;
            } else if (isVariable && subfieldKind != (OwlControlKind)-1) {
                /* Sous-champ DSL : 'IMG_X est un Champ Image ... FIN'. */
                Token ctrlTok = parser.current;
                int   kindLine = parser.current.line;
                advance_token(); /* IDENT */
                advance_token(); /* EST */
                consume_en_a_an_filler(); /*  : copule EN `is a/an` */
                advance_token(); /* CHAMP */
                skip_optional_de_after_champ(); /*  : 'Champ de <Genre>' */
                advance_token(); /* type keyword (Libellé/Bouton/Saisie/...) ou IDENT "Image" */
                window_parse_subfield(decl, subfieldKind, ctrlTok, kindLine);
            } else if (isVariable && isUserType) {
                /* Declaration de type user-defined dans le body fenetre :
                 * 'EEnum est une Enumeration ... FIN' / Structure / Combinaison.
                 *
                 *  — DECLARATIF STATIQUE, hors top-level. Une def de
                 * type n'est PAS du code d'init : elle est resolue au compile et
                 * accessible globalement sans ouvrir la fenetre. enum/struct/
                 * combination_declaration emettent du bytecode (OP_CLASS,
                 * OP_DEFINE_GLOBAL, __EnumVal…) ; on le route vers le compiler
                 * ENCLOSING (main script, scopeDepth 0) et NON vers winTopCompiler,
                 * sinon le type ne se materialiserait qu'a l'ouverture. */
                Token typeNameTok = parser.current;
                advance_token(); /* IDENT */
                advance_token(); /* EST */
                advance_token(); /* keyword (ENUMERATION/STRUCTURE/COMBINAISON) */
                /*  — type interne d'element referencable QUALIFIE de
                 * l'exterieur (`FEN_X.Type`). On mangle le nom `<ELEM>$<Type>`
                 * (slot distinct par element, comme  pour les
                 * collections) et on enregistre le membre-type QUALIFIE-ONLY
                 * (exposed=false : l'accès nu depuis un autre fichier ne resout
                 * pas, seul `FEN_X.Type` le fait). enum/combination_declaration
                 * splitent le `$` (identité nue + slot mangled + alias nu) ;
                 * struct_declaration idem (cf. son elemDollar). */
                Token declTok = typeNameTok;
                char elemTypeMangle[128];
                if (g_current_element_name[0] != '\0') {
                    int pn = element_var_prefix(g_current_element_name,
                                                typeNameTok.start, typeNameTok.length,
                                                elemTypeMangle, sizeof(elemTypeMangle));
                    if (pn > 0) {
                        collection_member_register(g_current_element_name,
                            (int)strlen(g_current_element_name),
                            typeNameTok.start, typeNameTok.length, /*exposed=*/false);
                        declTok.start  = elemTypeMangle;
                        declTok.length = pn;
                    }
                }
                Compiler* savedCur = current;
                current = current->enclosing;   /* -> main script (init) */
                if      (userTypeTok == TOKEN_ENUMERATION) enum_declaration(declTok);
                else if (userTypeTok == TOKEN_STRUCTURE)   struct_declaration(declTok);
                else if (userTypeTok == TOKEN_COMBINAISON) combination_declaration(declTok);
                current = savedCur;             /* -> winTopCompiler */
            } else if (isVariable && isRejectedType) {
                /* canon-conforme : Classe/Interface doivent etre declarees au
                 * top-level (fichier separe / collection de procedures), pas
                 * imbriquees dans une fenetre. Erreur claire + skip body. */
                Token typeTok = parser.current;
                owl_emit_error_at(&typeTok, E_SEM_DSL_TYPE_REJECTED_IN_WINDOW,
                                  "type", rejectedTypeName,
                                  NULL);
                /* Skip jusqu'au FIN matching pour eviter cascade. */
                advance_token(); /* IDENT */
                advance_token(); /* EST */
                advance_token(); /* CLASSE/INTERFACE */
                window_skip_nested_block();
                /* Reset panicMode pour que la prochaine iteration parte
                 * sur un etat propre. */
                parser.panicMode = false;
            } else if (isVariable && isUnknownWidget) {
                /*  : 'CHP est un <TypeInconnu>' suivi d'un bloc
                 * PROPRIETES. Type de widget mal orthographié (typo live). On
                 * émet une erreur nommée et on SKIP le bloc PROPRIETES (sinon
                 * il reste orphelin et la boucle hang). Anti-hang. */
                char tname[128];
                int tl = unknownWidgetTok.length < 127 ? unknownWidgetTok.length : 127;
                memcpy(tname, unknownWidgetTok.start, (size_t)tl);
                tname[tl] = '\0';
                owl_emit_error_at(&unknownWidgetTok, E_SEM_DSL_UNKNOWN_WIDGET_TYPE,
                                  "name", tname, NULL);
                advance_token(); /* IDENT */
                advance_token(); /* EST */
                if (sawChampModifier) advance_token(); /* CHAMP */
                advance_token(); /* type IDENT inconnu */
                window_skip_nested_block();
                parser.panicMode = false;
            } else if (isVariable) {
                /* "Declarations globales" canon : 'nom est un Type [= init]'.
                 * Delegue au handler standard var_declaration_after_est qui
                 * emet le bytecode + declare le global. La variable est
                 * ensuite visible depuis tous les events de la fenetre
                 * (PROCEDURE surClic, etc.). */
                Token nameTok = parser.current;
                advance_token(); /* IDENT */
                advance_token(); /* EST */
                var_declaration_after_est(nameTok);
            } else {
                /*  — statement de niveau 0 demarrant par un IDENT
                 * (appel 'Trace(...)', affectation 'marqueur += ...', appel de
                 * procedure…). C'est du code top-level fenetre : le scanner est
                 * deja restore au debut du statement, on compile via
                 * declaration() dans winTopCompiler. Avant : warning
                 * W_SEM_WINDOW_BODY_UNKNOWN + skip (code jete). */
                /*  : reprise d'erreur uniforme avec le top-level. */
                bool savedDslBodyStmtIdent = g_in_dsl_body_stmt;
                g_in_dsl_body_stmt = true;
                declaration();
                g_in_dsl_body_stmt = savedDslBodyStmtIdent;
            }
        } else if (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION)) {
            advance_token(); /* consume PROCEDURE/FONCTION */
            if (!check(TOKEN_IDENTIFIER)) {
                owl_emit_error_current(E_SYNTAX_EXPECTED_BLOCK_NAME_AFTER_PROC);
                window_skip_nested_block();
                continue;
            }
            Token nameTok = parser.current;
            advance_token();

            char* blockName = (char*)malloc((size_t)nameTok.length + 1);
            memcpy(blockName, nameTok.start, nameTok.length);
            blockName[nameTok.length] = '\0';

            if (!match_token(TOKEN_LEFT_PAREN)) {
                owl_emit_error_at(&nameTok, E_SYNTAX_EXPECTED_LPAREN_AFTER_BLOCK_NAME);
                free(blockName);
                window_skip_nested_block();
                continue;
            }

            bool hasParams = !check(TOKEN_RIGHT_PAREN);

            /*  — l'event 'Initialisation' n'existe plus : le code
             * d'init vit dans le top-level de la fenetre. Rejet net. */
            if (window_ci_eq(blockName, "Initialisation")
                || window_ci_eq(blockName, "Initialization")) {
                owl_emit_error_at(&nameTok, E_SEM_DSL_INITIALISATION_OBSOLETE, NULL);
                int parenDepth = 1;
                while (parenDepth > 0 && !check(TOKEN_EOF)) {
                    if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                    else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                    if (parenDepth > 0) advance_token();
                }
                if (check(TOKEN_RIGHT_PAREN)) advance_token();
                window_skip_nested_block();
                free(blockName);
                continue;
            }

            /*  — forme morte : PROCEDURE portant le nom de la
             * fenetre (ou MaFenetre/MyWindow) servait jadis a capturer les
             * params. Rejet net AVANT parse du corps : sinon le bloc serait
             * compile comme user_proc et son scope emettrait un faux warning
             * de masquage. Les params se declarent sur la 1ere ligne. */
            if (decl
                && (window_ci_eq(blockName, decl->name)
                    || window_ci_eq(blockName, "MaFenetre")
                    || window_ci_eq(blockName, "MyWindow"))) {
                owl_emit_error_at(&nameTok, E_SEM_DSL_WINDOW_PARAMS_VIA_PROC,
                                  "name", blockName,
                                  NULL);
                int parenDepth = 1;
                while (parenDepth > 0 && !check(TOKEN_EOF)) {
                    if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                    else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                    if (parenDepth > 0) advance_token();
                }
                if (check(TOKEN_RIGHT_PAREN)) advance_token();
                window_skip_nested_block();
                free(blockName);
                continue;
            }

            /* Detection doublon : event ou user_proc deja declare au niveau
             * fenetre. */
            if (decl
                && window_decl_has_block_name(decl, blockName)) {
                owl_emit_error_at(&nameTok, E_SEM_DSL_PROC_DUPLICATE_IN_WINDOW,
                                  "name", blockName,
                                  NULL);
                int parenDepth = 1;
                while (parenDepth > 0 && !check(TOKEN_EOF)) {
                    if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                    else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                    if (parenDepth > 0) advance_token();
                }
                if (check(TOKEN_RIGHT_PAREN)) advance_token();
                window_skip_nested_block();
                free(blockName);
                continue;
            }

            if (is_predefined_window_block(blockName)) {
                /*  — certains events fenetre portent un payload canon
                 * (surToucheAppuyee/Relachee : 1 entier). Si le catalogue
                 * lifecycle declare des params, on les parse + valide comme
                 * cote champ (compile_event_block_body_with_params). Pour les
                 * events sans payload (FinInitialisation, Fermeture...) on garde
                 * le warning historique « params ignores ». */
                const OwlEventDef* winEventDef =
                    owl_window_lifecycle_catalog_find(blockName);

                char winDeclaredNames[8][64];
                char winDeclaredTypes[8][32];
                Token winDeclaredTypeToks[8];
                int  winDeclaredCount = 0;
                bool winParamsParseOK = true;
                bool catalogHasParams =
                    (winEventDef != NULL && winEventDef->paramCount > 0);

                if (hasParams && !catalogHasParams) {
                    /* Event lifecycle 0-arg : params ignores (warning + skip). */
                    owl_emit_warning_at(&nameTok,
                        W_SEM_PREDEFINED_BLOCK_PARAMS_IGNORED,
                        "block", blockName,
                        NULL);
                    int parenDepth = 1;
                    while (parenDepth > 0 && !check(TOKEN_EOF)) {
                        if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                        else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                        if (parenDepth > 0) advance_token();
                    }
                } else if (hasParams) {
                    /* Parse "name est un[e] type[, ...]" jusqu'au ')'. */
                    while (!check(TOKEN_RIGHT_PAREN) && !check(TOKEN_EOF)) {
                        if (winDeclaredCount >= 8) {
                            owl_emit_error_current(E_SEM_DSL_TOO_MANY_EVENT_PARAMS);
                            winParamsParseOK = false;
                            break;
                        }
                        if (!check(TOKEN_IDENTIFIER)) {
                            owl_emit_error_current(E_SEM_DSL_EXPECTED_PARAM_NAME_AFTER_LPAREN);
                            winParamsParseOK = false;
                            break;
                        }
                        Token pNameTok = parser.current;
                        advance_token();
                        if (!match_token(TOKEN_EST)) {
                            owl_emit_error_current(E_SEM_DSL_EXPECTED_EST_AFTER_PARAM);
                            winParamsParseOK = false;
                            break;
                        }
                        /*  : avale l'article EN `a`/`an`. */
                        consume_en_a_an_filler();
                        Token pTypeTok = parser.current;
                        advance_token();
                        int nlen = pNameTok.length < 63 ? pNameTok.length : 63;
                        memcpy(winDeclaredNames[winDeclaredCount], pNameTok.start, nlen);
                        winDeclaredNames[winDeclaredCount][nlen] = '\0';
                        int tlen = pTypeTok.length < 31 ? pTypeTok.length : 31;
                        memcpy(winDeclaredTypes[winDeclaredCount], pTypeTok.start, tlen);
                        winDeclaredTypes[winDeclaredCount][tlen] = '\0';
                        winDeclaredTypeToks[winDeclaredCount] = pTypeTok;
                        winDeclaredCount++;
                        if (!match_token(TOKEN_COMMA)) break;
                    }
                }
                consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_BLOCK_NAME);

                /*  Cas 1 : annotation type retour `: <Type>` toleree
                 * (consommee + ignoree) sur PROCEDURE de fenetre. Sans ce
                 * skip, le `:` casse en `:membre` au 1er statement du body. */
                if (is_return_type_colon() ||
                    (check(TOKEN_COLON) && !crossedNewline)) {
                    advance_token(); /* consume ':' */
                    skip_type_spec();
                }

                /* Validation contre catalogue (arite + types), symetrique champ. */
                if (winParamsParseOK && winDeclaredCount > 0 && winEventDef) {
                    if (winDeclaredCount > winEventDef->paramCount) {
                        char sigBuf[160];
                        if (winEventDef->paramCount == 0) {
                            snprintf(sigBuf, sizeof(sigBuf), "aucun");
                        } else {
                            snprintf(sigBuf, sizeof(sigBuf), "%s est un %s%s",
                                winEventDef->params[0].name,
                                winEventDef->params[0].typeName,
                                winEventDef->paramCount > 1 ? ", ..." : "");
                        }
                        char declaredBuf[16], maxBuf[16];
                        snprintf(declaredBuf, sizeof(declaredBuf), "%d", winDeclaredCount);
                        snprintf(maxBuf, sizeof(maxBuf), "%d", winEventDef->paramCount);
                        owl_emit_error_at(&nameTok, E_SEM_DSL_EVENT_TOO_MANY_PARAMS,
                                          "event", blockName,
                                          "declared", declaredBuf,
                                          "max", maxBuf,
                                          "signature", sigBuf,
                                          NULL);
                        winDeclaredCount = 0;
                    } else {
                        /*  : resolution bilingue du type declare (cf.
                         * site sous-champ ci-dessus). */
                        for (int i = 0; i < winDeclaredCount; i++) {
                            char declCanon[32], expCanon[32];
                            event_param_type_canon(winDeclaredTypeToks[i],
                                winDeclaredTypes[i], declCanon, sizeof(declCanon));
                            scanner_strip_accents(winEventDef->params[i].typeName,
                                (int)strlen(winEventDef->params[i].typeName),
                                expCanon, sizeof(expCanon));
                            for (char* p = expCanon; *p; p++)
                                *p = (char)tolower((unsigned char)*p);
                            if (strcmp(declCanon, expCanon) != 0) {
                                char posBuf[16];
                                snprintf(posBuf, sizeof(posBuf), "%d", i + 1);
                                owl_emit_error_at(&nameTok,
                                    E_SEM_DSL_EVENT_PARAM_TYPE_MISMATCH,
                                    "event", blockName,
                                    "position", posBuf,
                                    "name", winDeclaredNames[i],
                                    "expected", winEventDef->params[i].typeName,
                                    "got", winDeclaredTypes[i],
                                    NULL);
                                winDeclaredCount = 0;
                                break;
                            }
                        }
                    }
                }

                /* Bloc PROCEDURE de fenetre : MaFenetre dispo, pas MonChamp +
                 * params canon de l'event declares en locals. */
                const char* winParamPtrs[8];
                for (int i = 0; i < winDeclaredCount; i++)
                    winParamPtrs[i] = winDeclaredNames[i];
                ObjFunction* fn = compile_event_block_body_with_params(
                    blockName, false, winDeclaredCount, winParamPtrs);
                if (decl && fn) {
                    owl_window_decl_add_event(decl, blockName, fn, nameTok.line);
                }
                parser.panicMode = false;
            } else {
                /* Phase 6 : PROCEDURE custom dans body fenetre. */
                ObjFunction* fn = compile_user_proc_body(blockName);
                if (decl && fn) {
                    owl_window_decl_add_user_proc(decl, blockName, fn, nameTok.line);
                    char qualified[160];
                    snprintf(qualified, sizeof(qualified), "%s_%s",
                             decl->name, blockName);
                    dsl_aliases_add(blockName, qualified);
                    /*  lot 2 — qs rootee pendant table_set (cf.
                     * symetrie site subfield ~L14830).  : canon. */
                    ObjString* qs = obj_copy_string(qualified, (int)strlen(qualified));
                    vm_push(OBJ_VAL(qs));
                    obj_globals_set_kv(qs, NIL_VAL);
                    vm_pop();
                    /*  — emet aussi DEFINE_GLOBAL pour le nom NU dans
                     * le __fenetre_TopLevel. Permet aux PROCEDURE top-level
                     * du fichier-fenetre (helpers globaux) d'invoquer
                     * Valider(...) par nom nu en plus du qualifie. La fn
                     * est partagee — pas de duplication. */
                    Token nuToken;
                    nuToken.start = blockName;
                    nuToken.length = (int)strlen(blockName);
                    nuToken.line = nameTok.line;
                    nuToken.type = TOKEN_IDENTIFIER;
                    ConstIdx nuGlobal = identifier_constant(&nuToken);
                    emit_constant(OBJ_VAL(fn));
                    emit_const_op(OP_DEFINE_GLOBAL, nuGlobal);
                    /* Track le nom comme global declare (validation
                     * compile-time des references). */
                    global_track_declare(blockName, (int)strlen(blockName),
                                          nameTok.line);
                    global_track_mark_initialized(blockName,
                                                   (int)strlen(blockName));
                }
                parser.panicMode = false;
                free(blockName);
                continue;
            }

            free(blockName);
        } else {
            /*  — statement de niveau 0 (Trace(...), x += y, SI…,
             * appel de procedure…). C'est du code top-level fenetre : compile
             * dans winTopCompiler (current) via declaration(). Avant, ce code
             * etait silencieusement jete (advance_token). */
            /*  : reprise d'erreur uniforme avec le top-level. */
            bool savedDslBodyStmt = g_in_dsl_body_stmt;
            g_in_dsl_body_stmt = true;
            declaration();
            g_in_dsl_body_stmt = savedDslBodyStmt;
        }
    }

    /*  — finalise le top-level fenetre. Le compiler restore current
     * vers le main script. On stocke l'ObjFunction seulement si le body
     * contient du code utile (plus que l'OP_RETURN implicite : chunk->count>1).
     * Stocke AVANT le consume FIN car end_compiler restore current ; les
     * checks ulterieurs (PROPRIETES manquant, Layout) operent sur le decl. */
    ObjFunction* winTopFn = end_compiler();
    if (decl && winTopFn && winTopFn->chunk && winTopFn->chunk->count > 1) {
        decl->top_level = winTopFn;
    }

    /*  — modele d'execution : la fenetre est ENDORMIE jusqu'a Ouvre.
     * Son top-level (code d'init, ) ne tourne PLUS de maniere eager au
     * chargement du script ; il est execute UNE SEULE FOIS par Ouvre, dans son
     * contexte (build_window / open_window_instance, stdlib_ui). L'eager
     * historique provoquait un double-run (boot + Ouvre) et faisait
     * tourner le top-level d'un voisin fenetre jamais ouvert.
     *
     * On preserve neanmoins la VISIBILITE COMPILE-TIME des noms des globales
     * top-level fenetre : elle vient des global_track_declare emis pendant la
     * compil du body (boucle declaration() ci-dessus), independants de tout
     * code runtime. Aucune emission dans le chunk principal n'est donc
     * necessaire ici. Avant Ouvre, ces globales n'existent pas au runtime
     * (fenetre endormie : noms connus du compilo, valeurs indisponibles tant
     * que la fenetre n'est pas ouverte). A l'Ouvre, build_window /
     * open_window_instance lient les helpers qualifies '<window>_<proc>' PUIS
     * executent decl->top_level (vraies valeurs + effets de bord, une fois).
     *
     * Note : l'ancienne liaison eager des globales qualifiees des helpers
     * est devenue inutile — elle ne servait qu'a faire resoudre les
     * call-sites reecrits qualifie PENDANT l'appel eager. Le top-level ne
     * tournant plus qu'a l'ouverture (moment ou stdlib_ui a deja lie ces
     * globales, /0494), elle est supprimee (pas de code mort). */

    if (check(TOKEN_FIN)) {
        advance_token(); /* consume FIN */
    } else {
        owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_FIN_CLOSE_WINDOW);
    }

    /* DSL v2 : bloc PROPRIETES obligatoire dans la fenetre. */
    if (!propertiesBlockSeen && !dup) {
        char nameBuf[128];
        snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                 windowName.length, windowName.start);
        owl_emit_error_at(&windowName,
                          E_SEM_DSL_PROPRIETES_BLOCK_MISSING_WINDOW,
                          "name", nameBuf,
                          NULL);
    }

    (void)dup;

    /*  — `MenuPrincipal = X` se resout ici : les blocs MenuPrincipal
     * se declarent apres le bloc PROPRIETES, donc la cible n'est connue qu'a
     * la fermeture du body. */
    window_resolve_main_menu(decl);

    /*  — `MenuContextuel = X` (fenetre + champs) se resout ici, meme
     * raison : la cible peut etre declaree apres l'attache. */
    window_resolve_context_menus(decl);

    /* Note : les noms de sous-champs sont exposes comme globals strings
     * directement dans window_parse_subfield (pour qu'ils soient
     * visibles depuis les PROCEDURE freres compiles immediatement). */

    /* Lot F — validation X/Y interdit hors dispLibre.
     * Pour chaque sous-champ avec une prop X ou Y, on verifie que SON parent
     * (Fenetre ou Conteneur) est en Disposition = dispLibre. Sinon erreur.
     * Defaut Disposition = dispVerticale (strict modern).
     * dispVerticale=0, dispHorizontale=1, dispGrille=2, dispLibre=3.
     * Lookup du parent : si parent_name=NULL -> Fenetre ; sinon controle nomme. */
    if (decl) {
        for (int i = 0; i < decl->control_count; i++) {
            OwlControlDecl* c = &decl->controls[i];
            int xLine = -1, yLine = -1;
            for (int j = 0; j < c->property_count; j++) {
                if (strcasecmp(c->properties[j].name, "X") == 0) xLine = c->properties[j].line;
                if (strcasecmp(c->properties[j].name, "Y") == 0) yLine = c->properties[j].line;
            }
            if (xLine <= 0 && yLine <= 0) continue;

            /* Chercher la Disposition du parent (Window ou Conteneur). */
            int parent_disp = OWL_DISP_VERTICALE;  /* defaut dispVerticale */
            const char* parent_label = "la fenetre";
            OwlPropertyInit* parent_props = NULL;
            int parent_prop_count = 0;
            bool parent_is_zr = false;
            if (c->parent_name) {
                /* Parent = un autre controle de la meme fenetre. */
                for (int k = 0; k < decl->control_count; k++) {
                    if (strcmp(decl->controls[k].name, c->parent_name) == 0) {
                        parent_props = decl->controls[k].properties;
                        parent_prop_count = decl->controls[k].property_count;
                        parent_label = c->parent_name;
                        if (decl->controls[k].kind == OWL_CONTROL_ZONE_REPETEE)
                            parent_is_zr = true;
                        break;
                    }
                }
            } else {
                parent_props = decl->properties;
                parent_prop_count = decl->property_count;
            }
            for (int j = 0; j < parent_prop_count; j++) {
                OwlPropertyInit* p = &parent_props[j];
                /* Nom de prop bilingue : Disposition (FR) ou Layout (EN), aligne
                 * sur la resolution bilingue runtime de find_prop (stdlib_ui.c). */
                if ((strcasecmp(p->name, "Disposition") == 0
                     || strcasecmp(p->name, "Layout") == 0)
                    && p->is_constant && IS_INTEGER(p->const_value)) {
                    parent_disp = (int)AS_INTEGER(p->const_value);
                    break;
                }
            }

            /* Sous-widget d'une ZR : exempte du check (le rep container du
             * template n'a pas de QLayout, X/Y absolu est la norme). */
            if (parent_is_zr) continue;

            if (parent_disp != OWL_DISP_LIBRE) {
                Token fakeTok = {0};
                fakeTok.line = (xLine > 0) ? xLine : yLine;
                fakeTok.start = c->name;
                fakeTok.length = (int)strlen(c->name);
                owl_emit_error_at(&fakeTok,
                                  E_SEM_DSL_XY_FORBIDDEN_NOT_LIBRE,
                                  "name", c->name,
                                  "parent", parent_label,
                                  NULL);
            }
        }
    }

    /*  — warning ColSpan/RowSpan sans effet hors dispGrille.
     * Mirroir du check X/Y ci-dessus : ces props (fusion de cellules) n'ont de
     * sens que si le parent (Fenetre ou Conteneur) est en Disposition =
     * dispGrille. Ailleurs (defaut dispVerticale, dispLibre, dispHorizontale)
     * elles sont ignorees au rendu -> warning non-bloquant. Meme lookup du
     * parent que le check X/Y ; ZR exemptee (pas de QLayout sur son template).
     * Le warning porte le canon FR (ColSpan/RowSpan) meme si la source emploie
     * l'alias EN (ColumnSpan), via 2 codes distincts (parite bilingue). */
    if (decl) {
        for (int i = 0; i < decl->control_count; i++) {
            OwlControlDecl* c = &decl->controls[i];

            /* Le control a-t-il au moins une prop ColSpan/ColumnSpan/RowSpan ? */
            bool has_span = false;
            for (int j = 0; j < c->property_count; j++) {
                const char* pn = c->properties[j].name;
                if (strcasecmp(pn, "ColSpan") == 0
                    || strcasecmp(pn, "ColumnSpan") == 0
                    || strcasecmp(pn, "RowSpan") == 0) {
                    has_span = true;
                    break;
                }
            }
            if (!has_span) continue;

            /* Chercher la Disposition du parent (Window ou Conteneur) —
             * strictement le meme lookup que le check X/Y ci-dessus. */
            int parent_disp = OWL_DISP_VERTICALE;  /* defaut dispVerticale */
            const char* parent_label = "la fenetre";
            OwlPropertyInit* parent_props = NULL;
            int parent_prop_count = 0;
            bool parent_is_zr = false;
            if (c->parent_name) {
                for (int k = 0; k < decl->control_count; k++) {
                    if (strcmp(decl->controls[k].name, c->parent_name) == 0) {
                        parent_props = decl->controls[k].properties;
                        parent_prop_count = decl->controls[k].property_count;
                        parent_label = c->parent_name;
                        if (decl->controls[k].kind == OWL_CONTROL_ZONE_REPETEE)
                            parent_is_zr = true;
                        break;
                    }
                }
            } else {
                parent_props = decl->properties;
                parent_prop_count = decl->property_count;
            }
            for (int j = 0; j < parent_prop_count; j++) {
                OwlPropertyInit* p = &parent_props[j];
                if ((strcasecmp(p->name, "Disposition") == 0
                     || strcasecmp(p->name, "Layout") == 0)
                    && p->is_constant && IS_INTEGER(p->const_value)) {
                    parent_disp = (int)AS_INTEGER(p->const_value);
                    break;
                }
            }

            if (parent_is_zr) continue;
            if (parent_disp == OWL_DISP_GRILLE) continue;

            /* Emettre par occurrence de prop, dans l'ordre de declaration. */
            for (int j = 0; j < c->property_count; j++) {
                OwlPropertyInit* p = &c->properties[j];
                bool is_col = (strcasecmp(p->name, "ColSpan") == 0
                               || strcasecmp(p->name, "ColumnSpan") == 0);
                bool is_row = (strcasecmp(p->name, "RowSpan") == 0);
                if (!is_col && !is_row) continue;
                Token fakeTok = {0};
                fakeTok.line = p->line;
                fakeTok.start = c->name;
                fakeTok.length = (int)strlen(c->name);
                owl_emit_warning_at(&fakeTok,
                                    is_col ? W_SEM_COLSPAN_NOT_GRILLE
                                           : W_SEM_ROWSPAN_NOT_GRILLE,
                                    "name", c->name,
                                    "parent", parent_label,
                                    NULL);
            }
        }
    }

    /*  — validation marge interieure interdite en dispLibre.
     * Symetrique du check X/Y ci-dessus : sans layout, aucune marge interieure
     * ne peut ecarter le contenu du bord. La propriete etait acceptee et
     * silencieusement ignoree au rendu. Le check porte sur le bloc qui DECLARE
     * la disposition (fenetre ou conteneur), pas sur ses enfants. */
    if (decl) {
        for (int i = -1; i < decl->control_count; i++) {
            OwlPropertyInit* props = (i < 0) ? decl->properties
                                             : decl->controls[i].properties;
            int prop_count = (i < 0) ? decl->property_count
                                     : decl->controls[i].property_count;
            const char* block_name = (i < 0) ? decl->name : decl->controls[i].name;

            bool is_libre = false;
            for (int j = 0; j < prop_count; j++) {
                OwlPropertyInit* p = &props[j];
                if ((strcasecmp(p->name, "Disposition") == 0
                     || strcasecmp(p->name, "Layout") == 0)
                    && p->is_constant && IS_INTEGER(p->const_value)
                    && (int)AS_INTEGER(p->const_value) == OWL_DISP_LIBRE) {
                    is_libre = true;
                    break;
                }
            }
            if (!is_libre) continue;

            for (int j = 0; j < prop_count; j++) {
                OwlPropertyInit* p = &props[j];
                /* Nom bilingue, forme uniforme Padding* / Padding*. */
                if (strncasecmp(p->name, "Padding", 7) != 0) continue;
                Token fakeTok = {0};
                fakeTok.line = p->line;
                fakeTok.start = block_name;
                fakeTok.length = (int)strlen(block_name);
                owl_emit_error_at(&fakeTok,
                                  E_SEM_DSL_PADDING_FORBIDDEN_LIBRE,
                                  "name", block_name,
                                  "prop", p->name,
                                  NULL);
            }
        }
    }

    /*  — warning raccourci clavier duplique DANS une meme fenetre.
     * Portee = decl courant : deux fenetres distinctes peuvent reutiliser le
     * meme raccourci sans conflit. Pour chaque control ayant un raccourci
     * effectif, on cherche un control anterieur (meme fenetre) avec le meme
     * raccourci normalise ; si trouve, warning sur le control courant (2e
     * site). O(n^2) sur le nombre de controls — trivial pour une fenetre. */
    if (decl) {
        for (int j = 0; j < decl->control_count; j++) {
            char normJ[64], dispJ[64];
            int lineJ = decl->controls[j].line;
            if (!control_effective_shortcut(&decl->controls[j],
                                            normJ, sizeof normJ,
                                            dispJ, sizeof dispJ, &lineJ))
                continue;
            bool dup = false;
            for (int i = 0; i < j && !dup; i++) {
                char normI[64], dispI[64];
                int lineI = 0;
                if (control_effective_shortcut(&decl->controls[i],
                                               normI, sizeof normI,
                                               dispI, sizeof dispI, &lineI)
                    && strcmp(normJ, normI) == 0)
                    dup = true;
            }
            if (dup) {
                Token t = {0};
                t.line = lineJ;
                t.column = 1;
                t.start = decl->controls[j].name;
                t.length = (int)strlen(decl->controls[j].name);
                owl_emit_warning_at(&t, W_SEM_SHORTCUT_DUPLICATE,
                                    "raccourci", dispJ,
                                    NULL);
            }
        }
    }

    /* Phase 6 : pop le scope d'aliases de la fenetre. */
    dsl_aliases_pop_scope();

    /*  — restore window decl tracker (parent fenetre si imbriquee,
     * sinon NULL). */
    g_current_window_decl = savedWindowDecl;
    /*  — restore le contexte element courant. */
    memcpy(g_current_element_name, savedElementName, sizeof(g_current_element_name));
    g_toplevel_confine = savedConfineWin;  /*  */

    /* Clear panicMode pour que la prochaine declaration top-level
     * (incluant une autre fenetre) parte sur un etat propre. */
    parser.panicMode = false;
}

/* ================================================================
 * DSL Etat V2 — etat_declaration
 * ================================================================
 *
 * Syntaxe :
 *   ETA_X est un Etat
 *       PROPRIETES
 *           Format = formatA4
 *           ...
 *       FIN
 *
 *       INTRO est un EnTeteDocument
 *           PROPRIETES Hauteur = 40 FIN  // optionnel
 *           <code canon>                    // body bytecode
 *       FIN
 *
 *       LIGNE est un Corps
 *           ...
 *       FIN
 *
 *       PROCEDURE Initialisation(p1, p2)
 *           ...
 *       FIN
 *   FIN
 *
 * Types de blocs canon : EnTeteDocument / HautDePage / Corps / BasDePage /
 * FinDeDocument / Iteration. Un seul de chaque canon, plusieurs Iteration OK.
 */

/* Compile le body code d'un sub-bloc Etat en ObjFunction. Capture le code
 * inline (apres le PROPRIETES optionnel) jusqu'au FIN du sub-bloc. */
/* Compile une expression OWL standalone en une ObjFunction qui la retourne.
 * Equivalent d'un lambda 0-arg `() => <expression>`. Utilise par les props
 * dynamiques de Libelle d'Etat (ex: 'Libellé = client' ou 'Libellé = "X" + maVar').
 * Le caller doit etre positionne sur le 1er token de l'expression. */
static ObjFunction* compile_expression_as_fn(const char* fnName) {
    Compiler ec;
    init_compiler(&ec, TYPE_FUNCTION);
    begin_scope();
    current->function->name = obj_copy_string(fnName, (int)strlen(fnName));
    expression();
    /* Top-of-stack contient la valeur. OP_RETURN la pop et la renvoie. */
    emit_byte(OP_RETURN);
    return end_compiler();
}

/*  — Implementation du parseur Icone literal partage. Voir le forward
 * decl (compile_icone_brace_literal_inplace) pour la docstring complete. */
static void compile_icone_brace_literal_inplace(void) {
    advance_token(); /* consume '{' */
    /* Skip newlines initiales. */
    while (check(TOKEN_NEWLINE)) advance_token();

    /* Emit le prologue InstanceCoerce sur la stack. */
    Token coerceTok;
    coerceTok.start  = "__InstanceCoerce";
    coerceTok.length = 16;
    ConstIdx coerceIdx = identifier_constant(&coerceTok);
    emit_const_op(OP_GET_GLOBAL, coerceIdx);

    /* Parse l'expression source (1er element). Cas vide `{}` : pousser NIL
     * pour produire une Icone vide. */
    if (check(TOKEN_RIGHT_BRACE)) {
        emit_byte(OP_NIL);
    } else {
        condition_expression();
    }

    /* Push le nom de type "Icone" (constante chaine) + CALL 2 -> ObjIcone
     * materialise. */
    ObjString* iconeTypeName = obj_copy_string("Icone", 5);
    ConstIdx iconeTypeIdx = make_constant(OBJ_VAL(iconeTypeName));
    emit_const_op(OP_CONSTANT, iconeTypeIdx);
    emit_bytes(OP_CALL, 2);

    /* Boucle des bindings nommes `IDENT = expr` separes par virgule ou
     * newline. */
    while (!check(TOKEN_RIGHT_BRACE) && !check(TOKEN_EOF)) {
        while (check(TOKEN_COMMA) || check(TOKEN_NEWLINE)) {
            advance_token();
        }
        if (check(TOKEN_RIGHT_BRACE) || check(TOKEN_EOF)) break;

        /* Field name : un identifier (ou keyword-token que le scanner peut
         * reconnaitre pour Couleur etc.). */
        if (parser.current.type < TOKEN_IDENTIFIER ||
            parser.current.type >= TOKEN_NEWLINE) {
            owl_emit_error_current(E_SYNTAX_EXPECTED_FIELD_NAME_IN_BRACE);
            break;
        }
        Token fieldName = parser.current;
        advance_token();

        if (!match_token(TOKEN_EQUAL)) {
            owl_emit_error_at(&fieldName,
                E_SYNTAX_EXPECTED_EQUAL_AFTER_FIELD);
            break;
        }

        /* Emit DUP / expr / STRUCT_SET <field> / POP. */
        emit_byte(OP_DUP);
        condition_expression();
        ConstIdx fnameIdx = identifier_constant(&fieldName);
        emit_const_op(OP_STRUCT_SET, fnameIdx);
        emit_byte(OP_POP);
    }

    consume(TOKEN_RIGHT_BRACE, E_SYNTAX_EXP_RBRACE_ICONE);

    /* Le tag pose par un caller pour instance_literal n'a plus lieu d'etre —
     * on a consume le bloc nous-meme. */
    g_inline_target_type     = NULL;
    g_inline_target_type_len = 0;
}

static ObjFunction* compile_icone_brace_literal_as_fn(const char* fnName) {
    Compiler ec;
    init_compiler(&ec, TYPE_FUNCTION);
    begin_scope();
    current->function->name = obj_copy_string(fnName, (int)strlen(fnName));
    compile_icone_brace_literal_inplace();
    emit_byte(OP_RETURN);
    return end_compiler();
}

/* Parse une prop simple 'IDENT = <literal | expression>' dans un Libelle d'Etat.
 * Pas de validation contre un catalogue (V2 PoC) — toutes les props sont
 * acceptees. Si l'expression n'est pas un literal, on la compile comme une
 * fonction 0-arg (eval) appelee a chaque rendu. */
static void etat_label_parse_property_init(OwlControlDecl* ctrl) {
    if (!check(TOKEN_IDENTIFIER) && !check(TOKEN_LIBELLE)) {
        owl_emit_error_current(E_SYNTAX_EXPECTED_PROP_NAME_ETAT_LABEL);
        advance_token();
        return;
    }
    Token propTok = parser.current;
    advance_token();

    /*  : cascade declarative `Prop..SousChamp = valeur` dans un
     * Libelle d'Etat (ex: Cadre..Epaisseur = 3). Symetrique de
     * control_parse_property_init (Fenetre). Le Libelle d'Etat n'a pas de
     * catalogue de props (toutes acceptees), donc on derive l'object_type du
     * nom de prop lui-meme : pour les props composees canon (Cadre, Police),
     * le nom de prop EST le nom du type compose enregistre. */
    if (check(TOKEN_DOUBLE_DOT) && ctrl) {
        char propAsciiC[128];
        int pl = scanner_strip_accents(propTok.start, propTok.length,
                                       propAsciiC, sizeof(propAsciiC));
        if (pl <= 0) pl = propTok.length < 127 ? propTok.length : 127;
        propAsciiC[pl] = '\0';
        const OwlTypeDef* td = owl_registry_type_find(propAsciiC);
        if (!td || !td->canonicalAscii) {
            /* Pas un type compose connu : la cascade n'a pas de cible. */
            owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
            window_skip_to_next_stmt();
            return;
        }
        /* Invariant : g_cascade_buffer est toujours actif ici. Toute prop DSL
         * (donc toute cascade `..`) est parsee dans un bloc PROPRIETES qui ouvre
         * ce buffer ; il n'existe pas de chemin d'entree hors buffer. La cascade
         * est bufferisee pour regroupement compile-time des cascades homonymes. */
        cascade_buffer_capture(g_cascade_buffer, propTok,
                               propAsciiC, pl,
                               td->canonicalAscii,
                               (int)strlen(td->canonicalAscii), NULL);
        return;
    }

    if (!match_token(TOKEN_EQUAL)) {
        owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
        return;
    }
    if (dsl_prop_value_missing_reported(&propTok)) return;
    char propName[128];
    int n = scanner_strip_accents(propTok.start, propTok.length, propName, sizeof(propName));
    if (n <= 0) n = propTok.length < 127 ? propTok.length : 127;
    propName[n] = '\0';
    int line = propTok.line;

    /*  Lot D — parité Fenêtre/État pour le littéral colon-brace
     * `{...}`. Le parseur générique d'un sous-champ d'État (modèle plat, sans
     * validation catalogue) ne posait pas le type cible pour un littéral inline,
     * d'où BRACE_LITERAL_NO_TYPE là où la Fenêtre compile. On aligne sur
     * control_parse_property_init : lookup best-effort de la prop dans le
     * catalogue du kind du sous-champ, et pour un slot multilingue (ex.
     * ..Libellé) on tag g_inline_target_type. Prop absente du catalogue =
     * comportement générique inchangé (pas de validation). */
    const OwlControlPropDef* def =
        ctrl ? owl_control_catalog_find(ctrl->kind, propName) : NULL;

    /*  : valeur nue chaine-sans-guillemets dans un Libelle d'Etat
     * (symetrie stricte avec window/control_parse_property_init). Sans ce garde,
     * la valeur nue part sur le chemin expression dynamique et desynchronise la
     * boucle PROPRIETES -> cascade trompeuse ("variable inconnue" sur le 1er
     * mot, "Nom de propriete attendu" sur la ligne valide suivante). Peek pur,
     * message clair + resync a la propriete suivante. */
    if (dsl_prop_value_is_bare_words(def)) {
        owl_emit_error_at(&propTok, E_SEM_DSL_PROP_VALUE_BARE_WORDS,
                          "prop", propName, NULL);
        window_skip_to_next_stmt();
        return;
    }

    if (def && check(TOKEN_LEFT_BRACE)) {
        if (def->type == OWL_PROP_TYPE_MULTILINGUE) {
            g_inline_target_type     = "cha\xc3\xae" "neMultilingue";
            g_inline_target_type_len = (int)strlen("cha\xc3\xae" "neMultilingue");
            char fnNameBuf[160];
            snprintf(fnNameBuf, sizeof(fnNameBuf), "__etat_label_prop_%s", propName);
            ObjFunction* eval = compile_expression_as_fn(fnNameBuf);
            if (ctrl) owl_control_decl_add_property(ctrl, propName, NIL_VAL, eval, false, line);
            return;
        }
        if (def->type == OWL_PROP_TYPE_VARIANT) {
            char fnNameBuf[160];
            snprintf(fnNameBuf, sizeof(fnNameBuf), "__etat_label_prop_%s", propName);
            ObjFunction* eval = compile_icone_brace_literal_as_fn(fnNameBuf);
            if (ctrl) owl_control_decl_add_property(ctrl, propName, NIL_VAL, eval, false, line);
            return;
        }
        if (def->type == OWL_PROP_TYPE_COLOR) {
            /*  (L3.6) — cf. window_parse_property_init : littéral
             * couleur inline en PROPRIETES sur un slot couleur -> Couleur. */
            g_inline_target_type     = "Couleur";
            g_inline_target_type_len = 7;
            char fnNameBuf[160];
            snprintf(fnNameBuf, sizeof(fnNameBuf), "__etat_label_prop_%s", propName);
            ObjFunction* eval = compile_expression_as_fn(fnNameBuf);
            if (ctrl) owl_control_decl_add_property(ctrl, propName, NIL_VAL, eval, false, line);
            return;
        }
        if (def->type != OWL_PROP_TYPE_ENUM
            && def->type != OWL_PROP_TYPE_OBJECT) {
            /* Slot non-texte : rejet propre (pas de coercition ni d'inférence). */
            owl_emit_error_at(&parser.current, E_SEM_DSL_INLINE_DICT_NOT_MULTILINGUE,
                              "prop", def->nameFR,
                              "type", owl_prop_type_name(def->type),
                              NULL);
            window_skip_to_next_stmt();
            return;
        }
        /* ENUM/OBJECT : g_inline_target_type posé dans le chemin dynamique. */
    }

    /* Tentative literal d'abord (rapide + permet const-folding). */
    Scanner saved = parser.scanner;
    Token savedCur = parser.current;
    Token savedPrev = parser.previous;
    bool savedCrossed = crossedNewline;

    Value v;
    /*  : cf. window_parse_property_init / control_parse_property_init
     *. Le const-folder s'arrete au premier atome non foldable et
     * rollback le reste (`"a" + RC + "b"` folde `"a"` puis rend `+ RC ...`),
     * mais renvoie quand meme true en laissant le curseur AVANT le terminateur.
     * Une valeur pleinement constante laisse le curseur sur un terminateur de
     * propriete (newline traverse, FIN, EOF) ; un reliquat d'operateur sur la
     * meme ligne signale une expression composee -> chemin dynamique
     * (compile_expression_as_fn) au lieu d'accepter un litteral partiel. Parite
     * avec l'imperatif `WIDGET..Prop = <expr>`. */
    if (window_try_parse_const_literal(&v)
        && (crossedNewline || check(TOKEN_FIN) || check(TOKEN_EOF))) {
        if (ctrl) owl_control_decl_add_property(ctrl, propName, v, NULL, true, line);
        return;
    }

    /* Pas un literal : restore et compile comme expression dynamique. */
    parser.scanner = saved;
    parser.current = savedCur;
    parser.previous = savedPrev;
    crossedNewline = savedCrossed;

    /* Parité chemin dynamique Fenêtre : pour une prop ENUM/OBJECT, propager le
     * type cible au littéral inline `{...}` (ou `[ {...} ]`). */
    const char* inlineTarget = prop_inline_target_type(def);
    if (inlineTarget &&
        (check(TOKEN_LEFT_BRACE) || check(TOKEN_LEFT_BRACKET))) {
        g_inline_target_type     = inlineTarget;
        g_inline_target_type_len = (int)strlen(inlineTarget);
    }

    char fnNameBuf[160];
    snprintf(fnNameBuf, sizeof(fnNameBuf), "__etat_label_prop_%s", propName);
    ObjFunction* eval = compile_expression_as_fn(fnNameBuf);
    if (ctrl) {
        owl_control_decl_add_property(ctrl, propName, NIL_VAL, eval, false, line);
    }
}

/* Parse: 'IDENT est un Libellé ... FIN' a l'interieur d'un bloc Etat.
 * Le caller a deja consomme IDENT + EST + LIBELLE. nameTok = nom du libelle.
 * Au runtime, iImprimeEtat parcourt b->controls et imprime chaque Libelle
 * via iImprimeZone + iPolice.
 *
 * DSL v2 : bloc PROPRIETES obligatoire — meme contrat que les widgets
 * Fenetre (cf etat_parse_widget). Permet aux outils (formatter, designer,
 * LSP) d'avoir une grammaire homogene Fenetre <-> Etat. */
/* Parse 'PROCEDURE name() ... FIN' a l'interieur du body d'un sous-control
 * d'un Etat (Libelle, Image). name doit etre Initialisation ou
 * AvantImpression (canon et derives). Le caller a deja
 * consomme TOKEN_PROCEDURE. */
static void etat_control_parse_procedure(OwlControlDecl* ctrl) {
    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_current(E_SYNTAX_EXPECTED_EVENT_NAME_AFTER_PROC);
        return;
    }
    Token nameTok = parser.current;
    advance_token();

    char blockName[64];
    int nlen = nameTok.length < 63 ? nameTok.length : 63;
    memcpy(blockName, nameTok.start, nlen);
    blockName[nlen] = '\0';

    /*  — l'event 'Initialisation' n'existe plus (sous-champ d'Etat
     * inclus) : le code d'init vit dans le top-level du champ. Rejet net. */
    if (window_ci_eq(blockName, "Initialisation")
        || window_ci_eq(blockName, "Initialization")) {
        owl_emit_error_at(&nameTok, E_SEM_DSL_INITIALISATION_OBSOLETE, NULL);
        if (match_token(TOKEN_LEFT_PAREN)) {
            while (!check(TOKEN_RIGHT_PAREN) && !check(TOKEN_EOF)) advance_token();
            if (check(TOKEN_RIGHT_PAREN)) advance_token();
        }
        window_skip_nested_block();
        return;
    }

    /* Validation : consomme owl_etat_subcontrol_event_catalog (source
     * de vérité unique pour la liste des events lifecycle des
     * sous-contrôles d'État). Toute fiche ajoutée au catalogue est
     * acceptée automatiquement par le compilateur. */
    bool valid = owl_etat_subcontrol_event_catalog_find(blockName) != NULL;
    if (!valid) {
        /*  — un nom libre (helper) dans un widget d'Etat est
         * refuse avec le meme message pedagogique que les blocs/sections
         * d'Etat (etat_compile_block_user_proc) et que les widgets de
         * Fenetre (E_SEM_DSL_PROC_HELPER_NOT_TOPLEVEL) : seul le top-level
         * de l'Etat porte des procedures globales ; un sous-champ ne porte
         * que ses events connus (AvantImpression). On skip params + body
         * (anti-cascade) et on repart propre — comme le miroir Fenetre. */
        owl_emit_error_at(&nameTok, E_SEM_ETAT_PROC_HELPER_NOT_TOPLEVEL,
                          "name", blockName, NULL);
        if (match_token(TOKEN_LEFT_PAREN)) {
            int parenDepth = 1;
            while (parenDepth > 0 && !check(TOKEN_EOF)) {
                if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                if (parenDepth > 0) advance_token();
            }
            if (check(TOKEN_RIGHT_PAREN)) advance_token();
        }
        window_skip_nested_block();
        parser.panicMode = false;
        return;
    }

    if (!match_token(TOKEN_LEFT_PAREN)) {
        owl_emit_error_current(E_SYNTAX_EXPECTED_LPAREN_AFTER_EVENT_NAME);
        window_skip_nested_block();
        return;
    }
    if (!match_token(TOKEN_RIGHT_PAREN)) {
        owl_emit_warning_at(&nameTok,
            W_SEM_ETAT_SUBFIELD_EVENT_PARAMS_IGNORED, NULL);
        while (!check(TOKEN_RIGHT_PAREN) && !check(TOKEN_EOF)) advance_token();
        if (check(TOKEN_RIGHT_PAREN)) advance_token();
    }

    ObjFunction* fn = compile_event_block_body(blockName, true);
    if (ctrl && fn && valid) {
        owl_control_decl_add_event(ctrl, blockName, fn, nameTok.line);
    }
    parser.panicMode = false;
}

/* Parse: 'IDENT est un Champ <Genre> ... FIN' a l'interieur d'un bloc Etat.
 * Le caller a deja consomme IDENT + EST + Champ + <Genre>. nameTok = nom du
 * controle, kind = OwlControlKind detecte.
 *
 *  : unifie les anciens etat_parse_block_label/_image. Le body
 * (PROPRIETES, PROCEDURE, top-level) est identique quel que soit le genre ;
 * seul le kind du decl change (le rendu PDF aiguille ensuite sur ctrl->kind :
 * render_etat_label / render_etat_image / ...). */
static void etat_parse_block_control(OwlEtatBlockDecl* b, OwlControlKind kind,
                                     Token nameTok, int line) {
    char* ctrlName = (char*)malloc((size_t)nameTok.length + 1);
    memcpy(ctrlName, nameTok.start, nameTok.length);
    ctrlName[nameTok.length] = '\0';

    OwlControlDecl* ctrl = owl_control_decl_new(kind, ctrlName, line);

    /*  lot D — pose un ObjUiControlRef dans vm.globals sous la cle
     * strippee du nom du sous-champ. Modele EXACT de window_parse_subfield.
     * Permet a `LIB_X..Prop` d'etre resolvable a runtime via resolve_ui_ref(),
     * qui consultera etat_stack en repli. Le decl C est consomme par
     * owl_etat_block_decl_add_control en fin de parse (shallow copy + free) :
     * pour une resolution stable on passe le nom strippe au ref. */
    {
        char gstripped[256];
        int glen = scanner_strip_accents(ctrlName, (int)strlen(ctrlName),
                                          gstripped, sizeof(gstripped));
        /*  lot 2 — roots GC compile-time : sans roots, sous
         * DEBUG_STRESS_GC le triple-alloc (string + ref + table_set/grow)
         * collecte gname avant usage -> string corrompue au runtime. */
        ObjString* gname = obj_copy_string(gstripped, glen);
        vm_push(OBJ_VAL(gname));
        ObjUiControlRef* ref = obj_new_ui_control_ref_named(ctrl, gname);
        vm_push(OBJ_VAL(ref));
        obj_globals_set_kv(gname, OBJ_VAL(ref));  /*  : canon */
        vm_pop();  /* ref */
        vm_pop();  /* gname */
    }

    /*  lot 1c +  lot 3-bis A1 — isolation du scope du
     * sous-champ d'Etat (symetrie champ de fenetre, Lot 1b). Push mini-stack
     * pour rester GC-rooted. */
    if (g_control_decl_top >= G_CONTROL_DECL_STACK_MAX) {
        fprintf(stderr,
                "[compile] control nesting depth > %d (limite interne)\n",
                G_CONTROL_DECL_STACK_MAX);
        parser.hadError = true;
        return;
    }
    g_control_decl_stack[g_control_decl_top++] = ctrl;

    /*  lot 1c — top-level executable du sous-champ d'Etat. Tout code
     * de niveau 0 dans le body est compile dans cette ObjFunction implicite,
     * executee 1x a l'ouverture de l'Etat. Modele identique au champ de
     * fenetre (ctrlTopCompiler). */
    Compiler ctrlTopCompiler;
    init_compiler(&ctrlTopCompiler, TYPE_FUNCTION);
    {
        char topFnName[200];
        snprintf(topFnName, sizeof(topFnName), "__etat_champ_%s_TopLevel",
                 ctrlName);
        current->function->name =
            obj_copy_string(topFnName, (int)strlen(topFnName));
    }

    bool propsBlockSeen = false;
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;

        if (check(TOKEN_PROPRIETES)) {
            advance_token();
            if (propsBlockSeen) {
                owl_emit_error_current(E_SYNTAX_DUPLICATE_PROPRIETES_ETAT);
            }
            propsBlockSeen = true;
            /*  : buffer cascade actif pendant la duree du bloc
             * PROPRIETES pour regrouper les cascades homonymes en un seul eval. */
            CascadeBuffer ctrlCascadeBuf;
            cascade_buffer_init(&ctrlCascadeBuf);
            CascadeBuffer* savedCascadeBuf = g_cascade_buffer;
            g_cascade_buffer = &ctrlCascadeBuf;
            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                while (check(TOKEN_NEWLINE)) advance_token();
                if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
                etat_label_parse_property_init(ctrl);  /* generique : pas valide
                                                        * contre catalogue ici */
            }
            g_cascade_buffer = savedCascadeBuf;
            cascade_buffer_flush(&ctrlCascadeBuf, CASCADE_FLUSH_CONTROL, ctrl,
                                  "__etat_label_prop");
            cascade_buffer_free(&ctrlCascadeBuf);
            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROPRIETES_ETAT_CHAMP);
            continue;
        }
        if (check(TOKEN_PROCEDURE)) {
            advance_token();
            etat_control_parse_procedure(ctrl);
            continue;
        }

        /*  lot 1c — tout le reste = code top-level du sous-champ,
         * compile dans ctrlTopCompiler (current). */
        declaration();
    }
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_ETAT_CHAMP);

    /* Finalise le top-level : stocke seulement si du code utile a ete emis
     * (chunk->count > 1 = plus que l'OP_RETURN implicite). */
    ObjFunction* ctrlTopFn = end_compiler();
    if (ctrl && ctrlTopFn && ctrlTopFn->chunk && ctrlTopFn->chunk->count > 1) {
        ctrl->top_level = ctrlTopFn;
    }
    /*  lot 3-bis A1 — pop mini-stack. */
    if (g_control_decl_top > 0) g_control_decl_top--;

    if (!propsBlockSeen) {
        owl_emit_error_at(&nameTok,
                          E_SEM_ETAT_CONTROL_PROPRIETES_MISSING,
                          "name", ctrlName,
                          "genre", owl_control_kind_name_fr(kind),
                          NULL);
    }
    free(ctrlName);

    if (b) {
        owl_etat_block_decl_add_control(b, ctrl);
    } else {
        owl_control_decl_free(ctrl);
    }
}

/*  — modele plat Etat : une PROCEDURE declaree DANS un bloc (corps,
 * en-tete, pied, widget...) est une procedure GLOBALE de l'Etat, exactement
 * comme une proc top-level. On la compile ici et on l'enregistre dans
 * decl->user_procs (PAS via declaration(), qui en ferait une globale/locale
 * de programme et declencherait l'erreur de masking sur le slot pre-reserve
 * par la pre-passe). Le current token est sur PROCEDURE/FONCTION a l'entree.
 * Aucune globale au nom nu n'est emise : la liaison runtime au nom qualifie
 * `<etat>_<proc>` (iImprimeEtat) + l'alias DSL scope a l'Etat suffisent, et
 * preservent la fermeture externe. */
static void etat_compile_block_user_proc(OwlEtatDecl* decl) {
    advance_token(); /* consume PROCEDURE/FONCTION */
    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_current(E_SYNTAX_EXPECTED_PROC_NAME_AFTER_PROC);
        return;
    }
    Token nameTok = parser.current;
    advance_token();
    char* procName = (char*)malloc((size_t)nameTok.length + 1);
    memcpy(procName, nameTok.start, nameTok.length);
    procName[nameTok.length] = '\0';

    if (!match_token(TOKEN_LEFT_PAREN)) {
        owl_emit_error_at(&nameTok, E_SYNTAX_EXPECTED_LPAREN_AFTER_PROC_NAME);
        free(procName);
        return;
    }

    /*  — une PROCEDURE a nom libre (helper) ne peut etre declaree
     * QU'au top-level de l'Etat. Dans un bloc/section, seuls les events
     * connus (AvantImpression, cf. catalogue sous-controle) sont admis. Tout
     * autre nom = erreur compile : deplacer le helper au niveau superieur. */
    if (owl_etat_subcontrol_event_catalog_find(procName) == NULL) {
        owl_emit_error_at(&nameTok, E_SEM_ETAT_PROC_HELPER_NOT_TOPLEVEL,
                          "name", procName, NULL);
        int parenDepth = 1;
        while (parenDepth > 0 && !check(TOKEN_EOF)) {
            if (check(TOKEN_LEFT_PAREN))  parenDepth++;
            else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
            if (parenDepth > 0) advance_token();
        }
        if (check(TOKEN_RIGHT_PAREN)) advance_token();
        window_skip_nested_block();
        free(procName);
        parser.panicMode = false;
        return;
    }

    /* Dedup : meme nom deja declare (event ou user_proc) au niveau Etat.
     * Modele plat : une PROCEDURE de bloc rejoint la meme liste que celles du
     * top-level, d'ou la meme regle de comparaison des deux cotes. */
    if (decl) {
        int procNameLen0 = (int)strlen(procName);
        bool dup = false;
        for (int i = 0; i < decl->event_count; i++) {
            if (dsl_proc_name_eq(decl->events[i].name,
                                 (int)strlen(decl->events[i].name),
                                 procName, procNameLen0)) { dup = true; break; }
        }
        if (!dup) {
            for (int i = 0; i < decl->user_proc_count; i++) {
                if (dsl_proc_name_eq(decl->user_procs[i].name,
                                     (int)strlen(decl->user_procs[i].name),
                                     procName, procNameLen0)) { dup = true; break; }
            }
        }
        if (dup) {
            owl_emit_error_at(&nameTok, E_SEM_ETAT_PROCEDURE_DUPLICATE,
                              "name", procName, NULL);
            int parenDepth = 1;
            while (parenDepth > 0 && !check(TOKEN_EOF)) {
                if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                if (parenDepth > 0) advance_token();
            }
            if (check(TOKEN_RIGHT_PAREN)) advance_token();
            dsl_skip_block_body();
            free(procName);
            parser.panicMode = false;
            return;
        }
    }

    Compiler pcompiler;
    init_compiler(&pcompiler, TYPE_FUNCTION);
    begin_scope();
    char fnNameBuf[200];
    snprintf(fnNameBuf, sizeof(fnNameBuf), "__etat_%s_%s",
             decl ? decl->name : "?", procName);
    current->function->name =
        obj_copy_string(fnNameBuf, (int)strlen(fnNameBuf));
    Value pDefaults[255];
    int pDefaultCount = 0;
    int pMinArity = 0;
    if (!check(TOKEN_RIGHT_PAREN)) {
        do {
            current->function->arity++;
            if (current->function->arity > 255) {
                owl_emit_error_current(E_SYNTAX_TOO_MANY_PARAMETERS);
                break;
            }
            if (!check(TOKEN_IDENTIFIER)) {
                owl_emit_error_current(E_SYNTAX_EXPECTED_PARAM_NAME);
                break;
            }
            advance_token();
            Token paramName = parser.previous;
            declare_variable(&paramName);
            if (match_token(TOKEN_EST)) skip_type_spec();
            if (match_token(TOKEN_EQUAL)) {
                Value v;
                if (parse_default_literal(&v)) {
                    pDefaults[pDefaultCount++] = v;
                    if (current->localCount > 0)
                        current->locals[current->localCount - 1].hasInitializer = true;
                }
            } else {
                if (pDefaultCount > 0) {
                    owl_emit_error_at(&parser.previous, E_SEM_REQUIRED_PARAM_AFTER_DEFAULT);
                }
                pMinArity = current->function->arity;
            }
        } while (match_token(TOKEN_COMMA));
    }
    consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_PARAMS);
    current->function->minArity = pMinArity;
    if (pDefaultCount > 0) {
        current->function->defaults =
            (Value*)malloc(sizeof(Value) * pDefaultCount);
        for (int di = 0; di < pDefaultCount; di++) {
            current->function->defaults[di] = pDefaults[di];
        }
        current->function->defaultCount = pDefaultCount;
    }
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) declaration();
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROCEDURE);
    ObjFunction* fn = end_compiler();

    if (decl && fn) {
        owl_etat_decl_add_user_proc(decl, procName, fn, nameTok.line);
        /* global_track au nom nu : resolution compile-time des refs externes
         * -> echec runtime "non appelable" (fermeture externe), comme les
         * procs top-level. Pas d'OP_DEFINE_GLOBAL nu (slot reste NIL). */
        int procNameLen = (int)strlen(procName);
        global_track_declare(procName, procNameLen, nameTok.line);
        global_track_mark_initialized(procName, procNameLen);
    }
    free(procName);
    parser.panicMode = false;
}

/* Compile le body d'un sub-bloc Etat. Reconnait deux types de constructions :
 *   1. 'IDENT est un Libellé ... FIN' -> declaration WYSIWYG, ajoutee dans
 *      b->controls. Imprimee au runtime par iImprimeEtat.
 *   2. autre -> code canon classique compile dans l'ObjFunction body.
 *
 * b peut etre NULL (cas de declaration Etat invalide). Dans ce cas on
 * compile quand meme pour faire avancer le parser sans cascade d'erreurs. */
static ObjFunction* etat_compile_block_body(OwlEtatDecl* decl,
                                             OwlEtatBlockDecl* b,
                                             const char* nameForFn) {
    Compiler bcompiler;
    init_compiler(&bcompiler, TYPE_FUNCTION);
    begin_scope();
    char fnNameBuf[160];
    snprintf(fnNameBuf, sizeof(fnNameBuf), "__etat_block_%s",
             nameForFn ? nameForFn : "?");
    current->function->name =
        obj_copy_string(fnNameBuf, (int)strlen(fnNameBuf));
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        /*  — PROCEDURE/FONCTION dans un bloc = proc globale de l'Etat
         * (modele plat). Compilee a part dans decl->user_procs, jamais via
         * declaration() (qui declencherait le masking sur le slot pre-reserve
         * par la pre-passe). */
        if (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION)) {
            etat_compile_block_user_proc(decl);
            continue;
        }
        /* Detection 'IDENT est un Libellé' -> declaration WYSIWYG. */
        if (check(TOKEN_IDENTIFIER)) {
            Scanner saved = parser.scanner;
            Token savedCur = parser.current;
            Token savedPrev = parser.previous;
            bool savedCrossed = crossedNewline;

            Token nameTok = parser.current;
            advance_token();
            if (check(TOKEN_EST)) {
                advance_token();
                consume_en_a_an_filler(); /*  : copule EN `is a/an` */
                /*  : prefixe 'Champ' obligatoire devant tout controle
                 * dans un bloc Etat. 'IDENT est un Champ <Genre> ... FIN' pour
                 * les 11 OwlControlKind via le chemin unifie etat_parse_block_control.
                 * "Champ" est un identifiant contextuel (pas keyword scanner —
                 * eviter le conflit avec une variable nommee 'champ'). */
                bool etatSawChamp = false;
                if (check_ident_champ()) {
                    advance_token();
                    etatSawChamp = true;
                    skip_optional_de_after_champ(); /*  */
                }
                OwlControlKind kind;
                if (detect_subfield_kind(&kind)) {
                    if (etatSawChamp) {
                        advance_token(); /* <Genre> */
                        etat_parse_block_control(b, kind, nameTok, nameTok.line);
                        continue;
                    }
                    /*  lot 1-bis : Image/Liste nu SANS corps
                     * PROPRIETES = variable/collection (le type gagne). Pas une
                     * erreur Champ : on restore et on compile comme un statement
                     * canon ordinaire (declaration() ci-dessous). scanner positionne
                     * sur le token de genre pour le peek PROPRIETES. */
                    if (owl_control_kind_is_ambiguous(kind)
                        && !peek_proprietes_follows()) {
                        parser.scanner = saved;
                        parser.current = savedCur;
                        parser.previous = savedPrev;
                        crossedNewline = savedCrossed;
                        declaration();
                        continue;
                    }
                    /* Controle nu (sans Champ) : erreur nommee. Restore au
                     * debut du statement, emet l'erreur sur l'identifiant, puis
                     * skip le body jusqu'au FIN matching (anti-cascade).
                     * Couvre les 9 genres controle-seuls (toujours) ET Image/
                     * Liste nu suivi d'un corps PROPRIETES (exception messaging). */
                    parser.scanner = saved;
                    parser.current = savedCur;
                    parser.previous = savedPrev;
                    crossedNewline = savedCrossed;
                    char cname[128];
                    int cl = nameTok.length < 127 ? nameTok.length : 127;
                    memcpy(cname, nameTok.start, (size_t)cl);
                    cname[cl] = '\0';
                    owl_emit_error_at(&nameTok, E_SEM_DSL_CHAMP_PREFIXE_REQUIS,
                                      "name", cname,
                                      "genre", owl_control_kind_name_fr(kind),
                                      NULL);
                    /* parser.current restaure sur l'IDENT (cf restore ci-dessus). */
                    window_skip_control_block();
                    parser.panicMode = false;
                    continue;
                }
            }
            /* Pas un controle DSL : restore et compile comme statement canon. */
            parser.scanner = saved;
            parser.current = savedCur;
            parser.previous = savedPrev;
            crossedNewline = savedCrossed;
        }
        declaration();
    }
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_ETAT_BLOCK);
    return end_compiler();
}

/* Parse une init de propriete simple `IDENT = literal` dans un sub-bloc
 * Etat (ex: Hauteur = 40). Validation contre PROPS_ETAT_BLOCK. */
static void etat_block_parse_property_init(OwlEtatBlockDecl* b) {
    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_PROP_NAME_ETAT_BLOCK);
        advance_token();
        return;
    }
    Token propTok = parser.current;
    advance_token();

    /*  : cascade declarative `Prop..SousChamp = valeur` au niveau
     * bloc d'Etat. Symetrique de window_parse_property_init : lookup catalogue,
     * reservee aux props composees (OBJECT). */
    if (check(TOKEN_DOUBLE_DOT)) {
        char propAsciiB[128];
        int pl = scanner_strip_accents(propTok.start, propTok.length,
                                       propAsciiB, sizeof(propAsciiB));
        if (pl <= 0) pl = propTok.length < 127 ? propTok.length : 127;
        propAsciiB[pl] = '\0';
        const OwlControlPropDef* bdef = owl_etat_block_catalog_find(propAsciiB);
        if (!bdef) {
            owl_emit_error_at(&propTok, E_SEM_ETAT_PROP_UNKNOWN_BLOCK,
                              "prop", propAsciiB, NULL);
            window_skip_to_next_stmt();
            return;
        }
        if (bdef->type != OWL_PROP_TYPE_OBJECT || !bdef->object_type) {
            owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
            window_skip_to_next_stmt();
            return;
        }
        /* Invariant : g_cascade_buffer est toujours actif ici. Toute prop DSL
         * (donc toute cascade `..`) est parsee dans un bloc PROPRIETES qui ouvre
         * ce buffer ; il n'existe pas de chemin d'entree hors buffer. La cascade
         * est bufferisee pour regroupement compile-time des cascades homonymes. */
        cascade_buffer_capture(g_cascade_buffer, propTok,
                               propAsciiB, pl,
                               bdef->object_type,
                               (int)strlen(bdef->object_type), NULL);
        return;
    }

    if (!match_token(TOKEN_EQUAL)) {
        owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
        return;
    }
    if (dsl_prop_value_missing_reported(&propTok)) return;
    char propName[128];
    int n = scanner_strip_accents(propTok.start, propTok.length, propName, sizeof(propName));
    if (n <= 0) n = propTok.length < 127 ? propTok.length : 127;
    propName[n] = '\0';
    /* Validation : nom de propriete doit etre dans le catalogue. */
    const OwlControlPropDef* def = owl_etat_block_catalog_find(propName);
    if (!def) {
        owl_emit_error_at(&propTok, E_SEM_ETAT_PROP_UNKNOWN_BLOCK,
                          "prop", propName,
                          NULL);
        window_skip_to_next_stmt();
        return;
    }
    Value v;
    int line = propTok.line;
    if (window_try_parse_const_literal(&v)) {
        if (b) owl_etat_block_decl_add_property(b, propName, v, NULL, true, line);
    } else {
        owl_emit_warning_at(&propTok, W_SEM_PROP_DYNAMIC_NOT_SUPPORTED,
            "prop", propName,
            NULL);
        window_skip_to_next_stmt();
    }
}

/* Parse une init de propriete au niveau Etat top-level. Validation contre
 * PROPS_ETAT (Format/Orientation/Marges). */
static void etat_parse_property_init(OwlEtatDecl* decl) {
    if (!check(TOKEN_IDENTIFIER)) {
        owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_PROP_NAME_ETAT_BODY);
        advance_token();
        return;
    }
    Token propTok = parser.current;
    advance_token();

    /*  : cascade declarative `Prop..SousChamp = valeur` au niveau
     * Etat top-level. Symetrique de window_parse_property_init : lookup
     * catalogue, reservee aux props composees (OBJECT). */
    if (check(TOKEN_DOUBLE_DOT)) {
        char propAsciiE[128];
        int pl = scanner_strip_accents(propTok.start, propTok.length,
                                       propAsciiE, sizeof(propAsciiE));
        if (pl <= 0) pl = propTok.length < 127 ? propTok.length : 127;
        propAsciiE[pl] = '\0';
        const OwlControlPropDef* edef = owl_etat_catalog_find(propAsciiE);
        if (!edef) {
            owl_emit_error_at(&propTok, E_SEM_ETAT_PROP_UNKNOWN_TOPLEVEL,
                              "prop", propAsciiE, NULL);
            window_skip_to_next_stmt();
            return;
        }
        if (edef->type != OWL_PROP_TYPE_OBJECT || !edef->object_type) {
            owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
            window_skip_to_next_stmt();
            return;
        }
        /* Invariant : g_cascade_buffer est toujours actif ici. Toute prop DSL
         * (donc toute cascade `..`) est parsee dans un bloc PROPRIETES qui ouvre
         * ce buffer ; il n'existe pas de chemin d'entree hors buffer. La cascade
         * est bufferisee pour regroupement compile-time des cascades homonymes. */
        cascade_buffer_capture(g_cascade_buffer, propTok,
                               propAsciiE, pl,
                               edef->object_type,
                               (int)strlen(edef->object_type), NULL);
        return;
    }

    if (!match_token(TOKEN_EQUAL)) {
        owl_emit_error_at(&propTok, E_SYNTAX_EXPECTED_EQUAL_AFTER_PROP);
        return;
    }
    if (dsl_prop_value_missing_reported(&propTok)) return;
    char propName[128];
    int n = scanner_strip_accents(propTok.start, propTok.length, propName, sizeof(propName));
    if (n <= 0) n = propTok.length < 127 ? propTok.length : 127;
    propName[n] = '\0';
    /* Validation : nom de propriete doit etre dans le catalogue. */
    const OwlControlPropDef* def = owl_etat_catalog_find(propName);
    if (!def) {
        owl_emit_error_at(&propTok, E_SEM_ETAT_PROP_UNKNOWN_TOPLEVEL,
                          "prop", propName,
                          NULL);
        window_skip_to_next_stmt();
        return;
    }
    Value v;
    int line = propTok.line;
    if (window_try_parse_const_literal(&v)) {
        if (decl) owl_etat_decl_add_property(decl, propName, v, NULL, true, line);
    } else {
        owl_emit_warning_at(&propTok, W_SEM_PROP_DYNAMIC_NOT_SUPPORTED,
            "prop", propName,
            NULL);
        window_skip_to_next_stmt();
    }
}

/* Parse un sub-bloc Etat: '<NOM> est un <TypeBloc> [PROPRIETES ... FIN] <body> FIN'.
 * Le caller a deja consomme `<NOM> est un <TypeBlocTok>`. blockKindName est
 * le nom du token suivant l'IDENT du nom de sub-bloc. */
static void etat_parse_subblock(OwlEtatDecl* decl, Token nameTok,
                                  const char* blockKindName, int line) {
    int kindInt = owl_etat_block_kind_from_name(blockKindName);
    if (kindInt < 0) {
        owl_emit_error_at(&nameTok, E_SEM_ETAT_BLOCK_KIND_UNKNOWN,
                          "kind", blockKindName,
                          NULL);
        return;
    }
    OwlEtatBlockKind kind = (OwlEtatBlockKind)kindInt;

    char nameBuf[128];
    int nlen = nameTok.length < 127 ? nameTok.length : 127;
    memcpy(nameBuf, nameTok.start, nlen);
    nameBuf[nlen] = '\0';

    /* Compile-time : un seul bloc canon de chaque type max.
     * Iteration : exempté — autant de blocs que voulu, mais avec des noms
     * differents (pour que iImprimeBloc("nom") puisse les distinguer). */
    bool dup = false;
    bool dupIsCanon = false;
    if (decl) {
        if (kind != OWL_ETAT_BLOCK_ITERATION &&
            owl_etat_decl_find_canon_block(decl, kind) != NULL) {
            dupIsCanon = true;
            dup = true;
        } else if (owl_etat_decl_find_block_by_name(decl, nameBuf) != NULL) {
            dup = true;
        }
    }
    if (dup) {
        if (dupIsCanon) {
            owl_emit_error_at(&nameTok, E_SEM_ETAT_BLOCK_CANON_DUPLICATE,
                              "kind", blockKindName,
                              NULL);
        } else {
            owl_emit_error_at(&nameTok, E_SEM_ETAT_BLOCK_NAME_DUPLICATE,
                              "name", nameBuf,
                              NULL);
        }
        /* Skip body. */
        dsl_skip_block_body();
        return;
    }

    OwlEtatBlockDecl* b = decl ? owl_etat_decl_add_block(decl, kind, nameBuf, line) : NULL;

    /* Eat NEWLINE après l'entête. */
    while (check(TOKEN_NEWLINE)) advance_token();

    /* PROPRIETES optionnel en début de body. */
    if (check(TOKEN_PROPRIETES)) {
        advance_token();
        /*  : buffer cascade actif pendant la duree du bloc PROPRIETES
         * pour regrouper les cascades homonymes en un seul eval. */
        CascadeBuffer blkCascadeBuf;
        cascade_buffer_init(&blkCascadeBuf);
        CascadeBuffer* savedCascadeBufBlk = g_cascade_buffer;
        g_cascade_buffer = &blkCascadeBuf;
        while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
            while (check(TOKEN_NEWLINE)) advance_token();
            if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
            etat_block_parse_property_init(b);
        }
        g_cascade_buffer = savedCascadeBufBlk;
        cascade_buffer_flush(&blkCascadeBuf, CASCADE_FLUSH_ETAT_BLOCK, b,
                              "__etat_block_prop");
        cascade_buffer_free(&blkCascadeBuf);
        consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROPRIETES_ETAT_SUB);
        while (check(TOKEN_NEWLINE)) advance_token();
    }

    /* Compile le body code en ObjFunction + collecte les controls WYSIWYG. */
    ObjFunction* body = etat_compile_block_body(decl, b, nameBuf);
    if (b) b->body = body;
}

/* Parse: ETA_X est un Etat ... FIN. Le caller a deja consomme 'IDENT est un Etat'. */
static void etat_declaration(Token etatName, int line) {
    /*  — marque le scope Etat actif pour toute la duree du parse
     * de ce block (top-level + sub-blocs + PROCEDUREs internes). Le
     * verrou compile-time sur Ouvre/OuvreFille/OuvreSoeur consulte cette
     * profondeur dans call(). Depth (vs bool) par cohérence si un jour
     * un Etat se retrouvait imbrique — improbable mais pas cher. */
    g_in_etat_scope_depth++;

    /*  — contexte element courant (nom de l'etat, forme tapee). Sert
     * au mangling `<ELEM>$<var>` des globales top-level de l'etat (portee
     * scopee a l'element, ). Restaure en fin de parse de l'etat. */
    char savedElementNameEtat[64];
    memcpy(savedElementNameEtat, g_current_element_name,
           sizeof(savedElementNameEtat));
    {
        int en = etatName.length < (int)sizeof(g_current_element_name) - 1
                 ? etatName.length : (int)sizeof(g_current_element_name) - 1;
        memcpy(g_current_element_name, etatName.start, (size_t)en);
        g_current_element_name[en] = '\0';
    }
    /*  — corps d'Etat = nouveau contexte top-level : mode GLOBAL. */
    bool savedConfineEtat = g_toplevel_confine;
    g_toplevel_confine = false;

    /* Garde-fou : un fichier ne peut pas mixer Classe + Etat (convention
     * OWL "1 classe = 1 fichier"). */
    bool mixed = false;
    if (g_file_first_class_line > 0) {
        char classNameBuf[128], lineBuf[16];
        snprintf(classNameBuf, sizeof(classNameBuf), "%.*s",
                 g_file_first_class_name_len, g_file_first_class_name);
        snprintf(lineBuf, sizeof(lineBuf), "%d", g_file_first_class_line);
        owl_emit_error_at(&etatName, E_SEM_ETAT_FILE_AND_CLASS,
                          "name", classNameBuf,
                          "line", lineBuf,
                          NULL);
        mixed = true;
    }
    /* Garde-fou : un fichier ne peut pas mixer Fenetre + Etat. Si un mix
     * est detecte, on saute aussi le check 'Corps obligatoire' a la fin
     * pour ne pas spammer l'utilisateur avec une 2eme erreur quand le vrai
     * probleme est la cohabitation des deux types. */
    if (g_file_first_window_line > 0) {
        char lineBuf[16];
        snprintf(lineBuf, sizeof(lineBuf), "%d", g_file_first_window_line);
        owl_emit_error_at(&etatName, E_SEM_ETAT_FILE_AND_WINDOW,
                          "line", lineBuf,
                          NULL);
        mixed = true;
    }
    if (g_file_first_etat_line == 0) g_file_first_etat_line = line;

    char* nameBuf = (char*)malloc((size_t)etatName.length + 1);
    memcpy(nameBuf, etatName.start, etatName.length);
    nameBuf[etatName.length] = '\0';
    /* On garde un nameBuf2 pour pouvoir l'utiliser plus loin (ouverture
     * compiler name). Le nameBuf principal est libere apres la lookup. */
    char* etatNameForFn = (char*)malloc((size_t)etatName.length + 1);
    memcpy(etatNameForFn, etatName.start, etatName.length);
    etatNameForFn[etatName.length] = '\0';

    OwlEtatDecl* decl = NULL;
    /*  — doublon de nom d'element cross-fichier (tous types confondus),
     * signale de facon deterministe par le check unifie
     * (E_SEM_ELEMENT_NAME_DUPLICATE). On reutilise la decl du 1er fichier pour
     * parser le corps sans cascade (decl==NULL casserait le parse des PROPRIETES
     * et produirait les 3 erreurs en cascade de l'ancien chemin vm_etat_lookup).
     * Le repli vm_etat_lookup ne sert plus qu'en l'absence de contexte projet. */
    bool projectElementDup = (projectSymbols != NULL)
        && symtable_element_has_earlier_dup(projectSymbols,
               etatName.start, etatName.length, currentFileIndex);
    if (projectElementDup) {
        /* decl jetable (non enregistree) : parse du corps propre, pas de cascade. */
        decl = owl_etat_decl_new(nameBuf, line);
    } else if (vm_etat_lookup(nameBuf) != NULL) {
        owl_emit_error_at(&etatName, E_SEM_ETAT_DUPLICATE,
                          "name", nameBuf,
                          NULL);
    } else {
        decl = owl_etat_decl_new(nameBuf, line);
        if (!vm_etat_register(decl)) {
            owl_etat_decl_free(decl);
            decl = NULL;
            owl_emit_error_at(&parser.previous, E_SEM_INTERNAL_ETAT_REGISTER_FAILED);
        }
    }
    free(nameBuf);

    /* Parametres optionnels : 'est un Etat(<param1> [est un <type1>], ...)'.
     * Les params sont accessibles comme globales dans tout le scope de
     * l'Etat (top-level + sub-blocs + PROCEDUREs). Au runtime
     * iImprimeEtat(MonEtat, val1, val2, ...) injecte les valeurs avant
     * d'executer le code. */
    if (match_token(TOKEN_LEFT_PAREN)) {
        bool sawDefault = false;
        if (!check(TOKEN_RIGHT_PAREN)) {
            do {
                if (!check(TOKEN_IDENTIFIER)) {
                    owl_emit_error_current(E_SYNTAX_EXPECTED_PARAM_NAME_ETAT);
                    break;
                }
                Token paramTok = parser.current;
                advance_token();
                char paramName[128];
                int plen = paramTok.length < 127 ? paramTok.length : 127;
                memcpy(paramName, paramTok.start, plen);
                paramName[plen] = '\0';

                /* Type optionnel : 'est un <Type>'. 'un'/'une' sont des
                 * filler words consommes par le scanner — on ne voit que EST
                 * puis directement le type token. */
                char typeNameBuf[128] = "";
                bool hasType = false;
                if (match_token(TOKEN_EST)) {
                    /* Capture le nom du type (premier token apres EST). */
                    Token typTok = parser.current;
                    int tlen = typTok.length < 127 ? typTok.length : 127;
                    memcpy(typeNameBuf, typTok.start, tlen);
                    typeNameBuf[tlen] = '\0';
                    hasType = (tlen > 0);
                    skip_type_spec();
                }

                /* Valeur par defaut optionnelle : `= <litteral>`. Parite stricte
                 * avec les params de fenetre / PROCEDURE. Un param
                 * requis ne peut pas suivre un param a valeur par defaut. */
                Value defaultVal = NIL_VAL;
                bool hasDefault = false;
                if (match_token(TOKEN_EQUAL)) {
                    if (parse_default_literal(&defaultVal)) {
                        hasDefault = true;
                        sawDefault = true;
                    }
                } else if (sawDefault) {
                    owl_emit_error_at(&parser.previous, E_SEM_REQUIRED_PARAM_AFTER_DEFAULT);
                    /* Erreur SEMANTIQUE : flux de tokens synchronise (param
                     * consomme proprement). Desactive le panic mode pour que
                     * le body de l'Etat parse sans cascade parasite. */
                    parser.panicMode = false;
                }

                if (decl) {
                    owl_etat_decl_add_param(decl, paramName,
                                              hasType ? typeNameBuf : NULL,
                                              defaultVal, hasDefault,
                                              paramTok.line);
                    /* Expose le nom comme global string pour que le
                     * compile-time validation accepte les references depuis
                     * les sub-blocs et PROCEDUREs internes. La vraie valeur
                     * sera injectee par iImprimeEtat au runtime (V2.1+).
                     *  : delegue au canon obj_globals_set. */
                    obj_globals_set(paramName, NIL_VAL);
                }
            } while (match_token(TOKEN_COMMA));
        }
        consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_ETAT_PARAMS);
    }

    /*  : pre-passe ordre-independant. Scanne le body du bloc Etat
     * pour pre-enregistrer les PROCEDURE custom (alias DSL inutile en Etat
     * mais global track + slot vm.globals indispensables pour la resolution
     * de '<proc>(...)' avant sa declaration). Rewind du scanner au DEBUT
     * de parser.current (cf. window_declaration pour le rationale).
     *
     * Env var OWL_DISABLE_PREPASS=1 desactive la pre-passe (benchmark). */
    /*  — scope DSL alias propre a l'Etat (parite fenetre). Les alias
     * bare->qualifie `<proc>`->`<etat>_<proc>` poses par la pre-passe et la
     * compilation des procs ne doivent vivre QUE le temps du parse de l'Etat :
     * pop a la sortie => un script/fenetre voisin ne peut pas reformer le nom
     * qualifie d'une proc d'Etat (fermeture externe). */
    dsl_aliases_push_scope();

    if (decl != NULL && getenv("OWL_DISABLE_PREPASS") == NULL) {
        Scanner pre = parser.scanner;
        if (parser.current.start != NULL) {
            pre.current = parser.current.start;
            pre.start   = parser.current.start;
            pre.line    = parser.current.line;
            pre.column  = parser.current.column;
            pre.startColumn = parser.current.column;
            pre.atLineStart = false;
        }
        prepass_block_collect_procs(pre, decl->name, /*isEtat=*/true);
    }

    /* Init compiler "Ouverture" : tout statement orphelin (pas PROPRIETES,
     * pas sub-bloc, pas PROCEDURE) est compile dans cette ObjFunction
     * implicite. Equivalent du bloc Ouverture canon.
     *
     *  — pas de begin_scope() : symetrique stricte de la Fenetre
     * (winTopCompiler), pour que les variables declarees au top-level de
     * l'Etat (`nTotal est un entier = 0`) soient des GLOBALES visibles
     * depuis les PROCEDURE top-level du fichier-etat (helpers globaux du
     * contexte etat). Sans ca, ces vars seraient des locals de la fn
     * Ouverture, invisibles ailleurs. */
    Compiler ouvCompiler;
    init_compiler(&ouvCompiler, TYPE_FUNCTION);
    char ouvFnName[200];
    snprintf(ouvFnName, sizeof(ouvFnName), "__etat_%s_Ouverture", etatNameForFn);
    current->function->name =
        obj_copy_string(ouvFnName, (int)strlen(ouvFnName));

    bool propertiesBlockSeen = false;
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        if (parser.panicMode) {
            while (!check(TOKEN_NEWLINE) && !check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                advance_token();
            }
            parser.panicMode = false;
        }
        while (check(TOKEN_NEWLINE)) advance_token();
        if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;

        /* PROPRIETES { ... } FIN */
        if (check(TOKEN_PROPRIETES)) {
            Token propTok = parser.current;
            advance_token();
            if (propertiesBlockSeen) {
                owl_emit_error_at(&propTok, E_SYNTAX_DUPLICATE_PROPRIETES_ETAT);
            }
            propertiesBlockSeen = true;
            /*  : buffer cascade actif pendant la duree du bloc PROPRIETES
             * pour regrouper les cascades homonymes en un seul eval. */
            CascadeBuffer topCascadeBuf;
            cascade_buffer_init(&topCascadeBuf);
            CascadeBuffer* savedCascadeBufTop = g_cascade_buffer;
            g_cascade_buffer = &topCascadeBuf;
            /*  : garde anti-hang (cf ). Meme classe que la
             * boucle PROPRIETES Fenetre : un sous-champ declare dans le bloc
             * gare window_skip_to_next_stmt() sur un keyword non consommable. */
            const char* lastPropPosEtat = NULL;
            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
                while (check(TOKEN_NEWLINE)) advance_token();
                if (check(TOKEN_FIN) || check(TOKEN_EOF)) break;
                if (parser.current.start == lastPropPosEtat) {
                    advance_token();
                    parser.panicMode = false;
                    continue;
                }
                lastPropPosEtat = parser.current.start;
                if (!check(TOKEN_IDENTIFIER)) {
                    owl_emit_error_current(E_SYNTAX_ETAT_PROPRIETES_EXPECTED_PROP_NAME);
                    window_skip_to_next_stmt();
                    continue;
                }
                etat_parse_property_init(decl);
            }
            g_cascade_buffer = savedCascadeBufTop;
            cascade_buffer_flush(&topCascadeBuf, CASCADE_FLUSH_ETAT_TOP, decl,
                                  "__etat_prop");
            cascade_buffer_free(&topCascadeBuf);
            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROPRIETES);
            continue;
        }

        /* PROCEDURE Fermeture/custom (le code d'init vit dans le top-level) */
        if (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION)) {
            advance_token();
            if (!check(TOKEN_IDENTIFIER)) {
                owl_emit_error_current(E_SYNTAX_EXPECTED_PROC_NAME_AFTER_PROC);
                continue;
            }
            Token nameTok = parser.current;
            advance_token();
            char* procName = (char*)malloc((size_t)nameTok.length + 1);
            memcpy(procName, nameTok.start, nameTok.length);
            procName[nameTok.length] = '\0';

            if (!match_token(TOKEN_LEFT_PAREN)) {
                owl_emit_error_at(&nameTok, E_SYNTAX_EXPECTED_LPAREN_AFTER_PROC_NAME);
                free(procName);
                continue;
            }

            /*  — l'event 'Initialisation' n'existe plus (Etat inclus) :
             * le code d'init vit dans le top-level (Ouverture implicite). */
            if (window_ci_eq(procName, "Initialisation")
                || window_ci_eq(procName, "Initialization")) {
                owl_emit_error_at(&nameTok, E_SEM_DSL_INITIALISATION_OBSOLETE, NULL);
                while (!check(TOKEN_RIGHT_PAREN) && !check(TOKEN_EOF)) advance_token();
                if (check(TOKEN_RIGHT_PAREN)) advance_token();
                dsl_skip_block_body();
                free(procName);
                parser.panicMode = false;
                continue;
            }

            /* Si nom == nom Etat, c'est la capture des paramètres
             * (PROCEDURE ETA_X(p1, p2)). Sinon Initialisation/Fermeture/custom. */
            bool isCaptureParams = decl && decl->name &&
                                   strcmp(decl->name, procName) == 0;

            /* Detection doublon : event ou user_proc deja declare au niveau
             * Etat. Capture parametres traitee separement (peut etre une seule
             * fois aussi, check via decl->param_capture). */
            if (decl && !isCaptureParams) {
                int procNameLen0 = (int)strlen(procName);
                bool dup = false;
                for (int i = 0; i < decl->event_count; i++) {
                    if (dsl_proc_name_eq(decl->events[i].name,
                                         (int)strlen(decl->events[i].name),
                                         procName, procNameLen0)) { dup = true; break; }
                }
                if (!dup) {
                    for (int i = 0; i < decl->user_proc_count; i++) {
                        if (dsl_proc_name_eq(decl->user_procs[i].name,
                                             (int)strlen(decl->user_procs[i].name),
                                             procName, procNameLen0)) { dup = true; break; }
                    }
                }
                if (dup) {
                    owl_emit_error_at(&nameTok, E_SEM_ETAT_PROCEDURE_DUPLICATE,
                                      "name", procName,
                                      NULL);
                    /* Skip jusqu'au FIN de la procedure pour eviter la cascade. */
                    int parenDepth = 1;
                    while (parenDepth > 0 && !check(TOKEN_EOF)) {
                        if (check(TOKEN_LEFT_PAREN))  parenDepth++;
                        else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                        if (parenDepth > 0) advance_token();
                    }
                    if (check(TOKEN_RIGHT_PAREN)) advance_token();
                    dsl_skip_block_body();
                    free(procName);
                    parser.panicMode = false;
                    continue;
                }
            }

            Compiler bcompiler;
            init_compiler(&bcompiler, TYPE_FUNCTION);
            begin_scope();
            char fnNameBuf[200];
            snprintf(fnNameBuf, sizeof(fnNameBuf), "__etat_%s_%s",
                     decl ? decl->name : "?", procName);
            current->function->name =
                obj_copy_string(fnNameBuf, (int)strlen(fnNameBuf));
            Value etatDefaults[255];
            int etatDefaultCount = 0;
            int etatMinArity = 0;
            if (!check(TOKEN_RIGHT_PAREN)) {
                do {
                    current->function->arity++;
                    if (current->function->arity > 255) {
                        owl_emit_error_current(E_SYNTAX_TOO_MANY_PARAMETERS);
                        break;
                    }
                    if (!check(TOKEN_IDENTIFIER)) {
                        owl_emit_error_current(E_SYNTAX_EXPECTED_PARAM_NAME);
                        break;
                    }
                    advance_token();
                    Token paramName = parser.previous;
                    declare_variable(&paramName);
                    if (match_token(TOKEN_EST)) skip_type_spec();
                    /* Optional default value: "= <literal>". Once a param has a
                     * default, all subsequent params must also have one
                     * (parity rule). */
                    if (match_token(TOKEN_EQUAL)) {
                        Value v;
                        if (parse_default_literal(&v)) {
                            etatDefaults[etatDefaultCount++] = v;
                            if (current->localCount > 0)
                                current->locals[current->localCount - 1].hasInitializer = true;
                        }
                    } else {
                        if (etatDefaultCount > 0) {
                            owl_emit_error_at(&parser.previous, E_SEM_REQUIRED_PARAM_AFTER_DEFAULT);
                        }
                        etatMinArity = current->function->arity;
                    }
                } while (match_token(TOKEN_COMMA));
            }
            consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_PARAMS);
            current->function->minArity = etatMinArity;
            if (etatDefaultCount > 0) {
                current->function->defaults =
                    (Value*)malloc(sizeof(Value) * etatDefaultCount);
                for (int di = 0; di < etatDefaultCount; di++) {
                    current->function->defaults[di] = etatDefaults[di];
                }
                current->function->defaultCount = etatDefaultCount;
            }
            while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) declaration();
            consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_PROCEDURE);
            ObjFunction* fn = end_compiler();

            if (decl) {
                if (isCaptureParams) {
                    decl->param_capture = fn;
                } else {
                    /* Events Etat canon : Filtre/Lecture/Fermeture top-level.
                     * Tout autre nom = user_proc (procedure custom). */
                    bool isCanonEvent =
                        strcasecmp(procName, "Filtre") == 0 ||
                        strcasecmp(procName, "Filter") == 0 ||
                        strcasecmp(procName, "Lecture") == 0 ||
                        strcasecmp(procName, "Read") == 0 ||
                        strcasecmp(procName, "Fermeture") == 0 ||
                        strcasecmp(procName, "Closing") == 0;
                    if (isCanonEvent) {
                        owl_etat_decl_add_event(decl, procName, fn, nameTok.line);
                    } else {
                        owl_etat_decl_add_user_proc(decl, procName, fn, nameTok.line);
                        /*  — modele plat + fermeture externe : la proc
                         * d'Etat devient une globale de l'Etat liee au runtime
                         * sous son nom QUALIFIE `<etat>_<proc>` (cf iImprimeEtat),
                         * resolue intra-Etat via l'alias DSL scope. On NE definit
                         * PLUS de globale au nom NU : sinon un script/fenetre
                         * voisin pourrait l'appeler par nom nu apres impression
                         * (le top-level Ouverture l'aurait definie), cassant la
                         * fermeture externe. Le slot nu reste reserve a NIL par
                         * la pre-passe ; global_track garde la resolution
                         * compile-time pour que tout appel externe echoue au
                         * runtime ("non appelable", capturable) plutot qu'en
                         * "fonction inconnue" non capturable. */
                        int procNameLen = (int)strlen(procName);
                        global_track_declare(procName, procNameLen,
                                              nameTok.line);
                        global_track_mark_initialized(procName, procNameLen);
                    }
                }
            }
            free(procName);
            parser.panicMode = false;
            continue;
        }

        /* Sub-bloc : <NOM> est un <TypeBloc> ... FIN */
        if (check(TOKEN_IDENTIFIER)) {
            Scanner saved = parser.scanner;
            Token savedCur = parser.current;
            Token savedPrev = parser.previous;
            bool savedCrossed = crossedNewline;

            Token nameTok = parser.current;
            advance_token();
            if (check(TOKEN_EST)) {
                advance_token();
                /*  — copule EN `is a/an <BlockType>` : saute l'article. */
                consume_en_a_an_filler();
                if (check(TOKEN_IDENTIFIER)) {
                    /* Le type-de-bloc est un IDENTIFIER (EnTeteDocument, Corps, ...). */
                    Token kindTok = parser.current;
                    char kindBuf[64];
                    int klen = kindTok.length < 63 ? kindTok.length : 63;
                    memcpy(kindBuf, kindTok.start, klen);
                    kindBuf[klen] = '\0';
                    if (owl_etat_block_kind_from_name(kindBuf) >= 0) {
                        advance_token(); /* consume kind */
                        etat_parse_subblock(decl, nameTok, kindBuf, nameTok.line);
                        continue;
                    }
                }
                /*  — type user interne a l'Etat (`stInfo est une
                 * Structure`, énum, combinaison) : DECLARATIF STATIQUE
                 * referencable QUALIFIE de l'exterieur (`ETAT_X.stInfo`).
                 * Symetrique du dispatch fenetre : mangle `<ELEM>$<Type>`
                 * (slot distinct), enregistre le membre-type QUALIFIE-ONLY
                 * (exposed=false), et route le bytecode vers le compiler
                 * ENCLOSING (main script, materialisé a l'init) et NON vers
                 * ouvCompiler qui ne tourne qu'a la 1re impression. */
                if (check(TOKEN_ENUMERATION) || check(TOKEN_STRUCTURE)
                    || check(TOKEN_COMBINAISON)) {
                    TokenType etatUserTok = parser.current.type;
                    advance_token(); /* consume keyword */
                    Token declTok = nameTok;
                    char etatTypeMangle[128];
                    if (g_current_element_name[0] != '\0') {
                        int pn = element_var_prefix(g_current_element_name,
                                                    nameTok.start, nameTok.length,
                                                    etatTypeMangle, sizeof(etatTypeMangle));
                        if (pn > 0) {
                            collection_member_register(g_current_element_name,
                                (int)strlen(g_current_element_name),
                                nameTok.start, nameTok.length, /*exposed=*/false);
                            declTok.start  = etatTypeMangle;
                            declTok.length = pn;
                        }
                    }
                    Compiler* savedCurEtat = current;
                    current = current->enclosing;   /* -> main script (init) */
                    if      (etatUserTok == TOKEN_ENUMERATION) enum_declaration(declTok);
                    else if (etatUserTok == TOKEN_STRUCTURE)   struct_declaration(declTok);
                    else                                       combination_declaration(declTok);
                    current = savedCurEtat;         /* -> ouvCompiler */
                    continue;
                }
            }
            /* Pas un sub-bloc : c'est un statement top-level (ex: 'iImprime(...)',
             * 'monVar = 5', etc.). Restore et delegue a declaration() qui
             * compile dans le current = ouvCompiler (Ouverture implicite). */
            parser.scanner = saved;
            parser.current = savedCur;
            parser.previous = savedPrev;
            crossedNewline = savedCrossed;
            /*  : reprise d'erreur uniforme avec le top-level. */
            bool savedDslBodyStmtId = g_in_dsl_body_stmt;
            g_in_dsl_body_stmt = true;
            declaration();
            g_in_dsl_body_stmt = savedDslBodyStmtId;
            continue;
        }

        /* Statement non-IDENTIFIER (SI, POUR, TANTQUE, SELON, ...) : c'est
         * du code top-level Etat = Ouverture. Compile via declaration(). */
        /*  : reprise d'erreur uniforme avec le top-level. */
        bool savedDslBodyStmt = g_in_dsl_body_stmt;
        g_in_dsl_body_stmt = true;
        declaration();
        g_in_dsl_body_stmt = savedDslBodyStmt;
    }

    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_ETAT);

    /* Garde-fou : un Etat doit imperativement contenir un bloc Corps.
     * Le Corps porte la donnee a imprimer (1 fois par enregistrement) ;
     * sans lui, l'Etat n'a aucun sens. C'est aussi ce que demande l'editeur
     * visuel pour ne jamais permettre a l'utilisateur de supprimer le bloc.
     * En cas de mix Fenetre/Etat detecte plus haut, le parse de l'Etat est
     * deja casse (panic mode peut sauter des sub-blocs), inutile d'ajouter
     * une 2eme erreur — l'erreur de mix suffit. */
    if (!mixed && decl != NULL && owl_etat_decl_find_canon_block(decl, OWL_ETAT_BLOCK_CORPS) == NULL) {
        owl_emit_error_at(&etatName, E_SEM_ETAT_BODY_NEEDS_CORPS,
                          "name", decl->name,
                          NULL);
    }

    /* Finalize le compiler Ouverture (code top-level de l'Etat = decls
     * + statements orphelins, semantique pseudo-event "Ouverture"). */
    ObjFunction* ouv_fn = end_compiler();

    /*  — modele d'execution : l'Etat est ENDORMI jusqu'a la 1re
     * impression (symetrie stricte avec la Fenetre, ). Le top-level
     * (code d'init, equivalent Ouverture canon) n'est PLUS auto-call de maniere
     * eager dans le chunk principal (vestige ). On le stocke sur le
     * decl ; iImprimeEtat l'execute UNE seule fois (decl->top_level_done) a
     * la 1re impression, avant les sous-blocs (Corps/Filtre/Lecture...).
     *
     * NUANCE vs Fenetre : la fenetre re-execute son top-level a chaque Ouvre
     * (nouvelle instance) ; l'Etat n'init qu'UNE fois pour toute la vie du
     * process, meme si imprime N fois (contrat dev : init UNIQUE, pas de
     * re-fire par iImprimeEtat — cf test_init_une_fois_pas_par_impression et
     * etat_lifecycle_top_level/test_ordre_execution_etat_headless.owl).
     *
     * L'eager historique faisait tourner le top-level d'un Etat voisin jamais
     * imprime au lancement d'un script (bug ). La VISIBILITE
     * COMPILE-TIME des globales top-level Etat est preservee independamment :
     * elle vient des global_track_declare emis pendant declaration() ci-dessus
     * (et de hydrate_globals_from_neighbors cote cross-fichier), pas d'un appel
     * runtime au boot. */
    if (decl && ouv_fn && ouv_fn->chunk && ouv_fn->chunk->count > 1) {
        decl->top_level = ouv_fn;
    }

    free(etatNameForFn);
    parser.panicMode = false;

    /*  — ferme le scope DSL alias de l'Etat (cf push avant la
     * pre-passe). Les alias bare->qualifie des procs d'Etat sont oublies. */
    dsl_aliases_pop_scope();

    /*  — sort du scope Etat. */
    if (g_in_etat_scope_depth > 0) g_in_etat_scope_depth--;
    /*  — restore le contexte element courant. */
    memcpy(g_current_element_name, savedElementNameEtat,
           sizeof(g_current_element_name));
    g_toplevel_confine = savedConfineEtat;  /*  */
}

/* Parse: stName est une Structure ... FIN */
static void struct_declaration(Token structName) {
    /*  — structure declaree dans une CollectionDeProcédures : membre-type
     * EXPOSE. Miroir exact du traitement énum/combinaison : IDENTITÉ
     * DE TYPE NUE (register_user_type_kind + champs + tag template sous le nom nu
     * `stPoint`) pour que `p est un stPoint` et le dot-check résolvent quel que
     * soit le chemin ; SLOT template GLOBAL mangled `<COL>$<Struct>` distinct par
     * collection (deux `stForme` = deux templates, case_071) + alias NU (dernier
     * gagnant, l'accès qualifié passe par les slots mangled). Le dispatch
     * TOKEN_STRUCTURE se fait au niveau statement (court-circuit de
     * var_declaration_after_est) : on mangle donc ICI, pas via le peek collection.
     * L'enregistrement membre cote define double celui de hydrate (cross-fichier).
     * Hors collection : g_current_collection_name vide -> slotName == structName. */
    Token slotName = structName;   /* slot template runtime (mangled si collection/element) */
    Token idName   = structName;   /* identité NUE du type (tag, champs, alias nu) */
    char structMangleBuf[128];
    bool inCollection = false;
    /*  — structure interne d'une Fenetre/Etat : arrive DEJA manglée
     * `<ELEM>$<Struct>` (mangle pose par le routing du body element, cf. le
     * dispatch isUserType dans window_declaration / etat body). Miroir du
     * traitement énum/combinaison : IDENTITÉ NUE (idName = partie après `$`)
     * pour le tag + les champs + l'alias nu, SLOT template GLOBAL mangled
     * (distinct par element, deux `stConf` de deux fenetres ne se confondent
     * pas) + alias nu. Le membre-type est enregistré QUALIFIE-ONLY (exposed=
     * false) par le routing/hydrate — l'accès nu depuis l'exterieur ne resout
     * pas, seul `FEN_X.stConf` le fait. */
    const char* elemDollar = (structName.length > 0)
        ? memchr(structName.start, '$', (size_t)structName.length) : NULL;
    if (elemDollar != NULL) {
        idName.start  = elemDollar + 1;
        idName.length = structName.length - (int)(elemDollar + 1 - structName.start);
        slotName      = structName;   /* slot = nom mangled complet */
        inCollection  = true;         /* déclenche l'alias nu vers le template */
    } else if (g_current_collection_name[0] != '\0'
        && current != NULL && current->scopeDepth == 0) {
        collection_member_register(g_current_collection_name,
                                   (int)strlen(g_current_collection_name),
                                   structName.start, structName.length, true);
        int pn = collection_var_prefix(g_current_collection_name,
                                       structName.start, structName.length,
                                       structMangleBuf, sizeof(structMangleBuf));
        if (pn > 0) {
            slotName.start  = structMangleBuf;
            slotName.length = pn;
            inCollection = true;
        }
    }
    /* Identité + champs sous le nom NU (idName). */
    register_user_type_kind(idName.start, idName.length,
                            OWL_USER_TYPE_STRUCTURE, structName.line);
    /* Track structure as a type (not a variable) so variables with same name are allowed */
    if (current->scopeDepth == 0) {
        global_track_declare_structure(slotName.start, slotName.length, slotName.line);
        if (inCollection) {
            global_track_declare_structure(idName.start, idName.length,
                                           structName.line);
        }
    }
    ConstIdx global = { 0 };
    if (current->scopeDepth == 0) {
        global = identifier_constant(&slotName);   /* slot mangled */
    }

    /* Tag de type porté par le template = nom NU (identité stable). */
    ConstIdx nameConst = make_constant(OBJ_VAL(
        obj_copy_string(idName.start, idName.length)));

    {
        Token newName;
        newName.start = "__StructNew";
        newName.length = 11;
        ConstIdx newConst = identifier_constant(&newName);
        emit_const_op(OP_GET_GLOBAL, newConst);
        emit_const_op(OP_CONSTANT, nameConst);
        emit_bytes(OP_CALL, 1);
    }

    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        /*  : TOKEN_TYPE libres (date, duree, json, ...) comme nom
         * de champ → demote en IDENTIFIER pour passer la garde check(IDENT)
         * juste apres. */
        (void)demote_free_type_to_identifier();
        /*  : declarateur GUI (Libelle, Etat, Bouton, ...) comme nom de
         * champ → demote en IDENTIFIER (mot-cle contextuel). NE touche PAS aux
         * mots-cles de controle (traites par le garde reserved juste apres). */
        (void)demote_gui_declarator_to_identifier();
        /*  : nom de champ ne peut pas etre un mot-cle reserve
         * (`buffer est un buffer`, `tableau est un tableau`, ...). Message
         * dedie avant le fallback generique "Nom de field attendu". */
        if (tokentype_is_reserved_keyword(parser.current.type)) {
            char kwname[32];
            keyword_canonical_uppercase_for(parser.current, kwname, sizeof(kwname));
            owl_emit_error_current(E_SEM_KEYWORD_AS_VAR_NAME, "name", kwname, NULL);
            /* Skip jusqu'a la fin de la ligne logique pour eviter une
             * cascade d'erreurs sur les tokens du type qui suit. */
            while (parser.current.type != TOKEN_FIN &&
                   parser.current.type != TOKEN_EOF &&
                   parser.current.type != TOKEN_NEWLINE) {
                advance_token();
            }
            if (parser.current.type == TOKEN_NEWLINE) advance_token();
            continue;
        }
        if (check(TOKEN_IDENTIFIER)) {
            advance_token();
            Token fieldTok = parser.previous;
            ConstIdx fieldNameConst = identifier_constant(&fieldTok);

            if (check(TOKEN_EST)) {
                advance_token();

                /*  — type imbriqué inline dans le corps de Structure,
                 * parité Classe (cf. class_declaration dispatch  +
                 * ). Un champ `X est une Structure / Énumération /
                 * Combinaison ... FIN` déclare un TYPE imbriqué (doctrine
                 * TYPE-PUR : enregistré au registre plat, utilisable comme type
                 * d'un champ suivant), PAS un membre de l'instance. On route
                 * donc AVANT toute émission de champ : ni OP_STRUCT_FIELD_ORDER
                 * ni user_type_add_field pour le nom du type. Le sub-declaration
                 * consomme son propre FIN → la fermeture de la structure
                 * englobante reste équilibrée (aucun FIN avalé, champs suivants
                 * non orphelins). enum/combination/struct_declaration sont
                 * neutres sur la pile à scopeDepth 0 — et le corps de struct
                 * opère toujours à scopeDepth 0 : top-level, dans une Collection
                 *, et routé depuis une Fenêtre/État (le body element
                 * swap `current = current->enclosing` avant struct_declaration).
                 * Le template en cours (poussé par __StructNew) reste intact au
                 * sommet. L'article EN `a`/`an` est consommé pour parité (no-op
                 * en FR, où le scanner l'a déjà gommé). Le nom du type est passé
                 * NU : le mangling collection/élément vise l'accès qualifié
                 * externe (`COL.Type`), non requis pour un type niché dans une
                 * struct. */
                consume_en_a_an_filler();
                if (check(TOKEN_STRUCTURE) || check(TOKEN_ENUMERATION)
                    || check(TOKEN_COMBINAISON)) {
                    /*  — un type imbriqué DANS le corps d'une struct est
                     * un TYPE PLAT (registre nu), jamais un membre EXPOSÉ de la
                     * collection englobante. struct_declaration récursif relit
                     * l'état GLOBAL g_current_collection_name (toujours posé sur
                     * toute la durée du corps de la collection) et, sans ce
                     * guard, manglerait le type niché en <COL>$<Nom> :
                     * collection_member_register avec seenParse-only → crash
                     * cross-check prescan (E_SEM_COLLECTION_MEMBER_NOT_PRESCANNED),
                     * et dédup par (collection, name) → collision de deux types
                     * nichés homonymes dans deux structs de la même collection.
                     * On neutralise donc l'état le temps de la sous-déclaration
                     * (miroir de enum/combination_declaration qui n'auto-manglent
                     * que sur `$` explicite posé par l'appelant). Restore après :
                     * seul un struct_declaration récursif relit cet état, mais on
                     * garde l'équilibre par principe. Le chemin Fenêtre/État reste
                     * inchangé (nom déjà manglé `$` par le caller, pas de
                     * dépendance à g_current_collection_name). */
                    char savedColl[64];
                    memcpy(savedColl, g_current_collection_name, sizeof(savedColl));
                    g_current_collection_name[0] = '\0';

                    if (check(TOKEN_STRUCTURE)) {
                        advance_token();  /* consume STRUCTURE */
                        struct_declaration(fieldTok);
                    } else if (check(TOKEN_ENUMERATION)) {
                        advance_token();  /* consume ENUMERATION */
                        enum_declaration(fieldTok);
                    } else {
                        advance_token();  /* consume COMBINAISON */
                        combination_declaration(fieldTok);
                    }

                    memcpy(g_current_collection_name, savedColl,
                           sizeof(g_current_collection_name));
                    continue;
                }

                /* Champ de données classique. Record field order on the
                 * template (top-of-stack ObjInstance) to support positional
                 * coercion [v1,v2,...] -> struct instance. */
                emit_const_op(OP_STRUCT_FIELD_ORDER, fieldNameConst);

                /* Capture the type token (might be primitive keyword or
                 * user-struct identifier) so chained access (p.Adr.Ville)
                 * can validate against the sub-struct's fields. */
                {
                    Token tt = parser.current;
                    /*  — un champ dont le type debute par TABLEAU /
                     * ASSOCIATIF est un conteneur : `..Occurrence` & co sont des
                     * proprietes legitimes. Marque pose au registre pour que le
                     * validateur `.`/`..` ne le confonde pas avec un scalaire. */
                    bool fieldIsContainer = (tt.type == TOKEN_TABLEAU
                                             || tt.type == TOKEN_ASSOCIATIF);
                    user_type_add_field(idName.start, idName.length,
                                        fieldTok.start, fieldTok.length,
                                        tt.start, tt.length, fieldIsContainer,
                                        tt.line, tt.column);
                }

                /* Capture the type token BEFORE skip_type_spec consumes it.
                 * If it's a known user struct, auto-initialise the field on
                 * the template with a fresh sub-instance (deep auto-init). */
                Token typeTok = parser.current;
                bool typeIsUserStruct =
                    typeTok.type == TOKEN_IDENTIFIER &&
                    is_known_user_type(typeTok.start, typeTok.length);
                /*  — champ dont le type est un type composé BUILTIN
                 * (httpRequête, Cadre, Police...) : comme une variable directe
                 * de ce type, on l'auto-initialise à une instance fraîche via
                 * __StructClone(<template>), sinon le champ reste Null et
                 * `s.champ..Prop` échoue au runtime (« Accès champ sur Null »).
                 * On exclut les alias scalaire registry (hasDefault, ex.
                 * Couleur/zipArchive : pas de template) et chaineMultilingue
                 * (factory dédiée) — hors scope, comportement inchangé. */
                bool typeIsBuiltinComposite = false;
                bool typeIsMultilingue = false;   /*  */
                if (!typeIsUserStruct && typeTok.type == TOKEN_IDENTIFIER) {
                    char cprobe[128];
                    int cpl = typeTok.length < (int)sizeof(cprobe) - 1
                                  ? typeTok.length : (int)sizeof(cprobe) - 1;
                    memcpy(cprobe, typeTok.start, (size_t)cpl);
                    cprobe[cpl] = '\0';
                    const OwlTypeDef* ctd = owl_registry_type_find(cprobe);
                    typeIsMultilingue = (ctd != NULL && ctd->canonicalAscii &&
                        strcmp(ctd->canonicalAscii, "chaineMultilingue") == 0);
                    typeIsBuiltinComposite = (ctd != NULL && ctd->fields != NULL
                                              && !ctd->hasDefault && !typeIsMultilingue);
                }

                /* Reject direct self-reference: a value-type struct cannot
                 * own a field of its own type by value (infinite size +
                 * infinite auto-init). The language rejects identically. The
                 * standard OWL workaround is a CLASSE (reference type),
                 * which does support recursion naturally. The language's
                 * `dynamique` keyword isn't implemented; a nullable marker
                 * (`?` / `<nullable>`) isn't parsed on struct fields
                 * either — both are separate chantiers. */
                if (typeIsUserStruct &&
                    typeTok.length == idName.length &&
                    strncasecmp(typeTok.start, idName.start, (size_t)typeTok.length) == 0) {
                    char typeBuf[128];
                    snprintf(typeBuf, sizeof(typeBuf), "%.*s",
                             typeTok.length, typeTok.start);
                    owl_emit_error_at(&typeTok, E_SEM_STRUCT_SELF_RECURSION,
                                      "type", typeBuf,
                                      NULL);
                    typeIsUserStruct = false; /* skip auto-init emission */
                }

                /*  : champ de structure `tableau associatif de X`
                 * (2 ordres FR/EN). Detecte + consomme la spec assoc avant le
                 * skip_type_spec (qui ignore TOKEN_ASSOCIATIF). Default = tableau
                 * associatif vide, symetrique au tableau dynamique. */
                int structAssocVK = 0;
                Token structAssocValueType;     /*  */
                structAssocValueType.start = NULL;
                structAssocValueType.length = 0;
                bool fieldIsAssoc =
                    try_consume_assoc_array_field_type(&structAssocVK,
                                                       &structAssocValueType);

                /*  — valide le nom de type du champ (scalaire ET
                 * element de collection) au meme titre qu'une declaration de
                 * variable. Un type inconnu etait avale en silence. */
                if (!fieldIsAssoc) skip_type_spec_ex(true, false);

                if (fieldIsAssoc) {
                    /* DUP template, push assoc vide, STRUCT_SET, POP (meme
                     * pattern que le default scalaire ci-dessous). */
                    emit_byte(OP_DUP);
                    emit_empty_assoc_array(structAssocVK, &structAssocValueType);
                    emit_const_op(OP_STRUCT_SET, fieldNameConst);
                    emit_byte(OP_POP);
                } else if (typeTok.type == TOKEN_TABLEAU) {
                    /*  — membre `tableau [de X]` dynamique (non
                     * associatif) : tableau vide utilisable des l'instanciation
                     * (TableauAjoute / ..Occurrence / POUR TOUT). Sans ce default
                     * le membre restait absent du template -> Null sur l'instance
                     * -> « Acces a un champ sur une valeur Null ». Miroir du
                     * champ de classe et du path assoc ci-dessus ;
                     * native_struct_clone deep-clone l'array -> instances
                     * independantes. */
                    emit_byte(OP_DUP);
                    emit_byte(OP_ARRAY);
                    emit_const_op(OP_STRUCT_SET, fieldNameConst);
                    emit_byte(OP_POP);
                } else if (typeIsMultilingue) {
                    /*  — membre chaineMultilingue : instance fraiche via
                     * la factory dediee (__MultilingueNew), symetrique de la
                     * declaration de variable (type mutable, pas de singleton
                     * partage). Le clone par instance (native_struct_clone ->
                     * value_deep_clone) garantit l'independance. */
                    emit_byte(OP_DUP);
                    Token mlTok;
                    mlTok.start = "__MultilingueNew";
                    mlTok.length = 16;
                    mlTok.type = TOKEN_IDENTIFIER;
                    mlTok.line = parser.previous.line;
                    mlTok.column = 0;
                    ConstIdx mlIdx = identifier_constant(&mlTok);
                    emit_const_op(OP_GET_GLOBAL, mlIdx);
                    emit_bytes(OP_CALL, 0);
                    emit_const_op(OP_STRUCT_SET, fieldNameConst);
                    emit_byte(OP_POP);
                } else if (typeIsUserStruct || typeIsBuiltinComposite) {
                    /* Template instance is on the stack (pushed by __StructNew
                     * at the start of struct_declaration). We consume it via
                     * DUP → get sub-instance → STRUCT_SET, and the DUP'd copy
                     * remains on the stack so subsequent fields can also DUP.
                     *  — emit_get_type_global résout aussi bien un
                     * template builtin (httpRequête) qu'une structure user. */
                    emit_byte(OP_DUP);
                    Token cloneName;
                    cloneName.start = "__StructClone";
                    cloneName.length = 13;
                    cloneName.type = TOKEN_IDENTIFIER;
                    cloneName.line = parser.previous.line;
                    cloneName.column = 0;
                    ConstIdx cloneConst = identifier_constant(&cloneName);
                    emit_const_op(OP_GET_GLOBAL, cloneConst);
                    ConstIdx typeNameConst = identifier_constant(&typeTok);
                    emit_get_type_global(typeTok.start, typeTok.length,
                                         typeNameConst);   /*  */
                    emit_bytes(OP_CALL, 1);
                    emit_const_op(OP_STRUCT_SET, fieldNameConst);
                    emit_byte(OP_POP);  /* STRUCT_SET leaves value on stack */
                } else {
                    /* Field scalaire : init à la valeur par défaut du type
                     * (canon : pas de field "Null" sur un type non-nullable).
                     * Pattern : DUP template, push zero-typed, STRUCT_SET. */
                    bool emitDefault = true;
                    emit_byte(OP_DUP);
                    switch (typeTok.type) {
                        case TOKEN_CHAINE:
                            emit_constant(OBJ_VAL(obj_copy_string("", 0)));
                            break;
                        case TOKEN_ENTIER:
                            emit_constant(INTEGER_VAL(0));
                            break;
                        case TOKEN_REEL:
                            emit_constant(REAL_VAL(0.0));
                            break;
                        case TOKEN_BOOLEEN:
                            emit_byte(OP_FALSE);
                            break;
                        case TOKEN_MONETAIRE:
                            emit_constant(CURRENCY_VAL(0));
                            break;
                        case TOKEN_NUMERIQUE:
                            emit_constant(numeric_from_i64(0));
                            break;
                        default:
                            /* Type non-primitive (date, buffer, tableau...) :
                             * pas d'init zero-typed simple. Annule le DUP. */
                            emit_byte(OP_POP);
                            emitDefault = false;
                            break;
                    }
                    if (emitDefault) {
                        emit_const_op(OP_STRUCT_SET, fieldNameConst);
                        emit_byte(OP_POP); /* STRUCT_SET leaves value on stack */
                    }
                }

                /* Attributs d'extension <…> sur la déclaration du champ.
                 * Reconnait Sérialise=Faux / Sérialise=Vrai / Sérialise="rename".
                 * Les autres attributs (nullable, indétectable, …) sont
                 * silencieusement skippés — pas leur place ici. */
                if (check(TOKEN_LESS)) {
                    advance_token();  /* consume '<' */
                    while (!check(TOKEN_GREATER) && !check(TOKEN_EOF) &&
                           !check(TOKEN_NEWLINE)) {
                        if (check(TOKEN_IDENTIFIER)) {
                            Token attr = parser.current;
                            advance_token();
                            /* "Sérialise" en UTF-8 = 10 bytes (S, é=0xC3,0xA9, r, i, a, l, i, s, e),
                             * ASCII alias "Serialise" = 9 bytes. */
                            bool isSerialise =
                                (attr.length == 10 && strncmp(attr.start,
                                    "S\xc3\xa9" "rialise", 10) == 0) ||
                                (attr.length == 9  && strncasecmp(attr.start,
                                    "Serialise", 9) == 0);
                            if (isSerialise && match_token(TOKEN_EQUAL)) {
                                if (check(TOKEN_FAUX)) {
                                    advance_token();
                                    user_type_set_field_serialise(
                                        idName.start, idName.length,
                                        true, NULL, 0);
                                } else if (check(TOKEN_VRAI)) {
                                    advance_token();
                                    /* Sérialise=Vrai = défaut, no-op. */
                                } else if (check(TOKEN_STRING)) {
                                    Token rn = parser.current;
                                    advance_token();
                                    /* Sans le CR-stripping, ils ressortiraient
                                     * echappes dans la cle JSON. `rename` n'est
                                     * pas enracine : aucune allocation OWL ne
                                     * doit s'intercaler jusqu'au consommateur. */
                                    ObjString* rename =
                                        string_literal_value_from_token(rn);
                                    user_type_set_field_serialise(
                                        idName.start, idName.length,
                                        false, rename->chars, rename->length);
                                }
                            }
                            /* Un attribut sans valeur (ex: nullable) ou inconnu
                             * est simplement skippé. */
                        } else {
                            advance_token();
                        }
                        if (check(TOKEN_COMMA)) advance_token();
                    }
                    if (check(TOKEN_GREATER)) advance_token();
                }

                /* Valeur initiale du champ. Elle ECRASE le default zero-typed
                 * emis juste au-dessus : meme patron (DUP template, valeur,
                 * STRUCT_SET, POP) que ce default, donc le template porte la
                 * valeur declaree et chaque instance en recoit une copie via
                 * __StructClone. Avant  l'expression etait compilee
                 * puis jetee (OP_POP) : la declaration etait acceptee et la
                 * valeur silencieusement perdue, alors qu'un membre de CLASSE
                 * l'honorait deja. */
                if (match_token(TOKEN_EQUAL)) {
                    emit_byte(OP_DUP);
                    expression();
                    emit_const_op(OP_STRUCT_SET, fieldNameConst);
                    emit_byte(OP_POP);   /* STRUCT_SET laisse la valeur */
                }
            } else {
                owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_EST_AFTER_STRUCT_FIELD);
            }
        } else {
            /*  : pointer le token fautif courant (le nom de champ
             * invalide), pas parser.previous — sinon le diagnostic designe
             * l'ouverture de la structure ou le token precedent. */
            owl_emit_error_at(&parser.current, E_SYNTAX_EXPECTED_STRUCT_FIELD_NAME);
            advance_token();
        }
    }

    define_variable(global);

    /*  — alias NU vers le même template (cf. enum_declaration). Le slot
     * MANGLED reste le canon de l'accès qualifié `COL.stPoint` (distinct par
     * collection) ; le slot NU sert la position de type nom-nu (case_073) et le
     * clone `__StructClone(<nom nu>)`. Collision de nom nu -> dernier gagnant,
     * sans impact (l'accès qualifié passe par les slots mangled). */
    if (inCollection && current->scopeDepth == 0) {
        ConstIdx bareConst = identifier_constant(&idName);
        emit_const_op(OP_GET_GLOBAL, global);
        emit_const_op(OP_DEFINE_GLOBAL, bareConst);
    }

    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_STRUCTURE);
}

/* AVEC/WITH block: AVEC expr ... FIN */
static void avec_statement(void) {
    begin_scope();

    /* Compile the target expression — stop before infix dot/call to avoid
     * consuming `.member = val` as part of the AVEC target expression */
    parse_precedence((Precedence)(PREC_CALL + 1));

    /* Store as hidden local (same pattern as for-loop variables) */
    Token hidden;
    hidden.start = " avec";
    hidden.length = 5;
    hidden.line = parser.previous.line;
    hidden.column = 0;
    hidden.type = TOKEN_IDENTIFIER;
    add_local(hidden);

    int targetSlot = current->localCount - 1;

    if (avecDepth >= MAX_AVEC_DEPTH) {
        error_capacity_exceeded("MAX_AVEC_DEPTH", MAX_AVEC_DEPTH);
        return;
    }
    avecSlots[avecDepth++] = targetSlot;

    /* Parse body until FIN */
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        declaration();
    }

    avecDepth--;
    end_scope();
    consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_AVEC);
}

/* Bloc CONSTANTE / CONSTANT (doc 1514012) — formes synonymes :
 *
 *   Forme bloc (newline obligatoire apres le mot-cle) :
 *     CONSTANTE
 *         Nom1 = ValeurLittérale1
 *         Nom2 = ValeurLittérale2
 *     FIN
 *
 *   Forme inline (IDENT sur la meme ligne) :
 *     CONSTANT Nom = ValeurLittérale
 *
 * Discrimination via `crossedNewline` apres consommation du mot-cle, comme
 * deja fait pour les constantes de classe (cf. L11197). Inline parse un
 * unique binding ; bloc parse jusqu'a FIN.
 *
 * Émet, pour chaque binding, OP_CONSTANT(litéral) + OP_DEFINE_GLOBAL(nom).
 * Les constantes sont des globales avec une valeur fixe — l'immutabilité
 * runtime est suivie via g_const_globals (cf. error message à la
 * réassignation). */
static void constante_block(void) {
    /* TOKEN_CONSTANTE déjà consommé par le caller. crossedNewline reflete
     * le saut de ligne entre CONSTANT[E] et le token courant. */
    bool isBlock = crossedNewline;
    do {
        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_current(E_SYNTAX_EXPECTED_CONST_NAME_IN_CONSTANTE);
            advance_token();
            if (isBlock) continue;
            return;
        }
        Token name = parser.current;
        advance_token();
        consume(TOKEN_EQUAL, E_SYNTAX_EXP_EQUAL_CONST_NAME);

        /* Émet la valeur littérale. parse_default_literal accepte les mêmes
         * formes que pour les paramètres par défaut : INTEGER, REAL, STRING,
         * VRAI/FAUX, NUL, et négation unaire. */
        Value v;
        if (!parse_default_literal(&v)) {
            owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_LITERAL_VALUE);
            if (isBlock) continue;
            return;
        }
        emit_constant(v);

        /* Define as global. Marque comme constante pour interdire la
         * réassignation au compile-time. Track aussi dans g_declaredGlobals
         * pour que la validation d'identifiant `is_known_global_name`
         * la reconnaisse. */
        ConstIdx global = identifier_constant(&name);
        const_globals_add(name.start, name.length, v);
        global_track_declare(name.start, name.length, parser.previous.line);
        global_track_mark_initialized(name.start, name.length);
        emit_const_op(OP_DEFINE_GLOBAL, global);
    } while (isBlock && !check(TOKEN_FIN) && !check(TOKEN_EOF));
    if (isBlock) {
        consume(TOKEN_FIN, E_SYNTAX_EXP_FIN_CONSTANTE);
    }
}

/* Garde Arb 1 strict (ticket 0014) : à l'intérieur d'un body ENFIN
 * (FINALLY), on refuse les statements qui interrompent le flux. Le
 * cleanup doit s'exécuter linéairement. Émet une compile-error
 * spécifique nommant le keyword fautif et avale le token. Retourne
 * true si le token a été rejeté et la statement absorbée. */
static bool enfin_gate_reject_current_statement(void) {
    if (insideEnfinBody <= 0) return false;

    const char* kw = NULL;
    switch (parser.current.type) {
        case TOKEN_RENVOYER:  kw = "RENVOYER";  break;
        case TOKEN_RETOUR:    kw = "RETOUR";    break;
        case TOKEN_SORTIR:    kw = "SORTIR";    break;
        case TOKEN_CONTINUER: kw = "CONTINUER"; break;
        case TOKEN_EXCEPTION: kw = "EXCEPTION"; break;
        default: break;
    }

    /* ExceptionDéclenche : intercepté par match de nom — comparaison
     * accent/case-insensitive sur l'identifier courant. */
    if (kw == NULL && parser.current.type == TOKEN_IDENTIFIER) {
        const char* p = parser.current.start;
        int len = parser.current.length;
        /* Forme canon UTF-8 "ExceptionDéclenche" (19 bytes) ou ASCII
         * "ExceptionDeclenche" (18 bytes), ou EN "ExceptionThrow"
         * (14 bytes). Tous traités identiquement. */
        if ((len == 19 && strncmp(p, "ExceptionD\xc3\xa9" "clenche", 19) == 0) ||
            (len == 18 && strncasecmp(p, "ExceptionDeclenche", 18) == 0) ||
            (len == 14 && strncasecmp(p, "ExceptionThrow",    14) == 0)) {
            kw = "ExceptionD\xc3\xa9" "clenche"; /* canon FR pour le wording */
        }
    }

    if (kw == NULL) return false;

    owl_emit_error_current(E_SEM_ENFIN_FORBIDDEN_STATEMENT,
                           "keyword", kw,
                           NULL);
    /* Consume le token fautif pour éviter une cascade. */
    advance_token();
    return true;
}

static void statement(void) {
    if (enfin_gate_reject_current_statement()) {
        return;
    }
    /* ENFIN orphelin : seul `exception_statement` doit le consommer
     * (en lookahead via check + advance). Tout autre site qui voit
     * ENFIN ici est hors d'un QUAND EXCEPTION DANS. */
    if (check(TOKEN_ENFIN)) {
        owl_emit_error_current(E_SYNTAX_ENFIN_ORPHAN);
        /* Consume jusqu'à FIN pour éviter une cascade. */
        advance_token();
        int depth = 0;
        while (!check(TOKEN_EOF)) {
            /*  — source unique. `SI c ALORS instr` ne compte pas. */
            if (!check(TOKEN_FIN)
                && prescan_token_in_depth_table(parser.current.type)
                && parser_depth_delta() > 0) {
                depth++;
            } else if (check(TOKEN_FIN)) {
                if (depth == 0) { advance_token(); return; }
                depth--;
            }
            advance_token();
        }
        return;
    }
    /*  : `Delete(...)` en tete de statement (forme EN de Supprime)
     * ne doit pas etre intercepte par la branche LIBERER (liberation OOP).
     * Meme discrimination que dans parse_precedence : native resolue +
     * `(` suivant -> demote en IDENTIFIER, route vers expression_statement.
     * `delete oVar` (var, pas `(`) reste une liberation OOP. */
    (void)demote_liberer_native_call_to_identifier();
    if (match_token(TOKEN_SI)) {
        if_statement();
    } else if (match_token(TOKEN_POUR)) {
        if (match_token(TOKEN_TOUT)) {
            foreach_statement();
        } else {
            for_statement();
        }
    } else if (match_token(TOKEN_TANTQUE)) {
        while_statement();
    } else if (match_token(TOKEN_BOUCLE)) {
        loop_statement();
    } else if (match_token(TOKEN_SELON)) {
        switch_statement();
    } else if (match_token(TOKEN_QUAND)) {
        exception_statement();
    } else if (match_token(TOKEN_CONSTANTE)) {
        constante_block();
    } else if (check(TOKEN_EXCEPTION) && insideExceptionHandler > 0) {
        /* Bare `EXCEPTION` keyword inside a handler → re-raise the current
         * exception to the enclosing handler. */
        advance_token();
        emit_byte(OP_RERAISE);
    } else if (match_token(TOKEN_AVEC)) {
        avec_statement();
    } else if (match_token(TOKEN_CONSTRUCTEUR)) {
        /* Constructeur ClassName(args) - call parent constructor
         * Compiled as: this.ClassName(args) via OP_INVOKE.
         * Stack: [this] [arg1] ... [argN] -> OP_INVOKE(className, argCount) */
        consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_CLASS_NAME_AFTER_CTOR);
        Token parentClass = parser.previous;
        ConstIdx nameConst = identifier_constant(&parentClass);

        /* Push 'this' (slot 0) as receiver */
        emit_bytes(OP_GET_LOCAL, 0);

        /* Parse and emit arguments */
        consume(TOKEN_LEFT_PAREN, E_SYNTAX_EXP_LPAREN_AFTER_CLASS_NAME);
        uint8_t argCount = argument_list();

        /* Invoke the parent constructor on this */
        emit_const_op_b(OP_INVOKE, nameConst, argCount);
        emit_byte(OP_POP); /* pop result */
    } else if (match_token(TOKEN_SORTIR)) {
        if (check(TOKEN_SELON)) {
            /* Conserver la position du SORTIR pour pointer l'erreur a
             * son debut, pas au SELON consomme par le lookahead. */
            Token sortirToken = parser.previous;
            advance_token();
            emit_break_switch_at(sortirToken);
        } else if (check(TOKEN_LEFT_PAREN)) {
            /* SORTIR(<niveau>) : sortie multi-niveau de boucles imbriquees.
             * Canon — <niveau> est un entier litteral
             * entre 1 et N (profondeur des boucles imbriquees). */
            advance_token(); /* consume ( */
            if (!check(TOKEN_INTEGER)) {
                owl_emit_error_at(&parser.previous, E_SEM_SORTIR_EXPECTS_INTEGER_LITERAL);
            } else {
                int levels = (int)strtol(parser.current.start, NULL, 10);
                advance_token();
                consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_SORTIR_LEVEL);
                emit_break_levels(levels);
            }
        } else {
            emit_break();
        }
    } else if (match_token(TOKEN_CONTINUER)) {
        emit_continue();
    } else if (check(TOKEN_RENVOYER) || check(TOKEN_RETOUR)) {
        /* Enforcement canon : ne pas mélanger RETOUR
         * et RENVOYER dans une meme procedure. Le check tracke le kind
         * du premier vu et claque sur le 2eme si different. */
        int thisKind = parser.current.type;
        int thisLine = parser.current.line;
        if (current->seenReturnKind != 0 &&
            current->seenReturnKind != thisKind) {
            const char* firstName = (current->seenReturnKind == TOKEN_RETOUR)
                                    ? "RETOUR" : "RENVOYER";
            const char* thisName = (thisKind == TOKEN_RETOUR)
                                    ? "RETOUR" : "RENVOYER";
            char lineBuf[16];
            snprintf(lineBuf, sizeof(lineBuf), "%d",
                     current->seenReturnLine);
            owl_emit_error_at(&parser.previous, E_SEM_RETURN_KEYWORD_MIX,
                              "this", thisName,
                              "first", firstName,
                              "line", lineBuf,
                              NULL);
        } else if (current->seenReturnKind == 0) {
            current->seenReturnKind = thisKind;
            current->seenReturnLine = thisLine;
        }
        advance_token();  /* consume RETOUR ou RENVOYER */
        /* Garde divergence assumee : le mode canon
         * "RETOUR = X" (assignation differee) n'est pas supporte. Au
         * lieu de laisser le compilo emettre un cryptique "Expected
         * expression" sur le '=' qui suit, on capture le pattern pour
         * un message dedie qui pointe le substitut idiomatique. */
        if (check(TOKEN_EQUAL)) {
            const char* kwName = (thisKind == TOKEN_RETOUR)
                                  ? "RETOUR" : "RENVOYER";
            owl_emit_error_current(E_SEM_RETURN_ASSIGN_NOT_SUPPORTED,
                                   "keyword", kwName,
                                   NULL);
            return;
        }
        /* RETOUR / RENVOYER at top-level exits the script cleanly. The
         * semantic: a script is a "traitement" and
         * returning from it terminates execution.
         *
         * Detection "RENVOYER sans valeur" : le statement est termine si
         * le token suivant marque une frontiere de statement.
         *
         * IMPORTANT : advance_token() skip silently TOKEN_NEWLINE et
         * TOKEN_SEMICOLON, en posant le flag crossedNewline. On consulte
         * donc ce flag (pas check(TOKEN_NEWLINE) qui ne match jamais) en
         * plus de TOKEN_FIN / TOKEN_EOF / TOKEN_SINON.
         *
         * Bug historique (sans ce check) : la forme courte
         * `SI n < 0 ALORS RENVOYER\n Trace(...)` avalait le Trace de la
         * ligne suivante comme expression de retour. Resultat :
         * inversion totale du comportement attendu de la garde — quand
         * la condition etait vraie, le body s'executait avec OP_RETURN
         * en piggy-back ; quand fausse, on sautait tout. */
        if (crossedNewline ||
            check(TOKEN_FIN) || check(TOKEN_EOF) || check(TOKEN_SINON)) {
            emit_return();
        } else if (check(TOKEN_LEFT_PAREN)) {
            /*  : distinguer tuple multi-valeurs vs expression
             * parenthesee. Avant le fix, toute paren apres RENVOYER
             * declenchait le mode tuple, ce qui cassait
             * `RENVOYER (a = b) OU (a > 10)` en faisant remonter le OU
             * comme token inattendu apres la `)` matching de `(a = b)`.
             *
             * Strategie : lookahead jusqu'a la `)` matching du paren
             * racine. Si une virgule apparait a la profondeur du paren
             * racine (en ignorant les virgules sous-brackets / accolades
             * comme `tab[i, j]` ou `{a, b}`), c'est un tuple. Sinon,
             * c'est une expression parenthesee — on retombe sur
             * condition_expression() qui consommera proprement la paren
             * et continuera le parsing au niveau RENVOYER (operateur
             * binaire eventuel apres la `)`). */
            bool isTuple = false;
            {
                Scanner savedSc   = parser.scanner;
                Token   savedCur  = parser.current;
                Token   savedPrev = parser.previous;
                bool    savedXNL  = crossedNewline;
                advance_token(); /* consume ( */
                int parenDepth   = 1;
                int bracketDepth = 0;
                int braceDepth   = 0;
                int guard        = 0;
                while (parenDepth > 0 && !check(TOKEN_EOF) && guard++ < 100000) {
                    if (check(TOKEN_LEFT_PAREN))       parenDepth++;
                    else if (check(TOKEN_RIGHT_PAREN)) parenDepth--;
                    else if (check(TOKEN_LEFT_BRACKET))  bracketDepth++;
                    else if (check(TOKEN_RIGHT_BRACKET)) bracketDepth--;
                    else if (check(TOKEN_LEFT_BRACE))    braceDepth++;
                    else if (check(TOKEN_RIGHT_BRACE))   braceDepth--;
                    else if (check(TOKEN_COMMA)
                             && parenDepth == 1
                             && bracketDepth == 0
                             && braceDepth == 0) {
                        isTuple = true;
                        break;
                    }
                    advance_token();
                }
                parser.scanner  = savedSc;
                parser.current  = savedCur;
                parser.previous = savedPrev;
                crossedNewline  = savedXNL;
            }
            if (isTuple) {
                /* Multiple return: RENVOYER (a, b, c)
                 * Compile each expression, then emit OP_ARRAY_PACK N
                 * which pops N values and creates an array. */
                advance_token(); /* consume ( */
                uint8_t count = 0;
                do {
                    expression();
                    count++;
                } while (match_token(TOKEN_COMMA));
                consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_RETURN_VALUES);
                emit_bytes(OP_ARRAY_PACK, count);
                emit_byte(OP_RETURN);
            } else {
                /* Expression parenthesee : meme traitement que la
                 * branche `else` ci-dessous. */
                condition_expression();
                emit_byte(OP_RETURN);
            }
        } else {
            /* RENVOYER expr : meme principe que la RHS d'assignment, on
             * utilise condition_expression pour eviter que `<=` ou `=`
             * dans expr soient aspires comme assignments. */
            condition_expression();
            emit_byte(OP_RETURN);
        }
    } else if (match_token(TOKEN_LIBERER)) {
        /* Libérer oObj — tries to call __destructor, then sets variable to Nil */
        if (!check(TOKEN_IDENTIFIER)) {
            owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_VAR_NAME_AFTER_LIBERER);
        } else {
            advance_token();
            Token varName = parser.previous;
            int arg = resolve_local(current, &varName);
            uint8_t getOp, setOp;

            if (arg != -1) {
                getOp = OP_GET_LOCAL;
                setOp = OP_SET_LOCAL;
            } else {
                arg = const_idx_i(identifier_constant(&varName));
                getOp = OP_GET_GLOBAL;
                setOp = OP_SET_GLOBAL;
            }

            /* Try calling __destructor via OP_INVOKE_SAFE (0 args, no error if missing) */
            emit_var_op(getOp, arg);
            {
                ConstIdx dtorName = make_constant(OBJ_VAL(
                    obj_copy_string("__destructor", 12)));
                emit_const_op_b(OP_INVOKE_SAFE, dtorName, 0);
            }
            emit_byte(OP_POP); /* pop invoke result */

            /* Set variable to Nil */
            emit_byte(OP_NIL);
            emit_var_op(setOp, arg);
        }
    } else {
        expression_statement();
    }
}

/* ================================================================
 * DECLARATION PARSING
 * ================================================================ */

/*  — profondeur de brackets DU POINT DE VUE DU PARSER, avant
 * consommation de parser.current. scanner.bracketDepth compte l'effet de
 * parser.current DES SA LECTURE (make_token) : le parser, lui, ne l'a pas
 * encore consomme. Correction pour ne pas mal juger le contexte de recovery :
 *   - current est un ouvreur `( [ {` : le scanner a deja +1, le parser est
 *     encore DEHORS -> depth reelle = scanner - 1.
 *   - current est un fermeur `) ] }` : le scanner a deja -1, le parser est
 *     encore DEDANS -> depth reelle = scanner + 1.
 * Sans ca, une erreur dans une liste de parametres `(...)` (current = `)`
 * non consomme) lirait une profondeur 0 trompeuse. */
static int parser_effective_bracket_depth(void) {
    int d = parser.scanner.bracketDepth;
    switch (parser.current.type) {
        case TOKEN_LEFT_PAREN:
        case TOKEN_LEFT_BRACE:
        case TOKEN_LEFT_BRACKET:
            d--;
            break;
        case TOKEN_RIGHT_PAREN:
        case TOKEN_RIGHT_BRACE:
        case TOKEN_RIGHT_BRACKET:
            d++;
            break;
        default:;
    }
    return d;
}

static void synchronize(void) {
    /*  : flag positionne uniquement ici (resynchronisation =
     * preuve que le parser a perdu son chemin). Les erreurs isolees
     * sans recovery ne le declenchent pas, ce qui laisse les enforces
     * de fichier-classe s'exprimer normalement. */
    parser.hadFileError = true;
    parser.panicMode = false;

    /*  : frontiere de recuperation sur fin de statement, pour que
     * `owl --check` (et donc les diagnostics de l'editeur) rapporte
     * PLUSIEURS erreurs par fichier au lieu de s'arreter a la premiere.
     *
     * OWL est a separateur-newline ; advance_token() avale les NEWLINE et
     * positionne crossedNewline=true quand le token courant commence une
     * nouvelle ligne. Cas dominant : le statement fautif a ete parse
     * jusqu'au bout (ex `n est un entier = inconnue()` -> l'erreur
     * "fonction inconnue" est emise APRES avoir consomme tout l'appel),
     * la boucle appelante a fini le statement, et a l'entree de
     * synchronize() parser.current est DEJA au debut du statement suivant
     * (crossedNewline=true). Dans ce cas on rend la main immediatement,
     * sans consommer : la boucle (top-level / body de bloc) reparse le
     * statement suivant et emet SA propre erreur. Pas de spin :
     * declaration() consomme toujours >=1 token.
     *
     * Volontairement LIMITE a l'entree (et non a chaque ligne franchie
     * pendant le skip). Si l'erreur a saute AU MILIEU d'une construction
     * (entry crossedNewline=false : appel/litteral `{...}` multi-ligne,
     * desynchro DSL...), on NE resynchronise PAS sur la 1ere newline
     * rencontree — ce serait au milieu d'une construction legitime et
     * produirait des fragments parasites ("Expression attendue" sur le
     * `})` residuel, faux "masque l'identifiant"...). On retombe alors sur
     * le skip historique jusqu'au prochain keyword/FIN (recuperation de
     * bloc, /0373/0317), qui evite ces cascades.
     *
     * L'anti-cascade intra-statement reste par ailleurs assure par le
     * guard panicMode d'error_at.
     *
     * GARDE  : on N'applique PAS le newline-stop dans un
     * fichier-fenetre/-etat. La, une desynchro DSL (NBSP, ==, prop mal
     * parsee) doit collapser tout le reste du fichier vers UNE seule
     * erreur "bloc ferme trop tot" + UNE note agregee
     * (enforce_dsl_file_isolation_at_top_level, gate sur
     * parser.hadFileError pose juste au-dessus). Le collapse rentre dans
     * synchronize a une frontiere de ligne propre (entre deux widgets) :
     * sans cette garde, le newline-stop rendrait la main widget par
     * widget, le top-level reparserait fragment par fragment et
     * re-emettrait le header de collapse → flood + double comptage. */
    /* Contexte-fichier ou le newline-stop anti-cascade est autorise :
     * dans un corps de bloc DSL, ou dans un fichier hors
     * fenetre/-etat. En fichier-fenetre/-etat au scan de widgets, la
     * garde  impose le collapse (skip-to-keyword) — pas de
     * newline-stop. */
    bool newlineStopAllowed =
        g_in_dsl_body_stmt
        || (!g_file_has_window_block_prescan
            && !g_file_has_etat_block_prescan);

    /*  — une chaine multi-lignes `[ ... ]` a absorbe le code des lignes
     * suivantes en CONTENU (le scanner a mange les frontieres de ligne). La
     * structure de lignes en aval n'est plus fiable : le newline-stop plat
     * atterrirait au milieu de texte absorbe et fabriquerait des fragments.
     * Quand une telle chaine est en jeu (comme token fautif courant ou
     * rencontree pendant le skip), on retombe sur le collapse skip-to-keyword
     * historique. */
    bool absorbedMultiline = (parser.current.type == TOKEN_MULTILINE_STRING);

    /*  — le newline-stop plat n'est arme que si l'erreur a ete emise
     * sur un statement PLAT (profondeur de brackets 0 vue par le parser a
     * l'entree). Si on entre en recovery DEPUIS l'interieur d'un groupe
     * `(...)`/`{...}`/`[...]` (p.ex. une valeur de defaut invalide dans une
     * liste de parametres : current = `)` encore non consomme, profondeur 1),
     * la continuation et le corps qui suivent ne doivent PAS etre traites
     * comme des statements plats a reparse ligne par ligne — on garde le
     * skip-to-keyword historique (qui saute jusqu'au FIN du bloc). */
    bool flatEntry = (parser_effective_bracket_depth() == 0);

    if (crossedNewline && newlineStopAllowed) {
        /*  : dans le corps d'un bloc DSL (g_in_dsl_body_stmt), on
         * autorise le newline-stop meme en fichier-fenetre/-etat. L'erreur a
         * ete emise APRES un statement pleinement parse (crossedNewline=true,
         * parser.current au debut de la ligne suivante) : rendre la main sans
         * consommer laisse la boucle du corps reparser le statement suivant et
         * emettre SA propre erreur (les N sont rapportees). Le collapse
         *  reste actif au scan de widgets (g_in_dsl_body_stmt=false). */
        return;
    }

    while (parser.current.type != TOKEN_EOF) {
        switch (parser.current.type) {
            case TOKEN_PROCEDURE:
            case TOKEN_FONCTION:
            case TOKEN_SI:
            case TOKEN_POUR:
            case TOKEN_TANTQUE:
            case TOKEN_BOUCLE:
            case TOKEN_SELON:
            case TOKEN_RENVOYER:
            case TOKEN_RETOUR:
            case TOKEN_CLASSE:
            /* TOKEN_FIN est un block-closer : on s'arrete dessus pour
             * laisser le parser parent (compile_event_block_body, body
             * d'une PROCEDURE/CLASSE/etc.) le consommer proprement.
             * Sans ca, une erreur dans le body fait que synchronize skip
             * tous les FIN imbriques jusqu'au prochain keyword statement
             * → le parent perd le compte de ses scopes. Cf flood
             * "Construction inconnue dans le body de champ" sur le code
             * top-level apres une typo dans une PROCEDURE Clic. */
            case TOKEN_FIN:
            /*  : FAIRE / SINON / ENFIN sont des clause-closers
             * pour QUAND EXCEPTION DANS (et FAIRE / SINON pour les
             * boucles / SI). Sans s'arreter dessus, une erreur dans le
             * body T saute par-dessus FAIRE et atterrit sur le FIN du
             * bloc QUAND, declenchant un faux positif "Expected FAIRE"
             * + cascade. Memes considerations que TOKEN_FIN ci-dessus :
             * c'est un boundary structurel, le parser parent doit le
             * voir pour fermer ses scopes proprement. */
            case TOKEN_FAIRE:
            case TOKEN_SINON:
            case TOKEN_ENFIN:
                return;
            default:;
        }
        advance_token();
        if (parser.current.type == TOKEN_MULTILINE_STRING) absorbedMultiline = true;

        /*  — newline-stop pendant le skip, MAIS uniquement a
         * profondeur de brackets 0 (statement plat). Cas cible : une erreur
         * a ete emise AU MILIEU d'une ligne (crossedNewline=false a l'entree,
         * donc l'early-return ci-dessus n'a pas tire) sur un statement plat
         * — p.ex. `x = a + ::b` ou `x = a @ b`. Sans ca, le skip historique
         * avale jusqu'au prochain keyword et engloutit la declaration suivante
         * -> erreur fantome "variable inconnue" sur une variable pourtant
         * bien declaree. On saute donc le reste de la ligne fautive puis on
         * rend la main a la frontiere de ligne, ou la boucle appelante reparse
         * proprement le statement suivant.
         *
         * A profondeur >0 (dans un `(...)` / `{...}` / `[...]` multi-ligne
         * legitime : appel etale, litteral tableau/JSON, liste de parametres),
         * on NE stoppe PAS sur la newline interne — ce serait au milieu d'une
         * construction et produirait des fragments parasites. La profondeur est
         * celle vue par le PARSER (parser_effective_bracket_depth, relue apres
         * chaque advance) : elle suit une continuation qui ouvre un bracket
         * pendant le skip et ne rend la main qu'une fois revenu a 0. */
        if (flatEntry
            && crossedNewline
            && !absorbedMultiline
            && parser_effective_bracket_depth() == 0
            && newlineStopAllowed) {
            return;
        }
    }
}

static void avec_member_access(void) {
    /* .member inside AVEC block — compiled as a standalone statement */
    consume(TOKEN_IDENTIFIER, E_SYNTAX_EXP_MEMBER_NAME_AFTER_DOT);
    ConstIdx name = identifier_constant(&parser.previous);

    /* Push AVEC target */
    emit_bytes(OP_GET_LOCAL, (uint8_t)avecSlots[avecDepth - 1]);

    if (match_token(TOKEN_EQUAL)) {
        /* .member = value — the crossedNewline check in parse_precedence
         * prevents infix DOT from chaining across lines inside AVEC. */
        expression();
        emit_const_op(OP_STRUCT_SET, name);
        emit_byte(OP_POP); /* discard SET result */
    } else if (check(TOKEN_LEFT_PAREN)) {
        /* .method(args) */
        advance_token(); /* consume '(' */
        uint8_t argCount = argument_list();
        emit_const_op_b(OP_INVOKE, name, argCount);
        emit_byte(OP_POP); /* discard return value */
    } else {
        /* .member as standalone read — unusual but not an error */
        emit_const_op(OP_STRUCT_GET, name);
        emit_byte(OP_POP);
    }
}

/* Reconnait `EXIT SWITCH` (alias EN canon de SORTIR SELON) en lookahead,
 * sans transformer `Exit` en keyword scanner (collision avec des
 * identifiants utilisateur legitimes : PROCEDURE Exit, etc.).
 * Retourne true et emet le break-switch si le pattern matche, false
 * sinon (sans consommer aucun token). */
static bool try_match_exit_switch(void) {
    if (parser.current.type != TOKEN_IDENTIFIER ||
        parser.current.length != 4) return false;
    const char* s = parser.current.start;
    if (!((s[0] == 'E' || s[0] == 'e') &&
          (s[1] == 'X' || s[1] == 'x') &&
          (s[2] == 'I' || s[2] == 'i') &&
          (s[3] == 'T' || s[3] == 't'))) return false;

    Scanner saved      = parser.scanner;
    Token   savedCur   = parser.current;
    Token   savedPrev  = parser.previous;
    bool    savedXNL   = crossedNewline;
    Token   exitToken  = parser.current;
    advance_token();
    if (check(TOKEN_SELON)) {
        advance_token();
        emit_break_switch_at(exitToken);
        return true;
    }
    /* Rollback : Exit n'etait pas suivi de SWITCH. */
    parser.scanner   = saved;
    parser.current   = savedCur;
    parser.previous  = savedPrev;
    crossedNewline   = savedXNL;
    return false;
}

/* True si le TokenType est un keyword reserve susceptible d'apparaitre
 * fautivement en debut de declaration (`<kw> est un entier`).
 *
 *  : extension aux TOKEN_TYPE des 4 categories verrouillees comme
 * noms d'identifiant (registry source de verite, determinisme du langage) :
 *   - Scalaires primitifs (chaine, entier, reel, monetaire, numerique,
 *     caractere, booleen, buffer, octet, octets)
 *   - Composites structurels (tableau, structure, enumeration, combinaison,
 *     liste, pile, file, associatif)
 *   - Modificateurs (fixe, dynamique, par, sans, signe)
 *   - Declarateurs OOP/proc (classe, interface, procedure, fonction)
 * Les types valeur datetime (date, heure, dateheure, duree) et les types
 * valeur (json, uuid) restent LIBRES comme noms — alignement sur le
 * canon. Idem types registry (httpRequete,
 * chrono, ...) et types user (Structure/Classe user-declared). */
static bool tokentype_is_reserved_keyword(TokenType t) {
    switch (t) {
        case TOKEN_SI: case TOKEN_ALORS: case TOKEN_SINON: case TOKEN_FIN:
        case TOKEN_POUR: case TOKEN_A: case TOKEN_A_SC:
        case TOKEN_PAS: case TOKEN_PAS_SC: case TOKEN_TOUT:
        case TOKEN_DE: case TOKEN_DANS: case TOKEN_DANS_SC:
        case TOKEN_TANTQUE: case TOKEN_BOUCLE: case TOKEN_FAIRE:
        case TOKEN_SELON: case TOKEN_CAS: case TOKEN_AUTRE:
        case TOKEN_SORTIR: case TOKEN_CONTINUER:
        case TOKEN_RENVOYER: case TOKEN_RETOUR: case TOKEN_AVEC:
        case TOKEN_QUAND: case TOKEN_EXCEPTION:
        case TOKEN_ET: case TOKEN_ET_SC: case TOKEN_OU: case TOKEN_OU_SC:
        /* Keywords reserves scanner-only — semantique a implementer mais nom
         * deja verrouille pour eviter une migration douloureuse plus tard
         * (portee globale variable/procedure, namespace OWL). TOKEN_OBJET
         * et TOKEN_ANCETRE sont desormais operationnels (parselets dedies)
         * mais restent reserves comme noms d'identifiants utilisateur. */
        case TOKEN_OBJET: case TOKEN_ANCETRE:
        case TOKEN_MOIMEME:
        case TOKEN_MONCHAMP: case TOKEN_MAFENETRE:
        case TOKEN_LOCAL: case TOKEN_GLOBAL: case TOKEN_GLOBALE:
        case TOKEN_OWL_RESERVED:
        /*  : scalaires primitifs. */
        case TOKEN_CHAINE: case TOKEN_ENTIER: case TOKEN_REEL:
        case TOKEN_MONETAIRE: case TOKEN_NUMERIQUE: case TOKEN_CARACTERE:
        case TOKEN_BOOLEEN: case TOKEN_BUFFER:
        /*  : composites structurels. */
        case TOKEN_TABLEAU: case TOKEN_STRUCTURE: case TOKEN_ENUMERATION:
        case TOKEN_COMBINAISON: case TOKEN_LISTE: case TOKEN_PILE:
        case TOKEN_FILE: case TOKEN_ASSOCIATIF:
        /*  : modificateurs. */
        case TOKEN_FIXE: case TOKEN_DYNAMIQUE: case TOKEN_PAR:
        case TOKEN_SANS: case TOKEN_SIGNE:
        /*  : declarateurs OOP/proc. */
        case TOKEN_CLASSE: case TOKEN_INTERFACE:
        case TOKEN_PROCEDURE: case TOKEN_FONCTION:
            return true;
        default:
            return false;
    }
}

/* Forme canon visuelle d'un token reserve pour message d'erreur.
 *
 * Deux strategies selon la categorie du token :
 *
 *  1. Structurels / control-flow (SI, FIN, POUR, A, ...) : upper-case du
 *     texte source. Preserve `to`->`TO`, `for`->`FOR`, `if`->`IF`. Les
 *     formes accentuees de TOKEN_A (`à`/`À`) sont normalisees vers `A`
 *     ASCII (canon).
 *
 *  2.  — Types et declarateurs (TOKEN_CHAINE, TOKEN_TABLEAU, ...) :
 *     affichage de la forme canon registry FR (avec accents et casse
 *     correcte : `chaîne`, `entier`, `réel`, `monétaire`, `numérique`,
 *     `caractère`, `booléen`, `tableau`, `structure`, ...). On NE fait
 *     PAS de uppercase ici : ce serait non canonique (`CHAÎNE` au lieu
 *     de `chaîne`) et incoherent avec ce que le registry expose comme
 *     forme canonique des types primitifs.
 *
 * Buffer interne 32B suffisant pour tous les cas. */
static const char* keyword_canonical_uppercase_for(Token tok, char* buf, int bufsz) {
    /*  : forme canon registry FR pour les TOKEN_TYPE reserves.
     * Mappage direct du tokentype vers la forme canonique attendue
     * (cohérent avec docs/public_documentation/10_conventions_de_code.md
     * et avec la sortie du formatter sur ces tokens). */
    const char* canon = NULL;
    switch (tok.type) {
        /* Scalaires primitifs. */
        case TOKEN_CHAINE:     canon = "cha\xc3\xaene";        break;  /* chaîne */
        case TOKEN_ENTIER:     canon = "entier";               break;
        case TOKEN_REEL:       canon = "r\xc3\xa9" "el";       break;  /* réel */
        case TOKEN_MONETAIRE:  canon = "mon\xc3\xa9taire";     break;  /* monétaire */
        case TOKEN_NUMERIQUE:  canon = "num\xc3\xa9rique";     break;  /* numérique */
        case TOKEN_CARACTERE:  canon = "caract\xc3\xa8re";     break;  /* caractère */
        case TOKEN_BOOLEEN:    canon = "bool\xc3\xa9" "en";    break;  /* booléen */
        case TOKEN_BUFFER:     canon = "buffer";               break;
        /* Composites structurels. */
        case TOKEN_TABLEAU:    canon = "tableau";              break;
        case TOKEN_STRUCTURE:  canon = "structure";            break;
        case TOKEN_ENUMERATION:canon = "\xc3\xa9num\xc3\xa9ration"; break; /* énumération */
        case TOKEN_COMBINAISON:canon = "combinaison";          break;
        case TOKEN_LISTE:      canon = "liste";                break;
        case TOKEN_PILE:       canon = "pile";                 break;
        case TOKEN_FILE:       canon = "file";                 break;
        case TOKEN_ASSOCIATIF: canon = "associatif";           break;
        /* Modificateurs. */
        case TOKEN_FIXE:       canon = "fixe";                 break;
        case TOKEN_DYNAMIQUE:  canon = "dynamique";            break;
        case TOKEN_PAR:        canon = "par";                  break;
        case TOKEN_SANS:       canon = "sans";                 break;
        case TOKEN_SIGNE:      canon = "signe";                break;
        /* Declarateurs OOP/proc. */
        case TOKEN_CLASSE:     canon = "classe";               break;
        case TOKEN_INTERFACE:  canon = "interface";            break;
        case TOKEN_PROCEDURE:  canon = "procedure";            break;
        case TOKEN_FONCTION:   canon = "fonction";             break;
        default: break;
    }
    if (canon != NULL) {
        snprintf(buf, bufsz, "%s", canon);
        return buf;
    }

    /* Cas special : forme accentuee de TOKEN_A → canon ASCII `A`. */
    if (tok.type == TOKEN_A && tok.length >= 2 &&
        (unsigned char)tok.start[0] == 0xC3 &&
        ((unsigned char)tok.start[1] == 0x80 ||   /* À */
         (unsigned char)tok.start[1] == 0xA0 ||   /* à */
         (unsigned char)tok.start[1] == 0x82 ||   /* Â */
         (unsigned char)tok.start[1] == 0xA2)) {  /* â */
        snprintf(buf, bufsz, "A");
        return buf;
    }
    int n = tok.length < bufsz - 1 ? tok.length : bufsz - 1;
    for (int i = 0; i < n; i++) {
        unsigned char c = (unsigned char)tok.start[i];
        buf[i] = (c < 0x80) ? (char)toupper(c) : (char)c;
    }
    buf[n] = '\0';
    return buf;
}

/* Position parametre : si le token courant est un keyword reserve (ex `a`/`à`,
 * `POUR`, `SI`...), emet le message dedie "mot reserve" plutot que le generique
 * "Expected parameter name". Ne consomme rien — le caller fait son consume()
 * habituel ensuite (qui produira son erreur generique si jamais ce n'etait pas
 * un keyword, vrai cas non-identifiant).
 *
 *  : les TOKEN_TYPE libres (date, heure, dateheure, duree, json,
 * uuid) sont autorises comme noms de parametre. On les demote en IDENTIFIER
 * AVANT le check reserved pour que le consume(TOKEN_IDENTIFIER) du caller
 * les accepte. */
static bool reject_keyword_as_param_name(void) {
    if (demote_free_type_to_identifier()) return false;
    /*  : un identifiant qui normalise (casse+accent) vers un
     * declarateur GUI est scanne en token dedie (`libellé`->TOKEN_LIBELLE,
     * `bouton`->TOKEN_BOUTON, `table`->TOKEN_TABLE, ...). En position de NOM
     * DE PARAMETRE c'est un identifiant ordinaire — meme demotion que le nom
     * de champ de structure pour ne pas le refuser a tort. */
    if (demote_gui_declarator_to_identifier()) return false;
    if (!tokentype_is_reserved_keyword(parser.current.type)) return false;
    char kwname[32];
    keyword_canonical_uppercase_for(parser.current, kwname, sizeof(kwname));
    owl_emit_error_current(E_SEM_KEYWORD_AS_VAR_NAME, "name", kwname, NULL);
    return true;
}

/*  : TOKEN_TYPE non-reserves libres comme noms d'identifiant.
 * Le scanner emet ces TOKEN_TYPE en table de lookup (TOKEN_DATE, TOKEN_DUREE,
 * etc.) mais le canon les autorise comme noms de variable/parametre/champ
 * (`duree est une durée`, `date est une date`). Helper utilise par les paths
 * qui attendent normalement TOKEN_IDENTIFIER en position de nom. */
static bool tokentype_is_free_value_type(TokenType t) {
    switch (t) {
        case TOKEN_DATE:
        case TOKEN_HEURE:
        case TOKEN_DATEHEURE:
        case TOKEN_DUREE:
        case TOKEN_JSON_KW:
        case TOKEN_UUID:
            return true;
        default:
            return false;
    }
}

/*  : les noms de type widget (Fenetre, Libelle, Bouton, Saisie, Table,
 * Colonne) sont scannes en tokens dedies (TOKEN_FENETRE, ...) et non en
 * TOKEN_IDENTIFIER. Utilises comme nom de variable en tete de declaration ils
 * heurtent le garde E_SYNTAX_WIDGET_TOKEN_AT_STATEMENT_START (Fenetre/Libelle/
 * Bouton/Saisie/Table) ou degenerent en « Expression attendue » (Colonne, sans
 * garde ni parselet prefix). On les autorise comme noms de variable au meme
 * titre que les types-registry scannes en identifiant (image, Tenseur) —
 * coherence d'acceptation .
 *  : set complete avec Etat (TOKEN_ETAT) et Conteneur (TOKEN_CONTENEUR),
 * les 2 seuls declarateurs GUI a token dedie qui manquaient (asymetrie ,
 * pas une decision). Le set couvre desormais les 8 declarateurs a token dedie et
 * s'aligne sur tokentype_is_gui_declarator. La demotion n'agit qu'en
 * position d'expression (parse_precedence), jamais sur le type apres `est un[e]`
 * — les block-openers DSL `X est un Etat` / `X est un Conteneur` restent intacts. */
static bool tokentype_is_widget_keyword(TokenType t) {
    switch (t) {
        case TOKEN_FENETRE:
        case TOKEN_LIBELLE:
        case TOKEN_BOUTON:
        case TOKEN_SAISIE:
        case TOKEN_TABLE:
        case TOKEN_COLONNE:
        case TOKEN_CONTENEUR:
        case TOKEN_ETAT:
            return true;
        default:
            return false;
    }
}

/*  : demote un widget-keyword-token courant en TOKEN_IDENTIFIER (le
 * texte source est preserve, seul le type change). Appele en position
 * d'EXPRESSION (lecture de variable) pour que le path identifier resolve la
 * variable declaree sous ce nom. Les parsers de la DSL widget consomment ces
 * tokens via check()/advance_token() AVANT tout appel a expression() : quand
 * on atteint ici avec un widget-token, il est genuinement lu comme une valeur
 * -> variable. Si aucune variable de ce nom n'existe, le message « Variable
 * inconnue » sera emis, plus parlant que « Expression attendue ». Miroir de
 * demote_free_type_to_identifier. Ne consomme rien. */
static bool demote_widget_keyword_to_identifier(void) {
    if (!tokentype_is_widget_keyword(parser.current.type)) return false;
    parser.current.type = TOKEN_IDENTIFIER;
    return true;
}

/*  : declarateurs GUI complets scannes en tokens dedies (Fenetre,
 * Libelle, Bouton, Saisie, Table, Colonne, Conteneur, Etat). tokentype_is_
 * widget_keyword n'en couvre que 6 pour la position d'EXPRESSION ;
 * la position de NOM DE CHAMP de structure les accepte tous les 8 comme
 * identifiants ordinaires. Predicat dedie a cette position (mot-cle contextuel,
 * invariant 6.5) pour ne pas elargir la demotion d'expression a Etat/Conteneur
 * (autre discussion). */
static bool tokentype_is_gui_declarator(TokenType t) {
    switch (t) {
        case TOKEN_FENETRE:
        case TOKEN_LIBELLE:
        case TOKEN_BOUTON:
        case TOKEN_SAISIE:
        case TOKEN_TABLE:
        case TOKEN_COLONNE:
        case TOKEN_CONTENEUR:
        case TOKEN_ETAT:
            return true;
        default:
            return false;
    }
}

/*  : demote un declarateur GUI courant en TOKEN_IDENTIFIER en position
 * de nom de champ de structure (le texte source est preserve, seul le type
 * change). `Libelle`/`Etat` sont des mots extremement courants en donnees
 * metier FR ; le canon les accepte comme nom de champ. NE demote PAS les vrais
 * mots-cles de controle (SI/POUR/FIN...) : le controle reserved reste. Miroir
 * de demote_free_type_to_identifier. Ne consomme rien. */
static bool demote_gui_declarator_to_identifier(void) {
    if (!tokentype_is_gui_declarator(parser.current.type)) return false;
    parser.current.type = TOKEN_IDENTIFIER;
    return true;
}

/*  : si le token courant est un TOKEN_TYPE libre (date, heure,
 * dateheure, duree, json, uuid), le "demote" en TOKEN_IDENTIFIER pour que les
 * paths qui attendent un identifier classique (consume(TOKEN_IDENTIFIER),
 * check(TOKEN_IDENTIFIER), ...) le reconnaissent comme tel. Le texte source
 * du token n'est pas modifie — seul son type est ajuste. Renvoie true si une
 * demotion a eu lieu. Ne consomme rien. */
static bool demote_free_type_to_identifier(void) {
    if (!tokentype_is_free_value_type(parser.current.type)) return false;
    parser.current.type = TOKEN_IDENTIFIER;
    return true;
}

/*  : `delete` est tokenise TOKEN_LIBERER par le scanner (alias OOP
 * de Liberer/Free). Mais `delete` est aussi le nameEN de la native FR
 * `Supprime`. En position d'expression, TOKEN_LIBERER n'a pas de parselet
 * prefix -> `x = Delete(t, 1)` echoue sur « Expression attendue » alors que
 * `Supprime(...)` compile.
 *
 * Discrimination par contexte : la liberation OOP est `delete oVar` (un
 * identifiant suit, jamais `(`) ; l'appel native est `Delete(args)` (un `(`
 * suit immediatement). Si le lexeme courant resout une native (lookup
 * bilingue case+accent insensible) ET que le token suivant est `(`, on
 * demote en TOKEN_IDENTIFIER pour router vers le path d'appel native, qui
 * substitue deja le canonical (Delete -> Supprime). `Free`/`liberer` ne
 * resolvent aucune native -> jamais demotes (forme OOP preservee). */
static bool demote_liberer_native_call_to_identifier(void) {
    if (parser.current.type != TOKEN_LIBERER) return false;

    char probe[128];
    int n = parser.current.length < (int)sizeof(probe) - 1
                ? parser.current.length : (int)sizeof(probe) - 1;
    memcpy(probe, parser.current.start, n);
    probe[n] = '\0';
    if (owl_registry_find(probe) == NULL) return false;

    /* Peek non-destructif du token suivant : doit etre `(`. */
    Scanner savedScanner = parser.scanner;
    Token   savedCur     = parser.current;
    Token   savedPrev    = parser.previous;
    bool    savedXNL     = crossedNewline;
    advance_token();
    bool isCall = check(TOKEN_LEFT_PAREN);
    parser.scanner  = savedScanner;
    parser.current  = savedCur;
    parser.previous = savedPrev;
    crossedNewline  = savedXNL;
    if (!isCall) return false;

    parser.current.type = TOKEN_IDENTIFIER;
    return true;
}

/* Detecte `<keyword> est/sont un/une ...` — tentative d'utiliser un mot-cle
 * comme nom de variable. Renvoie true et remplit `out` avec le canon
 * UPPERCASE si on est en presence d'une telle declaration, false sinon.
 * Ne consomme aucun token (peek-only). */
static bool detect_keyword_as_variable(char* out, int outsz) {
    if (!tokentype_is_reserved_keyword(parser.current.type)) return false;
    Token     savedTok     = parser.current;
    Scanner   savedScanner = parser.scanner;
    Token     savedCur     = parser.current;
    Token     savedPrev    = parser.previous;
    bool      savedXNL     = crossedNewline;
    advance_token();
    bool isDecl = check(TOKEN_EST) || check(TOKEN_SONT);
    parser.scanner  = savedScanner;
    parser.current  = savedCur;
    parser.previous = savedPrev;
    crossedNewline  = savedXNL;
    if (!isDecl) return false;
    keyword_canonical_uppercase_for(savedTok, out, outsz);
    return true;
}

/*  — variante groupee de detect_keyword_as_variable : dans une
 * declaration groupee `nom1, nom2, ... est un/sont des <type>`, un des noms
 * est un mot-cle reserve (`a, b est un entier` en tete ; `n, a, cpt est un
 * entier` au milieu ; `n, objet, cpt est un entier` generique). Le chemin
 * mono-decl ne matche pas (le mot-cle est suivi d'une virgule, pas de EST) et
 * le chemin multi-decl standard exige un IDENTIFIER a chaque position -> il
 * echoue et produit une cascade trompeuse (« Expression attendue » en tete,
 * « 'n' variable inconnue » plus loin). On peek le motif : liste de noms
 * separes par virgules, ou au moins un slot est un mot-cle reserve, terminee
 * par EST/SONT. Si match, `outTok` recoit le PREMIER mot-cle fautif (position
 * = sa colonne source) et `out` sa forme canon. Peek non destructif : etat
 * parser/scanner restaure dans tous les cas. */
static bool detect_keyword_in_grouped_decl(char* out, int outsz, Token* outTok) {
    Scanner savedScanner = parser.scanner;
    Token   savedCur     = parser.current;
    Token   savedPrev    = parser.previous;
    bool    savedXNL     = crossedNewline;

    Token firstKeyword = parser.current;
    bool  haveKeyword  = false;
    bool  sawComma     = false;
    bool  ok           = true;

    for (;;) {
        if (check(TOKEN_IDENTIFIER)) {
            advance_token();
        } else if (tokentype_is_reserved_keyword(parser.current.type)) {
            if (!haveKeyword) { firstKeyword = parser.current; haveKeyword = true; }
            advance_token();
        } else {
            ok = false;   /* slot non nommable -> pas une decl groupee */
            break;
        }
        if (check(TOKEN_COMMA)) {
            sawComma = true;
            advance_token();
            continue;
        }
        break;
    }

    bool isDecl = ok && sawComma && haveKeyword
               && (check(TOKEN_EST) || check(TOKEN_SONT));

    parser.scanner  = savedScanner;
    parser.current  = savedCur;
    parser.previous = savedPrev;
    crossedNewline  = savedXNL;

    if (!isDecl) return false;
    keyword_canonical_uppercase_for(firstKeyword, out, outsz);
    *outTok = firstKeyword;
    return true;
}

/*  — le lexeme du token courant commence-t-il comme un identifiant
 * (lettre / '_' / octet UTF-8 >= 0x80) ? Vrai pour les identifiants ET les
 * mots-cles (ETAT, FENETRE, POUR...), faux pour les operateurs/nombres. Sert
 * a reconnaitre les segments d'un nom d'element decoupe par le tiret, y
 * compris quand un segment scanne comme mot-cle (`ETAT-Rap` -> TOKEN_ETAT). */
static bool current_token_is_word_like(void) {
    if (parser.current.length <= 0) return false;
    unsigned char c = (unsigned char)parser.current.start[0];
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
        || c == '_' || c >= 0x80;
}

/*  — detecte une tentative de declaration d'element DSL dont le nom
 * contient un tiret : `cl-Tot est une Classe`. Le scanner decoupe `cl-Tot` en
 * IDENT '-' IDENT (le '-' est l'operateur moins), donc sans detection dediee
 * le compilo part en chemin expression et emet une cascade cryptique. On peek
 * le motif WORD (- WORD)+ EST/SONT [a/an] <declarateur> (WORD = identifiant ou
 * mot-cle, cf. `ETAT-Rap` dont le 1er segment scanne en TOKEN_ETAT) ; le
 * declarateur en fin est ce qui evite le faux positif sur une vraie
 * soustraction top-level (`nX - nY` sans `est un <Type>` derriere ne matche
 * pas). Si match, reconstitue le nom depuis la source (tokens contigus) dans
 * `out` et renseigne `outNameTok` (1er segment, pour la position). Peek non
 * destructif : etat parser/scanner restaure dans tous les cas. */
static bool detect_hyphen_in_element_name(char* out, int outsz, Token* outNameTok) {
    if (!current_token_is_word_like()) return false;

    Scanner savedScanner = parser.scanner;
    Token   savedCur     = parser.current;
    Token   savedPrev    = parser.previous;
    bool    savedXNL     = crossedNewline;

    Token       firstTok  = parser.current;
    const char* spanStart = firstTok.start;
    const char* spanEnd   = firstTok.start + firstTok.length;

    advance_token();  /* consomme le 1er segment */

    bool sawHyphen = false;
    while (check(TOKEN_MINUS) || check(TOKEN_MINUS_MINUS)) {
        advance_token();  /* consomme '-' ou '--' */
        if (!current_token_is_word_like()) {
            break;  /* pas un segment de nom derriere le tiret */
        }
        sawHyphen = true;
        spanEnd = parser.current.start + parser.current.length;
        advance_token();  /* consomme le segment */
    }

    bool match = false;
    if (sawHyphen && (check(TOKEN_EST) || check(TOKEN_SONT))) {
        advance_token();          /* consomme EST/SONT */
        consume_en_a_an_filler(); /* copule EN : `is a/an <Type>` */
        TokenType t = parser.current.type;
        match = (t == TOKEN_CLASSE || t == TOKEN_FENETRE || t == TOKEN_ETAT
              || t == TOKEN_STRUCTURE || t == TOKEN_INTERFACE
              || t == TOKEN_ENUMERATION || t == TOKEN_COMBINAISON
              || t == TOKEN_LIBELLE || t == TOKEN_BOUTON
              || t == TOKEN_SAISIE || t == TOKEN_TABLE);
    }

    parser.scanner  = savedScanner;
    parser.current  = savedCur;
    parser.previous = savedPrev;
    crossedNewline  = savedXNL;

    if (!match) return false;

    int len = (int)(spanEnd - spanStart);
    if (len <= 0 || len >= outsz) return false;  /* garde-fou buffer */
    memcpy(out, spanStart, (size_t)len);
    out[len] = '\0';
    *outNameTok = firstTok;
    return true;
}

static void declaration(void) {
    /* Verrou anti-keyword en position de declaration : `a est un entier`,
     * `POUR est un entier`, etc. Sans ca le routing par statement() partirait
     * dans le path POUR/SI/expression_statement et produirait un message
     * generique opaque. Apres detection, on rebascule en panic mode jusqu'a
     * EOF — c'est volontairement coupant : les references collaterales au
     * keyword fautif sur les lignes suivantes (typiquement `Trace(POUR)` qui
     * essayait de logger la valeur supposee de la variable inexistante)
     * produiraient sinon des erreurs en cascade. */
    {
        char kwname[32];
        if (detect_keyword_as_variable(kwname, sizeof(kwname))) {
            owl_emit_error_current(E_SEM_KEYWORD_AS_VAR_NAME,
                                   "name", kwname,
                                   NULL);
            while (parser.current.type != TOKEN_EOF) advance_token();
            return;
        }
    }

    /*  — meme verrou pour une declaration GROUPEE dont un des noms est
     * un mot-cle reserve (`a, b est un entier`, `n, a, cpt est un entier`).
     * Doit preceder le dispatch IDENTIFIER / multi-decl : ce dernier exige un
     * IDENTIFIER a chaque position et degenere sinon en cascade trompeuse.
     * Meme resync coupant (jusqu'a EOF) que le verrou mono : une seule erreur
     * propre, nommant le mot fautif a sa colonne source. */
    {
        char  kwname[32];
        Token kwTok;
        if (detect_keyword_in_grouped_decl(kwname, sizeof(kwname), &kwTok)) {
            owl_emit_error_at(&kwTok, E_SEM_KEYWORD_AS_VAR_NAME,
                              "name", kwname,
                              NULL);
            while (parser.current.type != TOKEN_EOF) advance_token();
            return;
        }
    }

    /*  — nom d'element DSL avec tiret (`cl-Tot est une Classe`). Doit
     * preceder tout dispatch CLASSE/FENETRE/ETAT : le tiret casse l'adjacence
     * IDENT-EST attendue par ces gardes, donc sans interception ici le parse
     * degenere en cascade cryptique. Meme resync coupant (jusqu'a EOF) que le
     * verrou keyword-as-var : une seule erreur propre, pas de bruit collateral. */
    {
        char elemName[128];
        Token nameTok;
        if (detect_hyphen_in_element_name(elemName, sizeof(elemName), &nameTok)) {
            owl_emit_error_at(&nameTok, E_SEM_INVALID_ELEMENT_NAME,
                              "name", elemName,
                              NULL);
            while (parser.current.type != TOKEN_EOF) advance_token();
            return;
        }
    }

    /*  — bascule de portee top-level (hors classe) : GLOBAL / LOCAL
     * seuls en tete de declaration basculent le mode des declarations qui
     * SUIVENT (collant, alternable). GLOBAL = promotion (defaut), LOCAL =
     * confinement au flux top-level. N'a d'effet qu'a scopeDepth 0 : dans une
     * procedure/fonction (scopeDepth > 0) le mot-cle est redondant et consomme
     * sans effet. Place APRES detect_keyword_as_variable : `GLOBAL est un ...`
     * (tentative de nom de variable) reste rejete par le message dedie. Les
     * corps de classe ne passent pas par declaration() : GLOBAL/GLOBALE y
     * gardent leur semantique de membre/methode statique. */
    if (check(TOKEN_GLOBAL) || check(TOKEN_LOCAL)) {
        bool toLocal = check(TOKEN_LOCAL);
        advance_token();  /* consomme GLOBAL / LOCAL */
        if (current->scopeDepth == 0) {
            g_toplevel_confine = toLocal;
        }
        if (parser.panicMode) synchronize();
        return;
    }

    /*  : TOKEN_TYPE libres (date, heure, dateheure, duree, json, uuid)
     * autorises comme noms d'identifiant. Le scanner les emet en TOKEN_<type>
     * via sa table de lookup, mais le canon les considere libres comme noms
     * de variable. Si on detecte un tel token suivi de EST/SONT en tete de
     * declaration, on le "demote" en TOKEN_IDENTIFIER pour que le routing
     * standard (path IDENTIFIER -> declaration de variable) puisse l'attraper. */
    if (tokentype_is_free_value_type(parser.current.type)) {
        Scanner   savedScanner = parser.scanner;
        Token     savedCur     = parser.current;
        Token     savedPrev    = parser.previous;
        bool      savedXNL     = crossedNewline;
        advance_token();
        bool isDecl = check(TOKEN_EST) || check(TOKEN_SONT);
        parser.scanner  = savedScanner;
        parser.current  = savedCur;
        parser.previous = savedPrev;
        crossedNewline  = savedXNL;
        if (isDecl) demote_free_type_to_identifier();
    }

    /*  : nom de type widget (Fenetre, Libelle, Bouton, Saisie, Table,
     * Colonne) en tete de statement. Le scanner les emet en TOKEN_<widget> ;
     * sans interception ils heurtent le garde widget-token (plus bas dans
     * declaration()) ou « Expression attendue » (Colonne). On les demote en
     * TOKEN_IDENTIFIER UNIQUEMENT quand ils sont immediatement suivis de
     * EST/SONT : c'est une declaration de variable `<nom> est un/une <type>`,
     * exactement comme les types-registry (image, Tenseur). Un widget-token
     * NON suivi de EST/SONT garde son comportement actuel (garde ou
     * statement()), preservant la DSL widget legitime. Miroir du peek
     * free-type ci-dessus. */
    if (tokentype_is_widget_keyword(parser.current.type)) {
        Scanner savedScanner = parser.scanner;
        Token   savedCur     = parser.current;
        Token   savedPrev    = parser.previous;
        bool    savedXNL     = crossedNewline;
        advance_token();
        bool isDecl = check(TOKEN_EST) || check(TOKEN_SONT);
        /*  : widget-kind en TETE d'une liste multi-var
         * `Conteneur, cpt sont des entiers`. Le peek EST/SONT direct ne matche
         * pas (une virgule suit le widget), donc sans ca le token n'est jamais
         * demote et le routing IDENTIFIER en aval rate toute la declaration. On
         * parcourt la liste `, (ident|widget-kind)` et on n'accepte la demotion
         * que si elle se termine par SONT/EST : pattern non ambigu (aucune DSL
         * widget ne finit une liste virgulee par SONT/EST), meme ensemble de
         * tokens que le single-var. */
        if (!isDecl && check(TOKEN_COMMA)) {
            bool listOk = true;
            while (check(TOKEN_COMMA)) {
                advance_token(); /* , */
                if (!check(TOKEN_IDENTIFIER)
                    && !tokentype_is_widget_keyword(parser.current.type)) {
                    listOk = false;
                    break;
                }
                advance_token(); /* nom */
            }
            if (listOk && (check(TOKEN_SONT) || check(TOKEN_EST))) {
                isDecl = true;
            }
        }
        parser.scanner  = savedScanner;
        parser.current  = savedCur;
        parser.previous = savedPrev;
        crossedNewline  = savedXNL;
        if (isDecl) parser.current.type = TOKEN_IDENTIFIER;
    }

    /* Garde ENFIN body — doit être appliquée AVANT le routing IDENTIFIER de
     * declaration() (qui shunte statement() pour les identifiants comme
     * `ExceptionDéclenche(...)`). Couvre RENVOYER/RETOUR/SORTIR/CONTINUER/
     * EXCEPTION (keywords) ET ExceptionDéclenche/ExceptionThrow (identifier). */
    if (enfin_gate_reject_current_statement()) {
        return;
    }

    /* AVEC/WITH dot-prefix member access: .member = val / .method() */
    if (avecDepth > 0 && check(TOKEN_DOT)) {
        advance_token(); /* consume '.' */
        avec_member_access();
    } else if (try_match_exit_switch()) {
        /* `EXIT SWITCH` reconnu et emis. Rien d'autre a faire. */
    } else if (check(TOKEN_LEFT_PAREN)) {
        /* Check for multi-assign: (x, y) = Func()
         * Save complete parser state, peek ahead, restore. */
        Scanner savedScanner = parser.scanner;
        Token savedCurrent = parser.current;
        Token savedPrevious = parser.previous;
        bool savedCrossed = crossedNewline;

        advance_token(); /* consume ( */
        bool isMultiAssign = false;
        if (check(TOKEN_IDENTIFIER)) {
            advance_token(); /* first id */
            while (match_token(TOKEN_COMMA)) {
                if (!check(TOKEN_IDENTIFIER)) break;
                advance_token();
            }
            if (check(TOKEN_RIGHT_PAREN)) {
                advance_token(); /* ) */
                if (check(TOKEN_EQUAL)) {
                    isMultiAssign = true;
                }
            }
        }
        /* Restore complete parser state */
        parser.scanner = savedScanner;
        parser.current = savedCurrent;
        parser.previous = savedPrevious;
        crossedNewline = savedCrossed;

        if (isMultiAssign) {
            /* Parse: (var1, var2, ...) = expression
             * Strategy: parse vars, consume =, call __Unpack native
             * which takes the array + returns individual values via globals */
            advance_token(); /* consume ( */
            Token vars[16];
            int n = 0;
            do {
                if (!check(TOKEN_IDENTIFIER)) { owl_emit_error_at(&parser.previous, E_SYNTAX_EXPECTED_VAR_NAME); break; }
                advance_token();
                vars[n++] = parser.previous;
            } while (match_token(TOKEN_COMMA) && n < 16);
            consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_VAR_LIST);
            consume(TOKEN_EQUAL, E_SYNTAX_EXP_EQUAL_AFTER_VAR_LIST);
            expression(); /* Stack: [array] */

            /* Stack: [array]. Emit OP_ARRAY_UNPACK N which pushes N values. */
            emit_bytes(OP_ARRAY_UNPACK, (uint8_t)n);
            /* Stack: [v1, v2, ..., vN] -- assign in REVERSE order (last pushed = top) */
            for (int i = n - 1; i >= 0; i--) {
                int arg = resolve_local(current, &vars[i]);
                if (arg != -1) {
                    emit_bytes(OP_SET_LOCAL, (uint8_t)arg);
                } else {
                    ConstIdx nameConst = identifier_constant(&vars[i]);
                    emit_const_op(OP_SET_GLOBAL, nameConst);
                }
                emit_byte(OP_POP);
            }
        } else {
            /* Not multi-assign: already restored above, treat as expression */
            statement();
        }
    } else if (check(TOKEN_IDENTIFIER)
            || ((check(TOKEN_VRAI) || check(TOKEN_FAUX) || check(TOKEN_NUL))
                && /* peek pour distinguer 'Vrai est un booleen' (declaration
                    * shadowing constante) de 'Vrai' tout court (expression). */
                ({
                    Scanner _sn  = parser.scanner;
                    Token   _cu  = parser.current;
                    Token   _pr  = parser.previous;
                    bool    _cr  = crossedNewline;
                    advance_token();
                    bool _isDecl = check(TOKEN_EST) || check(TOKEN_SONT)
                                || check(TOKEN_COMMA);
                    parser.scanner   = _sn;
                    parser.current   = _cu;
                    parser.previous  = _pr;
                    crossedNewline   = _cr;
                    _isDecl;
                }))
            /*  — nom de SERVICE mot-cle : `<mot-cle> est un ServiceREST`.
             * Gate strict (peek confirme ServiceREST) pour ne PAS deborder hors
             * de cette position (un `PUBLIC est un entier` reste refuse). */
            || peek_leading_keyword_is_service_rest()) {
        advance_token();
        Token identTok = parser.previous;

        /* canon multi-declaration: `a, b, c sont des <type>` (or `are`).
         * Peek past `, ident, ident, ...` and dispatch to var_declaration_after_est
         * once per name, replaying the post-SONT token stream each time. */
        if (check(TOKEN_COMMA)) {
            Scanner peekScanner = parser.scanner;
            Token   peekCurrent = parser.current;
            Token   peekPrev    = parser.previous;
            bool    peekCrossed = crossedNewline;

            Token names[16];
            int nameCount = 0;
            names[nameCount++] = identTok;

            bool valid = true;
            while (check(TOKEN_COMMA)) {
                advance_token(); /* consume , */
                /*  : accepter un widget-kind (Etat/Report, Conteneur,
                 * Colonne...) comme nom en position non-initiale, comme le
                 * chemin single-var le fait deja (demotion keyword->variable,
                 * ). No-op si le token n'est pas un widget-kind ; si le
                 * peek multi-var echoue plus bas, l'etat parser est restaure
                 * (peekScanner) et la mutation de type est annulee. */
                demote_widget_keyword_to_identifier();
                if (!check(TOKEN_IDENTIFIER)) { valid = false; break; }
                advance_token();
                if (nameCount >= 16) {
                    owl_emit_error_at(&parser.previous, E_SYNTAX_TOO_MANY_NAMES_IN_MULTI_DECL);
                    valid = false;
                    break;
                }
                names[nameCount++] = parser.previous;
            }
            /* Require SONT (or EST for single-name edge case) after the list */
            if (valid && (check(TOKEN_SONT) || check(TOKEN_EST))) {
                advance_token(); /* consume SONT */

                /* Snapshot the scanner position right after SONT — this is the
                 * type spec we want to replay for each declared name. */
                Scanner afterSont     = parser.scanner;
                Token   afterCurrent  = parser.current;
                Token   afterPrev     = parser.previous;
                bool    afterCrossed  = crossedNewline;

                for (int i = 0; i < nameCount; i++) {
                    if (i > 0) {
                        /* Replay the type spec tokens for subsequent names */
                        parser.scanner   = afterSont;
                        parser.current   = afterCurrent;
                        parser.previous  = afterPrev;
                        crossedNewline   = afterCrossed;
                    }
                    /*  : idem chemin single-name — l'article EN `a`/`an`
                     * est consomme (re-joue par nom via le snapshot afterSont)
                     * avant le court-circuit STRUCTURE. No-op sans article. */
                    consume_en_a_an_filler();
                    if (check(TOKEN_STRUCTURE)) {
                        advance_token();
                        struct_declaration(names[i]);
                    } else {
                        var_declaration_after_est(names[i]);
                    }
                }
                return; /* done */
            }
            /* Not a valid multi-decl: restore state and fall through to
             * the normal single-ident assignment/expression handling. */
            parser.scanner  = peekScanner;
            parser.current  = peekCurrent;
            parser.previous = peekPrev;
            crossedNewline  = peekCrossed;
        }

        if (check(TOKEN_EST) || check(TOKEN_SONT)) {
            advance_token(); /* consume EST */

            /*  : consommer l'article EN `a`/`an` juste apres `is`,
             * AVANT le court-circuit STRUCTURE. Sans ca `MaStruct is a
             * Structure` laisse l'article polluer le check TOKEN_STRUCTURE ->
             * fallback var_declaration_after_est qui interprete `a Structure`
             * de travers. Miroir de la classe (consume au chemin dedie) et des
             * autres types (enum/combi/interface) geres via
             * var_declaration_after_est qui consomme deja l'article (14382).
             * No-op si pas d'article ; le var_declaration_after_est en aval
             * garde sa propre consommation devenue no-op. */
            consume_en_a_an_filler();
            if (check(TOKEN_STRUCTURE)) {
                advance_token(); /* consume STRUCTURE */
                struct_declaration(identTok);
            } else {
                var_declaration_after_est(identTok);
            }
        } else {
            /* Detect whether this statement is an assignment (`x = …`,
             * `x += …`, `x++`, `obj.f = …`, etc.). Assignments are
             * statements, not expressions: auto-print must stay silent
             * on them — otherwise a banal `POUR / compteur += 1 / FIN`
             * spams the notebook output. We snapshot enough parser state
             * to look ahead, decide, then let named_variable + infix
             * loop compile normally. */
            bool isAssign = false;
            {
                /* Peek at what follows the identifier (possibly through
                 * a dot chain like `obj.field.sub = ...`). */
                Scanner savedScanner   = parser.scanner;
                Token   savedCurrent   = parser.current;
                Token   savedPrevious  = parser.previous;
                bool    savedCrossed   = crossedNewline;
                /* Walk `.ident` / `..ident` / `[idx]` / `(call)` segments
                 * to reach the post-receiver token. Stop as soon as we
                 * see an assignment op or something that clearly isn't. */
                for (;;) {
                    if (check(TOKEN_EQUAL)        || check(TOKEN_PLUS_EQUAL)   ||
                        check(TOKEN_MINUS_EQUAL)  || check(TOKEN_STAR_EQUAL)   ||
                        check(TOKEN_SLASH_EQUAL)  || check(TOKEN_PERCENT_EQUAL)||
                        check(TOKEN_PLUS_PLUS)    || check(TOKEN_MINUS_MINUS)  ||
                        check(TOKEN_LESS_EQUAL) /* deep-copy assign <= */) {
                        isAssign = true;
                        break;
                    }
                    if (check(TOKEN_DOT) || check(TOKEN_DOUBLE_DOT)) {
                        advance_token();       /* '.' */
                        if (!check(TOKEN_IDENTIFIER)) break;
                        advance_token();       /* field name */
                        continue;
                    }
                    if (check(TOKEN_LEFT_BRACKET)) {
                        /* Skip `[...]` balanced. */
                        int depth = 0;
                        while (parser.current.type != TOKEN_EOF) {
                            if (check(TOKEN_LEFT_BRACKET))  depth++;
                            if (check(TOKEN_RIGHT_BRACKET)) { depth--; if (depth == 0) { advance_token(); break; } }
                            advance_token();
                        }
                        continue;
                    }
                    break; /* Anything else -> not an assignment. */
                }
                parser.scanner       = savedScanner;
                parser.current       = savedCurrent;
                parser.previous      = savedPrevious;
                crossedNewline       = savedCrossed;
            }

            int chunkStartBare = current_chunk()->count;
            Token firstBareTok = parser.previous;

            named_variable(parser.previous, true);

            while (get_rule(parser.current.type)->precedence > PREC_NONE) {
                advance_token();
                ParseFn infixRule = get_rule(parser.previous.type)->infix;
                if (infixRule == NULL) break;
                infixRule(true);
            }

            /* Une instruction-expression a tete d'identifiant qui n'est ni
             * une affectation ni un appel (bytecode = lectures pures seules)
             * ne fait rien d'utile — on la rejette. Exempt REPL mode.
             * Miroir du check dans expression_statement (branche des
             * statements sans identifiant de tete : litteraux, `(...)`). */
            if (!g_auto_print_expr && !isAssign &&
                !expr_stmt_has_effect(current_chunk(), chunkStartBare)) {
                /* Message dedie "il manque les ()" quand tout le statement
                 * est une reference nue a une fonction native. */
                int emitted = current_chunk()->count - chunkStartBare;
                bool barePattern = (emitted == bare_global_read_len() &&
                                    current_chunk()->code[chunkStartBare] == OP_GET_GLOBAL);
                const OwlNativeDef* d = barePattern
                    ? bare_identifier_as_native(&firstBareTok) : NULL;
                if (d != NULL) {
                    char nameBuf[128];
                    snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                             firstBareTok.length, firstBareTok.start);
                    owl_emit_error_at(&firstBareTok,
                                      E_SEM_BARE_NATIVE_REFERENCE,
                                      "name", nameBuf,
                                      NULL);
                } else {
                    owl_emit_error_at(&firstBareTok,
                                      E_SEM_INSTRUCTION_SANS_EFFET, NULL);
                }
            }

            /* Auto-print only on real expressions, never on assignments —
             * `x += 1` is a statement, not a value to show. */
            emit_byte((g_auto_print_expr && !isAssign) ? OP_PRINT : OP_POP);
        }
    } else if (match_token(TOKEN_PROCEDURE) || match_token(TOKEN_FONCTION)) {
        proc_declaration();
    } else if (check(TOKEN_FENETRE) || check(TOKEN_LIBELLE)
            || check(TOKEN_BOUTON)  || check(TOKEN_SAISIE)
            || check(TOKEN_TABLE)) {
        /* Phase G v2 : ces tokens ne sont jamais valides en debut de
         * statement. Ils suivent 'IDENT est un/une', dispatch via la
         * variable declaration. Si on les voit ici, c'est une syntaxe
         * obsolete (ancien DSL pre-fixed) ou une erreur. */
        const char* kind = check(TOKEN_FENETRE) ? "Fenetre"
                         : check(TOKEN_LIBELLE) ? "Libelle"
                         : check(TOKEN_BOUTON)  ? "Bouton"
                         : check(TOKEN_TABLE)   ? "Table"
                         : "Saisie";
        owl_emit_error_at(&parser.previous,
                          E_SYNTAX_WIDGET_TOKEN_AT_STATEMENT_START,
                          "kind", kind,
                          NULL);
        advance_token();
    } else {
        statement();
    }

    if (parser.panicMode) synchronize();
}

/* ================================================================
 * PUBLIC: COMPILE
 * ================================================================ */

/* Absorb a leading `PROCEDURE [name]([params]) [: returnType]` header into
 * the CURRENT function compiler (not as a sub-declaration). Called from
 * compile_impl when the source is in PROCEDURE form, e.g.
 *   Compile("PROCEDURE Foo(n est une chaine); Trace(n)")
 * After this helper returns, the body is parsed by the regular declaration
 * loop, and end_compiler produces a function whose arity + params match
 * the PROCEDURE header. Entry point used only by
 * Compile/ExécuteCode/EvalueExpression (never by top-level script parsing). */
static void absorb_procedure_header(void) {
    /* Open a fresh scope for the params — declare_variable at scopeDepth 0
     * would mark them as globals; we need them as locals on the function's
     * stack frame. Same pattern as proc_declaration. */
    begin_scope();

    /* Consume PROCEDURE or FONCTION (already matched by caller). */
    advance_token();

    /* Optional visibility modifiers (PRIVE, PROTEGE…). */
    if (check(TOKEN_PRIVE) || check(TOKEN_PROTEGE) || check(TOKEN_PUBLIC)) {
        advance_token();
    }

    /* Optional name → assigned as the function's display name. */
    if (check(TOKEN_IDENTIFIER)) {
        advance_token();
        current->function->name = obj_copy_string(parser.previous.start,
                                                  parser.previous.length);
    }

    /* Params: `(p1 [est un type] [= default], p2, ...)`. Same logic as the
     * "Regular procedure/function" branch in proc_declaration, minus the
     * global registration. */
    consume(TOKEN_LEFT_PAREN, E_SYNTAX_EXPECTED_LPAREN_AFTER_PROC_NAME);
    uint8_t localParamSlots[256];
    int localParamCount = 0;
    Value defaults[255];
    int defaultCount = 0;
    int minArity = 0;
    if (!check(TOKEN_RIGHT_PAREN)) {
        do {
            current->function->arity++;
            if (current->function->arity > 255) {
                owl_emit_error_current(E_SYNTAX_TOO_MANY_PARAMETERS);
            }
            bool isLocalParam = match_token(TOKEN_LOCAL);
            if (reject_keyword_as_param_name()) advance_token();
            else consume(TOKEN_IDENTIFIER, E_SYNTAX_EXPECTED_PARAM_NAME);
            Token paramName = parser.previous;
            declare_variable(&paramName);
            if (isLocalParam) {
                localParamSlots[localParamCount++] = (uint8_t)(current->localCount - 1);
            }
            bool typeSeen = match_token(TOKEN_EST);
            if (typeSeen) skip_type_spec();
            /*  — attribut de declaration <utile>/<useful> sur un param
             * d'un en-tete PROCEDURE/FONCTION absorbe par Compile()/ExecuteCode()
             * (3e des trois copies du parseur de params). Sans ce parse, le
             * marqueur restant provoquait « ')' attendu apres les parametres ».
             * Meme mecanisme partage que les autres sites ; sorties nullable /
             * indetectable consommees puis ignorees sur un slot de parametre. */
            {
                bool pUndetectable = false;
                bool pSuppressUnused = false;
                (void)parse_nullability_marker_ex(&pUndetectable, &pSuppressUnused);
                if (pSuppressUnused) {
                    record_suppress_unused(paramName);
                }
            }
            reject_untyped_param(&paramName, typeSeen);
            if (match_token(TOKEN_EQUAL)) {
                Value v;
                if (parse_default_literal(&v)) {
                    defaults[defaultCount++] = v;
                    if (current->localCount > 0)
                        current->locals[current->localCount - 1].hasInitializer = true;
                }
            } else {
                if (defaultCount > 0) {
                    owl_emit_error_at(&parser.previous, E_SEM_REQUIRED_PARAM_AFTER_DEFAULT);
                }
                minArity = current->function->arity;
            }
        } while (match_token(TOKEN_COMMA));
    }
    consume(TOKEN_RIGHT_PAREN, E_SYNTAX_EXP_RPAREN_PARAMS);
    current->function->minArity = minArity;
    if (defaultCount > 0) {
        current->function->defaults = (Value*)malloc(sizeof(Value) * defaultCount);
        for (int di = 0; di < defaultCount; di++) {
            current->function->defaults[di] = defaults[di];
        }
        current->function->defaultCount = defaultCount;
    }

    /* Optional `: returnType`. */
    if (is_return_type_colon()) {
        advance_token();
        skip_type_spec();
    }

    /* LOCAL params: deep-clone for caller-isolation (same as proc_declaration). */
    for (int li = 0; li < localParamCount; li++) {
        uint8_t slot = localParamSlots[li];
        emit_bytes(OP_GET_LOCAL, slot);
        emit_byte(OP_DEEP_COPY);
        emit_bytes(OP_SET_LOCAL, slot);
        emit_byte(OP_POP);
    }
}

/* Internal shared body. `asFunction` = true disables the "no RENVOYER at
 * top-level" restriction, used by Compile() / ExécuteCode() / EvalueExpression()
 * at runtime. If the source starts with `PROCEDURE` / `FONCTION`, the header
 * is absorbed into the returned function (Compile form). */

/* B.2 — Pre-scan unifie single-file. UN seul walk de tokens qui gere :
 *
 *   1. Forme 2-args `Compile("Name", "body")` : enregistre Name comme global
 *      pour qu'il survive a la validation `is_known_global_name`. OWL's
 *      implicit EXTERNE — contract "this will exist by runtime, else throw".
 *      La forme 1-arg `Compile("body")` renvoie une fonction anonyme, rien
 *      a enregistrer.
 *
 *   2. Hoisting des declarations structurelles top-level (PROCEDURE/FONCTION/
 *      CLASSE/STRUCTURE/ENUMERATION/COMBINAISON/INTERFACE/Fenetre) : leurs
 *      noms sont pre-declares pour autoriser les forward references depuis
 *      les statements top-level.
 *
 * En mode projet, prescan_file (dans prescan.c) couvre #2 cross-file via la
 * SymbolTable. Le pre-scan single-file s'execute en plus pour les forward
 * refs INTERNES au fichier courant.
 *
 * Un seul scan de tokens — plus rapide qu'avant ou on faisait deux passes
 * separees. */
/* ====================================================================
 * Prescan widgets DSL : table parallele des widgets user-declares
 * detectes par le prescan source. Permet le forward-reference dans les
 * PROCEDURE event-handlers : si BTN_X est declare avant LIB_R dans le
 * source mais que PROCEDURE surClic() de BTN_X fait `LIB_R = X`, le
 * compilo doit savoir que LIB_R est un widget AVANT d'avoir parse sa
 * declaration. Vu que le parse de window_declaration enregistre les
 * widgets dans vm.windows au fil du source (et non en prescan), un
 * fix purement runtime ne couvre pas le cas forward-ref.
 *
 * Table parallele : ne touche pas a vm.windows, consultee en plus par
 * vm_find_widget_info_by_name. Reset au debut de chaque compile.
 * ==================================================================== */

#define PRESCAN_WIDGETS_MAX 512
typedef struct {
    char name[64];
    OwlControlKind kind;
} PrescanWidget;
static PrescanWidget g_prescan_widgets[PRESCAN_WIDGETS_MAX];
static int g_prescan_widget_count = 0;

/*  — table parallele des enfants NOMMES d'un widget (aujourd'hui les
 * colonnes d'une Table). Le pre-scan ne retenait que { nom, genre } : le
 * compilo savait « TABLE_A est une Table » mais ignorait quelles colonnes elle
 * porte, d'ou l'acceptation silencieuse de `TABLE_A[ligne].<n'importe quoi>`
 * (sac de proprietes dynamique) et de `TABLE_A[ligne].COL_D_UNE_AUTRE_TABLE`. */
#define PRESCAN_CHILDREN_MAX 2048
typedef struct {
    int  owner;          /* index dans g_prescan_widgets */
    char name[64];
} PrescanChild;
static PrescanChild g_prescan_children[PRESCAN_CHILDREN_MAX];
static int g_prescan_child_count = 0;

static void prescan_widgets_reset(void) {
    g_prescan_widget_count = 0;
    g_prescan_child_count = 0;
}

/* Renvoie l'index du widget enregistre (existant ou neuf), -1 si rejete. */
static int prescan_widget_register(const char* name, int nameLen, OwlControlKind kind) {
    if (nameLen <= 0 || nameLen >= 64) return -1;
    /* Dedup CI : ne re-enregistre pas si meme nom deja present. */
    for (int i = 0; i < g_prescan_widget_count; i++) {
        if ((int)strlen(g_prescan_widgets[i].name) == nameLen &&
            strncasecmp(g_prescan_widgets[i].name, name, (size_t)nameLen) == 0) {
            return i;
        }
    }
    if (g_prescan_widget_count >= PRESCAN_WIDGETS_MAX) return -1;
    int idx = g_prescan_widget_count++;
    PrescanWidget* w = &g_prescan_widgets[idx];
    memcpy(w->name, name, (size_t)nameLen);
    w->name[nameLen] = '\0';
    w->kind = kind;
    return idx;
}

static void prescan_child_register(int owner, const char* name, int nameLen) {
    if (owner < 0 || nameLen <= 0 || nameLen >= 64) return;
    if (g_prescan_child_count >= PRESCAN_CHILDREN_MAX) return;
    for (int i = 0; i < g_prescan_child_count; i++) {
        if (g_prescan_children[i].owner == owner &&
            (int)strlen(g_prescan_children[i].name) == nameLen &&
            strncasecmp(g_prescan_children[i].name, name, (size_t)nameLen) == 0) {
            return;
        }
    }
    PrescanChild* c = &g_prescan_children[g_prescan_child_count++];
    c->owner = owner;
    memcpy(c->name, name, (size_t)nameLen);
    c->name[nameLen] = '\0';
}

/* Comparaison de deux identifiants OWL : casse ET accents insensibles
 * (invariants 1 et 2) — COL_Clé, COL_Cle et col_clé sont le meme nom. */
static bool prescan_ident_equal(const char* a, const char* b) {
    char sa[256], sb[256];
    int la = scanner_strip_accents(a, (int)strlen(a), sa, sizeof(sa));
    int lb = scanner_strip_accents(b, (int)strlen(b), sb, sizeof(sb));
    return la == lb && strncasecmp(sa, sb, (size_t)la) == 0;
}

static int prescan_widget_index(const char* name) {
    if (!name) return -1;
    for (int i = 0; i < g_prescan_widget_count; i++) {
        if (prescan_ident_equal(g_prescan_widgets[i].name, name)) return i;
    }
    return -1;
}

/* API publique consommee par vm_find_widget_info_by_name. */
const OwlControlKindInfo* compiler_prescan_widget_find(const char* name) {
    /* Resolution accent-insensible (invariant 2) : TAB_Donnees == TAB_Donnees.
     * Les noms prescan sont stockes bruts (forme tapee), on strippe les deux
     * cotes avant compare, comme la cle vm.globals materialisee. */
    int idx = prescan_widget_index(name);
    if (idx < 0) return NULL;
    /* Map kind -> OwlControlKindInfo* */
    for (const OwlControlKindInfo* k = owl_control_kinds_table(); k->nameFR; k++) {
        OwlControlKind tmp;
        if (owl_control_kind_of_info(k, &tmp) && tmp == g_prescan_widgets[idx].kind) {
            return k;
        }
    }
    return NULL;
}

/*  — nombre d'enfants nommes vus par le pre-scan pour ce widget.
 * Zero = « le pre-scan n'a rien vu » : soit le widget n'a pas d'enfant, soit
 * sa declaration vit hors du perimetre scanne. Dans les deux cas on ne peut
 * rien affirmer, donc aucune validation (pas de faux positif). */
static int prescan_widget_child_count(const char* widget) {
    int owner = prescan_widget_index(widget);
    if (owner < 0) return 0;
    int n = 0;
    for (int i = 0; i < g_prescan_child_count; i++) {
        if (g_prescan_children[i].owner == owner) n++;
    }
    return n;
}

static bool prescan_widget_has_child(const char* widget, const char* child) {
    int owner = prescan_widget_index(widget);
    if (owner < 0) return false;
    for (int i = 0; i < g_prescan_child_count; i++) {
        if (g_prescan_children[i].owner == owner &&
            prescan_ident_equal(g_prescan_children[i].name, child)) {
            return true;
        }
    }
    return false;
}

/* Liste « COL_A, COL_B » pour le message d'erreur : une impasse devient une
 * indication seulement si elle nomme les noms qui, eux, marcheraient. */
static void prescan_widget_child_list(const char* widget, char* out, size_t cap) {
    out[0] = '\0';
    int owner = prescan_widget_index(widget);
    if (owner < 0) return;
    size_t used = 0;
    for (int i = 0; i < g_prescan_child_count; i++) {
        if (g_prescan_children[i].owner != owner) continue;
        const char* n = g_prescan_children[i].name;
        size_t need = strlen(n) + (used > 0 ? 2 : 0);
        if (used + need >= cap) break;
        if (used > 0) { memcpy(out + used, ", ", 2); used += 2; }
        memcpy(out + used, n, strlen(n));
        used += strlen(n);
        out[used] = '\0';
    }
}

/*  — Tables (kind OWL_CONTROL_TABLE) qui declarent une
 * colonne nommee `col`, en ordre de declaration. Renvoie le nombre trouve ;
 * remplit `firstOwner` (nom de la 1re Table) et `list` (noms separes par « , »).
 * Filtre STRICT sur le kind Table :  a ajoute les enfants de ZoneRépétée
 * au meme g_prescan_children — un enfant de ZR ne fait pas d'une colonne un
 * receveur, on ne le compte pas. g_prescan_children est rempli dans l'ordre du
 * scan, donc l'iteration par index rend l'ordre de declaration. */
static int prescan_tables_declaring_column(const char* col,
                                           char* firstOwner, size_t firstCap,
                                           char* list, size_t listCap) {
    if (firstOwner && firstCap) firstOwner[0] = '\0';
    if (list && listCap) list[0] = '\0';
    int count = 0;
    size_t used = 0;
    for (int i = 0; i < g_prescan_child_count; i++) {
        if (!prescan_ident_equal(g_prescan_children[i].name, col)) continue;
        int owner = g_prescan_children[i].owner;
        if (owner < 0 || owner >= g_prescan_widget_count) continue;
        if (g_prescan_widgets[owner].kind != OWL_CONTROL_TABLE) continue;
        const char* tname = g_prescan_widgets[owner].name;
        if (count == 0 && firstOwner && firstCap) {
            snprintf(firstOwner, firstCap, "%s", tname);
        }
        if (list && listCap) {
            size_t need = strlen(tname) + (used > 0 ? 2 : 0);
            if (used + need < listCap) {
                if (used > 0) { memcpy(list + used, ", ", 2); used += 2; }
                memcpy(list + used, tname, strlen(tname));
                used += strlen(tname);
                list[used] = '\0';
            }
        }
        count++;
    }
    return count;
}

static void prescan_source_unified(const char* source, bool registerTopLevelDecls) {
    Scanner s;
    scanner_init(&s, source);

    int depth = 0;
    /*  — quel widget est ouvert a chaque profondeur, pour rattacher un
     * bloc `COL_X est une colonne` a la Table qui le contient. Ecrit AVANT le
     * depth++ du bloc, lu en depth-1 par l'enfant. -1 = bloc non-widget. */
    #define PRESCAN_DEPTH_MAX 64
    int openWidget[PRESCAN_DEPTH_MAX];
    for (int i = 0; i < PRESCAN_DEPTH_MAX; i++) openWidget[i] = -1;
    #define PRESCAN_OPEN_SET(d, v) \
        do { if ((d) >= 0 && (d) < PRESCAN_DEPTH_MAX) openWidget[(d)] = (v); } while (0)

    for (;;) {
        Token tok = scanner_scan_token(&s);
        if (tok.type == TOKEN_EOF) break;
        if (tok.type == TOKEN_NEWLINE || tok.type == TOKEN_ERROR) continue;

        /* Detection Compile("Name", ...) — peut apparaitre a n'importe quel
         * niveau de profondeur (top-level, dans un body, etc.). On consomme
         * les tokens forward sans toucher au depth (Compile est juste un
         * call expr). Match case-insensitive sur "Compile". */
        if (tok.type == TOKEN_IDENTIFIER && tok.length == 7 &&
            strncasecmp(tok.start, "Compile", 7) == 0) {
            Token next = scanner_scan_token(&s);
            while (next.type == TOKEN_NEWLINE) next = scanner_scan_token(&s);
            if (next.type == TOKEN_LEFT_PAREN) {
                Token strTok = scanner_scan_token(&s);
                while (strTok.type == TOKEN_NEWLINE) strTok = scanner_scan_token(&s);
                if (strTok.type == TOKEN_STRING) {
                    Token after = scanner_scan_token(&s);
                    while (after.type == TOKEN_NEWLINE) after = scanner_scan_token(&s);
                    /* Forme 2-args : `Compile("Name", "body")` -> register Name */
                    if (after.type == TOKEN_COMMA &&
                        strTok.length >= 2 &&
                        strTok.start[0] == '"' &&
                        strTok.start[strTok.length - 1] == '"') {
                        const char* raw = strTok.start + 1;
                        int rawLen = strTok.length - 2;
                        if (rawLen > 0 && rawLen < 64) {
                            global_track_declare(raw, rawLen, strTok.line);
                            /* Marqué hasInitializer car la global est
                             * "initialisée" au runtime par Compile() :
                             * éviter le warning "declared but never used"
                             * vu que les usages se font via string littérale
                             * passée à ExécuteTraitement, indétectable au
                             * compile-time. */
                            if (g_declaredGlobalsCount > 0) {
                                g_declaredGlobals[g_declaredGlobalsCount - 1].hasInitializer = true;
                            }
                        }
                    }
                    /* Forme 1-arg ou inconnue : on continue, after est deja consomme */
                }
                /* Si pas TOKEN_STRING, strTok est deja consomme — on reprend
                 * la boucle au prochain scanner_scan_token. */
            }
            /* Que la forme matche ou pas, les tokens consommes ne sont pas
             * des keywords structurels — pas de depth update a faire. */
            continue;
        }

        if (tok.type == TOKEN_FIN) {
            if (depth > 0) depth--;
            continue;
        }

        if (depth > 0) {
            /* Track nested block-openers — exhaustif. Necessaire pour ne pas
             * sortir trop tot du depth. */
            /* Ouvrants imbriques : source unique. Une forme sans FIN
             * comptee ici faisait sortir du depth trop tard, et les widgets
             * declares apres ne se pre-enregistraient plus. */
            if (prescan_token_in_depth_table(tok.type)) {
                if (local_scan_depth_delta(tok, &s) > 0) {
                    PRESCAN_OPEN_SET(depth, -1);
                    depth++;
                }
                continue;
            }
            if (tok.type == TOKEN_AVEC) {
                PRESCAN_OPEN_SET(depth, -1);
                depth++;
                continue;
            }
            /* Detection forward-ref widgets : `IDENT est un <WidgetKind>` au
             * sein d'une window/etat. Pre-enregistre dans g_prescan_widgets
             * pour que vm_find_widget_info_by_name puisse resoudre les
             * widgets declares APRES le site d'usage (ex : LIB_R declare
             * apres BTN_X qui contient `PROCEDURE surClic() LIB_R = X FIN`).
             *
             * Pattern reconnu : IDENT [est|is] [un|une|a|an]? <KindToken|IDENT>
             * On scan en avant via le scanner s avec snapshot/restore : si pas
             * EST apres l'IDENT, on remet le scanner a l'etat pre-peek pour ne
             * pas avaler accidentellement un FIN ou un block-opener (qui
             * fausserait le compteur depth — typiquement `Disposition = dispLibre`
             * dans un PROPRIETES qui consommait le FIN suivant). */
            if (tok.type == TOKEN_IDENTIFIER) {
                Token ident = tok;
                /* Peek non-newline. */
                Scanner sBeforePeek = s;
                Token t2;
                do { t2 = scanner_scan_token(&s); } while (t2.type == TOKEN_NEWLINE);
                if (t2.type == TOKEN_EST) {
                    Token t3;
                    do { t3 = scanner_scan_token(&s); } while (t3.type == TOKEN_NEWLINE);
                    /* Skip optional "un"/"une". */
                    if (t3.type == TOKEN_IDENTIFIER &&
                        (t3.length == 2 || t3.length == 3) &&
                        (strncasecmp(t3.start, "un", 2) == 0 ||
                         strncasecmp(t3.start, "une", 3) == 0)) {
                        do { t3 = scanner_scan_token(&s); } while (t3.type == TOKEN_NEWLINE);
                    }
                    /*  : article EN `a` (TOKEN_A) / `an` (IDENT 2-char),
                     * miroir de la branche depth==0. Sans ca le widget reste sur
                     * l'article -> prefixe Champ/genre non resolu -> forward-ref
                     * non pre-enregistre + depth desync. */
                    if (t3.type == TOKEN_A ||
                        (t3.type == TOKEN_IDENTIFIER &&
                         ((t3.length == 1 &&
                           (t3.start[0] == 'a' || t3.start[0] == 'A')) ||
                          (t3.length == 2 &&
                           (t3.start[0] == 'a' || t3.start[0] == 'A') &&
                           (t3.start[1] == 'n' || t3.start[1] == 'N'))))) {
                        do { t3 = scanner_scan_token(&s); } while (t3.type == TOKEN_NEWLINE);
                    }
                    /*  lot 1-bis : skip le modificateur 'Champ'
                     * optionnel, comme le parsing principal. Sans ca, un widget
                     * 'LIB_X est un Champ Libelle' n'est pas reconnu (t3 = 'Champ'
                     * IDENT) -> non pre-enregistre -> 'variable inconnue' en
                     * forward-ref + depth desync (bloc ferme trop tot). */
                    bool prescanSawChamp = false;
                    if (token_is_champ_modifier(t3)) {
                        prescanSawChamp = true;
                        do { t3 = scanner_scan_token(&s); } while (t3.type == TOKEN_NEWLINE);
                        /*  : 'de'/'of' filler optionnel apres 'Champ'.
                         * Sans ca, t3 = TOKEN_DE -> genre non resolu -> forward-ref
                         * 'X est un Champ de Saisie' non pre-enregistre. */
                        if (t3.type == TOKEN_DE) {
                            do { t3 = scanner_scan_token(&s); } while (t3.type == TOKEN_NEWLINE);
                        }
                    }
                    /* Resolution kind via tokens dedies OU via control_kind_from_token. */
                    OwlControlKind kind = (OwlControlKind)-1;
                    bool isWidget = false;
                    /*  — une colonne (`COL_X est une colonne ... FIN`)
                     * ouvre un bloc au meme titre qu'un widget, mais n'est PAS
                     * un global resoluble (compile-time only, jamais posee dans
                     * vm.globals par parse_one_column). Il faut neanmoins
                     * incrementer depth pour equilibrer son FIN : sinon le FIN
                     * de la colonne fait retomber depth d'un cran de trop, la
                     * Table le referme a d=0, et TOUT widget frere declare
                     * APRES la Table-avec-colonne sort du scope window trop tot
                     * -> non pre-enregistre -> resolution accent-insensible
                     * cassee (invariant 2). */
                    bool isColumnBlock = (t3.type == TOKEN_COLONNE);
                    /*  — meme raisonnement pour le sous-bloc Volet
                     * (`VOL_X est un [Champ] Volet ... FIN`) : corps a refermer,
                     * mais genre non resolu par owl_control_kind_from_token
                     * (is_widget=false). Sans ce depth++, le FIN du volet
                     * decremente un cran de trop : le Champ Onglet retombe a
                     * d=0, et TOUT champ declare APRES lui sort du scope
                     * fenetre -> non pre-enregistre -> plus aucune validation
                     * de propriete sur ce champ (cascade acceptee en silence)
                     * et forward-ref cassee. */
                    bool isVoletBlock = token_is_volet_genre(t3);
                    switch (t3.type) {
                        case TOKEN_LIBELLE:   kind = OWL_CONTROL_LABEL;       isWidget = true; break;
                        case TOKEN_BOUTON:    kind = OWL_CONTROL_BUTTON;      isWidget = true; break;
                        case TOKEN_SAISIE:    kind = OWL_CONTROL_INPUT;       isWidget = true; break;
                        case TOKEN_TABLE:     kind = OWL_CONTROL_TABLE;       isWidget = true; break;
                        case TOKEN_CONTENEUR: kind = OWL_CONTROL_CONTAINER;   isWidget = true; break;
                        case TOKEN_FENETRE:   kind = OWL_CONTROL_WINDOW;      isWidget = true; break;
                        case TOKEN_LISTE:     kind = OWL_CONTROL_LISTE;       isWidget = true; break;
                        case TOKEN_IDENTIFIER:
                            /* Image/Combo/Selecteur/Interrupteur/ZoneRépétée :
                             * via control_kind_from_token (catalog lookup). */
                            isWidget = owl_control_kind_from_token(
                                t3.start, t3.length, &kind, NULL);
                            break;
                        default: break;
                    }
                    /*  lot 1-bis : Image/Liste nu (sans 'Champ') = type
                     * runtime / collection deterministe, PAS un widget. Ne pas le
                     * pre-enregistrer comme controle (sinon depth desync sur la
                     * forme `img est une Image = init` sans corps -> fausse la
                     * resolution + provoque un faux shadow). Cohérent avec la
                     * desambiguisation du parsing principal. Le peek PROPRIETES
                     * (exception messaging) n'est PAS pertinent ici : le prescan
                     * ne pre-enregistre que les vrais controles, et le cas
                     * 'Image nu + PROPRIETES' est traite en erreur cote parseur. */
                    if (isWidget && !prescanSawChamp
                        && owl_control_kind_is_ambiguous(kind)) {
                        isWidget = false;
                    }
                    if (isWidget) {
                        int wIdx = prescan_widget_register(ident.start,
                                                           ident.length, kind);
                        /*  — un widget declare DANS une ZoneRépétée est
                         * aussi un enfant nomme de cette ZoneRépétée : `ZR_X[i]
                         * .LIB_R` doit pouvoir se valider contre ces noms. Les
                         * enfants d'une Table passent, eux, par les blocs colonne
                         * (plus bas) : ce sont deux surfaces disjointes, aucun
                         * recouvrement. */
                        if (depth >= 1 && depth - 1 < PRESCAN_DEPTH_MAX) {
                            int parentIdx = openWidget[depth - 1];
                            if (parentIdx >= 0
                                && parentIdx < g_prescan_widget_count
                                && g_prescan_widgets[parentIdx].kind
                                       == OWL_CONTROL_ZONE_REPETEE) {
                                prescan_child_register(parentIdx, ident.start,
                                                       ident.length);
                            }
                        }
                        PRESCAN_OPEN_SET(depth, wIdx);
                        /* Le body du widget (PROPRIETES + PROCEDURE) ouvre
                         * un nouveau scope — incremente depth pour que les
                         * FIN du widget redescendent correctement et que
                         * les widgets siblings DECLARES APRES soient
                         * detectes au bon niveau. Sans ca, le compteur
                         * depth sort de la window trop tot et rate LIB_R
                         * declare apres BTN_X. */
                        depth++;
                    } else if (isColumnBlock || isVoletBlock) {
                        /*  — bloc colonne : depth++ SANS registration
                         * (pas un global resoluble), pour equilibrer son FIN.
                         * Idem Volet : le nom du volet n'est pas pre-enregistre
                         * ici (registration = decision de surface separee), on
                         * ne fait qu'equilibrer la profondeur. */
                        if (isColumnBlock && depth >= 1 &&
                            depth - 1 < PRESCAN_DEPTH_MAX) {
                            /*  — la colonne n'est pas un global, mais
                             * son NOM appartient a la Table qui l'englobe. */
                            prescan_child_register(openWidget[depth - 1],
                                                   ident.start, ident.length);
                        }
                        PRESCAN_OPEN_SET(depth, -1);
                        depth++;
                    }
                } else {
                    /* Pas EST : restore le scanner pour ne pas avaler le
                     * token suivant (peut etre un FIN, un PROCEDURE, etc.
                     * qui doit etre vu par la boucle pour ajuster depth). */
                    s = sBeforePeek;
                }
                continue;
            }
            continue;
        }

        /* depth == 0 : reconnaitre les top-level decls */

        if (tok.type == TOKEN_PROCEDURE || tok.type == TOKEN_FONCTION) {
            /* Skip optional visibility modifier, then read the name */
            Token name;
            for (;;) {
                name = scanner_scan_token(&s);
                if (name.type != TOKEN_NEWLINE) break;
            }
            if (name.type == TOKEN_PRIVE || name.type == TOKEN_PROTEGE
             || name.type == TOKEN_PUBLIC) {
                for (;;) {
                    name = scanner_scan_token(&s);
                    if (name.type != TOKEN_NEWLINE) break;
                }
            }
            if (name.type == TOKEN_IDENTIFIER) {
                /* Methode `Class.Method` ou `Class::Method` : on n'enregistre
                 * pas un global pour ces formes (elles n'introduisent pas de
                 * nom top-level visible). */
                Token after;
                for (;;) {
                    after = scanner_scan_token(&s);
                    if (after.type != TOKEN_NEWLINE) break;
                }
                if (registerTopLevelDecls
                 && after.type != TOKEN_DOT && after.type != TOKEN_DOUBLE_COLON) {
                    global_track_prescan(name.start, name.length, name.line);
                }
            }
            PRESCAN_OPEN_SET(depth, -1);
            depth++;
            continue;
        }

        if (tok.type == TOKEN_CONSTANTE) {
            /* CONSTANT[E] top-level — deux formes (doc 1514012) :
             *   bloc   : `CONSTANT[E]\n  NAME = literal\n  ...\nFIN`
             *   inline : `CONSTANT[E] NAME = literal`  (pas de FIN)
             * Discrimination : on peek le token immediatement suivant. Un
             * NEWLINE → bloc (on entre en depth, le FIN refermera). Un IDENT
             * sur la meme ligne → inline (pas de depth, sinon le compteur
             * resterait deséquilibré faute de FIN, ce qui ferait sortir les
             * decls suivantes du niveau top-level et casserait leur
             * hoisting / forward-ref). */
            Token peek = scanner_scan_token(&s);
            if (peek.type == TOKEN_NEWLINE) {
                PRESCAN_OPEN_SET(depth, -1);
                depth++;          /* forme bloc */
            } else if (peek.type == TOKEN_IDENTIFIER && registerTopLevelDecls) {
                /* forme inline : enregistre le nom comme global top-level. */
                global_track_prescan(peek.start, peek.length, peek.line);
            }
            /* Le reste de la ligne inline (`= literal`) est inoffensif : les
             * tokens seront re-lus par la boucle et ignores a depth 0. */
            continue;
        }

        if (tok.type == TOKEN_IDENTIFIER) {
            Token name = tok;
            Token next;
            /*  — le lookahead saute les NEWLINE pour tolerer `NAME\n est
             * un Bloc`, mais quand l'IDENT n'est PAS suivi de EST il avalait le
             * PREMIER token de la ligne suivante (cas `= icones.maison` en fin de
             * ligne : le lookahead de `maison` mangeait le `NAME` du bloc DSL
             * suivant -> bloc invisible au prescan -> verrou DSL jamais arme sur
             * le code pre-bloc). Snapshot + restore comme la branche depth>0
             * (L37738/37881) : si pas EST, on rend les tokens a la boucle. */
            Scanner sBeforePeek = s;
            for (;;) {
                next = scanner_scan_token(&s);
                if (next.type != TOKEN_NEWLINE) break;
            }
            if (next.type == TOKEN_EST) {
                Token after;
                for (;;) {
                    after = scanner_scan_token(&s);
                    if (after.type != TOKEN_NEWLINE) break;
                }
                /* Copule EN : `is a/an <BlockType>`. Le scanner mappe `a` sur
                 * TOKEN_A (borne de plage), `an` reste un IDENT 2 chars ; en
                 * position post-EST l'un comme l'autre est l'article EN. On le
                 * saute pour atteindre le token de bloc (miroir raw-scanner de
                 * consume_en_a_an_filler). */
                if (after.type == TOKEN_A ||
                    (after.type == TOKEN_IDENTIFIER &&
                     ((after.length == 1 &&
                       (after.start[0] == 'a' || after.start[0] == 'A')) ||
                      (after.length == 2 &&
                       (after.start[0] == 'a' || after.start[0] == 'A') &&
                       (after.start[1] == 'n' || after.start[1] == 'N'))))) {
                    for (;;) {
                        after = scanner_scan_token(&s);
                        if (after.type != TOKEN_NEWLINE) break;
                    }
                }
                bool isClassDecl = (after.type == TOKEN_CLASSE);
                bool isUserType  = isClassDecl
                    || after.type == TOKEN_STRUCTURE
                    || after.type == TOKEN_INTERFACE
                    || after.type == TOKEN_ENUMERATION
                    || after.type == TOKEN_COMBINAISON;
                bool isWindowDecl = (after.type == TOKEN_FENETRE
                                  || after.type == TOKEN_LIBELLE
                                  || after.type == TOKEN_BOUTON
                                  || after.type == TOKEN_SAISIE);
                /*  — pose les flags has_window_block / has_etat_block
                 * des le prescan pour permettre au verrou DSL toplevel
                 * (enforce_dsl_file_isolation_at_top_level) de rejeter du
                 * code top-level non-PROCEDURE meme s'il apparait AVANT le
                 * bloc Fenetre/Etat dans le source. */
                if (after.type == TOKEN_FENETRE) {
                    g_file_has_window_block_prescan = true;
                } else if (after.type == TOKEN_ETAT) {
                    g_file_has_etat_block_prescan = true;
                }
                /*  — `Projet`/`Project` n'est pas un token dedie mais
                 * un IDENTIFIER (type compose). Pose le flag des le prescan pour
                 * que le verrou top-level rejette le code AVANT la declaration
                 * (enforce_projet_file_isolation_at_top_level). Casse-insensible
                 * (invariant 1) ; pas d'accent a stripper sur ces deux mots. */
                if (after.type == TOKEN_IDENTIFIER
                    && ((after.length == 6
                         && strncasecmp(after.start, "Projet", 6) == 0)
                     || (after.length == 7
                         && strncasecmp(after.start, "Project", 7) == 0))) {
                    g_file_has_projet_block = true;
                }
                /*  — meme voie pour `CollectionDeProcédures` /
                 * `ProcedureCollection` (IDENTIFIER, pas de token dedie). */
                if (after.type == TOKEN_IDENTIFIER
                    && token_is_collection_kw(after.start, after.length)) {
                    g_file_has_collection_block = true;
                }
                /*  — `ServiceREST` (IDENTIFIER, pas de token dedie ;
                 * accent-strip + compare, miroir du dispatch compilateur). Pose
                 * le flag des le prescan pour que le verrou top-level rejette le
                 * code AVANT la declaration du bloc. */
                if (after.type == TOKEN_IDENTIFIER) {
                    char svcProbe[24];
                    int svcLen = scanner_strip_accents(after.start, after.length,
                                                       svcProbe, sizeof(svcProbe));
                    if (svcLen == 11 &&
                        strncasecmp(svcProbe, "ServiceREST", 11) == 0) {
                        g_file_has_service_block = true;
                    }
                }
                if (registerTopLevelDecls) {
                    if (isUserType) {
                        /* Prescan : on enregistre le NOM uniquement (kind reste
                         * UNKNOWN). Le kind STRUCTURE/ENUMERATION sera pose par
                         * struct_declaration / enum_declaration quand le body
                         * est parse — sinon le strict-check sur kind==STRUCTURE
                         * trippe avant que les fields soient ajoutes (forward
                         * ref `stP.X` ou stPoint est declare plus bas). CLASSE
                         * n'a pas de strict-check field-based donc kind peut
                         * etre pose en prescan sans casser les forward refs.
                         * Cf tests/regression/test_prescan_struct_kind_premature.owl */
                        register_user_type(name.start, name.length, name.line);
                        if (isClassDecl) {
                            user_type_set_kind(name.start, name.length,
                                               OWL_USER_TYPE_CLASSE);
                        }
                        global_track_declare_structure(name.start, name.length, name.line);
                    } else if (isWindowDecl) {
                        global_track_prescan(name.start, name.length, name.line);
                        /*  : enregistrer aussi la Fenetre top-level
                         * comme widget pour que compiler_prescan_widget_find
                         * la resolve depuis le `dot()` setter (necessaire au
                         * lookup catalog du slot pour detecter MULTILINGUE
                         * sur `FEN_X..Titre = {langueXxx: "..."}`). Les
                         * sous-controls (Libelle/Bouton/Saisie top-level)
                         * sont refuses au compile principal (E_SEM_CONTROL_
                         * KIND_OUTSIDE_WINDOW) donc on ne les enregistre
                         * pas ici — seule la Fenetre est valide. */
                        if (after.type == TOKEN_FENETRE) {
                            prescan_widget_register(name.start, name.length,
                                                    OWL_CONTROL_WINDOW);
                        }
                    }
                }
                if (isUserType || isWindowDecl) {
                    PRESCAN_OPEN_SET(depth, -1);
                    depth++;
                }
                /* Si ce n'est pas un block-type apres `est`, c'est une variable
                 * declaration ordinaire — pas de pre-registration ici (le
                 * compile principal s'en charge en ordre source). */
            } else {
                /*  — pas EST : rendre a la boucle les tokens avales par le
                 * lookahead (dont un eventuel IDENT de la ligne suivante, qui peut
                 * ouvrir un bloc DSL). Sinon le bloc suivant reste invisible. */
                s = sBeforePeek;
            }
            continue;
        }
    }
    #undef PRESCAN_OPEN_SET
    #undef PRESCAN_DEPTH_MAX
}

/*  — replay des widgets/sous-widgets voisins (skip self). Les owners de
 * sous-widgets sont memorises en index LOCAL au fichier (table remise a zero par
 * fichier au prebuild) : on reconstruit la table de correspondance local->live
 * en rejouant les widgets du fichier avant ses enfants. Reproduit exactement les
 * index vivants et le dedup par nom du scan live. */
static void neighbor_replay_widgets(int curFileIndex) {
    for (int k = 0; k < g_neighbor_buf_count; k++) {
        NeighborContribution* c = &g_neighbor_buf[k];
        if (c->fileIndex == curFileIndex) continue;
        int* liveIdx = NULL;
        if (c->widgetCount > 0) {
            liveIdx = (int*)malloc(sizeof(int) * (size_t)c->widgetCount);
        }
        for (int i = 0; i < c->widgetCount; i++) {
            int li = prescan_widget_register(c->widgets[i].name,
                        (int)strlen(c->widgets[i].name), c->widgets[i].kind);
            if (liveIdx) liveIdx[i] = li;
        }
        for (int i = 0; i < c->childCount; i++) {
            int ol = c->children[i].ownerLocal;
            int owner = (liveIdx && ol >= 0 && ol < c->widgetCount)
                        ? liveIdx[ol] : -1;
            prescan_child_register(owner, c->children[i].name,
                                   (int)strlen(c->children[i].name));
        }
        for (int i = 0; i < c->cglobalCount; i++) {
            global_track_declare(c->cglobals[i].name,
                (int)strlen(c->cglobals[i].name), c->cglobals[i].line);
            /* Miroir de la mutation post-Compile() du scan live (L36704+) :
             * une globale posee par Compile() est "initialisee" au runtime. */
            if (g_declaredGlobalsCount > 0)
                g_declaredGlobals[g_declaredGlobalsCount - 1].hasInitializer = true;
        }
        free(liveIdx);
    }
}

/*  — pass 1 (widgets voisins) extraite de compile_in_project /
 * _split, partagee par les deux. Fast-path replay quand l'etat voisins est
 * precalcule, sinon scan live historique (fallback). */
static void hydrate_widgets_from_neighbors(SymbolTable* symbols) {
    if (symbols != NULL) {
        if (neighbor_prebuilt_for(symbols)) {
            neighbor_replay_widgets(currentFileIndex);
        } else {
            for (int k = 0; k < symbols->sourceCount; k++) {
                if (symbols->sources[k].fileIndex == currentFileIndex) continue;
                if (symbols->sources[k].source == NULL) continue;
                prescan_source_unified(symbols->sources[k].source,
                                       /*registerTopLevelDecls=*/false);
            }
        }
        /* Reset des flags pollues par le scan voisins : sans ca,
         * g_file_has_window_block_prescan reste true si un voisin a un
         * bloc Fenetre, polluant l'isolation classe du fichier courant. */
        g_file_has_window_block_prescan = false;
        g_file_has_etat_block_prescan   = false;
        g_file_has_projet_block         = false;
        g_file_has_collection_block     = false;
        g_file_has_service_block        = false;
    }
}

void compiler_neighbor_prebuild_reset(void) {
    if (g_neighbor_buf != NULL) {
        for (int k = 0; k < g_neighbor_buf_count; k++) {
            free(g_neighbor_buf[k].widgets);
            free(g_neighbor_buf[k].children);
            free(g_neighbor_buf[k].cglobals);
            free(g_neighbor_buf[k].globals);
            free(g_neighbor_buf[k].elems);
            free(g_neighbor_buf[k].colls);
        }
        free(g_neighbor_buf);
        g_neighbor_buf = NULL;
    }
    g_neighbor_buf_count = 0;
    g_neighbor_buf_symbols = NULL;
    g_neighbor_prebuilt = false;
    /*  — le set d'identifiants references partage le cycle de vie du
     * prebuild voisins (une construction par check, liberee entre checks). */
    refset_free();
}

/*  — tokenise chaque source du projet UNE fois et memorise sa
 * contribution brute (par position de source). A appeler une fois par check,
 * AVANT les passes de compilation du driver ; l'etat est partage par toutes les
 * compilations (contexte + capture). compile_in_project reset les tables live a
 * son entree, le buffer (structure separee) survit. */
void compiler_neighbor_prebuild(SymbolTable* symbols) {
    compiler_neighbor_prebuild_reset();
    if (symbols == NULL || symbols->sourceCount <= 0) return;

    int n = symbols->sourceCount;
    g_neighbor_buf = (NeighborContribution*)calloc((size_t)n,
                                                   sizeof(NeighborContribution));
    if (g_neighbor_buf == NULL) return;
    g_neighbor_buf_count = n;

    for (int k = 0; k < n; k++) {
        NeighborContribution* c = &g_neighbor_buf[k];
        c->fileIndex = symbols->sources[k].fileIndex;
        c->source    = symbols->sources[k].source;
        const char* src = symbols->sources[k].source;
        if (src == NULL) continue;

        /* --- Pass widgets/sous-widgets + globales Compile() (mode voisin) --- */
        prescan_widgets_reset();
        decl_globals_reset_all();  /*  */
        prescan_source_unified(src, /*registerTopLevelDecls=*/false);
        if (g_prescan_widget_count > 0) {
            c->widgetCount = g_prescan_widget_count;
            c->widgets = (NeiWidgetRec*)malloc(sizeof(NeiWidgetRec)
                                               * (size_t)c->widgetCount);
            for (int i = 0; c->widgets && i < c->widgetCount; i++) {
                memcpy(c->widgets[i].name, g_prescan_widgets[i].name,
                       sizeof(c->widgets[i].name));
                c->widgets[i].kind = g_prescan_widgets[i].kind;
            }
            if (!c->widgets) c->widgetCount = 0;
        }
        if (g_prescan_child_count > 0) {
            c->childCount = g_prescan_child_count;
            c->children = (NeiChildRec*)malloc(sizeof(NeiChildRec)
                                               * (size_t)c->childCount);
            for (int i = 0; c->children && i < c->childCount; i++) {
                c->children[i].ownerLocal = g_prescan_children[i].owner;
                memcpy(c->children[i].name, g_prescan_children[i].name,
                       sizeof(c->children[i].name));
            }
            if (!c->children) c->childCount = 0;
        }
        if (g_declaredGlobalsCount > 0) {
            c->cglobalCount = g_declaredGlobalsCount;
            c->cglobals = (NeiCGlobalRec*)malloc(sizeof(NeiCGlobalRec)
                                                 * (size_t)c->cglobalCount);
            for (int i = 0; c->cglobals && i < c->cglobalCount; i++) {
                memcpy(c->cglobals[i].name, g_declaredGlobals[i].name,
                       sizeof(c->cglobals[i].name));
                c->cglobals[i].line = g_declaredGlobals[i].line;
            }
            if (!c->cglobals) c->cglobalCount = 0;
        }

        /* --- Pass globales bare + globales d'element --- */
        decl_globals_reset_all();  /*  */
        element_globals_reset();
        globals_scan_one_source(src);
        if (g_declaredGlobalsCount > 0) {
            c->globalCount = g_declaredGlobalsCount;
            c->globals = (NeiGlobalRec*)malloc(sizeof(NeiGlobalRec)
                                               * (size_t)c->globalCount);
            for (int i = 0; c->globals && i < c->globalCount; i++) {
                memcpy(c->globals[i].name, g_declaredGlobals[i].name,
                       sizeof(c->globals[i].name));
                c->globals[i].line = g_declaredGlobals[i].line;
            }
            if (!c->globals) c->globalCount = 0;
        }
        if (g_element_globals_count > 0) {
            c->elemCount = g_element_globals_count;
            c->elems = (NeiElemRec*)malloc(sizeof(NeiElemRec)
                                           * (size_t)c->elemCount);
            for (int i = 0; c->elems && i < c->elemCount; i++) {
                memcpy(c->elems[i].elem, g_element_globals[i].element,
                       sizeof(c->elems[i].elem));
                memcpy(c->elems[i].name, g_element_globals[i].name,
                       sizeof(c->elems[i].name));
            }
            if (!c->elems) c->elemCount = 0;
        }

        /* --- Pass membres de collection --- */
        collection_members_reset();
        g_collection_register_from_prescan = true;
        collection_scan_one_source(src);
        g_collection_register_from_prescan = false;
        if (g_collection_members_count > 0) {
            c->collCount = g_collection_members_count;
            c->colls = (NeiCollRec*)malloc(sizeof(NeiCollRec)
                                           * (size_t)c->collCount);
            for (int i = 0; c->colls && i < c->collCount; i++) {
                memcpy(c->colls[i].coll, g_collection_members[i].collection,
                       sizeof(c->colls[i].coll));
                memcpy(c->colls[i].name, g_collection_members[i].name,
                       sizeof(c->colls[i].name));
                c->colls[i].exposed = g_collection_members[i].exposed;
            }
            if (!c->colls) c->collCount = 0;
        }
    }

    /* Remet les tables live a zero : la premiere compile_in_project les reset
     * aussi, mais on ne laisse pas fuiter l'etat du dernier fichier scanne. */
    prescan_widgets_reset();
    decl_globals_reset_all();  /*  */
    element_globals_reset();
    collection_members_reset();
    g_file_has_window_block_prescan = false;
    g_file_has_etat_block_prescan   = false;
    g_file_has_projet_block         = false;
    g_file_has_collection_block     = false;
    g_file_has_service_block        = false;

    g_neighbor_buf_symbols = symbols;
    g_neighbor_prebuilt = true;
}

/* B.2 — Hoisting des declarations structurelles top-level.
 *
 * Modele d'execution OWL : un fichier .owl est un script Python-style. Le
 * top-level est libre (pas besoin d'un Main() obligatoire). Les declarations
 * structurelles (PROCEDURE/FONCTION/CLASSE/STRUCTURE/ENUMERATION/COMBINAISON/
 * INTERFACE/Fenetre/CONSTANTE) sont automatiquement HOISTEES en tete du chunk
 * du script — peu importe leur position dans le source. Les statements
 * top-level (Trace, assignements, calls, control flow) restent en ordre source.
 *
 * Resultat au runtime :
 *   1. [hoisted decls] — toutes les declarations enregistrees avant tout code
 *   2. [top-level statements] — en ordre source (le top-level EST le programme)
 *   3. Fermeture()/Closing() si defini dans projet.owl (teardown auto-appele
 *      par project.c en fin de projet)
 *
 * Depuis , aucune procedure Main() n'est auto-appelee : le point de
 * demarrage est le top-level (du script, ou de projet.owl pour un projet).
 *
 * Ce hoisting permet aux statements top-level de referencer librement les
 * procedures/classes/structures definies plus bas dans le fichier (forward refs
 * style JavaScript hoisted functions / Python after import). */

typedef struct {
    int start;   /* byte offset (inclusif) dans chunk->code */
    int end;     /* byte offset (exclusif) */
} ByteRange;

/* Saturation du suivi des plages top-level. Avant , la plage en trop
 * etait jetee en silence : le reordonnancement [declarations][init] devenait
 * partiel, et une procedure declaree apres la 4096e plage n'etait plus visible
 * des appels qui la precedent — « fonction inconnue » AU RUNTIME, sur un
 * source legal, sans le moindre diagnostic a la compilation.
 *
 * Une seule plainte par compilation : le parser reprend apres synchronize(),
 * donc panicMode ne suffit pas a etouffer les suivantes. */
static bool g_toplevel_ranges_saturated = false;

static void toplevel_range_push(ByteRange* ranges, int* count,
                                int start, int end) {
    if (*count >= MAX_TOP_LEVEL_RANGES) {
        if (!g_toplevel_ranges_saturated) {
            g_toplevel_ranges_saturated = true;
            error_capacity_exceeded("MAX_TOP_LEVEL_RANGES", MAX_TOP_LEVEL_RANGES);
        }
        return;
    }
    ranges[*count].start = start;
    ranges[*count].end   = end;
    (*count)++;
}

/* Peek si le prochain construct top-level est une declaration structurelle :
 *   - PROCEDURE / FONCTION
 *   - CONSTANTE (bloc, pas precede de 'est un')
 *   - <id> est <BlockType>  ou BlockType ∈ {CLASSE, STRUCTURE, INTERFACE,
 *     ENUMERATION, COMBINAISON, FENETRE, LIBELLE, BOUTON, SAISIE}
 *
 * Sauve/restaure l'etat parser+scanner : le construct n'est pas consomme. */
static bool peek_top_level_is_declaration(void) {
    if (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION) || check(TOKEN_CONSTANTE)) {
        return true;
    }
    if (!check(TOKEN_IDENTIFIER)) return false;

    Scanner savedScanner   = parser.scanner;
    Token   savedCurrent   = parser.current;
    Token   savedPrevious  = parser.previous;
    bool    savedCrossed   = crossedNewline;

    advance_token();   /* consomme l'identifier */
    /* canon multi-decl : `a, b sont des Personnes` — sauter les ',' identifiers
     * pour atteindre EST/SONT, sinon test rate. */
    while (check(TOKEN_COMMA)) {
        advance_token();
        if (!check(TOKEN_IDENTIFIER)) break;
        advance_token();
    }
    bool isDecl = false;
    if (check(TOKEN_EST) || check(TOKEN_SONT)) {
        advance_token();
        consume_en_a_an_filler(); /* copule EN : `is a/an <BlockType>` */
        TokenType t = parser.current.type;
        isDecl = (t == TOKEN_CLASSE || t == TOKEN_STRUCTURE
              || t == TOKEN_INTERFACE || t == TOKEN_ENUMERATION
              || t == TOKEN_COMBINAISON || t == TOKEN_FENETRE
              || t == TOKEN_LIBELLE || t == TOKEN_BOUTON
              || t == TOKEN_SAISIE  || t == TOKEN_TABLE);
    }

    parser.scanner   = savedScanner;
    parser.current   = savedCurrent;
    parser.previous  = savedPrevious;
    crossedNewline   = savedCrossed;
    return isDecl;
}

/* Convention OWL "1 classe = 1 fichier" : verifie que le construct top-level
 * a venir (parser.current) est compatible avec un fichier qui a deja declare
 * une Classe. Whitelist (autorise) :
 *   - PROCEDURE / FONCTION (methodes externes qualifiees cName.X, constructeur
 *     cName(...), proc orpheline tolere; l'analyse fine est differee aux
 *     tickets POO suivants)
 *   - TILDE / DESTRUCTEUR (destructeur ~cName())
 *   - PUBLIC / PRIVE / PROTEGE (modificateurs de visibilite devant PROCEDURE)
 *   - NEWLINE / EOF (skippes par le parser de toute facon)
 * Tout autre token au top-level d'un fichier classe est rejete.
 * Appelle error_at_current() avec un message clair. */
static void enforce_class_file_isolation_at_top_level(void) {
    if (g_file_first_class_line == 0) return;
    /*  : si une faute a deja ete reportee pour ce fichier, ne pas
     * empiler le message "Convention OWL : ..." par dessus. Le parser
     * peut etre devenu erratique post-FIN-orphelin et voir du runtime
     * fantome au top-level. La cause racine est deja signalee. */
    if (parser.hadFileError) return;
    TokenType t = parser.current.type;
    if (t == TOKEN_PROCEDURE || t == TOKEN_FONCTION
        || t == TOKEN_TILDE   || t == TOKEN_DESTRUCTEUR
        || t == TOKEN_PUBLIC  || t == TOKEN_PRIVE || t == TOKEN_PROTEGE
        || t == TOKEN_NEWLINE || t == TOKEN_EOF) {
        return;
    }
    /* IDENT au top-level : ce serait soit "IDENT est une Classe/Fenetre/Etat"
     * (deja traite par class/window/etat_declaration via leurs propres gardes
     * — on les laisse emettre leurs messages plus precis), soit du code
     * runtime (assignation, appel, expression statement). On laisse passer
     * IDENT ici aussi pour que les gardes specifiques s'expriment, ET on ne
     * spamme pas. Les statements runtime IDENT-start (Trace(...), x = 1, etc.)
     * seront couverts par le tracking g_file_first_non_class_stmt_line en
     * amont (si la classe vient apres) ou par un message ici en aval. */
    if (t == TOKEN_IDENTIFIER) {
        /* Peek si c'est une declaration "IDENT est un/une <TypeBloc>" : si oui,
         * laisser les gardes window/etat/class emettre. Sinon, c'est du
         * runtime → erreur. */
        Scanner saved      = parser.scanner;
        Token   savedCur   = parser.current;
        Token   savedPrev  = parser.previous;
        bool    savedXNL   = crossedNewline;
        advance_token();
        bool isDeclShape = false;
        if (check(TOKEN_EST) || check(TOKEN_SONT)) {
            advance_token();
            consume_en_a_an_filler(); /* copule EN : `is a/an <BlockType>` */
            TokenType nt = parser.current.type;
            isDeclShape = (nt == TOKEN_CLASSE || nt == TOKEN_FENETRE
                        || nt == TOKEN_ETAT   || nt == TOKEN_STRUCTURE
                        || nt == TOKEN_INTERFACE || nt == TOKEN_ENUMERATION
                        || nt == TOKEN_COMBINAISON);
        }
        parser.scanner   = saved;
        parser.current   = savedCur;
        parser.previous  = savedPrev;
        crossedNewline   = savedXNL;
        if (isDeclShape) return;
    }
    /* Tout le reste = code runtime / construct non-permis au top-level d'un
     * fichier classe. */
    char nameBuf[128], lineBuf[16];
    snprintf(nameBuf, sizeof(nameBuf), "%.*s",
             g_file_first_class_name_len, g_file_first_class_name);
    snprintf(lineBuf, sizeof(lineBuf), "%d", g_file_first_class_line);
    owl_emit_error_current(E_SEM_CLASS_FILE_TOPLEVEL_CODE,
                           "name", nameBuf,
                           "line", lineBuf,
                           NULL);
}

/*  +  — verrou DSL strict "1 fichier = 1 Fenetre/Etat" :
 * un fichier contenant un bloc Fenetre/Etat ne peut contenir AUCUN code
 * top-level hors du bloc. Seuls sont autorises au top-level : le bloc
 * Fenetre/Etat lui-meme (capture via le peek `IDENT est une Fenetre/Etat`
 * plus bas) + commentaires + sentinelles (NEWLINE/EOF).
 *
 * Avant  : PROCEDURE/FONCTION/CONSTANTE top-level etaient tolerees
 * (helpers globaux du contexte fenetre/etat). Decision dev  :
 * les helpers de la Fenetre vivent DANS le bloc (au top-level du bloc, hors
 * widget) — meme scope que `PROCEDURE FinInitialisation()`. Pas d'adressage
 * cross-fichier des champs ; pour partager du code → classe ou collection
 * de procedures (futur).
 *
 * Symetrique strict de enforce_class_file_isolation_at_top_level. Appelee a
 * chaque iteration de la boucle top-level juste avant declaration(). Consulte
 * les flags g_file_has_window_block_prescan / g_file_has_etat_block_prescan
 * poses au prescan unifie. */
/*  — avale un bloc-widget / bande retombe au top-level :
 * `NAME est un <Type> ... FIN`, en suivant l'equilibre des FIN. Compte comme
 * ouvreurs de bloc : PROPRIETES, PROCEDURE/FONCTION, structures de controle
 * (SI/POUR/...), et les sous-shapes `IDENT est un <widget/bande>` imbriques.
 * window_skip_nested_block (le helper generique) ne compte PAS PROPRIETES
 * comme un ouvreur, donc il s'arrete trop tot ici — d'ou ce skip dedie. */
static bool peek_is_dsl_block_widget_shape(void); /* fwd */
static void dsl_skip_toplevel_widget_block(void) {
    advance_token(); /* IDENT (nom du widget/bande) */
    if (check(TOKEN_EST) || check(TOKEN_SONT)) advance_token();
    if (check_ident_champ()) { advance_token(); skip_optional_de_after_champ(); } /*  */
    advance_token(); /* type keyword/ident */
    dsl_skip_block_body();
}

/*  — avale le CORPS d'un bloc DSL deja ouvert, jusqu'a son FIN
 * matching INCLUS. Le token courant doit etre le premier du corps (entete
 * consommee par l'appelant : type de bloc, ou ')' de la liste de params).
 *
 * La boucle TESTE avant d'avancer. Les variantes locales qui avancaient
 * d'abord mangeaient un jeton de trop sur un corps VIDE (`PROCEDURE x()
 * <FIN>`) : le FIN teste etait alors celui du conteneur, d'ou un
 * « Expected 'FIN' to close Etat declaration » sur une declaration
 * pourtant bien fermee. */
static void dsl_skip_block_body(void) {
    int depth = 1; /* le bloc dont on saute le corps */
    while (depth > 0 && !check(TOKEN_EOF)) {
        /*  — source unique. `SI c ALORS instr` ne compte pas. */
        if (!check(TOKEN_FIN)
            && prescan_token_in_depth_table(parser.current.type)
            && parser_depth_delta() > 0) {
            depth++;
            advance_token();
            continue;
        }
        if (check(TOKEN_FIN)) {
            depth--;
            advance_token();
            continue;
        }
        if (peek_is_dsl_block_widget_shape()) {
            /* sous-widget imbrique : compte son ouverture, le FIN matching
             * sera vu par l'iteration depth-- correspondante. */
            depth++;
            advance_token(); /* IDENT */
            if (check(TOKEN_EST) || check(TOKEN_SONT)) advance_token();
            if (check_ident_champ()) { advance_token(); skip_optional_de_after_champ(); } /*  */
            advance_token(); /* type */
            continue;
        }
        advance_token();
    }
}

/*  — peek `IDENT est un[e] <WidgetOrBandType>` SANS consommer.
 * Distingue les blocs-widgets (Libellé/Bouton/...) et les bandes d'État
 * (Corps/EnTêteDocument/...) retombes au top-level apres desynchro. Ces
 * shapes ne sont JAMAIS valides hors d'un bloc Fenetre/Etat : leur presence
 * au top-level est la signature de la cascade (bloc ferme trop tot). */
static bool peek_is_dsl_block_widget_shape(void) {
    if (!check(TOKEN_IDENTIFIER)) return false;
    Scanner saved     = parser.scanner;
    Token   savedCur  = parser.current;
    Token   savedPrev = parser.previous;
    bool    savedXNL  = crossedNewline;
    bool    isWidget  = false;
    advance_token(); /* IDENT */
    if (check(TOKEN_EST) || check(TOKEN_SONT)) {
        advance_token(); /* EST/SONT */
        if (check_ident_champ()) { advance_token(); skip_optional_de_after_champ(); } /*  */
        OwlControlKind dummy;
        if (detect_subfield_kind(&dummy)) {
            isWidget = true;
        } else if (check(TOKEN_IDENTIFIER)) {
            /* Bande d'État : Corps / EnTêteDocument / BasDePage / ...
             * Strip accents avant lookup : la table de noms canon est en
             * ASCII (EnTeteDocument) et le token source peut porter l'accent
             * (EnTêteDocument), accent-insensibilite oblige (invariant 2). */
            char kindBuf[64];
            int klen = scanner_strip_accents(parser.current.start,
                                              parser.current.length,
                                              kindBuf, sizeof(kindBuf));
            if (klen <= 0) {
                klen = parser.current.length < 63 ? parser.current.length : 63;
                memcpy(kindBuf, parser.current.start, (size_t)klen);
                kindBuf[klen] = '\0';
            }
            if (owl_etat_block_kind_from_name(kindBuf) >= 0) isWidget = true;
        }
    }
    parser.scanner  = saved;
    parser.current  = savedCur;
    parser.previous = savedPrev;
    crossedNewline  = savedXNL;
    return isWidget;
}

/* Retourne true si l'item courant a ete consomme (collapse cascade) : le
 * caller doit alors `continue` sans appeler declaration(). */
static bool enforce_dsl_file_isolation_at_top_level(void) {
    if (!g_file_has_window_block_prescan && !g_file_has_etat_block_prescan) {
        return false;
    }
    /*  — nom d'element DSL avec tiret dans un fichier-fenetre/-etat
     * (`FEN-Test est une Fenêtre`). Ce chemin precede declaration(), donc sans
     * interception ici le construct fautif retombe sur le message generique
     * "un fichier-fenetre ne peut contenir que...". On pointe le nom fautif,
     * meme resync coupant (jusqu'a EOF) qu'en tete de declaration(). */
    {
        char elemName[128];
        Token nameTok;
        if (detect_hyphen_in_element_name(elemName, sizeof(elemName), &nameTok)) {
            owl_emit_error_at(&nameTok, E_SEM_INVALID_ELEMENT_NAME,
                              "name", elemName,
                              NULL);
            while (parser.current.type != TOKEN_EOF) advance_token();
            return true;
        }
    }
    TokenType t = parser.current.type;
    /* Whitelist minimale : sentinelles uniquement. Le bloc Fenetre/Etat
     * lui-meme est laisse passer par le peek `IDENT est une Fenetre/Etat`
     * plus bas. Tout le reste — PROCEDURE, FONCTION, CONSTANTE, modifiers
     * d'acces, variables, appels, expressions — est interdit hors bloc. */
    if (t == TOKEN_NEWLINE || t == TOKEN_EOF) {
        return false;
    }
    if (t == TOKEN_IDENTIFIER) {
        /* Peek si c'est `IDENT est un/une <BlockType>` : laisse les gardes
         * window/etat/class/struct emettre leur erreur specifique. */
        Scanner saved      = parser.scanner;
        Token   savedCur   = parser.current;
        Token   savedPrev  = parser.previous;
        bool    savedXNL   = crossedNewline;
        advance_token();
        bool isDeclShape = false;
        if (check(TOKEN_EST) || check(TOKEN_SONT)) {
            advance_token();
            consume_en_a_an_filler(); /* copule EN : `is a/an <BlockType>` */
            TokenType nt = parser.current.type;
            isDeclShape = (nt == TOKEN_CLASSE || nt == TOKEN_FENETRE
                        || nt == TOKEN_ETAT   || nt == TOKEN_STRUCTURE
                        || nt == TOKEN_INTERFACE || nt == TOKEN_ENUMERATION
                        || nt == TOKEN_COMBINAISON);
        }
        parser.scanner   = saved;
        parser.current   = savedCur;
        parser.previous  = savedPrev;
        crossedNewline   = savedXNL;
        if (isDeclShape) return false;

        /*  — collapse cascade Classe 1 : un bloc-widget / une bande
         * d'Etat retombe au top-level APRES qu'un bloc Fenetre/Etat ait ete
         * ouvert dans ce fichier. C'est TOUJOURS la signature d'une desynchro
         * (un widget/bande n'est jamais valide hors bloc) — la vraie cause est
         * un bloc ferme trop tot (FIN surnumeraire, prop mal parsee, NBSP,
         * ==...). On avale le bloc entier pour ne pas re-declencher l'erreur
         * sur chacun de ses FIN imbriques, on emet UNE erreur pointant la ligne
         * d'OUVERTURE du bloc (pas le token courant, dont la ligne mentirait)
         * + UNE note agregee pour le surplus. Restreint au cas "fenetre/etat
         * deja vue" : du vrai code colle hors bloc (variables, Trace) n'est PAS
         * un widget-shape et garde son unique erreur via le chemin normal. */
        int openLine = g_file_has_window_block_prescan ? g_file_first_window_line
                                                       : g_file_first_etat_line;
        if (openLine > 0 && peek_is_dsl_block_widget_shape()) {
            /* Avale ce bloc-widget + tous les blocs-widgets consecutifs
             * (separes de simples NEWLINE), en comptant le surplus. */
            int swallowed = 0;
            do {
                dsl_skip_toplevel_widget_block(); /* avale `NAME est un X ... FIN` */
                swallowed++;
                while (check(TOKEN_NEWLINE)) advance_token();
            } while (peek_is_dsl_block_widget_shape());

            char lineBuf[16];
            snprintf(lineBuf, sizeof(lineBuf), "%d", openLine);
            /* Token synthetique pointant la ligne d'ouverture, colonne 1. */
            Token openTok = savedCur;
            openTok.line   = openLine;
            openTok.column = 1;
            owl_emit_error_at(&openTok, E_SEM_DSL_WINDOW_CLOSED_EARLY,
                              "line", lineBuf, NULL);
            /* panicMode pose par l'erreur : on le clear, l'item est deja
             * consomme proprement, pas de synchronize a declencher. */
            parser.panicMode = false;

            if (swallowed > OWL_DSL_TOPLEVEL_WIDGET_CAP) {
                char countBuf[16];
                snprintf(countBuf, sizeof(countBuf), "%d",
                         swallowed - 1); /* -1 : la 1ere est deja signalee */
                owl_emit_error_at(&openTok, E_SEM_DSL_TOPLEVEL_CASCADE_NOTE,
                                  "count", countBuf,
                                  "line", lineBuf,
                                  NULL);
                parser.panicMode = false;
            }
            return true; /* item(s) consomme(s) : le caller doit continue */
        }
    }
    /*  — desynchro "depuis l'interieur" (NBSP, ==, prop mal parsee...)
     * ou le bloc Fenetre/Etat a avale les IDENT des widgets en panic et n'a
     * laisse au top-level que des FIN orphelins / fragments. Ici le token
     * courant n'est PAS un widget-shape (souvent un FIN), donc le collapse
     * widget ci-dessus ne s'applique pas. Des qu'on est en desynchro CONFIRMEE
     * (`hadFileError`, pose par un synchronize precedent) ET qu'un bloc
     * Fenetre/Etat a ete ouvert, plus rien de legal ne subsiste au top-level :
     * on emet UNE erreur pointant la ligne d'ouverture (vraie cause) + UNE note
     * agregee pour le surplus, et on avale tout jusqu'a EOF. Sans `hadFileError`
     * la 1ere violation passe par le chemin normal ci-dessous (cas temoins :
     * variable / Trace stray => 1 erreur "ne peut contenir que", puis leur
     * synchronize collapse le reste avant qu'il n'atteigne cette fonction). */
    int openLine = g_file_has_window_block_prescan ? g_file_first_window_line
                                                   : g_file_first_etat_line;
    if (parser.hadFileError && openLine > 0) {
        /* Compte les fragments restants (approx : declarations top-level =
         * shapes `IDENT est ...` + statements separes par newline). On donne
         * un ordre de grandeur, pas un decompte exact. */
        int remaining = 0;
        while (!check(TOKEN_EOF)) {
            if (check(TOKEN_IDENTIFIER) || check(TOKEN_FIN)) remaining++;
            advance_token();
            while (check(TOKEN_NEWLINE)) advance_token();
        }
        char lineBuf[16];
        snprintf(lineBuf, sizeof(lineBuf), "%d", openLine);
        Token openTok = parser.previous;
        openTok.line   = openLine;
        openTok.column = 1;
        owl_emit_error_at(&openTok, E_SEM_DSL_WINDOW_CLOSED_EARLY,
                          "line", lineBuf, NULL);
        parser.panicMode = false;
        if (remaining > 1) {
            char countBuf[16];
            snprintf(countBuf, sizeof(countBuf), "%d", remaining - 1);
            owl_emit_error_at(&openTok, E_SEM_DSL_TOPLEVEL_CASCADE_NOTE,
                              "count", countBuf,
                              "line", lineBuf,
                              NULL);
            parser.panicMode = false;
        }
        return true; /* tout avale jusqu'a EOF */
    }
    /* Reste = code runtime / construct non-permis. Selectionne le code erreur
     * fenetre vs etat (les deux sont mutuellement exclusifs au compile via
     * E_SEM_FILE_WINDOW_AND_ETAT, donc un seul flag est set en pratique). */
    if (g_file_has_window_block_prescan) {
        owl_emit_error_current(E_SEM_DSL_FENETRE_TOPLEVEL_INTERDIT, NULL);
    } else {
        owl_emit_error_current(E_SEM_DSL_ETAT_TOPLEVEL_INTERDIT, NULL);
    }
    /*  — code AVANT le bloc DSL (le bloc n'a pas encore ete parse :
     * g_file_first_window/etat_line vaut 0, pose seulement au parse reel). Le
     * bloc qui suit ne pourrait etre parse qu'en etat panic (hadFileError),
     * ce qui desynchronise son corps et fait re-declencher ce meme verrou sur
     * chaque widget/bande/FIN retombe au top-level -> cascade de messages
     * identiques. Le fichier etant deja invalide, on avale tout jusqu'a EOF :
     * UNE erreur sur la ligne fautive, comme le cas "apres le bloc" (ou le
     * synchronize collapse le reste) et comme la famille service. */
    int firstBlockLine = g_file_has_window_block_prescan
                             ? g_file_first_window_line
                             : g_file_first_etat_line;
    if (firstBlockLine == 0) {
        while (parser.current.type != TOKEN_EOF) advance_token();
        parser.panicMode = false;
        return true;
    }
    return false;
}

/*  — peek non destructif : le construct top-level courant est-il la
 * declaration du bloc Projet (`IDENT est un[e] Projet` / `... Project`) ? */
static bool peek_top_level_is_projet_block(void) {
    if (!check(TOKEN_IDENTIFIER)) return false;
    Scanner saved     = parser.scanner;
    Token   savedCur  = parser.current;
    Token   savedPrev = parser.previous;
    bool    savedXNL  = crossedNewline;
    bool    isProjet  = false;
    advance_token();  /* IDENT (nom du projet) */
    if (check(TOKEN_EST) || check(TOKEN_SONT)) {
        advance_token();
        consume_en_a_an_filler();  /* copule EN : is a/an <BlockType> */
        if (check(TOKEN_IDENTIFIER)
            && ((parser.current.length == 6
                 && strncasecmp(parser.current.start, "Projet", 6) == 0)
             || (parser.current.length == 7
                 && strncasecmp(parser.current.start, "Project", 7) == 0))) {
            isProjet = true;
        }
    }
    parser.scanner   = saved;
    parser.current   = savedCur;
    parser.previous  = savedPrev;
    crossedNewline   = savedXNL;
    return isProjet;
}

/*  — verrou top-level d'un fichier-projet. Un fichier contenant un
 * bloc `est un Projet` ne peut comporter QUE ce bloc au top-level : aucun
 * statement/declaration avant la declaration ni apres son FIN final. Le corps
 * du bloc (apres PROPRIETES) est le programme d'initialisation, parse par
 * var_declaration_after_est. Appele a chaque iteration des boucles top-level,
 * juste avant declaration(). Symetrique des verrous classe / fenetre-etat. */
static void enforce_projet_file_isolation_at_top_level(void) {
    if (!g_file_has_projet_block) return;
    if (parser.hadFileError) return;
    TokenType t = parser.current.type;
    if (t == TOKEN_NEWLINE || t == TOKEN_EOF) return;
    /* Laisse passer la declaration du bloc Projet lui-meme. */
    if (!g_projet_block_parsed && peek_top_level_is_projet_block()) return;
    /* Tout autre construct : code avant la declaration (le programme d'init
     * vit DANS le bloc) ou apres le FIN final. */
    if (g_projet_block_parsed) {
        owl_emit_error_current(E_SEM_PROJET_TOPLEVEL_CODE_AFTER, NULL);
    } else {
        owl_emit_error_current(E_SEM_PROJET_TOPLEVEL_CODE_BEFORE, NULL);
    }
}

/*  — peek non destructif : le construct top-level courant est-il la
 * declaration du bloc collection (`IDENT est une CollectionDeProcédures`) ? */
static bool peek_top_level_is_collection_block(void) {
    if (!check(TOKEN_IDENTIFIER)) return false;
    Scanner saved     = parser.scanner;
    Token   savedCur  = parser.current;
    Token   savedPrev = parser.previous;
    bool    savedXNL  = crossedNewline;
    bool    isColl    = false;
    advance_token();  /* IDENT (nom de la collection) */
    if (check(TOKEN_EST) || check(TOKEN_SONT)) {
        advance_token();
        consume_en_a_an_filler();  /* copule EN : is a <BlockType> */
        isColl = check(TOKEN_IDENTIFIER)
              && token_is_collection_kw(parser.current.start,
                                        parser.current.length);
    }
    parser.scanner   = saved;
    parser.current   = savedCur;
    parser.previous  = savedPrev;
    crossedNewline   = savedXNL;
    return isColl;
}

/*  — verrou top-level d'un fichier-collection. Symetrique du verrou
 * fichier-projet : hors du bloc, rien n'est permis (le code d'initialisation
 * vit DANS le bloc). */
static void enforce_collection_file_isolation_at_top_level(void) {
    if (!g_file_has_collection_block) return;
    if (parser.hadFileError) return;
    TokenType t = parser.current.type;
    if (t == TOKEN_NEWLINE || t == TOKEN_EOF) return;
    if (!g_collection_block_parsed && peek_top_level_is_collection_block()) return;
    if (g_collection_block_parsed) {
        owl_emit_error_current(E_SEM_COLLECTION_TOPLEVEL_CODE_AFTER, NULL);
    } else {
        owl_emit_error_current(E_SEM_COLLECTION_TOPLEVEL_CODE_BEFORE, NULL);
    }
}

/*  — peek non destructif : le construct top-level courant est-il la
 * declaration du bloc `IDENT est un ServiceREST` ? Miroir de
 * peek_top_level_is_projet_block ; nom compose sans token dedie (accent-strip
 * + compare, comme le dispatch). */
static bool peek_top_level_is_service_block(void) {
    if (!check(TOKEN_IDENTIFIER)) return false;
    Scanner saved     = parser.scanner;
    Token   savedCur  = parser.current;
    Token   savedPrev = parser.previous;
    bool    savedXNL  = crossedNewline;
    bool    isSvc     = false;
    advance_token();  /* IDENT (nom du service) */
    if (check(TOKEN_EST) || check(TOKEN_SONT)) {
        advance_token();
        consume_en_a_an_filler();  /* copule EN : is a <BlockType> */
        if (check(TOKEN_IDENTIFIER)) {
            char probe[24];
            int n = scanner_strip_accents(parser.current.start,
                                          parser.current.length,
                                          probe, sizeof(probe));
            if (n == 11 && strncasecmp(probe, "ServiceREST", 11) == 0) {
                isSvc = true;
            }
        }
    }
    parser.scanner   = saved;
    parser.current   = savedCur;
    parser.previous  = savedPrev;
    crossedNewline   = savedXNL;
    return isSvc;
}

/*  — verrou top-level d'un fichier-service. Symetrique du verrou
 * fichier-projet : hors du bloc ServiceREST, rien n'est permis (les
 * declarations et les operations vivent DANS le bloc). */
static void enforce_service_file_isolation_at_top_level(void) {
    if (!g_file_has_service_block) return;
    if (parser.hadFileError) return;
    TokenType t = parser.current.type;
    if (t == TOKEN_NEWLINE || t == TOKEN_EOF) return;
    /* Mono-bloc (miroir Projet) : un seul ServiceREST par fichier. La
     * declaration du bloc passe UNE fois ; un 2e bloc (meme apres le FIN du
     * premier) tombe dans le verrou "code apres". Le croisement de routes entre
     * services releve du `serve` CROSS-FICHIER (resolution projet), pas d'un
     * multi-bloc intra-fichier. */
    if (!g_service_block_parsed && peek_top_level_is_service_block()) return;
    if (g_service_block_parsed) {
        /* Un 2e bloc ServiceREST merite un conseil dedie : "un service par
         * fichier", pas le generique "deplace ca DANS le bloc" (on ne met pas
         * un service dans un service). parser.current pointe le nom du 2e
         * service. Le reste du code hors-bloc garde le message ONLY_BLOCK. */
        if (peek_top_level_is_service_block()) {
            owl_emit_error_current(E_SEM_SERVICE_DUPLICATE_IN_FILE, NULL);
        } else {
            owl_emit_error_current(E_SEM_SERVICE_FILE_ONLY_BLOCK_AFTER, NULL);
        }
    } else {
        owl_emit_error_current(E_SEM_SERVICE_FILE_ONLY_BLOCK_BEFORE, NULL);
    }
}

/* Reordonne le chunk : copie d'abord les byte-ranges declRanges (en ordre
 * source) puis stmtRanges (en ordre source). Les jumps relatifs internes a
 * une range sont preserves car la range est copiee comme un bloc contigu.
 * Le pool de constantes n'est pas touche. */
static void reorder_chunk_for_hoisting(Chunk* chunk,
                                        const ByteRange* decls, int declCount,
                                        const ByteRange* stmts, int stmtCount) {
    int totalSize = 0;
    for (int i = 0; i < declCount; i++) totalSize += decls[i].end - decls[i].start;
    for (int i = 0; i < stmtCount; i++) totalSize += stmts[i].end - stmts[i].start;
    /* Si les ranges ne couvrent pas le chunk (parse-error / panic recovery
     * a saute des bytes), on ne touche pas au chunk : pas de reorder fragile. */
    if (totalSize != chunk->count) return;

    uint8_t* newCode  = ALLOCATE(uint8_t, chunk->capacity);
    int*     newLines = ALLOCATE(int,     chunk->capacity);
    int pos = 0;

    for (int i = 0; i < declCount; i++) {
        int len = decls[i].end - decls[i].start;
        memcpy(newCode  + pos, chunk->code  + decls[i].start, (size_t)len);
        memcpy(newLines + pos, chunk->lines + decls[i].start, (size_t)len * sizeof(int));
        pos += len;
    }
    for (int i = 0; i < stmtCount; i++) {
        int len = stmts[i].end - stmts[i].start;
        memcpy(newCode  + pos, chunk->code  + stmts[i].start, (size_t)len);
        memcpy(newLines + pos, chunk->lines + stmts[i].start, (size_t)len * sizeof(int));
        pos += len;
    }

    FREE_ARRAY(uint8_t, chunk->code,  chunk->capacity);
    FREE_ARRAY(int,     chunk->lines, chunk->capacity);
    chunk->code  = newCode;
    chunk->lines = newLines;
    chunk->count = pos;
}

/*  — variante de reorder_chunk_for_hoisting bornée à un SOUS-RANGE
 * [rangeStart, chunk->count). Réordonne les octets en [decls][stmts] EN PLACE,
 * en préservant tout ce qui précède rangeStart. Les ranges doivent couvrir
 * EXACTEMENT le sous-range (sinon no-op : un parse-error/panic a sauté des
 * octets → reorder fragile évité). Sert au hoisting du corps de collection. */
static void reorder_bytecode_range(Chunk* chunk, int rangeStart,
                                   const ByteRange* decls, int declCount,
                                   const ByteRange* stmts, int stmtCount) {
    int totalSize = 0;
    for (int i = 0; i < declCount; i++) totalSize += decls[i].end - decls[i].start;
    for (int i = 0; i < stmtCount; i++) totalSize += stmts[i].end - stmts[i].start;
    int subLen = chunk->count - rangeStart;
    if (subLen <= 0 || totalSize != subLen) return;

    uint8_t* newCode  = ALLOCATE(uint8_t, subLen);
    int*     newLines = ALLOCATE(int,     subLen);
    int pos = 0;
    for (int i = 0; i < declCount; i++) {
        int len = decls[i].end - decls[i].start;
        memcpy(newCode  + pos, chunk->code  + decls[i].start, (size_t)len);
        memcpy(newLines + pos, chunk->lines + decls[i].start, (size_t)len * sizeof(int));
        pos += len;
    }
    for (int i = 0; i < stmtCount; i++) {
        int len = stmts[i].end - stmts[i].start;
        memcpy(newCode  + pos, chunk->code  + stmts[i].start, (size_t)len);
        memcpy(newLines + pos, chunk->lines + stmts[i].start, (size_t)len * sizeof(int));
        pos += len;
    }
    memcpy(chunk->code  + rangeStart, newCode,  (size_t)subLen);
    memcpy(chunk->lines + rangeStart, newLines, (size_t)subLen * sizeof(int));
    FREE_ARRAY(uint8_t, newCode,  subLen);
    FREE_ARRAY(int,     newLines, subLen);
}

/*  — corps de CollectionDeProcédures. On compile le body en ORDRE
 * SOURCE (une suite de `declaration()`), en trackant les plages d'octets de
 * chaque construct : déclarations structurelles (PROCEDURE/FONCTION/STRUCTURE/
 * CONSTANTE/ENUMERATION, via peek_top_level_is_declaration) vs code d'init
 * (globales + appels). On réordonne ensuite le sous-range du body en
 * [decls][init] : les procédures sont DÉFINIES avant que l'init ne s'exécute.
 * Exactement le hoisting du top-level d'un script (support #214). */
static void compile_collection_body_hoisted(void) {
    int bodyStart = current_chunk()->count;
    ByteRange* declRanges = ALLOCATE(ByteRange, MAX_TOP_LEVEL_RANGES);
    ByteRange* stmtRanges = ALLOCATE(ByteRange, MAX_TOP_LEVEL_RANGES);
    int declCount = 0, stmtCount = 0;
    g_toplevel_ranges_saturated = false;

    while (check(TOKEN_NEWLINE)) advance_token();
    while (!check(TOKEN_FIN) && !check(TOKEN_EOF)) {
        Token classNameTok;
        if (peek_top_level_is_class_declaration(&classNameTok)) {
            char nameBuf[128];
            snprintf(nameBuf, sizeof(nameBuf), "%.*s",
                     classNameTok.length, classNameTok.start);
            owl_emit_error_at(&classNameTok, E_SEM_COLLECTION_CLASSE_INTERDITE,
                              "name", nameBuf, NULL);
            parser.panicMode = false;  /* le parse continue proprement */
        }
        int startOff = current_chunk()->count;
        bool isDecl = peek_top_level_is_declaration();
        declaration();
        int endOff = current_chunk()->count;
        if (endOff > startOff) {
            if (isDecl) toplevel_range_push(declRanges, &declCount,
                                            startOff, endOff);
            else        toplevel_range_push(stmtRanges, &stmtCount,
                                            startOff, endOff);
        }
        while (check(TOKEN_NEWLINE)) advance_token();
    }

    if (declCount > 0 && stmtCount > 0) {
        reorder_bytecode_range(current_chunk(), bodyStart,
                               declRanges, declCount, stmtRanges, stmtCount);
    }
    FREE_ARRAY(ByteRange, declRanges, MAX_TOP_LEVEL_RANGES);
    FREE_ARRAY(ByteRange, stmtRanges, MAX_TOP_LEVEL_RANGES);
}

/*  /  — les structures OWL sont des types VALEUR strictement
 * acycliques. Un membre de type structure est construit par valeur a
 * l'instanciation ; un cycle (direct A→A, ou indirect A→B→…→A) rendrait la
 * construction infinie. Le refus DIRECT est pose au fil du parse (voir
 * E_SEM_STRUCT_SELF_RECURSION dans struct_declaration). Ici on ferme les
 * cycles INDIRECTS, invisibles au fil du parse (forward refs : stAlpha peut
 * referencer stBeta declare apres) — d'ou ce passage post-parse, une fois
 * toutes les structures connues. On ne suit QUE les aretes de membre-structure
 * PAR VALEUR : un membre `tableau de X` (conteneur vide a l'instanciation) et
 * un membre de type CLASSE (reference) ne sont pas des cycles par valeur.
 * L'utilisateur qui veut un graphe / une liste chainee utilise une CLASSE. */

/* La structure `targetIdx` est-elle atteignable depuis `fromIdx` en suivant
 * >= 1 arete de membre-structure-par-valeur, self-loop exclue (le refus direct
 * en a la charge) ? DFS avec marquage `visited` sur l'index de type. */
static bool struct_reaches(int fromIdx, int targetIdx, bool* visited) {
    for (int fi = knownUserTypes[fromIdx].fieldFirst; fi >= 0;
         fi = userTypeFieldPool[fi].next) {
        const UserTypeField* f = &userTypeFieldPool[fi];
        if (f->is_container) continue;   /* tableau / assoc : pas un cycle valeur */
        if (f->typeLen <= 0) continue;
        if (!type_name_is_structure(f->typeName, f->typeLen)) continue;
        int tIdx = user_type_index(f->typeName, f->typeLen);
        if (tIdx < 0 || tIdx == fromIdx) continue;  /* self-loop : refus direct */
        if (tIdx == targetIdx) return true;
        if (!visited[tIdx]) {
            visited[tIdx] = true;
            if (struct_reaches(tIdx, targetIdx, visited)) return true;
        }
    }
    return false;
}

static void validate_struct_acyclicity(void) {
    bool visited[MAX_USER_TYPES];
    for (int s = 0; s < knownUserTypeCount; s++) {
        if (knownUserTypes[s].kind != OWL_USER_TYPE_STRUCTURE) continue;
        memset(visited, 0, sizeof(bool) * (size_t)knownUserTypeCount);
        visited[s] = true;
        if (!struct_reaches(s, s, visited)) continue;
        /* `s` est sur un cycle. On rapporte sur la 1re arete sortante de `s`
         * qui participe au cycle (membre dont le type ramene a `s`), en
         * nommant `s` — meme message que le refus direct (pointe CLASSE). Un
         * seul rapport pour tout le programme : les fixtures encodent un cycle
         * unique, et un cycle rapporte une fois par type serait bruyant. */
        for (int fi = knownUserTypes[s].fieldFirst; fi >= 0;
             fi = userTypeFieldPool[fi].next) {
            const UserTypeField* f = &userTypeFieldPool[fi];
            if (f->is_container) continue;
            if (f->typeLen <= 0) continue;
            if (!type_name_is_structure(f->typeName, f->typeLen)) continue;
            int tIdx = user_type_index(f->typeName, f->typeLen);
            if (tIdx < 0 || tIdx == s) continue;
            memset(visited, 0, sizeof(bool) * (size_t)knownUserTypeCount);
            visited[tIdx] = true;
            if (tIdx == s || struct_reaches(tIdx, s, visited)) {
                Token synth;
                synth.type = TOKEN_IDENTIFIER;
                synth.start = knownUserTypes[s].name;
                synth.length = knownUserTypes[s].length;
                synth.line = f->typeLine;
                synth.column = f->typeColumn;
                parser.panicMode = false;  /* emettre meme apres une cascade */
                owl_emit_error_at(&synth, E_SEM_STRUCT_SELF_RECURSION,
                                  "type", knownUserTypes[s].name, NULL);
                return;
            }
        }
        return;  /* cycle detecte mais arete introuvable : on ne reboucle pas */
    }
}

static ObjFunction* compile_impl(const char* source, bool asFunction) {
    init_rules();
    user_types_reset_all();  /*  */
    userTypeFieldPoolCount = 0;
    pendingTypeRefCount = 0;
    declaredMethodCount = 0;
    /*  : les `:membre` differes sont per-fichier (le check final ne
     * porte que sur les classes declarees ici, cf. colon_member_cross_check_global).
     * Sans ce reset les refs s'accumulent au fil des compile_in_project d'un
     * meme projet : une ref non resolue d'un fichier deja compile est
     * re-checkee lors du compile d'un autre fichier (knownUserTypes etant
     * pre-peuple cross-fichier via le symtable) -> erreur dupliquee ou
     * attribuee au mauvais fichier. */
    g_pending_colon_refs_count = 0;
    typed_globals_reset();
    const_globals_reset();
    element_globals_reset();
    collection_members_reset();  /*  */
    xfile_style_type_cache_reset();  /*  */
    theme_style_index_reset();       /*  */
    /*  — le tag de type cible d'un `{ }` pointe DANS la source en
     * cours (structTypeName). Un parse interrompu avant que le litteral ne le
     * consomme le laissait vivant : la compilation suivante du meme process
     * lisait un pointeur mort et fabriquait un litteral la ou elle devait
     * refuser (erreur reelle avalee cote --check-server et
     * --self-test-compile-error). Per-fichier, comme les autres. */
    g_inline_target_type            = NULL;
    g_inline_target_type_len        = 0;
    g_inline_target_refuses_literal = false;
    g_toplevel_confine = false;  /*  : chaque fichier repart en mode GLOBAL */
    decl_globals_reset_all();  /*  */
    g_file_first_window_line = 0;
    g_file_first_etat_line   = 0;
    g_file_first_class_line  = 0;
    g_file_first_class_name[0] = '\0';
    g_file_first_class_name_len = 0;
    g_file_first_non_class_stmt_line = 0;
    g_in_etat_scope_depth    = 0;
    g_file_has_window_block_prescan = false;
    g_file_has_etat_block_prescan   = false;
    /*  — les deux flags projet manquaient ici alors que les deux
     * autres points d'entree (compile_in_project / _split) les remettent a
     * zero. Ils sont poses au prescan et jamais effaces : dans un process qui
     * compile plusieurs sources (serveur MCP, --check-server, REPL, harnais de
     * test), tout fichier compile APRES un fichier a bloc Projet heritait de
     * l'etat « fichier-projet » et se voyait refuser son propre code au
     * top-level. Mesure : 541 faux rejets sur un balayage de 645 fichiers. */
    g_file_has_projet_block         = false;
    g_projet_block_parsed           = false;
    g_file_has_collection_block     = false;
    g_collection_block_parsed       = false;
    g_file_has_service_block        = false;
    g_service_block_parsed          = false;
    /* Opt-out test-only "1 fichier = 1 Fenetre" : detection bete de la
     * directive commentaire avant le parse. strstr suffit (le source n'est
     * pas si gros pour la perf compile). */
    g_file_allow_multi_window = (source && strstr(source, "@owl-allow-multi-window") != NULL);

    /* Pre-scan unifie : (1) Compile("Name", ...) registrations, (2) hoisting
     * des decls top-level pour les forward refs. UN seul walk de tokens.
     * Le 2e flag desactive (2) en mode TYPE_FUNCTION (Compile/ExécuteCode) ou
     * la source est un body de fonction, pas un script. */
    prescan_widgets_reset();
    prescan_source_unified(source, /*registerTopLevelDecls=*/!asFunction);

    scanner_init(&parser.scanner, source);
    parser.hadError = false;
    parser.panicMode = false;
    parser.hadFileError = false; /*  */

    Compiler compiler;
    init_compiler(&compiler, asFunction ? TYPE_FUNCTION : TYPE_SCRIPT);

    advance_token();

    /* PROCEDURE-as-source form (Compile/ExécuteCode only). */
    bool absorbedProc = false;
    if (asFunction && (check(TOKEN_PROCEDURE) || check(TOKEN_FONCTION))) {
        absorb_procedure_header();
        absorbedProc = true;
    }

    /* B.2 : track top-level construct ranges pour hoisting (TYPE_SCRIPT only,
     * pas en mode TYPE_FUNCTION qui represente Compile/ExécuteCode). */
    bool doHoisting = !asFunction;
    ByteRange* declRanges = NULL;
    ByteRange* stmtRanges = NULL;
    int declCount = 0, stmtCount = 0;
    g_toplevel_ranges_saturated = false;
    if (doHoisting) {
        declRanges = ALLOCATE(ByteRange, MAX_TOP_LEVEL_RANGES);
        stmtRanges = ALLOCATE(ByteRange, MAX_TOP_LEVEL_RANGES);
    }

    /*  — fichier au nom reserve projet.owl/project.owl sans bloc
     * `est un Projet` : rejet unique (ligne 1 col 1) avant la boucle. */
    if (doHoisting) enforce_reserved_projet_requires_block();
    if (doHoisting) enforce_no_ambiguous_projet_markers();

    while (!check(TOKEN_EOF)) {
        /* When the PROCEDURE header was absorbed, an optional trailing `FIN`
         * terminates the body (standard syntax). */
        if (absorbedProc && check(TOKEN_FIN)) { advance_token(); break; }

        if (doHoisting) {
            int startOff = current_chunk()->count;
            bool isDecl = peek_top_level_is_declaration();
            /* Track ligne du 1er statement runtime top-level (utile pour
             * rejeter une Classe declaree apres du code). On detecte les
             * statements via "pas une declaration ET pas une declaration
             * de type bloc". On utilise peek_top_level_is_declaration qui
             * couvre PROCEDURE/FONCTION/CONSTANTE + "IDENT est un Bloc". */
            if (!isDecl && g_file_first_non_class_stmt_line == 0
                && g_file_first_class_line == 0) {
                g_file_first_non_class_stmt_line = parser.current.line;
            }
            /* Convention OWL "1 classe = 1 fichier" : si une Classe est
             * deja declaree, rejeter tout construct non-whitelist. */
            enforce_class_file_isolation_at_top_level();
            /*  — verrou DSL : si fichier-fenetre/-etat, rejeter
             * code top-level non-PROCEDURE.  : true => le(s)
             * bloc(s)-widget(s) retombe(s) ont ete avale(s) (collapse
             * cascade), on saute declaration() pour ne pas re-parser. */
            if (enforce_dsl_file_isolation_at_top_level()) continue;
            /*  — verrou top-level fichier-projet. */
            enforce_projet_file_isolation_at_top_level();
            /*  — verrou top-level fichier-collection. */
            enforce_collection_file_isolation_at_top_level();
            /*  — verrou top-level fichier-service. */
            enforce_service_file_isolation_at_top_level();
            declaration();
            int endOff = current_chunk()->count;
            if (endOff > startOff) {
                if (isDecl) toplevel_range_push(declRanges, &declCount,
                                                startOff, endOff);
                else        toplevel_range_push(stmtRanges, &stmtCount,
                                                startOff, endOff);
            }
        } else {
            declaration();
        }
    }

    validate_pending_type_refs();
    validate_struct_acyclicity();  /*  — cycles de structures indirects */
    /*  : cross-check des contrats d'interfaces (`implemente iX`).
     * Mono-fichier : interfaces + classes + methodes sont toutes dans CE
     * fichier, le check est complet. Multi-fichier : passe par
     * symtable_verify_interfaces (prescan-based) — voir project.c. */
    interface_cross_check_global();
    abstract_cross_check_global();
    colon_member_cross_check_global();

    if (doHoisting && declCount > 0 && stmtCount > 0) {
        reorder_chunk_for_hoisting(current_chunk(),
                                    declRanges, declCount,
                                    stmtRanges, stmtCount);
    }
    if (declRanges) FREE_ARRAY(ByteRange, declRanges, MAX_TOP_LEVEL_RANGES);
    if (stmtRanges) FREE_ARRAY(ByteRange, stmtRanges, MAX_TOP_LEVEL_RANGES);

    ObjFunction* function = end_compiler();
    return parser.hadError ? NULL : function;
}

ObjFunction* compile(const char* source) {
    return compile_impl(source, false);
}

ObjFunction* compile_as_function(const char* source) {
    return compile_impl(source, true);
}

/* ================================================================
 * PUBLIC: COMPILE IN PROJECT CONTEXT
 * ================================================================ */

/*  — check d'unicite des noms d'elements top-level du projet. Le
 * registre deterministe projectSymbols->elements liste toutes les declarations
 * d'element (Fenetre, Etat, Classe, CollectionDeProcedures, Theme, Structure,
 * Enumeration, Combinaison, Interface) avec leur position. On emet une erreur
 * sur chaque element du FICHIER COURANT dont le nom (canon casse+accent) est
 * deja pris par un element d'un fichier de fileIndex strictement inferieur — la
 * 1re declaration (fileIndex le plus bas) ne porte donc pas d'erreur. Voie
 * unique et order-independante : les chemins vm_window/etat_lookup ne servent
 * plus qu'en l'absence de contexte projet. */
static void emit_toplevel_element_dups(void) {
    if (projectSymbols == NULL || currentFileIndex < 0) return;
    for (int i = 0; i < projectSymbols->elementCount; i++) {
        ProjectElement* e = &projectSymbols->elements[i];
        if (e->fileIndex != currentFileIndex) continue;
        if (!symtable_element_has_earlier_dup(projectSymbols, e->name,
                                              (int)strlen(e->name),
                                              currentFileIndex)) {
            continue;
        }
        Token synth;
        synth.start  = e->name;
        synth.length = (int)strlen(e->name);
        synth.line   = e->line;
        synth.column = e->column;
        synth.type   = TOKEN_IDENTIFIER;
        parser.panicMode = false;  /* emettre meme apres une cascade suppressee */
        owl_emit_error_at(&synth, E_SEM_ELEMENT_NAME_DUPLICATE,
                          "name", e->name,
                          NULL);
    }
}

ObjFunction* compile_in_project(const char* source, const char* filename,
                                 SymbolTable* symbols, int fileIndex) {
    currentFilename = filename;
    projectSymbols = symbols;
    currentFileIndex = fileIndex;

    init_rules();
    user_types_reset_all();  /*  */
    userTypeFieldPoolCount = 0;
    pendingTypeRefCount = 0;
    declaredMethodCount = 0;
    /*  : les `:membre` differes sont per-fichier (le check final ne
     * porte que sur les classes declarees ici, cf. colon_member_cross_check_global).
     * Sans ce reset les refs s'accumulent au fil des compile_in_project d'un
     * meme projet : une ref non resolue d'un fichier deja compile est
     * re-checkee lors du compile d'un autre fichier (knownUserTypes etant
     * pre-peuple cross-fichier via le symtable) -> erreur dupliquee ou
     * attribuee au mauvais fichier. */
    g_pending_colon_refs_count = 0;
    typed_globals_reset();
    const_globals_reset();
    element_globals_reset();
    collection_members_reset();  /*  */
    xfile_style_type_cache_reset();  /*  */
    theme_style_index_reset();       /*  */
    /*  — le tag de type cible d'un `{ }` pointe DANS la source en
     * cours (structTypeName). Un parse interrompu avant que le litteral ne le
     * consomme le laissait vivant : la compilation suivante du meme process
     * lisait un pointeur mort et fabriquait un litteral la ou elle devait
     * refuser (erreur reelle avalee cote --check-server et
     * --self-test-compile-error). Per-fichier, comme les autres. */
    g_inline_target_type            = NULL;
    g_inline_target_type_len        = 0;
    g_inline_target_refuses_literal = false;
    g_toplevel_confine = false;  /*  : chaque fichier repart en mode GLOBAL */
    decl_globals_reset_all();  /*  */
    g_file_first_window_line = 0;
    g_file_first_etat_line   = 0;
    g_file_first_class_line  = 0;
    g_file_first_class_name[0] = '\0';
    g_file_first_class_name_len = 0;
    g_file_first_non_class_stmt_line = 0;
    g_in_etat_scope_depth    = 0;
    g_file_has_window_block_prescan = false;
    g_file_has_etat_block_prescan   = false;
    g_file_has_projet_block         = false;
    g_projet_block_parsed           = false;
    g_file_has_collection_block     = false;
    g_collection_block_parsed       = false;
    g_file_has_service_block        = false;
    g_service_block_parsed          = false;
    g_file_allow_multi_window = (source && strstr(source, "@owl-allow-multi-window") != NULL);

    /*  — capture des fenetres declarees du projet pour ElementsDe. */
    compiler_projet_windows_collect(symbols);

    /* Pre-populate from project symbol table so the compiler can recognize
     * cross-file class constructors AND cross-file type references. */
    if (symbols != NULL) {
        for (int i = 0; i < symbols->count; i++) {
            const char* n = symbols->symbols[i].name;
            int nl = (int)strlen(n);
            SymbolKind k = symbols->symbols[i].kind;
            /* Seuls les kinds qui définissent des types peuvent être référencés
             * comme types. SYM_VARIABLE / SYM_PROCEDURE / SYM_FUNCTION sont des
             * globals scalaires/callables — ne PAS les enregistrer comme user
             * types (sinon `tab est un tableau` enregistrerait `tab` comme
             * type, ce qui bloque toute variable nommée `tab` au compile). */
            if (k == SYM_CLASS || k == SYM_STRUCT ||
                k == SYM_INTERFACE || k == SYM_ENUM) {
                /* Cross-file prescan : on enregistre le NOM uniquement (sauf
                 * CLASSE qui peut etre tagged). STRUCTURE/ENUM laissent kind
                 * UNKNOWN — sera pose quand le body est parse dans le fichier
                 * d'origine. Sans ca, le strict-check sur kind==STRUCTURE
                 * trippe avant que les fields soient ajoutes.
                 * Cf tests/regression/test_prescan_struct_kind_premature.owl */
                register_user_type(n, nl, 0);  /*  : pre-population cross-file, ligne d'origine indisponible ici */
                if (k == SYM_CLASS) {
                    user_type_set_kind(n, nl, OWL_USER_TYPE_CLASSE);
                } else if (k == SYM_STRUCT &&
                           symbols->symbols[i].fileIndex != currentFileIndex) {
                    /*  : charge les champs des structs compagnons pour
                     * que le garde `..prop` cross-fichier distingue conteneur
                     * (legitime) de scalaire (refuse). */
                    hydrate_companion_struct_fields(symbols, n, nl, currentFileIndex);
                }
            }
        }
    }

    /* Pre-scan unifie (cf compile_impl) : Compile() + hoisting top-level decls
     * en UN walk. Toujours actif en project mode car les forward refs internes
     * au fichier ne sont pas couvertes par la SymbolTable cross-file. */
    prescan_widgets_reset();
    /*  : pre-populer g_prescan_widgets depuis le symtable projet pour
     * que les FEN_X declarees dans un fichier voisin soient reconnues comme
     * widgets (kind=Fenetre) cote compilateur du fichier courant. Sans ca,
     * `FEN_X..Titre = {langueFr: ..., langueEn: ...}` cross-fichier echoue
     * en E_SYNTAX_BRACE_LITERAL_NO_TYPE faute d'ancrage du type cible. */
    if (symbols != NULL) {
        for (int i = 0; i < symbols->count; i++) {
            const ProjectSymbol* s = &symbols->symbols[i];
            if (s->fileIndex == currentFileIndex) continue;  /* self : sera vu par prescan_source_unified */
            if (s->kind == SYM_WINDOW) {
                const char* n = s->name;
                prescan_widget_register(n, (int)strlen(n), OWL_CONTROL_WINDOW);
            }
        }
    }
    /*  : pre-scan widgets des voisins pour reconnaitre les
     * sous-widgets DSL (BTN_X dans FEN_Y) en cross-fichier. Sans ca,
     * `BTN_X..Libelle = {...}` voisin echoue en BRACE_LITERAL_NO_TYPE
     * faute d'ancrage kind=Bouton -> slot=MULTILINGUE. On utilise
     * registerTopLevelDecls=false : prescan_widget_register interne reste
     * actif (catalogue les sous-widgets) mais on ne pollue pas la table
     * des forward-refs top-level locales du fichier courant. */
    hydrate_widgets_from_neighbors(symbols);
    /*  — hydrate g_declaredGlobals avec les globales declarees au
     * top-level des fichiers voisins du projet, pour alimenter le shadow
     * check (champ Fenetre / variable locale qui collisionne avec un
     * global du voisin). Symetrique de mark_globals_used_from_neighbors
     *. Appel AVANT prescan_source_unified(source, true) pour
     * que les entries neighbor soient en place quand le compile principal
     * tournera. */
    hydrate_globals_from_neighbors(symbols);
    hydrate_collection_members(symbols, source);  /*  ; source :  */
    prescan_source_unified(source, /*registerTopLevelDecls=*/true);

    scanner_init(&parser.scanner, source);
    parser.hadError = false;
    parser.panicMode = false;
    parser.hadFileError = false; /*  */

    Compiler compiler;
    init_compiler(&compiler, TYPE_SCRIPT);

    advance_token();

    /* B.2 : track top-level construct ranges pour hoisting des declarations. */
    ByteRange* declRanges = ALLOCATE(ByteRange, MAX_TOP_LEVEL_RANGES);
    ByteRange* stmtRanges = ALLOCATE(ByteRange, MAX_TOP_LEVEL_RANGES);
    int declCount = 0, stmtCount = 0;
    g_toplevel_ranges_saturated = false;

    /*  — fichier au nom reserve projet.owl/project.owl sans bloc
     * `est un Projet` : rejet unique (ligne 1 col 1) avant la boucle. */
    enforce_reserved_projet_requires_block();
    /*  — coexistence projet.owl + project.owl dans le dossier :
     * ambiguite de frontiere, meme verrou symetrique que le chemin RUN. */
    enforce_no_ambiguous_projet_markers();

    while (!check(TOKEN_EOF)) {
        int startOff = current_chunk()->count;
        bool isDecl = peek_top_level_is_declaration();
        if (!isDecl && g_file_first_non_class_stmt_line == 0
            && g_file_first_class_line == 0) {
            g_file_first_non_class_stmt_line = parser.current.line;
        }
        enforce_class_file_isolation_at_top_level();
        /*  — verrou DSL fenetre/etat.  : collapse cascade. */
        if (enforce_dsl_file_isolation_at_top_level()) continue;
        /*  — verrou top-level fichier-projet. */
        enforce_projet_file_isolation_at_top_level();
        /*  — verrou top-level fichier-collection. */
        enforce_collection_file_isolation_at_top_level();
        /*  — verrou top-level fichier-service. */
        enforce_service_file_isolation_at_top_level();
        declaration();
        int endOff = current_chunk()->count;
        if (endOff > startOff) {
            if (isDecl) toplevel_range_push(declRanges, &declCount,
                                            startOff, endOff);
            else        toplevel_range_push(stmtRanges, &stmtCount,
                                            startOff, endOff);
        }
    }

    validate_pending_type_refs();
    validate_struct_acyclicity();  /*  — cycles de structures indirects */
    /*  : check de conformite des contrats `cX implemente iY`.
     * Le filtre `classDeclaredHere` (interne) limite le check aux classes
     * declarees dans CE fichier — pas de re-check des classes des autres
     * fichiers du projet. Les interfaces necessaires doivent etre dans le
     * meme fichier OU avoir ete vues lors d'une compilation precedente
     * (tables persistantes). */
    interface_cross_check_global();
    abstract_cross_check_global();
    colon_member_cross_check_global();
    emit_toplevel_element_dups();  /*  : unicite des noms d'elements */

    if (declCount > 0 && stmtCount > 0) {
        reorder_chunk_for_hoisting(current_chunk(),
                                    declRanges, declCount,
                                    stmtRanges, stmtCount);
    }
    FREE_ARRAY(ByteRange, declRanges, MAX_TOP_LEVEL_RANGES);
    FREE_ARRAY(ByteRange, stmtRanges, MAX_TOP_LEVEL_RANGES);

    ObjFunction* function = end_compiler();

    currentFilename = NULL;
    projectSymbols = NULL;
    currentFileIndex = -1;

    return parser.hadError ? NULL : function;
}

/*  — construit un ObjFunction frais a partir d'une liste de
 * plages d'octets (contigues, tracees pendant le parse top-level) d'un chunk
 * source. Copie le pool de constantes ENTIER (aucune reindexation des
 * OP_CONSTANT : les index restent valides tant que le pool est copie tel quel)
 * et reemet le terminateur (OP_NIL + OP_RETURN) — les plages ne contiennent pas
 * le OP_RETURN final (reorder tourne avant end_compiler). Le ObjFunction
 * retourne est POUSSE sur la pile VM (root GC) : les allocations internes
 * (chunk, pool, code) peuvent declencher un GC, et le caller doit vm_pop apres
 * l'avoir rattache. `src` doit rester rooted par le caller pendant l'appel (ses
 * Obj de pool sont lus ici). */
static ObjFunction* build_split_function_from_ranges(
        const Chunk* src, const ByteRange* ranges, int rangeCount,
        ObjString* filename, int termLine) {
    ObjFunction* fn = obj_new_function();
    vm_push(OBJ_VAL(fn));            /* root : les alloc suivantes peuvent GC */
    fn->filename = filename;         /* partage l'ObjString (GC-managed) */

    fn->chunk = ALLOCATE(Chunk, 1);
    chunk_init(fn->chunk);

    /* Copie du pool entier. Chaque value_array_write peut GROW -> GC : les Obj
     * ecrits sont references par `src` (rooted par le caller) et par le pool
     * partiel de `fn` (rooted via vm_push). Chaque fonction possede SA copie du
     * tableau de constantes -> pas de partage du backing array, pas de
     * double-free. Les Obj pointes restent partages (geres par le GC). */
    for (int i = 0; i < src->constants.count; i++) {
        value_array_write(&fn->chunk->constants, src->constants.values[i]);
    }

    /* Copie des plages d'octets. Blocs contigus : aucun saut ne traverse la
     * frontiere decl/stmt (invariant deja exploite par
     * reorder_chunk_for_hoisting), les offsets internes restent valides. */
    for (int r = 0; r < rangeCount; r++) {
        for (int j = ranges[r].start; j < ranges[r].end; j++) {
            chunk_write(fn->chunk, src->code[j], src->lines[j]);
        }
    }

    chunk_write(fn->chunk, OP_NIL, termLine);
    chunk_write(fn->chunk, OP_RETURN, termLine);

    return fn;   /* reste rooted (pousse) : le caller vm_pop */
}

/*  — cf. compiler.h. Duplique volontairement le setup de
 * compile_in_project (celle-ci doit rester intacte pour proteger --check /
 * owl test) ; seule la queue diverge : au lieu de reordonner un chunk unique
 * puis end_compiler, on materialise DEUX ObjFunction (declarations / corps). */
bool compile_in_project_split(const char* source, const char* filename,
                              SymbolTable* symbols, int fileIndex,
                              ObjFunction** outDecls, ObjFunction** outBody) {
    *outDecls = NULL;
    *outBody  = NULL;

    currentFilename = filename;
    projectSymbols = symbols;
    currentFileIndex = fileIndex;

    init_rules();
    user_types_reset_all();  /*  */
    userTypeFieldPoolCount = 0;
    pendingTypeRefCount = 0;
    declaredMethodCount = 0;
    g_pending_colon_refs_count = 0;
    typed_globals_reset();
    const_globals_reset();
    element_globals_reset();
    collection_members_reset();  /*  */
    xfile_style_type_cache_reset();  /*  */
    theme_style_index_reset();       /*  */
    /*  — le tag de type cible d'un `{ }` pointe DANS la source en
     * cours (structTypeName). Un parse interrompu avant que le litteral ne le
     * consomme le laissait vivant : la compilation suivante du meme process
     * lisait un pointeur mort et fabriquait un litteral la ou elle devait
     * refuser (erreur reelle avalee cote --check-server et
     * --self-test-compile-error). Per-fichier, comme les autres. */
    g_inline_target_type            = NULL;
    g_inline_target_type_len        = 0;
    g_inline_target_refuses_literal = false;
    g_toplevel_confine = false;  /*  : chaque fichier repart en mode GLOBAL */
    decl_globals_reset_all();  /*  */
    g_file_first_window_line = 0;
    g_file_first_etat_line   = 0;
    g_file_first_class_line  = 0;
    g_file_first_class_name[0] = '\0';
    g_file_first_class_name_len = 0;
    g_file_first_non_class_stmt_line = 0;
    g_in_etat_scope_depth    = 0;
    g_file_has_window_block_prescan = false;
    g_file_has_etat_block_prescan   = false;
    g_file_has_projet_block         = false;
    g_projet_block_parsed           = false;
    g_file_has_collection_block     = false;
    g_collection_block_parsed       = false;
    g_file_has_service_block        = false;
    g_service_block_parsed          = false;
    g_file_allow_multi_window = (source && strstr(source, "@owl-allow-multi-window") != NULL);

    /*  — capture des fenetres declarees du projet pour ElementsDe. */
    compiler_projet_windows_collect(symbols);

    /* Pre-populate depuis le symtable projet (types cross-fichier). */
    if (symbols != NULL) {
        for (int i = 0; i < symbols->count; i++) {
            const char* n = symbols->symbols[i].name;
            int nl = (int)strlen(n);
            SymbolKind k = symbols->symbols[i].kind;
            if (k == SYM_CLASS || k == SYM_STRUCT ||
                k == SYM_INTERFACE || k == SYM_ENUM) {
                register_user_type(n, nl, 0);
                if (k == SYM_CLASS) {
                    user_type_set_kind(n, nl, OWL_USER_TYPE_CLASSE);
                } else if (k == SYM_STRUCT &&
                           symbols->symbols[i].fileIndex != currentFileIndex) {
                    /*  : cf. compile_in_project. */
                    hydrate_companion_struct_fields(symbols, n, nl, currentFileIndex);
                }
            }
        }
    }

    prescan_widgets_reset();
    if (symbols != NULL) {
        for (int i = 0; i < symbols->count; i++) {
            const ProjectSymbol* s = &symbols->symbols[i];
            if (s->fileIndex == currentFileIndex) continue;
            if (s->kind == SYM_WINDOW) {
                const char* n = s->name;
                prescan_widget_register(n, (int)strlen(n), OWL_CONTROL_WINDOW);
            }
        }
    }
    hydrate_widgets_from_neighbors(symbols);
    hydrate_globals_from_neighbors(symbols);
    hydrate_collection_members(symbols, source);  /*  ; source :  */
    prescan_source_unified(source, /*registerTopLevelDecls=*/true);

    scanner_init(&parser.scanner, source);
    parser.hadError = false;
    parser.panicMode = false;
    parser.hadFileError = false;

    Compiler compiler;
    init_compiler(&compiler, TYPE_SCRIPT);

    advance_token();

    ByteRange* declRanges = ALLOCATE(ByteRange, MAX_TOP_LEVEL_RANGES);
    ByteRange* stmtRanges = ALLOCATE(ByteRange, MAX_TOP_LEVEL_RANGES);
    int declCount = 0, stmtCount = 0;
    g_toplevel_ranges_saturated = false;

    /*  — fichier au nom reserve projet.owl/project.owl sans bloc
     * `est un Projet` : rejet unique (ligne 1 col 1) avant la boucle. */
    enforce_reserved_projet_requires_block();
    /*  — coexistence projet.owl + project.owl dans le dossier :
     * ambiguite de frontiere, meme verrou symetrique que le chemin RUN. */
    enforce_no_ambiguous_projet_markers();

    while (!check(TOKEN_EOF)) {
        int startOff = current_chunk()->count;
        bool isDecl = peek_top_level_is_declaration();
        if (!isDecl && g_file_first_non_class_stmt_line == 0
            && g_file_first_class_line == 0) {
            g_file_first_non_class_stmt_line = parser.current.line;
        }
        enforce_class_file_isolation_at_top_level();
        if (enforce_dsl_file_isolation_at_top_level()) continue;
        /*  — verrou top-level fichier-projet. */
        enforce_projet_file_isolation_at_top_level();
        /*  — verrou top-level fichier-collection. */
        enforce_collection_file_isolation_at_top_level();
        /*  — verrou top-level fichier-service. */
        enforce_service_file_isolation_at_top_level();
        declaration();
        int endOff = current_chunk()->count;
        if (endOff > startOff) {
            if (isDecl) toplevel_range_push(declRanges, &declCount,
                                            startOff, endOff);
            else        toplevel_range_push(stmtRanges, &stmtCount,
                                            startOff, endOff);
        }
    }

    validate_pending_type_refs();
    validate_struct_acyclicity();  /*  — cycles de structures indirects */
    interface_cross_check_global();
    abstract_cross_check_global();
    colon_member_cross_check_global();

    /* Divergence vs compile_in_project : au lieu de reordonner UN chunk et de
     * finir par end_compiler, on materialise DEUX ObjFunction depuis le meme
     * chunk source (rooted par `current` tant qu'il n'est pas depile) puis on
     * end_compiler pour depiler proprement le compiler script (la fonction
     * fusionnee retournee est jetee). Les deux nouveaux ObjFunction restent
     * pousses (rooted) pendant end_compiler, qui peut GC (emit_return + warns). */
    const Chunk* src   = current_chunk();
    int    termLine    = parser.previous.line;
    ObjString* fnFile  = current->function->filename;

    ObjFunction* decls = build_split_function_from_ranges(
        src, declRanges, declCount, fnFile, termLine);   /* pousse */
    ObjFunction* body  = build_split_function_from_ranges(
        src, stmtRanges, stmtCount, fnFile, termLine);   /* pousse */

    FREE_ARRAY(ByteRange, declRanges, MAX_TOP_LEVEL_RANGES);
    FREE_ARRAY(ByteRange, stmtRanges, MAX_TOP_LEVEL_RANGES);

    (void)end_compiler();  /* depile `current` ; fonction fusionnee jetee */

    vm_pop();  /* body  (LIFO : pousse en dernier) */
    vm_pop();  /* decls */

    currentFilename = NULL;
    projectSymbols = NULL;
    currentFileIndex = -1;

    if (parser.hadError) return false;

    *outDecls = decls;
    *outBody  = body;
    return true;
}

/* ================================================================
 * GC: MARK COMPILER ROOTS
 * ================================================================ */

void gc_mark_compiler_roots(void) {
    Compiler* compiler = current;
    while (compiler != NULL) {
        gc_mark_object((Obj*)compiler->function);
        compiler = compiler->enclosing;
    }

    /*  lot 3-bis A1 — marque TOUS les controls EN COURS de parse
     * (mini-stack). Le control en cours n'est pas encore append a
     * decl->controls[] (ajout en fin pour eviter realloc invalidant le
     * pointer) → mark_ui_decl_roots ne descend pas dedans. Sans cette
     * racine : sous DEBUG_STRESS_GC, les ObjFunction events/user_procs
     * deja compilees pour ce control (et ses parents Conteneur/ZoneRepetee
     * en cas d'imbrication) sont collectees → segfault au dispatch event. */
    for (int i = 0; i < g_control_decl_top; i++) {
        gc_mark_control_decl(g_control_decl_stack[i]);
    }
}

/* ================================================================
 * SELF-TEST — GARDE DE COHERENCE PRE-SCAN / PARSE (COLLECTIONS)
 * ================================================================
 *  — verrou de collection_prescan_cross_check. Le garde et les deux
 * indexations qu'il confronte sont des statics de ce fichier : l'exercer
 * depuis un fichier de test exigerait de les exposer, donc d'elargir la
 * surface interne du compilateur pour les besoins d'un test. Le hook vit donc
 * ici et n'expose qu'un seul point d'entree.
 *
 * Le cote pre-scan est le VRAI scan lexical (hydrate_collection_members sur
 * une source forgee). Le cote parse rejoue ce que font les sites
 * d'enregistrement du parse (collection_member_register hors mode pre-scan).
 * Le verdict se lit sur le canal de diagnostics reel (compile_set_error_capture)
 * et pas sur un temoin ad hoc : le garde est donc exerce jusqu'a l'emission.
 *
 * Le cas decisif est l'anti-faux-positif (membre confine par LOCAL) : un garde
 * qui accuse du code legitime coute plus cher que pas de garde du tout. */

static int g_colguard_pass = 0;
static int g_colguard_fail = 0;

/* Joue un scenario complet et compare le nombre de diagnostics emis a
 * l'attendu. `prescanSrc` alimente le scan lexical ; `parseMembers` (liste
 * terminee par NULL) rejoue les enregistrements du parse pour `coll`.
 * `sawSource` a faux simule une source hors perimetre du scan (fichier isole,
 * buffer d'editeur divergent du disque). `expectInMsg`, si non NULL, doit
 * apparaitre dans le premier diagnostic : verifie qu'on a bien LE diagnostic
 * attendu et pas un autre. */
static void colguard_case(const char* label, const char* coll,
                          const char* prescanSrc,
                          const char* const* parseMembers,
                          bool sawSource, int expected,
                          const char* expectInMsg) {
    Parser savedParser = parser;
    parser.hadError  = false;
    parser.panicMode = false;

    collection_members_reset();

    SymbolTable* t = symtable_create();
    t->sources[0].fileIndex = 0;
    t->sources[0].source = prescanSrc;
    t->sourceCount = 1;
    hydrate_collection_members(t, sawSource ? prescanSrc : "");
    symtable_destroy(t);

    for (int i = 0; parseMembers != NULL && parseMembers[i] != NULL; i++) {
        collection_member_register(coll, (int)strlen(coll),
                                   parseMembers[i],
                                   (int)strlen(parseMembers[i]), true);
    }

    CompileDiagnostic diags[16];
    int count = 0;
    compile_set_error_capture(diags, 16, &count);

    Token where;
    where.type   = TOKEN_IDENTIFIER;
    where.start  = coll;
    where.length = (int)strlen(coll);
    where.line   = 1;
    where.column = 1;
    collection_prescan_cross_check(coll, &where);

    compile_set_error_capture(NULL, 0, NULL);
    collection_members_reset();
    parser = savedParser;

    bool ok = (count == expected);
    if (ok && expectInMsg != NULL && count > 0) {
        ok = (strstr(diags[0].message, expectInMsg) != NULL);
    }
    if (ok) {
        g_colguard_pass++;
    } else {
        g_colguard_fail++;
        fprintf(stderr, "  FAIL [%s] : %d diagnostic(s), %d attendu(s)\n",
                label, count, expected);
        for (int i = 0; i < count; i++) {
            fprintf(stderr, "        -> %s\n", diags[i].message);
        }
    }
}

int collection_prescan_guard_self_test(void) {
    g_colguard_pass = 0;
    g_colguard_fail = 0;

    /* Corps de reference : ce que le scan lexical sait indexer. */
    static const char* const SRC_COL_A =
        "COL_A est une CollectionDeProcedures\n"
        "  PROCEDURE Connue()\n"
        "  FIN\n"
        "FIN\n";

    /* 1. Parse-seul — le membre existe pour le parse mais pas dans l'index :
     *    invisible sous son nom nu depuis un autre fichier. Le garde parle. */
    {
        static const char* const members[] = { "Fantome", NULL };
        colguard_case("parse-seul -> diagnostic", "COL_A",
                      SRC_COL_A, members, /*sawSource=*/true,
                      /*expected=*/1, "Fantome");
    }

    /* 2. Parse + pre-scan — les deux indexations coincident, cas nominal. */
    {
        static const char* const members[] = { "Connue", NULL };
        colguard_case("parse + pre-scan -> muet", "COL_A",
                      SRC_COL_A, members, true, 0, NULL);
    }

    /* 3. Pre-scan seul — sens UNIQUE du garde (parse inclus dans scan). Un nom
     *    indexe que le parse ne definit pas arrive legitimement (bloc mort,
     *    collection homonyme d'un voisin) et ne prouve aucune panne. */
    colguard_case("pre-scan seul -> muet", "COL_A",
                  SRC_COL_A, NULL, true, 0, NULL);

    /* 4. ANTI-FAUX-POSITIF — corps mixant un membre confine par LOCAL et des
     *    membres exposes declares APRES. Le confine n'est enregistre par
     *    aucun des deux cotes ; les exposes doivent l'etre par les deux. Si le
     *    suivi LOCAL/GLOBAL du scan derive, les membres suivants sortent de
     *    l'index et le garde accuse du code parfaitement legitime. */
    {
        static const char* const src =
            "COL_A est une CollectionDeProcedures\n"
            "LOCAL\n"
            "  gSecret est un entier\n"
            "GLOBAL\n"
            "  gPartage est un entier\n"
            "  PROCEDURE Exposee()\n"
            "  FIN\n"
            "FIN\n";
        static const char* const members[] = { "gPartage", "Exposee", NULL };
        colguard_case("membre confine (LOCAL) -> muet", "COL_A",
                      src, members, true, 0, NULL);
    }

    /* 5. Source jamais scannee — comparer un parse a l'index d'un AUTRE texte
     *    ne prouve rien. Meme desynchronisation qu'au cas 1, garde muet. */
    {
        static const char* const members[] = { "Fantome", NULL };
        colguard_case("source hors perimetre du scan -> muet", "COL_A",
                      SRC_COL_A, members, /*sawSource=*/false, 0, NULL);
    }

    if (g_colguard_pass + g_colguard_fail == 0) {
        fprintf(stderr, "collection-prescan-guard: CORPUS VIDE — 0 cas "
                        "execute. Un controle qui n'examine rien ne prouve "
                        "rien.\n");
        return 1;
    }
    if (g_colguard_fail > 0) {
        fprintf(stderr, "collection-prescan-guard: %d FAIL, %d PASS\n",
                g_colguard_fail, g_colguard_pass);
    } else {
        fprintf(stdout, "collection-prescan-guard: %d PASS\n", g_colguard_pass);
    }
    return g_colguard_fail;
}
